"use client";

import { loadFont } from "@remotion/google-fonts/Unbounded";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const unbounded = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface AToZProps {
  entries?: string[];
  finale?: string;
  connector?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_ENTRIES = [
  "any aspect ratio.",
  "brand fonts.",
  "captions.",
  "dark mode.",
];

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const ELLIPSIS = "…";
const FONT_PX = 200;
const TRACK = -0.03;
const LETTER_TRACK = -0.02;

const EASE_ROLL = Easing.bezier(0.6, 0, 0.1, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const DWELLS = [28, 19, 17, 17];
const ROLL = 7;
const STAGGER = 2;
const FINAL_ROLL = 13;
const HOLD_MIN = 36;

interface Metrics {
  letters: Record<string, number>;
  maxLetter: number;
  words: Record<string, number>;
  space: number;
  connector: number;
  asc: number;
  desc: number;
  cap: number;
  tall: number;
  deep: number;
}

function measure(texts: string[], connector: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("a-to-z: no 2d context");
  const em = (s: string, w: number, track: number) => {
    ctx.font = `${w} ${FONT_PX}px "${unbounded.fontFamily}"`;
    return (
      ctx.measureText(s).width / FONT_PX +
      track * Math.max(0, Array.from(s).length - 1)
    );
  };
  const letters: Record<string, number> = {};
  let maxLetter = 0;
  for (const ch of ALPHABET) {
    letters[ch] = em(ch, 500, 0);
    maxLetter = Math.max(maxLetter, letters[ch]);
  }
  const words: Record<string, number> = {};
  for (const tx of texts) {
    for (const w of tx.split(/\s+/)) {
      if (w && words[w] === undefined) words[w] = em(w, 500, TRACK);
    }
  }
  ctx.font = `500 ${FONT_PX}px "${unbounded.fontFamily}"`;
  const fm = ctx.measureText("Hgy");
  return {
    letters,
    maxLetter,
    words,
    space: em(" ", 500, 0),
    connector: em(connector, 400, TRACK),
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
    cap: ctx.measureText("H").actualBoundingBoxAscent / FONT_PX,
    tall: ctx.measureText("dlkhfH").actualBoundingBoxAscent / FONT_PX,
    deep: ctx.measureText("gjpqy,").actualBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics(texts: string[], connector: string) {
  const key = `${connector}\u0001${texts.join("\u0002")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("a-to-z: measuring"));
  const released = useRef(false);
  const input = useRef({ texts, connector });
  input.current = { texts, connector };
  useEffect(() => {
    let live = true;
    Promise.all([
      unbounded.waitUntilDone(),
      document.fonts.load(`500 100px "${unbounded.fontFamily}"`),
      document.fonts.load(`400 100px "${unbounded.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          m: measure(input.current.texts, input.current.connector),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function wrap(text: string, m: Metrics, max: number) {
  const words = text.trim().split(/\s+/);
  const widths = words.map((w) => m.words[w] ?? w.length * 0.7);
  const run = (limit: number) => {
    const lines: string[][] = [];
    let line: string[] = [];
    let w = 0;
    words.forEach((word, i) => {
      const add = line.length === 0 ? widths[i] : w + m.space + widths[i];
      if (line.length > 0 && add > limit) {
        lines.push(line);
        line = [word];
        w = widths[i];
      } else {
        line.push(word);
        w = add;
      }
    });
    if (line.length) lines.push(line);
    return lines;
  };
  const first = run(max);
  let best = first;
  for (let k = 1; k <= 20; k++) {
    const next = run(max * (1 - k * 0.025));
    if (next.length !== first.length) break;
    best = next;
  }
  return {
    lines: best.map((l) => l.join(" ")),
    widest: Math.max(
      ...best.map((l) =>
        l.reduce((s, w, i) => s + (m.words[w] ?? 0) + (i > 0 ? m.space : 0), 0),
      ),
    ),
  };
}

function initialOf(text: string) {
  const ch = text.trim().charAt(0).toUpperCase();
  return ALPHABET.includes(ch) ? ch : "A";
}

interface Step<T> {
  at: number;
  value: T;
  roll: number;
  ease: (x: number) => number;
}

function stepAt<T>(steps: Step<T>[], t: number) {
  let k = 0;
  for (let i = 0; i < steps.length; i++) if (t >= steps[i].at) k = i;
  return { cur: steps[k], prev: k > 0 ? steps[k - 1] : null };
}

function flickDurations(count: number) {
  return Array.from({ length: count }, (_, i) => {
    const fromStart = i;
    const fromEnd = count - 1 - i;
    if (fromStart === 0) return 3;
    if (fromStart === 1) return 2;
    if (fromEnd === 0) return 4;
    if (fromEnd === 1) return 3;
    if (fromEnd === 2) return 2;
    return 1;
  });
}

export function AToZ({
  entries = DEFAULT_ENTRIES,
  finale = "zero lock-in.",
  connector = "is for",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: AToZProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const dark = theme === "dark";
  const field = dark ? (accent ?? "#FF5A1F") : "#FFFFFF";
  const stage =
    background === "transparent" ? "transparent" : (background ?? field);
  const ink = "#000000";
  const letterInk = dark ? "#000000" : (accent ?? "#E8480F");

  const list = entries.length > 0 ? entries : DEFAULT_ENTRIES;
  const m = useMetrics([...list, finale, ELLIPSIS], connector);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const total = durationInFrames * speed;
  const lastLetter = initialOf(list[list.length - 1]);
  const finalLetter = initialOf(finale);
  const between =
    ALPHABET.indexOf(finalLetter) > ALPHABET.indexOf(lastLetter) + 1
      ? ALPHABET.slice(
          ALPHABET.indexOf(lastLetter) + 1,
          ALPHABET.indexOf(finalLetter),
        ).split("")
      : [];
  const flick = flickDurations(between.length);
  const flickSum = flick.reduce((s, d) => s + d, 0);
  const natural = list.map((_, k) => DWELLS[Math.min(k, DWELLS.length - 1)]);
  const natSum = natural.reduce((s, d) => s + d, 0);
  const budget = total - HOLD_MIN - FINAL_ROLL - flickSum - 4;
  const fit = natSum > 0 ? Math.min(1, budget / natSum) : 1;
  const starts: number[] = [];
  let at = 0;
  for (let k = 0; k < list.length; k++) {
    starts.push(at);
    at += Math.max(8, Math.round(natural[k] * fit));
  }
  const ellipsisAt = at;
  const flickAt = between.length > 0 ? ellipsisAt + 2 : ellipsisAt;
  const finaleAt = flickAt + flickSum;

  const letterSteps: Step<string>[] = list.map((e, k) => ({
    at: starts[k],
    value: initialOf(e),
    roll: ROLL,
    ease: EASE_ROLL,
  }));
  let fa = flickAt;
  between.forEach((ch, i) => {
    letterSteps.push({ at: fa, value: ch, roll: 0, ease: EASE_ROLL });
    fa += flick[i];
  });
  letterSteps.push({
    at: finaleAt,
    value: finalLetter,
    roll: FINAL_ROLL,
    ease: EASE_OUT,
  });

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.09 : 0.075);

  const shown = [...list, finale].map(initialOf);
  const shownMax = Math.max(...shown.map((ch) => m.letters[ch] ?? 0));
  const all = [...list, finale];
  const widestWord = Math.max(
    ...all.flatMap((s) => s.split(/\s+/).map((w) => m.words[w] ?? 0)),
  );
  const singleWidest = Math.max(...all.map((s) => wrap(s, m, 1e9).widest));
  const lead = Math.max(1.04, m.tall + m.deep + 0.1);

  let G: number;
  let F: number;
  let xL: number;
  let textX: number;
  let textMax: number;
  let yB: number;
  let connectorBase: number;
  if (portrait) {
    G = Math.min(H * 0.26, W * 0.62) / m.cap;
    xL = marginX;
    textX = marginX;
    textMax = W - marginX * 2;
    F = Math.min(
      W * 0.1,
      textMax / Math.max(widestWord, 0.1),
      (textMax * 2) / Math.max(singleWidest * 1.1, 0.1),
    );
    yB = H * 0.44;
    connectorBase = yB + F * 1.1;
  } else {
    const gap0 = W * 0.04;
    G = (H * 0.5) / m.cap;
    G = Math.min(G, (marginX * 0.8) / Math.max(m.maxLetter - shownMax, 0.01));
    const colW = shownMax * G;
    const avail = W - marginX * 2 - colW - gap0;
    F = Math.min(
      H * 0.15,
      avail / Math.max(widestWord, 0.1),
      (avail * 2) / Math.max(singleWidest * 1.1, 0.1),
    );
    const textW = Math.max(...all.map((s) => wrap(s, m, avail / F).widest)) * F;
    const groupW = colW + gap0 + textW;
    const left = Math.max(marginX, (W - groupW) / 2);
    xL = left + colW;
    textX = xL + gap0;
    textMax = W - marginX - textX;
    yB = H / 2 + (m.cap * G) / 2;
    connectorBase = yB - m.cap * G + F * 0.5 * m.cap;
  }
  const capPx = m.cap * G;
  const capTop = yB - capPx;
  const lineSets = [...list, ELLIPSIS, finale].map(
    (s) => wrap(s, m, textMax / F).lines,
  );
  const Fc = F * 0.5;
  const lineH = lead * F;
  const itemTop0 = connectorBase + F * (m.deep + 0.25 + m.tall);

  const textSteps: Step<string[]>[] = list.map((_, k) => ({
    at: starts[k],
    value: lineSets[k],
    roll: ROLL,
    ease: EASE_ROLL,
  }));
  if (between.length > 0) {
    textSteps.push({
      at: ellipsisAt,
      value: lineSets[list.length],
      roll: ROLL,
      ease: EASE_ROLL,
    });
  }
  textSteps.push({
    at: finaleAt + 2,
    value: lineSets[list.length + 1],
    roll: FINAL_ROLL,
    ease: EASE_OUT,
  });

  const rise = (delay: number) =>
    interpolate(t, [delay - 3, delay + 11], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const rollPair = (
    key: string,
    winTop: number,
    winH: number,
    render: (value: string, y: number, k: string) => React.ReactNode,
    outgoing: string | null,
    incoming: string | null,
    p: number,
    winStyle?: React.CSSProperties,
  ) => {
    const travel = winH * 1.02;
    const kids: React.ReactNode[] = [];
    if (outgoing !== null && p < 1)
      kids.push(render(outgoing, -travel * p, "o"));
    if (incoming !== null && p > 0)
      kids.push(render(incoming, travel * (1 - p), "i"));
    return (
      <div
        key={key}
        style={{
          position: "absolute",
          top: winTop,
          height: winH,
          overflow: "hidden",
          ...winStyle,
        }}
      >
        {kids}
      </div>
    );
  };

  const nodes: React.ReactNode[] = [];

  {
    const { cur, prev } = stepAt(letterSteps, t);
    const p = !prev
      ? rise(0)
      : cur.roll === 0
        ? 1
        : interpolate(t, [cur.at, cur.at + cur.roll], [0, 1], {
            ...CLAMP,
            easing: cur.ease,
          });
    const pad = G * 0.06;
    const winTop = capTop - pad;
    const winH = capPx + pad * 2;
    const lineBox = (m.asc + m.desc) * G;
    const textTop = yB - m.asc * G - winTop;
    nodes.push(
      rollPair(
        "letter",
        winTop,
        winH,
        (v, y, k) => (
          <div
            key={k}
            style={{
              position: "absolute",
              ...(portrait ? { left: 0 } : { right: 0 }),
              top: textTop + y,
              height: lineBox,
              lineHeight: `${lineBox}px`,
              fontFamily: unbounded.fontFamily,
              fontWeight: 500,
              fontSize: G,
              letterSpacing: `${LETTER_TRACK}em`,
              color: letterInk,
              whiteSpace: "pre",
            }}
          >
            {v}
          </div>
        ),
        prev ? prev.value : null,
        cur.value,
        p,
        portrait
          ? { left: marginX, width: W - marginX }
          : { left: 0, width: xL },
      ),
    );
  }

  const textLine = (size: number, weight: number, color: string) =>
    function TextLine(v: string, y: number, k: string) {
      const lineBox = (m.asc + m.desc) * size;
      return (
        <div
          key={k}
          style={{
            position: "absolute",
            left: 0,
            top: (m.tall + 0.05 - m.asc) * size + y,
            height: lineBox,
            lineHeight: `${lineBox}px`,
            fontFamily: unbounded.fontFamily,
            fontWeight: weight,
            fontSize: size,
            letterSpacing: `${TRACK}em`,
            color,
            whiteSpace: "pre",
          }}
        >
          {v}
        </div>
      );
    };

  {
    const cp = rise(3);
    const winTop = connectorBase - Fc * (m.tall + 0.05);
    nodes.push(
      rollPair(
        "connector",
        winTop,
        Fc * (m.tall + m.deep + 0.1),
        textLine(Fc, 400, ink),
        null,
        connector,
        cp,
        { left: textX, right: 0 },
      ),
    );
  }

  {
    const { cur, prev } = stepAt(textSteps, t);
    const prevLines = prev ? prev.value : [];
    const curLines = cur.value;
    const slots = Math.max(prevLines.length, curLines.length);
    const slotOf = (lines: string[], s: number) => {
      if (portrait) return lines[s] ?? null;
      const i = lines.length - 1 - s;
      return i >= 0 ? lines[i] : null;
    };
    for (let s = 0; s < slots; s++) {
      const base = portrait ? itemTop0 + s * lineH : yB - s * lineH;
      const order = portrait ? s : slots - 1 - s;
      const delay = order * STAGGER;
      const p = !prev
        ? rise(5 + delay)
        : interpolate(t, [cur.at + delay, cur.at + delay + cur.roll], [0, 1], {
            ...CLAMP,
            easing: cur.ease,
          });
      const winTop = base - F * (m.tall + 0.05);
      nodes.push(
        rollPair(
          `s${s}`,
          winTop,
          F * (m.tall + m.deep + 0.1),
          textLine(F, 500, ink),
          slotOf(prevLines, s),
          slotOf(curLines, s),
          p,
          { left: textX, right: 0 },
        ),
      );
    }
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

"use client";

import { TransitionSeries } from "@remotion/transitions";
import type { ReactNode } from "react";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { planTransitionTiming } from "./duration";
import { FeatureFrame } from "./feature-frame";
import { FlowithDemo } from "./flowith-demo";
import {
  CtaScene,
  cameraCraneUp,
  type ProductDemoConfig,
  type ProductDemoScene,
  resolveTiming,
  spatialPush,
  type TemplateTheme,
} from "./foundation";
import { ProductHero } from "./product-hero";

export { getProductDemoDuration } from "./duration";
export type {
  ProductDemoConfig,
  ProductDemoScene,
  TemplateTheme,
} from "./foundation";

export interface A1ProductDemoProps {
  accentColor?: string;
  theme?: "light" | "dark";
  speed?: number;
  config?: ProductDemoConfig;
}

const THEME_TOKENS = {
  dark: {
    background: "#0B0B0F",
    foreground: "#FAFAFA",
    muted: "rgba(250,250,250,0.55)",
  },
  light: {
    background: "#FFFFFF",
    foreground: "#0B0B0F",
    muted: "rgba(11,11,15,0.55)",
  },
} as const;

export const DEFAULT_PRODUCT_DEMO_CONFIG: ProductDemoConfig = {
  meta: { fps: 30, width: 1920, height: 1080 },
  theme: {
    accent: "#6366F1",
    background: "#0B0B0F",
    foreground: "#FAFAFA",
    muted: "rgba(250,250,250,0.55)",
    fontFamily: "Geist",
  },
  scenes: [
    {
      type: "product-hero",
      durationInFrames: 150,
      content: {
        name: "Switchboard",
        pitch: "One inbox for every channel",
      },
    },
    {
      type: "feature-frame",
      durationInFrames: 180,
      content: {
        title: "Unified inbox",
        bullet: "Email, chat and SMS in one stream",
        side: "left",
      },
    },
    {
      type: "feature-frame",
      durationInFrames: 180,
      content: {
        title: "Auto routing",
        bullet: "Every message reaches the right person",
        side: "right",
      },
    },
    {
      type: "cta-scene",
      durationInFrames: 120,
      content: { line: "Try it free", domain: "switchboard.app" },
    },
  ],
};

const SNAPSHOT_START = 20;
const SNAPSHOT_STAGGER = 4;

function SnapshotLine({
  width,
  strong,
  order,
  theme,
  f,
}: {
  width: string;
  strong?: boolean;
  order: number;
  theme: TemplateTheme;
  f: number;
}) {
  const start = SNAPSHOT_START + order * SNAPSHOT_STAGGER;
  const p = interpolate(f, [start, start + 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <div
      style={{
        height: 16,
        width,
        borderRadius: 6,
        background: strong ? `${theme.foreground}30` : `${theme.foreground}16`,
        opacity: p,
        scale: `${interpolate(p, [0, 1], [0.6, 1])} 1`,
        transformOrigin: "left center",
      }}
    />
  );
}

function DefaultSnapshot({
  theme,
  speed = 1,
}: {
  theme: TemplateTheme;
  speed?: number;
}) {
  const f = useCurrentFrame() * speed;
  const sidebar: Array<[string, boolean?]> = [
    ["70%", true],
    ["90%"],
    ["80%"],
    ["60%"],
    ["85%"],
  ];
  const main: Array<[string, boolean?]> = [
    ["40%", true],
    ["100%"],
    ["95%"],
    ["88%"],
    ["70%"],
  ];

  return (
    <div style={{ display: "flex", gap: 22, height: "100%" }}>
      <div
        style={{
          flex: "0 0 30%",
          display: "flex",
          flexDirection: "column",
          gap: 16,
          paddingRight: 22,
          borderRight: `1px solid ${theme.foreground}14`,
        }}
      >
        {sidebar.map(([width, strong], i) => (
          <SnapshotLine
            key={`s-${i}`}
            width={width}
            strong={strong}
            order={i}
            theme={theme}
            f={f}
          />
        ))}
      </div>
      <div
        style={{ flex: 1, display: "flex", flexDirection: "column", gap: 18 }}
      >
        {main.map(([width, strong], i) => (
          <SnapshotLine
            key={`m-${i}`}
            width={width}
            strong={strong}
            order={i + 2}
            theme={theme}
            f={f}
          />
        ))}
      </div>
    </div>
  );
}

export function ProductDemo({
  config,
  speed = 1,
}: {
  config: ProductDemoConfig;
  speed?: number;
}) {
  const { theme, scenes } = config;

  const nodes: ReactNode[] = [];
  scenes.forEach((scene, index) => {
    nodes.push(
      <TransitionSeries.Sequence
        key={`scene-${index}`}
        durationInFrames={scene.durationInFrames}
      >
        <AbsoluteFill style={{ background: theme.background }} />
        <SceneContent scene={scene} theme={theme} speed={speed} />
      </TransitionSeries.Sequence>,
    );

    const next = scenes[index + 1];
    if (next) {
      const timing = resolveTiming(planTransitionTiming(scene, next));
      if (scene.type === "feature-frame" && next.type === "feature-frame") {
        const direction = next.content.side === "right" ? "left" : "right";
        nodes.push(
          <TransitionSeries.Transition
            key={`transition-${index}`}
            presentation={spatialPush({ direction })}
            timing={timing}
          />,
        );
      } else {
        nodes.push(
          <TransitionSeries.Transition
            key={`transition-${index}`}
            presentation={cameraCraneUp()}
            timing={timing}
          />,
        );
      }
    }
  });

  return (
    <AbsoluteFill style={{ background: theme.background }}>
      <TransitionSeries>{nodes}</TransitionSeries>
    </AbsoluteFill>
  );
}

function SceneContent({
  scene,
  theme,
  speed,
}: {
  scene: ProductDemoScene;
  theme: TemplateTheme;
  speed: number;
}) {
  if (scene.type === "product-hero") {
    return <ProductHero content={scene.content} theme={theme} speed={speed} />;
  }
  if (scene.type === "feature-frame") {
    return (
      <FeatureFrame
        title={scene.content.title}
        bullet={scene.content.bullet}
        side={scene.content.side}
        accent={theme.accent}
        theme={theme}
        header=""
        frame={<DefaultSnapshot theme={theme} speed={speed} />}
        speed={speed}
      />
    );
  }
  return (
    <CtaScene
      line={scene.content.line}
      domain={scene.content.domain}
      theme={theme}
      speed={speed}
    />
  );
}

export function A1ProductDemo({
  accentColor,
  theme = "dark",
  speed = 1,
  config,
}: A1ProductDemoProps) {
  if (!config) {
    return <FlowithDemo speed={speed} />;
  }

  const tokens = THEME_TOKENS[theme];
  const resolvedConfig: ProductDemoConfig = {
    ...config,
    theme: {
      accent: accentColor ?? config.theme.accent,
      background: tokens.background,
      foreground: tokens.foreground,
      muted: tokens.muted,
      fontFamily: config.theme.fontFamily,
    },
  };

  return <ProductDemo config={resolvedConfig} speed={speed} />;
}

"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import { type ReactNode, useId, useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: geist } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

// gradients.sh "rise" palette
const RISE = {
  bg: "#030306",
  c: ["#fff1e2", "#ff8a3d", "#a3301a", "#2a0d0a"],
} as const;

export interface AbacusCountProps {
  value?: number;
  label?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const BEADS = 9;
const START = 16;
const TICK = 5;
const CARRY_DELAY = 3;
const MID = [0.37, 0.58, 0.46, 0.63, 0.52];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const BEAD_SPRING = { damping: 14, stiffness: 260, mass: 0.55 };

const THEMES = {
  dark: {
    bg: RISE.bg,
    fg: "#F3F2EF",
    muted: "#8B8A90",
    faint: "#2A2A30",
    bead: "#2E2E34",
    ground: 0.26,
    stops: [RISE.c[0], "#ffb47a", RISE.c[1], "#d4522a"],
    rod: "rgba(255,255,255,0.24)",
    post: "rgba(255,255,255,0.32)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#DAD8D2",
    bead: "#D6D4CE",
    ground: 0,
    stops: ["#ffb47a", RISE.c[1], "#d4522a", RISE.c[2]],
    rod: "rgba(18,18,20,0.26)",
    post: "rgba(18,18,20,0.34)",
    grain: 0.045,
  },
} as const;

function digitAt(v: number, place: number) {
  return Math.floor(v / 10 ** place) % 10;
}

function leadOf(v: number) {
  return v <= 0 ? -1 : Math.floor(Math.log10(v) + 1e-9);
}

function buildSteps(value: number, places: number) {
  const seq: number[] = [0];
  const add = (v: number) => {
    if (v > seq[seq.length - 1] && v <= value) seq.push(v);
  };
  for (const v of [3, 6, 9, 10]) add(v);
  for (let pl = 2; pl < places; pl++) {
    const top = 10 ** pl;
    add(Math.round(top * MID[pl % MID.length]));
    add(top - 1);
    add(top);
  }
  add(value);
  const times: number[] = [START];
  let clock = START;
  for (let k = 1; k < seq.length; k++) {
    const prog = (k - 1) / Math.max(1, seq.length - 2);
    let gap = interpolate(prog, [0, 1], [9, 5]);
    let carry = false;
    for (let pl = 0; pl < places; pl++) {
      if (digitAt(seq[k], pl) < digitAt(seq[k - 1], pl)) carry = true;
    }
    if (carry) gap += 4;
    if (k === seq.length - 1 && k > 1) gap += 6;
    clock += gap;
    times.push(clock);
  }
  return { seq, times };
}

interface Move {
  at: number;
  from: number;
  to: number;
}

function buildMoves(seq: number[], times: number[], places: number) {
  const moves: Move[][][] = [];
  for (let pl = 0; pl < places; pl++) {
    const rod: Move[][] = Array.from({ length: BEADS }, () => []);
    for (let k = 1; k < seq.length; k++) {
      const d0 = digitAt(seq[k - 1], pl);
      const d1 = digitAt(seq[k], pl);
      if (d0 === d1) continue;
      let lowerReset = false;
      for (let q = 0; q < pl; q++) {
        if (digitAt(seq[k], q) < digitAt(seq[k - 1], q)) lowerReset = true;
      }
      const delay = d1 > d0 && lowerReset ? CARRY_DELAY : 0;
      for (let i = 0; i < BEADS; i++) {
        const c0 = i >= BEADS - d0 ? 1 : 0;
        const c1 = i >= BEADS - d1 ? 1 : 0;
        if (c0 === c1) continue;
        const order = c1 > c0 ? BEADS - d0 - 1 - i : i - (BEADS - d0);
        rod[i].push({ at: times[k] + delay + order * 0.7, from: c0, to: c1 });
      }
    }
    moves.push(rod);
  }
  return moves;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function AbacusCount({
  value = 48216,
  label = "renders this week",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: AbacusCountProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const target = Math.max(0, Math.min(999999, Math.round(value)));
  const places = Math.max(3, String(target).length);
  const { seq, times } = useMemo(
    () => buildSteps(target, places),
    [target, places],
  );
  const moves = useMemo(
    () => buildMoves(seq, times, places),
    [seq, times, places],
  );

  let kNow = 0;
  for (let k = 0; k < times.length; k++) if (t >= times[k]) kNow = k;
  const lead = leadOf(seq[kNow]);
  const lastAt = times[times.length - 1];

  const cx = width / 2;
  const cy = height / 2;
  const D = 32 * u;
  const rodGap = 58 * u;
  const pad = 6 * u;
  const travel = 5.5 * D;
  const rodLen = BEADS * D + travel + 2 * pad;
  const postW = 5 * u;
  const numSize = 132 * u;
  const cell = numSize * 0.58;
  const commaW = numSize * 0.28;
  const commas = Math.floor((places - 1) / 3);
  const readW = places * cell + commas * commaW;
  const gapX = 88 * u;
  const totalW = rodLen + 2 * postW + gapX + readW;
  const x0 = cx - totalW / 2 + postW;
  const x1 = x0 + rodLen;
  const readX = x1 + postW + gapX;
  const abH = (places - 1) * rodGap;
  const rodY = (row: number) => cy - abH / 2 + row * rodGap;
  const postTop = rodY(0) - D / 2 - 18 * u;
  const postBot = rodY(places - 1) + D / 2 + 18 * u;

  const restX = (i: number) => x0 + pad + i * D + D / 2;
  const countX = (i: number) => x1 - pad - (BEADS - 1 - i) * D - D / 2;

  const frameIn = interpolate(t, [0, 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [0, lastAt + 40], [0.985, 1.01], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const gradId = `ab${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const drift = interpolate(t, [0, lastAt + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const leadGrad = `linear-gradient(${165 - 10 * drift}deg, ${p.stops[0]} 0%, ${p.stops[1]} 30%, ${p.stops[2]} 66%, ${p.stops[3]} 100%)`;

  const rodsEls: ReactNode[] = [];
  const beadEls: ReactNode[] = [];
  for (let row = 0; row < places; row++) {
    const pl = places - 1 - row;
    const y = rodY(row);
    const rodK = interpolate(t, [2 + row * 2, 18 + row * 2], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    rodsEls.push(
      <line
        key={`r${pl}`}
        x1={x0}
        y1={y}
        x2={x0 + rodLen * rodK}
        y2={y}
        stroke={p.rod}
        strokeWidth={Math.max(1, 1.5 * u)}
      />,
    );
    const xs: number[] = [];
    const states: number[] = [];
    for (let i = 0; i < BEADS; i++) {
      let st = i >= BEADS - digitAt(seq[0], pl) ? 1 : 0;
      for (const m of moves[pl][i]) {
        if (t < m.at) break;
        st +=
          (m.to - m.from) *
          spring({ frame: t - m.at, fps, config: BEAD_SPRING });
      }
      states.push(st);
      xs.push(restX(i) + (countX(i) - restX(i)) * st);
    }
    for (let i = 1; i < BEADS; i++) xs[i] = Math.max(xs[i], xs[i - 1] + D);
    for (let i = BEADS - 2; i >= 0; i--) xs[i] = Math.min(xs[i], xs[i + 1] - D);
    for (let i = 0; i < BEADS; i++) {
      const bIn = interpolate(
        t,
        [6 + row * 2 + i * 0.6, 14 + row * 2 + i * 0.6],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      const by = y + (1 - bIn) * -6 * u;
      const br = D / 2 - 0.75 * u;
      const lit = Math.max(0, Math.min(1, states[i]));
      beadEls.push(
        <g key={`b${pl}-${i.toString()}`} opacity={bIn}>
          <circle cx={xs[i]} cy={by} r={br} fill={p.bead} />
          {lit > 0 ? (
            <circle
              cx={xs[i]}
              cy={by}
              r={br}
              fill={`url(#${gradId})`}
              opacity={lit}
            />
          ) : null}
        </g>,
      );
    }
  }

  const digitEls: ReactNode[] = [];
  for (let pl = places - 1; pl >= 0; pl--) {
    let kc = 0;
    for (let k = 1; k <= kNow; k++) {
      if (digitAt(seq[k], pl) !== digitAt(seq[k - 1], pl)) kc = k;
    }
    const tick =
      kc === 0
        ? 1
        : interpolate(t, [times[kc], times[kc] + TICK], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
    const dNew = digitAt(seq[kc], pl);
    const isLead = pl === lead;
    const color = pl > lead ? p.faint : isLead ? "transparent" : p.fg;
    digitEls.push(
      <span
        key={`d${pl}`}
        style={{
          display: "inline-block",
          width: cell,
          textAlign: "center",
          color,
          ...(isLead
            ? {
                backgroundImage: leadGrad,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
              }
            : null),
          opacity: 0.8 + 0.2 * tick,
          transform: `translateY(${(1 - tick) * 6}%)`,
        }}
      >
        {dNew}
      </span>,
    );
    if (pl > 0 && pl % 3 === 0) {
      digitEls.push(
        <span
          key={`c${pl}`}
          style={{
            display: "inline-block",
            width: commaW,
            textAlign: "center",
            color: pl > lead ? p.faint : p.fg,
          }}
        >
          ,
        </span>,
      );
    }
  }

  const labelIn = interpolate(t, [lastAt + 6, lastAt + 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const blockH = numSize * 1.12 + 10 * u + 24 * u * 1.3;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(75% 55% at ${46 + 6 * drift}% 112%, color-mix(in oklab, ${RISE.c[2]} ${p.ground * 100}%, transparent) 0%, color-mix(in oklab, ${RISE.c[3]} ${p.ground * 100}%, transparent) 45%, transparent 100%)`,
          opacity: frameIn,
        }}
      />
      <AbsoluteFill
        style={{ transform: `scale(${push})`, transformOrigin: "50% 50%" }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <g opacity={frameIn}>
            <rect
              x={x0 - postW}
              y={postTop}
              width={postW}
              height={postBot - postTop}
              rx={postW / 2}
              fill={p.post}
            />
            <rect
              x={x1}
              y={postTop}
              width={postW}
              height={postBot - postTop}
              rx={postW / 2}
              fill={p.post}
            />
          </g>
          <defs>
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={x1 - travel * (1.1 + 0.15 * drift)}
              y1={postTop}
              x2={x1}
              y2={postBot}
            >
              <stop offset="0" stopColor={p.stops[0]} />
              <stop offset="0.34" stopColor={p.stops[1]} />
              <stop offset="0.7" stopColor={p.stops[2]} />
              <stop offset="1" stopColor={p.stops[3]} />
            </linearGradient>
          </defs>
          {rodsEls}
          {beadEls}
        </svg>

        <div
          style={{
            position: "absolute",
            left: readX,
            top: cy - blockH / 2,
            opacity: frameIn,
          }}
        >
          <div
            style={{
              display: "flex",
              fontFamily: geist,
              fontWeight: 300,
              fontSize: numSize,
              lineHeight: 1.12,
              letterSpacing: "-0.03em",
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
            }}
          >
            {digitEls}
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 12 * u,
              marginTop: 10 * u,
              paddingLeft: numSize * 0.06,
              fontFamily: geist,
              fontWeight: 400,
              fontSize: 24 * u,
              lineHeight: 1.3,
              letterSpacing: "-0.01em",
              color: p.muted,
              whiteSpace: "nowrap",
              opacity: labelIn,
              transform: `translateY(${(1 - labelIn) * 8 * u}px)`,
            }}
          >
            <span
              style={{
                width: 10 * u,
                height: 10 * u,
                borderRadius: "50%",
                background: accent,
                flexShrink: 0,
              }}
            />
            {label}
          </div>
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadVariableFont } from "@remotion/google-fonts/Jost";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const jost = loadVariableFont("normal", { subsets: ["latin"] });

export interface AbsorbStackProps {
  lines?: string[];
  accentLine?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2A1C17", ink: "#E8C9B0", accent: "#C8102E" },
  light: { bg: "#EAD3C3", ink: "#2A1C17", accent: "#C8102E" },
} as const;

const LEADING = 1.02;
const WEIGHT = 400;
const ENTER_LEN = 12;
const SETTLE_AT = 14;
const RING_GAP = 5;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

export function AbsorbStack({
  lines = ["made to", "sink into", "your cut,", "not sit", "on top."],
  accentLine,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: AbsorbStackProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const c = THEMES[theme];
  const hot = accent ?? c.accent;
  const bg = background ?? c.bg;
  const n = Math.max(1, lines.length);
  const hotIndex = accentLine ?? n - 1;

  const fs = Math.min(height * 0.125, width * 0.1);
  const pitch = fs * LEADING;
  const mid = (n - 1) / 2;
  const centreY = height * 0.5;
  const spreadPitch = n > 1 ? (height * 0.84) / (n - 1) : 0;

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {lines.map((line, i) => {
        const offset = i - mid;
        const ring = Math.abs(offset);
        const enter = interpolate(
          frame,
          [ring * 3, ring * 3 + ENTER_LEN],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_OUT,
          },
        );
        const settle = spring({
          frame: frame - SETTLE_AT - ring * RING_GAP,
          fps,
          config: { damping: 20, stiffness: 70, mass: 1 },
        });
        const from = centreY + offset * spreadPitch;
        const to = centreY + offset * pitch;
        const y = from + (to - from) * settle;
        const drift = interpolate(
          enter,
          [0, 1],
          [offset >= 0 ? 0.25 : -0.25, 0],
        );
        const sat = interpolate(settle, [0, 1], [72, 100], CLAMP);
        const ink = i === hotIndex ? hot : c.ink;
        return (
          <div
            key={`${i}-${line}`}
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: y - pitch / 2,
              height: pitch,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: jost.fontFamily,
              fontWeight: WEIGHT,
              fontSize: fs,
              lineHeight: 1,
              letterSpacing: "-0.025em",
              textTransform: "lowercase",
              whiteSpace: "pre",
              color: `color-mix(in oklab, ${ink} ${sat.toFixed(1)}%, ${bg})`,
              opacity: enter,
              transform: `translateY(${(drift * fs).toFixed(2)}px)`,
            }}
          >
            {line}
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

"use client";

import type React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type AccordionUnfoldProps = {
  /** Lockup printed across the card. Use a color that reads on `color`. Falls back to a placeholder "remocn" lockup. */
  children?: React.ReactNode;
  /** Number of vertical pleats. */
  panels?: number;
  /** Paper color of the card. */
  color?: string;
  /** Darkness of the panels facing away from the light, 0 to 1. */
  shade?: number;
  backgroundColor?: string;
  /** Fold angle of each pleat at the start, in degrees. */
  foldAngle?: number;
  speed?: number;
};

export const accordionUnfoldDefaults = {
  panels: 6,
  color: "#FFFFFF",
  shade: 0.55,
  backgroundColor: "#111111",
  foldAngle: 82,
  speed: 1,
};

const START = 4;
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const PLACEHOLDER_FONT =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Helvetica, Arial, sans-serif";

// Neutral lockup shown when no children are passed.
function PlaceholderLockup({
  mark,
  dot,
  text,
  scale = 1,
}: {
  mark: string;
  dot: string;
  text: string;
  scale?: number;
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28 * scale }}>
      <div
        style={{
          width: 120 * scale,
          height: 120 * scale,
          borderRadius: 32 * scale,
          backgroundColor: mark,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36 * scale,
            height: 36 * scale,
            borderRadius: "50%",
            backgroundColor: dot,
          }}
        />
      </div>
      <span
        style={{
          fontFamily: PLACEHOLDER_FONT,
          fontSize: 104 * scale,
          fontWeight: 800,
          letterSpacing: "-0.04em",
          color: text,
        }}
      >
        remocn
      </span>
    </div>
  );
}

export function AccordionUnfold(props: AccordionUnfoldProps) {
  const { children, panels, color, shade, backgroundColor, foldAngle, speed } =
    { ...accordionUnfoldDefaults, ...props };
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = frame * Math.max(0, speed);
  const n = Math.max(2, Math.round(panels));
  const cardW = Math.round(Math.min(width * 0.66, height * 1.3));
  const cardH = Math.round(Math.min(height * 0.4, cardW * 0.4));
  const pw = cardW / n;

  const open = spring({
    frame: t - START,
    fps,
    config: { damping: 15, stiffness: 70, mass: 0.9 },
  });
  const theta = foldAngle * (1 - open);
  const rad = (theta * Math.PI) / 180;
  // Keep the pleated stack centered while its projected width grows.
  const shift = (cardW - cardW * Math.cos(rad)) / 2;
  const lift = interpolate(t, [0, START + 2], [0.92, 1], clamp);
  const appear = interpolate(t, [0, 3], [0, 1], clamp);
  const flat = Math.abs(theta) < 0.3;

  const print = (offset: number) => (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: -offset,
        width: cardW,
        height: cardH,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {children ?? (
        <PlaceholderLockup
          mark={backgroundColor}
          dot={color}
          text={backgroundColor}
          scale={0.8}
        />
      )}
    </div>
  );

  const panel = (i: number): React.ReactNode => {
    if (i >= n) return null;
    const angle = i === 0 ? theta : (i % 2 === 1 ? -2 : 2) * theta;
    const facing = i % 2 === 0 ? 1 : -1;
    const tilt = Math.abs(Math.sin(rad));
    const darkness = facing > 0 ? shade * tilt : shade * 0.25 * tilt;
    return (
      <div
        style={{
          position: "absolute",
          top: 0,
          left: i === 0 ? 0 : pw,
          width: pw,
          height: cardH,
          transformOrigin: "0% 50%",
          transform: `rotateY(${angle}deg)`,
          transformStyle: "preserve-3d",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            // A hair of bleed hides antialiased seams between pleats.
            width: pw + 1,
            overflow: "hidden",
            backgroundColor: color,
            backfaceVisibility: "hidden",
          }}
        >
          {print(i * pw)}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                facing > 0
                  ? `linear-gradient(90deg, rgba(0,0,0,${darkness * 0.6}), rgba(0,0,0,${darkness}))`
                  : `linear-gradient(90deg, rgba(255,255,255,${0.12 * tilt}), rgba(0,0,0,${darkness}))`,
            }}
          />
        </div>
        {panel(i + 1)}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor,
        alignItems: "center",
        justifyContent: "center",
        perspective: cardW * 1.8,
      }}
    >
      <div
        style={{
          position: "relative",
          width: cardW,
          height: cardH,
          opacity: appear,
          transform: `translateX(${shift}px) scale(${lift})`,
          transformStyle: "preserve-3d",
        }}
      >
        {flat ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: color,
              overflow: "hidden",
            }}
          >
            {print(0)}
          </div>
        ) : (
          panel(0)
        )}
      </div>
    </AbsoluteFill>
  );
}

