export function AchievementPop({
  achievements = [
    {
      label: "Unlocked · 64% of makers",
      title: "Shipped in one day",
      points: 100,
      icon: "trophy",
    },
    {
      label: "Unlocked · 23% of makers",
      title: "Zero keyframes by hand",
      points: 50,
      icon: "bolt",
    },
    {
      label: "Rare · 1.8% of makers",
      title: "Launch video shipped",
      points: 250,
      icon: "star",
    },
  ],
  theme = "dark",
  ground,
  groundParams,
  speed = 1,
}: AchievementPopProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const tall = H > W;
  const dark = theme === "dark";
  const c = THEMES[theme];
  const u = tall ? (W * 0.88) / 820 : Math.min(W / 1280, H / 720);
  const resolvedGround: GshPresetId | undefined =
    ground ?? (groundParams ? undefined : dark ? "kiln" : undefined);
  const resolvedParams = groundParams ?? (dark ? DARK_GROUND : LIGHT_GROUND);

  const list = achievements.slice(0, BEATS.starts.length);
  const n = list.length;
  const starts = BEATS.starts.slice(0, n);
  const lastStart = starts[n - 1] ?? BEATS.starts[0];

  const ph = 116 * u;
  const D = ph;
  const pw = 820 * u;
  const gap = ph + 20 * u;
  const cy = tall ? 0.4 * H : 0.46 * H;

  const sp = (from: number, config: Partial<typeof CARD>, dur?: number) =>
    spring({
      frame: t - from,
      fps,
      config,
      durationInFrames: dur,
    });

  const kf =
    1 + starts.slice(1).reduce((a, s) => a + sp(s - BEATS.shiftLead, CARD), 0);
  const posterAt = lastStart + BEATS.poster;
  const poster = sp(posterAt, HEAVY);
  const stackK = interpolate(kf, [1, 2, 3], [1.26, 1.1, 1], CLAMP);
  const groupK = stackK * interpolate(poster, [0, 1], [1, tall ? 1.04 : 1.12]);
  const logoP = interpolate(
    t,
    [posterAt + BEATS.logo, posterAt + BEATS.logo + 14],
    [0, 1],
    { ...CLAMP, easing: ENTER },
  );

  const total = list.reduce(
    (a, item, i) =>
      a +
      item.points *
        interpolate(t, [starts[i] + 10, starts[i] + 22], [0, 1], {
          ...CLAMP,
          easing: ENTER,
        }),
    0,
  );
  const totalIn = interpolate(t, [starts[0] + 8, starts[0] + 22], [0, 1], {
    ...CLAMP,
    easing: ENTER,
  });

  return (
    <AbsoluteFill style={{ background: c.base, overflow: "hidden" }}>
      <GshGround
        preset={resolvedGround}
        params={resolvedParams}
        timeOffset={dark ? 5 : 3}
        timeScale={0.45}
      />
      <AbsoluteFill style={{ background: c.scrim }} />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${groupK})`,
          transformOrigin: `50% ${(cy / H) * 100}%`,
        }}
      >
        {list.map((a, i) => {
          const s = starts[i];
          if (t < s) return null;
          const rare = i === n - 1 && n > 1;
          const y = cy + (i - (kf - 1) / 2) * gap;
          const pop = sp(s, CHIP);
          const badgeK = 0.5 + 0.5 * pop;
          const open = sp(s + BEATS.open, MORPH, 16);
          const pillW = D + (pw - D) * open;
          const left = W / 2 - pillW / 2;
          const textP = interpolate(
            t,
            [s + BEATS.open + 4, s + BEATS.open + 16],
            [0, 1],
            { ...CLAMP, easing: ENTER },
          );
          const ptsP = interpolate(
            t,
            [s + BEATS.open + 8, s + BEATS.open + 20],
            [0, 1],
            { ...CLAMP, easing: ENTER },
          );
          const flashP = interpolate(t, [s + 2, s + 16], [0, 1], {
            ...CLAMP,
            easing: ENTER,
          });
          const sheen = interpolate(
            t,
            [s + BEATS.open + 14, s + BEATS.open + 32],
            [0, 1],
            { ...CLAMP, easing: Easing.bezier(0.65, 0, 0.35, 1) },
          );
          const ink = rare ? "#FFF4E8" : c.ink;
          const dim = rare ? "rgba(255,233,199,0.72)" : c.dim;
          const bx = left + D / 2;
          const R = D / 2;
          const appear = interpolate(t, [s, s + 3], [0, 1], CLAMP);
          return (
            <div key={`${a.title}-${s}`}>
              <div
                style={{
                  position: "absolute",
                  left,
                  top: y - ph / 2,
                  width: pillW,
                  height: ph,
                  borderRadius: ph / 2,
                  overflow: "hidden",
                  background: rare ? RARE_FILL : c.pill,
                  boxShadow: rare
                    ? `inset 0 1px 0 rgba(255,233,199,0.28), 0 0 0 1px rgba(255,154,58,0.28), 0 22px 48px -14px rgba(120,24,4,${dark ? 0.8 : 0.45})`
                    : c.depth,
                  opacity: appear,
                }}
              >
                {rare && sheen > 0 && sheen < 1 ? (
                  <div
                    style={{
                      position: "absolute",
                      top: 0,
                      bottom: 0,
                      width: 160 * u,
                      left: interpolate(sheen, [0, 1], [-200 * u, pw + 40 * u]),
                      background:
                        "linear-gradient(100deg, transparent 0%, rgba(255,233,199,0.32) 50%, transparent 100%)",
                      transform: "skewX(-20deg)",
                    }}
                  />
                ) : null}
                <div
                  style={{
                    position: "absolute",
                    left: D + 22 * u,
                    top: 0,
                    bottom: 0,
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    gap: 10 * u,
                    opacity: textP,
                    transform: `translateX(${(1 - textP) * -24 * u}px)`,
                    whiteSpace: "nowrap",
                  }}
                >
                  <div
                    style={{
                      fontFamily: mono,
                      fontWeight: 400,
                      fontSize: 17 * u,
                      lineHeight: 1,
                      letterSpacing: "0.04em",
                      textTransform: "uppercase",
                      color: dim,
                    }}
                  >
                    {a.label}
                  </div>
                  <div
                    style={{
                      fontFamily: geist,
                      fontWeight: 400,
                      fontSize: 40 * u,
                      lineHeight: 1,
                      letterSpacing: "-0.03em",
                      color: ink,
                    }}
                  >
                    {a.title}
                  </div>
                </div>
                <div
                  style={{
                    position: "absolute",
                    left: pw - 220 * u,
                    width: 180 * u,
                    top: 0,
                    bottom: 0,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "flex-end",
                    gap: 8 * u,
                    opacity: ptsP,
                    transform: `translateX(${(1 - ptsP) * -16 * u}px)`,
                    whiteSpace: "nowrap",
                  }}
                >
                  <span
                    style={{
                      fontFamily: geist,
                      fontWeight: 300,
                      fontSize: 40 * u,
                      lineHeight: 1,
                      letterSpacing: "-0.03em",
                      fontVariantNumeric: "tabular-nums",
                      color: ink,
                    }}
                  >
                    +{a.points}
                  </span>
                  <span
                    style={{
                      fontFamily: mono,
                      fontWeight: 400,
                      fontSize: 17 * u,
                      letterSpacing: "0.04em",
                      color: dim,
                      transform: `translateY(${4 * u}px)`,
                    }}
                  >
                    XP
                  </span>
                </div>
              </div>

              {flashP > 0 && flashP < 1 ? (
                <svg
                  width={W}
                  height={H}
                  style={{
                    position: "absolute",
                    inset: 0,
                    overflow: "visible",
                  }}
                  aria-hidden
                >
                  <circle
                    cx={bx}
                    cy={y}
                    r={R * interpolate(flashP, [0, 1], [0.9, 1.7])}
                    fill="none"
                    stroke={rare ? KILN[2] : c.flash}
                    strokeWidth={interpolate(flashP, [0, 1], [5, 0.5]) * u}
                    opacity={(1 - flashP) * 0.9}
                  />
                </svg>
              ) : null}

              <div
                style={{
                  position: "absolute",
                  left: bx - R,
                  top: y - R,
                  width: D,
                  height: D,
                  transform: `scale(${badgeK})`,
                  opacity: appear,
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    inset: 10 * u,
                    borderRadius: "50%",
                    background: rare ? "rgba(255,233,199,0.12)" : c.badge,
                    boxShadow: rare
                      ? "inset 0 0 0 1px rgba(255,233,199,0.45)"
                      : `inset 0 0 0 1px ${c.ring}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <Icon name={a.icon ?? "trophy"} size={40 * u} color={ink} />
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {tall ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: 0.66 * H,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 18 * u,
            opacity: totalIn,
            transform: `translateY(${(1 - totalIn) * 24 * u}px)`,
          }}
        >
          <div
            style={{
              fontFamily: mono,
              fontWeight: 400,
              fontSize: 20 * u,
              letterSpacing: "0.06em",
              textTransform: "uppercase",
              color: c.dim,
            }}
          >
            Launch week
          </div>
          <div
            style={{
              fontFamily: geist,
              fontWeight: 300,
              fontSize: 170 * u,
              lineHeight: 1,
              letterSpacing: "-0.05em",
              fontVariantNumeric: "tabular-nums",
              color: c.ink,
            }}
          >
            {Math.round(total)}
            <span
              style={{ fontSize: 56 * u, letterSpacing: "0", color: c.dim }}
            >
              {" "}
              XP
            </span>
          </div>
        </div>
      ) : null}

      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: tall ? 0.88 * H : 0.885 * H,
          display: "flex",
          justifyContent: "center",
          opacity: logoP,
          transform: `translateY(${(1 - logoP) * 14 * u}px)`,
        }}
      >
        <RemocnLogo fontSize={30 * u} color={c.logo} />
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadSora } from "@remotion/google-fonts/Sora";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const sora = loadSora("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const mono = loadMono("normal", { weights: ["500"], subsets: ["latin"] });

export interface AcronymExpandProps {
  short?: string;
  full?: string;
  eyebrow?: string;
  subhead?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    ground: [
      `radial-gradient(46% 58% at 50% 52%, color-mix(in oklab, ${LIMB[3]} 85%, transparent) 0%, transparent 72%)`,
      `radial-gradient(30% 34% at 50% 50%, color-mix(in oklab, ${LIMB[2]} 22%, transparent) 0%, transparent 80%)`,
    ].join(", "),
    init: (a: string) =>
      `linear-gradient(120deg, ${LIMB[0]} 0%, ${LIMB[1]} 42%, color-mix(in oklab, ${a} 75%, ${LIMB[1]}) 72%, ${LIMB[1]} 100%)`,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    ground: [
      `radial-gradient(46% 58% at 50% 52%, color-mix(in oklab, ${LIMB[0]} 90%, transparent) 0%, transparent 72%)`,
      `radial-gradient(30% 34% at 50% 50%, color-mix(in oklab, ${LIMB[1]} 16%, transparent) 0%, transparent 80%)`,
    ].join(", "),
    init: (a: string) =>
      `linear-gradient(120deg, ${LIMB[2]} 0%, ${a} 46%, ${LIMB[1]} 100%)`,
  },
} as const;

const TRACK_SHORT = -0.02;
const TRACK_FULL = -0.035;
const LINE = 1.08;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.72, 0, 0.18, 1);
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

type Measure = ((s: string) => number) & {
  base: number;
};

function useMeasure(): Measure {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("acronym-expand: measuring"));
  const released = useRef(false);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);

  useEffect(() => {
    let live = true;
    const font = `500 100px "${sora.fontFamily}"`;
    Promise.all([sora.waitUntilDone(), document.fonts.load(font)])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        if (ctx) ctx.font = font;
        ctxRef.current = ctx;
        setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);

  const ctx = ready ? ctxRef.current : null;
  const fn = (s: string) =>
    ctx ? ctx.measureText(s).width / 100 : s.length * 0.6;
  let asc = 0.97;
  let desc = 0.24;
  if (ctx) {
    const m = ctx.measureText("Hg");
    asc = m.fontBoundingBoxAscent / 100 || asc;
    desc = m.fontBoundingBoxDescent / 100 || desc;
  }
  return Object.assign(fn, { base: (LINE - asc - desc) / 2 + asc });
}

function matchInitials(short: string, full: string) {
  const lower = full.toLowerCase();
  const starts = new Set<number>();
  for (let i = 0; i < full.length; i++) {
    if (full[i] !== " " && (i === 0 || full[i - 1] === " ")) starts.add(i);
  }
  const out: number[] = [];
  let from = 0;
  for (const ch of short.toLowerCase()) {
    if (ch === " ") {
      out.push(-1);
      continue;
    }
    let hit = -1;
    for (let i = from; i < lower.length; i++) {
      if (lower[i] === ch && starts.has(i)) {
        hit = i;
        break;
      }
    }
    if (hit < 0) hit = lower.indexOf(ch, from);
    out.push(hit);
    if (hit >= 0) from = hit + 1;
  }
  return out;
}

function splitTwo(words: string[], measure: Measure) {
  let best = { a: words.join(" "), b: "", w: Number.POSITIVE_INFINITY };
  for (let k = 1; k < words.length; k++) {
    const a = words.slice(0, k).join(" ");
    const b = words.slice(k).join(" ");
    const w = Math.max(measure(a), measure(b));
    if (w < best.w) best = { a, b, w };
  }
  return best;
}

interface Glyph {
  ch: string;
  x: number;
  y: number;
  fs: number;
  w: number;
}

function placeLine(
  text: string,
  measure: Measure,
  fs: number,
  track: number,
  cx: number,
  top: number,
): Glyph[] {
  const total = measure(text) + track * Math.max(0, text.length - 1);
  const left = cx - (total * fs) / 2;
  const out: Glyph[] = [];
  for (let i = 0; i < text.length; i++) {
    const x = left + (measure(text.slice(0, i)) + track * i) * fs;
    const w = (measure(text.slice(0, i + 1)) - measure(text.slice(0, i))) * fs;
    out.push({ ch: text[i], x, y: top, fs, w });
  }
  return out;
}

export function AcronymExpand({
  short = "MCP",
  full = "Model Context Protocol",
  eyebrow = "Now in remocn",
  subhead = "Your agent browses, installs and edits every component.",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: AcronymExpandProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const t = THEMES[theme];
  const measure = useMeasure();

  const portrait = height > width * 1.1;
  const s = portrait ? width / 1080 : Math.min(width / 1280, height / 720);
  const maxW = width * (portrait ? 0.84 : 0.8);
  const cx = width / 2;

  const words = full.split(/\s+/).filter(Boolean);
  const oneEm = measure(full) + TRACK_FULL * Math.max(0, full.length - 1);
  const capFull = (portrait ? 156 : 112) * s;
  let lines = [words.join(" ")];
  let fsF = Math.min(capFull, maxW / Math.max(oneEm, 0.01));
  if (words.length > 1) {
    const two = splitTwo(words, measure);
    const twoEm = two.w + TRACK_FULL * Math.max(two.a.length, two.b.length);
    const fsTwo = Math.min(capFull, maxW / Math.max(twoEm, 0.01));
    if (fsTwo > fsF * 1.3 || portrait) {
      lines = [two.a, two.b];
      fsF = fsTwo;
    }
  }

  const eyeFs = (portrait ? 26 : 19) * s;
  const subFs = (portrait ? 34 : 26) * s;
  const eyeH = eyebrow ? eyeFs * 1.2 + fsF * 0.42 : 0;
  const fullH = lines.length * LINE * fsF;
  const subH = subhead ? fsF * 0.34 + subFs * 1.4 * (portrait ? 2 : 1) : 0;
  const stackTop = height / 2 - (eyeH + fullH + subH) / 2;
  const fullTop = stackTop + eyeH;
  const fullCy = fullTop + fullH / 2;

  const fullGlyphs: Glyph[] = [];
  lines.forEach((ln, i) => {
    for (const g of placeLine(
      ln,
      measure,
      fsF,
      TRACK_FULL,
      cx,
      fullTop + i * LINE * fsF,
    )) {
      fullGlyphs.push(g);
    }
    if (i < lines.length - 1)
      fullGlyphs.push({ ch: " ", x: 0, y: 0, fs: fsF, w: 0 });
  });
  const joined = lines.join(" ");

  const shortEm = measure(short) + TRACK_SHORT * Math.max(0, short.length - 1);
  const fsS = Math.min(
    (portrait ? 330 : 300) * s,
    (maxW * 0.86) / Math.max(shortEm, 0.01),
    height * 0.5,
  );
  const shortGlyphs = placeLine(
    short,
    measure,
    fsS,
    TRACK_SHORT,
    cx,
    fullCy - (LINE * fsS) / 2,
  );

  const anchors = matchInitials(short, joined);
  const anchorOf = new Map<number, number>();
  anchors.forEach((fi, si) => {
    if (fi >= 0) anchorOf.set(fi, si);
  });

  const wordSpans: { a: number; b: number; anchor: number }[] = [];
  {
    const re = /\S+/g;
    for (let m = re.exec(joined); m; m = re.exec(joined)) {
      const a = m.index;
      const b = a + m[0].length;
      let anchor = -1;
      for (let i = a; i < b; i++) {
        if (anchorOf.has(i)) {
          anchor = i;
          break;
        }
      }
      wordSpans.push({ a, b, anchor });
    }
  }

  const EXPAND = 38;
  const EXPAND_LEN = 26;
  const anchorT = (si: number) =>
    EASE_IO(clamp01((frame - EXPAND - si * 2) / EXPAND_LEN));
  const drift = interpolate(
    frame,
    [0, durationInFrames * speed],
    [0, 1],
    CLAMP,
  );

  type Draw = {
    id: string;
    ch: string;
    x: number;
    y: number;
    fs: number;
    opacity: number;
    blur: number;
    init: number;
    z: number;
  };
  const draws: Draw[] = [];

  const mid = (short.length - 1) / 2;
  shortGlyphs.forEach((g, si) => {
    if (g.ch === " ") return;
    const e = EASE_OUT(clamp01((frame - si * 3) / 18));
    const spread = (1 - e) * (si - mid) * 0.14 * fsS;
    const fi = anchors[si];
    const u = anchorT(si);
    if (fi < 0) {
      const out = clamp01((frame - EXPAND) / 12);
      draws.push({
        id: `s${si}`,
        ch: g.ch,
        x: g.x + spread,
        y: g.y + (1 - e) * 0.4 * fsS,
        fs: g.fs,
        opacity: e * (1 - out),
        blur: (1 - e) * 0.05 * fsS + out * 0.04 * fsS,
        init: 1,
        z: 2,
      });
      return;
    }
    const f = fullGlyphs[fi];
    const fs = g.fs + (f.fs - g.fs) * u;
    const x = g.x + spread + (f.x - g.x) * u;
    const y = g.y + (1 - e) * 0.4 * fsS + (f.y - g.y) * u;
    const same = g.ch === f.ch;
    const c = same ? 0 : interpolate(u, [0.35, 0.75], [0, 1], CLAMP);
    draws.push({
      id: `s${si}`,
      ch: g.ch,
      x,
      y,
      fs,
      opacity: e * (1 - c),
      blur: (1 - e) * 0.05 * fsS,
      init: 1,
      z: 2,
    });
    if (!same) {
      draws.push({
        id: `s${si}b`,
        ch: f.ch,
        x,
        y,
        fs,
        opacity: c,
        blur: 0,
        init: 1,
        z: 2,
      });
    }
  });

  type Tail = {
    id: string;
    text: string;
    edge: number;
    dir: 1 | -1;
    y: number;
    fs: number;
    w: number;
    v: number;
    max: number;
  };
  const tails: Tail[] = [];
  const runW = (txt: string, fs: number) =>
    (measure(txt) + TRACK_FULL * txt.length) * fs;
  const nowX = new Map<number, number>();
  anchors.forEach((fi, si) => {
    if (fi < 0) return;
    const u = anchorT(si);
    nowX.set(
      fi,
      shortGlyphs[si].x + (fullGlyphs[fi].x - shortGlyphs[si].x) * u,
    );
  });
  const lineOf = (i: number) => (fullGlyphs[i].y > fullTop + 1 ? 1 : 0);
  const room = (from: number, finalRight: number, now: number) => {
    for (const span of wordSpans) {
      if (span.a <= from || span.anchor < 0) continue;
      if (lineOf(span.a) !== lineOf(from)) return Number.POSITIVE_INFINITY;
      const nx = nowX.get(span.anchor) as number;
      const head = fullGlyphs[span.anchor].x - fullGlyphs[span.a].x;
      return nx - head - (fullGlyphs[span.a].x - finalRight) - now;
    }
    return Number.POSITIVE_INFINITY;
  };
  for (const span of wordSpans) {
    if (span.anchor < 0) {
      const v = EASE_OUT(clamp01((frame - EXPAND - 18) / 16));
      for (let i = span.a; i < span.b; i++) {
        const f = fullGlyphs[i];
        draws.push({
          id: `f${i}`,
          ch: f.ch,
          x: f.x,
          y: f.y + (1 - v) * 0.22 * f.fs,
          fs: f.fs,
          opacity: v,
          blur: (1 - v) * 0.06 * f.fs,
          init: 0,
          z: 1,
        });
      }
      continue;
    }
    const si = anchorOf.get(span.anchor) as number;
    const u = anchorT(si);
    const af = fullGlyphs[span.anchor];
    const sg = shortGlyphs[si];
    const ax = sg.x + (af.x - sg.x) * u;
    const ay = sg.y + (af.y - sg.y) * u;
    const afs = sg.fs + (af.fs - sg.fs) * u;
    const aw = af.w * (afs / af.fs);
    const fs = af.fs;
    const y = ay + (afs - fs) * measure.base;
    const v = EASE_OUT(clamp01((frame - EXPAND - si * 2 - 8) / 22));
    const after = joined.slice(span.anchor + 1, span.b);
    const before = joined.slice(span.a, span.anchor);
    if (after) {
      const next = fullGlyphs[span.anchor + 1];
      const gap = next.x - (af.x + af.w);
      const w = runW(after, fs);
      const edge = ax + aw + gap;
      const finalRight = next.x + w;
      tails.push({
        id: `t${span.anchor}`,
        text: after,
        edge,
        dir: 1,
        y,
        fs,
        w,
        v,
        max: room(span.anchor, finalRight, edge),
      });
    }
    if (before) {
      const first = fullGlyphs[span.a];
      tails.push({
        id: `h${span.anchor}`,
        text: before,
        edge: ax - (af.x - first.x - runW(before, fs)),
        dir: -1,
        y,
        fs,
        w: runW(before, fs),
        v,
        max: Number.POSITIVE_INFINITY,
      });
    }
  }

  const eyeT = EASE_OUT(clamp01((frame - 60) / 18));
  const subT = EASE_OUT(clamp01((frame - 66) / 20));
  const transparent = background === "transparent";
  const initImage = t.init(accent);

  const glyphStyle = (d: Draw): React.CSSProperties => ({
    position: "absolute",
    left: d.x,
    top: d.y,
    fontFamily: sora.fontFamily,
    fontWeight: 500,
    fontSize: d.fs,
    lineHeight: LINE,
    whiteSpace: "pre",
    opacity: d.opacity,
    zIndex: d.z,
    filter: d.blur > 0.05 ? `blur(${d.blur.toFixed(2)}px)` : undefined,
    ...(d.init
      ? {
          backgroundImage: initImage,
          backgroundSize: `${width}px ${height}px`,
          backgroundPosition: `${-d.x + (drift - 0.5) * width * 0.08}px ${-d.y}px`,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }
      : { color: t.fg }),
  });

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? t.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: t.ground,
            transform: `scale(${1.04 + drift * 0.04})`,
          }}
        />
      ) : null}

      {eyebrow ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: stackTop + (1 - eyeT) * 10 * s,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: eyeFs * 0.6,
            fontFamily: mono.fontFamily,
            fontWeight: 500,
            fontSize: eyeFs,
            lineHeight: 1.2,
            letterSpacing: "0.12em",
            textTransform: "uppercase",
            color: t.muted,
            opacity: eyeT,
          }}
        >
          <span
            style={{
              width: eyeFs * 0.42,
              height: eyeFs * 0.42,
              borderRadius: 999,
              background: accent,
            }}
          />
          {eyebrow}
        </div>
      ) : null}

      {tails.map((tl) => {
        const pad = tl.fs * 0.25;
        const open = Math.max(
          0,
          Math.min(tl.w * tl.v + pad * tl.v, tl.max + pad * 0.2),
        );
        return (
          <div
            key={tl.id}
            style={{
              position: "absolute",
              left: tl.dir === 1 ? tl.edge : tl.edge - open,
              top: tl.y - pad,
              width: open,
              height: LINE * tl.fs + pad * 2,
              overflow: "hidden",
              zIndex: 1,
            }}
          >
            <span
              style={{
                position: "absolute",
                top: pad,
                ...(tl.dir === 1 ? { left: 0 } : { right: 0 }),
                fontFamily: sora.fontFamily,
                fontWeight: 500,
                fontSize: tl.fs,
                lineHeight: LINE,
                letterSpacing: `${TRACK_FULL}em`,
                whiteSpace: "pre",
                color: t.fg,
                transform: `translateX(${(-(1 - tl.v) * tl.w * 0.45 * tl.dir).toFixed(2)}px)`,
                filter:
                  tl.v < 0.98
                    ? `blur(${((1 - tl.v) * 0.04 * tl.fs).toFixed(2)}px)`
                    : undefined,
              }}
            >
              {tl.text}
            </span>
          </div>
        );
      })}

      {draws.map((d) => (
        <div key={d.id} style={glyphStyle(d)}>
          {d.ch}
        </div>
      ))}

      {subhead ? (
        <div
          style={{
            position: "absolute",
            left: (width - Math.min(maxW, 820 * s * (portrait ? 1.1 : 1))) / 2,
            width: Math.min(maxW, 820 * s * (portrait ? 1.1 : 1)),
            top: fullTop + fullH + fsF * 0.34 + (1 - subT) * 12 * s,
            textAlign: "center",
            fontFamily: sora.fontFamily,
            fontWeight: 400,
            fontSize: subFs,
            lineHeight: 1.4,
            letterSpacing: "-0.01em",
            color: t.muted,
            textWrap: "balance",
            opacity: subT,
            filter: `blur(${((1 - subT) * 5 * s).toFixed(2)}px)`,
          }}
        >
          {subhead}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

/** gradients.sh "beam" (#f4f7ff #8fb4ff #3d5bff #1a1660): the hero ring's light. */
const BEAM = {
  stops: ["#C4D6FF", "#8FB4FF", "#3D5BFF", "#3A2FC4"],
  css: "linear-gradient(135deg, #C4D6FF, #8FB4FF 30%, #3D5BFF 66%, #3A2FC4)",
};

export interface ActivityRing {
  label: string;
  /** The number the label counts up to. */
  value: number;
  /** Optional suffix after the value: "h", "k". */
  unit?: string;
  /** How far past the goal the ring laps, as a fraction: 1.14 = 114%. */
  goal?: number;
}

export interface ActivityRingsProps {
  /** Up to three rings, outermost first. */
  rings?: ActivityRing[];
  /** Small heading above the readouts. */
  title?: string;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_RINGS: ActivityRing[] = [
  { label: "Renders", value: 1284, goal: 1.14 },
  { label: "Templates", value: 42, goal: 1.08 },
  { label: "Hours saved", value: 310, goal: 1.05 },
];

const EASE_FILL = Easing.bezier(0.55, 0, 0.18, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    key: "radial-gradient(ellipse 38% 62% at 36% 50%, rgba(61,91,255,0.16), rgba(26,22,96,0.10) 55%, transparent 100%)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.12)",
    neutrals: ["#BEBCB6", "#6A686E"],
    track: 0.13,
    capShadow: "rgba(0,0,0,0.65)",
    grain: 0.07,
  },
  light: {
    bg: "#F5F4F0",
    key: "radial-gradient(ellipse 50% 70% at 36% 46%, rgba(255,255,255,0.95), transparent 70%)",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.12)",
    neutrals: ["#5E5C57", "#B3B0A8"],
    track: 0.11,
    capShadow: "rgba(30,24,16,0.4)",
    grain: 0.045,
  },
} as const;

function rgb(hex: string): number[] | null {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const v = Number.parseInt(m[1], 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}

function alpha(color: string, a: number) {
  const c = rgb(color);
  if (c) return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
  const m = /^rgb\((\d+),(\d+),(\d+)\)$/.exec(color);
  if (m) return `rgba(${m[1]},${m[2]},${m[3]},${a})`;
  return color;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const fmt = (v: number) => Math.round(v).toLocaleString("en-US");

/** Point on a ring at progress `p` (0 = 12 o'clock, clockwise). */
function at(cx: number, cy: number, r: number, p: number) {
  const a = p * Math.PI * 2;
  return { x: cx + r * Math.sin(a), y: cy - r * Math.cos(a), a };
}

function Ring({
  cx,
  cy,
  r,
  sw,
  p,
  color,
  lapColor,
  track,
  shadow,
  uid,
  u,
}: {
  cx: number;
  cy: number;
  r: number;
  sw: number;
  p: number;
  color: string;
  lapColor: string;
  track: string;
  shadow: string;
  uid: string;
  u: number;
}) {
  const C = 2 * Math.PI * r;
  const clipId = `${uid}c`;
  const blurId = `${uid}b`;
  const base = Math.min(p, 1);
  const lap = Math.max(0, p - 1);
  // the end cap casts a soft shadow forward onto the ring it is about to cover
  const capP = p > 0.75 ? p : 0;
  const end = at(cx, cy, r, capP);
  const fwd = 2.6 * u;
  const capOpacity = interpolate(p, [0.8, 1], [0, 1], CLAMP);
  const rot = `rotate(-90 ${cx} ${cy})`;
  return (
    <g>
      <defs>
        <clipPath id={clipId}>
          <path
            clipRule="evenodd"
            d={`M ${cx - r - sw / 2} ${cy} a ${r + sw / 2} ${r + sw / 2} 0 1 0 ${2 * r + sw} 0 a ${r + sw / 2} ${r + sw / 2} 0 1 0 ${-(2 * r + sw)} 0 Z M ${cx - r + sw / 2} ${cy} a ${r - sw / 2} ${r - sw / 2} 0 1 0 ${2 * r - sw} 0 a ${r - sw / 2} ${r - sw / 2} 0 1 0 ${-(2 * r - sw)} 0 Z`}
          />
        </clipPath>
        <filter id={blurId} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation={2.6 * u} />
        </filter>
      </defs>
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        stroke={track}
        strokeWidth={sw}
      />
      {base > 0.001 ? (
        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke={color}
          strokeWidth={sw}
          strokeLinecap={base >= 1 ? "butt" : "round"}
          strokeDasharray={base >= 1 ? undefined : `${base * C} ${C}`}
          transform={rot}
        />
      ) : null}
      {capP > 0 ? (
        <g clipPath={`url(#${clipId})`} opacity={capOpacity}>
          <circle
            cx={end.x + Math.cos(end.a) * fwd}
            cy={end.y + Math.sin(end.a) * fwd}
            r={sw / 2}
            fill={shadow}
            filter={`url(#${blurId})`}
          />
        </g>
      ) : null}
      {lap > 0.0005 ? (
        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke={lapColor}
          strokeWidth={sw}
          strokeLinecap="round"
          strokeDasharray={`${lap * C} ${C}`}
          transform={rot}
        />
      ) : capP > 0 ? (
        // redraw the cap over its own shadow while still inside the first lap
        <circle cx={end.x} cy={end.y} r={sw / 2} fill={color} />
      ) : null}
    </g>
  );
}

export function ActivityRings({
  rings = DEFAULT_RINGS,
  title = "This month",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: ActivityRingsProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = frame * speed;
  const u = Math.min(width / 1280, height / 720);
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const list = rings.slice(0, 3);

  // hero ring carries the gradient; the others stay neutral so the data reads
  const gradId = `${uid}beam`;
  const colors = [accent, c.neutrals[0], c.neutrals[1]];
  const paints = [`url(#${gradId})`, c.neutrals[0], c.neutrals[1]];
  const swatches = [BEAM.css, c.neutrals[0], c.neutrals[1]];

  const cx = width * 0.355;
  const cy = height * 0.5;
  const sw = 26 * u;
  const gap = 8 * u;
  const R0 = 182 * u;
  const radius = (i: number) => R0 - i * (sw + gap);

  // timeline
  const FILL_START = 16;
  const fillEnd = (i: number) => 58 + i * 4; // every ring closes, outermost first
  const HIT = fillEnd(list.length - 1);

  const stageIn = interpolate(t, [0, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const progress = (i: number) => {
    const goal = Math.max(1, list[i].goal ?? 1);
    const p1 = interpolate(t, [FILL_START + i * 4, fillEnd(i)], [0, 1], {
      ...CLAMP,
      easing: EASE_FILL,
    });
    if (t < HIT) return p1;
    const s = spring({
      frame: t - HIT - i * 2,
      fps,
      config: { damping: 15, mass: 0.9, stiffness: 120 },
    });
    return 1 + (goal - 1) * s;
  };

  // the hit: a small bump of the whole object and a check in the centre
  const bump = interpolate(t, [HIT, HIT + 5, HIT + 16], [0, 1, 0], {
    ...CLAMP,
    easing: Easing.bezier(0.65, 0, 0.35, 1),
  });
  const check = spring({
    frame: t - HIT - 1,
    fps,
    config: { damping: 13, mass: 0.6, stiffness: 160 },
  });
  const checkDraw = interpolate(t, [HIT + 3, HIT + 13], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const pulse = interpolate(t, [HIT, HIT + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const push = interpolate(t, [0, HIT + 60], [0, 1], CLAMP);
  const innerR = radius(list.length - 1) - sw / 2;
  const badge = Math.min(32 * u, innerR * 0.42);

  // readouts
  const rowX = width * 0.6;
  const rowH = 108 * u;
  const rowsTop = cy - (list.length * rowH) / 2 + 18 * u;
  const row = (k: number, d = 0) =>
    interpolate(t, [8 + k * 4 + d, 26 + k * 4 + d], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: c.key,
        }}
      />

      {/* rings plane: moves a touch more than the readouts for parallax */}
      <AbsoluteFill
        style={{
          transform: `translateX(${-push * 10 * u}px) scale(${(0.94 + stageIn * 0.06) * (1 + push * 0.02) * (1 + bump * 0.016)})`,
          transformOrigin: `${cx}px ${cy}px`,
          opacity: stageIn,
        }}
      >
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            {/* fixed in space, drifting a few degrees: light falls from the top right */}
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={cx + R0 * Math.cos(-0.9 + push * 0.25)}
              y1={cy + R0 * Math.sin(-0.9 + push * 0.25)}
              x2={cx - R0 * Math.cos(-0.9 + push * 0.25)}
              y2={cy - R0 * Math.sin(-0.9 + push * 0.25)}
            >
              {BEAM.stops.map((col, k) => (
                <stop
                  key={col}
                  offset={k / (BEAM.stops.length - 1)}
                  stopColor={col}
                />
              ))}
            </linearGradient>
          </defs>
          {list.map((ring, i) => (
            <Ring
              key={ring.label}
              cx={cx}
              cy={cy}
              r={radius(i)}
              sw={sw}
              p={progress(i)}
              color={paints[i]}
              lapColor={paints[i]}
              track={alpha(i === 0 ? BEAM.stops[2] : colors[i], c.track)}
              shadow={c.capShadow}
              uid={`${uid}r${i}`}
              u={u}
            />
          ))}
          {/* hit pulse just outside the outer ring */}
          {t >= HIT ? (
            <circle
              cx={cx}
              cy={cy}
              r={R0 + sw / 2 + 6 * u + pulse * 26 * u}
              fill="none"
              stroke={accent}
              strokeWidth={Math.max(1, 1.5 * u)}
              opacity={(1 - pulse) * 0.45}
            />
          ) : null}
          {/* centre check */}
          {t >= HIT ? (
            <g
              transform={`translate(${cx} ${cy}) scale(${0.82 + check * 0.18})`}
              opacity={Math.min(1, check * 1.6)}
            >
              <circle r={badge} fill={`url(#${gradId})`} />
              <path
                d={`M ${-badge * 0.36} ${badge * 0.02} L ${-badge * 0.1} ${badge * 0.28} L ${badge * 0.38} ${-badge * 0.24}`}
                fill="none"
                stroke="#FFFFFF"
                strokeWidth={badge * 0.15}
                strokeLinecap="round"
                strokeLinejoin="round"
                pathLength={1}
                strokeDasharray="1 1"
                strokeDashoffset={1 - checkDraw}
              />
            </g>
          ) : null}
        </svg>
      </AbsoluteFill>

      {/* readouts */}
      <AbsoluteFill
        style={{
          transform: `translateX(${-push * 5 * u}px)`,
          fontFamily: sans,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: rowX,
            top: rowsTop - 58 * u,
            display: "flex",
            alignItems: "center",
            gap: 12 * u,
            opacity: row(0, -6),
            transform: `translateY(${(1 - row(0, -6)) * 10 * u}px)`,
          }}
        >
          <span
            style={{
              color: c.fg,
              fontWeight: 500,
              fontSize: 18 * u,
              letterSpacing: "-0.01em",
            }}
          >
            {title}
          </span>
          <span
            style={{
              width: 200 * u * row(0, -2),
              height: Math.max(1, u),
              background: c.hair,
            }}
          />
        </div>
        {list.map((ring, i) => {
          const p = progress(i);
          const v = ring.value * Math.min(1, p);
          const over = Math.round((p - 1) * 100);
          const overIn = interpolate(
            t,
            [HIT + 4 + i * 3, HIT + 16 + i * 3],
            [0, 1],
            {
              ...CLAMP,
              easing: EASE_OUT,
            },
          );
          const r = row(i + 1);
          return (
            <div
              key={ring.label}
              style={{
                position: "absolute",
                left: rowX,
                top: rowsTop + i * rowH,
                display: "flex",
                flexDirection: "column",
                gap: 6 * u,
                overflow: "hidden",
                paddingBottom: 4 * u,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 10 * u,
                  transform: `translateY(${(1 - r) * 120}%)`,
                }}
              >
                <span
                  style={{
                    width: 10 * u,
                    height: 10 * u,
                    borderRadius: "50%",
                    background: swatches[i],
                  }}
                />
                <span
                  style={{
                    color: c.muted,
                    fontWeight: 400,
                    fontSize: 17 * u,
                    letterSpacing: "-0.005em",
                  }}
                >
                  {ring.label}
                </span>
              </div>
              <div
                style={{
                  display: "flex",
                  alignItems: "baseline",
                  gap: 12 * u,
                  transform: `translateY(${(1 - r) * 110}%)`,
                }}
              >
                <span
                  style={{
                    fontWeight: 400,
                    fontSize: 64 * u,
                    lineHeight: 1,
                    letterSpacing: "-0.045em",
                    fontVariantNumeric: "tabular-nums",
                    color: c.fg,
                  }}
                >
                  {fmt(v)}
                  {ring.unit ? (
                    <span style={{ color: c.muted, fontSize: 30 * u }}>
                      {ring.unit}
                    </span>
                  ) : null}
                </span>
                {over > 0 ? (
                  <span
                    style={{
                      fontWeight: 400,
                      fontSize: 16 * u,
                      color: c.muted,
                      fontVariantNumeric: "tabular-nums",
                      opacity: overIn,
                      transform: `translateY(${(1 - overIn) * 8 * u}px)`,
                    }}
                  >
                    +{over}% of goal
                  </span>
                ) : null}
              </div>
            </div>
          );
        })}
      </AbsoluteFill>

      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

