function Icon({
  name,
  size,
  color,
}: {
  name: IconName;
  size: number;
  color: string;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: "block", flexShrink: 0 }}
    >
      {ICONS[name].map((node, index) => {
        if (node.tag === "path") return <path key={index} d={node.d} />;
        if (node.tag === "circle") {
          return <circle key={index} cx={node.cx} cy={node.cy} r={node.r} />;
        }
        if (node.tag === "ellipse") {
          return (
            <ellipse
              key={index}
              cx={node.cx}
              cy={node.cy}
              rx={node.rx}
              ry={node.ry}
            />
          );
        }
        return (
          <rect
            key={index}
            x={node.x}
            y={node.y}
            width={node.width}
            height={node.height}
            rx={node.rx}
          />
        );
      })}
    </svg>
  );
}

function Spinner({
  state,
  size,
  palette,
}: {
  state: AgentRunSpinnerState;
  size: number;
  palette: AgentRunPalette;
}) {
  const active = 1 - state.done;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: "block", flexShrink: 0 }}
    >
      <circle cx={12} cy={12} r={10} stroke={palette.track} opacity={active} />
      <circle
        cx={12}
        cy={12}
        r={10}
        stroke={palette.accent}
        opacity={active}
        strokeDasharray={`${round(state.arc * CIRCLE)} ${round(CIRCLE)}`}
        transform={`rotate(${state.angle} 12 12)`}
      />
      <circle
        cx={12}
        cy={12}
        r={10}
        stroke={palette.muted}
        opacity={state.done}
      />
      <path
        d="m9 12 2 2 4-4"
        stroke={palette.muted}
        strokeDasharray={round(CHECK_LENGTH)}
        strokeDashoffset={round(CHECK_LENGTH * (1 - state.check))}
        opacity={state.check > 0 ? 1 : 0}
      />
    </svg>
  );
}

function spanStyle(
  span: AgentRunSpan,
  palette: AgentRunPalette,
): CSSProperties {
  if (span.kind === "bold") return { fontWeight: 600 };
  if (span.kind === "code") {
    return {
      fontFamily: MONO,
      fontSize: "0.875em",
      padding: "1px 5px",
      borderRadius: 5,
      background: palette.surface,
      border: `1px solid ${palette.surfaceBorder}`,
    };
  }
  if (span.kind === "cite") {
    return {
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      minWidth: 18,
      height: 18,
      padding: "0 5px",
      marginLeft: 2,
      borderRadius: 9,
      boxSizing: "border-box",
      background: palette.accentTint,
      color: palette.accentText,
      fontSize: 11.5,
      fontWeight: 600,
      lineHeight: "18px",
      fontVariantNumeric: "tabular-nums",
      verticalAlign: "middle",
      opacity: span.opacity,
      transform: `scale(${span.scale})`,
    };
  }
  if (span.kind === "punct" || span.kind === "comment") {
    return { color: palette.subtle };
  }
  if (span.kind === "string") return { color: palette.muted };
  return {};
}

function renderSpans(spans: readonly AgentRunSpan[], palette: AgentRunPalette) {
  return spans.map((span, index) => (
    <span key={index} style={spanStyle(span, palette)}>
      {span.fragments.map((fragment, part) => (
        <span
          key={part}
          style={
            fragment.opacity < 1 ? { opacity: fragment.opacity } : undefined
          }
        >
          {fragment.text}
        </span>
      ))}
    </span>
  ));
}

function AnswerBlock({
  block,
  palette,
}: {
  block: AgentRunBlockState;
  palette: AgentRunPalette;
}) {
  if (block.kind === "code") {
    return (
      <div
        style={{
          position: "absolute",
          top: block.y,
          left: 0,
          width: COLUMN,
          height: block.height,
          opacity: block.opacity,
          overflow: "hidden",
          boxSizing: "border-box",
          border: `1px solid ${palette.surfaceBorder}`,
          borderRadius: 10,
          background: palette.code,
        }}
      >
        <div
          style={{
            height: CODE_HEAD,
            boxSizing: "border-box",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "0 12px 0 16px",
            borderBottom: `1px solid ${palette.divider}`,
            fontFamily: MONO,
            fontSize: 12.5,
            color: palette.muted,
          }}
        >
          <span>{block.lang}</span>
          <Icon name="copy" size={14} color={palette.subtle} />
        </div>
        {block.lines.map((line) => (
          <div
            key={line.key}
            style={{
              position: "absolute",
              top: CODE_HEAD + CODE_PAD - 1 + line.y,
              left: 16,
              height: line.height,
              lineHeight: `${line.height}px`,
              fontFamily: MONO,
              fontSize: CODE_SIZE,
              whiteSpace: "pre",
              color: palette.fg,
            }}
          >
            {renderSpans(line.spans, palette)}
          </div>
        ))}
      </div>
    );
  }
  if (block.kind === "heading") {
    const spec = HEADINGS[block.level];
    const from = BODY_SIZE / spec.size;
    const scale = block.styled ? from + (1 - from) * block.morph : 1;
    return (
      <div>
        {block.lines.map((line, index) => (
          <div
            key={line.key}
            style={{
              position: "absolute",
              top: block.y + line.y,
              left: 0,
              height: line.height,
              display: "flex",
              alignItems: "center",
              whiteSpace: "pre",
            }}
          >
            {index === 0 && block.mark.length > 0 && block.morph < 1 ? (
              <span
                style={{
                  maxWidth: block.markWidth * (1 - block.morph),
                  overflow: "hidden",
                  flexShrink: 0,
                  opacity: 1 - block.morph,
                  fontSize: BODY_SIZE,
                  color: palette.subtle,
                }}
              >
                {block.mark}
              </span>
            ) : null}
            <span
              style={{
                fontSize: block.styled ? spec.size : BODY_SIZE,
                fontWeight: Math.round(400 + 200 * block.morph),
                lineHeight: 1.25,
                transform: `scale(${round(scale)})`,
                transformOrigin: "0 50%",
              }}
            >
              {renderSpans(line.spans, palette)}
            </span>
          </div>
        ))}
      </div>
    );
  }
  const indent = block.kind === "item" ? ITEM_INDENT : 0;
  return (
    <div>
      {block.kind === "item" ? (
        <div
          style={{
            position: "absolute",
            top: block.y + BODY_LINE / 2 - 3,
            left: 5,
            width: 6,
            height: 6,
            borderRadius: 3,
            background: palette.fg,
            opacity: block.dotOpacity,
            transform: `scale(${block.dot})`,
          }}
        />
      ) : null}
      {block.lines.map((line) => (
        <div
          key={line.key}
          style={{
            position: "absolute",
            top: block.y + line.y,
            left: indent,
            height: line.height,
            lineHeight: `${line.height}px`,
            whiteSpace: "pre",
          }}
        >
          {renderSpans(line.spans, palette)}
        </div>
      ))}
    </div>
  );
}

