function Tools({
  tools,
  palette,
}: {
  tools: NonNullable<AgentRunState["tools"]>;
  palette: AgentRunPalette;
}) {
  if (tools.rows.length === 0) return null;
  return (
    <div
      style={{
        position: "absolute",
        top: tools.y,
        left: 0,
        width: COLUMN,
        height: tools.height,
