                          padding: "0 12px",
                          borderRadius: 8,
                          fontSize: 15,
                          color: i === 0 ? c.ink : c.muted,
                          background: i === 0 ? c.card : "transparent",
                          boxShadow:
                            i === 0
                              ? `0 0 0 1px ${c.hair}, 0 1px 2px ${c.hair}`
                              : "none",
