                      >
                        <Icon
                          d={i === 0 ? ICONS.search : ICONS.layers}
                          size={15}
                          color={i === 0 ? c.ink : c.muted}
                        />
                        {t}
                      </div>
                    ))}
                  </div>
                  <div style={{ flex: 1 }} />
                  {[ICONS.globe, ICONS.clip, ICONS.mic].map((d) => (
                    <div
                      key={d}
                      style={{
                        width: 34,
