                        boxShadow:
                          i === 0 ? `inset 0 -1.5px 0 ${c.ink}` : "none",
                      }}
                    >
                      <Icon d={d} size={16} color={i === 0 ? c.ink : c.muted} />
                      {t}
                    </div>
                  ))}
                </div>
                {portrait ? null : (
                  <div
                    style={{
                      display: "flex",
