function hash(n: number) {
  const x = Math.sin(n * 12.9898 + 78.233) * 43758.5453;
  return x - Math.floor(x);
}

function City({ sc, seed, uid }: { sc: Scene; seed: number; uid: string }) {
  const { s, n, cy, hMax } = sc;
  const cx = 200;
  const cells: { i: number; j: number }[] = [];
  for (let d = 0; d <= 2 * (n - 1); d++)
    for (let i = 0; i < n; i++) {
      const j = d - i;
      if (j >= 0 && j < n) cells.push({ i, j });
    }
  const baseY = cy + ((n - 1) * s) / 2;
  const pts = (p: number[][]) => p.map((q) => q.join(",")).join(" ");
  const top = [
    [cx, cy - s / 2],
    [cx + n * s, cy - s / 2 + (n * s) / 2],
    [cx, cy - s / 2 + n * s],
    [cx - n * s, cy - s / 2 + (n * s) / 2],
  ];
  return (
    <g>
      {sc.island && (
        <>
          <polygon
            points={pts([top[3], top[2], [cx, top[2][1] + 78]])}
            fill={sc.ground}
          />
          <polygon
            points={pts([top[2], top[1], [cx, top[2][1] + 78]])}
            fill="#000"
            opacity={0.35}
          />
        </>
      )}
      <polygon points={pts(top)} fill={sc.ground} />
      {cells.map(({ i, j }) => {
        const r = hash(seed * 97 + i * 13 + j * 7);
        if (r < 0.16) {
          const x = cx + (i - j) * s;
          const y = cy + ((i + j) * s) / 2;
          return (
            <g key={`${i}-${j}`}>
              <circle
                cx={x}
                cy={y - 5}
                r={s * 0.32}
                fill="#5FBF9A"
                opacity={0.85}
              />
              <circle
                cx={x - 2}
                cy={y - 7}
                r={s * 0.14}
                fill="#B8F0D4"
                opacity={0.6}
              />
            </g>
          );
        }
        const h = 12 + r ** 1.6 * hMax * (1 - (i + j) / (4 * n));
        const w = s * (0.78 + 0.18 * hash(r * 31));
        const x = cx + (i - j) * s;
        const y = cy + ((i + j) * s) / 2;
        const L = [x - w, y];
        const B = [x, y + w / 2];
        const R = [x + w, y];
        const T = [x, y - w / 2];
        const up = (p: number[]) => [p[0], p[1] - h];
        const lines = Math.floor(h / 7);
        return (
          <g key={`${i}-${j}`}>
            <polygon
              points={pts([L, B, up(B), up(L)])}
              fill={sc.glass[0]}
              opacity={0.92}
            />
            <polygon
              points={pts([B, R, up(R), up(B)])}
              fill={sc.glass[1]}
              opacity={0.94}
            />
            <polygon
              points={pts([B, R, up(R), up(B)])}
              fill={`url(#${uid}refl)`}
            />
            <polygon
              points={pts([L, B, up(B), up(L)])}
              fill={`url(#${uid}shade)`}
            />
            {Array.from({ length: lines }, (_, k) => {
              const yy = 5 + k * 7;
              return (
                <path
                  key={yy}
                  d={`M${L[0]} ${L[1] - yy}L${B[0]} ${B[1] - yy}L${R[0]} ${R[1] - yy}`}
                  stroke="#FFFFFF"
                  strokeOpacity={0.16}
                  strokeWidth={0.6}
                  fill="none"
                />
              );
            })}
            <polygon
              points={pts([up(L), up(B), up(R), up(T)])}
              fill={sc.glass[2]}
            />
            <line
              x1={B[0]}
              y1={B[1]}
              x2={B[0]}
              y2={B[1] - h}
              stroke="#FFFFFF"
              strokeOpacity={0.55}
              strokeWidth={0.8}
            />
            {r > 0.7 && <circle cx={x} cy={y - h} r={1.6} fill="#FFFFFF" />}
          </g>
        );
      })}
      {sc.island && (
        <ellipse
          cx={cx}
          cy={baseY + 96}
          rx={150}
          ry={14}
          fill="#FFFFFF"
          opacity={0.25}
        />
      )}
    </g>
  );
}

