          </g>
          {[0, 1, 2, 3, 4].map((k) => (
            <rect
              key={k}
              x={sc.sunAt[0] - 30 + k * 6}
              y={waterY + 8 + k * 12}
              width={60 - k * 12}
              height={1.4}
              fill={sc.sun}
              opacity={0.7}
            />
          ))}
        </>
      ) : null}
      <City sc={sc} seed={index + 1} uid={uid} />
      <rect width={400} height={300} fill={`url(#${uid}fog)`} />
      <rect width={400} height={300} fill={`url(#${uid}vig)`} />
