        scrim: "rgba(238,240,246,0.18)",
        winShadow:
          "0 0 0 1px rgba(17,19,24,0.07), 0 1px 2px rgba(17,19,24,0.05), 0 30px 70px -20px rgba(28,38,92,0.28)",
        tipShadow:
          "0 0 0 1px rgba(17,19,24,0.08), 0 2px 4px rgba(17,19,24,0.05), 0 22px 44px -14px rgba(28,38,92,0.3)",
        stageText: "#14151A",
        stageMuted: "rgba(20,21,26,0.6)",
        dark: false,
      };
}

const ICONS = {
  arrowUp: "M8 12.5v-9M4.5 7 8 3.5 11.5 7",
  calendar: "M3.25 4h9.5v9.25h-9.5zM3.25 6.75h9.5M5.75 2.5v2.75M10.25 2.5v2.75",
} as const;

function Icon({
  name,
  color,
  size = 16,
}: {
  name: keyof typeof ICONS;
  color: string;
  size?: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      style={{ flexShrink: 0, display: "block" }}
    >
      <path
        d={ICONS[name]}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Cursor({ x, y, scale }: { x: number; y: number; scale: number }) {
  return (
    <svg
      width={24}
      height={28}
      viewBox="0 0 20 24"
      style={{
        position: "absolute",
        left: x - 2,
        top: y - 2,
        transformOrigin: "2px 2px",
        transform: `scale(${scale})`,
        filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.3))",
        overflow: "visible",
      }}
    >
      <path
        d="M2 2 L2 19.5 L6.6 15.4 L9.8 22.4 L12.9 21 L9.8 14.2 L16 14.2 Z"
        fill="#FFFFFF"
        stroke="#16171A"
        strokeWidth={1.1}
        strokeLinejoin="round"
      />
    </svg>
  );
}

const T = {
  win: 0,
  bars: 8,
  cursorIn: 26,
  click: 50,
  morph: 56,
  badge: 74,
  toHover: 70,
  tip: 96,
  end: 165,
};

export function AnalyticsFunnel({
  steps = DEFAULT_STEPS,
  title = "Activation funnel",
  variantLabel = "New onboarding",
  tooltipStep = 2,
  breakdown = DEFAULT_BREAKDOWN,
  dateRange = "Last 30 days",
  theme = "light",
  accent = "#3B5BFD",
  speed = 1,
  ground,
  groundParams,
}: AnalyticsFunnelProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const pal = palette(theme);
  const tall = H > W * 1.2;
  const D = tall ? { w: 800, h: 1422 } : { w: 1280, h: 720 };
  const s = Math.min(W / D.w, H / D.h);
  const sp = (at: number, config: object) =>
    spring({ frame: frame - at, fps, config });

  const WIN = tall
    ? { x: 40, y: 330, w: 720, h: 1000 }
    : { x: 156, y: 60, w: 968, h: 600 };
  const PAD = tall ? 28 : 32;
  const HEAD_H = 76;
  const KPI_Y = HEAD_H + 22;
  const CT = tall ? HEAD_H + 112 : KPI_Y + 112;
  const AXIS_W = 52;
  const PLOT = {
    x: PAD + AXIS_W,
    y: CT + 62,
    w: WIN.w - PAD * 2 - AXIS_W,
    h: WIN.h - PAD - 64 - (CT + 62),
  };
  const n = steps.length;
  const slot = PLOT.w / n;
  const BAR_W = Math.min(124, slot * 0.58);
  const colX = (i: number) => PLOT.x + slot * i + (slot - BAR_W) / 2;
  const yOf = (p: number) => PLOT.y + PLOT.h * (1 - p / 100);

  const morph = steps.map((_, i) => sp(T.morph + i * 3, MORPH));
  const value = (i: number) =>
    lerp(steps[i].control, steps[i].variant, morph[i]);
  const first = value(0) || 1;
  const ofFirst = (i: number) => (value(i) / first) * 100;
  const fromPrev = (i: number) =>
    i === 0 ? 100 : (value(i) / value(i - 1)) * 100;
  const grow = steps.map((_, i) => sp(T.bars + i * 3, CARD));
  const totalC = (steps[n - 1].control / steps[0].control) * 100;
  const totalV = (steps[n - 1].variant / steps[0].variant) * 100;
  const uplift = Math.round(((totalV - totalC) / totalC) * 100);
  const totalNow = lerp(totalC, totalV, morph[n - 1]);

  const win = sp(T.win, HEAVY);
  const winA = tween(frame, 0, 10);
  const toggleOn = sp(T.click + 2, CHIP);
  const on = toggleOn > 0.5;
  const badge = sp(T.badge, CHIP);
  const tip = sp(T.tip, CARD);
  const tipA = tween(frame, T.tip, T.tip + 8);
  const tt = clamp(tooltipStep, 0, n - 1);
  const cam = tween(frame, 20, T.end, camEase);

  const TOG_W = 236;
  const togX = WIN.w - PAD - TOG_W;
  const togglePt = { x: WIN.x + togX + 14 + 18, y: WIN.y + HEAD_H / 2 + 4 };
  const hoverPt = {
    x: WIN.x + colX(tt) + BAR_W * 0.6,
    y: WIN.y + yOf(ofFirst(tt) * 0.55),
  };
  const startPt = { x: D.w * 0.86, y: D.h + 40 };
  const leg1 = sp(T.cursorIn, HEAVY);
  const leg2 = sp(T.toHover, HEAVY);
  const arc = (
    a: { x: number; y: number },
    b: { x: number; y: number },
    p: number,
  ) => {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const d = Math.hypot(dx, dy) || 1;
    const bow = Math.sin(clamp(p, 0, 1) * Math.PI) * Math.min(60, d * 0.18);
    return {
      x: lerp(a.x, b.x, p) + (dy / d) * bow,
      y: lerp(a.y, b.y, p) - (dx / d) * bow,
    };
  };
  const cur =
    frame < T.toHover
      ? arc(startPt, togglePt, leg1)
      : arc(togglePt, hoverPt, leg2);
  const press = sp(T.click - 3, CHIP) - sp(T.click + 2, CHIP);
  const cursorScale = 1 - 0.04 * clamp(press, 0, 1.2);
  const cursorA =
    tween(frame, T.cursorIn, T.cursorIn + 6) *
    (1 - tween(frame, T.end - 20, T.end - 10, exitEase));

  const tint = withAlpha(accent, pal.dark ? 0.16 : 0.1);
  const ink = (t: number) => (t > 0.5 ? pal.text : pal.muted);

  const stat = (label: string, val: React.ReactNode, i: number) => {
    const a = tween(frame, 12 + i * 3, 24 + i * 3);
    return (
      <div
        style={{
          paddingLeft: tall && i === 0 ? 0 : 24,
          borderLeft: tall && i === 0 ? "none" : `1px solid ${pal.line}`,
          opacity: a,
          transform: `translateY(${(1 - a) * 8}px)`,
          flex: tall ? 1 : undefined,
        }}
      >
        <div style={{ fontSize: 16, color: pal.muted }}>{label}</div>
        <div
          style={{
            fontSize: 26,
            fontWeight: 300,
            color: pal.text,
            marginTop: 6,
            letterSpacing: "-0.02em",
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {val}
        </div>
      </div>
    );
  };

  const badgeEl = (size: number) => (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        height: size * 1.75,
        padding: `0 ${size * 0.55}px 0 ${size * 0.4}px`,
        borderRadius: 8,
        background: pal.greenBg,
        color: pal.green,
        fontSize: size,
        fontVariantNumeric: "tabular-nums",
        opacity: clamp(badge * 2, 0, 1),
        transform: `translateY(${(1 - badge) * 10}px) scale(${0.85 + 0.15 * badge})`,
        transformOrigin: "0% 50%",
        whiteSpace: "nowrap",
      }}
    >
      <Icon name="arrowUp" color={pal.green} size={size} />
      {uplift > 0 ? "+" : ""}
      {uplift}%
    </span>
  );

  const tipW = tall ? 312 : 264;
  const tipX = PLOT.x + PLOT.w - tipW + 8;
  const tipY = tall ? PLOT.y - 8 : PLOT.y - 20;
  const rowH = tall ? 32 : 26;
  const stepV = value(tt);

  return (
    <AbsoluteFill
      style={{
        fontFamily,
        fontWeight: 400,
        overflow: "hidden",
        WebkitFontSmoothing: "antialiased",
        background: pal.dark ? "#03050C" : "#EEF0F6",
      }}
    >
      <GshGround
        preset={ground ?? (pal.dark ? "film-blue" : "glasswork")}
        params={groundParams}
        timeOffset={pal.dark ? 4 : 3}
        timeScale={0.3}
      />
      <AbsoluteFill style={{ background: pal.scrim }} />
      <div
        style={{
          position: "absolute",
          left: (W - D.w * s) / 2,
          top: (H - D.h * s) / 2,
          width: D.w,
          height: D.h,
          transformOrigin: "0 0",
          transform: `scale(${s})`,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transformOrigin: `${WIN.x + tipX}px ${WIN.y + tipY + 120}px`,
            transform: `scale(${1 + 0.035 * cam})`,
          }}
        >
          {tall ? (
            <div style={{ position: "absolute", left: 48, top: 92, right: 48 }}>
              <div
                style={{
                  fontSize: 24,
                  color: pal.stageMuted,
                  opacity: tween(frame, 4, 16),
                }}
              >
                Paid conversion · {dateRange.toLowerCase()}
              </div>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 22,
                  marginTop: 10,
                  overflow: "hidden",
                }}
              >
                <span
                  style={{
                    fontSize: 132,
                    fontWeight: 300,
                    letterSpacing: "-0.045em",
                    lineHeight: 1.05,
                    color: pal.stageText,
                    fontVariantNumeric: "tabular-nums",
                    transform: `translateY(${(1 - tween(frame, 6, 20)) * 100}%)`,
                  }}
                >
                  {pct(totalNow)}
                </span>
                {badgeEl(30)}
              </div>
            </div>
          ) : null}
          <div
            style={{
              position: "absolute",
              left: WIN.x,
              top: WIN.y,
              width: WIN.w,
              height: WIN.h,
              opacity: winA,
              transform: `translateY(${(1 - win) * 48}px) scale(${0.97 + 0.03 * win})`,
              transformOrigin: "50% 100%",
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: 16,
                background: pal.win,
                boxShadow: pal.winShadow,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  height: HEAD_H,
                  display: "flex",
                  alignItems: "center",
                  gap: 14,
                  padding: `0 ${PAD}px`,
                  borderBottom: `1px solid ${pal.line}`,
                }}
              >
                <span
                  style={{
                    fontSize: 20,
                    color: pal.text,
                    letterSpacing: "-0.01em",
                  }}
                >
                  {tall ? "Funnel" : title}
                </span>
                <span
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    fontSize: 16,
                    color: pal.muted,
                  }}
                >
                  <Icon name="calendar" color={pal.faint} />
                  {dateRange}
                </span>
                <div style={{ flex: 1 }} />
                <div
                  style={{
                    width: TOG_W,
                    height: 40,
                    boxSizing: "border-box",
                    display: "flex",
                    alignItems: "center",
                    gap: 10,
                    padding: "0 14px",
                    borderRadius: 10,
                    background: on
                      ? withAlpha(accent, pal.dark ? 0.14 : 0.07)
                      : "transparent",
                    boxShadow: `inset 0 0 0 1px ${on ? withAlpha(accent, 0.4) : pal.line}`,
                    transform: `scale(${1 - 0.04 * clamp(press, 0, 1.2)})`,
                  }}
                >
                  <div
                    style={{
                      width: 36,
                      height: 22,
                      borderRadius: 99,
                      position: "relative",
                      flexShrink: 0,
                      background: on ? accent : pal.knobOff,
                    }}
                  >
                    <div
                      style={{
                        position: "absolute",
                        top: 3,
                        left: 3 + 14 * toggleOn,
                        width: 16,
                        height: 16,
                        borderRadius: 99,
                        background: "#fff",
                        boxShadow: "0 1px 2px rgba(0,0,0,0.25)",
                      }}
                    />
                  </div>
                  <span style={{ fontSize: 16, color: pal.text }}>
                    {variantLabel}
                  </span>
                </div>
              </div>

              {!tall ? (
                <div
                  style={{
                    position: "absolute",
                    left: PAD,
                    right: PAD,
                    top: KPI_Y,
                    display: "flex",
                    alignItems: "flex-end",
                    gap: 24,
                  }}
                >
                  <div>
                    <div style={{ fontSize: 16, color: pal.muted }}>
                      Total conversion
                    </div>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 14,
                        marginTop: 2,
                        overflow: "hidden",
                      }}
                    >
                      <span
                        style={{
                          fontSize: 54,
                          fontWeight: 300,
                          letterSpacing: "-0.04em",
                          color: pal.text,
                          fontVariantNumeric: "tabular-nums",
                          lineHeight: 1.1,
                          transform: `translateY(${(1 - tween(frame, 8, 22)) * 100}%)`,
                        }}
                      >
                        {pct(totalNow)}
                      </span>
                      {badgeEl(18)}
                    </div>
                  </div>
                  <div style={{ flex: 1 }} />
                  {stat("Visits", fmt(value(0)), 0)}
                  {stat("Paying users", fmt(value(n - 1)), 1)}
                  {stat(
                    "Time to pay",
                    morph[n - 1] > 0.5 ? "1d 19h" : "2d 6h",
                    2,
                  )}
                </div>
              ) : (
                <div
                  style={{
                    position: "absolute",
                    left: PAD,
                    right: PAD,
                    top: HEAD_H + 20,
                    display: "flex",
                    gap: 24,
                  }}
                >
                  {stat("Visits", fmt(value(0)), 0)}
                  {stat("Paying users", fmt(value(n - 1)), 1)}
                  {stat(
                    "Time to pay",
                    morph[n - 1] > 0.5 ? "1d 19h" : "2d 6h",
                    2,
                  )}
                </div>
              )}

              <div
                style={{
                  position: "absolute",
                  left: PAD,
                  right: PAD,
                  top: CT,
                  height: 1,
                  background: pal.line,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: PAD,
                  right: PAD,
                  top: CT + 18,
                  display: "flex",
                  alignItems: "center",
                  gap: 22,
                  justifyContent: "flex-end",
                  fontSize: 16,
                  color: pal.muted,
                }}
              >
                <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: 3,
                      background: accent,
                    }}
                  />
                  {on ? variantLabel : "All users"}
                </span>
                <span
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    opacity: tween(frame, T.morph + 4, T.morph + 14),
                  }}
                >
                  <span
                    style={{
                      width: 16,
                      borderTop: `1.5px dashed ${pal.faint}`,
                    }}
                  />
                  Control
                </span>
              </div>

              <svg
                width={WIN.w}
                height={WIN.h}
                style={{ position: "absolute", left: 0, top: 0 }}
              >
                {[0, 50, 100].map((g) => (
                  <g key={g}>
                    <line
                      x1={PLOT.x}
                      x2={PLOT.x + PLOT.w}
                      y1={yOf(g)}
                      y2={yOf(g)}
                      stroke={pal.line}
                      strokeDasharray={g ? "2 5" : undefined}
                    />
                    <text
                      x={PLOT.x - 14}
                      y={yOf(g) + 5}
                      textAnchor="end"
                      fontSize={15}
                      fill={pal.faint}
                      fontFamily={fontFamily}
                      style={{ fontVariantNumeric: "tabular-nums" }}
                    >
                      {g}%
                    </text>
                  </g>
                ))}
                <rect
                  x={colX(tt) - 12}
                  y={PLOT.y - 6}
                  width={BAR_W + 24}
                  height={yOf(0) - PLOT.y + 6}
                  rx={10}
                  fill={pal.track}
                  opacity={tipA * 0.7}
                />
                {steps.map((st, i) => {
                  const g = grow[i];
                  const x = colX(i);
                  const prev = i === 0 ? 100 : ofFirst(i - 1);
                  const curP = ofFirst(i);
                  const ctrl = (st.control / steps[0].control) * 100;
                  const top = yOf(prev * g);
                  const bar = yOf(curP * g);
                  const dim = i === tt ? 0 : tipA;
                  const ghost =
                    i > 0
                      ? tween(frame, T.morph + 6 + i * 3, T.morph + 16 + i * 3)
                      : 0;
                  return (
                    <g key={st.label}>
                      <rect
                        x={x}
                        y={top}
                        width={BAR_W}
                        height={Math.max(0, bar - top)}
                        rx={6}
                        fill={tint}
                      />
                      <rect
                        x={x}
                        y={bar}
                        width={BAR_W}
                        height={Math.max(0, yOf(0) - bar)}
                        rx={6}
                        fill={accent}
                        opacity={1 - 0.3 * dim}
                      />
                      {ghost > 0 && Math.abs(ctrl - curP) > 0.3 ? (
                        <line
                          x1={x - 8}
                          x2={lerp(x - 8, x + BAR_W + 8, ghost)}
                          y1={yOf(ctrl)}
                          y2={yOf(ctrl)}
                          stroke={pal.dark ? "#FFFFFF" : "#16171A"}
                          strokeOpacity={0.7}
                          strokeWidth={1.5}
                          strokeDasharray="4 4"
                        />
                      ) : null}
                    </g>
                  );
                })}
              </svg>

              {steps.map((st, i) => {
                const x = colX(i);
                const lab = tween(
                  frame,
                  T.bars + i * 3 + 6,
                  T.bars + i * 3 + 18,
                );
                return (
                  <div key={st.label}>
                    <div
                      style={{
                        position: "absolute",
                        left: x,
                        width: BAR_W,
                        textAlign: "center",
                        top: yOf(ofFirst(i) * grow[i]) - 30,
                        opacity: lab,
                        fontSize: 16,
                        color: pal.text,
                        fontVariantNumeric: "tabular-nums",
                      }}
                    >
                      {pct(ofFirst(i))}
                    </div>
                    <div
                      style={{
                        position: "absolute",
                        left: x,
                        top: yOf(0) + 14,
                        opacity: lab,
                        transform: `translateY(${(1 - lab) * 6}px)`,
                        whiteSpace: "nowrap",
                      }}
                    >
                      <div style={{ fontSize: 17, color: ink(1) }}>
                        {st.label}
                      </div>
                      <div
                        style={{
                          fontSize: 16,
                          color: pal.muted,
                          marginTop: 3,
                          fontVariantNumeric: "tabular-nums",
                        }}
                      >
                        {fmt(value(i))}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            <div
              style={{
                position: "absolute",
                left: tipX,
                top: tipY,
                width: tipW,
                opacity: tipA,
                transform: `translateY(${(1 - tip) * 12}px) scale(${0.94 + 0.06 * tip})`,
                transformOrigin: "0% 0%",
                background: pal.tip,
                borderRadius: 14,
                boxShadow: pal.tipShadow,
                padding: tall ? "16px 18px 14px" : "12px 16px 10px",
                boxSizing: "border-box",
              }}
            >
              <div style={{ fontSize: 16, color: pal.muted }}>
                {tt + 1} · {steps[tt].event}
              </div>
              <div
                style={{
                  display: "flex",
                  alignItems: "baseline",
                  gap: 10,
                  marginTop: tall ? 6 : 4,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                <span
                  style={{
                    fontSize: tall ? 34 : 30,
                    lineHeight: 1.2,
                    fontWeight: 300,
                    color: pal.text,
                    letterSpacing: "-0.03em",
                  }}
                >
                  {fmt(stepV)}
                </span>
                <span style={{ fontSize: 16, color: pal.muted }}>
                  {pct(fromPrev(tt))} of{" "}
                  {steps[Math.max(0, tt - 1)].label.toLowerCase()}
                </span>
              </div>
              <div
                style={{
                  height: 1,
                  background: pal.line,
                  margin: tall ? "14px 0 8px" : "10px 0 6px",
                }}
              />
              {breakdown.map((b, k) => {
                const r = sp(T.tip + 6 + k * 3, CARD);
                return (
                  <div
                    key={b.label}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                      height: rowH,
                      fontSize: 16,
                      color: pal.text,
                      fontVariantNumeric: "tabular-nums",
                    }}
                  >
                    <span style={{ width: 66 }}>{b.label}</span>
                    <div
                      style={{
                        flex: 1,
                        height: 6,
                        borderRadius: 3,
                        background: pal.track,
                      }}
                    >
                      <div
                        style={{
                          width: `${b.share * 100 * clamp(r, 0, 1.04)}%`,
                          height: "100%",
                          borderRadius: 3,
                          background: withAlpha(accent, 1 - k * 0.28),
                        }}
                      />
                    </div>
                    <span
                      style={{
                        width: 52,
                        textAlign: "right",
                        color: pal.muted,
                      }}
                    >
                      {fmt(stepV * b.share)}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
          <div style={{ opacity: cursorA }}>
            <Cursor x={cur.x} y={cur.y} scale={cursorScale} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type AnamorphicFlareProps = {
  /** Lockup revealed behind the streak. Falls back to a placeholder "remocn" lockup. */
  children?: React.ReactNode;
  /** Warm tint of the streak glow and ghosts. */
  tint?: string;
  /** Color of the hot core line. */
  coreColor?: string;
  backgroundColor?: string;
  /** Number of ghost orbs mirrored across the frame center. */
  ghosts?: number;
  /** Vertical position of the streak, 0 to 1. */
  y?: number;
  seed?: number;
  speed?: number;
};

export const anamorphicFlareDefaults = {
  tint: "#E5322D",
  coreColor: "#FFFFFF",
  backgroundColor: "#111111",
  ghosts: 4,
  y: 0.5,
  seed: 2,
  speed: 1,
};

const IGNITE = 6;
const CROSS_START = 4;
const CROSS_END = 26;
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const PLACEHOLDER_FONT =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Helvetica, Arial, sans-serif";

// Neutral lockup shown when no children are passed.
function PlaceholderLockup({
  mark,
  dot,
  text,
  scale = 1,
}: {
  mark: string;
  dot: string;
  text: string;
  scale?: number;
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28 * scale }}>
      <div
        style={{
          width: 120 * scale,
          height: 120 * scale,
          borderRadius: 32 * scale,
          backgroundColor: mark,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36 * scale,
            height: 36 * scale,
            borderRadius: "50%",
            backgroundColor: dot,
          }}
        />
      </div>
      <span
        style={{
          fontFamily: PLACEHOLDER_FONT,
          fontSize: 104 * scale,
          fontWeight: 800,
          letterSpacing: "-0.04em",
          color: text,
        }}
      >
        remocn
      </span>
    </div>
  );
}

export function AnamorphicFlare(props: AnamorphicFlareProps) {
  const { children, tint, coreColor, backgroundColor, ghosts, y, seed, speed } =
    { ...anamorphicFlareDefaults, ...props };
  const uid = `anamorphic-flare-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = frame * Math.max(0, speed);
  const cy = y * height;
  const cx = width / 2;

  const head = interpolate(t, [CROSS_START, CROSS_END], [0.07, 1.12], {
    ...clamp,
    easing: Easing.bezier(0.45, 0, 0.4, 1),
  });
  const hx = head * width;
  const ignite = interpolate(t, [0, IGNITE], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const fade = interpolate(t, [CROSS_END - 6, CROSS_END + 2], [1, 0], clamp);
  const power = ignite * fade;
  const streakLen =
    width *
    interpolate(t, [0, 12], [0.04, 1.3], {
      ...clamp,
      easing: Easing.out(Easing.quad),
    });
  const coreH = Math.max(2, height * 0.004);
  const glowH = height * 0.05;
  const residual = interpolate(
    t,
    [CROSS_END - 2, CROSS_END + 14],
    [0, 0.14],
    clamp,
  );
  const soft = width * 0.08;
  const mask = `linear-gradient(90deg, #000 0px, #000 ${hx - soft}px, transparent ${hx}px)`;

  const ghostList = Array.from(
    { length: Math.max(0, Math.round(ghosts)) },
    (_, i) => {
      const k = -1.3 + random(`anamorphic-flare-${seed}-${i}-k`) * 2.2;
      return {
        x: cx - (hx - cx) * k,
        r: height * (0.025 + 0.07 * random(`anamorphic-flare-${seed}-${i}-r`)),
        o: 0.12 + 0.18 * random(`anamorphic-flare-${seed}-${i}-o`),
        dy: (random(`anamorphic-flare-${seed}-${i}-y`) - 0.5) * height * 0.05,
      };
    },
  );

  return (
    <AbsoluteFill style={{ backgroundColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
      >
        <defs>
          <linearGradient id={`${uid}-trail`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={tint} stopOpacity={0} />
            <stop offset="0.5" stopColor={tint} stopOpacity={1} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </linearGradient>
        </defs>
        <rect
          x={0}
          y={cy - 1}
          width={width}
          height={2}
          fill={`url(#${uid}-trail)`}
          opacity={residual}
        />
      </svg>
      <AbsoluteFill
        style={{
          alignItems: "center",
          justifyContent: "center",
          WebkitMaskImage: mask,
          maskImage: mask,
        }}
      >
        {children ?? (
          <PlaceholderLockup
            mark={tint}
            dot={backgroundColor}
            text={coreColor}
          />
        )}
      </AbsoluteFill>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          inset: 0,
          mixBlendMode: "screen",
        }}
      >
        <defs>
          <linearGradient id={`${uid}-core`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={coreColor} stopOpacity={0} />
            <stop offset="0.5" stopColor={coreColor} stopOpacity={1} />
            <stop offset="1" stopColor={coreColor} stopOpacity={0} />
          </linearGradient>
          <radialGradient id={`${uid}-bloom`}>
            <stop offset="0" stopColor={coreColor} stopOpacity={1} />
            <stop offset="0.25" stopColor={tint} stopOpacity={0.7} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </radialGradient>
          <radialGradient id={`${uid}-ghost`}>
            <stop offset="0" stopColor={tint} stopOpacity={0.15} />
            <stop offset="0.8" stopColor={tint} stopOpacity={0.5} />
            <stop offset="1" stopColor={tint} stopOpacity={0} />
          </radialGradient>
          <filter
            id={`${uid}-blur`}
            x={-width}
            y={-height}
            width={width * 3}
            height={height * 3}
            filterUnits="userSpaceOnUse"
          >
            <feGaussianBlur stdDeviation={glowH * 0.35} />
          </filter>
        </defs>
        <g opacity={power}>
          <rect
            x={hx - streakLen * 0.45}
            y={cy - glowH / 2}
            width={streakLen * 0.9}
            height={glowH}
            fill={`url(#${uid}-trail)`}
            opacity={0.55}
            filter={`url(#${uid}-blur)`}
          />
          <rect
            x={hx - streakLen / 2}
            y={cy - coreH / 2}
            width={streakLen}
            height={coreH}
            fill={`url(#${uid}-core)`}
          />
          <ellipse
            cx={hx}
            cy={cy}
            rx={height * 0.16}
            ry={height * 0.1}
            fill={`url(#${uid}-bloom)`}
          />
          {ghostList.map((g, i) => (
            <circle
              key={i}
              cx={g.x}
              cy={cy + g.dy}
              r={g.r}
              fill={`url(#${uid}-ghost)`}
              opacity={g.o * 2}
            />
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Gabarito";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const gabarito = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface AndYouProps {
  clauses?: string[];
  last?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#3B1E6E", ink: "#FFFFFF", accent: "#FF7A6B" },
  light: { bg: "#EDE7FB", ink: "#3B1E6E", accent: "#D9483A" },
} as const;

const BODY_W = 400;
const LAST_W = 500;
const TRACK = -0.02;
const LAST_TRACK = -0.035;
const FONT_PX = 200;
const LH = 1.12;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  body: (s: string) => number;
  last: (s: string) => number;
  asc: number;
  desc: number;
}

function measure(): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("and-you: no 2d context");
  const bodyCache: Record<string, number> = {};
  const lastCache: Record<string, number> = {};
  const em = (s: string, w: number, track: number) => {
    ctx.font = `${w} ${FONT_PX}px "${gabarito.fontFamily}"`;
    return ctx.measureText(s).width / FONT_PX + track * Array.from(s).length;
  };
  ctx.font = `${BODY_W} ${FONT_PX}px "${gabarito.fontFamily}"`;
  const fm = ctx.measureText("Hxg");
  return {
    body: (s) => {
      if (bodyCache[s] === undefined) bodyCache[s] = em(s, BODY_W, TRACK);
      return bodyCache[s];
    },
    last: (s) => {
      if (lastCache[s] === undefined) lastCache[s] = em(s, LAST_W, LAST_TRACK);
      return lastCache[s];
    },
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics() {
  const [m, setM] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("and-you: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      gabarito.waitUntilDone(),
      document.fonts.load(`${BODY_W} 100px "${gabarito.fontFamily}"`),
      document.fonts.load(`${LAST_W} 100px "${gabarito.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setM(measure());
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return m;
}

interface Placed {
  text: string;
  clause: number;
  order: number;
  line: number;
  x: number;
}

function flow(
  clauses: string[],
  room: number,
  width: (s: string) => number,
): { words: Placed[]; lastLine: number[] } {
  const words: Placed[] = [];
  const lastLine: number[] = [];
  let line = 0;
  let cur: string[] = [];
  clauses.forEach((cl, ci) => {
    const parts = cl.split(" ").filter(Boolean);
    parts.forEach((w, wi) => {
      const prefix = cur.length > 0 ? `${cur.join(" ")} ` : "";
      if (cur.length > 0 && width(prefix + w) > room) {
        line += 1;
        cur = [];
        words.push({ text: w, clause: ci, order: wi, line, x: 0 });
      } else {
        words.push({
          text: w,
          clause: ci,
          order: wi,
          line,
          x: width(prefix),
        });
      }
      cur.push(w);
    });
    lastLine.push(line);
  });
  return { words, lastLine };
}

export function AndYou({
  clauses = [
    "For the founder who launches on Monday,",
    "the designer who just learned React,",
    "the two-person studio,",
    "the student with a weekend project,",
  ],
  last = "and you.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: AndYouProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const t = frame * speed;
  const D = Math.max(110, durationInFrames);
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const list = clauses.length > 0 ? clauses : ["For everyone who builds,"];
  const m = useMetrics();

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.065);
  const marginY = H * (portrait ? 0.07 : 0.1);
  const room = W - marginX * 2;
  const F0 = portrait ? W * 0.12 : H * 0.15;
  const { words, lastLine } = flow(list, room / F0, m.body);
  const lineH = LH * F0;
  const heightAt = (k: number) => (lastLine[k] + 1) * lineH;
  const availH = H - marginY * 2;

  const scrollAt = (k: number) => Math.max(0, heightAt(k) - availH);

  const lastSplit = last.lastIndexOf(" ");
  const lastHead = lastSplit > 0 ? last.slice(0, lastSplit + 1) : "";
  const lastTail = lastSplit > 0 ? last.slice(lastSplit + 1) : last;
  const lastW = Math.max(0.1, m.last(last));
  const FY = Math.min(
    H * (portrait ? 0.16 : 0.34),
    (room * (portrait ? 1 : 0.62)) / lastW,
  );
  const lastCap = FY * 0.74;
  const gapY = H * 0.06;
  const finalRoomH = H - marginY * 2 - lastCap - gapY;
  const sFinal = Math.min(1, finalRoomH / heightAt(n - 1), portrait ? 1 : 0.6);

  const start = 6;
  const cl = Math.min(30, Math.max(14, (D * 0.56 - start) / n));
  const clauseAt = (k: number) => start + k * cl;
  const finalAt = clauseAt(n);

  let scroll = scrollAt(0);
  for (let k = 1; k < n; k++) {
    const e = interpolate(t, [clauseAt(k) - 2, clauseAt(k) + 12], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    scroll += (scrollAt(k) - scrollAt(k - 1)) * e;
  }
  const back = interpolate(t, [finalAt - 4, finalAt + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const s = 1 + (sFinal - 1) * back;
  const offY = -scroll * (1 - back);
  const dim = 1 - 0.38 * back;

  const wordStyle: React.CSSProperties = {
    position: "absolute",
    height: F0,
    lineHeight: `${F0}px`,
    whiteSpace: "pre",
    fontFamily: gabarito.fontFamily,
    fontWeight: BODY_W,
    fontSize: F0,
    letterSpacing: `${TRACK}em`,
    color: c.ink,
  };

  const nodes = words.map((w, i) => {
    const at = clauseAt(w.clause) + w.order * 2;
    const p = interpolate(t, [at, at + 14], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    if (p <= 0) return null;
    const lineTop = w.line * lineH;
    const screenTop = marginY + (offY + lineTop) * s;
    const seen = interpolate(
      screenTop,
      [marginY - lineH * s * 0.5, marginY + lineH * s * 0.05],
      [0, 1],
      CLAMP,
    );
    return (
      <div
        key={`w${i}`}
        style={{
          ...wordStyle,
          left: w.x * F0,
          top: lineTop + (lineH - F0) / 2,
          opacity: p * seen,
          transform: `translateY(${((1 - p) * F0 * 0.35).toFixed(2)}px)`,
        }}
      >
        {w.text}
      </div>
    );
  });

  const lastIn = interpolate(t, [finalAt + 4, finalAt + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const tailIn = interpolate(t, [finalAt + 8, finalAt + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lastBase = H - marginY;
  const lastTop = lastBase - ((1 - m.asc - m.desc) / 2 + m.asc) * FY;
  const lastStyle: React.CSSProperties = {
    display: "inline-block",
    height: FY,
    lineHeight: `${FY}px`,
    whiteSpace: "pre",
    fontFamily: gabarito.fontFamily,
    fontWeight: LAST_W,
    fontSize: FY,
    letterSpacing: `${LAST_TRACK}em`,
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: marginX,
          top: marginY,
          width: room,
          transformOrigin: "0 0",
          transform: `scale(${s.toFixed(5)}) translateY(${offY.toFixed(2)}px)`,
          opacity: dim,
        }}
      >
        {nodes}
      </div>
      {lastIn > 0 ? (
        <div
          style={{
            position: "absolute",
            right: marginX,
            top: lastTop - FY * 0.2,
            height: FY * 1.45,
            overflow: "hidden",
            display: "flex",
          }}
        >
          <div
            style={{
              ...lastStyle,
              marginTop: FY * 0.2,
              color: c.ink,
              transform: `translateY(${((1 - lastIn) * FY * 1.3).toFixed(2)}px)`,
            }}
          >
            {lastHead}
          </div>
          <div
            style={{
              ...lastStyle,
              marginTop: FY * 0.2,
              color: hi,
              transform: `translateY(${((1 - tailIn) * FY * 1.3).toFixed(2)}px)`,
            }}
          >
            {lastTail}
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface AnimatedBarChartProps {
  data?: number[];
  labels?: string[];
  width?: number;
  height?: number;
  barColor?: string;
  gap?: number;
  staggerFrames?: number;
  speed?: number;
  className?: string;
}

export function AnimatedBarChart({
  data = [35, 60, 45, 80, 55, 70, 90, 65],
  labels,
  width = 1000,
  height = 500,
  barColor = "#0ea5e9",
  gap = 16,
  staggerFrames = 6,
  speed = 1,
  className,
}: AnimatedBarChartProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const padding = 60;
  const labelSpace = labels ? 40 : 0;
  const innerWidth = width - padding * 2;
  const innerHeight = height - padding * 2 - labelSpace;
  const max = Math.max(...data);
  const barWidth = (innerWidth - gap * (data.length - 1)) / data.length;
  const baseY = padding + innerHeight;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        {/* Baseline */}
        <line
          x1={padding}
          x2={padding + innerWidth}
          y1={baseY}
          y2={baseY}
          stroke="#27272a"
          strokeWidth={2}
        />

        {data.map((value, index) => {
          const targetHeight = (value / max) * innerHeight;
          const x = padding + index * (barWidth + gap);
          const y = baseY - targetHeight;

          const scaleY = spring({
            frame: frame - index * staggerFrames,
            fps,
            config: { damping: 12, stiffness: 100, mass: 0.8 },
            from: 0,
            to: 1,
          });

          return (
            <g key={index}>
              <rect
                x={x}
                y={y}
                width={barWidth}
                height={targetHeight}
                rx={6}
                fill={barColor}
                style={{
                  scale: `1 ${scaleY}`,
                  transformOrigin: `${x + barWidth / 2}px ${baseY}px`,
                  transformBox: "fill-box",
                  filter: `drop-shadow(0 4px 16px ${barColor}55)`,
                }}
              />
              {labels?.[index] && (
                <text
                  x={x + barWidth / 2}
                  y={baseY + 28}
                  fill="#a1a1aa"
                  fontSize={16}
                  textAnchor="middle"
                  style={{
                    opacity: scaleY,
                    fontFamily:
                      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  {labels[index]}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

"use client";

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface AnimatedLineChartProps {
  data?: number[];
  width?: number;
  height?: number;
  strokeColor?: string;
  strokeWidth?: number;
  gridColor?: string;
  showDot?: boolean;
  speed?: number;
  className?: string;
}

export function AnimatedLineChart({
  data = [12, 19, 8, 15, 22, 18, 28, 25, 32],
  width = 1000,
  height = 500,
  strokeColor = "#22c55e",
  strokeWidth = 4,
  gridColor = "#27272a",
  showDot = true,
  speed = 1,
  className,
}: AnimatedLineChartProps) {
  const frame = useCurrentFrame() * speed;
  const { fps, durationInFrames } = useVideoConfig();

  const padding = 60;
  const innerWidth = width - padding * 2;
  const innerHeight = height - padding * 2;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const points = data.map((value, index) => {
    const x = padding + (index / (data.length - 1)) * innerWidth;
    const y = padding + innerHeight - ((value - min) / range) * innerHeight;
    return { x, y };
  });

  // Analytical path length: sum of segment distances
  let pathLength = 0;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i - 1].x;
    const dy = points[i].y - points[i - 1].y;
    pathLength += Math.sqrt(dx * dx + dy * dy);
  }

  const d = points
    .map((p, i) => `${i === 0 ? "M" : "L"}${p.x.toFixed(2)},${p.y.toFixed(2)}`)
    .join(" ");

  // Spring-driven progress: smooth, no bounce. Matches the "smooth" preset
  // from remotion-best-practices/timing.md.
  const progress = spring({
    frame,
    fps,
    durationInFrames: Math.round(durationInFrames * 0.85),
    config: { damping: 200 },
  });

  const dashOffset = pathLength * (1 - progress);

  // Find dot position along the path at current progress
  const targetLen = pathLength * progress;
  let traveled = 0;
  let dotX = points[0].x;
  let dotY = points[0].y;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i - 1].x;
    const dy = points[i].y - points[i - 1].y;
    const segLen = Math.sqrt(dx * dx + dy * dy);
    if (traveled + segLen >= targetLen) {
      const t = (targetLen - traveled) / segLen;
      dotX = points[i - 1].x + dx * t;
      dotY = points[i - 1].y + dy * t;
      break;
    }
    traveled += segLen;
    dotX = points[i].x;
    dotY = points[i].y;
  }

  const gridRows = 4;
  const gridCols = data.length - 1;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        {/* Horizontal grid */}
        {Array.from({ length: gridRows + 1 }).map((_, i) => {
          const y = padding + (i / gridRows) * innerHeight;
          return (
            <line
              key={`h-${i}`}
              x1={padding}
              x2={padding + innerWidth}
              y1={y}
              y2={y}
              stroke={gridColor}
              strokeWidth={1}
            />
          );
        })}
        {/* Vertical grid */}
        {Array.from({ length: gridCols + 1 }).map((_, i) => {
          const x = padding + (i / gridCols) * innerWidth;
          return (
            <line
              key={`v-${i}`}
              x1={x}
              x2={x}
              y1={padding}
              y2={padding + innerHeight}
              stroke={gridColor}
              strokeWidth={1}
            />
          );
        })}
        {/* Axis */}
        <line
          x1={padding}
          x2={padding}
          y1={padding}
          y2={padding + innerHeight}
          stroke={gridColor}
          strokeWidth={2}
        />
        <line
          x1={padding}
          x2={padding + innerWidth}
          y1={padding + innerHeight}
          y2={padding + innerHeight}
          stroke={gridColor}
          strokeWidth={2}
        />

        {/* Animated line */}
        <path
          d={d}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={pathLength}
          strokeDashoffset={dashOffset}
          style={{
            filter: `drop-shadow(0 0 12px ${strokeColor}55)`,
          }}
        />

        {showDot && progress > 0 && progress < 1 && (
          <circle
            cx={dotX}
            cy={dotY}
            r={strokeWidth * 2}
            fill={strokeColor}
            style={{
              filter: `drop-shadow(0 0 8px ${strokeColor})`,
            }}
          />
        )}
      </svg>
    </div>
  );
}

