const isBrand = (label: string) => label.trim().toLowerCase() === "remocn";

// gradients.sh "mesh" palette, laid flat: a diagonal ramp with two drifting
// blobs, so the shape reads as a printed swatch rather than a lit sphere.
const MESH = ["#ECDCF2", "#8796EE", "#2E45B7", "#0E1645"];

function meshFill(accent: string, drift: number) {
  const ax = 18 + Math.sin(drift * 1.3) * 6;
  const bx = 82 + Math.cos(drift * 1.1) * 6;
  return [
    `radial-gradient(70% 60% at ${ax}% 16%, color-mix(in oklab, ${MESH[0]} 55%, transparent) 0%, transparent 70%)`,
    `radial-gradient(80% 70% at ${bx}% 92%, ${MESH[3]} 0%, transparent 72%)`,
    `linear-gradient(${150 + drift * 6}deg, ${MESH[1]} 0%, ${accent} 44%, ${MESH[2]} 74%, ${MESH[3]} 100%)`,
  ].join(", ");
}

export interface AreaCompareProps {
  label?: string;
  before?: string;
  after?: string;
  beforeValue?: number;
  afterValue?: number;
  unit?: string;
  verdict?: string;
  shape?: "circle" | "square";
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SHRINK = Easing.bezier(0.7, 0, 0.22, 1.04);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    faint: "#5A595F",
    hair: "rgba(255,255,255,0.28)",
    fillTop: "#3A393F",
    fillBottom: "#2A292E",
    onFill: "#F3F2EF",
    stage: "rgba(255,255,255,0.05)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#A3A099",
    hair: "rgba(18,18,20,0.3)",
    fillTop: "#DEDCD6",
    fillBottom: "#CFCDC6",
    onFill: "#121214",
    stage: "rgba(255,255,255,0.7)",
    grain: 0.045,
  },
} as const;

const T_IN = 0;
const T_SHRINK = 38;
const SHRINK_LEN = 40;
const T_LAND = T_SHRINK + SHRINK_LEN;

function groupThousands(n: number) {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function formatValue(v: number, unit: string) {
  if (unit === "KB" && v >= 1000) return `${(v / 1000).toFixed(1)} MB`;
  if (unit === "MB" && v >= 1000) return `${(v / 1000).toFixed(1)} GB`;
  if (v < 10 && Math.abs(v - Math.round(v)) > 0.01) {
    return `${v.toFixed(1)} ${unit}`.trim();
  }
  return `${groupThousands(v)} ${unit}`.trim();
}

function formatRatio(r: number) {
  if (r >= 10) return `${Math.round(r)}×`;
  const s = r.toFixed(1);
  return `${s.endsWith(".0") ? s.slice(0, -2) : s}×`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={41}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Hero({
  text,
  t,
  size,
  color,
}: {
  text: string;
  t: number;
  size: number;
  color: string;
}) {
  const chars = Array.from(text);
  return (
    <div
      style={{
        display: "flex",
        whiteSpace: "pre",
        fontFamily: display,
        fontWeight: 400,
        fontSize: size,
        lineHeight: 1,
        letterSpacing: "-0.03em",
        fontVariantNumeric: "tabular-nums",
        color,
      }}
    >
      {chars.map((ch, i) => {
        const p = interpolate(t, [i * 3, i * 3 + 22], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingBottom: size * 0.06,
              marginBottom: -size * 0.06,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${(1 - p) * 0.7 * size}px)`,
                opacity: interpolate(p, [0, 0.4], [0, 1], CLAMP),
              }}
            >
              {ch}
            </span>
          </span>
        );
      })}
    </div>
  );
}

export function AreaCompare({
  label = "Bundle size",
  before = "Before",
  after = "remocn",
  beforeValue = 1200,
  afterValue = 84,
  unit = "KB",
  verdict = "smaller",
  shape = "circle",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: AreaCompareProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];

  const big = Math.max(beforeValue, afterValue, 0.0001);
  const small = Math.max(Math.min(beforeValue, afterValue), 0.0001);
  const ratio = big / small;
  const square = shape === "square";

  const R0 = height * (square ? 0.33 : 0.36);
  const Rf = R0 * Math.sqrt(small / big);

  const enter = interpolate(t, [T_IN - 8, T_IN + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const s = interpolate(t, [T_SHRINK, T_LAND], [0, 1], {
    ...CLAMP,
    easing: EASE_SHRINK,
  });
  const sLin = interpolate(t, [T_SHRINK, T_LAND], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const r = R0 + (Rf - R0) * s;
  const value = beforeValue + (afterValue - beforeValue) * sLin;

  const glide = interpolate(t, [T_SHRINK + 6, T_LAND + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const margin = width * 0.085;
  const gxEnd = margin + R0 + 14 * u;
  const gx = width / 2 + (gxEnd - width / 2) * glide;
  const gy = height / 2 + 6 * u;
  const bottom = gy + R0;
  const cy = bottom - r;

  const ghostIn = interpolate(t, [T_SHRINK, T_SHRINK + 10], [0, 1], CLAMP);
  const tagIn = interpolate(t, [T_SHRINK + 14, T_SHRINK + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const tint = interpolate(s, [0.2, 0.62], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const meshDrift = interpolate(t, [0, T_LAND + 90], [0, 1.4], CLAMP);
  const onFill = interpolateColors(
    interpolate(tint, [0.38, 0.58], [0, 1], CLAMP),
    [0, 1],
    [p.onFill, "#FFFFFF"],
  );

  const valueSize = Math.max(30 * u, 104 * u * (r / R0));
  const fitsInside = Rf * 2 >= 118 * u;
  const insideAlpha = fitsInside
    ? 1
    : interpolate(s, [0.55, 0.8], [1, 0], CLAMP);
  const eyebrowAlpha = interpolate(t, [T_SHRINK - 2, T_SHRINK + 10], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const afterTagIn = interpolate(t, [T_LAND - 4, T_LAND + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const outsideIn = fitsInside
    ? 0
    : interpolate(t, [T_LAND - 6, T_LAND + 12], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });

  const heroT = t - (T_LAND + 2);
  const heroSize = Math.min(250 * u, width * 0.19);
  const textX = gxEnd + R0 + width * 0.07;
  const textW = width - margin - textX;
  const lineIn = interpolate(heroT, [10, 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const eyeIn = interpolate(heroT, [-4, 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const breathe = interpolate(t, [0, T_LAND + 90], [1.025, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const cornerR = (side: number) => side * 0.1;

  const shapePath = (cx: number, ccy: number, rad: number) =>
    square
      ? {
          x: cx - rad,
          y: ccy - rad,
          w: rad * 2,
          h: rad * 2,
          rx: cornerR(rad * 2),
        }
      : { x: cx - rad, y: ccy - rad, w: rad * 2, h: rad * 2, rx: rad };

  const ghost = shapePath(gx, gy, R0);
  const body = shapePath(gx, cy, r);
  const enterScale = 0.96 + 0.04 * enter;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 70% at ${(gx / width) * 100}% 40%, ${p.stage}, transparent 75%)`,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${breathe})`,
          transformOrigin: "50% 50%",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, overflow: "visible" }}
          aria-hidden
        >
          <rect
            x={ghost.x}
            y={ghost.y}
            width={ghost.w}
            height={ghost.h}
            rx={ghost.rx}
            fill="none"
            stroke={p.hair}
            strokeWidth={Math.max(1, 1.25 * u)}
            opacity={ghostIn}
          />
        </svg>

        <div
          style={{
            position: "absolute",
            left: body.x,
            top: body.y,
            width: body.w,
            height: body.h,
            borderRadius: body.rx,
            overflow: "hidden",
            opacity: enter,
            transform: `scale(${enterScale})`,
            transformOrigin: `${gx - body.x}px ${bottom - body.y}px`,
            background: `linear-gradient(180deg, ${p.fillTop}, ${p.fillBottom})`,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: tint,
              background: meshFill(accent, meshDrift),
            }}
          />
        </div>

        <div
          style={{
            position: "absolute",
            left: gx,
            top: gy - R0 + 34 * u,
            transform: "translateX(-50%)",
            display: "flex",
            alignItems: "baseline",
            gap: 10 * u,
            whiteSpace: "nowrap",
            fontFamily: sans,
            fontSize: 18 * u,
            fontWeight: 500,
            color: p.muted,
            opacity: tagIn,
          }}
        >
          <span>{before}</span>
          <span style={{ color: p.faint }}>·</span>
          <span
            style={{
              color: p.fg,
              fontWeight: 500,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {formatValue(beforeValue, unit)}
          </span>
        </div>

        <div
          style={{
            position: "absolute",
            left: gx,
            top: cy,
            transform: `translate(-50%, -50%) scale(${enterScale})`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            opacity: enter * insideAlpha,
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              fontFamily: sans,
              fontSize: 22 * u,
              fontWeight: 500,
              color: p.muted,
              opacity: eyebrowAlpha,
              marginBottom: 6 * u * eyebrowAlpha,
              height: 28 * u * eyebrowAlpha,
              overflow: "hidden",
            }}
          >
            {label}
          </span>
          <span
            style={{
              fontFamily: display,
              fontWeight: 400,
              fontSize: valueSize * 1.12,
              lineHeight: 1,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
              color: onFill,
            }}
          >
            {formatValue(value, unit)}
          </span>
        </div>

        <div
          style={{
            position: "absolute",
            left: gx,
            top: bottom - Rf * 2 - 14 * u,
            transform: `translate(-50%, -100%) translateY(${(1 - afterTagIn) * 6 * u}px)`,
            fontFamily: sans,
            fontSize: 18 * u,
            fontWeight: 500,
            color: p.fg,
            opacity: afterTagIn * (fitsInside ? 1 : 0),
            whiteSpace: "nowrap",
          }}
        >
          {isBrand(after) ? (
            <RemocnLogo fontSize={22 * u} color={p.fg} />
          ) : (
            after
          )}
        </div>

        <div
          style={{
            position: "absolute",
            left: gx + Rf + 16 * u,
            top: bottom - Rf,
            transform: `translateY(-50%) translateX(${(1 - outsideIn) * -6 * u}px)`,
            display: "flex",
            flexDirection: "column",
            gap: 2 * u,
            opacity: outsideIn,
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              fontFamily: display,
              fontWeight: 400,
              fontSize: 34 * u,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
              color: p.fg,
            }}
          >
            {formatValue(afterValue, unit)}
          </span>
          {isBrand(after) ? (
            <RemocnLogo fontSize={20 * u} color={p.fg} />
          ) : (
            <span
              style={{
                fontFamily: sans,
                fontSize: 18 * u,
                fontWeight: 500,
                color: p.fg,
              }}
            >
              {after}
            </span>
          )}
        </div>

        <div
          style={{
            position: "absolute",
            left: textX,
            top: gy,
            width: textW,
            transform: "translateY(-50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
          }}
        >
          <span
            style={{
              fontFamily: sans,
              fontSize: 22 * u,
              fontWeight: 500,
              color: p.muted,
              opacity: eyeIn,
              transform: `translateY(${(1 - eyeIn) * 8 * u}px)`,
              marginBottom: 18 * u,
              whiteSpace: "nowrap",
            }}
          >
            {label}
          </span>
          <div style={{ marginLeft: -heroSize * 0.05 }}>
            <Hero
              text={formatRatio(ratio)}
              t={heroT}
              size={heroSize}
              color={p.fg}
            />
          </div>
          <span
            style={{
              fontFamily: display,
              fontStyle: "italic",
              fontWeight: 400,
              fontSize: 88 * u,
              lineHeight: 1,
              letterSpacing: "-0.02em",
              color: p.muted,
              opacity: lineIn,
              transform: `translateY(${(1 - lineIn) * 14 * u}px)`,
              filter:
                lineIn < 0.98 ? `blur(${(1 - lineIn) * 6 * u}px)` : undefined,
              whiteSpace: "nowrap",
            }}
          >
            {verdict}
          </span>
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 60%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import React from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  random,
  useVideoConfig,
} from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

// ---------------------------------------------------------------------------
// ascii-dissolve — the frame becomes plain text. The outgoing scene fades as
// a fullscreen field of monospace glyphs rises over it: a deterministic
// noise field drives each cell through a density ramp (" .:-=+*#%@"), so the
// cover reads as living ASCII. It holds fully opaque long enough to be READ
// as text, then the cells drop back down the ramp to space while the
// incoming scene resolves beneath.
//
// Text mode (enterText): the outgoing scene blurs out under the rising
// field; the incoming headline is never previewed as ascii — the field
// dissolves cell by cell (per-cell staggered, never a flat plane) while
// the real text fades in over it. `enterStyle` picks what happens AROUND
// the arriving text:
//   "fade"      — plain: staggered dissolve everywhere, text fades in.
//   "clearing"  — the dissolve order is biased by distance to the text:
//                 cells near the headline vanish first, the field opens a
//                 granular cavity around it.
//   "halo"      — a smooth radial attenuation grows around the text: near
//                 cells slide down the ramp into thin glyphs, a soft dark
//                 well forms behind the headline.
//   "wave"      — one density impulse rides outward from the text: cells
//                 on the wavefront jump up the ramp for a beat, then the
//                 front leaves cleared field behind it.
//   "focus"     — the field defocuses: it blurs and dims while the sharp
//                 text resolves — a depth-of-field handoff.
//   "lime-echo" — on landing, a sparse ring of accent-colored glyphs
//                 flashes once around the headline and settles.
//
// Fully deterministic: per-cell jitter comes from remotion's seeded random,
// the flow from fixed sinusoids over progress, the letterform masks from a
// one-time offscreen-canvas sample of the loaded fonts.
// ---------------------------------------------------------------------------

export type AsciiTextSpec = {
  /** The incoming headline (used for timing and the zone styles). */
  text: string;
  /** Must match the scene's rendered text exactly. */
  fontSize: number;
  /** Concrete family list for canvas sampling (CSS vars won't resolve). */
  fontFamily: string;
  /** Default 400. */
  fontWeight?: number;
  /** Letter-spacing in em, if the scene's text carries one. Default 0. */
  letterSpacingEm?: number;
  /** Glyph color of the ASCII letterform. Default ink. */
  color?: string;
  /** Vertical offset from frame center, px. Default 0. */
  offsetY?: number;
};

export type AsciiEnterStyle =
  | "fade"
  | "clearing"
  | "halo"
  | "wave"
  | "focus"
  | "lime-echo";

export type AsciiDissolveProps = {
  /** Row height of one glyph cell in px. Default 22 (use ~14 in text mode). */
  cellSize?: number;
  /** Glyph color. Default translucent ink. */
  colorFront?: string;
  /** Canvas behind the glyphs during the hold. Default near-black. */
  colorBack?: string;
  /** Optional second color for a sparse scattering of accent cells. */
  accentColor?: string;
  /** Share of cells rendered in the accent color, 0..1. Default 0.05. */
  accentDensity?: number;
  /** Density ramp, lightest → densest. Default " .:-=+*#%@". */
  ramp?: string;
  /** Monospace stack for the field. */
  fontFamily?: string;
  /** Text mode: the incoming headline (used for timing and as the zone). */
  enterText?: AsciiTextSpec;
  /** What happens around the arriving text. Default "fade". */
  enterStyle?: AsciiEnterStyle;
  /** Progress window over which the outgoing scene fades out. */
  exitFade?: [number, number];
  /** Progress window over which the incoming scene resolves. */
  enterFade?: [number, number];
};

// Per-cell stagger: global window progress g plus jitter j → this cell's
// local progress. spread controls how far cells drift apart.
const stagger = (g: number, j: number, spread = 0.55) =>
  Math.max(0, Math.min(1, (g - j * spread) / (1 - spread)));

// The field's mono advance, measured at the size the <pre> renders.
const measureAdvance = (fontFamily: string, fontSize: number): number => {
  const fallback = fontSize * 0.6;
  if (typeof document === "undefined") return fallback;
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return fallback;
  ctx.font = `400 ${fontSize}px ${fontFamily}`;
  const w = ctx.measureText("0").width;
  return w > 0 ? w : fallback;
};

// Sample the headline's letterforms: draw the text once on an offscreen
// canvas at 2× cell resolution and grade each cell by subsample coverage
// (0..4). Edge cells get mid-ramp glyphs, core cells the densest — the
// grading anti-aliases the letter contours, so strokes thinner than a cell
// still read as continuous letters.
const buildTextMask = (
  spec: AsciiTextSpec,
  width: number,
  height: number,
  cols: number,
  rows: number,
  advance: number,
  cellH: number,
): Uint8Array | null => {
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  canvas.width = cols * 2;
  canvas.height = rows * 2;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  ctx.setTransform(2 / advance, 0, 0, 2 / cellH, 0, 0);
  ctx.font = `${spec.fontWeight ?? 400} ${spec.fontSize}px ${spec.fontFamily}`;
  const spacing = (spec.letterSpacingEm ?? 0) * spec.fontSize;
  if (spacing !== 0) {
    (
      ctx as CanvasRenderingContext2D & { letterSpacing?: string }
    ).letterSpacing = `${spacing}px`;
  }
  ctx.textAlign = "center";
  // Canvas "middle" baseline is computed from the em square and lands
  // visibly ABOVE where a flex-centered DOM span puts the same text. Rebuild
  // the DOM's math instead: a flex-centered span (line-height normal) puts
  // its baseline at H/2 + (ascent - descent)/2, with ascent/descent taken
  // from the font's own metrics.
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#fff";
  const metrics = ctx.measureText(spec.text);
  const ascent = metrics.fontBoundingBoxAscent ?? spec.fontSize * 0.8;
  const descent = metrics.fontBoundingBoxDescent ?? spec.fontSize * 0.2;
  const baselineY = height / 2 + (ascent - descent) / 2 + (spec.offsetY ?? 0);
  ctx.fillText(spec.text, width / 2, baselineY);
  const data = ctx.getImageData(0, 0, cols * 2, rows * 2).data;
  const mask = new Uint8Array(cols * rows);
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let hits = 0;
      if (data[(y * 2 * cols * 2 + x * 2) * 4 + 3] > 100) hits++;
      if (data[(y * 2 * cols * 2 + x * 2 + 1) * 4 + 3] > 100) hits++;
      if (data[((y * 2 + 1) * cols * 2 + x * 2) * 4 + 3] > 100) hits++;
      if (data[((y * 2 + 1) * cols * 2 + x * 2 + 1) * 4 + 3] > 100) hits++;
      mask[y * cols + x] = hits;
    }
  }
  return mask;
};

const AsciiDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<AsciiDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    cellSize = 22,
    colorFront = "rgba(242,242,242,0.6)",
    colorBack = "#0d0d10",
    accentColor,
    accentDensity = 0.05,
    ramp = " .:-=+*#%@",
    fontFamily = "ui-monospace, SFMono-Regular, Menlo, monospace",
    enterText,
    enterStyle = "fade",
    exitFade,
    enterFade,
  } = passedProps;
  const { width, height } = useVideoConfig();
  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const textMode = enterText !== undefined;

  // The outgoing scene blurs out under the rising field.
  const exitWindow = exitFade ?? [0.14, 0.3];
  // The real text fades in while the field dissolves cell by cell.
  const enterWindow = enterFade ?? (textMode ? [0.6, 0.8] : [0.62, 0.8]);

  // The masks and the mono advance must be measured with the REAL webfonts.
  // The component can mount while they are still loading (a fallback font
  // would bake wrong metrics into the memoized masks and shift the letterform
  // off the scene's text) — so gate on document.fonts and hold the render.
  const [fontsReady, setFontsReady] = React.useState(
    () => typeof document === "undefined" || document.fonts.status === "loaded",
  );
  React.useEffect(() => {
    if (fontsReady || typeof document === "undefined") return;
    const handle = delayRender("ascii-dissolve: waiting for fonts");
    let alive = true;
    document.fonts.ready.then(() => {
      if (alive) setFontsReady(true);
      continueRender(handle);
    });
    return () => {
      alive = false;
      continueRender(handle);
    };
  }, [fontsReady]);

  const fontSize = cellSize * 0.86;
  // biome-ignore lint/correctness/useExhaustiveDependencies: fontsReady is an intentional extra dep — remeasure the mono advance once the real webfonts load
  const advance = React.useMemo(
    () => measureAdvance(fontFamily, fontSize),
    [fontFamily, fontSize, fontsReady],
  );
  const cols = Math.ceil(width / advance);
  const rows = Math.ceil(height / cellSize) + 1;

  // The zone styles need to know where the incoming text sits — a capsule
  // around its center line, derived from the letterform mask's bounds. The
  // mask itself is never displayed.
  const zoneStyles: AsciiEnterStyle[] = [
    "clearing",
    "halo",
    "wave",
    "lime-echo",
  ];
  const needZone = enterText !== undefined && zoneStyles.includes(enterStyle);
  const enterMask = React.useMemo(
    () =>
      enterText && needZone && fontsReady
        ? buildTextMask(enterText, width, height, cols, rows, advance, cellSize)
        : null,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      enterText,
      needZone,
      fontsReady,
      width,
      height,
      cols,
      rows,
      advance,
      cellSize,
    ],
  );
  const enterZone = React.useMemo(() => {
    if (enterMask === null) return null;
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        if (enterMask[y * cols + x] > 0) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }
    if (maxX < minX) return null;
    return {
      x0: minX * advance,
      x1: (maxX + 1) * advance,
      cy: ((minY + maxY + 1) / 2) * cellSize,
      halfH: ((maxY - minY + 1) / 2) * cellSize,
    };
  }, [enterMask, cols, rows, advance, cellSize]);

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, exitWindow, [1, 0], clampOpts),
      filter: `blur(${interpolate(p, [exitWindow[0], exitWindow[1] + 0.06], [0, 8], clampOpts)}px)`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  // -------------------------------------------------------------------------
  // Envelopes.
  // -------------------------------------------------------------------------
  // Generic mode keeps the original flat envelopes; text mode staggers the
  // rise and the dissolve per cell instead, so nothing moves as one plane.
  const coverage = textMode
    ? 1
    : interpolate(p, [0.06, 0.28, 0.6, 0.9], [0, 1, 1, 0], clampOpts);
  const fieldOpacity = textMode
    ? 1
    : interpolate(p, [0.04, 0.2, 0.66, 0.94], [0, 1, 1, 0], clampOpts);
  const panelOpacity = textMode
    ? interpolate(p, [0.06, 0.24, 0.55, 0.75], [0, 1, 1, 0], clampOpts)
    : fieldOpacity;

  // Text-mode phase clocks. The outgoing scene blurs out as the field
  // rises; the field boils, then dissolves cell by cell while the real
  // text fades in.
  const riseG = interpolate(p, [0.04, 0.3], [0, 1], clampOpts);
  const dissolveG = interpolate(
    p,
    enterStyle === "clearing" ? [0.52, 0.85] : [0.5, 0.82],
    [0, 1],
    clampOpts,
  );

  // Style clocks for the arriving text's surroundings.
  const haloG = interpolate(p, [0.52, 0.74], [0, 1], clampOpts);
  const waveT = interpolate(p, [0.56, 0.94], [0, 1], {
    ...clampOpts,
    easing: Easing.out(Easing.quad),
  });
  const waveR = waveT * 860; //  the impulse front, px from the text capsule
  const echoFlash = interpolate(p, [0.56, 0.64, 0.82], [0, 0.9, 0], clampOpts);
  const focusBlur = interpolate(p, [0.55, 0.9], [0, 4], clampOpts);
  const focusFade = interpolate(p, [0.62, 0.94], [1, 0], clampOpts);

  const cx = cols / 2;
  const cy = rows / 2;
  const t = p * 5;
  const rampLen = ramp.length;

  const mainRows: string[] = [];
  const accentRows: string[] = [];
  const echoRows: string[] = [];
  const fieldAlive = textMode ? p < 0.999 : fieldOpacity > 0.001;

  if (fieldAlive) {
    for (let y = 0; y < rows; y++) {
      let mainRow = "";
      let accentRow = "";
      let echoRow = "";
      for (let x = 0; x < cols; x++) {
        // A slow sinusoid flow plus per-cell jitter — organic, but textual.
        const base =
          0.5 +
          (Math.sin(x * 0.33 + t * 1.7) +
            Math.sin(y * 0.51 - t * 1.2) +
            Math.sin((x * 0.5 + y) * 0.24 + t * 0.9) +
            Math.sin(Math.hypot(x - cx, (y - cy) * 1.8) * 0.42 - t * 2.1)) /
            8;
        const jitter = random(`ascii-${x}-${y}`);

        // Distance to the incoming text's capsule, for the zone styles —
        // and the plain circular distance from its center, for the wave.
        let dist = Infinity;
        let distC = Infinity;
        let s = 0; // proximity, 1 at the text's center line → 0 far away
        if (enterZone !== null) {
          const px = (x + 0.5) * advance;
          const py = (y + 0.5) * cellSize;
          const nx = Math.min(Math.max(px, enterZone.x0), enterZone.x1);
          dist = Math.hypot(px - nx, py - enterZone.cy);
          distC = Math.hypot(
            px - (enterZone.x0 + enterZone.x1) / 2,
            py - enterZone.cy,
          );
          s = Math.max(0, 1 - dist / (enterZone.halfH + 64));
        }

        let cellCoverage: number;
        if (!textMode) {
          cellCoverage = coverage;
        } else if (enterStyle === "clearing" && enterZone !== null) {
          // Dissolve order biased by proximity: cells near the headline
          // vanish first, a granular cavity opens outward.
          const order = (1 - s) * 0.6 + random(`ascii-d-${x}-${y}`) * 0.4;
          const gone = Math.max(
            0,
            Math.min(1, (dissolveG * 1.35 - order) / 0.3),
          );
          cellCoverage = stagger(riseG, jitter) * (1 - gone);
        } else if (enterStyle === "wave" && enterZone !== null) {
          // The impulse front — a CIRCLE from the text's center — clears
          // the field behind it.
          const passed = Math.max(0, Math.min(1, (waveR - distC) / 55));
          cellCoverage = stagger(riseG, jitter) * (1 - passed);
        } else {
          cellCoverage =
            stagger(riseG, jitter) *
            (1 - stagger(dissolveG, random(`ascii-d-${x}-${y}`)));
        }

        let d = Math.max(
          0,
          Math.min(
            0.999,
            (base * 0.72 + jitter * 0.28) * cellCoverage * 1.2 - 0.08,
          ),
        );
        if (enterStyle === "halo" && enterZone !== null) {
          // A smooth radial attenuation: near cells slide down the ramp.
          d *= 1 - haloG * s;
        }
        if (enterStyle === "wave" && enterZone !== null && waveT > 0) {
          // Cells on the circular wavefront jump up the ramp for a beat.
          const bump = Math.exp(-(((distC - waveR) / 55) ** 2));
          d = Math.min(0.999, d + bump * 0.5);
        }
        const ch = ramp[Math.floor(d * rampLen)] ?? " ";
        const isAccent =
          accentColor !== undefined &&
          random(`ascii-a-${x}-${y}`) < accentDensity;
        mainRow += isAccent ? " " : ch;
        accentRow += isAccent ? ch : " ";

        // The lime echo: a sparse ring of accent glyphs around the headline.
        if (
          enterStyle === "lime-echo" &&
          enterZone !== null &&
          echoFlash > 0.01 &&
          dist > 8 &&
          dist < 84 &&
          ch !== " " &&
          random(`ascii-e-${x}-${y}`) < 0.5
        ) {
          echoRow += ch;
        } else {
          echoRow += " ";
        }
      }
      mainRows.push(mainRow);
      accentRows.push(accentRow);
      echoRows.push(echoRow);
    }
  }

  // The blur must hit exactly 0 by p = 1: the entering presentation stays
  // mounted at p = 1 for the whole scene, so any residue would soften the
  // incoming scene permanently. In text mode the incoming scene resolves
  // with NO transform at all — it must sit pixel-exact under the letterform.
  const enterBlur = textMode
    ? 0
    : interpolate(
        p,
        [enterWindow[0], Math.min(1, enterWindow[1] + 0.05)],
        [10, 0],
        clampOpts,
      );
  const childStyle: React.CSSProperties = textMode
    ? { opacity: interpolate(p, enterWindow, [0, 1], clampOpts) }
    : {
        opacity: interpolate(p, enterWindow, [0, 1], clampOpts),
        scale: `${interpolate(p, [enterWindow[0], 1], [1.04, 1], {
          ...clampOpts,
          easing: Easing.out(Easing.cubic),
        })}`,
        filter: enterBlur > 0.01 ? `blur(${enterBlur}px)` : undefined,
      };

  const preStyle: React.CSSProperties = {
    margin: 0,
    position: "absolute",
    inset: 0,
    overflow: "hidden",
    whiteSpace: "pre",
    fontFamily,
    fontSize,
    lineHeight: `${cellSize}px`,
    color: colorFront,
  };

  const renderLayer = (
    layerRows: string[],
    color: string,
    layerOpacity: number,
  ) =>
    layerOpacity > 0.001 ? (
      <pre style={{ ...preStyle, color, opacity: layerOpacity }}>
        {layerRows.join("\n")}
      </pre>
    ) : null;

  return (
    <AbsoluteFill>
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
      {fieldAlive ? (
        <AbsoluteFill style={{ pointerEvents: "none" }}>
          <AbsoluteFill
            style={{ background: colorBack, opacity: panelOpacity }}
          />
          <AbsoluteFill
            style={
              enterStyle === "focus" && textMode
                ? {
                    opacity: focusFade,
                    filter:
                      focusBlur > 0.01 ? `blur(${focusBlur}px)` : undefined,
                  }
                : undefined
            }
          >
            {renderLayer(mainRows, colorFront, fieldOpacity)}
            {accentColor !== undefined
              ? renderLayer(accentRows, accentColor, fieldOpacity)
              : null}
          </AbsoluteFill>
          {enterStyle === "lime-echo"
            ? renderLayer(echoRows, accentColor ?? "#C3E88D", echoFlash)
            : null}
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export function asciiDissolve(
  props: AsciiDissolveProps = {},
): TransitionPresentation<AsciiDissolveProps> {
  return {
    component: AsciiDissolvePresentation,
    props,
  };
}

"use client";

import type React from "react";
import { AbsoluteFill, useVideoConfig } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type AsciiRenderProps = {
  glyphSize?: number;
  charset?: string;
  colored?: boolean;
  ink?: string;
  intensity?: number;
};

const DEFAULTS = {
  glyphSize: 26,
  charset: " .:-=+*#%@",
  colored: false,
  ink: "#9dff9d",
  intensity: 1,
};

const GLYPH_ASPECT = 0.545;
const ATLAS_CELL_W = 24;
const ATLAS_CELL_H = 44;
const ATLAS_FONT =
  'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace';

type NormalizedProps = {
  cellX: number;
  cellY: number;
  charset: string;
  colored: boolean;
  ink: string;
  intensity: number;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform sampler2D u_atlas;
uniform vec2 u_cell;
uniform float u_glyph_count;
uniform float u_colored;
uniform vec3 u_ink;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const int TAPS = 3;

vec4 cellAverage(vec2 center, vec2 cell) {
  vec4 sum = vec4(0.0);
  for (int y = 0; y < TAPS; y++) {
    for (int x = 0; x < TAPS; x++) {
      vec2 offset = (vec2(float(x), float(y)) + 0.5) / float(TAPS) - 0.5;
      sum += texture(u_scene, center + offset * cell);
    }
  }
  return sum / float(TAPS * TAPS);
}

void main() {
  vec2 cell = max(u_cell, vec2(0.001));
  vec2 origin = floor(v_uv / cell) * cell;
  vec4 sampled = cellAverage(origin + cell * 0.5, cell);

  float luma = dot(sampled.rgb, vec3(0.299, 0.587, 0.114));
  float index = min(floor(luma * u_glyph_count), u_glyph_count - 1.0);

  vec2 local = clamp((v_uv - origin) / cell, 0.008, 0.992);
  float mask =
    texture(u_atlas, vec2((index + local.x) / u_glyph_count, local.y)).r;

  vec3 glyph = mix(u_ink, sampled.rgb, u_colored) * mask;
  vec4 source = texture(u_scene, v_uv);
  float amount = clamp(u_intensity, 0.0, 1.0);

  outColor = vec4(
    mix(source.rgb, glyph, amount),
    mix(source.a, max(mask, sampled.a), amount)
  );
}`;

type Atlas = { charset: string; texture: WebGLTexture };

const atlases = new WeakMap<WebGL2RenderingContext, Atlas>();

function drawAtlas(charset: string): OffscreenCanvas {
  const canvas = new OffscreenCanvas(
    ATLAS_CELL_W * charset.length,
    ATLAS_CELL_H,
  );
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error("ascii-render: failed to acquire a 2D context");
  }
  context.fillStyle = "#000000";
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#ffffff";
  context.font = `${Math.round(ATLAS_CELL_H * 0.74)}px ${ATLAS_FONT}`;
  context.textAlign = "center";
  context.textBaseline = "middle";
  for (let i = 0; i < charset.length; i++) {
    context.fillText(
      charset[i],
      i * ATLAS_CELL_W + ATLAS_CELL_W / 2,
      ATLAS_CELL_H / 2,
    );
  }
  return canvas;
}

function bindAtlas(gl: WebGL2RenderingContext, charset: string): void {
  gl.activeTexture(gl.TEXTURE1);

  let atlas = atlases.get(gl);
  if (!atlas) {
    const texture = gl.createTexture();
    if (!texture) {
      throw new Error("ascii-render: failed to create the glyph atlas");
    }
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    atlas = { charset: "", texture };
    atlases.set(gl, atlas);
  } else {
    gl.bindTexture(gl.TEXTURE_2D, atlas.texture);
  }

  if (atlas.charset !== charset) {
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      drawAtlas(charset),
    );
    atlas.charset = charset;
  }
}

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { cellX, cellY, charset, colored, ink, intensity } = passedProps;
    bindAtlas(gl, charset);
    gl.uniform1i(uniform("u_atlas"), 1);
    gl.uniform1f(uniform("u_glyph_count"), charset.length);
    gl.uniform2f(uniform("u_cell"), cellX, cellY);
    gl.uniform1f(uniform("u_colored"), colored ? 1 : 0);
    gl.uniform3fv(uniform("u_ink"), toRgb(ink));
    gl.uniform1f(uniform("u_intensity"), intensity);
  },
);

const AsciiRenderFallback: React.FC<NormalizedProps & CanvasFilterProps> = ({
  children,
}) => <AbsoluteFill>{children}</AbsoluteFill>;

const AsciiRenderCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: AsciiRenderFallback,
});

export const AsciiRender: React.FC<AsciiRenderProps & CanvasFilterProps> = ({
  glyphSize = DEFAULTS.glyphSize,
  charset = DEFAULTS.charset,
  colored = DEFAULTS.colored,
  ink = DEFAULTS.ink,
  intensity = DEFAULTS.intensity,
  children,
}) => {
  const { width, height } = useVideoConfig();
  const resolved = charset.length > 0 ? charset : DEFAULTS.charset;

  return (
    <AsciiRenderCanvas
      cellX={(glyphSize * GLYPH_ASPECT) / width}
      cellY={glyphSize / height}
      charset={resolved}
      colored={colored}
      ink={ink}
      intensity={intensity}
    >
      {children}
    </AsciiRenderCanvas>
  );
};

"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { useEffect, useId, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

/** Film-title serif for the hero, its sans sibling for the caption. */
const serif = loadSerif("normal", { weights: ["400"], subsets: ["latin"] });
const sans = loadSans("normal", { weights: ["400"], subsets: ["latin"] });

export interface AspectSlitProps {
  /** Short title. It first appears inside the slit, then grows to hero size. */
  title?: string;
  /** Small line under the hero title. Pass "" to hide. */
  caption?: string;
  /** Height of the narrowest slit, as a share of the frame height. */
  slit?: number;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Beat sheet (30fps):
//  0–24    letterbox bars close from 16:9 to 2.39:1 (already moving on frame 0)
//  24–32   a beat on scope
//  32–64   the bars keep closing to a thin slit
//  50–74   the title rises into the slit from behind the lower bar; holds,
//          tracking tightening, to 98
//  98–138  bars open back to full frame; the title grows to hero size, never
//          taller than the opening
//  128–150 caption settles under the title; poster hold to 180
const SCOPE_AT = -6;
const SCOPE_END = 24;
const SLIT_AT = 32;
const SLIT_END = 64;
const RISE_AT = 50;
const RISE_END = 74;
const OPEN_AT = 98;
const OPEN_END = 138;
const GROW_AT = 102;
const GROW_END = 146;
const CAPTION_AT = 128;
const CAPTION_END = 150;

/** Bars: a mechanical matte, eased at both ends. */
const BARS = Easing.bezier(0.62, 0, 0.3, 1);
const OPEN = Easing.bezier(0.7, 0, 0.22, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/** Hero tracking at full size, in em. The serif wants less than a grotesk. */
const HERO_TRACK = -0.022;

interface TitleMetrics {
  /** Cap top and baseline inside a line-height: 1 box, in em. */
  capTop: number;
  baseline: number;
  /** Descender depth below the baseline, in em. */
  descent: number;
  /** Title advance at 1em with hero tracking, in em. */
  width: number;
}

function measureTitle(title: string): TitleMetrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const n = Math.max(1, [...title].length);
  if (!ctx) {
    return { capTop: 0.2, baseline: 0.85, descent: 0.22, width: n * 0.42 };
  }
  ctx.font = `400 200px "${serif.fontFamily}"`;
  const box = ctx.measureText("H");
  const run = ctx.measureText(title);
  const asc = box.fontBoundingBoxAscent / 200;
  const desc = box.fontBoundingBoxDescent / 200;
  const baseline = 0.5 + (asc - desc) / 2;
  return {
    capTop: baseline - box.actualBoundingBoxAscent / 200,
    baseline,
    descent: Math.max(0.12, run.actualBoundingBoxDescent / 200),
    width: run.width / 200 + HERO_TRACK * (n - 1),
  };
}

function useTitleMetrics(title: string) {
  const [metrics, setMetrics] = useState<TitleMetrics | null>(null);
  const [handle] = useState(() => delayRender("aspect-slit: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      serif.waitUntilDone(),
      sans.waitUntilDone(),
      document.fonts.load(`400 100px "${serif.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measureTitle(title));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [title, handle]);
  return metrics;
}

/**
 * The opening is lit by a gradients.sh palette: "mesh" on dark (built on the
 * accent), "pixel-glass" washed onto the off-white stage for light. Blob
 * positions drift a few percent over the shot.
 */
const BLOBS = {
  dark: [
    { color: "#8796EE", x: 16, y: 20, a: 0.9 },
    { color: "#ACCENT", x: 84, y: 26, a: 0.95 },
    { color: "#0E1645", x: 70, y: 96, a: 0.6 },
    { color: "#1D2A8F", x: 22, y: 82, a: 0.85 },
    { color: "#ACCENT", x: 52, y: 48, a: 0.8 },
    { color: "#ECDCF2", x: 92, y: 62, a: 0.55 },
  ],
  light: [
    { color: "#7A3CFF", x: 18, y: 24, a: 0.2 },
    { color: "#FF4FB8", x: 82, y: 30, a: 0.16 },
    { color: "#3D6BFF", x: 66, y: 84, a: 0.22 },
    { color: "#ACCENT", x: 24, y: 82, a: 0.14 },
  ],
} as const;

const THEMES = {
  dark: {
    bars: "#0A0A0B",
    ground: "#2E45B7",
    ink: "#FFFFFF",
    caption: "rgba(255,255,255,0.78)",
    grain: 0.07,
    accentPeriod: false,
  },
  light: {
    bars: "#0A0A0B",
    ground: "#F4F3F1",
    ink: "#111113",
    caption: "#5E5C57",
    grain: 0.05,
    accentPeriod: true,
  },
} as const;

const alpha = (color: string, a: number) =>
  `color-mix(in oklab, ${color} ${Math.round(a * 100)}%, transparent)`;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.85"
          numOctaves={2}
          seed={7}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function AspectSlit({
  title = "Now showing.",
  caption = "A launch film, built in React.",
  slit = 0.125,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: AspectSlitProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const metrics = useTitleMetrics(title);

  // Bar height per side.
  const scopeBar = Math.max(0, (H - W / 2.39) / 2);
  const slitH = Math.round(H * slit);
  const slitBar = (H - slitH) / 2;
  const toScope = interpolate(frame, [SCOPE_AT, SCOPE_END], [0, 1], {
    ...CLAMP,
    easing: BARS,
  });
  const toSlit = interpolate(frame, [SLIT_AT, SLIT_END], [0, 1], {
    ...CLAMP,
    easing: BARS,
  });
  const open = interpolate(frame, [OPEN_AT, OPEN_END], [0, 1], {
    ...CLAMP,
    easing: OPEN,
  });
  const closed = toScope * scopeBar + toSlit * (slitBar - scopeBar);
  const bar = closed * (1 - open);
  const opening = H - 2 * bar;

  const drift = (k: number) => ({
    x: Math.sin(frame / 44 + k * 1.7) * 3,
    y: Math.cos(frame / 57 + k * 2.3) * 2.5,
  });
  const ground = [
    ...BLOBS[theme].map((b, k) => {
      const o = drift(k);
      const col = b.color === "#ACCENT" ? accent : b.color;
      return `radial-gradient(85% 95% at ${(b.x + o.x).toFixed(2)}% ${(b.y + o.y).toFixed(2)}%, ${alpha(col, b.a)} 0%, transparent 68%)`;
    }),
    c.ground,
  ].join(", ");

  const bars = (
    <>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: W,
          height: Math.ceil(bar),
          backgroundColor: c.bars,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          bottom: 0,
          width: W,
          height: Math.ceil(bar),
          backgroundColor: c.bars,
        }}
      />
    </>
  );

  if (!metrics) {
    return (
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: ground,
          overflow: "hidden",
        }}
      >
        {bars}
      </div>
    );
  }
  const { capTop: CAP_TOP, baseline: BASELINE } = metrics;

  // Title sizes: in the slit its caps take about half the gap; at hero size it
  // spans most of the width.
  const slitSize = (slitH * 0.5) / (BASELINE - CAP_TOP);
  const heroSize = Math.min(H * 0.3, (W * 0.78) / metrics.width);
  const grow = interpolate(frame, [GROW_AT, GROW_END], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  // A slow push while it sits in the slit, so the hold is never frozen.
  const push = interpolate(frame, [RISE_END - 6, OPEN_AT + 4], [0, 1], CLAMP);
  const wanted = slitSize * (1 + 0.035 * push) + (heroSize - slitSize) * grow;
  // Framed, never clipped: the ink stays inside the opening with room to spare.
  const size = Math.min(
    wanted,
    (opening * 0.6) / (BASELINE + metrics.descent - CAP_TOP),
  );
  const scale = size / heroSize;

  const rise = interpolate(frame, [RISE_AT, RISE_END], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const tracking = interpolate(
    frame,
    [RISE_AT, OPEN_AT, GROW_END],
    [0.01, -0.012, HERO_TRACK],
    CLAMP,
  );

  const captionIn = interpolate(frame, [CAPTION_AT, CAPTION_END], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const captionSize = H * 0.034;
  const captionGap = H * 0.028;

  // Cap-height centre of the title sits on the frame centre, then the group
  // (title + caption) recentres as the caption arrives.
  const capMid = ((CAP_TOP + BASELINE) / 2) * size;
  const descender = metrics.descent * size;
  const groupShift = -captionIn * (descender + captionGap + captionSize) * 0.5;
  // Starts with its cap line just behind the lower bar's edge, wherever it is.
  const riseFrom = opening / 2 + ((BASELINE - CAP_TOP) / 2) * size + 2;
  const titleTop = H / 2 - capMid + groupShift + (1 - rise) * riseFrom;
  const baseline = titleTop + BASELINE * size;

  const body =
    c.accentPeriod && title.endsWith(".") ? title.slice(0, -1) : title;
  const period = body !== title;

  return (
    <AbsoluteFill style={{ background: ground, overflow: "hidden" }}>
      <Grain opacity={c.grain} />
      {rise > 0 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: titleTop,
            height: heroSize,
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              fontFamily: serif.fontFamily,
              fontWeight: 400,
              fontSize: heroSize,
              lineHeight: 1,
              letterSpacing: `${tracking}em`,
              color: c.ink,
              whiteSpace: "nowrap",
              transform: `scale(${scale})`,
              transformOrigin: "50% 0%",
              // letter-spacing trails the last glyph; pad it back to centre the ink
              paddingRight: `${-tracking}em`,
            }}
          >
            {body}
            {period ? <span style={{ color: accent }}>.</span> : null}
          </div>
        </div>
      ) : null}

      {caption && captionIn > 0 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: baseline + descender + captionGap - captionSize * 0.2,
            textAlign: "center",
            fontFamily: sans.fontFamily,
            fontWeight: 400,
            fontSize: captionSize,
            lineHeight: 1.2,
            letterSpacing: "-0.005em",
            color: c.caption,
            opacity: captionIn,
            transform: `translateY(${(1 - captionIn) * H * 0.012}px)`,
          }}
        >
          {caption}
        </div>
      ) : null}

      {bars}
    </AbsoluteFill>
  );
}

