/* Mark sets */

/** Rulers then radius arcs, each `stagger` frames after the last. */
export function MeasureMarks({
  measures,
  radii = [],
  color,
  start = 0,
  stagger = 5,
}: {
  measures: Measure[];
  radii?: RadiusMark[];
  color: string;
  start?: number;
  stagger?: number;
}) {
  return (
    <>
      {measures.map((m, i) => (
        <Ruler
          key={`${m.from.join()}-${m.to.join()}`}
          from={m.from}
          to={m.to}
          label={m.label}
          color={color}
          delay={start + i * stagger}
          labelSide={m.side}
        />
      ))}
      {radii.map((r, i) => (
        <CornerArc
          key={`${r.x}-${r.y}`}
          x={r.x}
          y={r.y}
          r={r.r}
          label={r.label}
          color={color}
          delay={start + (measures.length + i) * stagger}
        />
      ))}
    </>
  );
}

const NOTE_SPOT = {
  start: (r: Rect) => ({
    x: r.x - 3,
    y: r.y - 3,
    anchor: "aboveStart" as const,
  }),
  end: (r: Rect) => ({
    x: r.x + r.w + 3,
    y: r.y - 3,
    anchor: "aboveEnd" as const,
  }),
  below: (r: Rect) => ({
    x: r.x - 3,
    y: r.y + r.h + 3,
    anchor: "belowStart" as const,
  }),
};

/** Every issue boxed, with its note popping on once the box closes. */
export function IssueMarks({
  issues,
  color,
  start = 0,
  stagger = 4,
}: {
  issues: Issue[];
  color: string;
  start?: number;
  stagger?: number;
}) {
  return (
    <>
      {issues.map((issue, i) => (
        <div key={`${issue.rect.x}-${issue.rect.y}-${issue.note}`}>
          <OutlineBox
            rect={issue.rect}
            color={color}
            delay={start + i * stagger}
          />
          <Pill
            {...NOTE_SPOT[issue.side ?? "start"](issue.rect)}
            text={issue.note}
            color={color}
            delay={start + i * stagger + 10}
          />
        </div>
      ))}
    </>
  );
}

export function TokenMarks({
  tokens,
  start = 0,
  stagger = 6,
  lineColor,
}: {
  tokens: TokenSpec[];
  start?: number;
  stagger?: number;
  lineColor?: string;
}) {
  return (
    <>
      {tokens.map((tag, i) => (
        <TokenTag
          key={`${tag.label}-${tag.anchor.join()}`}
          anchor={tag.anchor}
          at={tag.at}
          label={tag.label}
          swatch={tag.swatch}
          lineColor={lineColor}
          delay={start + i * stagger}
        />
      ))}
    </>
  );
}

/** Column guides drop in, the highlight fills, then the now line slides across. */
export function GuideMarks({
  guides,
  color,
  nowColor = C.primary,
  start = 0,
}: {
  guides: GuideSpec;
  color: string;
  nowColor?: string;
  start?: number;
}) {
  const { columns, top, bottom, highlight, ruler, now } = guides;
  const h = highlight?.rect;
  return (
    <>
      {columns.map((x, i) => (
        <Guide
          key={x}
          x={x}
          y={top}
          length={bottom - top}
          vertical
          color={color}
          dashed
          delay={start + i * 3}
        />
      ))}
      {h && highlight && (
        <>
          <OutlineBox
            rect={h}
            color={color}
            fill={`${color}14`}
            inset={0}
            radius={0}
            delay={start + 14}
          />
          <OutlineBox
            rect={{ x: h.x + 6, y: h.y + 4, w: h.w - 12, h: 22 }}
            color={color}
            radius={4}
            inset={0}
            delay={start + 20}
          />
          <Pill
            x={h.x + h.w / 2}
            y={h.y + 4}
            text={highlight.label}
            color={color}
            delay={start + 26}
            anchor="above"
          />
        </>
      )}
      {ruler && (
        <Ruler
          from={ruler.from}
          to={ruler.to}
          label={ruler.label}
          color={color}
          delay={start + 24}
          labelSide={ruler.side}
        />
      )}
      {now && (
        <>
          <Guide
            x={now.from}
            y={now.y}
            length={now.to - now.from}
            color={nowColor}
            width={1.5}
            delay={start + 30}
          />
          <Pill
            x={now.from}
            y={now.y}
            text={now.label}
            color={nowColor}
            delay={start + 30}
            anchor="left"
          />
        </>
      )}
    </>
  );
}

