          </div>
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: H / 2 + F * 0.95,
          display: "flex",
          justifyContent: "center",
          fontFamily: mono.fontFamily,
          fontWeight: 400,
          fontSize: 17 * u,
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          color: "rgba(255,255,255,0.84)",
          opacity: metaIn,
          transform: `translateY(${(1 - metaIn) * 12 * u}px)`,
        }}
