const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Tone = "dark" | "light";

const TONES: Record<Tone, { bg: string; fg: string }> = {
  dark: { bg: "#0A0A0B", fg: "#F3F2EF" },
  light: { bg: "#F5F4F0", fg: "#121214" },
};

/* gradients.sh "mesh" palette. The colour blocks are windows onto one
   frame-anchored mesh field; the landed scene sits on a quieter version. */
const MESH = {
  bg: "#0a0d24",
  colors: ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"],
  at: [
    [16, 20],
    [84, 26],
    [72, 86],
    [22, 80],
    [52, 48],
    [92, 62],
  ],
};

const mixA = (c: string, a: number) =>
  `color-mix(in oklab, ${c} ${Math.round(a * 100)}%, transparent)`;

/** Bright mesh, used inside the blocks: lilac and periwinkle blobs over the
    mesh blue, so every block reads as a lit colour. `d` drifts the blobs. */
function meshField(d: number) {
  const [c0, c1, c2, c3] = MESH.colors;
  const cols = [c0, c1, c3, c1, c0, c2];
  const alpha = [0.95, 0.9, 0.7, 0.8, 0.55, 0.9];
  const layers = MESH.at.map(([x, y], i) => {
    const dx = Math.sin(d * Math.PI * 2 + i * 1.7) * 3;
    const dy = Math.cos(d * Math.PI * 2 + i * 2.3) * 3;
    return `radial-gradient(55% 65% at ${(x + dx).toFixed(2)}% ${(y + dy).toFixed(2)}%, ${mixA(cols[i], alpha[i])} 0%, transparent 70%)`;
  });
  return `${layers.join(", ")}, linear-gradient(${c2}, ${c2})`;
}

/** Quiet mesh ground for the landed scene: dark centre, colour at the edges. */
function meshGround(tone: Tone, d: number) {
  const [c0, c1, c2] = MESH.colors;
  const s = Math.sin(d * Math.PI * 2) * 3;
  if (tone === "light") {
    return [
      `radial-gradient(60% 70% at ${(10 + s).toFixed(2)}% ${(12 - s).toFixed(2)}%, ${mixA(c1, 0.3)} 0%, transparent 70%)`,
      `radial-gradient(60% 70% at ${(90 - s).toFixed(2)}% ${(90 + s).toFixed(2)}%, ${mixA(c0, 1)} 0%, transparent 72%)`,
    ].join(", ");
  }
  return [
    `radial-gradient(60% 70% at ${(8 + s).toFixed(2)}% ${(6 - s).toFixed(2)}%, ${mixA(c2, 0.6)} 0%, transparent 70%)`,
    `radial-gradient(75% 85% at ${(92 - s).toFixed(2)}% ${(92 + s).toFixed(2)}%, ${mixA(c2, 1)} 0%, transparent 70%)`,
  ].join(", ");
}

const isLogo = (s: string) => /^remocn\.?$/i.test(s.trim());

function Headline({
  text,
  tone,
  accent,
  mark,
}: {
  text: string;
  tone: Tone;
  accent: string;
  mark: boolean;
}) {
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const c = TONES[tone];
  const logo = mark && isLogo(text);
  const dot = mark && !logo && text.endsWith(".");
  const body = dot ? text.slice(0, -1) : text;
  const size = Math.min(220 * u, (0.78 * W) / (Math.max(4, text.length) * 0.5));
  return (
    <AbsoluteFill
      style={{
        color: c.fg,
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {logo ? (
        <RemocnLogo
          fontSize={Math.min(168 * u, (0.56 * W) / 3.9)}
          color={c.fg}
        />
      ) : (
        <div
          style={{
            fontFamily: display,
            fontWeight: 500,
            fontSize: size,
            letterSpacing: "-0.04em",
            lineHeight: 1,
            whiteSpace: "nowrap",
            paddingBottom: size * 0.08,
            paddingRight: size * 0.04,
          }}
        >
          {body}
          {dot ? <span style={{ color: accent }}>.</span> : null}
        </div>
      )}
    </AbsoluteFill>
  );
}

function Scene({
  content,
  tone,
  accent,
  mark,
  ground,
}: {
  content: React.ReactNode;
  tone: Tone;
  accent: string;
  mark: boolean;
  ground?: string;
}) {
  const text = typeof content === "string" || typeof content === "number";
  return (
    <AbsoluteFill
      style={{ backgroundColor: TONES[tone].bg, backgroundImage: ground }}
    >
      {text ? (
        <Headline
          text={String(content)}
          tone={tone}
          accent={accent}
          mark={mark}
        />
      ) : (
        content
      )}
    </AbsoluteFill>
  );
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export interface BandShiftProps {
  /** Outgoing scene: a short headline string or any React node. */
  from?: React.ReactNode;
  /** Incoming scene. `"remocn"` sets the remocn.dev logo. */
  to?: React.ReactNode;
  /** Number of horizontal bands, 5–7. */
  bands?: number;
  /** Override the colour blocks riding between the scenes (default: a mesh gradient field). */
  colors?: string[];
  /** Frames the outgoing scene holds before the shift. */
  delay?: number;
  /** Frames between neighbouring bands. */
  stagger?: number;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  /** `dark` lands on a dark scene, `light` on a light one. */
  theme?: Tone;
}

const TRAVEL = 22;
const EASE_SHIFT = Easing.bezier(0.78, 0, 0.18, 1.045);
const BLOCKS = [0.2, 0.3, 0.16, 0.26, 0.34, 0.18, 0.24];
const STAGE = "#0A0A0B";

export function BandShift({
  from = "Before.",
  to = "remocn",
  bands = 6,
  colors,
  delay = 18,
  stagger = 3,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: BandShiftProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const n = Math.round(Math.min(7, Math.max(5, bands)));
  const toneB: Tone = theme;
  const toneA: Tone = theme === "dark" ? "light" : "dark";
  const fills = colors?.length ? colors : null;
  const drift = Math.min(1, t / 150);
  const field = meshField(drift * 0.18);
  const ground = meshGround(toneB, drift * 0.12);
  const bandH = H / n;
  const lastEnd = delay + (n - 1) * stagger + TRAVEL;

  return (
    <AbsoluteFill style={{ background: STAGE, overflow: "hidden" }}>
      {Array.from({ length: n }, (_, i) => {
        const start = delay + i * stagger;
        const p = interpolate(t, [start, start + TRAVEL], [0, 1], CLAMP);
        const e = EASE_SHIFT(p);
        const d = i % 2 === 0 ? 1 : -1;
        const S = BLOCKS[i % BLOCKS.length] * W;
        const offset = d * e * (W + S);
        const xA = offset;
        const xS = d > 0 ? offset - S : offset + W;
        const xB = d > 0 ? offset - S - W : offset + W + S;
        const moving = t > start && t < lastEnd;
        const gap = moving
          ? 3 * u * Math.sin(Math.PI * Math.min(1, p * 1.15))
          : 0;
        const top = i * bandH;
        const y0 = top + (i > 0 ? gap / 2 : 0);
        const y1 = top + bandH - (i < n - 1 ? gap / 2 : 0);
        const idle = p <= 0;
        const landed = p >= 1;
        const fill = fills ? fills[i % fills.length] : null;
        const inView = (x: number, w: number) => x < W && x + w > 0;
        return (
          <div
            key={`band-${top}`}
            style={{
              position: "absolute",
              left: 0,
              top: y0,
              width: W,
              height: y1 - y0,
              overflow: "hidden",
              background: landed || !idle ? TONES[toneB].bg : TONES[toneA].bg,
            }}
          >
            {landed || !inView(xA, W) ? null : (
              <div
                style={{
                  position: "absolute",
                  left: xA,
                  top: -y0,
                  width: W,
                  height: H,
                }}
              >
                <Scene
                  content={from}
                  tone={toneA}
                  accent={accent}
                  mark={false}
                />
              </div>
            )}
            {idle || landed || !inView(xS, S) ? null : (
              <div
                style={{
                  position: "absolute",
                  left: xS,
                  top: 0,
                  width: S,
                  height: "100%",
                  ...(fill
                    ? { background: fill }
                    : {
                        backgroundImage: field,
                        backgroundSize: `${W}px ${H}px`,
                        backgroundPosition: `${(-xS).toFixed(2)}px ${(-y0).toFixed(2)}px`,
                      }),
                }}
              />
            )}
            {idle || !inView(xB, W) ? null : (
              <div
                style={{
                  position: "absolute",
                  left: landed ? 0 : xB,
                  top: -y0,
                  width: W,
                  height: H,
                }}
              >
                <Scene
                  content={to}
                  tone={toneB}
                  accent={accent}
                  mark
                  ground={ground}
                />
              </div>
            )}
          </div>
        );
      })}
      <Grain opacity={theme === "light" ? 0.035 : 0.05} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import type React from "react";
import { useId, useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface BaselineDropProps {
  text?: string;
  words?: string[];
  stagger?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

/** Schibsted Grotesk 500 advance widths (per 1000 em) for ASCII 32–126. */
const SCHIBSTED_500 = [
  242, 251, 366, 672, 574, 867, 688, 205, 319, 319, 433, 635, 272, 481, 287,
  454, 617, 360, 579, 583, 596, 590, 601, 541, 588, 600, 287, 276, 635, 635,
  635, 539, 895, 710, 654, 707, 708, 591, 567, 721, 729, 373, 550, 678, 555,
  886, 739, 769, 630, 769, 648, 623, 656, 685, 688, 955, 675, 633, 606, 324,
  454, 324, 635, 500, 500, 563, 600, 560, 600, 580, 349, 562, 577, 253, 280,
  567, 271, 883, 591, 601, 600, 600, 417, 521, 351, 591, 567, 830, 572, 564,
  515, 336, 249, 336, 635,
];
const TRACK = -0.03;
const SPACE = 0.24;
const BASELINE = 0.8594;
const CAP = 0.703;

const DRAW = [4, 28] as const;
const FIRST_LAND = 30;
const FALL = 15;
const RETRACT_AFTER = 20;
const RETRACT_LEN = 22;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_FALL = Easing.bezier(0.5, 0, 0.9, 0.5);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  // gradients.sh "aurora": the ground under the baseline glows as words land.
  dark: {
    bg: "#03050B",
    fg: "#F2F4F1",
    line: "rgba(242,244,241,0.66)",
    grain: 0.07,
    glow: ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"],
    glowMix: 62,
    bandMix: 34,
  },
  // gradients.sh "ribbon" (light): the same ground in pink, orange, gold and violet.
  light: {
    bg: "#F6F4F0",
    fg: "#121214",
    line: "rgba(18,18,20,0.55)",
    grain: 0.045,
    glow: ["#FF8A3D", "#FF3D9A", "#7A5CFF", "#FFC83D"],
    glowMix: 34,
    bandMix: 22,
  },
} as const;

function auroraGround(
  colors: readonly string[],
  mix: number,
  band: number,
  drift: number,
) {
  const n = colors.length;
  const blobs = colors.map((col, i) => {
    const x = 15 + (70 * i) / (n - 1) + Math.sin(drift * 2.4 + i * 1.9) * 3;
    const y = 4 + Math.cos(drift * 2 + i * 1.3) * 3;
    return `radial-gradient(30% 62% at ${x.toFixed(2)}% ${y.toFixed(2)}%, color-mix(in oklab, ${col} ${mix}%, transparent) 0%, transparent 70%)`;
  });
  return [
    ...blobs,
    `linear-gradient(180deg, color-mix(in oklab, ${colors[0]} ${band}%, transparent) 0%, transparent 46%)`,
  ].join(", ");
}

function em(text: string) {
  let w = 0;
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    w += (code >= 32 && code < 127 ? SCHIBSTED_500[code - 32] : 600) / 1000;
    w += TRACK;
  }
  return w;
}

function landing(tau: number, amp: number) {
  if (tau <= 0) return 0;
  const omega = (2 * Math.PI) / 13;
  return amp * Math.exp(-tau * 0.26) * Math.sin(omega * tau);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function BaselineDrop({
  text = "Ship the story.",
  words: wordsProp,
  stagger = 11,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: BaselineDropProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];

  const words = useMemo(
    () => wordsProp ?? text.trim().split(/\s+/),
    [wordsProp, text],
  );
  const total = useMemo(
    () => words.reduce((s, w) => s + em(w), 0) + SPACE * (words.length - 1),
    [words],
  );
  const F = Math.min(H * 0.2, (W * 0.78) / total);
  const baseY = H / 2 + (CAP * F) / 2;
  const rowTop = baseY - BASELINE * F;
  const line = Math.max(1, (H / 720) * 1.5);
  const margin = W * 0.08;

  const land = (k: number) => FIRST_LAND + k * stagger;
  const lastLand = land(words.length - 1);
  const retractStart = lastLand + RETRACT_AFTER;

  const drawn = interpolate(t, DRAW, [0, 1], { ...CLAMP, easing: EASE_IO });
  const retracted = interpolate(
    t,
    [retractStart, retractStart + RETRACT_LEN],
    [0, 1],
    { ...CLAMP, easing: EASE_IO },
  );
  const push = interpolate(t, [0, retractStart + 60], [0, 1], CLAMP);

  const dropOf = (k: number) => {
    const tau = t - land(k);
    if (tau >= 0) return { y: landing(tau, F * 0.04), seen: true };
    const p = interpolate(t, [land(k) - FALL, land(k)], [0, 1], {
      ...CLAMP,
      easing: EASE_FALL,
    });
    const fallFrom = rowTop + F * 1.4;
    return { y: -fallFrom * (1 - p), seen: t > land(k) - FALL };
  };

  const landed = words.reduce(
    (sum, _, k) =>
      sum + interpolate(t, [land(k) - 2, land(k) + 10], [0, 1], CLAMP),
    0,
  );
  const glowLevel = 0.3 + (0.7 * landed) / Math.max(1, words.length);
  const ground = auroraGround(
    c.glow,
    c.glowMix,
    c.bandMix,
    interpolate(t, [0, retractStart + 60], [0, 1], CLAMP),
  );

  const contact = (k: number) =>
    interpolate(t - land(k), [0, 2, 24], [0, 1, 0], CLAMP);

  const row = (children: (w: string, k: number) => React.ReactNode) => (
    <div
      style={{
        position: "absolute",
        left: 0,
        width: W,
        top: rowTop,
        display: "flex",
        justifyContent: "center",
        gap: SPACE * F,
        whiteSpace: "pre",
        fontFamily: sans,
        fontWeight: 500,
        fontSize: F,
        lineHeight: 1,
        letterSpacing: `${TRACK}em`,
      }}
    >
      {words.map((w, k) => children(w, k))}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `scale(${1 + push * 0.02})`,
          transformOrigin: `50% ${(baseY / H) * 100}%`,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: baseY + line,
            bottom: -H * 0.05,
            background: ground,
            opacity: glowLevel * drawn,
            maskImage: `linear-gradient(90deg, transparent ${(1 - drawn) * 40}%, black ${8 + (1 - drawn) * 40}%, black ${92 - (1 - drawn) * 40}%, transparent ${100 - (1 - drawn) * 40}%)`,
            WebkitMaskImage: `linear-gradient(90deg, transparent ${(1 - drawn) * 40}%, black ${8 + (1 - drawn) * 40}%, black ${92 - (1 - drawn) * 40}%, transparent ${100 - (1 - drawn) * 40}%)`,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: margin,
            width: W - margin * 2,
            top: baseY,
            height: line,
            background: c.line,
            clipPath: `inset(0 ${(1 - drawn) * 100}% 0 ${retracted * 100}%)`,
          }}
        />
        {row((w, k) => (
          <span
            key={`c${k}`}
            style={{
              position: "relative",
              display: "inline-block",
              color: "transparent",
            }}
          >
            {w}
            <span
              style={{
                position: "absolute",
                left: -F * 0.04,
                right: -F * 0.04,
                top: BASELINE * F,
                height: line * 2.5,
                background: accent,
                opacity: contact(k) * (1 - retracted),
                transform: `scaleX(${0.6 + 0.4 * contact(k) ** 0.5})`,
              }}
            />
          </span>
        ))}
        {row((w, k) => {
          const { y, seen } = dropOf(k);
          return (
            <span
              key={`w${k}`}
              style={{
                display: "inline-block",
                color: c.fg,
                opacity: seen ? 1 : 0,
                transform: `translateY(${y}px)`,
              }}
            >
              {w}
            </span>
          );
        })}
      </AbsoluteFill>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: serif } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface BassDropProps {
  /** Small, widely tracked line that breathes in during the build. */
  build?: string;
  /**
   * A word that lands on the hit instead of the logo. Short, best in
   * capitals. Leave it out and the remocn logo slams in.
   */
  title?: string;
  /** Line that cuts in under the title once it holds. Defaults to `build`; pass "" to hide. */
  line?: string;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Beat sheet (30fps, speed 1):
//  0–66    the build: the small line breathes in, its tracking drifting open
//          faster and faster like a riser; an accent hairline grows under it
//  66–72   hard cut to black: seven frames of silence
//  73      one flash frame of light
//  74–76   the hit: the title cuts in at full size, 1.06 → 1 in two frames
//  76–end  the title holds on a slow push; the line cuts back in under it at
//          96 at the tracking the build ended on; poster hold
