interface Spec {
  size: number;
  weight: number;
  tracking: string;
  style: React.CSSProperties;
}

function layoutSpec(
  layout: BlinkLayout,
  text: string,
  W: number,
  H: number,
): Spec {
  const fit = (target: number, maxWidth: number) =>
    Math.min(target, maxWidth / Math.max(1, text.length * ADVANCE));
  const pad = H * 0.075;
  switch (layout) {
    case "giant":
      return {
        size: fit(H * 0.56, W * 0.86),
        weight: 500,
        tracking: "-0.04em",
        style: { left: 0, right: 0, top: "50%", textAlign: "center" },
      };
    case "center":
      return {
        size: fit(H * 0.17, W * 0.7),
        weight: 500,
        tracking: "-0.03em",
        style: { left: 0, right: 0, top: "50%", textAlign: "center" },
      };
    case "dot":
      return {
        size: H * 0.036,
        weight: 400,
        tracking: "-0.01em",
        style: { left: 0, right: 0, top: "50%", textAlign: "center" },
      };
    case "corner":
      return {
        size: H * 0.042,
        weight: 400,
        tracking: "-0.01em",
        style: { left: pad * 1.2, bottom: pad },
      };
    case "top-left":
      return {
        size: fit(H * 0.26, W * 0.6),
        weight: 500,
        tracking: "-0.035em",
        style: { left: pad * 1.1, top: pad * 0.7 },
      };
    case "low-right":
      return {
        size: fit(H * 0.13, W * 0.5),
        weight: 500,
        tracking: "-0.03em",
        style: { right: pad * 1.2, bottom: pad * 0.9, textAlign: "right" },
      };
    case "crop-right":
      return {
        size: H * 0.98,
        weight: 500,
        tracking: "-0.04em",
        style: { left: W * 0.36, top: "54%" },
      };
    case "crop-left":
      return {
        size: H * 0.98,
        weight: 500,
        tracking: "-0.04em",
        style: { right: W * 0.38, top: "46%", textAlign: "right" },
      };
    case "crop-bottom":
      return {
        size: fit(H * 1.05, W * 0.94),
        weight: 500,
        tracking: "-0.04em",
        style: { left: 0, right: 0, top: H * 0.3, textAlign: "center" },
      };
  }
}

const CENTERED: BlinkLayout[] = [
  "giant",
  "center",
  "dot",
  "crop-right",
  "crop-left",
];

export function BlinkCut({
  words = DEFAULT_WORDS,
  framesPerWord = 6,
  brand = "remocn",
  line = "Launch films, built in Remotion.",
  logo,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: BlinkCutProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const beat = Math.max(1, Math.round(framesPerWord));

  const cuts = words.map((w, i) => {
    const word = typeof w === "string" ? { text: w } : w;
    return {
      text: word.text,
      layout: word.layout ?? LAYOUT_CYCLE[i % LAYOUT_CYCLE.length],
      ground: word.ground ?? GROUND_CYCLE[i % GROUND_CYCLE.length],
      length: beat * Math.max(1, Math.round(word.beats ?? 1)),
    };
  });

  let start = 0;
  let active = -1;
  let local = 0;
  let activeLength = beat;
  for (let i = 0; i < cuts.length; i++) {
    if (frame >= start && frame < start + cuts[i].length) {
      active = i;
      local = frame - start;
      activeLength = cuts[i].length;
    }
    start += cuts[i].length;
  }
  const lockupStart = start;
  let background: string = c.bg;
  let content: React.ReactNode = null;

  const dark = theme === "dark";

  if (active === -1) {
    const t = Math.max(0, frame - lockupStart);
    const lineIn = interpolate(t, [6, 18], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    // The beam glow rises a touch under the lockup and keeps drifting.
    const rise =
      6 -
      interpolate(t, [0, 24], [0, 6], {
        ...CLAMP,
        easing: EASE_OUT,
      }) -
      t * 0.04;
    const [c0, c1, , c3] = BEAM.colors;
    const c2 = accent;
    const ground = dark
      ? [
          `radial-gradient(64% 44% at 50% ${104 + rise}%, color-mix(in oklab, ${c0} 50%, transparent) 0%, color-mix(in oklab, ${c1} 55%, transparent) 22%, color-mix(in oklab, ${c2} 50%, transparent) 50%, transparent 78%)`,
          `radial-gradient(120% 70% at 50% ${118 + rise}%, color-mix(in oklab, ${c3} 95%, transparent) 0%, transparent 72%)`,
          `linear-gradient(180deg, ${c.bg} 0%, ${BEAM.bg} 100%)`,
        ].join(", ")
      : [
          `radial-gradient(64% 46% at 50% ${100 + rise}%, color-mix(in oklab, ${c2} 70%, transparent) 0%, color-mix(in oklab, ${c1} 55%, transparent) 30%, color-mix(in oklab, ${c0} 40%, transparent) 56%, transparent 80%)`,
          `linear-gradient(${c.bg}, ${c.bg})`,
        ].join(", ");
    const isRemocn = !logo && brand.toLowerCase() === "remocn";
    background = ground;
    content = (
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: H * 0.045,
          }}
        >
          {isRemocn ? (
            <RemocnLogo fontSize={H * 0.17} color={c.fg} />
          ) : (
            <div
              style={{ display: "flex", alignItems: "center", gap: H * 0.022 }}
            >
              {logo}
              <div
                style={{
                  fontFamily: display,
                  fontWeight: 500,
                  fontSize: H * 0.135,
                  letterSpacing: "-0.035em",
                  lineHeight: 1,
                  color: c.fg,
                }}
              >
                {brand}
              </div>
            </div>
          )}
          {line ? (
            <div
              style={{
                fontFamily: display,
                fontWeight: 400,
                fontSize: H * 0.036,
                letterSpacing: "-0.01em",
                color: c.muted,
                opacity: lineIn,
                transform: `translateY(${(1 - lineIn) * H * 0.012}px)`,
              }}
            >
              {line}
            </div>
          ) : null}
        </div>
      </AbsoluteFill>
    );
  } else {
    const cut = cuts[active];
    const isAccent = cut.ground === "accent";
    const p = local / activeLength;
    background =
      isAccent && dark
        ? beamGround(active, p, accent)
        : cut.ground === "invert"
          ? c.fg
          : c.bg;
    const ink: React.CSSProperties =
      isAccent && !dark
        ? {
            backgroundImage: beamInk(active, p, accent),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
          }
        : {
            color:
              cut.ground === "invert" ? c.bg : isAccent ? BEAM.colors[0] : c.fg,
          };
    const spec = layoutSpec(cut.layout, cut.text, W, H);
    // A hair of drift keeps each cut alive without softening the hard edit.
    const drift = interpolate(local, [0, activeLength], [0, 1], CLAMP);
    const scale = 1 + drift * (CENTERED.includes(cut.layout) ? 0.025 : 0.015);
    const vertical =
      spec.style.top !== undefined && spec.style.bottom === undefined
        ? typeof spec.style.top === "string"
          ? "translateY(-50%)"
          : ""
        : "";
    const origin =
      cut.layout === "corner" || cut.layout === "top-left"
        ? "left center"
        : cut.layout === "low-right"
          ? "right center"
          : "center center";
    content = (
      <div
        style={{
          position: "absolute",
          ...spec.style,
          fontFamily: display,
          fontWeight: spec.weight,
          fontSize: spec.size,
          letterSpacing: spec.tracking,
          lineHeight: 0.9,
          ...ink,
          whiteSpace: "nowrap",
          transform: `${vertical} scale(${scale})`,
          transformOrigin: origin,
        }}
      >
        {cut.text}
      </div>
    );
  }

  return (
    <AbsoluteFill style={{ background, overflow: "hidden" }}>
      {content}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

export interface BlockCityProps {
  /** Hero number, counted up on the accent block. */
  value?: number;
  prefix?: string;
  suffix?: string;
  /** Muted word after the number. */
  caption?: string;
  /** Optional dataset: one value per column, left to right (any scale). */
  data?: number[];
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const RISE = Easing.bezier(0.3, 1.18, 0.5, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const COLS = 20;
const ROWS = 12;
const CELL = 52;
const FOOT = 37;

// camera keyframes: [frame, pitch°, yaw°, camX, camY, dolly, lens] (lengths in u).
// Fly low along the columns on a wide lens, then crane up and orbit to a long-lens
// front view where the skyline reads as a bar chart.
const CAM: [number, number, number, number, number, number, number][] = [
  [0, 76, -90, -150, 20, 260, 760],
  [112, 70, -76, 200, 60, -140, 900],
  [140, 69, -72, 220, 50, -170, 940],
  [210, 52, -20, 20, -110, -300, 1300],
];

const T_HERO = 112;
const T_LABEL = 178;

// gradients.sh "fluted" palette: bg #050507, [#1d2a8f, #2f7bff, #ff7a3d, #ffe2c4].
// It runs up the hero tower (deep blue at the street, warm at the roof) and tints the sky.
const FLUTED: RGB[] = [
  [29, 42, 143],
  [47, 123, 255],
  [255, 122, 61],
  [255, 226, 196],
];

const PALETTES = {
  dark: {
    bg: [6, 6, 9],
    haze: [22, 23, 30],
    top: [92, 92, 98],
    side: [38, 38, 43],
    ground: "#0E0E10",
    line: "rgba(255,255,255,0.05)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    lead: "rgba(255,255,255,0.35)",
    sky: "rgba(47,123,255,0.10)",
    dusk: "rgba(29,42,143,0.32)",
    ring: "rgba(6,6,9,0.9)",
    spill: 0.2,
    grain: 0.06,
  },
  light: {
    bg: [245, 244, 240],
    haze: [240, 238, 233],
    top: [255, 255, 253],
    side: [228, 224, 216],
    ground: "#EEECE6",
    line: "rgba(18,18,20,0.06)",
    fg: "#121214",
    muted: "#6E6C67",
    lead: "rgba(18,18,20,0.3)",
    sky: "rgba(255,255,255,0.9)",
    dusk: "rgba(255,226,196,0.55)",
    ring: "rgba(245,244,240,0.9)",
    spill: 0.12,
    grain: 0.04,
  },
} as const;

type Palette = (typeof PALETTES)[keyof typeof PALETTES];
type RGB = readonly number[];

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

const mix = (a: RGB, b: RGB, k: number): RGB => [
  a[0] + (b[0] - a[0]) * k,
  a[1] + (b[1] - a[1]) * k,
  a[2] + (b[2] - a[2]) * k,
];
const shade = (c: RGB, k: number): RGB => [c[0] * k, c[1] * k, c[2] * k];
const css = (c: RGB) =>
  `rgb(${Math.round(c[0])},${Math.round(c[1])},${Math.round(c[2])})`;

/** Deterministic dataset: a rising trend across columns, a ripple across rows. */
function heightAt(c: number, r: number, data?: number[]) {
  const trend = data?.length
    ? (() => {
        const max = Math.max(...data);
        const v = data[Math.round((c / (COLS - 1)) * (data.length - 1))];
        return max > 0 ? v / max : 0;
      })()
    : 0.22 + 0.78 * (c / (COLS - 1)) ** 1.7;
  const ripple = 0.66 + 0.34 * Math.sin(r * 0.85 + c * 0.45);
  const noise = 0.85 + hash(c * 31 + r * 7) * 0.3;
  return 12 + 190 * trend * ripple * noise;
}

function camAt(t: number) {
  let i = 0;
  while (i < CAM.length - 2 && t > CAM[i + 1][0]) i++;
  const a = CAM[i];
  const b = CAM[i + 1];
  const k = interpolate(t, [a[0], b[0]], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const v = a.map((x, j) => x + (b[j] - x) * k);
  return {
    pitch: v[1],
    yaw: v[2],
    camX: v[3],
    camY: v[4],
    dolly: v[5],
    lens: v[6],
  };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={31}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const face: React.CSSProperties = {
  position: "absolute",
  left: 0,
  top: 0,
  transformOrigin: "0 0",
};

export function BlockCity({
  value = 340,
  prefix = "+",
  suffix = "%",
  caption = "renders",
  data,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: BlockCityProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const pal: Palette = PALETTES[theme];

  const cam = camAt(t);
  const persp = cam.lens * u;
  const rad = Math.PI / 180;
  const cp = Math.cos(cam.pitch * rad);
  const sp = Math.sin(cam.pitch * rad);
  const cyw = Math.cos(cam.yaw * rad);
  const syw = Math.sin(cam.yaw * rad);

  // the same transform chain as the CSS camera, for fog and the 2D label
  const project = (x: number, y: number, z: number) => {
    const px = x - cam.camX * u;
    const py = y - cam.camY * u;
    const rx = px * cyw - py * syw;
    const ry = px * syw + py * cyw;
    const y2 = ry * cp - z * sp;
    const z2 = ry * sp + z * cp + cam.dolly * u;
    const s = persp / (persp - z2);
    return { x: width / 2 + rx * s, y: height / 2 + y2 * s, z: z2 };
  };

  const heroC = COLS - 3;
  const heroR = ROWS - 3;
  const tallest = Math.max(
    ...Array.from({ length: COLS * ROWS }, (_, n) =>
      heightAt(n % COLS, Math.floor(n / COLS), data),
    ),
  );
  const heroH = tallest * 1.95 * u;

  // the rise wave travels from the near rows to the far rows with the camera
  const wave = interpolate(t, [0, 112], [5, COLS + 3], CLAMP);
  const heroP = interpolate(t, [T_HERO, T_HERO + 26], [0, 1], {
    ...CLAMP,
    easing: RISE,
  });
  const heroTint = interpolate(t, [T_HERO - 4, T_HERO + 12], [0, 1], CLAMP);

  const blocks: React.ReactNode[] = [];
  const s = FOOT * u;
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const bx = (c - (COLS - 1) / 2) * CELL * u;
      const by = (r - (ROWS - 1) / 2) * CELL * u;
      const target = heightAt(c, r, data) * u;
      const lead = (wave - c + 2.6 - hash(c * 5 + r * 3) * 0.9) / 2.6;
      const rise = RISE(Math.max(0, Math.min(1, lead)));
      const isHero = c === heroC && r === heroR;
      let h = Math.max(2 * u, target * rise);
      if (isHero) h = h + (heroH - target) * heroP;

      // fog by distance past the point the camera looks at; cull what is behind the lens
      const pc = project(bx, by, h * 0.5);
      if (pc.z > persp * 0.86 || pc.y > height * 2) continue;
      const beyond = persp - pc.z - (persp - cam.dolly * u);
      const fog = interpolate(beyond, [-200 * u, 950 * u], [0, 0.88], CLAMP);
      // the hero tower throws warm light on its neighbours
      const near = (c - heroC) ** 2 + (r - heroR) ** 2;
      const spill = isHero ? 0 : heroTint * pal.spill * Math.exp(-near / 5);
      const baseTop: RGB = isHero
        ? mix(pal.top, FLUTED[3], heroTint)
        : mix(pal.top, FLUTED[2], spill);
      const baseSide: RGB = mix(pal.side, FLUTED[2], spill * 0.8);
      const bg = pal.haze;
      const top = css(mix(baseTop, bg, fog));
      const sideLit = mix(shade(baseSide, 1.08), bg, fog);
      const sideFront = mix(shade(baseSide, 0.9), bg, fog);
      const sideDark = mix(shade(baseSide, 0.72), bg, fog);
      // hero: the fluted gradient runs from the street (top of the face div) to the roof
      const heroFace = (k: number) => {
        const stops = FLUTED.map((c) =>
          css(mix(mix(shade(pal.side, k), shade(c, k), heroTint), bg, fog)),
        );
        return `linear-gradient(180deg, ${stops[0]} 0%, ${stops[1]} 38%, ${stops[2]} 78%, ${stops[3]} 100%)`;
      };
      const ao = (c3: RGB) =>
        `linear-gradient(180deg, ${css(mix(shade(c3, 0.72), bg, fog * 0.6))} 0%, ${css(c3)} ${Math.min(100, (40 * u * 100) / Math.max(h, 1))}%, ${css(c3)} 100%)`;

      blocks.push(
        <div
          key={`${c}-${r}`}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transformStyle: "preserve-3d",
            transform: `translate3d(${bx}px, ${by}px, 0px)`,
          }}
        >
          {/* left (-x) */}
          <div
            style={{
              ...face,
              width: s,
              height: h,
              background: isHero ? heroFace(1.04) : ao(sideLit),
              transform: `translate3d(${-s / 2}px, ${-s / 2}px, 0px) rotateZ(90deg) rotateX(90deg)`,
            }}
          />
          {/* right (+x) */}
          <div
            style={{
              ...face,
              width: s,
              height: h,
              background: isHero ? heroFace(0.7) : ao(sideDark),
              transform: `translate3d(${s / 2}px, ${-s / 2}px, 0px) rotateZ(90deg) rotateX(90deg)`,
            }}
          />
          {/* front (+y) */}
          <div
            style={{
              ...face,
              width: s,
              height: h,
              background: isHero ? heroFace(0.88) : ao(sideFront),
              transform: `translate3d(${-s / 2}px, ${s / 2}px, 0px) rotateX(90deg)`,
            }}
          />
          {/* top */}
          <div
            style={{
              ...face,
              width: s,
              height: s,
              background: top,
              boxShadow: `inset 0 0 0 ${Math.max(0.6, 0.8 * u)}px ${css(mix(shade(baseTop, theme === "dark" ? 1.25 : 0.97), bg, fog))}`,
              transform: `translate3d(${-s / 2}px, ${-s / 2}px, ${h}px)`,
            }}
          />
        </div>,
      );
    }
  }

  const groundW = (COLS + 8) * CELL * u;
  const groundH = (ROWS + 8) * CELL * u;

  // hero label, placed in 2D from the projected roof of the hero block
  const heroX = (heroC - (COLS - 1) / 2) * CELL * u;
  const heroY = (heroR - (ROWS - 1) / 2) * CELL * u;
  const heroBase = heightAt(heroC, heroR, data) * u;
  const roof = project(heroX, heroY, heroBase + (heroH - heroBase) * heroP);
  const labelP = interpolate(t, [T_LABEL, T_LABEL + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [T_LABEL, T_LABEL + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const shown = Math.round(value * count);
  const leadLen = 40 * u;

  const fogTop = interpolate(cam.pitch, [54, 72], [0.18, 0.42]);

  return (
    <AbsoluteFill style={{ background: css(pal.bg), overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 60% at 50% 18%, ${pal.sky}, transparent 70%), radial-gradient(ellipse 110% 46% at ${50 + Math.sin(t / 60) * 3}% 0%, ${pal.dusk}, transparent 72%)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          perspective: persp,
          perspectiveOrigin: "50% 50%",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: width / 2,
            top: height / 2,
            width: 0,
            height: 0,
            transformStyle: "preserve-3d",
            transform: `translateZ(${cam.dolly * u}px) rotateX(${cam.pitch}deg) rotateZ(${cam.yaw}deg) translate3d(${-cam.camX * u}px, ${-cam.camY * u}px, 0px)`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: -groundW / 2,
              top: -groundH / 2,
              width: groundW,
              height: groundH,
              background: `repeating-linear-gradient(90deg, ${pal.line} 0 ${Math.max(1, u)}px, transparent ${Math.max(1, u)}px ${CELL * u}px), repeating-linear-gradient(0deg, ${pal.line} 0 ${Math.max(1, u)}px, transparent ${Math.max(1, u)}px ${CELL * u}px), radial-gradient(closest-side, ${pal.ground}, ${css(pal.bg)})`,
              backgroundPosition: `${(CELL / 2 + 4) * u}px ${(CELL / 2 + 4) * u}px, ${(CELL / 2 + 4) * u}px ${(CELL / 2 + 4) * u}px, 0 0`,
              transform: "translateZ(-1px)",
            }}
          />
          {blocks}
        </div>
      </div>

      {/* atmospheric haze toward the horizon */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(180deg, ${css(pal.bg)} 0%, rgba(${pal.haze.join(",")},${fogTop}) 24%, rgba(${pal.haze.join(",")},0) 50%)`,
        }}
      />

      {/* hero label: a roof marker, a short leader, the number to its left */}
      <div
        style={{
          position: "absolute",
          left: roof.x,
          top: roof.y,
          width: 0,
          height: 0,
          opacity: labelP,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: -3.5 * u,
            top: -3.5 * u,
            width: 7 * u,
            height: 7 * u,
            borderRadius: "50%",
            background: accent,
            boxShadow: `0 0 0 ${2 * u}px ${pal.ring}`,
          }}
        />
        <div
          style={{
            position: "absolute",
            right: 10 * u,
            top: -0.5 * u,
            width: leadLen,
            height: Math.max(1, u),
            background: pal.lead,
            transformOrigin: "100% 50%",
            transform: `scaleX(${labelP})`,
          }}
        />
        <div
          style={{
            position: "absolute",
            right: leadLen + 22 * u,
            top: -30 * u,
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-end",
            gap: 6 * u,
            whiteSpace: "nowrap",
            transform: `translateX(${(1 - labelP) * 14 * u}px)`,
          }}
        >
          <span
            style={{
              fontFamily: sora,
              fontWeight: 400,
              fontSize: 60 * u,
              letterSpacing: "-0.045em",
              lineHeight: 1,
              color: pal.fg,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {prefix}
            {shown}
            {suffix}
          </span>
          <span
            style={{
              fontFamily: sora,
              fontWeight: 300,
              fontSize: 18 * u,
              letterSpacing: "0.01em",
              color: pal.muted,
            }}
          >
            {caption}
          </span>
        </div>
      </div>

      <AbsoluteFill
        style={{
          background:
            theme === "dark"
              ? "radial-gradient(ellipse 80% 80% at 50% 50%, transparent 60%, rgba(0,0,0,0.45) 100%)"
              : "radial-gradient(ellipse 85% 85% at 50% 50%, transparent 65%, rgba(110,100,85,0.1) 100%)",
        }}
      />
      <Grain opacity={pal.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadSpace } from "@remotion/google-fonts/SpaceGrotesk";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const space = loadSpace("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface BlockSwapProps {
  lines?: string[];
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;

const THEMES = {
  dark: { bg: "#0A0A0B", ink: "#F4F3F0" },
  light: { bg: "#F5F4F0", ink: "#111113" },
} as const;

const TRACK = -0.03;
const LEAD = 1.12;
const BLOCK_TOP = 0.86;
const BLOCK_BOT = 0.24;
const PAD_X = 0.08;
const RADIUS = 0.2;

const STAGGER = 2;
const RUN = 10;
const MORPH = 20;
const MORPH_STAGGER = 1;
const TEXT_IN = 6;
const HOLD = 14;
const OPEN_SPAWN = 2;
const END_HOLD = 30;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_WIPE = Easing.bezier(0.45, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface Word {
  text: string;
  x: number;
  base: number;
  w: number;
  block: Rect;
}

interface Layout {
  F: number;
  heads: Word[][];
  asc: number;
  desc: number;
}

function measureLayout(lines: string[], W: number, H: number): Layout {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("block-swap: no 2d context");
  const PX = 200;
  ctx.font = `500 ${PX}px "${space.fontFamily}"`;
  const wOf = (s: string) =>
    ctx.measureText(s).width / PX + TRACK * Array.from(s).length;
  const fm = ctx.measureText("Hg");
  const asc = fm.fontBoundingBoxAscent / PX;
  const desc = fm.fontBoundingBoxDescent / PX;
  const sp = wOf(" ");

  const words = lines.map((l) => l.split(/\s+/).filter(Boolean));
  const cuts = words.map((ws) => {
    const n = ws.length;
    const tw = ws.map(wOf);
    const lw = (a: number, b: number) => {
      let s = 0;
      for (let i = a; i < b; i++) s += tw[i] + (i > a ? sp : 0);
      return s;
    };
    const options: { cut: number[]; max: number }[] = [];
    for (let L = 1; L <= Math.min(3, n); L++) {
      let best: { cut: number[]; max: number } | null = null;
      const rec = (start: number, left: number, acc: number[], mx: number) => {
        if (best && mx >= best.max) return;
        if (left === 1) {
          const m = Math.max(mx, lw(start, n));
          if (!best || m < best.max) best = { cut: [...acc], max: m };
          return;
        }
        for (let i = start + 1; i <= n - left + 1; i++)
          rec(i, left - 1, [...acc, i], Math.max(mx, lw(start, i)));
      };
      rec(0, L, [], 0);
      if (best) options.push(best);
    }
    return { tw, lw, options };
  });

  const sizeFor = (max: number, L: number) =>
    Math.min((W * 0.84) / max, (H * 0.56) / (L * LEAD), H * 0.19);
  const pick = cuts.map(({ options }) => {
    let best = options[0];
    let bestF = sizeFor(best.max, 1);
    options.forEach((o, i) => {
      const f = sizeFor(o.max, i + 1);
      if (f > bestF * 1.15) {
        best = o;
        bestF = f;
      }
    });
    return { cut: best.cut, F: bestF };
  });
  const F = Math.min(...pick.map((p) => p.F));

  const heads = words.map((ws, hi) => {
    const { tw, lw } = cuts[hi];
    const bounds = [0, ...pick[hi].cut, ws.length];
    const L = bounds.length - 1;
    const lineH = F * LEAD;
    const top = H * 0.48 - (L * lineH) / 2;
    const out: Word[] = [];
    for (let li = 0; li < L; li++) {
      const a = bounds[li];
      const b = bounds[li + 1];
      let x = W / 2 - (lw(a, b) * F) / 2;
      const base = top + li * lineH + (lineH - (asc + desc) * F) / 2 + asc * F;
      for (let i = a; i < b; i++) {
        const w = tw[i] * F;
        out.push({
          text: ws[i],
          x,
          base,
          w,
          block: {
            x: x - PAD_X * F,
            y: base - BLOCK_TOP * F,
            w: w + 2 * PAD_X * F - TRACK * F,
            h: (BLOCK_TOP + BLOCK_BOT) * F,
          },
        });
        x += w + sp * F;
      }
    }
    return out;
  });
  return { F, heads, asc, desc };
}

function useLayout(lines: string[], W: number, H: number) {
  const [layout, setLayout] = useState<Layout | null>(null);
  const [handle] = useState(() => delayRender("block-swap: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      space.waitUntilDone(),
      document.fonts.load(`500 100px "${space.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setLayout(measureLayout(lines, W, H));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [lines, W, H, handle]);
  return layout;
}

interface Swap {
  to: number;
  from: number | null;
  start: number;
  covered: number;
  morphAt: number;
  textAt: number;
  uncoverAt: number;
  end: number;
}

function plan(counts: number[]): Swap[] {
  const out: Swap[] = [];
  let at = 0;
  counts.forEach((n, i) => {
    if (i === 0) {
      const covered = OPEN_SPAWN + (n - 1) * STAGGER + RUN + 2;
      const textAt = covered;
      const uncoverAt = textAt + TEXT_IN;
      const end = uncoverAt + (n - 1) * STAGGER + RUN;
      out.push({
        to: 0,
        from: null,
        start: 0,
        covered,
        morphAt: 0,
        textAt,
        uncoverAt,
        end,
      });
      at = end + HOLD;
      return;
    }
    const m = counts[i - 1];
    const k = Math.max(m, n);
    const covered = at + (m - 1) * STAGGER + RUN;
    const morphAt = covered - 2;
    const textAt = morphAt + MORPH + (k - 1) * MORPH_STAGGER;
    const uncoverAt = textAt + TEXT_IN;
    const end = uncoverAt + (n - 1) * STAGGER + RUN;
    out.push({
      to: i,
      from: i - 1,
      start: at,
      covered,
      morphAt,
      textAt,
      uncoverAt,
      end,
    });
    at = end + HOLD;
  });
  return out;
}

export function blockSwapDuration(lines: string[] = DEFAULT_LINES) {
  const counts = lines.map((l) => l.split(/\s+/).filter(Boolean).length);
  const p = plan(counts);
  return p[p.length - 1].end + END_HOLD;
}

const DEFAULT_LINES = ["Pick the beats you need.", "Render the launch."];

const lerpRect = (a: Rect, b: Rect, k: number): Rect => ({
  x: a.x + (b.x - a.x) * k,
  y: a.y + (b.y - a.y) * k,
  w: a.w + (b.w - a.w) * k,
  h: a.h + (b.h - a.h) * k,
});

const bare = (s: string) => s.replace(/[.,!?;:…]+$/, "").toLowerCase();

export function BlockSwap({
  lines = DEFAULT_LINES,
  highlight = "launch",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: BlockSwapProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const safeLines = useMemo(
    () => (lines.length > 0 ? lines : DEFAULT_LINES),
    [lines],
  );
  const layout = useLayout(safeLines, W, H);
  const swaps = useMemo(
    () => plan(safeLines.map((l) => l.split(/\s+/).filter(Boolean).length)),
    [safeLines],
  );

  if (!layout) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const { F, heads } = layout;
  let sw = swaps[0];
  for (const s of swaps) if (t >= s.start) sw = s;
  const isLast = sw.to === heads.length - 1;
  const next = heads[sw.to];
  const prev = sw.from === null ? null : heads[sw.from];
  const k = Math.max(next.length, prev ? prev.length : 0);
  const hiIndex =
    isLast && highlight
      ? next.findIndex((w) => bare(w.text) === bare(highlight))
      : -1;

  const r = RADIUS * F;
  const drift = (t / 30) * 0.18;
  const shimmer = `linear-gradient(90deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 18%, ${accent} 30%, ${FLUTED[2]} 48%, ${FLUTED[3]} 58%, ${FLUTED[1]} 76%, ${FLUTED[0]} 100%)`;
  const pill = `linear-gradient(100deg, ${accent} 0%, ${FLUTED[1]} 45%, ${FLUTED[2]} 100%)`;

  const textStyle = {
    position: "absolute" as const,
    fontFamily: space.fontFamily,
    fontWeight: 500,
    fontSize: F,
    lineHeight: 1,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre" as const,
  };
  const baseInBox = ((1 - layout.asc - layout.desc) * F) / 2 + layout.asc * F;
  const wordAt = (w: Word, color: string, dx = 0, dy = 0) => (
    <div
      style={{
        ...textStyle,
        left: w.x - dx,
        top: w.base - baseInBox - dy,
        color,
      }}
    >
      {w.text}
    </div>
  );

  const nodes: React.ReactNode[] = [];

  if (prev) {
    prev.forEach((w, i) => {
      const done = sw.start + i * STAGGER + RUN;
      if (t < done) nodes.push(<div key={`old-${i}`}>{wordAt(w, c.ink)}</div>);
    });
  }
  next.forEach((w, i) => {
    if (i === hiIndex) return;
    const off = sw.uncoverAt + i * STAGGER;
    if (t >= off) nodes.push(<div key={`new-${i}`}>{wordAt(w, c.ink)}</div>);
  });

  for (let j = 0; j < k; j++) {
    const target = next[Math.min(j, next.length - 1)];
    const merging = j >= next.length;
    let rect: Rect;
    let fill = 0;
    let inner: { w: Word; o: number } | null = null;
    let alpha = 1;

    if (prev) {
      const source = prev[Math.min(j, prev.length - 1)];
      const splitting = j >= prev.length;
      const cv = splitting
        ? 1
        : interpolate(
            t,
            [sw.start + j * STAGGER, sw.start + j * STAGGER + RUN],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
      const sq = source.block.h;
      const coverRect: Rect = {
        ...source.block,
        w: sq + (source.block.w - sq) * cv,
      };
      const mk = interpolate(
        t,
        [
          sw.morphAt + j * MORPH_STAGGER,
          sw.morphAt + j * MORPH_STAGGER + MORPH,
        ],
        [0, 1],
        { ...CLAMP, easing: EASE_IN_OUT },
      );
      rect = lerpRect(coverRect, target.block, mk);
      if (splitting && t < sw.morphAt) alpha = 0;
      if (!splitting && t < sw.start + j * STAGGER) alpha = 0;
      if (merging && mk >= 1) alpha = 0;
      fill =
        interpolate(t, [sw.morphAt, sw.morphAt + 6], [0, 1], CLAMP) *
        (1 - interpolate(t, [sw.textAt - 2, sw.textAt + 4], [0, 1], CLAMP));
      if (!splitting && t < sw.morphAt + 4) {
        inner = {
          w: source,
          o: 1 - interpolate(t, [sw.morphAt, sw.morphAt + 4], [0, 1], CLAMP),
        };
      }
    } else {
      const at = OPEN_SPAWN + j * STAGGER;
      const run = interpolate(t, [at, at + RUN + 2], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const sq = target.block.h;
      rect = { ...target.block, w: sq + (target.block.w - sq) * run };
      alpha = interpolate(t, [at - 2, at + 2], [0, 1], CLAMP);
      fill = 1 - interpolate(t, [sw.textAt - 2, sw.textAt + 4], [0, 1], CLAMP);
    }

    if (!merging && t >= sw.textAt) {
      inner = {
        w: target,
        o: interpolate(t, [sw.textAt, sw.textAt + TEXT_IN], [0, 1], CLAMP),
      };
    }
    const keep = j === hiIndex;
    if (!merging && !keep && t >= sw.uncoverAt) {
      const off = sw.uncoverAt + j * STAGGER;
      const u = interpolate(t, [off, off + RUN], [0, 1], {
        ...CLAMP,
        easing: EASE_WIPE,
      });
      const right = target.block.x + target.block.w;
      const left = target.block.x + target.block.w * u;
      rect = { ...target.block, x: left, w: right - left };
      if (rect.w < F * 0.03) alpha = 0;
    }
    const pillOn = keep
      ? interpolate(t, [sw.uncoverAt + 2, sw.uncoverAt + 12], [0, 1], {
          ...CLAMP,
          easing: EASE_IN_OUT,
        })
      : 0;
    if (alpha <= 0.001) continue;

    nodes.push(
      <div
        key={`blk-${j}`}
        style={{
          position: "absolute",
          left: rect.x,
          top: rect.y,
          width: rect.w,
          height: rect.h,
          borderRadius: Math.min(r, rect.w / 2),
          overflow: "hidden",
          opacity: alpha,
          background: c.ink,
        }}
      >
        {fill > 0 ? (
          <div
            style={{
              position: "absolute",
              left: -rect.x,
              top: -rect.y,
              width: W * 2,
              height: H,
              backgroundImage: shimmer,
              backgroundSize: `${W}px ${H}px`,
              backgroundRepeat: "repeat-x",
              transform: `translateX(${(-((drift * W) % W)).toFixed(2)}px)`,
              opacity: fill,
            }}
          />
        ) : null}
        {pillOn > 0 ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundImage: pill,
              opacity: pillOn,
            }}
          />
        ) : null}
        {inner && inner.o > 0 ? (
          <div style={{ opacity: inner.o }}>
            {wordAt(
              inner.w,
              pillOn > 0
                ? interpolateColors(pillOn, [0, 0.3], [c.bg, "#FFFFFF"])
                : c.bg,
              rect.x,
              rect.y,
            )}
          </div>
        ) : null}
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

