export interface BracketWinProps {
  /**
   * The seven teams remocn plays through, in bracket order after remocn:
   * [QF opponent, the two teams of the other left quarterfinal, then the four
   * teams of the right half]. remocn always holds the top-left seed.
   */
  opponents?: string[];
  /** Word on the champion plate. */
  title?: string;
  /** Small line under the plate. */
  caption?: string;
  /** Round labels over the columns: quarterfinal, semifinal, final. */
  rounds?: [string, string, string];
  /** Winner ticks on the non-remocn matches. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1):
//   0–14   slots slide in from the outer edges, empty later-round slots and
//          the connector lines draw toward the centre, round labels fade up
//  20     quarterfinals resolve: scores tick in, losers dim, winners' lines
//          draw to the semifinal slots (remocn's in the gradient)
//  40     semifinals resolve the same way, winners advance into the final
//  60     the final resolves; remocn's slot flashes
//  68–82  the final node bursts: a gradient plate grows out of it with a ring,
//          the bracket sinks back, "CHAMPION" slams in with the logo
//  86–    poster hold
const ROUND_AT = [20, 40, 60] as const;
const DIM_DELAY = 4;
const LINE_LEN = 9;
const BURST_AT = 68;

const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "radial-glow": bg #020204, [#f3f1ff, #9db4ff, #5a46cb, #1d1240].
const GLOW = ["#F3F1FF", "#9DB4FF", "#5A46CB", "#1D1240"] as const;

const THEMES = {
  dark: {
    stage: "#050507",
    slot: "#141418",
    edge: "#24242A",
    line: "#2A2A31",
    ink: "#F3F2EF",
    dim: "#7C7B82",
    score: "#1D1D22",
  },
  light: {
    stage: "#F5F4F0",
    slot: "#FFFFFF",
    edge: "#E1DFD8",
    line: "#D3D1CA",
    ink: "#121214",
    dim: "#86847E",
    score: "#EFEDE7",
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A hit: up in 1 frame, eases back over `len`. */
function kick(d: number, len = 8) {
  if (d < 0) return 0;
  if (d < 1) return d;
  const k = Math.max(0, 1 - (d - 1) / len);
  return k * k;
}

// Team indices: 0 is remocn, 1–7 the opponents in bracket order.
interface Match {
  round: 0 | 1 | 2;
  a: number;
  b: number;
  win: number;
  score: [number, number];
}
const MATCHES: Match[] = [
  { round: 0, a: 0, b: 1, win: 0, score: [2, 0] },
  { round: 0, a: 2, b: 3, win: 2, score: [2, 1] },
  { round: 0, a: 4, b: 5, win: 4, score: [2, 1] },
  { round: 0, a: 6, b: 7, win: 6, score: [2, 0] },
  { round: 1, a: 0, b: 2, win: 0, score: [2, 0] },
  { round: 1, a: 4, b: 6, win: 6, score: [1, 2] },
  { round: 2, a: 0, b: 6, win: 0, score: [3, 1] },
];

interface Slot {
  x: number;
  y: number;
  team: number;
  match: number;
  side: "a" | "b";
  /** Frame the team's name appears in the slot. */
  arrive: number;
}

interface Link {
  d: string;
  len: number;
  team: number;
  at: number;
}

export function BracketWin({
  opponents = [
    "Keyframes",
    "Stock clips",
    "Agency",
    "Screen rec",
    "Slide decks",
    "Templates",
    "Freelance",
  ],
  title = "Champion",
  caption = "Playoffs 2026 · 8 teams · 0 maps dropped",
  rounds = ["Quarterfinal", "Semifinal", "Grand final"],
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: BracketWinProps) {
  const t = useCurrentFrame() * speed + 1;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const names = ["remocn", ...opponents];

  // ── Geometry ──────────────────────────────────────────────────────────────
  const slotW = 192 * u;
  const slotH = 50 * u;
  const pairGap = 6 * u;
  const finalW = 204 * u;
  const cx = W / 2;
  const cy = H / 2 + 24 * u;
  const qfX = [48 * u, W - 48 * u - slotW];
  const sfX = [qfX[0] + slotW + 52 * u, qfX[1] - 52 * u - slotW];
  const fX = cx - finalW / 2;
  const qfCy = [cy - 142 * u, cy + 142 * u];
  const pairTop = (mcy: number) => mcy - slotH - pairGap / 2;
  const pairBot = (mcy: number) => mcy + pairGap / 2;

  // Every slot in the bracket.
  const slots: Slot[] = [];
  const links: Link[] = [];
  const addPair = (m: number, x: number, mcy: number, arrive: number): void => {
    slots.push({
      x,
      y: pairTop(mcy),
      team: MATCHES[m].a,
      match: m,
      side: "a",
      arrive,
    });
    slots.push({
      x,
      y: pairBot(mcy),
      team: MATCHES[m].b,
      match: m,
      side: "b",
      arrive,
    });
  };
  const winAt = (round: number) => ROUND_AT[round] + DIM_DELAY;
  const landAt = (round: number) => winAt(round) + LINE_LEN - 1;

  addPair(0, qfX[0], qfCy[0], 0);
  addPair(1, qfX[0], qfCy[1], 0);
  addPair(2, qfX[1], qfCy[0], 0);
  addPair(3, qfX[1], qfCy[1], 0);
  addPair(4, sfX[0], cy, landAt(0));
  addPair(5, sfX[1], cy, landAt(0));
  addPair(6, fX, cy, landAt(1));

  const elbow = (x0: number, y0: number, x1: number, y1: number) => {
    const xm = (x0 + x1) / 2;
    return {
      d: `M ${x0} ${y0} H ${xm} V ${y1} H ${x1}`,
      len: Math.abs(xm - x0) + Math.abs(y1 - y0) + Math.abs(x1 - xm),
    };
  };
  const slotMid = (y: number) => y + slotH / 2;
  // Quarterfinal → semifinal, left and right.
  for (let k = 0; k < 2; k++) {
    const mL = MATCHES[k];
    const toL = elbow(
      qfX[0] + slotW,
      qfCy[k],
      sfX[0],
      slotMid(k === 0 ? pairTop(cy) : pairBot(cy)),
    );
    links.push({ ...toL, team: mL.win, at: winAt(0) });
    const mR = MATCHES[2 + k];
    const toR = elbow(
      qfX[1],
      qfCy[k],
      sfX[1] + slotW,
      slotMid(k === 0 ? pairTop(cy) : pairBot(cy)),
    );
    links.push({ ...toR, team: mR.win, at: winAt(0) });
  }
  // Semifinal → final.
  const toFL = elbow(sfX[0] + slotW, cy, fX, slotMid(pairTop(cy)));
  links.push({ ...toFL, team: MATCHES[4].win, at: winAt(1) });
  const toFR = elbow(sfX[1], cy, fX + finalW, slotMid(pairBot(cy)));
  links.push({ ...toFR, team: MATCHES[5].win, at: winAt(1) });

  // ── Global beats ──────────────────────────────────────────────────────────
  const baseDraw = OUT(ramp(t, 4, 12));
  const labelsIn = OUT(ramp(t, 6, 10));
  const burst = SLAM(ramp(t, BURST_AT, 10));
  const sinkP = OUT(ramp(t, BURST_AT, 12));
  const titleIn = SLAM(ramp(t, BURST_AT + 2, 8));
  const logoIn = OUT(ramp(t, BURST_AT + 5, 10));
  const capIn = OUT(ramp(t, BURST_AT + 12, 10));
  const push = 1 + 0.035 * INOUT(ramp(t, 0, BURST_AT + 20));
  const hit = Math.max(
    ...ROUND_AT.map((r) => kick(t - r, 7) * 0.6),
    kick(t - BURST_AT - 4, 10),
  );

  // Final champion plate: grows out of the final node.
  const plateW0 = finalW;
  const plateH0 = slotH * 2 + pairGap;
  const plateW1 = 2 * (cx - sfX[0]) + 28 * u;
  const plateH1 = 262 * u;
  const plateW = plateW0 + (plateW1 - plateW0) * burst;
  const plateH = plateH0 + (plateH1 - plateH0) * burst;
  const plateCut = 26 * u * burst;

  const sunk = 1 - 0.72 * sinkP;

  const slotEl = (s: Slot, i: number) => {
    const m = MATCHES[s.match];
    const resolveAt = ROUND_AT[m.round];
    const isFinal = m.round === 2;
    const w = isFinal ? finalW : slotW;
    const enter =
      m.round === 0
        ? SLAM(ramp(t, (i % 4) - 1, 9))
        : OUT(ramp(t, 3 + m.round * 2, 10));
    const fromLeft = s.x < cx - (isFinal ? w : 0);
    const named = t >= s.arrive;
    const nameP = s.arrive === 0 ? 1 : SLAM(ramp(t, s.arrive, 6));
    const resolved = t >= resolveAt;
    const sc = s.side === "a" ? m.score[0] : m.score[1];
    const scoreP = SLAM(ramp(t, resolveAt + (s.match % 4) * 1, 5));
    const won = m.win === s.team;
    const lost = !won;
    const dimP = lost ? OUT(ramp(t, resolveAt + DIM_DELAY, 6)) : 0;
    const isRemocn = s.team === 0;
    const lit = isRemocn && named;
    const winFlash = won ? kick(t - resolveAt - DIM_DELAY, 9) : 0;
    const hideInBurst = isFinal && t >= BURST_AT;
    if (hideInBurst) return null;
    return (
      <div
        key={`slot-${i}`}
        style={{
          position: "absolute",
          left: s.x,
          top: s.y,
          width: w,
          height: slotH,
          transform:
            m.round === 0
              ? `translateX(${(1 - enter) * (fromLeft ? -1 : 1) * (slotW + 60 * u)}px)`
              : `scale(${0.94 + 0.06 * enter})`,
          opacity:
            (m.round === 0 ? 1 : enter) *
            (1 - 0.68 * dimP) *
            (isRemocn ? 1 : sunk),
          display: "flex",
          alignItems: "stretch",
          background: lit
            ? `linear-gradient(100deg, ${GLOW[2]} 0%, #3C3AA8 60%, ${GLOW[3]} 100%)`
            : c.slot,
          boxShadow: `inset 0 0 0 ${1 * u}px ${lit ? GLOW[2] : c.edge}`,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: 4 * u,
            background: isRemocn ? GLOW[0] : accent,
            opacity: resolved && won && named ? 1 : 0,
          }}
        />
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            paddingLeft: 14 * u,
            overflow: "hidden",
          }}
        >
          {named ? (
            <div
              style={{
                transform: `translateY(${(1 - nameP) * slotH}px)`,
                display: "flex",
                alignItems: "center",
              }}
            >
              {isRemocn ? (
                <RemocnLogo fontSize={25 * u} color="#FFFFFF" />
              ) : (
                <span
                  style={{
                    fontFamily: tektur,
                    fontWeight: 500,
                    fontSize: 21 * u,
                    letterSpacing: "0.01em",
                    color: c.ink,
                    whiteSpace: "nowrap",
                  }}
                >
                  {names[s.team]}
                </span>
              )}
            </div>
          ) : (
            <div
              style={{
                width: 34 * u,
                height: 3 * u,
                background: c.line,
              }}
            />
          )}
        </div>
        <div
          style={{
            width: 40 * u,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: lit ? "rgba(255,255,255,0.12)" : c.score,
            fontFamily: tektur,
            fontWeight: 500,
            fontSize: 22 * u,
            color: lit ? "#FFFFFF" : c.ink,
            fontVariantNumeric: "tabular-nums",
            overflow: "hidden",
          }}
        >
          {resolved && named ? (
            <span
              style={{
                transform: `translateY(${(1 - scoreP) * slotH * 0.8}px)`,
              }}
            >
              {sc}
            </span>
          ) : null}
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "#FFFFFF",
            opacity: 0.55 * winFlash,
          }}
        />
      </div>
    );
  };

  const labelCols = [
    { x: qfX[0], w: slotW, text: rounds[0] },
    { x: sfX[0], w: slotW, text: rounds[1] },
    { x: fX, w: finalW, text: rounds[2] },
    { x: sfX[1], w: slotW, text: rounds[1] },
    { x: qfX[1], w: slotW, text: rounds[0] },
  ];

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${push * (1 + 0.01 * hit)})`,
          transformOrigin: `${cx}px ${cy}px`,
        }}
      >
        <div style={{ position: "absolute", inset: 0 }}>
          {/* Round labels. */}
          {labelCols.map((l, i) => (
            <div
              key={`label-${i}-${l.text}`}
              style={{
                position: "absolute",
                left: l.x,
                width: l.w,
                top: qfCy[0] - slotH - 70 * u,
                textAlign: i === 2 ? "center" : i < 2 ? "left" : "right",
                fontFamily: tektur,
                fontWeight: 400,
                fontSize: 17 * u,
                letterSpacing: "0.24em",
                textTransform: "uppercase",
                color: c.dim,
                opacity: labelsIn * sunk,
                transform: `translateY(${(1 - labelsIn) * 10 * u}px)`,
              }}
            >
              {l.text}
            </div>
          ))}

          {/* Connectors: base lines, then each winner's advance. */}
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0, opacity: sunk }}
            aria-hidden
          >
            <defs>
              <linearGradient
                id={`${id}-path`}
                gradientUnits="userSpaceOnUse"
                x1={qfX[0]}
                y1={0}
                x2={cx}
                y2={0}
              >
                <stop offset="0" stopColor={GLOW[1]} />
                <stop offset="0.55" stopColor="#7C6CF0" />
                <stop offset="1" stopColor={GLOW[0]} />
              </linearGradient>
            </defs>
            {links.map((l, i) => (
              <path
                key={`base-${i}`}
                d={l.d}
                fill="none"
                stroke={c.line}
                strokeWidth={2 * u}
                strokeDasharray={l.len}
                strokeDashoffset={l.len * (1 - baseDraw)}
              />
            ))}
            {links.map((l, i) => {
              const p = SLAM(ramp(t, l.at, LINE_LEN));
              if (p <= 0) return null;
              const mine = l.team === 0;
              return (
                <path
                  key={`win-${i}`}
                  d={l.d}
                  fill="none"
                  stroke={mine ? `url(#${id}-path)` : c.ink}
                  strokeOpacity={mine ? 1 : 0.5}
                  strokeWidth={(mine ? 4 : 2) * u}
                  strokeDasharray={l.len}
                  strokeDashoffset={l.len * (1 - p)}
                />
              );
            })}
          </svg>

          {slots.map(slotEl)}
        </div>

        {/* remocn's lit path stays on top of the sunk bracket. */}
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0, opacity: sinkP }}
          aria-hidden
        >
          {links
            .filter((l) => l.team === 0)
            .map((l, i) => (
              <path
                key={`lit-${i}`}
                d={l.d}
                fill="none"
                stroke={`url(#${id}-path)`}
                strokeWidth={4 * u}
              />
            ))}
        </svg>

        {/* Burst: two crisp rings racing out of the final node. */}
        {t >= BURST_AT
          ? [0, 4].map((delay) => {
              const p = OUT(ramp(t, BURST_AT + delay, 26));
              const r = (120 + 560 * p) * u;
              return (
                <div
                  key={`ring-${delay}`}
                  style={{
                    position: "absolute",
                    left: cx - r,
                    top: cy - r,
                    width: 2 * r,
                    height: 2 * r,
                    borderRadius: "50%",
                    boxShadow: `inset 0 0 0 ${(delay === 0 ? 4 : 2) * u}px ${delay === 0 ? GLOW[1] : GLOW[2]}`,
                    opacity: (1 - p) * (p > 0 ? 1 : 0),
                  }}
                />
              );
            })
          : null}

        {/* Champion plate. */}
        {t >= BURST_AT ? (
          <div
            style={{
              position: "absolute",
              left: cx - plateW / 2,
              top: cy - plateH / 2,
              width: plateW,
              height: plateH,
              clipPath: `polygon(${plateCut}px 0, 100% 0, 100% calc(100% - ${plateCut}px), calc(100% - ${plateCut}px) 100%, 0 100%, 0 ${plateCut}px)`,
              background: [
                `radial-gradient(70% 90% at 50% 115%, ${GLOW[1]} 0%, transparent 70%)`,
                `radial-gradient(60% 80% at 50% 0%, ${GLOW[3]} 0%, transparent 80%)`,
                `linear-gradient(180deg, ${GLOW[3]} 0%, ${GLOW[2]} 70%, #7D73E6 100%)`,
              ].join(", "),
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: 6 * u,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                opacity: logoIn,
                transform: `translateY(${(1 - logoIn) * 14 * u}px)`,
              }}
            >
              <RemocnLogo fontSize={50 * u} color="#FFFFFF" />
            </div>
            <div
              style={{
                fontFamily: tektur,
                fontWeight: 500,
                fontSize: 128 * u,
                lineHeight: 1,
                letterSpacing: "0.02em",
                textTransform: "uppercase",
                color: "#FFFFFF",
                opacity: Math.min(1, titleIn * 1.5),
                transform: `scale(${1 + 0.16 * (1 - titleIn)})`,
                whiteSpace: "nowrap",
              }}
            >
              {title}
            </div>
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: "#FFFFFF",
                opacity: 0.3 * kick(t - BURST_AT - 1, 7),
              }}
            />
          </div>
        ) : null}

        {/* Caption under the plate. */}
        {capIn > 0 ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: cy + plateH1 / 2 + 26 * u,
              textAlign: "center",
              fontFamily: tektur,
              fontWeight: 400,
              fontSize: 20 * u,
              letterSpacing: "0.22em",
              textTransform: "uppercase",
              color: c.dim,
              opacity: capIn,
              transform: `translateY(${(1 - capIn) * 10 * u}px)`,
            }}
          >
            {caption}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/SpaceGrotesk";
import { evolvePath } from "@remotion/paths";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

/** gradients.sh "aurora" palette, top to bottom of the leaf column. Light keeps the hues, deeper. */
const AURORA = {
  dark: ["#a0f0c8", "#3fb5a3", "#5147b6", "#b25c9c"],
  light: ["#3fae86", "#2a8f84", "#4a3fb0", "#a2468b"],
} as const;

function lerpHex(stops: readonly string[], k: number) {
  const x = Math.min(1, Math.max(0, k)) * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(x));
  const w = x - i;
  const ch = (h: string, o: number) => Number.parseInt(h.slice(o, o + 2), 16);
  const m = (o: number) =>
    Math.round(ch(stops[i], o) + (ch(stops[i + 1], o) - ch(stops[i], o)) * w);
  return `rgb(${m(1)}, ${m(3)}, ${m(5)})`;
}

export interface BranchTreeProps {
  depth?: number;
  branching?: number | number[];
  title?: string;
  rootLabel?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_GROW = Easing.bezier(0.45, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    node: "#8B8A90",
    hair: "rgba(255,255,255,0.3)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    node: "#8E8C86",
    hair: "rgba(18,18,20,0.32)",
    grain: 0.045,
  },
} as const;

const ROOT_IN = 4;
const EDGE = 12;
const LEAD = 2;
const SIB = 2;
const MAX_LEAVES = 96;

interface TreeNode {
  level: number;
  parent: number;
  sib: number;
  sibs: number;
  y: number;
  path: number[];
  children: number[];
  arrive: number;
  start: number;
}

function buildTree(depth: number, fan: number[]) {
  const nodes: TreeNode[] = [
    {
      level: 0,
      parent: -1,
      sib: 0,
      sibs: 1,
      y: 0,
      path: [],
      children: [],
      arrive: ROOT_IN,
      start: ROOT_IN,
    },
  ];
  let frontier = [0];
  for (let l = 1; l <= depth; l++) {
    const next: number[] = [];
    const k = fan[l - 1];
    for (const pi of frontier) {
      const parent = nodes[pi];
      for (let j = 0; j < k; j++) {
        const start = parent.arrive + LEAD + Math.abs(j - (k - 1) / 2) * SIB;
        const idx = nodes.length;
        nodes.push({
          level: l,
          parent: pi,
          sib: j,
          sibs: k,
          y: 0,
          path: [...parent.path, j],
          children: [],
          arrive: start + EDGE,
          start,
        });
        parent.children.push(idx);
        next.push(idx);
      }
    }
    frontier = next;
  }
  return { nodes, leaves: frontier };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={43}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function BranchTree({
  depth = 3,
  branching = [3, 4, 4],
  title = "variants",
  rootLabel = "1 component",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: BranchTreeProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];

  const D = Math.min(5, Math.max(1, Math.round(depth)));
  const raw = Array.isArray(branching) ? branching : [branching];
  const fan: number[] = [];
  let leafCount = 1;
  for (let l = 0; l < D; l++) {
    const want = Math.min(
      6,
      Math.max(1, Math.round(raw[Math.min(l, raw.length - 1)] ?? 2)),
    );
    const k = Math.max(1, Math.min(want, Math.floor(MAX_LEAVES / leafCount)));
    fan.push(k);
    leafCount *= k;
  }

  const { nodes, leaves } = buildTree(D, fan);

  const rootX = width * 0.19;
  const leafX = width * 0.61;
  const cy = height / 2;
  const treeH = height * 0.76;
  const xOf = (l: number) => rootX + ((leafX - rootX) * l) / D;

  let acc = 0;
  const raws: number[] = [];
  leaves.forEach((li, j) => {
    if (j > 0) {
      const a = nodes[leaves[j - 1]].path;
      const b = nodes[li].path;
      let common = 0;
      while (common < D && a[common] === b[common]) common++;
      acc += 1 + 0.9 * (D - 1 - common);
    }
    raws.push(acc);
  });
  const span = acc || 1;
  leaves.forEach((li, j) => {
    nodes[li].y =
      leaves.length > 1 ? cy - treeH / 2 + (treeH * raws[j]) / span : cy;
  });
  for (let i = nodes.length - 1; i >= 0; i--) {
    const n = nodes[i];
    if (n.children.length) {
      n.y =
        (nodes[n.children[0]].y + nodes[n.children[n.children.length - 1]].y) /
        2;
    }
  }

  const lastArrive = Math.max(...leaves.map((i) => nodes[i].arrive));
  const HIT = lastArrive + 6;

  const land = spring({
    frame: t - HIT,
    fps,
    config: { damping: 18, stiffness: 150, mass: 0.8 },
  });
  const landO = interpolate(t, [HIT, HIT + 8], [0, 1], CLAMP);
  const blur = interpolate(t, [HIT, HIT + 14], [1, 0], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [HIT, HIT + 24], [0.6, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const cap = interpolate(t, [HIT + 10, HIT + 28], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const settle = interpolate(t, [HIT - 4, HIT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rootIn = spring({
    frame: t - ROOT_IN,
    fps,
    config: { damping: 16, stiffness: 160, mass: 0.7 },
  });
  const rootLab = interpolate(t, [ROOT_IN + 2, ROOT_IN + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, 140], [0.965, 1.005], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const stage = interpolate(t, [0, 8], [0.5, 1], CLAMP);

  const stroke = Math.max(1, 1.25 * u);
  const leafR = Math.max(2.4, 3.4 * u);
  const nodeR = Math.max(2.4, 3.4 * u);
  const numSize = 200 * u;
  const aur = AURORA[theme];
  const top = cy - treeH / 2;
  const tint = (y: number) => lerpHex(aur, (y - top) / treeH);
  const gid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const drift = interpolate(t, [0, 150], [0, 1], { ...CLAMP, easing: EASE_IO });

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `scale(${push})`,
          transformOrigin: "45% 50%",
          opacity: stage,
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={`${gid}e`}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={top}
              x2={0}
              y2={top + treeH}
            >
              {aur.map((c, i) => (
                <stop key={c} offset={i / (aur.length - 1)} stopColor={c} />
              ))}
            </linearGradient>
          </defs>
          {nodes.map((n, i) => {
            if (n.parent < 0 || t < n.start) return null;
            const par = nodes[n.parent];
            const px = xOf(par.level);
            const cx = xOf(n.level);
            const mx = px + (cx - px) * 0.5;
            const d = `M${px.toFixed(2)} ${par.y.toFixed(2)} C${mx.toFixed(2)} ${par.y.toFixed(2)} ${mx.toFixed(2)} ${n.y.toFixed(2)} ${cx.toFixed(2)} ${n.y.toFixed(2)}`;
            const k = interpolate(t, [n.start, n.arrive], [0, 1], {
              ...CLAMP,
              easing: EASE_GROW,
            });
            const evo = evolvePath(k, d);
            return (
              <path
                key={`e${i}`}
                d={d}
                fill="none"
                stroke={n.level === D ? `url(#${gid}e)` : p.hair}
                strokeWidth={stroke}
                strokeLinecap="round"
                strokeDasharray={evo.strokeDasharray}
                strokeDashoffset={evo.strokeDashoffset}
                opacity={
                  n.level === D
                    ? (theme === "dark" ? 0.5 : 0.6) + 0.25 * settle
                    : 1 - 0.3 * settle
                }
              />
            );
          })}

          {nodes.map((n, i) => {
            if (n.level === 0 || t < n.arrive - 2) return null;
            const isLeaf = n.level === D;
            const s = spring({
              frame: t - n.arrive + 1,
              fps,
              config: isLeaf
                ? { damping: 11, stiffness: 220, mass: 0.6 }
                : { damping: 18, stiffness: 200, mass: 0.6 },
            });
            const o = interpolate(
              t,
              [n.arrive - 2, n.arrive + 3],
              [0, 1],
              CLAMP,
            );
            return (
              <circle
                key={`n${i}`}
                cx={xOf(n.level)}
                cy={n.y}
                r={(isLeaf ? leafR : nodeR) * (0.4 + 0.6 * s)}
                fill={isLeaf ? tint(n.y) : p.node}
                opacity={o}
              />
            );
          })}

          <circle
            cx={rootX}
            cy={nodes[0].y}
            r={14 * u * (0.7 + 0.3 * rootIn)}
            fill="none"
            stroke={accent}
            strokeWidth={stroke * 1.4}
            opacity={interpolate(t, [ROOT_IN, ROOT_IN + 6], [0, 1], CLAMP)}
          />
          <circle
            cx={rootX}
            cy={nodes[0].y}
            r={7 * u * (0.4 + 0.6 * rootIn)}
            fill={p.fg}
            opacity={interpolate(t, [ROOT_IN, ROOT_IN + 5], [0, 1], CLAMP)}
          />
        </svg>

        <div
          style={{
            position: "absolute",
            left: rootX,
            top: nodes[0].y - 34 * u,
            transform: `translate(-50%, -100%) translateY(${(1 - rootLab) * 6 * u}px)`,
            opacity: rootLab,
            fontFamily: sans,
            fontWeight: 400,
            fontSize: 21 * u,
            letterSpacing: "-0.01em",
            color: p.fg,
            whiteSpace: "nowrap",
          }}
        >
          {rootLabel}
        </div>

        <div
          style={{
            position: "absolute",
            left: leafX + 64 * u,
            top: cy,
            transform: `translateY(${-numSize * 0.6}px)`,
          }}
        >
          <div
            style={{
              fontFamily: sans,
              fontWeight: 500,
              fontSize: numSize,
              lineHeight: 0.9,
              letterSpacing: "-0.05em",
              paddingRight: 0.06 * numSize,
              backgroundImage: `linear-gradient(${172 - 10 * drift}deg, ${aur[0]} 4%, ${aur[1]} 34%, ${aur[2]} 70%, ${aur[3]} 100%)`,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
              opacity: landO,
              filter: blur > 0.01 ? `blur(${blur * 8 * u}px)` : undefined,
              transform: `translateX(${(1 - land) * -24 * u}px)`,
            }}
          >
            {Math.round(leafCount * count)}
          </div>
          <div
            style={{
              marginTop: 18 * u,
              marginLeft: 0.04 * numSize,
              opacity: cap,
              transform: `translateY(${(1 - cap) * 8 * u}px)`,
              fontFamily: sans,
              fontWeight: 400,
              fontSize: 28 * u,
              letterSpacing: "-0.015em",
              color: p.muted,
              whiteSpace: "nowrap",
            }}
          >
            {title}
          </div>
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

