"use client";

import { hash01 } from "@/lib/remocn/stop-motion";

const GRAIN_RATIO = 0.5;
const GRAIN_FREQUENCY = 0.7;
const GRAIN_OCTAVES = 3;

export type BrushPoint = { x: number; y: number };

export type BrushTaper = {
  strokeWidth: number;
  pressure?: number;
  release?: number;
};

export function brushHalfWidth(taper: BrushTaper, t: number): number {
  const pressure = taper.pressure ?? 0.2;
  const release = taper.release ?? 1;
  return (taper.strokeWidth / 2) * (pressure + (release - pressure) * t);
}

export function brushGrainScale(strokeWidth: number, grain: number): number {
  return strokeWidth * GRAIN_RATIO * grain;
}

export function brushReach(strokeWidth: number, grain: number): number {
  return strokeWidth / 2 + brushGrainScale(strokeWidth, grain) / 2;
}

export function brushFilterId(
  seed: string,
  strokeWidth: number,
  grain: number,
): string {
  return `remocn-brush-${Math.floor(hash01(`${seed}:${strokeWidth}:${grain}`) * 1e9)}`;
}

export function sampleCubic(
  from: BrushPoint,
  c1: BrushPoint,
  c2: BrushPoint,
  to: BrushPoint,
  points = 32,
): BrushPoint[] {
  const count = Math.max(2, points);
  return Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1);
    const u = 1 - t;
    const a = u * u * u;
    const b = 3 * u * u * t;
    const c = 3 * u * t * t;
    const d = t * t * t;
    return {
      x: a * from.x + b * c1.x + c * c2.x + d * to.x,
      y: a * from.y + b * c1.y + c * c2.y + d * to.y,
    };
  });
}

export function sampleLine(
  from: BrushPoint,
  to: BrushPoint,
  points = 8,
): BrushPoint[] {
  const count = Math.max(2, points);
  return Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1);
    return {
      x: from.x + (to.x - from.x) * t,
      y: from.y + (to.y - from.y) * t,
    };
  });
}

const normalAt = (points: BrushPoint[], i: number): BrushPoint => {
  const before = points[i - 1] ?? points[i];
  const after = points[i + 1] ?? points[i];
  const tx = after.x - before.x;
  const ty = after.y - before.y;
  const length = Math.hypot(tx, ty) || 1;
  return { x: -ty / length, y: tx / length };
};

const curveSegments = (points: BrushPoint[]): string =>
  points
    .slice(0, -1)
    .map((p1, i) => {
      const p0 = points[i - 1] ?? p1;
      const p2 = points[i + 1];
      const p3 = points[i + 2] ?? p2;
      return `C ${p1.x + (p2.x - p0.x) / 6} ${p1.y + (p2.y - p0.y) / 6}, ${p2.x - (p3.x - p1.x) / 6} ${p2.y - (p3.y - p1.y) / 6}, ${p2.x} ${p2.y}`;
    })
    .join(" ");

export function brushRibbon(
  spine: BrushPoint[],
  options: BrushTaper & { progress?: number },
): string {
  const progress = options.progress ?? 1;
  const drawn = Math.max(2, Math.round(progress * (spine.length - 1)) + 1);

  const left: BrushPoint[] = [];
  const right: BrushPoint[] = [];
  for (let i = 0; i < drawn; i++) {
    const half = brushHalfWidth(options, i / (spine.length - 1));
    const normal = normalAt(spine, i);
    left.push({
      x: spine[i].x + normal.x * half,
      y: spine[i].y + normal.y * half,
    });
    right.push({
      x: spine[i].x - normal.x * half,
      y: spine[i].y - normal.y * half,
    });
  }
  const back = right.slice().reverse();

  return `M ${left[0].x} ${left[0].y} ${curveSegments(left)} L ${back[0].x} ${back[0].y} ${curveSegments(back)} Z`;
}

export function BrushGrain({
  seed,
  strokeWidth,
  grain,
}: {
  seed: string;
  strokeWidth: number;
  grain: number;
}) {
  return (
    <defs>
      <filter
        id={brushFilterId(seed, strokeWidth, grain)}
        x="-30%"
        y="-30%"
        width="160%"
        height="160%"
      >
        <feTurbulence
          type="fractalNoise"
          baseFrequency={GRAIN_FREQUENCY}
          numOctaves={GRAIN_OCTAVES}
          seed={Math.floor(hash01(`${seed}:grain`) * 1000)}
          result="brushGrain"
        />
        <feDisplacementMap
          in="SourceGraphic"
          in2="brushGrain"
          scale={brushGrainScale(strokeWidth, grain)}
          xChannelSelector="R"
          yChannelSelector="G"
        />
      </filter>
    </defs>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { useId, useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

/** gradients.sh "swirl" palette, light core to deep rim. */
const SWIRL = ["#ffe2c4", "#ff9a4d", "#d2456b", "#3a1f6b"] as const;

function mixHex(a: string, b: string, k: number) {
  const ch = (h: string, o: number) => Number.parseInt(h.slice(o, o + 2), 16);
  const m = (o: number) => Math.round(ch(a, o) + (ch(b, o) - ch(a, o)) * k);
  return `rgb(${m(1)}, ${m(3)}, ${m(5)})`;
}

export interface BubbleItem {
  label: string;
  value: number;
}

export interface BubblePackProps {
  items?: BubbleItem[];
  highlight?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_ITEMS: BubbleItem[] = [
  { label: "Launch videos", value: 420 },
  { label: "Demos", value: 180 },
  { label: "Changelogs", value: 150 },
  { label: "Social clips", value: 130 },
  { label: "Onboarding", value: 96 },
  { label: "Ads", value: 84 },
  { label: "Tutorials", value: 70 },
  { label: "Recaps", value: 58 },
  { label: "Teasers", value: 46 },
  { label: "Pitches", value: 38 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_GROW = Easing.bezier(0.45, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#9A999F",
    ramp: ["#3A3A40", "#222226"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    ramp: ["#D2D0CA", "#E7E5E0"],
    grain: 0.045,
  },
} as const;

const GROW_IN = 4;
const STAGGER = 3;
const ACC_START = 46;
const ACC_END = 86;
const SUB = 3;
const SQUASH = 2.1;

interface V {
  x: number;
  y: number;
}

function tangents(
  a: V & { r: number },
  b: V & { r: number },
  r: number,
  gap: number,
) {
  const da = a.r + r + gap;
  const db = b.r + r + gap;
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const d = Math.hypot(dx, dy);
  if (d > da + db || d < Math.abs(da - db) || d === 0) return [];
  const along = (da * da - db * db + d * d) / (2 * d);
  const h = Math.sqrt(Math.max(0, da * da - along * along));
  const mx = a.x + (dx * along) / d;
  const my = a.y + (dy * along) / d;
  return [
    { x: mx + (h * dy) / d, y: my - (h * dx) / d },
    { x: mx - (h * dy) / d, y: my + (h * dx) / d },
  ];
}

function place(placed: (V & { r: number })[], r: number, gap: number): V {
  if (placed.length === 0) return { x: 0, y: 0 };
  if (placed.length === 1)
    return { x: placed[0].x + placed[0].r + r + gap, y: 0 };
  let best: V = { x: 0, y: 0 };
  let score = Number.POSITIVE_INFINITY;
  const o = placed[0];
  for (const side of [-1, 1]) {
    const c = { x: o.x + side * (o.r + r + gap), y: o.y };
    const ok = placed.every(
      (q) => Math.hypot(q.x - c.x, q.y - c.y) >= q.r + r + gap - 0.01,
    );
    const sc = c.x * c.x + 1;
    if (ok && sc < score) {
      score = sc;
      best = c;
    }
  }
  for (let i = 0; i < placed.length; i++) {
    for (let j = i + 1; j < placed.length; j++) {
      for (const c of tangents(placed[i], placed[j], r, gap)) {
        const ok = placed.every(
          (q) => Math.hypot(q.x - c.x, q.y - c.y) >= q.r + r + gap - 0.01,
        );
        if (!ok) continue;
        const s = c.x * c.x + (c.y * SQUASH) ** 2;
        if (s < score) {
          score = s;
          best = c;
        }
      }
    }
  }
  return best;
}

function bounds(cs: (V & { r: number })[]) {
  let x0 = Number.POSITIVE_INFINITY;
  let y0 = Number.POSITIVE_INFINITY;
  let x1 = Number.NEGATIVE_INFINITY;
  let y1 = Number.NEGATIVE_INFINITY;
  for (const c of cs) {
    x0 = Math.min(x0, c.x - c.r);
    y0 = Math.min(y0, c.y - c.r);
    x1 = Math.max(x1, c.x + c.r);
    y1 = Math.max(y1, c.y + c.r);
  }
  return { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, w: x1 - x0, h: y1 - y0 };
}

function accentRadius(frame: number, seed: number, full: number) {
  const k = interpolate(frame, [ACC_START, ACC_END], [0, 1], {
    ...CLAMP,
    easing: EASE_GROW,
  });
  return seed + (full - seed) * k;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function formatValue(v: number) {
  return Math.round(v).toLocaleString("en-US");
}

export function BubblePack({
  items = DEFAULT_ITEMS,
  highlight = 0,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: BubblePackProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];

  const model = useMemo(() => {
    const src = items.slice(0, 16).map((it, i) => ({
      ...it,
      i,
      value: Math.max(0, it.value),
    }));
    const hlIdx = Math.min(Math.max(0, Math.round(highlight)), src.length - 1);
    const vmax = Math.max(1, ...src.map((s) => s.value));
    const Rmax = 172 * u;
    const gap = 6 * u;
    const rad = (v: number) => Math.max(10 * u, Rmax * Math.sqrt(v / vmax));
    const hero = src[hlIdx];
    const grays = src
      .filter((s) => s.i !== hlIdx)
      .sort((a, b) => b.value - a.value)
      .map((s, rank) => ({ ...s, r: rad(s.value), rank }));

    const seedR = 14 * u;
    const RA = rad(hero?.value ?? vmax);
    const S: V = { x: 0, y: 0 };
    const finals: (V & { r: number })[] = [{ ...S, r: RA }];
    for (const g of grays) {
      const c = place(finals, g.r, gap);
      finals.push({ ...c, r: g.r });
    }

    const back: V[][] = [];
    const pos = finals.slice(1).map((c) => ({ x: c.x, y: c.y }));
    back.push(pos.map((q) => ({ x: q.x, y: q.y })));
    for (let f = ACC_END - 1; f >= ACC_START; f--) {
      for (let s = 0; s < SUB; s++) {
        const ff = f + 1 - (s + 1) / SUB;
        const ra = accentRadius(ff, seedR, RA);
        const pull = 0.04;
        for (const q of pos) {
          q.x += (S.x - q.x) * pull;
          q.y += (S.y - q.y) * Math.min(0.5, pull * SQUASH);
        }
        for (let it = 0; it < 5; it++) {
          for (let i = 0; i < pos.length; i++) {
            const a = pos[i];
            const ri = grays[i].r;
            let dx = a.x - S.x;
            let dy = a.y - S.y;
            let d = Math.hypot(dx, dy);
            const minA = ri + ra + gap;
            if (d < minA) {
              if (d < 1e-6) {
                dx = Math.cos(i);
                dy = Math.sin(i);
                d = 1;
              }
              const o = minA - d;
              a.x += (dx / d) * o;
              a.y += (dy / d) * o;
            }
            for (let j = i + 1; j < pos.length; j++) {
              const b = pos[j];
              const rj = grays[j].r;
              let ex = b.x - a.x;
              let ey = b.y - a.y;
              let e = Math.hypot(ex, ey);
              const min = ri + rj + gap;
              if (e >= min) continue;
              if (e < 1e-6) {
                ex = Math.cos(i + j);
                ey = Math.sin(i + j);
                e = 1;
              }
              const o = min - e;
              const wa = (rj * rj) / (ri * ri + rj * rj);
              a.x -= (ex / e) * o * wa;
              a.y -= (ey / e) * o * wa;
              b.x += (ex / e) * o * (1 - wa);
              b.y += (ey / e) * o * (1 - wa);
            }
          }
        }
      }
      back.push(pos.map((q) => ({ x: q.x, y: q.y })));
    }
    const frames = back.reverse();
    const placed = frames[0].map((q, i) => ({ ...q, r: grays[i].r }));
    const pb = bounds(placed);
    const order = placed
      .map((q, i) => ({ i, d: Math.hypot(q.x - pb.cx, (q.y - pb.cy) * 1.3) }))
      .sort((a, b) => a.d - b.d);
    const seq = new Array<number>(placed.length);
    order.forEach((o, k) => {
      seq[o.i] = k;
    });

    const availW = width * 0.84;
    const availH = height * 0.8;
    const fit = (cs: (V & { r: number })[]) => {
      const b = bounds(cs);
      return {
        cx: b.cx,
        cy: b.cy,
        s: Math.min(1.18, availW / b.w, availH / b.h),
      };
    };
    const camA = fit(placed);
    const raw = frames.map((fr, k) =>
      fit([
        ...fr.map((q, i) => ({ ...q, r: grays[i].r })),
        { ...S, r: accentRadius(ACC_START + k, seedR, RA) },
      ]),
    );
    const W = 7;
    const cams = raw.map((_, k) => {
      let cx = 0;
      let cy = 0;
      let sc = 0;
      let n = 0;
      for (let j = k - W; j <= k + W; j++) {
        const c = j < 0 ? camA : raw[Math.min(j, raw.length - 1)];
        cx += c.cx;
        cy += c.cy;
        sc += c.s;
        n++;
      }
      return { cx: cx / n, cy: cy / n, s: Math.min(sc / n, raw[k].s * 1.01) };
    });
    return { grays, hero, placed, frames, S, seedR, RA, camA, cams, seq };
  }, [items, highlight, u, width, height]);

  const { grays, hero, placed, frames, S, seedR, RA, camA, cams, seq } = model;

  const sample = (i: number) => {
    if (t <= ACC_START) return placed[i];
    const k = Math.min(t - ACC_START, frames.length - 1);
    const f0 = Math.floor(k);
    const f1 = Math.min(f0 + 1, frames.length - 1);
    const w = k - f0;
    return {
      x: frames[f0][i].x * (1 - w) + frames[f1][i].x * w,
      y: frames[f0][i].y * (1 - w) + frames[f1][i].y * w,
    };
  };

  const camAt = (() => {
    if (t <= ACC_START) return camA;
    const k = Math.min(t - ACC_START, cams.length - 1);
    const f0 = Math.floor(k);
    const f1 = Math.min(f0 + 1, cams.length - 1);
    const w = k - f0;
    return {
      cx: cams[f0].cx * (1 - w) + cams[f1].cx * w,
      cy: cams[f0].cy * (1 - w) + cams[f1].cy * w,
      s: cams[f0].s * (1 - w) + cams[f1].s * w,
    };
  })();
  const ccx = camAt.cx;
  const ccy = camAt.cy;
  const drift = interpolate(t, [0, ACC_END + 60], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const cs = camAt.s * (0.985 + 0.015 * drift);
  const toScreen = (q: V) => ({
    x: width / 2 + (q.x - ccx) * cs,
    y: height / 2 + (q.y - ccy) * cs,
  });

  const ra = accentRadius(t, seedR, RA);
  const accOpacity = interpolate(
    t,
    [ACC_START - 2, ACC_START + 6],
    [0, 1],
    CLAMP,
  );
  const heroIn = interpolate(t, [ACC_END - 8, ACC_END + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const heroLab = interpolate(t, [ACC_END - 2, ACC_END + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [ACC_END - 8, ACC_END + 22], [0.5, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const quiet = interpolate(t, [ACC_START, ACC_END], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const nG = Math.max(1, grays.length - 1);
  const shade = (rank: number) => {
    const k = rank / nG;
    const a = p.ramp[0];
    const b = p.ramp[1];
    const ch = (s: string, o: number) => Number.parseInt(s.slice(o, o + 2), 16);
    const mix = (o: number) => Math.round(ch(a, o) + (ch(b, o) - ch(a, o)) * k);
    return `rgb(${mix(1)}, ${mix(3)}, ${mix(5)})`;
  };

  const gid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const sc = toScreen(S);
  const heroR = ra * cs;
  const heroFont = Math.min(136 * u, heroR * 0.68);

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        {grays.map((g, i) => {
          const start = GROW_IN + seq[i] * STAGGER;
          const k = spring({
            frame: t - start,
            fps,
            config: { damping: 15, stiffness: 120, mass: 0.7 },
          });
          const o = interpolate(t, [start, start + 6], [0, 1], CLAMP);
          const q = toScreen(sample(i));
          return (
            <circle
              key={g.label + g.i}
              cx={q.x}
              cy={q.y}
              r={Math.max(0, g.r * cs * (0.6 + 0.4 * k))}
              fill={shade(g.rank)}
              opacity={o}
            />
          );
        })}
        <defs>
          <linearGradient
            id={`${gid}h`}
            x1={0.15}
            y1={0}
            x2={0.85}
            y2={1}
            gradientTransform={`rotate(${-10 + 14 * drift} 0.5 0.5)`}
          >
            <stop offset={0} stopColor={SWIRL[0]} />
            <stop offset={0.22} stopColor={SWIRL[1]} />
            <stop offset={0.58} stopColor={SWIRL[2]} />
            <stop offset={1} stopColor={mixHex(SWIRL[3], accent, 0.25)} />
          </linearGradient>
        </defs>
        {hero ? (
          <circle
            cx={sc.x}
            cy={sc.y}
            r={heroR}
            fill={`url(#${gid}h)`}
            opacity={accOpacity}
          />
        ) : null}
      </svg>

      {grays.map((g, i) => {
        const rs = g.r * cs;
        const nameSize = 16 * u;
        const fits =
          rs >= 44 * u && g.label.length * nameSize * 0.56 <= rs * 1.6;
        if (!fits) return null;
        const start = GROW_IN + seq[i] * STAGGER + 8;
        const a = interpolate(t, [start, start + 12], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        const q = toScreen(sample(i));
        return (
          <div
            key={g.label + g.i}
            style={{
              position: "absolute",
              left: q.x,
              top: q.y,
              transform: `translate(-50%, -50%) translateY(${(1 - a) * 5 * u}px)`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2 * u,
              opacity: a * (1 - 0.25 * quiet),
              whiteSpace: "nowrap",
            }}
          >
            <span
              style={{
                fontFamily: sans,
                fontWeight: 400,
                fontSize: nameSize,
                letterSpacing: "-0.01em",
                color: p.fg,
              }}
            >
              {g.label}
            </span>
            <span
              style={{
                fontFamily: sans,
                fontWeight: 500,
                fontSize: 15 * u,
                color: p.muted,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {formatValue(g.value)}
            </span>
          </div>
        );
      })}

      {hero ? (
        <div
          style={{
            position: "absolute",
            left: sc.x,
            top: sc.y,
            transform: "translate(-50%, -50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              fontFamily: sans,
              fontWeight: 500,
              fontSize: heroFont,
              lineHeight: 1,
              letterSpacing: "-0.04em",
              color: "#FFFFFF",
              fontVariantNumeric: "tabular-nums",
              opacity: heroIn,
              filter:
                heroIn < 0.99 ? `blur(${(1 - heroIn) * 8 * u}px)` : undefined,
              transform: `translateY(${(1 - heroIn) * 16 * u}px)`,
            }}
          >
            {formatValue(hero.value * count)}
          </span>
          <span
            style={{
              marginTop: 8 * u,
              fontFamily: sans,
              fontWeight: 400,
              fontSize: 25 * u,
              letterSpacing: "-0.01em",
              color: "rgba(255,255,255,0.92)",
              opacity: heroLab,
              transform: `translateY(${(1 - heroLab) * 8 * u}px)`,
            }}
          >
            {hero.label}
          </span>
        </div>
      ) : null}

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${p.bg} 100%)`,
          opacity: 0.5,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { loadVariableFont } from "@remotion/google-fonts/Urbanist";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const urbanist = loadVariableFont("normal", { subsets: ["latin"] });
const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";
const R_RATIO = 124.06 / 134.26;
const R_EM = 0.76;
const R_GAP = 0.04;
const LOGO_TRACK = -0.025;

export interface BugDockProps {
  name?: string;
  headline?: string;
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#0B0B0B", ink: "#FFFFFF", blue: "#2F6BFF" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", blue: "#1F4FE0" },
} as const;

const ENTER_AT = 0;
const TUCK_AT = 34;
const TUCK_STEP = 6;
const TUCK_DUR = 11;
const DOCK_DUR = 30;
const HEAD_DELAY = 14;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_TUCK = Easing.bezier(0.55, 0, 0.2, 1);
const EASE_DOCK = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: number[];
  baseline: number;
  cap: number;
}

function measure(letters: string[], logo: boolean): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  const adv: number[] = [];
  let baseline = 0.78;
  let cap = 0.72;
  if (ctx) {
    const family = logo ? manrope.fontFamily : urbanist.fontFamily;
    const weight = logo ? 600 : 500;
    ctx.font = `${weight} 200px "${family}"`;
    for (const ch of letters) {
      adv.push(ctx.measureText(ch).width / 200 + LOGO_TRACK);
    }
    const fm = ctx.measureText("H");
    const asc = fm.fontBoundingBoxAscent / 200;
    const desc = fm.fontBoundingBoxDescent / 200;
    baseline = (1 - (asc + desc)) / 2 + asc;
    cap = fm.actualBoundingBoxAscent / 200;
  }
  return { adv, baseline, cap };
}

function useMetrics(letters: string[], logo: boolean) {
  const key = `${logo ? 1 : 0}${letters.join("")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("bug-dock: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const isLogo = key[0] === "1";
    const chars = Array.from(key.slice(1));
    Promise.all([
      urbanist.waitUntilDone(),
      manrope.waitUntilDone(),
      document.fonts.load(`600 100px "${manrope.fontFamily}"`),
      document.fonts.load(`500 100px "${urbanist.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(chars, isLogo) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function RMark({ height, color }: { height: number; color: string }) {
  return (
    <svg
      viewBox="0 0 124.06 134.26"
      height={height}
      width={height * R_RATIO}
      style={{ display: "block" }}
      aria-hidden
    >
      <path fill={color} d={REMOCN_R_PATH} />
    </svg>
  );
}

function normalizeHex(c: string | undefined, fallback: string) {
  if (c && /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(c)) return c;
  return fallback;
}

export function BugDock({
  name = "remocn",
  headline = "Playing on every screen you ship.",
  highlight = "every screen",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: BugDockProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const blue = normalizeHex(accent, c.blue);

  const clean = name.trim() || "remocn";
  const logo = clean.toLowerCase() === "remocn";
  const tail = useMemo(
    () => Array.from(logo ? "emocn" : clean.slice(1)),
    [logo, clean],
  );
  const head = logo ? "" : Array.from(clean)[0];
  const letters = useMemo(
    () => (logo ? tail : [head, ...tail]),
    [logo, tail, head],
  );
  const m = useMetrics(letters, logo);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  const words = useMemo(
    () => headline.split(/\s+/).filter(Boolean),
    [headline],
  );
  const hiWords = useMemo(
    () =>
      new Set(
        highlight
          .toLowerCase()
          .split(/\s+/)
          .filter(Boolean)
          .map((w) => w.replace(/[^\p{L}\p{N}]/gu, "")),
      ),
    [highlight],
  );

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);

  const tailAdv = logo ? m.adv : m.adv.slice(1);
  const firstAdv = logo ? R_EM * R_RATIO + R_GAP : m.adv[0];
  const fullEm = firstAdv + tailAdv.reduce((a, b) => a + b, 0);
  const LF = Math.min(
    (W * (portrait ? 0.8 : 0.58)) / fullEm,
    H * (portrait ? 0.14 : 0.3),
  );
  const baseY = H * 0.5 + (m.cap * LF) / 2;

  const n = tailAdv.length;
  const tuckP = tailAdv.map((_, k) => {
    const order = n - 1 - k;
    const at = TUCK_AT + order * TUCK_STEP;
    return interpolate(t, [at, at + TUCK_DUR], [0, 1], {
      ...CLAMP,
      easing: EASE_TUCK,
    });
  });
  const tuckEnd = TUCK_AT + (n - 1) * TUCK_STEP + TUCK_DUR;
  const dockAt = tuckEnd + 2;
  const headAt = dockAt + HEAD_DELAY;

  const visibleEm =
    firstAdv -
    (logo ? R_GAP : 0) * tuckP[0] +
    tailAdv.reduce((a, w, k) => a + w * (1 - tuckP[k]), 0);
  const groupLeft = (W - visibleEm * LF) / 2;

  const xs: number[] = [];
  let shift = 0;
  for (let k = 0; k < n; k++) {
    let orig = firstAdv;
    for (let j = 0; j < k; j++) orig += tailAdv[j];
    shift += tuckP[k] * tailAdv[k];
    xs.push(groupLeft + (orig - shift) * LF);
  }

  const dock = interpolate(t, [dockAt, dockAt + DOCK_DUR], [0, 1], {
    ...CLAMP,
    easing: EASE_DOCK,
  });

  const firstH = logo ? R_EM * LF : m.cap * LF;
  const firstW = logo ? firstH * R_RATIO : m.adv[0] * LF;
  const bugH = H * (portrait ? 0.04 : 0.08);
  const bugScale = bugH / firstH;
  const margin = Math.min(W, H) * 0.075;
  const bugRight = W - margin;
  const bugBottom = H - margin;

  const startLeft = groupLeft;
  const startBottom = baseY;
  const endLeft = bugRight - firstW * bugScale;
  const curLeft = startLeft + (endLeft - startLeft) * dock;
  const curBottom = startBottom + (bugBottom - startBottom) * dock;
  const curScale = 1 + (bugScale - 1) * dock;
  const bugOpacity = 1 - 0.18 * dock;

  const enter = (i: number) =>
    interpolate(t, [ENTER_AT + i * 2, ENTER_AT + i * 2 + 18], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const tailFont = logo ? manrope.fontFamily : urbanist.fontFamily;
  const tailWeight = logo ? 600 : 500;
  const tailNodes = tailAdv.map((adv, k) => {
    const prevRight =
      k === 0 ? groupLeft + firstAdv * LF : xs[k - 1] + tailAdv[k - 1] * LF;
    const clipL = Math.max(0, prevRight - xs[k]);
    const e = enter(k + 1);
    const ch = logo ? tail[k] : letters[k + 1];
    return (
      <div
        key={`${k}-${ch}`}
        style={{
          position: "absolute",
          left: xs[k],
          top: baseY - m.baseline * LF - LF * 0.15,
          height: LF * 1.3,
          width: adv * LF + LF * 0.3,
          overflow: "hidden",
          clipPath: `inset(0 0 0 ${clipL.toFixed(2)}px)`,
          opacity: 1 - tuckP[k],
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: LF * 0.15,
            fontFamily: tailFont,
            fontWeight: tailWeight,
            fontSize: LF,
            lineHeight: `${LF}px`,
            letterSpacing: `${LOGO_TRACK}em`,
            whiteSpace: "pre",
            color: c.ink,
            transform: `translateY(${((1 - e) * LF * 0.9).toFixed(2)}px)`,
          }}
        >
          {ch}
        </div>
      </div>
    );
  });

  const firstEnter = enter(0);
  const headFs = (portrait ? 132 : 124) * s;
  const headLeft = portrait ? W * 0.08 : W * 0.075;
  const headW = portrait ? W * 0.84 : W * 0.78;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: groupLeft,
          top: baseY - firstH - LF * 0.2,
          width: firstW + LF * 0.1,
          height: firstH + LF * 0.2,
          overflow: "hidden",
          opacity: dock > 0 ? 0 : 1,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: LF * 0.2,
            transform: `translateY(${((1 - firstEnter) * firstH * 1.1).toFixed(2)}px)`,
          }}
        >
          {logo ? (
            <RMark height={firstH} color={c.ink} />
          ) : (
            <span
              style={{
                display: "block",
                fontFamily: urbanist.fontFamily,
                fontWeight: 500,
                fontSize: LF,
                lineHeight: `${firstH}px`,
                color: c.ink,
              }}
            >
              {head}
            </span>
          )}
        </div>
      </div>

      {tailNodes}

      {dock > 0 ? (
        <div
          style={{
            position: "absolute",
            left: curLeft,
            top: curBottom - firstH * curScale,
            width: firstW,
            height: firstH,
            transformOrigin: "0 0",
            transform: `scale(${curScale.toFixed(4)})`,
            opacity: bugOpacity,
          }}
        >
          {logo ? (
            <RMark height={firstH} color={c.ink} />
          ) : (
            <span
              style={{
                display: "block",
                fontFamily: urbanist.fontFamily,
                fontWeight: 500,
                fontSize: LF,
                lineHeight: `${firstH}px`,
                color: c.ink,
              }}
            >
              {head}
            </span>
          )}
        </div>
      ) : null}

      <div
        style={{
          position: "absolute",
          left: headLeft,
          width: headW,
          top: portrait ? H * 0.36 : H * 0.27,
          fontFamily: urbanist.fontFamily,
          fontSize: headFs,
          fontVariationSettings: '"wght" 400',
          lineHeight: 1.04,
          letterSpacing: "-0.03em",
          color: c.ink,
          textWrap: "balance",
        }}
      >
        {words.map((w, i) => {
          const at = headAt + i * 2.5;
          const p = interpolate(t, [at, at + 16], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const hi = hiWords.has(
            w.toLowerCase().replace(/[^\p{L}\p{N}]/gu, ""),
          );
          return (
            <span
              key={`${i}-${w}`}
              style={{
                display: "inline-block",
                overflow: "hidden",
                verticalAlign: "top",
                paddingBottom: "0.12em",
                marginBottom: "-0.12em",
                marginRight: "0.24em",
              }}
            >
              <span
                style={{
                  display: "inline-block",
                  color: hi ? blue : c.ink,
                  transform: `translateY(${((1 - p) * 1.1).toFixed(3)}em)`,
                }}
              >
                {w}
              </span>
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

