      <path
        d="M5 3.5 18.6 11l-6 1.7-3 5.9L5 3.5Z"
        fill="#141110"
        stroke="#ffffff"
        strokeWidth={1.5}
        strokeLinejoin="round"
      />
    </svg>
  );
}

