export function ButtonToCard({
  theme = "dark",
  accent = "#f2552c",
  buttonLabel = "Add an item",
  name = "Ceramic pitcher",
  price = "$48.00",
  images = [
    staticFile("templates/brand-guidelines/ceramics.jpg"),
    staticFile("templates/brand-guidelines/chair.jpg"),
    staticFile("templates/product-showcase/sculpture.jpg"),
    staticFile("templates/brand-guidelines/materials.jpg"),
  ],
  others = [
    { name: "Oak stool", price: "$120.00" },
    { name: "Arch sculpture", price: "$86.00" },
    { name: "Material kit", price: "$32.00" },
  ],
  storeName = "Studio Goods",
  ground,
  groundParams,
}: ButtonToCardProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const dark = theme === "dark";
  const portrait = height > width * 1.2;
  const stageW = portrait ? 720 : 1280;
  const stageH = portrait ? 1280 : 720;
  const k = width / stageW;

  const ink = dark ? "#f7f0ea" : "#1c1612";
  const muted = dark ? "rgba(247,240,234,0.52)" : "rgba(28,22,18,0.5)";
  const faint = dark ? "rgba(247,240,234,0.3)" : "rgba(28,22,18,0.3)";
  const hair = dark ? "rgba(255,236,220,0.1)" : "rgba(70,40,20,0.1)";
  const field = dark ? "rgba(255,236,220,0.045)" : "#fbf8f5";
  const surface = dark
    ? "linear-gradient(180deg, rgba(40,31,27,0.9) 0%, rgba(22,17,15,0.94) 100%)"
    : "linear-gradient(180deg, #ffffff 0%, #fffcf9 100%)";
  const slotFill = dark ? "rgba(255,236,220,0.04)" : "#f8f2ec";
  const shadow = dark
    ? "inset 0 1px 0 rgba(255,240,225,0.07), 0 1px 2px rgba(0,0,0,0.4), 0 14px 32px rgba(0,0,0,0.35), 0 50px 110px rgba(20,6,0,0.55)"
    : "inset 0 1px 0 #ffffff, 0 1px 2px rgba(120,60,20,0.08), 0 12px 28px rgba(150,80,30,0.1), 0 44px 100px rgba(150,80,30,0.16)";
  const btnInk = dark ? "#1a1411" : "#ffffff";

  const all = [{ name, price }, ...others].slice(0, 4);
  const count = all.length;
  const cols = portrait ? 2 : count;
  const tileW = portrait ? 296 : 252;
  const tileH = portrait ? 372 : 340;
  const gap = portrait ? 20 : 22;
  const imgInset = 12;
  const tileImg = tileW - imgInset * 2;
  const rows = Math.ceil(count / cols);
  const gridW = cols * tileW + (cols - 1) * gap;
  const gridH = rows * tileH + (rows - 1) * gap;
  const headH = 64;
  const groupH = headH + gridH;
  const gridTop = -groupH / 2 + headH + (portrait ? 0 : 14);
  const tileRect = (i: number): Rect => ({
    x: -gridW / 2 + (i % cols) * (tileW + gap),
    y: gridTop + Math.floor(i / cols) * (tileH + gap),
    w: tileW,
    h: tileH,
    r: 24,
  });

  const cardW = portrait ? 620 : 940;
  const cardH = portrait ? 980 : 560;
  const cardRect: Rect = {
    x: -cardW / 2,
    y: -cardH / 2,
    w: cardW,
    h: cardH,
    r: 30,
  };
  const pillRect: Rect = { x: -132, y: -32, w: 264, h: 64, r: 32 };
  const mediaCard: Rect = portrait
    ? { x: 14, y: 14, w: cardW - 28, h: 400, r: 16 }
    : { x: 14, y: 14, w: 440, h: cardH - 28, r: 16 };
  const mediaTile: Rect = {
    x: imgInset,
    y: imgInset,
    w: tileImg,
    h: tileImg,
    r: 12,
  };
  const col = portrait
    ? { x: 36, y: 444, w: cardW - 72 }
    : { x: 494, y: 40, w: cardW - 494 - 40 };

  const pillIn = spring({ frame: frame - B.pill, fps, config: CARD });
  const morph = spring({
    frame: frame - B.morph,
    fps,
    config: MORPH,
    durationInFrames: 22,
  });
  const shrink = spring({
    frame: frame - B.shrink,
    fps,
    config: HEAVY,
    durationInFrames: 26,
  });
  const shrinkPrev = spring({
    frame: frame - 1 - B.shrink,
    fps,
    config: HEAVY,
    durationInFrames: 26,
  });
  const press = dip(frame, B.press, 0.07);
  let box = lerpRect(pillRect, cardRect, morph);
  box = lerpRect(box, tileRect(0), shrink);
  const t0 = tileRect(0);
  const shrinkV = Math.abs(shrink - shrinkPrev);
  const shrinkBlurX = Math.min(6, shrinkV * Math.abs(cardRect.x - t0.x) * 0.2);
  const shrinkBlurY = Math.min(6, shrinkV * Math.abs(cardRect.y - t0.y) * 0.2);

  const pillLabel = 1 - ramp(frame, B.morph, 6, EXIT);
  const fieldIn = (i: number) => ramp(frame, B.fields + i * 3, 12);
  const cardContent = 1 - ramp(frame, B.shrink, 8, EXIT);
  const tileContent = ramp(frame, B.shrink + 12, 12);
  const media = lerpRect(mediaCard, mediaTile, shrink);

  const typedName = name.slice(0, Math.max(0, frame - B.title));
  const typedPrice = price.slice(
    0,
    Math.max(0, Math.floor((frame - B.price) / 1.5)),
  );
  const nameCaret = frame >= B.title - 4 && frame < B.price;
  const priceCaret = frame >= B.price && frame < B.status;
  const caretBlink = Math.floor(frame / 8) % 2 === 0 ? 1 : 0.2;
  const statusOn = spring({ frame: frame - B.status, fps, config: CHIP });

  const mediaCx = cardRect.x + mediaCard.x + mediaCard.w / 2;
  const mediaCy = cardRect.y + mediaCard.y + mediaCard.h / 2;
  const startPt = portrait ? { x: 300, y: 720 } : { x: 720, y: 360 };
  const carry = spring({
    frame: frame - B.carry,
    fps,
    config: { mass: 0.9, damping: 20, stiffness: 90 },
  });
  const carryPrev = spring({
    frame: frame - 1 - B.carry,
    fps,
    config: { mass: 0.9, damping: 20, stiffness: 90 },
  });
  const hover = { x: mediaCx + 40, y: mediaCy - 20 };
  const arc = Math.sin(Math.PI * Math.min(1, carry)) * (portrait ? 60 : -80);
  const drop = spring({ frame: frame - B.drop, fps, config: CARD });
  let ix = mix(startPt.x, hover.x, carry);
  let iy = mix(startPt.y, hover.y, carry) + arc;
  const vx = Math.abs(carry - carryPrev) * Math.abs(hover.x - startPt.x);
  const vy = Math.abs(carry - carryPrev) * Math.abs(hover.y - startPt.y);
  ix = mix(ix, mediaCx, drop);
  iy = mix(iy, mediaCy, drop);
  const carriedW = mix(portrait ? 220 : 200, mediaCard.w, Math.min(1, drop));
  const carriedH = mix(portrait ? 170 : 240, mediaCard.h, Math.min(1, drop));
  const carriedRot = mix(mix(14, -5, carry), 0, Math.min(1, drop));
  const placed = frame >= B.drop + 10;
  const slotHot =
    ramp(frame, B.carry + 16, 8) * (1 - ramp(frame, B.drop + 4, 8, EXIT));
  const breathe = 1 + 0.012 * Math.sin((frame - B.carry) / 3.2) * slotHot;

  const btnX = cardRect.x + col.x + col.w - 90;
  const btnY = cardRect.y + cardH - (portrait ? 64 : 64);
  const cursorPath: [number, number, number][] = [
    [-6, 200, 170],
    [B.press - 2, 40, 14],
    [B.morph + 8, 40, 14],
    [B.morph + 24, startPt.x + 60, startPt.y + 50],
    [B.carry, startPt.x + 40, startPt.y + 40],
    [B.drop + 10, mediaCx + 120, mediaCy + 90],
    [B.save - 4, btnX + 10, btnY + 6],
    [B.shrink, btnX + 10, btnY + 6],
    [B.shrink + 18, btnX + 140, btnY + 120],
  ];
  const cAt = (i: 1 | 2) =>
    interpolate(
      frame,
      cursorPath.map((c) => c[0]),
      cursorPath.map((c) => c[i]),
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
        easing: MOVE,
      },
    );
  const attach =
    ramp(frame, B.carry - 2, 6) * (1 - ramp(frame, B.drop + 2, 8, EXIT));
  const pointerX = mix(cAt(1), ix + 30, attach);
  const pointerY = mix(cAt(2), iy + 40, attach);
  const cursorOpacity =
    ramp(frame, -6, 8) * (1 - ramp(frame, B.shrink + 6, 8, EXIT));
  const cursorScale = dip(frame, B.press, 0.16) * dip(frame, B.save, 0.16);
  const saveDip = dip(frame, B.save, 0.06);

  const headerIn = ramp(frame, B.header, 14);
  const liveIn = spring({ frame: frame - B.live, fps, config: CHIP });

  const camPill = 1 - ramp(frame, B.morph - 4, 26, CAM);
  const gridFocus = spring({
    frame: frame - B.shrink,
    fps,
    config: HEAVY,
  });
  const settle = spring({ frame: frame + 8, fps, config: HEAVY });
  const push =
    (portrait ? 1.7 : 2.1) * camPill +
    (1 - camPill) +
    0.035 * ramp(frame, B.shrink + 10, B.end - B.shrink, Easing.linear);
  const rotX = mix(10, 4, settle) - 2 * gridFocus + Math.sin(frame / 40) * 0.5;
  const rotY =
    mix(-14, -4, settle) + 5 * morph * (1 - gridFocus) - 3 * gridFocus;

  const resolvedParams: Partial<GradientParams> | undefined =
    groundParams ??
    (ground || dark
      ? undefined
      : {
          kind: "mist",
          background: "#faf5ef",
          colors: ["#ffb27a", "#ffd9bd", "#fff4ea", "#e0773a"],
        });
  const resolvedPreset: GshPresetId | undefined =
    ground ?? (dark ? "hearth" : undefined);

  const labelStyle: React.CSSProperties = {
    fontSize: 15,
    color: muted,
    letterSpacing: "0.01em",
    marginBottom: 8,
  };
  const inputStyle = (active: boolean): React.CSSProperties => ({
    height: 52,
    borderRadius: 12,
    background: field,
    border: `1px solid ${active ? accent : hair}`,
    boxShadow: active
      ? `0 0 0 4px color-mix(in oklab, ${accent} 16%, transparent)`
      : dark
        ? "inset 0 1px 0 rgba(255,240,225,0.03)"
        : "inset 0 1px 2px rgba(70,40,20,0.04)",
    display: "flex",
    alignItems: "center",
    padding: "0 16px",
    gap: 10,
    fontSize: 20,
    color: ink,
    letterSpacing: "-0.01em",
  });
  const caret = (on: boolean) =>
    on ? (
      <span
        style={{
          width: 2,
          height: 24,
          marginLeft: 1,
          background: accent,
          opacity: caretBlink,
        }}
      />
    ) : null;

  const fieldGap = portrait ? 96 : 92;
  const fieldsTop = portrait ? 92 : 104;

  const tileInfo = (n: { name: string; price: string }, op: number) => (
    <div
      style={{
        position: "absolute",
        left: 16,
        right: 16,
        top: tileImg + imgInset + 14,
        opacity: op,
        transform: `translateY(${mix(10, 0, op)}px)`,
      }}
    >
      <div
        style={{
          fontSize: 20,
          color: ink,
          whiteSpace: "nowrap",
          letterSpacing: "-0.015em",
        }}
      >
        {n.name}
      </div>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginTop: 8,
        }}
      >
        <span
          style={{ fontSize: 16, color: muted, fontFamily: mono.fontFamily }}
        >
          {n.price}
        </span>
        <span
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            fontSize: 15,
            color: muted,
          }}
        >
          <span
            style={{
              width: 7,
              height: 7,
              borderRadius: 4,
              background: "#3fb37f",
            }}
          />
          Active
        </span>
      </div>
    </div>
  );

  return (
    <AbsoluteFill style={{ fontFamily: hanken.fontFamily, overflow: "hidden" }}>
      <GshGround
        preset={resolvedPreset}
        params={resolvedParams}
        timeOffset={3}
        timeScale={0.45}
      />
      <DirBlur id="btc-shrink" x={shrinkBlurX} y={shrinkBlurY} />
      <DirBlur
        id="btc-carry"
        x={Math.min(6, vx * 0.12) * (1 - Math.min(1, drop))}
        y={Math.min(6, vy * 0.12) * (1 - Math.min(1, drop))}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: stageW,
          height: stageH,
          transform: `scale(${k})`,
          transformOrigin: "0 0",
          perspective: 2000,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: stageW / 2,
            top: stageH / 2,
            width: 0,
            height: 0,
            transformStyle: "preserve-3d",
            transform: `scale(${push}) rotateX(${rotX}deg) rotateY(${rotY}deg)`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: -gridW / 2,
              width: gridW,
              top: gridTop - headH - 6,
              height: headH,
              display: "flex",
              alignItems: "center",
              gap: 14,
              opacity: headerIn,
              transform: `translateY(${mix(18, 0, headerIn)}px)`,
              filter: `blur(${mix(6, 0, headerIn)}px)`,
            }}
          >
            <span
              style={{
                fontSize: portrait ? 36 : 38,
                fontWeight: 300,
                color: ink,
                letterSpacing: "-0.035em",
              }}
            >
              {storeName}
            </span>
            <span
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                height: 30,
                padding: "0 13px",
                borderRadius: 15,
                background: accent,
                color: "#fff",
                fontSize: 16,
                transform: `scale(${liveIn})`,
                opacity: Math.min(1, liveIn * 2),
                boxShadow: `inset 0 1px 0 rgba(255,255,255,0.3), 0 6px 18px color-mix(in oklab, ${accent} 40%, transparent)`,
              }}
            >
              <span
                style={{
                  width: 7,
                  height: 7,
                  borderRadius: 4,
                  background: "#fff",
                }}
              />
              Live
            </span>
            <span style={{ flex: 1 }} />
            {portrait ? null : (
              <span style={{ fontSize: 17, color: muted }}>
                {count} products
              </span>
            )}
            <span
              style={{
                height: 38,
                padding: "0 16px",
                borderRadius: 12,
                border: `1px solid ${hair}`,
                background: dark ? "rgba(255,236,220,0.05)" : "#ffffff",
                display: "flex",
                alignItems: "center",
                gap: 8,
                fontSize: 16,
                color: ink,
              }}
            >
              View store
              <svg viewBox="0 0 24 24" width={15} height={15} aria-hidden>
                <path d="M8 16 16 8M9 8h7v7" {...line(ink, 1.6)} />
              </svg>
            </span>
          </div>

          {all.slice(1).map((n, j) => {
            const i = j + 1;
            const r = tileRect(i);
            const at = B.pops[j] ?? B.pops[B.pops.length - 1] + j * 4;
            const pop = spring({ frame: frame - at, fps, config: CARD });
            return (
              <div
                key={n.name}
                style={{
                  position: "absolute",
                  left: r.x,
                  top: r.y,
                  width: r.w,
                  height: r.h,
                  borderRadius: r.r,
                  background: surface,
                  border: `1px solid ${hair}`,
                  boxShadow: shadow,
                  overflow: "hidden",
                  opacity: frame >= at ? Math.min(1, pop * 1.8) : 0,
                  transform: `translateY(${mix(48, 0, pop)}px) scale(${mix(0.82, 1, pop)})`,
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: mediaTile.x,
                    top: mediaTile.y,
                    width: mediaTile.w,
                    height: mediaTile.h,
                    borderRadius: mediaTile.r,
                    overflow: "hidden",
                    background: slotFill,
                  }}
                >
                  <Img
                    src={images[i % images.length]}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                    }}
                  />
                </div>
                {tileInfo(n, 1)}
              </div>
            );
          })}

          <div
            style={{
              position: "absolute",
              left: box.x,
              top: box.y,
              width: box.w,
              height: box.h,
              borderRadius: box.r,
              background: surface,
              border: `1px solid ${hair}`,
              boxShadow: shadow,
              overflow: "hidden",
              opacity: Math.min(1, pillIn * 1.6),
              transform: `translateY(${mix(40, 0, pillIn)}px) scale(${press})`,
              filter:
                shrinkBlurX + shrinkBlurY > 0.4
                  ? "url(#btc-shrink)"
                  : undefined,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: (box.w - pillRect.w) / 2,
                top: (box.h - pillRect.h) / 2,
                width: pillRect.w,
                height: pillRect.h,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: 10,
                color: ink,
                fontSize: 22,
                letterSpacing: "-0.01em",
                opacity: pillLabel,
                transform: `scale(${mix(1, 1.25, 1 - pillLabel)})`,
              }}
            >
              <span
                style={{
                  width: 26,
                  height: 26,
                  borderRadius: 13,
                  background: accent,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg viewBox="0 0 24 24" width={16} height={16} aria-hidden>
                  <path d="M12 6v12M6 12h12" {...line("#fff", 2)} />
                </svg>
              </span>
              {buttonLabel}
            </div>

            <div
              style={{
                position: "absolute",
                left: media.x,
                top: media.y,
                width: media.w,
                height: media.h,
                borderRadius: media.r,
                background: slotFill,
                overflow: "hidden",
                opacity: fieldIn(0),
                transform: `scale(${breathe})`,
                outline: placed
                  ? undefined
                  : `1.5px dashed ${slotHot > 0.3 ? accent : faint}`,
                outlineOffset: -10,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 14,
                  color: muted,
                  fontSize: 17,
                  opacity: placed ? 0 : 1,
                  transform: `translateY(${-8 * slotHot}px)`,
                }}
              >
                <div
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 14,
                    border: `1px solid ${hair}`,
                    background: dark ? "rgba(255,236,220,0.05)" : "#ffffff",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: dark
                      ? undefined
                      : "0 2px 6px rgba(70,40,20,0.06)",
                  }}
                >
                  <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden>
                    <path
                      d="M12 15V5M8 9l4-4 4 4M5 15v3a1.5 1.5 0 0 0 1.5 1.5h11A1.5 1.5 0 0 0 19 18v-3"
                      {...line(slotHot > 0.5 ? accent : ink)}
                    />
                  </svg>
                </div>
                <span style={{ color: ink, fontSize: 18 }}>
                  Drop an image here
                </span>
                <span style={{ marginTop: -8 }}>or click to browse</span>
              </div>
              {placed ? (
                <Img
                  src={images[0]}
                  style={{
                    position: "absolute",
                    inset: 0,
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              ) : null}
            </div>

            <div
              style={{
                position: "absolute",
                left: col.x,
                top: col.y,
                width: col.w,
                height: cardH - col.y,
                opacity: cardContent,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  opacity: fieldIn(1),
                  transform: `translateY(${mix(14, 0, fieldIn(1))}px)`,
                }}
              >
                <div style={{ flex: 1 }}>
                  <div
                    style={{
                      fontSize: 30,
                      fontWeight: 300,
                      color: ink,
                      letterSpacing: "-0.03em",
                    }}
                  >
                    New product
                  </div>
                  <div style={{ fontSize: 16, color: muted, marginTop: 4 }}>
                    {storeName} · Catalog
                  </div>
                </div>
                <div
                  style={{
                    position: "relative",
                    height: 30,
                    padding: "0 12px",
                    borderRadius: 15,
                    display: "flex",
                    alignItems: "center",
                    gap: 7,
                    fontSize: 15,
                    color: statusOn > 0.5 ? "#2f9b6a" : muted,
                    background:
                      statusOn > 0.5
                        ? "rgba(63,179,127,0.14)"
                        : dark
                          ? "rgba(255,236,220,0.06)"
                          : "rgba(70,40,20,0.05)",
                    transform: `scale(${frame >= B.status ? mix(0.8, 1, statusOn) : 1})`,
                  }}
                >
                  <span
                    style={{
                      width: 7,
                      height: 7,
                      borderRadius: 4,
                      background: statusOn > 0.5 ? "#3fb37f" : faint,
                    }}
                  />
                  {statusOn > 0.5 ? "Active" : "Draft"}
                </div>
              </div>

              {[
                {
                  label: "Title",
                  body: (
                    <div style={inputStyle(nameCaret)}>
                      {typedName ? (
                        <span style={{ whiteSpace: "pre" }}>{typedName}</span>
                      ) : (
                        <span style={{ color: faint }}>
                          {nameCaret ? "" : "Short sleeve t-shirt"}
                        </span>
                      )}
                      {caret(nameCaret)}
                    </div>
                  ),
                },
                {
                  label: "Price",
                  body: (
                    <div style={inputStyle(priceCaret)}>
                      <span
                        style={{
                          fontFamily: mono.fontFamily,
                          fontSize: 19,
                          whiteSpace: "pre",
                          color: typedPrice ? ink : faint,
                        }}
                      >
                        {typedPrice || "$0.00"}
                      </span>
                      {caret(priceCaret)}
                      <span style={{ flex: 1 }} />
                      <span
                        style={{
                          fontFamily: mono.fontFamily,
                          fontSize: 15,
                          color: muted,
                        }}
                      >
                        USD
                      </span>
                    </div>
                  ),
                },
                {
                  label: "Category",
                  body: (
                    <div style={inputStyle(false)}>
                      <span
                        style={{
                          height: 30,
                          padding: "0 12px",
                          borderRadius: 8,
                          background: dark
                            ? "rgba(255,236,220,0.08)"
                            : "rgba(70,40,20,0.06)",
                          display: "flex",
                          alignItems: "center",
                          fontSize: 16,
                        }}
                      >
                        Ceramics
                      </span>
                      <span
                        style={{
                          height: 30,
                          padding: "0 12px",
                          borderRadius: 8,
                          background: dark
                            ? "rgba(255,236,220,0.08)"
                            : "rgba(70,40,20,0.06)",
                          display: "flex",
                          alignItems: "center",
                          fontSize: 16,
                        }}
                      >
                        Tableware
                      </span>
                      <span style={{ flex: 1 }} />
                      <svg
                        viewBox="0 0 24 24"
                        width={18}
                        height={18}
                        aria-hidden
                      >
                        <path d="m7 10 5 5 5-5" {...line(muted)} />
                      </svg>
                    </div>
                  ),
                },
              ].map((f, i) => (
                <div
                  key={f.label}
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    top: fieldsTop + i * fieldGap,
                    opacity: fieldIn(i + 2),
                    transform: `translateY(${mix(16, 0, fieldIn(i + 2))}px)`,
                  }}
                >
                  <div style={labelStyle}>{f.label}</div>
                  {f.body}
                </div>
              ))}

              <div
                style={{
                  position: "absolute",
                  left: 0,
                  right: 0,
                  bottom: portrait ? 36 : 38,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-end",
                  gap: 10,
                  opacity: fieldIn(5),
                  transform: `translateY(${mix(14, 0, fieldIn(5))}px)`,
                }}
              >
                <span style={{ fontSize: 16, color: muted, flex: 1 }}>
                  Unsaved changes
                </span>
                <div
                  style={{
                    height: 48,
                    padding: "0 20px",
                    borderRadius: 14,
                    border: `1px solid ${hair}`,
                    display: "flex",
                    alignItems: "center",
                    fontSize: 18,
                    color: ink,
                  }}
                >
                  Discard
                </div>
                <div
                  style={{
                    height: 48,
                    padding: "0 22px",
                    borderRadius: 14,
                    background: ink,
                    color: btnInk,
                    display: "flex",
                    alignItems: "center",
                    fontSize: 18,
                    transform: `scale(${saveDip})`,
                    boxShadow: dark
                      ? "inset 0 1px 0 rgba(255,255,255,0.5), 0 8px 20px rgba(0,0,0,0.3)"
                      : "inset 0 1px 0 rgba(255,255,255,0.15), 0 8px 20px rgba(28,22,18,0.2)",
                  }}
                >
                  Add to store
                </div>
              </div>
            </div>

            {tileInfo({ name, price }, tileContent)}
          </div>

          {frame >= B.carry - 2 && !placed ? (
            <div
              style={{
                position: "absolute",
                left: ix - carriedW / 2,
                top: iy - carriedH / 2,
                width: carriedW,
                height: carriedH,
                borderRadius: mix(14, mediaCard.r, Math.min(1, drop)),
                overflow: "hidden",
                transform: `rotate(${carriedRot}deg)`,
                opacity: ramp(frame, B.carry - 2, 6),
                boxShadow: `0 ${mix(30, 4, Math.min(1, drop))}px ${mix(50, 10, Math.min(1, drop))}px rgba(30,10,0,${dark ? 0.55 : 0.3})`,
                border: `${mix(4, 0, Math.min(1, drop))}px solid #ffffff`,
                filter: "url(#btc-carry)",
              }}
            >
              <Img
                src={images[0]}
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            </div>
          ) : null}

          <div
            style={{
              position: "absolute",
              left: pointerX,
              top: pointerY,
              opacity: cursorOpacity,
              transformOrigin: "5px 4px",
              transform: `scale(${cursorScale})`,
              filter: "drop-shadow(0 4px 8px rgba(0,0,0,0.3))",
            }}
          >
            <Cursor size={32} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

export default ButtonToCard;

"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const sans = loadSans("normal", { weights: ["400"], subsets: ["latin"] });
const serif = loadSerif("normal", { weights: ["400"], subsets: ["latin"] });

export interface BookingHost {
  name: string;
  email?: string;
  /** Two-letter monogram for the avatar. */
  initials?: string;
}

export interface BookingEvent {
  title: string;
  description?: string;
  durations?: string[];
  /** Index into `durations` that is booked. */
  duration?: number;
  location?: string;
  timezone?: string;
  /** Month shown on the calendar. */
  month?: string;
  year?: number;
  /** Weekday of the 1st, 0 = Sunday. */
  firstWeekday?: number;
  daysInMonth?: number;
  /** First bookable day; weekends are never bookable. */
  firstAvailable?: number;
}

export interface CalendarBookingProps {
  host?: BookingHost;
  event?: BookingEvent;
  slots?: string[];
  /** Slot the cursor picks. Defaults to "10:30am" or the 4th slot. */
  pick?: string;
  /** Day of the month the cursor picks. */
  day?: number;
  accent?: string;
  speed?: number;
  theme?: "light" | "dark";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

const DEFAULT_HOST: BookingHost = {
  name: "Maya Chen",
  email: "maya@kitebase.io",
  initials: "MC",
};

const DEFAULT_EVENT: BookingEvent = {
  title: "Product walkthrough",
  description:
    "Thirty minutes on the registry, live previews and the render pipeline. Bring the product you want to launch.",
  durations: ["15m", "30m", "45m"],
  duration: 1,
  location: "Video call",
  timezone: "Europe/Lisbon",
  month: "June",
  year: 2026,
  firstWeekday: 1,
  daysInMonth: 30,
  firstAvailable: 9,
};

const DEFAULT_SLOTS = [
  "9:00am",
  "9:30am",
  "10:00am",
  "10:30am",
  "11:00am",
  "1:30pm",
  "2:00pm",
  "3:30pm",
];

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const WEEKDAY_LONG = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];

const SPR = {
  heavy: { mass: 1, damping: 26, stiffness: 120 },
  card: { mass: 0.8, damping: 18, stiffness: 160 },
  chip: { mass: 0.5, damping: 12, stiffness: 200 },
  morph: { damping: 200 },
};
const EASE = {
  enter: Easing.bezier(0.32, 0.72, 0, 1),
  soft: Easing.bezier(0.22, 1, 0.36, 1),
  move: Easing.bezier(0.65, 0, 0.35, 1),
  exit: Easing.bezier(0.55, 0, 1, 0.45),
  camera: Easing.bezier(0.87, 0, 0.13, 1),
};
const CL = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
const tween = (
  f: number,
  from: number,
  len: number,
  easing: (t: number) => number,
) => interpolate(f, [from, from + len], [0, 1], { ...CL, easing });

const BEAT = {
  card: 0,
  cursor: 8,
  day: 34,
  slot: 66,
  confirm: 88,
};

const PALETTES = {
  light: {
    card: "#FFFFFF",
    text: "#18181B",
    muted: "#71717A",
    faint: "#B4B4BB",
    line: "rgba(24,24,27,0.08)",
    tint: "rgba(24,24,27,0.045)",
    ink: "#18181B",
    inkText: "#FFFFFF",
    shadow:
      "0 0 0 1px rgba(24,24,27,0.06), 0 2px 4px rgba(24,24,27,0.04), 0 36px 80px -24px rgba(20,24,60,0.32)",
    ghost: "0 0 0 1px rgba(24,24,27,0.1), 0 1px 2px rgba(24,24,27,0.05)",
  },
  dark: {
    card: "#141518",
    text: "#EDEDEF",
    muted: "#8E9097",
    faint: "#4E5057",
    line: "rgba(255,255,255,0.07)",
    tint: "rgba(255,255,255,0.05)",
    ink: "#EDEDEF",
    inkText: "#141518",
    shadow:
      "0 0 0 1px rgba(255,255,255,0.09), inset 0 1px 0 rgba(255,255,255,0.06), 0 40px 90px -24px rgba(0,0,0,0.75)",
    ghost: "0 0 0 1px rgba(255,255,255,0.1)",
  },
};
type Palette = (typeof PALETTES)["light"];

const LIGHT_GROUND: Partial<GradientParams> = {
  colors: ["#a9bcff", "#3b5bfd", "#22349e", "#c9d6ff"],
  background: "#f1f1ef",
};

function withAlpha(color: string, alpha: number) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? hex.replace(/(.)/g, "$1$1") : hex;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) return color;
  const n = Number.parseInt(full, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}

type IconName = "clock" | "video" | "globe" | "left" | "right" | "check";

function Icon({
  name,
  color,
  size = 18,
}: {
  name: IconName;
  color: string;
  size?: number;
}) {
  const p = {
    fill: "none",
    stroke: color,
    strokeWidth: 1.5,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
  };
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      aria-hidden
      style={{ display: "block", flexShrink: 0 }}
    >
      {name === "clock" && (
        <>
          <circle cx={12} cy={12} r={8.5} {...p} />
          <path d="M12 7.5V12l3 2" {...p} />
        </>
      )}
      {name === "video" && (
        <>
          <rect x={3} y={6.5} width={12.5} height={11} rx={2.5} {...p} />
          <path d="M15.5 10.5l5-3v9l-5-3" {...p} />
        </>
      )}
      {name === "globe" && (
        <>
          <circle cx={12} cy={12} r={8.5} {...p} />
          <path
            d="M3.5 12h17M12 3.5c2.8 3 2.8 14 0 17M12 3.5c-2.8 3-2.8 14 0 17"
            {...p}
          />
        </>
      )}
      {name === "left" && <path d="M14.5 6.5L9 12l5.5 5.5" {...p} />}
      {name === "right" && <path d="M9.5 6.5L15 12l-5.5 5.5" {...p} />}
      {name === "check" && <path d="M6 12.5l4 4 8-9" {...p} />}
    </svg>
  );
}

function Cursor({
  x,
  y,
  press,
  opacity,
}: {
  x: number;
  y: number;
  press: number;
  opacity: number;
}) {
  return (
    <svg
      width={24}
      height={28}
      viewBox="0 0 20 24"
      aria-hidden
      style={{
        position: "absolute",
        left: x - 2.2,
        top: y - 2.2,
        opacity,
        transformOrigin: "2px 2px",
        transform: `scale(${1 - 0.04 * press})`,
        filter: "drop-shadow(0 2px 3px rgba(0,0,0,0.3))",
        overflow: "visible",
      }}
    >
      <path
        d="M2 2 L2 19.5 L6.6 15.4 L9.8 22.4 L12.9 21 L9.8 14.2 L16 14.2 Z"
        fill="#FFFFFF"
        stroke="#111114"
        strokeWidth={1.2}
        strokeLinejoin="round"
      />
    </svg>
  );
}

function geometry(tall: boolean, gridRows: number) {
  if (tall) {
    const cell = 64;
    const gap = 8;
    const hostH = 206;
    const calY = hostH + 24;
    const gridY = calY + 84;
    const gridBottom = gridY + gridRows * (cell + gap);
    const slotY = gridBottom + 18;
    return {
      cell,
      gap,
      host: { x: 0, y: 0, w: 560, h: hostH },
      calX: 28,
      calY,
      weekY: calY + 50,
      gridY,
      slotHeadY: slotY,
      slotX: 28,
      slotY: slotY + 44,
      slotCols: 2,
      slotW: 246,
      slotH: 46,
      slotStep: 54,
      narrow: { w: 560, h: slotY },
      wide: { w: 560, h: slotY + 44 + 4 * 54 + 16 },
      done: { w: 560, h: 440 },
    };
  }
  const cell = 56;
  const gap = 6;
  const hostW = 300;
  const calX = hostW + 32;
  const gridW = 7 * cell + 6 * gap;
  const narrowW = calX + gridW + 32;
  return {
    cell,
    gap,
    host: { x: 0, y: 0, w: hostW, h: 488 },
    calX,
    calY: 30,
    weekY: 86,
    gridY: 122,
    slotHeadY: 30,
    slotX: narrowW + 24,
    slotY: 86,
    slotCols: 1,
    slotW: 212,
    slotH: 42,
    slotStep: 50,
    narrow: { w: narrowW, h: 488 },
    wide: { w: narrowW + 260, h: 488 },
    done: { w: 620, h: 424 },
  };
}

export function CalendarBooking({
  host = DEFAULT_HOST,
  event: eventProp,
  slots = DEFAULT_SLOTS,
  pick,
  day = 18,
  accent = "#3B5BFD",
  speed = 1,
  theme = "light",
  ground,
  groundParams,
}: CalendarBookingProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const tall = height > width;
  const SW = tall ? 600 : 1280;
  const SH = tall ? (600 * height) / width : 720;
  const k = width / SW;
  const dark = theme === "dark";
  const c = PALETTES[theme];
  const event = { ...DEFAULT_EVENT, ...eventProp };
  const first = event.firstWeekday ?? 1;
  const days = event.daysInMonth ?? 30;
  const gridRows = Math.ceil((first + days) / 7);
  const G = geometry(tall, gridRows);
  const sp = (at: number, config: Record<string, number>) =>
    spring({ frame: frame - at, fps, config });
  const isOpen = (d: number) => {
    const wd = (first + d - 1) % 7;
    return d >= (event.firstAvailable ?? 1) && wd !== 0 && wd !== 6;
  };
  const shown = slots.slice(0, tall ? 8 : 7);
  const wanted = shown.indexOf(pick ?? "10:30am");
  const pickIdx = wanted >= 0 ? wanted : Math.min(3, shown.length - 1);
  const pickLabel = shown[pickIdx] ?? "";

  const cardIn = sp(BEAT.card, SPR.heavy);
  const cardOp = tween(frame, BEAT.card, 10, EASE.enter);
  const dayFill = sp(BEAT.day, SPR.chip);
  const widen = sp(BEAT.day + 2, SPR.heavy);
  const split = sp(BEAT.slot + 1, SPR.card);
  const morph = sp(BEAT.confirm + 2, SPR.morph);
  const cam =
    1 +
    0.03 * tween(frame, 6, 80, EASE.camera) +
    0.015 * tween(frame, BEAT.confirm + 10, 60, EASE.camera);

  const bookW = G.narrow.w + (G.wide.w - G.narrow.w) * widen;
  const bookH = G.narrow.h + (G.wide.h - G.narrow.h) * widen;
  const cardW = bookW + (G.done.w - bookW) * morph;
  const cardH = bookH + (G.done.h - bookH) * morph;
  const cardX = (SW - cardW) / 2;
  const cardY = (SH - cardH) / 2 + (1 - cardIn) * 36;

  const cellPos = (d: number) => {
    const idx = first + d - 1;
    return {
      x: G.calX + (idx % 7) * (G.cell + G.gap),
      y: G.gridY + Math.floor(idx / 7) * (G.cell + G.gap),
    };
  };
  const slotPos = (i: number) => ({
    x: G.slotX + (i % G.slotCols) * (G.slotW + 12),
    y: G.slotY + Math.floor(i / G.slotCols) * G.slotStep,
  });
  const narrowOrigin = { x: (SW - G.narrow.w) / 2, y: (SH - G.narrow.h) / 2 };
  const wideOrigin = { x: (SW - G.wide.w) / 2, y: (SH - G.wide.h) / 2 };
  const dc = cellPos(day);
  const dayPt = {
    x: narrowOrigin.x + dc.x + G.cell / 2 + 4,
    y: narrowOrigin.y + dc.y + G.cell / 2 + 4,
  };
  const ps = slotPos(pickIdx);
  const half = (G.slotW - 8) / 2;
  const slotPt = {
    x: wideOrigin.x + ps.x + G.slotW / 2 + 6,
    y: wideOrigin.y + ps.y + G.slotH / 2 + 4,
  };
  const confirmPt = {
    x: wideOrigin.x + ps.x + half + 8 + half / 2 + 4,
    y: slotPt.y,
  };
  const start = tall ? { x: 660, y: 1120 } : { x: 1360, y: 800 };
  const legs = [
    { at: BEAT.cursor, from: start, to: dayPt, arc: 1 },
    { at: BEAT.slot - 20, from: dayPt, to: slotPt, arc: -1 },
    { at: BEAT.confirm - 16, from: slotPt, to: confirmPt, arc: 1 },
    {
      at: BEAT.confirm + 10,
      from: confirmPt,
      to: { x: confirmPt.x + 60, y: confirmPt.y + 110 },
      arc: -1,
    },
  ];
  let curX = start.x;
  let curY = start.y;
  for (const leg of legs) {
    const p = sp(leg.at, SPR.heavy);
    const dx = leg.to.x - leg.from.x;
    const dy = leg.to.y - leg.from.y;
    const len = Math.hypot(dx, dy) || 1;
    const bend = Math.sin(clamp01(p) * Math.PI) * Math.min(60, len * 0.14);
    curX += dx * p + (-dy / len) * bend * leg.arc;
    curY += dy * p + (dx / len) * bend * leg.arc;
  }
  const pressOf = (at: number) =>
    clamp01(sp(at - 2, SPR.chip) - sp(at + 3, SPR.chip));
  const press = Math.max(
    pressOf(BEAT.day),
    pressOf(BEAT.slot),
    pressOf(BEAT.confirm),
  );
  const curOp =
    tween(frame, BEAT.cursor, 5, EASE.enter) *
    (1 - tween(frame, BEAT.confirm + 22, 10, EASE.exit));

  const bookOp = 1 - tween(frame, BEAT.confirm + 2, 7, EASE.exit);
  const doneOp = tween(frame, BEAT.confirm + 7, 9, EASE.enter);
  const slotHover = tween(frame, BEAT.slot - 6, 4, EASE.enter);
  const wd = (first + day - 1) % 7;
  const end = shown[pickIdx + 1] ?? "";

  return (
    <AbsoluteFill
      style={{
        overflow: "hidden",
        fontFamily: sans.fontFamily,
        WebkitFontSmoothing: "antialiased",
      }}
    >
      <GshGround
        preset={ground ?? (dark ? "film-blue" : "glasswork")}
        params={groundParams ?? (dark ? undefined : LIGHT_GROUND)}
        timeOffset={2}
        timeScale={0.45}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: SW,
          height: SH,
          transform: `scale(${k})`,
          transformOrigin: "0 0",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${cam})`,
            transformOrigin: `${SW / 2}px ${SH / 2}px`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: cardX,
              top: cardY,
              width: cardW,
              height: cardH,
              borderRadius: 22,
              background: c.card,
              boxShadow: c.shadow,
              overflow: "hidden",
              opacity: cardOp,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: G.wide.w,
                height: G.wide.h,
                opacity: bookOp,
                transform: `scale(${1 - 0.03 * morph})`,
                transformOrigin: "50% 40%",
              }}
            >
              <HostPanel host={host} event={event} c={c} tall={tall} G={G} />
              <div
                style={{
                  position: "absolute",
                  left: G.calX,
                  top: G.calY,
                  width: 7 * G.cell + 6 * G.gap,
                  height: 32,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                }}
              >
                <div style={{ fontSize: 19, color: c.text }}>
                  {event.month}{" "}
                  <span style={{ color: c.muted }}>{event.year}</span>
                </div>
                <div style={{ display: "flex", gap: 14 }}>
                  <Icon name="left" color={c.faint} size={20} />
                  <Icon name="right" color={c.text} size={20} />
                </div>
              </div>
              {WEEKDAYS.map((w, i) => (
                <div
                  key={w}
                  style={{
                    position: "absolute",
                    left: G.calX + i * (G.cell + G.gap),
                    top: G.weekY,
                    width: G.cell,
                    textAlign: "center",
                    fontSize: 16,
                    color: c.muted,
                  }}
                >
                  {w}
                </div>
              ))}
              {Array.from({ length: days }, (_, i) => i + 1).map((d) => {
                const idx = first + d - 1;
                const open = isOpen(d);
                const sel = d === day;
                const pos = cellPos(d);
                const appear = tween(
                  frame,
                  3 + (idx % 7) * 0.7 + Math.floor(idx / 7) * 1.6,
                  10,
                  EASE.soft,
                );
                return (
                  <div
                    key={d}
                    style={{
                      position: "absolute",
                      left: pos.x,
                      top: pos.y,
                      width: G.cell,
                      height: G.cell,
                      borderRadius: 12,
                      background: open ? c.tint : "transparent",
                      opacity: appear,
                      transform: `translateY(${(1 - appear) * 8}px)`,
                    }}
                  >
                    {sel ? (
                      <div
                        style={{
                          position: "absolute",
                          inset: 0,
                          borderRadius: 12,
                          background: c.ink,
                          transform: `scale(${0.6 + 0.4 * dayFill})`,
                          opacity: clamp01(dayFill * 3),
                        }}
                      />
                    ) : null}
                    <div
                      style={{
                        position: "absolute",
                        inset: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontSize: 17,
                        fontVariantNumeric: "tabular-nums",
                        color:
                          sel && dayFill > 0.3
                            ? c.inkText
                            : open
                              ? c.text
                              : c.faint,
                      }}
                    >
                      {d}
                    </div>
                  </div>
                );
              })}
              <div
                style={{
                  position: "absolute",
                  left: tall ? 0 : G.narrow.w,
                  top: tall ? G.narrow.h - 1 : 0,
                  width: tall ? G.wide.w : 1,
                  height: tall ? 1 : G.wide.h,
                  background: c.line,
                  opacity: clamp01(widen * 2),
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: G.slotX,
                  top: G.slotHeadY,
                  height: 32,
                  display: "flex",
                  alignItems: "center",
                  fontSize: 19,
                  color: c.text,
                  opacity: tween(frame, BEAT.day + 8, 10, EASE.enter),
                }}
              >
                {WEEKDAY_LONG[wd].slice(0, 3)}&nbsp;
                <span style={{ color: c.muted }}>{day}</span>
              </div>
              {shown.map((s, i) => {
                const inn = sp(BEAT.day + 10 + i * 2, SPR.card);
                const picked = i === pickIdx;
                const sv = picked ? split : 0;
                const pos = slotPos(i);
                const timeW = G.slotW - (G.slotW - half) * sv;
                const base: React.CSSProperties = {
                  position: "absolute",
                  top: pos.y,
                  height: G.slotH,
                  borderRadius: 10,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 8,
                  fontSize: 17,
                  boxSizing: "border-box",
                  overflow: "hidden",
                  whiteSpace: "nowrap",
                  fontVariantNumeric: "tabular-nums",
                };
                return (
                  <div key={s}>
                    <div
                      style={{
                        ...base,
                        left: pos.x + (1 - inn) * 18,
                        width: timeW,
                        opacity: clamp01(inn * 1.5),
                        color: c.text,
                        background: picked && sv > 0.05 ? c.tint : c.card,
                        boxShadow:
                          picked && slotHover > 0 && sv < 0.5
                            ? `0 0 0 1px ${c.text}`
                            : c.ghost,
                      }}
                    >
                      {s}
                    </div>
                    {picked && sv > 0.01 ? (
                      <div
                        style={{
                          ...base,
                          left: pos.x + timeW + 8,
                          width: Math.max(0, G.slotW - timeW - 8),
                          background: accent,
                          color: "#FFFFFF",
                          opacity: clamp01(sv * 2),
                          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.16)",
                          transform: `scale(${1 - 0.04 * pressOf(BEAT.confirm)})`,
                        }}
                      >
                        Confirm
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>
            {morph > 0.01 ? (
              <SuccessView
                frame={frame - BEAT.confirm - 6}
                fps={fps}
                c={c}
                accent={accent}
                opacity={doneOp}
                left={(cardW - G.done.w) / 2}
                top={(cardH - G.done.h) / 2}
                w={G.done.w}
                h={G.done.h}
                host={host}
                event={event}
                when={`${WEEKDAY_LONG[wd]}, ${event.month} ${day}`}
                time={`${pickLabel}${end ? ` – ${end}` : ""}`}
              />
            ) : null}
          </div>
          <Cursor x={curX} y={curY} press={press} opacity={curOp} />
        </div>
      </div>
    </AbsoluteFill>
  );
}

function HostPanel({
  host,
  event,
  c,
  tall,
  G,
}: {
  host: BookingHost;
  event: BookingEvent;
  c: Palette;
  tall: boolean;
  G: ReturnType<typeof geometry>;
}) {
  const meta: [IconName, string | undefined][] = [
    ["clock", event.durations?.[event.duration ?? 0]?.replace("m", " min")],
    ["video", event.location],
    ["globe", event.timezone],
  ];
  return (
    <div
      style={{
        position: "absolute",
        left: G.host.x,
        top: G.host.y,
        width: G.host.w,
        height: G.host.h,
        boxSizing: "border-box",
        padding: tall ? "28px 28px" : "32px 30px",
        boxShadow: tall
          ? `inset 0 -1px 0 ${c.line}`
          : `inset -1px 0 0 ${c.line}`,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 18,
            background: c.tint,
            boxShadow: `inset 0 0 0 1px ${c.line}`,
            color: c.text,
            fontSize: 14.5,
            letterSpacing: "0.02em",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {host.initials ?? host.name.slice(0, 2).toUpperCase()}
        </div>
        <span style={{ fontSize: 17, color: c.muted }}>{host.name}</span>
      </div>
      <div
        style={{
          marginTop: tall ? 16 : 22,
          fontFamily: serif.fontFamily,
          fontSize: tall ? 38 : 40,
          lineHeight: 1.05,
          letterSpacing: "-0.01em",
          color: c.text,
        }}
      >
        {event.title}
      </div>
      {!tall && event.description ? (
        <div
          style={{
            marginTop: 14,
            fontSize: 16,
            lineHeight: 1.5,
            color: c.muted,
          }}
        >
          {event.description}
        </div>
      ) : null}
      <div
        style={{
          marginTop: tall ? 22 : 26,
          display: "flex",
          flexDirection: tall ? "row" : "column",
          gap: tall ? 20 : 14,
        }}
      >
        {meta.map(([icon, label]) =>
          label ? (
            <div
              key={icon}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                fontSize: 16,
                color: c.text,
                whiteSpace: "nowrap",
              }}
            >
              <Icon name={icon} color={c.muted} />
              {label}
            </div>
          ) : null,
        )}
      </div>
    </div>
  );
}

function SuccessView({
  frame,
  fps,
  c,
  accent,
  opacity,
  left,
  top,
  w,
  h,
  host,
  event,
  when,
  time,
}: {
  frame: number;
  fps: number;
  c: Palette;
  accent: string;
  opacity: number;
  left: number;
  top: number;
  w: number;
  h: number;
  host: BookingHost;
  event: BookingEvent;
  when: string;
  time: string;
}) {
  const disc = spring({ frame: frame - 2, fps, config: SPR.chip });
  const tick = tween(frame, 6, 10, EASE.enter);
  const item = (i: number): React.CSSProperties => {
    const p = tween(frame, 4 + i * 3, 12, EASE.soft);
    return { opacity: p, transform: `translateY(${(1 - p) * 10}px)` };
  };
  const rows: [string, React.ReactNode][] = [
    [
      "When",
      <>
        {when}
        <div style={{ color: c.muted, marginTop: 2 }}>
          {time} · {event.timezone}
        </div>
      </>,
    ],
    [
      "With",
      <>
        {host.name}
        <div style={{ color: c.muted, marginTop: 2 }}>{host.email}</div>
      </>,
    ],
    ["Where", event.location],
  ];
  return (
    <div
      style={{
        position: "absolute",
        left,
        top,
        width: w,
        height: h,
        boxSizing: "border-box",
        padding: "40px 40px",
        opacity,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <div
          style={{
            width: 44,
            height: 44,
            borderRadius: 22,
            background: withAlpha(accent, 0.12),
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${0.5 + 0.5 * disc})`,
            opacity: clamp01(disc * 2),
          }}
        >
          <svg width={24} height={24} viewBox="0 0 24 24" aria-hidden>
            <path
              d="M6 12.5l4 4 8-9"
              fill="none"
              stroke={accent}
              strokeWidth={1.75}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={20}
              strokeDashoffset={20 * (1 - tick)}
            />
          </svg>
        </div>
        <div style={{ fontSize: 17, color: c.muted, ...item(0) }}>
          Invite sent to your inbox
        </div>
      </div>
      <div
        style={{
          ...item(1),
          marginTop: 26,
          fontFamily: serif.fontFamily,
          fontSize: 46,
          lineHeight: 1.05,
          letterSpacing: "-0.01em",
          color: c.text,
        }}
      >
        You’re booked with {host.name.split(" ")[0]}
      </div>
      <div
        style={{
          marginTop: 28,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {rows.map(([label, value], i) => (
          <div
            key={label}
            style={{
              display: "flex",
              padding: "14px 0",
              boxShadow: `inset 0 1px 0 ${c.line}`,
              fontSize: 17,
              lineHeight: 1.35,
              color: c.text,
              ...item(2 + i),
            }}
          >
            <div style={{ width: 92, flexShrink: 0, color: c.muted }}>
              {label}
            </div>
            <div>{value}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadOnest } from "@remotion/google-fonts/Onest";
import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const onest = loadOnest("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const CAM = Easing.bezier(0.87, 0, 0.13, 1);
const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const MORPH = { damping: 200 };

const B = {
  enter: -8,
  rows: 0,
  title: 6,
  zoom: 24,
  cursor: 42,
  click: 66,
  open: 70,
  type: 78,
  commit: 120,
  flood: 122,
  label: 130,
  pull: 132,
  end: 168,
};

const ramp = (f: number, start: number, dur: number, easing = ENTER) =>
  interpolate(f, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

function Chevron({ dir, color }: { dir: "l" | "r"; color: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={18}
      height={18}
      aria-hidden
      style={{ display: "block" }}
    >
      <path
        d={dir === "l" ? "m14.5 6-6 6 6 6" : "m9.5 6 6 6-6 6"}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Pointer({ size, dark }: { size: number; dark: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      style={{
        display: "block",
        filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.3))",
      }}
      aria-hidden
    >
      <path
        d="M5 3.2v16.2l4.3-4.1 2.8 6.3 2.6-1.1-2.8-6.2h6z"
        fill={dark ? "#ffffff" : "#16110d"}
        stroke={dark ? "#16110d" : "#ffffff"}
        strokeWidth={1.3}
        strokeLinejoin="round"
      />
    </svg>
  );
}

export interface CalendarPickProps {
  theme?: "dark" | "light";
  accent?: string;
  title?: string;
  month?: string;
  year?: string;
  firstWeekday?: number;
  daysInMonth?: number;
  today?: number;
  pickDay?: number;
  timeRange?: string;
  eventLabel?: string;
  busyDays?: number[];
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

export function CalendarPick({
  theme = "dark",
  accent = "#F26A2E",
  title = "Launch day, booked.",
  month = "June",
  year = "2026",
  firstWeekday = 0,
  daysInMonth = 30,
  today = 9,
  pickDay = 18,
  timeRange = "10:00 AM – 4:00 PM",
  eventLabel = "Launch",
  busyDays = [3, 11, 12, 22, 25, 29],
  ground,
  groundParams,
}: CalendarPickProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const dark = theme === "dark";
  const portrait = height > width * 1.2;
  const stageW = portrait ? 1080 : 1280;
  const stageH = portrait ? 1920 : 720;
  const s = width / stageW;

  const ink = dark ? "#f6f1ec" : "#1b1612";
  const soft = dark ? "rgba(246,241,236,0.7)" : "rgba(27,22,18,0.66)";
  const muted = dark ? "rgba(246,241,236,0.4)" : "rgba(27,22,18,0.38)";
  const hair = dark ? "rgba(255,255,255,0.08)" : "rgba(40,24,10,0.08)";
  const tile = dark ? "rgba(255,255,255,0.045)" : "rgba(60,36,16,0.04)";

  const W = 760;
  const padX = 30;
  const headH = 92;
  const weekH = 34;
  const colW = (W - padX * 2) / 7;
  const rowH = 84;
  const lead = ((firstWeekday % 7) + 7) % 7;
  const rows = Math.ceil((lead + daysInMonth) / 7);
  const H = headH + weekH + rows * rowH + 26;
  const gridTop = headH + weekH;
  const cellOf = (d: number) => {
    const i = lead + d - 1;
    return { col: i % 7, row: Math.floor(i / 7) };
  };
  const pick = cellOf(Math.max(1, Math.min(daysInMonth, pickDay)));
  const cellX = padX + pick.col * colW;
  const cellY = gridTop + pick.row * rowH;
  const inset = 5;

  const enter = spring({ frame: frame - B.enter, fps, config: CARD });
  const enterBlur = mix(10, 0, ramp(frame, B.enter, 15));
  const zoom = ramp(frame, B.zoom, 36, CAM);
  const pullBack = spring({ frame: frame - B.pull, fps, config: HEAVY });
  const zMax = portrait ? 1.9 : 1.75;
  const zRest = portrait ? 1.06 : 1.5;
  const Z =
    mix(mix(1, zMax, zoom), zRest, pullBack) *
    (1 + 0.025 * ramp(frame, B.pull + 20, B.end - B.pull - 20, Easing.linear)) *
    (portrait ? 1.25 : 1);
  const spanCols = Math.min(3, 6 - pick.col);
  const focusX = mix(W / 2, cellX + colW * (0.5 + spanCols / 2), zoom);
  const focusY = mix(H / 2, cellY + rowH / 2, zoom);
  const fX = mix(
    focusX,
    mix(W / 2, cellX + colW / 2, portrait ? 0.05 : 0.7),
    pullBack,
  );
  const fY = mix(focusY, mix(H / 2, cellY + rowH / 2, 0.7), pullBack);
  const screenX = stageW / 2;
  const screenY = portrait ? 1180 : 372;
  const rotX =
    mix(22, 0, enter) + mix(0, 7, zoom) * (1 - pullBack) + 3 * pullBack;
  const rotZ = mix(-5, 0, enter) + mix(0, -1.5, zoom) * (1 - pullBack);
  const rotY = mix(0, -8, zoom) * (1 - pullBack) - 4 * pullBack;

  const cStart = { x: W + 120, y: H + 80 };
  const cEnd = { x: cellX + colW * 0.56, y: cellY + rowH * 0.5 };
  const cP = ramp(frame, B.cursor, 24, MOVE);
  const cPrev = ramp(frame - 1, B.cursor, 24, MOVE);
  const exitP = ramp(frame, B.commit, 18, MOVE);
  const cX = mix(cStart.x, cEnd.x, cP) + 46 * exitP;
  const cY =
    mix(cStart.y, cEnd.y, cP) - Math.sin(Math.PI * cP) * 46 + 52 * exitP;
  const cBlur = Math.min(3, Math.abs(cP - cPrev) * 900 * 0.03);
  const clickDip = spring({ frame: frame - B.click, fps, config: CHIP });
  const clickUp = spring({ frame: frame - B.click - 4, fps, config: CHIP });
  const press = 1 - 0.12 * clickDip + 0.12 * clickUp;
  const ripple = ramp(frame, B.click, 18, ENTER);

  const openP = spring({ frame: frame - B.open, fps, config: CARD });
  const closeP = spring({ frame: frame - B.commit, fps, config: MORPH });
  const inputW = mix(
    colW - inset * 2,
    colW * (spanCols + 1) - inset * 2,
    openP * (1 - closeP),
  );
  const inputOn = frame >= B.open && closeP < 0.98;
  const chars = Math.max(
    0,
    Math.min(timeRange.length, Math.floor((frame - B.type) / 2)),
  );
  const typed = timeRange.slice(0, chars);
  const caretOn =
    Math.floor(frame / 8) % 2 === 0 ||
    (frame >= B.type && chars < timeRange.length);
  const flood = spring({ frame: frame - B.flood, fps, config: CHIP });
  const labelIn = ramp(frame, B.label, 12);
  const titleIn = ramp(frame, B.title, 15);

  const surface = dark
    ? "linear-gradient(180deg, rgba(34,27,23,0.94) 0%, rgba(22,18,16,0.96) 100%)"
    : "linear-gradient(180deg, #ffffff 0%, #fdfbf9 100%)";
  const shadow = dark
    ? "inset 0 1px 0 rgba(255,255,255,0.07), 0 2px 6px rgba(0,0,0,0.3), 0 30px 60px rgba(20,6,0,0.45), 0 80px 140px rgba(20,6,0,0.5)"
    : "inset 0 1px 0 #fff, 0 1px 2px rgba(80,40,10,0.06), 0 22px 50px rgba(120,60,20,0.1), 0 70px 130px rgba(160,80,30,0.16)";

  const weekdays = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];

  const days: React.ReactNode[] = [];
  for (let d = 1; d <= daysInMonth; d++) {
    const { col, row } = cellOf(d);
    const isPick = d === pickDay;
    const isToday = d === today;
    const weekend = col >= 5;
    const busy = busyDays.includes(d);
    const appear = ramp(frame, B.rows + row * 2 + col * 0.5, 12);
    const cellFlood = isPick ? flood : 0;
    const scale = isPick
      ? press * (1 + 0.06 * Math.sin(Math.PI * Math.min(1, cellFlood)))
      : 1;
    days.push(
      <div
        key={d}
        style={{
          position: "absolute",
          left: padX + col * colW + inset,
          top: gridTop + row * rowH + inset,
          width: colW - inset * 2,
          height: rowH - inset * 2,
          borderRadius: 14,
          background: weekend ? "transparent" : tile,
          opacity: appear,
          transform: `translateY(${mix(10, 0, appear)}px) scale(${scale})`,
        }}
      >
        {isPick ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: 14,
              background: `linear-gradient(180deg, color-mix(in oklab, ${accent} 86%, white) 0%, ${accent} 100%)`,
              boxShadow: `inset 0 1px 0 rgba(255,255,255,0.35), 0 10px 24px color-mix(in oklab, ${accent} 40%, transparent)`,
              opacity: Math.min(1, cellFlood),
              transform: `scale(${mix(0.4, 1, Math.min(1, cellFlood))})`,
            }}
          />
        ) : null}
        {isToday ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: 14,
              boxShadow: `inset 0 0 0 1.5px color-mix(in oklab, ${accent} 70%, transparent)`,
            }}
          />
        ) : null}
        <div
          style={{
            position: "absolute",
            left: 12,
            top: 9,
            fontSize: 24,
            letterSpacing: "-0.02em",
            fontWeight: 400,
            color:
              cellFlood > 0.5
                ? "#ffffff"
                : weekend
                  ? muted
                  : isToday
                    ? accent
                    : ink,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {d}
        </div>
        {busy ? (
          <div
            style={{
              position: "absolute",
              left: 13,
              bottom: 12,
              display: "flex",
              gap: 4,
            }}
          >
            <span
              style={{
                width: 16,
                height: 4,
                borderRadius: 2,
                background: `color-mix(in oklab, ${accent} 55%, transparent)`,
              }}
            />
            {d % 2 ? (
              <span
                style={{
                  width: 8,
                  height: 4,
                  borderRadius: 2,
                  background: muted,
                }}
              />
            ) : null}
          </div>
        ) : null}
        {isPick ? (
          <div
            style={{
              position: "absolute",
              left: 12,
              right: 8,
              bottom: 9,
              fontSize: 13,
              lineHeight: "16px",
              color: "#ffffff",
              opacity: labelIn,
              transform: `translateY(${mix(8, 0, labelIn)}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {eventLabel}
            <div
              style={{
                fontFamily: mono.fontFamily,
                fontSize: 11,
                opacity: 0.85,
              }}
            >
              {timeRange.split(" ")[0]}
            </div>
          </div>
        ) : null}
      </div>,
    );
  }

  const resolvedGround: GshPresetId =
    ground ?? (dark ? "hearth" : "paper-crease");
  const resolvedParams =
    groundParams ??
    (dark
      ? undefined
      : {
          kind: "mist",
          colors: ["#ff9a5a", "#ffc79c", "#fbe9da", "#e0622a"],
          background: "#f7f3ee",
        });

  return (
    <AbsoluteFill style={{ fontFamily: onest.fontFamily, overflow: "hidden" }}>
      <GshGround
        preset={resolvedGround}
        params={resolvedParams}
        timeOffset={5}
        timeScale={0.6}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: stageW,
          height: stageH,
          transform: `scale(${s})`,
          transformOrigin: "0 0",
          perspective: 2200,
        }}
      >
        {portrait ? (
          <div
            style={{
              position: "absolute",
              left: 90,
              right: 90,
              top: 260,
              overflow: "hidden",
              paddingBottom: 12,
            }}
          >
            <div
              style={{
                fontSize: 104,
                lineHeight: 1.0,
                letterSpacing: "-0.045em",
                fontWeight: 300,
                color: ink,
                transform: `translateY(${mix(110, 0, titleIn)}%)`,
              }}
            >
              {title}
            </div>
          </div>
        ) : null}
        <div
          style={{
            position: "absolute",
            left: screenX - fX * Z,
            top: screenY - fY * Z + mix(160, 0, enter),
            width: W,
            height: H,
            transformOrigin: "0 0",
            transform: `scale(${Z})`,
            opacity: ramp(frame, -6, 8),
            filter: enterBlur > 0.3 ? `blur(${enterBlur}px)` : undefined,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              transformStyle: "preserve-3d",
              transformOrigin: `${fX}px ${fY}px`,
              transform: `rotateX(${rotX}deg) rotateY(${rotY}deg) rotateZ(${rotZ}deg)`,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: 28,
                background: surface,
                boxShadow: shadow,
                border: `1px solid ${hair}`,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  left: padX + 4,
                  top: 30,
                  fontSize: 34,
                  letterSpacing: "-0.03em",
                  fontWeight: 300,
                  color: ink,
                }}
              >
                {month}
                <span style={{ color: muted, marginLeft: 10 }}>{year}</span>
              </div>
              <div
                style={{
                  position: "absolute",
                  right: padX,
                  top: 32,
                  display: "flex",
                  gap: 8,
                  alignItems: "center",
                }}
              >
                <div
                  style={{
                    height: 36,
                    padding: "0 14px",
                    borderRadius: 10,
                    border: `1px solid ${hair}`,
                    display: "flex",
                    alignItems: "center",
                    fontSize: 15,
                    color: soft,
                  }}
                >
                  Today
                </div>
                {(["l", "r"] as const).map((dir) => (
                  <div
                    key={dir}
                    style={{
                      width: 36,
                      height: 36,
                      borderRadius: 10,
                      border: `1px solid ${hair}`,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <Chevron dir={dir} color={soft} />
                  </div>
                ))}
              </div>
              {weekdays.map((wd, i) => (
                <div
                  key={wd}
                  style={{
                    position: "absolute",
                    left: padX + i * colW + 17,
                    top: headH,
                    height: weekH,
                    fontFamily: mono.fontFamily,
                    fontSize: 13,
                    letterSpacing: "0.06em",
                    color: i >= 5 ? muted : soft,
                  }}
                >
                  {wd}
                </div>
              ))}
              {days}
              <div
                style={{
                  position: "absolute",
                  left: cellX + colW * 0.56 - 30,
                  top: cellY + rowH * 0.5 - 30,
                  width: 60,
                  height: 60,
                  borderRadius: 30,
                  border: `1.5px solid ${accent}`,
                  opacity: frame >= B.click ? (1 - ripple) * 0.8 : 0,
                  transform: `scale(${mix(0.3, 1.4, ripple)})`,
                }}
              />
              {inputOn ? (
                <div
                  style={{
                    position: "absolute",
                    left: cellX + inset,
                    top: cellY + inset,
                    width: inputW,
                    height: rowH - inset * 2,
                    borderRadius: 14,
                    background: dark ? "#2a221d" : "#ffffff",
                    boxShadow: dark
                      ? `0 0 0 1.5px ${accent}, 0 0 0 5px color-mix(in oklab, ${accent} 22%, transparent), 0 14px 30px rgba(0,0,0,0.4)`
                      : `0 0 0 1.5px ${accent}, 0 0 0 5px color-mix(in oklab, ${accent} 16%, transparent), 0 14px 30px rgba(120,60,20,0.14)`,
                    overflow: "hidden",
                    opacity: Math.min(1, openP * 2),
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      left: 12,
                      top: 9,
                      fontSize: 24,
                      letterSpacing: "-0.02em",
                      color: ink,
                    }}
                  >
                    {pickDay}
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      left: 58,
                      top: 0,
                      bottom: 0,
                      display: "flex",
                      alignItems: "center",
                      fontSize: 21,
                      color: ink,
                      whiteSpace: "pre",
                      opacity: ramp(frame, B.open + 4, 8),
                    }}
                  >
                    {chars === 0 ? (
                      <span style={{ color: muted }}>Add time</span>
                    ) : (
                      typed
                    )}
                    <span
                      style={{
                        width: 2,
                        height: 24,
                        marginLeft: 2,
                        borderRadius: 1,
                        background: accent,
                        opacity: caretOn ? 1 : 0,
                      }}
                    />
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      right: 12,
                      top: 0,
                      bottom: 0,
                      display: "flex",
                      alignItems: "center",
                      fontFamily: mono.fontFamily,
                      fontSize: 12,
                      color: muted,
                      opacity: ramp(frame, B.type + 30, 8),
                    }}
                  >
                    ↵
                  </div>
                </div>
              ) : null}
            </div>
            <div
              style={{
                position: "absolute",
                left: cX,
                top: cY,
                opacity:
                  ramp(frame, B.cursor, 4) * (1 - ramp(frame, B.commit + 6, 9)),
                transform: `scale(${press})`,
                transformOrigin: "20% 15%",
                filter: cBlur > 0.3 ? `blur(${cBlur}px)` : undefined,
                display: frame >= B.cursor ? "block" : "none",
              }}
            >
              <Pointer size={26} dark={dark} />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

export default CalendarPick;

"use client";

import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type CameraLensProps = {
  softness?: number;
  bloom?: number;
  aberration?: number;
  vignette?: number;
  distortion?: number;
};

const DEFAULTS = {
  softness: 0.5,
  bloom: 0.5,
  aberration: 0.5,
  vignette: 0.5,
  distortion: 0.05,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_softness;
uniform float u_bloom;
uniform float u_aberration;
uniform float u_vignette;
uniform float u_distortion;

in vec2 v_uv;
out vec4 outColor;

const int SOFT_TAPS = 6;
const int GLARE_TAPS = 8;
const float GOLDEN = 2.39996323;

vec2 lensUv(vec2 direction, float distance) {
  vec2 q = direction * distance;
  q.x /= u_aspect;
  return q * 0.5 + 0.5;
}

vec2 spiral(int index, int count, float radius, float turn) {
  float angle = float(index) * GOLDEN + turn;
  float step = sqrt((float(index) + 0.5) / float(count)) * radius;
  return vec2(cos(angle) * step / u_aspect, sin(angle) * step);
}

vec4 softSample(vec2 uv, float radius) {
  vec4 sum = texture(u_scene, uv);
  if (radius <= 0.00002) {
    return sum;
  }
  for (int i = 0; i < SOFT_TAPS; i++) {
    sum += texture(u_scene, uv + spiral(i, SOFT_TAPS, radius, 0.0));
  }
  return sum / float(SOFT_TAPS + 1);
}

void main() {
  vec2 p = (v_uv - 0.5) * 2.0;
  p.x *= u_aspect;

  float span = sqrt(u_aspect * u_aspect + 1.0);
  float reach = length(p);
  float radius = reach / span;
  vec2 direction = reach > 0.0001 ? p / reach : vec2(0.0);

  float bend = 1.0 / (1.0 + clamp(u_distortion, 0.0, 1.0) * radius * radius);
  float focused = reach * bend;
  vec2 base = lensUv(direction, focused);

  float soft = u_softness * 0.011 * smoothstep(0.22, 1.0, radius);
  float split = u_aberration * 0.0035 * radius;

  vec4 mid = softSample(base, soft);
  float red = softSample(lensUv(direction, focused * (1.0 + split)), soft).r;
  float blue = softSample(lensUv(direction, focused * (1.0 - split)), soft).b;
  vec3 color = vec3(red, mid.g, blue);

  vec3 glare = vec3(0.0);
  for (int i = 0; i < GLARE_TAPS; i++) {
    vec3 tap =
      texture(u_scene, base + spiral(i, GLARE_TAPS, u_bloom * 0.026, 0.7)).rgb;
    glare += max(tap - 0.62, vec3(0.0));
  }
  color += (glare / float(GLARE_TAPS)) * u_bloom * 1.4;

  float falloff = pow(cos(min(radius, 1.0) * 0.55), 4.0);
  color *= mix(1.0, falloff, clamp(u_vignette, 0.0, 1.5));

  outColor = vec4(clamp(color, 0.0, 1.0), mid.a);
}`;

const shader = makeFilterShader<CameraLensProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      softness = DEFAULTS.softness,
      bloom = DEFAULTS.bloom,
      aberration = DEFAULTS.aberration,
      vignette = DEFAULTS.vignette,
      distortion = DEFAULTS.distortion,
    } = passedProps;
    gl.uniform1f(uniform("u_softness"), softness);
    gl.uniform1f(uniform("u_bloom"), bloom);
    gl.uniform1f(uniform("u_aberration"), aberration);
    gl.uniform1f(uniform("u_vignette"), vignette);
    gl.uniform1f(uniform("u_distortion"), distortion);
  },
);

const CameraLensFallback: React.FC<CameraLensProps & CanvasFilterProps> = ({
  children,
  bloom = DEFAULTS.bloom,
  vignette = DEFAULTS.vignette,
}) => (
  <AbsoluteFill>
    <AbsoluteFill>{children}</AbsoluteFill>
    <AbsoluteFill
      style={{
        filter: `blur(${6 * bloom}px) brightness(1.5) contrast(1.3)`,
        mixBlendMode: "screen",
        opacity: 0.3 * bloom,
      }}
    >
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background:
          "radial-gradient(ellipse 78% 76% at 50% 50%, transparent 52%, rgba(0, 0, 0, 0.5) 100%)",
        opacity: Math.min(vignette, 1),
      }}
    />
  </AbsoluteFill>
);

export const CameraLens = makeCanvasFilter<CameraLensProps>({
  shader,
  fallback: CameraLensFallback,
});

"use client";

import { loadFont } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: display } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CandleRallyProps {
  /** Ticker on the price tag riding the last wick. Fictional. */
  symbol?: string;
  /** Where the last candle closes; printed on the tag. */
  price?: number;
  /** The previous high the rally breaks through (dashed level). */
  prevHigh?: number;
  /** First line of the slam. */
  headline?: string;
  /** Second line of the slam. */
  headline2?: string;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_PUSH = Easing.bezier(0.42, 0, 0.18, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Beat sheet (30fps, speed 1):
//   0–48   ten small candles chop sideways, one every 4 frames
//  50–82   the rally: five green candles, 6 frames apart, each bigger
//  82–108  the last candle pushes up huge and fills with the aurora gradient;
//          the price tag rides its wick and breaks the dashed previous high
// 110–122  ALL-TIME / HIGH slams in, the candles fall back behind it
// 122–     poster holds
const RALLY_AT = 50;
const FINAL_AT = 82;
const FINAL_LEN = 26;
const SLAM = 110;

// Candles as [open, close, high, low]; the last close is replaced by `price`.
const CHOP: Array<[number, number, number, number]> = [
  [63.5, 66.5, 68, 62],
  [66.5, 63, 67.5, 61.5],
  [65.5, 62, 66.5, 60.5],
  [62, 65, 66, 61],
  [65, 62.5, 66.5, 61.5],
  [62.5, 66, 67.5, 61.5],
  [66, 63.5, 67.5, 62.5],
  [63.5, 65.5, 66.5, 62.5],
];
const RALLY: Array<[number, number, number, number]> = [
  [63, 66.5, 67.5, 62.5],
  [66.5, 71, 72, 65.5],
  [71, 77.5, 79, 70],
  [77.5, 87, 88.5, 76.5],
  [87, 99.5, 101.5, 86],
];
// The y-range auto-scales like a live chart: tight on the chop, pulled
// open by the rally so the newest high always rides near the top.
const LO = 58.5;
const HI_MIN = 70;

// gradients.sh "aurora" (bg #03050b): #a0f0c8 #3fb5a3 #5147b6 #b25c9c.
const AURORA = ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"];
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#77767C",
    hair: "rgba(243,242,239,0.08)",
    up: "#4FC8AE",
    down: "#E4604E",
    tagInk: "#06140F",
    ground: 0.55,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#8A8883",
    hair: "rgba(18,18,20,0.08)",
    up: "#169C82",
    down: "#D44A37",
    tagInk: "#06140F",
    ground: 0.14,
  },
} as const;

export function CandleRally({
  symbol = "RMCN",
  price = 128.4,
  prevHigh = 112,
  headline = "All-time",
  headline2 = "high",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: CandleRallyProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const p = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  // ---- candle slots: chop narrow and even, rally widening, last one huge ---
  const finalCandle: [number, number, number, number] = [
    99.5,
    price,
    price + 1.6,
    98.5,
  ];
  const all = [...CHOP, ...RALLY, finalCandle];
  const widths = all.map((_, i) =>
    i < CHOP.length
      ? 0.03
      : i < all.length - 1
        ? 0.032 + (i - CHOP.length) * 0.004
        : 0.09,
  );
  const gaps = all.map((_, i) =>
    i < CHOP.length
      ? 0.022
      : i < all.length - 1
        ? 0.024 + (i - CHOP.length) * 0.003
        : 0.04,
  );
  const xs: number[] = [];
  {
    let x = 0.065;
    all.forEach((_, i) => {
      if (i > 0) x += widths[i - 1] / 2 + gaps[i] + widths[i] / 2;
      xs.push(x);
    });
  }
  // fit the run so the last candle sits at ~84% of the width
  const fit = (0.84 - 0.065) / (xs[xs.length - 1] - 0.065);

  const startOf = (i: number) =>
    i < CHOP.length
      ? 4 + i * 5
      : i < all.length - 1
        ? RALLY_AT + (i - CHOP.length) * 6
        : FINAL_AT;
  const lenOf = (i: number) =>
    i < CHOP.length
      ? 8
      : i < all.length - 1
        ? 9 + (i - CHOP.length)
        : FINAL_LEN;

  const fi = all.length - 1;
  const cx = (i: number) => W * (0.065 + (xs[i] - 0.065) * fit * zx);
  const cw = (i: number) => W * widths[i] * fit * zx;
  const kOf = (i: number, tt: number) => {
    const r = Math.max(0, Math.min(1, (tt - startOf(i)) / lenOf(i)));
    return i === fi ? EASE_PUSH(r) : EASE_OUT(r);
  };
  // the auto-scaling range follows the highest wick so far, box-filtered
  // over a few frames so each new candle pumps the scale smoothly
  const topAt = (tt: number) => {
    let m = HI_MIN;
    all.forEach(([o, c, h], i) => {
      if (tt < startOf(i)) return;
      const k = kOf(i, tt);
      const cur = o + (c - o) * k;
      m = Math.max(m, Math.max(o, cur) + (h - Math.max(o, c)) * k);
    });
    return m;
  };
  let hiSum = 0;
  for (let k = 0; k < 6; k++) {
    const top = topAt(t - k);
    hiSum += Math.max(HI_MIN, top + (top - LO) * 0.12);
  }
  const topNow = topAt(t);
  const hi = Math.max(hiSum / 6, topNow + (topNow - LO) * 0.05);
  const lo = LO - (hi - HI_MIN) * 0.03;
  const yOf = (v: number) => H * 0.88 - ((v - lo) / (hi - lo)) * H * 0.76;
  // the camera pulls back as the rally needs the room
  const zx = interpolate(t, [0, RALLY_AT - 4, FINAL_AT + 16], [1.5, 1.42, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const slam1 = interpolate(t, [SLAM, SLAM + 7], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const slam2 = interpolate(t, [SLAM + 4, SLAM + 11], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const dim = interpolate(t, [SLAM, SLAM + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // one impact: the chart dips on the slam and settles
  const hit =
    interpolate(t, [SLAM + 1, SLAM + 3, SLAM + 16], [0, 1, 0], {
      ...CLAMP,
      easing: EASE_OUT,
    }) *
    10 *
    u;

  // last candle's live close, the tag reads it
  const fk = EASE_PUSH(Math.max(0, Math.min(1, (t - FINAL_AT) / FINAL_LEN)));
  const live = finalCandle[0] + (finalCandle[1] - finalCandle[0]) * fk;
  const broke = live >= prevHigh;
  const breakAt = (() => {
    // frame where the live close crosses the previous high
    for (let f = FINAL_AT; f <= FINAL_AT + FINAL_LEN; f += 0.25) {
      const k = EASE_PUSH(Math.min(1, (f - FINAL_AT) / FINAL_LEN));
      if (finalCandle[0] + (finalCandle[1] - finalCandle[0]) * k >= prevHigh)
        return f;
    }
    return FINAL_AT + FINAL_LEN;
  })();
  const levelIn = interpolate(t, [6, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const levelFlash = interpolate(
    t,
    [breakAt, breakAt + 2, breakAt + 16],
    [0, 1, 0],
    CLAMP,
  );
  const levelOut = interpolate(
    t,
    [breakAt + 6, breakAt + 22],
    [1, 0.35],
    CLAMP,
  );
  const ground = interpolate(t, [FINAL_AT, FINAL_AT + FINAL_LEN + 10], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gradK = interpolate(t, [FINAL_AT + 6, FINAL_AT + FINAL_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const candle = (i: number) => {
    const [o, c, h, l] = all[i];
    const s = startOf(i);
    const k = EASE_OUT(Math.max(0, Math.min(1, (t - s) / lenOf(i))));
    const isFinal = i === all.length - 1;
    const kk = isFinal ? fk : k;
    if (t < s) return null;
    const cur = o + (c - o) * kk;
    const top = Math.max(o, cur) + (h - Math.max(o, c)) * kk;
    const bot = Math.min(o, cur) - (Math.min(o, c) - l) * kk;
    const x = cx(i);
    const w = cw(i);
    const yA = yOf(Math.max(o, cur));
    const yB = yOf(Math.min(o, cur));
    const bodyH = Math.max(2 * u, yB - yA);
    const color = c >= o ? p.up : p.down;
    const appear = interpolate(t, [s, s + 2], [0, 1], CLAMP);
    const wick = Math.max(1.5 * u, w * (isFinal ? 0.05 : 0.09));
    const fade = isFinal ? 1 : 1 - dim * 0.78;
    return (
      <g key={i} opacity={appear * fade}>
        <rect
          x={x - wick / 2}
          y={yOf(top)}
          width={wick}
          height={yOf(bot) - yOf(top)}
          fill={isFinal ? `url(#${uid}wick)` : color}
        />
        <rect
          x={x - w / 2}
          y={yA - (bodyH - (yB - yA)) / 2}
          width={w}
          height={bodyH}
          rx={Math.min(w * 0.08, 4 * u)}
          fill={color}
        />
        {isFinal ? (
          <rect
            x={x - w / 2}
            y={yA}
            width={w}
            height={bodyH}
            rx={Math.min(w * 0.08, 4 * u)}
            fill={`url(#${uid}aurora)`}
            opacity={gradK}
          />
        ) : null}
      </g>
    );
  };

  const fx = cx(fi);
  const fw = cw(fi);
  const wickTop = yOf(
    Math.max(finalCandle[0], live) +
      (finalCandle[2] - Math.max(finalCandle[0], finalCandle[1])) * fk,
  );
  const tagIn = interpolate(t, [FINAL_AT + 2, FINAL_AT + 10], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const tagH = 44 * u;
  const tagFont = 21 * u;
  const levelY = yOf(prevHigh);
  const S = H * 0.3;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      {/* aurora ground behind the breakout */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: ground * p.ground,
          background: [
            `radial-gradient(34% 62% at 84% 26%, color-mix(in oklab, ${AURORA[0]} 55%, transparent) 0%, transparent 70%)`,
            `radial-gradient(40% 70% at 72% 40%, color-mix(in oklab, ${AURORA[2]} 45%, transparent) 0%, transparent 72%)`,
          ].join(", "),
        }}
      />

      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        role="img"
        aria-label={`${symbol} candles rally to ${price.toFixed(2)}, ${headline} ${headline2}`}
      >
        <defs>
          <linearGradient
            id={`${uid}aurora`}
            gradientUnits="userSpaceOnUse"
            x1={0}
            y1={yOf(finalCandle[1])}
            x2={0}
            y2={yOf(finalCandle[0])}
          >
            {AURORA.map((c, i) => (
              <stop key={c} offset={i / (AURORA.length - 1)} stopColor={c} />
            ))}
          </linearGradient>
          <linearGradient
            id={`${uid}wick`}
            gradientUnits="userSpaceOnUse"
            x1={0}
            y1={yOf(finalCandle[2])}
            x2={0}
            y2={yOf(finalCandle[3])}
          >
            <stop offset={0} stopColor={AURORA[0]} />
            <stop offset={1} stopColor={AURORA[3]} />
          </linearGradient>
        </defs>

        <g transform={`translate(0 ${hit})`}>
          {/* minimal axis: four faint levels with mono ticks */}
          {[60, 80, 100, 120].map((v) => (
            <g key={v} opacity={levelIn * (1 - dim * 0.6)}>
              <rect
                x={W * 0.04}
                y={yOf(v) - 0.5 * u}
                width={W * 0.88}
                height={1 * u}
                fill={p.hair}
              />
              <text
                x={W * 0.965}
                y={yOf(v) + 5 * u}
                textAnchor="end"
                fontFamily={mono}
                fontWeight={400}
                fontSize={13 * u}
                fill={p.muted}
              >
                {v.toFixed(0)}
              </text>
            </g>
          ))}

          {/* previous high: dashed level the last candle punches through */}
          <g opacity={levelIn * levelOut * (1 - dim)}>
            <line
              x1={W * 0.04}
              x2={W * 0.92}
              y1={levelY}
              y2={levelY}
              stroke={broke ? p.up : accent}
              strokeOpacity={0.55 + 0.45 * levelFlash}
              strokeWidth={(1.5 + 2 * levelFlash) * u}
              strokeDasharray={`${6 * u} ${6 * u}`}
            />
            <text
              x={W * 0.04}
              y={levelY - 12 * u}
              fontFamily={mono}
              fontWeight={500}
              fontSize={14 * u}
              letterSpacing="0.1em"
              fill={p.muted}
            >
              PREV HIGH {prevHigh.toFixed(2)}
            </text>
          </g>

          {all.map((_, i) => candle(i))}
        </g>
      </svg>

      {/* price tag riding the last wick */}
      <div
        style={{
          position: "absolute",
          left: fx - fw / 2 - 14 * u,
          top: wickTop + hit,
          height: tagH,
          transform: `translate(-100%, -50%) translateX(${(1 - tagIn) * 16 * u}px)`,
          opacity: tagIn,
          display: "flex",
          alignItems: "center",
          gap: 10 * u,
          padding: `0 ${16 * u}px`,
          borderRadius: tagH / 2,
          background: AURORA[0],
          color: p.tagInk,
          fontFamily: mono,
          fontWeight: 500,
          fontSize: tagFont,
          letterSpacing: "0.02em",
          fontVariantNumeric: "tabular-nums",
          whiteSpace: "nowrap",
          lineHeight: 1,
        }}
      >
        <span style={{ opacity: 0.62 }}>{symbol}</span>
        <span>{live.toFixed(2)}</span>
        <svg
          width={0.62 * tagFont}
          height={0.54 * tagFont}
          viewBox="0 0 10 8.66"
          aria-hidden
          style={{ display: "block" }}
        >
          <path d="M5 0 L10 8.66 L0 8.66 Z" fill={p.tagInk} />
        </svg>
      </div>

      {/* the slam */}
      <div
        style={{
          position: "absolute",
          left: W * 0.058,
          top: H * 0.255,
          fontFamily: display,
          fontWeight: 500,
          fontSize: S,
          lineHeight: 0.96,
          letterSpacing: "-0.012em",
          textTransform: "uppercase",
          color: p.fg,
          whiteSpace: "nowrap",
        }}
      >
        <div
          style={{
            opacity: Math.min(1, slam1 * 2.5),
            transform: `scale(${1.28 - 0.28 * slam1})`,
            transformOrigin: "0% 60%",
          }}
        >
          {headline}
        </div>
        <div
          style={{
            opacity: Math.min(1, slam2 * 2.5),
            transform: `scale(${1.28 - 0.28 * slam2})`,
            transformOrigin: "0% 60%",
          }}
        >
          {headline2}
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import React from "react";
import {
  AbsoluteFill,
  isHtmlInCanvasSupported,
  useCurrentFrame,
  useDelayRender,
  useVideoConfig,
} from "remotion";

const QUAD = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

const VERTEX_SHADER = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;
void main() {
  v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5);
  gl_Position = vec4(a_pos, 0.0, 1.0);
}`;

const LAYER: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
};

const OUTPUT_LAYER: React.CSSProperties = { ...LAYER, pointerEvents: "none" };

export const isCanvasTransitionSupported = (): boolean =>
  isHtmlInCanvasSupported();

export const isCanvasFilterSupported = (): boolean => isHtmlInCanvasSupported();

export type SceneShaderFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

export type SceneShaderDrawParams<Props> = {
  from: OffscreenCanvas | null;
  to: OffscreenCanvas | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

export type SceneShaderInstance<Props> = {
  draw: (params: SceneShaderDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

export type SceneShader<Props> = (
  canvas: OffscreenCanvas,
) => SceneShaderInstance<Props>;

export type SceneFilterFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

export type SceneFilterDrawParams<Props> = {
  scene: OffscreenCanvas | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

export type SceneFilterInstance<Props> = {
  draw: (params: SceneFilterDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

export type SceneFilter<Props> = (
  canvas: OffscreenCanvas,
) => SceneFilterInstance<Props>;

function compileShader(
  gl: WebGL2RenderingContext,
  source: string,
  type: GLenum,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) {
    throw new Error("canvas-presentation: failed to create shader");
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(`canvas-presentation: failed to compile shader: ${log}`);
  }
  return shader;
}

function createProgram(
  gl: WebGL2RenderingContext,
  fragment: string,
): WebGLProgram {
  const program = gl.createProgram();
  if (!program) {
    throw new Error("canvas-presentation: failed to create program");
  }
  const vs = compileShader(gl, VERTEX_SHADER, gl.VERTEX_SHADER);
  const fs = compileShader(gl, fragment, gl.FRAGMENT_SHADER);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(`canvas-presentation: failed to link program: ${log}`);
  }
  return program;
}

function createSceneTexture(gl: WebGL2RenderingContext): WebGLTexture {
  const texture = gl.createTexture();
  if (!texture) {
    throw new Error("canvas-presentation: failed to create texture");
  }
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    1,
    1,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    new Uint8Array([0, 0, 0, 0]),
  );
  return texture;
}

function createQuadSurface(canvas: OffscreenCanvas, fragment: string) {
  const gl = canvas.getContext("webgl2", { premultipliedAlpha: true });
  if (!gl) {
    throw new Error("canvas-presentation: WebGL2 is unavailable");
  }

  const program = createProgram(gl, fragment);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, QUAD, gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const locations = new Map<string, WebGLUniformLocation | null>();
  const uniform = (name: string) => {
    const cached = locations.get(name);
    if (cached !== undefined) {
      return cached;
    }
    const location = gl.getUniformLocation(program, name);
    locations.set(name, location);
    return location;
  };

  const clear = () => {
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  };

  const textures: WebGLTexture[] = [];
  const createTexture = () => {
    const texture = createSceneTexture(gl);
    textures.push(texture);
    return texture;
  };

  const begin = (width: number, height: number) => {
    gl.viewport(0, 0, width, height);
    clear();
    gl.useProgram(program);
    gl.bindVertexArray(vao);
  };

  const bindScene = (
    image: OffscreenCanvas | null,
    texture: WebGLTexture,
    unit: number,
    name: string,
  ) => {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    if (image) {
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        image,
      );
    }
    gl.uniform1i(uniform(name), unit);
  };

  const draw = () => gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  const cleanup = () => {
    gl.deleteProgram(program);
    for (const texture of textures) {
      gl.deleteTexture(texture);
    }
    gl.deleteBuffer(buffer);
    gl.deleteVertexArray(vao);
  };

  return {
    gl,
    uniform,
    clear,
    createTexture,
    begin,
    bindScene,
    draw,
    cleanup,
  };
}

export function makeSceneShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneShaderFrame<Props>) => void,
): SceneShader<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const fromTexture = surface.createTexture();
    const toTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ from, to, width, height, progress, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(from, fromTexture, 0, "u_from");
        surface.bindScene(to, toTexture, 1, "u_to");

        surface.gl.uniform1f(surface.uniform("u_progress"), progress);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          progress,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

export function makeFilterShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneFilterFrame<Props>) => void,
): SceneFilter<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const sceneTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ scene, width, height, frame, time, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(scene, sceneTexture, 0, "u_scene");

        surface.gl.uniform1f(surface.uniform("u_frame"), frame);
        surface.gl.uniform1f(surface.uniform("u_time"), time);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          frame,
          time,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

const transferred = new WeakMap<HTMLCanvasElement, OffscreenCanvas>();

function takeOffscreen(canvas: HTMLCanvasElement): OffscreenCanvas {
  const existing = transferred.get(canvas);
  if (existing) {
    return existing;
  }
  const created = canvas.transferControlToOffscreen();
  transferred.set(canvas, created);
  return created;
}

function makeCanvasComponent<Props extends Record<string, unknown>>(
  shader: SceneShader<Props>,
): React.FC<TransitionPresentationComponentProps<Props>> {
  return function CanvasScenePresentation({
    children,
    presentationProgress,
    presentationDirection,
    passedProps,
    onElementImage,
    onUnmount,
    bothEnteringAndExiting,
  }) {
    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneShaderInstance<Props> | null>(null);
    const passedPropsRef = React.useRef(passedProps);
    passedPropsRef.current = passedProps;
    const onElementImageRef = React.useRef(onElementImage);
    onElementImageRef.current = onElementImage;
    const onUnmountRef = React.useRef(onUnmount);
    onUnmountRef.current = onUnmount;

    const { delayRender, continueRender } = useDelayRender();
    const passThrough =
      bothEnteringAndExiting && presentationDirection === "exiting";

    const drawRef = React.useRef<
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => void
    >(() => undefined);
    drawRef.current = (prevImage, nextImage, progress) => {
      const instance = instanceRef.current;
      if (!instance) {
        return;
      }
      const handle = delayRender("canvas-presentation: paint");
      const to = prevImage;
      const from = nextImage;
      const width = from?.width ?? to?.width ?? 0;
      const height = from?.height ?? to?.height ?? 0;
      if (width === 0 || height === 0) {
        instance.clear();
        continueRender(handle);
        return;
      }
      instance.draw({
        from,
        to,
        width,
        height,
        progress: !to ? 0 : !from ? 1 : progress,
        passedProps: passedPropsRef.current,
      });
      continueRender(handle);
    };

    const draw = React.useCallback(
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => drawRef.current(prevImage, nextImage, progress),
      [],
    );

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [passThrough, shader]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        if (!scene || !capture || !context) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        onElementImageRef.current(capture, draw);
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, [passThrough, draw]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, [passThrough]);

    // biome-ignore lint/correctness/useExhaustiveDependencies: presentationProgress is the intentional trigger — a new progress value is what schedules the next paint
    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      layoutRef.current?.requestPaint?.();
    }, [passThrough, presentationProgress]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      return () => onUnmountRef.current();
    }, [passThrough]);

    if (passThrough) {
      return <>{children}</>;
    }

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

export type CanvasFilterProps = {
  children: React.ReactNode;
};

function makeFilterComponent<Props extends Record<string, unknown>>(
  shader: SceneFilter<Props>,
): React.FC<Props & CanvasFilterProps> {
  return function CanvasSceneFilter(props) {
    const frame = useCurrentFrame();
    const { fps } = useVideoConfig();
    const { delayRender, continueRender } = useDelayRender();

    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneFilterInstance<Props> | null>(null);

    const passedPropsRef = React.useRef(props);
    passedPropsRef.current = props;
    const frameRef = React.useRef(frame);
    frameRef.current = frame;
    const timeRef = React.useRef(frame / fps);
    timeRef.current = frame / fps;

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [shader]);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        const instance = instanceRef.current;
        if (!scene || !capture || !context || !instance) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        if (capture.width === 0 || capture.height === 0) {
          instance.clear();
          return;
        }
        instance.draw({
          scene: capture,
          width: capture.width,
          height: capture.height,
          frame: frameRef.current,
          time: timeRef.current,
          passedProps: passedPropsRef.current,
        });
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const handle = delayRender("canvas-presentation: filter paint");
      const settle = () => continueRender(handle);
      layout.addEventListener("paint", settle, { once: true });
      layout.requestPaint?.();
      return () => {
        layout.removeEventListener("paint", settle);
        continueRender(handle);
      };
    });

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {props.children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

export type CanvasPresentationOptions<Props extends Record<string, unknown>> = {
  shader: SceneShader<Props>;
  fallback: React.FC<TransitionPresentationComponentProps<Props>>;
};

export function makeCanvasPresentation<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasPresentationOptions<Props>): (
  props: Props,
) => TransitionPresentation<Props> {
  const Canvas = makeCanvasComponent(shader);

  const Presentation: React.FC<TransitionPresentationComponentProps<Props>> = (
    props,
  ) =>
    isCanvasTransitionSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );

  return (props) => ({ component: Presentation, props });
}

export type CanvasFilterOptions<Props extends Record<string, unknown>> = {
  shader: SceneFilter<Props>;
  fallback: React.FC<Props & CanvasFilterProps>;
};

export function makeCanvasFilter<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasFilterOptions<Props>): React.FC<Props & CanvasFilterProps> {
  const Canvas = makeFilterComponent(shader);

  return function CanvasFilter(props) {
    return isCanvasFilterSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );
  };
}

"use client";

import { Fragment } from "react";
import {
  Easing,
  interpolate,
  interpolateColors,
  spring,
  useVideoConfig,
} from "remotion";
import {
  type CaptionBaseProps,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
} from "@/lib/remocn/caption-core";

export interface CaptionActivePopProps extends CaptionBaseProps {
  activeColor?: string;
  popScale?: number;
  shadow?: boolean;
}

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const POP_SPRING = { damping: 12, stiffness: 220, mass: 0.6 };
const RELEASE_SPRING = { damping: 20, stiffness: 200, mass: 0.6 };

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export function CaptionActivePop({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  activeColor = "#facc15",
  popScale = 1.12,
  shadow = true,
  className,
}: CaptionActivePopProps) {
  const { fps } = useVideoConfig();
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    {
      ...clamp,
      easing: enterEasing,
    },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  const words = groupCaptionWords(state.tokens);
  const activeWord = words.findIndex((word) =>
    word.some(({ index }) => index === state.activeIndex),
  );
  const toFrames = (ms: number) => (ms / 1000) * fps;

  const emphasis = (w: number): number => {
    if (activeWord < 0 || w > activeWord) return 0;
    const startMs = words[w][0].token.fromMs;
    if (w === activeWord) {
      return spring({
        frame: toFrames(state.timeMs - startMs),
        fps,
        config: POP_SPRING,
      });
    }
    if (w < activeWord - 1) return 0;
    const releaseMs = words[w + 1][0].token.fromMs;
    const peak = spring({
      frame: toFrames(releaseMs - startMs),
      fps,
      config: POP_SPRING,
    });
    const release = spring({
      frame: toFrames(state.timeMs - releaseMs),
      fps,
      config: RELEASE_SPRING,
    });
    return peak * (1 - release);
  };

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: Math.min(enter, exit),
        transform: `translateY(${(1 - enter) * RISE_EM}em)`,
      }}
    >
      {words.map((word, w) => {
        const amount = emphasis(w);
        return (
          <Fragment key={`${state.pageIndex}-${word[0].index}`}>
            {w > 0 && " "}
            <span
              style={{
                position: "relative",
                zIndex: w === activeWord ? 1 : 0,
                display: "inline-block",
                whiteSpace: "nowrap",
                transform: `scale(${1 + (popScale - 1) * amount})`,
                transformOrigin: "50% 60%",
                color: interpolateColors(
                  Math.min(1, Math.max(0, amount)),
                  [0, 1],
                  [color, activeColor],
                ),
                textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
              }}
            >
              {word.map(({ index, token }) => (
                <span key={index}>{token.text}</span>
              ))}
            </span>
          </Fragment>
        );
      })}
    </div>
  );
}

"use client";

import { Fragment } from "react";
import { Easing, interpolate } from "remotion";
import {
  type CaptionBaseProps,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
} from "@/lib/remocn/caption-core";

export interface CaptionBlurInProps extends CaptionBaseProps {
  blur?: number;
  shadow?: boolean;
}

const EXIT_MS = 220;
const RESOLVE_MS = 220;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const resolveEasing = Easing.bezier(0.25, 0.6, 0.3, 1);

export function CaptionBlurIn({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  blur = 12,
  shadow = true,
  className,
}: CaptionBlurInProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      )
    : 1;

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: exit,
      }}
    >
      {groupCaptionWords(state.tokens).map((word, w) => (
        <Fragment key={`${state.pageIndex}-${word[0].index}`}>
          {w > 0 && " "}
          <span style={{ display: "inline-block", whiteSpace: "nowrap" }}>
            {word.map(({ index, token }) => {
              const sinceMs = state.timeMs - token.fromMs;
              const p =
                sinceMs < 0
                  ? 0
                  : interpolate(sinceMs, [0, RESOLVE_MS], [0, 1], {
                      easing: resolveEasing,
                      extrapolateLeft: "clamp",
                      extrapolateRight: "clamp",
                    });
              const radius = (1 - p) * blur;
              return (
                <span
                  key={index}
                  style={{
                    display: "inline-block",
                    opacity: p,
                    filter: radius > 0.01 ? `blur(${radius}px)` : undefined,
                    textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
                  }}
                >
                  {token.text}
                </span>
              );
            })}
          </span>
        </Fragment>
      ))}
    </div>
  );
}

"use client";

import { Fragment } from "react";
import { interpolate, spring, useVideoConfig } from "remotion";
import {
  type CaptionBaseProps,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
} from "@/lib/remocn/caption-core";

export interface CaptionBounceInProps extends CaptionBaseProps {
  bounce?: number;
  shadow?: boolean;
}

const EXIT_MS = 220;
const FADE_IN_MS = 90;
const DROP_EM = 0.35;
const START_SCALE = 0.7;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

export function CaptionBounceIn({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  bounce = 0.6,
  shadow = true,
  className,
}: CaptionBounceInProps) {
  const { fps } = useVideoConfig();
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const damping = interpolate(bounce, [0, 1], [22, 7], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      )
    : 1;

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: exit,
      }}
    >
      {groupCaptionWords(state.tokens).map((word, w) => (
        <Fragment key={`${state.pageIndex}-${word[0].index}`}>
          {w > 0 && " "}
          <span style={{ display: "inline-block", whiteSpace: "nowrap" }}>
            {word.map(({ index, token }) => {
              const sinceMs = state.timeMs - token.fromMs;
              const arrived = sinceMs >= 0;
              const p = arrived
                ? spring({
                    frame: (sinceMs / 1000) * fps,
                    fps,
                    config: { damping, stiffness: 220, mass: 0.6 },
                  })
                : 0;
              const opacity = arrived
                ? interpolate(sinceMs, [0, FADE_IN_MS], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })
                : 0;
              return (
                <span
                  key={index}
                  style={{
                    display: "inline-block",
                    opacity,
                    transform: `translateY(${(1 - p) * DROP_EM}em) scale(${
                      START_SCALE + (1 - START_SCALE) * p
                    })`,
                    transformOrigin: "50% 80%",
                    textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
                  }}
                >
                  {token.text}
                </span>
              );
            })}
          </span>
        </Fragment>
      ))}
    </div>
  );
}

