            ? {
                backgroundColor: `color-mix(in srgb, ${boxColor} ${opacityPercent}%, transparent)`,
                padding: "0.06em 0.36em",
                borderRadius: "0.16em",
                boxDecorationBreak: "clone",
                WebkitBoxDecorationBreak: "clone",
              }
            : { textShadow: LEGIBILITY_SHADOW }
        }
      >
        {state.page.text}
      </span>
    </div>
  );
