import type { Caption } from "@remotion/captions";
import { useLayoutEffect, useMemo, useRef, useState } from "react";
import { interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import type { CaptionBaseProps } from "@/lib/remocn/caption-core";

export interface CaptionTimelineProps extends CaptionBaseProps {
  width?: number;
  pxPerSecond?: number;
  playheadPosition?: number;
  playheadColor?: string;
  upcomingOpacity?: number;
  shadow?: boolean;
}

interface TimelineWord {
  id: number;
  text: string;
  startMs: number;
  endMs: number;
}

const LINE_HEIGHT = 1.3;
const GAP_EM = 0.32;
const LIGHT_MS = 80;
const EDGE_FADE =
  "linear-gradient(to right, transparent, #000 12%, #000 88%, transparent)";
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export function getTimelineWords(captions: Caption[]): TimelineWord[] {
  const words: TimelineWord[] = [];
  for (const caption of captions) {
    if (caption.text.trim() === "") continue;
    const last = words[words.length - 1];
    if (last && !/^\s/.test(caption.text)) {
      last.text += caption.text;
      last.endMs = caption.endMs;
    } else {
      words.push({
        id: words.length,
        text: caption.text.trim(),
        startMs: caption.startMs,
        endMs: caption.endMs,
      });
    }
  }
  return words;
}

export function layoutTimeline(
  words: TimelineWord[],
  widths: number[],
  pxPerSecond: number,
  gap: number,
): number[] {
  const xs: number[] = [];
  words.forEach((word, i) => {
    const ideal = (word.startMs / 1000) * pxPerSecond;
    xs.push(i === 0 ? ideal : Math.max(ideal, xs[i - 1] + widths[i - 1] + gap));
  });
  return xs;
}

export function timelineOffset(
  words: TimelineWord[],
  xs: number[],
  timeMs: number,
  pxPerSecond: number,
): number {
  if (words.length === 0) return (timeMs / 1000) * pxPerSecond;
  let i = -1;
  while (i + 1 < words.length && words[i + 1].startMs <= timeMs) i++;
  if (i === -1) {
    return xs[0] - ((words[0].startMs - timeMs) / 1000) * pxPerSecond;
  }
  const next = words[i + 1];
  if (!next) {
    return xs[i] + ((timeMs - words[i].startMs) / 1000) * pxPerSecond;
  }
  const span = next.startMs - words[i].startMs;
  const t = span > 0 ? (timeMs - words[i].startMs) / span : 1;
  return xs[i] + (xs[i + 1] - xs[i]) * t;
}

function sameWidths(a: number[], b: number[]): boolean {
  return a.length === b.length && a.every((w, i) => w === b[i]);
}

export function CaptionTimeline({
  captions,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  width = 1100,
  pxPerSecond = 260,
  playheadPosition = 0.35,
  playheadColor = "#facc15",
  upcomingOpacity = 0.4,
  shadow = true,
  className,
}: CaptionTimelineProps) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const timeMs = (frame / fps) * 1000;
  const words = useMemo(() => getTimelineWords(captions), [captions]);
  const elements = useRef<(HTMLSpanElement | null)[]>([]);
  const [widths, setWidths] = useState<number[]>([]);

  useLayoutEffect(() => {
    const measured = words.map((_, i) => elements.current[i]?.offsetWidth ?? 0);
    setWidths((prev) => (sameWidths(prev, measured) ? prev : measured));
  });

  const gap = fontSize * GAP_EM;
  const resolved =
    widths.length === words.length
      ? widths
      : words.map((word) => word.text.length * fontSize * 0.55);
  const xs = layoutTimeline(words, resolved, pxPerSecond, gap);
  const playheadX = width * playheadPosition;
  const offset = timelineOffset(words, xs, timeMs, pxPerSecond);
  const thickness = Math.max(2, Math.round(fontSize * 0.04));

  if (words.length === 0) return null;

  return (
    <div
      className={className}
      style={{
        position: "relative",
        width,
        height: `${LINE_HEIGHT}em`,
        fontSize,
        fontWeight,
        color,
        lineHeight: LINE_HEIGHT,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          overflow: "hidden",
          maskImage: EDGE_FADE,
          WebkitMaskImage: EDGE_FADE,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translateX(${playheadX - offset}px)`,
          }}
        >
          {words.map((word, i) => (
            <span
              key={word.id}
              ref={(el) => {
                elements.current[i] = el;
              }}
              style={{
                position: "absolute",
                left: xs[i],
                top: 0,
                whiteSpace: "nowrap",
                opacity: interpolate(
                  timeMs - word.startMs,
                  [-LIGHT_MS, 0],
                  [upcomingOpacity, 1],
                  clamp,
                ),
                textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
              }}
            >
              {word.text}
            </span>
          ))}
        </div>
      </div>
      <div
        aria-hidden
        style={{
          position: "absolute",
          top: "8%",
          bottom: "8%",
          left: playheadX - thickness / 2,
          width: thickness,
          borderRadius: thickness,
          background: playheadColor,
        }}
      />
    </div>
  );
}

"use client";

import { Fragment } from "react";
import { interpolate } from "remotion";
import {
  type CaptionBaseProps,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
} from "@/lib/remocn/caption-core";

export interface CaptionTypewriterProps extends CaptionBaseProps {
  caret?: boolean;
  shadow?: boolean;
}

const EXIT_MS = 220;
const BLINK_MS = 500;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";
const CARET_SHADOW = "0 2px 6px rgba(0, 0, 0, 0.45)";

function typedCount(text: string, progress: number): number {
  const length = Array.from(text).length;
  return Math.min(length, Math.ceil(progress * length));
}

export function CaptionTypewriter({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  caret = true,
  shadow = true,
  className,
}: CaptionTypewriterProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      )
    : 1;

  const active = state.tokens[state.activeIndex];
  const typing = active !== undefined && active.progress < 1;
  const idleMs = active ? state.timeMs - active.toMs : 0;
  const caretOn = typing || Math.floor(idleMs / BLINK_MS) % 2 === 0;

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: exit,
      }}
    >
      {groupCaptionWords(state.tokens).map((word, w) => (
        <Fragment key={`${state.pageIndex}-${word[0].index}`}>
          {w > 0 && " "}
          <span style={{ display: "inline-block", whiteSpace: "nowrap" }}>
            {word.map(({ index, token }) => {
              const chars = Array.from(token.text);
              const typed = typedCount(token.text, token.progress);
              return (
                <Fragment key={index}>
                  <span
                    style={{
                      textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
                    }}
                  >
                    {chars.slice(0, typed).join("")}
                  </span>
                  {caret && index === state.activeIndex ? (
                    <span style={{ position: "relative" }}>
                      <span
                        style={{
                          position: "absolute",
                          left: "0.03em",
                          top: "0.1em",
                          bottom: "0.1em",
                          width: "0.07em",
                          backgroundColor: color,
                          boxShadow: shadow ? CARET_SHADOW : undefined,
                          opacity: caretOn ? 1 : 0,
                        }}
                      />
                    </span>
                  ) : null}
                  <span aria-hidden style={{ color: "transparent" }}>
                    {chars.slice(typed).join("")}
                  </span>
                </Fragment>
              );
            })}
          </span>
        </Fragment>
      ))}
    </div>
  );
}

"use client";

import { Fragment } from "react";
import { Easing, interpolate } from "remotion";
import {
  type CaptionBaseProps,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
  useCaptionWordRects,
} from "@/lib/remocn/caption-core";

export interface CaptionUnderlineProps extends CaptionBaseProps {
  underlineColor?: string;
  thickness?: number;
  underlineOffset?: number;
  shadow?: boolean;
}

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const TRAVEL_MS = 120;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);
const travelEasing = Easing.bezier(0.3, 0, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function mix(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function CaptionUnderline({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  underlineColor = "#facc15",
  thickness = 0.08,
  underlineOffset = 0.02,
  shadow = true,
  className,
}: CaptionUnderlineProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  const words = state ? groupCaptionWords(state.tokens) : [];
  const pageIndex = state ? state.pageIndex : -1;
  const { wordRef, rects } = useCaptionWordRects(pageIndex, words.length);

  if (!state) return null;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    {
      ...clamp,
      easing: enterEasing,
    },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  const activeWord = words.findIndex((word) =>
    word.some(({ index }) => index === state.activeIndex),
  );
  const travel =
    activeWord >= 0
      ? interpolate(
          state.timeMs - words[activeWord][0].token.fromMs,
          [0, TRAVEL_MS],
          [0, 1],
          { ...clamp, easing: travelEasing },
        )
      : 0;

  const target = rects && activeWord >= 0 ? rects[activeWord] : null;
  const origin = rects && activeWord > 0 ? rects[activeWord - 1] : null;
  const barHeight = thickness * fontSize;
  const gap = underlineOffset * fontSize;
  const bar = target
    ? origin
      ? {
          left: mix(origin.left, target.left, travel),
          top: mix(
            origin.top + origin.height,
            target.top + target.height,
            travel,
          ),
          width: mix(origin.width, target.width, travel),
          opacity: 1,
        }
      : {
          left: target.left,
          top: target.top + target.height,
          width: target.width * travel,
          opacity: travel,
        }
    : null;

  return (
    <div
      className={className}
      style={{
        position: "relative",
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: Math.min(enter, exit),
        transform: `translateY(${(1 - enter) * RISE_EM}em)`,
      }}
    >
      {words.map((word, w) => (
        <Fragment key={`${state.pageIndex}-${word[0].index}`}>
          {w > 0 && " "}
          <span
            ref={wordRef(w)}
            style={{
              position: "relative",
              display: "inline-block",
              whiteSpace: "nowrap",
              textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
            }}
          >
            {word.map(({ index, token }) => (
              <span key={index}>{token.text}</span>
            ))}
          </span>
        </Fragment>
      ))}
      {bar && (
        <span
          aria-hidden
          style={{
            position: "absolute",
            left: bar.left,
            top: bar.top + gap,
            width: bar.width,
            height: barHeight,
            borderRadius: barHeight / 2,
            background: underlineColor,
            opacity: bar.opacity,
          }}
        />
      )}
    </div>
  );
}

"use client";

import { Fragment } from "react";
import { Easing, interpolate } from "remotion";
import {
  type CaptionBaseProps,
  captionWordText,
  DEFAULT_HOLD_MS,
  getExitWindowMs,
  groupCaptionWords,
  useCaptions,
} from "@/lib/remocn/caption-core";

export interface CaptionWeightProps extends CaptionBaseProps {
  activeWeight?: number;
  shadow?: boolean;
}

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const RAMP_MS = 150;
const RELEASE_MS = 220;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);
const rampEasing = Easing.bezier(0.2, 0.8, 0.3, 1);
const releaseEasing = Easing.bezier(0.4, 0, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export function CaptionWeight({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 400,
  activeWeight = 900,
  color = "#ffffff",
  shadow = true,
  className,
}: CaptionWeightProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    {
      ...clamp,
      easing: enterEasing,
    },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  const words = groupCaptionWords(state.tokens);
  const activeWord = words.findIndex((word) =>
    word.some(({ index }) => index === state.activeIndex),
  );

  const emphasis = (w: number): number => {
    if (activeWord < 0 || w > activeWord) return 0;
    const startMs = words[w][0].token.fromMs;
    const rise = interpolate(state.timeMs - startMs, [0, RAMP_MS], [0, 1], {
      ...clamp,
      easing: rampEasing,
    });
    if (w === activeWord) return rise;
    const releaseMs = words[w + 1][0].token.fromMs;
    const peak = interpolate(releaseMs - startMs, [0, RAMP_MS], [0, 1], {
      ...clamp,
      easing: rampEasing,
    });
    const release = interpolate(
      state.timeMs - releaseMs,
      [0, RELEASE_MS],
      [0, 1],
      { ...clamp, easing: releaseEasing },
    );
    return peak * (1 - release);
  };

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: Math.min(enter, exit),
        transform: `translateY(${(1 - enter) * RISE_EM}em)`,
      }}
    >
      {words.map((word, w) => {
        const weight = fontWeight + (activeWeight - fontWeight) * emphasis(w);
        return (
          <Fragment key={`${state.pageIndex}-${word[0].index}`}>
            {w > 0 && " "}
            <span style={{ display: "inline-grid", whiteSpace: "nowrap" }}>
              <span
                aria-hidden
                style={{
                  gridArea: "1 / 1",
                  fontWeight: Math.max(fontWeight, activeWeight),
                  visibility: "hidden",
                }}
              >
                {captionWordText(word)}
              </span>
              <span
                style={{
                  gridArea: "1 / 1",
                  justifySelf: "center",
                  fontWeight: weight,
                  textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
                }}
              >
                {word.map(({ index, token }) => (
                  <span key={index}>{token.text}</span>
                ))}
              </span>
            </span>
          </Fragment>
        );
      })}
    </div>
  );
}

