                  <CardBack
                    color={swatches[colorIdx]}
                    number={number}
                    exp={f < SCRAMBLE ? "••/••" : exp}
                    cvv={f < SCRAMBLE ? "•••" : cvv}
                  />
                </div>
              </div>
            ) : null}
            <div
              style={{
                position: "absolute",
                left: "50%",
                top: 600,
                transform: `translateX(-50%) translateY(${(1 - toast) * 20}px) scale(${0.9 + toast * 0.1})`,
                opacity: Math.min(1, toast * 1.5),
                height: 44,
                padding: "0 18px 0 12px",
                borderRadius: 22,
                background: c.chip,
                color: c.text,
                fontSize: 15,
                fontWeight: 400,
                display: "flex",
                alignItems: "center",
                gap: 8,
                whiteSpace: "nowrap",
              }}
            >
              <div
                style={{
                  width: 22,
                  height: 22,
                  borderRadius: 11,
                  background: accent,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg width={14} height={14} viewBox="0 0 24 24" fill="none">
                  <path
                    d="M5 12.5l4.5 4.5L19 7.5"
                    stroke="#fff"
                    strokeWidth={3}
                    strokeLinecap="round"
