function SceneB({
  title,
  subtitle,
  covers,
  palette,
  accent,
  ground,
  groundParams,
}: {
  title: string;
  subtitle: string;
  covers: CoverItem[];
  palette: (typeof THEMES)["dark"];
  accent: string;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const tall = height > width;
  const m = width * 0.07;
  const scale = tall ? width / 820 : width / 1280;
  const cols = tall ? 2 : 4;
