  const ch = tall ? cw * 1.32 : cw * 1.18;
  const push = interpolate(frame, [0, B_LEN], [1, 1.03], CLAMP);
  const lift = spring({
    frame: frame - B_BEATS.lift,
    fps,
    config: CARD,
  });
  const pill = spring({ frame: frame - B_BEATS.pill, fps, config: CHIP });
  const head = interpolate(frame, [0, 14], [0, 1], {
    ...CLAMP,
    easing: TYPE_IN,
