      >
        <div
          style={{
            position: "absolute",
            left: P.cardLeft - 40 * s,
            width: P.cardW + 80 * s,
            top: P.cardTop - qfs * (P.tall ? 2.9 : 1.75),
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            columnGap: "0.24em",
            fontSize: qfs,
            fontWeight: 300,
            letterSpacing: "-0.035em",
            lineHeight: 1.08,
            color: palette.ink,
          }}
        >
          {words.map((w, i) => {
            const p = interpolate(
              frame,
              [B_BEATS.heading + i * 2, B_BEATS.heading + i * 2 + 13],
              [0, 1],
              { ...CLAMP, easing: TYPE_IN },
            );
            return (
              <span
                key={`${w}-${i}`}
                style={{
                  display: "inline-block",
