                transform: `scale(${1 - Math.sin(Math.min(1, send) * Math.PI) * 0.12})`,
                boxShadow: `0 6px 18px rgba(${palette.shadow},${0.25 * armed})`,
              }}
            >
              <Icon d={ICONS.up} size={20 * s} color={palette.sendInk} />
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
