interface Layout {
  T: number;
  LH: number;
  cardX: number;
  cardY: number;
  cardW: number;
  cardH: number;
  pad: number;
  u: number;
  lines: { start: number; end: number }[];
  charX: (i: number) => number;
  lineOf: (i: number) => number;
  lineY: (li: number) => number;
  sendX: number;
  sendY: number;
  sendD: number;
}

export function CaretDolly({
  prompt = "Make a launch video for our new app with a bold title, product shots and a calm ending",
  focus = "launch video",
  chipLabel = "Video",
  modelLabel = "Remocn 1",
  accent,
  ink,
  background,
  theme = "dark",
  ground,
  groundParams,
}: CaretDollyProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, fps, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = background ?? gshParams(preset, gParams).background;
  const m = useMeasure();
  const portrait = H > W * 1.1;
  const filterId = `cd${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const found = prompt.indexOf(focus);
  const fs = found >= 0 && focus.length > 0 ? found : 0;
  const fe = found >= 0 && focus.length > 0 ? found + focus.length : 0;
  const focusLen = fe - fs;
  const postLen = prompt.length - fe;
  const rateA = Math.max(0.6, fs / 18);
  const rateF = Math.max(0.5, focusLen / BEAT.focusLen);
  const rateP = Math.max(2, postLen / BEAT.postLen);
  const punchEnd = BEAT.punch + BEAT.punchLen;
  const pullEnd = BEAT.pull + BEAT.pullLen;
  const postEnd = BEAT.post + postLen / rateP;

  const typedA = (f: number) =>
    Math.max(0, Math.min(fs, (f - BEAT.typeA) * rateA));
  const typedF = (f: number) =>
    Math.max(0, Math.min(focusLen, (f - punchEnd) * rateF));
  const typedP = (f: number) =>
    Math.max(0, Math.min(postLen, (f - BEAT.post) * rateP));

  const layout = ((): Layout | null => {
    if (!m) return null;
    const cardW = portrait ? W * 0.86 : Math.min(W * 0.66, H * 1.25);
    const T = portrait ? W * 0.05 : Math.max(H * 0.032, cardW * 0.031);
    const u = T / 22;
    const LH = T * 1.45;
    const pad = 22 * u;
    const room = cardW - pad * 2;
    const words = prompt.split(" ");
    const lines: { start: number; end: number }[] = [];
    let pos = 0;
    let cur = "";
    let curStart = 0;
    for (const w of words) {
      const next = cur.length > 0 ? `${cur} ${w}` : w;
      if (cur.length > 0 && m(next) * T > room) {
        lines.push({ start: curStart, end: curStart + cur.length });
        curStart = pos;
        cur = w;
      } else {
        cur = next;
      }
      pos += w.length + 1;
    }
    lines.push({ start: curStart, end: curStart + cur.length });
    const barH = 36 * u;
    const cardH = pad + lines.length * LH + 22 * u + barH + pad * 0.8;
    const cardX = (W - cardW) / 2;
    const cardY = H / 2 - cardH / 2;
    const lineOf = (i: number) => {
      for (let li = 0; li < lines.length; li++) {
        if (i <= lines[li].end) return li;
      }
      return lines.length - 1;
    };
    const charX = (i: number) => {
      const li = lineOf(i);
      return cardX + pad + m(prompt.slice(lines[li].start, i)) * T;
    };
    const lineY = (li: number) => cardY + pad + li * LH + LH / 2;
    const sendD = 34 * u;
    return {
      T,
      LH,
      cardX,
      cardY,
      cardW,
      cardH,
      pad,
      u,
      lines,
      charX,
      lineOf,
      lineY,
      sendX: cardX + cardW - pad * 0.8 - sendD / 2,
      sendY: cardY + cardH - pad * 0.8 - barH / 2,
      sendD,
    };
  })();

  const cams = (() => {
    if (!layout) return [];
    const { T, charX, lineOf, lineY } = layout;
    const C = { x: W / 2, y: H / 2 };
    const A = portrait ? W * 0.11 : H * 0.1;
    const giant = portrait ? W * 0.27 : Math.min(H * 0.36, W * 0.27);
    const sA = A / T;
    const sG = giant / T;
    const xAt = (ci: number) => {
      const lo = Math.floor(ci);
      const hiI = Math.min(prompt.length, lo + 1);
      const fr = ci - lo;
      if (lineOf(lo) !== lineOf(hiI)) return charX(lo);
      return charX(lo) + (charX(hiI) - charX(lo)) * CHAR(fr);
    };
    const goalA = (f: number) => {
      const ci = typedA(f);
      const li = lineOf(Math.floor(ci));
      return {
        x: (charX(layout.lines[li].start) + xAt(ci)) / 2,
        y: lineY(li),
      };
    };
    const goalG = (f: number) => {
      const ci = fs + typedF(f);
      const at = Math.floor(ci);
      let ws = at;
      while (ws > fs && prompt[ws - 1] !== " ") ws--;
      if (prompt[at] === " " && at > fs && ci - at < 0.5) {
        ws = at;
        while (ws > fs && prompt[ws - 1] !== " ") ws--;
      }
      const li = lineOf(at);
      return { x: (charX(ws) + xAt(ci)) / 2, y: lineY(li) };
    };
    const K = { x: charX(fs), y: lineY(lineOf(fs)) };
    const Fp = { x: charX(fe), y: lineY(lineOf(Math.max(fs, fe - 1))) };
    const out: { x: number; y: number; s: number }[] = [];
    let fx = goalA(0).x;
    let fy = goalA(0).y;
    let scrStart = { x: 0, y: 0 };
    let scrPull = { x: 0, y: 0 };
    const total = Math.max(durationInFrames, pullEnd + 1);
    for (let f = 0; f < total; f++) {
      if (f < BEAT.punch) {
        const g = goalA(f);
        fx += (g.x - fx) * 0.32;
        fy += (g.y - fy) * 0.32;
        out.push({ x: fx, y: fy, s: sA });
        scrStart = { x: C.x + (K.x - fx) * sA, y: C.y + (K.y - fy) * sA };
      } else if (f < punchEnd) {
        const p = CAMERA((f - BEAT.punch) / BEAT.punchLen);
        const s = Math.exp(Math.log(sA) + (Math.log(sG) - Math.log(sA)) * p);
        const sx = scrStart.x + (C.x - scrStart.x) * p;
        const sy = scrStart.y + (C.y - scrStart.y) * p;
        fx = K.x - (sx - C.x) / s;
        fy = K.y - (sy - C.y) / s;
        out.push({ x: fx, y: fy, s });
      } else if (f < BEAT.pull) {
        const g = goalG(f);
        fx += (g.x - fx) * 0.3;
        fy += (g.y - fy) * 0.3;
        out.push({ x: fx, y: fy, s: sG });
        scrPull = { x: C.x + (Fp.x - fx) * sG, y: C.y + (Fp.y - fy) * sG };
      } else if (f < pullEnd) {
        const p = CAMERA((f - BEAT.pull) / BEAT.pullLen);
        const s = Math.exp(Math.log(sG) * (1 - p));
        const sx = scrPull.x + (Fp.x - scrPull.x) * p;
        const sy = scrPull.y + (Fp.y - scrPull.y) * p;
        out.push({ x: Fp.x - (sx - C.x) / s, y: Fp.y - (sy - C.y) / s, s });
      } else {
        out.push({ x: C.x, y: C.y, s: 1 });
      }
    }
    return out;
  })();

  let content: ReactNode = <div />;
  if (layout && cams.length > 0) {
    const L = layout;
    const f = frame;
    const cam = cams[Math.min(cams.length - 1, f)];
    const prev = cams[Math.max(0, Math.min(cams.length - 1, f - 1))];
    const push =
      f >= pullEnd
        ? interpolate(f, [pullEnd, durationInFrames], [1, 1.03], CLAMP)
        : 1;
    const s = cam.s * push;
    const zoomV = Math.abs(Math.log(cam.s) - Math.log(prev.s));
    const panV = Math.abs(cam.x - prev.x) * cam.s;
    const zoomBlur = Math.min(7, zoomV * 26);
    const bx = Math.min(12, zoomBlur + panV * 0.05);
    const by = zoomBlur;

    const preOp =
      f < BEAT.punch
        ? 1
        : f < BEAT.pull
          ? interpolate(f, [BEAT.punch, BEAT.punch + 5], [1, 0], CLAMP)
          : interpolate(f, [BEAT.pull + 8, pullEnd], [0, 1], {
              ...CLAMP,
              easing: LIGHT_IN,
            });
    const shown =
      f < punchEnd
        ? Math.floor(typedA(f))
        : fs + Math.floor(typedF(f)) + Math.floor(typedP(f));
    const caretIdx = Math.min(prompt.length, shown);

    const segs: ReactNode[] = [];
    L.lines.forEach((ln, li) => {
      const ranges: [number, number, number][] = [
        [ln.start, Math.min(ln.end, fs), preOp],
        [Math.max(ln.start, fs), Math.min(ln.end, fe), 1],
        [Math.max(ln.start, fe), ln.end, 1],
      ];
      ranges.forEach(([a, b, op], ri) => {
        const to = Math.min(b, shown);
        if (to <= a || op <= 0.001) return;
        segs.push(
          <div
            key={`s${li}-${ri}`}
            style={{
              position: "absolute",
              left: L.charX(a),
              top: L.lineY(li) - L.T / 2,
              fontSize: L.T,
              lineHeight: 1,
              whiteSpace: "pre",
              fontFamily: face.fontFamily,
              fontWeight: 400,
              letterSpacing: `${TRACK}em`,
              color: inkC,
              opacity: op,
            }}
          >
            {prompt.slice(a, to)}
          </div>,
        );
      });
    });

    const typing =
      (f >= BEAT.typeA && f < BEAT.typeA + fs / rateA + 2) ||
      (f >= punchEnd && f < punchEnd + focusLen / rateF + 2) ||
      (f >= BEAT.post && f < postEnd + 2);
    const blinkOn = typing || Math.floor(f / 14) % 2 === 0;
    const caretFade =
      f >= postEnd + 4
        ? interpolate(f, [BEAT.press - 6, BEAT.press], [1, 0], CLAMP)
        : 1;
    const caretH = L.T * 1.18;
    const caretW = Math.max(L.T * 0.05, 1.6 / s);
    const caretLine = L.lineOf(Math.max(0, caretIdx === 0 ? 0 : caretIdx));
    const caret = (
      <div
        style={{
          position: "absolute",
          left: L.charX(caretIdx) + L.T * 0.04,
          top: L.lineY(caretLine) - caretH / 2,
          width: caretW,
          height: caretH,
          borderRadius: caretW,
          background: inkC,
          opacity: (blinkOn ? 1 : 0) * caretFade,
        }}
      />
    );

    const surfaceIn = interpolate(f, [BEAT.pull + 6, pullEnd], [0, 1], {
      ...CLAMP,
      easing: LIGHT_IN,
    });
    const u = L.u;
    const pop = (at: number) =>
      spring({
        frame: f - at,
        fps,
        config: { mass: 0.5, damping: 12, stiffness: 200 },
      });
    const toolIn = [0, 1, 2, 3, 4].map((i) => pop(pullEnd - 8 + i * 2));
    const armed = interpolate(f, [postEnd, postEnd + 4], [0, 1], CLAMP);
    const PRESS = { mass: 0.5, damping: 14, stiffness: 260 };
    const dip =
      spring({ frame: f - BEAT.press + 2, fps, config: PRESS }) -
      spring({ frame: f - BEAT.press - 3, fps, config: PRESS });
    const isPressed = f >= BEAT.press;
    const sendScale = 1 - 0.06 * dip;
    const sendBg = isPressed
      ? hi
      : `color-mix(in oklab, ${c.sendArmed} ${(armed * 100).toFixed(1)}%, ${c.send})`;
    const glyph = isPressed
      ? "#ffffff"
      : `color-mix(in oklab, ${c.sendGlyph} ${(armed * 100).toFixed(1)}%, ${c.muted})`;
    const stopIn = spring({
      frame: f - BEAT.press - 3,
      fps,
      config: { mass: 0.5, damping: 12, stiffness: 200 },
    });
    const arrowOut = interpolate(f - BEAT.press, [1, 5], [1, 0], CLAMP);
    const spin = interpolate(f - BEAT.press, [4, 12], [0, 1], {
      ...CLAMP,
      easing: LIGHT_IN,
    });
    const labelF = 15 * u;
    const ctrlD = 32 * u;

    const card = (
      <div
        style={{
          position: "absolute",
          left: L.cardX,
          top: L.cardY,
          width: L.cardW,
          height: L.cardH,
          borderRadius: 22 * u,
          background: c.card,
          boxShadow: `inset 0 0 0 1px ${c.border}, ${c.shadow}`,
          opacity: surfaceIn,
          transform: `scale(${(0.97 + 0.03 * surfaceIn).toFixed(4)})`,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: L.pad * 0.8,
            right: L.pad * 0.8,
            bottom: L.pad * 0.8,
            height: 36 * u,
            display: "flex",
            alignItems: "center",
            gap: 8 * u,
            fontFamily: face.fontFamily,
            fontWeight: 400,
            fontSize: labelF,
            color: c.muted,
          }}
        >
          <div
            style={{
              width: ctrlD,
              height: ctrlD,
              borderRadius: ctrlD,
              boxShadow: `inset 0 0 0 1px ${c.faint}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `scale(${toolIn[0].toFixed(4)})`,
            }}
          >
            <Icon size={18 * u} color={c.muted}>
              <path d="M12 5v14M5 12h14" />
            </Icon>
          </div>
          <div
            style={{
              height: ctrlD,
              padding: `0 ${12 * u}px 0 ${10 * u}px`,
              borderRadius: ctrlD,
              boxShadow: `inset 0 0 0 1px ${c.faint}`,
              display: "flex",
              alignItems: "center",
              gap: 6 * u,
              whiteSpace: "pre",
              transform: `scale(${toolIn[1].toFixed(4)})`,
              transformOrigin: "0% 50%",
            }}
          >
            <Icon size={16 * u} color={c.muted}>
              <rect x="3.5" y="5" width="17" height="14" rx="2.5" />
              <path d="M3.5 9.5h17M8 5v4.5M12 5v4.5M16 5v4.5" />
            </Icon>
            {chipLabel}
          </div>
          <div style={{ flex: 1 }} />
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 4 * u,
              whiteSpace: "pre",
              opacity: Math.min(1, toolIn[2]),
            }}
          >
            {modelLabel}
            <Icon size={14 * u} color={c.muted}>
              <path d="M7 10l5 5 5-5" />
            </Icon>
          </div>
          <div
            style={{
              position: "relative",
              width: L.sendD,
              height: L.sendD,
              flexShrink: 0,
              transform: `scale(${(toolIn[4] * sendScale).toFixed(4)})`,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: L.sendD,
                background: sendBg,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <div
                style={{
                  opacity: arrowOut,
                  transform: `translateY(${(-6 * u * (1 - arrowOut)).toFixed(3)}px)`,
                }}
              >
                <Icon size={18 * u} color={glyph}>
                  <path d="M12 19V5M6 11l6-6 6 6" />
                </Icon>
              </div>
              {isPressed ? (
                <div
                  style={{
                    position: "absolute",
                    width: 11 * u,
                    height: 11 * u,
                    borderRadius: 2.5 * u,
                    background: "#ffffff",
                    transform: `scale(${stopIn.toFixed(4)})`,
                  }}
                />
              ) : null}
            </div>
            {isPressed ? (
              <svg
                viewBox="0 0 40 40"
                width={L.sendD + 7 * u}
                height={L.sendD + 7 * u}
                style={{
                  position: "absolute",
                  left: -3.5 * u,
                  top: -3.5 * u,
                  opacity: spin,
                  transform: `rotate(${((f - BEAT.press) * 9).toFixed(2)}deg)`,
                }}
                aria-hidden
              >
                <circle
                  cx="20"
                  cy="20"
                  r="18.5"
                  fill="none"
                  stroke={hi}
                  strokeWidth={1.4}
                  strokeLinecap="round"
                  strokeDasharray="30 200"
                />
              </svg>
            ) : null}
          </div>
        </div>
      </div>
    );

    const world = (
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: W,
          height: H,
          transformOrigin: "0 0",
          transform: `translate(${(W / 2).toFixed(2)}px, ${(H / 2).toFixed(2)}px) scale(${s.toFixed(5)}) translate(${(-cam.x).toFixed(3)}px, ${(-cam.y).toFixed(3)}px)`,
        }}
      >
        {card}
        {segs}
        {caret}
      </div>
    );

    const curSize = portrait ? W * 0.05 : H * 0.05;
    const cursorP = spring({
      frame: f - BEAT.cursor,
      fps,
      config: { mass: 0.8, damping: 20, stiffness: 140 },
    });
    const cursorPy = spring({
      frame: f - BEAT.cursor - 3,
      fps,
      config: { mass: 0.8, damping: 20, stiffness: 140 },
    });
    const tx = W / 2 + (L.sendX + L.sendD * 0.12 - W / 2) * s;
    const ty = H / 2 + (L.sendY + L.sendD * 0.18 - H / 2) * s;
    const sx0 = W * (portrait ? 0.96 : 0.9);
    const sy0 = H * 1.06;
    const away = spring({
      frame: f - BEAT.press - 8,
      fps,
      config: { mass: 0.8, damping: 20, stiffness: 140 },
    });
    const curX = sx0 + (tx - sx0) * cursorP + curSize * 1.1 * away;
    const curY = sy0 + (ty - sy0) * cursorPy + curSize * 1.3 * away;
    const click = dip;
    const cursor =
      f >= BEAT.cursor ? (
        <svg
          viewBox="0 0 24 24"
          width={curSize}
          height={curSize}
          style={{
            position: "absolute",
            left: curX - curSize * 0.17,
            top: curY - curSize * 0.1,
            transform: `scale(${(1 - 0.12 * click).toFixed(4)})`,
            transformOrigin: "17% 10%",
            filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.28))",
          }}
          aria-hidden
        >
          <path
            d="M4.5 2.5v16.2l4.4-4.1 2.9 6.6 2.7-1.2-2.9-6.5h6.1z"
            fill={c.cursorFill}
            stroke={c.cursorStroke}
            strokeWidth={1.3}
            strokeLinejoin="round"
          />
        </svg>
      ) : null;

    content = (
      <>
        <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden>
          <filter id={filterId} x="-10%" y="-10%" width="120%" height="120%">
            <feGaussianBlur
              stdDeviation={`${bx.toFixed(2)} ${by.toFixed(2)}`}
            />
          </filter>
        </svg>
        <AbsoluteFill
          style={{ filter: bx > 0.2 ? `url(#${filterId})` : undefined }}
        >
          {world}
        </AbsoluteFill>
        {cursor}
      </>
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <GshGround
        preset={preset}
        params={gParams}
        timeOffset={c.groundOffset}
        timeScale={0.6}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(${portrait ? "90% 46%" : "64% 60%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
        }}
      />
      {content}
    </AbsoluteFill>
  );
}

export default CaretDolly;

"use client";

import { loadFont } from "@remotion/google-fonts/InterTight";
import { useLayoutEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const face = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

export interface CaretLetterProps {
  /** The word. The caret types every letter but one, then becomes that one. */
  word?: string;
  /** Index of the letter the caret turns into. Pick a plain stem: l, I, i without its dot, 1. */
  stemIndex?: number;
  /** Small grey line under the word. */
  subline?: string;
  /** Colour of the caret, and of the letter it becomes. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const THEMES = {
  light: { bg: "#FAFAF9", fg: "#0E0E0D", muted: "#8C8C88" },
  dark: { bg: "#0A0A0A", fg: "#F2F2F0", muted: "#7C7C79" },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_TYPE = Easing.bezier(0.4, 0, 0.3, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Beats, in frames at 30fps (before `speed`).
const CARET_IN = 0;
const TYPE = 46;
const TYPE_LEN = 46;
const LETTER_LEN = 16;
const SLIDE = 110;
const SLIDE_LEN = 26;
const OPEN = 118;
const OPEN_LEN = 24;
const MORPH = 134;
const MORPH_LEN = 16;
const SUB = 150;

/** Caret proportions in em. */
const CARET_W = 0.02;
const CARET_UP = 0.98;
const CARET_DOWN = 0.22;
const LINE_HEIGHT = 1.2;

interface Ink {
  left: number;
  right: number;
  top: number;
  bottom: number;
}

interface Layout {
  /** Letter origins in the finished word. */
  full: number[];
  /** Letter origins in the typed word (stem letter missing). */
  typed: number[];
  fullW: number;
  typedW: number;
  baseline: number;
  rowH: number;
  stem: Ink;
}

function measureInk(char: string, font: string, fontSize: number): Ink | null {
  const k = 4;
  const size = fontSize * k;
  const canvas = document.createElement("canvas");
  canvas.width = Math.ceil(size * 2);
  canvas.height = Math.ceil(size * 2);
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  const ox = Math.round(size * 0.5);
  const by = Math.round(size * 1.3);
  ctx.font = font.replace("{size}", `${size}px`);
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#000";
  ctx.fillText(char, ox, by);
  const { data, width, height } = ctx.getImageData(
    0,
    0,
    canvas.width,
    canvas.height,
  );
  let left = width;
  let right = 0;
  let top = height;
  let bottom = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (data[(y * width + x) * 4 + 3] > 127) {
        if (x < left) left = x;
        if (x + 1 > right) right = x + 1;
        if (y < top) top = y;
        if (y + 1 > bottom) bottom = y + 1;
      }
    }
  }
  if (right <= left) return null;
  return {
    left: (left - ox) / k,
    right: (right - ox) / k,
    top: (top - by) / k,
    bottom: (bottom - by) / k,
  };
}

function sameLayout(a: Layout | null, b: Layout) {
  return (
    a !== null &&
    a.full.join() === b.full.join() &&
    a.typed.join() === b.typed.join() &&
    a.baseline === b.baseline &&
    a.stem.left === b.stem.left
  );
}

export function CaretLetter({
  word = "launch",
  stemIndex = 0,
  subline = "Animated components for your next release.",
  accent = "#3B5BFD",
  theme = "light",
  speed = 1,
}: CaretLetterProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const t = THEMES[theme];

  const letters = Array.from(word);
  const stem = Math.max(0, Math.min(letters.length - 1, stemIndex));
  const typedLetters = letters.filter((_, i) => i !== stem);
  const fontSize = Math.round(width * 0.15);
  const subSize = Math.round(width * 0.0165);
  const textStyle = {
    fontFamily: face.fontFamily,
    fontSize,
    fontWeight: 300,
    letterSpacing: "-0.035em",
    lineHeight: LINE_HEIGHT,
    whiteSpace: "pre",
  } as const;

  const fullRef = useRef<HTMLDivElement>(null);
  const typedRef = useRef<HTMLDivElement>(null);
  const baseRef = useRef<HTMLSpanElement>(null);
  const [layout, setLayout] = useState<Layout | null>(null);
  const [handle] = useState(() => delayRender("caret-letter: measuring"));
  const released = useRef(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: re-measure when the copy or size changes
  useLayoutEffect(() => {
    let live = true;
    face
      .waitUntilDone()
      .catch(() => undefined)
      .then(() => document.fonts.ready)
      .then(() => {
        if (!live) return;
        const fullRow = fullRef.current;
        const typedRow = typedRef.current;
        const base = baseRef.current;
        if (fullRow && typedRow && base) {
          const origins = (row: HTMLDivElement) => {
            const r = row.getBoundingClientRect();
            const scale = r.width / row.offsetWidth || 1;
            const spans = Array.from(row.querySelectorAll("[data-l]"));
            return {
              xs: spans.map(
                (el) => (el.getBoundingClientRect().left - r.left) / scale,
              ),
              w: row.offsetWidth,
            };
          };
          const f = origins(fullRow);
          const ty = origins(typedRow);
          const family = face.fontFamily.includes('"')
            ? face.fontFamily
            : `"${face.fontFamily}"`;
          const ink = measureInk(
            letters[stem] ?? "l",
            `300 {size} ${family}`,
            fontSize,
          ) ?? {
            left: fontSize * 0.06,
            right: fontSize * 0.12,
            top: -fontSize * 0.74,
            bottom: 0,
          };
          const next: Layout = {
            full: f.xs,
            typed: ty.xs,
            fullW: f.w,
            typedW: ty.w,
            baseline: base.offsetTop,
            rowH: fullRow.offsetHeight,
            stem: ink,
          };
          setLayout((prev) => (sameLayout(prev, next) ? prev : next));
        }
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [word, stem, fontSize, handle]);

  const L = layout;
  const gap = fontSize * 0.05;
  const typedEnd = (L?.typedW ?? 0) + gap * 0.4;

  // Typing: the caret sweeps right, letters grow in its wake.
  const typeX = (f: number) =>
    interpolate(f, [TYPE, TYPE + TYPE_LEN], [0, typedEnd], {
      ...clamp,
      easing: EASE_TYPE,
    });
  // Right edge of each typed letter, for the moment the caret clears it.
  const typedRight = (j: number) =>
    j + 1 < typedLetters.length ? (L?.typed[j + 1] ?? 0) : (L?.typedW ?? 0);
  const letterIn = typedLetters.map((_, j) => {
    const left = L?.typed[j] ?? 0;
    const edge = typedRight(j) - (typedRight(j) - left) * 0.1;
    for (let f = TYPE; f <= TYPE + TYPE_LEN; f++)
      if (typeX(f) >= edge) return f - 2;
    return TYPE + TYPE_LEN;
  });

  // Slide home: the caret runs back into the word, the letters part for it.
  const slide = interpolate(frame, [SLIDE, SLIDE + SLIDE_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const open = interpolate(frame, [OPEN, OPEN + OPEN_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const morph = interpolate(frame, [MORPH, MORPH + MORPH_LEN], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });

  const ink = L?.stem ?? { left: 0, right: 0, top: 0, bottom: 0 };
  const stemOrigin = L?.full[stem] ?? 0;
  const stemCx = stemOrigin + (ink.left + ink.right) / 2;
  // Before the stem slot opens, the typed letters to its right sit where the
  // stem will go; the caret aims for the slot as it opens.
  const caretHome =
    stem < typedLetters.length
      ? interpolate(open, [0, 1], [L?.typed[stem] ?? 0, stemCx])
      : stemCx;
  const caretX =
    frame < SLIDE
      ? typeX(frame)
      : interpolate(slide, [0, 1], [typedEnd, caretHome]);

  // Centre the visible block, like centred text growing as it is typed.
  const typingCentre = typeX(frame) / 2;
  const fullCentre = (L?.fullW ?? 0) / 2;
  const centre = interpolate(slide, [0, 1], [typingCentre, fullCentre]);

  // Caret blink: soft on/off while idle, solid while it moves.
  const blinkAt = (f: number, from: number, to: number) => {
    if (f < from || f > to) return 1;
    const u = (f - from) % 24;
    if (u < 13) return 1;
    if (u < 16) return 1 - (u - 13) / 3;
    if (u < 21) return 0;
    return (u - 21) / 3;
  };
  const caretIn = interpolate(frame, [CARET_IN, CARET_IN + 10], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });
  const blink =
    frame < TYPE
      ? blinkAt(frame, 8, TYPE - 4)
      : blinkAt(frame, TYPE + TYPE_LEN + 2, SLIDE - 2);

  // Caret geometry, morphing into the stem of the letter.
  const baseline = L?.baseline ?? 0;
  const caretW = interpolate(
    morph,
    [0, 1],
    [fontSize * CARET_W, ink.right - ink.left],
  );
  const caretTop = interpolate(
    morph,
    [0, 1],
    [baseline - fontSize * CARET_UP, baseline + ink.top],
  );
  const caretBottom = interpolate(
    morph,
    [0, 1],
    [baseline + fontSize * CARET_DOWN, baseline + ink.bottom],
  );

  const subP = interpolate(frame, [SUB, SUB + 30], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });

  const rowH = L?.rowH ?? fontSize * LINE_HEIGHT;
  const left = width / 2 - centre;
  const top = height / 2 - rowH / 2 - height * 0.035;

  return (
    <AbsoluteFill style={{ background: t.bg, overflow: "hidden" }}>
      {/* measuring rows: never shown */}
      <div style={{ position: "absolute", visibility: "hidden", top: 0 }}>
        <div ref={fullRef} style={{ ...textStyle, display: "inline-block" }}>
          {letters.map((ch, i) => (
            <span key={i} data-l="">
              {ch}
            </span>
          ))}
          <span
            ref={baseRef}
            style={{ display: "inline-block", width: 0, height: 0 }}
          />
        </div>
        <br />
        <div ref={typedRef} style={{ ...textStyle, display: "inline-block" }}>
          {typedLetters.map((ch, i) => (
            <span key={i} data-l="">
              {ch}
            </span>
          ))}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left,
          top,
          width: 0,
          height: rowH,
          opacity: L ? 1 : 0,
        }}
      >
        {typedLetters.map((ch, j) => {
          const p = interpolate(
            frame,
            [letterIn[j] ?? TYPE, (letterIn[j] ?? TYPE) + LETTER_LEN],
            [0, 1],
            { ...clamp, easing: EASE_OUT },
          );
          const fullIndex = j < stem ? j : j + 1;
          const x = interpolate(
            open,
            [0, 1],
            [L?.typed[j] ?? 0, L?.full[fullIndex] ?? 0],
          );
          return (
            <span
              key={j}
              style={{
                ...textStyle,
                position: "absolute",
                left: x,
                top: 0,
                color: t.fg,
                opacity: p,
                filter: p < 1 ? `blur(${(1 - p) * 8}px)` : undefined,
                transformOrigin: `0px ${baseline}px`,
                transform: `scale(${0.6 + 0.4 * p})`,
              }}
            >
              {ch}
            </span>
          );
        })}

        <div
          style={{
            position: "absolute",
            left: caretX - caretW / 2,
            top: caretTop,
            width: caretW,
            height: caretBottom - caretTop,
            background: accent,
            borderRadius: interpolate(morph, [0, 1], [caretW / 2, 0]),
            opacity: caretIn * blink,
          }}
        />

        <div
          style={{
            position: "absolute",
            left: (L?.fullW ?? 0) / 2,
            top: rowH + fontSize * 0.02,
            transform: `translate(-50%, ${(1 - subP) * 12}px)`,
            whiteSpace: "nowrap",
            fontFamily: face.fontFamily,
            fontWeight: 400,
            fontSize: subSize,
            letterSpacing: "-0.005em",
            lineHeight: 1.4,
            color: t.muted,
            opacity: subP,
            filter: `blur(${(1 - subP) * 8}px)`,
          }}
        >
          {subline}
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface CaretSwapProps {
  fromText: string;
  toText: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  caretColor?: string;
  caretColorEnd?: string;
  swapAt?: number;
  typeSpeed?: number;
  speed?: number;
  className?: string;
}

const CARET_LEAD = 7;
const EXPAND_FRAMES = 6;
const COLLAPSE_FRAMES = 7;
const IDLE_FRAMES = 7;
const BLINK_FRAMES = 8;
const CARET_WIDTH_EM = 0.08;
const CARET_HEIGHT_EM = 1.1;
const CARET_GAP_EM = 0.06;
const CHAR_WIDTH_EM = 0.52;
const TYPE_ACCEL = 0.96;

function typeElapsed(count: number, typeSpeed: number): number {
  return (typeSpeed * (1 - TYPE_ACCEL ** count)) / (1 - TYPE_ACCEL);
}

export function caretSwapLength(
  toText: string,
  swapAt = 20,
  typeSpeed = 1,
): number {
  return Math.ceil(
    swapAt +
      EXPAND_FRAMES +
      COLLAPSE_FRAMES +
      IDLE_FRAMES +
      typeElapsed(Array.from(toText).length, typeSpeed),
  );
}

const expandEasing = Easing.bezier(0.6, 0, 0.8, 0.4);
const collapseEasing = Easing.bezier(0.2, 0.7, 0.3, 1);

export function CaretSwap({
  fromText,
  toText,
  fontSize = 72,
  color = "#171717",
  fontWeight = 400,
  caretColor = "#FF4DAA",
  caretColorEnd = "#8A5CF6",
  swapAt = 20,
  typeSpeed = 1,
  speed = 1,
  className,
}: CaretSwapProps) {
  const frame = useCurrentFrame() * speed;

  const toChars = Array.from(toText);
  const caretWidth = CARET_WIDTH_EM * fontSize;
  const caretHeight = CARET_HEIGHT_EM * fontSize;

  const caretVisibleAt = Math.max(swapAt - CARET_LEAD, 0);
  const expandEnd = swapAt + EXPAND_FRAMES;
  const collapseEnd = expandEnd + COLLAPSE_FRAMES;
  const typeStart = collapseEnd + IDLE_FRAMES;
  const typeEnd = typeStart + typeElapsed(toChars.length, typeSpeed);

  const expand = interpolate(frame, [swapAt, expandEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: expandEasing,
  });
  const collapse = interpolate(frame, [expandEnd, collapseEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: collapseEasing,
  });

  const typing = frame >= typeStart;
  let typedCount = 0;
  if (typing) {
    while (
      typedCount < toChars.length &&
      typeElapsed(typedCount, typeSpeed) <= frame - typeStart
    ) {
      typedCount++;
    }
  }
  const typed = toChars.slice(0, typedCount).join("");

  const anchorWidthEm =
    Array.from(fromText).length * CHAR_WIDTH_EM + CARET_WIDTH_EM + CARET_GAP_EM;
  const targetShiftEm = (anchorWidthEm - toChars.length * CHAR_WIDTH_EM) / 2;
  const typeProgress = toChars.length > 0 ? typedCount / toChars.length : 0;
  const typedShift = targetShiftEm * typeProgress * fontSize;

  const blinkOff =
    frame >= typeEnd + BLINK_FRAMES &&
    Math.floor((frame - typeEnd) / BLINK_FRAMES) % 2 === 1;

  const caretStyle = {
    background: `linear-gradient(180deg, ${caretColor}, ${caretColorEnd})`,
    borderRadius: fontSize * 0.03,
  };

  const overlayWidth =
    frame < expandEnd
      ? `calc(${(expand * 100).toFixed(3)}% + ${((1 - expand) * caretWidth).toFixed(2)}px)`
      : `calc(${((1 - collapse) * 100).toFixed(3)}% + ${(collapse * caretWidth).toFixed(2)}px)`;

  const tailSolidStop =
    frame < expandEnd ? 100 - 90 * expand : 10 + 90 * collapse;
  const tailMask =
    frame >= swapAt
      ? `linear-gradient(90deg, black ${tailSolidStop.toFixed(1)}%, transparent 100%)`
      : undefined;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        whiteSpace: "nowrap",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.02em",
          lineHeight: 1.15,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        <span
          style={{
            display: "inline-block",
            whiteSpace: "pre",
            visibility: frame < expandEnd ? "visible" : "hidden",
          }}
        >
          {fromText}
        </span>
        <span
          aria-hidden
          style={{
            ...caretStyle,
            display: "inline-block",
            flexShrink: 0,
            width: caretWidth,
            height: caretHeight,
            marginLeft: CARET_GAP_EM * fontSize,
            visibility: "hidden",
          }}
        />
        {!typing && (
          <span
            aria-hidden
            style={{
              ...caretStyle,
              position: "absolute",
              top: "50%",
              transform: "translateY(-50%)",
              height: caretHeight,
              ...(frame < swapAt
                ? { right: 0, width: caretWidth }
                : frame < expandEnd
                  ? { right: 0, width: overlayWidth }
                  : { left: 0, width: overlayWidth }),
              WebkitMaskImage: tailMask,
              maskImage: tailMask,
              opacity: frame >= caretVisibleAt ? 1 : 0,
            }}
          />
        )}
        {typing && (
          <span
            style={{
              position: "absolute",
              left: 0,
              top: "50%",
              transform: `translate(${typedShift.toFixed(1)}px, -50%)`,
              display: "inline-flex",
              alignItems: "center",
              whiteSpace: "pre",
            }}
          >
            <span style={{ display: "inline-block", whiteSpace: "pre" }}>
              {typed}
            </span>
            <span
              aria-hidden
              style={{
                ...caretStyle,
                display: "inline-block",
                flexShrink: 0,
                width: caretWidth,
                height: caretHeight,
                marginLeft: CARET_GAP_EM * fontSize,
                opacity: blinkOff ? 0 : 1,
              }}
            />
          </span>
        )}
      </span>
    </div>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export type CaretWipeProps = {
  /** Sweep direction. `right` types the screen left→right; `left` reverses it. */
  direction?: "left" | "right";
  /** The caret's color — the remocn lime by default. */
  caretColor?: string;
  /** Caret bar width in px. */
  caretWidth?: number;
  /** Caret bar height as a fraction of frame height (0–1), vertically centered. */
  caretHeight?: number;
};

// ---------------------------------------------------------------------------
// caret-wipe — a typographic scene transition.
//
// A single tall caret (the remocn text cursor) sweeps across the frame in one
// eased pass. The caret IS the wipe boundary: the region it has PASSED shows
// the incoming scene (freshly "typed in" — it settles down and un-blurs just
// behind the caret), while the region it has NOT reached still shows the
// outgoing scene (being "backspaced" — it lifts and blurs as it's consumed).
//
// Both scenes share whatever backdrop sits behind the TransitionSeries, so the
// complementary clips never expose a seam. Pure frame-driven interpolate — no
// CSS keyframes — so it seeks correctly and renders identically every time.
// ---------------------------------------------------------------------------
const CaretWipePresentation: React.FC<
  TransitionPresentationComponentProps<CaretWipeProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    direction = "right",
    caretColor = "#C3E88D",
    caretWidth = 3,
    caretHeight = 0.5,
  } = passedProps;

  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const goingRight = direction === "right";

  // Eased sweep so the caret decelerates as it lands the last column.
  const eased = interpolate(p, [0, 1], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.65, 0, 0.35, 1),
  });
  // Caret position as a percent of frame width; the wipe boundary.
  const caretX = goingRight ? eased * 100 : (1 - eased) * 100;

  if (!entering) {
    // Outgoing: keep only the column the caret hasn't reached yet, and let it
    // lift + blur as it's consumed (backspaced).
    const keep = goingRight
      ? `inset(0 0 0 ${caretX}%)` // keep the right band [caretX, 100]
      : `inset(0 ${100 - caretX}% 0 0)`; // keep the left band [0, caretX]
    return (
      <AbsoluteFill
        style={{
          clipPath: keep,
          WebkitClipPath: keep,
          translate: `0 ${interpolate(p, [0, 1], [0, -6], clampOpts)}px`,
          filter: `blur(${interpolate(p, [0.1, 1], [0, 4], clampOpts)}px)`,
        }}
      >
        {children}
      </AbsoluteFill>
    );
  }

  // Incoming: reveal only the column the caret has already passed, and let it
  // settle down + sharpen just behind the caret (typed in).
  const reveal = goingRight
    ? `inset(0 ${100 - caretX}% 0 0)` // reveal the left band [0, caretX]
    : `inset(0 0 0 ${caretX}%)`; // reveal the right band [caretX, 100]

  // The caret fades in at the very start and out at the very end so it never
  // pops on/off at the transition's frame edges.
  const caretOpacity = interpolate(
    p,
    [0, 0.08, 0.92, 1],
    [0, 1, 1, 0],
    clampOpts,
  );

  return (
    <AbsoluteFill>
      {/* Freshly typed content, clipped to the passed column. */}
      <AbsoluteFill
        style={{
          clipPath: reveal,
          WebkitClipPath: reveal,
          translate: `0 ${interpolate(p, [0, 1], [3, 0], clampOpts)}px`,
          filter: `blur(${interpolate(p, [0, 0.8], [2, 0], clampOpts)}px)`,
        }}
      >
        {children}
      </AbsoluteFill>

      {/* The caret — drawn on top, unclipped, only in the entering pass so it
          appears exactly once. */}
      <AbsoluteFill style={{ pointerEvents: "none", opacity: caretOpacity }}>
        <div
          style={{
            position: "absolute",
            left: `${caretX}%`,
            top: `${(1 - caretHeight) * 50}%`,
            height: `${caretHeight * 100}%`,
            width: caretWidth,
            translate: "-50%",
            background: caretColor,
            borderRadius: caretWidth,
            boxShadow: `0 0 18px ${caretColor}, 0 0 6px ${caretColor}`,
          }}
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export function caretWipe(
  props: CaretWipeProps = {},
): TransitionPresentation<CaretWipeProps> {
  return {
    component: CaretWipePresentation,
    props,
  };
}

"use client";

import { loadFont } from "@remotion/google-fonts/Nunito";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const nunito = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CarryCountProps {
  value?: number;
  from?: number;
  steps?: number;
  label?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#133A24",
    ink: "#EAF7EC",
    accent: "#FFD23F",
    carryInk: "#133A24",
  },
  light: {
    bg: "#FFD23F",
    ink: "#133A24",
    accent: "#FFFFFF",
    carryInk: "#133A24",
  },
} as const;

const FONT_PX = 200;
const TRACK = -0.02;
const LABEL_TRACK = -0.01;
const START = 16;
const STEP_LENS = [26, 20, 16, 14, 13, 12, 12, 12];
const COL_GAP = 5;
const NEW_COL_GAP = 3;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.5, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  slot: number;
  digit: number[];
  comma: number;
  cap: number;
  labelW: number[];
  labelCap: number;
  labelDesc: number;
  asc: number;
  desc: number;
}

function measure(lines: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("carry-count: no 2d context");
  const fam = `"${nunito.fontFamily}"`;
  ctx.font = `500 ${FONT_PX}px ${fam}`;
  const digit: number[] = [];
  for (let d = 0; d < 10; d++) {
    digit.push(ctx.measureText(String(d)).width / FONT_PX);
  }
  const slot = Math.max(...digit) + TRACK;
  const comma = ctx.measureText(",").width / FONT_PX + TRACK;
  const cap = ctx.measureText("0").actualBoundingBoxAscent / FONT_PX;
  ctx.font = `500 ${FONT_PX}px ${fam}`;
  const labelW = lines.map(
    (l) =>
      ctx.measureText(l).width / FONT_PX +
      LABEL_TRACK * Math.max(0, l.length - 1),
  );
  const lm = ctx.measureText("Hg");
  return {
    asc: lm.fontBoundingBoxAscent / FONT_PX,
    desc: lm.fontBoundingBoxDescent / FONT_PX,
    slot,
    digit,
    comma,
    cap,
    labelW,
    labelCap: ctx.measureText("H").actualBoundingBoxAscent / FONT_PX,
    labelDesc: lm.actualBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics(lines: string[]) {
  const key = lines.join("\n");
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("carry-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      nunito.waitUntilDone(),
      document.fonts.load(`500 100px "${nunito.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(key.split("\n")));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return metrics;
}

function digitsOf(n: number) {
  return Array.from(String(Math.max(0, Math.round(n))))
    .reverse()
    .map(Number);
}

interface Change {
  col: number;
  at: number;
  digit: number;
}

interface Carry {
  col: number;
  at: number;
  land: number;
}

function plan(from: number, value: number, steps: number) {
  const n = Math.max(1, Math.round(steps));
  const changes: Change[] = [];
  const carries: Carry[] = [];
  let cur = digitsOf(from);
  let at = START;
  for (let s = 0; s < n; s++) {
    const target = Math.round(from + ((value - from) * (s + 1)) / n);
    const prev = Math.round(from + ((value - from) * s) / n);
    const add = digitsOf(Math.max(0, target - prev));
    const next: number[] = [];
    let carry = 0;
    let time = at;
    const len = Math.max(cur.length, add.length);
    for (let i = 0; i < len || carry > 0; i++) {
      const sum = (cur[i] ?? 0) + (add[i] ?? 0) + carry;
      const d = sum % 10;
      next.push(d);
      if (d !== cur[i] || i >= cur.length) {
        changes.push({ col: i, at: time, digit: d });
      }
      carry = sum >= 10 ? 1 : 0;
      const gap = i + 1 >= len ? NEW_COL_GAP : COL_GAP;
      if (carry) carries.push({ col: i, at: time, land: time + gap });
      time += gap;
    }
    cur = next;
    at += STEP_LENS[Math.min(s, STEP_LENS.length - 1)];
  }
  const end = changes.reduce((m, c) => Math.max(m, c.at), START);
  return { start: digitsOf(from), changes, carries, cols: cur.length, end };
}

function impact(u: number) {
  if (u < 0) return 0;
  return Math.exp(-u / 3.2) * Math.cos(u * 0.62);
}

export function CarryCount({
  value = 13580,
  from = 2855,
  steps = 5,
  label = "scenes students\nbuilt in week one",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CarryCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const disc = accent ?? c.accent;
  const lines = useMemo(
    () =>
      label
        .split("\n")
        .map((l) => l.trim())
        .filter(Boolean),
    [label],
  );
  const m = useMetrics(lines);
  const p = useMemo(
    () => plan(Math.min(from, value), Math.max(from, value), steps),
    [from, value, steps],
  );

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const cols = p.cols;
  const commaAfter = (i: number) => i > 0 && i % 3 === 0;
  const offsets: number[] = [];
  let run = 0;
  for (let i = 0; i < cols; i++) {
    if (commaAfter(i)) run += m.comma;
    run += m.slot;
    offsets.push(run);
  }
  const numW = run;
  const labelW = Math.max(0, ...m.labelW);
  const portrait = H > W;
  const LR = 0.25;
  const lead = 1.12;
  const labelBlock =
    lines.length > 0 ? (lines.length - 1) * lead + m.labelCap : 0;

  let F: number;
  let numLeft: number;
  let base: number;
  let labelLeft: number;
  let labelBase: number;
  if (portrait) {
    F = Math.min((W * 0.86) / numW, H * 0.2);
    const L = F * LR * 1.25;
    const gapV = F * 0.34;
    const blockH = F * m.cap * 1.5 + gapV + labelBlock * L;
    const top = (H - blockH) / 2 + F * m.cap * 0.5;
    base = top + F * m.cap;
    numLeft = (W - numW * F) / 2;
    labelLeft = numLeft;
    labelBase = base + gapV + m.labelCap * L;
  } else {
    const gapH = 0.12;
    F = Math.min((W * 0.86) / (numW + gapH + labelW * LR), H * 0.4);
    const total = (numW + (lines.length ? gapH + labelW * LR : 0)) * F;
    numLeft = (W - total) / 2;
    base = H / 2 + (F * m.cap * 1.42) / 2;
    labelLeft = numLeft + (numW + gapH) * F;
    labelBase = base - (lines.length - 1) * lead * F * LR;
  }
  const L = portrait ? F * LR * 1.25 : F * LR;
  const right = numLeft + numW * F;
  const colX = (i: number) => right - offsets[i] * F;
  const capTop = base - m.cap * F;
  const bo = (size: number, lh: number) =>
    (lh - (m.asc + m.desc) * size) / 2 + m.asc * size;
  const digitTop = base - bo(F, F);

  const digitAt = (i: number) => {
    let d: number | null = i < p.start.length ? p.start[i] : null;
    let last = -1e9;
    for (const ch of p.changes) {
      if (ch.col === i && ch.at <= t) {
        d = ch.digit;
        last = ch.at;
      }
    }
    return { d, last };
  };

  const intro = interpolate(t, [0, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const glyphs: React.ReactNode[] = [];
  for (let i = 0; i < cols; i++) {
    const { d, last } = digitAt(i);
    if (d === null) continue;
    const born = i >= p.start.length ? last : -1e9;
    const grow =
      born > -1e8
        ? interpolate(t - born, [0, 7], [0.55, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          })
        : 1;
    const q = impact(t - last);
    const sy = (1 - 0.16 * q) * grow;
    const sx = (1 + 0.1 * q) * grow;
    const x = colX(i);
    const w = m.digit[d] * F;
    glyphs.push(
      <div
        key={`d${i}`}
        style={{
          position: "absolute",
          left: x + (m.slot * F - w) / 2,
          top: digitTop,
          height: F,
          fontSize: F,
          lineHeight: `${F}px`,
          fontFamily: nunito.fontFamily,
          fontWeight: 500,
          color: c.ink,
          whiteSpace: "pre",
          transform: `scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`,
          transformOrigin: `50% ${bo(F, F).toFixed(1)}px`,
          opacity: intro,
        }}
      >
        {d}
      </div>,
    );
    if (commaAfter(i) && i < cols) {
      const cx = colX(i) + m.slot * F;
      glyphs.push(
        <div
          key={`c${i}`}
          style={{
            position: "absolute",
            left: cx,
            top: digitTop,
            height: F,
            fontSize: F,
            lineHeight: `${F}px`,
            fontFamily: nunito.fontFamily,
            fontWeight: 500,
            color: c.ink,
            whiteSpace: "pre",
            opacity: intro * grow,
          }}
        >
          ,
        </div>,
      );
    }
  }

  const D = F * 0.34;
  const carryNodes: React.ReactNode[] = [];
  for (const k of p.carries) {
    const span = k.land - k.at;
    const u = ((t - k.at) / span) * COL_GAP;
    if (u < 0 || u > COL_GAP + 1) continue;
    const x0 = colX(k.col) + (m.slot * F) / 2;
    const x1 = colX(k.col + 1) + (m.slot * F) / 2;
    const hoverY = capTop - D * 0.95;
    const startY = capTop + D * 0.2;
    const a = interpolate(u, [0, COL_GAP * 0.52], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const dropP = interpolate(u, [COL_GAP * 0.68, COL_GAP], [0, 1], {
      ...CLAMP,
      easing: EASE_IN,
    });
    const x = x0 + (x1 - x0) * a;
    const lift = Math.sin(a * Math.PI) * D * 0.55;
    const y =
      startY +
      (hoverY - startY) * a -
      lift +
      (capTop + D * 0.15 - hoverY) * dropP;
    const s =
      interpolate(u, [0, 1.6], [0.5, 1], { ...CLAMP, easing: EASE_OUT }) *
      (1 - 0.35 * dropP);
    const o = interpolate(u, [COL_GAP - 0.4, COL_GAP + 0.6], [1, 0], CLAMP);
    carryNodes.push(
      <div
        key={`k${k.col}-${k.at}`}
        style={{
          position: "absolute",
          left: x - D / 2,
          top: y - D / 2,
          width: D,
          height: D,
          borderRadius: D,
          background: disc,
          color: c.carryInk,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: nunito.fontFamily,
          fontWeight: 500,
          fontSize: D * 0.72,
          lineHeight: 1,
          transform: `scale(${s.toFixed(3)})`,
          opacity: o,
        }}
      >
        <span style={{ transform: `translateY(${(-D * 0.02).toFixed(2)}px)` }}>
          1
        </span>
      </div>,
    );
  }

  const labelNodes = lines.map((line, k) => {
    const lp = interpolate(t, [6 + k * 4, 26 + k * 4], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const yb = labelBase + k * lead * L;
    return (
      <div
        key={`l${k}`}
        style={{
          position: "absolute",
          left: labelLeft,
          top: yb - bo(L, L * 1.45),
          height: L * 1.45,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            fontFamily: nunito.fontFamily,
            fontWeight: 500,
            fontSize: L,
            lineHeight: `${L * 1.45}px`,
            letterSpacing: `${LABEL_TRACK}em`,
            color: c.ink,
            whiteSpace: "pre",
            transform: `translateY(${((1 - lp) * L * 1.3).toFixed(2)}px)`,
          }}
        >
          {line}
        </div>
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {glyphs}
      {carryNodes}
      {labelNodes}
    </AbsoluteFill>
  );
}

