"use client";

import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const face = loadFont("normal", { weights: ["500"], subsets: ["latin"] });

export interface CaseFlipProps {
  /** The headline in its final casing. */
  text?: string;
  /** Word (as written in `text`) that lands in the accent color. */
  accentWord?: string;
  /** Frames between neighbouring glyphs in each wave. */
  stagger?: number;
  showGuides?: boolean;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const THEMES = {
  dark: { bg: "#0A0A0B", fg: "#F3F2EF" },
  light: { bg: "#F5F4F0", fg: "#121214" },
} as const;

// gradients.sh "halo" (bg #030306): warm peach through rose into blue. It
// fills the accent word once it lands, left to right, and its stops slide a
// few percent while the word holds. Light drops the palest stop.
const HALO = {
  dark: ["#ffb36b", "#e2457a", "#3d4dff"],
  light: ["#f08a3a", "#d6336c", "#3d4dff"],
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const WEIGHT = 500;
const PROBE = 200;
const TRACK_LOWER = -0.035;
const TRACK_UPPER = -0.01;
const FLIP = 10;

/** Per-slot glyph forms for the three casing stages: lower, UPPER, final. */
type Forms = [string, string, string];

interface Metrics {
  /** adv[i][own stage][next stage], in em, kerned against the next glyph. */
  adv: number[][][];
  /** Unkerned advance of each stage's glyph, in em. */
  plain: number[][];
  xHeight: number;
  capHeight: number;
}

function buildForms(text: string): Forms[] {
  return [...text].map((ch) => [ch.toLowerCase(), ch.toUpperCase(), ch]);
}

function isUpperLetter(ch: string) {
  return ch !== ch.toLowerCase() && ch === ch.toUpperCase();
}

function measure(forms: Forms[]): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const fallback = forms.map((f) =>
    [0, 1, 2].map((s) => [0, 1, 2].map(() => (f[s] === " " ? 0.26 : 0.6))),
  );
  if (!ctx) {
    return {
      adv: fallback,
      plain: fallback.map((a) => a.map((row) => row[0])),
      xHeight: 0.55,
      capHeight: 0.73,
    };
  }
  ctx.font = `${WEIGHT} ${PROBE}px "${face.fontFamily}"`;
  const w = (s: string) => ctx.measureText(s).width / PROBE;
  const adv = forms.map((f, i) => {
    const next = forms[i + 1];
    return [0, 1, 2].map((s) => {
      const own = f[s];
      const track = isUpperLetter(own) ? TRACK_UPPER : TRACK_LOWER;
      return [0, 1, 2].map((n) => {
        const kerned = next ? w(own + next[n]) - w(next[n]) : w(own);
        return kerned + (own === " " ? 0 : track);
      });
    });
  });
  const plain = forms.map((f) => f.map((g) => w(g)));
  const xHeight = ctx.measureText("x").actualBoundingBoxAscent / PROBE;
  const capHeight = ctx.measureText("H").actualBoundingBoxAscent / PROBE;
  return {
    adv,
    plain,
    xHeight: xHeight > 0 ? xHeight : 0.55,
    capHeight: capHeight > 0 ? capHeight : 0.73,
  };
}

function useMetrics(forms: Forms[]) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("case-flip: measuring glyphs"));
  const released = useRef(false);

  useEffect(() => {
    let live = true;
    Promise.all([
      face.waitUntilDone(),
      document.fonts.load(`${WEIGHT} 100px "${face.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(forms));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [forms, handle]);

  return metrics;
}

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

/** Sample a 3×3 table at fractional (stage, nextStage), bilinear. */
function sample(table: number[][], s: number, n: number) {
  const s0 = Math.min(1, Math.floor(s));
  const n0 = Math.min(1, Math.floor(n));
  const fs = s - s0;
  const fn = n - n0;
  const top = lerp(table[s0][n0], table[s0][n0 + 1], fn);
  const bottom = lerp(table[s0 + 1][n0], table[s0 + 1][n0 + 1], fn);
  return lerp(top, bottom, fs);
}

function mix(a: string, b: string, t: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (shift: number) =>
    Math.round(lerp((pa >> shift) & 255, (pb >> shift) & 255, t));
  return `rgb(${ch(16)}, ${ch(8)}, ${ch(0)})`;
}

function wordIndexOf(text: string, word: string) {
  if (!word) return [-1, -1];
  const at = text.indexOf(word);
  return at < 0 ? [-1, -1] : [at, at + word.length];
}

export function CaseFlip({
  text = "Launch it LOUD",
  accentWord = "LOUD",
  stagger = 2,
  showGuides = true,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: CaseFlipProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = W / 1280;
  const haloId = `cfh${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const forms = useMemo(() => buildForms(text), [text]);
  const metrics = useMetrics(forms);
  const [accentFrom, accentTo] = wordIndexOf(text, accentWord);

  if (!metrics)
    return <div style={{ position: "absolute", inset: 0, background: c.bg }} />;

  const n = forms.length;
  const wave1 = 16;
  const wave2 = wave1 + (n - 1) * stagger + FLIP + 12;
  const settled = wave2 + (n - 1) * stagger + FLIP;

  // Stage of each slot (0 lower → 1 UPPER → 2 final) and its flip clocks.
  const local = forms.map((_, i) => {
    const q1 = interpolate(
      t,
      [wave1 + i * stagger, wave1 + i * stagger + FLIP],
      [0, 1],
      CLAMP,
    );
    const q2 = interpolate(
      t,
      [wave2 + i * stagger, wave2 + i * stagger + FLIP],
      [0, 1],
      CLAMP,
    );
    return { q1, q2 };
  });
  const stage = local.map(({ q1, q2 }) => EASE_IO(q1) + EASE_IO(q2));

  const widest = Math.max(
    ...[0, 1, 2].map((s) =>
      metrics.adv.reduce((sum, a, i) => sum + a[s][i < n - 1 ? s : 0], 0),
    ),
  );
  const size = Math.min(H * 0.3, (W * 0.92) / widest);
  const cap = metrics.capHeight * size;
  const xh = metrics.xHeight * size;
  const baseline = H / 2 + cap / 2;

  const advances = forms.map((_, i) =>
    sample(metrics.adv[i], stage[i], i < n - 1 ? stage[i + 1] : 0),
  );
  const lineW = advances.reduce((a, b) => a + b, 0) * size;
  let cursor = W / 2 - lineW / 2;

  const enter = interpolate(t, [0, 14], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const guidesIn = interpolate(t, [2, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const guidesOut = interpolate(t, [settled, settled + 20], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const guideHalf = (lineW / 2 + size * 0.5) * guidesIn;
  const hair = Math.max(1, u);

  const lineL = cursor;
  const accentL =
    lineL +
    advances.slice(0, Math.max(0, accentFrom)).reduce((a, b) => a + b, 0) *
      size;
  const accentW =
    advances
      .slice(Math.max(0, accentFrom), Math.max(0, accentTo))
      .reduce((a, b) => a + b, 0) * size;
  const drift = interpolate(t, [settled, settled + 50], [0, 0.08], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const halo = HALO[theme];

  const glyphs = forms.map((f, i) => {
    const x = cursor;
    const slot = advances[i] * size;
    cursor += slot;
    if (f[0] === " ") return null;

    const { q1, q2 } = local[i];
    const flipping2 = q2 > 0;
    const q = flipping2 ? q2 : q1;
    const from = flipping2 ? f[1] : f[0];
    const to = flipping2 ? f[2] : f[1];
    const changes = from !== to;
    const firstHalf = q < 0.5;
    const shown = changes && firstHalf ? from : to;
    const shownStage = flipping2 ? (firstHalf ? 1 : 2) : firstHalf ? 0 : 1;
    const nextStage = i < n - 1 ? stage[i + 1] : 0;
    const ownSlot = sample(metrics.adv[i], shownStage, nextStage) * size;
    const glyphW = metrics.plain[i][shownStage] * size;

    // Squash onto the baseline, swap the glyph, spring back up.
    let sy = 1;
    let sx = 1;
    if (q > 0 && q < 1) {
      if (changes) {
        if (firstHalf) {
          const k = EASE_IN(q / 0.5);
          sy = lerp(1, 0.06, k);
          sx = lerp(1, 1.1, k);
        } else {
          const k = (q - 0.5) / 0.5;
          sy = interpolate(k, [0, 0.65, 1], [0.06, 1.045, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          sx = interpolate(k, [0, 0.65, 1], [1.1, 0.985, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
        }
      } else {
        const dip = Math.sin(Math.PI * q);
        sy = 1 - 0.1 * dip;
        sx = 1 + 0.03 * dip;
      }
    }

    const inAccent = i >= accentFrom && i < accentTo;
    // The wave front carries a brief accent tint; the accent word then takes
    // the halo gradient, faded in over its second flip.
    const pulse = changes ? Math.sin(Math.PI * q) * 0.55 : 0;
    const fill = pulse > 0 ? mix(c.fg, accent, pulse) : c.fg;
    const lit = inAccent ? EASE_OUT(q2) : 0;
    const cx = x + (slot - ownSlot) / 2 + glyphW / 2;
    const glyph = (paint: string, opacity: number, key: string) => (
      <text
        key={key}
        x={cx}
        y={baseline}
        textAnchor="middle"
        fontFamily={face.fontFamily}
        fontWeight={WEIGHT}
        fontSize={size}
        fill={paint}
        opacity={opacity}
        // Scale about the glyph's baseline point; at rest the transform is the
        // identity, so the shared gradient lines up across the whole word.
        transform={`translate(${cx} ${baseline}) scale(${sx} ${sy}) translate(${-cx} ${-baseline})`}
      >
        {shown}
      </text>
    );

    return (
      <g key={`${i}-${f[2]}`}>
        {lit < 1 ? glyph(fill, 1, "base") : null}
        {lit > 0 ? glyph(`url(#${haloId})`, lit, "halo") : null}
      </g>
    );
  });

  const guideYs = [baseline, baseline - xh, baseline - cap];

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={haloId}
            gradientUnits="userSpaceOnUse"
            x1={accentL - accentW * 0.05}
            y1={baseline - cap}
            x2={accentL + accentW * 1.05}
            y2={baseline}
          >
            <stop offset={0.04 - drift} stopColor={halo[0]} />
            <stop offset={0.5 - drift} stopColor={halo[1]} />
            <stop offset={1 - drift} stopColor={halo[2]} />
          </linearGradient>
        </defs>
        {showGuides
          ? guideYs.map((y, k) => (
              <rect
                key={y}
                x={W / 2 - guideHalf}
                y={y - hair / 2}
                width={guideHalf * 2}
                height={hair}
                fill={c.fg}
                opacity={guidesIn * (k === 0 ? 0.16 : 0.1) * guidesOut}
              />
            ))
          : null}
        <g
          opacity={enter}
          transform={`translate(0 ${(1 - enter) * cap * 0.12})`}
        >
          {glyphs}
        </g>
      </svg>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import { type CSSProperties, type ReactNode, useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

// gradients.sh "beam" palette
const BEAM = {
  bg: "#02030a",
  c: ["#f4f7ff", "#8fb4ff", "#3d5bff", "#1a1660"],
} as const;

export interface CellDivideProps {
  generations?: number;
  label?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const RAYS = 96;
const R_RATIO = 0.4;
const SQ2 = Math.SQRT2;
const START = 14;
const MOTION = [17, 15, 14, 13, 12, 12, 12];
const PAUSE = 4;
const SWITCH_AT = 0.74;
const ROLL = 9;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_DIV = Easing.bezier(0.42, 0, 0.45, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: BEAM.bg,
    fg: "#F3F2EF",
    muted: "#8E90A0",
    stops: [BEAM.c[0], BEAM.c[1], BEAM.c[2], "#2a35a8"],
    glow: 0.2,
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    stops: [BEAM.c[1], "#6f8dff", BEAM.c[2], BEAM.c[3]],
    glow: 0,
    grain: 0.045,
  },
} as const;

function gridOf(g: number) {
  return { cols: 2 ** Math.ceil(g / 2), rows: 2 ** Math.floor(g / 2) };
}

function schedule(G: number) {
  let t = START;
  const divs: { start: number; dur: number }[] = [];
  for (let g = 0; g < G; g++) {
    const dur = MOTION[Math.min(g, MOTION.length - 1)];
    divs.push({ start: t, dur });
    t += dur + PAUSE;
  }
  return { divs, end: t - PAUSE };
}

function smin(a: number, b: number, k: number) {
  if (k <= 1e-6) return Math.min(a, b);
  const h = Math.max(k - Math.abs(a - b), 0) / k;
  return Math.min(a, b) - (h * h * k) / 4;
}

function lobe(
  mx: number,
  my: number,
  ex: number,
  ey: number,
  sep: number,
  rho: number,
  k: number,
) {
  const half = sep / 2;
  const fx = -ey;
  const fy = ex;
  const sdf = (u: number, v: number) =>
    smin(Math.hypot(u - half, v) - rho, Math.hypot(u + half, v) - rho, k);
  const reach = rho + k / 4;
  const pinched = half >= reach;
  const neckH = pinched ? 0 : Math.sqrt(reach * reach - half * half);
  const angles: { a: number; neck: number }[] = [];
  for (let i = 0; i < RAYS; i++)
    angles.push({ a: (i / RAYS) * Math.PI * 2, neck: 0 });
  if (!pinched) {
    const n1 = Math.atan2(neckH, -half);
    const n2 = Math.atan2(-neckH, -half) + Math.PI * 2;
    angles.push({ a: n1, neck: 1 }, { a: n2, neck: -1 });
    angles.sort((p, q) => p.a - q.a);
  }
  const rMax = 2 * rho + k + sep;
  const step = Math.max(rho / 14, 0.4);
  const pts: string[] = [];
  for (const { a, neck } of angles) {
    let u: number;
    let v: number;
    if (neck !== 0) {
      u = 0;
      v = neck * neckH;
    } else {
      const c = Math.cos(a);
      const s = Math.sin(a);
      const rEnd = c < -1e-9 ? Math.min(rMax, half / -c) : rMax;
      let lo = 0;
      let hi = -1;
      for (let r = step; r < rEnd; r += step) {
        if (sdf(half + r * c, r * s) > 0) {
          hi = r;
          break;
        }
        lo = r;
      }
      if (hi < 0 && sdf(half + rEnd * c, rEnd * s) > 0) hi = rEnd;
      let r = rEnd;
      if (hi >= 0) {
        for (let it = 0; it < 12; it++) {
          const mid = (lo + hi) / 2;
          if (sdf(half + mid * c, mid * s) > 0) hi = mid;
          else lo = mid;
        }
        r = (lo + hi) / 2;
      }
      u = half + r * c;
      v = r * s;
    }
    const x = mx + ex * u + fx * v;
    const y = my + ey * u + fy * v;
    pts.push(`${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return `M${pts.join("L")}Z`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={41}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function CellDivide({
  generations = 6,
  label = "×2 every week",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: CellDivideProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const G = Math.max(2, Math.min(7, Math.round(generations)));
  const { divs, end } = schedule(G);

  const heroSize = 176 * u;
  const labelSize = 24 * u;
  const finalCount = 2 ** G;
  const heroW = String(finalCount).length * 0.6 * heroSize;
  const labelW = label.length * 0.56 * labelSize + 24 * u;
  const textW = Math.max(heroW, labelW);
  const gap = 72 * u;
  const f = G % 2 === 0 ? 1 : SQ2;
  const E = Math.min(
    height * 0.6,
    (0.44 * width - (gap + textW) / 2) / (SQ2 - f / 2),
    (0.88 * width - gap - textW) / f,
  );
  const slotRight = width / 2 - (f * E + gap + textW) / 2 + f * E;
  const cy = height / 2;

  const pitchOf = (g: number) => E / 2 ** (g / 2);
  const posOf = (g: number, c: number, r: number) => {
    const { cols, rows } = gridOf(g);
    const pitch = pitchOf(g);
    const cx = slotRight - (cols * pitch) / 2;
    return {
      x: cx + (c - (cols - 1) / 2) * pitch,
      y: cy + (r - (rows - 1) / 2) * pitch,
    };
  };

  let gen = 0;
  let active = -1;
  let s = 0;
  for (let g = 0; g < divs.length; g++) {
    const d = divs[g];
    if (t >= d.start + d.dur) gen = g + 1;
    else if (t >= d.start) {
      active = g;
      s = (t - d.start) / d.dur;
      break;
    }
  }

  const intro = interpolate(t, [0, 16], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const push = interpolate(t, [0, end + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const camScale = 0.985 + 0.03 * push;

  const gradId = `cd${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const colW = f * E;
  const colCx = slotRight - colW / 2;
  const gradCx = colCx - colW * (0.34 - 0.1 * push);
  const gradCy = cy - E * (0.42 - 0.06 * push);
  const gradR = Math.hypot(colW, E) * 0.98;
  const cellFill = `url(#${gradId})`;

  const shapes: ReactNode[] = [];
  if (active >= 0) {
    const g = active;
    const { cols, rows } = gridOf(g);
    const horiz = g % 2 === 0;
    const pitchP = pitchOf(g);
    const pitchC = pitchOf(g + 1);
    const e = interpolate(EASE_DIV(s), [0, 0.3, 0.78, 1], [0, 0.44, 0.86, 1]);
    const k0 = 0.55 * R_RATIO * pitchP;
    const k = k0 * (1 - e);
    const rho0 = R_RATIO * pitchP - k0 / 4;
    const rho1 = R_RATIO * pitchC;
    const rho = rho0 + (rho1 - rho0) * Math.min(1, e / 0.7);
    const sep = pitchC * e;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const P = posOf(g, c, r);
        const d1 = horiz ? posOf(g + 1, 2 * c, r) : posOf(g + 1, c, 2 * r);
        const d2 = horiz
          ? posOf(g + 1, 2 * c + 1, r)
          : posOf(g + 1, c, 2 * r + 1);
        const mx = P.x + ((d1.x + d2.x) / 2 - P.x) * e;
        const my = P.y + ((d1.y + d2.y) / 2 - P.y) * e;
        const ex = horiz ? 1 : 0;
        const ey = horiz ? 0 : 1;
        const d =
          lobe(mx, my, ex, ey, sep, rho, k) +
          lobe(mx, my, -ex, -ey, sep, rho, k);
        shapes.push(<path key={`${c}-${r}`} d={d} fill={cellFill} />);
      }
    }
  } else {
    const { cols, rows } = gridOf(gen);
    const rad = R_RATIO * pitchOf(gen);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const P = posOf(gen, c, r);
        const wave =
          gen === G
            ? Math.sin(
                Math.PI *
                  interpolate(
                    t,
                    [end + 2 + (c + r) * 0.6, end + 11 + (c + r) * 0.6],
                    [0, 1],
                    CLAMP,
                  ),
              )
            : 0;
        const introScale = gen === 0 ? 0.86 + 0.14 * intro : 1;
        shapes.push(
          <circle
            key={`${c}-${r}`}
            cx={P.x}
            cy={P.y}
            r={rad * introScale * (1 + 0.07 * wave)}
            fill={cellFill}
          />,
        );
      }
    }
  }

  const switches = divs.map((d) => d.start + d.dur * SWITCH_AT);
  let shown = 0;
  for (let i = 0; i < switches.length; i++) if (t >= switches[i]) shown = i + 1;
  const rollK =
    shown > 0
      ? interpolate(
          t,
          [switches[shown - 1], switches[shown - 1] + ROLL],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_OUT,
          },
        )
      : 1;
  const cur = 2 ** shown;
  const prev = shown > 0 ? 2 ** (shown - 1) : cur;
  const rolling = rollK < 1;

  const textIn = interpolate(t, [6, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelIn = interpolate(t, [12, 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lineH = heroSize * 0.98;
  const numStyle: CSSProperties = {
    fontFamily: sora,
    fontWeight: 300,
    fontSize: heroSize,
    lineHeight: `${lineH}px`,
    height: lineH,
    letterSpacing: "-0.05em",
    color: p.fg,
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(${colW * 0.95}px ${E * 0.95}px at ${colCx}px ${cy}px, color-mix(in oklab, ${BEAM.c[2]} ${p.glow * 100}%, transparent) 0%, transparent 100%)`,
          opacity: intro,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${camScale})`,
          transformOrigin: "50% 50%",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, opacity: intro }}
          aria-hidden
        >
          <defs>
            <radialGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              cx={gradCx}
              cy={gradCy}
              r={gradR}
            >
              <stop offset="0" stopColor={p.stops[0]} />
              <stop offset="0.3" stopColor={p.stops[1]} />
              <stop offset="0.66" stopColor={p.stops[2]} />
              <stop offset="1" stopColor={p.stops[3]} />
            </radialGradient>
          </defs>
          {shapes}
        </svg>

        <div
          style={{
            position: "absolute",
            left: slotRight + gap,
            top: cy,
            transform: "translateY(-50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            gap: 16 * u,
          }}
        >
          <div
            style={{
              position: "relative",
              height: lineH,
              overflow: "hidden",
              opacity: textIn,
              transform: `translateY(${(1 - textIn) * 14 * u}px)`,
            }}
          >
            <div
              style={{
                ...numStyle,
                transform: `translateY(${rolling ? (1 - rollK) * lineH : 0}px)`,
              }}
            >
              {cur}
            </div>
            {rolling ? (
              <div
                style={{
                  ...numStyle,
                  position: "absolute",
                  left: 0,
                  top: 0,
                  transform: `translateY(${-rollK * lineH}px)`,
                }}
              >
                {prev}
              </div>
            ) : null}
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 12 * u,
              marginLeft: 6 * u,
              opacity: labelIn,
              transform: `translateY(${(1 - labelIn) * 8 * u}px)`,
            }}
          >
            <span
              style={{
                width: 10 * u,
                height: 10 * u,
                borderRadius: "50%",
                background: accent,
                flexShrink: 0,
              }}
            />
            <span
              style={{
                fontFamily: sora,
                fontWeight: 400,
                fontSize: labelSize,
                letterSpacing: "-0.015em",
                color: p.muted,
                whiteSpace: "nowrap",
              }}
            >
              {label}
            </span>
          </div>
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${p.bg} 100%)`,
          opacity: 0.5,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface CenteredWordBuildProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  wordGap?: number;
  accel?: number;
  rise?: number;
  zoomStep?: number;
  settleFrames?: number;
  exitAt?: number;
  exitFrames?: number;
  speed?: number;
  className?: string;
}

function revealFrame(index: number, wordGap: number, accel: number): number {
  let frame = 0;

  for (let step = 1; step <= index; step++) {
    // Establish two even beats before tightening the cadence.
    frame += wordGap * accel ** Math.max(step - 2, 0);
  }

  return Math.round(frame);
}

export function centeredWordBuildLength(
  text: string,
  wordGap = 11,
  accel = 0.75,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
): number {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 0;

  const lastReveal = revealFrame(words.length - 1, wordGap, accel);
  return Math.max(lastReveal + settleFrames, exitAt + exitFrames);
}

const settleEasing = Easing.bezier(0.16, 1, 0.3, 1);

export function CenteredWordBuild({
  text,
  fontSize = 52,
  color = "#fff3df",
  fontWeight = 400,
  wordGap = 11,
  accel = 0.75,
  rise = 0.18,
  zoomStep = 0.035,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
  speed = 1,
  className,
}: CenteredWordBuildProps) {
  const frame = useCurrentFrame() * speed;
  const words = text.trim().split(/\s+/).filter(Boolean);

  if (words.length === 0) return null;

  const visibleCount = words.filter(
    (_, index) => frame >= revealFrame(index, wordGap, accel),
  ).length;
  let cameraScale = 1;
  for (let index = 1; index < visibleCount; index++) {
    const revealAt = revealFrame(index, wordGap, accel);
    cameraScale +=
      zoomStep *
      interpolate(
        frame,
        [revealAt, revealAt + Math.max(settleFrames, 0.001)],
        [0, 1],
        {
          easing: settleEasing,
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      );
  }
  const exitProgress = interpolate(
    frame,
    [exitAt, exitAt + Math.max(exitFrames, 0.001)],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const fadeStart = -35 + exitProgress * 135;
  const fadeEnd = fadeStart + 35;
  const exitMask = `linear-gradient(90deg, transparent ${fadeStart}%, black ${fadeEnd}%)`;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          color,
          display: "inline-block",
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
          fontSize,
          fontWeight,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          scale: `${cameraScale}`,
          opacity: exitProgress >= 1 ? 0 : 1,
          maskImage: exitProgress > 0 ? exitMask : undefined,
          WebkitMaskImage: exitProgress > 0 ? exitMask : undefined,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {words.slice(0, visibleCount).map((word, index) => {
          const revealAt = revealFrame(index, wordGap, accel);
          const y = interpolate(
            frame,
            [revealAt, revealAt + Math.max(settleFrames, 0.001)],
            [rise * fontSize, 0],
            {
              easing: settleEasing,
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            },
          );

          return (
            <span
              key={index}
              style={{
                display: "inline-block",
                marginLeft: index > 0 ? "0.25em" : undefined,
                translate: `0 ${y}px`,
              }}
            >
              {word}
            </span>
          );
        })}
      </span>
    </div>
  );
}

