function Row({
  entry,
  y,
  left,
  right,
  textLeft,
  rowFont,
  dateFont,
  rowH,
  opacity,
  c,
}: {
  entry: ChangelogEntry;
  y: number;
  left: number;
  right: number;
  textLeft: number;
  rowFont: number;
  dateFont: number;
  rowH: number;
  opacity: number;
  c: (typeof THEMES)[keyof typeof THEMES];
}) {
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: y - rowH / 2,
        height: rowH,
        opacity,
      }}
    >
      <div
        style={{
          position: "absolute",
          left,
          top: 0,
          height: rowH,
