                        opacity: cursorOpacity,
                        zIndex: 5,
                      }}
                    >
                      <MacCursor press={clamp(press)} />
                    </div>
                  </div>
                </Grow>
                {replies.map((r, i) => {
                  const p = sp(replyAt[i], MORPH, 14);
                  const o = ease(replyAt[i], replyAt[i] + 10);
                  return (
                    <Grow key={r.text} p={p}>
                      <div
                        style={{
                          opacity: o,
                          transform: `translateY(${(1 - o) * 12}px)`,
                        }}
                      >
                        <Message
                          person={r.author}
                          time="10:31 AM"
                          pal={pal}
                          pad={PAD}
                          context={
                            tall ? undefined : `${message.slice(0, 18)}…`
                          }
                        >
                          {r.text}
                        </Message>
                      </div>
                    </Grow>
                  );
                })}
              </div>
            </div>
            <div style={{ padding: `0 ${PAD}px 8px`, flexShrink: 0 }}>
              <div
                style={{
                  borderRadius: 12,
                  height: 52,
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  padding: "0 14px",
                  boxSizing: "border-box",
                  boxShadow: `inset 0 0 0 1px ${pal.rule}`,
                }}
              >
                {ic(I.plus, pal.muted, 18)}
                <span style={{ fontSize: 16, color: pal.muted, flex: 1 }}>
                  Message #{channel}
                </span>
                {ic(I.send, pal.muted, 18)}
              </div>
              <div
                style={{
                  height: 22,
                  fontSize: 14,
                  color: pal.muted,
                  paddingTop: 4,
                  opacity: typing,
                }}
              >
                <span style={{ color: pal.text }}>{author.name}</span> is
                typing…
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

