            opacity: pillFade.opacity,
            translate: `0 ${pillFade.translateY + intro.translateY * 0.6}px`,
            scale: `${intro.scale}`,
            transformOrigin: "center top",
            display: "flex",
            alignItems: "center",
            paddingLeft: 20,
