              <span style={{ color: t.fg }}>
                {visibleText}
                <Caret
                  color={t.fg}
                  blink={!tw.typing}
                  speed={speed}
                  height={24}
                  radius={0}
                  marginLeft={1}
                  style={{
                    verticalAlign: "text-bottom",
                    translate: "0 3px",
                  }}
                />
              </span>
            ) : (
              <span
                style={{
                  color: t.placeholder,
                  display: "inline-flex",
                  alignItems: "center",
                }}
              >
                <Caret
                  color={t.fg}
                  blink={!tw.typing}
                  speed={speed}
                  height={24}
                  radius={0}
                  marginLeft={1}
                  style={{
                    verticalAlign: "text-bottom",
                    translate: "0 3px",
                  }}
                />
                <span style={{ marginLeft: 2 }}>{placeholder}</span>
              </span>
            )}
          </div>

          <div
            style={{
              padding: "14px 18px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <IconButton size={iconBtnSize} border={t.iconBtnBorder}>
              <PlusIcon size={20} color={t.fg} />
            </IconButton>

            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 14,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 7,
                }}
              >
                <span
                  style={{
                    fontFamily: SANS_FAMILY,
                    fontSize: 18,
                    fontWeight: 500,
                    color: t.fg,
                  }}
                >
                  {modelName}
                </span>
                <span
                  style={{
                    fontFamily: SANS_FAMILY,
                    fontSize: 18,
                    fontWeight: 400,
                    color: t.fgMuted,
                  }}
                >
                  {modelTier}
