                  }}
                >
                  <WaveformIcon size={22} color={t.fg} />
                </div>
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    borderRadius: 10,
                    background: accentColor,
                    opacity: morph,
                    scale: `${0.8 + 0.2 * morph}`,
                  }}
                >
                  <SendIcon size={22} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

