const MAX_MORPH = 120;
const MIN_FONT = 10;
const MAX_FONT = 40;
const LINE_COST = 10;
const COLUMN_COST = 0.5;
const MAX_COST = 1000;
const PUNCT_VALUE = 12;
const TAB = "  ";

const KEYWORDS = new Set([
  "abstract",
  "as",
  "async",
  "await",
  "break",
  "case",
  "catch",
  "class",
  "const",
  "continue",
