  "protected",
  "public",
  "readonly",
  "return",
  "satisfies",
  "static",
  "super",
  "switch",
  "this",
  "throw",
  "true",
  "try",
  "type",
  "typeof",
  "undefined",
  "var",
  "void",
  "while",
  "yield",
]);

const OPERATORS = [
  "===",
  "!==",
  "**=",
  "...",
  "&&=",
  "||=",
  "??=",
  "=>",
  "==",
  "!=",
  "<=",
  ">=",
  "&&",
  "||",
  "??",
  "?.",
  "++",
  "--",
  "+=",
  "-=",
  "*=",
  "/=",
  "%=",
  "**",
  "</",
  "/>",
];

const NUMBER =
  /0[xXbBoO][\dA-Fa-f_]+n?|\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?\d+)?n?/y;
const WORD =
  /[A-Za-z_$\u00c0-\u024f\u0370-\u03ff][\w$\u00c0-\u024f\u0370-\u03ff]*/y;
const SPACE = /\s/;
const CAPITAL = /^[A-Z]/;
const OPENERS = new Set(["(", "[", "{"]);
const CLOSERS = new Map([
  [")", "("],
  ["]", "["],
  ["}", "{"],
]);

const glide = Easing.bezier(0.6, 0, 0.2, 1);

