const NEWS_ITALIC_EXTRA: Record<string, number> = {
  "’": 236,
  "‘": 234,
  "“": 408,
  "”": 409,
  "–": 499,
  "—": 656,
  "…": 633,
};

function kernMap(pairs: string) {
  return new Map(
    pairs.split(" ").map((p) => [p.slice(0, 2), Number(p.slice(2)) / 1000]),
  );
}
const KERN_SANS = kernMap(NEWS_KERN);
const KERN_SERIF = kernMap(NEWS_ITALIC_KERN);

const TRACK = -0.008;
const SERIF_SCALE = 1.04;
const SPACE = 0.229 + TRACK;
const NARROW_EM = 9.6;
const LEADING = 1.3;
const BASELINE_SANS = 0.735;
const BASELINE_SERIF = 0.735;

const ENTER = -4;
const X_START = 22;
const X_DUR = 24;
const X_ROW = 1.5;
const X_WORD = 0.7;
const Y_START = 44;
const Y_DUR = 26;
const Y_ROW = 2;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_Y = Easing.bezier(0.55, 0, 0.25, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    key: "rgba(255,255,255,0.05)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.16)",
    grain: 0.07,
  },
  light: {
    bg: "#F5F4F0",
    key: "rgba(255,255,255,0.9)",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.16)",
    grain: 0.045,
  },
} as const;

function advance(
  text: string,
  table: number[],
  extra: Record<string, number>,
  kern: Map<string, number>,
  track: number,
) {
  let w = 0;
  let prev = "";
  for (const ch of text) {
    w += kern.get(prev + ch) ?? 0;
    prev = ch;
    const code = ch.charCodeAt(0);
    const a = code >= 32 && code < 127 ? table[code - 32] : (extra[ch] ?? 600);
    w += a / 1000 + track;
  }
  return w;
}

const sansEm = (s: string) => advance(s, NEWS, NEWS_EXTRA, KERN_SANS, TRACK);
const serifEm = (s: string) =>
  advance(s, NEWS_ITALIC, NEWS_ITALIC_EXTRA, KERN_SERIF, 0) * SERIF_SCALE;

interface Word {
  core: string;
  tail: string;
  serif: boolean;
  w: number;
}

function strip(s: string) {
  return s.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
}

function toWords(text: string, accentWord: string): Word[] {
  const target = strip(accentWord);
  let used = false;
  return text
    .trim()
    .split(/\s+/)
    .map((raw) => {
      const isAccent = !used && target.length > 0 && strip(raw) === target;
      if (!isAccent) {
        return { core: raw, tail: "", serif: false, w: sansEm(raw) };
      }
      used = true;
      const m = /^(.*?)([^\p{L}\p{N}]*)$/u.exec(raw);
      const core = m ? m[1] : raw;
      const tail = m ? m[2] : "";
      return {
        core,
        tail,
        serif: true,
        w: serifEm(core) + (tail ? 0.04 + sansEm(tail) : 0),
      };
    });
}

/**
 * Break into justified rows with the least stretched word spacing (a small
 * Knuth–Plass: dynamic programming over break points). Returns the cost too,
 * so the caller can try a few measures and keep the evenest column.
 */
function breakRows(words: Word[], measure: number) {
  const n = words.length;
  const best = new Array<number>(n + 1).fill(Number.POSITIVE_INFINITY);
  const from = new Array<number>(n + 1).fill(0);
  best[0] = 0;
  for (let j = 1; j <= n; j++) {
    let width = -SPACE;
    for (let i = j - 1; i >= 0; i--) {
      width += words[i].w + SPACE;
      if (width > measure && i < j - 1) break;
      const count = j - i;
      let cost = 0;
      if (j < n) {
        const gap = count > 1 ? (measure - width) / (count - 1) + SPACE : 9;
        const stretch = (gap - SPACE) / SPACE;
        cost = stretch * stretch + (count < 3 ? 1.5 : 0);
      } else if (width < measure * 0.3) {
        cost = 1;
      }
      if (best[i] + cost < best[j]) {
        best[j] = best[i] + cost;
        from[j] = i;
      }
    }
  }
  const rows: number[][] = [];
  for (let j = n; j > 0; j = from[j]) {
    const row: number[] = [];
    for (let k = from[j]; k < j; k++) row.push(k);
    rows.unshift(row);
  }
  return { rows, cost: best[n] };
}

function chooseMeasure(words: Word[]) {
  let pick = { measure: NARROW_EM, rows: breakRows(words, NARROW_EM).rows };
  let low = Number.POSITIVE_INFINITY;
  for (let m = NARROW_EM - 1; m <= NARROW_EM + 1.001; m += 0.1) {
    const { rows, cost } = breakRows(words, m);
    const paired: number[] = [];
    for (let r = 0; r + 1 < rows.length - 1; r += 2) {
      paired.push(rowWidth(words, [...rows[r], ...rows[r + 1]]));
    }
    const top = Math.max(1, ...paired);
    const rag = paired.reduce((s, w) => s + ((top - w) / top) ** 2, 0);
    const score = cost + rag * 40 + Math.abs(m - NARROW_EM) * 0.4;
    if (rows.length > 1 && score < low) {
      low = score;
      pick = { measure: m, rows };
    }
  }
  return pick;
}

function rowWidth(words: Word[], row: number[]) {
  return row.reduce((s, i) => s + words[i].w, 0) + SPACE * (row.length - 1);
}

/** x offsets (em) of each word in a row, justified unless it is the last. */
function setRow(words: Word[], row: number[], measure: number, last: boolean) {
  const sum = row.reduce((s, i) => s + words[i].w, 0);
  const gap =
    last || row.length < 2 ? SPACE : (measure - sum) / (row.length - 1);
  const xs: number[] = [];
  let x = 0;
  for (const i of row) {
    xs.push(x);
    x += words[i].w + gap;
  }
  return xs;
}

interface Placed {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  row: number;
  slot: number;
  rowLen: number;
  dir: number;
}

/**
 * The narrow column is justified; the wide paragraph pairs its rows (row 2t
 * and 2t + 1 become line t) set with natural spacing. Pairing is what keeps
 * the move clean: odd rows slide out sideways into empty space, then both
 * halves close vertically, so no word ever crosses another.
 */
function layout(words: Word[]) {
  const { measure: narrow, rows } = chooseMeasure(words);
  const R = rows.length;
  const T = Math.ceil(R / 2);
  const lines = Array.from({ length: T }, (_, t) => [
    ...rows[2 * t],
    ...(rows[2 * t + 1] ?? []),
  ]);
  const wide = Math.max(...lines.map((l) => rowWidth(words, l)));
  const placed: Placed[] = [];
  const narrowX: number[] = [];
  const narrowRow: number[] = [];
  rows.forEach((row, r) => {
    const xs = setRow(words, row, narrow, r === R - 1);
    row.forEach((i, k) => {
      narrowX[i] = xs[k] - narrow / 2;
      narrowRow[i] = r;
    });
  });
  lines.forEach((line, t) => {
    const xs = setRow(words, line, wide, true);
    line.forEach((i, k) => {
      const r = narrowRow[i];
      const own = rows[r];
      placed[i] = {
        x0: narrowX[i],
        y0: r - (R - 1) / 2,
        x1: xs[k] - wide / 2,
        y1: t - (T - 1) / 2,
        row: r,
        slot: own.indexOf(i),
        rowLen: own.length,
        dir: r % 2 === 0 ? -1 : 1,
      };
    });
  });
  return { placed, R, T, wide, narrow };
}

/** Motion progress for a word at virtual time v (widen direction). */
function progress(p: Placed, R: number, v: number) {
  const order = p.dir < 0 ? p.slot : p.rowLen - 1 - p.slot;
  const xs = X_START + p.row * X_ROW + order * X_WORD;
  const px = interpolate(v, [xs, xs + X_DUR], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const ys = Y_START + Math.abs(p.row - (R - 1) / 2) * Y_ROW;
  const py = interpolate(v, [ys, ys + Y_DUR], [0, 1], {
    ...CLAMP,
    easing: EASE_Y,
  });
  return { px, py };
}

function motionEnd(R: number) {
  return Y_START + ((R - 1) / 2) * Y_ROW + Y_DUR;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function ColumnReflow({
  text = DEFAULT_TEXT,
  accentWord = "room",
  direction = "widen",
  theme = "dark",
  speed = 1,
}: ColumnReflowProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const c = THEMES[theme];

  const words = toWords(text, accentWord);
  const { placed, R, T, wide, narrow } = layout(words);
  const F = Math.min(56 * u, (W * 0.86) / wide, (H * 0.74) / (R * LEADING));
  const L = F * LEADING;
  const cx = W / 2;
  const cy = H / 2 + 0.28 * F;

  const end = motionEnd(R);
  const narrowing = direction === "narrow";
  const v = narrowing ? X_START + end - Math.min(Math.max(t, X_START), end) : t;

  const settle = interpolate(t, [end - 6, end + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  // The accent word develops into a swirl gradient as the paragraph lands;
  // the warm core drifts a few percent across the hold.
  const drift = interpolate(t, [end - 6, end + 60], [0, 1], CLAMP);
  const haze = interpolate(t, [ENTER, end + 10], [0.35, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const swirl =
    theme === "dark"
      ? `linear-gradient(100deg, ${SWIRL[0]} ${6 + 8 * drift}%, ${SWIRL[1]} ${44 + 8 * drift}%, ${SWIRL[2]} 96%)`
      : `linear-gradient(100deg, ${SWIRL[1]} ${4 + 8 * drift}%, ${SWIRL[2]} ${48 + 8 * drift}%, ${SWIRL[3]} 100%)`;

  // Measure guides follow the column edges.
  const edge = interpolate(
    v,
    [X_START, X_START + (R - 1) * X_ROW + X_DUR],
    [0, 1],
    { ...CLAMP, easing: EASE_IO },
  );
  const tall = interpolate(v, [Y_START, end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const halfW = interpolate(edge, [0, 1], [narrow / 2, wide / 2]) * F;
  const halfH =
    (interpolate(tall, [0, 1], [(R - 1) / 2, (T - 1) / 2]) + 0.95) * L;
  const guideIn = interpolate(t, [ENTER + 4, ENTER + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const guideOut = interpolate(t, [end - 4, end + 16], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const hair = Math.max(1, u);

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 80% at 40% 35%, ${c.key}, transparent 70%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: [
            `radial-gradient(70% 60% at ${88 - 6 * drift}% 112%, color-mix(in oklab, ${SWIRL[2]} ${theme === "dark" ? 30 : 16}%, transparent) 0%, transparent 70%)`,
            `radial-gradient(60% 55% at ${8 + 4 * drift}% -12%, color-mix(in oklab, ${theme === "dark" ? SWIRL[3] : SWIRL[0]} ${theme === "dark" ? 55 : 60}%, transparent) 0%, transparent 70%)`,
          ].join(", "),
          opacity: haze,
        }}
      />

      {[-1, 1].map((side) => (
        <div
          key={`g${side}`}
          style={{
            position: "absolute",
            left: cx + side * (halfW + 0.55 * F) - hair / 2,
            top: cy - 0.36 * F - halfH * guideIn,
            width: hair,
            height: halfH * 2 * guideIn,
            background: c.hair,
            opacity: guideOut,
          }}
        />
      ))}

      {words.map((w, i) => {
        const p = placed[i];
        const { px, py } = progress(p, R, v);
        const x = cx + interpolate(px, [0, 1], [p.x0, p.x1]) * F;
        const y = cy + interpolate(py, [0, 1], [p.y0, p.y1]) * L;
        const startRow = narrowing ? Math.round(p.y1 + (T - 1) / 2) : p.row;
        const enter = interpolate(
          t,
          [ENTER + startRow * 1.6, ENTER + startRow * 1.6 + 16],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        );
        const lift = (1 - enter) * 0.35 * F;
        if (!w.serif) {
          return (
            <div
              key={`${i}-${w.core}`}
              style={{
                position: "absolute",
                left: x,
                top: y - BASELINE_SANS * F + lift,
                fontFamily: sans,
                fontWeight: 400,
                fontSize: F,
                lineHeight: 1,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color: c.fg,
                opacity: enter,
              }}
            >
              {w.core}
            </div>
          );
        }
        const sF = F * SERIF_SCALE;
        const serifType = {
          position: "absolute",
          left: x - 0.2 * sF,
          top: y - BASELINE_SERIF * sF + lift,
          paddingLeft: 0.2 * sF,
          paddingRight: 0.2 * sF,
          fontFamily: serif,
          fontStyle: "italic",
          fontWeight: 400,
          fontSize: sF,
          lineHeight: 1,
          whiteSpace: "pre",
        } as const;
        return (
          <div key={`${i}-${w.core}`}>
            <div
              style={{
                ...serifType,
                color: c.fg,
                opacity: enter * (1 - settle),
              }}
            >
              {w.core}
            </div>
            <div
              style={{
                ...serifType,
                color: "transparent",
                backgroundImage: swirl,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                opacity: enter * settle,
              }}
            >
              {w.core}
            </div>
            {w.tail ? (
              <div
                style={{
                  position: "absolute",
                  left: x + (serifEm(w.core) + 0.04) * F,
                  top: y - BASELINE_SANS * F + lift,
                  fontFamily: sans,
                  fontWeight: 400,
                  fontSize: F,
                  lineHeight: 1,
                  letterSpacing: `${TRACK}em`,
                  whiteSpace: "pre",
                  color: c.fg,
                  opacity: enter,
                }}
              >
                {w.tail}
              </div>
            ) : null}
          </div>
        );
      })}

      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadDisplay } from "@remotion/google-fonts/BricolageGrotesque";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface ColumnSlideProps {
  from?: string;
  to?: string;
  columns?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const MOVE_AT = 6;
const STEP = 4;
const LAND = 42;
const SETTLE_END = 66;

const SLIDE = Easing.bezier(0.72, 0, 0.18, 1);
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);

const TRACK = -0.035;

/** gradients.sh palettes: "beam" (dark) and "pixel-glass" (light). */
const STAGES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    dim: "rgba(243,242,239,0.1)",
    light: "rgba(255,255,255,0.06)",
    ground: "#02030a",
    colors: ["#f4f7ff", "#8fb4ff", "#3d5bff", "#1a1660"],
    blobs: [
      [80, 4, 30, 34, 0.2],
      [84, 16, 48, 58, 0.55],
      [60, 66, 96, 96, 0.9],
      [8, 16, 72, 84, 1],
    ],
    toFg: "#F7F8FF",
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    dim: "rgba(18,18,20,0.08)",
    light: "rgba(255,255,255,0.9)",
    ground: "#f4f3f1",
    colors: ["#ffffff", "#ff4fb8", "#3d6bff", "#7a3cff"],
    blobs: [
      [74, 8, 46, 40, 0.9],
      [86, 34, 62, 70, 0.55],
      [22, 88, 80, 85, 0.72],
      [8, 18, 70, 80, 0.8],
    ],
    toFg: "#121214",
  },
};

type Stage = {
  colors: string[];
  blobs: number[][];
  ground: string;
};

/** Bricolage Grotesque 500 advances (opsz 96), ASCII 32–126, per 1000 em. */
const ADV = [
  211, 220, 274, 584, 563, 913, 677, 149, 267, 271, 391, 486, 150, 300, 178,
  330, 594, 264, 534, 556, 572, 551, 591, 471, 599, 592, 182, 179, 486, 486,
  486, 398, 878, 621, 588, 625, 614, 531, 507, 645, 625, 209, 306, 594, 450,
  784, 664, 657, 566, 656, 591, 573, 504, 620, 606, 897, 579, 556, 534, 276,
  329, 276, 516, 588, 283, 514, 552, 524, 554, 526, 340, 546, 534, 197, 203,
  504, 197, 830, 534, 560, 551, 552, 359, 497, 339, 532, 515, 775, 502, 522,
  454, 323, 193, 331, 486,
];

function widthEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += (c >= 32 && c < 127 ? ADV[c - 32] : 560) / 1000 + TRACK;
  }
  return Math.max(w - TRACK, 0.5);
}

/** Mesh-style layered radial blobs; positions drift a few % over the shot. */
function ground(stage: Stage, k: number) {
  const drift = [
    [-6, 4],
    [-4, -3],
    [5, -4],
    [3, 5],
  ];
  const mix = (c: string, a: number) =>
    `color-mix(in oklab, ${c} ${Math.round(a * 100)}%, transparent)`;
  return [
    ...stage.colors.map((c, i) => {
      const [x, y, w, h, a] = stage.blobs[i];
      return `radial-gradient(${w}% ${h}% at ${x + drift[i][0] * k}% ${y + drift[i][1] * k}%, ${mix(c, a)} 0%, transparent 68%)`;
    }),
    stage.ground,
  ].join(", ");
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={13}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Scene({
  W,
  H,
  left,
  top,
  background,
  overlay,
  text,
  size,
  color,
  scale,
}: {
  W: number;
  H: number;
  left: number;
  top: number;
  background: string;
  overlay: string;
  text: string;
  size: number;
  color: string;
  scale: number;
}) {
  const label: React.CSSProperties = {
    position: "absolute",
    left: 0,
    width: W,
    top: H / 2 - 0.56 * size,
    textAlign: "center",
    fontFamily: display,
    fontWeight: 500,
    fontSize: size,
    letterSpacing: `${TRACK}em`,
    lineHeight: 1,
    whiteSpace: "nowrap",
    color,
    paddingBottom: 0.12 * size,
    transform: `scale(${scale})`,
    transformOrigin: `${W / 2}px ${0.56 * size}px`,
  };
  return (
    <div
      style={{
        position: "absolute",
        left,
        top,
        width: W,
        height: H,
        background,
      }}
    >
      <div style={{ position: "absolute", inset: 0, background: overlay }} />
      <div style={label}>{text}</div>
    </div>
  );
}

export function ColumnSlide({
  from = "Plan the launch",
  to = "Launch day",
  columns = 5,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ColumnSlideProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const stage = STAGES[theme];
  const n = Math.min(7, Math.max(3, Math.round(columns)));

  const fsA = Math.min(128 * u, (0.8 * W) / widthEm(from));
  const fsB = Math.min(140 * u, (0.8 * W) / widthEm(to));
  const driftA = 1 + 0.03 * SLIDE(interpolate(t, [0, LAND], [0, 1], CLAMP));
  const settle = SETTLE(interpolate(t, [LAND - 14, SETTLE_END], [0, 1], CLAMP));
  const scaleB = 1.05 - 0.05 * settle;
  const seam = Math.max(2, 3 * u);

  const lightA = `radial-gradient(ellipse 80% 90% at 24% 0%, ${stage.light}, transparent 70%)`;
  const sheenB =
    "linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0) 45%, rgba(0,0,0,0.08))";
  const guides = interpolate(t, [0, MOVE_AT], [0.35, 1], CLAMP);
  const groundB = ground(stage, interpolate(t, [0, 96], [0, 1], CLAMP));

  const cols = Array.from({ length: n }, (_, k) => {
    const x0 = Math.round((k * W) / n);
    const x1 = Math.round(((k + 1) * W) / n);
    const order = k % 2 === 0 ? k / 2 : Math.floor(n / 2) + (k + 1) / 2;
    const start = MOVE_AT + order * STEP;
    const p = SLIDE(interpolate(t, [start, LAND], [0, 1], CLAMP));
    const up = k % 2 === 0;
    const yA = up ? -p * H : p * H;
    const yB = up ? H - p * H : -H + p * H;
    const moving = p > 0 && p < 1;
    const seamY = up ? yB : yA;
    return { k, x0, x1, yA, yB, p, moving, seamY, up };
  });

  return (
    <AbsoluteFill style={{ background: stage.bg, overflow: "hidden" }}>
      {cols.map((c) => (
        <div
          key={c.k}
          style={{
            position: "absolute",
            left: c.x0,
            top: 0,
            width: c.x1 - c.x0,
            height: H,
            overflow: "hidden",
          }}
        >
          {c.p < 1 ? (
            <Scene
              W={W}
              H={H}
              left={-c.x0}
              top={c.yA}
              background={stage.bg}
              overlay={lightA}
              text={from}
              size={fsA}
              color={stage.fg}
              scale={driftA}
            />
          ) : null}
          {c.p > 0 ? (
            <Scene
              W={W}
              H={H}
              left={-c.x0}
              top={c.yB}
              background={groundB}
              overlay={sheenB}
              text={to}
              size={fsB}
              color={stage.toFg}
              scale={scaleB}
            />
          ) : null}
          {c.moving ? (
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: c.up ? c.seamY : c.seamY - seam,
                height: seam,
                background: accent,
              }}
            />
          ) : null}
          {c.k > 0 && c.p < 1 ? (
            <div
              style={{
                position: "absolute",
                left: 0,
                top: c.yA,
                width: Math.max(1, u),
                height: H,
                background: stage.dim,
                opacity: guides,
              }}
            />
          ) : null}
        </div>
      ))}
      <Grain opacity={theme === "light" ? 0.04 : 0.055} />
    </AbsoluteFill>
  );
}

