export interface ComboRating {
  /** The hit count this rating kicks in at. */
  from: number;
  text: string;
}

export interface ComboCounterProps {
  /** One hit per feature, in order. The combo count is the number of hits landed. */
  hits?: string[];
  /** Ratings, swapped in as the count passes `from`. The last one is the poster's. */
  ratings?: ComboRating[];
  /** Small marker next to the rating. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1):
//   6–66   twelve feature names hit one after another, the gaps shrinking from
//          8 frames to 4; each lands as a hit-spark (star flash + gradient
//          slash + the word slamming in from 1.4×) and fades after ~10 frames
//  14–66  the combo meter on the left counts from 2 up, every hit scales and
//          shakes it a bit harder; the rating swaps Nice → Great → PERFECT
//  66     finisher: the 12th hit, the frame flashes, PERFECT slams in
//  72–86  the meter glides to the centre and scales up into the poster, the
//          number fills with the "swirl" gradient
//  92–    the logo rises in, poster hold
const HIT_GAPS = [8, 7, 7, 6, 6, 5, 5, 4, 4, 4, 4];
const FIRST_HIT = 6;
const WORD_LIFE = 11;
const GLIDE_DELAY = 6;
const GLIDE_LEN = 14;
const FILL_DELAY = 10;
const FILL_LEN = 10;
const LOGO_DELAY = 26;

const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const INOUT = Easing.bezier(0.65, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "swirl": bg #07060a, [#ffe2c4, #ff9a4d, #d2456b, #3a1f6b].
const SWIRL = ["#FFE2C4", "#FF9A4D", "#D2456B", "#3A1F6B"] as const;

const THEMES = {
  dark: {
    stage: "#08070B",
    ink: "#F3F2EF",
    dim: "#8A8990",
    flash: "#FFFFFF",
    number: `linear-gradient(170deg, ${SWIRL[0]} 6%, ${SWIRL[1]} 38%, ${SWIRL[2]} 72%, #8E3A9E 100%)`,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    flash: "#FFFFFF",
    number: `linear-gradient(170deg, ${SWIRL[1]} 4%, ${SWIRL[2]} 50%, ${SWIRL[3]} 100%)`,
  },
} as const;

// Where each hit lands, centre of the word, in units of W and H.
const SLOTS = [
  { x: 0.67, y: 0.3, r: -4 },
  { x: 0.79, y: 0.54, r: 3 },
  { x: 0.63, y: 0.74, r: -2 },
  { x: 0.8, y: 0.22, r: 4 },
  { x: 0.66, y: 0.5, r: -3 },
  { x: 0.78, y: 0.8, r: 2 },
];

// Long hit-slashes that stay behind the poster.
const POSTER_SLASHES = [
  { dx: -0.06, dy: 0, len: 0.42, thick: 9, delay: 0, op: 0.9 },
  { dx: 0.1, dy: 0.07, len: 0.26, thick: 4, delay: 2, op: 0.7 },
  { dx: -0.16, dy: -0.08, len: 0.18, thick: 3, delay: 3, op: 0.5 },
];

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 1 frame, eases back over `len`. */
function kick(d: number, len = 8) {
  if (d < 0) return 0;
  if (d < 1) return d;
  const k = Math.max(0, 1 - (d - 1) / len);
  return k * k;
}

function starPath(L: number, w: number) {
  return `M0 ${-L} L${w} ${-w} L${L} 0 L${w} ${w} L0 ${L} L${-w} ${w} L${-L} 0 L${-w} ${-w} Z`;
}

export function ComboCounter({
  hits = [
    "Captions",
    "Transitions",
    "Logo reveal",
    "Backgrounds",
    "Charts",
    "Text effects",
    "Lower thirds",
    "Mockups",
    "Countdowns",
    "Kinetic type",
    "Particles",
    "Templates",
  ],
  ratings = [
    { from: 2, text: "Nice" },
    { from: 6, text: "Great" },
    { from: 12, text: "PERFECT" },
  ],
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ComboCounterProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const times: number[] = [];
  hits.forEach((_, i) => {
    times.push(
      i === 0
        ? FIRST_HIT
        : times[i - 1] + (HIT_GAPS[i - 1] ?? HIT_GAPS[HIT_GAPS.length - 1]),
    );
  });
  const lastAt = times[times.length - 1] ?? FIRST_HIT;
  const n = times.filter((h) => t >= h).length;
  const lastHit = n > 0 ? times[n - 1] : -99;
  const final = n === hits.length;

  // ── Meter ─────────────────────────────────────────────────────────────────
  const numFs = 210 * u;
  const hitFs = 66 * u;
  const comboFs = 30 * u;
  const rateFs = 70 * u;
  const meterIn = n >= 2 ? OUT(ramp(t, times[1], 6)) : 0;
  const d = t - lastHit;
  const hitAmp = final ? 0.24 : 0.08 + 0.012 * n;
  const pop = 1 + hitAmp * kick(d, final ? 10 : 6);
  const shakeAmp = (final ? 16 : 3 + 0.9 * n) * u;
  const sd = Math.floor(d);
  const shakeK = sd >= 0 && sd < 8 ? (1 - sd / 8) ** 2 : 0;
  const shx = shakeAmp * shakeK * Math.sin(sd * 2.7 + 0.4);
  const shy = shakeAmp * 0.5 * shakeK * Math.cos(sd * 3.3);

  // Glide to the poster: the meter block is laid out from its left edge, so
  // the target x centres an estimate of its width (number + label column).
  const glide = INOUT(ramp(t, lastAt + GLIDE_DELAY, GLIDE_LEN));
  const digits = String(hits.length).length;
  const blockW = digits * 0.6 * numFs + 0.24 * numFs + 2.1 * hitFs;
  const posterK = 1.65;
  const gx = interpolate(
    glide,
    [0, 1],
    [0.075 * W, W / 2 - (blockW * posterK) / 2],
  );
  const gy = interpolate(glide, [0, 1], [0.47 * H, 0.47 * H]);
  const gk = interpolate(glide, [0, 1], [1, posterK]);
  const fillP = OUT(ramp(t, lastAt + FILL_DELAY, FILL_LEN));
  const logoP = OUT(ramp(t, lastAt + LOGO_DELAY, 10));

  const numberGlyphs = (text: string, gradient: boolean) => (
    <div
      style={{
        fontFamily: sairaItalic,
        fontStyle: "italic",
        fontWeight: 500,
        fontSize: numFs,
        lineHeight: 0.8,
        letterSpacing: "-0.03em",
        paddingRight: 0.08 * numFs,
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
        ...(gradient
          ? {
              backgroundImage: c.number,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
            }
          : { color: c.ink }),
      }}
    >
      {text}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <defs>
          <linearGradient id={`${id}-sw`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor={SWIRL[0]} />
            <stop offset="0.45" stopColor={SWIRL[1]} />
            <stop offset="1" stopColor={SWIRL[2]} />
          </linearGradient>
        </defs>
      </svg>

      {/* Hit-sparks: one per feature. */}
      {hits.map((word, i) => {
        const h = times[i];
        const dd = t - h;
        if (dd < 0 || dd > WORD_LIFE + 4) return null;
        const slot = SLOTS[i % SLOTS.length];
        const x = slot.x * W;
        const y = slot.y * H;
        const isFinal = i === hits.length - 1;
        const wordIn = SLAM(ramp(dd, 0, 4));
        const out = ramp(dd, WORD_LIFE - 3, 5);
        const starP = ramp(dd, 0, 7);
        const L =
          interpolate(OUT(starP), [0, 1], [50, isFinal ? 190 : 120]) * u;
        const streak = OUT(ramp(dd, 0, 3));
        const streakOut = ramp(dd, 3, 6);
        const sl = 0.2 * W * streak;
        return (
          <div key={`${i}-${word}`}>
            <svg
              width={W}
              height={H}
              style={{ position: "absolute", inset: 0 }}
              aria-hidden
            >
              <g
                transform={`translate(${x} ${y}) rotate(${-22 + slot.r})`}
                opacity={1 - streakOut}
              >
                <path
                  d={`M${-sl} 0 L0 ${-5 * u} L${sl} 0 L0 ${5 * u} Z`}
                  fill={`url(#${id}-sw)`}
                />
              </g>
              <g
                transform={`translate(${x - word.length * 0.25 * 62 * u - 34 * u} ${y - 6 * u})`}
                opacity={1 - starP}
              >
                <path d={starPath(L, 7 * u)} fill={`url(#${id}-sw)`} />
                <path
                  d={starPath(L * 0.45, 4 * u)}
                  fill={c.flash}
                  transform="rotate(45)"
                />
              </g>
            </svg>
            <div
              style={{
                position: "absolute",
                left: x - 0.3 * W,
                width: 0.6 * W,
                top: y - 50 * u,
                height: 100 * u,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: `translateY(${-18 * u * out}px) rotate(${slot.r}deg) scale(${interpolate(wordIn, [0, 1], [1.4, 1]) * (1 - 0.08 * out)})`,
                opacity: ramp(dd, 0, 2) * (1 - out),
                fontFamily: sairaItalic,
                fontStyle: "italic",
                fontWeight: 500,
                fontSize: 62 * u,
                lineHeight: 1,
                letterSpacing: "-0.01em",
                color: c.ink,
                whiteSpace: "nowrap",
              }}
            >
              {word}
            </div>
          </div>
        );
      })}

      {/* Poster slashes behind the meter. */}
      {glide > 0 ? (
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {POSTER_SLASHES.map((p) => {
            const g = OUT(ramp(t, lastAt + GLIDE_DELAY + 6 + p.delay, 8));
            const len = p.len * W * g;
            return (
              <g
                key={p.dy}
                transform={`translate(${W / 2 + p.dx * W} ${0.4 * H + p.dy * H}) rotate(-22)`}
              >
                <path
                  d={`M${-len} 0 L0 ${-p.thick * u} L${len} 0 L0 ${p.thick * u} Z`}
                  fill={`url(#${id}-sw)`}
                  opacity={p.op}
                />
              </g>
            );
          })}
        </svg>
      ) : null}

      {/* The combo meter. */}
      {n >= 2 ? (
        <div
          style={{
            position: "absolute",
            left: gx,
            top: gy,
            transform: `translate(${shx}px, ${shy}px) translateY(-50%) scale(${gk})`,
            transformOrigin: "0% 50%",
            opacity: meterIn,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "flex-end",
              gap: 0.16 * numFs,
            }}
          >
            <div
              style={{
                position: "relative",
                transform: `scale(${pop * interpolate(meterIn, [0, 1], [1.5, 1])})`,
                transformOrigin: "100% 100%",
              }}
            >
              {numberGlyphs(String(n), false)}
              {fillP > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    clipPath: `inset(0 ${(1 - fillP) * 100}% 0 0)`,
                  }}
                >
                  {numberGlyphs(String(n), true)}
                </div>
              ) : null}
            </div>
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                paddingBottom: 0.02 * numFs,
              }}
            >
              <div
                style={{
                  fontFamily: sairaItalic,
                  fontStyle: "italic",
                  fontWeight: 500,
                  fontSize: hitFs,
                  lineHeight: 0.9,
                  letterSpacing: "0.01em",
                  color: c.ink,
                }}
              >
                HIT
              </div>
              <div
                style={{
                  fontFamily: saira,
                  fontWeight: 500,
                  fontSize: comboFs,
                  lineHeight: 1,
                  letterSpacing: "0.28em",
                  color: c.dim,
                  marginTop: 0.12 * hitFs,
                }}
              >
                COMBO
              </div>
            </div>
          </div>

          {/* Rating: swaps as the combo climbs. */}
          <div
            style={{
              position: "relative",
              height: rateFs * 1.2,
              marginTop: 0.14 * numFs,
            }}
          >
            {ratings.map((r, k) => {
              const startAt = times[r.from - 1];
              if (startAt === undefined) return null;
              const next = ratings[k + 1];
              const endAt = next ? times[next.from - 1] : undefined;
              if (t < startAt) return null;
              if (endAt !== undefined && t >= endAt + 2) return null;
              const inP = SLAM(ramp(t, startAt, 5));
              const outP = endAt !== undefined ? ramp(t, endAt, 2) : 0;
              const isLast = k === ratings.length - 1;
              return (
                <div
                  key={r.text}
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    display: "flex",
                    alignItems: "center",
                    gap: 0.28 * rateFs,
                    transform: `translateY(${-0.5 * rateFs * outP}px) scale(${interpolate(inP, [0, 1], [1.45, 1])})`,
                    transformOrigin: "0% 50%",
                    opacity: ramp(t, startAt + (k > 0 ? 1 : 0), 2) * (1 - outP),
                    whiteSpace: "nowrap",
                  }}
                >
                  <div
                    style={{
                      width: 0.16 * rateFs,
                      height: 0.62 * rateFs,
                      background: accent,
                      transform: "skewX(-14deg)",
                    }}
                  />
                  <div
                    style={{
                      fontFamily: sairaItalic,
                      fontStyle: "italic",
                      fontWeight: isLast ? 500 : 400,
                      fontSize: rateFs,
                      lineHeight: 1,
                      letterSpacing: isLast ? "0.06em" : "-0.01em",
                      color: c.ink,
                    }}
                  >
                    {r.text}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : null}

      {/* Logo. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: 0.88 * H,
          display: "flex",
          justifyContent: "center",
          opacity: logoP,
          transform: `translateY(${(1 - logoP) * 16 * u}px)`,
        }}
      >
        <RemocnLogo fontSize={30 * u} color={c.ink} />
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadSora } from "@remotion/google-fonts/Sora";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const sora = loadSora("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface CometHeadlineProps {
  eyebrow?: string;
  headline?: string;
  highlight?: string;
  subhead?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    trail: LIMB[1],
    head: "#FFFFFF",
    highlight: (accent: string) =>
      `linear-gradient(90deg, ${LIMB[0]} 0%, #b7b8ff 30%, ${LIMB[1]} 60%, color-mix(in oklab, ${accent} 55%, ${LIMB[1]}) 85%, ${LIMB[0]} 100%)`,
    ground: [
      `radial-gradient(75% 95% at 106% 112%, color-mix(in oklab, ${LIMB[2]} 42%, transparent) 0%, color-mix(in oklab, ${LIMB[3]} 55%, transparent) 42%, transparent 78%)`,
      `radial-gradient(28% 40% at 98% 104%, color-mix(in oklab, ${LIMB[1]} 22%, transparent) 0%, transparent 80%)`,
    ],
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    trail: LIMB[2],
    head: LIMB[2],
    highlight: (accent: string) =>
      `linear-gradient(90deg, ${LIMB[2]} 0%, ${accent} 36%, #6f6ff0 64%, ${LIMB[1]} 84%, ${LIMB[2]} 100%)`,
    ground: [
      `radial-gradient(75% 95% at 106% 112%, color-mix(in oklab, ${LIMB[1]} 26%, transparent) 0%, color-mix(in oklab, ${LIMB[0]} 50%, transparent) 45%, transparent 78%)`,
    ],
    grain: 0.035,
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_FLIGHT = Easing.bezier(0.33, 0.1, 0.12, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const SORA_500 = [
  222, 303, 452, 702, 652, 864, 702, 264, 382, 382, 568, 592, 266, 506, 266,
  365, 750, 423, 623, 620, 652, 630, 668, 585, 647, 668, 266, 266, 592, 590,
  592, 556, 1124, 765, 684, 797, 788, 598, 560, 832, 803, 320, 641, 703, 549,
  937, 858, 865, 649, 865, 710, 682, 602, 785, 719, 1052, 705, 654, 652, 382,
  365, 382, 587, 581, 300, 581, 694, 608, 694, 616, 380, 679, 644, 317, 324,
  595, 296, 973, 644, 678, 694, 694, 414, 543, 429, 634, 572, 873, 574, 555,
  493, 382, 375, 382, 511,
];
const ASC = 0.97;
const DESC = 0.29;
const TRACK = -0.035;
const LINE = 1.06;

function textEm(text: string, tracking = TRACK) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += (c >= 32 && c <= 126 ? SORA_500[c - 32] : 640) / 1000 + tracking;
  }
  return w;
}

interface Word {
  text: string;
  index: number;
  line: number;
  x: number;
  w: number;
  hl: [number, number] | null;
}

function layout(headline: string, highlight: string, maxEm: number) {
  const lower = headline.toLowerCase();
  const hStart = highlight ? lower.indexOf(highlight.toLowerCase()) : -1;
  const hEnd = hStart >= 0 ? hStart + highlight.length : -1;
  const hLen = Math.max(1, hEnd - hStart);
  const space = textEm(" ");
  const words: Word[] = [];
  let line = 0;
  let x = 0;
  let index = 0;
  const re = /\S+|\n/g;
  for (let m = re.exec(headline); m; m = re.exec(headline)) {
    if (m[0] === "\n") {
      if (x > 0) line += 1;
      x = 0;
      continue;
    }
    const w = textEm(m[0]);
    if (x > 0 && x + space + w > maxEm) {
      line += 1;
      x = 0;
    }
    const left = x > 0 ? x + space : 0;
    const a = m.index;
    const b = a + m[0].length;
    const inside = hStart >= 0 && a < hEnd && b > hStart;
    words.push({
      text: m[0],
      index: index++,
      line,
      x: left,
      w,
      hl: inside
        ? [
            (Math.max(a, hStart) - hStart) / hLen,
            (Math.min(b, hEnd) - hStart) / hLen,
          ]
        : null,
    });
    x = left + w;
  }
  const lines = words.length ? words[words.length - 1].line + 1 : 1;
  const widths = Array.from({ length: lines }, (_, l) =>
    words
      .filter((w) => w.line === l)
      .reduce((m, w) => Math.max(m, w.x + w.w), 0),
  );
  return { words, lines, widths };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

type Pt = { x: number; y: number };

function quad(a: Pt, c: Pt, b: Pt, t: number): Pt {
  const u = 1 - t;
  return {
    x: u * u * a.x + 2 * u * t * c.x + t * t * b.x,
    y: u * u * a.y + 2 * u * t * c.y + t * t * b.y,
  };
}

function quadSlice(a: Pt, c: Pt, b: Pt, t0: number, t1: number) {
  const p0 = quad(a, c, b, t0);
  const p1 = quad(a, c, b, t1);
  const blossom = (s: number, t: number) => ({
    x:
      (1 - s) * (1 - t) * a.x + ((1 - s) * t + s * (1 - t)) * c.x + s * t * b.x,
    y:
      (1 - s) * (1 - t) * a.y + ((1 - s) * t + s * (1 - t)) * c.y + s * t * b.y,
  });
  const q = blossom(t0, t1);
  return `M ${p0.x.toFixed(2)} ${p0.y.toFixed(2)} Q ${q.x.toFixed(2)} ${q.y.toFixed(2)} ${p1.x.toFixed(2)} ${p1.y.toFixed(2)}`;
}

function highlightFill(
  [a, b]: [number, number],
  drift: number,
  image: string,
): React.CSSProperties {
  const f = Math.max(0.02, b - a);
  const K = 1.6 / f;
  const o = drift * 0.35;
  const P = (a / f + o * K) / (K - 1);
  return {
    backgroundImage: image,
    backgroundSize: `${K * 100}% 100%`,
    backgroundPosition: `${P * 100}% 0%`,
    WebkitBackgroundClip: "text",
    backgroundClip: "text",
    color: "transparent",
  };
}

export function CometHeadline({
  eyebrow = "New in remocn",
  headline = "Every launch beat, already in orbit.",
  highlight = "in orbit",
  subhead = "Reveals, feature heads and stats as drop-in Remotion scenes.",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: CometHeadlineProps) {
  const raw = useCurrentFrame();
  const frame = raw * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const p = PALETTES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.55
    : Math.min(width / 1280, height / 720);
  const padX = width * (portrait ? 0.08 : 0.09);
  const maxW = Math.min(width - padX * 2, (portrait ? 2000 : 1060) * s);

  const flat = headline.replace(/\n/g, " ");
  const baseFs = (portrait ? 108 : 96) * s;
  const estEm = textEm(flat) * 1.04;
  const hardLines = headline.split("\n").length;
  const fitLines = portrait ? 3 : 2;
  const linesAtBase = Math.max(hardLines, Math.ceil((estEm * baseFs) / maxW));
  const fs =
    linesAtBase <= fitLines
      ? baseFs
      : Math.max(baseFs * 0.7, (maxW * fitLines) / Math.max(estEm, 1));
  const { words, lines } = layout(headline, highlight, maxW / fs);
  const lh = fs * LINE;
  const baseline = ((LINE - (ASC + DESC)) / 2 + ASC) * fs;

  const eyeFs = 17 * s * (portrait ? 1.25 : 1);
  const eyeH = eyebrow ? eyeFs * 1.3 + fs * 0.4 : 0;
  const subFs = (portrait ? 30 : 25) * s;
  const subGap = fs * 0.36;
  const subMax = Math.min(maxW * 0.8, 720 * s * (portrait ? 1.35 : 1));
  const subLines = subhead
    ? Math.max(1, Math.ceil((textEm(subhead, -0.008) * subFs * 1.02) / subMax))
    : 0;
  const subH = subhead ? subGap + subLines * subFs * 1.4 : 0;
  const blockH = eyeH + lines * lh + subH;
  const top = (height - blockH) / 2 - (portrait ? 0 : 6 * s);
  const left = padX;
  const headTop = top + eyeH;

  const n = words.length;
  const stagger = n > 1 ? Math.min(5, 34 / (n - 1)) : 0;
  const FLIGHT = 26;
  const launch = (i: number) => 6 + i * stagger;
  const land = (i: number) => launch(i) + FLIGHT;
  const lastLand = land(Math.max(0, n - 1));
  const eyeT = interpolate(frame, [0, 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const subT = interpolate(frame, [lastLand - 2, lastLand + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const cool = interpolate(frame, [lastLand, lastLand + 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const drift = interpolate(raw, [0, durationInFrames], [0, 1], CLAMP);

  const origin: Pt = portrait
    ? { x: width * 1.1, y: height * 0.96 }
    : { x: width * 1.05, y: height * 1.12 };
  const peakY = Math.max(
    height * 0.02,
    headTop - (portrait ? 0.2 : 0.3) * height,
  );
  const orbit = (w: Word) => {
    const target: Pt = {
      x: left + (w.x + w.w / 2) * fs,
      y: headTop + w.line * lh + baseline - fs * 0.36,
    };
    const k = n > 1 ? 1 - w.index / (n - 1) : 0;
    const control: Pt = {
      x: target.x + (origin.x - target.x) * (0.34 - 0.06 * k),
      y: peakY - (0.04 + 0.12 * k) * height,
    };
    return { target, control };
  };

  const transparent = background === "transparent";
  const trailW = Math.max(1, 1.3 * s);

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: p.ground.join(", "),
              transform: `translate(${(-drift * 2).toFixed(3)}%, ${(-drift * 1.5).toFixed(3)}%) scale(1.06)`,
            }}
          />
          <Grain opacity={p.grain} />
        </>
      ) : null}

      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          {words.map((w) => {
            const { target } = orbit(w);
            return (
              <linearGradient
                key={w.index}
                id={`${uid}t${w.index}`}
                gradientUnits="userSpaceOnUse"
                x1={origin.x}
                y1={origin.y}
                x2={target.x}
                y2={target.y}
              >
                <stop offset="0" stopColor={p.trail} stopOpacity={0} />
                <stop offset="0.35" stopColor={p.trail} stopOpacity={0.45} />
                <stop offset="1" stopColor={p.trail} stopOpacity={1} />
              </linearGradient>
            );
          })}
        </defs>
        {words.map((w) => {
          const { target, control } = orbit(w);
          const raw01 = interpolate(
            frame,
            [launch(w.index), land(w.index)],
            [0, 1],
            CLAMP,
          );
          if (raw01 <= 0) return null;
          const t = EASE_FLIGHT(raw01);
          const head = quad(origin, control, target, t);
          const tail = Math.max(0, t - 0.22);
          const landed = frame - land(w.index);
          const trailOp = interpolate(cool, [0, 1], [0.75, 0.42]);
          const headR = interpolate(landed, [-3, 5], [0.05, 0], CLAMP) * fs;
          const tailOp = interpolate(landed, [-2, 6], [1, 0], CLAMP);
          return (
            <g key={w.index}>
              <path
                d={quadSlice(origin, control, target, 0, t)}
                fill="none"
                stroke={`url(#${uid}t${w.index})`}
                strokeWidth={trailW}
                strokeLinecap="round"
                opacity={trailOp}
              />
              {tailOp > 0 ? (
                <path
                  d={quadSlice(origin, control, target, tail, t)}
                  fill="none"
                  stroke={p.head}
                  strokeWidth={trailW * 2.2}
                  strokeLinecap="round"
                  opacity={0.55 * tailOp}
                />
              ) : null}
              {headR > 0.1 ? (
                <circle cx={head.x} cy={head.y} r={headR} fill={p.head} />
              ) : null}
              {landed >= 0 && landed < 16 ? (
                <circle
                  cx={target.x}
                  cy={target.y}
                  r={
                    interpolate(landed, [0, 16], [0.06, 0.62], {
                      ...CLAMP,
                      easing: EASE_OUT,
                    }) * fs
                  }
                  fill="none"
                  stroke={p.trail}
                  strokeWidth={trailW}
                  opacity={interpolate(landed, [0, 16], [0.8, 0], CLAMP)}
                />
              ) : null}
            </g>
          );
        })}
      </svg>

      {eyebrow ? (
        <div
          style={{
            position: "absolute",
            left,
            top,
            height: eyeFs * 1.3,
            display: "flex",
            alignItems: "center",
            gap: eyeFs * 0.7,
            clipPath: `inset(-20% ${(1 - eyeT) * 100}% -20% 0)`,
          }}
        >
          <div
            style={{
              width: eyeFs * 0.48,
              height: eyeFs * 0.48,
              borderRadius: 999,
              background: theme === "dark" ? LIMB[1] : accent,
            }}
          />
          <span
            style={{
              fontFamily: mono.fontFamily,
              fontWeight: 500,
              fontSize: eyeFs,
              letterSpacing: "0.1em",
              textTransform: "uppercase",
              color: p.muted,
              whiteSpace: "nowrap",
              transform: `translateX(${(1 - eyeT) * -12 * s}px)`,
            }}
          >
            {eyebrow}
          </span>
        </div>
      ) : null}

      {words.map((w) => {
        const k = interpolate(
          frame,
          [land(w.index) - 2, land(w.index) + 12],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_OUT,
          },
        );
        if (k <= 0) return null;
        const wght = 100 + 400 * k;
        const track = TRACK + (1 - k) * 0.05;
        const chars = Math.max(1, w.text.length);
        const shift = (-(track - TRACK) * chars * fs) / 2;
        const hl = w.hl
          ? highlightFill(w.hl, drift, p.highlight(accent))
          : { color: p.fg };
        return (
          <div
            key={w.index}
            style={{
              position: "absolute",
              left: left + w.x * fs + shift,
              top: headTop + w.line * lh,
              height: lh,
              lineHeight: `${lh}px`,
              fontFamily: sora.fontFamily,
              fontWeight: 500,
              fontVariationSettings: `"wght" ${wght.toFixed(1)}`,
              fontSize: fs,
              letterSpacing: `${track.toFixed(4)}em`,
              whiteSpace: "nowrap",
              opacity: interpolate(k, [0, 0.35], [0, 1], CLAMP),
              filter:
                k < 0.98
                  ? `blur(${((1 - k) * 0.05 * fs).toFixed(2)}px)`
                  : undefined,
              paddingRight: "0.06em",
              ...hl,
            }}
          >
            {w.text}
          </div>
        );
      })}

      {subhead ? (
        <div
          style={{
            position: "absolute",
            left,
            top: headTop + lines * lh + subGap,
            width: subMax,
            fontFamily: sora.fontFamily,
            fontWeight: 400,
            fontSize: subFs,
            lineHeight: 1.4,
            letterSpacing: "-0.008em",
            color: p.muted,
            textWrap: "balance",
            opacity: subT,
            transform: `translateY(${(1 - subT) * 14 * s}px)`,
            filter: `blur(${(1 - subT) * 6 * s}px)`,
          }}
        >
          {subhead}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { type ReactNode, useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type ComicPanelsColors = {
  ink: string;
  paper: string;
  accent: string;
};

export type ComicPanelsProps = {
  /** Hero content, framed in the top panel once the page cracks. Falls back to a placeholder "remocn" lockup. */
  children?: ReactNode;
  /** Optional word in the starburst, e.g. "POW". */
  word?: string;
  colors?: Partial<ComicPanelsColors>;
  /** Ink color. Overrides `colors.ink` when set. */
  ink?: string;
  /** Paper color. Overrides `colors.paper` when set. */
  paper?: string;
  /** Accent color. Overrides `colors.accent` when set. */
  accent?: string;
  /** Scale of `children` inside the top panel. */
  heroScale?: number;
  speed?: number;
};

export const comicPanelsDefaults = {
  colors: {
    ink: "#111111",
    paper: "#FFFFFF",
    accent: "#E5322D",
  } as ComicPanelsColors,
  heroScale: 0.62,
  speed: 1,
};

export const comicPanelsLength = 36;

const FONT =
  "'Arial Black', Impact, Inter, -apple-system, 'Segoe UI', sans-serif";
const SANS =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Helvetica, Arial, sans-serif";

// Placeholder hero shown when no children are passed.
function PlaceholderLockup({ ink, accent }: { ink: string; accent: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28 }}>
      <div
        style={{
          width: 120,
          height: 120,
          borderRadius: 32,
          backgroundColor: accent,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: "50%",
            backgroundColor: ink,
          }}
        />
      </div>
      <span
        style={{
          fontFamily: SANS,
          fontSize: 104,
          fontWeight: 800,
          letterSpacing: "-0.04em",
          color: ink,
        }}
      >
        remocn
      </span>
    </div>
  );
}
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};
const ease = (
  t: number,
  from: number,
  to: number,
  easing: (n: number) => number = Easing.inOut(Easing.cubic),
) => interpolate(t, [from, to], [0, 1], { ...clamp, easing });

type Pt = [number, number];
const poly = (points: Pt[]) => points.map((p) => p.join(",")).join(" ");

function starburst(spikes: number, outer: number, inner: number, seed: string) {
  const points: Pt[] = [];
  for (let i = 0; i < spikes * 2; i++) {
    const a =
      (i / (spikes * 2)) * Math.PI * 2 +
      (random(`${seed}-a-${i}`) - 0.5) * 0.12;
    const r =
      i % 2 === 0
        ? outer * (0.82 + 0.18 * random(`${seed}-r-${i}`))
        : inner * (0.9 + 0.1 * random(`${seed}-r-${i}`));
    points.push([Math.cos(a) * r, Math.sin(a) * r]);
  }
  return poly(points);
}

export function ComicPanels({
  children,
  word,
  colors,
  ink,
  paper,
  accent,
  heroScale = comicPanelsDefaults.heroScale,
  speed = comicPanelsDefaults.speed,
}: ComicPanelsProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, fps } = useVideoConfig();
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const merged = { ...comicPanelsDefaults.colors, ...colors };
  const c: ComicPanelsColors = {
    ink: ink ?? merged.ink,
    paper: paper ?? merged.paper,
    accent: accent ?? merged.accent,
  };
  const t = (frame / fps) * 30 * speed;
  const u = Math.min(W, H) / 720;

  // Page geometry: one slanted horizontal gutter, one slanted vertical one.
  const a0 = 0.6 * H;
  const a1 = 0.5 * H;
  const yA = (x: number) => a0 + ((a1 - a0) * x) / W;
  const b0: Pt = [0.53 * W, yA(0.53 * W)];
  const b1: Pt = [0.46 * W, H];
  const gutter = 16 * u;
  const border = 5 * u;

  const margin = ease(t, 0, 8) * 22 * u;
  const crackA = ease(t, 2, 10, Easing.out(Easing.cubic));
  const crackB = ease(t, 8, 14, Easing.out(Easing.cubic));
  const slide2 = ease(t, 10, 18, Easing.out(Easing.exp));
  const slide3 = ease(t, 13, 21, Easing.out(Easing.exp));
  const burst = ease(t, 23, 34, Easing.in(Easing.cubic));
  const settle = ease(t, 30, 36, Easing.out(Easing.cubic));
  const shaking = t >= 22 && t < 31;
  const step = Math.floor(t / 2);
  const shake = shaking
    ? [
        (random(`comic-sx-${step}`) - 0.5) * 14 * u,
        (random(`comic-sy-${step}`) - 0.5) * 14 * u,
      ]
    : [0, 0];
  const jolt = `translate(${shake[0]} ${shake[1]})`;

  const left: Pt[] = [[0, a0], b0, b1, [0, H]];
  const right: Pt[] = [b0, [W, a1], [W, H], b1];
  const heroFocus: Pt = [W / 2, interpolate(crackA, [0, 1], [H / 2, 0.27 * H])];
  const heroS = interpolate(crackA, [0, 1], [1, heroScale]);

  // Speed lines: wedges from the hero focus, redrawn every 2 frames.
  const wedges = Array.from({ length: 56 }, (_, i) => {
    const a =
      (i / 56) * Math.PI * 2 + (random(`comic-w-${step}-${i}`) - 0.5) * 0.09;
    const spread = 0.008 + 0.014 * random(`comic-ws-${step}-${i}`);
    const r0 = (0.3 + 0.12 * random(`comic-wr-${step}-${i}`)) * W * heroS;
    const r1 = W * 1.2;
    const [fx, fy] = heroFocus;
    const at = (r: number, d: number): Pt => [
      fx + Math.cos(a + d) * r,
      fy + Math.sin(a + d) * r * 0.62,
    ];
    return poly([at(r0, 0), at(r1, -spread), at(r1, spread)]);
  });

  // Halftone: dots swell toward the panel's lower-left corner.
  const pitch = 20 * u;
  const dots: { x: number; y: number; r: number }[] = [];
  for (let y = a1 - pitch; y < H + pitch; y += pitch) {
    for (let x = 0; x < b0[0] + pitch; x += pitch) {
      const ox = (Math.round(y / pitch) % 2) * (pitch / 2);
      const d = Math.hypot(x + ox, H - y) / Math.hypot(b0[0], H - a0);
      const r = pitch * 0.5 * Math.max(0, Math.min(1, 1.15 - d));
      if (r > 0.6 * u) dots.push({ x: x + ox, y, r });
    }
  }

  const c3: Pt = [(b0[0] + W + W + b1[0]) / 4, (b0[1] + a1 + H + H) / 4];
  const outer = 0.4 * (H - a1);
  const pulse = 1 + 0.04 * Math.sin(t * 1.4);
  const center: Pt = [
    interpolate(burst, [0, 1], [c3[0], W / 2]),
    interpolate(burst, [0, 1], [c3[1], H / 2]),
  ];
  const redScale = interpolate(burst, [0, 1], [1, 9]) * pulse;
  const whiteScale =
    interpolate(burst, [0, 1], [1, (0.4 * H) / (outer * 0.62)]) *
    pulse *
    interpolate(settle, [0, 1], [1.08, 1]);
  const spin = interpolate(burst, [0, 1], [0, 14]);
  const burstLayer = (
    <g transform={`translate(${center[0]} ${center[1]}) rotate(${spin})`}>
      <polygon
        transform={`scale(${redScale})`}
        points={starburst(16, outer, outer * 0.68, "comic-red")}
        fill={c.accent}
        stroke={c.ink}
        strokeWidth={(border * 0.8) / redScale}
        strokeLinejoin="round"
      />
      <polygon
        transform={`scale(${whiteScale})`}
        points={starburst(13, outer * 0.62, outer * 0.42, "comic-white")}
        fill={c.paper}
        stroke={c.ink}
        strokeWidth={(border * 0.8) / whiteScale}
        strokeLinejoin="round"
      />
      {word ? (
        <g
          transform={`scale(${whiteScale}) rotate(-8)`}
          textAnchor="middle"
          dominantBaseline="central"
          fontFamily={FONT}
          fontWeight={900}
          fontSize={outer * 0.4}
        >
          <text x={outer * 0.03} y={outer * 0.03} fill={c.accent}>
            {word}
          </text>
          <text fill={c.ink}>{word}</text>
        </g>
      ) : null}
    </g>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: c.paper, overflow: "hidden" }}>
      <AbsoluteFill>
        <svg width={W} height={H} style={{ position: "absolute" }} aria-hidden>
          <defs>
            <clipPath id={`${id}-left`}>
              <polygon points={poly(left)} />
            </clipPath>
            <clipPath id={`${id}-right`}>
              <polygon points={poly(right)} />
            </clipPath>
          </defs>
          <g fill={c.ink} transform={jolt}>
            {wedges.map((points, i) => (
              <polygon key={i} points={points} />
            ))}
          </g>
        </svg>
        <AbsoluteFill
          style={{
            alignItems: "center",
            justifyContent: "center",
            transform: `translate(${heroFocus[0] - W / 2 + shake[0]}px, ${heroFocus[1] - H / 2 + shake[1]}px) scale(${heroS})`,
          }}
        >
          {children ?? <PlaceholderLockup ink={c.ink} accent={c.accent} />}
        </AbsoluteFill>
        <svg width={W} height={H} style={{ position: "absolute" }} aria-hidden>
          <g
            clipPath={`url(#${id}-left)`}
            transform={`translate(${(slide2 - 1) * b0[0]} 0)`}
            opacity={slide2 > 0 ? 1 : 0}
          >
            <polygon points={poly(left)} fill={c.paper} />
            <g fill={c.accent} transform={jolt}>
              {dots.map((d) => (
                <circle key={`${d.x}-${d.y}`} cx={d.x} cy={d.y} r={d.r} />
              ))}
            </g>
          </g>
          <g clipPath={`url(#${id}-right)`}>
            <g
              transform={`translate(${(1 - slide3) * (W - b1[0])} 0)`}
              opacity={slide3 > 0 ? 1 : 0}
            >
              <polygon points={poly(right)} fill={c.ink} />
              <g transform={jolt}>{burst === 0 ? burstLayer : null}</g>
            </g>
          </g>
          {/* Gutters: ink edges first, then the white channel on top. */}
          {[c.ink, c.paper].map((stroke, pass) => (
            <g
              key={stroke + pass}
              stroke={stroke}
              strokeWidth={pass === 0 ? gutter + border * 2 : gutter}
              strokeLinecap="butt"
            >
              <line
                x1={-gutter}
                y1={yA(-gutter)}
                x2={-gutter + (W + 2 * gutter) * crackA}
                y2={yA(-gutter + (W + 2 * gutter) * crackA)}
              />
              <line
                x1={b0[0]}
                y1={b0[1]}
                x2={b0[0] + (b1[0] + (b1[0] - b0[0]) * 0.05 - b0[0]) * crackB}
                y2={b0[1] + (H * 1.05 - b0[1]) * crackB}
              />
            </g>
          ))}
          <path
            d={`M ${-W} ${-H} H ${2 * W} V ${2 * H} H ${-W} Z M ${margin} ${margin} V ${H - margin} H ${W - margin} V ${margin} Z`}
            fill={c.paper}
          />
          {margin > 0 ? (
            <rect
              x={margin}
              y={margin}
              width={W - margin * 2}
              height={H - margin * 2}
              fill="none"
              stroke={c.ink}
              strokeWidth={border}
            />
          ) : null}
        </svg>
      </AbsoluteFill>
      {burst > 0 ? (
        <svg width={W} height={H} style={{ position: "absolute" }} aria-hidden>
          <g transform={jolt}>{burstLayer}</g>
        </svg>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadHanken } from "@remotion/google-fonts/HankenGrotesk";
import type React from "react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const hanken = loadHanken("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CompactStatProps {
  value?: number;
  decimals?: number;
  suffix?: string;
  prefix?: string;
  label?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    muted: "#8E8D94",
    fill: (a: string) =>
      `linear-gradient(170deg, #f4f7ff 6%, #8fb4ff 38%, ${a} 72%, #1a1660 118%)`,
    ground: (a: string) =>
      `radial-gradient(60% 46% at 50% 112%, color-mix(in oklab, ${a} 34%, transparent) 0%, color-mix(in oklab, #1a1660 40%, transparent) 48%, transparent 80%)`,
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    muted: "#6E6C67",
    fill: (a: string) =>
      `linear-gradient(170deg, #1a1660 0%, ${a} 48%, #8fb4ff 112%)`,
    ground: (a: string) =>
      `radial-gradient(60% 46% at 50% 114%, color-mix(in oklab, ${a} 16%, transparent) 0%, transparent 78%)`,
    grain: 0.035,
  },
} as const;

const TRACK = -0.025;
const FONT_PX = 400;

const RISE_AT = 0;
const RISE_LEN = 18;
const RISE_GAP = 2;
const LABEL_AT = 12;
const RETRACT_AT = 40;
const RETRACT_LEN = 18;
const SUFFIX_AT = 52;
const GROW_AT = 58;
const GROW_LEN = 28;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_REEL = Easing.bezier(0.55, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const SCALES = ["", "K", "M", "B", "T"];

interface Plan {
  full: string[];
  short: string[];
  keep: number[];
  sep: number;
  mag: number;
}

function plan(
  value: number,
  decimals: number,
  suffix: string | undefined,
  prefix: string,
): Plan {
  const v = Math.max(0, Math.floor(Math.abs(value)));
  const digits = String(v);
  const tier = Math.min(
    SCALES.length - 1,
    Math.max(0, Math.floor((digits.length - 1) / 3)),
  );
  const intLen = digits.length - tier * 3;
  let dec = digits.slice(intLen, intLen + Math.max(0, Math.min(2, decimals)));
  dec = dec.replace(/0+$/, "");
  const grouped: string[] = [];
  for (let i = 0; i < digits.length; i++) {
    const fromEnd = digits.length - i;
    if (i > 0 && fromEnd % 3 === 0) grouped.push(",");
    grouped.push(digits[i]);
  }
  const pre = Array.from(prefix);
  const full = [...pre, ...grouped];
  const mag = suffix ?? SCALES[tier];
  const short = [
    ...pre,
    ...Array.from(digits.slice(0, intLen)),
    ...(dec ? [".", ...Array.from(dec)] : []),
    ...Array.from(mag),
  ];
  const keep = full.map(() => -1);
  let j = 0;
  for (let i = 0; i < pre.length; i++) keep[i] = j++;
  let seen = 0;
  let sep = -1;
  const keptDigits = intLen + dec.length;
  for (let i = pre.length; i < full.length; i++) {
    const ch = full[i];
    if (ch === ",") {
      if (seen === intLen && dec.length > 0 && tier > 0) {
        keep[i] = j++;
        sep = i;
      }
      continue;
    }
    if (seen < keptDigits) keep[i] = j++;
    seen++;
  }
  return {
    full,
    short,
    keep,
    sep,
    mag: tier > 0 || suffix ? j : -1,
  };
}

interface Metrics {
  xf: number[];
  wf: number[];
  xs: number[];
  ws: number[];
  fullW: number;
  shortW: number;
  cap: number;
  base: number;
  label: number;
}

function layout(ctx: CanvasRenderingContext2D, chars: string[]) {
  const x: number[] = [];
  const w: number[] = [];
  let prefix = "";
  for (let i = 0; i < chars.length; i++) {
    const a = ctx.measureText(prefix).width / FONT_PX + TRACK * i;
    prefix += chars[i];
    const b = ctx.measureText(prefix).width / FONT_PX + TRACK * (i + 1);
    x.push(a);
    w.push(b - a);
  }
  const total =
    ctx.measureText(chars.join("")).width / FONT_PX +
    TRACK * Math.max(0, chars.length - 1);
  return { x, w, total };
}

function measure(p: Plan, label: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("compact-stat: no 2d context");
  ctx.font = `500 ${FONT_PX}px "${hanken.fontFamily}"`;
  const f = layout(ctx, p.full);
  const s = layout(ctx, p.short);
  const zm = ctx.measureText("0");
  const cap = zm.actualBoundingBoxAscent / FONT_PX;
  const asc = zm.fontBoundingBoxAscent / FONT_PX;
  const desc = zm.fontBoundingBoxDescent / FONT_PX;
  ctx.font = `400 ${FONT_PX}px "${hanken.fontFamily}"`;
  return {
    xf: f.x,
    wf: f.w,
    xs: s.x,
    ws: s.w,
    fullW: f.total,
    shortW: s.total,
    cap,
    base: (1 - (asc + desc)) / 2 + asc,
    label: label ? ctx.measureText(label).width / FONT_PX : 0,
  };
}

function useMetrics(p: Plan, label: string) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("compact-stat: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      hanken.waitUntilDone(),
      document.fonts.load(`500 100px "${hanken.fontFamily}"`),
      document.fonts.load(`400 100px "${hanken.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(p, label));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [p, label, handle]);
  return metrics;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `cs${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function CompactStat({
  value = 1200000,
  decimals = 1,
  suffix,
  prefix = "",
  label = "frames rendered with remocn",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: CompactStatProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;

  const p = useMemo(
    () => plan(value, decimals, suffix, prefix),
    [value, decimals, suffix, prefix],
  );
  const m = useMetrics(p, label);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const F1 = Math.min(H * 0.3, (W * 0.86) / m.fullW);
  const F2 = Math.min(H * 0.48, (W * 0.8) / m.shortW, F1 * 2.6);
  const grow = interpolate(t, [GROW_AT, GROW_AT + GROW_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const F = F1 + (F2 - F1) * grow;

  const reel = interpolate(t, [RETRACT_AT, RETRACT_AT + RETRACT_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_REEL,
  });
  const magP = spring({
    frame: t - SUFFIX_AT,
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.9 },
  });

  const keptX = (i: number) => {
    const j = p.keep[i];
    return m.xf[i] + (m.xs[j] - m.xf[i]) * reel;
  };
  const lastKept = p.keep.reduce((acc, j, i) => (j >= 0 ? i : acc), -1);
  const slotEm =
    lastKept >= 0
      ? keptX(lastKept) +
        m.wf[lastKept] +
        (m.ws[p.keep[lastKept]] - m.wf[lastKept]) * reel
      : 0;
  const tailStart = lastKept + 1;
  const tailFrom = tailStart < p.full.length ? m.xf[tailStart] : slotEm;
  const tailEnd = m.fullW;
  const tailShift = (tailEnd - tailFrom + 0.04) * reel + (tailFrom - slotEm);

  const hasMag = p.mag >= 0;
  const magW = hasMag
    ? m.xs[p.short.length - 1] + m.ws[p.short.length - 1] - m.xs[p.mag]
    : 0;
  const magX = hasMag
    ? slotEm - magW + (m.xs[p.mag] - slotEm + magW) * magP
    : slotEm;

  const width = Math.max(slotEm, tailEnd - tailShift, magX + magW);
  const left = (W - width * F) / 2;

  const labelSize = label
    ? Math.min(Math.max(F2 * 0.12, H * 0.044), H * 0.056, (W * 0.84) / m.label)
    : 0;
  const gap = Math.max(F * 0.28, H * 0.05);
  const blockH = m.cap * F + (label ? gap + labelSize : 0);
  const baseY = (H - blockH) / 2 + m.cap * F;

  const maskTop = baseY - m.cap * F - F * 0.08;
  const maskH = m.cap * F + F * 0.3;

  const glyph = (
    ch: string,
    x: number,
    key: string,
    rise: number,
    extra?: React.CSSProperties,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: x,
        top: baseY - maskTop - m.base * F + (1 - rise) * maskH * 1.05,
        height: F,
        fontFamily: hanken.fontFamily,
        fontWeight: 500,
        fontSize: F,
        lineHeight: `${F}px`,
        color: c.ink,
        whiteSpace: "pre",
        fontFeatureSettings: '"lnum" 1',
        ...extra,
      }}
    >
      {ch}
    </div>
  );

  const riseOf = (i: number) =>
    interpolate(
      t,
      [RISE_AT + i * RISE_GAP, RISE_AT + i * RISE_GAP + RISE_LEN],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );

  const slotPx = left + slotEm * F;
  const kept: React.ReactNode[] = [];
  const tail: React.ReactNode[] = [];
  p.full.forEach((ch, i) => {
    const r = riseOf(i);
    if (p.keep[i] >= 0) {
      if (i === p.sep) {
        const swap = interpolate(reel, [0.25, 0.6], [0, 1], CLAMP);
        const x = left + keptX(i) * F;
        kept.push(
          glyph(ch, x, `k${i}`, r, {
            opacity: 1 - swap,
            clipPath: `inset(0 0 ${(swap * 22).toFixed(1)}% 0)`,
          }),
          glyph(".", x, `k${i}p`, r, { opacity: swap }),
        );
        return;
      }
      kept.push(glyph(ch, left + keptX(i) * F, `k${i}`, r));
      return;
    }
    const x = left + (m.xf[i] - tailShift) * F - slotPx;
    tail.push(glyph(ch, x, `t${i}`, r));
  });

  const magGlyphs = hasMag
    ? p.short.slice(p.mag).map((ch, k) =>
        glyph(
          ch,
          left + (magX + m.xs[p.mag + k] - m.xs[p.mag]) * F - slotPx,
          `m${k}`,
          1,
          {
            backgroundImage: c.fill(accent),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
          },
        ),
      )
    : [];

  const labelP = interpolate(t, [LABEL_AT, LABEL_AT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const groundP = interpolate(t, [GROW_AT, GROW_AT + GROW_LEN + 10], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {bg === "transparent" ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: c.ground(accent),
            opacity: groundP,
          }}
        />
      )}
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: maskTop,
          height: maskH,
          overflow: "hidden",
        }}
      >
        {kept}
        <div
          style={{
            position: "absolute",
            left: slotPx,
            top: 0,
            width: Math.max(0, W - slotPx),
            height: maskH,
            overflow: "hidden",
          }}
        >
          {tail}
          {magGlyphs}
        </div>
      </div>
      {label ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: baseY + gap - labelSize * 0.2,
            height: labelSize * 1.4,
            overflow: "hidden",
            textAlign: "center",
            fontFamily: hanken.fontFamily,
            fontWeight: 400,
            fontSize: labelSize,
            lineHeight: `${labelSize * 1.2}px`,
            letterSpacing: "-0.01em",
            color: c.muted,
            whiteSpace: "pre",
          }}
        >
          <div
            style={{
              transform: `translateY(${((1 - labelP) * labelSize * 1.3).toFixed(2)}px)`,
            }}
          >
            {label}
          </div>
        </div>
      ) : null}
      {bg === "transparent" ? null : <Grain opacity={c.grain} />}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

// gradients.sh "limb" palette: the final disc glows at its rim like a planet limb.
const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

export interface ScaleStep {
  value: string;
  label?: string;
}

export interface ConcentricScaleProps {
  steps?: ScaleStep[];
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_STEPS: ScaleStep[] = [
  { value: "1" },
  { value: "10" },
  { value: "1,000" },
  { value: "100,000", label: "creators" },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_RING = Easing.bezier(0.22, 0.8, 0.3, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const TAU = Math.PI * 2;
const G = 1.9;
const FIRST = 18;
const STEP = 30;
const NODE_A = (-45 * Math.PI) / 180;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.2)",
    hairStrong: "rgba(255,255,255,0.5)",
    // [offset, colour, alpha] from the centre out to the rim.
    limb: [
      [0, LIMB[3], 0],
      [0.45, LIMB[3], 0.55],
      [0.8, LIMB[2], 0.55],
      [0.95, LIMB[1], 0.7],
      [1, LIMB[0], 0.82],
    ],
    dotIn: LIMB[1],
    dotOut: LIMB[0],
    arc: LIMB[0],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.2)",
    hairStrong: "rgba(18,18,20,0.5)",
    limb: [
      [0, LIMB[0], 0],
      [0.5, LIMB[0], 0.5],
      [0.8, LIMB[1], 0.4],
      [0.94, LIMB[2], 0.55],
      [1, LIMB[2], 0.85],
    ],
    dotIn: LIMB[1],
    dotOut: LIMB[2],
    arc: LIMB[2],
    grain: 0.045,
  },
} as const;

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function beadCount(k: number) {
  return k === 1 ? 10 : Math.round(10 * 3.4 ** (k - 1));
}

const FIELD_N = 520;
const FIELD = Array.from({ length: FIELD_N }, (_, i) => {
  const turn = (i * 0.381966 + (hash(i * 3 + 1) - 0.5) * 0.004) % 1;
  return {
    id: i,
    a: turn,
    r: Math.min(
      1,
      Math.max(0, (i + 0.5) / FIELD_N + (hash(i * 7 + 2) - 0.5) * 0.02),
    ),
    o: 0.45 + 0.4 * hash(i * 11 + 5),
  };
});

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={53}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function RingLabel({
  x,
  y,
  step,
  size,
  color,
  sub,
  opacity,
  shift,
}: {
  x: number;
  y: number;
  step: ScaleStep;
  size: number;
  color: string;
  sub: string;
  opacity: number;
  shift: number;
}) {
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(calc(-100% + ${shift}px), -100%)`,
        display: "flex",
        alignItems: "baseline",
        gap: size * 0.32,
        whiteSpace: "nowrap",
        opacity,
      }}
    >
      <span
        style={{
          fontFamily: sora,
          fontWeight: 500,
          fontSize: size,
          letterSpacing: "-0.03em",
          fontVariantNumeric: "tabular-nums",
          color,
        }}
      >
        {step.value}
      </span>
      {step.label ? (
        <span
          style={{
            fontFamily: sora,
            fontWeight: 400,
            fontSize: size * 0.78,
            color: sub,
          }}
        >
          {step.label}
        </span>
      ) : null}
    </div>
  );
}

export function ConcentricScale({
  steps = DEFAULT_STEPS,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ConcentricScaleProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const list = steps.length >= 2 ? steps.slice(0, 7) : DEFAULT_STEPS;
  const last = list.length - 1;

  const startOf = (k: number) => FIRST + (k - 1) * STEP;
  const T_FINAL = startOf(last);
  const SWEEP = 30;
  const HIT = T_FINAL + SWEEP;

  let lc = 0;
  for (let k = 1; k < last; k++) {
    lc += interpolate(t, [startOf(k) + 12, startOf(k) + 40], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  }
  lc += interpolate(t, [T_FINAL + 8, HIT + 22], [0, 0.14], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const pan = interpolate(t, [T_FINAL + 16, HIT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const cx = interpolate(pan, [0, 1], [width * 0.5, width * 0.34]);
  const cy = height * 0.5;
  const RH = height * 0.38;
  const screenR = (x: number) => RH * G ** (x - 1 - lc);

  const ringX = (k: number) => {
    if (k === last) return k;
    const s = startOf(k);
    const e = interpolate(t, [s, s + 28], [0, 1], {
      ...CLAMP,
      easing: EASE_RING,
    });
    const from = k === 1 ? -2.6 : k - 1;
    return from + (k - from) * e;
  };

  const dotIn = interpolate(t, [2, 16], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const sweep = interpolate(t, [T_FINAL, HIT], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const lead = interpolate(t, [HIT - 4, HIT + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const hero = interpolate(t, [HIT + 2, HIT + 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const sub = interpolate(t, [HIT + 10, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const settle = interpolate(t, [T_FINAL, T_FINAL + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const rFinal = screenR(last);
  const rInner = last > 1 ? screenR(last - 1) * 1.14 : 18 * u;
  const hw = Math.max(1, u);
  const arcEnd = TAU * sweep;
  const startA = Math.PI / 2;
  const arcPt = (a: number) => ({
    x: cx + rFinal * Math.sin(startA + a),
    y: cy - rFinal * Math.cos(startA + a),
  });
  const ae = arcPt(arcEnd);
  const as = arcPt(0);
  const arcD =
    sweep >= 0.999
      ? `M ${cx + rFinal} ${cy} A ${rFinal} ${rFinal} 0 1 1 ${cx - rFinal} ${cy} A ${rFinal} ${rFinal} 0 1 1 ${cx + rFinal} ${cy}`
      : `M ${as.x} ${as.y} A ${rFinal} ${rFinal} 0 ${arcEnd > Math.PI ? 1 : 0} 1 ${ae.x} ${ae.y}`;
  const wedgeD = `M ${cx} ${cy} L ${as.x} ${as.y} A ${rFinal} ${rFinal} 0 ${arcEnd > Math.PI ? 1 : 0} 1 ${ae.x} ${ae.y} Z`;
  const gid = `cs${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const leadX0 = cx + rFinal + 14 * u;
  const textLeft = width * 0.6;
  const leadX1 = leadX0 + (textLeft - 22 * u - leadX0) * lead;

  const rings = Array.from({ length: last - 1 }, (_, i) => i + 1);
  const finalStep = list[last];

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        {rings.map((k) => {
          const s = startOf(k);
          const vis = interpolate(t, [s, s + 8], [0, 1], CLAMP);
          if (vis <= 0) return null;
          const r = screenR(ringX(k));
          const newest = k === last - 1 || t < startOf(k + 1);
          return (
            <g key={`r${k}`} opacity={vis}>
              <circle
                cx={cx}
                cy={cy}
                r={r}
                fill="none"
                stroke={newest && settle < 1 ? p.hairStrong : p.hair}
                strokeOpacity={newest ? 1 - 0.5 * settle : 1}
                strokeWidth={hw * 1.25}
              />
              {Array.from({ length: beadCount(k) }, (_, j) => {
                const count = beadCount(k);
                const jitter = j === 0 ? 0 : (hash(k * 97 + j) - 0.5) * 0.5;
                const a = NODE_A + ((j + jitter) / count) * TAU;
                const delay = (j / count) * 14;
                const b = interpolate(
                  t,
                  [s + 4 + delay, s + 12 + delay],
                  [0, 1],
                  {
                    ...CLAMP,
                    easing: EASE_OUT,
                  },
                );
                if (b <= 0) return null;
                return (
                  <circle
                    key={`b${j}`}
                    cx={cx + r * Math.sin(a)}
                    cy={cy - r * Math.cos(a)}
                    r={(j === 0 ? 3.4 : 2.4) * u * (0.5 + 0.5 * b)}
                    fill={p.fg}
                    opacity={(j === 0 ? 1 : 0.62) * b}
                  />
                );
              })}
            </g>
          );
        })}
        {sweep > 0 ? (
          <>
            <defs>
              <radialGradient
                id={`${gid}l`}
                gradientUnits="userSpaceOnUse"
                cx={cx + Math.sin(t / 50) * 4 * u}
                cy={cy + Math.cos(t / 60) * 4 * u}
                r={rFinal}
              >
                {p.limb.map(([o, col, a]) => (
                  <stop
                    key={`s${o}`}
                    offset={o}
                    stopColor={col}
                    stopOpacity={a}
                  />
                ))}
              </radialGradient>
              <radialGradient
                id={`${gid}d`}
                gradientUnits="userSpaceOnUse"
                cx={cx}
                cy={cy}
                r={rFinal}
              >
                <stop offset={rInner / rFinal} stopColor={p.dotIn} />
                <stop offset={1} stopColor={p.dotOut} />
              </radialGradient>
              <clipPath id={`${gid}w`}>
                <path d={wedgeD} />
              </clipPath>
            </defs>
            <circle
              cx={cx}
              cy={cy}
              r={rFinal}
              fill={`url(#${gid}l)`}
              clipPath={sweep >= 0.999 ? undefined : `url(#${gid}w)`}
              opacity={0.55 + 0.45 * lead}
            />
            <circle
              cx={cx}
              cy={cy}
              r={rFinal}
              fill="none"
              stroke={p.hair}
              strokeWidth={hw}
              strokeOpacity={0.6}
            />
            {FIELD.map((d) => {
              const k = interpolate(
                sweep,
                [d.a * 0.92, d.a * 0.92 + 0.08],
                [0, 1],
                CLAMP,
              );
              if (k <= 0) return null;
              const ro = rFinal * 0.95;
              const rr = Math.sqrt(rInner ** 2 + (ro ** 2 - rInner ** 2) * d.r);
              const a = startA + d.a * TAU;
              return (
                <circle
                  key={d.id}
                  cx={cx + rr * Math.sin(a)}
                  cy={cy - rr * Math.cos(a)}
                  r={1.6 * u}
                  fill={`url(#${gid}d)`}
                  opacity={k * d.o}
                />
              );
            })}
            <path
              d={arcD}
              fill="none"
              stroke={p.arc}
              strokeWidth={2.5 * u}
              strokeLinecap="round"
            />
            <circle
              cx={sweep >= 0.999 ? cx + rFinal : ae.x}
              cy={sweep >= 0.999 ? cy : ae.y}
              r={5 * u}
              fill={p.arc}
            />
          </>
        ) : null}
        {lead > 0 ? (
          <line
            x1={leadX0}
            y1={cy}
            x2={leadX1}
            y2={cy}
            stroke={p.hairStrong}
            strokeWidth={hw}
          />
        ) : null}
        <circle
          cx={cx}
          cy={cy}
          r={5 * u * (0.6 + 0.4 * dotIn)}
          fill={p.fg}
          opacity={dotIn}
        />
      </svg>

      <RingLabel
        x={cx - 10 * u}
        y={cy - 10 * u}
        step={list[0]}
        size={
          interpolate(t, [startOf(1), startOf(1) + 20], [40, 20], {
            ...CLAMP,
            easing: EASE_IO,
          }) * u
        }
        color={p.fg}
        sub={p.muted}
        opacity={interpolate(t, [6, 20], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })}
        shift={0}
      />
      {rings.map((k) => {
        const s = startOf(k);
        const a = interpolate(t, [s + 10, s + 26], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        if (a <= 0) return null;
        const r = screenR(ringX(k));
        const newer = interpolate(
          t,
          [startOf(k + 1), startOf(k + 1) + 20],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_IO,
          },
        );
        const qx = cx + r * Math.sin(NODE_A) - 10 * u;
        const qy = cy - r * Math.cos(NODE_A) - 8 * u;
        return (
          <RingLabel
            key={`l${k}`}
            x={qx}
            y={qy}
            step={list[k]}
            size={(28 - 8 * newer) * u}
            color={p.fg}
            sub={p.muted}
            opacity={a}
            shift={(1 - a) * 10 * u}
          />
        );
      })}

      <div
        style={{
          position: "absolute",
          left: textLeft,
          top: cy,
          transform: "translateY(-50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
        }}
      >
        <div
          style={{
            fontFamily: sora,
            fontWeight: 300,
            fontSize: 112 * u,
            lineHeight: 0.9,
            letterSpacing: "-0.055em",
            color: p.fg,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
            opacity: hero,
            filter: hero < 0.99 ? `blur(${(1 - hero) * 8 * u}px)` : undefined,
            transform: `translateX(${(1 - hero) * -22 * u}px)`,
          }}
        >
          {finalStep.value}
        </div>
        {finalStep.label ? (
          <div
            style={{
              marginTop: 18 * u,
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
              fontFamily: sora,
              fontWeight: 400,
              fontSize: 26 * u,
              letterSpacing: "-0.015em",
              color: p.muted,
              whiteSpace: "nowrap",
              opacity: sub,
              transform: `translateY(${(1 - sub) * 8 * u}px)`,
            }}
          >
            <span
              style={{
                width: 10 * u,
                height: 10 * u,
                borderRadius: "50%",
                background: accent,
                flexShrink: 0,
              }}
            />
            {finalStep.label}
          </div>
        ) : null}
      </div>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export interface ConfettiProps {
  /** Number of confetti pieces. */
  particleCount?: number;
  colors?: string[];
  /** Burst origin as a 0..1 fraction of the canvas. */
  originX?: number;
  originY?: number;
  /** Frame the burst fires on. */
  startFrame?: number;
  /** Lifetime of the burst, in frames. */
  lifetime?: number;
  /** Initial launch speed (px/frame at the 720px reference height). */
  power?: number;
  /** Downward acceleration (px/frame² at the 720px reference height). */
  gravity?: number;
  /** Base piece size in reference px. */
  size?: number;
  /** PRNG seed — same seed renders an identical burst every time. */
  seed?: number;
}

export interface Particle {
  angle: number;
  speed: number;
  color: string;
  size: number;
  rot0: number;
  spin: number;
  drift: number;
}

const DEFAULT_COLORS = [
  "#1d9bf0",
  "#ff5da2",
  "#ffd23f",
  "#22c55e",
  "#a855f7",
  "#ff7a45",
];

// --- Pure helpers (unit-tested) -------------------------------------------

/** Deterministic PRNG (mulberry32) — returns a function yielding [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Build a deterministic particle set for a seed (stable across renders). */
export function makeParticles({
  count,
  seed,
  colors,
}: {
  count: number;
  seed: number;
  colors: string[];
}): Particle[] {
  const rand = mulberry32(seed);
  const palette = colors.length > 0 ? colors : DEFAULT_COLORS;
  const out: Particle[] = [];
  for (let i = 0; i < count; i++) {
    const angle = rand() * Math.PI * 2;
    const speed = 0.35 + 0.65 * rand();
    out.push({
      angle,
      speed,
      color: palette[Math.floor(rand() * palette.length)],
      size: 0.7 + 0.6 * rand(),
      rot0: rand() * Math.PI * 2,
      spin: (rand() - 0.5) * 0.6,
      drift: (rand() - 0.5) * 2,
    });
  }
  return out;
}

/** Opacity envelope over a particle's lifetime: quick fade-in, slow fade-out. */
export function particleOpacity(tt: number, lifetime: number): number {
  if (tt < 0 || tt > lifetime) return 0;
  const fadeIn = interpolate(tt, [0, 4], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fadeOut = interpolate(tt, [lifetime * 0.7, lifetime], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return Math.min(fadeIn, fadeOut);
}

// --- Component -------------------------------------------------------------

export function Confetti({
  particleCount = 140,
  colors = DEFAULT_COLORS,
  originX = 0.5,
  originY = 0.5,
  startFrame = 0,
  lifetime = 90,
  power = 17,
  gravity = 0.45,
  size = 13,
  seed = 1,
}: ConfettiProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const tt = frame - startFrame;
  if (tt < 0 || tt > lifetime) return null;

  const sc = height / 720;
  const ox = width * originX;
  const oy = height * originY;
  const particles = makeParticles({ count: particleCount, seed, colors });

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {particles.map((p, i) => {
        const opacity = particleOpacity(tt, lifetime);
        if (opacity <= 0) return null;

        const vx = Math.cos(p.angle) * p.speed * power + p.drift;
        const vy = Math.sin(p.angle) * p.speed * power;
        const x = ox + vx * tt * sc;
        const y = oy + (vy * tt + 0.5 * gravity * tt * tt) * sc;
        const rot = p.rot0 + p.spin * tt;
        const flutter = Math.cos(p.rot0 + p.spin * tt * 1.6);
        const w = size * p.size * sc;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              width: w,
              height: w * 0.62,
              borderRadius: 2,
              background: p.color,
              opacity,
              translate: "-50% -50%",
              rotate: `${rot}rad`,
              scale: `${flutter} 1`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { type ReactNode, useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface ContributionHeatmapProps {
  value?: number;
  label?: string;
  weeks?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_POP = Easing.bezier(0.3, 1.25, 0.6, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    empty: "rgba(255,255,255,0.055)",
    // gradients.sh "beam": the year warms from the accent into ice white.
    ramp: ["#7E9BFF", "#F4F7FF"],
    toward: [18, 22, 64],
    levels: [0.68, 0.46, 0.22, 0],
    glow: "rgba(61,91,255,0.20)",
    ground: "rgba(61,91,255,0.14)",
    dim: 0.42,
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    empty: "rgba(18,18,20,0.06)",
    // gradients.sh "pixel-glass" (light): accent → violet → pink.
    ramp: ["#7A3CFF", "#FF4FB8"],
    toward: [245, 244, 240],
    levels: [0.74, 0.52, 0.28, 0],
    glow: "rgba(122,60,255,0.10)",
    ground: "rgba(255,79,184,0.06)",
    dim: 0.36,
    grain: 0.045,
  },
} as const;

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];
const DAYS = ["", "Mon", "", "Wed", "", "Fri", ""];

const SWEEP = [4, 50] as const;
const CELL_IN = 10;
const HIT = 62;

function rgb(hex: string): number[] | null {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const v = Number.parseInt(m[1], 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}

function mix(hex: string, toward: readonly number[], amt: number) {
  const a = rgb(hex);
  if (!a) return hex;
  const c = a.map((v, i) => Math.round(v + (toward[i] - v) * amt));
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}

function hash(a: number, b: number, seed: number) {
  let h = Math.imul(a + 1, 374761393) ^ Math.imul(b + 7, 668265263) ^ seed;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967295;
}

function levelOf(week: number, day: number, weeks: number) {
  const r = hash(week, day, 0x51ed);
  const trend = 0.42 + 0.58 * (week / Math.max(1, weeks - 1)) ** 0.8;
  const weekend = day === 0 || day === 6 ? 0.42 : 1;
  const quiet = hash(week, 99, 0x2b1) > 0.9 ? 0.3 : 1;
  const burst = hash(week, day, 0x9e37) > 0.94 ? 0.45 : 0;
  const a = r * trend * weekend * quiet + burst;
  if (a < 0.12) return 0;
  if (a < 0.28) return 1;
  if (a < 0.47) return 2;
  if (a < 0.67) return 3;
  return 4;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function ContributionHeatmap({
  value = 12480,
  label = "renders this year",
  weeks = 52,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ContributionHeatmapProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const cols = Math.max(4, Math.round(weeks));

  const pitch = Math.min((width * 0.8) / cols, 34 * u);
  const cell = pitch * 0.8;
  const radius = cell * 0.26;
  const gridW = cols * pitch - (pitch - cell);
  const gridH = 7 * pitch - (pitch - cell);
  const gx = (width - gridW) / 2;
  const gy = height / 2 - gridH / 2;

  const gradId = `r${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const flashColor =
    theme === "dark" ? mix(accent, [255, 255, 255], 0.6) : accent;
  const diag = 2.4;
  const span = cols + 6 * diag;
  const startOf = (c: number, r: number) =>
    SWEEP[0] + ((c + r * diag) / span) * (SWEEP[1] - SWEEP[0]);

  const stage = interpolate(t, [0, 8], [0.45, 1], CLAMP);
  const settle = interpolate(t, [HIT - 4, HIT + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const drift = interpolate(t, [0, HIT + 60], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const zoom = interpolate(t, [0, HIT - 2], [1.12, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gridScale = zoom * (1 - 0.1 * settle);
  const gridY = settle * 0.16 * height;
  const gridOpacity = 1 - p.dim * settle;
  const gridBlur = 0.9 * u * settle;
  const axisO =
    interpolate(t, [2, 14], [0, 1], { ...CLAMP, easing: EASE_OUT }) *
    interpolate(t, [HIT - 4, HIT + 6], [1, 0], CLAMP);

  const land = interpolate(t, [HIT + 6, HIT + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [HIT + 6, HIT + 34], [0.8, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const labIn = interpolate(t, [HIT + 14, HIT + 32], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const shown = Math.round(value * count).toLocaleString("en-US");

  const cells: ReactNode[] = [];
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < 7; r++) {
      const lv = levelOf(c, r, cols);
      const s0 = startOf(c, r);
      const k = interpolate(t, [s0, s0 + CELL_IN], [0, 1], CLAMP);
      const pop = EASE_POP(k);
      const flash = interpolate(t - s0, [0, 3, 13], [0, 1, 0], CLAMP);
      const x = gx + c * pitch;
      const y = gy + r * pitch;
      const sz = cell * (0.66 + 0.34 * pop);
      const off = (cell - sz) / 2;
      cells.push(
        <g key={`${c}-${r}`}>
          <rect
            x={x}
            y={y}
            width={cell}
            height={cell}
            rx={radius}
            fill={p.empty}
          />
          {lv > 0 && k > 0 ? (
            <rect
              x={x + off}
              y={y + off}
              width={sz}
              height={sz}
              rx={radius * (sz / cell)}
              fill={`url(#${gradId}${lv - 1})`}
              opacity={EASE_OUT(k)}
            />
          ) : null}
          {flash > 0.01 ? (
            <rect
              x={x + off}
              y={y + off}
              width={sz}
              height={sz}
              rx={radius * (sz / cell)}
              fill={flashColor}
              opacity={flash * (lv > 0 ? 0.75 : 0.18)}
            />
          ) : null}
        </g>,
      );
    }
  }

  const valueSize = 200 * u;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(70% 55% at ${58 + 10 * drift}% 108%, ${p.ground}, transparent 72%)`,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `translate(${(0.5 - drift) * 14 * u}px, ${gridY}px) scale(${gridScale})`,
          transformOrigin: "50% 50%",
          opacity: stage * gridOpacity,
          filter: gridBlur > 0.05 ? `blur(${gridBlur}px)` : undefined,
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            {p.levels.map((amt, i) => (
              <linearGradient
                key={amt}
                id={`${gradId}${i}`}
                gradientUnits="userSpaceOnUse"
                x1={gx - gridW * 0.08 * (1 - drift)}
                y1={gy + gridH}
                x2={gx + gridW * (1.02 - 0.06 * drift)}
                y2={gy}
              >
                <stop offset="0" stopColor={mix(accent, p.toward, amt)} />
                <stop offset="0.6" stopColor={mix(p.ramp[0], p.toward, amt)} />
                <stop
                  offset="0.86"
                  stopColor={mix(p.ramp[1], p.toward, amt * 0.9 + 0.12)}
                />
                <stop offset="1" stopColor={mix(p.ramp[1], p.toward, amt)} />
              </linearGradient>
            ))}
          </defs>
          {cells}
        </svg>
        {MONTHS.map((m, i) => {
          const c = Math.round((i * cols) / 12);
          const a = interpolate(t, [2 + i * 1.5, 14 + i * 1.5], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          return (
            <div
              key={m}
              style={{
                position: "absolute",
                left: gx + c * pitch,
                top: gy - 30 * u,
                fontFamily: mono,
                fontWeight: 400,
                fontSize: 12 * u,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                color: p.muted,
                opacity: a * axisO,
                transform: `translateY(${(1 - a) * 6 * u}px)`,
              }}
            >
              {m}
            </div>
          );
        })}
        {DAYS.map((d, r) =>
          d ? (
            <div
              key={d}
              style={{
                position: "absolute",
                right: width - gx + 14 * u,
                top: gy + r * pitch + cell / 2 - 8 * u,
                fontFamily: mono,
                fontWeight: 400,
                fontSize: 12 * u,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                lineHeight: `${16 * u}px`,
                color: p.muted,
                opacity: axisO,
              }}
            >
              {d}
            </div>
          ) : null,
        )}
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 46% 34% at 50% 36%, ${p.glow}, transparent 72%)`,
          opacity: land,
        }}
      />
      <AbsoluteFill
        style={{
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          transform: `translateY(${-0.15 * height}px)`,
        }}
      >
        <div
          style={{
            fontFamily: sans,
            fontWeight: 400,
            fontSize: valueSize,
            lineHeight: 0.92,
            letterSpacing: "-0.04em",
            color: p.fg,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
            opacity: land,
            filter: land < 0.99 ? `blur(${(1 - land) * 10 * u}px)` : undefined,
            transform: `translateY(${(1 - land) * 28 * u}px) scale(${1.04 - 0.04 * land})`,
          }}
        >
          {shown}
        </div>
        <div
          style={{
            marginTop: 22 * u,
            display: "flex",
            alignItems: "center",
            gap: 12 * u,
            opacity: labIn,
            transform: `translateY(${(1 - labIn) * 10 * u}px)`,
          }}
        >
          <span
            style={{
              width: 44 * u,
              height: 12 * u,
              borderRadius: 4 * u,
              background: `linear-gradient(90deg, ${accent}, ${p.ramp[0]} 62%, ${p.ramp[1]})`,
            }}
          />
          <span
            style={{
              fontFamily: sans,
              fontWeight: 400,
              fontSize: 24 * u,
              letterSpacing: "-0.015em",
              color: p.muted,
              whiteSpace: "nowrap",
            }}
          >
            {label}
          </span>
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadSaira } from "@remotion/google-fonts/Saira";
import { useEffect, useId, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const saira = loadSaira("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CoolDownProps {
  title?: string;
  label?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#000000",
    ink: "#F2F4EE",
    grid: "rgba(255,255,255,0.07)",
    accent: "#76B900",
  },
  light: {
    bg: "#FFFFFF",
    ink: "#0B0D08",
    grid: "rgba(0,0,0,0.08)",
    accent: "#4C7A00",
  },
} as const;

const FONT_PX = 200;
const TRACK = -0.035;
const RISE_LEN = 14;
const COOL_AT = 16;
const COOL_END = 86;
const LABEL_AT = 4;
const LABEL_LEN = 16;
const STILL_AT = 92;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  lines: number[];
  cap: number;
  base: number;
  asc: number;
  desc: number;
}

function measure(lines: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("cool-down: no 2d context");
  ctx.font = `400 ${FONT_PX}px "${saira.fontFamily}"`;
  const widths = lines.map(
    (s) =>
      ctx.measureText(s).width / FONT_PX +
      TRACK * Math.max(0, Array.from(s).length - 1),
  );
  const m = ctx.measureText("Hxg");
  const asc = m.fontBoundingBoxAscent / FONT_PX;
  const desc = m.fontBoundingBoxDescent / FONT_PX;
  return {
    lines: widths,
    cap: ctx.measureText("H").actualBoundingBoxAscent / FONT_PX,
    base: (1 - (asc + desc)) / 2 + asc,
    asc,
    desc,
  };
}

function useMetrics(lines: string[]) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("cool-down: measuring"));
  const released = useRef(false);
  const key = lines.join("\n");
  useEffect(() => {
    let live = true;
    Promise.all([
      saira.waitUntilDone(),
      document.fonts.load(`400 100px "${saira.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(key.split("\n")));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return metrics;
}

function splitLines(title: string) {
  const words = title.split(" ").filter(Boolean);
  if (words.length < 2) return [title];
  let best = 1;
  let score = Number.POSITIVE_INFINITY;
  for (let i = 1; i < words.length; i++) {
    const a = words.slice(0, i).join(" ").length;
    const b = words.slice(i).join(" ").length;
    const sc = Math.max(a, b);
    if (sc < score) {
      score = sc;
      best = i;
    }
  }
  return [words.slice(0, best).join(" "), words.slice(best).join(" ")];
}

export function CoolDown({
  title = "Runs cool.",
  label = "a full launch film rendered, fans silent",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CoolDownProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const hot = accent ?? c.accent;
  const fid = `cd${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const lines = splitLines(title);
  const m = useMetrics(lines);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const margin = Math.round(Math.min(W, H) * 0.075);
  const widest = Math.max(...m.lines);
  const F = Math.min(H * 0.4, (W - margin * 2) / widest);
  const lead = F * 0.96;
  const blockH = lead * (lines.length - 1) + m.cap * F;

  const rise = interpolate(t, [0, RISE_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const heat = interpolate(t, [COOL_AT, COOL_END], [1, 0], {
    ...CLAMP,
    easing: Easing.bezier(0.33, 0, 0.2, 1),
  });
  const shimmer = heat ** 1.4;
  const scale = shimmer * F * 0.075;
  const still = t >= STILL_AT || scale < 0.05;
  const color = `color-mix(in oklab, ${hot} ${(heat * 100).toFixed(1)}%, ${c.ink})`;
  const climb = t * F * 0.035;

  const labelP = interpolate(t, [LABEL_AT, LABEL_AT + LABEL_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelSize = Math.max(18, Math.min(H * 0.044, W * 0.04));
  const labelColor = `color-mix(in oklab, ${hot} ${(40 + heat * 60).toFixed(1)}%, ${c.ink})`;

  const pitch = Math.min(W, H) / 9;
  const gridCols = Math.ceil(W / pitch) + 1;
  const gridRows = Math.ceil(H / pitch) + 1;
  const gx = (W - Math.floor(W / pitch) * pitch) / 2;
  const gy = (H - Math.floor(H / pitch) * pitch) / 2;

  const baseLast = H - margin;
  const clipTop = baseLast - blockH - F * 0.12;
  const clipH = blockH + F * 0.32;

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <svg
        width={W}
        height={H}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <filter
            id={fid}
            x="-10%"
            y="-250%"
            width="120%"
            height="600%"
            colorInterpolationFilters="sRGB"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency={`${(0.9 / F).toFixed(5)} ${(5.2 / F).toFixed(5)}`}
              numOctaves={2}
              seed={5}
              result="noise"
            />
            <feOffset in="noise" dy={-climb} result="drift" />
            <feDisplacementMap
              in="SourceGraphic"
              in2="drift"
              scale={scale}
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>
        {Array.from({ length: gridCols }, (_, i) => (
          <line
            key={`v${i}`}
            x1={gx + i * pitch}
            x2={gx + i * pitch}
            y1={0}
            y2={H}
            stroke={c.grid}
            strokeWidth={1}
          />
        ))}
        {Array.from({ length: gridRows }, (_, i) => (
          <line
            key={`h${i}`}
            x1={0}
            x2={W}
            y1={gy + i * pitch}
            y2={gy + i * pitch}
            stroke={c.grid}
            strokeWidth={1}
          />
        ))}
      </svg>
      <div
        style={{
          position: "absolute",
          left: margin,
          top: margin,
          width: W - margin * 2,
          height: labelSize * 2.9,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            fontFamily: saira.fontFamily,
            fontWeight: 400,
            fontSize: labelSize,
            lineHeight: `${labelSize * 1.3}px`,
            letterSpacing: "-0.005em",
            color: labelColor,
            textWrap: "balance",
            maxWidth: Math.min(W - margin * 2, labelSize * 18),
            transform: `translateY(${((1 - labelP) * labelSize * 2.8).toFixed(2)}px)`,
          }}
        >
          {label}
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: clipTop,
          height: clipH,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            right: margin,
            top: (1 - rise) * clipH,
            width: W - margin,
            height: clipH,
            filter: still ? undefined : `url(#${fid})`,
          }}
        >
          {lines.map((line, i) => {
            const baseY = baseLast - clipTop - (lines.length - 1 - i) * lead;
            return (
              <div
                key={`${i}-${line}`}
                style={{
                  position: "absolute",
                  right: 0,
                  top: baseY - m.base * F,
                  height: F,
                  fontFamily: saira.fontFamily,
                  fontWeight: 400,
                  fontSize: F,
                  lineHeight: `${F}px`,
                  letterSpacing: `${TRACK}em`,
                  whiteSpace: "pre",
                  color,
                  textAlign: "right",
                }}
              >
                {line}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/InterTight";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const inter = loadInter("normal", {
  weights: ["300"],
  subsets: ["latin"],
});
const serif = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface CoolingTypeProps {
  text?: string;
  accentWord?: string;
  hot?: string;
  accent?: string;
  ink?: string;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  startAt?: number;
  charFrames?: number;
  coolFrames?: number;
  seed?: number;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "aurora",
  background: "#eef2f4",
  colors: ["#d4e4ff", "#f3f5f7", "#cfeee6", "#e7e3fb"],
  blur: 0.85,
  warp: 0.35,
  seed: 4,
  grain: 0.16,
};

const THEMES = {
  dark: {
    ink: "#eef3f1",
    hot: "#7dffd9",
    accent: "#7de8c8",
    glow: 1,
    band: 0.3,
    ground: "kiruna" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    groundOffset: 5,
    scrim: "2,8,8",
    scrimAlpha: 0.72,
  },
  light: {
    ink: "#141618",
    hot: "#2f5bff",
    accent: "#2f5bff",
    glow: 0.45,
    band: 0.2,
    ground: undefined as GshPresetId | undefined,
    groundParams: LIGHT_GROUND as Partial<GradientParams> | undefined,
    groundOffset: 3,
    scrim: "238,242,244",
    scrimAlpha: 0.4,
  },
};

const BEAT = {
  start: -3,
  breath: 8,
  accentRate: 1.25,
};

const FONT_PX = 200;
const TRACK = -0.028;
const COOL = Easing.bezier(0.33, 0, 0.2, 1);
const KEY = Easing.bezier(0.22, 1, 0.36, 1);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Measure = (s: string, serifFace: boolean) => number;

function buildMeasure(_version: number): Measure {
  const ctx = document.createElement("canvas").getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string, serifFace: boolean) => {
    const k = `${serifFace ? 1 : 0}|${s}`;
    if (cache[k] === undefined) {
      if (!ctx) return s.length * 0.5;
      ctx.font = serifFace
        ? `italic 400 ${FONT_PX}px "${serif.fontFamily}"`
        : `300 ${FONT_PX}px "${inter.fontFamily}"`;
      const tr = serifFace ? -0.01 : TRACK;
      cache[k] = ctx.measureText(s).width / FONT_PX + tr * Array.from(s).length;
    }
    return cache[k];
  };
}

function useMeasure() {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("cooling-type: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      inter.waitUntilDone(),
      serif.waitUntilDone(),
      document.fonts.load(`300 100px "${inter.fontFamily}"`),
      document.fonts.load(`italic 400 100px "${serif.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle]);
  return useMemo(() => buildMeasure(version), [version]);
}

interface Ch {
  ch: string;
  x: number;
  w: number;
  line: number;
  serif: boolean;
  t: number;
}

export function CoolingType({
  text = "What if your launch video could write itself?",
  accentWord = "itself?",
  hot,
  accent,
  ink,
  theme = "dark",
  ground,
  groundParams,
  startAt = BEAT.start,
  charFrames = 1.6,
  coolFrames = 20,
  seed = 5,
}: CoolingTypeProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hotC = hot ?? c.hot;
  const accC = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = gshParams(preset, gParams).background;
  const portrait = H > W * 1.1;
  const m = useMeasure();

  let content: ReactNode = <div />;
  if (m) {
    const words = text.split(" ").filter((w) => w.length > 0);
    const accIdx = accentWord ? words.lastIndexOf(accentWord) : -1;
    const isSerif = (wi: number) => wi === accIdx;
    const wordW = (wi: number) => m(words[wi], isSerif(wi));
    const space = m(" ", false);
    const maxW = (portrait ? 0.84 : 0.78) * W;
    const maxLines = portrait ? 5 : 2;
    let size = portrait ? W * 0.16 : H * 0.125;
    let rows: number[][] = [];
    const rowW = (row: number[]) =>
      row.reduce((a, wi, k) => a + wordW(wi) + (k > 0 ? space : 0), 0);
    for (let k = 0; k < 30; k++) {
      rows = [];
      let cur: number[] = [];
      words.forEach((_, wi) => {
        const next = [...cur, wi];
        if (cur.length > 0 && rowW(next) * size > maxW) {
          rows.push(cur);
          cur = [wi];
        } else {
          cur = next;
        }
      });
      if (cur.length > 0) rows.push(cur);
      if (
        rows.length <= maxLines &&
        rows.every((rw) => rowW(rw) * size <= maxW)
      )
        break;
      size *= 0.94;
    }
    const LH = size * 1.14;
    const blockW = Math.max(...rows.map(rowW)) * size;
    const x0 = (W - blockW) / 2;
    const top = H / 2 - (rows.length * LH) / 2;
    const lineY = (li: number) => top + LH * (li + 0.5);

    const chars: Ch[] = [];
    let t = startAt;
    let total = 0;
    rows.forEach((rw) => {
      total += rw.reduce((a, wi) => a + words[wi].length + 1, 0);
    });
    let n = 0;
    rows.forEach((rw, li) => {
      let x = x0;
      rw.forEach((wi, k) => {
        if (k > 0) {
          x += space * size;
        }
        const sf = isSerif(wi);
        if (sf) t += BEAT.breath;
        const word = words[wi];
        Array.from(word).forEach((ch, ci) => {
          const pre = word.slice(0, ci);
          const cx = x + m(pre, sf) * size;
          const cw = m(ch, sf) * size;
          chars.push({ ch, x: cx, w: cw, line: li, serif: sf, t });
          const accel = 1.2 - 0.45 * (n / Math.max(1, total));
          const jitter = (random(`ct-${seed}-${n}`) - 0.5) * 0.9;
          let step = sf ? BEAT.accentRate : charFrames * accel + jitter;
          if (/[,.;:!?]/.test(ch)) step += 4;
          t += Math.max(0.6, step);
          n++;
        });
        x += wordW(wi) * size;
        t += sf ? 0 : charFrames * 0.9;
        n++;
      });
    });
    const typedEnd = chars.length > 0 ? chars[chars.length - 1].t : startAt;
    const f = frame;

    const shownAt = (fr: number) => {
      let k = 0;
      while (k < chars.length && chars[k].t <= fr) k++;
      return k;
    };
    const caretAt = (fr: number) => {
      const k = shownAt(fr);
      if (k === 0) return { x: x0, li: 0 };
      const cur = chars[k - 1];
      const end = cur.x + cur.w;
      const prevEnd =
        k >= 2 && chars[k - 2].line === cur.line
          ? chars[k - 2].x + chars[k - 2].w
          : cur.x;
      const e = KEY(Math.min(1, (fr - cur.t) / 2));
      return { x: prevEnd + (end - prevEnd) * e, li: cur.line };
    };

    const heatOf = (ch: Ch) => {
      const a = f - ch.t;
      const len = ch.serif ? coolFrames * 1.8 : coolFrames;
      return 1 - interpolate(a, [0, len], [0, 1], { ...CLAMP, easing: COOL });
    };

    const pct = (v: number) =>
      `${(Math.max(0, Math.min(1, v)) * 100).toFixed(1)}%`;

    const bands = rows.map((_, li) => {
      const warm = chars.filter(
        (ch) => ch.line === li && ch.t <= f && heatOf(ch) > 0.04,
      );
      if (warm.length === 0) return null;
      const peak = Math.max(...warm.map(heatOf));
      const left = warm[0].x - size * 0.06;
      const last = warm[warm.length - 1];
      const right = last.x + last.w + size * 0.08;
      return (
        <div
          key={`b${li}`}
          style={{
            position: "absolute",
            left,
            top: lineY(li) - LH * 0.46,
            width: Math.max(1, right - left),
            height: LH * 0.92,
            borderRadius: LH * 0.18,
            background: `linear-gradient(90deg, color-mix(in oklab, ${hotC} 0%, transparent) 0%, color-mix(in oklab, ${hotC} ${pct(c.band * peak)}, transparent) 100%)`,
            filter: `blur(${(size * 0.07).toFixed(2)}px)`,
          }}
        />
      );
    });

    const glyphEls = chars.map((ch, i) => {
      if (ch.t > f) return null;
      const a = f - ch.t;
      const heat = heatOf(ch);
      const e = KEY(Math.min(1, a / 4));
      const target = ch.serif ? accC : inkC;
      const flare = ch.serif ? 1.4 : 1;
      const g = heat * c.glow * flare;
      const shadow =
        g > 0.02
          ? `0 0 ${(size * 0.12 * g).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.9 * g)}, transparent), 0 0 ${(size * 0.42 * g).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.4 * g)}, transparent)`
          : undefined;
      return (
        <div
          key={`c${i}`}
          style={{
            position: "absolute",
            left: ch.x,
            top: lineY(ch.line) - size / 2,
            height: size,
            display: "flex",
            alignItems: "center",
            fontFamily: ch.serif ? serif.fontFamily : inter.fontFamily,
            fontStyle: ch.serif ? "italic" : "normal",
            fontWeight: ch.serif ? 400 : 300,
            fontSize: ch.serif ? size * 1.04 : size,
            lineHeight: 1,
            whiteSpace: "pre",
            color: `color-mix(in oklab, ${hotC} ${pct(heat)}, ${target})`,
            textShadow: shadow,
            opacity: Math.min(1, 0.35 + a / 1.5),
            transform: `translateY(${((1 - e) * size * 0.1).toFixed(2)}px)`,
            filter:
              e < 0.98 ? `blur(${((1 - e) * 4).toFixed(2)}px)` : undefined,
          }}
        >
          {ch.ch}
        </div>
      );
    });

    const cur = caretAt(f);
    const back = caretAt(f - 3);
    const typing = f <= typedEnd + 2;
    const vel = cur.li === back.li ? Math.max(0, (cur.x - back.x) / 3) : 0;
    const trail = typing
      ? Math.min(size * 2.6, Math.max(size * 0.25, vel * 7))
      : interpolate(f, [typedEnd + 2, typedEnd + 10], [size * 0.25, 0], CLAMP);
    const caretHeat = typing
      ? 1
      : 1 -
        interpolate(f, [typedEnd, typedEnd + coolFrames], [0, 1], {
          ...CLAMP,
          easing: COOL,
        });
    const blink = typing || Math.floor((f - typedEnd) / 15) % 2 === 1;
    const caretW = Math.max(2, size * 0.045);
    const caretH = size * 1.02;
    const caretC = `color-mix(in oklab, ${hotC} ${pct(caretHeat)}, ${inkC})`;
    const cx = cur.x + size * 0.05;
    const cy = lineY(cur.li);
    const caret = (
      <>
        {trail > 1 ? (
          <div
            style={{
              position: "absolute",
              left: cx - trail,
              top: cy - caretH * 0.2,
              width: trail,
              height: caretH * 0.4,
              borderRadius: caretH,
              background: `linear-gradient(90deg, color-mix(in oklab, ${hotC} 0%, transparent) 0%, color-mix(in oklab, ${hotC} ${pct(0.55 * c.glow + 0.15)}, transparent) 100%)`,
              filter: `blur(${(size * 0.09).toFixed(2)}px)`,
            }}
          />
        ) : null}
        <div
          style={{
            position: "absolute",
            left: cx,
            top: cy - caretH / 2,
            width: caretW,
            height: caretH,
            borderRadius: caretW,
            background: caretC,
            opacity: blink ? 1 : 0,
            boxShadow: `0 0 ${(size * 0.18 * caretHeat * c.glow).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.8 * caretHeat)}, transparent)`,
          }}
        />
      </>
    );

    const push = interpolate(frame, [0, durationInFrames], [1, 1.04], {
      ...CLAMP,
      easing: CAMERA,
    });
    content = (
      <AbsoluteFill
        style={{
          transform: `scale(${push.toFixed(5)})`,
          transformOrigin: "50% 50%",
        }}
      >
        {bands}
        {glyphEls}
        {caret}
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <GshGround
        preset={preset}
        params={gParams}
        timeOffset={c.groundOffset}
        timeScale={0.5}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(${portrait ? "95% 50%" : "72% 62%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
        }}
      />
      {content}
    </AbsoluteFill>
  );
}

export default CoolingType;

"use client";

import { loadFont as loadSaira } from "@remotion/google-fonts/Saira";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const saira = loadSaira("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CoreSumProps {
  value?: number;
  parts?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  partLabel?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#000000",
    ink: "#F2F4EE",
    small: "#9A9D94",
    rule: "rgba(255,255,255,0.18)",
    accent: "#76B900",
  },
  light: {
    bg: "#FFFFFF",
    ink: "#0B0D08",
    small: "#5E6158",
    rule: "rgba(0,0,0,0.18)",
    accent: "#4C7A00",
  },
} as const;

const FONT_PX = 200;
const TRACK = -0.02;

const COUNT_LEN = 36;
const STAGGER = 2;
const FIRST_MERGE = 48;
const MERGE_GAP = 16;
const MERGE_LEN = 15;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_MERGE = Easing.bezier(0.6, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const WEIGHTS = [
  0.142, 0.118, 0.131, 0.109, 0.127, 0.121, 0.138, 0.114, 0.126, 0.133, 0.112,
  0.129, 0.117, 0.136, 0.11, 0.124,
];

function format(v: number) {
  const r = Math.round(Math.abs(v));
  return `${v < 0 ? "−" : ""}${String(r).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}`;
}

function pad(n: number) {
  return String(n).padStart(2, "0");
}

interface Metrics {
  digit: number;
  chars: Record<string, number>;
  cap: number;
  base: number;
}

function measure(extra: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("core-sum: no 2d context");
  ctx.font = `500 ${FONT_PX}px "${saira.fontFamily}"`;
  ctx.fontKerning = "none";
  const digit = ctx.measureText("0").width / FONT_PX;
  const chars: Record<string, number> = {};
  for (const ch of Array.from(`,.−${extra}`)) {
    chars[ch] = ctx.measureText(ch).width / FONT_PX;
  }
  const m = ctx.measureText("0123456789");
  const asc = m.fontBoundingBoxAscent / FONT_PX;
  const desc = m.fontBoundingBoxDescent / FONT_PX;
  return {
    digit,
    chars,
    cap: m.actualBoundingBoxAscent / FONT_PX,
    base: (1 - (asc + desc)) / 2 + asc,
  };
}

function useMetrics(extra: string) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("core-sum: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      saira.waitUntilDone(),
      document.fonts.load(`500 100px "${saira.fontFamily}"`),
      document.fonts.load(`400 100px "${saira.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(extra));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [extra, handle]);
  return metrics;
}

function widthOf(m: Metrics, s: string) {
  const chars = Array.from(s);
  let w = 0;
  for (const ch of chars) {
    w += ch >= "0" && ch <= "9" ? m.digit : (m.chars[ch] ?? m.digit * 0.6);
  }
  return w + TRACK * Math.max(0, chars.length - 1);
}

export function CoreSum({
  value = 2097152,
  parts = 8,
  prefix = "",
  suffix = "",
  label = "frames per night, every core busy",
  partLabel = "core",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CoreSumProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const hue = accent ?? c.accent;

  const count = useMemo(() => {
    const p = Math.round(Math.log2(Math.max(2, parts)));
    return 2 ** Math.max(1, Math.min(4, p));
  }, [parts]);
  const levels = Math.round(Math.log2(count));

  const leaves = useMemo(() => {
    const w = WEIGHTS.slice(0, count);
    const sum = w.reduce((a, b) => a + b, 0);
    const round = Math.abs(value) >= 1000 ? 1000 : 1;
    const out = w.map((x) => Math.round((value * x) / sum / round) * round);
    out[0] += value - out.reduce((a, b) => a + b, 0);
    return out;
  }, [count, value]);

  const m = useMetrics(`${prefix}${suffix}`);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const str = (v: number) => `${prefix}${format(v)}${suffix}`;
  const portrait = W < H;
  const margin = Math.round(Math.min(W, H) * 0.075);
  const top = portrait ? H * 0.2 : margin;
  const regionH = portrait ? H * 0.6 : H - margin * 2;
  const colX = margin + W * (portrait ? 0.3 : 0.27);
  const valX = colX + Math.min(W, H) * 0.04;
  const valW = W - margin - valX;

  const sums: number[][] = [leaves];
  for (let l = 1; l <= levels; l++) {
    const prev = sums[l - 1];
    const next: number[] = [];
    for (let i = 0; i < prev.length; i += 2) next.push(prev[i] + prev[i + 1]);
    sums.push(next);
  }

  const sizeAt = (l: number) => {
    const n = count / 2 ** l;
    const pitch = regionH / n;
    const widest = Math.max(...sums[l].map((v) => widthOf(m, str(v))));
    return Math.min(
      pitch * (l === levels ? 0.5 : 0.52),
      (valW * 0.96) / widest,
      l === levels ? H * 0.34 : H * 0.2,
    );
  };
  const rowY = (l: number, i: number) => {
    const pitch = regionH / (count / 2 ** l);
    return top + (i + 0.5) * pitch;
  };

  const mergeAt = (l: number) => FIRST_MERGE + (l - 1) * MERGE_GAP;
  const mergeP = (l: number) =>
    interpolate(t, [mergeAt(l), mergeAt(l) + MERGE_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_MERGE,
    });
  let level = 0;
  for (let l = 1; l <= levels; l++) if (t >= mergeAt(l)) level = l;
  const lActive = Math.max(1, level === 0 ? 1 : level);
  const p = level === 0 ? 0 : mergeP(lActive);

  const fillP = interpolate(
    t,
    [mergeAt(levels) + 4, mergeAt(levels) + MERGE_LEN + 10],
    [0, 1],
    { ...CLAMP, easing: EASE_IO },
  );

  const glyphs = (
    s: string,
    x: number,
    cy: number,
    F: number,
    key: string,
    style: React.CSSProperties,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: x,
        top: cy - m.base * F + (m.cap * F) / 2,
        height: F,
        fontFamily: saira.fontFamily,
        fontWeight: 500,
        fontSize: F,
        lineHeight: `${F}px`,
        letterSpacing: `${TRACK}em`,
        fontFeatureSettings: '"tnum" 1, "lnum" 1',
        fontKerning: "none",
        whiteSpace: "pre",
        ...style,
      }}
    >
      {s}
    </div>
  );

  const rowLabel = (l: number, i: number) => {
    if (l === levels) return label;
    const span = 2 ** l;
    const a = i * span + 1;
    const b = (i + 1) * span;
    return span === 1
      ? `${partLabel} ${pad(a)}`
      : `${partLabel}s ${pad(a)}–${pad(b)}`;
  };
  const labelSizeAt = (l: number) =>
    l === levels
      ? Math.max(16, Math.min(H * 0.04, W * 0.036))
      : Math.max(15, Math.min(sizeAt(l) * 0.46, H * 0.032));

  const nodes: React.ReactNode[] = [];
  const labels: React.ReactNode[] = [];

  const pushLabel = (l: number, i: number, opacity: number, key: string) => {
    if (opacity <= 0.001) return;
    const F = sizeAt(l);
    const size = labelSizeAt(l);
    const capTop = rowY(l, i) - (m.cap * F) / 2;
    labels.push(
      <div
        key={key}
        style={{
          position: "absolute",
          left: margin,
          top: capTop - size * 0.28,
          width: colX - margin - Math.min(W, H) * 0.03,
          fontFamily: saira.fontFamily,
          fontWeight: 400,
          fontSize: size,
          lineHeight: `${size * 1.25}px`,
          color: l === levels ? c.ink : c.small,
          opacity,
          textWrap: "balance",
        }}
      >
        {rowLabel(l, i)}
      </div>,
    );
  };

  if (level === 0) {
    const F = sizeAt(0);
    leaves.forEach((v, i) => {
      const start = i * STAGGER;
      const cp = interpolate(t, [start, start + COUNT_LEN], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const rise = interpolate(t, [start, start + 14], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const y = rowY(0, i);
      const capH = m.cap * F;
      nodes.push(
        <div
          key={`l0-${i}`}
          style={{
            position: "absolute",
            left: 0,
            top: y - capH / 2 - F * 0.1,
            width: W,
            height: capH + F * 0.22,
            overflow: "hidden",
          }}
        >
          {glyphs(
            str(v * cp),
            valX,
            capH / 2 + F * 0.1 + (1 - rise) * (capH + F * 0.3),
            F,
            "g",
            { color: c.small },
          )}
        </div>,
      );
      pushLabel(0, i, rise, `lb0-${i}`);
    });
  } else {
    const l = lActive;
    const F0 = sizeAt(l - 1);
    const F1 = sizeAt(l);
    const F = F0 + (F1 - F0) * p;
    const isFinal = l === levels;
    const k = Math.min(1, (l - 1 + p) / Math.max(1, levels - 1));
    const color = `color-mix(in oklab, ${c.ink} ${(k * 100).toFixed(1)}%, ${c.small})`;
    sums[l].forEach((_, i) => {
      const va = sums[l - 1][2 * i];
      const vb = sums[l - 1][2 * i + 1];
      const ay = rowY(l - 1, 2 * i) + (rowY(l, i) - rowY(l - 1, 2 * i)) * p;
      const byStart = rowY(l - 1, 2 * i + 1);
      const by = byStart + (ay - byStart) * p;
      const capH = m.cap * F;
      const edge = ay + capH / 2 + F * 0.32;
      if (p < 1) {
        nodes.push(
          <div
            key={`b${l}-${i}`}
            style={{
              position: "absolute",
              overflow: "hidden",
              left: 0,
              top: edge,
              width: W,
              height: Math.max(0, H - edge),
              opacity: interpolate(p, [0.3, 0.6], [1, 0], CLAMP),
            }}
          >
            {glyphs(str(vb), valX, by - edge, F, "g", { color })}
          </div>,
        );
      }
      const sa = str(va + vb * p);
      if (isFinal) {
        nodes.push(
          glyphs(sa, valX, ay, F, `a${l}-${i}`, {
            color: `color-mix(in oklab, ${hue} ${(fillP * 100).toFixed(1)}%, ${c.ink})`,
          }),
        );
      } else {
        nodes.push(glyphs(sa, valX, ay, F, `a${l}-${i}`, { color }));
      }
      pushLabel(
        l - 1,
        2 * i,
        interpolate(p, [0, 0.4], [1, 0], CLAMP),
        `lo${l}-${2 * i}`,
      );
      pushLabel(
        l - 1,
        2 * i + 1,
        interpolate(p, [0, 0.4], [1, 0], CLAMP),
        `lo${l}-${2 * i + 1}`,
      );
      pushLabel(
        l,
        i,
        interpolate(p, [0.55, 1], [0, 1], { ...CLAMP, easing: EASE_OUT }),
        `ln${l}-${i}`,
      );
    });
  }

  const shownLevel = level;
  const rows = count / 2 ** shownLevel;
  const pitch = regionH / rows;
  const rules: React.ReactNode[] = [];
  const drawIn = interpolate(t, [0, 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  for (let j = 0; j <= rows; j++) {
    rules.push(
      <line
        key={`r${shownLevel}-${j}`}
        x1={margin}
        x2={margin + (W - margin * 2) * drawIn}
        y1={top + j * pitch}
        y2={top + j * pitch}
        stroke={c.rule}
        strokeWidth={1}
      />,
    );
  }
  if (level > 0 && p < 1) {
    const prevPitch = pitch / 2;
    for (let j = 1; j < rows * 2; j += 2) {
      rules.push(
        <line
          key={`ro${level}-${j}`}
          x1={margin}
          x2={W - margin}
          y1={top + j * prevPitch}
          y2={top + j * prevPitch}
          stroke={c.rule}
          strokeWidth={1}
          opacity={interpolate(p, [0, 0.6], [1, 0], CLAMP)}
        />,
      );
    }
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <svg
        width={W}
        height={H}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        {rules}
        <line
          x1={colX}
          x2={colX}
          y1={top}
          y2={top + regionH * drawIn}
          stroke={c.rule}
          strokeWidth={1}
        />
      </svg>
      {labels}
      {nodes}
    </AbsoluteFill>
  );
}

