export interface CountdownProps {
  /** First number of the countdown. */
  from?: number;
  /** What the countdown lands on: "Live", a product name, a date. */
  finalLabel?: string;
  /** Show the small accent dot before the final label. */
  indicator?: boolean;
  /** Small lockup under the final label. Pass "" to hide it. */
  caption?: string;
  /** Replaces the default remocn mark in the lockup. */
  logo?: React.ReactNode;
  /** Frames per number. */
  beat?: number;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    track: "rgba(255,255,255,0.10)",
    stage: "rgba(255,255,255,0.06)",
    push: "rgba(255,255,255,0.09)",
    grain: 0.06,
    /** gradients.sh "radial-glow" (#f3f1ff #9db4ff #5a46cb #1d1240) as a thick halo */
    halo: [
      "rgba(29,18,64,0)",
      "rgba(29,18,64,0.55)",
      "rgba(90,70,203,0.55)",
      "rgba(157,180,255,0.5)",
      "rgba(214,218,255,0.32)",
      "rgba(90,70,203,0.36)",
      "rgba(29,18,64,0.4)",
    ],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    track: "rgba(18,18,20,0.10)",
    stage: "rgba(255,255,255,0.85)",
    push: "rgba(255,255,255,0.75)",
    grain: 0.045,
    halo: [
      "rgba(157,180,255,0)",
      "rgba(157,180,255,0.16)",
      "rgba(90,70,203,0.22)",
      "rgba(157,180,255,0.55)",
      "rgba(243,241,255,0.9)",
      "rgba(157,180,255,0.3)",
      "rgba(90,70,203,0.08)",
    ],
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];
type Exit = "ring" | "slice" | "through";

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={13}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** A centred monumental numeral; everything else is styling passed in. */
function Numeral({
  n,
  size,
  color,
  style,
}: {
  n: number;
  size: number;
  color: string;
  style?: React.CSSProperties;
}) {
  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        ...style,
      }}
    >
      <div
        style={{
          fontFamily: sans,
          fontWeight: 400,
          fontSize: size,
          lineHeight: 1,
          letterSpacing: "-0.04em",
          color,
          fontVariantNumeric: "tabular-nums",
          // optical centring: Inter Tight figures sit high in the em box
          transform: `translateY(${size * 0.035}px)`,
        }}
      >
        {n}
      </div>
    </AbsoluteFill>
  );
}

export function Countdown({
  from = 3,
  finalLabel = "Live",
  indicator = true,
  caption = "remocn 2.0",
  logo,
  beat = 20,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: CountdownProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = height / 720;
  const p: Palette = THEMES[theme];
  const count = Math.max(1, Math.round(from));
  const size = height * 0.66;
  const ringR = height * 0.36;
  const cxp = width / 2;
  const cyp = height / 2;
  const final = count * beat;

  const exitOf = (k: number): Exit =>
    k === count - 1 ? "through" : k % 2 === 0 ? "ring" : "slice";

  const layers: React.ReactNode[] = [];
  const overlays: React.ReactNode[] = [];

  for (let k = 0; k < count; k++) {
    const n = count - k;
    const start = k * beat;
    const end = start + beat;
    if (t < start - beat || t > end + beat) continue;

    // ---- entrance (driven by the previous numeral's exit) ----
    const prevExit: Exit | null = k === 0 ? null : exitOf(k - 1);
    let style: React.CSSProperties = {};
    let opacity = 1;
    let scale = 1;
    let blur = 0;
    let mask: string | undefined;

    if (prevExit === null) {
      const a = interpolate(t, [0, 9], [0, 1], { ...CLAMP, easing: EASE_OUT });
      opacity = 0.3 + 0.7 * a;
      scale = 1.05 - 0.05 * a;
      blur = (1 - a) * 8 * u;
    } else if (prevExit === "ring") {
      const a = interpolate(t, [start - 12, start], [0, 360], {
        ...CLAMP,
        easing: EASE_IO,
      });
      if (t < start - 12) opacity = 0;
      else if (t < start)
        mask = `conic-gradient(from 0deg at 50% 50%, #000 0deg, #000 ${a}deg, transparent ${a + 0.8}deg)`;
      const s = interpolate(t, [start - 12, start + 6], [1.04, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      scale = s;
    } else if (prevExit === "slice") {
      const a = interpolate(t, [start, start + 9], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      opacity = t < start ? 0 : a;
      scale = 1.14 - 0.14 * a;
      blur = (1 - a) * 10 * u;
    }

    // a slow breath while the numeral holds
    scale *= interpolate(t, [start, end], [1, 0.985], CLAMP);

    // ---- exit ----
    const exit = exitOf(k);
    if (exit === "ring") {
      const a = interpolate(t, [end - 12, end], [0, 360], {
        ...CLAMP,
        easing: EASE_IO,
      });
      if (t >= end) opacity = 0;
      else if (t > end - 12)
        mask = `conic-gradient(from 0deg at 50% 50%, transparent 0deg, transparent ${a}deg, #000 ${a + 0.8}deg)`;

      // the ring itself: a hairline track and an accent sweep that leads the wipe
      const ringIn = interpolate(t, [end - 16, end - 10], [0, 1], CLAMP);
      const ringOut = interpolate(t, [end, end + 8], [1, 0], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const ringScale = interpolate(t, [end, end + 8], [1, 1.06], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const ro = ringIn * ringOut;
      if (ro > 0) {
        const circ = 2 * Math.PI * ringR;
        const hand = ((a - 90) * Math.PI) / 180;
        overlays.push(
          <svg
            key={`ring${k}`}
            width={width}
            height={height}
            style={{
              position: "absolute",
              inset: 0,
              opacity: ro,
              transform: `scale(${ringScale})`,
            }}
            aria-hidden
          >
            <circle
              cx={cxp}
              cy={cyp}
              r={ringR}
              fill="none"
              stroke={p.track}
              strokeWidth={Math.max(1, 1.2 * u)}
            />
            <circle
              cx={cxp}
              cy={cyp}
              r={ringR}
              fill="none"
              stroke={accent}
              strokeWidth={3 * u}
              strokeLinecap="round"
              strokeDasharray={`${(circ * a) / 360} ${circ}`}
              transform={`rotate(-90 ${cxp} ${cyp})`}
            />
            {a > 0 && a < 360 && (
              <line
                x1={cxp}
                y1={cyp}
                x2={cxp + Math.cos(hand) * ringR}
                y2={cyp + Math.sin(hand) * ringR}
                stroke={p.fg}
                strokeOpacity={0.35}
                strokeWidth={Math.max(1, u)}
              />
            )}
          </svg>,
        );
      }
    } else if (exit === "slice") {
      const cut = interpolate(t, [end - 9, end - 3], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      });
      const part = interpolate(t, [end - 3, end + 5], [0, 1], {
        ...CLAMP,
        easing: Easing.bezier(0.5, 0, 0.2, 1),
      });
      if (t >= end - 3) {
        // replace the whole numeral with two halves that shear apart
        const cutY = cyp + size * 0.02;
        const shift = part * width * 0.42;
        const gapY = part * size * 0.03;
        const halves: Array<[string, number]> = [
          [`inset(0 0 ${height - cutY}px 0)`, -1],
          [`inset(${cutY}px 0 0 0)`, 1],
        ];
        for (const [clip, dir] of halves) {
          // trailing ghosts: a fake motion blur along the shear
          for (let g = 2; g >= 0; g--) {
            const lag = g * 0.09;
            const sh = Math.max(0, part - lag) / Math.max(0.001, 1 - lag);
            layers.push(
              <Numeral
                key={`h${k}${dir}${g}`}
                n={n}
                size={size}
                color={p.fg}
                style={{
                  clipPath: clip,
                  transform: `translate(${dir * sh * shift}px, ${dir * gapY}px) scale(${scale})`,
                  opacity:
                    interpolate(part, [0.25, 1], [1, 0], CLAMP) *
                    (g === 0
                      ? 1
                      : 0.2 * interpolate(part, [0.1, 0.35], [0, 1], CLAMP)),
                  filter: g === 0 ? undefined : `blur(${3 * u}px)`,
                }}
              />,
            );
          }
        }
        opacity = 0;
      }
      const lineO =
        interpolate(t, [end - 9, end - 7], [0, 1], CLAMP) *
        interpolate(t, [end - 1, end + 6], [1, 0], CLAMP);
      if (lineO > 0) {
        const span = width * 0.62;
        overlays.push(
          <div
            key={`cut${k}`}
            style={{
              position: "absolute",
              left: cxp - span / 2,
              top: cyp + size * 0.02 - u,
              width: span,
              height: Math.max(1.5, 2 * u),
              background: accent,
              transformOrigin: "0% 50%",
              transform: `scaleX(${cut})`,
              opacity: lineO,
            }}
          />,
        );
      }
    } else {
      // scale-through: the last numeral rushes past the camera
      const r = interpolate(t, [end - 8, end + 2], [0, 1], CLAMP);
      const grow = (x: number) => 1 + 9 * x * x * x;
      if (r > 0) {
        for (let g = 3; g >= 1; g--) {
          const gr = Math.max(0, r - g * 0.06);
          layers.push(
            <Numeral
              key={`g${k}${g}`}
              n={n}
              size={size}
              color={p.fg}
              style={{
                transform: `scale(${scale * grow(gr)})`,
                opacity:
                  0.14 * interpolate(gr, [0, 0.2, 0.8], [0, 1, 0], CLAMP),
                filter: `blur(${(3 + gr * gr * 18) * u}px)`,
              }}
            />,
          );
        }
      }
      scale *= grow(r);
      opacity *= interpolate(r, [0.45, 0.95], [1, 0], CLAMP);
      blur += r * r * 16 * u;
    }

    if (opacity > 0.001) {
      style = {
        opacity,
        transform: `scale(${scale})`,
        filter: blur > 0.2 ? `blur(${blur}px)` : undefined,
        WebkitMaskImage: mask,
        maskImage: mask,
      };
      layers.push(
        <Numeral key={`n${k}`} n={n} size={size} color={p.fg} style={style} />,
      );
    }
  }

  // ---- final hit ----
  const f = spring({
    frame: t - final,
    fps,
    config: { damping: 16, stiffness: 160, mass: 0.8 },
  });
  const fO = interpolate(t, [final, final + 6], [0, 1], CLAMP);
  const fBlur = interpolate(t, [final, final + 8], [10 * u, 0], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const dot = spring({
    frame: t - final - 4,
    fps,
    config: { damping: 12, stiffness: 200, mass: 0.5 },
  });
  const push = interpolate(t, [final - 2, final + 2, final + 26], [0, 1, 0], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const cap = interpolate(t, [final + 12, final + 32], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const finalIsLogo = finalLabel.trim().toLowerCase() === "remocn";
  const finalSize = Math.min(
    height * 0.3,
    (width * 0.7) / Math.max(3, Array.from(finalLabel).length * 0.56),
  );
  // rough rendered width of the final line, so the halo can open around it
  const finalW = Math.max(
    2 * ringR,
    finalSize *
      (finalIsLogo
        ? 3.9
        : Array.from(finalLabel).length * 0.55 + (indicator ? 0.4 : 0)),
  );
  // "remocn 2.0" -> the real logo followed by "2.0"
  const capMatch = /^remocn\b\s*(.*)$/i.exec(caption);
  const capText = capMatch ? capMatch[1] : caption;
  const capLogo =
    logo ??
    (finalIsLogo && !capMatch ? null : (
      <RemocnLogo fontSize={27 * u} color={p.fg} />
    ));
  // the whole stage leans in a touch at the cut, then settles
  const stageKick =
    1 + 0.02 * interpolate(t, [final, final + 3, final + 24], [0, 1, 0], CLAMP);

  // the halo sits on the countdown ring's radius, breathes in as the count
  // runs, and opens up at the hit to frame the final label
  const haloOpen = interpolate(t, [final - 4, final + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const haloScale =
    interpolate(t, [0, final], [0.94, 1], CLAMP) *
    (1 + (finalW / (2 * ringR * 0.9) - 1) * haloOpen);
  const haloIn = interpolate(t, [0, 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const hs = (k: number) => `${(ringR * k).toFixed(1)}px`;
  const h = p.halo;
  const halo = `radial-gradient(circle at 50% 50%, ${h[0]} ${hs(0.78)}, ${h[1]} ${hs(0.88)}, ${h[2]} ${hs(0.96)}, ${h[3]} ${hs(0.995)}, ${h[4]} ${hs(1.01)}, ${h[5]} ${hs(1.07)}, ${h[6]} ${hs(1.2)}, transparent ${hs(1.55)})`;
  // a slow light that travels around the halo
  const sweep = 200 + t * 1.1;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 65% at 50% 38%, ${p.stage}, transparent 75%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: halo,
          opacity: haloIn,
          transform: `scale(${haloScale})`,
          WebkitMaskImage: `conic-gradient(from ${sweep}deg at 50% 50%, rgba(0,0,0,0.55), #000 40%, rgba(0,0,0,0.55) 70%, rgba(0,0,0,0.55))`,
          maskImage: `conic-gradient(from ${sweep}deg at 50% 50%, rgba(0,0,0,0.55), #000 40%, rgba(0,0,0,0.55) 70%, rgba(0,0,0,0.55))`,
        }}
      />
      <AbsoluteFill style={{ transform: `scale(${stageKick})` }}>
        {layers}
        {overlays}

        {t >= final - 1 && (
          <AbsoluteFill
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: 30 * u,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: finalSize * 0.16,
                opacity: fO,
                filter: fBlur > 0.2 ? `blur(${fBlur}px)` : undefined,
                transform: `scale(${0.9 + 0.1 * f})`,
              }}
            >
              {indicator && (
                <div
                  style={{
                    width: finalSize * 0.2,
                    height: finalSize * 0.2,
                    borderRadius: "50%",
                    background: accent,
                    transform: `scale(${0.5 + 0.5 * dot})`,
                    marginTop: finalSize * 0.06,
                  }}
                />
              )}
              {finalIsLogo ? (
                <RemocnLogo fontSize={finalSize} color={p.fg} />
              ) : (
                <div
                  style={{
                    fontFamily: sans,
                    fontWeight: 500,
                    fontSize: finalSize,
                    lineHeight: 1,
                    letterSpacing: "-0.04em",
                    color: p.fg,
                    whiteSpace: "nowrap",
                  }}
                >
                  {finalLabel}
                </div>
              )}
            </div>
            {caption !== "" && (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 10 * u,
                  opacity: cap,
                  transform: `translateY(${(1 - cap) * 12 * u}px)`,
                  fontFamily: sans,
                  fontWeight: 400,
                  fontSize: 24 * u,
                  letterSpacing: "-0.01em",
                  color: p.muted,
                }}
              >
                {capLogo}
                {capText}
              </div>
            )}
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* exposure push at the hit: light lifts, no white flash */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 70% at 50% 50%, ${p.push}, transparent 80%)`,
          opacity: push,
        }}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 60%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import { useId, useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface CounterRevealProps {
  /**
   * Huge front word. Letters with embedded outlines (the default "Beta")
   * get real counter windows; any other letter falls back to live text.
   */
  word?: string;
  /** The line seen through the counters, then revealed in full. */
  line?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Sora 500 advance widths (per 1000 em) for ASCII 32–126, and full outlines
// (outer contours + counters, overlaps removed) for the default word, in the
// same units with the baseline at y = 0, y down. Extracted offline from the
// Google Fonts Sora build (fontTools + skia-pathops).
const SORA_500 = [
  222, 303, 452, 702, 652, 864, 702, 264, 382, 382, 568, 592, 266, 506, 266,
  365, 750, 423, 623, 620, 652, 630, 668, 585, 647, 668, 266, 266, 592, 590,
  592, 556, 1124, 765, 684, 797, 788, 598, 560, 832, 803, 320, 641, 703, 549,
  937, 858, 865, 649, 865, 710, 682, 602, 785, 719, 1052, 705, 654, 652, 382,
  365, 382, 587, 581, 300, 581, 694, 608, 694, 616, 380, 679, 644, 317, 324,
  595, 296, 973, 644, 678, 694, 694, 414, 543, 429, 634, 572, 873, 574, 555,
  493, 382, 375, 382, 511,
];

const GLYPHS: Record<string, { outer: string; holes: string }> = {
  B: {
    outer:
      "M98 4V-735H348Q470 -735 532 -684Q594 -632 594 -536V-522Q594 -454 562 -414Q543 -390 516 -374Q563 -357 592 -321Q624 -281 624 -212V-198Q624 -134 596 -88Q569 -43 514 -20Q460 4 378 4Z",
    holes:
      "M217 -320V-96H390Q444 -96 474 -126Q503 -156 503 -208Q503 -261 474 -290Q445 -320 390 -320ZM217 -635V-416H363Q420 -416 446 -446Q473 -477 473 -525Q473 -574 446 -604Q420 -635 363 -635Z",
  },
  e: {
    outer:
      "M321 18Q251 18 199 -6Q147 -30 114 -70Q81 -109 64 -158Q48 -208 48 -260V-279Q48 -332 64 -382Q81 -431 114 -470Q147 -510 198 -534Q248 -557 315 -557Q402 -557 460 -519Q518 -481 547 -420Q576 -360 576 -290V-243H160Q163 -204 176 -172Q193 -130 229 -106Q265 -81 321 -81Q377 -81 413 -106Q449 -130 457 -163H566Q555 -108 522 -67Q488 -26 437 -4Q386 18 321 18Z",
    holes:
      "M163 -322H462Q458 -351 448 -375Q431 -415 398 -436Q365 -458 315 -458Q263 -458 228 -434Q193 -410 176 -368Q167 -347 163 -322Z",
  },
  t: {
    outer:
      "M307 6Q240 6 194 -12Q148 -30 124 -74Q101 -118 101 -193V-452H12V-539H101V-696H212V-539H388V-452H212V-183Q212 -141 234 -118Q257 -96 298 -96H388V6Z",
    holes: "",
  },
  a: {
    outer:
      "M411 0V-105Q405 -83 394 -65Q372 -27 332 -6Q293 14 236 14Q177 14 133 -6Q89 -27 65 -66Q41 -106 41 -161Q41 -219 68 -257Q96 -295 147 -314Q198 -333 269 -333H392V-343Q392 -393 366 -419Q340 -445 289 -445Q261 -445 227 -444Q193 -443 160 -442Q128 -440 103 -438V-539Q125 -541 152 -542Q178 -544 206 -545Q235 -546 261 -546Q343 -546 397 -525Q451 -504 478 -458Q504 -413 504 -337V0Z",
    holes:
      "M392 -256H266Q213 -256 185 -230Q157 -205 157 -164Q157 -123 185 -98Q213 -74 266 -74Q297 -74 325 -86Q353 -97 372 -124Q390 -151 392 -200Z",
  },
};

const CAP = 0.73;
const WORD_TRACK = -0.03;
const LINE_TRACK = -0.035;
const WORD_SPACE = 0.24;

// Beats (frames at 30fps).
const ENTER = -6; // first letter is already mid-rise on frame 0
const ENTER_LEN = 20;
const STAGGER = 3;
const EXIT = 66;
const EXIT_LEN = 26;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.7, 0, 0.3, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// The ground under the plate is a gradients.sh palette: "mesh" (blue family,
// sits with the accent) for dark, "pixel-glass" for light. `tint` is the line
// while it is seen through the counters, `ink` once it is uncovered.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    ink: "#F5F4F0",
    tint: "#0A0F33",
    grain: 0.07,
    ground: "#0a0d24",
    blobs: [
      ["#ecdcf2", 86, 94, 30],
      ["#2e45b7", 16, 20, 100],
      ["#8796ee", 84, 22, 62],
      ["#0e1645", 20, 86, 100],
      ["accent", 52, 50, 58],
    ],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    ink: "#121214",
    tint: "#2B1D6E",
    grain: 0.045,
    ground: "#f4f3f1",
    blobs: [
      ["#7a3cff", 18, 24, 78],
      ["#ff4fb8", 84, 28, 62],
      ["#3d6bff", 72, 88, 82],
      ["accent", 24, 82, 50],
    ],
  },
} as const;

export const counterRevealDuration = EXIT + EXIT_LEN + 40;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? SORA_500[code - 32] : 640) / 1000;
}

function layoutRow(text: string, track: number) {
  const chars = Array.from(text);
  const xs: number[] = [];
  let x = 0;
  chars.forEach((ch, i) => {
    xs.push(x);
    const a = ch === " " ? WORD_SPACE : advance(ch);
    x += a + (i < chars.length - 1 ? track : 0);
  });
  return { chars, xs, width: x };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function CounterReveal({
  word = "Beta",
  line = "Out now.",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: CounterRevealProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const front = useMemo(() => layoutRow(word, WORD_TRACK), [word]);
  const back = useMemo(() => layoutRow(line, LINE_TRACK), [line]);

  // Front word fills the frame edge to edge.
  const F = Math.min((W * 0.96) / front.width, (H * 0.66) / CAP);
  const wordLeft = W / 2 - (front.width * F) / 2;
  const baseline = H / 2 + (CAP * F) / 2;

  // Back line at poster size; while it hides behind the windows it is set
  // much larger and darker, so its strokes register inside the counters.
  const B = Math.min((W * 0.86) / back.width, (H * 0.34) / CAP);
  const lineLeft = W / 2 - (back.width * B) / 2;
  const lineBase = H / 2 + (CAP * B) / 2;
  const end = EXIT + EXIT_LEN;
  const drift = EASE_IO(interpolate(t, [0, end], [0, 1], CLAMP));
  const lineShift = (1 - drift) * W * 0.45;
  const shrink = EASE_IO(interpolate(t, [EXIT - 6, end + 4], [0, 1], CLAMP));
  const settle = interpolate(t, [end, end + 36], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lineScale = (1.9 - 0.9 * shrink) * (1 + 0.03 * settle);
  const tint = c.tint;
  // Blobs drift a few percent over the shot, deterministic in frame.
  const flow = interpolate(t, [0, counterRevealDuration], [0, 1], CLAMP);
  const ground = [
    ...c.blobs.map(([col, x, y, a], i) => {
      const dx = (i % 2 ? -5 : 5) * flow;
      const dy = (i % 3 === 0 ? 4 : -3) * flow;
      const cc = col === "accent" ? accent : col;
      return `radial-gradient(85% 95% at ${x + dx}% ${y + dy}%, color-mix(in oklab, ${cc} ${a}%, transparent) 0%, transparent 68%)`;
    }),
    c.ground,
  ].join(", ");

  const exit = EASE_IO(interpolate(t, [EXIT, end], [0, 1], CLAMP));
  const plateY = -exit * H * 1.04;
  const push = 1 + 0.025 * interpolate(t, [ENTER_LEN, EXIT], [0, 1], CLAMP);
  // Screen y of the plate's trailing edge: below it the line is already
  // uncovered and shows in its final ink; through the windows it stays dark.
  const edgeY = plateY + baseline + (H - baseline) * push;

  const rise = (i: number) =>
    EASE_OUT(
      interpolate(
        t,
        [ENTER + i * STAGGER, ENTER + i * STAGGER + ENTER_LEN],
        [0, 1],
        CLAMP,
      ),
    );
  const glyphAt = (i: number) =>
    `translate(${wordLeft + front.xs[i] * F} ${baseline + (1 - rise(i)) * CAP * F * 1.08}) scale(${F / 1000})`;

  const maskId = `m${uid}`;
  const clipId = `c${uid}`;
  const edgeId = `e${uid}`;
  // Holes in the plate overshoot by a hair; the glyph drawn on top hides it.
  const pad = (Math.max(1.5, 0.004 * F) * 1000) / F;

  return (
    <AbsoluteFill style={{ background: c.ground, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, background: ground }} />
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <clipPath id={clipId}>
            <rect
              x={-W}
              y={-H}
              width={W * 3}
              height={H + baseline + 0.02 * F}
            />
          </clipPath>
          <clipPath id={edgeId}>
            <rect x={0} y={edgeY} width={W} height={Math.max(0, H - edgeY)} />
          </clipPath>
          <mask id={maskId} maskUnits="userSpaceOnUse">
            <rect x={-W} y={-H} width={W * 3} height={H * 3} fill="white" />
            <g clipPath={`url(#${clipId})`}>
              {front.chars.map((ch, i) => {
                const g = GLYPHS[ch];
                if (!g?.holes) return null;
                return (
                  <path
                    key={`${i}-${ch}`}
                    d={g.holes}
                    fill="black"
                    stroke="black"
                    strokeWidth={pad}
                    strokeLinejoin="round"
                    transform={glyphAt(i)}
                  />
                );
              })}
            </g>
          </mask>
        </defs>

        <g
          transform={`translate(${W / 2 + lineShift} ${H / 2}) scale(${lineScale}) translate(${-W / 2} ${-H / 2})`}
        >
          <text
            x={back.xs.map((x) => lineLeft + x * B).join(" ")}
            y={lineBase}
            fontFamily={sora}
            fontWeight={500}
            fontSize={B}
            fill={tint}
            style={{ fontOpticalSizing: "none" }}
          >
            {back.chars.join("")}
          </text>
        </g>

        <g transform={`translate(0 ${plateY})`}>
          <g
            transform={`translate(${W / 2} ${baseline}) scale(${push}) translate(${-W / 2} ${-baseline})`}
          >
            <rect
              x={-W}
              y={-H}
              width={W * 3}
              height={H * 2}
              fill={c.bg}
              mask={`url(#${maskId})`}
            />
            <g clipPath={`url(#${clipId})`} fill={c.fg}>
              {front.chars.map((ch, i) => {
                const g = GLYPHS[ch];
                if (g) {
                  return (
                    <path
                      key={`${i}-${ch}`}
                      d={g.outer + g.holes}
                      fillRule="evenodd"
                      transform={glyphAt(i)}
                    />
                  );
                }
                return (
                  <text
                    key={`${i}-${ch}`}
                    transform={glyphAt(i)}
                    fontFamily={sora}
                    fontWeight={500}
                    fontSize={1000}
                    style={{ fontOpticalSizing: "none" }}
                  >
                    {ch}
                  </text>
                );
              })}
            </g>
          </g>
        </g>
        <g clipPath={`url(#${edgeId})`}>
          <g
            transform={`translate(${W / 2 + lineShift} ${H / 2}) scale(${lineScale}) translate(${-W / 2} ${-H / 2})`}
          >
            <text
              x={back.xs.map((x) => lineLeft + x * B).join(" ")}
              y={lineBase}
              fontFamily={sora}
              fontWeight={500}
              fontSize={B}
              fill={c.ink}
              style={{ fontOpticalSizing: "none" }}
            >
              {back.chars.join("")}
            </text>
          </g>
        </g>
      </svg>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/InstrumentSans";
import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const { fontFamily } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface CouponLineItem {
  name: string;
  detail: string;
  amount: number;
  /** Kept for API compatibility; the summary no longer draws item tiles. */
  mark?: string;
}

export interface CouponApplyProps {
  merchant?: string;
  items?: CouponLineItem[];
  /** First attempt, rejected with a shake. Set to "" to skip the invalid beat. */
  invalidCode?: string;
  /** Code that works. If it starts with `invalidCode`, only the rest is typed on retry. */
  code?: string;
  percentOff?: number;
  currency?: string;
  payLabel?: string;
  email?: string;
  cardholder?: string;
  theme?: "light" | "dark";
  accent?: string;
  speed?: number;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

const DEFAULT_ITEMS: CouponLineItem[] = [
  { name: "Lumen Pro", detail: "Billed yearly", amount: 180 },
  { name: "Extra seats", detail: "Qty 2 · $30.00 each", amount: 60 },
];

const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const MORPH = { damping: 200 };

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const ENTER2 = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);

const clampOpts = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const tween = (f: number, a: number, b: number, easing = ENTER) =>
  interpolate(f, [a, b], [0, 1], { ...clampOpts, easing });
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

function withAlpha(hex: string, alpha: number) {
  const h = hex.replace("#", "");
  const full = h.length === 3 ? h.replace(/./g, (c) => c + c) : h.slice(0, 6);
  const n = Number.parseInt(full, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}
const fmt = (n: number, cur: string) =>
  `${cur}${n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

interface Pal {
  dark: boolean;
  scrim: string;
  card: string;
  side: string;
  cardShadow: string;
  text: string;
  muted: string;
  faint: string;
  line: string;
  field: string;
  fieldRing: string;
  btn2: string;
  green: string;
  red: string;
  chip: string;
}

function palette(theme: "light" | "dark"): Pal {
  return theme === "dark"
    ? {
        dark: true,
        scrim: "rgba(3,5,12,0.34)",
        card: "#101114",
        side: "#15161A",
        cardShadow:
          "0 0 0 1px rgba(255,255,255,0.08), inset 0 1px 0 rgba(255,255,255,0.06), 0 24px 60px -18px rgba(0,0,0,0.7), 0 8px 18px -8px rgba(0,0,0,0.5)",
        text: "#F2F2F4",
        muted: "#A1A2AA",
        faint: "#6D6E77",
        line: "rgba(255,255,255,0.08)",
        field: "#0C0D10",
        fieldRing: "rgba(255,255,255,0.11)",
        btn2: "#1D1E23",
        green: "#45C98E",
        red: "#FF6B6F",
        chip: "rgba(255,255,255,0.07)",
      }
    : {
        dark: false,
