const READ_HOLD = 28;
const ROUND_GAP = 12;
const OUT_LEN = 10;
const MIN_HOLD = 36;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string, weight: number, track: number) {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) throw new Error("coy-denial: no 2d context");
  measureCtx.font = `${weight} ${MEASURE_PX}px "${funnel.fontFamily}"`;
  return (
    measureCtx.measureText(s).width / MEASURE_PX + track * Array.from(s).length
  );
}

function useFontsReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("coy-denial: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      funnel.waitUntilDone(),
      document.fonts.load(`${SAY_W} 100px "${funnel.fontFamily}"`),
      document.fonts.load(`${ASIDE_W} 100px "${funnel.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

interface Row {
  words: { text: string; x: number }[];
  w: number;
}

function split(s: string) {
  return s.split(/\s+/).filter(Boolean);
}

function sayW(words: string[]) {
  return em(words.join(" "), SAY_W, TRACK);
}

function toRow(words: string[], weight: number, track: number): Row {
  const space = em(" ", weight, track);
  let x = 0;
  const out = words.map((text) => {
    const at = x;
    x += em(text, weight, track) + space;
    return { text, x: at };
  });
  return { words: out, w: em(words.join(" "), weight, track) };
}

function balanced(words: string[], n: number): string[][] {
  if (n <= 1) return [words];
  let best: string[][] = [words];
  let bestW = Number.POSITIVE_INFINITY;
  let bestSlack = Number.POSITIVE_INFINITY;
  const walk = (start: number, left: number, acc: string[][]) => {
    if (left === 1) {
      const rows = [...acc, words.slice(start)];
      const widths = rows.map(sayW);
      const w = Math.max(...widths);
      const slack = widths.reduce((a, x) => a + (w - x) ** 2, 0);
      if (w < bestW - 0.01 || (w < bestW + 0.01 && slack < bestSlack)) {
        bestW = Math.min(w, bestW);
        bestSlack = slack;
        best = rows;
      }
      return;
    }
    for (let i = start + 1; i <= words.length - left + 1; i++) {
      walk(i, left - 1, [...acc, words.slice(start, i)]);
    }
  };
  walk(0, n, []);
  return best;
}

function wrapAside(s: string, maxEm: number): Row[] {
  const rows: string[][] = [];
  let cur: string[] = [];
  for (const w of split(s)) {
    const next = [...cur, w];
    if (cur.length > 0 && em(next.join(" "), ASIDE_W, ASIDE_TRACK) > maxEm) {
      rows.push(cur);
      cur = [w];
    } else {
      cur = next;
    }
  }
  if (cur.length) rows.push(cur);
  return rows.map((r) => toRow(r, ASIDE_W, ASIDE_TRACK));
}

function fitSay(say: string, W: number, H: number, portrait: boolean) {
  const words = split(say);
  const maxN = Math.min(words.length, portrait ? 6 : 3);
  let rows: string[][] = [words];
  let F = 0;
  for (let n = 1; n <= maxN; n++) {
    const cand = balanced(words, n);
    const w = Math.max(...cand.map(sayW));
    const f = Math.min(
      (W * (portrait ? 0.84 : 0.86)) / w,
      (H * (portrait ? 0.46 : 0.6)) / ((n - 1) * PITCH + 1),
    );
    if (f > F * 1.08) {
      F = f;
      rows = cand;
    }
  }
  return { rows, F };
}

function buildLayout(rounds: CoyDenialRound[], W: number, H: number) {
  const portrait = H > W * 1.1;
  const fits = rounds.map((r) => fitSay(r.say, W, H, portrait));
  const F = Math.min(...fits.map((f) => f.F));
  const says = fits.map((f) => f.rows.map((r) => toRow(r, SAY_W, TRACK)));
  const FA = Math.min(W, H) * (portrait ? 0.05 : 0.046);
  const asides = rounds.map((r) =>
    wrapAside(r.aside, (W * (portrait ? 0.6 : 0.36)) / FA),
  );
  return { says, asides, F, FA, portrait };
}

export function CoyDenial({
  rounds = DEFAULT_ROUNDS,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CoyDenialProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontsReady();

  const layout = useMemo(
    () => (ready ? buildLayout(rounds, W, H) : null),
    [ready, rounds, W, H],
  );

  if (!layout) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const { F, FA, portrait } = layout;
  const n = layout.says.length;
  const plan = layout.asides.map((rows) => {
    const words = rows.reduce((acc, r) => acc + r.words.length, 0);
    const gap = Math.max(3, Math.min(ASIDE_GAP, 36 / Math.max(1, words)));
    const end = ASIDE_AT + (words - 1) * gap + ASIDE_LEN;
    return { gap, end, out: Math.max(OUT_MIN, end + READ_HOLD) };
  });
  const starts: number[] = [];
  plan.reduce((acc, p) => {
    starts.push(acc);
    return acc + p.out + ROUND_GAP;
  }, 0);
  const motionEnd = starts[n - 1] + plan[n - 1].end;
  const room = durationInFrames * speed - MIN_HOLD;
  const k = Math.max(0.6, Math.min(1, room / motionEnd));
  const t = (frame * speed) / k;

  const mx = W * (portrait ? 0.08 : 0.065);
  const my = H * (portrait ? 0.07 : 0.1);
  const rowH = F * 1.18;
  const clipTop = -F * 0.06;

  const nodes = layout.says.map((rows, ri) => {
    const s = starts[ri];
    const { gap: aGap, out: outAt } = plan[ri];
    const local = t - s;
    const isLast = ri === n - 1;
    if (local < -2) return null;
    if (!isLast && local > outAt + OUT_LEN + 4) return null;

    const out = isLast
      ? 0
      : interpolate(local, [outAt, outAt + OUT_LEN], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });

    let wi = 0;
    const sayNodes = rows.map((row, li) => (
      <div
        key={`s-${ri}-${li}`}
        style={{
          position: "absolute",
          left: mx - F * 0.1,
          top: my + li * PITCH * F + clipTop,
          width: row.w * F + F * 0.3,
          height: rowH,
          overflow: "hidden",
        }}
      >
        {row.words.map((w) => {
          const i = wi++;
          const q = interpolate(
            local,
            [i * SAY_STAGGER, i * SAY_STAGGER + SAY_LEN],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
          const dy = (1 - q) * rowH - out * rowH;
          return (
            <div
              key={`sw-${ri}-${i}`}
              style={{
                position: "absolute",
                left: w.x * F + F * 0.1,
                top: -clipTop,
                height: F,
                fontFamily: funnel.fontFamily,
                fontWeight: SAY_W,
                fontSize: F,
                lineHeight: `${F}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color: c.ink,
                transform: `translateY(${dy.toFixed(2)}px)`,
              }}
            >
              {w.text}
            </div>
          );
        })}
      </div>
    ));

    const asideRows = layout.asides[ri];
    const asideFade = isLast
      ? 1
      : interpolate(local, [outAt - 6, outAt + 2], [1, 0], CLAMP);
    let ai = 0;
    const asideNodes = asideRows.flatMap((arow, ar) => {
      const ax = W - mx - arow.w * FA;
      const ay = H - my - FA - (asideRows.length - 1 - ar) * FA * 1.22;
      return arow.words.map((w) => {
        const i = ai++;
        const at = ASIDE_AT + i * aGap;
        const q = interpolate(local, [at, at + ASIDE_LEN], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <div
            key={`a-${ri}-${i}`}
            style={{
              position: "absolute",
              left: ax + w.x * FA,
              top: ay,
              height: FA,
              fontFamily: funnel.fontFamily,
              fontWeight: ASIDE_W,
              fontSize: FA,
              lineHeight: `${FA}px`,
              letterSpacing: `${ASIDE_TRACK}em`,
              whiteSpace: "pre",
              color: hi,
              opacity: q * asideFade,
              transform: `translateY(${((1 - q) * FA * 0.35).toFixed(2)}px)`,
            }}
          >
            {w.text}
          </div>
        );
      });
    });

    return (
      <div key={`r-${ri}`} style={{ position: "absolute", inset: 0 }}>
        {sayNodes}
        {asideNodes}
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const { fontFamily: grotesk } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const { fontFamily: serifItalic } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface CrashZoomProps {
  /** The calm tease, set in the serif italic. A trailing "…" types in dot by dot. */
  tease?: string;
  /** The reveal, slammed huge in solid ink. */
  reveal?: string;
  /** Line under the reveal. Empty string hides it. */
  tagline?: string;
  /** Kept for the shared draft API; the payoff colour comes from the ground. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
  /** gradients.sh preset for the ground. Defaults to "ember" (dark) or a warm paper mist (light). */
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

const BEAT = {
  teaseIn: 0,
  dots: 9,
  dotGap: 6,
  crash: 36,
  crashLen: 6,
  impact: 42,
  tag: 54,
} as const;

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const SOFT = Easing.bezier(0.22, 1, 0.36, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "radial-glow",
  colors: ["#fff3e4", "#ffb27a", "#f2643a", "#e889b5"],
  background: "#f5f4f0",
  speed: 0.97,
  loopSeconds: 10,
  warp: 0.6,
  blur: 0.7,
  grain: 0.12,
  seed: 14,
};

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    lines: "#F3F2EF",
    veil: "10,10,11",
    veilRest: 0.18,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    lines: "#121214",
    veil: "245,244,240",
    veilRest: 0.1,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function shake(d: number, amp: number, len: number, seed: number) {
  if (d < 0 || d > len) return { x: 0, y: 0, r: 0 };
  const k = (1 - d / len) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.9 + seed),
    y: amp * 0.75 * k * Math.cos(d * 3.7 + seed * 1.3),
    r: 0.5 * k * Math.sin(d * 2.3 + seed * 0.7),
  };
}

const LINE_COUNT = 72;

export function CrashZoom({
  tease = "Wait for it…",
  reveal = "1 DAY.",
  tagline = "to make this video.",
  theme = "dark",
  speed = 1,
  ground,
  groundParams,
}: CrashZoomProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);
  const inverted = t >= BEAT.impact && t < BEAT.impact + 1;

  const hasDots = tease.endsWith("…");
  const teaseBody = hasDots ? tease.slice(0, -1) : tease;
  const teaseIn = ENTER(ramp(t, BEAT.teaseIn, 12));
  const dots = hasDots
    ? Math.min(3, Math.max(0, Math.floor((t - BEAT.dots) / BEAT.dotGap) + 1))
    : 0;
  const push = interpolate(t, [0, BEAT.crash], [1, 1.28], {
    ...CLAMP,
    easing: EXIT,
  });
  const crash = ramp(t, BEAT.crash, BEAT.crashLen);
  const teaseScale = push * (1 + 7 * crash ** 2.2);
  const teaseBlur = crash > 0 ? 2 + 10 * crash : 0;
  const teaseOpacity = teaseIn * (1 - ramp(t, BEAT.crash + 3, 3));

  const slam = spring({
    frame: t - BEAT.impact - 1,
    fps,
    config: CARD,
  });
  const revealScale = inverted ? 1.14 : 1.14 - 0.14 * slam;
  const revealBlur = inverted ? 0 : 10 * Math.max(0, 1 - slam * 1.4);

  const rumble = ramp(t, BEAT.crash, BEAT.crashLen);
  const rx = t < BEAT.impact ? 5 * u * rumble * Math.sin(t * 2.1) : 0;
  const ry = t < BEAT.impact ? 4 * u * rumble * Math.cos(t * 2.7) : 0;
  const hit = shake(t - BEAT.impact, 14 * u, 12, 1.7);

  const linesIn = ramp(t, BEAT.crash + 1, BEAT.crashLen - 1) ** 1.4;
  const linesBack = SOFT(ramp(t, BEAT.impact + 1, 20));
  const reach = t < BEAT.impact ? 1.9 - 0.9 * linesIn : 1 + 0.18 * linesBack;
  const linesAlpha =
    t < BEAT.impact ? 0.55 * linesIn : 0.55 - (0.55 - 0.1) * linesBack;
  const cx = W / 2;
  const cy = H / 2;
  const far = Math.hypot(W, H) * 0.75;
  const lines: string[] = [];
  for (let i = 0; i < LINE_COUNT; i++) {
    const a =
      (i / LINE_COUNT) * Math.PI * 2 +
      (hash(i) - 0.5) * ((Math.PI * 2) / LINE_COUNT) * 0.9;
    const near = 1 + 0.35 * hash(i + 91);
    const rxIn = 0.44 * W * near * reach;
    const ryIn = 0.36 * H * near * reach;
    const half = (1.5 + 6 * hash(i + 37)) * u;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    const ox = cx + far * ca;
    const oy = cy + far * sa;
    const tipX = cx + rxIn * ca;
    const tipY = cy + ryIn * sa;
    lines.push(
      `M${(ox - sa * half).toFixed(1)} ${(oy + ca * half).toFixed(1)}L${(ox + sa * half).toFixed(1)} ${(oy - ca * half).toFixed(1)}L${tipX.toFixed(1)} ${tipY.toFixed(1)}Z`,
    );
  }

  const bloom = ENTER(ramp(t, BEAT.impact, 18));
  const veil = t < BEAT.impact ? 0.9 : 0.9 - (0.9 - c.veilRest) * bloom;
  const groundScale = 1.12 - 0.12 * bloom + 0.03 * ramp(t, BEAT.impact, 80);

  const revealFs = Math.min(0.5 * H, (0.84 * W) / (0.43 * reveal.length));
  const teaseFs = Math.min(0.1 * H, 0.085 * W);
  const tagFs = Math.min(0.075 * H, 0.062 * W);
  const tagIn = ENTER(ramp(t, BEAT.tag, 12));

  const teaseText = (scale: number, opacity: number, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transform: `translateY(${(1 - teaseIn) * 0.04 * H}px) scale(${scale})`,
        filter:
          teaseBlur > 0.2
            ? `blur(${(teaseBlur * u) / scale}px)`
            : `blur(${(1 - teaseIn) * 6 * u}px)`,
        opacity,
      }}
    >
      <div
        style={{
          fontFamily: serifItalic,
          fontStyle: "italic",
          fontWeight: 400,
          fontSize: teaseFs,
          lineHeight: 1,
          letterSpacing: "-0.01em",
          color: c.ink,
          whiteSpace: "nowrap",
        }}
      >
        {teaseBody}
        {hasDots ? (
          <span
            style={{
              display: "inline-block",
              clipPath: `inset(-20% ${100 - (dots / 3) * 100}% -20% 0)`,
            }}
          >
            …
          </span>
        ) : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        background: inverted ? c.ink : c.stage,
        overflow: "hidden",
      }}
    >
      {!inverted ? (
        <>
          <AbsoluteFill style={{ transform: `scale(${groundScale})` }}>
            <GshGround
              preset={ground ?? (theme === "dark" ? "ember" : undefined)}
              params={
                groundParams ?? (theme === "light" ? LIGHT_GROUND : undefined)
              }
              timeOffset={2.4}
              timeScale={0.5}
            />
          </AbsoluteFill>
          <AbsoluteFill style={{ background: `rgba(${c.veil},${veil})` }} />
        </>
      ) : null}

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${rx + hit.x}px, ${ry + hit.y}px) rotate(${hit.r}deg)`,
          transformOrigin: "50% 50%",
        }}
      >
        {linesAlpha > 0.01 ? (
          <svg
            width={W}
            height={H}
            viewBox={`0 0 ${W} ${H}`}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <path
              d={lines.join("")}
              fill={inverted ? c.stage : c.lines}
              opacity={inverted ? 0.8 : linesAlpha}
            />
          </svg>
        ) : null}

        {t < BEAT.impact ? (
          <>
            {crash > 0.02
              ? [5, 4, 3, 2, 1].map((k) =>
                  teaseText(
                    teaseScale * (1 + 0.07 * k * crash),
                    (teaseOpacity * 0.5) / (1 + 0.6 * k),
                    `ghost-${k}`,
                  ),
                )
              : null}
            {teaseText(teaseScale, teaseOpacity, "tease")}
          </>
        ) : (
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <div
              style={{
                fontFamily: grotesk,
                fontWeight: 400,
                fontSize: revealFs,
                lineHeight: 0.9,
                letterSpacing: "-0.05em",
                whiteSpace: "nowrap",
                color: inverted ? c.stage : c.ink,
                transform: `scale(${revealScale})`,
                filter:
                  revealBlur > 0.2 ? `blur(${revealBlur * u}px)` : undefined,
              }}
            >
              {reveal}
            </div>
            {tagline ? (
              <div
                style={{
                  marginTop: 0.035 * H,
                  fontFamily: serifItalic,
                  fontStyle: "italic",
                  fontWeight: 400,
                  fontSize: tagFs,
                  lineHeight: 1,
                  color: c.ink,
                  whiteSpace: "nowrap",
                  opacity: inverted ? 0 : tagIn,
                  transform: `translateY(${(1 - tagIn) * 0.03 * H}px)`,
                  filter: `blur(${(1 - tagIn) * 6 * u}px)`,
                }}
              >
                {tagline}
              </div>
            ) : null}
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Gabarito";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const gabarito = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CrewOfOneProps {
  roles?: string[];
  name?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#3B1E6E", ink: "#FFFFFF", accent: "#FF7A6B" },
  light: { bg: "#EDE7FB", ink: "#3B1E6E", accent: "#D9483A" },
} as const;

const ROLE_W = 400;
const NAME_W = 500;
const TRACK = -0.02;
const NAME_TRACK = -0.03;
const FONT_PX = 200;
const NAME_SCALE = 2.3;
const LINE = 1.32;
const STACK_LINE = 1.06;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  roles: number;
  name: number;
  asc: number;
  desc: number;
}

function measure(roles: string[], name: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("crew-of-one: no 2d context");
  ctx.font = `${ROLE_W} ${FONT_PX}px "${gabarito.fontFamily}"`;
  let widest = 0.1;
  for (const r of roles) {
    widest = Math.max(
      widest,
      ctx.measureText(r).width / FONT_PX + TRACK * Array.from(r).length,
    );
  }
  const fm = ctx.measureText("Hxg");
  ctx.font = `${NAME_W} ${FONT_PX}px "${gabarito.fontFamily}"`;
  const nameW =
    ctx.measureText(name).width / FONT_PX +
    NAME_TRACK * Array.from(name).length;
  return {
    roles: widest,
    name: nameW,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics(roles: string[], name: string) {
  const key = [name, ...roles].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("crew-of-one: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      gabarito.waitUntilDone(),
      document.fonts.load(`${ROLE_W} 100px "${gabarito.fontFamily}"`),
      document.fonts.load(`${NAME_W} 100px "${gabarito.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [n, ...rs] = key.split("\u0001");
        setState({ key, m: measure(rs, n) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

export function CrewOfOne({
  roles = [
    "Written by",
    "Directed by",
    "Edited by",
    "Motion by",
    "Captions by",
    "Shipped by",
  ],
  name = "you",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CrewOfOneProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const t = frame * speed;
  const D = Math.max(90, durationInFrames);
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const list = roles.length > 0 ? roles : ["Made by"];
  const m = useMetrics(list, name);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.07 : 0.06);
  const gap = W * (portrait ? 0.035 : 0.025);
  const gutter = W * (portrait ? 0.56 : 0.54);
  const leftRoom = gutter - gap / 2 - margin;
  const rightRoom = W - margin - (gutter + gap / 2);
  const stackFit = (H * 0.86) / (n * STACK_LINE);
  const F = Math.min(
    H * (portrait ? 0.055 : 0.13),
    leftRoom / m.roles,
    rightRoom / (m.name * NAME_SCALE),
    stackFit,
  );
  const NF = F * NAME_SCALE;
  const mid = H / 2;
  const baseline = mid + F * 0.36;
  const top = (base: number, size: number) =>
    base - ((1 - m.asc - m.desc) / 2 + m.asc) * size;

  const introEnd = 18;
  const rollStart = 30;
  const rollEnd = Math.max(rollStart + (n - 1) * 10, D * 0.6);
  const step = n > 1 ? (rollEnd - rollStart) / (n - 1) : 1;
  const move = Math.min(13, step * 0.55);
  let p = 0;
  for (let k = 1; k < n; k++) {
    const s = rollStart + (k - 1) * step + (step - move);
    p += interpolate(t, [s, s + move], [0, 1], { ...CLAMP, easing: EASE_IO });
  }
  const cStart = rollEnd + 12;
  const cLen = 24;
  const gather = interpolate(t, [cStart, cStart + cLen], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const intro = interpolate(t, [0, introEnd], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const nameIn = interpolate(t, [8, 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const LS = F * LINE;
  const LS2 = F * STACK_LINE;
  const stackTop = -((n - 1) / 2) * LS2;

  const roleStyle: React.CSSProperties = {
    position: "absolute",
    right: W - (gutter - gap / 2),
    height: F,
    lineHeight: `${F}px`,
    whiteSpace: "pre",
    fontFamily: gabarito.fontFamily,
    fontWeight: ROLE_W,
    fontSize: F,
    letterSpacing: `${TRACK}em`,
    color: c.ink,
    textAlign: "right",
  };

  const nodes: React.ReactNode[] = list.map((r, i) => {
    const d = i - p;
    const rollY = d * LS + (1 - intro) * LS * 0.9;
    const stackY = stackTop + i * LS2;
    const y = rollY + (stackY - rollY) * gather;
    const ad = Math.abs(d);
    const rollA =
      interpolate(ad, [0, 0.55, 1, 2.6], [1, 0.42, 0.3, 0], CLAMP) * intro;
    const a = rollA + (1 - rollA) * gather;
    return (
      <div
        key={`r${i}`}
        style={{
          ...roleStyle,
          top: top(baseline + y, F),
          opacity: a,
        }}
      >
        {r}
      </div>
    );
  });

  const nameTop = top(baseline, NF);
  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
      <div
        style={{
          position: "absolute",
          left: gutter + gap / 2,
          top: nameTop - NF * 0.15,
          height: NF * 1.35,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "relative",
            top: NF * 0.15,
            height: NF,
            lineHeight: `${NF}px`,
            whiteSpace: "pre",
            fontFamily: gabarito.fontFamily,
            fontWeight: NAME_W,
            fontSize: NF,
            letterSpacing: `${NAME_TRACK}em`,
            color: hi,
            transform: `translateY(${((1 - nameIn) * NF * 1.3).toFixed(2)}px)`,
          }}
        >
          {name}
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadDisplay } from "@remotion/google-fonts/SpaceGrotesk";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CrosshairLockProps {
  x?: number;
  y?: number;
  label?: string;
  value?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

const V_AT = 14;
const H_AT = 18;
const SLIDE = 26;
const LOCK = H_AT + SLIDE;
const LEAD_AT = LOCK + 8;
const POP_AT = LEAD_AT + 10;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.55)",
    axis: "rgba(255,255,255,0.2)",
    dotRGB: "#FFFFFF",
    dotA: 0.26,
    // gradients.sh "mesh": blooms out of the locked peak
    mesh: ["#ECDCF2", "#8796EE", "#2E45B7"],
    grain: 0.055,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.55)",
    axis: "rgba(18,18,20,0.2)",
    dotRGB: "#121214",
    dotA: 0.22,
    // gradients.sh "mesh", deep end first on off-white
    mesh: ["#0E1645", "#2E45B7", "#8796EE"],
    grain: 0.04,
  },
} as const;

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function parseValue(v: string) {
  const m = v.match(/([\d.,]+)\s*([kKmM])?/);
  if (!m) return null;
  const n = Number.parseFloat(m[1].replace(/,/g, ""));
  if (!Number.isFinite(n)) return null;
  const mult = m[2] ? (m[2].toLowerCase() === "k" ? 1e3 : 1e6) : 1;
  return n * mult;
}

function splitValue(v: string) {
  const m = v.match(/^(\s*[^\d]*[\d.,]+\s*[kKmMbB%×x]?)(.*)$/);
  if (!m) return { head: v, tail: "" };
  return { head: m[1], tail: m[2] };
}

function clock(f: number) {
  const mins = Math.round((9 * 60 + f * 12 * 60) / 5) * 5;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={41}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function CrosshairLock({
  x = 0.7,
  y = 0.94,
  label = "Peak",
  value = "2.4k/min",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: CrosshairLockProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];

  const left = 0.14 * W;
  const right = 0.9 * W;
  const top = 0.42 * H;
  const bottom = 0.84 * H;
  const step = 16 * u;
  const cols = Math.floor((right - left) / step);
  const rows = Math.floor((bottom - top) / step);
  const fx = Math.min(0.97, Math.max(0.03, x));
  const fy = Math.min(1, Math.max(0.15, y));
  const peakCol = Math.round(fx * cols);

  const heights = Array.from({ length: cols + 1 }, (_, c) => {
    const f = c / cols;
    const base =
      0.34 +
      0.12 * Math.sin(f * 7.3 + 0.8) +
      0.08 * Math.sin(f * 17.1 + 2.1) +
      0.07 * (hash(c) - 0.5);
    const g = Math.exp(-(((f - fx) / 0.075) ** 2));
    const v = fy * (Math.min(0.66, Math.max(0.12, base)) * (1 - g) + g);
    return c === peakCol ? rows : Math.min(rows - 1, Math.round(v * rows));
  });
  const peakRows = Math.round(fy * rows);
  heights[peakCol] = peakRows;
  for (let c = 0; c <= cols; c++) {
    if (c !== peakCol) heights[c] = Math.min(heights[c], peakRows - 1);
  }

  const px = left + peakCol * step;
  const py = bottom - (peakRows - 1) * step;

  const vk = EASE_IO(interpolate(t, [V_AT, V_AT + SLIDE], [0, 1], CLAMP));
  const hk = EASE_IO(interpolate(t, [H_AT, H_AT + SLIDE], [0, 1], CLAMP));
  const fromLeft = fx > 0.5;
  const vStart = fromLeft ? left - 0.07 * W : right + 0.07 * W;
  const vx = vStart + (px - vStart) * vk;
  const hStart = bottom + 0.1 * H;
  const hy = hStart + (py - hStart) * hk;
  const vOn = interpolate(t, [V_AT, V_AT + 6], [0, 1], CLAMP);
  const hOn = interpolate(t, [H_AT, H_AT + 6], [0, 1], CLAMP);

  const ring = interpolate(t, [LOCK, LOCK + 20], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const lock = spring({
    frame: t - LOCK,
    fps,
    config: { damping: 14, stiffness: 220, mass: 0.6 },
  });
  const locked = t >= LOCK;

  const num = parseValue(value);
  const yFrac = Math.max(0, (bottom - hy) / (bottom - py));
  const yRead =
    num === null
      ? (fy * yFrac).toFixed(2)
      : Math.round(num * yFrac).toLocaleString("en-US");
  const xFrac = (vx - left) / (right - left);
  const xRead = clock(Math.min(1, Math.max(0, xFrac)));

  const dir = fx > 0.55 ? -1 : 1;
  const valueSize = 112 * u;
  const labelY = top - 96 * u;
  const diag = py - labelY;
  const run = 64 * u;
  const elbowX = px + dir * diag;
  const endX = elbowX + dir * run;
  const leadLen = Math.SQRT2 * diag + run;
  const lead = EASE_IO(interpolate(t, [LEAD_AT, LEAD_AT + 14], [0, 1], CLAMP));
  const pop = spring({
    frame: t - POP_AT,
    fps,
    config: { damping: 16, stiffness: 200, mass: 0.6 },
  });
  const popOp = interpolate(t, [POP_AT, POP_AT + 8], [0, 1], CLAMP);
  const { head, tail } = splitValue(value);
  const gradId = `mesh${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const bloom = interpolate(t, [LOCK - 2, LOCK + 34], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const bloomR = Math.max(1, (0.06 + 0.34 * bloom) * W);

  const dots: React.ReactNode[] = [];
  for (let c = 0; c <= cols; c++) {
    const f = c / cols;
    const rise = EASE_OUT(interpolate(t, [f * 14, f * 14 + 12], [0, 1], CLAMP));
    const isPeak = c === peakCol;
    for (let r = 0; r < heights[c]; r++) {
      const top1 = isPeak && r === heights[c] - 1;
      if (top1 && locked) continue;
      dots.push(
        <circle
          key={`${c}-${r}`}
          cx={left + c * step}
          cy={bottom - r * step - (1 - rise) * 10 * u}
          r={2.2 * u}
          fill={`url(#${gradId})`}
          opacity={rise}
        />,
      );
    }
  }

  const hair = Math.max(1, 1.25 * u);
  const readout: React.CSSProperties = {
    position: "absolute",
    fontFamily: mono,
    fontWeight: 500,
    fontSize: 16 * u,
    fontVariantNumeric: "tabular-nums",
    letterSpacing: "-0.01em",
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
        <defs>
          <radialGradient
            id={gradId}
            gradientUnits="userSpaceOnUse"
            cx={px}
            cy={py}
            r={bloomR}
            gradientTransform={`translate(${px} ${py}) scale(1.35 1) translate(${-px} ${-py})`}
          >
            <stop offset="0" stopColor={p.mesh[0]} stopOpacity={bloom} />
            <stop
              offset="0.28"
              stopColor={p.mesh[1]}
              stopOpacity={0.95 * bloom}
            />
            <stop offset="0.62" stopColor={p.mesh[2]} stopOpacity={0.6} />
            <stop offset="1" stopColor={p.dotRGB} stopOpacity={p.dotA} />
          </radialGradient>
        </defs>
        <line
          x1={left - 8 * u}
          x2={right + 8 * u}
          y1={bottom + 14 * u}
          y2={bottom + 14 * u}
          stroke={p.axis}
          strokeWidth={hair}
          opacity={interpolate(t, [0, 10], [0, 1], CLAMP)}
        />
        {dots}
        <line
          x1={vx}
          x2={vx}
          y1={top - 24 * u}
          y2={bottom + 14 * u}
          stroke={p.hair}
          strokeWidth={hair}
          opacity={vOn}
        />
        <line
          x1={left - 8 * u}
          x2={right + 8 * u}
          y1={hy}
          y2={hy}
          stroke={p.hair}
          strokeWidth={hair}
          opacity={hOn}
        />
        <line
          x1={vx}
          x2={vx}
          y1={bottom + 14 * u}
          y2={bottom + 22 * u}
          stroke={p.fg}
          strokeWidth={hair * 1.6}
          opacity={vOn}
        />
        <line
          x1={left - 16 * u}
          x2={left - 8 * u}
          y1={hy}
          y2={hy}
          stroke={p.fg}
          strokeWidth={hair * 1.6}
          opacity={hOn}
        />
        {locked ? (
          <>
            <circle
              cx={px}
              cy={py}
              r={(10 + 34 * ring) * u}
              fill="none"
              stroke={accent}
              strokeWidth={2 * u}
              opacity={0.9 * (1 - ring)}
            />
            <circle
              cx={px}
              cy={py}
              r={(14 - 3 * lock) * u}
              fill={p.bg}
              stroke={accent}
              strokeWidth={2 * u}
              opacity={Math.min(1, lock * 1.4)}
            />
            <circle cx={px} cy={py} r={(3 + 2 * lock) * u} fill={accent} />
          </>
        ) : null}
        {lead > 0 ? (
          <path
            d={`M ${px + dir * 14 * u * Math.SQRT1_2} ${py - 14 * u * Math.SQRT1_2} L ${elbowX} ${labelY} L ${endX} ${labelY}`}
            fill="none"
            stroke={accent}
            strokeWidth={1.75 * u}
            strokeDasharray={leadLen}
            strokeDashoffset={leadLen * (1 - lead)}
          />
        ) : null}
        {lead > 0.98 ? (
          <circle cx={endX} cy={labelY} r={3 * u} fill={accent} />
        ) : null}
      </svg>

      <div
        style={{
          ...readout,
          left: vx,
          top: bottom + 30 * u,
          transform: "translateX(-50%)",
          color: locked ? p.fg : p.muted,
          opacity: vOn,
        }}
      >
        {xRead}
      </div>
      <div
        style={{
          ...readout,
          right: W - left + 24 * u,
          top: hy,
          transform: "translateY(-50%)",
          color: locked ? p.fg : p.muted,
          opacity: hOn,
        }}
      >
        {yRead}
      </div>

      <div
        style={{
          position: "absolute",
          ...(dir < 0
            ? { right: W - (endX - 18 * u) }
            : { left: endX + 18 * u }),
          top: labelY - valueSize * 0.5,
          height: valueSize,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: dir < 0 ? "flex-end" : "flex-start",
          opacity: popOp,
          transform: `translateX(${dir * (1 - pop) * 14 * u}px) scale(${0.96 + 0.04 * pop})`,
          transformOrigin: dir < 0 ? "100% 50%" : "0% 50%",
        }}
      >
        <div
          style={{
            position: "absolute",
            bottom: "100%",
            marginBottom: 2 * u,
            display: "flex",
            alignItems: "center",
            gap: 8 * u,
            fontFamily: mono,
            fontWeight: 500,
            fontSize: 13 * u,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            color: p.muted,
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              width: 6 * u,
              height: 6 * u,
              borderRadius: "50%",
              background: accent,
            }}
          />
          {label}
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            fontFamily: display,
            fontWeight: 500,
            lineHeight: 1,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              fontSize: valueSize,
              letterSpacing: "-0.04em",
              color: p.fg,
            }}
          >
            {head}
          </span>
          {tail ? (
            <span
              style={{
                fontSize: valueSize * 0.36,
                fontWeight: 400,
                letterSpacing: "-0.01em",
                marginLeft: 0.08 * valueSize,
                color: p.muted,
              }}
            >
              {tail}
            </span>
          ) : null}
        </div>
      </div>

      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type CrtScreenProps = {
  curvature?: number;
  scanlines?: number;
  maskScale?: number;
  vignette?: number;
};

const DEFAULTS = {
  curvature: 1,
  scanlines: 1,
  maskScale: 2,
  vignette: 1,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_curvature;
uniform float u_scanlines;
uniform float u_mask_scale;
uniform float u_vignette;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float SCAN_LINES = 240.0;

vec2 warpTube(vec2 uv, float k) {
  vec2 p = uv * 2.0 - 1.0;
  float x2 = p.x * p.x;
  float y2 = p.y * p.y;
  p.x *= 1.0 + k * 0.11 * y2;
  p.y *= 1.0 + k * 0.17 * x2;
  p /= 1.0 + k * 0.045;
  return p * 0.5 + 0.5;
}

vec3 phosphorMask(float x, float scale) {
  float sub = mod(floor(x / max(scale, 1.0)), 3.0);
  vec3 lit = vec3(
    step(sub, 0.5),
    step(0.5, sub) * step(sub, 1.5),
    step(1.5, sub)
  );
  return mix(vec3(0.34), vec3(1.0), lit);
}

void main() {
  vec2 uv = warpTube(v_uv, u_curvature);

  vec2 edge =
    smoothstep(vec2(0.0), vec2(0.005), uv) *
    smoothstep(vec2(0.0), vec2(0.005), 1.0 - uv);
  float inside = edge.x * edge.y;

  vec4 base = texture(u_scene, uv);

  vec3 spread = vec3(0.0);
  for (int i = -2; i <= 2; i++) {
    spread += texture(u_scene, uv + vec2(float(i) * 0.0018, 0.0)).rgb;
  }
  spread /= 5.0;
  vec3 bloom = max(spread - 0.5, vec3(0.0));

  vec3 color = base.rgb;
  color *= phosphorMask(gl_FragCoord.x, u_mask_scale);
  color += bloom * 0.75;

  float scan = mix(1.0, 0.5 + 0.5 * cos(uv.y * SCAN_LINES * PI * 2.0), 0.55);
  color *= mix(1.0, scan, clamp(u_scanlines, 0.0, 1.5));

  vec2 vc = uv * 2.0 - 1.0;
  float radius = length(vc * vec2(0.86, 1.0));
  color *= mix(1.0, smoothstep(1.6, 0.35, radius), clamp(u_vignette, 0.0, 1.5));

  color *= 1.0 + 0.012 * sin(u_frame * PI / 30.0);
  color *= inside;

  outColor = vec4(clamp(color, 0.0, 1.0), max(base.a, 1.0 - inside));
}`;

const shader = makeFilterShader<CrtScreenProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      curvature = DEFAULTS.curvature,
      scanlines = DEFAULTS.scanlines,
      maskScale = DEFAULTS.maskScale,
      vignette = DEFAULTS.vignette,
    } = passedProps;
    gl.uniform1f(uniform("u_curvature"), curvature);
    gl.uniform1f(uniform("u_scanlines"), scanlines);
    gl.uniform1f(uniform("u_mask_scale"), maskScale);
    gl.uniform1f(uniform("u_vignette"), vignette);
  },
);

const CrtScreenFallback: React.FC<CrtScreenProps & CanvasFilterProps> = ({
  children,
  scanlines = DEFAULTS.scanlines,
  vignette = DEFAULTS.vignette,
}) => (
  <AbsoluteFill>
    <AbsoluteFill style={{ filter: "saturate(1.1) contrast(1.06)" }}>
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background:
          "repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.34) 0px, rgba(0, 0, 0, 0.34) 1.5px, transparent 1.5px, transparent 3px)",
        opacity: Math.min(scanlines, 1),
      }}
    />
    <AbsoluteFill
      style={{
        background:
          "radial-gradient(ellipse 82% 78% at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.72) 100%)",
        opacity: Math.min(vignette, 1),
      }}
    />
  </AbsoluteFill>
);

export const CrtScreen = makeCanvasFilter<CrtScreenProps>({
  shader,
  fallback: CrtScreenFallback,
});

"use client";

import type React from "react";
import { useCurrentFrame } from "remotion";
import { DEFAULT_STEP, hashRange, qstep } from "@/lib/remocn/stop-motion";

const GRAVITY = 0.9;
const FLIGHT_SHRINK = 0.5;
const EXIT_OPACITY = 0.4;

const FOLD_TILT = 46;
const WAD_REACH = 0.27;
const WAD_SPREAD = 0.07;
const ANGLE_JITTER = 0.22;
const SCALE_SPREAD = 0.25;
const DEFAULT_RANDOMNESS = 0.6;
const DEFAULT_LAYERS = 2;
const LAYER_TILT_FLOOR = 0.45;
const FACET_SIZE = 0.5;
const FACET_CAP = 0.5;

const TONE_PATTERN = [0, 1, 3, 1, 0, 2, 1, 2, 0];

const TONES = [
  { lit: "rgba(255,255,255,0.66)", dark: "rgba(255,255,255,0.18)" },
  { lit: "rgba(255,255,255,0.30)", dark: "rgba(38,36,44,0.10)" },
  { lit: "rgba(255,255,255,0.08)", dark: "rgba(38,36,44,0.20)" },
  { lit: "rgba(38,36,44,0.06)", dark: "rgba(38,36,44,0.30)" },
];

const LIGHT_ANGLE = -55;
const CREASE_BLEND = 9;

export type CrumplePhase = "idle" | "crumple" | "toss" | "gone";

export type CrumplePose = {
  phase: CrumplePhase;
  crush: number;
  scale: number;
  rotate: number;
  x: number;
  y: number;
  opacity: number;
};

export type CrumpleSegment = {
  clip: [number, number][];
  origin: [number, number];
  dx: number;
  dy: number;
  scale: number;
  rotate: number;
  tone: number;
  crease: number;
};

export type CrumpleTossTiming = {
  at: number;
  crumpleSteps?: number;
  tossSteps?: number;
  direction?: number;
  distance?: number;
  spin?: number;
  crushTo?: number;
  seed?: string;
  step?: number;
};

const rayToEdge = (
  angle: number,
  halfWidth: number,
  halfHeight: number,
): [number, number] => {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const t = Math.min(
    halfWidth / (Math.abs(cos) || 1e-9),
    halfHeight / (Math.abs(sin) || 1e-9),
  );
  return [cos * t, sin * t];
};

const normalize = (angle: number) => {
  const turn = Math.PI * 2;
  return ((angle % turn) + turn) % turn;
};

const shrinkToward = (
  [x, y]: [number, number],
  factor: number,
): [number, number] => [x * factor, y * factor];

const averageOf = (points: [number, number][]): [number, number] => [
  points.reduce((sum, p) => sum + p[0], 0) / points.length,
  points.reduce((sum, p) => sum + p[1], 0) / points.length,
];

export function crumpleSegments(args: {
  width: number;
  height: number;
  segments?: number;
  layers?: number;
  crushTo?: number;
  randomness?: number;
  seed?: string;
}): CrumpleSegment[] {
  const count = Math.max(3, Math.round(args.segments ?? 9));
  const layers = Math.max(1, Math.round(args.layers ?? DEFAULT_LAYERS));
  const crushTo = args.crushTo ?? 0.34;
  const chaos = Math.min(1, Math.max(0, args.randomness ?? DEFAULT_RANDOMNESS));
  const seed = args.seed ?? "toss";
  const halfWidth = args.width / 2;
  const halfHeight = args.height / 2;
  const wad = Math.min(args.width, args.height) * crushTo;

  const angles = Array.from(
    { length: count },
    (_, i) =>
      (i / count) * Math.PI * 2 +
      hashRange(`${seed}:ang${i}`, -ANGLE_JITTER, ANGLE_JITTER) * chaos,
  );

  const corners: [number, number][] = [
    [halfWidth, halfHeight],
    [-halfWidth, halfHeight],
    [-halfWidth, -halfHeight],
    [halfWidth, -halfHeight],
  ];

  const toPercent = ([x, y]: [number, number]): [number, number] => [
    ((x + halfWidth) / args.width) * 100,
    ((y + halfHeight) / args.height) * 100,
  ];

  const panels: CrumpleSegment[] = [];

  angles.forEach((angle, i) => {
    const nextAngle =
      angles[(i + 1) % count] + (i === count - 1 ? Math.PI * 2 : 0);
    const from = rayToEdge(angle, halfWidth, halfHeight);
    const to = rayToEdge(nextAngle, halfWidth, halfHeight);

    const span = normalize(nextAngle - angle);
    const between = corners
      .map((corner): [[number, number], number] => [
        corner,
        normalize(Math.atan2(corner[1], corner[0]) - angle),
      ])
      .filter(([, spanned]) => spanned > 0 && spanned < span)
      .sort((a, b) => a[1] - b[1])
      .map(([corner]) => corner);

    const rim: [number, number][] = [from, ...between, to];

    for (let layer = 0; layer < layers; layer++) {
      const inner = layer / layers;
      const outer = (layer + 1) / layers;
      const depth = (layer + 1) / layers;
      const shape: [number, number][] =
        layer === 0
          ? [[0, 0], ...rim.map((point) => shrinkToward(point, outer))]
          : [
              ...rim.map((point) => shrinkToward(point, outer)),
              ...[...rim].reverse().map((point) => shrinkToward(point, inner)),
            ];

      const centroid = averageOf(shape);
      const extent =
        Math.max(
          ...shape.map((point) =>
            Math.hypot(point[0] - centroid[0], point[1] - centroid[1]),
          ),
        ) || 1;
      const key = `${seed}:${i}:${layer}`;

      const reach =
        wad *
        (WAD_REACH * depth +
          hashRange(`${key}:reach`, -WAD_SPREAD, WAD_SPREAD) * chaos * depth);
      const heading = Math.atan2(centroid[1], centroid[0]);

      panels.push({
        clip: shape.map(toPercent),
        origin: toPercent(centroid),
        dx: Math.cos(heading) * reach - centroid[0],
        dy: Math.sin(heading) * reach - centroid[1],
        scale:
          Math.min(FACET_CAP, (wad * FACET_SIZE) / extent) *
          (1 + hashRange(`${key}:size`, -SCALE_SPREAD, SCALE_SPREAD) * chaos),
        rotate:
          chaos === 0
            ? 0
            : hashRange(`${seed}:tilt${i}`, -FOLD_TILT, FOLD_TILT) *
              chaos *
              (LAYER_TILT_FLOOR + (1 - LAYER_TILT_FLOOR) * depth),
        tone: Math.min(
          TONES.length - 1,
          TONE_PATTERN[panels.length % TONE_PATTERN.length] +
            Math.ceil((1 - depth) * 2),
        ),
        crease: 0.5 + hashRange(`${key}:crease`, -0.2, 0.2) * chaos,
      });
    }
  });

  return panels;
}

export function creaseShading(
  piece: Pick<CrumpleSegment, "tone" | "rotate" | "crease">,
  crush: number,
): string {
  const tone = TONES[piece.tone];
  const fold = piece.crease * 100;
  const lit = Math.max(0, fold - CREASE_BLEND).toFixed(1);
  const dark = Math.min(100, fold + CREASE_BLEND).toFixed(1);
  const angle = (LIGHT_ANGLE - piece.rotate * crush).toFixed(1);
  return `linear-gradient(${angle}deg, ${tone.lit} 0%, ${tone.lit} ${lit}%, ${tone.dark} ${dark}%, ${tone.dark} 100%)`;
}

export function crumpleTossLanding(options?: {
  direction?: number;
  distance?: number;
}): { x: number; y: number } {
  const distance = options?.distance ?? 900;
  const radians = ((options?.direction ?? -35) * Math.PI) / 180;
  return {
    x: distance * Math.cos(radians),
    y: distance * Math.sin(radians) + GRAVITY * distance,
  };
}

export function crumpleTossPose(
  args: CrumpleTossTiming & { frame: number },
): CrumplePose {
  const crumpleSteps = args.crumpleSteps ?? 4;
  const tossSteps = args.tossSteps ?? 5;
  const direction = args.direction ?? -35;
  const distance = args.distance ?? 900;
  const spin = args.spin ?? 220;
  const step = args.step ?? DEFAULT_STEP;

  if (args.frame < args.at) {
    return {
      phase: "idle",
      crush: 0,
      scale: 1,
      rotate: 0,
      x: 0,
      y: 0,
      opacity: 1,
    };
  }

  const pose = qstep(args.frame - args.at, step);

  if (pose < crumpleSteps) {
    return {
      phase: "crumple",
      crush: (pose + 1) / crumpleSteps,
      scale: 1,
      rotate: 0,
      x: 0,
      y: 0,
      opacity: 1,
    };
  }

  if (pose < crumpleSteps + tossSteps) {
    const t = (pose - crumpleSteps + 1) / tossSteps;
    const radians = (direction * Math.PI) / 180;
    return {
      phase: "toss",
      crush: 1,
      scale: 1 - FLIGHT_SHRINK * t,
      rotate: spin * t,
      x: distance * Math.cos(radians) * t,
      y: distance * Math.sin(radians) * t + GRAVITY * distance * t * t,
      opacity: t === 1 ? EXIT_OPACITY : 1,
    };
  }

  return {
    phase: "gone",
    crush: 1,
    scale: 0,
    rotate: 0,
    x: 0,
    y: 0,
    opacity: 0,
  };
}

export interface CrumpleTossProps extends CrumpleTossTiming {
  children: React.ReactNode;
  width: number;
  height: number;
  segments?: number;
  layers?: number;
  randomness?: number;
}

export function CrumpleToss({
  children,
  width,
  height,
  segments,
  layers,
  randomness,
  ...timing
}: CrumpleTossProps) {
  const frame = useCurrentFrame();
  const pose = crumpleTossPose({ frame, ...timing });
  if (pose.phase === "gone") return null;

  const pieces = crumpleSegments({
    width,
    height,
    segments,
    layers,
    randomness,
    crushTo: timing.crushTo,
    seed: timing.seed,
  });
  const c = pose.crush;

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        transformOrigin: "center",
        opacity: pose.opacity,
        translate: `${pose.x}px ${pose.y}px`,
        rotate: `${pose.rotate}deg`,
        scale: `${pose.scale}`,
      }}
    >
      {pieces.map((piece, i) => (
        <div
          key={`piece:${i}`}
          style={{
            position: "absolute",
            inset: 0,
            clipPath: `polygon(${piece.clip.map(([x, y]) => `${x}% ${y}%`).join(", ")})`,
            transformOrigin: `${piece.origin[0]}% ${piece.origin[1]}%`,
            translate: `${piece.dx * c}px ${piece.dy * c}px`,
            rotate: `${piece.rotate * c}deg`,
            scale: `${1 + (piece.scale - 1) * c}`,
            filter:
              c > 0
                ? `drop-shadow(0 0 ${0.6 * c}px rgba(38,36,44,0.55))`
                : undefined,
          }}
        >
          <div style={{ position: "absolute", inset: 0 }}>{children}</div>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: creaseShading(piece, c),
              opacity: c,
            }}
          />
        </div>
      ))}
    </div>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Afacad";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const afacad = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface StoryBeat {
  slug: string;
  line: string;
}

export interface CrunchProps {
  setup?: StoryBeat;
  snag?: StoryBeat;
  resolution?: StoryBeat;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#3A1F1A",
    ink: "#FBF3EA",
    accent: "#F2B544",
    wall: "#241210",
    edge: "#4F2C25",
  },
  light: {
    bg: "#FBF6EE",
    ink: "#3B2414",
    accent: "#B07A00",
    wall: "#3B2414",
    edge: "#E9DCC8",
  },
} as const;

const DEFAULT_SETUP: StoryBeat = {
  slug: "Monday, 10:00 AM",
  line: "Maya had a launch on Friday.",
};
const DEFAULT_SNAG: StoryBeat = {
  slug: "Thursday, 11:40 PM",
  line: "Nine hours left, and still no video.",
};
const DEFAULT_RESOLUTION: StoryBeat = {
  slug: "Friday, 9:00 AM",
  line: "It shipped, with time to spare.",
};

const LINE_TRACK = -0.02;
const SLUG_TRACK = 0.08;
const LH = 1.04;
const SLUG_RATIO = 0.3;
const PX = 100;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SQUEEZE = Easing.bezier(0.55, 0, 0.75, 1);
const EASE_IN = Easing.bezier(0.5, 0, 0.75, 0);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function words(s: string) {
  return s.split(/\s+/).filter(Boolean);
}

function useWidths(strings: string[]) {
  const key = strings.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("crunch: measuring"));
  const released = useRef(false);
  const ref = useRef(strings);
  ref.current = strings;
  useEffect(() => {
    let live = true;
    Promise.all([
      afacad.waitUntilDone(),
      document.fonts.load(`500 ${PX}px "${afacad.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        if (ctx) ctx.font = `500 ${PX}px "${afacad.fontFamily}"`;
        for (const s of ref.current) {
          w[s] = ctx ? ctx.measureText(s).width / PX : s.length * 0.45;
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.w : null;
}

interface Laid {
  x: number[];
  line: number[];
  widths: number[];
  lines: number;
}

function greedy(ws: number[], space: number, max: number): Laid {
  const x: number[] = [];
  const line: number[] = [];
  const widths: number[] = [0];
  let l = 0;
  let cx = 0;
  ws.forEach((w, i) => {
    if (i > 0 && cx + space + w > max) {
      l++;
      widths.push(0);
      cx = 0;
    } else if (i > 0) {
      cx += space;
    }
    x.push(cx);
    line.push(l);
    cx += w;
    widths[l] = cx;
  });
  return { x, line, widths, lines: l + 1 };
}

function balanced(ws: number[], space: number, max: number): Laid {
  const base = greedy(ws, space, max);
  if (base.lines <= 1) return base;
  let lo = Math.max(...ws);
  let hi = max;
  for (let k = 0; k < 18; k++) {
    const mid = (lo + hi) / 2;
    if (greedy(ws, space, mid).lines <= base.lines) hi = mid;
    else lo = mid;
  }
  return greedy(ws, space, hi);
}

interface Block {
  lineWords: string[];
  slugWords: string[];
}

export function Crunch({
  setup = DEFAULT_SETUP,
  snag = DEFAULT_SNAG,
  resolution = DEFAULT_RESOLUTION,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CrunchProps) {
  const frame = useCurrentFrame();
  const t = frame * speed;
  const { width: W, height: H, durationInFrames: T } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const blocks: Block[] = [setup, snag, resolution].map((b) => ({
    lineWords: words(b.line),
    slugWords: words(b.slug.toUpperCase()),
  }));
  const strings = Array.from(
    new Set([" ", ...blocks.flatMap((b) => [...b.lineWords, ...b.slugWords])]),
  );
  const w = useWidths(strings);

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const unit = Math.min(W, H);
  const space = w[" "] ?? 0.22;
  const lineAdv = (s: string) =>
    (w[s] ?? 0) + LINE_TRACK * Array.from(s).length;
  const slugAdv = (s: string) =>
    (w[s] ?? 0) + SLUG_TRACK * Array.from(s).length;

  const wideCol = W * (portrait ? 0.86 : 0.8);
  const pad = unit * 0.05;

  let F = portrait ? W * 0.14 : H * 0.17;
  const fitWide = () =>
    blocks.every(
      (b) =>
        balanced(b.lineWords.map(lineAdv), space, wideCol / F).lines <=
        (portrait ? 4 : 2),
    );
  for (let k = 0; k < 60 && !fitWide(); k++) F *= 0.96;

  const room = H * (portrait ? 0.8 : 0.86);
  const snagStack = (size: number, col: number) => {
    const ss = Math.max(14, size * SLUG_RATIO);
    const a = balanced(
      blocks[1].slugWords.map((s) => slugAdv(s) * ss),
      space * ss,
      col,
    );
    const b = balanced(
      blocks[1].lineWords.map((s) => lineAdv(s) * size),
      space * size,
      col,
    );
    return a.lines * ss * 1.25 + ss * 0.9 + b.lines * size * LH;
  };
  for (let k = 0; k < 60 && snagStack(F, wideCol) > room; k++) F *= 0.96;
  const S = Math.max(14, F * SLUG_RATIO);
  const minWord =
    Math.max(
      ...blocks[1].lineWords.map((s) => lineAdv(s) * F),
      ...blocks[1].slugWords.map((s) => slugAdv(s) * S),
    ) * 1.02;
  let lo = minWord;
  let hiCol = Math.max(minWord, wideCol);
  for (let k = 0; k < 24; k++) {
    const mid = (lo + hiCol) / 2;
    if (snagStack(F, mid) <= room) hiCol = mid;
    else lo = mid;
  }
  const tightCol = hiCol;

  const k = Math.min(1.6, Math.max(0.75, T / 180));
  const at = (f: number) => f * k;
  const setupIn = at(4);
  const setupOut = at(44);
  const snagIn = at(52);
  const squeezeA = at(74);
  const squeezeB = at(122);
  const release = at(134);
  const resIn = at(140);

  const maxInset = Math.max(0, (W - tightCol) / 2 - pad);
  const squeeze = interpolate(t, [squeezeA, squeezeB], [0, 1], {
    ...CLAMP,
    easing: EASE_SQUEEZE,
  });
  const open = interpolate(t, [release, release + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const inset = maxInset * squeeze * (1 - open);
  const colAt = (tt: number) => {
    const sq = interpolate(tt, [squeezeA, squeezeB], [0, 1], {
      ...CLAMP,
      easing: EASE_SQUEEZE,
    });
    return Math.max(
      tightCol,
      Math.min(wideCol, W - 2 * maxInset * sq - 2 * pad),
    );
  };

  const centreY = H * (portrait ? 0.5 : 0.52);

  const layout = (b: Block, col: number) => {
    const sw = b.slugWords.map((s) => slugAdv(s) * S);
    const lw = b.lineWords.map((s) => lineAdv(s) * F);
    const a = balanced(sw, space * S, col);
    const l = balanced(lw, space * F, col);
    const slugLH = S * 1.25;
    const gap = S * 0.9;
    const total = a.lines * slugLH + gap + l.lines * F * LH;
    const top = centreY - total / 2;
    const pts: { x: number; y: number }[] = [];
    b.slugWords.forEach((_, i) => {
      pts.push({
        x: W / 2 - a.widths[a.line[i]] / 2 + a.x[i],
        y: top + a.line[i] * slugLH,
      });
    });
    b.lineWords.forEach((_, i) => {
      pts.push({
        x: W / 2 - l.widths[l.line[i]] / 2 + l.x[i],
        y: top + a.lines * slugLH + gap + l.line[i] * F * LH,
      });
    });
    return pts;
  };

  const wideFor = (b: Block) => layout(b, wideCol);

  const snagPts = (() => {
    const start = Math.floor(squeezeA);
    const end = Math.min(Math.floor(t), Math.floor(release));
    let pos = layout(blocks[1], colAt(start));
    for (let f = start + 1; f <= end; f++) {
      const target = layout(blocks[1], colAt(f));
      pos = pos.map((p, i) => ({
        x: p.x + (target[i].x - p.x) * 0.75,
        y: p.y + (target[i].y - p.y) * 0.75,
      }));
    }
    return pos;
  })();

  const renderBlock = (
    b: Block,
    pts: { x: number; y: number }[],
    key: string,
    inAt: number,
    outAt: number | null,
    lineColor: string,
    slugColor: string,
  ) => {
    const n = b.slugWords.length;
    const all = [...b.slugWords, ...b.lineWords];
    return all.map((word, i) => {
      const isSlug = i < n;
      const s0 = inAt + i * Math.min(2.2, 16 / all.length);
      const e = interpolate(t, [s0, s0 + 16], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      let o = e;
      let dy = (1 - e) * (isSlug ? S : F) * 0.45;
      if (outAt !== null) {
        const x0 = outAt + i * 0.8;
        const x = interpolate(t, [x0, x0 + 9], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        o *= 1 - x;
        dy -= x * F * 0.35;
      }
      if (o <= 0.001) return null;
      const size = isSlug ? S : F;
      return (
        <div
          key={`${key}${i}`}
          style={{
            position: "absolute",
            left: pts[i].x,
            top: pts[i].y,
            fontSize: size,
            lineHeight: `${isSlug ? size * 1.25 : size * LH}px`,
            whiteSpace: "pre",
            fontWeight: isSlug ? 500 : 400,
            letterSpacing: `${isSlug ? SLUG_TRACK : LINE_TRACK}em`,
            color: isSlug ? slugColor : lineColor,
            opacity: o,
            transform: `translateY(${dy.toFixed(2)}px)`,
          }}
        >
          {word}
        </div>
      );
    });
  };

  const wallW = inset + pad * 0.35 * squeeze * (1 - open);
  const wallStyle = (side: "left" | "right") => ({
    position: "absolute" as const,
    top: 0,
    bottom: 0,
    [side]: 0,
    width: Math.max(0, wallW),
    background: c.wall,
    boxShadow:
      wallW > 1
        ? `inset ${side === "left" ? -1 : 1}px 0 0 ${c.edge}`
        : undefined,
  });

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily: afacad.fontFamily,
      }}
    >
      {renderBlock(
        blocks[0],
        wideFor(blocks[0]),
        "a",
        setupIn,
        setupOut,
        c.ink,
        hi,
      )}
      {renderBlock(blocks[1], snagPts, "b", snagIn, release - 4, c.ink, hi)}
      <div style={wallStyle("left")} />
      <div style={wallStyle("right")} />
      {renderBlock(blocks[2], wideFor(blocks[2]), "c", resIn, null, hi, hi)}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { useEffect, useMemo, useRef, useState } from "react";
import {
