const DEFAULT_SCENES: CueWordScene[] = [
  { text: "This line slides left.", cue: "slides left", cut: "slide" },
  { text: "The next one drops in.", cue: "drops in", cut: "drop" },
  { text: "And this one cuts.", cue: "cuts", cut: "cut" },
  { text: "Every move is one line of code.", cue: "one line" },
];

function useEmWidths(texts: string[]) {
  const key = texts.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    em: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("cue-word: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      syne.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${syne.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        const em: Record<string, number> = {};
        if (ctx) {
          ctx.font = `${WGHT} ${FONT_PX}px "${syne.fontFamily}"`;
          for (const s of key.split("\u0001")) {
            em[s] =
              ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
          }
        }
        setState({ key, em });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.em : null;
}

const bare = (w: string) =>
  w.toLowerCase().replace(/^[“"'‘(]+|[.,!?;:…”"'’)—–]+$/g, "");

function cueMask(words: string[], cue: string | undefined) {
  const flags = words.map(() => false);
  const target = (cue ?? words[words.length - 1] ?? "")
    .split(" ")
    .filter(Boolean)
    .map(bare);
  if (target.length === 0) return flags;
  for (let i = words.length - target.length; i >= 0; i--) {
    if (target.every((tw, j) => bare(words[i + j]) === tw)) {
      for (let j = 0; j < target.length; j++) flags[i + j] = true;
      return flags;
    }
  }
  flags[words.length - 1] = true;
  return flags;
}

function lineCount(
  words: string[],
  em: Record<string, number>,
  F: number,
  maxW: number,
) {
  let lines = 1;
  let cur = "";
  for (const w of words) {
    const next = cur ? `${cur} ${w}` : w;
    if (cur && em[next] * F > maxW) {
      lines++;
      cur = w;
    } else {
      cur = next;
    }
  }
  return lines;
}

export function CueWord({
  scenes = DEFAULT_SCENES,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CueWordProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const transparent = background === "transparent";
  const base = transparent ? "transparent" : (background ?? c.bg);

  const list = scenes.length > 0 ? scenes : [{ text: "" }];
  const sceneWords = list.map((s) => s.text.split(" ").filter(Boolean));
  const texts: string[] = [];
  for (const ws of sceneWords) {
    for (let i = 0; i < ws.length; i++) {
      texts.push(ws[i]);
      for (let j = i + 1; j < ws.length; j++) {
        texts.push(ws.slice(i, j + 1).join(" "));
      }
    }
  }
  const em = useEmWidths(texts);

  if (!em) {
    return <div style={{ position: "absolute", inset: 0, background: base }} />;
  }

  const portrait = H > W * 1.1;
  const boxW = W * (portrait ? 0.86 : 0.84);
  const maxLines = portrait ? 5 : 3;
  const capF = portrait ? W * 0.19 : H * 0.215;

  const sizes = sceneWords.map((ws) => {
    const widest = Math.max(...ws.map((w) => em[w] ?? 0), 0.01);
    let lo = 4;
    let top = Math.min(capF, boxW / widest);
    for (let i = 0; i < 28; i++) {
      const mid = (lo + top) / 2;
      if (lineCount(ws, em, mid, boxW) <= maxLines) lo = mid;
      else top = mid;
    }
    return lo;
  });

  const n = list.length;
  const settleOf = (k: number) =>
    k === 0
      ? RISE +
        Math.max(0, sceneWords[k].length - 1) * STAGGER +
        CUE_GAP +
        CUE_LAND
      : CUE_GAP + CUE_LAND;
  const moveOf = (k: number) => (list[k].cut === "cut" ? 0 : MOVE);
  let fixed = FINAL_HOLD;
  for (let k = 0; k < n; k++)
    fixed += settleOf(k) + (k < n - 1 ? moveOf(k) : 0);
  const read = Math.max(12, Math.floor((durationInFrames - fixed) / n));

  const arrive: number[] = [];
  const leave: number[] = [];
  let cursor = 0;
  for (let k = 0; k < n; k++) {
    arrive.push(cursor);
    const end = cursor + settleOf(k) + read;
    leave.push(end);
    cursor = end + (k < n - 1 ? moveOf(k) : 0);
  }

  const offsetOf = (k: number) => {
    let x = 0;
    let y = 0;
    if (k > 0) {
      const cut = list[k - 1].cut ?? "slide";
      const span = moveOf(k - 1);
      const p =
        span === 0
          ? t >= leave[k - 1]
            ? 1
            : 0
          : interpolate(t, [leave[k - 1], leave[k - 1] + span], [0, 1], {
              ...CLAMP,
              easing: EASE_IO,
            });
      if (cut === "slide") x += (1 - p) * W;
      if (cut === "drop") y -= (1 - p) * H;
      if (cut === "lift") y += (1 - p) * H;
      if (cut === "cut" && p < 1) y += H * 2;
    }
    if (k < n - 1) {
      const cut = list[k].cut ?? "slide";
      const span = moveOf(k);
      const p =
        span === 0
          ? t >= leave[k]
            ? 1
            : 0
          : interpolate(t, [leave[k], leave[k] + span], [0, 1], {
              ...CLAMP,
              easing: EASE_IO,
            });
      if (cut === "slide") x -= p * W;
      if (cut === "drop") y += p * H;
      if (cut === "lift") y -= p * H;
      if (cut === "cut" && p >= 1) y += H * 2;
    }
    return { x, y };
  };

  const layers: React.ReactNode[] = [];
  for (let k = 0; k < n; k++) {
    const startVis = k === 0 ? 0 : leave[k - 1];
    const endVis = k < n - 1 ? leave[k] + moveOf(k) : Number.POSITIVE_INFINITY;
    if (t < startVis || t > endVis) continue;
    const { x, y } = offsetOf(k);
    if (Math.abs(x) >= W || Math.abs(y) >= H) continue;

    const onAccent = k % 2 === 1;
    const field = onAccent ? hi : base;
    const inkCol = onAccent ? c.onAccent : c.ink;
    const cueCol = onAccent ? c.cueOnAccent : hi;
    const F = sizes[k];
    const ws = sceneWords[k];
    const flags = cueMask(ws, list[k].cue);
    const t0 = arrive[k];
    const restTime = (i: number) => (k === 0 ? t0 + i * STAGGER : -1e9);
    const cueAt =
      k === 0
        ? t0 + (ws.length - 1) * STAGGER + RISE + CUE_GAP - 8
        : t0 + CUE_GAP - 5;

    const spans = ws.map((w, i) => {
      const isCue = flags[i];
      const startAt = isCue ? cueAt : restTime(i);
      const p = interpolate(
        t,
        [startAt, startAt + (isCue ? CUE_LAND : RISE)],
        [0, 1],
        {
          ...CLAMP,
          easing: EASE_OUT,
        },
      );
      const style: React.CSSProperties = {
        display: "inline-block",
        overflow: "hidden",
        verticalAlign: "top",
        paddingBottom: F * 0.14,
        marginBottom: -F * 0.14,
      };
      return (
        <span key={`w${i}`}>
          <span style={style}>
            <span
              style={{
                display: "inline-block",
                color: isCue ? cueCol : inkCol,
                transform: `translateY(${((1 - p) * F * 1.15).toFixed(2)}px)`,
              }}
            >
              {w}
            </span>
          </span>
          {i < ws.length - 1 ? " " : ""}
        </span>
      );
    });

    layers.push(
      <div
        key={`s${k}`}
        style={{
          position: "absolute",
          inset: 0,
          background: field,
          transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: boxW,
            textAlign: "center",
            textWrap: "balance",
            fontFamily: syne.fontFamily,
            fontWeight: WGHT,
            fontSize: F,
            lineHeight: LH,
            letterSpacing: `${TRACK}em`,
            marginTop: -F * 0.06,
          }}
        >
          {spans}
        </div>
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: base, overflow: "hidden" }}>
      {layers}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { useLayoutEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const face = loadFont("normal", { weights: ["400"], subsets: ["latin"] });
const mono = loadMono("normal", { weights: ["500"], subsets: ["latin"] });

export interface CursorFrameProps {
  /** The headline set inside the text frame. */
  title?: string;
  /** Selection colour: frame, handles and the size badge. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const THEMES = {
  light: { bg: "#FAFAF9", fg: "#0E0E0D", handle: "#FFFFFF" },
  dark: { bg: "#0A0A0A", fg: "#F2F2F0", handle: "#FFFFFF" },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_DRAG = Easing.bezier(0.45, 0, 0.2, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Beats, in frames at 30fps (before `speed`).
const ENTER = 0;
const ENTER_LEN = 24;
const PRESS = 25;
const DRAG = 28;
const DRAG_END = 70;
const GRAB = 80;
const RESIZE = 86;
const RESIZE_END = 134;
const RELEASE = 140;
const CLEAR = 150;
const RECENTRE = 148;
const RECENTRE_LEN = 36;
const WORD_IN = 12;
const LINE_HEIGHT = 1.1;
const WRAP_IN = 11;
/** How far a wrapping word drifts out and slides in, in em. */
const WRAP_SLIDE = 0.3;

interface Metrics {
  words: number[];
  space: number;
}

interface Placed {
  x: number;
  y: number;
}

/** Greedy line breaking at a given box width. */
function breakLines(m: Metrics, boxW: number, lineH: number) {
  const pos: Placed[] = [];
  let x = 0;
  let line = 0;
  let maxW = 0;
  m.words.forEach((w, i) => {
    if (i > 0 && x + m.space + w > boxW + 0.5) {
      line++;
      x = 0;
    } else if (i > 0) {
      x += m.space;
    }
    pos.push({ x, y: line * lineH });
    x += w;
    maxW = Math.max(maxW, x);
  });
  return { pos, lines: line + 1, maxW };
}

/** The narrowest two-line box: the most balanced split of the words. */
function twoLineWidth(m: Metrics) {
  let best = Number.POSITIVE_INFINITY;
  for (let k = 1; k < m.words.length; k++) {
    const a = m.words.slice(0, k);
    const b = m.words.slice(k);
    const wa = a.reduce((s, w) => s + w, 0) + (a.length - 1) * m.space;
    const wb = b.reduce((s, w) => s + w, 0) + (b.length - 1) * m.space;
    best = Math.min(best, Math.max(wa, wb));
  }
  return best;
}

function ArrowCursor({ size }: { size: number }) {
  return (
    <svg
      viewBox="-2 -2 20 30"
      width={(size * 20) / 30}
      height={size}
      style={{ display: "block", overflow: "visible" }}
      aria-hidden
    >
      <path
        d="M0 0 L0 21.6 L5 16.9 L8.5 25.1 L12 23.6 L8.6 15.5 L15.4 15.5 Z"
        fill="#000"
        stroke="#fff"
        strokeWidth={1.7}
        strokeLinejoin="round"
        paintOrder="stroke"
      />
    </svg>
  );
}

function ResizeCursor({ size }: { size: number }) {
  return (
    <svg
      viewBox="-15 -15 30 30"
      width={size}
      height={size}
      style={{ display: "block", overflow: "visible" }}
      aria-hidden
    >
      <path
        d="M-10.5 0 L-4.6 -5.9 L-4.6 -2.1 L4.6 -2.1 L4.6 -5.9 L10.5 0 L4.6 5.9 L4.6 2.1 L-4.6 2.1 L-4.6 5.9 Z"
        transform="rotate(45)"
        fill="#000"
        stroke="#fff"
        strokeWidth={1.7}
        strokeLinejoin="round"
        paintOrder="stroke"
      />
    </svg>
  );
}

export function CursorFrame({
  title = "Launch videos, in code.",
  accent = "#3B5BFD",
  theme = "light",
  speed = 1,
}: CursorFrameProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const t = THEMES[theme];
  const words = title.split(/\s+/).filter(Boolean);
  const u = width / 1280;

  const fontSize = Math.round(width * 0.068);
  const lineH = fontSize * LINE_HEIGHT;

  const wordRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const spaceRef = useRef<HTMLSpanElement>(null);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("cursor-frame: measuring"));
  const released = useRef(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: re-measure when the copy or size changes
  useLayoutEffect(() => {
    let live = true;
    face
      .waitUntilDone()
      .catch(() => undefined)
      .then(() => document.fonts.ready)
      .then(() => {
        if (!live) return;
        const space = spaceRef.current;
        if (space) {
          const next: Metrics = {
            words: wordRefs.current
              .slice(0, words.length)
              .map((el) => el?.offsetWidth ?? 0),
            space: space.offsetWidth,
          };
          setMetrics((prev) =>
            prev &&
            prev.space === next.space &&
            prev.words.join() === next.words.join()
              ? prev
              : next,
          );
        }
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [title, fontSize, handle]);

  const m = metrics ?? { words: words.map(() => 0), space: 0 };
  const wide = breakLines(m, Number.POSITIVE_INFINITY, lineH);
  const W1 = wide.maxW + fontSize * 0.04;
  const W2 = twoLineWidth(m) + fontSize * 0.04;
  const H1 = lineH;
  const x0 = width / 2 - W1 / 2;
  const y0 = height / 2 - H1 / 2;

  // Box width the hand asks for at frame f (the corner follows the cursor).
  const dragX = (f: number) =>
    interpolate(f, [DRAG, DRAG_END], [0, 1], { ...clamp, easing: EASE_DRAG });
  const dragY = (f: number) =>
    interpolate(f, [DRAG, DRAG + 14], [0, 1], { ...clamp, easing: EASE_OUT });
  const boxW = (f: number) =>
    f < RESIZE
      ? W1 * dragX(f)
      : interpolate(f, [RESIZE, RESIZE_END], [W1, W2], {
          ...clamp,
          easing: EASE_IN_OUT,
        });

  // Reflow: a word that keeps its line slides to its new slot on a critically
  // damped spring. A word that wraps leaves a fading ghost drifting on at the
  // old line end and slides in fresh at the start of the next, so no two
  // words ever cross.
  const settleAt = (f: number) => {
    const start = breakLines(m, W1, lineH);
    const pos = start.pos.map((p) => ({
      ...p,
      vx: 0,
      wrap: -1e4,
      fromX: 0,
      fromY: 0,
    }));
    let h = lineH * start.lines;
    let vh = 0;
    const w = 0.6;
    const wh = 0.6;
    const end = Math.min(f, RESIZE_END + 60);
    for (let s = RESIZE; s <= end; s++) {
      const target = breakLines(m, boxW(s), lineH);
      pos.forEach((p, i) => {
        const tp = target.pos[i] ?? p;
        if (Math.abs(tp.y - p.y) > 0.5) {
          p.wrap = s;
          p.fromX = p.x;
          p.fromY = p.y;
          p.x = tp.x;
          p.y = tp.y;
          p.vx = 0;
        }
        p.vx += (tp.x - p.x) * w * w - 2 * w * p.vx;
        p.x += p.vx;
      });
      vh += (target.lines * lineH - h) * wh * wh - 2 * wh * vh;
      h += vh;
    }
    return { pos, h };
  };
  const fA = Math.floor(frame);
  const a = settleAt(fA);
  const b = settleAt(fA + 1);
  const fr = frame - fA;
  const wordPos = a.pos.map((p, i) => {
    const q = b.pos[i];
    return q && q.wrap === p.wrap ? { ...p, x: p.x + (q.x - p.x) * fr } : p;
  });
  const settledH = a.h + (b.h - a.h) * fr;

  const fw = boxW(frame);
  const fh = frame < RESIZE ? H1 * dragY(frame) : settledH;

  // When does the growing frame first pass each word's centre?
  const wordIn = wide.pos.map((p, i) => {
    const centre = p.x + (m.words[i] ?? 0) * 0.5;
    for (let f = DRAG; f <= DRAG_END; f++) if (boxW(f) >= centre) return f - 4;
    return DRAG_END;
  });

  // Cursor: glides in, presses, drags the corner out, swaps to the resize
  // arrows, drags the corner in, lets go and drifts off.
  const enter = interpolate(frame, [ENTER, ENTER + ENTER_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const leave = interpolate(frame, [RELEASE + 6, RELEASE + 34], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  let cx = x0;
  let cy = y0;
  if (frame < DRAG) {
    cx = interpolate(enter, [0, 1], [x0 + width * 0.16, x0]);
    cy = interpolate(enter, [0, 1], [y0 + height * 0.2, y0]);
  } else {
    cx = x0 + fw;
    cy = y0 + fh;
  }
  cx += leave * width * 0.1;
  cy += leave * height * 0.12;
  const cursorOpacity =
    interpolate(frame, [ENTER, ENTER + 8], [0, 1], clamp) *
    interpolate(frame, [RELEASE + 14, RELEASE + 34], [1, 0], clamp);
  const press =
    interpolate(frame, [PRESS, PRESS + 3], [0, 1], clamp) -
    interpolate(frame, [DRAG_END, DRAG_END + 3], [0, 1], clamp) +
    interpolate(frame, [RESIZE - 3, RESIZE], [0, 1], clamp) -
    interpolate(frame, [RESIZE_END + 4, RESIZE_END + 7], [0, 1], clamp);
  const resizeIcon =
    interpolate(frame, [GRAB, GRAB + 3], [0, 1], clamp) -
    interpolate(frame, [RELEASE, RELEASE + 3], [0, 1], clamp);
  const cursorSize = 30 * u * (1 - press * 0.06);

  // Selection chrome: appears with the drag, clears once the text is set.
  const chromeIn = interpolate(frame, [DRAG, DRAG + 4], [0, 1], clamp);
  const clear = interpolate(frame, [CLEAR, CLEAR + 14], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });
  const chrome = chromeIn * (1 - clear);
  const handlesIn = interpolate(frame, [DRAG + 2, DRAG + 12], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });
  const handleScale = (0.5 + 0.5 * handlesIn) * (1 - clear * 0.5);

  // Once the frame is gone, the text block glides to the optical centre.
  const re = interpolate(frame, [RECENTRE, RECENTRE + RECENTRE_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const finalH = breakLines(m, W2, lineH).lines * lineH;
  const shiftX = re * (W1 - W2) * 0.5;
  const shiftY = re * (H1 - finalH) * 0.5;

  const stroke = Math.max(1, 1.5 * u);
  const hs = 9 * u;
  const corners = [
    [0, 0],
    [fw, 0],
    [0, fh],
    [fw, fh],
  ];
  const badgeSize = 13 * u;

  return (
    <AbsoluteFill style={{ background: t.bg, overflow: "hidden" }}>
      {/* measuring row: never shown */}
      <div
        style={{
          position: "absolute",
          visibility: "hidden",
          whiteSpace: "pre",
          fontFamily: face.fontFamily,
          fontSize,
          fontWeight: 400,
          letterSpacing: "-0.035em",
        }}
      >
        {words.map((w, i) => (
          <span
            key={i}
            ref={(el) => {
              wordRefs.current[i] = el;
            }}
            style={{ display: "inline-block" }}
          >
            {w}
          </span>
        ))}
        <span ref={spaceRef} style={{ display: "inline-block" }}>
          {" "}
        </span>
      </div>

      <div
        style={{
          position: "absolute",
          left: x0 + shiftX,
          top: y0 + shiftY,
          width: 0,
          height: 0,
          opacity: metrics ? 1 : 0,
        }}
      >
        {words.map((w, i) => {
          const p = interpolate(
            frame,
            [wordIn[i] ?? DRAG, (wordIn[i] ?? DRAG) + WORD_IN],
            [0, 1],
            { ...clamp, easing: EASE_OUT },
          );
          const pos = wordPos[i] ?? {
            x: 0,
            y: 0,
            wrap: -1e4,
            fromX: 0,
            fromY: 0,
          };
          const wrapP = interpolate(
            frame,
            [pos.wrap + 4, pos.wrap + 4 + WRAP_IN],
            [0, 1],
            {
              ...clamp,
              easing: EASE_OUT,
            },
          );
          const ghostP = interpolate(
            frame,
            [pos.wrap, pos.wrap + WRAP_IN],
            [0, 1],
            {
              ...clamp,
              easing: EASE_OUT,
            },
          );
          const style = {
            position: "absolute",
            whiteSpace: "pre",
            fontFamily: face.fontFamily,
            fontSize,
            fontWeight: 400,
            letterSpacing: "-0.035em",
            lineHeight: LINE_HEIGHT,
            color: t.fg,
          } as const;
          const inP = p * wrapP;
          return (
            <span key={i}>
              {ghostP < 1 ? (
                <span
                  style={{
                    ...style,
                    left: pos.fromX + ghostP * fontSize * WRAP_SLIDE,
                    top: pos.fromY,
                    opacity: 1 - ghostP,
                    filter: `blur(${ghostP * 6}px)`,
                  }}
                >
                  {w}
                </span>
              ) : null}
              <span
                style={{
                  ...style,
                  left: pos.x,
                  top: pos.y,
                  opacity: inP,
                  filter: inP < 1 ? `blur(${(1 - inP) * 8}px)` : undefined,
                  transform: `translateY(${(1 - p) * fontSize * 0.12 - (1 - wrapP) * fontSize * 0.22}px)`,
                }}
              >
                {w}
              </span>
            </span>
          );
        })}

        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: fw,
            height: fh,
            boxShadow: `inset 0 0 0 ${stroke}px ${accent}`,
            opacity: chrome,
          }}
        />
        {corners.map(([hx, hy]) => (
          <div
            key={`${hx === 0 ? "l" : "r"}${hy === 0 ? "t" : "b"}`}
            style={{
              position: "absolute",
              left: hx - hs / 2,
              top: hy - hs / 2,
              width: hs,
              height: hs,
              boxSizing: "border-box",
              background: t.handle,
              border: `${stroke}px solid ${accent}`,
              borderRadius: 1.5 * u,
              opacity: chrome * handlesIn,
              transform: `scale(${handleScale})`,
            }}
          />
        ))}
        <div
          style={{
            position: "absolute",
            left: fw / 2,
            top: fh + 10 * u,
            transform: "translateX(-50%)",
            padding: `${3 * u}px ${6 * u}px`,
            borderRadius: 4 * u,
            background: accent,
            color: "#FFFFFF",
            fontFamily: mono.fontFamily,
            fontWeight: 500,
            fontSize: badgeSize,
            lineHeight: 1.2,
            letterSpacing: "0.01em",
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "pre",
            opacity: chrome * handlesIn,
          }}
        >
          {`${Math.round(fw)} × ${Math.round(fh)}`}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: cx + shiftX,
          top: cy + shiftY,
          opacity: metrics ? cursorOpacity : 0,
          filter: "drop-shadow(0 1px 1.5px rgba(0,0,0,0.28))",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            opacity: 1 - resizeIcon,
          }}
        >
          <ArrowCursor size={cursorSize} />
        </div>
        <div
          style={{
            position: "absolute",
            left: -cursorSize * 0.5,
            top: -cursorSize * 0.5,
            opacity: resizeIcon,
          }}
        >
          <ResizeCursor size={cursorSize} />
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import type { ReactNode } from "react";
import { Easing, useCurrentFrame, useVideoConfig } from "remotion";

export interface CursorGravityProps {
  /** Custom content in a 300 × 88 reference-pixel slot. */
  children?: ReactNode;
  label?: string;
  /** Strength of the elastic neck and recoil, 0–1.5. */
  tension?: number;
  cursorColor?: string;
  color?: string;
  textColor?: string;
  backgroundColor?: string;
  speed?: number;
  className?: string;
}

export const cursorGravityLength = 151;
const DURATION = 180;
const finite = (value: number, fallback: number) =>
  Number.isFinite(value) ? value : fallback;
const clamp = (value: number) => Math.max(0, Math.min(1, value));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const progress = (frame: number, start: number, end: number) =>
  clamp((frame - start) / (end - start));
const ease = Easing.bezier(0.65, 0, 0.35, 1);
const pullEase = Easing.bezier(0.12, 0.8, 0.22, 1);

/** Complete transition plus a one-second hold, in frames at 30 fps. */
export function getCursorGravityDuration({
  speed = 1,
}: Pick<CursorGravityProps, "speed"> = {}) {
  const rate = Math.max(0, finite(speed, 1));
  return rate === 0 ? 1 : Math.max(1, Math.ceil(DURATION / rate));
}

/** A pull advances sharply, pauses under load, then recoils before the next tug. */
function pullDistance(t: number, strength: number) {
  const keys = [
    [48, 0],
    [59, 116],
    [64, 116],
    [70, 116 - 30 * strength],
    [83, 292],
    [87, 292],
    [94, 292 - 42 * strength],
    [112, 772],
  ];
  if (t <= keys[0][0]) return 0;
  for (let i = 1; i < keys.length; i++) {
    const [start, a] = keys[i - 1];
    const [end, b] = keys[i];
    if (t <= end)
      return mix(a, b, (b > a ? pullEase : ease)(progress(t, start, end)));
  }
  return 772;
}

/** Pure, resolution-aware pose. The right edge is the real composition boundary. */
export function getCursorGravityState(
  frame: number,
  {
    width = 1280,
    height = 720,
    tension = 1,
  }: { width?: number; height?: number; tension?: number } = {},
) {
  const w = Math.max(1, finite(width, 1280));
  const h = Math.max(1, finite(height, 720));
  const unit = Math.min(w / 1280, h / 720);
  const t = Math.max(0, finite(frame, 0));
  const strength = Math.max(0, Math.min(1.5, finite(tension, 1)));
  const centerY = h * 0.5;
  const finalLeft = w / 2 - 150 * unit;
  const finalRight = w / 2 + 150 * unit;
  const edgeTip = w - 24 * unit;
  const distance = pullDistance(t, strength) / 772;
  const extraction = distance * (edgeTip - (finalLeft - 14 * unit));
  // The back of the button resists the first two tugs beyond the frame edge.
  const releaseTime = progress(t, 94, 132);
  // Closed-form damped spring stays continuous at fractional frames too.
  const springRelease =
    1 -
    Math.exp(-7 * releaseTime) *
      (Math.cos(10 * releaseTime) + 0.7 * Math.sin(10 * releaseTime));
  const release = mix(springRelease, 1, ease(progress(t, 122, 132)));
  const front = mix(w + 12 * unit, finalLeft, distance);
  const right = mix(w + 312 * unit - distance * 70 * unit, finalRight, release);
  const buttonWidth = Math.max(220 * unit, right - front);
  const strain = clamp((buttonWidth / (300 * unit) - 1) / 1.3) * strength;
  const wobble =
    t < 112
      ? 0
      : Math.sin((t - 112) * 0.48) *
        Math.exp(-(t - 112) * 0.14) *
        5 *
        unit *
        strength *
        (1 - progress(t, 132, 140));
  const y = centerY + wobble;
  const entry = ease(progress(t, 10, 39));
  const approach = ease(progress(t, 39, 48));
  const leave = ease(progress(t, 127, 151));
  const holdTip = mix(w * 0.28, edgeTip - 80 * unit, entry);
  const pullTip = edgeTip - extraction;
  const cursorX =
    t < 48 ? mix(holdTip, edgeTip, approach) : mix(pullTip, w * 0.25, leave);
  const cursorY =
    t < 39
      ? mix(h + 110 * unit, centerY + 70 * unit, entry)
      : t < 48
        ? mix(centerY + 70 * unit, centerY, approach)
        : mix(centerY, h + 110 * unit, leave);
  // Triangle points toward the edge while pulling; turns toward its exit afterward.
  const cursorAngle = t < 48 ? mix(-32, 0, approach) : mix(0, 115, leave);
  const effortPulse = (
    start: number,
    peak: number,
    hold: number,
    end: number,
  ) => ease(progress(t, start, peak)) * (1 - ease(progress(t, hold, end)));
  const cursorEffort =
    strength *
    (0.8 * effortPulse(48, 58, 64, 70) +
      effortPulse(70, 81, 87, 94) +
      1.15 * effortPulse(94, 100, 104, 118));
  return {
    frame: t,
    unit,
    front,
    right: front + buttonWidth,
    buttonWidth,
    centerY: y,
    strain,
    neckHeight: 88 * unit * (1 - 0.58 * strain),
    bodyHeight: 88 * unit * (1 - 0.17 * strain),
    cursorX,
    cursorY,
    cursorAngle,
    cursorEffort,
    attached: t >= 48 && t <= 121,
    tetherOpacity: progress(t, 46, 49) * (1 - progress(t, 115, 122)),
  };
}

/** The tip stays fixed; the rear bows backward as each tug builds effort. */
export function getGravityCursorPath(effort: number) {
  const load = Math.max(0, Math.min(1.725, finite(effort, 0)));
  const shoulder = -62 - 30 * load;
  const rear = -70 - 40 * load;
  const halfHeight = 26 - 4 * load;
  return `M -5 -4 Q 3 0 -5 4
    C -24 ${11.333 - load * 3} ${shoulder + 19} ${halfHeight - 7.333} ${shoulder} ${halfHeight}
    Q ${rear} ${halfHeight + 4} ${rear} ${halfHeight - 6}
    C ${rear} 4 ${rear - 18 * load} 8 ${rear - 18 * load} 0
    C ${rear - 18 * load} -8 ${rear} -4 ${rear} ${-halfHeight + 6}
    Q ${rear} ${-halfHeight - 4} ${shoulder} ${-halfHeight}
    C ${shoulder + 19} ${-halfHeight + 7.333} -24 ${-11.333 + load * 3} -5 -4 Z`;
}

/** Rounded rectangle with a narrow leading edge: the pull deforms the surface. */
export function getGravityButtonPath(
  state: ReturnType<typeof getCursorGravityState>,
) {
  const { buttonWidth: w, neckHeight, bodyHeight, unit } = state;
  const a = neckHeight / 2;
  const b = bodyHeight / 2;
  const r = Math.min(25 * unit, a * 0.9);
  const backRadius = 25 * unit;
  return `M ${r} ${-a}
    C ${w * 0.35} ${-a} ${w * 0.35} ${-b} ${w - backRadius} ${-b}
    Q ${w} ${-b} ${w} ${-b + backRadius}
    L ${w} ${b - backRadius} Q ${w} ${b} ${w - backRadius} ${b}
    C ${w * 0.35} ${b} ${w * 0.35} ${a} ${r} ${a}
    Q 0 ${a} 0 ${a - r} L 0 ${-a + r} Q 0 ${-a} ${r} ${-a} Z`;
}

export function CursorGravity({
  children,
  label = "Create something",
  tension = 1,
  cursorColor = "#fffaf0",
  color = "#fffaf0",
  textColor = "#32153c",
  backgroundColor = "#a800b7",
  speed = 1,
  className,
}: CursorGravityProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = frame * (30 / fps) * Math.max(0, finite(speed, 1));
  const state = getCursorGravityState(t, { width, height, tension });
  const { unit } = state;
  // Content travels with the material, without stretching the lettering.
  const contentUnit = unit * Math.min(1, state.buttonWidth / (300 * unit));
  const contentX = state.front + state.buttonWidth - 150 * contentUnit;
  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
        fontFamily: "Arial, sans-serif",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        aria-hidden="true"
        style={{ position: "absolute", inset: 0 }}
      >
        <path
          d={getGravityButtonPath(state)}
          transform={`translate(${state.front} ${state.centerY})`}
          fill={color}
        />
        <path
          d={`M ${state.cursorX + 2 * unit} ${state.cursorY} Q ${mix(state.cursorX, state.front, 0.5)} ${state.centerY} ${state.front + 2 * unit} ${state.centerY}`}
          fill="none"
          stroke={cursorColor}
          strokeWidth={2 * unit}
          strokeLinecap="round"
          opacity={state.tetherOpacity}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: 300,
          height: 88,
          translate: `${contentX - 150 * contentUnit}px ${state.centerY - 44 * contentUnit}px`,
          scale: contentUnit,
          transformOrigin: "top left",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 20,
          color: textColor,
          fontWeight: 600,
          fontSize: 23,
        }}
      >
        {children ?? (
          <>
            <span
              style={{
                maxWidth: 220,
                overflow: "hidden",
                whiteSpace: "nowrap",
                textOverflow: "ellipsis",
              }}
            >
              {label}
            </span>
            <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true">
              <path
                d="M5 12H19M13 6L19 12L13 18"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </>
        )}
      </div>
      <svg
        width={190 * unit}
        height={70 * unit}
        viewBox="-180 -35 190 70"
        role="img"
        aria-label="Rounded triangular cursor"
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          translate: `${state.cursorX - 180 * unit}px ${state.cursorY - 35 * unit}px`,
          transform: `rotate(${state.cursorAngle}deg)`,
          transformOrigin: `${180 * unit}px ${35 * unit}px`,
        }}
      >
        <path d={getGravityCursorPath(state.cursorEffort)} fill={cursorColor} />
      </svg>
    </div>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Syne";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const syne = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CutOffProps {
  line?: string;
  reply?: string;
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0A0A0A",
    ink: "#FFFFFF",
    dim: "rgba(255,255,255,0.94)",
    replyBg: "#FFFFFF",
    replyInk: "#0A0A0A",
    accent: "#FF3EA5",
  },
  light: {
    bg: "#FFFFFF",
    ink: "#000000",
    dim: "rgba(0,0,0,0.92)",
    replyBg: "#000000",
    replyInk: "#FFFFFF",
    accent: "#D61F7F",
  },
} as const;

const TRACK_A = -0.02;
const TRACK_B = -0.04;
const FONT_PX = 200;
const LH_A = 1.18;
const LH_B = 1.0;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_HIT = Easing.bezier(0.2, 1.35, 0.4, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const LEAD_IN = 6;
const WORD_IN = 9;
const LETTER = 2;
const DASH_HOLD = 4;
const HIT = 8;
const HIT_GAP = 9;
const MIN_HOLD = 40;

function useEm(textsA: string[], textsB: string[]) {
  const key = `${textsA.join("\u0001")}\u0002${textsB.join("\u0001")}`;
  const [state, setState] = useState<{
    key: string;
    a: Record<string, number>;
    b: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("cut-off: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      syne.waitUntilDone(),
      document.fonts.load(`400 100px "${syne.fontFamily}"`),
      document.fonts.load(`500 100px "${syne.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [ka, kb] = key.split("\u0002");
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        const a: Record<string, number> = {};
        const b: Record<string, number> = {};
        if (ctx) {
          ctx.font = `400 ${FONT_PX}px "${syne.fontFamily}"`;
          for (const s of ka.split("\u0001")) {
            a[s] =
              ctx.measureText(s).width / FONT_PX +
              TRACK_A * Array.from(s).length;
          }
          ctx.font = `500 ${FONT_PX}px "${syne.fontFamily}"`;
          for (const s of kb.split("\u0001")) {
            b[s] =
              ctx.measureText(s).width / FONT_PX +
              TRACK_B * Array.from(s).length;
          }
        }
        setState({ key, a, b });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state : null;
}

function runs(words: string[]) {
  const out: string[] = [];
  for (let i = 0; i < words.length; i++) {
    for (let j = i; j < words.length; j++) {
      out.push(words.slice(i, j + 1).join(" "));
    }
  }
  return out;
}

function wrap(
  words: string[],
  em: Record<string, number>,
  F: number,
  maxW: number,
) {
  const lines: string[][] = [[]];
  for (const w of words) {
    const cur = lines[lines.length - 1];
    if (cur.length > 0 && em[[...cur, w].join(" ")] * F > maxW) lines.push([w]);
    else cur.push(w);
  }
  return lines;
}

const bare = (w: string) =>
  w.toLowerCase().replace(/^[“"'‘(]+|[.,!?;:…”"'’)—–]+$/g, "");

export function CutOff({
  line = "So first I export the clips, redo all the captions, then line up the mus",
  reply = "Or let the code cut it.",
  highlight = "the code",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: CutOffProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  const cleanLine = line.replace(/[\s—–-]+$/, "");
  const aWords = cleanLine.split(" ").filter(Boolean);
  const bWords = reply.split(" ").filter(Boolean);
  const fragment = aWords[aWords.length - 1] ?? "";
  const em = useEm(
    runs([...aWords.slice(0, -1), `${fragment}—`]),
    runs(bWords),
  );

  if (!em) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const shown = [...aWords.slice(0, -1), `${fragment}—`];

  const aMaxW = W * (portrait ? 0.84 : 0.8);
  const fA = portrait ? W * 0.09 : H * 0.122;
  const aLines = wrap(shown, em.a, fA, aMaxW);
  const aBlockH = aLines.length * LH_A * fA;
  const aLeft = W * (portrait ? 0.09 : 0.08);
  const aTop = (H - aBlockH) / 2;

  const bBoxW = W * (portrait ? 0.84 : 0.86);
  const bBoxH = H * (portrait ? 0.5 : 0.62);
  const widestB = Math.max(...bWords.map((w) => em.b[w] ?? 0), 0.01);
  let lo = 4;
  let top = Math.min(portrait ? W * 0.26 : H * 0.34, bBoxW / widestB);
  for (let i = 0; i < 28; i++) {
    const mid = (lo + top) / 2;
    if (wrap(bWords, em.b, mid, bBoxW).length * LH_B * mid <= bBoxH) lo = mid;
    else top = mid;
  }
  const fB = lo;
  const bLines = wrap(bWords, em.b, fB, bBoxW);
  const bLeft = W * (portrait ? 0.08 : 0.07);
  const bBottom = H * (portrait ? 0.9 : 0.86);
  const bTop = bBottom - bLines.length * LH_B * fB;

  const fragLetters = Array.from(fragment).length;
  const fixedTail = fragLetters * LETTER + DASH_HOLD + HIT_GAP + HIT + MIN_HOLD;
  const gap = Math.max(
    3,
    Math.min(
      7,
      (durationInFrames - LEAD_IN - fixedTail) / Math.max(1, aWords.length - 1),
    ),
  );
  const fragAt = LEAD_IN + (aWords.length - 1) * gap;
  const dashAt = fragAt + fragLetters * LETTER;
  const cutAt = dashAt + DASH_HOLD;

  const hlTokens = highlight.split(" ").filter(Boolean).map(bare);
  const hlFlags = bWords.map(() => false);
  for (
    let i = 0;
    i + hlTokens.length <= bWords.length && hlTokens.length > 0;
    i++
  ) {
    if (hlTokens.every((h, j) => bare(bWords[i + j]) === h)) {
      for (let j = 0; j < hlTokens.length; j++) hlFlags[i + j] = true;
      break;
    }
  }
  let splitAt = bWords.findIndex((w) => /[,;:—]$/.test(w)) + 1;
  if (splitAt <= 0 || splitAt >= bWords.length) {
    const firstHl = hlFlags.indexOf(true);
    splitAt = firstHl > 0 ? firstHl : Math.ceil(bWords.length / 2);
  }

  const textBase = (
    size: number,
    wght: number,
    track: number,
    lh: number,
  ): React.CSSProperties => ({
    position: "absolute",
    whiteSpace: "pre",
    fontFamily: syne.fontFamily,
    fontWeight: wght,
    fontSize: size,
    lineHeight: `${size * lh}px`,
    height: size * lh,
    letterSpacing: `${track}em`,
  });

  const before = t < cutAt;
  const nodes: React.ReactNode[] = [];
  if (before) {
    let idx = 0;
    aLines.forEach((ln, li) => {
      ln.forEach((w, wi) => {
        const i = idx++;
        const before = ln.slice(0, wi).join(" ");
        const x = wi === 0 ? 0 : (em.a[`${before} ${w}`] ?? 0) - (em.a[w] ?? 0);
        const isFrag = i === shown.length - 1;
        const at = LEAD_IN + i * gap;
        let content = w;
        let p = interpolate(t, [at, at + WORD_IN], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        if (isFrag) {
          const letters = Array.from(fragment);
          const typed = Math.max(
            0,
            Math.min(letters.length, Math.floor((t - fragAt) / LETTER) + 1),
          );
          content = letters.slice(0, typed).join("");
          p = t >= fragAt ? 1 : 0;
        }
        if (p <= 0 || content === "") return;
        nodes.push(
          <div
            key={`a${i}`}
            style={{
              ...textBase(fA, 400, TRACK_A, LH_A),
              left: aLeft + x * fA,
              top: aTop + li * LH_A * fA,
              color: c.dim,
              opacity: p,
              transform: `translateY(${((1 - p) * fA * 0.35).toFixed(2)}px)`,
            }}
          >
            {content}
            {isFrag && t >= dashAt ? (
              <span style={{ color: hi }}>—</span>
            ) : null}
          </div>,
        );
      });
    });
  }

  let bi = 0;
  if (!before)
    bLines.forEach((ln, li) => {
      ln.forEach((w, wi) => {
        const i = bi++;
        const before = ln.slice(0, wi).join(" ");
        const x = wi === 0 ? 0 : (em.b[`${before} ${w}`] ?? 0) - (em.b[w] ?? 0);
        const at = i < splitAt ? cutAt - 3 : cutAt + HIT_GAP;
        if (t < Math.max(cutAt, at)) return;
        const p = interpolate(t, [at, at + HIT], [0, 1], {
          ...CLAMP,
          easing: EASE_HIT,
        });
        nodes.push(
          <div
            key={`b${i}`}
            style={{
              position: "absolute",
              left: bLeft + x * fB,
              top: bTop + li * LH_B * fB - fB * 0.1,
              height: fB * (LH_B + 0.32),
            }}
          >
            <div
              style={{
                ...textBase(fB, 500, TRACK_B, LH_B),
                position: "relative",
                top: fB * 0.1,
                color: hlFlags[i] ? hi : c.replyInk,
                transform: `translateY(${((1 - p) * fB * 0.22).toFixed(2)}px) scale(${(1 + (1 - p) * 0.05).toFixed(4)})`,
                transformOrigin: "0% 100%",
              }}
            >
              {w}
            </div>
          </div>,
        );
      });
    });

  const field = before ? stage : transparent ? "transparent" : c.replyBg;
  return (
    <AbsoluteFill style={{ background: field, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadPlexMono } from "@remotion/google-fonts/IBMPlexMono";
import { loadFont as loadInstrument } from "@remotion/google-fonts/InstrumentSans";
import { Fragment, useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const instrument = loadInstrument("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const plex = loadPlexMono("normal", { weights: ["500"], subsets: ["latin"] });

export interface CutStatProps {
  value?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  caption?: string;
  fromLabel?: string;
  toLabel?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const MESH = ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"] as const;
const MESH_BG = "#0a0d24";
const BLOBS: [number, number][] = [
  [16, 20],
  [84, 26],
  [72, 86],
  [22, 80],
  [52, 48],
  [92, 62],
];

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    fieldFg: "#F6F4FF",
    fieldMuted: "rgba(246,244,255,0.66)",
    edge: "#F6F4FF",
    tick: "rgba(255,255,255,0.09)",
    fieldTick: "rgba(255,255,255,0.16)",
    fieldBg: MESH_BG,
    blobs: [MESH[3], MESH[3], MESH[1], MESH[2], MESH[1], MESH[0]],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    fieldFg: "#0E1238",
    fieldMuted: "rgba(14,18,56,0.6)",
    edge: "#111113",
    tick: "rgba(17,17,19,0.1)",
    fieldTick: "rgba(14,18,56,0.16)",
    fieldBg: "#DCE0F8",
    blobs: ["#c9d0f7", "#a9b4f2", MESH[1], "#b3bdf4", MESH[0], "#f3eef9"],
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_CUT = Easing.bezier(0.72, 0, 0.16, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function estimateEm(text: string) {
  let w = 0;
  for (const ch of text) {
    if (/[0-9]/.test(ch)) w += 0.56;
    else if (ch === "%") w += 0.78;
    else if (/[.,]/.test(ch)) w += 0.24;
    else if (/[−\-+×x]/.test(ch)) w += 0.52;
    else if (ch === "$" || ch === "€") w += 0.56;
    else if (ch === " ") w += 0.22;
    else w += 0.56;
  }
  return w;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `grain-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.8"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function CutStat({
  value = 44,
  decimals = 0,
  prefix = "−",
  suffix = "%",
  label = "less time to a finished cut",
  caption = "vs. keyframing every scene by hand",
  fromLabel = "Before",
  toLabel = "With remocn",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: CutStatProps) {
  const raw = useCurrentFrame();
  const frame = raw * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const p = PALETTES[theme];

  const portrait = height > width * 1.1;
  const u = Math.min(width, height) / 720;
  const v = Math.min(95, Math.max(5, value));
  const along = portrait ? height : width;

  const intro = interpolate(frame, [0, 6], [0, 1], CLAMP);
  const fill = interpolate(frame, [0, 15], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const cut = interpolate(frame, [19, 51], [0, 1], {
    ...CLAMP,
    easing: EASE_CUT,
  });
  const flash = interpolate(frame, [49, 52, 63], [0, 1, 0], CLAMP);
  const drift = interpolate(raw, [0, durationInFrames], [0, 1], CLAMP);
  const cutPx = (along * v * cut) / 100;
  const remaining = 100 - v * cut;
  const counted = v * cut;
  const fmt = (n: number) => n.toFixed(decimals);
  const swapT = interpolate(frame, [44, 56], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const margin = (portrait ? 56 : 52) * u;
  const zone = (along * v) / 100;
  const finalText = `${prefix}${fmt(v)}${suffix}`;
  const em = estimateEm(finalText);
  const roomW = portrait
    ? width - margin * 2
    : Math.max(zone, width * 0.36) - margin * 1.6;
  const statFs = Math.min(
    (portrait ? 300 : 236) * u,
    roomW / em,
    portrait ? Math.max(zone, height * 0.3) * 0.5 : Infinity,
  );
  const words = label.split(/\s+/).filter(Boolean);
  const wordT = (i: number) =>
    interpolate(frame, [47 + i * 3, 65 + i * 3], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const capT = interpolate(
    frame,
    [63 + words.length * 2, 81 + words.length * 2],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const transparent = background === "transparent";
  const labelFs = 14 * u;
  const blobs = BLOBS.map(([x, y], i) => {
    const c = p.blobs[i];
    const dx = Math.sin(i * 1.7 + drift * 2.2) * 3;
    const dy = Math.cos(i * 1.3 + drift * 2.2) * 3;
    return `radial-gradient(85% 95% at ${x + dx}% ${y + dy}%, ${c} 0%, transparent 68%)`;
  });
  blobs[2] = `radial-gradient(85% 95% at ${72 + drift * 3}% ${86 - drift * 3}%, color-mix(in oklab, ${accent} ${theme === "dark" ? 70 : 45}%, ${MESH[1]}) 0%, transparent 68%)`;

  const shut = cutPx + along * (1 - fill);
  const fieldClip = portrait
    ? `inset(0 0 ${shut}px 0)`
    : `inset(0 ${shut}px 0 0)`;
  const edgePos = along - shut;
  const edgeO =
    fill < 1
      ? fill > 0.02 && fill < 0.98
        ? 1
        : 0
      : cut <= 0
        ? 0
        : cut < 1
          ? 1
          : 0.35 + flash * 0.65;

  const release = interpolate(frame, [53, 69], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const clipAt = edgePos * (1 - release);
  const statClip = portrait
    ? `inset(${clipAt}px 0 0 0)`
    : `inset(0 0 0 ${clipAt}px)`;

  const scaleT = interpolate(frame, [4, 20], [0, 1], CLAMP);
  const scale = (line: string, text: string) => (
    <div style={{ position: "absolute", inset: 0, opacity: scaleT }}>
      {Array.from({ length: 11 }, (_, i) => {
        const at = (along * i) / 10;
        return (
          <Fragment key={i}>
            {i > 0 && i < 10 ? (
              <div
                style={{
                  position: "absolute",
                  background: line,
                  ...(portrait
                    ? { left: 0, right: 0, top: at, height: 1 }
                    : { top: 0, bottom: 0, left: at, width: 1 }),
                }}
              />
            ) : null}
            <div
              style={{
                position: "absolute",
                fontFamily: plex.fontFamily,
                fontWeight: 500,
                fontSize: 11 * u * (portrait ? 1.3 : 1),
                letterSpacing: "0.04em",
                color: text,
                fontVariantNumeric: "tabular-nums",
                ...(portrait
                  ? {
                      right: 18 * u,
                      top: Math.min(
                        Math.max(at - 18 * u, 8 * u),
                        height - 26 * u,
                      ),
                    }
                  : {
                      bottom: 16 * u,
                      left: Math.min(
                        Math.max(at + 7 * u, 8 * u),
                        width - 30 * u,
                      ),
                    }),
              }}
            >
              {i * 10}
            </div>
          </Fragment>
        );
      })}
    </div>
  );

  const readout = (fg: string, muted: string) => (
    <div
      style={{
        position: "absolute",
        left: margin,
        top: margin,
        display: "flex",
        alignItems: "center",
        gap: 12 * u,
        fontFamily: plex.fontFamily,
        fontWeight: 500,
        fontSize: labelFs,
        letterSpacing: "0.06em",
        textTransform: "uppercase",
        color: fg,
      }}
    >
      <span
        style={{
          display: "grid",
          overflow: "hidden",
        }}
      >
        <span
          style={{
            gridArea: "1 / 1",
            transform: `translateY(${-swapT * 110}%)`,
          }}
        >
          {fromLabel}
        </span>
        <span
          style={{
            gridArea: "1 / 1",
            transform: `translateY(${(1 - swapT) * 110}%)`,
          }}
        >
          {toLabel}
        </span>
      </span>
      <span style={{ width: 24 * u, height: 1, background: muted }} />
      <span
        style={{
          color: muted,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {fmt(remaining)}%
      </span>
    </div>
  );

  const statStyle = {
    fontFamily: instrument.fontFamily,
    fontWeight: 500,
    fontSize: statFs,
    lineHeight: 0.9,
    letterSpacing: "-0.05em",
    fontVariantNumeric: "tabular-nums",
    color: p.fg,
    whiteSpace: "nowrap",
  } as const;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {scale(p.tick, p.muted)}
      <div style={{ position: "absolute", inset: 0, opacity: intro }}>
        {readout(p.fg, p.muted)}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: statClip,
          opacity: interpolate(frame, [18, 20], [0, 1], CLAMP),
          zIndex: 2,
        }}
      >
        <div
          style={{
            position: "absolute",
            ...(portrait
              ? {
                  left: margin,
                  right: margin * 1.6,
                  bottom: margin,
                  height: Math.max(zone, height * 0.3) - margin,
                  justifyContent: "flex-end",
                }
              : {
                  right: margin,
                  top: margin,
                  bottom: margin * 1.45,
                  width: Math.max(zone, width * 0.36) - margin * 1.6,
                  justifyContent: "flex-end",
                }),
            display: "flex",
            flexDirection: "column",
            alignItems: portrait ? "flex-start" : "flex-end",
            textAlign: portrait ? "left" : "right",
          }}
        >
          <div
            style={{
              ...statStyle,
              marginRight: portrait ? 0 : -statFs * 0.04,
              marginLeft: portrait ? -statFs * 0.04 : 0,
            }}
          >
            {prefix}
            {fmt(counted)}
            {suffix}
          </div>
          <div
            style={{
              marginTop: statFs * 0.14,
              maxWidth: portrait
                ? width - margin * 2
                : Math.max(roomW, 300 * u),
              fontFamily: instrument.fontFamily,
              fontWeight: 400,
              fontSize: (portrait ? 46 : 34) * u,
              lineHeight: 1.12,
              letterSpacing: "-0.02em",
              color: p.fg,
              textWrap: "balance",
            }}
          >
            {words.map((w, k) => {
              const t = wordT(k);
              return (
                <Fragment key={`${w}-${k}`}>
                  {k > 0 ? " " : null}
                  <span
                    style={{
                      display: "inline-block",
                      overflow: "hidden",
                      verticalAlign: "top",
                      paddingBottom: "0.12em",
                      marginBottom: "-0.12em",
                    }}
                  >
                    <span
                      style={{
                        display: "inline-block",
                        transform: `translateY(${(1 - t) * 105}%)`,
                      }}
                    >
                      {w}
                    </span>
                  </span>
                </Fragment>
              );
            })}
          </div>
          {caption ? (
            <div
              style={{
                marginTop: 16 * u,
                fontFamily: plex.fontFamily,
                fontWeight: 500,
                fontSize: labelFs * (portrait ? 1.3 : 1),
                letterSpacing: "0.04em",
                textTransform: "uppercase",
                color: p.muted,
                opacity: capT,
                transform: `translateY(${(1 - capT) * 8 * u}px)`,
              }}
            >
              {caption}
            </div>
          ) : null}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: fieldClip,
          opacity: intro,
          background: [...blobs, p.fieldBg].join(", "),
        }}
      >
        <Grain opacity={0.1} />
        {scale(p.fieldTick, p.fieldMuted)}
        {readout(p.fieldFg, p.fieldMuted)}
      </div>

      <div
        style={{
          position: "absolute",
          ...(portrait
            ? { left: 0, right: 0, top: edgePos - 1 * u, height: 2 * u }
            : { top: 0, bottom: 0, left: edgePos - 1 * u, width: 2 * u }),
          background: p.edge,
          opacity: edgeO * intro,
          zIndex: 3,
        }}
      />
    </AbsoluteFill>
  );
}

