  const ax = mix(mix(K.aT[0], K.a0[0], g), K.a1[0], p);
  const ay = mix(mix(K.aT[1], K.a0[1], g), K.a1[1], p);
  const camBlur = Math.min(3, Math.abs(p - pPrev) * 70);

  const bezelIn = ramp(frame, B.grow, 18, SOFT);
  const bezelScale = mix(
