  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const sans = loadInstrumentSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", { weights: ["500"], subsets: ["latin"] });

export interface DiffSwapProps {
  before?: string;
  after?: string;
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    dim: "#77767D",
    sign: "#B9B8BE",
    minusBand: `linear-gradient(90deg, color-mix(in oklab, ${FLUTED[2]} 22%, transparent) 0%, color-mix(in oklab, ${FLUTED[2]} 7%, transparent) 55%, transparent 100%)`,
    minusEdge: `color-mix(in oklab, ${FLUTED[2]} 70%, transparent)`,
    plusBand: (a: string) =>
      `linear-gradient(90deg, color-mix(in oklab, ${a} 30%, transparent) 0%, color-mix(in oklab, ${a} 9%, transparent) 55%, transparent 100%)`,
    ground: [
      `radial-gradient(70% 70% at 104% 108%, color-mix(in oklab, ${FLUTED[0]} 62%, transparent) 0%, transparent 70%)`,
      `radial-gradient(40% 40% at -4% -6%, color-mix(in oklab, ${FLUTED[2]} 12%, transparent) 0%, transparent 75%)`,
    ].join(", "),
    hl: (a: string) =>
      `linear-gradient(95deg, ${FLUTED[3]} 0%, #ffb183 22%, ${FLUTED[1]} 62%, color-mix(in oklab, ${a} 60%, ${FLUTED[1]}) 100%)`,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    dim: "#9A9893",
    sign: "#55534F",
    minusBand: `linear-gradient(90deg, color-mix(in oklab, ${FLUTED[2]} 18%, transparent) 0%, color-mix(in oklab, ${FLUTED[2]} 6%, transparent) 55%, transparent 100%)`,
    minusEdge: `color-mix(in oklab, ${FLUTED[2]} 75%, transparent)`,
    plusBand: (a: string) =>
      `linear-gradient(90deg, color-mix(in oklab, ${a} 18%, transparent) 0%, color-mix(in oklab, ${a} 6%, transparent) 55%, transparent 100%)`,
    ground: [
      `radial-gradient(70% 70% at 104% 108%, color-mix(in oklab, ${FLUTED[1]} 16%, transparent) 0%, transparent 70%)`,
      `radial-gradient(40% 40% at -4% -6%, color-mix(in oklab, ${FLUTED[3]} 60%, transparent) 0%, transparent 75%)`,
    ].join(", "),
    hl: (a: string) =>
      `linear-gradient(95deg, #d9531c 0%, ${FLUTED[2]} 26%, ${a} 64%, ${FLUTED[0]} 100%)`,
  },
} as const;

const TRACK = -0.03;
const LINE = 1.1;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.7, 0, 0.2, 1);
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

type Measure = (s: string) => number;

function useMeasure(): Measure {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("diff-swap: measuring"));
  const released = useRef(false);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);

  useEffect(() => {
    let live = true;
    const font = `500 100px "${sans.fontFamily}"`;
    Promise.all([sans.waitUntilDone(), document.fonts.load(font)])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        if (ctx) ctx.font = font;
        ctxRef.current = ctx;
        setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);

  const ctx = ready ? ctxRef.current : null;
  return (s: string) =>
    (ctx ? ctx.measureText(s).width / 100 : s.length * 0.55) +
    TRACK * Math.max(0, s.length - 1);
}

function wrapTwo(text: string, measure: Measure, maxEm: number) {
  const words = text.split(/\s+/).filter(Boolean);
  const one = words.join(" ");
  if (measure(one) <= maxEm || words.length < 2) {
    return { lines: [one], widest: measure(one) };
  }
  let best = { lines: [one], widest: Number.POSITIVE_INFINITY };
  for (let k = 1; k < words.length; k++) {
    const a = words.slice(0, k).join(" ");
    const b = words.slice(k).join(" ");
    const w = Math.max(measure(a), measure(b));
    if (w < best.widest) best = { lines: [a, b], widest: w };
  }
  return best;
}

function splitHighlight(line: string, phrase: string) {
  if (!phrase) return [line, "", ""] as const;
  const i = line.toLowerCase().indexOf(phrase.toLowerCase());
  if (i < 0) return [line, "", ""] as const;
  return [
    line.slice(0, i),
    line.slice(i, i + phrase.length),
    line.slice(i + phrase.length),
  ] as const;
}

export function DiffSwap({
  before = "Keyframe every frame by hand.",
  after = "Install the scene. Edit the props.",
  highlight = "Edit the props.",
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: DiffSwapProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const t = THEMES[theme];
  const measure = useMeasure();

  const portrait = height > width * 1.1;
  const s = portrait ? width / 1080 : Math.min(width / 1280, height / 720);
  const padX = width * (portrait ? 0.07 : 0.085);
  const gutterEm = 0.95;

  const cap = (portrait ? 118 : 92) * s;
  const avail = width - padX * 2;
  const fitRows = (fs: number) => {
    const maxEm = avail / fs - gutterEm;
    return {
      b: wrapTwo(before, measure, maxEm),
      a: wrapTwo(after, measure, maxEm),
      maxEm,
    };
  };
  let fs = cap;
  let rows = fitRows(fs);
  for (let i = 0; i < 24; i++) {
    const tooWide = rows.b.widest > rows.maxEm || rows.a.widest > rows.maxEm;
    const tall =
      (rows.b.lines.length + rows.a.lines.length) * LINE * fs + fs * 0.6 >
      height * (portrait ? 0.56 : 0.72);
    if (!tooWide && !tall) break;
    fs *= 0.94;
    rows = fitRows(fs);
  }
  const rowPadY = fs * 0.2;
  const rowH = (n: number) => n * LINE * fs + rowPadY * 2;
  const hB = rowH(rows.b.lines.length);
  const hA = rowH(rows.a.lines.length);
  const gap = fs * 0.12;

  const scaleEnd = Math.min(
    portrait ? 1.5 : 1.42,
    avail / fs / Math.max(rows.a.widest, 0.01),
    (height * (portrait ? 0.5 : 0.62)) / (rows.a.lines.length * LINE * fs),
  );

  const enter = (i: number) => EASE_OUT(clamp01((frame - i * 3) / 18));
  const mark = EASE_OUT(clamp01((frame - 30) / 14));
  const open = EASE_IO(clamp01((frame - 42) / 18));
  const addIn = (i: number) => EASE_OUT(clamp01((frame - 53 - i * 3) / 18));
  const plusBand = EASE_OUT(clamp01((frame - 46) / 14));
  const fold = EASE_IO(clamp01((frame - 72) / 20));
  const clear = EASE_OUT(clamp01((frame - 78) / 16));
  const grow = EASE_IO(clamp01((frame - 76) / 22));
  const hlT = EASE_OUT(clamp01((frame - 84) / 18));
  const drift = interpolate(
    frame,
    [0, durationInFrames * speed],
    [0, 1],
    CLAMP,
  );

  const curB = hB * (1 - fold);
  const curGap = gap * open * (1 - fold);
  const curA = hA * open;
  const scale = 1 + (scaleEnd - 1) * grow;
  const total = curB + curGap + curA * scale;
  const top = height / 2 - total / 2;
  const topA = top + curB + curGap;

  const transparent = background === "transparent";
  const gutter = gutterEm * fs;
  const left = padX;
  const bandW = width - padX * 2 + fs * 0.3;

  const lineStyle: React.CSSProperties = {
    fontFamily: sans.fontFamily,
    fontWeight: 500,
    fontSize: fs,
    lineHeight: LINE,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre",
  };
  const signStyle = (o: number, x: number): React.CSSProperties => ({
    position: "absolute",
    left: 0,
    top: rowPadY,
    width: gutter * 0.7,
    textAlign: "center",
    fontFamily: mono.fontFamily,
    fontWeight: 500,
    fontSize: fs * 0.72,
    lineHeight: `${LINE * fs}px`,
    color: t.sign,
    opacity: o,
    transform: `translateX(${x}px)`,
  });

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? t.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: t.ground,
            transform: `translate(${(-drift * 1.5).toFixed(3)}%, ${(-drift * 1).toFixed(3)}%) scale(1.04)`,
          }}
        />
      ) : null}

      <div
        style={{
          position: "absolute",
          left: left - fs * 0.15,
          top,
          width: bandW,
          height: curB,
          overflow: "hidden",
          borderRadius: fs * 0.12,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: t.minusBand,
            clipPath: `inset(0 ${((1 - mark) * 100).toFixed(2)}% 0 0)`,
            opacity: 1 - clear,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            bottom: 0,
            width: Math.max(2, fs * 0.04),
            background: t.minusEdge,
            opacity: mark * (1 - clear),
          }}
        />
        <div style={signStyle(mark * (1 - fold), (1 - mark) * -fs * 0.3)}>
          −
        </div>
        <div
          style={{
            position: "absolute",
            left: gutter + fs * 0.15,
            top: rowPadY - fold * hB * 0.55,
            opacity: clamp01(1 - fold * 1.5),
          }}
        >
          {rows.b.lines.map((ln, i) => {
            const e = enter(i);
            return (
              <div
                key={`b${i}`}
                style={{
                  overflow: "hidden",
                  paddingBottom: fs * 0.12,
                  marginBottom: -fs * 0.12,
                }}
              >
                <div
                  style={{
                    ...lineStyle,
                    color: `color-mix(in oklab, ${t.fg} ${((1 - mark) * 100).toFixed(1)}%, ${t.dim})`,
                    transform: `translateY(${((1 - e) * 105).toFixed(2)}%)`,
                  }}
                >
                  {ln}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: left - fs * 0.15,
          top: topA,
          width: bandW,
          height: curA,
          overflow: "hidden",
          borderRadius: fs * 0.12,
          transform: `translateX(${(grow * (fs * 0.15 - (gutter + fs * 0.15) * scale)).toFixed(2)}px) scale(${scale.toFixed(4)})`,
          transformOrigin: "left top",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: t.plusBand(accent),
            clipPath: `inset(0 ${((1 - plusBand) * 100).toFixed(2)}% 0 0)`,
            opacity: 1 - clear,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            bottom: 0,
            width: Math.max(2, fs * 0.04),
            background: accent,
            opacity: plusBand * (1 - clear),
          }}
        />
        <div
          style={signStyle(plusBand * (1 - clear), (1 - plusBand) * -fs * 0.3)}
        >
          +
        </div>
        <div
          style={{
            position: "absolute",
            left: gutter + fs * 0.15,
            top: rowPadY,
          }}
        >
          {rows.a.lines.map((ln, i) => {
            const e = addIn(i);
            const [pre, hl, post] = splitHighlight(ln, highlight);
            return (
              <div
                key={`a${i}`}
                style={{
                  overflow: "hidden",
                  paddingBottom: fs * 0.12,
                  marginBottom: -fs * 0.12,
                }}
              >
                <div
                  style={{
                    ...lineStyle,
                    color: t.fg,
                    opacity: clamp01(e * 1.8),
                    transform: `translateY(${((1 - e) * 105).toFixed(2)}%)`,
                  }}
                >
                  {pre}
                  {hl ? (
                    <span style={{ position: "relative" }}>
                      <span style={{ opacity: 1 - hlT }}>{hl}</span>
                      <span
                        style={{
                          position: "absolute",
                          left: 0,
                          top: 0,
                          opacity: hlT,
                          backgroundImage: t.hl(accent),
                          backgroundSize: "160% 100%",
                          backgroundPosition: `${(drift * 50).toFixed(2)}% 0%`,
                          WebkitBackgroundClip: "text",
                          backgroundClip: "text",
                          color: "transparent",
                          paddingRight: "0.05em",
                        }}
                      >
                        {hl}
                      </span>
                    </span>
                  ) : null}
                  {post}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadArimo } from "@remotion/google-fonts/Arimo";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const arimo = loadArimo("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface DiminuendoProps {
  value?: number;
  from?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  ratio?: number;
  separator?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const tone = (ink: string, field: string, k: number) =>
  `color-mix(in oklab, ${ink} ${k}%, ${field})`;

const THEMES = {
  dark: {
    bg: (_a: string) => "#000000",
    label: (a: string) => a,
    ramp: (a: string) => [
      a,
      tone(a, "#000", 74),
      tone(a, "#000", 54),
      tone(a, "#000", 40),
    ],
    spin: (_a: string) => "#000000",
  },
  light: {
    bg: (a: string) => a,
    label: (_a: string) => "#000000",
    ramp: (a: string) => [
      "#000000",
      tone("#000", a, 76),
      tone("#000", a, 56),
      tone("#000", a, 42),
    ],
    spin: (a: string) => a,
  },
} as const;

const WEIGHT = 500;
const HEAD = 1.06;
const TRACK = -0.02;

const INTRO_LEN = 14;
const COUNT_AT = 8;
const COUNT_LEN = 64;
const BIRTH_LEN = 10;
const ROLL_LEN = 6;
const LABEL_AT = 4;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_COUNT = Easing.bezier(0.33, 0.05, 0.2, 1);
const EASE_ROLL = Easing.bezier(0.3, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  digit: number;
  sep: number;
  prefix: number;
  suffix: number;
  baseline: number;
  figTop: number;
}

function measure(sep: string, prefix: string, suffix: string): Metrics {
  const probe = document.createElement("span");
  Object.assign(probe.style, {
    position: "absolute",
    left: "-99999px",
    top: "0",
    visibility: "hidden",
    whiteSpace: "pre",
    fontFamily: `"${arimo.fontFamily}"`,
    fontSize: "100px",
    lineHeight: "1",
    fontWeight: WEIGHT,
    fontFeatureSettings: '"tnum" 1',
  });
  document.body.appendChild(probe);
  const w = (s: string) => {
    if (!s) return 0;
    probe.textContent = s;
    return probe.getBoundingClientRect().width / 100;
  };
  let digit = 0;
  for (let d = 0; d < 10; d++) digit = Math.max(digit, w(String(d)));
  const m = { digit, sep: w(sep), prefix: w(prefix), suffix: w(suffix) };
  probe.remove();
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  let baseline = 0.8;
  let figTop = 0.7;
  if (ctx) {
    ctx.font = `${WEIGHT} 200px "${arimo.fontFamily}"`;
    const fm = ctx.measureText("0123456789");
    const asc = fm.fontBoundingBoxAscent / 200;
    const desc = fm.fontBoundingBoxDescent / 200;
    baseline = (1 - (asc + desc)) / 2 + asc;
    figTop = fm.actualBoundingBoxAscent / 200;
  }
  return { ...m, baseline, figTop };
}

function useMetrics(sep: string, prefix: string, suffix: string) {
  const key = [sep, prefix, suffix].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("diminuendo: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [a, b, c] = key.split("\u0001");
    Promise.all([
      arimo.waitUntilDone(),
      document.fonts.load(`${WEIGHT} 100px "${arimo.fontFamily}"`),
      document.fonts.load(`400 100px "${arimo.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(a, b, c) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function rampAt(ramp: readonly string[], u: number) {
  const s = Math.min(Math.max(u, 0), 1) * (ramp.length - 1);
  const i = Math.min(Math.floor(s), ramp.length - 2);
  const f = s - i;
  return `color-mix(in oklab, ${ramp[i]} ${((1 - f) * 100).toFixed(1)}%, ${ramp[i + 1]})`;
}

function placesOf(v: number) {
  return Math.max(1, Math.floor(Math.log10(Math.max(1, v))) + 1);
}

export function Diminuendo({
  value = 860000,
  from = 0,
  prefix = "",
  suffix = "",
  label = "frames rendered from the registry last month",
  ratio = 0.8,
  separator = ",",
  accent = "#8ACE00",
  background,
  speed = 1,
  theme = "dark",
}: DiminuendoProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg(accent);
  const ramp = c.ramp(accent);
  const m = useMetrics(separator, prefix, suffix);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const lo = Math.max(0, Math.round(Math.min(from, value)));
  const hi = Math.max(0, Math.round(value));
  const g = 1 / Math.min(0.95, Math.max(0.5, ratio));
  const logLo = Math.log10(lo + 1);
  const logHi = Math.log10(hi + 1);
  const valueAt = (f: number) => {
    const p = EASE_COUNT(Math.min(1, Math.max(0, (f - COUNT_AT) / COUNT_LEN)));
    if (p >= 1) return hi;
    return Math.round(10 ** (logLo + (logHi - logLo) * p) - 1);
  };

  const nFinal = placesOf(hi);
  const birthOf = (p: number) => {
    if (p === 0 || placesOf(lo) > p) return Number.NEGATIVE_INFINITY;
    for (let f = COUNT_AT; f <= COUNT_AT + COUNT_LEN; f += 0.5) {
      if (valueAt(f) >= 10 ** p) return f;
    }
    return COUNT_AT + COUNT_LEN;
  };
  const presence = Array.from({ length: nFinal }, (_, p) => {
    const b = birthOf(p);
    if (!Number.isFinite(b)) return 1;
    return interpolate(t, [b, b + BIRTH_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  });
  const leadEff = presence.reduce((s, a, p) => (p > 0 ? s + a : s), 0);

  const sizeAt = (p: number) => g ** p;
  const slot = (p: number) => (m.digit + TRACK) * sizeAt(p);
  const hasSep = separator.length > 0;
  const sepAfter = (p: number) => hasSep && p >= 3 && p % 3 === 0;
  const sepW = (p: number) => (m.sep + TRACK) * sizeAt(p);
  const prefixW = (lead: number) => (m.prefix + TRACK) * sizeAt(lead);
  const suffixW = m.suffix * sizeAt(-1);

  const widthWith = (a: number[]) => {
    let w = 0;
    for (let p = 0; p < a.length; p++) {
      if (a[p] <= 0) continue;
      w += slot(p) * (0.62 + 0.38 * a[p]);
      if (sepAfter(p)) w += sepW(p) * a[p];
    }
    const leadSize = a.reduce((s, x, p) => (p > 0 ? s + x : s), 0);
    return w + prefixW(leadSize) + suffixW;
  };
  const widthFinal = widthWith(Array.from({ length: nFinal }, () => 1));
  const widthNow = widthWith(presence);

  const vertical = H > W;
  const M = Math.min(W, H) * 0.08;
  const maxW = W - 2 * M;
  const capMax = H * (vertical ? 0.24 : 0.54);
  const S0 = Math.min(
    maxW / widthFinal,
    capMax / (m.figTop * sizeAt(nFinal - 1)),
  );
  const tallest = presence.reduce(
    (best, a, p) =>
      a > 0 ? Math.max(best, sizeAt(p) * (0.62 + 0.38 * a)) : best,
    sizeAt(0),
  );
  const K = Math.min(
    maxW / (widthNow * S0),
    capMax / (m.figTop * S0 * Math.max(tallest, g ** leadEff)),
  );
  const unit = S0 * K;

  const v = valueAt(t);
  const intro = interpolate(t, [0, INTRO_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const baseY = H - M;

  const left = M;

  const spinning = (p: number) => {
    const cur = Math.floor(v / 10 ** p);
    const before = Math.floor(valueAt(t - 3) / 10 ** p);
    return cur !== before;
  };
  const rollOf = (p: number) => {
    const cur = Math.floor(v / 10 ** p) % 10;
    for (let k = 1; k <= ROLL_LEN; k++) {
      const prev = Math.floor(valueAt(t - k) / 10 ** p) % 10;
      if (prev !== cur) {
        const earlier = Math.floor(valueAt(t - k - 1) / 10 ** p) % 10;
        if (earlier !== prev) return { from: prev, p: 1 };
        return { from: prev, p: EASE_ROLL(k / ROLL_LEN) };
      }
    }
    return { from: cur, p: 1 };
  };

  const items: React.ReactNode[] = [];
  let x = left;
  let leadNow = 0;
  presence.forEach((a, p) => {
    if (a > 0) leadNow = p;
  });
  const colorFor = (p: number) =>
    rampAt(ramp, leadEff <= 0 ? 0 : (leadEff - p) / Math.max(1, leadEff));

  if (prefix) {
    const size = sizeAt(leadEff) * unit;
    items.push(
      <Glyph
        key="prefix"
        text={prefix}
        x={x}
        baseY={baseY}
        size={size}
        m={m}
        color={colorFor(leadEff)}
        rise={1 - intro}
      />,
    );
    x += prefixW(leadEff) * unit;
  }

  for (let p = nFinal - 1; p >= 0; p--) {
    const a = presence[p];
    if (a <= 0) continue;
    const size = sizeAt(p) * unit;
    const scale = 0.62 + 0.38 * a;
    const w = slot(p) * unit * scale;
    const digit = Math.floor(v / 10 ** p) % 10;
    const roll = p >= leadNow - 1 ? { from: digit, p: 1 } : rollOf(p);
    const spin = spinning(p) && t < COUNT_AT + COUNT_LEN;
    const base = colorFor(p);
    const color = spin
      ? `color-mix(in oklab, ${base} 72%, ${c.spin(accent)})`
      : base;
    items.push(
      <div
        key={`d${p}`}
        style={{
          position: "absolute",
          left: x + (w - slot(p) * unit * scale) / 2,
          top: baseY - size * m.figTop * HEAD * scale,
          width: slot(p) * unit * scale,
          height: size * (m.figTop * HEAD + 0.06) * scale,
          overflow: "hidden",
          opacity: Math.min(1, a * 1.6),
        }}
      >
        <RollDigit
          digit={digit}
          prev={roll.from}
          p={roll.p}
          size={size * scale}
          m={m}
          color={color}
          rise={p === leadNow && leadNow === 0 ? 1 - intro : 0}
        />
      </div>,
    );
    x += w;
    if (sepAfter(p)) {
      const sw = sepW(p) * unit * a;
      items.push(
        <Glyph
          key={`s${p}`}
          text={separator}
          x={x - sepW(p) * unit * 0.12}
          baseY={baseY}
          size={sizeAt(p) * unit}
          m={m}
          color={colorFor(p)}
          opacity={a}
        />,
      );
      x += sw;
    }
  }

  if (suffix) {
    items.push(
      <Glyph
        key="suffix"
        text={suffix}
        x={x + 0.04 * unit}
        baseY={baseY}
        size={sizeAt(-1) * unit}
        m={m}
        color={colorFor(-1)}
        rise={1 - intro}
      />,
    );
  }

  const labelIn = interpolate(t, [LABEL_AT, LABEL_AT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelSize = vertical ? W * 0.068 : H * 0.058;
  const labelBox: React.CSSProperties = {
    left: M,
    width: Math.min(W - 2 * M, labelSize * 15),
    top: M - labelSize * 0.18,
    textAlign: "left",
  };

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {items}
      {label ? (
        <div
          style={{
            position: "absolute",
            ...labelBox,
            fontFamily: arimo.fontFamily,
            fontWeight: 400,
            fontSize: labelSize,
            lineHeight: 1.08,
            letterSpacing: "-0.025em",
            color: c.label(accent),
            textWrap: "balance",
            opacity: labelIn,
            transform: `translateY(${((1 - labelIn) * labelSize * 0.6).toFixed(2)}px)`,
          }}
        >
          {label.toLowerCase()}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

function Glyph({
  text,
  x,
  baseY,
  size,
  m,
  color,
  rise = 0,
  opacity = 1,
}: {
  text: string;
  x: number;
  baseY: number;
  size: number;
  m: Metrics;
  color: string;
  rise?: number;
  opacity?: number;
}) {
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: baseY - m.baseline * size,
        fontFamily: arimo.fontFamily,
        fontWeight: WEIGHT,
        fontFeatureSettings: '"tnum" 1',
        fontSize: size,
        lineHeight: 1,
        whiteSpace: "pre",
        letterSpacing: `${TRACK}em`,
        color,
        opacity: opacity * (1 - rise),
        transform: `translateY(${(rise * size * 0.4).toFixed(2)}px)`,
      }}
    >
      {text}
    </div>
  );
}

function RollDigit({
  digit,
  prev,
  p,
  size,
  m,
  color,
  rise,
}: {
  digit: number;
  prev: number;
  p: number;
  size: number;
  m: Metrics;
  color: string;
  rise: number;
}) {
  const pitch = size * 1.2;
  const top = size * m.figTop * HEAD - m.baseline * size;
  const style = (dy: number): React.CSSProperties => ({
    position: "absolute",
    left: 0,
    right: 0,
    top: top + dy,
    textAlign: "center",
    fontFamily: arimo.fontFamily,
    fontWeight: WEIGHT,
    fontFeatureSettings: '"tnum" 1',
    fontSize: size,
    lineHeight: 1,
    color,
  });
  const lift = rise * pitch;
  return (
    <>
      {p < 1 ? <div style={style(-p * pitch)}>{prev}</div> : null}
      <div style={style((1 - p) * pitch + lift)}>{digit}</div>
    </>
  );
}

