              style={{
                fontFamily: serif.fontFamily,
                fontWeight: 400,
                fontSize: (tall ? 76 : 58) * u,
                lineHeight: 1,
                letterSpacing: "-0.02em",
                color: "#fff",
              }}
            >
              {words.map((w, i) => {
                const s = spring({
                  frame: frame - B_BEATS.title - i * 3,
                  fps,
                  config: { mass: 0.8, damping: 18, stiffness: 160 },
                });
                return (
                  <span
                    key={`${w}-${i}`}
                    style={{
                      display: "inline-block",
                      overflow: "hidden",
                      paddingBottom: "0.1em",
                      marginBottom: "-0.1em",
                      verticalAlign: "bottom",
                    }}
                  >
                    <span
                      style={{
                        display: "inline-block",
                        transform: `translateY(${(1 - s) * 100}%)`,
                      }}
                    >
                      {w}
                      {i < words.length - 1 ? " " : ""}
                    </span>
                  </span>
                );
              })}
            </div>
          </div>
          <div
            style={{
              position: "absolute",
              left: 24 * u,
              right: 24 * u,
              bottom: 18 * u,
              display: "flex",
              alignItems: "center",
              gap: 14 * u,
            }}
          >
            <Stroke d={UI_ICONS.play} size={18 * u} color="#fff" fill />
            <Stroke d={UI_ICONS.volume} size={18 * u} color="#fff" />
            <span
              style={{
                fontFamily: mono.fontFamily,
                fontSize: 13 * u,
                color: "rgba(255,255,255,0.8)",
              }}
            >
              0:0{Math.min(9, Math.floor(progress * 12))} / 0:12
            </span>
            <div
              style={{
                flex: 1,
                height: 3 * u,
                borderRadius: 3 * u,
                background: "rgba(255,255,255,0.25)",
                position: "relative",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  bottom: 0,
                  width: `${progress * 100}%`,
                  borderRadius: 3 * u,
                  background: "#fff",
                }}
              />
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}

