}

export function DistributionShift({
  before = 840,
  after = 120,
  unit = "ms",
  label = "p99 latency",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: DistributionShiftProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const hw = Math.max(1, u);

  const hi = Math.max(before, after);
  const step = niceStep(hi * 1.18);
  const axisMax = Math.ceil((hi * 1.12) / step) * step;
  const ticks = Array.from(
    { length: Math.round(axisMax / step) + 1 },
    (_, i) => i * step,
  );

  const L = width * 0.08;
  const R = width * 0.92;
  const base = height * 0.8;
  const top = height * 0.3;
  const xOf = (v: number) => L + (v / axisMax) * (R - L);

  const morph = interpolate(t, MORPH, [0, 1], { ...CLAMP, easing: EASE_IO });
  const sb = shape(before, SIGMA_BEFORE);
  const sa = shape(after, SIGMA_AFTER);
  const curveAt = (k: number) => {
    const mu = lerp(sb.mu, sa.mu, k);
    const sigma = lerp(SIGMA_BEFORE, SIGMA_AFTER, k);
    const peak = density(Math.exp(mu - sigma * sigma), mu, sigma);
    const h = lerp(0.3, 1, k) * (base - top);
    return (v: number) => (density(v, mu, sigma) / peak) * h;
  };
  const now = curveAt(morph);
  const was = curveAt(0);

  const markerV = Math.exp(lerp(Math.log(before), Math.log(after), morph));
  const markerX = xOf(markerV);
  const color = interpolateColors(morph, [0, 1], [p.neutral, p.stroke]);
  const gradId = `d${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const stops = [p.ramp[0], p.ramp[1], accent].map((c) =>
    interpolateColors(morph, [0, 1], [p.neutral, c]),
  );

  const axisK = interpolate(t, AXIS, [0, 1], { ...CLAMP, easing: EASE_IO });
  const markK = interpolate(t, MARK, [0, 1], { ...CLAMP, easing: EASE_OUT });
  const tagIn = interpolate(t, [MARK[0] + 6, MARK[1] + 8], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const ghostO = interpolate(t, [MORPH[0], MORPH[0] + 14], [0, 1], CLAMP);
  const kick = spring({
    frame: t - HIT,
    fps,
    config: { damping: 14, stiffness: 180, mass: 0.6 },
  });
  const after1 = interpolate(t, [HIT + 4, HIT + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, HIT + 54], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const closer = interpolate(t, [MORPH[0] + 16, HIT + 44], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const zoom = 1 + push * 0.025 + closer * 0.16;
  const pitch = (R - L) / BINS;
  const barW = pitch * 0.56;
  const bars = Array.from({ length: BINS }, (_, i) => {
    const v = ((i + 0.5) / BINS) * axisMax;
    const rise = interpolate(t, [RISE + i * 0.3, RISE + i * 0.3 + 16], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const h = now(v) * rise;
    const x = L + i * pitch + (pitch - barW) / 2;
    const tail = v > markerV;
    return { key: i, x, h, tail };
  });

  const samples = 260;
  const path = (fn: (v: number) => number, k: number) =>
    Array.from({ length: samples + 1 }, (_, i) => {
      const v = (i / samples) * axisMax * k;
      return `${i ? "L" : "M"}${xOf(v).toFixed(2)} ${(base - fn(v)).toFixed(2)}`;
    }).join(" ");
  const strokeK = interpolate(t, [RISE + 2, RISE + 40], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.4, 0, 0.2, 1),
  });
  const ghostMarkX = xOf(before);
  const ghostTop = base - (base - top) * 0.5;
  const markTop = top - 12 * u;
  const drop = Math.round((1 - after / before) * 100);
  const modeX = xOf(
    Math.exp(
      lerp(sb.mu, sa.mu, morph) - lerp(SIGMA_BEFORE, SIGMA_AFTER, morph) ** 2,
    ),
  );
  const glowX = ((width * 0.3 + (modeX - width * 0.3) * zoom) / width) * 100;
  const heroScale = 1 + 0.04 * (1 - kick) * (t >= HIT ? 1 : 0);

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(${16 + 14 * (1 - morph)}% ${46 - 6 * morph}% at ${glowX}% 74%, ${p.glow}, transparent 70%)`,
          opacity: 0.2 + 0.8 * morph,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${zoom})`,
          transformOrigin: "30% 70%",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={top - 16 * u}
              x2={0}
              y2={base}
            >
              <stop offset="0" stopColor={stops[0]} />
              <stop offset="0.42" stopColor={stops[1]} />
              <stop offset="1" stopColor={stops[2]} />
            </linearGradient>
          </defs>
          <path
            d={`${path(now, 1)} L ${xOf(axisMax).toFixed(2)} ${base} L ${L} ${base} Z`}
            fill={`url(#${gradId})`}
            opacity={p.area * strokeK}
          />
          {bars.map((b) =>
            b.h > 0.2 ? (
              <rect
                key={b.key}
                x={b.x}
                y={base - b.h}
                width={barW}
                height={b.h}
                rx={Math.min(barW / 2, 1.5 * u)}
                fill={`url(#${gradId})`}
                opacity={b.tail ? 0.32 : 0.9}
              />
            ) : null,
          )}

          <path
            d={path(was, 1)}
            fill="none"
            stroke={p.ghost}
            strokeWidth={hw}
            strokeDasharray={`${3 * u} ${4 * u}`}
            opacity={ghostO}
          />
          <path
            d={path(now, strokeK)}
            fill="none"
            stroke={color}
            strokeWidth={2 * u}
            strokeLinejoin="round"
            strokeLinecap="round"
          />

          <line
            x1={L}
            y1={base}
            x2={lerp(L, R, axisK)}
            y2={base}
            stroke={p.axis}
            strokeWidth={hw}
          />
          {ticks.map((v, i) => {
            const a = interpolate(t, [4 + i * 2, 14 + i * 2], [0, 1], CLAMP);
            return (
              <line
                key={v}
                x1={xOf(v)}
                y1={base}
                x2={xOf(v)}
                y2={base + 6 * u}
                stroke={p.axis}
                strokeWidth={hw}
                opacity={a}
              />
            );
          })}

          <line
            x1={ghostMarkX}
            y1={base}
            x2={ghostMarkX}
            y2={ghostTop}
            stroke={p.ghost}
            strokeWidth={hw}
            strokeDasharray={`${3 * u} ${4 * u}`}
            opacity={ghostO}
          />
          <line
            x1={markerX}
            y1={base}
            x2={markerX}
            y2={lerp(base, markTop, markK)}
            stroke={p.fg}
            strokeWidth={hw * 1.2}
            opacity={markK > 0 ? 1 : 0}
          />
          <circle
            cx={markerX}
            cy={base}
            r={3.6 * u}
            fill={p.bg}
            stroke={p.fg}
            strokeWidth={hw * 1.4}
            opacity={markK}
          />
        </svg>

        {ticks.map((v, i) => {
          const a = interpolate(t, [4 + i * 2, 16 + i * 2], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          return (
            <div
              key={v}
              style={{
                position: "absolute",
                left: xOf(v) - 60 * u,
                width: 120 * u,
                top: base + 14 * u,
                textAlign: "center",
                fontFamily: mono,
                fontWeight: 400,
                fontSize: 12 * u,
                color: p.muted,
                fontVariantNumeric: "tabular-nums",
                opacity: a,
                transform: `translateY(${(1 - a) * 5 * u}px)`,
              }}
            >
              {v.toLocaleString("en-US")}
              {i === ticks.length - 1 ? ` ${unit}` : ""}
            </div>
          );
        })}

        <div
          style={{
            position: "absolute",
            left: ghostMarkX + 8 * u,
            top: ghostTop - 4 * u,
            fontFamily: mono,
            fontWeight: 400,
            fontSize: 12 * u,
            color: p.muted,
            fontVariantNumeric: "tabular-nums",
            opacity: ghostO,
            whiteSpace: "nowrap",
          }}
        >
          {before.toLocaleString("en-US")}
          {unit}
        </div>
      </AbsoluteFill>

      <div
        style={{
          position: "absolute",
          left: width * 0.3 + (markerX - width * 0.3) * zoom + 14 * u,
          top: height * 0.7 + (markTop - height * 0.7) * zoom - 4 * u,
          opacity: tagIn,
          transform: `translateY(${(1 - tagIn) * 10 * u}px)`,
        }}
      >
        <div
          style={{
            fontFamily: mono,
            fontWeight: 400,
            fontSize: 13 * u,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            color: p.muted,
            marginBottom: 12 * u,
            whiteSpace: "nowrap",
          }}
        >
          {label}
        </div>
        <div
          style={{
            transform: `scale(${heroScale})`,
            transformOrigin: "0% 50%",
          }}
        >
          <Readout
            value={markerV}
            unit={unit}
            size={104 * u}
            color={p.fg}
            unitColor={p.muted}
          />
        </div>
        <div
          style={{
            marginTop: 14 * u,
            display: "flex",
            alignItems: "baseline",
            gap: 10 * u,
            fontFamily: sans,
            fontWeight: 400,
            fontSize: 20 * u,
            fontVariantNumeric: "tabular-nums",
            opacity: after1,
            transform: `translateY(${(1 - after1) * 8 * u}px)`,
            whiteSpace: "nowrap",
          }}
        >
          <span style={{ color: p.muted }}>
            from {before.toLocaleString("en-US")}
            {unit}
          </span>
          <span style={{ color: p.delta, fontWeight: 500 }}>
            {drop > 0 ? "−" : "+"}
            {Math.abs(drop)}%
          </span>
        </div>
      </div>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, interpolate } from "remotion";
import { ShaderDithering } from "@/components/remocn/shader-dithering";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const coverEnvelope = (p: number) =>
  interpolate(p, [0, 0.3, 0.65, 1], [0, 1, 1, 0], clampOpts);

const coverChildOpacity = (p: number, entering: boolean) =>
  entering
    ? interpolate(p, [0.58, 0.66], [0, 1], clampOpts)
    : interpolate(p, [0.28, 0.36], [1, 0], clampOpts);

type DitherShape = NonNullable<
  React.ComponentProps<typeof ShaderDithering>["shape"]
>;

export type DitherDissolveProps = {
  colorBack?: string;
  colorFront?: string;
  shape?: DitherShape;
  speed?: number;
};

const DitherDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<DitherDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colorBack = "#141318",
    colorFront = "#8f88ae",
    shape = "simplex",
    speed = 1.5,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const size = interpolate(p, [0, 1], [1.6, 2.8], clampOpts);

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: coverChildOpacity(p, entering) }}>
        {children}
      </AbsoluteFill>
      {entering ? (
        <AbsoluteFill
          style={{ opacity: coverEnvelope(p), pointerEvents: "none" }}
        >
          <ShaderDithering
            speed={speed}
            colorBack={colorBack}
            colorFront={colorFront}
            shape={shape}
            size={size}
          />
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export function ditherDissolve(
  props: DitherDissolveProps = {},
): TransitionPresentation<DitherDissolveProps> {
  return {
    component: DitherDissolvePresentation,
    props,
  };
}

"use client";

import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type DollyZoomColors = {
  background: string;
  wall: string;
  wallAlt: string;
  floor: string;
  floorAlt: string;
  line: string;
  light: string;
  door: string;
  figure: string;
};

export type DollyZoomProps = {
  /** Subject held at a constant size. Defaults to a standing figure. */
  children?: React.ReactNode;
  /** How far the camera dollies in while zooming out, 0 to 2. */
  intensity?: number;
  /** Play the move in reverse: background compresses toward the subject. */
  reverse?: boolean;
  colors?: Partial<DollyZoomColors>;
  /** Door color at the end of the corridor. Overrides `colors.door`. */
  doorColor?: string;
  /** Default figure color. Overrides `colors.figure`. */
  figureColor?: string;
  /** Corridor edge line color. Overrides `colors.line`. */
  lineColor?: string;
  speed?: number;
};

export const dollyZoomDefaults = {
  intensity: 1,
  reverse: false,
  colors: {
    background: "#0B0B0B",
    wall: "#1B1B1B",
    wallAlt: "#151515",
    floor: "#262626",
    floorAlt: "#1D1D1D",
    line: "#FFFFFF",
    light: "#FFFFFF",
    door: "#E5322D",
    figure: "#FFFFFF",
  } satisfies DollyZoomColors,
  speed: 1,
};

const START = 4;
const END = 36;
// Corridor in world units. Screen y points down, so the floor is positive.
const HALF_W = 2;
const CEIL = -1.3;
const FLOOR = 1.7;
const SUBJECT_Z = 6;
const DOOR_Z = 14;
const NEAR = 0.25;

type Vec = [number, number, number];

export function DollyZoom({
  children,
  intensity = dollyZoomDefaults.intensity,
  reverse = dollyZoomDefaults.reverse,
  colors: colorOverrides,
  doorColor,
  figureColor,
  lineColor,
  speed = dollyZoomDefaults.speed,
}: DollyZoomProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const baseColors = { ...dollyZoomDefaults.colors, ...colorOverrides };
  const colors = {
    ...baseColors,
    door: doorColor ?? baseColors.door,
    figure: figureColor ?? baseColors.figure,
    line: lineColor ?? baseColors.line,
  };
  const t = (frame * speed * 30) / fps;
  const move = interpolate(t, [START, END], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.45, 0, 0.3, 1),
  });
  const amount = reverse ? 1 - move : move;

  // Focal length tracks the subject distance so the subject never changes size.
  const k = height * 0.19;
  const d0 = SUBJECT_Z;
  const d1 = d0 / (1 + 1.7 * Math.max(0, intensity));
  const dist = d0 + (d1 - d0) * amount;
  const cam = SUBJECT_Z - dist;
  const f = k * dist;
  const cx = width / 2;
  const cy = height / 2;

  const project = ([x, y, z]: Vec) => {
    const depth = Math.max(NEAR, z - cam);
    return [cx + (f * x) / depth, cy + (f * y) / depth] as const;
  };
  const poly = (pts: Vec[]) =>
    pts
      .map(project)
      .map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`)
      .join(" ");

  const fog = (z: number) =>
    interpolate(z - cam, [1, DOOR_Z - cam], [1, 0.25], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const segments: React.ReactNode[] = [];
  // The corridor runs on behind the camera so its mouth never shows.
  const firstZ = Math.floor(cam);
  for (let z = DOOR_Z - 1; z >= firstZ; z--) {
    const z0 = Math.max(z, cam + NEAR);
    const z1 = z + 1;
    if (z1 <= z0) continue;
    const alt = z % 2 === 0;
    const L = -HALF_W;
    const R = HALF_W;
    segments.push(
      <g key={z}>
        <polygon
          points={poly([
            [L, FLOOR, z0],
            [R, FLOOR, z0],
            [R, FLOOR, z1],
            [L, FLOOR, z1],
          ])}
          fill={alt ? colors.floor : colors.floorAlt}
        />
        <polygon
          points={poly([
            [L, CEIL, z0],
            [R, CEIL, z0],
            [R, CEIL, z1],
            [L, CEIL, z1],
          ])}
          fill={colors.wallAlt}
        />
        <polygon
          points={poly([
            [L, CEIL, z0],
            [L, FLOOR, z0],
            [L, FLOOR, z1],
            [L, CEIL, z1],
          ])}
          fill={alt ? colors.wall : colors.wallAlt}
        />
        <polygon
          points={poly([
            [R, CEIL, z0],
            [R, FLOOR, z0],
            [R, FLOOR, z1],
            [R, CEIL, z1],
          ])}
          fill={alt ? colors.wall : colors.wallAlt}
        />
        <polygon
          points={poly([
            [-0.35, CEIL, z + 0.3],
            [0.35, CEIL, z + 0.3],
            [0.35, CEIL, z + 0.7],
            [-0.35, CEIL, z + 0.7],
          ])}
          fill={colors.light}
          opacity={0.75 * fog(z)}
        />
        {z >= cam + NEAR ? (
          <polygon
            points={poly([
              [L, CEIL, z],
              [R, CEIL, z],
              [R, FLOOR, z],
              [L, FLOOR, z],
            ])}
            fill="none"
            stroke={colors.line}
            strokeOpacity={0.32 * fog(z)}
            strokeWidth={Math.max(1, (f / (z - cam)) * 0.012)}
          />
        ) : null}
      </g>,
    );
  }

  const edges: Vec[][] = [
    [
      [-HALF_W, CEIL, -4],
      [-HALF_W, CEIL, DOOR_Z],
    ],
    [
      [HALF_W, CEIL, -4],
      [HALF_W, CEIL, DOOR_Z],
    ],
    [
      [-HALF_W, FLOOR, -4],
      [-HALF_W, FLOOR, DOOR_Z],
    ],
    [
      [HALF_W, FLOOR, -4],
      [HALF_W, FLOOR, DOOR_Z],
    ],
  ];

  const doorW = 0.85;
  const doorTop = FLOOR - 2.3;
  const [, floorY] = project([0, FLOOR, SUBJECT_Z]);
  const figureH = k * 1.75;

  return (
    <AbsoluteFill
      style={{ backgroundColor: colors.background, overflow: "hidden" }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <polygon
          points={poly([
            [-HALF_W, CEIL, DOOR_Z],
            [HALF_W, CEIL, DOOR_Z],
            [HALF_W, FLOOR, DOOR_Z],
            [-HALF_W, FLOOR, DOOR_Z],
          ])}
          fill={colors.wallAlt}
        />
        <polygon
          points={poly([
            [-doorW, doorTop, DOOR_Z],
            [doorW, doorTop, DOOR_Z],
            [doorW, FLOOR, DOOR_Z],
            [-doorW, FLOOR, DOOR_Z],
          ])}
          fill={colors.door}
        />
        {segments}
        {edges.map((edge, i) => {
          const [a, b] = edge.map((p) =>
            project([p[0], p[1], Math.max(p[2], cam + NEAR)]),
          );
          return (
            <line
              key={i}
              x1={a[0]}
              y1={a[1]}
              x2={b[0]}
              y2={b[1]}
              stroke={colors.line}
              strokeOpacity={0.45}
              strokeWidth={1.5}
            />
          );
        })}
      </svg>
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(ellipse at center, rgba(0,0,0,0) 45%, rgba(0,0,0,0.55) 100%)",
        }}
      />
      {children ? (
        <AbsoluteFill
          style={{ alignItems: "center", justifyContent: "center" }}
        >
          {children}
        </AbsoluteFill>
      ) : (
        <svg
          viewBox="0 0 60 175"
          height={figureH}
          style={{
            position: "absolute",
            left: cx - (figureH * 60) / 175 / 2,
            top: floorY - figureH,
          }}
          aria-hidden
        >
          <g fill={colors.figure}>
            <circle cx={30} cy={14} r={12} />
            <path d="M12 34 Q30 26 48 34 L54 96 Q54 102 48 102 L44 102 L42 172 L33 172 L30 108 L27 172 L18 172 L16 102 L12 102 Q6 102 6 96 Z" />
          </g>
        </svg>
      )}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: display } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface DominoRunProps {
  count?: number;
  value?: string;
  caption?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    small: "#47464D",
    large: "#BDBBB6",
    axis: "rgba(255,255,255,0.2)",
    // gradients.sh "halo": #fff4ec → #ffb36b → #e2457a → #3d4dff
    hero: ["#FFF4EC", "#FFB36B", "#E2457A"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    small: "#CFCDC7",
    large: "#55534F",
    axis: "rgba(18,18,20,0.22)",
    // gradients.sh "halo", warm end deepened to read on off-white
    hero: ["#F07A3A", "#E2457A", "#5A3FD8"],
    grain: 0.045,
  },
} as const;

const RATIO = 1.18;
const THICK = 0.13;
const GAP = 0.44;
const T0 = 14;
const TAU0 = 3.6;
const PUSH = 2.2;
const CHAIN = 1.7;
const DEG = 180 / Math.PI;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Domino {
  h: number;
  w: number;
  px: number;
  gap: number;
  start: number;
  tau: number;
  contact: number;
}

function layout(n: number) {
  const ds: Domino[] = [];
  let x = 0;
  let start = T0;
  for (let i = 0; i < n; i++) {
    const h = RATIO ** i;
    const w = THICK * h;
    const gap = GAP * h;
    const last = i === n - 1;
    const contact = last ? Math.PI / 2 : Math.asin(gap / h);
    const tau = TAU0 * Math.sqrt(h) * (last ? 2.1 : 1);
    ds.push({ h, w, px: x + w, gap, start, tau, contact });
    x += w + gap;
    start += tau;
  }
  const lastD = ds[n - 1];
  const extent = lastD.px + lastD.h;
  return { ds, extent };
}

function freeAngle(d: Domino, t: number, first: boolean, last: boolean) {
  const k = (t - d.start) / d.tau;
  if (k <= 0) return 0;
  const a = d.contact * k ** (first ? PUSH : last ? 2 : CHAIN);
  return Math.min(Math.PI / 2, a);
}

function poseAt(ds: Domino[], t: number) {
  const n = ds.length;
  const last = ds[n - 1];
  const angles = new Array<number>(n).fill(0);
  angles[n - 1] = freeAngle(last, t, n === 1, true);
  const impact = last.start + last.tau;
  if (t > impact) {
    const tb = t - impact;
    angles[n - 1] =
      Math.PI / 2 -
      (3.2 / DEG) * Math.abs(Math.sin((Math.PI * tb) / 7)) * Math.exp(-tb / 6);
  }
  for (let i = n - 2; i >= 0; i--) {
    const free = freeAngle(ds[i], t, i === 0, false);
    angles[i] = Math.min(free, restAngle(ds[i], ds[i + 1], angles[i + 1]));
  }
  return angles;
}

function topOver(ds: Domino[], angles: number[], from: number, to: number) {
  let top = 0;
  ds.forEach((d, i) => {
    const a = angles[i];
    const pts = [
      [0, 0],
      [-d.w, 0],
      [-d.w, d.h],
      [0, d.h],
    ].map(([x, y]) => [
      d.px + x * Math.cos(a) + y * Math.sin(a),
      -x * Math.sin(a) + y * Math.cos(a),
    ]);
    const xs = pts.map((q) => q[0]);
    if (Math.max(...xs) < from || Math.min(...xs) > to) return;
    for (const q of pts) top = Math.max(top, q[1]);
  });
  return top;
}

function restAngle(d: Domino, next: Domino, psi: number) {
  const s = d.gap + next.w;
  let best = Math.PI / 2;
  const arg = (s * Math.cos(psi) - next.w) / d.h;
  if (arg >= -1 && arg <= 1) {
    const phiA = psi + Math.asin(arg);
    const tipX = -s + d.h * Math.sin(phiA);
    const tipY = d.h * Math.cos(phiA);
    const cx = -next.w * Math.cos(psi);
    const cy = next.w * Math.sin(psi);
    const along = (tipX - cx) * Math.sin(psi) + (tipY - cy) * Math.cos(psi);
    if (along >= 0 && along <= next.h) best = Math.min(best, phiA);
  }
  const bx = s - next.w * Math.cos(psi);
  const by = next.w * Math.sin(psi);
  if (Math.hypot(bx, by) <= d.h && by > 0) {
    best = Math.min(best, Math.atan2(bx, by));
  }
  return best;
}

export function DominoRun({
  count = 13,
  value = "10×",
  caption = "Every push tips a bigger one.",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: DominoRunProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const n = Math.max(5, Math.min(24, Math.round(count)));
  const { ds, extent } = layout(n);
  const last = ds[n - 1];

  const groundY = height * 0.66;
  const avail = width * 0.84;
  const maxTall = groundY - height * 0.16;
  const S = Math.min(avail / extent, maxTall / last.h);
  const x0 = (width - extent * S) / 2;

  const angles = poseAt(ds, t);
  const impact = last.start + last.tau;
  const rest = poseAt(ds, impact + 400);

  const enter = interpolate(t, [0, 16], [0, 1], { ...CLAMP, easing: EASE_IO });
  const sw = Math.max(1, u);
  const haloId = `halo${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const drift = interpolate(t, [0, 165], [0, 1], CLAMP);
  const heroGradient = `linear-gradient(${172 - 8 * drift}deg, ${p.hero[0]} ${4 + 6 * drift}%, ${p.hero[1]} ${46 + 4 * drift}%, ${p.hero[2]} 96%)`;
  const chars = Math.max(1, value.length);
  const valueSize = Math.max(
    96 * u,
    Math.min(200 * u, (width * 0.36) / (chars * 0.56)),
  );
  const valueW = chars * 0.56 * valueSize;
  const valueRight = x0 + (last.px + last.h) * S;
  const clearTop = topOver(ds, rest, (valueRight - valueW - x0) / S, extent);
  const valueBottom = groundY - clearTop * S - 34 * u;
  const reveal = interpolate(t, [impact + 2, impact + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const capIn = interpolate(t, [impact + 12, impact + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill>
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, overflow: "visible" }}
          aria-hidden
        >
          <defs>
            <linearGradient id={haloId} x1="0" y1="1" x2="0" y2="0">
              <stop offset="0" stopColor={accent} />
              <stop offset="0.55" stopColor="#E2457A" />
              <stop offset="1" stopColor="#FFB36B" />
            </linearGradient>
          </defs>
          <line
            x1={width / 2 - width * 0.43 * enter}
            x2={width / 2 + width * 0.43 * enter}
            y1={groundY + sw / 2}
            y2={groundY + sw / 2}
            stroke={p.axis}
            strokeWidth={sw}
          />
          {ds.map((d, i) => {
            const isLast = i === n - 1;
            const appear = interpolate(t, [2 + i * 1.2, 14 + i * 1.2], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const fill = isLast
              ? `url(#${haloId})`
              : interpolateColors(
                  i / Math.max(1, n - 2),
                  [0, 1],
                  [p.small, p.large],
                );
            return (
              <g
                key={`d${d.h.toFixed(4)}`}
                opacity={appear}
                transform={`translate(${x0 + d.px * S} ${groundY + (1 - appear) * 10 * u}) rotate(${angles[i] * DEG})`}
              >
                <rect
                  x={-d.w * S}
                  y={-d.h * S}
                  width={d.w * S}
                  height={d.h * S}
                  rx={Math.min(3 * u, d.w * S * 0.3)}
                  fill={fill}
                />
              </g>
            );
          })}
        </svg>

        <div
          style={{
            position: "absolute",
            right: width - valueRight - valueSize * 0.03,
            bottom: height - valueBottom,
            fontFamily: display,
            fontWeight: 500,
            fontSize: valueSize,
            lineHeight: 0.74,
            letterSpacing: "-0.035em",
            backgroundImage: heroGradient,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            paddingTop: valueSize * 0.08,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
            opacity: reveal,
            filter:
              reveal < 0.99 ? `blur(${(1 - reveal) * 10 * u}px)` : undefined,
            transform: `translateY(${(1 - reveal) * 22 * u}px)`,
          }}
        >
          {value}
        </div>
        {caption ? (
          <div
            style={{
              position: "absolute",
              right: width - valueRight,
              top: groundY + 24 * u,
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
              fontFamily: display,
              fontWeight: 400,
              fontSize: 24 * u,
              letterSpacing: "-0.01em",
              color: p.muted,
              whiteSpace: "nowrap",
              opacity: capIn,
              transform: `translateY(${(1 - capIn) * 8 * u}px)`,
            }}
          >
            <span
              style={{
                width: 10 * u,
                height: 10 * u,
                borderRadius: "50%",
                background: accent,
              }}
            />
            {caption}
          </div>
        ) : null}
      </AbsoluteFill>
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

