const isRemocn = (label: string) => label.trim().toLowerCase() === "remocn";

/** gradients.sh "aurora" palette, laid along the hero series. */
const AURORA = {
  dark: ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"],
  light: ["#2E9C86", "#3FB5A3", "#5147B6", "#B25C9C"],
} as const;

function mix(a: string, b: string, k: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (v: number, sh: number) => (v >> sh) & 255;
  const c = (sh: number) =>
    Math.round(ch(pa, sh) + (ch(pb, sh) - ch(pa, sh)) * k)
      .toString(16)
      .padStart(2, "0");
  return `#${c(16)}${c(8)}${c(0)}`;
}

function sample(stops: readonly string[], k: number) {
  const x = Math.min(1, Math.max(0, k)) * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(x));
  return mix(stops[i], stops[i + 1], x - i);
}

export interface DotSortGroup {
  label: string;
  value: number;
}

export interface DotSortProps {
  groups?: DotSortGroup[];
  highlight?: number;
  caption?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_GROUPS: DotSortGroup[] = [
  { label: "remocn", value: 41 },
  { label: "Kitebase", value: 23 },
  { label: "Lumen", value: 17 },
  { label: "Fernway", value: 12 },
  { label: "Other", value: 7 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const FLIGHT = Easing.bezier(0.5, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    grays: ["#C9C7C2", "#8E8D93", "#69686F", "#4E4D53"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    grays: ["#3F3D3A", "#7A7873", "#A19F99", "#BDBBB4"],
    grain: 0.045,
  },
} as const;

const DOTS = 400;
const ROWS = 4;
const SORT_AT = 18;
const SWEEP = 24;
const JITTER = 9;
const FLY = 28;
const HIT = SORT_AT + SWEEP + JITTER + FLY + 2;

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function split(values: number[], total: number) {
  const sum = values.reduce((s, v) => s + Math.max(0, v), 0) || 1;
  const raw = values.map((v) => (Math.max(0, v) / sum) * total);
  const out = raw.map(Math.floor);
  let left = total - out.reduce((s, v) => s + v, 0);
  const order = raw
    .map((v, i) => ({ i, f: v - Math.floor(v) }))
    .sort((a, b) => b.f - a.f);
  for (const o of order) {
    if (left <= 0) break;
    out[o.i]++;
    left--;
  }
  return out;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function DotSort({
  groups = DEFAULT_GROUPS,
  highlight = 0,
  caption,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: DotSortProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const aurora = AURORA[theme];

  const list = groups.slice(0, 5);
  const hl = Math.min(Math.max(0, Math.round(highlight)), list.length - 1);
  const total = list.reduce((s, g) => s + Math.max(0, g.value), 0) || 1;
  const counts = split(
    list.map((g) => g.value),
    DOTS,
  );

  let gray = 0;
  const bands = list
    .map((g, i) => ({
      ...g,
      i,
      count: counts[i],
      pct: Math.round((Math.max(0, g.value) / total) * 100),
      color: i === hl ? accent : "",
    }))
    .sort((a, b) => b.value - a.value || a.i - b.i)
    .map((b) => ({
      ...b,
      color: b.i === hl ? accent : p.grays[Math.min(gray++, 3)],
      cols: Math.max(1, Math.ceil(b.count / ROWS)),
    }));
  const maxCols = Math.max(1, ...bands.map((b) => b.cols));

  const labelW = 132 * u;
  const labelGap = 24 * u;
  const heroGap = 84 * u;
  const heroW = 300 * u;
  const pitch = Math.min(
    13.5 * u,
    (W * 0.86 - labelW - labelGap - heroGap - heroW) / maxCols,
  );
  const r = pitch * 0.33;
  const barsW = maxCols * pitch;
  const totalW = labelW + labelGap + barsW + heroGap + heroW;
  const x0 = (W - totalW) / 2;
  const barX = x0 + labelW + labelGap;
  const heroX = barX + barsW + heroGap;
  const bandH = ROWS * pitch;
  const bandGap = 26 * u;
  const blockH = bands.length * bandH + (bands.length - 1) * bandGap;
  const y0 = (H - blockH) / 2;

  const dots = useMemo(() => {
    const out: {
      k: number;
      band: number;
      color: string;
      sx: number;
      sy: number;
      tx: number;
      ty: number;
      bend: number;
      start: number;
      phase: number;
      appear: number;
    }[] = [];
    let k = 0;
    bands.forEach((b, bi) => {
      for (let j = 0; j < b.count; j++) {
        const col = Math.floor(j / ROWS);
        const row = j % ROWS;
        const seed = k * 3.17 + 1.1;
        out.push({
          k,
          band: bi,
          color:
            b.i === hl
              ? sample(aurora, col / Math.max(1, b.cols - 1))
              : b.color,
          sx: W * (0.08 + 0.84 * hash(seed)),
          sy: H * (0.12 + 0.76 * hash(seed + 7.7)),
          tx: barX + (col + 0.5) * pitch,
          ty: y0 + bi * (bandH + bandGap) + (row + 0.5) * pitch,
          bend: (hash(seed + 3.3) - 0.5) * 120 * u,
          start: SORT_AT + (col / maxCols) * SWEEP + hash(seed + 5.5) * JITTER,
          phase: hash(seed + 9.1) * Math.PI * 2,
          appear: hash(seed + 2.4) * 10 - 6,
        });
        k++;
      }
    });
    const order = out
      .map((d) => d.k)
      .sort((a, b) => hash(a * 1.9 + 0.3) - hash(b * 1.9 + 0.3));
    return order.map((i) => out[i]);
  }, [bands, W, H, u, barX, pitch, y0, bandH, bandGap, maxCols, hl, aurora]);

  const dim = interpolate(t, [HIT, HIT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const land = interpolate(t, [HIT + 2, HIT + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [HIT + 2, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const capIn = interpolate(t, [HIT + 12, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, HIT + 50], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const scale = 0.975 + 0.035 * push;

  const circles: React.ReactNode[] = [];
  for (const d of dots) {
    const a = interpolate(t - d.appear, [0, 12], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    if (a <= 0) continue;
    const e = FLIGHT(interpolate(t, [d.start, d.start + FLY], [0, 1], CLAMP));
    const drift = 1 - e;
    const dx = Math.sin(t * 0.06 + d.phase) * 7 * u * drift;
    const dy = Math.cos(t * 0.05 + d.phase * 1.3) * 7 * u * drift;
    const mx = (d.sx + d.tx) / 2;
    const my = (d.sy + d.ty) / 2 + d.bend;
    const q = 1 - e;
    const x = q * q * d.sx + 2 * q * e * mx + e * e * d.tx + dx;
    const y = q * q * d.sy + 2 * q * e * my + e * e * d.ty + dy;
    const isHl = bands[d.band].i === hl;
    const fade = isHl ? 1 : 1 - 0.3 * dim;
    circles.push(
      <circle
        key={d.k}
        cx={x}
        cy={y}
        r={r * (0.86 + 0.14 * e)}
        fill={d.color}
        opacity={a * fade}
      />,
    );
  }

  const target = bands.find((b) => b.i === hl);
  const hero = target ? Math.round(target.pct * count) : 0;
  const capText = caption ?? (target ? `choose ${target.label}` : "");
  const capLogo = caption === undefined && target && isRemocn(target.label);
  const auroraCss = `linear-gradient(90deg, ${aurora.join(", ")})`;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{ transform: `scale(${scale})`, transformOrigin: "50% 50%" }}
      >
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {circles}
        </svg>

        {bands.map((b, bi) => {
          const done = SORT_AT + SWEEP * 0.4 + FLY + bi * 3;
          const a = interpolate(t, [done, done + 16], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const isHl = b.i === hl;
          const fade = isHl ? 1 : 1 - 0.35 * dim;
          return (
            <div
              key={b.label}
              style={{
                position: "absolute",
                left: x0,
                top: y0 + bi * (bandH + bandGap),
                width: labelW,
                height: bandH,
                display: "flex",
                flexDirection: "column",
                alignItems: "flex-end",
                justifyContent: "center",
                gap: 3 * u,
                opacity: a * fade,
                transform: `translateX(${(1 - a) * -10 * u}px)`,
                whiteSpace: "nowrap",
              }}
            >
              {isRemocn(b.label) ? (
                <RemocnLogo fontSize={20 * u} color={p.fg} />
              ) : (
                <span
                  style={{
                    fontFamily: sans,
                    fontWeight: 500,
                    fontSize: 18 * u,
                    letterSpacing: "-0.01em",
                    color: p.fg,
                    lineHeight: 1,
                  }}
                >
                  {b.label}
                </span>
              )}
              <span
                style={{
                  fontFamily: sans,
                  fontWeight: 400,
                  fontSize: 15 * u,
                  color: isHl ? aurora[0] : p.muted,
                  lineHeight: 1,
                }}
              >
                {b.pct}%
              </span>
            </div>
          );
        })}

        {target ? (
          <div
            style={{
              position: "absolute",
              left: heroX,
              top: 0,
              height: H,
              width: heroW,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
            }}
          >
            <div
              style={{
                fontFamily: serif,
                fontWeight: 400,
                fontSize: 184 * u,
                lineHeight: 0.9,
                letterSpacing: "-0.005em",
                color: p.fg,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
                opacity: land,
                filter:
                  land < 0.99 ? `blur(${(1 - land) * 8 * u}px)` : undefined,
                transform: `translateY(${(1 - land) * 20 * u}px)`,
              }}
            >
              {hero}
              <span
                style={{
                  fontSize: 104 * u,
                  marginLeft: 6 * u,
                  color: aurora[0],
                }}
              >
                %
              </span>
            </div>
            <div
              style={{
                marginTop: 18 * u,
                display: "flex",
                alignItems: "center",
                gap: 10 * u,
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 8 * u}px)`,
              }}
            >
              <span
                style={{
                  width: 10 * u,
                  height: 10 * u,
                  borderRadius: "50%",
                  background: auroraCss,
                  flexShrink: 0,
                }}
              />
              <span
                style={{
                  fontFamily: sans,
                  fontWeight: 400,
                  fontSize: 24 * u,
                  letterSpacing: "-0.01em",
                  color: p.muted,
                  whiteSpace: "nowrap",
                  display: "flex",
                  alignItems: "baseline",
                  gap: 8 * u,
                }}
              >
                {capLogo ? (
                  <>
                    choose
                    <RemocnLogo fontSize={25 * u} color={p.fg} />
                  </>
                ) : (
                  capText
                )}
              </span>
            </div>
          </div>
        ) : null}
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
          pointerEvents: "none",
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadDisplay } from "@remotion/google-fonts/Sora";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const DISPLAY = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface DotTypeProps {
  words?: string[];
  accentLast?: boolean;
  count?: number;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_WORDS = ["Think.", "Make.", "Ship."];

const FIELD = 14;
const FIRST = 32;
const STREAM = 34;
const HOLD = 22;
const FINAL_HOLD = 32;
const FLIGHT = 0.66;

const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const SOFT = Easing.bezier(0.45, 0, 0.2, 1);

function windows(wordCount: number) {
  const out: { start: number; len: number }[] = [];
  let t = FIELD;
  for (let i = 0; i < wordCount; i++) {
    const len = i === 0 ? FIRST : STREAM;
    out.push({ start: t, len });
    t += len + HOLD;
  }
  return out;
}

export const dotTypeLength = (wordCount = DEFAULT_WORDS.length) => {
  const w = windows(wordCount);
  const last = w[w.length - 1];
  return last.start + last.len + FINAL_HOLD;
};

function hash(n: number): number {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function valueNoise(x: number, y: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const h = (a: number, b: number) => hash(a * 57.3 + b * 131.9);
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const top = h(xi, yi) * (1 - u) + h(xi + 1, yi) * u;
  const bot = h(xi, yi + 1) * (1 - u) + h(xi + 1, yi + 1) * u;
  return top * (1 - v) + bot * v;
}

interface Pt {
  x: number;
  y: number;
}

interface WordSample {
  pts: Pt[];
  spacing: number;
  cy: number;
}

function hilbert(x: number, y: number, order = 128): number {
  let d = 0;
  let px = x;
  let py = y;
  for (let s = order / 2; s >= 1; s = Math.floor(s / 2)) {
    const rx = (px & s) > 0 ? 1 : 0;
    const ry = (py & s) > 0 ? 1 : 0;
    d += s * s * ((3 * rx) ^ ry);
    if (ry === 0) {
      if (rx === 1) {
        px = s - 1 - px;
        py = s - 1 - py;
      }
      const t = px;
      px = py;
      py = t;
    }
  }
  return d;
}

function hilbertOrder(pts: Pt[]): number[] {
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  for (const p of pts) {
    minX = Math.min(minX, p.x);
    minY = Math.min(minY, p.y);
    maxX = Math.max(maxX, p.x);
    maxY = Math.max(maxY, p.y);
  }
  const span = Math.max(maxX - minX, maxY - minY) || 1;
  const ox = minX - (span - (maxX - minX)) / 2;
  const oy = minY - (span - (maxY - minY)) / 2;
  return pts
    .map((p, i) => ({
      i,
      h: hilbert(
        Math.min(127, Math.floor(((p.x - ox) / span) * 128)),
        Math.min(127, Math.floor(((p.y - oy) / span) * 128)),
      ),
    }))
    .sort((m, n) => m.h - n.h)
    .map((m) => m.i);
}

function xOrder(pts: Pt[]): number[] {
  return pts
    .map((p, i) => ({ i, k: p.x + p.y * 1e-4 }))
    .sort((m, n) => m.k - n.k)
    .map((m) => m.i);
}

function sampleWords(
  words: string[],
  family: string,
  n: number,
  W: number,
  H: number,
): WordSample[] | null {
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  const setFont = (px: number) => {
    ctx.font = `500 ${px}px "${family}", sans-serif`;
    if ("letterSpacing" in ctx) {
      (
        ctx as CanvasRenderingContext2D & { letterSpacing: string }
      ).letterSpacing = `${(-0.03 * px).toFixed(2)}px`;
    }
  };
  setFont(100);
  let widest = 1;
  for (const w of words) widest = Math.max(widest, ctx.measureText(w).width);
  const cap = ctx.measureText("H").actualBoundingBoxAscent || 72;
  const fs = Math.min((W * 0.66 * 100) / widest, (H * 0.34 * 100) / cap);
  setFont(fs);
  const capPx = ctx.measureText("H").actualBoundingBoxAscent || fs * 0.72;
  const baseline = H / 2 + capPx / 2;
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";

  return words.map((word) => {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#fff";
    ctx.fillText(word, W / 2, baseline);
    const data = ctx.getImageData(0, 0, W, H).data;
    let x0 = W;
    let y0 = H;
    let x1 = 0;
    let y1 = 0;
    for (let y = 0; y < H; y += 2) {
      for (let x = 0; x < W; x += 2) {
        if (data[(y * W + x) * 4 + 3] > 127) {
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
      }
    }
    x0 = Math.max(0, x0 - 4);
    y0 = Math.max(0, y0 - 4);
    x1 = Math.min(W - 1, x1 + 4);
    y1 = Math.min(H - 1, y1 + 4);
    const grid = (s: number) => {
      const out: Pt[] = [];
      const rowH = s * 0.866;
      let row = 0;
      for (let y = y0 + rowH / 2; y < y1; y += rowH, row++) {
        const off = row % 2 ? s / 2 : 0;
        for (let x = x0 + off; x < x1; x += s) {
          const px = Math.round(x);
          const py = Math.round(y);
          if (data[(py * W + px) * 4 + 3] > 127) out.push({ x, y });
        }
      }
      return out;
    };
    let lo = 1;
    let hi = 40;
    for (let it = 0; it < 16; it++) {
      const mid = (lo + hi) / 2;
      if (grid(mid).length >= n) lo = mid;
      else hi = mid;
    }
    const pts = grid(lo);
    const picked: Pt[] = [];
    for (let j = 0; j < n; j++) {
      picked.push(pts[Math.floor(((j + 0.5) * pts.length) / n)] ?? pts[0]);
    }
    return { pts: picked, spacing: lo, cy: H / 2 };
  });
}

function fieldPoints(n: number, W: number, H: number) {
  const cols = Math.round(Math.sqrt((n * W) / H));
  const rows = Math.ceil(n / cols);
  const pts: (Pt & { b: number })[] = [];
  for (let i = 0; i < n; i++) {
    const c = i % cols;
    const r = Math.floor(i / cols);
    const x = ((c + 0.15 + hash(i * 3.1) * 0.7) / cols) * W;
    const y = ((r + 0.15 + hash(i * 5.7) * 0.7) / rows) * H;
    const nx = x / W - 0.5;
    const ny = y / H - 0.5;
    const vignette = Math.max(0, 1 - (nx * nx * 2.6 + ny * ny * 3.4));
    const b = valueNoise(x / (W * 0.14), y / (H * 0.2)) ** 1.4;
    pts.push({ x, y, b: (0.12 + b * 0.55) * (0.25 + 0.75 * vignette) });
  }
  return pts;
}

function Grain({ opacity, light }: { opacity: number; light: boolean }) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={`${uid}-grain`}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency={0.85}
          numOctaves={2}
          seed={7}
        />
        <feColorMatrix
          type="matrix"
          values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0"
        />
      </filter>
      <rect
        width="100%"
        height="100%"
        filter={`url(#${uid}-grain)`}
        opacity={opacity}
        style={{ mixBlendMode: light ? "multiply" : "screen" }}
      />
    </svg>
  );
}

/* gradients.sh "dither-field" palette, as a fill on the last word's dots. */
const DITHER = {
  dark: ["#2b3dd8", "#ff6a3d", "#ffd9a8"],
  light: ["#2b3dd8", "#ff6a3d", "#e0703b"],
} as const;

function circle(x: number, y: number, r: number) {
  const rs = r.toFixed(2);
  const d = (2 * r).toFixed(2);
  return `M${(x - r).toFixed(1)} ${y.toFixed(1)}a${rs} ${rs} 0 1 0 ${d} 0a${rs} ${rs} 0 1 0 -${d} 0`;
}

export function DotType({
  words = DEFAULT_WORDS,
  accentLast = true,
  count = 1500,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: DotTypeProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const isLight = theme === "light";
  const bg = isLight ? "#F5F4F0" : "#0A0A0B";
  const ink = isLight ? "#141416" : "#EEEEF0";
  const n = Math.max(300, Math.round(count));
  const list = words.length ? words : DEFAULT_WORDS;
  const key = list.join("\u0000");

  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("dot-type: font"));
  const released = useRef(false);

  useEffect(() => {
    let alive = true;
    const done = () => {
      if (alive) setReady(true);
    };
    DISPLAY.waitUntilDone()
      .then(() =>
        typeof document !== "undefined" && document.fonts
          ? document.fonts.load(`500 120px "${DISPLAY.fontFamily}"`)
          : undefined,
      )
      .then(done, done);
    return () => {
      alive = false;
    };
  }, []);

  useEffect(() => {
    if (ready && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  }, [ready, handle]);

  const model = useMemo(() => {
    if (!ready) return null;
    const samples = sampleWords(
      key.split("\u0000"),
      DISPLAY.fontFamily,
      n,
      W,
      H,
    );
    if (!samples) return null;
    const field = fieldPoints(n, W, H);
    const fieldIdx = hilbertOrder(field);
    const firstIdx = hilbertOrder(samples[0].pts);
    const states: Pt[][] = [];
    const s0: Pt[] = new Array(n);
    const s1: Pt[] = new Array(n);
    const fieldB: number[] = new Array(n);
    for (let r = 0; r < n; r++) {
      const dot = fieldIdx[r];
      s0[dot] = field[dot];
      fieldB[dot] = field[dot].b;
      s1[dot] = samples[0].pts[firstIdx[r]];
    }
    states.push(s0, s1);
    const rankOf: number[][] = [];
    for (let k = 1; k < samples.length; k++) {
      const prev = states[k];
      const prevOrder = xOrder(prev);
      const rank: number[] = new Array(n);
      prevOrder.forEach((dot, r) => {
        rank[dot] = r;
      });
      rankOf.push(rank);
      const target = samples[k].pts;
      const tOrder = xOrder(target);
      const next: Pt[] = new Array(n);
      for (let dot = 0; dot < n; dot++)
        next[dot] = target[tOrder[n - 1 - rank[dot]]];
      states.push(next);
    }
    return {
      states,
      fieldB,
      rankOf,
      spacing: samples.map((s) => s.spacing),
    };
  }, [ready, key, n, W, H]);

  const wins = windows(list.length);
  const total = dotTypeLength(list.length);
  const cx = W / 2;
  const cy = H / 2;

  const push = 1 + 0.035 * INOUT(Math.min(1, frame / total));
  const gid = `dt${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const sweep = Math.min(1, frame / total);
  const stops = DITHER[theme];

  const BUCKETS = 6;
  const inkPaths: string[][] = Array.from({ length: BUCKETS }, () => []);
  const accPaths: string[][] = Array.from({ length: BUCKETS }, () => []);

  if (model) {
    let k = 0;
    for (let i = 0; i < wins.length; i++) if (frame >= wins[i].start) k = i + 1;
    const { states, fieldB, rankOf, spacing } = model;
    const from = states[Math.max(0, k - 1)];
    const to = states[k];
    const win = wins[Math.max(0, k - 1)];
    const u = k === 0 ? 0 : (frame - win.start) / win.len;
    const lastK = list.length;
    const unit = Math.min(W, H) / 720;
    const rField = 1.7 * unit;
    const rWord = (s: number) => s * 0.37;
    const maxD = Math.hypot(W, H) / 2;

    for (let i = 0; i < n; i++) {
      const a = from[i];
      const b = to[i];
      let x: number;
      let y: number;
      let r: number;
      let bright: number;
      let acc = false;
      if (k === 0) {
        x = a.x + Math.sin(frame * 0.028 + i) * 2 * unit + frame * 0.35 * unit;
        y = a.y + Math.cos(frame * 0.022 + i * 1.3) * 2 * unit;
        r = rField * (0.5 + fieldB[i]);
        bright = fieldB[i];
      } else if (k === 1) {
        const ax =
          a.x + Math.sin(FIELD * 0.028 + i) * 2 * unit + FIELD * 0.35 * unit;
        const ay = a.y + Math.cos(FIELD * 0.022 + i * 1.3) * 2 * unit;
        const d = Math.hypot(ax - cx, ay - cy) / maxD;
        const delay = Math.min(1, d * 0.8 + hash(i * 9.1) * 0.2) * (1 - FLIGHT);
        const t = Math.max(0, Math.min(1, (u - delay) / FLIGHT));
        const e = INOUT(t);
        const dx = b.x - ax;
        const dy = b.y - ay;
        const curl = (0.22 + hash(i * 4.3) * 0.14) * Math.sin(Math.PI * e);
        x = ax + dx * e - dy * curl;
        y = ay + dy * e + dx * curl;
        r = rField * (0.5 + fieldB[i]) * (1 - e) + rWord(spacing[0]) * e;
        bright = fieldB[i] + (1 - fieldB[i]) * e;
        acc = accentLast && lastK === 1 && e > 0.92;
      } else {
        const rank = rankOf[k - 2][i] / n;
        const delay =
          Math.min(1, (1 - rank) * 0.82 + hash(i * 7.7) * 0.18) * (1 - FLIGHT);
        const t = Math.max(0, Math.min(1, (u - delay) / FLIGHT));
        const e = SOFT(t);
        const lift = Math.sin(Math.PI * e);
        const side = a.y < cy ? -1 : 1;
        const lane = 0.78 + hash(i * 3.3) * 0.44;
        const theta = Math.PI * e;
        const ox = cx + Math.cos(theta) * W * 0.36 * (0.9 + lane * 0.1);
        const oy = cy + side * Math.sin(theta) * H * 0.29 * lane;
        x = (a.x + (b.x - a.x) * e) * (1 - lift) + ox * lift;
        y = (a.y + (b.y - a.y) * e) * (1 - lift) + oy * lift;
        r =
          (rWord(spacing[k - 2]) * (1 - e) + rWord(spacing[k - 1]) * e) *
          (1 - lift * 0.3);
        bright = 1 - lift * 0.35;
        acc = accentLast && k === lastK && e > 0.9;
      }
      const sx = cx + (x - cx) * push;
      const sy = cy + (y - cy) * push;
      if (sx < -10 || sx > W + 10) continue;
      bright = Math.max(0, Math.min(1, bright));
      const bucket = Math.min(BUCKETS - 1, Math.floor(bright * BUCKETS));
      (acc ? accPaths : inkPaths)[bucket].push(circle(sx, sy, r * push));
    }
  }

  return (
    <AbsoluteFill
      style={{
        background: isLight
          ? `radial-gradient(80% 75% at 50% 45%, #FBFAF7 0%, ${bg} 72%)`
          : `radial-gradient(80% 75% at 50% 45%, #121215 0%, ${bg} 72%)`,
        overflow: "hidden",
      }}
    >
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={gid}
            gradientUnits="userSpaceOnUse"
            colorInterpolation="linearRGB"
            x1={W * (0.2 - 0.04 * sweep)}
            y1={H * 0.36}
            x2={W * (0.8 - 0.04 * sweep)}
            y2={H * 0.64}
          >
            <stop offset="0" stopColor={accent} />
            <stop offset="0.18" stopColor={stops[0]} />
            <stop offset="0.66" stopColor={stops[1]} />
            <stop offset="1" stopColor={stops[2]} />
          </linearGradient>
        </defs>
        {inkPaths.map((segs, i) =>
          segs.length ? (
            <path
              key={`i${i}`}
              d={segs.join("")}
              fill={ink}
              opacity={0.22 + ((i + 1) / BUCKETS) * 0.78}
            />
          ) : null,
        )}
        {accPaths.map((segs, i) =>
          segs.length ? (
            <path
              key={`a${i}`}
              d={segs.join("")}
              fill={`url(#${gid})`}
              opacity={0.5 + ((i + 1) / BUCKETS) * 0.5}
            />
          ) : null,
        )}
      </svg>
      <Grain opacity={isLight ? 0.045 : 0.06} light={isLight} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Outfit";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const outfit = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface DoubleTakeProps {
  text?: string;
  focus?: string;
  cue?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2445E5", ink: "#FFFFFF", accent: "#FF8FB1" },
  light: { bg: "#FFFFFF", ink: "#2445E5", accent: "#E0457B" },
} as const;

const WGHT = 500;
const TRACK = -0.035;
const MEASURE_PX = 100;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_CRAWL = Easing.bezier(0.42, 0, 0.62, 1);
const EASE_REWIND = Easing.bezier(0.5, 0, 0.12, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const IN_LEN = 14;
const IN_STAGGER = 3;
const CRAWL_AT = 16;
const PER_WORD = 6.5;
const STOP_HOLD = 8;
const REWIND_LEN = 24;
const CLEAR_LEN = 12;
const MIN_HOLD = 26;

let measureCtx: CanvasRenderingContext2D | null = null;

function ctx2d() {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) throw new Error("double-take: no 2d context");
  measureCtx.font = `${WGHT} ${MEASURE_PX}px "${outfit.fontFamily}"`;
  return measureCtx;
}

function em(s: string) {
  return (
    ctx2d().measureText(s).width / MEASURE_PX + TRACK * Array.from(s).length
  );
}

function useFontsReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("double-take: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      outfit.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${outfit.fontFamily}"`),
      document.fonts.load(`400 100px "${outfit.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

interface Layout {
  words: { text: string; x: number; w: number; focus: boolean }[];
  lineW: number;
  focusX0: number;
  focusX1: number;
  baseline: number;
  cap: number;
}

function buildLayout(text: string, focus: string): Layout {
  const tokens: { text: string; start: number; end: number }[] = [];
  const re = /\S+/g;
  let m = re.exec(text);
  while (m) {
    tokens.push({ text: m[0], start: m.index, end: m.index + m[0].length });
    m = re.exec(text);
  }
  const needle = focus.trim().toLowerCase();
  let at = needle ? text.toLowerCase().indexOf(needle) : -1;
  let end = at + needle.length;
  if (at < 0) {
    const last = tokens[tokens.length - 1];
    at = last ? last.start : 0;
    end = last ? last.end : 0;
  }
  const space = em(" ");
  let x = 0;
  const words = tokens.map((tk) => {
    const w = em(tk.text);
    const out = {
      text: tk.text,
      x,
      w,
      focus: tk.end > at && tk.start < end,
    };
    x += w + space;
    return out;
  });
  const lineW = em(tokens.map((tk) => tk.text).join(" "));
  const fw = words.filter((w) => w.focus);
  const focusX0 = fw.length ? fw[0].x : 0;
  const focusX1 = fw.length ? fw[fw.length - 1].x + fw[fw.length - 1].w : 0;

  const c = ctx2d();
  const fm = c.measureText("Hxg");
  const asc = fm.fontBoundingBoxAscent / MEASURE_PX;
  const desc = fm.fontBoundingBoxDescent / MEASURE_PX;
  const cap = c.measureText("H").actualBoundingBoxAscent / MEASURE_PX;
  const baseline = (1 - asc - desc) / 2 + asc;
  return { words, lineW, focusX0, focusX1, baseline, cap };
}

export function DoubleTake({
  text = "One person wrote this entire launch video over a single lunch break.",
  focus = "One person",
  cue = "Read that again.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: DoubleTakeProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontsReady();

  const layout = useMemo(
    () => (ready ? buildLayout(text, focus) : null),
    [ready, text, focus],
  );

  if (!layout) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const F = portrait ? W * 0.3 : H * 0.34;
  const mx = W * (portrait ? 0.08 : 0.07);
  const my = H * (portrait ? 0.07 : 0.1);
  const { words, lineW, focusX0, focusX1, baseline, cap } = layout;

  const crawlLen = Math.max(36, Math.min(120, words.length * PER_WORD));
  const stopAt = CRAWL_AT + crawlLen;
  const rewindAt = stopAt + STOP_HOLD;
  const landAt = rewindAt + REWIND_LEN;
  const motionEnd = landAt + CLEAR_LEN;
  const room = durationInFrames * speed - MIN_HOLD;
  const k = Math.max(0.55, Math.min(1, room / motionEnd));
  const t = (frame * speed) / k;

  const startLeft = mx;
  const endLeft = Math.min(mx, W - mx - lineW * F);
  const crawl = interpolate(t, [CRAWL_AT, stopAt], [0, 1], {
    ...CLAMP,
    easing: EASE_CRAWL,
  });
  const left = startLeft + (endLeft - startLeft) * crawl;
  const centreAtStop = (W / 2 - endLeft) / F;

  const focusW = focusX1 - focusX0;
  const sF = Math.max(0.4, Math.min(1.25, (W * 0.84) / (focusW * F)));
  const r = interpolate(t, [rewindAt, landAt], [0, 1], {
    ...CLAMP,
    easing: EASE_REWIND,
  });
  const zoom = interpolate(t, [rewindAt + REWIND_LEN * 0.35, landAt], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.45, 0, 0.2, 1),
  });
  const s = Math.exp(Math.log(sF) * zoom);
  const focusCentre = (focusX0 + focusX1) / 2;

  const rewinding = t >= rewindAt;
  const fx = rewinding
    ? centreAtStop + (focusCentre - centreAtStop) * r
    : (W / 2 - left) / F;

  const stripY = H * (portrait ? 0.52 : 0.55);
  const lineTop = stripY + (cap / 2 - baseline) * F;

  const tint = interpolate(t, [landAt - 10, landAt + 2], [0, 1], CLAMP);
  const clear = interpolate(t, [landAt - 6, landAt + CLEAR_LEN], [1, 0], {
    ...CLAMP,
    easing: Easing.bezier(0.4, 0, 0.6, 1),
  });
  const focusColor = interpolateColors(tint, [0, 1], [c.ink, hi]);

  const cueF = Math.max(16, (portrait ? W : H) * 0.07);
  const cueIn = interpolate(t, [stopAt + 2, stopAt + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const clipTop = (baseline - 1.0) * F;
  const clipH = 1.3 * F;
  const fade = (mx * 0.9).toFixed(1);
  const edgeMask = `linear-gradient(90deg, transparent 0px, #000 ${fade}px, #000 calc(100% - ${fade}px), transparent 100%)`;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {cue ? (
        <div
          style={{
            position: "absolute",
            left: mx,
            top: my - (baseline - cap) * cueF,
            height: cueF * 1.3,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              fontFamily: outfit.fontFamily,
              fontWeight: 400,
              fontSize: cueF,
              lineHeight: `${cueF}px`,
              letterSpacing: "-0.015em",
              whiteSpace: "pre",
              color: c.ink,
              transform: `translateY(${((1 - cueIn) * 1.2 * cueF).toFixed(2)}px)`,
            }}
          >
            {cue}
          </div>
        </div>
      ) : null}
      <div
        style={{
          position: "absolute",
          inset: 0,
          maskImage: edgeMask,
          WebkitMaskImage: edgeMask,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transformOrigin: "0 0",
            transform: `translate(${(W / 2).toFixed(2)}px, ${stripY.toFixed(2)}px) scale(${s.toFixed(5)}) translate(${(-fx * F).toFixed(2)}px, ${(-stripY).toFixed(2)}px)`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: -0.2 * F,
              top: lineTop + clipTop,
              width: (lineW + 0.6) * F,
              height: clipH,
              overflow: "hidden",
            }}
          >
            {words.map((w, i) => {
              const q = interpolate(
                t,
                [i * IN_STAGGER, i * IN_STAGGER + IN_LEN],
                [0, 1],
                { ...CLAMP, easing: EASE_OUT },
              );
              return (
                <div
                  key={`${i}-${w.text}`}
                  style={{
                    position: "absolute",
                    left: (w.x + 0.2) * F,
                    top: -clipTop,
                    height: F,
                    fontFamily: outfit.fontFamily,
                    fontWeight: WGHT,
                    fontSize: F,
                    lineHeight: `${F}px`,
                    letterSpacing: `${TRACK}em`,
                    whiteSpace: "pre",
                    color: w.focus ? focusColor : c.ink,
                    opacity: w.focus ? 1 : clear,
                    transform: `translateY(${((1 - q) * 1.15 * F).toFixed(2)}px)`,
                  }}
                >
                  {w.text}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

