export interface DropTimerProps {
  /** Small line over the countdown. */
  label?: string;
  /** Seconds on the clock when the shot opens; it counts down to zero. */
  from?: number;
  /** Frames per counted second (a film second, not a real one). */
  tick?: number;
  /** Unit captions under the three digit pairs. */
  units?: [string, string, string];
  /** What the clock smashes into at zero, set full-bleed. */
  live?: string;
  /** Brand over the payoff; "remocn" renders the real logo. */
  name?: string;
  /** Replaces the logo / name over the payoff. */
  logo?: React.ReactNode;
  /** Line under the payoff. */
  url?: string;
  /** The small "live" dot beside the url. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Big Shoulders 500 (fontTools, wght 500): cap 0.8; advances in em.
// Digits sit in fixed 0.46em cells (true tabular), colons in 0.24em cells.
const CAP = 0.8;
const CELL = 0.46;
const COLON = 0.24;
const ADV: Record<string, number> = {
  L: 0.359,
  I: 0.2175,
  V: 0.4405,
  E: 0.3845,
  N: 0.541,
  O: 0.457,
  W: 0.7235,
  " ": 0.212,
  D: 0.453,
  R: 0.4395,
  P: 0.4295,
  S: 0.438,
};
const LSB: Record<string, number> = { L: 0.056, D: 0.056, I: 0.056 };
const RSB: Record<string, number> = { W: 0.0295, N: 0.056, E: 0.0275 };
const TRACK_LIVE = -0.01;

function inkWidth(s: string, track: number) {
  const chars = Array.from(s);
  let w = 0;
  for (const ch of chars) w += ADV[ch] ?? 0.38;
  w += track * Math.max(0, chars.length - 1);
  const first = chars[0] ?? " ";
  const last = chars[chars.length - 1] ?? " ";
  return w - (LSB[first] ?? 0.04) - (RSB[last] ?? 0.04);
}

// Beat sheet (30fps, speed 1, from 5, tick 14):
//   0–6    the clock punches in at 00:00:05 from 1.3× and a blur
//   6–76   every 14 frames: a one-frame inverted flash, a hard cut to the next
//          digit and a new ground colour from the palette, a bump and a shake
//  76–84   00:00:00 holds on black, the digits lit in the gradient
//  84–90   smash: the clock rushes past the lens, LIVE NOW slams in full-bleed
//  92–     logo and url rise; poster hold, the gradient drifts
const START = 6;
const ZERO_HOLD = 8;

const SLAM = Easing.bezier(0.22, 1, 0.36, 1);
const RUSH = Easing.bezier(0.6, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Ground {
  bg: string;
  ink: string;
}

// Dark: gradients.sh "fluted" (bg #050507): #1d2a8f #2f7bff #ff7a3d #ffe2c4.
// Light: gradients.sh "ribbon" (bg #ffffff): #ff3d9a #ff8a3d #ffc83d #7a5cff.
const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    flash: "#F3F2EF",
    flashInk: "#0A0A0B",
    grounds: [
      {
        bg: "radial-gradient(70% 90% at 80% 10%, #1d2a8f 0%, transparent 70%), #0A0A0B",
        ink: "#F3F2EF",
      },
      {
        bg: "radial-gradient(80% 110% at 18% 0%, #8fb6ff 0%, transparent 62%), #2f7bff",
        ink: "#F3F2EF",
      },
      {
        bg: "radial-gradient(80% 110% at 85% 100%, #ffe2c4 0%, transparent 62%), #ff7a3d",
        ink: "#0A0A0B",
      },
      {
        bg: "radial-gradient(90% 110% at 10% 100%, #ffb98a 0%, transparent 60%), #ffe2c4",
        ink: "#0A0A0B",
      },
      {
        bg: "radial-gradient(80% 110% at 82% 0%, #2f7bff 0%, transparent 64%), #1d2a8f",
        ink: "#F3F2EF",
      },
    ] as Ground[],
    zero: "#050507",
    hero: ["#ffe2c4", "#ff7a3d", "#2f7bff"],
    haze: "#1d2a8f",
    hazeHi: "#2f7bff",
    hazeAlpha: 0.9,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    flash: "#121214",
    flashInk: "#F5F4F0",
    grounds: [
      {
        bg: "radial-gradient(70% 90% at 80% 10%, #ffe9f3 0%, transparent 70%), #F5F4F0",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(80% 110% at 18% 0%, #b8a6ff 0%, transparent 62%), #7a5cff",
        ink: "#F5F4F0",
      },
      {
        bg: "radial-gradient(80% 110% at 85% 100%, #ff8a3d 0%, transparent 62%), #ff3d9a",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(90% 110% at 10% 100%, #ff8a3d 0%, transparent 60%), #ffc83d",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(80% 110% at 82% 0%, #ffc83d 0%, transparent 64%), #ff8a3d",
        ink: "#121214",
      },
    ] as Ground[],
    zero: "#F5F4F0",
    hero: ["#7a5cff", "#ff3d9a", "#ff8a3d"],
    haze: "#ff3d9a",
    hazeHi: "#ffc83d",
    hazeAlpha: 0.22,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 2 frames, eases back over 8. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 8);
  return k * k;
}

/** A decaying shake that dies in 7 frames. Deterministic. */
function shake(d: number, amp: number, seed: number) {
  if (d < 0 || d > 7) return { x: 0, y: 0 };
  const k = (1 - d / 7) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.7 + seed),
    y: amp * 0.7 * k * Math.cos(d * 3.3 + seed * 1.7),
  };
}

const pad = (n: number) => String(Math.max(0, Math.floor(n))).padStart(2, "0");

export function DropTimer({
  label = "DROPS IN",
  from = 5,
  tick = 14,
  units = ["HRS", "MIN", "SEC"],
  live = "LIVE NOW",
  name = "remocn",
  logo,
  url = "remocn.dev",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: DropTimerProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const total = Math.max(1, Math.round(from));
  const zeroAt = START + total * tick;
  const smashAt = zeroAt + ZERO_HOLD;

  // ── Clock state ──
  const elapsed = Math.max(0, Math.floor((t - START) / tick));
  const left = Math.max(0, total - elapsed);
  const tickIdx = Math.min(total, elapsed);
  const lastTick = START + tickIdx * tick;
  const sinceTick = t - lastTick;
  const isFlash = t >= START + tick && sinceTick >= 0 && sinceTick < 1;
  const atZero = left === 0;
  const ground = c.grounds[tickIdx % c.grounds.length];

  const hh = Math.floor(left / 3600);
  const mm = Math.floor((left % 3600) / 60);
  const ss = left % 60;
  const clock = `${pad(hh)}:${pad(mm)}:${pad(ss)}`;

  // ── Clock layout: fixed cells, fitted to the frame width ──
  const cells = Array.from(clock).map((ch) => (ch === ":" ? COLON : CELL));
  const clockEm = cells.reduce((a, b) => a + b, 0);
  const fs = Math.min((0.9 * W) / clockEm, (0.56 * H) / CAP);
  const clockW = clockEm * fs;
  const clockX = (W - clockW) / 2;
  const capH = CAP * fs;
  const baseline = H * 0.5 + capH * 0.5 + 0.02 * H;
  let cx = clockX;
  const glyphs = Array.from(clock).map((ch, i) => {
    const mid = cx + (cells[i] * fs) / 2;
    cx += cells[i] * fs;
    return { ch, mid, i };
  });
  const pairMid = [0, 3, 6].map((i) => (glyphs[i].mid + glyphs[i + 1].mid) / 2);

  // ── Camera ──
  const enter = SLAM(ramp(t, 0, START));
  const enterScale = 1.3 - 0.3 * enter;
  const enterBlur = (1 - enter) * 16;
  let bump = 0;
  let sx = 0;
  let sy = 0;
  for (let k = 1; k <= total; k++) {
    const d = t - (START + k * tick);
    if (d < -1 || d > 12) continue;
    // hits grow as the clock runs out
    const g = 0.7 + (0.6 * k) / total;
    bump = Math.max(bump, g * kick(d));
    const s = shake(d, 6 * u * g, k * 1.3);
    sx += s.x;
    sy += s.y;
  }
  const smashD = t - smashAt;
  bump = Math.max(bump, 1.4 * kick(smashD - 4));
  const s3 = shake(smashD - 4, 12 * u, 4.4);
  sx += s3.x;
  sy += s3.y;
  const camScale = 1 + 0.04 * bump;

  // ── Smash ──
  const rush = RUSH(ramp(t, smashAt, 5));
  const clockScale = enterScale * (1 + 1.8 * rush);
  const clockBlur = enterBlur + 26 * rush;
  const clockOpacity = Math.min(ramp(t, 0, 2), 1 - ramp(t, smashAt + 2, 3));
  const liveP = SLAM(ramp(t, smashAt + 1, 7));
  const liveScale = 1.7 - 0.7 * liveP;
  const liveBlur = (1 - liveP) * 18;
  const liveOpacity = ramp(t, smashAt + 1, 2);
  const flashSmash = interpolate(
    t,
    [smashAt, smashAt + 1, smashAt + 5],
    [0, 1, 0],
    CLAMP,
  );
  const after = t >= smashAt + 1;
  const rise = (a: number) => SLAM(ramp(t, a, 16));
  const drift = ramp(t, smashAt, 70);
  const haze = SLAM(ramp(t, smashAt + 1, 24));

  // ── Payoff layout ──
  const liveEm = inkWidth(live.toUpperCase(), TRACK_LIVE);
  const liveFs = Math.min((0.9 * W) / liveEm, (0.5 * H) / CAP);
  const liveCap = CAP * liveFs;
  const liveBase = H * 0.535 + liveCap * 0.5;

  const bgNow = after
    ? c.zero
    : isFlash
      ? c.flash
      : atZero
        ? c.zero
        : ground.bg;
  const digitInk = isFlash ? c.flashInk : ground.ink;
  const labelInk = isFlash ? c.flashInk : atZero ? c.ink : ground.ink;

  const heroGrad = `${uid}hero`;
  const zeroGrad = `${uid}zero`;

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, background: bgNow }} />
      {/* Payoff haze rising from the bottom. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: after ? haze * c.hazeAlpha : 0,
          background: [
            `radial-gradient(60% 50% at ${44 + 10 * drift}% ${122 - 18 * haze}%, ${c.hazeHi} 0%, transparent 70%)`,
            `radial-gradient(95% 70% at 50% ${130 - 16 * haze}%, ${c.haze} 0%, transparent 76%)`,
          ].join(", "),
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${sx}px, ${sy}px) scale(${camScale})`,
          transformOrigin: "50% 50%",
        }}
      >
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{ position: "absolute", inset: 0, overflow: "visible" }}
          role="img"
          aria-label={after ? `${live} — ${name} ${url}` : `${label} ${clock}`}
        >
          <defs>
            <linearGradient
              id={zeroGrad}
              gradientUnits="userSpaceOnUse"
              x1={clockX}
              y1={baseline - capH}
              x2={clockX + clockW}
              y2={baseline}
            >
              <stop offset="0" stopColor={c.hero[2]} />
              <stop offset="0.55" stopColor={c.hero[1]} />
              <stop offset="1" stopColor={c.hero[0]} />
            </linearGradient>
            <linearGradient
              id={heroGrad}
              gradientUnits="userSpaceOnUse"
              x1={W * (0.02 + 0.06 * drift)}
              y1={liveBase}
              x2={W * (0.92 + 0.06 * drift)}
              y2={liveBase - liveCap}
            >
              <stop offset="0" stopColor={c.hero[1]} />
              <stop offset="0.62" stopColor={c.hero[0]} />
              <stop offset="1" stopColor={c.hero[0]} />
            </linearGradient>
          </defs>

          {/* The clock. */}
          {t < smashAt + 6 ? (
            <g
              style={{
                transform: `scale(${clockScale})`,
                transformOrigin: `${W / 2}px ${baseline - capH / 2}px`,
                filter:
                  clockBlur > 0.2 ? `blur(${clockBlur * u}px)` : undefined,
              }}
              opacity={clockOpacity}
            >
              <text
                x={W / 2}
                y={baseline - capH - 0.075 * H}
                textAnchor="middle"
                fontFamily={display}
                fontWeight={500}
                fontSize={0.068 * H}
                fill={labelInk}
                style={{ letterSpacing: "0.08em" }}
              >
                {label}
              </text>
              <g
                fontFamily={display}
                fontWeight={500}
                fontSize={fs}
                textAnchor="middle"
                fill={atZero && !isFlash ? `url(#${zeroGrad})` : digitInk}
              >
                {glyphs.map((g) => (
                  <text
                    key={g.i}
                    x={g.mid}
                    y={g.ch === ":" ? baseline - 0.035 * fs : baseline}
                  >
                    {g.ch}
                  </text>
                ))}
              </g>
              <g
                fontFamily={mono}
                fontWeight={400}
                fontSize={0.03 * H}
                textAnchor="middle"
                fill={labelInk}
                opacity={0.8}
                style={{ letterSpacing: "0.14em" }}
              >
                {units.map((un, i) => (
                  <text key={un} x={pairMid[i]} y={baseline + 0.075 * H}>
                    {un}
                  </text>
                ))}
              </g>
            </g>
          ) : null}

          {/* LIVE NOW, full-bleed. */}
          {after ? (
            <text
              x={W / 2}
              y={liveBase}
              textAnchor="middle"
              fontFamily={display}
              fontWeight={500}
              fontSize={liveFs}
              fill={`url(#${heroGrad})`}
              opacity={liveOpacity}
              style={{
                letterSpacing: `${TRACK_LIVE}em`,
                transform: `scale(${liveScale})`,
                transformOrigin: `${W / 2}px ${liveBase - liveCap / 2}px`,
                filter: liveBlur > 0.2 ? `blur(${liveBlur * u}px)` : undefined,
              }}
            >
              {live.toUpperCase()}
            </text>
          ) : null}
        </svg>

        {/* Brand over the payoff. */}
        {after ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: liveBase - liveCap - 0.135 * H,
              display: "flex",
              justifyContent: "center",
              opacity: rise(smashAt + 7),
              transform: `translateY(${(1 - rise(smashAt + 7)) * 14 * u}px)`,
            }}
          >
            {logo ??
              (name.trim().toLowerCase() === "remocn" ? (
                <RemocnLogo fontSize={0.064 * H} color={c.ink} />
              ) : (
                <span
                  style={{
                    fontFamily: display,
                    fontWeight: 500,
                    fontSize: 0.064 * H,
                    color: c.ink,
                    lineHeight: 1,
                  }}
                >
                  {name}
                </span>
              ))}
          </div>
        ) : null}

        {/* Url under the payoff. */}
        {after ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: liveBase + 0.075 * H,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: 12 * u,
              fontFamily: mono,
              fontWeight: 400,
              fontSize: 0.032 * H,
              letterSpacing: "0.04em",
              color: c.ink,
              lineHeight: 1,
              opacity: rise(smashAt + 11),
              transform: `translateY(${(1 - rise(smashAt + 11)) * 14 * u}px)`,
            }}
          >
            <div
              style={{
                width: 0.016 * H,
                height: 0.016 * H,
                borderRadius: 99,
                background: accent,
                opacity:
                  0.8 + 0.2 * Math.cos(((t - smashAt) / 22) * Math.PI * 2),
              }}
            />
            {url}
          </div>
        ) : null}
      </div>

      {/* The smash flash. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: c.flash,
          opacity: flashSmash,
        }}
      />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont as loadInstrument } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadJetBrains } from "@remotion/google-fonts/JetBrainsMono";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const instrument = loadInstrument("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const jetbrains = loadJetBrains("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const FILL = Easing.bezier(0.83, 0, 0.17, 1);
const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const MORPH = { damping: 200 };

const B = {
  zone: -8,
  title: -2,
  fly: 6,
  hover: 30,
  drop: 54,
  collapse: 60,
  info: 72,
  progress: 78,
  done: 114,
  end: 162,
};

const ramp = (f: number, start: number, dur: number, easing = ENTER) =>
  interpolate(f, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

function FileTile({
  kind,
  accent,
  w,
}: {
  kind: string;
  accent: string;
  w: number;
}) {
  const h = w * 1.26;
  const fold = w * 0.27;
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <svg
        width={w}
        height={h}
        viewBox={`0 0 ${w} ${h}`}
        style={{ position: "absolute", inset: 0, overflow: "visible" }}
        aria-hidden
      >
        <defs>
          <linearGradient id="du-paper" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#ffffff" />
            <stop offset="1" stopColor="#eceef6" />
          </linearGradient>
        </defs>
        <path
          d={`M ${w * 0.1} 0 H ${w - fold} L ${w} ${fold} V ${h - w * 0.1} Q ${w} ${h} ${w * 0.9} ${h} H ${w * 0.1} Q 0 ${h} 0 ${h - w * 0.1} V ${w * 0.1} Q 0 0 ${w * 0.1} 0 Z`}
          fill="url(#du-paper)"
          stroke="rgba(20,24,48,0.1)"
        />
        <path
          d={`M ${w - fold} 0 V ${fold * 0.72} Q ${w - fold} ${fold} ${w - fold * 0.72} ${fold} H ${w} Z`}
          fill="#d7dbea"
        />
        {[0.3, 0.4, 0.5, 0.6].map((y, i) => (
          <rect
            key={y}
            x={w * 0.16}
            y={h * y}
            width={w * (i === 3 ? 0.36 : i === 0 ? 0.4 : 0.62)}
            height={w * 0.045}
            rx={w * 0.022}
            fill={i === 0 ? "#b9bfd6" : "#d9dce8"}
          />
        ))}
      </svg>
      <div
        style={{
          position: "absolute",
          left: w * 0.12,
          bottom: w * 0.12,
          height: w * 0.24,
          padding: `0 ${w * 0.08}px`,
          borderRadius: w * 0.06,
          background: accent,
          color: "#fff",
          fontFamily: jetbrains.fontFamily,
          fontSize: w * 0.15,
          display: "flex",
          alignItems: "center",
          letterSpacing: "0.04em",
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.3)",
        }}
      >
        {kind}
      </div>
    </div>
  );
}

export interface DropUploadProps {
  theme?: "dark" | "light";
  accent?: string;
  title?: string;
  fileName?: string;
  fileKind?: string;
  fileSize?: string;
  hint?: string;
  history?: { name: string; kind: string; size: string; ago: string }[];
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

export function DropUpload({
  theme = "dark",
  accent = "#3B5BFD",
  title = "Drop in your launch notes",
  fileName = "launch-notes.md",
  fileKind = "MD",
  fileSize = "2.4 MB",
  hint = "MD, PDF or ZIP · up to 50 MB",
  history = [
    {
      name: "changelog-2.0.pdf",
      kind: "PDF",
      size: "1.1 MB",
      ago: "4 min ago",
    },
    { name: "press-kit.zip", kind: "ZIP", size: "18.6 MB", ago: "12 min ago" },
  ],
  ground,
  groundParams,
}: DropUploadProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const dark = theme === "dark";
  const portrait = height > width * 1.2;
  const stageW = portrait ? 760 : 1280;
  const stageH = portrait ? 1351 : 720;
  const sc = width / stageW;

  const ink = dark ? "#f1f2fb" : "#151824";
  const soft = dark ? "rgba(225,228,250,0.7)" : "rgba(21,24,36,0.66)";
  const muted = dark ? "rgba(225,228,250,0.46)" : "rgba(21,24,36,0.44)";
  const dash = dark ? "rgba(225,228,250,0.34)" : "rgba(21,24,36,0.26)";
  const base = dark ? "#11141f" : "#ffffff";
  const rowShadow = (k: number) =>
    dark
      ? `0 0 0 1px rgba(255,255,255,${0.08 * k}), 0 40px 90px -24px rgba(0,2,14,${0.7 * k})`
      : `0 0 0 1px rgba(20,24,48,${0.07 * k}), 0 1px 3px rgba(20,24,48,${0.06 * k}), 0 36px 80px -24px rgba(20,30,70,${0.22 * k})`;
  const accentMix = (pct: number, base: string) =>
    `color-mix(in oklab, ${accent} ${pct}%, ${base})`;

  const zoneW = portrait ? 564 : 760;
  const zoneH = portrait ? 440 : 320;
  const rowW = portrait ? 564 : 760;
  const rowH = 104;
  const cx = stageW / 2;
  const cy = portrait ? 640 : 412;
  const titleSize = portrait ? 50 : 60;
  const titleGap = portrait ? 56 : 44;

  const zoneIn = spring({ frame: frame - B.zone, fps, config: HEAVY });
  const titleIn = ramp(frame, B.title, 15);
  const collapse = spring({ frame: frame - B.collapse, fps, config: MORPH });
  const highlight =
    ramp(frame, B.hover - 8, 12) * (1 - ramp(frame, B.collapse, 8, EXIT));
  const breathe =
    Math.sin(((frame - B.hover) / 22) * Math.PI * 2) * 0.012 * highlight;
  const dropHit = spring({ frame: frame - B.drop - 6, fps, config: CHIP });
  const dropPunch =
    0.03 *
    Math.sin(Math.PI * Math.min(1, dropHit)) *
    (1 - ramp(frame, B.drop + 14, 6));

  const solid = ramp(frame, B.collapse - 2, 14);
  const tint = accentMix(Math.round(12 * highlight), "transparent");
  const radius = mix(24, 20, collapse);
  const zW = mix(zoneW, rowW, collapse);
  const zH = mix(zoneH, rowH, collapse);
  const zL = cx - zW / 2;
  const zT = cy - zH / 2;

  const startX = portrait ? cx + 260 : cx + 560;
  const startY = portrait ? cy + 600 : cy + 360;
  const ctrlX = portrait ? cx + 300 : cx + 300;
  const ctrlY = portrait ? cy - 200 : cy - 300;
  const hoverX = cx + 30;
  const hoverY = cy - (portrait ? 84 : 66);
  const flyT = (f: number) =>
    spring({ frame: f - B.fly, fps, config: CARD, durationInFrames: 26 });
  const bez = (t: number, a: number, c: number, b: number) =>
    (1 - t) * (1 - t) * a + 2 * (1 - t) * t * c + t * t * b;
  const p = flyT(frame);
  const pPrev = flyT(frame - 1);
  let tx = bez(p, startX, ctrlX, hoverX);
  let ty = bez(p, startY, ctrlY, hoverY);
  const speed = Math.hypot(
    tx - bez(pPrev, startX, ctrlX, hoverX),
    ty - bez(pPrev, startY, ctrlY, hoverY),
  );
  const hoverAmt = ramp(frame, B.hover - 4, 10) * (1 - ramp(frame, B.drop, 8));
  tx += Math.sin((frame - B.hover) / 7) * 5 * hoverAmt;
  ty += Math.cos((frame - B.hover) / 9) * 5 * hoverAmt;
  let rot = mix(28, -7, p) + Math.sin((frame - B.hover) / 10) * 2.5 * hoverAmt;
  let lift = mix(1.2, 0.74, p);
  const drop = ramp(frame, B.drop, 8, EXIT);
  lift *= mix(1, 0.84, drop);
  ty += 16 * drop;
  rot = mix(rot, -3, drop);
  const tileW = 112;
  const iconW = 48;
  const iconX = cx - rowW / 2 + 26 + iconW / 2;
  const iconY = cy;
  const toRow = spring({ frame: frame - B.collapse - 2, fps, config: MORPH });
  tx = mix(tx, iconX, toRow);
  ty = mix(ty, iconY, toRow);
  rot = mix(rot, 0, toRow);
  const tileScale = mix(lift, iconW / tileW, toRow);
  const tileBlur = Math.min(6, speed * 0.1);
  const shadowAmt = (1 - drop * 0.7) * (1 - toRow);

  const zoneContent = 1 - ramp(frame, B.collapse - 2, 8, EXIT);
  const info = ramp(frame, B.info, 12);
  const prog = interpolate(frame, [B.progress, B.done - 4], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: FILL,
  });
  const done = spring({ frame: frame - B.done, fps, config: CHIP });
  const doneIn = ramp(frame, B.done, 6);
  const pct = Math.round(prog * 100);

  const camIn = spring({ frame: frame + 8, fps, config: HEAVY });
  const rowFocus = spring({ frame: frame - B.collapse, fps, config: HEAVY });
  const rotX = mix(18, 4, camIn) - 2.5 * rowFocus;
  const rotY = mix(14, 4, camIn) - 4 * rowFocus;
  const push =
    mix(0.9, 1, camIn) +
    0.025 * ramp(frame, 0, B.end, Easing.linear) +
    (portrait ? 0.06 : 0.26) * rowFocus;
  const titleTop0 = cy - zoneH / 2 - titleGap - titleSize * 1.05;
  const titleTop1 = cy - rowH / 2 - (portrait ? 44 : 34) - titleSize * 1.05;
  const titleTop = mix(titleTop0, titleTop1, rowFocus);
  const histH = 84;
  const histGap = 14;
  const shown = portrait ? history : [];
  const listBottom = cy + rowH / 2 + shown.length * (histH + histGap);
  const groupMid = (titleTop1 + listBottom) / 2;
  const camY = rowFocus * (groupMid - cy) * 0.9;

  const resolvedGround: GshPresetId =
    ground ?? (dark ? "earthshine" : "paper-crease");
