                <span
                  style={{
                    fontFamily: jetbrains.fontFamily,
                    fontSize: 17,
                    color: muted,
                  }}
                >
                  {h.size}
                </span>
                <div style={{ flex: 1 }} />
                <span style={{ fontSize: 17, color: muted }}>{h.ago}</span>
