function niceMax(v: number) {
  const steps = [5, 10, 20, 25, 50, 100, 200, 250, 500, 1000];
  for (const s of steps) if (v <= s) return s;
  return Math.ceil(v / 1000) * 1000;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function DumbbellShift({
  rows = DEFAULT_ROWS,
  beforeLabel = "Before",
  afterLabel = "With remocn",
  summaryCaption,
  max,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: DumbbellShiftProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];

  const list = rows.slice(0, 7);
  const n = list.length;
  const deltas = list.map((r) => r.after - r.before);
  const order = list
    .map((_, i) => i)
    .sort((a, b) => deltas[b] - deltas[a] || a - b);
  const rank = list.map((_, i) => order.indexOf(i));
  const winner = order[0] ?? 0;
  const top = Math.max(1, ...list.map((r) => Math.max(r.before, r.after)));
  const scaleMax = max ?? niceMax(top * 1.04);

  const m = width * 0.08;
  const rowsTop = height * 0.12;
  const rowsBottom = height * 0.9;
  const rowH = (rowsBottom - rowsTop) / Math.max(1, n);
  const ax0 = width * 0.27;
  const ax1 = width * 0.705;
  const heroX = width * 0.74;
  const r = Math.min(15 * u, rowH * 0.17);
  const barH = r * 0.78;
  const gid = `db${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const xOf = (v: number) =>
    ax0 + (Math.max(0, Math.min(v, scaleMax)) / scaleMax) * (ax1 - ax0);

  const sortK = interpolate(t, [SORT[0], SORT[1]], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const dim = interpolate(t, [HERO, HERO + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const grow = interpolate(t, [HERO, HERO + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const capIn = interpolate(t, [HERO + 12, HERO + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const noteOut = interpolate(t, [SORT[0] - 8, SORT[0] + 2], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [0, HERO + 40], [1.025, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const items = list.map((row, i) => {
    const enter = interpolate(
      t,
      [2 + i * ENTER_STAGGER, 20 + i * ENTER_STAGGER],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const s0 = SLIDE_START + i * SLIDE_STAGGER;
    const slide = interpolate(t, [s0, s0 + SLIDE_DUR], [0, 1], {
      ...CLAMP,
      easing: EASE_SLIDE,
    });
    const deltaIn = interpolate(
      t,
      [s0 + SLIDE_DUR - 8, s0 + SLIDE_DUR + 8],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
    const pos = i + (rank[i] - i) * sortK;
    const y = rowsTop + rowH * (pos + 0.5);
    const xb = xOf(row.before);
    const xa = xOf(row.after);
    const x = xb + (xa - xb) * slide;
    const isWin = i === winner;
    const fade = isWin ? 1 : 1 - 0.4 * dim;
    const tone = isWin
      ? p.fluted[3]
      : interpolateColors(dim, [0, 1], [p.fluted[3], p.muted]);
    return { row, i, enter, slide, deltaIn, y, xb, xa, x, isWin, fade, tone };
  });
  const duck = items.map((it) => {
    let d = Number.POSITIVE_INFINITY;
    for (const o of items) if (o !== it) d = Math.min(d, Math.abs(o.y - it.y));
    return it.isWin
      ? 1
      : interpolate(d, [rowH * 0.3, rowH * 0.65], [0, 1], CLAMP);
  });

  const win = items[winner];
  const heroText = win
    ? `${deltas[winner] >= 0 ? "+" : "−"}${Math.abs(Math.round(deltas[winner] * win.slide))}`
    : "";
  const deltaText = (v: number) => `${v >= 0 ? "+" : "−"}${Math.abs(v)}`;
  const winCaption =
    summaryCaption ?? (win ? `${win.row.label.toLowerCase()} a month` : "");

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{ transform: `scale(${push})`, transformOrigin: "50% 50%" }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient id={gid} x1={0} y1={0} x2={1} y2={0}>
              <stop offset={0} stopColor={p.fluted[0]} />
              <stop offset={0.38} stopColor={p.fluted[1]} />
              <stop offset={0.78} stopColor={p.fluted[2]} />
              <stop offset={1} stopColor={p.fluted[3]} />
            </linearGradient>
          </defs>
          {items.map((it) => (
            <g key={it.row.label} opacity={it.fade}>
              <line
                x1={ax0}
                x2={ax0 + (ax1 - ax0) * it.enter}
                y1={it.y}
                y2={it.y}
                stroke={p.guide}
                strokeWidth={Math.max(1, u)}
              />
              {it.slide > 0 && Math.abs(it.x - it.xb) > 0.5 ? (
                <>
                  <rect
                    x={Math.min(it.xb, it.x)}
                    y={it.y - (barH * (it.isWin ? 1 + 0.35 * dim : 1)) / 2}
                    width={Math.abs(it.x - it.xb)}
                    height={barH * (it.isWin ? 1 + 0.35 * dim : 1)}
                    rx={(barH * (it.isWin ? 1 + 0.35 * dim : 1)) / 2}
                    fill={`url(#${gid})`}
                    opacity={it.isWin ? 1 : 1 - dim}
                  />
                  {it.isWin ? null : (
                    <rect
                      x={Math.min(it.xb, it.x)}
                      y={it.y - barH / 2}
                      width={Math.abs(it.x - it.xb)}
                      height={barH}
                      rx={barH / 2}
                      fill={p.muted}
                      opacity={0.42 * dim}
                    />
                  )}
                </>
              ) : null}
              {it.slide > 0 ? (
                <circle
                  cx={it.x}
                  cy={it.y}
                  r={r}
                  fill={it.tone}
                  opacity={interpolate(it.slide, [0, 0.12], [0, 1], CLAMP)}
                />
              ) : null}
              {it.isWin ? (
                <circle
                  cx={it.x}
                  cy={it.y}
                  r={r + (4 + 6 * dim) * u}
                  fill="none"
                  stroke={accent}
                  strokeWidth={1.5 * u}
                  opacity={dim * 0.9}
                />
              ) : null}
              <circle
                cx={it.xb}
                cy={it.y}
                r={r * (0.6 + 0.4 * it.enter)}
                fill={p.dot}
                opacity={it.enter}
              />
            </g>
          ))}
        </svg>

        {items.map((it) => (
          <div
            key={it.row.label}
            style={{
              position: "absolute",
              left: m,
              top: it.y,
              transform: `translateY(-50%) translateX(${(1 - it.enter) * -10 * u}px)`,
              fontFamily: sans,
              fontWeight: it.isWin && dim > 0.5 ? 500 : 400,
              fontSize: 24 * u,
              letterSpacing: "-0.015em",
              color: p.fg,
              opacity: it.enter * it.fade * duck[it.i],
              whiteSpace: "nowrap",
            }}
          >
            {it.row.label}
          </div>
        ))}

        {items.map((it) => {
          if (it.isWin) return null;
          const v = Math.round(deltas[it.i] * it.slide);
          return (
            <div
              key={it.row.label}
              style={{
                position: "absolute",
                left: it.xa + r + 14 * u,
                top: it.y,
                transform: `translateY(-50%) translateX(${(1 - it.deltaIn) * -6 * u}px)`,
                fontFamily: sans,
                fontWeight: 400,
                fontSize: 20 * u,
                color: p.muted,
                fontVariantNumeric: "tabular-nums",
                opacity: it.deltaIn * (1 - dim) * duck[it.i],
                whiteSpace: "nowrap",
              }}
            >
              {deltaText(v)}
            </div>
          );
        })}

        {win
          ? [
              { key: "b", x: win.xb, text: beforeLabel, a: win.enter },
              { key: "a", x: win.xa, text: afterLabel, a: win.deltaIn },
            ].map((nt) => (
              <div
                key={nt.key}
                style={{
                  position: "absolute",
                  left: nt.x,
                  top: win.y - r - 10 * u,
                  transform: `translate(-50%, -100%) translateY(${(1 - nt.a) * 6 * u}px)`,
                  display: "flex",
                  alignItems: "baseline",
                  gap: "0.3em",
                  fontFamily: sans,
                  fontWeight: 400,
                  fontSize: 17 * u,
                  color: nt.key === "a" ? p.fg : p.muted,
                  opacity: nt.a * noteOut,
                  whiteSpace: "nowrap",
                }}
              >
                {nt.key === "a" && /remocn$/i.test(nt.text) ? (
                  <>
                    {nt.text.replace(/remocn$/i, "").trim()}
                    <RemocnLogo fontSize={18 * u} color={p.fg} />
                  </>
                ) : (
                  nt.text
                )}
              </div>
            ))
          : null}

        {win ? (
          <div
            style={{
              position: "absolute",
              left:
                win.xa + r + 14 * u + (heroX - (win.xa + r + 14 * u)) * grow,
              top: win.y,
              transform: "translateY(-50%)",
              opacity: win.deltaIn,
            }}
          >
            <div
              style={{
                fontFamily: sans,
                fontWeight: 400,
                fontSize: 132 * u,
                lineHeight: 1,
                letterSpacing: `${interpolate(grow, [0, 1], [0, -0.05])}em`,
                color: interpolateColors(grow, [0, 1], [p.muted, p.fg]),
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
                transformOrigin: "0% 50%",
                transform: `scale(${interpolate(grow, [0, 1], [20 / 132, 1])})`,
              }}
            >
              <span style={{ position: "relative", display: "inline-block" }}>
                {heroText}
                <span
                  aria-hidden
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundImage: p.heroText,
                    backgroundSize: "100% 100%",
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                    opacity: grow,
                  }}
                >
                  {heroText}
                </span>
              </span>
            </div>
            <div
              style={{
                position: "absolute",
                left: 4 * u,
                top: "100%",
                marginTop: 6 * u,
                fontFamily: sans,
                fontWeight: 400,
                fontSize: 21 * u,
                color: p.muted,
                whiteSpace: "nowrap",
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 6 * u}px)`,
              }}
            >
              {winCaption}
            </div>
          </div>
        ) : null}
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.5,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

/** [shadow ink, highlight ink], hex colors. */
export type DuotonePalette = [string, string];

export type DuotoneBeatProps = {
  /** Portrait image. Without it a head-and-shoulders silhouette is drawn. */
  src?: string;
  /** Ink pairs, one per beat, cycled. Hex colors only (they feed an SVG LUT). */
  palettes?: DuotonePalette[];
  /** Frames per beat at 30fps. Ignored when `bpm` is set. */
  beatFrames?: number;
  bpm?: number;
  /** Beats per bar; the first beat of each bar gets the bigger punch-in. */
  beatsPerBar?: number;
  /** Scale added on the downbeat. Off-beats get a third of it. */
  punch?: number;
  showIndicator?: boolean;
  /** Halftone dot pitch in px at 720p for a printed look. 0 keeps smooth tones. */
  halftone?: number;
  speed?: number;
};

export const duotoneBeatDefaults = {
  palettes: [
    ["#111111", "#FFFFFF"],
    ["#111111", "#E5322D"],
    ["#E5322D", "#FFFFFF"],
    ["#E5322D", "#111111"],
  ] as DuotonePalette[],
  beatFrames: 15,
  beatsPerBar: 4,
  punch: 0.07,
  showIndicator: true,
  halftone: 8,
  speed: 1,
};

const MONO = "ui-monospace, 'SF Mono', Menlo, Consolas, monospace";

function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace("#", "").trim();
  const full =
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h.slice(0, 6);
  const n = Number.parseInt(full, 16);
  if (Number.isNaN(n)) return [0, 0, 0];
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function Ground({
  id,
  width,
  height,
}: {
  id: string;
  width: number;
  height: number;
}) {
  return (
    <svg width={width} height={height} aria-hidden>
      <defs>
        <radialGradient id={`${id}-ground`} cx="0.5" cy="0.4" r="0.8">
          <stop offset="0" stopColor="#FFFFFF" />
          <stop offset="0.5" stopColor="#F2F2F2" />
          <stop offset="1" stopColor="#C4C4C4" />
        </radialGradient>
      </defs>
      <rect width={width} height={height} fill={`url(#${id}-ground)`} />
    </svg>
  );
}

function Portrait({
  id,
  width,
  height,
}: {
  id: string;
  width: number;
  height: number;
}) {
  const h = height;
  const cx = width / 2;
  const P = (x: number, y: number) => `${cx + x * h} ${y * h}`;
  const head = [
    `M ${P(0, 0.17)}`,
    `C ${P(0.075, 0.17)} ${P(0.118, 0.23)} ${P(0.118, 0.32)}`,
    `C ${P(0.118, 0.4)} ${P(0.095, 0.46)} ${P(0.06, 0.49)}`,
    `C ${P(0.035, 0.51)} ${P(-0.035, 0.51)} ${P(-0.06, 0.49)}`,
    `C ${P(-0.095, 0.46)} ${P(-0.118, 0.4)} ${P(-0.118, 0.32)}`,
