const THEMES = {
  dark: {
    bg: "#1B2A6B",
    ink: "#F3E9D2",
  },
  light: {
    bg: "#F3E9D2",
    ink: "#1B2A6B",
  },
} as const;

const TRACK = -0.005;
const FONT_PX = 200;
const RISE = 6;
const LEAD = 3;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface WordMetrics {
  chars: string[];
  adv: number[];
  inkTop: number;
  inkBottom: number;
  inkLeft: number[];
  inkRight: number[];
}

interface Metrics {
  words: WordMetrics[];
  baseline: number;
}

function measure(words: string[]): Metrics {
  const probe = document.createElement("span");
  Object.assign(probe.style, {
    position: "absolute",
    left: "-99999px",
    top: "0",
    visibility: "hidden",
    whiteSpace: "pre",
    fontFamily: `"${anton.fontFamily}"`,
    fontWeight: "400",
    fontSize: `${FONT_PX}px`,
    lineHeight: "1",
    letterSpacing: `${TRACK}em`,
  });
  document.body.appendChild(probe);
  const width = (s: string) => {
    probe.textContent = s;
    return probe.getBoundingClientRect().width / FONT_PX;
  };
  const canvas = document.createElement("canvas");
  canvas.width = 10;
  canvas.height = 10;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.font = `400 ${FONT_PX}px "${anton.fontFamily}"`;
    ctx.letterSpacing = `${TRACK * FONT_PX}px`;
  }

  const out: WordMetrics[] = words.map((word) => {
    const chars = Array.from(word);
    const adv: number[] = [];
    const inkLeft: number[] = [];
    const inkRight: number[] = [];
    let prev = 0;
    for (let i = 0; i < chars.length; i++) {
      const x = width(chars.slice(0, i + 1).join(""));
      adv.push(x - prev);
      prev = x;
      const pm = ctx?.measureText(chars.slice(0, i + 1).join(""));
      inkLeft.push(pm ? pm.actualBoundingBoxLeft / FONT_PX : 0);
      inkRight.push(pm ? pm.actualBoundingBoxRight / FONT_PX : x);
    }
    const wm = ctx?.measureText(word);
    return {
      chars,
      adv,
      inkTop: wm ? wm.actualBoundingBoxAscent / FONT_PX : 0.75,
      inkBottom: wm ? wm.actualBoundingBoxDescent / FONT_PX : 0.2,
      inkLeft,
      inkRight,
    };
  });
  probe.remove();

  let baseline = 0.8;
  if (ctx) {
    const fm = ctx.measureText("Hg");
    const asc = fm.fontBoundingBoxAscent / FONT_PX;
    const desc = fm.fontBoundingBoxDescent / FONT_PX;
    baseline = (1 - (asc + desc)) / 2 + asc;
  }
  return { words: out, baseline };
}

function useMetrics(words: string[]) {
  const key = words.join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("edge-fit: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      anton.waitUntilDone(),
      manrope.waitUntilDone(),
      document.fonts.load(`400 100px "${anton.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

export function edgeFitTiming(words: string[], letterGap = 3, hold = 14) {
  const starts: number[] = [];
  let at = 0;
  for (const w of words) {
    starts.push(at);
    at += Math.max(1, Array.from(w).length - 1) * letterGap + 10 + hold;
  }
  return { starts, end: at };
}

export function EdgeFit({
  words = ["intros", "teasers", "recaps"],
  caption = "Fresh from the registry",
  logo,
  letterGap = 3,
  hold = 14,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: EdgeFitProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.ink;
  const list = useMemo(() => (words.length > 0 ? words : ["remocn"]), [words]);
  const m = useMetrics(list);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);
  const { starts } = edgeFitTiming(list, letterGap, hold);
  let wi = 0;
  for (let i = 0; i < starts.length; i++) if (t >= starts[i]) wi = i;
  const last = wi === list.length - 1;
  const wm = m.words[wi];
  const local = t - starts[wi];
  const n = wm.chars.length;

  const measureW = W * (portrait ? 0.9 : 0.9);
  const maxInk = H * (portrait ? 0.3 : 0.66);
  const inkH = wm.inkTop + wm.inkBottom;
  const fitOf = (k: number) => {
    const ink = wm.inkLeft[k - 1] + wm.inkRight[k - 1];
    return Math.min(measureW / Math.max(0.05, ink), maxInk / inkH);
  };
  const arrive = (j: number) =>
    j === 0
      ? 1
      : spring({
          frame: local - j * letterGap + LEAD,
          fps,
          config: { damping: 19, stiffness: 260, mass: 0.6 },
        });
  let S = fitOf(1);
  for (let k = 2; k <= n; k++) S += (fitOf(k) - fitOf(k - 1)) * arrive(k - 1);

  const open = wm.adv.map((_, j) => Math.min(1.04, Math.max(0, arrive(j))));
  let cursor = 0;
  const xs: number[] = [];
  for (let j = 0; j < n; j++) {
    xs.push(cursor);
    cursor += wm.adv[j] * open[j];
  }
  let shown = 1;
  for (let j = 1; j < n; j++) if (open[j] > 0.001) shown = j + 1;
  const kIn = Math.max(1, shown);
  const blend = shown > 1 ? Math.min(1, open[shown - 1]) : 1;
  const inkRightPrev = kIn > 1 ? wm.inkRight[kIn - 2] : wm.inkRight[0];
  const inkRight = inkRightPrev + (wm.inkRight[kIn - 1] - inkRightPrev) * blend;
  const inkW = (wm.inkLeft[0] + inkRight) * S;
  const left = (W - inkW) / 2 + wm.inkLeft[0] * S;

  const baseY = H / 2 + ((wm.inkTop - wm.inkBottom) / 2) * S;
  const boxTop = baseY - m.baseline * S;
  const maskTop = baseY - wm.inkTop * S - S * 0.04;
  const maskH = inkH * S + S * 0.08;

  const signAt = starts[list.length - 1] + Math.max(0, n - 1) * letterGap;
  const sign = last
    ? interpolate(t, [signAt, signAt + 16], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      })
    : 0;
  const smallFs = (portrait ? 38 : 26) * s;
  const margin = (portrait ? 64 : 48) * s;
  const logoNode =
    logo === null
      ? null
      : (logo ?? <RemocnLogo fontSize={smallFs * 1.25} color={c.ink} />);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: maskTop,
          height: maskH,
        }}
      >
        {wm.chars.map((ch, j) => {
          if (open[j] <= 0.001) return null;
          const first = j === 0;
          const rp = first
            ? wi === 0
              ? interpolate(local, [0, RISE + 2], [0, 1], {
                  ...CLAMP,
                  easing: EASE_OUT,
                })
              : 1
            : interpolate(local - j * letterGap, [0, RISE], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
          const x = left + xs[j] * S;
          return (
            <div
              key={`${wi}-${j}-${ch}`}
              style={{
                position: "absolute",
                left: x,
                top: boxTop - maskTop,
                height: S,
                lineHeight: `${S}px`,
                whiteSpace: "pre",
                fontFamily: anton.fontFamily,
                fontWeight: 400,
                fontSize: S,
                opacity: interpolate(rp, [0, 0.55], [0, 1], CLAMP),
                transform: `translateY(${((1 - rp) * S * 0.22).toFixed(2)}px)`,
                color: spot,
              }}
            >
              {ch}
            </div>
          );
        })}
      </div>

      {sign > 0 ? (
        <>
          {caption ? (
            <div
              style={{
                position: "absolute",
                left: margin,
                bottom: margin,
                fontFamily: anton.fontFamily,
                fontWeight: 400,
                fontSize: smallFs,
                letterSpacing: "0.005em",
                lineHeight: 1,
                color: c.ink,
                opacity: sign,
                transform: `translateY(${((1 - sign) * smallFs * 0.8).toFixed(2)}px)`,
              }}
            >
              {caption}
            </div>
          ) : null}
          {logoNode ? (
            <div
              style={{
                position: "absolute",
                right: margin,
                bottom: margin,
                opacity: sign,
                transform: `translateY(${((1 - sign) * smallFs * 0.8).toFixed(2)}px)`,
              }}
            >
              {logoNode}
            </div>
          ) : null}
        </>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Epilogue";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const epilogue = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface EditRipplePair {
  cause: string;
  effect: string;
}

export interface EditRippleProps {
  pairs?: EditRipplePair[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#111418", ink: "#FFFFFF", accent: "#5CF2B5" },
  light: { bg: "#F4F6F5", ink: "#111418", accent: "#12A06B" },
} as const;

const DEFAULT_PAIRS: EditRipplePair[] = [
  { cause: "Change one word,", effect: "every scene follows." },
  { cause: "Swap the color,", effect: "every shot repaints." },
  { cause: "Change your mind,", effect: "render it again." },
];

const WGHT = 500;
const TRACK = -0.03;
const FONT_PX = 200;
const LH = 1.08;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 1, 0.45);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const ENTER = 18;
const EXIT = 10;
const HANDOFF = 6;
const CAUSE_PER_EM = 0.5;
const LAG = 14;
const EFFECT_PER_EM = 1.1;
const COOL = 18;
const PAIR_MOTION = 56;
const TAIL = 34;

type Metrics = Record<string, number>;

function measureAll(texts: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("edit-ripple: no 2d context");
  ctx.font = `${WGHT} ${FONT_PX}px "${epilogue.fontFamily}"`;
  const w: Metrics = {};
  for (const s of texts) {
    w[s] = ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
  }
  return w;
}

function useMetrics(texts: string[]) {
  const key = texts.join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("edit-ripple: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      epilogue.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${epilogue.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measureAll(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

const splitWords = (s: string) => s.split(" ").filter(Boolean);

interface Placed {
  word: string;
  x: number;
  row: number;
  top: number;
}

function place(words: string[], m: Metrics, F: number, x0: number): Placed[] {
  const out: Placed[] = [];
  let x = x0;
  for (const word of words) {
    out.push({ word, x, row: 0, top: 0 });
    x += (m[word] + m[" "]) * F;
  }
  return out;
}

function lineW(words: string[], m: Metrics) {
  return words.reduce((acc, w, i) => acc + m[w] + (i > 0 ? m[" "] : 0), 0);
}

function breakLines(words: string[], m: Metrics, L: number): string[][] {
  const n = words.length;
  const lines = Math.max(1, Math.min(L, n));
  if (lines === 1) return [words];
  let best: string[][] = [words];
  let bestW = Number.POSITIVE_INFINITY;
  const walk = (from: number, left: number, acc: string[][]) => {
    if (left === 1) {
      const all = [...acc, words.slice(from)];
      const w = Math.max(...all.map((l) => lineW(l, m)));
      if (w < bestW) {
        bestW = w;
        best = all;
      }
      return;
    }
    for (let cut = from + 1; cut <= n - left + 1; cut++) {
      walk(cut, left - 1, [...acc, words.slice(from, cut)]);
    }
  };
  walk(0, lines, []);
  return best;
}

export function EditRipple({
  pairs = DEFAULT_PAIRS,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: EditRippleProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = pairs.length > 0 ? pairs : DEFAULT_PAIRS;
  const causes = list.map((p) => splitWords(p.cause));
  const effects = list.map((p) => splitWords(p.effect));
  const m = useMetrics([
    " ",
    ...list.map((p) => p.cause),
    ...list.map((p) => p.effect),
    ...causes.flat(),
    ...effects.flat(),
  ]);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const span = durationInFrames * speed;
  const period =
    n > 1
      ? Math.min(
          96,
          Math.max(PAIR_MOTION + 12, (span - PAIR_MOTION - TAIL) / (n - 1)),
        )
      : 0;
  const startOf = (k: number) => k * period;

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.07);
  const measureW = W - marginX * 2;
  let F = 0;
  let causeLines: string[][][] = [];
  let effectLines: string[][][] = [];
  for (const L of portrait ? [1, 2, 3] : [1, 2]) {
    const cl = causes.map((w) => breakLines(w, m, L));
    const el = effects.map((w) => breakLines(w, m, L));
    const widest = Math.max(
      0.1,
      ...[...cl, ...el].flat().map((l) => lineW(l, m)),
    );
    const rows =
      Math.max(...cl.map((l) => l.length)) +
      Math.max(...el.map((l) => l.length));
    const size = Math.min(
      H * (portrait ? 0.13 : 0.185),
      (measureW * 0.94) / widest,
      (H * 0.74) / (rows * LH + 0.5),
    );
    if (size > F * 1.12) {
      F = size;
      causeLines = cl;
      effectLines = el;
    }
  }
  const causeTop = (j: number, count: number) =>
    H * 0.5 - F * 1.25 - (count - 1 - j) * LH * F;
  const effectTop = (j: number) => H * 0.5 + F * 0.25 + j * LH * F;

  const lineStyle: React.CSSProperties = {
    position: "relative",
    top: F * 0.1,
    height: F,
    lineHeight: `${F}px`,
    whiteSpace: "pre",
    fontFamily: epilogue.fontFamily,
    fontWeight: WGHT,
    fontSize: F,
    letterSpacing: `${TRACK}em`,
  };

  const nodes: React.ReactNode[] = [];

  const word = (
    key: string,
    text: string,
    x: number,
    top: number,
    y: number,
    color: string,
  ) => {
    nodes.push(
      <div
        key={key}
        style={{
          position: "absolute",
          left: x - F * 0.05,
          top: top - F * 0.1,
          height: F * 1.3,
          paddingLeft: F * 0.05,
          paddingRight: F * 0.1,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            ...lineStyle,
            color,
            transform: `translateY(${y.toFixed(2)}px)`,
          }}
        >
          {text}
        </div>
      </div>,
    );
  };

  const enter = (d: number) =>
    interpolate(t, [d, d + ENTER], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const exit = (d: number) =>
    interpolate(t, [d, d + EXIT], [0, 1], { ...CLAMP, easing: EASE_IN });
  const cool = (land: number, keep: boolean) =>
    keep
      ? hi
      : interpolateColors(
          Math.min(Math.max(t, land), land + COOL),
          [land, land + COOL],
          [hi, c.ink],
        );

  const drawLine = (
    k: number,
    words: Placed[],
    lag: number,
    perEm: number,
    keep: boolean,
    prefix: string,
  ) => {
    const first = k === 0;
    const hasNext = k + 1 < n;
    for (let i = 0; i < words.length; i++) {
      const p = words[i];
      const along = ((p.x - marginX) / F + p.row * 2) * perEm;
      const dIn = startOf(k) + lag + along + (first ? 0 : HANDOFF);
      if (t < dIn - 1) continue;
      const pin = enter(dIn);
      const pout = hasNext ? exit(startOf(k + 1) + lag + along) : 0;
      if (pout >= 1) continue;
      word(
        `${prefix}${k}-${i}`,
        p.word,
        p.x,
        p.top,
        (1 - pin - pout) * F * 1.4,
        cool(dIn + ENTER * 0.6, keep),
      );
    }
  };

  const layout = (
    lines: string[][],
    xOf: (line: string[]) => number,
    topOf: (j: number) => number,
  ) =>
    lines.flatMap((line, j) =>
      place(line, m, F, xOf(line)).map((p) => ({
        ...p,
        row: j,
        top: topOf(j),
      })),
    );

  for (let k = 0; k < n; k++) {
    if (t < startOf(k) - 1) continue;
    const cl = causeLines[k];
    drawLine(
      k,
      layout(
        cl,
        () => marginX,
        (j) => causeTop(j, cl.length),
      ),
      0,
      CAUSE_PER_EM,
      false,
      "c",
    );
    drawLine(
      k,
      layout(
        effectLines[k],
        (line) => W - marginX - lineW(line, m) * F,
        effectTop,
      ),
      LAG,
      EFFECT_PER_EM,
      k === n - 1,
      "e",
    );
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import { useId, useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily: serif } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface EllipsisResolveProps {
  /** The word the ellipsis resolves into. A period is always appended. */
  word?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Instrument Serif 400 advance widths (1/1000 em) for ASCII 32–126.
const SERIF_400 = [
  170, 237, 371, 635, 417, 590, 579, 233, 340, 340, 444, 531, 217, 430, 213,
  258, 460, 249, 404, 371, 393, 382, 404, 364, 433, 402, 213, 217, 531, 531,
  531, 317, 660, 457, 478, 480, 530, 453, 408, 521, 546, 249, 249, 496, 413,
  665, 540, 540, 466, 540, 513, 407, 461, 536, 457, 651, 546, 477, 427, 325,
  258, 325, 433, 376, 354, 399, 443, 339, 457, 355, 288, 402, 470, 223, 215,
  451, 220, 704, 470, 408, 444, 442, 318, 308, 259, 454, 393, 597, 385, 401,
  353, 318, 252, 318, 531,
];
const TRACK = -0.012;
const CAP = 0.72;
const BASELINE = 0.94; // baseline offset inside a lineHeight 1.2 box (asc 990, desc 310)
const PERIOD = 0.213; // advance of "."
const DOT = 0.105; // period diameter
const DOT_LSB = 0.054; // period left side bearing

// Beats (frames at 30fps).
const PULSE_A = 2;
const PULSE_B = 20;
const BUMP = 11;
const BUMP_STEP = 4;
const STRETCH = 40;
const STRETCH_LEN = 20;
const SWEEP = 58;
const SWEEP_LEN = 26;
const RISE = 13;
const SETTLE = 10;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_SWEEP = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "silk" palette (#3b3fd8, #f3d6c0, #8a7bff on #030308): a
// sheen across the resolved word, plus a faint haze of it on the stage.
const THEMES = {
  dark: {
    bg: "#030308",
    fg: "#F4F1EE",
    muted: "#46464F",
    ink: ["#F3D6C0", "#F6EEE9", "#B4A9FF", "#8A7BFF"],
    haze: "rgba(138,123,255,0.16)",
    grain: 0.07,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#BBBAB4",
    ink: ["#14163F", "#2A2DA8", "#3B3FD8", "#8A7BFF"],
    haze: "rgba(243,214,192,0.55)",
    grain: 0.045,
  },
} as const;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? SERIF_400[code - 32] : 620) / 1000;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const lerp = (a: number, b: number, p: number) => a + (b - a) * p;

export const ellipsisResolveDuration = SWEEP + SWEEP_LEN + RISE + 34;

export function EllipsisResolve({
  word = "Shipped",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: EllipsisResolveProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = H / 720;

  const layout = useMemo(() => {
    const chars = Array.from(word);
    const adv = chars.map((ch) => advance(ch) + TRACK);
    const total = adv.reduce((s, a) => s + a, 0) + PERIOD;
    const F = Math.min(250 * u, (W * 0.72) / total);
    const left = W / 2 - (total * F) / 2;
    let x = left;
    const letters = chars.map((ch, i) => {
      const box = { ch, x, w: adv[i] * F };
      x += adv[i] * F;
      return box;
    });
    const periodCx = x + (DOT_LSB + DOT / 2) * F;
    return { F, left, letters, periodCx, wordW: x - left };
  }, [word, W, u]);
  const { F, left, letters, periodCx, wordW } = layout;

  const d = DOT * F;
  const baseline = H / 2 + (CAP * F) / 2;
  const restY = baseline - d / 2;
  const pitch = 1.95 * d;

  // Camera: starts close on the typing indicator, eases out to the word.
  const zoom = interpolate(
    t,
    [STRETCH - 6, STRETCH + STRETCH_LEN + 6],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const cam = lerp(1.75, 1, zoom);

  // Dots begin centered in frame, then settle onto the word's baseline.
  const drop = EASE_IO(
    interpolate(t, [STRETCH, STRETCH + STRETCH_LEN], [0, 1], CLAMP),
  );
  const dotY = lerp(H / 2, restY, drop);

  const bump = (k: number) => {
    let b = 0;
    for (const start of [PULSE_A, PULSE_B]) {
      const local = (t - start - k * BUMP_STEP) / BUMP;
      if (local > 0 && local < 1) b = Math.max(b, Math.sin(Math.PI * local));
    }
    return b;
  };

  // Stretch: dot 3 travels to the period, dots 1 and 2 pull into one bar.
  const st = (k: number) =>
    EASE_IO(
      interpolate(
        t,
        [STRETCH + (2 - k) * 2, STRETCH + (2 - k) * 2 + STRETCH_LEN - 4],
        [0, 1],
        CLAMP,
      ),
    );
  const barRight = periodCx - d / 2 - 0.55 * d;
  const mid = (left + barRight) / 2;
  const startCx = (k: number) => W / 2 + (k - 1) * pitch;

  // Sweep: the bar's left edge chases right and folds into the period.
  const sweepRaw = interpolate(t, [SWEEP, SWEEP + SWEEP_LEN], [0, 1], CLAMP);
  const sweep = EASE_SWEEP(sweepRaw);
  const closeGap = EASE_IO(interpolate(t, [SWEEP, SWEEP + 10], [0, 1], CLAMP));
  const barL = lerp(left, periodCx - d / 2, sweep);
  const barR = lerp(barRight, periodCx + d / 2, closeGap);
  const sweeping = t >= SWEEP;

  // Each letter starts rising the frame the bar's edge clears its middle.
  const crossAt = useMemo(
    () =>
      letters.map((l) => {
        const target = l.x + l.w * 0.45;
        for (let f = 0; f <= SWEEP_LEN; f += 0.25) {
          const x = lerp(left, periodCx - d / 2, EASE_SWEEP(f / SWEEP_LEN));
          if (x >= target) return SWEEP + f;
        }
        return SWEEP + SWEEP_LEN;
      }),
    [letters, left, periodCx, d],
  );

  const accentIn = EASE_OUT(
    interpolate(t, [STRETCH + 4, STRETCH + STRETCH_LEN], [0, 1], CLAMP),
  );
  const landAt = SWEEP + SWEEP_LEN;
  const settle = interpolate(t, [landAt - 2, landAt + SETTLE], [0, 1], CLAMP);
  const pop = 1 + 0.14 * Math.sin(Math.PI * EASE_OUT(settle));
  const push = interpolate(t, [landAt, landAt + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  // The silk sheen drifts a few degrees while the word holds.
  const sheen = `linear-gradient(${96 + 10 * push}deg, ${c.ink[0]} 0%, ${c.ink[1]} 34%, ${c.ink[2]} 72%, ${c.ink[3]} 100%)`;

  const dotStyle = (
    l: number,
    r: number,
    y: number,
    color: string,
  ): React.CSSProperties => ({
    position: "absolute",
    left: l,
    top: y - d / 2,
    width: Math.max(d, r - l),
    height: d,
    borderRadius: d / 2,
    background: color,
  });

  const dot3Cx = lerp(startCx(2), periodCx, st(2));
  const dot3Color = interpolateColors(
    accentIn,
    [0, 1],
    [interpolateColors(bump(2), [0, 1], [c.muted, c.fg]), accent],
  );

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          opacity: 0.4 + 0.6 * accentIn,
          background: `radial-gradient(60% 42% at ${46 + 4 * push}% 50%, ${c.haze} 0%, transparent 70%)`,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${cam * (1 + 0.02 * push)})`,
          transformOrigin: `${W / 2}px ${lerp(H / 2, baseline - 0.3 * F, zoom)}px`,
        }}
      >
        {letters.map((l, i) => {
          const p = EASE_OUT(
            interpolate(t, [crossAt[i], crossAt[i] + RISE], [0, 1], CLAMP),
          );
          if (p <= 0) return null;
          return (
            <div
              key={`${i}-${l.ch}`}
              style={{
                position: "absolute",
                left: l.x,
                top: baseline - BASELINE * F,
                fontFamily: serif,
                fontWeight: 400,
                fontSize: F,
                lineHeight: 1.2,
                whiteSpace: "pre",
                color: "transparent",
                backgroundImage: sheen,
                backgroundSize: `${wordW}px ${1.2 * F}px`,
                backgroundPosition: `${left - l.x}px 0`,
                backgroundRepeat: "no-repeat",
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                opacity: Math.min(1, p * 1.6),
                transform: `translateY(${(1 - p) * 0.16 * F}px)`,
              }}
            >
              {l.ch}
            </div>
          );
        })}

        {(() => {
          if (sweeping) return <div style={dotStyle(barL, barR, dotY, c.fg)} />;
          const segs = [0, 1].map((k) => {
            const s = st(k);
            const cx = startCx(k);
            const l0 = cx - d / 2;
            const r0 = cx + d / 2;
            return {
              l: k === 0 ? lerp(l0, left, s) : lerp(l0, mid - d / 2, s),
              r: k === 0 ? lerp(r0, mid + d / 2, s) : lerp(r0, barRight, s),
              lift: bump(k) * 0.05 * F * (1 - s),
              color: interpolateColors(
                Math.max(bump(k), Math.min(1, s * 3)),
                [0, 1],
                [c.muted, c.fg],
              ),
            };
          });
          // Once the two capsules overlap they are one bar: draw it once so
          // the rounded ends never leave an antialiased seam.
          if (segs[1].l < segs[0].r) {
            return <div style={dotStyle(segs[0].l, segs[1].r, dotY, c.fg)} />;
          }
          return segs.map((g, k) => (
            <div
              key={k === 0 ? "a" : "b"}
              style={dotStyle(g.l, g.r, dotY - g.lift, g.color)}
            />
          ));
        })()}

        <div
          style={{
            ...dotStyle(
              dot3Cx - d / 2,
              dot3Cx + d / 2,
              dotY - bump(2) * 0.05 * F * (1 - st(2)),
              dot3Color,
            ),
            transform: `scale(${pop})`,
          }}
        />
      </AbsoluteFill>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/BigShoulders";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const shoulders = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface EmbargoLiftProps {
  lines?: string[];
  slug?: string;
  liftedSlug?: string;
  highlight?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#26231F", ink: "#F6F0E6", accent: "#2BD96B" },
  light: { bg: "#F5F5F2", ink: "#000000", accent: "#0E9F4B" },
} as const;

const WGHT = 500;
const PX = 200;
const LEAD = 1.2;

const T_SLUG = 50;
const T_LIFT = 58;
const LIFT_STEP = 14;
const LIFT_DUR = 16;
const HOLD = 34;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_LIFT = Easing.bezier(0.7, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Seg {
  text: string;
  hidden: boolean;
  bar: number;
}

function parseLine(line: string, start: number): Seg[] {
  const out: Seg[] = [];
  let bar = start;
  const re = /\[([^\]]*)\]/g;
  let last = 0;
  for (let r = re.exec(line); r; r = re.exec(line)) {
    if (r.index > last)
      out.push({ text: line.slice(last, r.index), hidden: false, bar: -1 });
    out.push({ text: r[1], hidden: true, bar });
    bar += 1;
    last = r.index + r[0].length;
  }
  if (last < line.length)
    out.push({ text: line.slice(last), hidden: false, bar: -1 });
  return out;
}

interface Metrics {
  w: Record<string, number>;
  asc: number;
  desc: number;
  cap: number;
  dsc: number;
}

function measureAll(texts: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("embargo-lift: no 2d context");
  ctx.font = `${WGHT} ${PX}px "${shoulders.fontFamily}"`;
  const w: Record<string, number> = {};
  for (const s of texts) w[s] = ctx.measureText(s).width / PX;
  const fm = ctx.measureText("Hgp");
  const h = ctx.measureText("Hbdl");
  const g = ctx.measureText("gpy");
  return {
    w,
    asc: fm.fontBoundingBoxAscent / PX,
    desc: fm.fontBoundingBoxDescent / PX,
    cap: h.actualBoundingBoxAscent / PX,
    dsc: g.actualBoundingBoxDescent / PX,
  };
}

function useMetrics(texts: string[]) {
  const key = texts.join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("embargo-lift: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      shoulders.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${shoulders.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measureAll(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

export function EmbargoLift({
  lines = ["remocn is [free],", "[open source]", "and [out today]."],
  slug = "Embargoed until 9:00 a.m.",
  liftedSlug = "Embargo lifted, 9:00 a.m.",
  highlight,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: EmbargoLiftProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const rows: Seg[][] = [];
  let barCount = 0;
  for (const l of lines.length > 0 ? lines : ["[out today]."]) {
    const segs = parseLine(l, barCount);
    barCount += segs.filter((s) => s.hidden).length;
    rows.push(segs);
  }
  const hiBar = highlight ?? barCount - 1;

  const naturalEnd =
    T_LIFT + Math.max(0, barCount - 1) * LIFT_STEP + LIFT_DUR + HOLD;
  const pace = Math.max(1, naturalEnd / Math.max(1, durationInFrames));
  const t = frame * speed * pace;

  const texts: string[] = [];
  for (const segs of rows) {
    let prefix = "";
    for (const s of segs) {
      texts.push(prefix, s.text);
      prefix += s.text;
    }
    texts.push(prefix);
  }
  texts.push(slug, liftedSlug);
  const m = useMetrics(texts);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.07 : 0.06);
  const lineTexts = rows.map((segs) => segs.map((s) => s.text).join(""));
  const maxW = Math.max(0.1, ...lineTexts.map((l) => m.w[l]));
  const size = Math.min(
    (W - marginX * 2) / maxW,
    (H * (portrait ? 0.52 : 0.68)) / (rows.length * LEAD),
  );
  const slugSize = Math.max(H * (portrait ? 0.018 : 0.034), size * 0.13);
  const slugGap = slugSize * 1.6;
  const blockH = rows.length * LEAD * size;
  const totalH = slugSize + slugGap + blockH;
  const top = (H - totalH) / 2 + slugSize * 0.2;
  const firstBase = top + slugSize + slugGap + m.cap * size;

  const boxTop = (base: number, s: number) =>
    base - ((1 - m.asc - m.desc) / 2 + m.asc) * s;

  const textStyle = (s: number): React.CSSProperties => ({
    position: "absolute",
    height: s,
    lineHeight: `${s}px`,
    whiteSpace: "pre",
    fontFamily: shoulders.fontFamily,
    fontWeight: WGHT,
    fontSize: s,
  });

  const nodes: React.ReactNode[] = [];

  rows.forEach((segs, r) => {
    const lineW = m.w[lineTexts[r]] * size;
    const left = (W - lineW) / 2;
    const base = firstBase + r * LEAD * size;
    const p = interpolate(t, [2 + r * 4, 22 + r * 4], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const dy = (1 - p) * size * 0.22;
    nodes.push(
      <div
        key={`line-${r}`}
        style={{
          ...textStyle(size),
          left,
          top: boxTop(base, size),
          opacity: p,
          transform: `translateY(${dy.toFixed(2)}px)`,
          color: c.ink,
        }}
      >
        {segs.map((s, i) => (
          <span
            key={`${r}-${i}`}
            style={{ color: s.hidden && s.bar === hiBar ? hi : c.ink }}
          >
            {s.text}
          </span>
        ))}
      </div>,
    );
    let prefix = "";
    segs.forEach((s, i) => {
      const x0 = left + m.w[prefix] * size;
      prefix += s.text;
      if (!s.hidden) return;
      const tw = m.w[s.text] * size;
      const padX = size * 0.012;
      const barTop = base - (m.cap + 0.05) * size;
      const barBottom =
        base + (Math.min(Math.max(m.dsc, 0.1), 0.24) + 0.02) * size;
      const startAt = T_LIFT + s.bar * LIFT_STEP;
      const g = interpolate(t, [startAt, startAt + LIFT_DUR], [1, 0], {
        ...CLAMP,
        easing: EASE_LIFT,
      });
      if (g <= 0) return;
      nodes.push(
        <div
          key={`bar-${r}-${i}`}
          style={{
            position: "absolute",
            left: x0 - padX,
            top: barTop,
            width: tw + padX * 2,
            height: barBottom - barTop,
            background: c.ink,
            opacity: p,
            transform: `translateY(${dy.toFixed(2)}px) scaleX(${g.toFixed(4)})`,
            transformOrigin: "100% 50%",
          }}
        />,
      );
    });
  });

  const slugBase = top + m.cap * slugSize;
  const slugIn = interpolate(t, [10, 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const flip = interpolate(t, [T_SLUG, T_SLUG + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_LIFT,
  });
  const slugClipTop = slugBase - (m.cap + 0.2) * slugSize;
  const slugClipH = (m.cap + 0.2 + 0.3) * slugSize;
  const slugLine = (text: string, y: number, o: number, key: string) => (
    <div
      key={key}
      style={{
        ...textStyle(slugSize),
        left: (W - m.w[text] * slugSize) / 2,
        top: boxTop(slugBase, slugSize) - slugClipTop,
        color: c.ink,
        opacity: o,
        transform: `translateY(${y.toFixed(2)}px)`,
      }}
    >
      {text}
    </div>
  );
  const travel = slugClipH;
  nodes.push(
    <div
      key="slug"
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: slugClipTop,
        height: slugClipH,
        overflow: "hidden",
        opacity: slugIn,
      }}
    >
      {flip < 1
        ? slugLine(slug, -flip * travel, 0.6 * (1 - flip * 0.5), "old")
        : null}
      {flip > 0
        ? slugLine(liftedSlug, (1 - flip) * travel, 0.6 + 0.4 * flip, "new")
        : null}
    </div>,
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  makeCanvasPresentation,
  makeSceneShader,
} from "@/lib/remocn/canvas-presentation";

export type EmberBurnProps = {
  patches?: number;
  edgeSoftness?: number;
  contentBias?: number;
  heat?: number;
  glowColor?: string;
  emberAmount?: number;
};

const DEFAULTS = {
  patches: 5,
  edgeSoftness: 0.07,
  contentBias: 0.6,
  heat: 0.5,
  glowColor: "#ff7a2f",
  emberAmount: 0.5,
};

function hexToRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) {
    return [1, 0.48, 0.18];
  }
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_aspect;
uniform float u_patches;
uniform float u_softness;
uniform float u_content;
uniform float u_heat;
uniform vec3 u_glow;
uniform float u_embers;

in vec2 v_uv;
out vec4 outColor;

const float EMBER_GRID = 110.0;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    sum += noise(p) * amp;
    p *= 2.03;
    amp *= 0.5;
  }
  return sum * 1.032;
}

float luma(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

void main() {
  vec2 skewed = vec2(v_uv.x * u_aspect, v_uv.y);
  float alive =
    smoothstep(0.0, 0.06, u_progress) * smoothstep(1.0, 0.94, u_progress);

  float brightness = luma(texture(u_from, v_uv).rgb);
  float field = clamp(
    clamp(fbm(skewed * u_patches), 0.0, 1.0) *
      (1.0 - u_content * brightness * 0.9),
    0.0,
    1.0
  );

  float soft = max(u_softness, 0.004);
  float margin = soft * 3.0 + 0.02;
  float front = mix(-margin, 1.0 + margin, pow(u_progress, 1.2));
  float depth = field - front;

  float intact = smoothstep(-soft, soft, depth);
  float arrived = 1.0 - intact;

  vec2 shimmer = vec2(
    noise(skewed * u_patches * 2.4 + vec2(0.0, u_progress * 3.1)) - 0.5,
    noise(skewed * u_patches * 2.4 + vec2(5.2, 1.7 + u_progress * 4.3)) - 0.5
  );
  float heatBand = depth / (soft * 6.0);
  float boil = exp(-heatBand * heatBand) * alive * u_heat * 0.14;
  vec4 from = texture(u_from, v_uv + shimmer * boil * intact);
  vec4 to = texture(u_to, v_uv - shimmer * boil * arrived);

  float ramp = depth / (soft * 2.2);
  float charBand = (ramp - 0.55) * 1.5;
  float moltenBand = (ramp + 0.55) * 1.5;
  float rimBand = depth / (soft * 1.1);
  float charred = intact * exp(-charBand * charBand) * alive;
  float molten = arrived * exp(-moltenBand * moltenBand) * alive;
  float rim = exp(-rimBand * rimBand);

  float since = clamp(-depth / (soft * 3.0), 0.0, 1.0);
  float emberBand = depth / (soft * 2.6);
  vec2 emberSpace = skewed + vec2(0.0, u_progress * 0.42);
  float cellSeed = hash(floor(emberSpace * EMBER_GRID));
  float ember =
    step(1.0 - u_embers * 0.08, cellSeed) *
    arrived *
    exp(-emberBand * emberBand) *
    alive;
  vec3 sparkSource = texture(u_from, v_uv + vec2(0.0, since * 0.07)).rgb;

  vec4 color = mix(to, from, intact);
  color.rgb *= 1.0 - charred * 0.92;
  color.rgb += (color.rgb * 1.2 + u_glow * 0.6) * molten;

  vec3 spark = mix(u_glow, sparkSource * 1.4 + u_glow * 0.3, 0.5);
  float light = min(rim * 0.85, 1.4);
  color.rgb += u_glow * light + spark * ember * 1.3;
  color.a = clamp(color.a + light + molten + ember, 0.0, 1.0);

  outColor = color;
}`;

const shader = makeSceneShader<EmberBurnProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      patches = DEFAULTS.patches,
      edgeSoftness = DEFAULTS.edgeSoftness,
      contentBias = DEFAULTS.contentBias,
      heat = DEFAULTS.heat,
      glowColor = DEFAULTS.glowColor,
      emberAmount = DEFAULTS.emberAmount,
    } = passedProps;
    const glow = hexToRgb(glowColor);
    gl.uniform1f(uniform("u_patches"), patches);
    gl.uniform1f(uniform("u_softness"), edgeSoftness);
    gl.uniform1f(uniform("u_content"), contentBias);
    gl.uniform1f(uniform("u_heat"), heat);
    gl.uniform3f(uniform("u_glow"), glow[0], glow[1], glow[2]);
    gl.uniform1f(uniform("u_embers"), emberAmount);
  },
);

const EmberBurnFallback: React.FC<
  TransitionPresentationComponentProps<EmberBurnProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const { glowColor = DEFAULTS.glowColor } = passedProps;

  if (presentationDirection === "exiting") {
    return <AbsoluteFill>{children}</AbsoluteFill>;
  }

  const p = presentationProgress;
  const reveal = Math.min(1, Math.max(0, (p - 0.25) / 0.5));
  const flash = Math.max(0, Math.sin(p * Math.PI)) ** 0.6 * 0.4;

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: reveal }}>{children}</AbsoluteFill>
      <AbsoluteFill
        style={{
          background: glowColor,
          mixBlendMode: "screen",
          opacity: flash,
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<EmberBurnProps>({
  shader,
  fallback: EmberBurnFallback,
});

export function emberBurn(
  props: EmberBurnProps = {},
): TransitionPresentation<EmberBurnProps> {
  return presentation(props);
}

"use client";

import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// Brand face: the remocn.dev logo is the R mark + "emocn" in Manrope 600.
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";
const R_W = 124.06;
const R_H = 134.26;

// gradients.sh "silk" palette: bg #030308, [#3b3fd8, #f3d6c0, #8a7bff].
// Used once, as the foil pressed into the debossed R. The sheen band follows
// the raking light.
const SILK = ["#3b3fd8", "#f3d6c0", "#8a7bff"] as const;

export interface EmbossedMarkProps {
  /** Custom mark to deboss instead of the remocn R (square slot, black fill). */
  logo?: React.ReactNode;
  /** Letters printed after the mark. With the default R this completes "Remocn". */
  name?: string;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    paper: "#212124",
    floor: "#1F1F22",
    ink: "#E8E5DE",
    shadow: "#000000",
    shadowA: 0.85,
    hi: "#FFFFFF",
    hiA: 0.32,
    pool: "rgba(255,255,255,0.1)",
    falloff: "rgba(0,0,0,0.5)",
    tooth: 0.55,
    foil: 0.94,
    grain: 0.07,
  },
  light: {
    paper: "#EBE7DF",
    floor: "#E7E3DA",
    ink: "#1C1B19",
    shadow: "#3C3020",
    shadowA: 0.5,
    hi: "#FFFFFF",
    hiA: 0.95,
    pool: "rgba(255,253,248,0.55)",
    falloff: "rgba(60,48,30,0.16)",
    tooth: 0.6,
    foil: 0.96,
    grain: 0.05,
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function ReliefFilter({
  id,
  p,
  lx,
  ly,
  depth,
  blur,
  base,
}: {
  id: string;
  p: Palette;
  lx: number;
  ly: number;
  depth: number;
  blur: number;
  base: "floor" | "source";
}) {
  return (
    <filter
      id={id}
      x="-20%"
      y="-20%"
      width="140%"
      height="140%"
      colorInterpolationFilters="sRGB"
    >
      {base === "floor" ? (
        <>
          <feFlood floodColor={p.floor} result="fc" />
          <feComposite in="fc" in2="SourceAlpha" operator="in" result="base" />
        </>
      ) : (
        <feOffset in="SourceGraphic" dx={0} dy={0} result="base" />
      )}
      <feComponentTransfer in="SourceAlpha" result="inv">
        <feFuncA type="table" tableValues="1 0" />
      </feComponentTransfer>
      <feOffset in="inv" dx={-lx * depth} dy={-ly * depth} result="invS" />
      <feGaussianBlur in="invS" stdDeviation={blur} result="invSB" />
      <feFlood floodColor={p.shadow} floodOpacity={p.shadowA} />
      <feComposite in2="invSB" operator="in" result="sh0" />
      <feComposite in="sh0" in2="SourceAlpha" operator="in" result="sh" />
      <feOffset
        in="inv"
        dx={lx * depth * 0.8}
        dy={ly * depth * 0.8}
        result="invH"
      />
      <feGaussianBlur in="invH" stdDeviation={blur * 0.6} result="invHB" />
      <feFlood floodColor={p.hi} floodOpacity={p.hiA} />
      <feComposite in2="invHB" operator="in" result="hi0" />
      <feComposite in="hi0" in2="SourceAlpha" operator="in" result="hi" />
      <feMerge>
        <feMergeNode in="base" />
        <feMergeNode in="sh" />
        <feMergeNode in="hi" />
      </feMerge>
    </filter>
  );
}

export function EmbossedMark({
  logo,
  name = "emocn",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: EmbossedMarkProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const p = THEMES[theme];
  const u = height / 720;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const debId = `deb${uid}`;
  const pressId = `press${uid}`;
  const toothId = `tooth${uid}`;
  const foilId = `foil${uid}`;

  // Logo geometry from remocn.dev: the R is 0.76em tall and sits on the
  // baseline of "emocn"; the letters start 0.04em after it.
  const fontSize = 214 * u;
  const markH = fontSize * 0.76;
  const markW = logo ? markH : (markH * R_W) / R_H;

  const sweep = EASE_IO(interpolate(t, [0, 112], [0, 1], CLAMP));
  const az = (196 + 104 * sweep) * (Math.PI / 180);
  const lx = Math.cos(az);
  const ly = Math.sin(az);
  const elev = interpolate(sweep, [0, 1], [10, 34]);
  const depth = interpolate(elev, [10, 34], [7.5, 3.6]) * u;
  const blur = interpolate(elev, [10, 34], [2.6, 1.8]) * u;

  // Camera: starts centred on the mark, eases out to centre the lockup.
  // translateX(%) resolves against the lockup's own width, so no text
  // measuring is needed.
  const cam = EASE_IO(interpolate(t, [56, 100], [0, 1], CLAMP));
  const zoom = 1 + 0.1 * (1 - cam);
  const camX = `calc(${(1 - cam) * 50}% - ${((1 - cam) * markW) / 2}px)`;

  const foil = interpolate(t, [66, 84], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const sheen = 0.18 + 0.5 * sweep;
  const letters = [...name];
  const letterIn = (i: number) =>
    interpolate(t, [80 + i * 3, 90 + i * 3], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const poolX = 50 + lx * 46;
  const poolY = 50 + ly * 70;
  const huge = {
    position: "absolute",
    left: -width * 1.5,
    top: -height * 1.5,
    width: width * 4,
    height: height * 4,
  } as const;

  return (
    <AbsoluteFill style={{ background: p.paper, overflow: "hidden" }}>
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <defs>
          <ReliefFilter
            id={debId}
            p={p}
            lx={lx}
            ly={ly}
            depth={depth}
            blur={blur}
            base="floor"
          />
          <ReliefFilter
            id={pressId}
            p={p}
            lx={lx}
            ly={ly}
            depth={depth * 0.32}
            blur={blur * 0.45}
            base="source"
          />
          <filter id={toothId} x="0" y="0" width="100%" height="100%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.55 0.75"
              numOctaves={3}
              seed={5}
              result="n"
            />
            <feDiffuseLighting
              in="n"
              surfaceScale={1.6}
              diffuseConstant={1}
              lightingColor="#FFFFFF"
            >
              <feDistantLight azimuth={(az * 180) / Math.PI} elevation={elev} />
            </feDiffuseLighting>
          </filter>
          <linearGradient
            id={foilId}
            x1="0"
            y1="0"
            x2="1"
            y2="1"
            gradientTransform={`rotate(${-18 + 30 * sweep} 0.5 0.5)`}
          >
            <stop offset="0" stopColor={accent} />
            <stop offset={Math.max(0, sheen - 0.2)} stopColor={SILK[2]} />
            <stop offset={sheen} stopColor={SILK[1]} />
            <stop offset={Math.min(1, sheen + 0.22)} stopColor={SILK[2]} />
            <stop offset="1" stopColor={SILK[0]} />
          </linearGradient>
        </defs>
      </svg>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            position: "relative",
            display: "flex",
            alignItems: "baseline",
            fontFamily: manrope.fontFamily,
            fontWeight: 600,
            fontSize,
            lineHeight: 1,
            letterSpacing: "-0.025em",
            color: p.ink,
            transformOrigin: `${markW / 2}px 50%`,
            transform: `translateX(${camX}) scale(${zoom})`,
          }}
        >
          <div style={{ ...huge, background: p.paper }} />
          <div
            style={{
              position: "relative",
              flex: "none",
              width: markW,
              height: markH,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                filter: `url(#${debId})`,
              }}
            >
              {logo ?? (
                <svg
                  width={markW}
                  height={markH}
                  viewBox={`0 0 ${R_W} ${R_H}`}
                  style={{ display: "block" }}
                  aria-hidden
                >
                  <path d={REMOCN_R_PATH} fill="#000" />
                </svg>
              )}
            </div>
            {logo ? null : (
              <svg
                width={markW}
                height={markH}
                viewBox={`0 0 ${R_W} ${R_H}`}
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "block",
                  overflow: "visible",
                  filter: `url(#${pressId})`,
                  opacity: foil * p.foil,
                }}
                aria-hidden
              >
                <path d={REMOCN_R_PATH} fill={`url(#${foilId})`} />
              </svg>
            )}
          </div>
          <div
            style={{
              position: "relative",
              marginLeft: "0.04em",
              whiteSpace: "pre",
              filter: `url(#${pressId})`,
            }}
          >
            {letters.map((ch, i) => (
              <span key={`${ch}${i}`} style={{ opacity: letterIn(i) }}>
                {ch}
              </span>
            ))}
          </div>
          <svg
            style={{
              ...huge,
              opacity: p.tooth,
              mixBlendMode: "soft-light",
              pointerEvents: "none",
            }}
            aria-hidden
          >
            <rect width="100%" height="100%" filter={`url(#${toothId})`} />
          </svg>
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(ellipse 80% 110% at ${poolX}% ${poolY}%, ${p.pool}, rgba(0,0,0,0) 70%)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(ellipse 90% 120% at ${poolX}% ${poolY}%, rgba(0,0,0,0) 45%, ${p.falloff} 100%)`,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

"use client";

import { loadVariableFont } from "@remotion/google-fonts/InterTight";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const inter = loadVariableFont("normal", { subsets: ["latin"] });

export interface EnhanceCountProps {
  text?: string;
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#1C1C1E",
    ink: "#E9E9E6",
    accent: "#6D5BFF",
  },
  light: {
    bg: "#E9E9E6",
    ink: "#0B0B0C",
    accent: "#6D5BFF",
  },
} as const;

const DRAFT_WGHT = 100;
const DONE_WGHT = 440;
const TRACK = -0.025;

const ENTER_LEN = 14;
const ENHANCE_AT = 38;
const ENHANCE_SPAN = 34;
const ENHANCE_MAX_GAP = 2.4;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface LineMetrics {
  chars: string[];
  x: number[];
  width: number;
}

interface Metrics {
  lines: LineMetrics[];
  capTop: number;
  baseline: number;
}

function measure(lines: string[]): Metrics {
  const canvas = document.createElement("canvas");
  canvas.width = 10;
  canvas.height = 10;
  const ctx = canvas.getContext("2d");
  const size = 200;
  const out: LineMetrics[] = [];
  let capTop = 0.72;
  let baseline = 0.8;
  if (!ctx) {
    for (const l of lines) {
      const chars = Array.from(l);
      out.push({
        chars,
        x: chars.map((_, i) => i * 0.55),
        width: chars.length * 0.55,
      });
    }
    return { lines: out, capTop, baseline };
  }
  ctx.font = `${DONE_WGHT} ${size}px "${inter.fontFamily}"`;
  ctx.letterSpacing = `${TRACK * size}px`;
  for (const l of lines) {
    const chars = Array.from(l);
    const x: number[] = [];
    let acc = "";
    for (const ch of chars) {
      x.push(ctx.measureText(acc).width / size);
      acc += ch;
    }
    out.push({ chars, x, width: ctx.measureText(acc).width / size });
  }
  const fm = ctx.measureText("H");
  const asc = fm.fontBoundingBoxAscent / size;
  const desc = fm.fontBoundingBoxDescent / size;
  baseline = (1 - (asc + desc)) / 2 + asc;
  capTop = fm.actualBoundingBoxAscent / size;
  return { lines: out, capTop, baseline };
}

function useMetrics(lines: string[]) {
  const key = lines.join("\n");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("enhance-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`${DONE_WGHT} 100px "${inter.fontFamily}"`),
      document.fonts.load(`${DRAFT_WGHT} 100px "${inter.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(key.split("\n")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

const mix = (a: string, b: string, u: number) =>
  `color-mix(in oklab, ${a} ${((1 - u) * 100).toFixed(1)}%, ${b})`;

export function EnhanceCount({
  text = "Draft it fast.\nFinish it sharp.",
  highlight = "sharp.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: EnhanceCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const lines = useMemo(() => {
    const l = text
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean);
    return l.length ? l : ["Finish it sharp."];
  }, [text]);
  const m = useMetrics(lines);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const widest = Math.max(0.1, ...m.lines.map((l) => l.width));
  const LH = 1.1;
  const F = Math.min(
    (W * (portrait ? 0.78 : 0.56)) / widest,
    (H * (portrait ? 0.07 : 0.12)) / m.capTop,
  );
  const lineH = F * LH;
  const blockH = lineH * m.lines.length;
  const top0 = (H - blockH) / 2;

  const hiWords = new Set(
    highlight
      .split(/\s+/)
      .filter(Boolean)
      .map((w) => w.toLowerCase()),
  );
  const nGlyphs = m.lines.reduce((a, l) => a + l.chars.length, 0);
  const gap = Math.min(ENHANCE_MAX_GAP, ENHANCE_SPAN / Math.max(1, nGlyphs));
  const enter = interpolate(t, [0, ENTER_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  let gi = 0;
  const glyphs = m.lines.flatMap((line, li) => {
    const left0 = (W - line.width * F) / 2;
    const baseY = top0 + li * lineH + (lineH + m.capTop * F) / 2;
    const words: boolean[] = [];
    let wordStart = 0;
    for (let i = 0; i <= line.chars.length; i++) {
      if (i === line.chars.length || line.chars[i] === " ") {
        const w = line.chars.slice(wordStart, i).join("").toLowerCase();
        for (let k = wordStart; k < i; k++) words[k] = hiWords.has(w);
        words[i] = false;
        wordStart = i + 1;
      }
    }
    return line.chars.map((ch, i) => {
      const idx = gi++;
      const u = spring({
        frame: t - ENHANCE_AT - idx * gap,
        fps,
        config: { damping: 18, stiffness: 140, mass: 0.8 },
      });
      const uc = Math.min(1, Math.max(0, u));
      const next = i + 1 < line.chars.length ? line.x[i + 1] : line.width;
      const slot = (next - line.x[i]) * F;
      const wght = DRAFT_WGHT + (DONE_WGHT - DRAFT_WGHT) * u;
      const blur = (1 - uc) * F * 0.045;
      const hi = words[i] && ch !== " ";
      const color = hi ? mix(c.ink, spot, uc) : c.ink;
      return (
        <div
          key={`${li}-${i}`}
          style={{
            position: "absolute",
            left: left0 + line.x[i] * F,
            width: slot,
            top: baseY - m.baseline * F,
            height: F,
            lineHeight: `${F}px`,
            textAlign: "center",
            whiteSpace: "pre",
            fontFamily: inter.fontFamily,
            fontSize: F,
            fontVariationSettings: `"wght" ${wght.toFixed(1)}`,
            color,
            opacity: enter * (0.5 + 0.5 * uc),
            filter: blur > 0.05 ? `blur(${blur.toFixed(2)}px)` : undefined,
          }}
        >
          {ch}
        </div>
      );
    });
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {glyphs}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Oswald";
import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const { fontFamily } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

export interface EscalateCardsProps {
  /** One word per card, smallest first. The last one fills the frame and holds. */
  words?: string[];
  /** Small line that cuts in under the last card. Pass "" to hide. */
  date?: string;
  /** Length of the first card in frames. Every next card is shorter. */
  firstBeat?: number;
  /** Each card lasts this share of the one before: below 1 the cuts accelerate. */
  accel?: number;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Beat sheet (30fps, speed 1, defaults):
//  0–26    "ONE", small and light (300), alone in the middle of the frame
//  26–42   hard cut: "CODEBASE", bigger and a step heavier (400)
//  42–51   hard cut: "EVERY", bigger again; the cuts keep accelerating
//  51      hard cut to the gradient ground: "LAUNCH" edge to edge, its
//          outer letters cropped by the frame
//  65      the date cuts in under it; slow push, poster hold to 130
const DATE_DELAY = 14;
/** Frames the default demo needs: the cards plus a long poster hold. */
export const ESCALATE_CARDS_DURATION = 130;

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);

const THEMES = {
  /** Dark: the climax cuts to the mesh ground, white type on top. */
  dark: { bg: "#0A0A0B", fg: "#F5F4F0", pale: 55, clip: false },
  /** Light: the stage stays off-white and the mesh fills the letters. */
  light: { bg: "#F5F4F0", fg: "#0A0A0B", pale: 18, clip: true },
} as const;

/** Oswald 500 advance widths (per mille) for ASCII 32–126 (harfbuzz). */
const ADV = [
  243, 233, 315, 511, 488, 950, 587, 149, 319, 295, 411, 433, 213, 314, 217,
  396, 534, 382, 497, 496, 504, 493, 521, 413, 510, 521, 239, 251, 386, 429,
  386, 483, 928, 522, 557, 540, 557, 428, 413, 559, 586, 275, 326, 532, 421,
  683, 545, 563, 527, 564, 561, 494, 430, 566, 516, 712, 499, 487, 425, 336,
  396, 317, 460, 356, 293, 435, 477, 440, 473, 446, 304, 472, 478, 248, 250,
  471, 252, 718, 474, 455, 476, 474, 353, 400, 330, 473, 404, 593, 416, 421,
  370, 338, 251, 351, 465,
];
/** Oswald 500 capital pairs that move the most (per mille, tightening). */
const KERN = new Map(
  [
    "AT43 AV36 AW23 AY42 BT21 BV24 BX20 BY17 FA35 FJ26 KC21 KG21 KO21 KQ17",
    "LT73 LU14 LV71 LW47 LY86 PA47 PJ26 PZ16 RY19 TA43 TJ26 VA36 WA23 YA42",
  ]
    .join(" ")
    .split(" ")
    .map((p) => [p.slice(0, 2), -Number(p.slice(2)) / 1000] as const),
);
const CAP = 0.81;
/** Cap centre inside a line-height: 1 box, in em (ascent 1.193, descent 0.289). */
const CAP_MID = 0.547;

/**
 * gradients.sh "mesh" palette (bg #0a0d24, [#ecdcf2, #8796ee, #2e45b7,
 * #0e1645]): the climax ground, with the accent in the middle. Blobs
 * drift a few percent over the hold.
 */
function meshGround(drift: number, accent: string, pale: number) {
  // The palest blob is mixed down so white type over it stays legible.
  const blobs: Array<[string, number, number]> = [
    [`color-mix(in oklab, #ecdcf2 ${pale}%, transparent)`, 14, 16],
    ["#8796ee", 86, 24],
    ["#2e45b7", 70, 88],
    ["#0e1645", 22, 82],
    [accent, 50, 54],
  ];
  return [
    ...blobs.map(
      ([color, x, y], i) =>
        `radial-gradient(85% 95% at ${x + drift * (i % 2 ? -4 : 4)}% ${y + drift * (i % 3 ? 3 : -3)}%, ${color} 0%, transparent 68%)`,
    ),
    // A solid layer, not a bare colour, so the stack is also a valid background-image.
    "linear-gradient(#0a0d24, #0a0d24)",
  ].join(", ");
}

/**
 * Width in em at 500, tracking between letters. Lighter cuts are narrower,
 * so this is a safe upper bound for them too.
 */
function textWidth(text: string, track: number) {
  const chars = Array.from(text);
  let w = 0;
  chars.forEach((ch, i) => {
    const code = ch.charCodeAt(0);
    w += (code >= 32 && code < 127 ? ADV[code - 32] : 680) / 1000;
    if (i > 0) w += KERN.get(chars[i - 1] + ch) ?? 0;
  });
  return w + track * Math.max(0, chars.length - 1);
}

/**
 * One centred line in a line-height: 1 box; `y` is the cap centre. The left
 * padding cancels the letter-spacing that trails the last glyph.
 */
function Line({
  y,
  size,
  tracking,
  weight,
  color,
  scale,
  fill,
  children,
}: {
  y: number;
  size: number;
  tracking: number;
  weight: number;
  color: string;
  scale: number;
  /** A frame-sized background painted through the glyphs. */
  fill?: { image: string; W: number; H: number };
  children: string;
}) {
  const top = y - size * CAP_MID;
  const paint: React.CSSProperties = fill
    ? {
        color: "transparent",
        backgroundImage: fill.image,
        // The box is twice the frame wide; pin the ground to the frame.
        backgroundSize: `${fill.W}px ${fill.H}px`,
        backgroundPosition: `${fill.W / 2}px ${-top}px`,
        backgroundRepeat: "no-repeat",
        WebkitBackgroundClip: "text",
        backgroundClip: "text",
      }
    : { color };
  return (
    <div
      style={{
        position: "absolute",
        left: "-50%",
        right: "-50%",
        top,
        height: size,
        textAlign: "center",
        whiteSpace: "nowrap",
        fontFamily,
        fontWeight: weight,
        fontSize: size,
        lineHeight: 1,
        letterSpacing: `${tracking}em`,
        paddingLeft: `${tracking}em`,
        ...paint,
        fontVariantNumeric: "tabular-nums",
        transform: scale === 1 ? undefined : `scale(${scale})`,
        transformOrigin: `50% ${CAP_MID * 100}%`,
      }}
    >
      {children}
    </div>
  );
}

export function EscalateCards({
  words = ["ONE", "CODEBASE", "EVERY", "LAUNCH"],
  date = "OCTOBER 30",
  firstBeat = 26,
  accel = 0.6,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: EscalateCardsProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const n = Math.max(1, words.length);
  const last = n - 1;

  // The climax: the last word set edge to edge, a hair wider than the frame.
  const lastTrack = -0.02;
  const lastSize = Math.min(
    (W * 1.06) / textWidth(words[last] ?? "", lastTrack),
    (H * 0.62) / CAP,
  );

  // The cards before it grow geometrically from small to half of the climax,
  // so the last cut is still the biggest jump. Weight climbs 300 → 500.
  const firstSize = H * 0.07;
  const peak = lastSize * 0.5;
  const cards = words.map((text, i) => {
    const k = last <= 1 ? 1 : i / (last - 1);
    const climax = i === last;
    const track = climax ? lastTrack : 0.06 - 0.07 * k;
    const target = climax ? lastSize : firstSize * (peak / firstSize) ** k;
    const size = climax
      ? target
      : Math.min(target, (W * 0.84) / textWidth(text, track));
    const weight = climax ? 500 : Math.round(3 + 2 * k) * 100;
    const length = climax
      ? Number.POSITIVE_INFINITY
      : Math.max(4, Math.round(firstBeat * accel ** i));
    return { text, size, track, weight, length, climax };
  });

  let start = 0;
  let active = last;
  let local = 0;
  for (let i = 0; i < cards.length; i++) {
    if (t < start + cards[i].length) {
      active = i;
      local = t - start;
      break;
    }
    start += cards[i].length;
  }
  const card = cards[active];
  const settle = card.climax
    ? interpolate(local, [0, 80], [0, 1], { ...CLAMP, easing: SETTLE })
    : 0;
  const mesh = card.climax ? meshGround(settle, accent, c.pale) : "";
  const ground = card.climax && !c.clip ? mesh : c.bg;
  const ink = card.climax && !c.clip ? "#FFFFFF" : c.fg;

  // A hair of drift keeps each card alive without softening the cut; the
  // climax gets a slow settling push instead.
  const scale = card.climax
    ? 1 + 0.045 * settle
    : 1 + 0.025 * Math.min(1, local / card.length);
  const showDate = card.climax && date !== "" && local >= DATE_DELAY;
  const titleY = card.climax && date !== "" ? H * 0.45 : H * 0.5;
  const dateSize = H * 0.032;

  return (
    <AbsoluteFill style={{ background: ground, overflow: "hidden" }}>
      <Line
        y={titleY}
        size={card.size}
        tracking={card.track}
        weight={card.weight}
        color={ink}
        scale={scale}
        fill={card.climax && c.clip ? { image: mesh, W, H } : undefined}
      >
        {card.text}
      </Line>
      {showDate ? (
        <Line
          y={titleY + (lastSize * CAP * scale) / 2 + H * 0.1}
          size={dateSize}
          tracking={0.36}
          weight={400}
          color={ink}
          scale={1}
        >
          {date}
        </Line>
      ) : null}
    </AbsoluteFill>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/HubotSans";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const hubot = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface ExactlyRound {
  objection: string;
  reply: string;
}

export interface ExactlyProps {
  rounds?: ExactlyRound[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_ROUNDS: ExactlyRound[] = [
  { objection: "There’s nothing to click.", reply: "Good." },
  { objection: "It’s just code.", reply: "Exactly." },
];

const THEMES = {
  dark: {
    bg: "#1C1C1E",
    ink: "#FFFFFF",
    muted: "#9E9EA3",
    accent: "#FFE14D",
  },
  light: {
    bg: "#FFFBEA",
    ink: "#17150F",
    muted: "#7A7363",
    accent: "#9A7A00",
  },
} as const;

const TRACK = -0.03;
const LH = 1.06;
const WORD = 3;
const RISE = 13;
const DROP = 14;
const REFLOW = 20;
const EXIT = 12;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.85, 0.35);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function breakLines(ws: number[], space: number, maxEm: number) {
  const n = ws.length;
  if (n === 0) return [] as number[][];
  let count = 1;
  let x = 0;
  for (let i = 0; i < n; i++) {
    if (x > 0 && x + space + ws[i] > maxEm) {
      count++;
      x = ws[i];
    } else {
      x += (x > 0 ? space : 0) + ws[i];
    }
  }
  if (count === 1) return [ws.map((_, i) => i)];
  const lineW = (i: number, j: number) => {
    let s = 0;
    for (let k = i; k < j; k++) s += ws[k] + (k > i ? space : 0);
    return s;
  };
  const avg = lineW(0, n) / count;
  const INF = 1e12;
  const dp = Array.from({ length: count + 1 }, () =>
    new Array<number>(n + 1).fill(INF),
  );
  const back = Array.from({ length: count + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  dp[0][0] = 0;
  for (let l = 1; l <= count; l++) {
    for (let j = 1; j <= n; j++) {
      for (let i = l - 1; i < j; i++) {
        if (dp[l - 1][i] >= INF) continue;
        const lw = lineW(i, j);
        if (lw > maxEm + 1e-6 && j - i > 1) continue;
        const cost = (lw - avg) ** 2;
        if (dp[l - 1][i] + cost < dp[l][j]) {
          dp[l][j] = dp[l - 1][i] + cost;
          back[l][j] = i;
        }
      }
    }
  }
  if (dp[count][n] >= INF) return [ws.map((_, i) => i)];
  const starts: number[] = [];
  let j = n;
  for (let l = count; l > 0; l--) {
    const i = back[l][j];
    starts.unshift(i);
    j = i;
  }
  return starts.map((s, l) => {
    const e = l + 1 < starts.length ? starts[l + 1] : n;
    return Array.from({ length: e - s }, (_, k) => s + k);
  });
}

function useWidths(specs: string[]) {
  const key = specs.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("exactly: measuring"));
  const released = useRef(false);
  const ref = useRef(specs);
  ref.current = specs;
  useEffect(() => {
    let live = true;
    Promise.all([
      hubot.waitUntilDone(),
      document.fonts.load(`400 100px "${hubot.fontFamily}"`),
      document.fonts.load(`500 100px "${hubot.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        for (const spec of ref.current) {
          const cut = spec.indexOf("|");
          const weight = spec.slice(0, cut);
          const text = spec.slice(cut + 1);
          if (ctx) ctx.font = `${weight} 100px "${hubot.fontFamily}"`;
          w[spec] = ctx ? ctx.measureText(text).width / 100 : text.length * 0.5;
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.w : null;
}

interface Placed {
  x: number;
  y: number;
}

function centred(ws: number[], space: number, maxEm: number) {
  const lines = breakLines(ws, space, maxEm);
  const placed: Placed[] = new Array(ws.length);
  let widest = 0;
  const lineWidths: number[] = [];
  lines.forEach((idx, line) => {
    let lw = 0;
    idx.forEach((k, m) => {
      lw += ws[k] + (m > 0 ? space : 0);
    });
    lineWidths.push(lw);
    widest = Math.max(widest, lw);
    let x = -lw / 2;
    idx.forEach((k, m) => {
      if (m > 0) x += space;
      placed[k] = { x, y: line };
      x += ws[k];
    });
  });
  return { placed, lines: lines.length, widest, lineWidths };
}

export function Exactly({
  rounds = DEFAULT_ROUNDS,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: ExactlyProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames: T } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = rounds.length > 0 ? rounds : DEFAULT_ROUNDS;
  const objs = list.map((r) => r.objection.trim().split(/\s+/));
  const replies = list.map((r) => r.reply.trim());
  const specs = Array.from(
    new Set([
      "500| ",
      "500|“",
      "500|”",
      ...objs.flat().map((s) => `500|${s}`),
      ...replies.map((s) => `500|${s}`),
    ]),
  );
  const w = useWidths(specs);

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const adv = (s: string) =>
    (w[`500|${s}`] ?? 0) + TRACK * Array.from(s).length;
  const space = (w["500| "] ?? 0.25) + 0.04;
  const openW = adv("“");
  const closeW = adv("”");

  const portrait = H > W * 1.1;
  const maxW = W * 0.84;
  const maxLines = portrait ? 5 : 2;
  const maxH = H * (portrait ? 0.46 : 0.5);

  const build = (F: number) =>
    list.map((_, i) => {
      const ows = objs[i].map(adv);
      const rw = adv(replies[i]);
      const full = maxW / F;
      const inline = full - rw - space;
      const own = inline < Math.max(...ows) * 1.15;
      const a = centred(ows, space, own ? full - openW - closeW : inline);
      const shift = own ? 0 : (rw + space) / 2;
      const b = a.placed.map((p) => ({
        x: p.y === 0 ? p.x + shift : p.x,
        y: own ? p.y + 1 : p.y,
      }));
      const replyX = own ? -rw / 2 : -(a.lineWidths[0] + rw + space) / 2;
      const bLines = own ? a.lines + 1 : a.lines;
      const bWidest = own
        ? Math.max(a.widest, rw)
        : Math.max(a.widest, a.lineWidths[0] + rw + space);
      return { a, b, own, replyX, bLines, bWidest };
    });

  let F = portrait ? W * 0.13 : H * 0.15;
  let lays = build(F);
  for (let k = 0; k < 80; k++) {
    const ok = lays.every(
      (l) =>
        l.bLines <= maxLines &&
        (l.a.widest + openW + closeW) * F <= maxW + 0.5 &&
        l.bWidest * F <= maxW + 0.5 &&
        l.bLines * LH * F <= maxH,
    );
    if (ok) break;
    F *= 0.97;
    lays = build(F);
  }
  const lineH = LH * F;

  const startAt: number[] = [];
  const dropAt: number[] = [];
  let clock = 4;
  list.forEach((_, i) => {
    startAt.push(clock);
    clock += objs[i].length * WORD + RISE + 16;
    dropAt.push(clock);
    clock += 6 + REFLOW;
    clock += i < list.length - 1 ? 30 : 0;
  });
  const room = Math.max(1, T - Math.max(30, T * 0.2));
  const k = clock > room ? room / clock : 1;

  const textStyle = (size: number) => ({
    position: "absolute" as const,
    fontSize: size,
    lineHeight: `${lineH}px`,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre" as const,
  });

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily: hubot.fontFamily,
        fontWeight: 500,
      }}
    >
      {list.map((_, i) => {
        const last = i === list.length - 1;
        const leaveAt = last ? 1e9 : startAt[i + 1] * k - 4;
        const leave = interpolate(t, [leaveAt, leaveAt + EXIT], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        if (t < startAt[i] * k - 1 || leave >= 1) return null;
        const { a, b, own, replyX, bLines } = lays[i];
        const ayTop = H / 2 - (a.lines * lineH) / 2;
        const byTop = H / 2 - (bLines * lineH) / 2;
        const cx = W / 2;
        const d0 = dropAt[i] * k;
        const drop = interpolate(t, [d0, d0 + DROP * k], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        const r0 = (dropAt[i] + 6) * k;
        const flow = interpolate(t, [r0, r0 + REFLOW * k], [0, 1], {
          ...CLAMP,
          easing: EASE_IO,
        });
        const words = objs[i];
        const n = words.length;
        const lagOf = (j: number) =>
          Math.min(
            1,
            Math.max(0, flow * 1.15 - ((n - 1 - j) / Math.max(1, n)) * 0.15),
          );
        const posOf = (j: number) => {
          const l = lagOf(j);
          const pa = a.placed[j];
          const pb = b[j];
          return {
            x: cx + (pa.x + (pb.x - pa.x) * l) * F,
            y:
              ayTop +
              pa.y * lineH +
              (byTop + pb.y * lineH - (ayTop + pa.y * lineH)) * l,
          };
        };
        const inAt = (j: number) =>
          interpolate(
            t,
            [(startAt[i] + j * WORD) * k, (startAt[i] + j * WORD + RISE) * k],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
        const first = posOf(0);
        const lastPos = posOf(n - 1);
        const replyIn = interpolate(flow, [0.35, 0.9], [0, 1], CLAMP);
        const reply = own
          ? {
              x: cx + replyX * F,
              y: byTop - (1 - replyIn) * F * 0.2,
            }
          : {
              x: first.x - (space + adv(replies[i])) * F,
              y: first.y,
            };
        const quote = (x: number, y: number, appear: number) => ({
          ...textStyle(F),
          left: x,
          top: y,
          color: c.muted,
          opacity: appear * Math.max(0, 1 - drop * 1.6),
          transform: `translateY(${((1 - appear) * F * 0.18 + drop * F * 0.45).toFixed(2)}px)`,
        });
        return (
          <div
            key={`r${i}`}
            style={{
              position: "absolute",
              inset: 0,
              opacity: 1 - leave,
              transform: `translateY(${(-leave * H * 0.06).toFixed(2)}px)`,
            }}
          >
            <div style={quote(first.x - openW * F, first.y, inAt(0))}>“</div>
            <div
              style={quote(
                lastPos.x + adv(words[n - 1]) * F,
                lastPos.y,
                inAt(n - 1),
              )}
            >
              ”
            </div>
            <div
              style={{
                ...textStyle(F),
                left: reply.x,
                top: reply.y,
                color: hi,
                opacity: replyIn,
              }}
            >
              {replies[i]}
            </div>
            {words.map((word, j) => {
              const e = inAt(j);
              const p = posOf(j);
              return (
                <div
                  key={`w${j}`}
                  style={{
                    ...textStyle(F),
                    left: p.x,
                    top: p.y,
                    color: interpolateColors(flow, [0, 1], [c.muted, c.ink]),
                    opacity: e,
                    transform: `translateY(${((1 - e) * F * 0.18).toFixed(2)}px)`,
                  }}
                >
                  {word}
                </div>
              );
            })}
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

type ExplodedViewColors = {
  background: string;
  top: string;
  left: string;
  right: string;
  highlightTop: string;
  highlightLeft: string;
  highlightRight: string;
  line: string;
  label: string;
};

type ExplodedViewProps = {
  /** Number of slabs, 2 to 6. */
  layers?: number;
  /** One label per slab, top slab first. */
  labels?: string[];
  /** Index of the red slab, counted from the top. */
  highlight?: number;
  colors?: Partial<ExplodedViewColors>;
  /** Background color. Overrides `colors.background`. */
  backgroundColor?: string;
  /** Label text color. Overrides `colors.label`. */
  labelColor?: string;
  speed?: number;
};

const explodedViewDefaults = {
  layers: 4,
  labels: ["Interface", "Engine", "Storage", "Hardware"],
  highlight: 1,
  colors: {
    background: "#111111",
    top: "#F4F4F4",
    left: "#A6A6A6",
    right: "#747474",
    highlightTop: "#E5322D",
    highlightLeft: "#B5231F",
    highlightRight: "#8A1A17",
    line: "#FFFFFF",
    label: "#FFFFFF",
  } satisfies ExplodedViewColors,
  speed: 1,
};

const FONT = "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
const OPEN = 3;
const CLOSE = 38;
const COS30 = Math.cos(Math.PI / 6);
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function ExplodedViewBase({
  layers = explodedViewDefaults.layers,
  labels = explodedViewDefaults.labels,
  highlight = explodedViewDefaults.highlight,
  colors: colorOverrides,
  backgroundColor,
  labelColor,
  speed = explodedViewDefaults.speed,
}: ExplodedViewProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const baseColors = { ...explodedViewDefaults.colors, ...colorOverrides };
  const colors = {
    ...baseColors,
    background: backgroundColor ?? baseColors.background,
    label: labelColor ?? baseColors.label,
  };
  const n = Math.round(Math.min(6, Math.max(2, layers)));
  const t = (frame * speed * 30) / fps;

  const side = height * 0.36;
  const thick = height * 0.036;
  const gap = (height * 0.27) / (n - 1);
  const cx = width * 0.4;
  const cy = height * 0.5;

  const iso = (X: number, Y: number, Z: number) =>
    [(X - Y) * COS30, (X + Y) * 0.5 - Z] as const;
  const pts = (list: (readonly [number, number])[]) =>
    list.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");

  const close = spring({
    frame: t - CLOSE,
    fps: 30,
    config: { damping: 26, stiffness: 320, mass: 0.8 },
  });
  // Top slab leaves first; bottom one barely waits.
  const spread = Array.from({ length: n }, (_, i) => {
    const fromTop = n - 1 - i;
    const open = spring({
      frame: t - OPEN - fromTop * 1.5,
      fps: 30,
      config: { damping: 12, stiffness: 110 },
    });
    return Math.max(0, open * (1 - close));
  });
  const offsets: number[] = [];
  let z = 0;
  for (let i = 0; i < n; i++) {
    offsets.push(z);
    z += thick + (i < n - 1 ? gap * Math.max(spread[i + 1], 0) : 0);
  }
  const total = z;
  // The click: a short downward knock once the slabs meet again.
  const knock =
    interpolate(t, [CLOSE + 5, CLOSE + 7, CLOSE + 12], [0, 1, 0], {
      ...clamp,
      easing: Easing.out(Easing.quad),
    }) *
    height *
    0.008;
  const baseY = cy + side * 0.02 + total / 2 + knock;
  const labelOut = interpolate(t, [CLOSE - 5, CLOSE], [1, 0], clamp);
  const labelX = width * 0.66;
  const fontSize = height * 0.042;

  const slabs: React.ReactNode[] = [];
  const leaders: React.ReactNode[] = [];
  for (let i = 0; i < n; i++) {
    const fromTop = n - 1 - i;
    const hot = fromTop === highlight;
    const z0 = offsets[i];
    const z1 = z0 + thick;
    const h = side / 2;
    const top = [
      iso(-h, -h, z1),
      iso(h, -h, z1),
      iso(h, h, z1),
      iso(-h, h, z1),
    ];
    const left = [iso(-h, h, z1), iso(h, h, z1), iso(h, h, z0), iso(-h, h, z0)];
    const right = [
      iso(h, -h, z1),
      iso(h, h, z1),
      iso(h, h, z0),
      iso(h, -h, z0),
    ];
    const inset = h * 0.78;
    const inner = [
      iso(-inset, -inset, z1),
      iso(inset, -inset, z1),
      iso(inset, inset, z1),
      iso(-inset, inset, z1),
    ];
    const ink = hot ? "#FFFFFF" : "#111111";
    slabs.push(
      <g key={i}>
        <polygon
          points={pts(left)}
          fill={hot ? colors.highlightLeft : colors.left}
        />
        <polygon
          points={pts(right)}
          fill={hot ? colors.highlightRight : colors.right}
        />
        <polygon
          points={pts(top)}
          fill={hot ? colors.highlightTop : colors.top}
        />
        <polygon
          points={pts(inner)}
          fill="none"
          stroke={ink}
          strokeOpacity={0.18}
          strokeWidth={height * 0.002}
        />
        {[-0.4, 0, 0.4].map((k) => {
          const a = iso(-inset * 0.7, k * inset, z1);
          const b = iso(inset * (fromTop % 2 ? 0.2 : 0.7), k * inset, z1);
          return (
            <line
              key={k}
              x1={a[0]}
              y1={a[1]}
              x2={b[0]}
              y2={b[1]}
              stroke={ink}
              strokeOpacity={0.22}
              strokeWidth={height * 0.006}
              strokeLinecap="round"
            />
          );
        })}
      </g>,
    );

    const label = labels[fromTop];
    if (!label) continue;
    const anchor = iso(h, -h, (z0 + z1) / 2);
    const draw = interpolate(
      t,
      [14 + fromTop * 2.5, 24 + fromTop * 2.5],
      [0, 1],
      {
        ...clamp,
        easing: Easing.inOut(Easing.cubic),
      },
    );
    const show =
      interpolate(t, [19 + fromTop * 2.5, 27 + fromTop * 2.5], [0, 1], {
        ...clamp,
        easing: Easing.out(Easing.cubic),
      }) * labelOut;
    const ax = cx + anchor[0] + height * 0.012;
    const ay = baseY + anchor[1];
    const length = (labelX - ax) * draw * labelOut;
    leaders.push(
      <g key={`l${i}`}>
        <circle
          cx={ax}
          cy={ay}
          r={height * 0.006}
          fill={colors.line}
          opacity={Math.min(1, draw * 3) * labelOut}
        />
        <line
          x1={ax}
          y1={ay}
          x2={ax + length}
          y2={ay}
          stroke={colors.line}
          strokeOpacity={0.6}
          strokeWidth={Math.max(1, height * 0.0022)}
        />
        <g
          opacity={show}
          transform={`translate(${labelX + height * 0.02 + (1 - show) * height * 0.03} ${ay})`}
        >
          <text
            y={-fontSize * 0.62}
            fill={hot ? colors.highlightTop : colors.label}
            fillOpacity={hot ? 1 : 0.5}
            fontFamily={FONT}
            fontSize={fontSize * 0.5}
            fontWeight={600}
            letterSpacing="0.12em"
          >
            {`0${fromTop + 1}`}
          </text>
          <text
            y={fontSize * 0.42}
            fill={colors.label}
            fontFamily={FONT}
            fontSize={fontSize}
            fontWeight={700}
            letterSpacing="-0.02em"
          >
            {label}
          </text>
        </g>
      </g>,
    );
  }

  return (
    <AbsoluteFill
      style={{ backgroundColor: colors.background, overflow: "hidden" }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <ellipse
          cx={cx}
          cy={baseY + side * 0.5 + height * 0.035}
          rx={side * COS30 * 1.05}
          ry={side * 0.16}
          fill="#000000"
          opacity={0.5}
        />
        <g transform={`translate(${cx} ${baseY})`}>{slabs}</g>
        {leaders}
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  labels: {
    type: "text-content",
    default: "Interface, Engine, Storage, Hardware",
    description: "Labels (comma-separated)",
  },
  layers: {
    type: "number",
    default: 4,
    min: 2,
    max: 6,
    step: 1,
    description: "Slabs",
    hiddenFromList: false,
  },
  highlight: {
    type: "number",
    default: 1,
    min: 0,
    max: 5,
    step: 1,
    description: "Highlighted slab",
    hiddenFromList: false,
  },
  backgroundColor: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  labelColor: {
    type: "color",
    default: "#FFFFFF",
    description: "Labels",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["labels","layers","highlight","backgroundColor","labelColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  labels: "Interface, Engine, Storage, Hardware",
  layers: 4,
  highlight: 1,
  backgroundColor: "#111111",
  labelColor: "#FFFFFF",
  speed: 1,
};

type ExplodedViewElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ExplodedViewBase>;

const ExplodedViewInner = forwardRef<
  HTMLDivElement,
  ExplodedViewElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ExplodedView>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ExplodedViewBase
          {...(componentProps as unknown as ComponentProps<typeof ExplodedViewBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ExplodedView = Interactive.withSchema({
  Component: ExplodedViewInner,
  componentName: "<ExplodedView>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ExtrudePopProps {
  className?: string;
  width?: number;
  height?: number;
  letter?: string;
  fontFamily?: string;
  fontWeight?: number | string;
  fontSize?: number;
  basePosition?: [number, number];
  maxTextWidth?: number;
  minimaxRadius?: number;
  extrudeAngleDeg?: number;
  extrudeSteps?: number;
  extrudeStartFrame?: number;
  extrudeEndFrame?: number;
  bodyColor?: string;
  faceColor?: string;
}

function ExtrudePopBase({
  className,
  width = 1920,
  height = 1080,
  letter = "WIN",
  fontFamily = "'Helvetica Neue', Helvetica, Arial, sans-serif",
  fontWeight = 700,
  fontSize = 603,
  basePosition = [959.2, 752.5],
  maxTextWidth = 1660,
  minimaxRadius = 80,
  extrudeAngleDeg = -58.6,
  extrudeSteps = 200,
  extrudeStartFrame = 0,
  extrudeEndFrame = 48,
  bodyColor = "#e8192b",
  faceColor = "#ffffff",
}: ExtrudePopProps) {
  const frame = useCurrentFrame();

  const fit = useMemo(() => {
    if (typeof document === "undefined") return 1;
    const ctx = document.createElement("canvas").getContext("2d");
    if (!ctx) return 1;
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    const measured = ctx.measureText(letter).width;
    if (measured <= 0) return 1;
    return Math.min(1, maxTextWidth / measured);
  }, [letter, fontFamily, fontWeight, fontSize, maxTextWidth]);

  const fitFontSize = fontSize * fit;
  const fitRadius = minimaxRadius * fit;

  const radius = interpolate(
    frame,
    [extrudeStartFrame, extrudeEndFrame],
    [0, fitRadius],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    },
  );

  const depth = radius * 2;

  const theta = (extrudeAngleDeg * Math.PI) / 180;
  const stepX = (depth * Math.sin(theta)) / extrudeSteps;
  const stepY = (depth * Math.cos(theta)) / extrudeSteps;

  const glyph = (fill: string, dx: number, dy: number, key?: string) => (
    <text
      key={key}
      x={basePosition[0] + dx}
      y={basePosition[1] + dy}
      textAnchor="middle"
      fontFamily={fontFamily}
      fontWeight={fontWeight}
      fontSize={fitFontSize}
      fill={fill}
    >
      {letter}
    </text>
  );

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ display: "block" }}
      >
        <g>
          {Array.from(
            { length: extrudeSteps + 1 },
            (_, i) => extrudeSteps - i,
          ).map((i) => glyph(bodyColor, stepX * i, stepY * i, `body-${i}`))}
        </g>

        {glyph(faceColor, stepX * extrudeSteps, stepY * extrudeSteps)}
      </svg>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  letter: {
    type: "text-content",
    default: "WIN",
    description: "Text",
  },
  bodyColor: {
    type: "color",
    default: "#e8192b",
    description: "Body color",
  },
  faceColor: {
    type: "color",
    default: "#ffffff",
    description: "Face color",
  },
  minimaxRadius: {
    type: "number",
