const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.6, 0, 0.9, 0.5);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/** Geist 500 advances (per 1000 em), ASCII 32–126. Used to size, not to place. */
const GEIST_500 = [
  243, 230, 349, 513, 632, 853, 668, 174, 329, 329, 420, 563, 186, 432, 186,
  457, 677, 374, 614, 600, 629, 629, 610, 507, 629, 613, 227, 227, 547, 544,
  547, 517, 901, 678, 681, 704, 701, 610, 596, 692, 705, 281, 592, 652, 584,
  883, 738, 739, 653, 739, 673, 642, 558, 696, 688, 956, 633, 586, 557, 342,
  439, 342, 438, 532, 257, 556, 591, 549, 591, 566, 413, 591, 581, 256, 274,
  565, 283, 852, 581, 562, 592, 591, 394, 535, 414, 587, 548, 806, 559, 540,
  499, 405, 274, 406, 522,
];

function textEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += c >= 32 && c <= 126 ? GEIST_500[c - 32] : 600;
  }
  return w / 1000;
}

interface Word {
  text: string;
  line: number;
  index: number;
  /** Char range inside the highlight, as fractions of the highlight. */
  hl: [number, number] | null;
}

function splitWords(headline: string, highlight: string | undefined) {
  const lower = headline.toLowerCase();
  const hStart = highlight ? lower.indexOf(highlight.toLowerCase()) : -1;
  const hEnd = hStart >= 0 && highlight ? hStart + highlight.length : -1;
  const hLen = Math.max(1, hEnd - hStart);
  const words: Word[] = [];
  const re = /\S+|\n/g;
  let line = 0;
  let index = 0;
  for (let m = re.exec(headline); m; m = re.exec(headline)) {
    if (m[0] === "\n") {
      line += 1;
      continue;
    }
    const a = m.index;
    const b = a + m[0].length;
    const inside = hStart >= 0 && a < hEnd && b > hStart;
    words.push({
      text: m[0],
      line,
      index: index++,
      hl: inside
        ? [
            (Math.max(a, hStart) - hStart) / hLen,
            (Math.min(b, hEnd) - hStart) / hLen,
          ]
        : null,
    });
  }
  return { words, lines: line + 1 };
}

/**
 * One gradient spans the whole highlighted phrase even though each word is
 * its own masked span: every word shows its slice of a gradient sized to the
 * phrase (1.6x wider so it can drift slowly).
 */
function highlightFill(
  [a, b]: [number, number],
  drift: number,
  image: string,
): React.CSSProperties {
  const f = Math.max(0.02, b - a);
  const K = 1.6 / f;
  const o = drift * 0.35;
  const P = (a / f + o * K) / (K - 1);
  return {
    backgroundImage: image,
    backgroundSize: `${K * 100}% 100%`,
    backgroundPosition: `${P * 100}% 0%`,
    WebkitBackgroundClip: "text",
    backgroundClip: "text",
    color: "transparent",
  };
}

function FeatureHeadlineBase({
  tag = "New",
  label = "Captions",
  headline = "Captions that move with every word.",
  highlight = "every word",
  subhead = "31 transcript-driven caption styles, ready to drop into any video.",
  align = "left",
  exit = true,
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: FeatureHeadlineProps) {
  const raw = useCurrentFrame();
  const frame = raw * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const p = PALETTES[theme];
  const centre = align === "center";

  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.55
    : Math.min(width / 1280, height / 720);
  const padX = width * (portrait ? 0.08 : 0.09);
  const maxW = Math.min(width - padX * 2, (portrait ? 2000 : 1040) * s);

  // headline size: two lines at most at full size, then shrink to a floor
  const { words, lines: hardLines } = splitWords(headline, highlight);
  const flat = headline.replace(/\n/g, " ");
  const baseFs = (portrait ? 104 : 94) * s;
  const est = (textEm(flat) - 0.035 * flat.length) * 1.06;
  const linesAtBase = Math.max(hardLines, Math.ceil((est * baseFs) / maxW));
  const fs =
    linesAtBase <= 2
      ? baseFs
      : Math.max(baseFs * 0.72, (maxW * 2) / Math.max(est, 1));

  // ---- timing ----------------------------------------------------------------
  const pillT = interpolate(frame, [0, 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const wordT = (i: number) =>
    interpolate(frame, [4 + i * 2, 20 + i * 2], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const subStart = 12 + Math.min(words.length, 8) * 1.5;
  const subT = interpolate(frame, [subStart, subStart + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const EXIT = 12;
  const exitStart = durationInFrames - EXIT;
  const exitT = (delay: number) =>
    exit
      ? interpolate(raw, [exitStart + delay, exitStart + delay + 9], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        })
      : 0;
  const drift = interpolate(raw, [0, durationInFrames], [0, 1], CLAMP);

  const transparent = background === "transparent";
  const showPill = label.length > 0;
  const pillFs = 19 * s;
  const pillExit = exitT(0);
  const clip = (1 - pillT) * 100;
  const pillClip = centre
    ? `inset(0 ${clip / 2}% 0 ${clip / 2}% round 999px)`
    : `inset(0 ${clip}% 0 0 round 999px)`;
  const subExit = exitT(1);

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: p.ground.join(", "),
            transform: `translate(${(-drift * 2).toFixed(3)}%, ${(drift * 1.5).toFixed(3)}%) scale(1.06)`,
          }}
        />
      ) : null}

      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: `0 ${padX}px`,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: centre ? "center" : "flex-start",
          textAlign: centre ? "center" : "left",
        }}
      >
        {showPill ? (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: pillFs * 0.6,
              height: pillFs * 2.15,
              padding: `0 ${pillFs * 0.95}px 0 ${tag ? pillFs * 0.3 : pillFs * 0.95}px`,
              borderRadius: 999,
              background: p.pillBg,
              boxShadow: `inset 0 0 0 1px ${p.pillLine}`,
              clipPath: pillClip,
              opacity: 1 - pillExit,
              transform: `translateY(${-pillExit * 14 * s}px)`,
              marginBottom: fs * 0.42,
            }}
          >
            {tag ? (
              <span
                style={{
                  display: "flex",
                  alignItems: "center",
                  height: pillFs * 1.55,
                  padding: `0 ${pillFs * 0.6}px`,
                  borderRadius: 999,
                  background: accent,
                  color: p.tagFg,
                  fontFamily: mono.fontFamily,
                  fontWeight: 500,
                  fontSize: pillFs * 0.72,
                  letterSpacing: "0.08em",
                  textTransform: "uppercase",
                  transform: `translateX(${(1 - pillT) * -10 * s}px)`,
                }}
              >
                {tag}
              </span>
            ) : null}
            <span
              style={{
                fontFamily: geist.fontFamily,
                fontWeight: 500,
                fontSize: pillFs,
                letterSpacing: "-0.01em",
                color: p.fg,
                whiteSpace: "nowrap",
                opacity: interpolate(pillT, [0.3, 1], [0, 1], CLAMP),
                transform: `translateX(${(1 - pillT) * -14 * s}px)`,
              }}
            >
              {label}
            </span>
          </div>
        ) : null}

        <div
          style={{
            maxWidth: maxW,
            fontFamily: geist.fontFamily,
            fontWeight: 500,
            fontSize: fs,
            lineHeight: 1.06,
            letterSpacing: "-0.035em",
            color: p.fg,
          }}
        >
          {Array.from({ length: hardLines }, (_, line) => (
            <div key={line} style={{ textWrap: "balance" }}>
              {words
                .filter((w) => w.line === line)
                .map((w, k) => {
                  const t = wordT(w.index);
                  const out = exitT(w.index * 0.6);
                  const y = (1 - t) * 108 - out * 108;
                  const hlStyle: React.CSSProperties = w.hl
                    ? highlightFill(w.hl, drift, p.highlight(accent))
                    : {};
                  return (
                    <Fragment key={w.index}>
                      {k > 0 ? " " : null}
                      <span
                        style={{
                          display: "inline-block",
                          overflow: "hidden",
                          verticalAlign: "top",
                          paddingBottom: "0.14em",
                          marginBottom: "-0.14em",
                          paddingRight: "0.04em",
                          marginRight: "-0.04em",
                        }}
                      >
                        <span
                          style={{
                            display: "inline-block",
                            transform: `translateY(${y}%)`,
                            ...hlStyle,
                          }}
                        >
                          {w.text}
                        </span>
                      </span>
                    </Fragment>
                  );
                })}
            </div>
          ))}
        </div>

        {subhead ? (
          <div
            style={{
              marginTop: fs * 0.36,
              maxWidth: Math.min(maxW * 0.82, 760 * s * (portrait ? 1.3 : 1)),
              fontFamily: geist.fontFamily,
              fontWeight: 400,
              fontSize: (portrait ? 30 : 26) * s,
              lineHeight: 1.4,
              letterSpacing: "-0.008em",
              color: p.muted,
              textWrap: "balance",
              opacity: subT * (1 - subExit),
              transform: `translateY(${(1 - subT) * 14 * s - subExit * 12 * s}px)`,
              filter: `blur(${(1 - subT) * 6 * s}px)`,
            }}
          >
            {subhead}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  tag: {
    type: "text-content",
    default: "New",
    description: "Tag",
  },
  label: {
    type: "text-content",
    default: "Captions",
    description: "Label",
  },
  headline: {
    type: "text-content",
    default: "Captions that move with every word.",
    description: "Headline",
  },
  highlight: {
    type: "text-content",
    default: "every word",
    description: "Highlight",
  },
  subhead: {
    type: "text-content",
    default: "31 transcript-driven caption styles, ready to drop into any video.",
    description: "Subhead",
  },
  align: {
    type: "enum",
    default: "left",
    variants: {
      left: {},
      center: {},
    },
    description: "Align",
  },
  exit: {
    type: "boolean",
    default: true,
    description: "Exit",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","tag","label","headline","highlight","subhead","align","exit","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  tag: "New",
  label: "Captions",
  headline: "Captions that move with every word.",
  highlight: "every word",
  subhead: "31 transcript-driven caption styles, ready to drop into any video.",
  align: "left",
  exit: true,
  speed: 1,
};

type FeatureHeadlineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FeatureHeadlineBase>;

const FeatureHeadlineInner = forwardRef<
  HTMLDivElement,
  FeatureHeadlineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FeatureHeadline>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FeatureHeadlineBase
          {...(componentProps as unknown as ComponentProps<typeof FeatureHeadlineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FeatureHeadline = Interactive.withSchema({
  Component: FeatureHeadlineInner,
  componentName: "<FeatureHeadline>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadBricolage } from "@remotion/google-fonts/BricolageGrotesque";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

const bricolage = loadBricolage("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const geist = loadGeist("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

/**
 * Beat sheet (30fps, speed 1, three items, 165 frames):
 * 6–40     "Fast." rises out of a mask at hero size, its line follows; a row
 *          of progress ticks under it fills for the current item.
 * 40–74    it leaves upward as "Composable." rises into the same spot.
 * 74–104   "Open source." rises and holds.
 * 104–132  resolve: the last title shrinks and travels into its column,
 *          the earlier titles rise back into theirs, the ticks stretch into
 *          the column rules, descriptions settle under each.
 * 132–165  poster hold.
 * The per-item slot stretches or shrinks with `durationInFrames`.
 */

interface FeatureTrioItem {
  title: string;
  description: string;
}

interface FeatureTrioProps {
  /** 2–4 short benefits. */
  items?: FeatureTrioItem[];
  accent?: string;
  /** Stage fill. "transparent" drops the stage and its glow. */
  background?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

/** gradients.sh "grain": bg #070505, [#ffd8b4, #e0703b, #8a2c1d, #2b1015]. */
const GRAIN = ["#ffd8b4", "#e0703b", "#8a2c1d", "#2b1015"] as const;
/** gradients.sh "smear" (light): bg #efe8dc, [#f2552c, #f7b23b, #e889b5, #2f6b3f]. */
const SMEAR = ["#f2552c", "#f7b23b", "#e889b5", "#2f6b3f"] as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    track: "rgba(255,255,255,0.14)",
    rule: "rgba(255,255,255,0.22)",
    glow: [GRAIN[0], GRAIN[1], GRAIN[2]],
    glowAlpha: [0.36, 0.4, 0.42],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    track: "rgba(17,17,19,0.12)",
    rule: "rgba(17,17,19,0.2)",
    glow: [SMEAR[1], SMEAR[0], SMEAR[2]],
    glowAlpha: [0.22, 0.16, 0.18],
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.6, 0, 0.9, 0.5);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/** Bricolage Grotesque 500 advances (per 1000 em), ASCII 32–126. */
const BRICOLAGE_500 = [
  246, 266, 317, 612, 630, 947, 756, 158, 305, 290, 395, 516, 165, 339, 196,
  353, 656, 320, 583, 595, 595, 599, 646, 493, 645, 640, 207, 187, 516, 516,
  516, 413, 952, 671, 666, 670, 691, 599, 578, 706, 708, 274, 357, 666, 508,
  908, 746, 716, 629, 719, 660, 641, 553, 719, 657, 957, 652, 600, 560, 315,
  341, 300, 546, 578, 283, 567, 618, 555, 617, 570, 380, 588, 608, 259, 266,
  561, 257, 912, 608, 604, 618, 617, 411, 535, 380, 599, 546, 827, 534, 591,
  500, 353, 259, 331, 516,
];
const TRACK = -0.04;

function titleEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += c >= 32 && c <= 126 ? BRICOLAGE_500[c - 32] : 620;
  }
  return w / 1000 + TRACK * [...text].length;
}

const DEFAULT_ITEMS: FeatureTrioItem[] = [
  { title: "Fast.", description: "Drop in a scene and render it in minutes." },
  {
    title: "Composable.",
    description: "Every piece is a React component you can remix.",
  },
  {
    title: "Open source.",
    description: "MIT licensed. The code lands in your repo.",
  },
];

function FeatureTrioBase({
  items = DEFAULT_ITEMS,
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: FeatureTrioProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const p = PALETTES[theme];
  const list = items.slice(0, 4);
  const n = list.length;
  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.5
    : Math.min(width / 1280, height / 720);

  // ---- timing ----------------------------------------------------------------
  const START = 6;
  const RESOLVE = 24;
  const HOLD = 36;
  const total = durationInFrames * speed;
  const slot = Math.max(
    22,
    Math.min(40, (total - START - RESOLVE - HOLD + 4) / Math.max(1, n)),
  );
  const at = (i: number) => START + i * slot;
  const r0 = at(n - 1) + slot - 4;
  const resolve = interpolate(frame, [r0, r0 + RESOLVE], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // ---- geometry ----------------------------------------------------------------
  const maxEm = Math.max(...list.map((it) => titleEm(it.title)), 1);
  const heroFs = Math.min((portrait ? 150 : 172) * s, (width * 0.84) / maxEm);
  const heroY = height * (portrait ? 0.46 : 0.45);
  const heroDescFs = (portrait ? 34 : 28) * s;
  const heroDescTop = heroY + heroFs * 0.52 + 18 * s;
  // progress ticks sit above the hero title, so on the way to becoming the
  // column rules they never cross a line of text
  const ticksY = heroY - heroFs * 0.62 - (portrait ? 48 : 34) * s;
  const tickW = 40 * s;
  const tickGap = 8 * s;
  const ticksW = n * tickW + (n - 1) * tickGap;

  // final layout: a row (landscape) or a stack (portrait)
  const rowW = Math.min(width * 0.88, 1180 * s);
  const colW = portrait ? width * 0.84 : rowW / n;
  const gutter = (portrait ? 0 : 26) * s;
  const rowFs = portrait
    ? Math.min(84 * s, (colW * 0.92) / maxEm)
    : Math.min(60 * s, ((colW - gutter * 2) * 0.94) / maxEm);
  const rowDescFs = (portrait ? 28 : 19) * s;
  const ruleToTitle = rowFs * 0.5 + 30 * s;
  const titleToDesc = rowFs * 0.52 + 12 * s;
  const blockH = ruleToTitle + titleToDesc + rowDescFs * 1.45 * 2;
  const stackGap = 64 * s;
  const col = (i: number) => {
    if (portrait) {
      const groupH = n * blockH + (n - 1) * stackGap;
      const top = height / 2 - groupH / 2 + i * (blockH + stackGap);
      return { x: width / 2, ruleY: top, w: colW * 0.4 };
    }
    const groupH = blockH;
    return {
      x: width / 2 - rowW / 2 + colW * (i + 0.5),
      ruleY: height / 2 - groupH / 2,
      w: colW - gutter * 2,
    };
  };

  const transparent = background === "transparent";

  // the glow breathes with each new item and widens into a band for the row
  const beat = list.reduce(
    (acc, _, i) =>
      acc +
      interpolate(
        frame,
        [at(i), at(i) + 10, at(i) + slot],
        [0, 1, 0.35],
        CLAMP,
      ) *
        (i === n - 1
          ? 1
          : interpolate(frame, [at(i + 1), at(i + 1) + 6], [1, 0], CLAMP)),
    0,
  );
  const glowIn = interpolate(frame, [0, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const glowW = interpolate(resolve, [0, 1], [46, 95]);
  const glowH = interpolate(resolve, [0, 1], [58, 44]);
  const glowY = interpolate(resolve, [0, 1], [104, 112]);
  const glowLift = 0.75 + Math.min(1, beat) * 0.25;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            opacity: glowIn * glowLift,
            background: [
              `radial-gradient(${glowW * 0.6}% ${glowH * 0.6}% at 50% ${glowY}%, color-mix(in oklab, ${p.glow[0]} ${p.glowAlpha[0] * 100}%, transparent) 0%, transparent 70%)`,
              `radial-gradient(${glowW * 0.85}% ${glowH * 0.85}% at 50% ${glowY}%, color-mix(in oklab, ${p.glow[1]} ${p.glowAlpha[1] * 100}%, transparent) 0%, transparent 70%)`,
              `radial-gradient(${glowW * 1.1}% ${glowH * 1.1}% at 50% ${glowY + 4}%, color-mix(in oklab, ${p.glow[2]} ${p.glowAlpha[2] * 100}%, transparent) 0%, transparent 72%)`,
            ].join(", "),
          }}
        />
      ) : null}

      {/* ticks → column rules */}
      {list.map((it, i) => {
        const c = col(i);
        const tickX =
          width / 2 - ticksW / 2 + i * (tickW + tickGap) + tickW / 2;
        const x = interpolate(resolve, [0, 1], [tickX, c.x]);
        const y = interpolate(resolve, [0, 1], [ticksY, c.ruleY]);
        const w = interpolate(resolve, [0, 1], [tickW, c.w]);
        const th = interpolate(resolve, [0, 1], [3, 1.5]) * s;
        const fill =
          i === n - 1
            ? interpolate(frame, [at(i), at(i) + slot - 6], [0, 1], CLAMP)
            : interpolate(frame, [at(i), at(i + 1)], [0, 1], CLAMP);
        const tickIn = interpolate(frame, [0, 14], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        // the accent hands over to a neutral rule once the row stands
        const accentShare = 1 - resolve;
        return (
          <div
            key={`${it.title}-rule`}
            style={{
              position: "absolute",
              left: x - w / 2,
              top: y - th / 2,
              width: w,
              height: th,
              borderRadius: th,
              background: resolve > 0 ? p.rule : p.track,
              overflow: "hidden",
              opacity: tickIn,
              transform: `scaleX(${0.4 + tickIn * 0.6})`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: `${fill * 100}%`,
                background: accent,
                opacity: accentShare,
              }}
            />
          </div>
        );
      })}

      {list.map((it, i) => {
        const last = i === n - 1;
        const c = col(i);
        const rowTitleY = c.ruleY + ruleToTitle;
        const rowDescTop = c.ruleY + ruleToTitle + titleToDesc;

        // solo: rise in, hold, leave upward (except the last)
        const rise = interpolate(frame, [at(i), at(i) + 14], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        const leave = last
          ? 0
          : interpolate(frame, [at(i + 1) - 8, at(i + 1) + 2], [0, 1], {
              ...CLAMP,
              easing: EASE_IN,
            });
        const descIn = interpolate(frame, [at(i) + 5, at(i) + 19], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        // row: earlier titles come back into their columns
        const back = interpolate(
          frame,
          [r0 + 15 + i * 3, r0 + 31 + i * 3],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        );
        const rowDescIn = interpolate(
          frame,
          [r0 + 20 + i * 3, r0 + 36 + i * 3],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        );

        const titleStyle = {
          fontFamily: bricolage.fontFamily,
          fontWeight: 500,
          letterSpacing: `${TRACK}em`,
          lineHeight: 1,
          color: p.fg,
          whiteSpace: "nowrap" as const,
        };

        // hero copy (and, for the last item, the copy that travels)
        const heroX = last
          ? interpolate(resolve, [0, 1], [width / 2, c.x])
          : width / 2;
        const heroYNow = last
          ? interpolate(resolve, [0, 1], [heroY, rowTitleY])
          : heroY;
        const heroFsNow = last
          ? interpolate(resolve, [0, 1], [heroFs, rowFs])
          : heroFs;
        const soloY = (1 - rise) * 112 - leave * 112;
        const heroVisible = rise > 0 && leave < 1 && (last || frame < r0);
        const heroDescOut = last
          ? interpolate(resolve, [0, 0.35], [1, 0], CLAMP)
          : interpolate(frame, [at(i + 1) - 10, at(i + 1) - 3], [1, 0], CLAMP);

        return (
          <div key={it.title}>
            {heroVisible ? (
              <>
                <div
                  style={{
                    position: "absolute",
                    left: heroX,
                    top: heroYNow,
                    transform: "translate(-50%, -50%)",
                    overflow: resolve > 0 && last ? "visible" : "hidden",
                    padding: `${heroFsNow * 0.08}px ${heroFsNow * 0.06}px ${heroFsNow * 0.14}px`,
                  }}
                >
                  <div
                    style={{
                      ...titleStyle,
                      fontSize: heroFsNow,
                      transform: `translateY(${soloY}%)`,
                    }}
                  >
                    {it.title}
                  </div>
                </div>
                <div
                  style={{
                    position: "absolute",
                    left: width / 2 - width * 0.35,
                    width: width * 0.7,
                    top: heroDescTop,
                    textAlign: "center",
                    textWrap: "balance",
                    fontFamily: geist.fontFamily,
                    fontWeight: 400,
                    fontSize: heroDescFs,
                    lineHeight: 1.35,
                    letterSpacing: "-0.01em",
                    color: p.muted,
                    opacity: descIn * heroDescOut,
                    transform: `translateY(${(1 - descIn) * 12 * s - (1 - heroDescOut) * 10 * s}px)`,
                    filter: `blur(${(1 - descIn) * 5 * s}px)`,
                  }}
                >
                  {it.description}
                </div>
              </>
            ) : null}

            {/* row copy for the earlier items */}
            {!last && back > 0 ? (
              <div
                style={{
                  position: "absolute",
                  left: c.x,
                  top: rowTitleY,
                  transform: "translate(-50%, -50%)",
                  overflow: "hidden",
                  padding: `${rowFs * 0.08}px ${rowFs * 0.06}px ${rowFs * 0.14}px`,
                }}
              >
                <div
                  style={{
                    ...titleStyle,
                    fontSize: rowFs,
                    transform: `translateY(${(1 - back) * 112}%)`,
                  }}
                >
                  {it.title}
                </div>
              </div>
            ) : null}

            {/* row description */}
            {rowDescIn > 0 ? (
              <div
                style={{
                  position: "absolute",
                  left: c.x - (portrait ? colW : c.w) / 2,
                  width: portrait ? colW : c.w,
                  top: rowDescTop,
                  textAlign: "center",
                  textWrap: "balance",
                  fontFamily: geist.fontFamily,
                  fontWeight: 400,
                  fontSize: rowDescFs,
                  lineHeight: 1.45,
                  letterSpacing: "-0.005em",
                  color: p.muted,
                  opacity: rowDescIn,
                  transform: `translateY(${(1 - rowDescIn) * 10 * s}px)`,
                  filter: `blur(${(1 - rowDescIn) * 4 * s}px)`,
                }}
              >
                {it.description}
              </div>
            ) : null}
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

