          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FeatureTrioBase
          {...(componentProps as unknown as ComponentProps<typeof FeatureTrioBase>)}
        />
      </div>
    </Sequence>
  );
});

