const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");

interface Token {
  said: string;
  keep: number;
  cut: number;
}

function plan(transcript: string, keep: string) {
  const said = transcript.split(/\s+/).filter(Boolean);
  const kept = keep.split(/\s+/).filter(Boolean);
  const tokens: Token[] = said.map((s) => ({ said: s, keep: -1, cut: -1 }));
  let j = 0;
  for (let i = 0; i < tokens.length && j < kept.length; i++)
    if (norm(tokens[i].said) === norm(kept[j])) tokens[i].keep = j++;
  const extra = kept.map((_, q) => q).filter((q) => q >= j);
  let cuts = 0;
  tokens.forEach((tk, i) => {
    if (tk.keep >= 0) return;
    tk.cut = i > 0 && tokens[i - 1].cut >= 0 ? tokens[i - 1].cut : cuts++;
  });
  return { tokens, kept, extra, cuts };
}

interface Metrics {
  said: number[];
  head: number[];
  space400: number;
  space500: number;
}

function measure(said: string[], kept: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  const fam = `"${grotesk.fontFamily}"`;
  if (!ctx)
    return {
      said: said.map((s) => s.length * 0.5),
      head: kept.map((s) => s.length * 0.52),
      space400: 0.25,
      space500: 0.25,
    };
  const width = (s: string, track: number) =>
    ctx.measureText(s).width / 1000 + track * Array.from(s).length;
  ctx.font = `400 1000px ${fam}`;
  const s400 = said.map((s) => width(s, SPEAK_TRACK));
  const space400 = ctx.measureText(" ").width / 1000;
  ctx.font = `500 1000px ${fam}`;
  const h500 = kept.map((s) => width(s, HEAD_TRACK));
  const space500 = ctx.measureText(" ").width / 1000;
  return { said: s400, head: h500, space400, space500 };
}

function useMetrics(said: string[], kept: string[]) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("filler-cut: measuring"));
  const released = useRef(false);
  const key = `${said.join(" ")}\n${kept.join(" ")}`;
  useEffect(() => {
    let live = true;
    Promise.all([
      grotesk.waitUntilDone(),
      mono.waitUntilDone(),
      document.fonts.load(`400 100px "${grotesk.fontFamily}"`),
      document.fonts.load(`500 100px "${grotesk.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [a, b] = key.split("\n");
        setMetrics(
          measure(a.split(" ").filter(Boolean), b.split(" ").filter(Boolean)),
        );
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return metrics;
}

function wrap(widths: number[], space: number, size: number, maxW: number) {
  const line: number[] = [];
  let li = 0;
  let x = 0;
  widths.forEach((w, i) => {
    const add = (x > 0 ? space : 0) * size + w * size;
    if (x > 0 && x + add > maxW) {
      li++;
      x = w * size;
    } else x += add;
    line[i] = li;
  });
  return line;
}

function headlineBreaks(
  widths: number[],
  space: number,
  maxW: number,
  cap: number,
) {
  const n = widths.length;
  let best: { line: number[]; size: number } | null = null;
  const tries: { line: number[]; size: number }[] = [];
  for (let mask = 0; mask < 1 << Math.max(0, n - 1); mask++) {
    let k = 1;
    for (let q = 0; q < n - 1; q++) if (mask & (1 << q)) k++;
    if (k > 3) continue;
    const line: number[] = [0];
    const lw = [widths[0]];
    for (let q = 1; q < n; q++) {
      if (mask & (1 << (q - 1))) {
        line.push(line[q - 1] + 1);
        lw.push(widths[q]);
      } else {
        line.push(line[q - 1]);
        lw[lw.length - 1] += space + widths[q];
      }
    }
    const widest = Math.max(...lw);
    const spread = widest - Math.min(...lw);
    tries.push({ line, size: Math.min(cap, maxW / widest) - spread * 0.001 });
  }
  const top = Math.max(...tries.map((r) => r.size));
  for (const r of tries) {
    const k = r.line[r.line.length - 1] + 1;
    const bk = best ? best.line[best.line.length - 1] + 1 : 99;
    if (r.size < top * 0.9) continue;
    if (!best || k < bk || (k === bk && r.size > best.size)) best = r;
  }
  return best ?? { line: widths.map(() => 0), size: cap };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `fc${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={9}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const lerp = (a: number, b: number, p: number) => a + (b - a) * p;

const shade = (a: string, b: string, p: number) =>
  p <= 0
    ? b
    : p >= 1
      ? a
      : `color-mix(in oklab, ${a} ${(p * 100).toFixed(1)}%, ${b})`;

const clock = (sec: number) => {
  const s = Math.max(0, sec);
  const whole = Math.floor(s);
  const tenth = Math.floor((s - whole) * 10);
  return `0:${String(whole).padStart(2, "0")}.${tenth}`;
};

function FillerCutBase({
  transcript = "So, um, ship your, like, launch video, uh, today. You know?",
  keep = "Ship your launch video today.",
  highlight = "today.",
  showTime = true,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: FillerCutProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const P = useMemo(() => plan(transcript, keep), [transcript, keep]);
  const m = useMetrics(
    P.tokens.map((tk) => tk.said),
    P.kept,
  );

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: c.bg }} />;
  }

  const portrait = H > W;
  const unit = Math.min(W, H);
  const left = W * (portrait ? 0.08 : 0.1);
  const maxW = W - left * 2;
  const sA = portrait ? W * 0.075 : unit * 0.084;
  const lineA = wrap(m.said, m.space400, sA, maxW);
  const nLinesA = (lineA[lineA.length - 1] ?? 0) + 1;

  const n = P.tokens.length;
  const speakPer = Math.min(SPEAK_PER, SPEAK_MAX / Math.max(1, n - 1));
  const markAt = Math.max(MARK_AT, SPEAK_AT + (n - 1) * speakPer + 8);
  const cutAt = markAt + MARK_TO_CUT;
  const cutP = (k: number) =>
    interpolate(
      t,
      [cutAt + k * CUT_GAP, cutAt + k * CUT_GAP + CUT_LEN],
      [0, 1],
      { ...CLAMP, easing: EASE_CUT },
    );
  const collapse = P.tokens.map((tk) => (tk.cut >= 0 ? cutP(tk.cut) : 0));

  const ripple = (col: number[]) => {
    const lineH = new Array(nLinesA).fill(0);
    for (let li = 0; li < nLinesA; li++) {
      let h = 0;
      for (let i = 0; i < n; i++)
        if (lineA[i] === li) h = Math.max(h, 1 - col[i]);
      lineH[li] = h * SPEAK_LEAD * sA;
    }
    const total = lineH.reduce((a, b) => a + b, 0);
    const top = H * 0.5 - total / 2;
    const xs: number[] = [];
    const ys: number[] = [];
    let y = top;
    for (let li = 0; li < nLinesA; li++) {
      let x = left;
      P.tokens.forEach((_, i) => {
        if (lineA[i] !== li) return;
        xs[i] = x;
        ys[i] = y + (SPEAK_LEAD * sA) / 2;
        x += (m.said[i] + m.space400) * sA * (1 - col[i]);
      });
      y += lineH[li];
    }
    return { xs, ys, total, top };
  };
  const live = ripple(collapse);
  const cutDone = ripple(P.tokens.map((tk) => (tk.cut >= 0 ? 1 : 0)));

  const cap = portrait ? W * 0.15 : H * 0.19;
  const hb = headlineBreaks(m.head, m.space500, maxW, cap);
  const sC = hb.size;
  const nLinesC = (hb.line[hb.line.length - 1] ?? 0) + 1;
  const blockC = nLinesC * HEAD_LEAD * sC;
  const topC = H * 0.5 - blockC / 2;
  const headX: number[] = [];
  const headY: number[] = [];
  {
    let x = left;
    let prev = -1;
    P.kept.forEach((_, q) => {
      if (hb.line[q] !== prev) {
        x = left;
        prev = hb.line[q];
      }
      headX[q] = x;
      headY[q] = topC + (hb.line[q] + 0.5) * HEAD_LEAD * sC;
      x += (m.head[q] + m.space500) * sC;
    });
  }

  const cutEnd = cutAt + Math.max(0, P.cuts - 1) * CUT_GAP + CUT_LEN;
  const reflowAt = cutEnd + REFLOW_GAP;
  const reflowEarly = interpolate(
    t,
    [reflowAt, reflowAt + REFLOW_LEN * 0.6],
    [0, 1],
    { ...CLAMP, easing: EASE_SET },
  );
  const reflowLate = interpolate(
    t,
    [reflowAt + REFLOW_LEN * 0.4, reflowAt + REFLOW_LEN],
    [0, 1],
    { ...CLAMP, easing: EASE_SET },
  );
  const reflowP = reflowEarly;
  const keptIdx = P.tokens.flatMap((tk, i) => (tk.keep >= 0 ? [i] : []));
  const lineB = wrap(
    keptIdx.map((i) => m.said[i]),
    m.space400,
    sA,
    maxW,
  );
  const nLinesB = (lineB[lineB.length - 1] ?? 0) + 1;
  const topB = H * 0.5 - (nLinesB * SPEAK_LEAD * sA) / 2;
  const reX: number[] = [];
  const reY: number[] = [];
  {
    let x = left;
    let prev = -1;
    keptIdx.forEach((i, r) => {
      if (lineB[r] !== prev) {
        x = left;
        prev = lineB[r];
      }
      reX[i] = x;
      reY[i] = topB + (lineB[r] + 0.5) * SPEAK_LEAD * sA;
      x += (m.said[i] + m.space400) * sA;
    });
  }
  const setAt = reflowAt + REFLOW_LEN + SET_GAP;
  const setP = interpolate(t, [setAt, setAt + SET_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_SET,
  });
  const setY = interpolate(t, [setAt, setAt + SET_LEN * 0.7], [0, 1], {
    ...CLAMP,
    easing: EASE_SET,
  });
  const markP = interpolate(t, [markAt, markAt + 8], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const hiP = interpolate(
    t,
    [setAt + SET_LEN - 6, setAt + SET_LEN + 10],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const hiStart = highlight ? keep.lastIndexOf(highlight) : -1;
  const isHi = (q: number) => {
    if (hiStart < 0) return false;
    let at = 0;
    const words = keep.split(/\s+/).filter(Boolean);
    for (let i = 0; i < q; i++)
      at = keep.indexOf(words[i], at) + words[i].length;
    const s = keep.indexOf(words[q], at);
    return s < hiStart + highlight.length && s + words[q].length > hiStart;
  };
  const fill = `linear-gradient(100deg, ${c.stops[0]} 0%, ${c.stops[1]} 55%, ${accent} 100%)`;

  const els: React.ReactNode[] = [];
  P.tokens.forEach((tk, i) => {
    const spoken = interpolate(
      t,
      [SPEAK_AT + i * speakPer, SPEAK_AT + i * speakPer + 8],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const survivor = tk.keep >= 0;
    if (!survivor) {
      const col = collapse[i];
      if (col >= 1) return;
      els.push(
        <div
          key={`s${i}`}
          style={{
            position: "absolute",
            left: live.xs[i],
            top: live.ys[i] - sA * 0.5,
            fontFamily: grotesk.fontFamily,
            fontWeight: 400,
            fontSize: sA,
            lineHeight: `${sA}px`,
            letterSpacing: `${SPEAK_TRACK}em`,
            whiteSpace: "pre",
            color: shade(c.filler, c.muted, markP),
            opacity: spoken * (1 - col) ** 0.6,
            transformOrigin: "0% 50%",
            transform: `translateY(${((1 - spoken) * sA * 0.4).toFixed(2)}px) scaleX(${(1 - col).toFixed(4)})`,
          }}
        >
          {tk.said}
        </div>,
      );
      return;
    }
    const q = tk.keep;
    const p = setP;
    const size = lerp(sA, sC, p);
    const up = reY[i] < cutDone.ys[i] - 1;
    const preX =
      reflowP > 0
        ? lerp(cutDone.xs[i], reX[i], up ? reflowEarly : reflowLate)
        : live.xs[i];
    const preY =
      reflowP > 0
        ? lerp(cutDone.ys[i], reY[i], up ? reflowLate : reflowEarly)
        : live.ys[i];
    const x = lerp(preX, headX[q], p);
    const yMid = lerp(preY, headY[q], setY);
    const head = p >= 0.5;
    const hi = isHi(q);
    const textStyle: React.CSSProperties = {
      position: "absolute",
      left: x,
      top: yMid - size * 0.5,
      fontFamily: grotesk.fontFamily,
      fontWeight: head ? 500 : 400,
      fontSize: size,
      lineHeight: `${size}px`,
      letterSpacing: `${lerp(SPEAK_TRACK, HEAD_TRACK, p)}em`,
      whiteSpace: "pre",
      transform: `translateY(${((1 - spoken) * sA * 0.4).toFixed(2)}px)`,
      opacity: spoken,
    };
    const ink = shade(c.ink, c.muted, markP);
    const word = head ? P.kept[q] : tk.said;
    els.push(
      <div key={`k${i}`} style={{ ...textStyle, color: ink }}>
        {word}
      </div>,
    );
    if (hi && hiP > 0)
      els.push(
        <div
          key={`h${i}`}
          style={{
            ...textStyle,
            color: "transparent",
            backgroundImage: fill,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            opacity: hiP,
          }}
        >
          {word}
        </div>,
      );
  });
  for (const q of P.extra) {
    const a = interpolate(t, [setAt + 8, setAt + SET_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    els.push(
      <div
        key={`x${q}`}
        style={{
          position: "absolute",
          left: headX[q],
          top: headY[q] - sC * 0.5 + (1 - a) * sC * 0.3,
          fontFamily: grotesk.fontFamily,
          fontWeight: 500,
          fontSize: sC,
          lineHeight: `${sC}px`,
          letterSpacing: `${HEAD_TRACK}em`,
          whiteSpace: "pre",
          color: c.ink,
          opacity: a,
        }}
      >
        {P.kept[q]}
      </div>,
    );
  }

  const gone = P.tokens.reduce(
    (acc, tk, i) => acc + (tk.cut >= 0 ? collapse[i] : 0),
    0,
  );
  const secs = (n - gone) * SEC_PER_WORD;
  const timeOn =
    interpolate(t, [SPEAK_AT + 4, SPEAK_AT + 18], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    }) *
    (1 - interpolate(t, [setAt, setAt + 10], [0, 1], CLAMP));
  const timeSize = Math.max(unit * 0.024, 11);
  const blockTop = live.top;

  const glow = `radial-gradient(60% 50% at 30% 55%, color-mix(in oklab, ${c.stops[1]} ${(c.glow * 100 * hiP).toFixed(1)}%, transparent) 0%, transparent 70%)`;

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, backgroundImage: glow }} />
      {els}
      {showTime ? (
        <div
          style={{
            position: "absolute",
            left,
            top: blockTop - timeSize * 2.6,
            display: "flex",
            gap: timeSize * 1.2,
            fontFamily: mono.fontFamily,
            fontWeight: 400,
            fontSize: timeSize,
            lineHeight: 1,
            letterSpacing: "0.04em",
            color: c.muted,
            fontVariantNumeric: "tabular-nums",
            opacity: timeOn,
            whiteSpace: "pre",
          }}
        >
          <span style={{ color: c.ink }}>{clock(secs)}</span>
          <span>{gone > 0.05 ? `−${clock(gone * SEC_PER_WORD)}` : ""}</span>
        </div>
      ) : null}
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  transcript: {
    type: "text-content",
    default: "So, um, ship your, like, launch video, uh, today. You know?",
    description: "Transcript",
  },
  keep: {
    type: "text-content",
    default: "Ship your launch video today.",
    description: "Keep",
  },
  highlight: {
    type: "text-content",
    default: "today.",
    description: "Highlight",
  },
  showTime: {
    type: "boolean",
    default: true,
    description: "Show time",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","transcript","keep","highlight","showTime","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  transcript: "So, um, ship your, like, launch video, uh, today. You know?",
  keep: "Ship your launch video today.",
  highlight: "today.",
  showTime: true,
  speed: 1,
};

type FillerCutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FillerCutBase>;

const FillerCutInner = forwardRef<
  HTMLDivElement,
  FillerCutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FillerCut>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FillerCutBase
          {...(componentProps as unknown as ComponentProps<typeof FillerCutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FillerCut = Interactive.withSchema({
  Component: FillerCutInner,
  componentName: "<FillerCut>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Gloock";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const gloock = loadFont("normal", { weights: ["400"], subsets: ["latin"] });

interface FinePrintUpProps {
  lines?: string[];
  closing?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_LINES = [
  "Every component you install is a file you own.",
  "Use it in paid client work. It’s MIT.",
  "No account and no watermark. Ever.",
];

const THEMES = {
  dark: {
    bg: "#0A1230",
    ink: "#FFFFFF",
    muted: "rgba(255,255,255,0.58)",
    accent: "#FF4436",
  },
  light: {
    bg: "#F7F3EC",
    ink: "#14161F",
    muted: "rgba(20,22,31,0.6)",
    accent: "#D92B1E",
  },
} as const;

const TRACK = -0.02;
const LH = 1.08;
const FINE_LH = 1.3;
const START = 10;
const TRAVEL = 26;
const TAIL = 76;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string): number {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) return s.length * 0.5;
  measureCtx.font = `400 100px "${gloock.fontFamily}"`;
  return measureCtx.measureText(s).width / 100 + TRACK * Array.from(s).length;
}

function useFontReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("fine-print-up: font"));
  useEffect(() => {
    let live = true;
    gloock
      .waitUntilDone()
      .then(() => document.fonts.load(`400 100px "${gloock.fontFamily}"`))
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setReady(true);
        continueRender(handle);
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

interface Laid {
  words: { text: string; x: number; line: number }[];
  lines: number;
}

function wrapAt(words: string[], maxEm: number, indent = 0): Laid {
  const space = em(" ");
  const out: { text: string; x: number; line: number }[] = [];
  let line = 0;
  let x = indent;
  for (const w of words) {
    const ww = em(w);
    if (x > indent && x + ww > maxEm) {
      line += 1;
      x = indent;
    }
    out.push({ text: w, x, line });
    x += ww + space;
  }
  return { words: out, lines: line + 1 };
}

function balanced(words: string[], maxEm: number): Laid {
  const base = wrapAt(words, maxEm);
  let lo = Math.max(...words.map(em), 0.1);
  let hi = maxEm;
  for (let i = 0; i < 14; i++) {
    const mid = (lo + hi) / 2;
    if (wrapAt(words, mid).lines <= base.lines) hi = mid;
    else lo = mid;
  }
  return wrapAt(words, hi);
}

function fitSize(words: string[], boxW: number, boxH: number, maxF: number) {
  const widest = Math.max(...words.map(em), 0.1);
  let lo = 8;
  let hi = maxF;
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    const lay = wrapAt(words, boxW / mid);
    if (lay.lines * LH * mid <= boxH && widest * mid <= boxW) lo = mid;
    else hi = mid;
  }
  return lo;
}

function FinePrintUpBase({
  lines = DEFAULT_LINES,
  closing = "That’s all the fine print.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: FinePrintUpProps) {
  const frame = useCurrentFrame();
  const t = frame * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontReady();

  if (!ready || lines.length === 0) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = lines.length;
  const portrait = H > W * 1.1;
  const mx = W * (portrait ? 0.08 : 0.07);
  const headTop = H * (portrait ? 0.1 : 0.11);
  const boxW = W * (portrait ? 0.84 : 0.78);
  const boxH = H * (portrait ? 0.42 : 0.56);
  const fs = H * (portrait ? 0.017 : 0.028);
  const fineW = W * (portrait ? 0.62 : 0.34);
  const fineX = W - mx - fineW;
  const fineBottom = H - H * (portrait ? 0.07 : 0.09);

  const words = lines.map((l) => l.split(/\s+/).filter(Boolean));
  const marks = lines.map((_, i) => "*".repeat(i + 1));
  const markW = em("***") + em(" ") * 0.6;
  const fineLays = words.map((ws) => wrapAt(ws, fineW / fs - markW));
  const fineHeights = fineLays.map((l) => l.lines * FINE_LH * fs);
  const fineGap = fs * 0.7;
  const fineTotal =
    fineHeights.reduce((a, b) => a + b, 0) + fineGap * Math.max(0, n - 1);
  const fineTops: number[] = [];
  let acc = fineBottom - fineTotal;
  for (let i = 0; i < n; i++) {
    fineTops.push(acc);
    acc += fineHeights[i] + fineGap;
  }

  const heads = words.map((ws) => {
    const F = fitSize(ws, boxW, boxH, H * (portrait ? 0.1 : 0.15));
    return { F, lay: balanced(ws, boxW / F) };
  });

  const D = durationInFrames * speed;
  const per = Math.max(50, (D - START - TAIL) / n);
  const stepAt = (i: number) => START + i * per;
  const closeAt = stepAt(n - 1) + TRAVEL + 26;

  const intro = interpolate(t, [0, 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const nodes: React.ReactNode[] = [];
  const text = (
    key: string,
    s: string,
    x: number,
    y: number,
    size: number,
    renderSize: number,
    lh: number,
    color: string,
    opacity: number,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        fontFamily: gloock.fontFamily,
        fontWeight: 400,
        fontSize: renderSize,
        lineHeight: `${lh * renderSize}px`,
        letterSpacing: `${TRACK}em`,
        whiteSpace: "pre",
        color,
        opacity,
        transformOrigin: "0 0",
        transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) scale(${(size / renderSize).toFixed(4)})`,
      }}
    >
      {s}
    </div>
  );

  lines.forEach((_, i) => {
    const s0 = stepAt(i);
    const u = t - s0;
    const { F, lay } = heads[i];
    const fl = fineLays[i];
    const pick = interpolate(u, [-2, 6], [0, 1], CLAMP);
    const exit =
      i < n - 1
        ? interpolate(t, [stepAt(i + 1), stepAt(i + 1) + 12], [0, 1], {
            ...CLAMP,
            easing: Easing.bezier(0.55, 0, 1, 0.45),
          })
        : 0;
    if (exit >= 1) return;

    const markOp = interpolate(u, [4, 14], [1, 0], CLAMP) * intro;
    if (markOp > 0) {
      nodes.push(
        text(
          `m${i}`,
          marks[i],
          fineX,
          fineTops[i],
          fs,
          fs,
          FINE_LH,
          interpolateColors(pick, [0, 1], [c.muted, hi]),
          markOp,
        ),
      );
    }

    const count = lay.words.length;
    const stagger = Math.min(1.4, 12 / Math.max(1, count));
    lay.words.forEach((hw, wi) => {
      const fw = fl.words[wi];
      const fx = fineX + (markW + fw.x) * fs;
      const fy = fineTops[i] + fw.line * FINE_LH * fs;
      const hx = mx + hw.x * F;
      const hy = headTop + hw.line * LH * F;
      const move = interpolate(
        u,
        [6 + wi * stagger, 6 + wi * stagger + TRAVEL],
        [0, 1],
        { ...CLAMP, easing: EASE_IO },
      );
      const fyScaled = fy + (FINE_LH - LH) * fs * 0.5;
      const x = fx + (hx - fx) * move;
      const y = fyScaled + (hy - fyScaled) * move - exit * F * 0.18;
      const size = fs + (F - fs) * move;
      const land = interpolate(move, [0.7, 1], [0, 1], CLAMP);
      const flyColor = interpolateColors(pick, [0, 1], [c.muted, hi]);
      const baseColor = interpolateColors(land, [0, 1], [flyColor, c.ink]);
      nodes.push(
        text(
          `w${i}-${wi}`,
          hw.text,
          x,
          y,
          size,
          F,
          LH,
          baseColor,
          intro * (1 - exit),
        ),
      );
    });
  });

  const closeIn = interpolate(t, [closeAt, closeAt + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  if (closeIn > 0 && closing) {
    const cl = wrapAt(closing.split(/\s+/), fineW / fs);
    const ch = cl.lines * FINE_LH * fs;
    cl.words.forEach((w, wi) => {
      nodes.push(
        text(
          `c${wi}`,
          w.text,
          fineX + w.x * fs,
          fineBottom - ch + w.line * FINE_LH * fs + (1 - closeIn) * fs * 0.6,
          fs,
          fs,
          FINE_LH,
          c.muted,
          closeIn,
        ),
      );
    });
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

