};

const FONT_PX = 200;
const TRACK = -0.02;
const LINE = 1.3;
const TYPE_IN = Easing.bezier(0.32, 0.72, 0, 1);
const ROLL = Easing.bezier(0.65, 0, 0.35, 1);
const PUSH = Easing.bezier(0.87, 0, 0.13, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };

function buildMetrics(_version: number) {
  const ctx = document.createElement("canvas").getContext("2d");
  const font = `400 ${FONT_PX}px "${hanken.fontFamily}"`;
  const cache: Record<string, number> = {};
  return (s: string) => {
    if (cache[s] === undefined) {
      if (!ctx) return s.length * 0.55;
      ctx.font = font;
      cache[s] =
        ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
    }
    return cache[s];
  };
}

function useMetrics() {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("flank-roll-swap: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      hanken.waitUntilDone(),
      document.fonts.load(`400 ${FONT_PX}px "${hanken.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle]);
  return useMemo(() => buildMetrics(version), [version]);
}

const rollEnd = (start: number, a: string, b: string) =>
  start + Math.max(a.length, b.length) * BEAT.stagger + BEAT.roll;

export const flankRollSwapLength = (
  from: [string, string] = ["Remocn", "Studio"],
  to: [string, string] = ["Out now", "on remocn.dev"],
) => {
  const leftEnd = rollEnd(BEAT.leftRoll, from[0], to[0]);
  const rightEnd = rollEnd(BEAT.leftRoll + BEAT.rightGap, from[1], to[1]);
  return Math.ceil(Math.max(leftEnd, rightEnd) / 6) * 6 + BEAT.hold;
};

const cutIndex = (frame: number, swapEnd: number) => {
  let t = 0;
  let k = 0;
  while (t <= frame) {
    const step = t < BEAT.fastFrom ? 6 : t < swapEnd ? 4 : 9;
    t += step;
    if (t <= frame) k++;
  }
  return k;
};

export function FlankRollSwap({
  from = ["Remocn", "Studio"],
  to = ["Out now", "on remocn.dev"],
  accentWord = "remocn.dev",
  images,
  accent,
  ink,
  theme = "dark",
  ground,
  groundParams,
}: FlankRollSwapProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const portrait = H > W * 1.1;
  const gParams =
    groundParams ??
    (ground ? undefined : portrait ? c.groundParamsTall : c.groundParams);
  const bg = gshParams(preset, gParams).background;
  const u = Math.min(W, H) / 720;
  const measure = useMetrics();
  const pics = (images ?? DEFAULT_IMAGES.map((p) => staticFile(p))).filter(
    Boolean,
  );

  const leftStart = BEAT.leftRoll;
  const rightStart = BEAT.leftRoll + BEAT.rightGap;
  const leftEnd = rollEnd(leftStart, from[0], to[0]);
  const rightEnd = rollEnd(rightStart, from[1], to[1]);
  const swapEnd = Math.max(leftEnd, rightEnd);

  const geo = useMemo(() => {
    if (portrait) {
      const widest = Math.max(
        measure(from[0]),
        measure(from[1]),
        measure(to[0]),
        measure(to[1]),
      );
      const cardW = W * 0.74;
      const cardH = cardW * 1.18;
      const F = Math.min((W * 0.8) / widest, cardH * 0.24);
      return { cardW, cardH, F, gap: F * 0.18, cx: W / 2 };
    }
    const leftMax = Math.max(measure(from[0]), measure(to[0]));
    const rightMax = Math.max(measure(from[1]), measure(to[1]));
    const gapEm = 0.42;
    const sumEm = leftMax + rightMax + 2 * gapEm;
    const cardW = W * Math.min(0.3, Math.max(0.2, 0.86 / (1 + 0.16 * sumEm)));
    const cardH = cardW / 1.9;
    const F = Math.min((W * 0.86 - cardW) / sumEm, cardH * 0.42);
    const cx = W / 2 + ((measure(to[0]) - measure(to[1])) * F) / 2;
    return { cardW, cardH, F, gap: F * gapEm, cx };
  }, [measure, from, to, portrait, W]);

  const { cardW, cardH, F, gap, cx } = geo;
  const cy = H / 2;

  const pop = spring({ frame, fps, config: CARD });
  const punch = interpolate(
    frame,
    [leftStart, leftStart + 2, leftStart + 7],
    [0, 1, 0],
    CLAMP,
  );
  const push =
    1 +
    0.035 *
      interpolate(frame, [0, swapEnd + BEAT.hold - 12], [0, 1], {
        ...CLAMP,
        easing: PUSH,
      });
  const cardScale = (0.55 + 0.45 * pop) * (1 + 0.035 * punch);
  const tilt = (1 - pop) * 14;
  const cut = cutIndex(frame, swapEnd);
  const pic = pics[cut % Math.max(1, pics.length)];
  let cutStart = 0;
  {
    let t = 0;
    while (t <= frame) {
      cutStart = t;
      t += t < BEAT.fastFrom ? 6 : t < swapEnd ? 4 : 9;
    }
  }
  const kb =
    1.08 -
    0.08 *
      interpolate(frame - cutStart, [0, 9], [0, 1], {
        ...CLAMP,
        easing: TYPE_IN,
      });

  const accentAt = (word: string) => {
    const i = accentWord ? word.indexOf(accentWord) : -1;
    return i < 0 ? [-1, -1] : [i, i + accentWord.length];
  };

  const renderRow = (
    text: string,
    phase: "old" | "new",
    side: "a" | "b",
    start: number,
    landed: number,
  ) => {
    const chars = Array.from(text);
    const n = chars.length;
    const [a0, a1] = phase === "new" ? accentAt(text) : [-1, -1];
    const accentP =
      a0 >= 0
        ? interpolate(frame, [landed, landed + 9], [0, 1], {
            ...CLAMP,
            easing: TYPE_IN,
          })
        : 0;
    return chars.map((ch, i) => {
      const fromCard = portrait ? i : side === "a" ? n - 1 - i : i;
      const t0 = start + fromCard * BEAT.stagger;
      const p = interpolate(frame, [t0, t0 + BEAT.roll], [0, 1], {
        ...CLAMP,
        easing: ROLL,
      });
      const y = phase === "old" ? -p * 105 : (1 - p) * 105;
      const op =
        phase === "old"
          ? interpolate(p, [0.4, 1], [1, 0], CLAMP)
          : interpolate(p, [0, 0.6], [0, 1], CLAMP);
      const isAccent = i >= a0 && i < a1;
      const color =
        isAccent && accentP > 0
          ? accentP >= 1
            ? hi
            : `color-mix(in oklab, ${hi} ${accentP * 100}%, ${inkC})`
          : inkC;
      const velocity = Math.abs(
        p -
          interpolate(frame - 1, [t0, t0 + BEAT.roll], [0, 1], {
            ...CLAMP,
            easing: ROLL,
          }),
      );
      const blur = Math.min(4, velocity * 14) * u;
      return (
        <span
          key={`${phase}-${i}-${ch}`}
          style={{
            display: "inline-block",
            whiteSpace: "pre",
            transform: `translateY(${y}%)`,
            opacity: op,
            color,
            filter: blur > 0.2 ? `blur(${blur * 0.4}px)` : undefined,
          }}
        >
          {ch}
        </span>
      );
    });
  };

  const renderSide = (side: "a" | "b") => {
    const idx = side === "a" ? 0 : 1;
    const inAt = side === "a" ? BEAT.leftIn : BEAT.rightIn;
    const rollAt = side === "a" ? leftStart : rightStart;
    const landed = side === "a" ? leftEnd : rightEnd;
    const slide = interpolate(frame, [inAt, inAt + BEAT.slide], [0, 1], {
      ...CLAMP,
      easing: TYPE_IN,
    });
    const lineH = F * LINE;
    const justify = portrait
      ? "center"
      : side === "a"
        ? "flex-end"
        : "flex-start";
    const textStyle = {
      position: "absolute" as const,
      inset: 0,
      display: "flex",
      justifyContent: justify,
      fontFamily: hanken.fontFamily,
      fontWeight: 400,
      fontSize: F,
      letterSpacing: `${TRACK}em`,
      lineHeight: `${lineH}px`,
      whiteSpace: "pre" as const,
    };
    const rows = (
      <>
        <div style={textStyle}>
          {renderRow(from[idx], "old", side, rollAt, landed)}
        </div>
        <div style={textStyle}>
          {renderRow(to[idx], "new", side, rollAt + 1, landed)}
        </div>
      </>
    );
    if (portrait) {
      const top = side === "a";
      const edge = (cardH / 2) * Math.min(1, cardScale);
      const travel = (1 - slide) * (lineH + gap + cardH / 2 - edge);
      const clipTop = top ? 0 : cy + edge;
      const rowTop = top
        ? cy - cardH / 2 - gap - lineH
        : cy + cardH / 2 + gap - clipTop;
      return (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: clipTop,
            width: W,
            height: top ? cy - edge : H - clipTop,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: rowTop + (top ? travel : -travel),
              height: lineH,
              overflow: "hidden",
            }}
          >
            {rows}
          </div>
        </div>
      );
    }
    const left = side === "a";
    const edge = (cardW / 2) * Math.min(1, cardScale);
    const shift =
      (1 - slide) * (measure(from[idx]) * F + gap + cardW / 2 - edge);
    const inner = cardW / 2 + gap - shift - edge;
    return (
      <div
        style={{
          position: "absolute",
          top: cy - lineH / 2,
          height: lineH,
          left: left ? 0 : cx + edge,
          width: left ? cx - edge : W - cx - edge,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            height: lineH,
            width: W * 0.6,
            ...(left ? { right: inner } : { left: inner }),
          }}
        >
          {rows}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <GshGround
        preset={preset}
        params={gParams}
        timeOffset={c.groundOffset}
        timeScale={0.5}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(${portrait ? "95% 50%" : "70% 60%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
        }}
      />
      <AbsoluteFill
        style={{ transform: `scale(${push})`, transformOrigin: "50% 50%" }}
      >
        {renderSide("a")}
        {renderSide("b")}
        <div
          style={{
            position: "absolute",
            left: cx - cardW / 2,
            top: cy - cardH / 2,
            width: cardW,
            height: cardH,
            perspective: 1200 * u,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: Math.max(6, cardW * (portrait ? 0.045 : 0.035)),
              overflow: "hidden",
              boxShadow: `${c.highlight}, ${c.shadow}`,
              border: `1px solid ${c.border}`,
              transform: `scale(${cardScale}) rotateX(${tilt}deg)`,
              background: "#111",
            }}
          >
            {pic ? (
              <Img
                src={pic}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  transform: `scale(${kb})`,
                }}
              />
            ) : null}
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: "inherit",
                boxShadow: c.highlight,
              }}
            />
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}

export default FlankRollSwap;

import { loadFont as loadHanken } from "@remotion/google-fonts/HankenGrotesk";
import React, { useEffect, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig } from "remotion";

const hanken = loadHanken("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

export interface FlashCountProps {
  value?: number;
  from?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  eyebrow?: string;
  flashAt?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#1A1918",
    ambient: "#131211",
    pop: "#D9D6D0",
    dim: "#57534E",
    ink: "#D9D6D0",
    muted: "#8F8A83",
    shadow: "#0B0A0A",
  },
  light: {
    bg: "#D9D6D0",
    ambient: "#C4C0B9",
    pop: "#F6F4F0",
    dim: "#9C978F",
    ink: "#111111",
    muted: "#57534E",
    shadow: "rgba(17,17,17,0.2)",
  },
} as const;

const RED = "#E2001A";
const TRACK = -0.04;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: Record<string, number>;
  digit: number;
  cap: number;
  label: number;
  eyebrow: number;
}

function measure(chars: string[], label: string, eyebrow: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) throw new Error("flash-count: no 2d context");
  ctx.font = `300 100px "${hanken.fontFamily}"`;
  const adv: Record<string, number> = {};
  for (const ch of chars) adv[ch] = ctx.measureText(ch).width / 100;
  let digit = 0;
  for (const d of "0123456789") digit = Math.max(digit, adv[d] ?? 0);
  const cap = ctx.measureText("8").actualBoundingBoxAscent / 100;
  ctx.font = `400 100px "${hanken.fontFamily}"`;
  const lw = label ? ctx.measureText(label).width / 100 : 0;
  ctx.font = `500 100px "${hanken.fontFamily}"`;
  const ew = eyebrow ? ctx.measureText(eyebrow).width / 100 : 0;
  return { adv, digit, cap, label: lw, eyebrow: ew };
}

function useMetrics(chars: string, label: string, eyebrow: string) {
  const key = `${chars}\u0001${label}\u0001${eyebrow}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("flash-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      hanken.waitUntilDone(),
      document.fonts.load(`300 100px "${hanken.fontFamily}"`),
      document.fonts.load(`400 100px "${hanken.fontFamily}"`),
      document.fonts.load(`500 100px "${hanken.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [c, l, e] = key.split("\u0001");
        setState({ key, m: measure(Array.from(c), l, e) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function format(n: number, decimals: number) {
  return n.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

const isDigit = (ch: string) => ch >= "0" && ch <= "9";

export function FlashCount({
  value = 3600,
  from = 120,
  decimals = 0,
  prefix = "",
  suffix = "",
  label = "frames in a two\u2011minute launch film",
  eyebrow = "f/8  ·  1/250 s",
  flashAt = 54,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: FlashCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const dot = accent ?? RED;
  const transparent = background === "transparent";

  const finalText = `${prefix}${format(value, decimals)}${suffix}`;
  const chars = Array.from(
    new Set(Array.from(`${finalText}0123456789,.-`)),
  ).join("");
  const m = useMetrics(chars, label, eyebrow);

  const F_ = flashAt;
  const lit = t >= F_;
  const pop = lit
    ? interpolate(t, [F_, F_ + 1, F_ + 12], [1, 0.85, 0], {
        ...CLAMP,
        easing: EASE_OUT,
      })
    : 0;
  const pre = interpolate(t, [F_ - 8, F_ - 7, F_ - 5], [0, 1, 0], CLAMP);
  const field = lit
    ? interpolateColors(pop, [0, 1], [c.bg, c.pop])
    : interpolateColors(pre * 0.25, [0, 1], [c.ambient, c.pop]);
  const stage = transparent ? "transparent" : (background ?? field);

  if (!m) {
    return (
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: transparent ? "transparent" : (background ?? c.ambient),
        }}
      />
    );
  }

  const countP = interpolate(t, [4, F_], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.3, 0.6, 0.4, 1),
  });
  const n = lit ? value : from + (value - from) * countP;
  const shown = `${prefix}${format(
    lit ? value : Number(n.toFixed(decimals)),
    decimals,
  )}${suffix}`;

  const widthOf = (s: string) => {
    let w = 0;
    const list = Array.from(s);
    for (const ch of list) w += isDigit(ch) ? m.digit : (m.adv[ch] ?? m.digit);
    return w + TRACK * Math.max(0, list.length - 1);
  };

  const portrait = H > W * 1.1;
  const minDim = Math.min(W, H);
  const marginX = W * (portrait ? 0.09 : 0.08);
  const marginY = H * (portrait ? 0.07 : 0.12);
  const F = Math.min(
    (H * (portrait ? 0.15 : 0.34)) / m.cap,
    (W * (portrait ? 0.82 : 0.56)) / widthOf(finalText),
  );
  const capPx = m.cap * F;
  const smallFs = Math.max(minDim * 0.026, Math.min(minDim * 0.032, 24));

  const baseline = H - marginY;
  const right = W - marginX;

  const driftP = Math.min(1, t / F_);
  const drift = 1 - driftP;
  const dx = drift * -W * 0.05;
  const ds = 1 - drift * 0.06;

  const shadowDx = F * 0.03;
  const shadowDy = F * 0.045;

  const textW = widthOf(shown) * F;
  const left = right - textW;
  const labelW = portrait
    ? W - marginX * 2
    : Math.max(W * 0.2, right - widthOf(finalText) * F - marginX - W * 0.04);

  const glyphs = (key: string) => {
    let x = 0;
    return Array.from(shown).map((ch, i) => {
      const cell = isDigit(ch) ? m.digit : (m.adv[ch] ?? m.digit);
      const own = m.adv[ch] ?? cell;
      const at = x + (cell - own) / 2;
      x += cell + TRACK;
      return (
        <span
          key={`${key}${i}`}
          style={{ position: "absolute", left: at * F, top: 0 }}
        >
          {ch}
        </span>
      );
    });
  };

  const numberBox = (style: React.CSSProperties, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left,
        top: baseline - F,
        width: textW + F * 0.1,
        height: F * 1.3,
        lineHeight: `${F * 1.2}px`,
        fontFamily: hanken.fontFamily,
        fontWeight: 300,
        fontSize: F,
        whiteSpace: "pre",
        ...style,
      }}
    >
      {glyphs(key)}
    </div>
  );

  const labelP = interpolate(t, [F_ + 4, F_ + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const cx = right;
  const cy = baseline - capPx / 2;
  const subject = `translate(${dx.toFixed(2)}px, 0px) translate(${cx}px, ${cy}px) scale(${ds.toFixed(4)}) translate(${-cx}px, ${-cy}px)`;
  const dotR = smallFs * 0.32;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: marginX,
          top: marginY,
          display: "flex",
          alignItems: "center",
          gap: smallFs * 0.6,
          fontFamily: hanken.fontFamily,
          fontWeight: 500,
          fontSize: smallFs,
          lineHeight: 1,
          whiteSpace: "pre",
          color: lit ? c.ink : c.dim,
        }}
      >
        <div
          style={{
            width: dotR * 2,
            height: dotR * 2,
            borderRadius: "50%",
            background: dot,
            opacity: lit ? 1 : 0.35 + pre * 0.65,
            flexShrink: 0,
          }}
        />
        {eyebrow}
      </div>

      <div style={{ position: "absolute", inset: 0, transform: subject }}>
        {lit
          ? numberBox(
              {
                transform: `translate(${shadowDx}px, ${shadowDy}px)`,
                color: c.shadow,
              },
              "s",
            )
          : null}
        {numberBox({ color: lit ? c.ink : c.dim }, "n")}
      </div>

      {label ? (
        <div
          style={{
            position: "absolute",
            left: marginX,
            width: labelW,
            ...(portrait
              ? { top: baseline - capPx - smallFs * 4.2 }
              : { bottom: H - baseline }),
            fontFamily: hanken.fontFamily,
            fontWeight: 400,
            fontSize: smallFs,
            lineHeight: 1.3,
            color: c.muted,
            textWrap: "balance",
            opacity: labelP,
          }}
        >
          {label}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont } from "@remotion/google-fonts/Onest";
import React, { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Img, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: serif } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/**
 * gradients.sh "fluted" palette: [#1d2a8f, #2f7bff, #ff7a3d, #ffe2c4]. It is
 * the ground of the closing statement shot (ribbed like fluted glass), the
 * product bar in the number shot and, on paper, the italic accent word.
 */
const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;
const flutedLinear = (deg: number) =>
  `linear-gradient(${deg}deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 48%, ${FLUTED[2]} 86%, ${FLUTED[3]} 108%)`;

/* ------------------------------------------------------------------ */
/* Built-in placeholder shots: abstract compositions in one palette.   */
/* ------------------------------------------------------------------ */

type Tone = "dark" | "graphite" | "light" | "accent";
type Kind = "title" | "pane" | "number" | "statement";
interface SceneSpec {
  kind: Kind;
  tone: Tone;
}

function toRgb(color: string): [number, number, number] {
  if (color.startsWith("rgb")) {
    const [r, g, b] = color.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0];
    return [r, g, b];
  }
  const h = color.replace("#", "");
  const v =
    h.length === 3
      ? h
          .split("")
          .map((ch) => ch + ch)
          .join("")
      : h.slice(0, 6);
  const n = Number.parseInt(v, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function mix(a: string, b: string, t: number) {
  const x = toRgb(a);
  const y = toRgb(b);
  const c = x.map((v, i) => Math.round(v + (y[i] - v) * t));
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}

function tones(tone: Tone, accent: string) {
  if (tone === "light") {
    return {
      bg: "#F5F4F0",
      fg: "#121214",
      muted: "#6E6C67",
      hair: "rgba(18,18,20,0.10)",
      surface: "#FFFFFF",
      block: "#E8E5DE",
      light: "rgba(255,255,255,0.95)",
      shadow: "rgba(40,36,30,0.16)",
      dot: accent,
    };
  }
  if (tone === "accent") {
    return {
      // fluted glass: soft ribs over the palette, the warm end held back
