      light: "rgba(255,255,255,0.22)",
      shadow: "rgba(0,0,0,0.35)",
      dot: "#0A0A0B",
    };
  }
  const graphite = tone === "graphite";
  return {
    bg: graphite ? "#17171A" : "#0A0A0B",
    fg: "#F3F2EF",
    muted: graphite ? "#97969C" : "#8B8A90",
    hair: "rgba(255,255,255,0.10)",
