        d="M8 2 A6 6 0 0 1 14 8"
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
      />
    </svg>
  );
}

function Check({
  color,
  size,
  draw,
}: {
  color: string;
  size: number;
  draw: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      style={{ flexShrink: 0 }}
    >
      <path
        d="M3.5 8.4 6.6 11.4 12.5 5"
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray="1 1"
        strokeDashoffset={1 - draw}
      />
    </svg>
  );
}

function NodeCard({
  node,
