  );
}

export function FlowBuilder({
  nodes = DEFAULT_NODES,
  title = "Welcome new signups",
  workspace = "remocn",
  toast = "Live · runs on every signup",
  theme = "light",
  accent = "#3B5BFD",
  speed = 1,
  ground,
  groundParams,
}: FlowBuilderProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const tall = height > width;
  const SW = tall ? 720 : 1280;
  const SH = tall ? 1280 : 720;
  const u = Math.min(width / SW, height / SH);
  const pal = palette(theme);
  const sp = (at: number, config: typeof CARD, dur?: number) =>
    spring({ frame: frame - at, fps, config, durationInFrames: dur });

  const WIN = tall
    ? { x: 80, y: 290, w: 560, h: 860 }
    : { x: 150, y: 110, w: 980, h: 500 };
  const CW = WIN.w;
  const CH = WIN.h - BAR;

  const byId = new Map(nodes.map((n) => [n.id, n]));
  const parents = new Map<string, string>();
  for (const n of nodes)
    for (const id of n.next ?? []) if (!parents.has(id)) parents.set(id, n.id);
  const depth = new Map<string, number>();
  const queue = nodes.filter((n) => !parents.has(n.id)).map((n) => n.id);
  for (const id of queue) depth.set(id, 0);
  while (queue.length) {
    const id = queue.shift() as string;
    for (const nx of byId.get(id)?.next ?? []) {
      if (!depth.has(nx)) {
        depth.set(nx, (depth.get(id) ?? 0) + 1);
        queue.push(nx);
      }
    }
  }
  const maxDepth = Math.max(0, ...depth.values());
  const levels = Array.from({ length: maxDepth + 1 }, (_, d) =>
    nodes.filter((n) => (depth.get(n.id) ?? 0) === d),
  );

  const box = new Map<string, { x: number; y: number; w: number }>();
  if (tall) {
    const pitch = 150;
    const top = (CH - (maxDepth * pitch + NODE_H)) / 2 + 8;
    levels.forEach((row, d) => {
      const gap = 28;
      const w =
        row.length === 1
          ? 264
          : Math.min(240, (CW - 64 - gap * (row.length - 1)) / row.length);
      const total = row.length * w + (row.length - 1) * gap;
      row.forEach((n, k) => {
        box.set(n.id, {
          x: (CW - total) / 2 + k * (w + gap),
          y: top + d * pitch,
          w,
        });
      });
    });
  } else {
    const colW = levels.map((row) =>
      Math.max(...row.map((n) => n.width ?? 196)),
    );
    const gaps = levels
      .slice(1)
      .map((_, i) => (i === levels.length - 2 ? 66 : 42));
    const total =
      colW.reduce((a, b) => a + b, 0) + gaps.reduce((a, b) => a + b, 0);
    let x = (CW - total) / 2;
    levels.forEach((row, d) => {
      const pitch = NODE_H + 76;
      const top = CH / 2 - NODE_H / 2 - ((row.length - 1) * pitch) / 2 + 6;
      row.forEach((n, k) => {
        const w = n.width ?? 196;
        box.set(n.id, { x: x + (colW[d] - w) / 2, y: top + k * pitch, w });
      });
      x += colW[d] + (gaps[d] ?? 0);
    });
  }

  const edges = nodes.flatMap((n) =>
    (n.next ?? []).flatMap((id) => {
      const to = byId.get(id);
      const fb = box.get(n.id);
      const tb = to ? box.get(id) : undefined;
      if (!to || !fb || !tb) return [];
      const a = tall
        ? { x: fb.x + fb.w / 2, y: fb.y + NODE_H }
        : { x: fb.x + fb.w, y: fb.y + NODE_H / 2 };
      const b = tall
        ? { x: tb.x + tb.w / 2, y: tb.y }
        : { x: tb.x, y: tb.y + NODE_H / 2 };
      const c1 = tall
        ? { x: a.x, y: lerp(a.y, b.y, 0.55) }
        : { x: lerp(a.x, b.x, 0.55), y: a.y };
      const c2 = tall
        ? { x: b.x, y: lerp(a.y, b.y, 0.45) }
        : { x: lerp(a.x, b.x, 0.45), y: b.y };
      return [{ from: n, to, a, c1, c2, b }];
    }),
  );
  type Edge = (typeof edges)[number];
  const bez = (e: Edge, t: number): Pt => {
    const m = 1 - t;
    const k = (p: keyof Pt) =>
      m * m * m * e.a[p] +
      3 * m * m * t * e.c1[p] +
      3 * m * t * t * e.c2[p] +
      t * t * t * e.b[p];
    return { x: k("x"), y: k("y") };
  };

  const dropAt = (i: number) => B.node + i * B.nodeStep;
  const arriveAt = (d: number) => B.run + 4 + d * B.level;
  const checkAt = (d: number) => arriveAt(d) + 8;
  const runEnd = checkAt(maxDepth);
  const PUBLISH = runEnd + 12;

  const RUN_W = 88;
  const PUB_W = 112;
  const pubX = CW - 12 - PUB_W;
  const runX = pubX - 8 - RUN_W;
  const runPt = { x: runX + RUN_W / 2 + 4, y: BAR / 2 + 4 };
  const pubPt = { x: pubX + PUB_W / 2 + 8, y: BAR / 2 + 4 };
  const keys: Key[] = [
    { t: B.cursor, x: CW + 70, y: WIN.h * 0.62 },
    { t: B.run - 2, ...runPt },
    { t: runEnd, ...runPt },
    { t: PUBLISH - 2, ...pubPt },
    { t: PUBLISH + 18, ...pubPt },
    { t: PUBLISH + 42, x: pubPt.x - 70, y: pubPt.y + 120 },
  ];
  let cur: Pt = keys[0];
  for (let i = 1; i < keys.length; i++) {
    const a = keys[i - 1];
    const b = keys[i];
    if (frame < a.t) break;
    const p = spring({
      frame: frame - a.t,
      fps,
      config: { mass: 0.9, damping: 22, stiffness: 140 },
      durationInFrames: b.t - a.t,
    });
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const d = Math.hypot(dx, dy) || 1;
    const arc = Math.sin(clamp(p) * Math.PI) * Math.min(42, d * 0.14);
    cur = {
      x: lerp(a.x, b.x, p) + (dy / d) * arc,
      y: lerp(a.y, b.y, p) - (dx / d) * arc,
    };
  }
  const pressAt = (at: number) => sp(at - 2, PRESS) - sp(at + 3, PRESS);
  const runPress = pressAt(B.run);
  const pubPress = pressAt(PUBLISH);
  const press = Math.max(runPress, pubPress);
  const cursorIn = interpolate(frame, [B.cursor, B.cursor + 8], [0, 1], {
    ...CL,
    easing: ENTER,
  });

  const win = sp(0, HEAVY);
  const winFade = interpolate(frame, [0, 12], [0, 1], { ...CL, easing: ENTER });
  const running = frame >= B.run && frame < runEnd + 2;
  const published = frame >= PUBLISH + 2;
  const pubS = sp(PUBLISH + 2, CARD);
  const toastS = sp(PUBLISH + 8, HEAVY);
  const toastFade = interpolate(frame, [PUBLISH + 8, PUBLISH + 18], [0, 1], {
    ...CL,
    easing: ENTER,
  });
  const cam = interpolate(frame, [0, 205], [1, 1.035], {
    ...CL,
    easing: CAMERA,
  });
  const headIn = interpolate(frame, [4, 20], [0, 1], { ...CL, easing: ENTER });

  const nodeEls = nodes.map((n, i) => {
    const bx = box.get(n.id);
    if (!bx) return null;
    const s = sp(dropAt(i), CARD);
    const o = interpolate(frame, [dropAt(i), dropAt(i) + 8], [0, 1], {
      ...CL,
      easing: ENTER,
    });
    const d = depth.get(n.id) ?? 0;
    const active = interpolate(
      frame,
      [arriveAt(d) - 1, arriveAt(d) + 4, checkAt(d), checkAt(d) + 6],
      [0, 1, 1, 0],
      { ...CL, easing: MOVE },
    );
    const chipOn = frame >= arriveAt(d);
    const done = frame >= checkAt(d);
    const chipS = sp(done ? checkAt(d) : arriveAt(d), CHIP);
    const draw = interpolate(frame, [checkAt(d) + 2, checkAt(d) + 10], [0, 1], {
      ...CL,
      easing: ENTER,
    });
    return (
      <div key={n.id}>
        <div
          style={{
            position: "absolute",
            left: bx.x,
            top: bx.y,
            width: bx.w,
            height: NODE_H,
            opacity: o,
            transform: `translateY(${(1 - s) * 18}px) scale(${0.94 + 0.06 * s})`,
            zIndex: 3,
          }}
        >
          <NodeCard node={n} pal={pal} accent={accent} active={active} />
        </div>
        {chipOn ? (
          <div
            style={{
              position: "absolute",
              left: bx.x + bx.w - 4,
              top: bx.y - 28,
              transform: `translateX(-100%) scale(${0.7 + 0.3 * chipS})`,
              transformOrigin: "100% 100%",
              opacity: clamp(chipS * 2),
              display: "flex",
              alignItems: "center",
              gap: 5,
              fontFamily: mono.fontFamily,
              fontSize: 13,
              color: done ? pal.success : pal.muted,
              whiteSpace: "nowrap",
              zIndex: 3,
            }}
          >
            {done ? (
              <Check color={pal.success} size={14} draw={draw} />
            ) : (
              <Spinner
                color={accent}
                track={pal.rule}
                frame={frame}
                size={13}
              />
            )}
            {done ? n.duration : "running"}
          </div>
        ) : null}
      </div>
    );
  });

  const edgeEls = edges.map((e) => {
    const ti = nodes.indexOf(e.to);
    const fi = nodes.indexOf(e.from);
    const start = Math.max(dropAt(ti), dropAt(fi)) + 6;
    const draw = interpolate(frame, [start, start + 12], [0, 1], {
      ...CL,
      easing: MOVE,
    });
    const d0 = depth.get(e.from.id) ?? 0;
    const lit = interpolate(
      frame,
      [checkAt(d0), checkAt(d0) + B.travel],
      [0, 1],
      { ...CL, easing: MOVE },
    );
    const p = `M ${e.a.x} ${e.a.y} C ${e.c1.x} ${e.c1.y} ${e.c2.x} ${e.c2.y} ${e.b.x} ${e.b.y}`;
    return (
      <g key={`${e.from.id}-${e.to.id}`}>
        <path
          d={p}
          fill="none"
          stroke={pal.edge}
          strokeWidth={1.25}
          pathLength={1}
          strokeDasharray="1 1"
          strokeDashoffset={1 - draw}
        />
        {lit > 0 ? (
          <path
            d={p}
            fill="none"
            stroke={accent}
            strokeWidth={1.75}
            strokeLinecap="round"
            pathLength={1}
            strokeDasharray="1 1"
            strokeDashoffset={1 - lit}
          />
        ) : null}
        <circle
          cx={e.b.x}
          cy={e.b.y}
          r={3}
          fill={lit >= 1 ? accent : pal.card}
          stroke={lit >= 1 ? accent : pal.edge}
          strokeWidth={1.25}
          opacity={clamp((draw - 0.8) / 0.2)}
        />
      </g>
    );
  });

  const packets = edges.map((e) => {
    const d0 = depth.get(e.from.id) ?? 0;
    const t = (frame - checkAt(d0)) / B.travel;
    if (t < 0 || t > 1.25) return null;
    const pt = bez(e, MOVE(clamp(t)));
    const fade = interpolate(t, [0, 0.12, 1, 1.25], [0, 1, 1, 0], CL);
    return (
      <div
        key={`k-${e.to.id}`}
        style={{
          position: "absolute",
          left: pt.x - 5,
          top: pt.y - 5,
          width: 10,
          height: 10,
          borderRadius: 999,
          background: accent,
          boxShadow: `0 0 0 3px ${withAlpha(accent, 0.2)}, 0 0 14px ${withAlpha(accent, 0.6)}`,
          opacity: fade,
          zIndex: 4,
        }}
      />
    );
  });

  const btn: React.CSSProperties = {
    position: "absolute",
    top: (BAR - 34) / 2,
    height: 34,
    borderRadius: 9,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 7,
    fontSize: 15,
    boxSizing: "border-box",
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill
      style={{
        fontFamily: hanken.fontFamily,
        WebkitFontSmoothing: "antialiased",
        overflow: "hidden",
      }}
    >
      <GshGround
        preset={ground ?? (pal.dark ? "earthshine" : "glasswork")}
        params={
          groundParams ??
          (pal.dark || ground
            ? undefined
            : { colors: ["#b9c8ff", "#3552ff", "#1d2f9e", "#8fb0ff"] })
        }
        timeOffset={pal.dark ? 7 : 6}
        timeScale={0.4}
      />
      <div
        style={{
          position: "absolute",
          left: (width - SW * u) / 2,
          top: (height - SH * u) / 2,
          width: SW,
          height: SH,
          transform: `scale(${u})`,
          transformOrigin: "0 0",
        }}
      >
        {tall ? (
          <div
            style={{
              position: "absolute",
              left: WIN.x,
              top: 150,
              width: WIN.w,
              opacity: headIn,
              transform: `translateY(${(1 - headIn) * 18}px)`,
              color: pal.dark ? "#F2F3F5" : "#16181D",
            }}
          >
            <div
              style={{
                fontSize: 52,
                fontWeight: 300,
                letterSpacing: "-0.035em",
                lineHeight: 1.04,
              }}
            >
              {title}
            </div>
          </div>
        ) : null}
        <div
          style={{
            position: "absolute",
            left: WIN.x,
            top: WIN.y,
            width: WIN.w,
            height: WIN.h,
            opacity: winFade,
            transformOrigin: "50% 45%",
            transform: `translateY(${(1 - win) * 60}px) scale(${(0.96 + 0.04 * win) * cam})`,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: 16,
              overflow: "hidden",
              background: pal.window,
              boxShadow: pal.depth,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                right: 0,
                height: BAR,
                display: "flex",
                alignItems: "center",
                gap: 10,
                padding: "0 18px",
                boxShadow: `inset 0 -1px 0 ${pal.rule}`,
                fontSize: 15,
              }}
            >
              <span style={{ color: pal.muted }}>{workspace}</span>
              <span style={{ color: pal.faint }}>/</span>
              <span style={{ color: pal.text }}>
                {tall ? "Workflows" : title}
              </span>
              <div
                style={{
                  position: "relative",
                  height: 24,
                  padding: "0 9px",
                  borderRadius: 7,
                  fontSize: 13,
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                  background: published
                    ? withAlpha(pal.success, 0.12)
                    : pal.pill,
                  color: published ? pal.success : pal.muted,
                  transform: `scale(${published ? 0.9 + 0.1 * pubS : 1})`,
                }}
              >
                {published ? (
                  <div
                    style={{
                      width: 6,
                      height: 6,
                      borderRadius: 3,
                      background: pal.success,
                    }}
                  />
                ) : null}
                {published ? "Live" : "Draft"}
              </div>
            </div>
            <div
              style={{
                position: "absolute",
                left: 0,
                top: BAR,
                right: 0,
                bottom: 0,
                background: pal.canvas,
                backgroundImage: `radial-gradient(circle, ${pal.dot} 1px, transparent 1.4px)`,
                backgroundSize: "22px 22px",
              }}
            >
              <svg
                width={CW}
                height={CH}
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  overflow: "visible",
                }}
              >
                {edgeEls}
              </svg>
              {packets}
              {nodeEls}
              {frame >= PUBLISH + 8 ? (
                <div
                  style={{
                    position: "absolute",
                    left: CW / 2,
                    top: CH - 64,
                    transform: `translateX(-50%) translateY(${(1 - toastS) * 26}px)`,
                    opacity: toastFade,
                    height: 40,
                    padding: "0 16px 0 12px",
                    borderRadius: 12,
                    background: pal.dark ? "#1E2128" : "#1B1A18",
                    color: "#F4F3F0",
                    display: "flex",
                    alignItems: "center",
                    gap: 9,
                    fontSize: 15,
                    boxShadow: pal.dark
                      ? "0 0 0 1px rgba(255,255,255,0.1), 0 16px 32px -12px rgba(0,0,0,0.6)"
                      : "0 16px 32px -12px rgba(20,18,14,0.35), 0 4px 10px -4px rgba(20,18,14,0.2)",
                    whiteSpace: "nowrap",
                    zIndex: 10,
                  }}
                >
                  <Check
                    color="#5BE39B"
                    size={16}
                    draw={interpolate(
                      frame,
                      [PUBLISH + 14, PUBLISH + 24],
                      [0, 1],
                      { ...CL, easing: ENTER },
                    )}
                  />
                  {toast}
                </div>
              ) : null}
            </div>
          </div>
          <div
            style={{
              ...btn,
              left: runX,
              width: RUN_W,
              background: pal.card,
              boxShadow: pal.cardDepth,
              color: pal.text,
              transform: `scale(${1 - 0.04 * runPress})`,
            }}
          >
            {running ? (
              <Spinner color={accent} track={pal.rule} frame={frame} />
            ) : (
              <svg width={11} height={11} viewBox="0 0 12 12">
                <path
                  d="M3 1.8v8.4L10 6z"
                  fill="none"
                  stroke={pal.text}
                  strokeWidth={1.3}
                  strokeLinejoin="round"
                />
              </svg>
            )}
            {running ? "Running" : "Run"}
          </div>
          <div
            style={{
              ...btn,
              left: pubX,
              width: PUB_W,
              background: accent,
              color: "#fff",
              boxShadow: `inset 0 1px 0 rgba(255,255,255,0.2), 0 1px 2px ${withAlpha(accent, 0.4)}, 0 6px 14px -6px ${withAlpha(accent, 0.6)}`,
              transform: `scale(${1 - 0.04 * pubPress})`,
            }}
          >
            {published ? (
              <Check color="#fff" size={14} draw={clamp(pubS * 1.4)} />
            ) : null}
            {published ? "Published" : "Publish"}
          </div>
          <div
            style={{
              position: "absolute",
              left: cur.x - 2,
              top: cur.y - 2,
              opacity: cursorIn,
              zIndex: 50,
            }}
          >
            <Cursor press={press} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Interactive, Sequence, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type FlowFieldProps = {
  /** Number of particles in flight. */
  particles?: number;
  /** Trail length in simulation steps (frames). */
  trailLength?: number;
  /** Frames for one seamless loop of the field and the particle lifecycles. */
  loopFrames?: number;
  /** Particle lifetime in frames, rounded so it divides loopFrames. */
  lifeFrames?: number;
  /** Share of particles drawn in the accent color, 0 to 1. */
  accentRatio?: number;
  /** Trail width in px at 720p. */
  strokeWidth?: number;
  seed?: number;
  speed?: number;
  background?: string;
  color?: string;
  accent?: string;
};

const flowFieldDefaults: Required<FlowFieldProps> = {
  particles: 300,
  trailLength: 72,
  loopFrames: 300,
  lifeFrames: 150,
  accentRatio: 0.1,
  strokeWidth: 1.4,
  seed: 1,
  speed: 1,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
};

const TAU = Math.PI * 2;
const WAVES = 4;
// Distance per frame in units of the short side of the frame.
const STEP = 0.0042;
const BUCKETS = 6;

type Wave = {
  fx: number;
  fy: number;
  phase: number;
  drift: number;
  amp: number;
};

function makeField(seed: number) {
  const r = (key: string) => random(`flow-field-${seed}-${key}`);
  const base = r("base") * TAU;
  const waves: Wave[] = Array.from({ length: WAVES }, (_, k) => ({
    fx: (r(`fx${k}`) * 2 - 1) * (0.9 + k * 0.8),
    fy: (r(`fy${k}`) * 2 - 1) * (0.9 + k * 0.8),
    phase: r(`ph${k}`) * TAU,
    drift: 0.6 + r(`dr${k}`) * 0.9,
    amp: 1.6 / (1 + k * 1.4),
  }));
  // Flow angle at (x, y). `tau` walks around a circle once per loop, so the
  // field at the end of the loop is exactly the field at the start.
  return (x: number, y: number, tau: number) => {
    let a = base;
    for (const w of waves) {
      a +=
        w.amp *
        Math.sin(
          w.fx * x + w.fy * y + w.phase + w.drift * Math.sin(tau + w.phase),
        );
    }
    return a;
  };
}

const fmt = (n: number) => Math.round(n * 10) / 10;

function FlowFieldBase({
  particles = flowFieldDefaults.particles,
  trailLength = flowFieldDefaults.trailLength,
  loopFrames = flowFieldDefaults.loopFrames,
  lifeFrames = flowFieldDefaults.lifeFrames,
  accentRatio = flowFieldDefaults.accentRatio,
  strokeWidth = flowFieldDefaults.strokeWidth,
  seed = flowFieldDefaults.seed,
  speed = flowFieldDefaults.speed,
  background = flowFieldDefaults.background,
  color = flowFieldDefaults.color,
  accent = flowFieldDefaults.accent,
}: FlowFieldProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const field = useMemo(() => makeField(seed), [seed]);

  const unit = Math.min(width, height);
  const spanX = width / unit;
  const spanY = height / unit;
  const loop = Math.max(1, Math.round(loopFrames));
  const lives = Math.max(1, Math.round(loop / Math.max(1, lifeFrames)));
  const life = loop / lives;
  const trail = Math.max(2, Math.min(trailLength, life * 0.6));
  const travel = life - trail;
  const time = frame * speed;

  const paths = {
    color: new Array<string>(BUCKETS).fill(""),
    accent: new Array<string>(BUCKETS).fill(""),
  };
  const pts: number[] = [];

  for (let i = 0; i < particles; i++) {
    const offset = random(`flow-field-${seed}-off-${i}`) * life;
    const local = time + offset;
    const cycle = Math.floor(local / life);
    const age = local - cycle * life;
    // Head moves for `travel` frames, then stops while the tail catches up,
    // so trails grow in and drain out instead of popping.
    const head = Math.min(age, travel);
    const tail = Math.max(0, age - trail);
    if (head - tail < 0.05) continue;

    const slot = ((cycle % lives) + lives) % lives;
    const key = `flow-field-${seed}-p${i}-c${slot}`;
    let x = -0.08 + random(`${key}-x`) * (spanX + 0.16);
    let y = -0.08 + random(`${key}-y`) * (spanY + 0.16);
    const birth = time - age;

    pts.length = 0;
    pts.push(x, y);
    const steps = Math.ceil(head);
    for (let s = 0; s < steps; s++) {
      const a = field(x, y, (TAU * (birth + s)) / loop);
      x += Math.cos(a) * STEP;
      y += Math.sin(a) * STEP;
      pts.push(x, y);
    }
    const at = (k: number) => {
      const j = Math.min(Math.floor(k), steps - 1);
      const f = k - j;
      if (j < 0) return [pts[0], pts[1]];
      return [
        pts[j * 2] + (pts[j * 2 + 2] - pts[j * 2]) * f,
        pts[j * 2 + 1] + (pts[j * 2 + 3] - pts[j * 2 + 1]) * f,
      ];
    };

    const target =
      random(`flow-field-${seed}-accent-${i}`) < accentRatio
        ? paths.accent
        : paths.color;
    // Split the visible trail into age buckets; older buckets are fainter.
    for (let b = 0; b < BUCKETS; b++) {
      const from = Math.max(tail, age - (trail * (b + 1)) / BUCKETS);
      const to = Math.min(head, age - (trail * b) / BUCKETS);
      if (to - from <= 0.01) continue;
      const [fx, fy] = at(from);
      let d = `M ${fmt(fx * unit)} ${fmt(fy * unit)}`;
      for (let k = Math.floor(from) + 1; k < to; k++) {
        d += ` L ${fmt(pts[k * 2] * unit)} ${fmt(pts[k * 2 + 1] * unit)}`;
      }
      const [tx, ty] = at(to);
      d += ` L ${fmt(tx * unit)} ${fmt(ty * unit)} `;
      target[b] += d;
    }
  }

  const sw = (strokeWidth * unit) / 720;
  const layers = [
    { key: "color", paint: color, list: paths.color },
    { key: "accent", paint: accent, list: paths.accent },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: background }}>
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Flow field"
        style={{ display: "block" }}
      >
        {layers.map((layer) => (
          <g
            key={layer.key}
            fill="none"
            stroke={layer.paint}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {layer.list.map((d, b) => (
              <path
                key={b}
                d={d}
                strokeOpacity={0.9 * (1 - b / BUCKETS) ** 1.4}
                strokeWidth={sw * (1 - (b / BUCKETS) * 0.5)}
              />
            ))}
          </g>
        ))}
      </svg>
    </AbsoluteFill>
  );
}

