  },
} as const;

const ROW_DRAW_AT = 0;
const ROW_STAGGER = 6;
const ROW_DRAW_DUR = 22;
const SLOT_IN = [22, 40] as const;
const MERGE_AT = 44;
const MERGE_STAGGER = 11;
const MERGE_DUR = 20;
const PHASE = Math.PI / 2;

const lerp = (a: number, b: number, k: number) => a + (b - a) * k;

function Grain({ opacity }: { opacity: number }) {
