function wavePath(
  x0: number,
  w: number,
  yc: number,
  amp: number,
  fn: (theta: number) => number,
  periods: number,
  prog: number,
  samples: number,
) {
  const n = Math.max(2, Math.ceil(samples * prog));
  let d = "";
  for (let i = 0; i <= n; i++) {
    const k = (prog * i) / n;
    const x = x0 + w * k;
    const y = yc - amp * fn(k * periods * Math.PI * 2);
    d += `${i ? "L" : "M"}${x.toFixed(2)} ${y.toFixed(2)}`;
  }
  return d;
}

function FourierSumBase({
  harmonics = [1, 3, 5, 7, 9],
  title = "Many parts. One signal.",
  periods = 2,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: FourierSumProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const p = THEMES[theme];
  const count = harmonics.length;
  const maxN = Math.max(...harmonics);
  const samples = Math.max(240, Math.ceil(maxN * periods * 14));

  const labelCol = 58 * u;
  const waveW = W * 0.7;
  const blockX = (W - labelCol - waveW) / 2;
  const waveX = blockX + labelCol;
  const gap = Math.min(80 * u, (H * 0.6) / Math.max(1, count));
  const amp = Math.min(34 * u, gap * 0.42);
  const midY = H * 0.5;

  const mergeStart = (i: number) => MERGE_AT + i * MERGE_STAGGER;
  const mergeEnd = mergeStart(count - 1) + MERGE_DUR;
  const merge = harmonics.map((_, i) =>
    interpolate(t, [mergeStart(i), mergeStart(i) + MERGE_DUR], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    }),
  );
  const merged = merge.reduce((a, b) => a + b, 0);
  const remaining = count - merged;
  const slotIndexY = (idx: number) => midY + (idx - remaining / 2) * gap;
  const rowIndex = (i: number) => 1 + i - merged;

  const FINAL = [mergeEnd - 2, mergeEnd + 26] as const;
  const TITLE_AT = mergeEnd + 14;

  const weights = harmonics.map((_, i) =>
    interpolate(
      t,
      [mergeStart(i) + MERGE_DUR * 0.5, mergeStart(i) + MERGE_DUR],
      [0, 1],
      { ...CLAMP, easing: EASE_IO },
    ),
  );
  const sumFn = (th: number) =>
    harmonics.reduce(
      (s, n, i) => s + (weights[i] * Math.sin(n * (th + PHASE))) / n,
      0,
    );

  const slotY = slotIndexY(0);
  const fin = interpolate(t, FINAL, [0, 1], { ...CLAMP, easing: EASE_IO });
  const finW = W * 0.74;
  const finY = H * 0.43;
  const sumX = lerp(waveX, (W - finW) / 2, fin);
  const sumW = lerp(waveW, finW, fin);
  const sumY = lerp(slotY, finY, fin);
  const sumAmp = lerp(amp, 108 * u, fin);
  const sumStroke = lerp(2.6, 5.5, fin) * u;
  const sumO = Math.min(1, weights[0] * 2.5);

  const slotIn = interpolate(t, SLOT_IN, [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const slotO = slotIn * (1 - fin);
  const titleA = interpolate(t, [TITLE_AT, TITLE_AT + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const capY = lerp(slotY - amp - 40 * u, finY - 158 * u, fin);

  const gid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const isDark = theme === "dark";
  const drift = interpolate(t, [0, 180], [0, 1], { ...CLAMP, easing: EASE_IO });
  const stops = isDark
    ? [AURORA[0], AURORA[1], AURORA[2], AURORA[3]]
    : [AURORA[1], AURORA[2], AURORA[3]];
  const gx1 = sumX - sumW * 0.12 * drift;
  const gx2 = sumX + sumW * (1.04 - 0.12 * drift);
  const fillO = fin * (isDark ? 0.34 : 0.26);
  const sentence = title.match(/^(.*?[.!?\u2026])\s+(.+)$/);
  const inkText = {
    backgroundImage: `linear-gradient(90deg, ${stops.join(", ")})`,
    WebkitBackgroundClip: "text",
    backgroundClip: "text",
    color: "transparent",
  } as const;
  const capX = lerp(waveX, W / 2, fin);

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse ${W * 0.5}px ${H * 0.45}px at 50% 46%, ${p.wash}, transparent 100%)`,
        }}
      />
      <svg
        width={W}
        height={H}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={`${gid}s`}
            gradientUnits="userSpaceOnUse"
            x1={gx1}
            x2={gx2}
            y1={0}
            y2={0}
          >
            {stops.map((c, i) => (
              <stop key={c} offset={i / (stops.length - 1)} stopColor={c} />
            ))}
          </linearGradient>
          <linearGradient
            id={`${gid}f`}
            gradientUnits="userSpaceOnUse"
            x1={0}
            x2={0}
            y1={sumY - sumAmp * 1.25}
            y2={sumY + sumAmp * 1.25}
          >
            <stop offset={0} stopColor="#fff" stopOpacity={1} />
            <stop offset={0.5} stopColor="#fff" stopOpacity={0.05} />
            <stop offset={1} stopColor="#fff" stopOpacity={1} />
          </linearGradient>
          <mask id={`${gid}m`} maskUnits="userSpaceOnUse">
            <rect width={W} height={H} fill={`url(#${gid}f)`} />
          </mask>
        </defs>
        <line
          x1={waveX}
          x2={waveX + waveW * slotIn}
          y1={slotY}
          y2={slotY}
          stroke={p.base}
          strokeWidth={Math.max(1, u)}
          opacity={slotO}
        />
        {harmonics.map((n, i) => {
          const drawAt = ROW_DRAW_AT + i * ROW_STAGGER;
          const prog = interpolate(t, [drawAt, drawAt + ROW_DRAW_DUR], [0, 1], {
            ...CLAMP,
            easing: DRAW,
          });
          if (prog <= 0) return null;
          const o = interpolate(
            t,
            [mergeStart(i) + MERGE_DUR * 0.6, mergeStart(i) + MERGE_DUR],
            [1, 0],
            CLAMP,
          );
          if (o <= 0) return null;
          return (
            <path
              key={n}
              d={wavePath(
                waveX,
                waveW,
                slotIndexY(rowIndex(i)),
                amp,
                (th) => Math.sin(n * (th + PHASE)) / n,
                periods,
                prog,
                samples,
              )}
              fill="none"
              stroke={p.hair}
              strokeWidth={1.4 * u}
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity={o}
            />
          );
        })}
        {fillO > 0 && (
          <path
            d={`${wavePath(sumX, sumW, sumY, sumAmp, sumFn, periods, 1, samples)}L${(sumX + sumW).toFixed(2)} ${sumY.toFixed(2)}L${sumX.toFixed(2)} ${sumY.toFixed(2)}Z`}
            fill={`url(#${gid}s)`}
            opacity={fillO}
            mask={`url(#${gid}m)`}
          />
        )}
        {sumO > 0 && (
          <path
            d={wavePath(sumX, sumW, sumY, sumAmp, sumFn, periods, 1, samples)}
            fill="none"
            stroke={`url(#${gid}s)`}
            strokeWidth={sumStroke}
            strokeLinecap="round"
            strokeLinejoin="round"
            opacity={sumO}
          />
        )}
      </svg>

      {harmonics.map((n, i) => {
        const drawAt = ROW_DRAW_AT + i * ROW_STAGGER;
        const a = interpolate(t, [drawAt + 2, drawAt + 14], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        const out = interpolate(
          t,
          [mergeStart(i), mergeStart(i) + 8],
          [1, 0],
          CLAMP,
        );
        return (
          <div
            key={n}
            style={{
              position: "absolute",
              left: blockX,
              top: slotIndexY(rowIndex(i)) - 12 * u,
              width: labelCol - 14 * u,
              textAlign: "right",
              fontFamily: sans,
              fontWeight: 400,
              fontSize: 15 * u,
              lineHeight: `${24 * u}px`,
              color: p.muted,
              fontVariantNumeric: "tabular-nums",
              opacity: a * out,
              transform: `translateX(${(1 - a) * -8 * u}px)`,
            }}
          >
            {n}×
          </div>
        );
      })}

      <div
        style={{
          position: "absolute",
          left: blockX,
          top: slotY - 16 * u,
          width: labelCol - 14 * u,
          textAlign: "right",
          fontFamily: sans,
          fontWeight: 400,
          fontSize: 22 * u,
          lineHeight: `${32 * u}px`,
          color: accent,
          opacity: slotO,
          transform: `translateX(${(1 - slotIn) * 10 * u}px)`,
        }}
      >
        Σ
      </div>

      <div
        style={{
          position: "absolute",
          left: capX,
          top: capY,
          transform: `translateX(${-50 * fin}%)`,
          display: "flex",
          whiteSpace: "nowrap",
          fontFamily: sans,
          fontWeight: 400,
          fontSize: 15 * u,
          lineHeight: `${24 * u}px`,
          color: p.muted,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {harmonics.map((n, i) => {
          const a = interpolate(
            t,
            [mergeStart(i) + MERGE_DUR * 0.6, mergeStart(i) + MERGE_DUR + 4],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
          return (
            <span
              key={n}
              style={{
                opacity: a,
                transform: `translateY(${(1 - a) * 6 * u}px)`,
                display: "inline-block",
              }}
            >
              {i ? <span style={{ padding: `0 ${8 * u}px` }}>+</span> : null}
              {n}×
            </span>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: finY + 162 * u,
          textAlign: "center",
          fontFamily: display,
          fontWeight: 400,
          fontSize: 60 * u,
          lineHeight: 1.05,
          letterSpacing: "-0.02em",
          color: p.fg,
          textWrap: "balance",
          opacity: titleA,
          transform: `translateY(${(1 - titleA) * 18 * u}px)`,
        }}
      >
        {sentence ? (
          <>
            {sentence[1]}{" "}
            <span
              style={{
                ...inkText,
                fontStyle: "italic",
                paddingRight: "0.08em",
              }}
            >
              {sentence[2]}
            </span>
          </>
        ) : (
          title
        )}
      </div>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  title: {
    type: "text-content",
    default: "Many parts. One signal.",
    description: "Title",
  },
  periods: {
    type: "number",
    default: 2,
    min: 0,
    max: 10,
    step: 1,
    description: "Periods",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","periods","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "Many parts. One signal.",
  periods: 2,
  speed: 1,
};

type FourierSumElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FourierSumBase>;

const FourierSumInner = forwardRef<
  HTMLDivElement,
  FourierSumElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FourierSum>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FourierSumBase
          {...(componentProps as unknown as ComponentProps<typeof FourierSumBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FourierSum = Interactive.withSchema({
  Component: FourierSumInner,
  componentName: "<FourierSum>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

// gradients.sh "fluted" palette
const FLUTED = {
  bg: "#050507",
  c: ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"],
} as const;

interface FractionSplitProps {
  line?: string;
  highlight?: string;
  accentPiece?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const SEGS = 8;
const LEVELS = [
  { at: 24, label: "1/2", size: 4 },
  { at: 50, label: "1/4", size: 2 },
  { at: 76, label: "1/8", size: 1 },
];
const REG = 104;
const REG_LEN = 26;
const TEXT_IN = REG + 12;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const SPLIT_SPRING = { damping: 17, stiffness: 170, mass: 0.7 };

const THEMES = {
  dark: {
    bg: FLUTED.bg,
    fg: "#F3F2EF",
    muted: "#8B8A90",
    outline: "rgba(243,242,239,0.34)",
    hl: ["#6a9dff", FLUTED.c[2], "#ffb27e"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    outline: "rgba(18,18,20,0.34)",
    hl: [FLUTED.c[0], FLUTED.c[2], "#e85a26"],
    grain: 0.045,
  },
} as const;

function boundaryLevel(b: number) {
  if (b === 4) return 0;
  if (b === 2 || b === 6) return 1;
  return 2;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={37}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function FractionSplitBase({
  line = "Renders in 1/8 the time.",
  highlight = "1/8",
  accentPiece = 0,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: FractionSplitProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const ap = Math.max(0, Math.min(SEGS - 1, Math.round(accentPiece)));

  const cx = width / 2;
  const cy = height / 2;
  const barW = Math.min(width * 0.8, 1040 * u);
  const barH = 116 * u;
  const G = 14 * u;
  const R = 8 * u;
  const E = 3 * G;
  const textSize = 96 * u;
  const textLines = line.length * 0.43 * textSize > barW * 0.98 ? 2 : 1;
  const textH = textSize * textLines * 1.02;
  const textGap = 58 * u;
  const finalTop = cy - (barH + textGap + textH) / 2;

  const open: number[] = [0];
  for (let b = 1; b < SEGS; b++) {
    const lv = LEVELS[boundaryLevel(b)];
    const stagger = boundaryLevel(b) === 2 ? Math.abs(b - 4) * 0.6 : 0;
    open.push(
      spring({ frame: t - lv.at - stagger, fps, config: SPLIT_SPRING }),
    );
  }
  const totalGap = open.reduce((s, x) => s + x, 0) * G;
  const segW = (barW - totalGap) / SEGS;

  const reg = interpolate(t, [REG, REG + REG_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rise = interpolate(t, [REG, REG + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const drainOf = (j: number) => {
    const order = j > ap ? j - 1 : j;
    return interpolate(
      t,
      [REG + 2 + order * 1.5, REG + 16 + order * 1.5],
      [0, 1],
      { ...CLAMP, easing: EASE_IO },
    );
  };
  const left = cx - barW / 2 - (E / 2) * reg;
  const xs: number[] = [];
  let acc = left;
  for (let j = 0; j < SEGS; j++) {
    if (j > 0) acc += open[j] * G;
    xs.push(acc + (j > ap ? E * reg : 0));
    acc += segW;
  }
  const top = cy - barH / 2 + (finalTop - (cy - barH / 2)) * reg;

  const wipe = interpolate(t, [2, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const runs: { j0: number; j1: number }[] = [];
  for (let j = 0; j < SEGS; j++) {
    const solo = reg > 0 || j === 0 || open[j] > 0.002;
    if (solo) runs.push({ j0: j, j1: j });
    else runs[runs.length - 1].j1 = j;
  }

  const cornerAt = (b: number) =>
    b <= 0 || b >= SEGS ? R : R * Math.min(1, open[b] * 1.6 + reg);

  const labelStyle = {
    position: "absolute",
    left: 14 * u,
    fontFamily: sans,
    fontWeight: 500,
    fontSize: 20 * u,
    lineHeight: 1.2,
    letterSpacing: "-0.01em",
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
  } as const;
  const lastLabel = LEVELS[LEVELS.length - 1].label;
  const drift = interpolate(t, [REG, REG + REG_LEN + 50], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // the palette's blue stop follows the accent prop
  const blue = accent;
  const flute = (deg: number) =>
    `linear-gradient(${deg + 12 * drift}deg, ${FLUTED.c[3]} 0%, ${FLUTED.c[2]} 30%, ${blue} 68%, ${FLUTED.c[0]} 100%)`;

  const pieces = runs.map(({ j0, j1 }) => {
    const x = xs[j0];
    const w = xs[j1] + segW - x;
    const rl = cornerAt(j0);
    const rr = cornerAt(j1 + 1);
    const box = {
      position: "absolute",
      left: x,
      top,
      width: w,
      height: barH,
      borderTopLeftRadius: rl,
      borderBottomLeftRadius: rl,
      borderTopRightRadius: rr,
      borderBottomRightRadius: rr,
    } as const;
    if (reg <= 0) {
      return <div key={`p${j0}-${j1}`} style={{ ...box, background: p.fg }} />;
    }
    const isAccent = j0 === ap;
    const fillH = barH * (isAccent ? rise : 1 - drainOf(j0));
    return (
      <div key={`p${j0}-${j1}`}>
        {isAccent ? null : (
          <div
            style={{
              ...box,
              boxSizing: "border-box",
              border: `${Math.max(1, 1.5 * u)}px solid ${p.outline}`,
            }}
          />
        )}
        <div
          style={{
            ...box,
            overflow: "hidden",
            background: isAccent ? p.fg : "transparent",
          }}
        >
          {isAccent ? (
            <div style={{ ...labelStyle, top: 12 * u, color: p.bg }}>
              {lastLabel}
            </div>
          ) : null}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: fillH,
              overflow: "hidden",
              backgroundColor: p.fg,
              backgroundImage: isAccent ? flute(20) : undefined,
              backgroundSize: isAccent ? `${w}px ${barH}px` : undefined,
              backgroundPosition: "left bottom",
            }}
          >
            <div
              style={{
                ...labelStyle,
                top: 12 * u - (barH - fillH),
                color: isAccent ? "#FFFFFF" : p.bg,
              }}
            >
              {lastLabel}
            </div>
          </div>
        </div>
      </div>
    );
  });

  const labels: ReactNode[] = [];
  LEVELS.forEach((lv, li) => {
    const inK = interpolate(t, [lv.at + 6, lv.at + 16], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const next = LEVELS[li + 1];
    const outK = next
      ? interpolate(t, [next.at - 5, next.at], [0, 1], CLAMP)
      : 0;
    if (!next && reg > 0) return;
    for (let g = 0; g < SEGS / lv.size; g++) {
      const j0 = g * lv.size;
      const op = inK * (1 - outK);
      if (op <= 0) continue;
      labels.push(
        <div
          key={`l${li}-${g.toString()}`}
          style={{
            ...labelStyle,
            left: xs[j0] + 14 * u,
            top: top + 12 * u,
            color: p.bg,
            opacity: op,
            transform: `translateY(${(1 - inK) * 6 * u}px)`,
          }}
        >
          {lv.label}
        </div>,
      );
    }
  });

  const idx = highlight ? line.indexOf(highlight) : -1;
  const words: { text: string; hl: boolean }[] = [];
  const pushWords = (s: string, hl: boolean) => {
    for (const w of s.split(/\s+/).filter(Boolean)) words.push({ text: w, hl });
  };
  if (idx >= 0) {
    pushWords(line.slice(0, idx), false);
    words.push({ text: highlight, hl: true });
    const rest = line.slice(idx + highlight.length);
    if (/^\S/.test(rest) && words.length) {
      const m = /^(\S+)(.*)$/.exec(rest);
      if (m) {
        words[words.length - 1] = {
          text: `${highlight}${m[1]}`,
          hl: true,
        };
        pushWords(m[2], false);
      }
    } else pushWords(rest, false);
  } else pushWords(line, false);

  const push = interpolate(t, [0, REG + REG_LEN + 40], [0.985, 1.01], {
    ...CLAMP,
    easing: EASE_IO,
  });

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{ transform: `scale(${push})`, transformOrigin: "50% 50%" }}
      >
        <AbsoluteFill
          style={{
            clipPath: `inset(0 ${(1 - wipe) * 100}% 0 0)`,
          }}
        >
          {pieces}
          {labels}
        </AbsoluteFill>

        <div
          style={{
            position: "absolute",
            left: cx - barW * 0.5,
            width: barW,
            top: finalTop + barH + textGap,
            textAlign: "center",
            fontFamily: sans,
            fontWeight: 400,
            fontSize: textSize,
            lineHeight: 1.02,
            letterSpacing: "-0.035em",
            color: p.fg,
            textWrap: "balance",
          }}
        >
          {words.map((w, i) => {
            const k = interpolate(
              t,
              [TEXT_IN + i * 3, TEXT_IN + i * 3 + 18],
              [0, 1],
              { ...CLAMP, easing: EASE_OUT },
            );
            return (
              <span key={`w${i.toString()}`}>
                <span
                  style={{
                    display: "inline-block",
                    color: w.hl ? "transparent" : p.fg,
                    ...(w.hl
                      ? {
                          fontWeight: 500,
                          paddingRight: "0.04em",
                          backgroundImage: `linear-gradient(${172 + 10 * drift}deg, ${p.hl[0]} 8%, ${blue} 32%, ${p.hl[1]} 70%, ${p.hl[2]} 94%)`,
                          WebkitBackgroundClip: "text",
                          backgroundClip: "text",
                        }
                      : null),
                    opacity: k,
                    filter: k < 0.99 ? `blur(${(1 - k) * 8 * u}px)` : undefined,
                    transform: `translateY(${(1 - k) * 18 * u}px)`,
                  }}
                >
                  {w.text}
                </span>
                {i < words.length - 1 ? " " : null}
              </span>
            );
          })}
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

