function Avatar({
  login,
  avatarUrl,
  size,
  theme,
}: {
  login: string;
  avatarUrl: string;
  size: number;
  theme: Theme;
}) {
  const [errored, setErrored] = useState(false);
  const ringStyle = {
    width: size,
    height: size,
    borderRadius: 9999,
    border: `1px solid ${theme.border}`,
    flexShrink: 0,
  } as const;

  if (errored || !avatarUrl) {
    return (
      <div
        style={{
          ...ringStyle,
          background: theme.bgSubtle,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: theme.fgMuted,
          fontSize: size * 0.42,
          fontWeight: 600,
        }}
      >
        {login.charAt(0).toUpperCase()}
      </div>
    );
  }

  return (
    <Img
      src={avatarUrl}
      crossOrigin="anonymous"
      onError={() => setErrored(true)}
      style={{ ...ringStyle, objectFit: "cover" }}
    />
  );
}

