/** Everything under the glass. Rendered once flat and once magnified. */
function Scene({
  t,
  lines,
  italicLast,
  logo,
  src,
  children,
  accent,
  p,
  L,
}: {
  t: number;
  lines: string[];
  italicLast: boolean;
  logo?: React.ReactNode;
  src?: string;
  children?: React.ReactNode;
  accent: string;
  p: Palette;
  L: Layout;
}) {
  const { width, height } = useVideoConfig();
  const { u } = L;
  const rise = (d: number) =>
    interpolate(t, [d - 8, d + 20], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const paneIn = rise(4);
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width,
        height,
        background: p.bg,
        overflow: "hidden",
