} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","label","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  label: "remocn",
  speed: 1,
};

type GlyphMatrixElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GlyphMatrixBase>;

const GlyphMatrixInner = forwardRef<
  HTMLDivElement,
  GlyphMatrixElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GlyphMatrix>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GlyphMatrixBase
          {...(componentProps as unknown as ComponentProps<typeof GlyphMatrixBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GlyphMatrix = Interactive.withSchema({
  Component: GlyphMatrixInner,
  componentName: "<GlyphMatrix>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

