function Handles({
  w,
  h,
  k,
  color,
  fill,
  t,
}: {
  w: number;
  h: number;
  k: number;
  color: string;
  fill: string;
  t: number;
}) {
  if (t <= 0.001) return null;
  const s = 7 * k;
  const corners = [
    [0, 0],
    [w, 0],
    [0, h],
    [w, h],
  ];
  return (
    <>
      {corners.map(([cx, cy], i) => (
        <div
          key={`h${cx}-${cy}`}
          style={{
            position: "absolute",
            left: cx - s / 2,
            top: cy - s / 2,
            width: s,
            height: s,
            background: fill,
            border: `${1.25 * k}px solid ${color}`,
            borderRadius: 1.5 * k,
            transform: `scale(${Math.max(0, t - i * 0.04)})`,
            boxSizing: "border-box",
          }}
        />
      ))}
    </>
  );
}

