  theme?: "dark" | "light";
  accent?: string;
  catalog?: Record<string, GraphNodeSpec>;
  layouts?: GraphLayout[];
  kicker?: string;
  cursorName?: string;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
