export interface GravityGridProps {
  /** Replaces the remocn logo at the bottom of the well; `name` is set beside it. */
  logo?: React.ReactNode;
  name?: string;
  /** Small line under the name. Pass an empty string to hide it. */
  caption?: string;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "radial-glow" palette: bg #020204, [#f3f1ff, #9db4ff, #5a46cb, #1d1240].
// It lights the well: a glowing ring at the bottom, and the brightest grid lines.
const GLOW = ["#f3f1ff", "#9db4ff", "#5a46cb", "#1d1240"] as const;

const THEMES = {
  dark: {
    bg: "#020204",
    ramp: ["#8E8D99", "#8E8D99", GLOW[1], GLOW[0]],
    fg: "#F3F2EF",
    muted: "#8B8A90",
    base: 0.13,
    lit: 0.95,
    pool: "rgba(2,2,4,0.9)",
    ring: [0.75, 0.5, 0.42],
    disc: 0.55,
    vignette: "rgba(0,0,0,0.65)",
    grain: 0.06,
    glow: 0.32,
    bloom: 0.6,
  },
  light: {
    bg: "#F5F4F0",
    ramp: ["#55545C", "#55545C", GLOW[2], GLOW[3]],
    fg: "#121214",
    muted: "#6E6C67",
    base: 0.12,
    lit: 0.8,
    pool: "rgba(245,244,240,0.94)",
    ring: [0.0, 0.7, 0.5],
    disc: 0.42,
    vignette: "rgba(120,110,95,0.14)",
    grain: 0.045,
    glow: 0.14,
    bloom: 0,
  },
} as const;

/** Frame the mass reaches the bottom of the well. */
const IMPACT = 72;
const WELL_Z = 13;
const CORE = 2.6;
const DEPTH = 5.4;
const LEVELS = 14;

function smooth(a: number, b: number, x: number) {
  const k = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return k * k * (3 - 2 * k);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.85"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function GravityGrid({
  logo,
  name = "remocn",
  caption = "Launch videos, in components.",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: GravityGridProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const pal = THEMES[theme];
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  // ---- the mass: accelerates down, lands, the well overshoots and settles ----
  const fallP = interpolate(t, [14, IMPACT], [0, 1], CLAMP);
  const fall = fallP ** 2.2;
  const after = Math.max(0, t - IMPACT);
  const bounce =
    t > IMPACT ? 0.12 * Math.exp(-after / 9) * Math.sin(after / 3.2) : 0;
  const depth = DEPTH * (fall + bounce);
  const massY = interpolate(fall, [0, 1], [7, -DEPTH + 0.9]);

  // ---- one ripple from the impact ----
  const ripR = after * 0.42;
  const ripAmp = t > IMPACT ? 0.55 * Math.exp(-after / 34) : 0;
  const rippleAt = (r: number) => {
    if (ripAmp <= 0.001) return 0;
    const dr = r - ripR;
    return (
      ripAmp *
      Math.exp(-(dr * dr) / 5) *
      Math.sin(dr * 1.5) *
      smooth(0, 2.5, ripR - 1.5)
    );
  };

  const heightAt = (x: number, z: number) => {
    const dx = x;
    const dz = z - WELL_Z;
    const r = Math.sqrt(dx * dx + dz * dz);
    return -depth * (CORE / Math.sqrt(r * r + CORE * CORE)) + rippleAt(r);
  };

  // ---- camera: slow push in, tilting down to follow the mass ----
  const follow = interpolate(t, [10, IMPACT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const camH = 6.4 - follow * 0.3;
  const camZ = interpolate(t, [0, 240], [-3.4, -2], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const f = height * 1.3;
  // look at the rim first, then down into the well as the mass sinks
  const lookY = -DEPTH * 0.92 * follow;
  const pitch =
    Math.atan2(camH - lookY, WELL_Z - camZ) -
    Math.atan((0.03 * height) / f) * (1 - follow);
  const camX = Math.sin(t / 90) * 0.35;
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const project = (x: number, y: number, z: number) => {
    const dx = x - camX;
    const dy = y - camH;
    const dz = z - camZ;
    const yc = dy * cosP + dz * sinP;
    const zc = -dy * sinP + dz * cosP;
    return {
      x: width / 2 + (f * dx) / zc,
      y: height / 2 - (f * yc) / zc,
      zc,
    };
  };

  // ---- lockup at the bottom of the well ----
  const lockIn = interpolate(t, [IMPACT + 6, IMPACT + 32], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const capIn = interpolate(t, [IMPACT + 18, IMPACT + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  // ---- light from the mass catches the curvature ----
  const brightness = (x: number, z: number, y: number) => {
    const e = 0.05;
    const gx = (heightAt(x + e, z) - heightAt(x - e, z)) / (2 * e);
    const gz = (heightAt(x, z + e) - heightAt(x, z - e)) / (2 * e);
    const nl = Math.sqrt(gx * gx + 1 + gz * gz);
    const lx = -x;
    const ly = massY - y;
    const lz = WELL_Z - z;
    const d2 = lx * lx + ly * ly + lz * lz;
    const dl = Math.sqrt(d2);
    const ndl = Math.max(0, (-gx * lx + ly - gz * lz) / (nl * dl));
    const falloff = 14 / (14 + d2);
    // the slope itself catches a rim of light, even far from the mass
    const slope = Math.min(1, Math.sqrt(gx * gx + gz * gz) * 0.9);
    const r = Math.sqrt(x * x + (z - WELL_Z) ** 2);
    const rip =
      ripAmp > 0 ? Math.exp(-((r - ripR) ** 2) / 4) * ripAmp * 1.1 : 0;
    return ndl * falloff * 1.6 + slope * 0.55 * fall + rip;
  };

  const levels: string[] = Array.from({ length: LEVELS + 1 }, () => "");
  const addLine = (pts: { x: number; z: number }[]) => {
    let prev: { sx: number; sy: number; ok: boolean } | null = null;
    for (const p of pts) {
      const y = heightAt(p.x, p.z);
      const s = project(p.x, y, p.z);
      const ok = s.zc > 0.6;
      if (prev?.ok && ok) {
        const r = Math.sqrt(p.x * p.x + (p.z - WELL_Z) ** 2);
        const fog =
          (1 - smooth(18, 80, s.zc)) *
          smooth(0.6, 3, s.zc) *
          (1 - smooth(16, 34, Math.abs(p.x)));
        const hole = 1 - lockIn * (1 - smooth(0.3, 2, r)) * 0.8;
        const b =
          (pal.base + pal.lit * Math.min(1, brightness(p.x, p.z, y))) *
          fog *
          hole;
        const lv = Math.min(LEVELS, Math.round(b * LEVELS));
        if (lv > 0) {
          levels[lv] +=
            `M${prev.sx.toFixed(1)} ${prev.sy.toFixed(1)}L${s.x.toFixed(1)} ${s.y.toFixed(1)}`;
        }
      }
      prev = { sx: s.x, sy: s.y, ok };
    }
  };

  const STEP = 0.5;
  for (let gx = -34; gx <= 34; gx++) {
    const pts = [];
    for (let z = 1; z <= 90; z += z < 30 ? STEP : 1) pts.push({ x: gx, z });
    addLine(pts);
  }
  for (let gz = 1; gz <= 90; gz++) {
    const pts = [];
    for (let x = -34; x <= 34; x += Math.abs(x) < 14 ? STEP : 1)
      pts.push({ x, z: gz });
    addLine(pts);
  }

  const bottom = project(0, -depth, WELL_Z);
  const horizonY = height / 2 - f * Math.tan(pitch);
  const scaleAtBottom = f / bottom.zc / (height * 0.072);
  const lift = (1 - lockIn) * 14 * u;
  const markSize = 62 * u * scaleAtBottom;
  const glowR = height * 0.34;
  const ringRx = height * 0.42 * (0.9 + 0.1 * lockIn) * (1 + ripAmp * 0.25);
  const ringRy = ringRx * Math.max(0.2, Math.sin(pitch) * 0.62);
  const massS = project(0, Math.max(massY, -depth + 0.4), WELL_Z);
  const massR = (6 * u * f) / Math.max(1, massS.zc) / (height * 0.072);
  const massO =
    interpolate(t, [10, 22], [0, 1], CLAMP) *
    (1 - interpolate(t, [IMPACT - 2, IMPACT + 10], [0, 1], CLAMP));
  const mixA = (c: string, a: number) =>
    `color-mix(in oklab, ${c} ${Math.round(Math.max(0, Math.min(1, a)) * 100)}%, transparent)`;
  const glowO = pal.glow * (0.35 * fall + 0.65 * lockIn) * (1 + ripAmp * 0.6);

  return (
    <AbsoluteFill style={{ background: pal.bg, overflow: "hidden" }}>
      {/* the light at the bottom of the well */}
      <AbsoluteFill
        style={{
          background: [
            `radial-gradient(${ringRx}px ${ringRy}px at ${bottom.x}px ${bottom.y + ringRy * 0.12}px, transparent 46%, ${mixA(GLOW[0], pal.ring[0])} 55%, ${mixA(GLOW[1], pal.ring[1])} 62%, ${mixA(GLOW[2], pal.ring[2])} 70%, transparent 86%)`,
            `radial-gradient(circle ${glowR}px at ${bottom.x}px ${bottom.y}px, ${mixA(GLOW[2], pal.disc)}, ${mixA(GLOW[3], pal.disc * 0.6)} 40%, transparent 70%)`,
          ].join(", "),
          opacity: glowO,
        }}
      />
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <filter id={`bloom${id}`}>
            <feGaussianBlur stdDeviation={2.2 * u} />
          </filter>
        </defs>
        {/* a soft bloom under the brightest lines */}
        <g filter={`url(#bloom${id})`} opacity={pal.bloom}>
          {levels.map((d, lv) =>
            lv >= LEVELS * 0.55 && d ? (
              <path
                key={lv}
                d={d}
                stroke={GLOW[2]}
                strokeWidth={2.4 * u}
                fill="none"
                opacity={(lv / LEVELS) ** 2}
              />
            ) : null,
          )}
        </g>
        {levels.map((d, lv) =>
          d ? (
            <path
              key={lv}
              d={d}
              stroke={interpolateColors(
                lv / LEVELS,
                [0, 0.42, 0.72, 1],
                [...pal.ramp],
              )}
              strokeOpacity={lv / LEVELS}
              strokeWidth={1.05 * u}
              strokeLinecap="round"
              fill="none"
            />
          ) : null,
        )}
      </svg>

      {/* the mass: a bright accent bead that sinks and becomes the light */}
      <div
        style={{
          position: "absolute",
          left: massS.x - massR,
          top: massS.y - massR,
          width: massR * 2,
          height: massR * 2,
          borderRadius: "50%",
          background: accent,
          boxShadow: `0 0 ${massR * 3}px ${massR}px ${mixA(accent, 0.45)}`,
          opacity: massO,
        }}
      />

      {/* the name settles where the mass came to rest */}
      <div
        style={{
          position: "absolute",
          left: bottom.x,
          top: bottom.y,
          transform: `translate(-50%, -50%) translateY(${lift}px)`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 14 * u * scaleAtBottom,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: markSize * 6.2,
            height: markSize * 3.4,
            transform: "translate(-50%, -50%)",
            background: `radial-gradient(ellipse closest-side, ${pal.pool}, transparent)`,
            opacity: lockIn * 0.95,
          }}
        />
        <div
          style={{
            position: "relative",
            display: "flex",
            alignItems: "center",
            gap: 10 * u * scaleAtBottom,
            opacity: lockIn,
            filter: `blur(${(1 - lockIn) * 6 * u}px)`,
            transform: `scale(${0.94 + lockIn * 0.06})`,
          }}
        >
          {logo ? (
            <>
              {logo}
              <div
                style={{
                  fontFamily: sans,
                  fontWeight: 500,
                  fontSize: markSize * 0.95,
                  lineHeight: 1,
                  letterSpacing: "-0.035em",
                  color: pal.fg,
                }}
              >
                {name}
              </div>
            </>
          ) : (
            <RemocnLogo fontSize={markSize * 1.02} color={pal.fg} />
          )}
        </div>
        {caption ? (
          <div
            style={{
              position: "relative",
              fontFamily: sans,
              fontWeight: 400,
              fontSize: 18 * u * scaleAtBottom,
              letterSpacing: "0em",
              color: pal.muted,
              opacity: capIn,
              transform: `translateY(${(1 - capIn) * 8 * u}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {caption}
          </div>
        ) : null}
      </div>

      {/* atmospheric falloff toward the horizon */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(to bottom, ${pal.bg} ${Math.max(0, horizonY + height * 0.03)}px, ${pal.bg}00 ${horizonY + height * 0.38}px)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 75% at 50% 50%, transparent 50%, ${pal.vignette} 100%)`,
        }}
      />
      <Grain opacity={pal.grain} />
    </AbsoluteFill>
  );
}

import React, { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Interactive, Sequence, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type GravityPileColors = {
  background: string;
  shapes: string[];
  accent: string;
  floor: string;
};

type GravityPileProps = {
  /** Number of falling bodies. */
  count?: number;
  seed?: number;
  /** Gravity multiplier. */
  gravity?: number;
  /** Optional nodes dropped as round bodies, landing on top of the heap. */
  items?: React.ReactNode[];
  colors?: Partial<GravityPileColors>;
  /** Color of the single accent body. Overrides `colors.accent`. */
  accentColor?: string;
  /** Background color. Overrides `colors.background`. */
  backgroundColor?: string;
  speed?: number;
};

const gravityPileDefaults = {
  count: 30,
  seed: 7,
  gravity: 1,
  colors: {
    background: "#111111",
    shapes: ["#FFFFFF", "#C9C9C9", "#7A7A7A"],
    accent: "#E5322D",
    floor: "#FFFFFF",
  } satisfies GravityPileColors,
  speed: 1,
};

type Kind = "circle" | "square" | "triangle" | "item";
type Body = { r: number; kind: Kind; color: number; accent: boolean };
type Sim = { bodies: Body[]; frames: Float32Array[]; floor: number };

const FRAMES = 150;
const SUBSTEPS = 10;
const ITERATIONS = 4;
const BOUNCE = 0.42;
const FRICTION = 0.12;
const DAMPING = 0.999;
const GRIP = 0.45;
const SETTLE_FROM = 46;
const SETTLE_FRAMES = 18;

// Verlet integration with position-based circle contacts. Runs once per
// (size, count, seed, gravity), records every frame, and the component only
// reads the table back.
function simulate(
  width: number,
  height: number,
  count: number,
  seed: number,
  gravity: number,
  itemCount: number,
): Sim {
  const rnd = (key: string, i: number) =>
    random(`gravity-pile-${seed}-${key}-${i}`);
  const floor = height * 0.9;
  const g = (height / 200) * gravity;
  const dt = 1 / SUBSTEPS;
  // Weaker gravity means a slower rain, so the heap settles later.
  const settleFrom = SETTLE_FROM / Math.sqrt(Math.max(0.2, gravity));
  const kinds: Kind[] = ["circle", "square", "triangle"];
  const accentIndex = Math.max(0, count - itemCount - 3);
  const bodies: Body[] = Array.from({ length: count }, (_, i) => ({
    r: height * (0.036 + rnd("r", i) * 0.032),
    kind: i >= count - itemCount ? "item" : kinds[Math.floor(rnd("k", i) * 3)],
    color: Math.floor(rnd("c", i) * 3),
    accent: i === accentIndex,
  }));
  const n = bodies.length;
  const x = new Float64Array(n);
  const y = new Float64Array(n);
  const px = new Float64Array(n);
  const py = new Float64Array(n);
  const angle = new Float64Array(n);
  const spin = new Float64Array(n);
  // Spawn in a tall column above the frame, rejecting overlaps so nothing
  // explodes apart on the first step.
  for (let i = 0; i < n; i++) {
    const r = bodies[i].r;
    const band = height * (0.1 + (i / Math.max(1, n)) * 2);
    for (let attempt = 0; attempt < 40; attempt++) {
      x[i] = width * (0.5 + (rnd(`x${attempt}`, i) - 0.5) * 0.26);
      y[i] = -r - band - rnd(`y${attempt}`, i) * height * 0.25;
      let clear = true;
      for (let j = 0; j < i && clear; j++) {
        const gap = bodies[i].r + bodies[j].r + 2;
        clear = (x[i] - x[j]) ** 2 + (y[i] - y[j]) ** 2 > gap * gap;
      }
      if (clear) break;
    }
    px[i] = x[i] - (rnd("vx", i) - 0.5) * 0.6 * dt;
    py[i] = y[i] - height * 0.004 * dt;
    angle[i] = rnd("a", i) * Math.PI * 2;
    spin[i] = (rnd("s", i) - 0.5) * 0.02;
  }

  const frames: Float32Array[] = [];
  const record = () => {
    const out = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      out[i * 3] = x[i];
      out[i * 3 + 1] = y[i];
      out[i * 3 + 2] = angle[i];
    }
    frames.push(out);
  };
  record();

  for (let f = 1; f <= FRAMES; f++) {
    // Once damped out, the heap sleeps: no more solver creep.
    if (f > settleFrom + SETTLE_FRAMES) {
      frames.push(frames[frames.length - 1]);
      continue;
    }
    for (let s = 0; s < SUBSTEPS; s++) {
      // Late in the sim, bleed energy off so the heap comes fully to rest
      // instead of creeping forever.
      const settle = Math.min(1, Math.max(0, (f - settleFrom) / SETTLE_FRAMES));
      const damping = DAMPING - settle * 0.12;
      for (let i = 0; i < n; i++) {
        const vx = (x[i] - px[i]) * damping;
        const vy = (y[i] - py[i]) * damping;
        px[i] = x[i];
        py[i] = y[i];
        x[i] += vx;
        y[i] += vy + g * dt * dt;
      }
      for (let it = 0; it < ITERATIONS; it++) {
        for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
            const dx = x[j] - x[i];
            const dy = y[j] - y[i];
            const min = bodies[i].r + bodies[j].r;
            const d2 = dx * dx + dy * dy;
            if (d2 >= min * min || d2 === 0) continue;
            const d = Math.sqrt(d2);
            const push = (min - d) / d;
            const mi = bodies[i].r ** 2;
            const mj = bodies[j].r ** 2;
            const wi = mj / (mi + mj);
            const wj = mi / (mi + mj);
            x[i] -= dx * push * wi;
            y[i] -= dy * push * wi;
            x[j] += dx * push * wj;
            y[j] += dy * push * wj;
          }
        }
        for (let i = 0; i < n; i++) {
          const r = bodies[i].r;
          if (y[i] + r > floor) {
            const vy = y[i] - py[i];
            y[i] = floor - r;
            // Reflect only real impacts so resting bodies do not buzz.
            py[i] = vy > g * dt * 4 ? y[i] + vy * BOUNCE : y[i];
            px[i] = x[i] - (x[i] - px[i]) * (1 - FRICTION);
          }
          if (x[i] - r < 0) {
            x[i] = r;
            px[i] = x[i] + (x[i] - px[i]) * BOUNCE;
          }
          if (x[i] + r > width) {
            x[i] = width - r;
            px[i] = x[i] + (x[i] - px[i]) * BOUNCE;
          }
        }
      }
      // Contact friction: damp relative sliding so bodies stack instead of
      // flowing apart like marbles.
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const dx = x[j] - x[i];
          const dy = y[j] - y[i];
          const min = bodies[i].r + bodies[j].r + 0.5;
          const d2 = dx * dx + dy * dy;
          if (d2 >= min * min || d2 === 0) continue;
          const d = Math.sqrt(d2);
          const tx = -dy / d;
          const ty = dx / d;
          const rel =
            (x[j] - px[j] - (x[i] - px[i])) * tx +
            (y[j] - py[j] - (y[i] - py[i])) * ty;
          const mi = bodies[i].r ** 2;
          const mj = bodies[j].r ** 2;
          const k = rel * GRIP;
          px[i] -= tx * k * (mj / (mi + mj));
          py[i] -= ty * k * (mj / (mi + mj));
          px[j] += tx * k * (mi / (mi + mj));
          py[j] += ty * k * (mi / (mi + mj));
        }
      }
      for (let i = 0; i < n; i++) {
        const r = bodies[i].r;
        const vx = x[i] - px[i];
        // Bodies near the floor or the heap roll; free-falling ones keep spinning.
        const grounded =
          y[i] + r > floor - 1 || Math.abs(y[i] - py[i]) < g * dt;
        if (grounded) spin[i] = Math.abs(vx) > 0.05 ? vx / r : spin[i] * 0.8;
        angle[i] += spin[i];
      }
    }
    record();
  }
  return { bodies, frames, floor };
}

function Shape({ body, fill }: { body: Body; fill: string }) {
  const r = body.r;
  if (body.kind === "circle") return <circle r={r} fill={fill} />;
  if (body.kind === "square") {
    const h = r * 0.84;
    return (
      <rect
        x={-h}
        y={-h}
        width={h * 2}
        height={h * 2}
        rx={r * 0.12}
        fill={fill}
      />
    );
  }
  const c = r * 1.12;
  const pts = [0, 1, 2]
    .map((k) => {
      const a = -Math.PI / 2 + (k * Math.PI * 2) / 3;
      return `${(Math.cos(a) * c).toFixed(2)},${(Math.sin(a) * c + r * 0.12).toFixed(2)}`;
    })
    .join(" ");
  return (
    <polygon
      points={pts}
      fill={fill}
      strokeLinejoin="round"
      stroke={fill}
      strokeWidth={r * 0.14}
    />
  );
}

function GravityPileBase({
  count = gravityPileDefaults.count,
  seed = gravityPileDefaults.seed,
  gravity = gravityPileDefaults.gravity,
  items,
  colors: colorOverrides,
  accentColor,
  backgroundColor,
  speed = gravityPileDefaults.speed,
}: GravityPileProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const baseColors = { ...gravityPileDefaults.colors, ...colorOverrides };
  const colors = {
    ...baseColors,
    accent: accentColor ?? baseColors.accent,
    background: backgroundColor ?? baseColors.background,
  };
  const itemCount = Math.min(
    items?.length ?? 0,
    Math.max(1, Math.round(count)),
  );
  const sim = useMemo(
    () =>
      simulate(
        width,
        height,
        Math.max(1, Math.round(count)),
        seed,
        gravity,
        itemCount,
      ),
    [width, height, count, seed, gravity, itemCount],
  );

  const t = Math.min(FRAMES, Math.max(0, (frame * speed * 30) / fps));
  const f0 = Math.floor(t);
  const f1 = Math.min(FRAMES, f0 + 1);
  const mix = t - f0;
  const a = sim.frames[f0];
  const b = sim.frames[f1];
  const n = sim.bodies.length;

  return (
    <AbsoluteFill
      style={{ backgroundColor: colors.background, overflow: "hidden" }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <line
          x1={0}
          x2={width}
          y1={sim.floor + 1}
          y2={sim.floor + 1}
          stroke={colors.floor}
          strokeOpacity={0.25}
          strokeWidth={2}
        />
        {sim.bodies.map((body, i) => {
          if (body.kind === "item") return null;
          const x = a[i * 3] + (b[i * 3] - a[i * 3]) * mix;
          const y = a[i * 3 + 1] + (b[i * 3 + 1] - a[i * 3 + 1]) * mix;
          const rot = a[i * 3 + 2] + (b[i * 3 + 2] - a[i * 3 + 2]) * mix;
          const fill = body.accent
            ? colors.accent
            : colors.shapes[body.color % colors.shapes.length];
          return (
            <g
              key={i}
              transform={`translate(${x.toFixed(2)} ${y.toFixed(2)}) rotate(${((rot * 180) / Math.PI).toFixed(2)})`}
            >
              <Shape body={body} fill={fill} />
            </g>
          );
        })}
      </svg>
      {items?.slice(0, itemCount).map((item, j) => {
        const i = n - itemCount + j;
        const body = sim.bodies[i];
        const x = a[i * 3] + (b[i * 3] - a[i * 3]) * mix;
        const y = a[i * 3 + 1] + (b[i * 3 + 1] - a[i * 3 + 1]) * mix;
        const rot = a[i * 3 + 2] + (b[i * 3 + 2] - a[i * 3 + 2]) * mix;
        return (
          <div
            key={j}
            style={{
              position: "absolute",
              left: x - body.r,
              top: y - body.r,
              width: body.r * 2,
              height: body.r * 2,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `rotate(${rot}rad)`,
            }}
          >
            {item}
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

