const ELEMENT_PROP_KEYS = new Set(["count","gravity","seed","accentColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  count: 30,
  gravity: 1,
  seed: 7,
  accentColor: "#E5322D",
  backgroundColor: "#111111",
  speed: 1,
};

type GravityPileElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GravityPileBase>;

const GravityPileInner = forwardRef<
  HTMLDivElement,
  GravityPileElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GravityPile>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GravityPileBase
          {...(componentProps as unknown as ComponentProps<typeof GravityPileBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GravityPile = Interactive.withSchema({
  Component: GravityPileInner,
