    block: graphite ? "#2B2B30" : "#232326",
    light: graphite ? "rgba(255,255,255,0.07)" : "rgba(255,255,255,0.06)",
    shadow: "rgba(0,0,0,0.6)",
    dot: accent,
  };
}

