const SHEAR = Easing.bezier(0.22, 1, 0.36, 1);
const OPEN = Easing.bezier(0.7, 0, 0.3, 1);
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);

const STAGES = {
