  447, 240, 745, 521, 414, 450, 425, 368, 302, 272, 508, 412, 609, 450, 418,
  385, 320, 252, 320, 531,
];
const TRACK = -0.008;

function widthEm(text: string, italic: boolean) {
  const table = italic ? SERIF_IT_ADV : SERIF_ADV;
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += (c >= 32 && c < 127 ? table[c - 32] : 420) / 1000 + TRACK;
  }
  return Math.max(w, 0.5);
}

// "beam" palette from gradients.sh (#f4f7ff, #8fb4ff, accent, #1a1660) laid out as a horizontal
// band of light centred on the hairline, so the slit reads as light pouring out. Drifts gently.
function beamGround(accent: string, k: number) {
  const x = 44 + 12 * k;
  const mix = (p: number) => `color-mix(in oklab, ${accent} ${p}%, #1a1660)`;
  const o = 2 * k;
  return [
    `radial-gradient(70% 30% at ${x}% 50%, rgba(143,180,255,0.24) 0%, rgba(143,180,255,0) 100%)`,
    `linear-gradient(180deg, #02030a 0%, #070726 ${10 - o}%, #1a1660 ${22 - o}%, ${mix(45)} ${33 - o}%, ${mix(80)} ${42 - o / 2}%, ${accent} 50%, ${mix(80)} ${58 + o / 2}%, ${mix(45)} ${67 + o}%, #1a1660 ${78 + o}%, #070726 ${90 + o}%, #02030a 100%)`,
  ].join(", ");
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Title({
  content,
  color,
  max,
  italic = false,
}: {
  content: React.ReactNode;
  color: string;
  max: number;
  italic?: boolean;
}) {
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  if (typeof content !== "string")
    return <AbsoluteFill>{content}</AbsoluteFill>;
  const size = Math.min(max * u, (0.8 * W) / widthEm(content, italic));
  return (
    <AbsoluteFill
      style={{
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily: serif,
          fontStyle: italic ? "italic" : "normal",
          fontWeight: 400,
          fontSize: size,
          letterSpacing: `${TRACK}em`,
          lineHeight: 1,
          whiteSpace: "nowrap",
          color,
          paddingBottom: 0.04 * size,
          paddingRight: italic ? 0.04 * size : 0,
        }}
      >
        {content}
      </div>
    </AbsoluteFill>
  );
}

export function HairlineOpen({
  from = "Write the story",
  to = "Ship the film",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: HairlineOpenProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const stage = STAGES[theme];
  const line = Math.max(1.5, 2.5 * u);

  const draw = DRAW(interpolate(t, [DRAW_AT, DRAW_END], [0, 1], CLAMP));
  const head = draw * W;
  const shear =
    6 * u * SHEAR(interpolate(t, [DRAW_END - 4, OPEN_AT + 2], [0, 1], CLAMP));
  const open = OPEN(interpolate(t, [OPEN_AT, OPEN_END], [0, 1], CLAMP));
  const gap = open * H * 1.24;
  const slide = 0.06 * W * open;
  const settle = SETTLE(
    interpolate(t, [OPEN_AT, OPEN_END + 16], [0, 1], CLAMP),
  );
  const bScale = 1.07 - 0.07 * settle;
  const panelsGone = gap / 2 >= H / 2 + 40 * u;
  const lineOn = draw > 0 && gap < line;

  const half = (top: boolean) => {
    const dir = top ? -1 : 1;
    const shift = top ? -(shear + slide) : shear + slide;
    const pad = 0.1 * W;
    return (
      <AbsoluteFill
        style={{
          transform: `translate(${shift}px, ${(dir * gap) / 2}px)`,
          filter:
            open > 0
              ? `drop-shadow(0 ${dir * 10 * u}px ${24 * u}px rgba(0,0,0,${0.28 * Math.min(1, open * 4)}))`
              : undefined,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: -pad,
            width: W + 2 * pad,
            top: top ? 0 : H / 2,
            height: H / 2,
            overflow: "hidden",
            background: stage.bg,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: pad,
              top: top ? 0 : -H / 2,
              width: W,
              height: H,
            }}
          >
            <AbsoluteFill
              style={{
                background: `radial-gradient(ellipse 80% 90% at 24% 0%, ${stage.light}, transparent 70%)`,
              }}
            />
            <Title content={from} color={stage.fg} max={176} />
          </div>
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              height: Math.max(1, u),
              [top ? "bottom" : "top"]: 0,
              background: stage.edge,
              opacity: Math.min(1, open * 6),
            }}
          />
        </div>
      </AbsoluteFill>
    );
  };

  return (
    <AbsoluteFill style={{ background: "#02030a", overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: beamGround(
            accent,
            interpolate(t, [OPEN_AT, OPEN_END + 40], [0, 1], CLAMP),
          ),
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${bScale})`,
          opacity: interpolate(gap, [0.05 * H, 0.32 * H], [0, 1], CLAMP),
        }}
      >
        <Title content={to} color="#F7F7F5" max={196} italic />
      </AbsoluteFill>
      {panelsGone ? null : (
        <>
          {half(true)}
          {half(false)}
        </>
      )}
      {lineOn ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: H / 2 - line / 2,
            width: head,
            height: line,
            background: stage.filament(accent),
          }}
        />
      ) : null}
      <Grain opacity={theme === "light" ? 0.04 : 0.055} />
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/GolosText";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const golos = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface HalfBuiltPart {
  text: string;
  when?: string;
}

interface HalfBuiltProps {
  parts?: HalfBuiltPart[];
  progress?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#1D2B53", ink: "#FFFFFF", accent: "#FFB38A", hollow: 0.62 },
  light: { bg: "#FFF4EC", ink: "#1D2B53", accent: "#D9623B", hollow: 0.55 },
} as const;

const DEFAULT_PARTS: HalfBuiltPart[] = [
  { text: "It cuts," },
  { text: "captions,", when: "Spring" },
  { text: "narrates", when: "Summer" },
  { text: "and" },
  { text: "translates", when: "Later" },
  { text: "your launch film." },
];

const LH = 1.34;
const TAG_EM = 0.22;
const WORD_GAP = 3;
const TAG_GAP = 5;
const FILL_FULL = 30;
const FILL_PAUSE = 12;
const SETTLE = 10;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_FILL = Easing.bezier(0.45, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Unit {
  key: string;
  text: string;
  plan: number;
  when?: string;
}

function toUnits(parts: HalfBuiltPart[]) {
  const units: Unit[] = [];
  let plan = 0;
  parts.forEach((p, pi) => {
    if (p.when !== undefined) {
      units.push({ key: `p${pi}`, text: p.text.trim(), plan, when: p.when });
      plan += 1;
    } else {
      p.text
        .split(/\s+/)
        .filter(Boolean)
        .forEach((w, wi) => {
          units.push({ key: `p${pi}-${wi}`, text: w, plan: -1 });
        });
    }
  });
  return { units, planned: plan };
}

function HalfBuiltBase({
  parts = DEFAULT_PARTS,
  progress = 1.6,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: HalfBuiltProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const { units, planned } = toUnits(parts);
  const goal = Math.max(0, Math.min(planned, progress));
  const wordsIn = 2 + units.length * WORD_GAP + 12;
  const tagsAt = Math.max(16, wordsIn - 8);
  const fillAt = tagsAt + planned * TAG_GAP + 14;
  const segments: { start: number; end: number; amount: number }[] = [];
  let cursor = fillAt;
  for (let j = 0; j < Math.ceil(goal); j++) {
    const amount = Math.min(1, goal - j);
    const dur = Math.max(16, FILL_FULL * amount);
    segments.push({ start: cursor, end: cursor + dur, amount });
    cursor += dur + FILL_PAUSE + (amount >= 1 ? SETTLE : 0);
  }
  const naturalEnd = segments.length
    ? segments[segments.length - 1].end + SETTLE
    : fillAt;
  const pace = Math.max(1, (naturalEnd + 30) / Math.max(1, durationInFrames));
  const t = frame * speed * pace;

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.08 : 0.07);
  const boxW = W - margin * 2;
  const maxH = H * (portrait ? 0.62 : 0.66);
  const sizeCap = Math.min(H * 0.2, W * (portrait ? 0.16 : 0.12));

  const probeRef = useRef<HTMLDivElement>(null);
  const [handle] = useState(() => delayRender("half-built: measuring"));
  const released = useRef(false);
  const [fontsOk, setFontsOk] = useState(false);
  const [size, setSize] = useState<number | null>(null);

  useEffect(() => {
    let live = true;
    Promise.all([
      golos.waitUntilDone(),
      document.fonts.load(`500 100px "${golos.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setFontsOk(true);
      });
    return () => {
      live = false;
    };
  }, []);

  useLayoutEffect(() => {
    if (!fontsOk) return;
    const probe = probeRef.current;
    if (!probe) return;
    let s = sizeCap;
    for (let i = 0; i < 60; i++) {
      probe.style.fontSize = `${s}px`;
      if (probe.offsetHeight <= maxH && probe.scrollWidth <= boxW + 1) break;
      s *= 0.96;
    }
    const next = Math.round(s * 10) / 10;
    setSize((prev) => (prev === next ? prev : next));
  });

  useEffect(() => {
    if (size !== null && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  }, [size, handle]);

  const fillOf = (plan: number) => {
    const seg = segments[plan];
    if (!seg) return 0;
    return (
      interpolate(t, [seg.start, seg.end], [0, 1], {
        ...CLAMP,
        easing: EASE_FILL,
      }) * seg.amount
    );
  };
  const doneOf = (plan: number) => {
    const seg = segments[plan];
    if (!seg || seg.amount < 1) return 0;
    return interpolate(t, [seg.end + 2, seg.end + 2 + SETTLE], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const rise = (start: number, dur = 12) =>
    interpolate(t, [start, start + dur], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const font: React.CSSProperties = {
    fontFamily: golos.fontFamily,
    fontWeight: 500,
    lineHeight: LH,
    letterSpacing: "-0.035em",
  };
  const stroke = `${Math.max(1, (size ?? 100) * 0.016).toFixed(2)}px`;

  const renderUnit = (u: Unit, i: number, live: boolean) => {
    const p = live ? rise(2 + i * WORD_GAP) : 1;
    const style: React.CSSProperties = {
      position: "relative",
      display: "inline-block",
      whiteSpace: "nowrap",
      marginRight: "0.24em",
      opacity: p,
      transform: `translateY(${((1 - p) * 0.28).toFixed(3)}em)`,
    };
    if (u.plan < 0) {
      return (
        <span key={u.key} style={{ ...style, color: c.ink }}>
          {u.text}
        </span>
      );
    }
    const fill = live ? fillOf(u.plan) : 0;
    const done = live ? doneOf(u.plan) : 0;
    const tagP = live ? rise(tagsAt + u.plan * TAG_GAP, 14) : 1;
    return (
      <span key={u.key} style={style}>
        <span
          style={{
            color: "transparent",
            WebkitTextStroke: `${stroke} ${c.ink}`,
            opacity: c.hollow * (1 - done),
          }}
        >
          {u.text}
        </span>
        <span
          aria-hidden
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            color: done > 0 ? c.ink : hi,
            opacity: 1,
            clipPath: `inset(-20% ${((1 - fill) * 100).toFixed(2)}% -20% -2%)`,
          }}
        >
          <span style={{ color: hi, opacity: 1 - done }}>{u.text}</span>
          <span
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              color: c.ink,
              opacity: done,
            }}
          >
            {u.text}
          </span>
        </span>
        <span
          style={{
            position: "absolute",
            left: "0.02em",
            bottom: `${((LH - 0.1) / TAG_EM).toFixed(3)}em`,
            fontSize: `${TAG_EM}em`,
            lineHeight: 1,
            letterSpacing: "0em",
            color: hi,
            whiteSpace: "nowrap",
            opacity: tagP * (1 - done),
            transform: `translateY(${((1 - tagP) * 0.5).toFixed(3)}em)`,
          }}
        >
          {u.when}
        </span>
      </span>
    );
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        ref={probeRef}
        style={{
          ...font,
          position: "absolute",
          left: 0,
          top: 0,
          width: boxW,
          visibility: "hidden",
        }}
      >
        {units.map((u, i) => renderUnit(u, i, false))}
      </div>
      <div
        style={{
          ...font,
          position: "absolute",
          left: margin,
          top: "50%",
          width: boxW,
          fontSize: size ?? sizeCap,
          transform: "translateY(-50%)",
          opacity: size === null ? 0 : 1,
        }}
      >
        {units.map((u, i) => renderUnit(u, i, true))}
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
