const ELEMENT_PROP_KEYS = new Set(["theme","progress","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  progress: 1.6,
  speed: 1,
};

type HalfBuiltElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HalfBuiltBase>;

const HalfBuiltInner = forwardRef<
  HTMLDivElement,
  HalfBuiltElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HalfBuilt>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HalfBuiltBase
          {...(componentProps as unknown as ComponentProps<typeof HalfBuiltBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HalfBuilt = Interactive.withSchema({
