const ELEMENT_PROP_KEYS = new Set(["dotSize","angle","misregistration","paperTint","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  dotSize: 10,
  angle: 0,
  misregistration: 1.2,
  paperTint: "#f4efe4",
