"use client";

import { loadFont } from "@remotion/google-fonts/Caveat";
import { useCurrentFrame } from "remotion";
import {
  DEFAULT_STEP,
  hashRange,
  qstep,
  steppedRamp,
} from "@/lib/remocn/stop-motion";

const { fontFamily: HAND_FAMILY } = loadFont("normal", {
  subsets: ["latin"],
  weights: ["400", "500", "600", "700"],
});

const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

const easeInOutCubic = (t: number) =>
  t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;

const DEFAULT_DURATION_STEPS = 18;

export type HandCountEase = "in-out" | "out" | "linear";

const EASES: Record<HandCountEase, (t: number) => number> = {
  "in-out": easeInOutCubic,
  out: easeOutCubic,
  linear: (t: number) => t,
};

export type HandCountTiming = {
  delay?: number;
  durationSteps?: number;
  step?: number;
};

export function handCountDuration(options?: HandCountTiming): number {
  const delay = options?.delay ?? 0;
  const durationSteps = options?.durationSteps ?? DEFAULT_DURATION_STEPS;
  const step = options?.step ?? DEFAULT_STEP;
  const end = delay + durationSteps * step;
  return Math.ceil(end / step) * step;
}

export function handCountValue(
  args: HandCountTiming & {
    frame: number;
    to: number;
    from?: number;
    ease?: HandCountEase;
  },
): number {
  const from = args.from ?? 0;
  const delay = args.delay ?? 0;
  const durationSteps = args.durationSteps ?? DEFAULT_DURATION_STEPS;
  const step = args.step ?? DEFAULT_STEP;
  const progress = steppedRamp(
    args.frame,
    delay,
    delay + durationSteps * step,
    {
      ease: EASES[args.ease ?? "in-out"],
      step,
    },
  );
  return from + (args.to - from) * progress;
}

export function handCountText(
  value: number,
  options?: { decimals?: number; prefix?: string; suffix?: string },
): string {
  return `${options?.prefix ?? ""}${value.toFixed(options?.decimals ?? 0)}${options?.suffix ?? ""}`;
}

export function handCountPose(
  frame: number,
  options?: HandCountTiming,
): number {
  const step = options?.step ?? DEFAULT_STEP;
  const settled = handCountDuration(options);
  return Math.min(qstep(Math.max(0, frame), step), qstep(settled, step));
}

export function handCountJitter(
  args: HandCountTiming & { frame: number; index: number; seed?: string },
): { rot: number; dy: number } {
  const seed = args.seed ?? "count";
  const pose = handCountPose(args.frame, args);
  return {
    rot: hashRange(`${seed}:${pose}:${args.index}:r`, -3.2, 3.2),
    dy: hashRange(`${seed}:${pose}:${args.index}:y`, -1.8, 1.8),
  };
}

export interface HandCountProps {
  to: number;
  from?: number;
  delay?: number;
  durationSteps?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  fontSize?: number;
  color?: string;
  weight?: 400 | 500 | 600 | 700;
  ease?: HandCountEase;
  align?: "left" | "center";
  fontFamily?: string;
  seed?: string;
  step?: number;
}

export function HandCount({
  to,
  from = 0,
  delay = 0,
  durationSteps = DEFAULT_DURATION_STEPS,
  decimals = 0,
  prefix = "",
  suffix = "",
  fontSize = 96,
  color = "#26242c",
  weight = 700,
  ease = "in-out",
  align = "center",
  fontFamily = HAND_FAMILY,
  seed = "count",
  step = DEFAULT_STEP,
}: HandCountProps) {
  const frame = useCurrentFrame();
  const value = handCountValue({
    frame,
    to,
    from,
    delay,
    durationSteps,
    step,
    ease,
  });
  const chars = Array.from(handCountText(value, { decimals, prefix, suffix }));

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: align === "center" ? "center" : "flex-start",
        background: "transparent",
      }}
    >
      <span
        style={{
          display: "inline-block",
          fontFamily: `${fontFamily}, cursive`,
          fontWeight: weight,
          fontSize,
          lineHeight: 1.15,
          color,
          whiteSpace: "pre",
          textAlign: align,
        }}
      >
        {chars.map((char, i) => {
          const { rot, dy } = handCountJitter({
            frame,
            index: i,
            seed,
            delay,
            durationSteps,
            step,
          });
          return (
            <span
              key={`${i}:${char}`}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                translate: `0 ${dy}px`,
                rotate: `${rot}deg`,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

"use client";

import { loadFont } from "@remotion/google-fonts/Caveat";
import { useCurrentFrame } from "remotion";
import { DEFAULT_STEP, hashRange, qf, qstep } from "@/lib/remocn/stop-motion";

const { fontFamily: HAND_FAMILY } = loadFont("normal", {
  subsets: ["latin"],
  weights: ["400", "500", "600", "700"],
});

export interface HandwriteProps {
  text: string;
  fontSize?: number;
  color?: string;
  delay?: number;
  perStep?: number;
  weight?: 400 | 500 | 600 | 700;
  align?: "left" | "center";
  fontFamily?: string;
  step?: number;
}

export function Handwrite({
  text,
  fontSize = 54,
  color = "#26242c",
  delay = 0,
  perStep = 1.6,
  weight = 600,
  align = "center",
  fontFamily = HAND_FAMILY,
  step = DEFAULT_STEP,
}: HandwriteProps) {
  const frame = useCurrentFrame();
  const steps = Math.max(0, qstep(Math.max(0, qf(frame, step) - delay), step));
  const shown = Math.floor(steps * perStep);
  const chars = Array.from(text);
  const freshFrom = shown - Math.ceil(perStep);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: align === "center" ? "center" : "flex-start",
        background: "transparent",
      }}
    >
      <span
        style={{
          display: "inline-block",
          fontFamily: `${fontFamily}, cursive`,
          fontWeight: weight,
          fontSize,
          lineHeight: 1.15,
          color,
          whiteSpace: "pre-wrap",
          textAlign: align,
        }}
      >
        {chars.map((char, i) => {
          const visible = i < shown;
          const slant = hashRange(`hw:${text}:${i}:r`, -3.2, 3.2);
          const dy = hashRange(`hw:${text}:${i}:y`, -1.8, 1.8);
          const fresh = visible && i >= freshFrom;
          return (
            <span
              key={i}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                opacity: visible ? 1 : 0,
                translate: visible ? `0 ${dy}px` : undefined,
                rotate: visible ? `${slant}deg` : undefined,
                scale: visible ? `${fresh ? 1.06 : 1}` : undefined,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

export function handwriteDuration(
  text: string,
  options?: { perStep?: number; step?: number },
): number {
  const perStep = options?.perStep ?? 1.6;
  const step = options?.step ?? DEFAULT_STEP;
  return Math.ceil(Array.from(text).length / perStep) * step + step;
}

import { loadFont as loadDisplay } from "@remotion/google-fonts/Fraunces";
import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
loadDisplay("italic", { weights: ["400"], subsets: ["latin"] });

// gradients.sh "grain" palette: a warm copper plate under the etching, and
// the copper ink of the shading pass.
const GRAIN = ["#ffd8b4", "#e0703b", "#8a2c1d", "#2b1015"] as const;

interface HatchShadeProps {
  value?: string;
  caption?: string;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const PEN = Easing.bezier(0.45, 0, 0.2, 1);

const CAP = 0.72;

const PASSES = [
  { at: 8, sweep: 30, draw: 11, angle: 45, gap: 8, ink: "fg" },
  { at: 40, sweep: 30, draw: 11, angle: -45, gap: 8, ink: "fg" },
  { at: 74, sweep: 26, draw: 10, angle: 0, gap: 6, ink: "copper" },
] as const;

const OUTLINE_AT = 100;
const OUTLINE_END = 110;
const CAPTION_AT = 112;

const THEMES = {
  dark: {
    bg: "#070505",
    fg: "#F6EEE6",
    muted: "#9A8E86",
    ink: 0.66,
    ghost: 0.05,
    grain: 0.055,
  },
  light: {
    bg: "#F5F2EC",
    fg: "#1A1210",
    muted: "#77695F",
    ink: 0.72,
    ghost: 0.045,
    grain: 0.04,
  },
} as const;

type Box = { x: number; y: number; w: number; h: number };

function hatchLines(box: Box, angleDeg: number, gap: number) {
  const a = (angleDeg * Math.PI) / 180;
  const dx = Math.cos(a);
  const dy = Math.sin(a);
  const nx = -dy;
  const ny = dx;
  const cx = box.x + box.w / 2;
  const cy = box.y + box.h / 2;
  const half = Math.hypot(box.w, box.h) / 2;
  const spread = Math.abs(nx) * box.w + Math.abs(ny) * box.h;
  const n = Math.ceil(spread / gap);
  const lines: Array<{
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    k: number;
  }> = [];
  for (let i = 0; i <= n; i++) {
    const off = -spread / 2 + i * gap;
    const px = cx + nx * off;
    const py = cy + ny * off;
    lines.push({
      x1: px - dx * half,
      y1: py - dy * half,
      x2: px + dx * half,
      y2: py + dy * half,
      k: n === 0 ? 0 : i / n,
    });
  }
  return lines;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function HatchShadeBase({
  value = "24",
  caption = "new components, drawn for launch week",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: HatchShadeProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const stage = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const bodyId = `b${uid}`;
  const shadeId = `s${uid}`;
  const rimId = `r${uid}`;
  const copperId = `c${uid}`;
  const isDark = theme === "dark";
  const drift = interpolate(t, [0, 160], [0, 1], CLAMP);

  const chars = Math.max(1, Array.from(value).length);
  const size = Math.min(0.68 * H, (0.8 * W) / (chars * 0.6));
  const capH = CAP * size;
  const capSize = 22 * u;
  const gapBelow = 40 * u;
  const blockH = capH + (caption ? gapBelow + capSize * 1.3 : 0);
  const top = (H - blockH) / 2;
  const baseline = top + capH;
  const cx = W / 2;
  const estW = chars * 0.66 * size;
  const box: Box = {
    x: cx - estW / 2 - 20 * u,
    y: top - 20 * u,
    w: estW + 40 * u,
    h: capH + 40 * u,
  };
  const shift = 0.034 * size;
  const hair = Math.max(1.5, 1.7 * u);

  const textProps = {
    x: cx,
    y: baseline,
    textAnchor: "middle" as const,
    fontFamily: display,
    fontWeight: 500,
    fontSize: size,
    letterSpacing: `${-0.02 * size}px`,
  };

  const outline = interpolate(t, [OUTLINE_AT, OUTLINE_END], [0, 1], CLAMP);
  const capIn = EASE_OUT(
    interpolate(t, [CAPTION_AT, CAPTION_AT + 16], [0, 1], CLAMP),
  );
  const ghost = interpolate(
    t,
    [0, 10, OUTLINE_AT, OUTLINE_END],
    [0, 1, 1, 0],
    CLAMP,
  );

  const passes = PASSES.map((pass, pi) => {
    const lines = hatchLines(box, pass.angle, pass.gap * u);
    const color = pass.ink === "copper" ? `url(#${copperId})` : stage.fg;
    const opacity = pass.ink === "copper" ? 1 : stage.ink;
    const els = lines.map((l, i) => {
      const order = pi === 1 ? l.k : l.k;
      const start = pass.at + order * pass.sweep;
      const p = PEN(interpolate(t, [start, start + pass.draw], [0, 1], CLAMP));
      if (p <= 0) return null;
      const taper = pi === 1 ? interpolate(l.k, [0.18, 0.8], [0, 1], CLAMP) : 1;
      if (taper * hair * 1.35 < 0.45) return null;
      return (
        <line
          key={i}
          strokeWidth={pi === 1 ? taper * hair * 1.35 : undefined}
          x1={l.x1}
          y1={l.y1}
          x2={l.x2}
          y2={l.y2}
          pathLength={1}
          strokeDasharray={p >= 1 ? undefined : "1 1"}
          strokeDashoffset={p >= 1 ? undefined : 1 - p}
        />
      );
    });
    return (
      <g
        key={pi}
        mask={`url(#${pi === 2 ? shadeId : bodyId})`}
        stroke={color}
        strokeWidth={hair}
        strokeLinecap="butt"
        opacity={opacity}
      >
        {els}
      </g>
    );
  });

  return (
    <AbsoluteFill style={{ background: stage.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: isDark
            ? [
                `radial-gradient(60% 45% at ${18 + drift * 4}% ${20 + drift * 3}%, ${GRAIN[2]}47 0%, transparent 62%)`,
                `linear-gradient(150deg, ${GRAIN[3]}e6 0%, ${GRAIN[3]}66 38%, transparent 70%)`,
                `radial-gradient(50% 40% at 88% 96%, ${GRAIN[2]}2e 0%, transparent 70%)`,
              ].join(", ")
            : [
                `radial-gradient(60% 45% at ${18 + drift * 4}% ${20 + drift * 3}%, ${GRAIN[0]}8c 0%, transparent 60%)`,
                `linear-gradient(150deg, ${GRAIN[0]}66 0%, transparent 60%)`,
              ].join(", "),
        }}
      />
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={copperId}
            gradientUnits="userSpaceOnUse"
            x1={box.x}
            y1={box.y}
            x2={box.x + box.w}
            y2={box.y + box.h}
          >
            <stop offset={0} stopColor={isDark ? GRAIN[0] : GRAIN[1]} />
            <stop offset={0.45} stopColor={isDark ? GRAIN[1] : GRAIN[2]} />
            <stop offset={1} stopColor={isDark ? GRAIN[2] : GRAIN[3]} />
          </linearGradient>
          <mask
            id={bodyId}
            maskUnits="userSpaceOnUse"
            x={0}
            y={0}
            width={W}
            height={H}
          >
            <text {...textProps} fill="#fff">
              {value}
            </text>
          </mask>
          <mask
            id={shadeId}
            maskUnits="userSpaceOnUse"
            x={0}
            y={0}
            width={W}
            height={H}
          >
            <text {...textProps} fill="#fff">
              {value}
            </text>
            <text
              {...textProps}
              x={cx - shift}
              y={baseline - shift}
              fill="#000"
            >
              {value}
            </text>
          </mask>
          <filter
            id={rimId}
            x={0}
            y={0}
            width={W}
            height={H}
            filterUnits="userSpaceOnUse"
          >
            <feMorphology
              in="SourceAlpha"
              operator="erode"
              radius={hair * 0.9}
              result="inner"
            />
            <feComposite
              in="SourceAlpha"
              in2="inner"
              operator="out"
              result="rim"
            />
            <feFlood floodColor={stage.fg} />
            <feComposite in2="rim" operator="in" />
          </filter>
        </defs>
        <text {...textProps} fill={accent} opacity={ghost * stage.ghost}>
          {value}
        </text>
        {passes}
        <text
          {...textProps}
          fill="#000"
          filter={`url(#${rimId})`}
          opacity={outline}
        >
          {value}
        </text>
      </svg>
      {caption ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: baseline + gapBelow + (1 - capIn) * 10 * u,
            textAlign: "center",
            fontFamily: display,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: capSize * 1.2,
            letterSpacing: "-0.005em",
            lineHeight: 1.3,
            color: stage.muted,
            opacity: capIn,
          }}
        >
          {caption}
        </div>
      ) : null}
      <Grain opacity={stage.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  value: {
    type: "text-content",
    default: "24",
    description: "Value",
  },
  caption: {
    type: "text-content",
    default: "new components, drawn for launch week",
    description: "Caption",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","caption","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "24",
  caption: "new components, drawn for launch week",
  speed: 1,
};

type HatchShadeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HatchShadeBase>;

const HatchShadeInner = forwardRef<
  HTMLDivElement,
  HatchShadeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HatchShade>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HatchShadeBase
          {...(componentProps as unknown as ComponentProps<typeof HatchShadeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HatchShade = Interactive.withSchema({
  Component: HatchShadeInner,
  componentName: "<HatchShade>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import {
  type CSSProperties,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const geist = loadFont("normal", {
  weights: ["300"],
  subsets: ["latin"],
});

export interface HeadlineToLineProps {
  words?: string[];
  accentIndex?: number;
  continuation?: string;
  accent?: string;
  ink?: string;
  background?: string;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
}

const THEMES = {
  dark: {
    ink: "#eef2ff",
    accent: "#8fb4ff",
    caret: "#b9cdff",
    ground: "earthshine" as GshPresetId,
    groundOffset: 4,
    scrim: "2,4,10",
    scrimAlpha: 0.5,
  },
  light: {
    ink: "#14161c",
    accent: "#3B5BFD",
    caret: "#3B5BFD",
    ground: "paper-crease" as GshPresetId,
    groundOffset: 2,
    scrim: "238,236,232",
    scrimAlpha: 0.55,
  },
} as const;

const FONT_PX = 200;
const TRACK_BIG = -0.045;
const TRACK_SMALL = -0.02;
const POP_SCALE = 0.12;

const BEAT = {
  wordStep: 6,
  enter: 12,
  pop: 24,
  shrink: 48,
  shrinkLen: 18,
  wordLag: 1,
  type: 66,
  charsPerFrame: 1,
  rise: 42,
  riseLen: 42,
};

const ENTER = Easing.bezier(0.22, 1, 0.36, 1);
const LIGHT_IN = Easing.bezier(0.32, 0.72, 0, 1);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Measure = (s: string, track: number) => number;

function buildMeasure(_version: number): Measure {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string, track: number) => {
    const key = `${track}|${s}`;
    if (cache[key] === undefined) {
      if (!ctx) return s.length * 0.55;
      ctx.font = `300 ${FONT_PX}px "${geist.fontFamily}"`;
      cache[key] =
        ctx.measureText(s).width / FONT_PX + track * Array.from(s).length;
    }
    return cache[key];
  };
}

function useMeasure() {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("headline-to-line: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      geist.waitUntilDone(),
      document.fonts.load(`300 100px "${geist.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle]);
  return useMemo(() => buildMeasure(version), [version]);
}

interface Slot {
  x: number;
  y: number;
  line: number;
}

interface Line {
  start: number;
  end: number;
  width: number;
}

function wrapWords(
  words: string[],
  room: number,
  w: (s: string) => number,
): string[][] {
  const lines: string[][] = [];
  let cur: string[] = [];
  for (const word of words) {
    if (cur.length > 0 && w([...cur, word].join(" ")) > room) {
      lines.push(cur);
      cur = [];
    }
    cur.push(word);
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

export function HeadlineToLine({
  words = ["Your", "launch", "video"],
  accentIndex = 1,
  continuation = ", built from blocks you own",
  accent,
  ink,
  background,
  theme = "dark",
  ground,
  groundParams,
}: HeadlineToLineProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, fps, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? c.ground;
  const bg = background ?? gshParams(preset, groundParams).background;
  const m = useMeasure();
  const t = frame;

  const rise = interpolate(t, [BEAT.rise, BEAT.rise + BEAT.riseLen], [0, 1], {
    ...CLAMP,
    easing: LIGHT_IN,
  });
  const portrait = H > W * 1.1;
  const push = interpolate(frame, [0, durationInFrames], [1, 1.03], CLAMP);
  const groundShift = (1 - rise) * (portrait ? 0.16 : 0.26);
  const scrimA = c.scrimAlpha * (1 - 0.45 * rise);

  let content: React.ReactNode = <div />;
  if (m && words.length > 0) {
    const head = words.join(" ");
    const full = head + continuation;
    const marginX = W * (portrait ? 0.08 : 0.07);
    const room = W - marginX * 2;
    const cx = W / 2;
    const cy = H * (portrait ? 0.46 : 0.47);

    const wb = (s: string) => m(s, TRACK_BIG);
    const ws = (s: string) => m(s, TRACK_SMALL);
    const longest = Math.max(...words.map((w) => wb(w)));
    const oneLine = (room * 0.92) / wb(head);
    const minOne = portrait ? W * 0.2 : H * 0.15;
    const cap = portrait ? W * 0.27 : H * 0.28;
    const B =
      oneLine >= minOne
        ? Math.min(cap, oneLine)
        : Math.min(cap, room / longest);
    const bigLines =
      oneLine >= minOne ? [words] : wrapWords(words, room / B, wb);
    const bigLH = B * 1.02;
    const multi = bigLines.length > 1;
    const bigSlots: Slot[] = [];
    bigLines.forEach((line, li) => {
      const lw = wb(line.join(" ")) * B;
      let x = cx - lw / 2;
      const y = cy + (li - (bigLines.length - 1) / 2) * bigLH;
      line.forEach((word, wi) => {
        const ww = wb(word) * B;
        bigSlots.push({ x: x + ww / 2, y, line: li });
        x += ww + (wi < line.length - 1 ? wb(" ") * B : 0);
      });
    });

    const s = Math.max(H * 0.026, portrait ? W * 0.068 : H * 0.068);
    const tokens = full.split(" ");
    const lines: Line[] = [];
    let pos = 0;
    let cur = "";
    let curStart = 0;
    for (const tok of tokens) {
      const next = cur.length > 0 ? `${cur} ${tok}` : tok;
      if (cur.length > 0 && ws(next) * s > room) {
        lines.push({
          start: curStart,
          end: curStart + cur.length,
          width: ws(cur) * s,
        });
        curStart = pos;
        cur = tok;
      } else {
        cur = next;
      }
      pos += tok.length + 1;
    }
    lines.push({
      start: curStart,
      end: curStart + cur.length,
      width: ws(cur) * s,
    });
    const smallLH = s * 1.3;
    const lineX = (i: number) => cx - lines[i].width / 2;
    const lineY = (i: number) => cy + (i - (lines.length - 1) / 2) * smallLH;
    const lineOf = (ch: number) => {
      for (let i = 0; i < lines.length; i++) {
        if (ch <= lines[i].end) return i;
      }
      return lines.length - 1;
    };
    const charX = (ch: number) => {
      const li = lineOf(ch);
      return lineX(li) + ws(full.slice(lines[li].start, ch)) * s;
    };

    const smallSlots: Slot[] = [];
    let at = 0;
    for (const word of words) {
      const li = lineOf(at);
      const x0 = charX(at);
      smallSlots.push({ x: x0 + (ws(word) * s) / 2, y: lineY(li), line: li });
      at += word.length + 1;
    }

    const k1 = s / B;
    const centroid = (sl: Slot[]): Slot => ({
      line: 0,
      x: sl.reduce((a, q) => a + q.x, 0) / sl.length,
      y: sl.reduce((a, q) => a + q.y, 0) / sl.length,
    });
    const bigC = centroid(bigSlots);
    const smallC = centroid(smallSlots);
    const validAccent = accentIndex >= 0 && accentIndex < words.length;
    const accentW = validAccent ? wb(words[accentIndex]) * B : 0;
    const shrinkP = (i: number, tt: number) => {
      const at0 = BEAT.shrink + i * (multi ? BEAT.wordLag * 3 : BEAT.wordLag);
      return interpolate(tt, [at0, at0 + BEAT.shrinkLen], [0, 1], {
        ...CLAMP,
        easing: CAMERA,
      });
    };
    const popSpring = spring({
      frame: t - BEAT.pop,
      fps,
      config: { mass: 0.5, damping: 12, stiffness: 200 },
    });
    const popNow = validAccent ? popSpring * (1 - shrinkP(accentIndex, t)) : 0;
    const popShift = (i: number) => {
      if (!validAccent || i === accentIndex) return 0;
      if (bigSlots[i].line !== bigSlots[accentIndex].line) return 0;
      const extra = POP_SCALE * popNow * accentW * 0.5 + B * 0.03 * popNow;
      return i < accentIndex ? -extra : extra;
    };
    const wordNodes = words.map((word, i) => {
      const enterAt = i * BEAT.wordStep - 4;
      const e = interpolate(t, [enterAt, enterAt + BEAT.enter], [0, 1], {
        ...CLAMP,
        easing: ENTER,
      });
      const p = shrinkP(i, t);
      const pPrev = shrinkP(i, t - 1);
      const k = Math.exp(Math.log(k1) * p);
      const relX =
        (bigSlots[i].x - bigC.x) * (1 - p) +
        ((smallSlots[i].x - smallC.x) / k1) * p;
      const relY =
        (bigSlots[i].y - bigC.y) * (1 - p) +
        ((smallSlots[i].y - smallC.y) / k1) * p;
      const x = multi
        ? bigSlots[i].x + (smallSlots[i].x - bigSlots[i].x) * p
        : bigC.x + (smallC.x - bigC.x) * p + (relX + popShift(i)) * k;
      const y = multi
        ? bigSlots[i].y + (smallSlots[i].y - bigSlots[i].y) * p
        : bigC.y + (smallC.y - bigC.y) * p + relY * k;
      const speed = Math.abs(p - pPrev);
      const blurScreen = Math.min(6, speed * 36) + (1 - e) * 6;

      const isAccent = i === accentIndex;
      const popAmt = isAccent ? popNow : 0;
      const lifted = -0.14 * popAmt;
      const popScale = 1 + POP_SCALE * popAmt;
      const tint = isAccent
        ? interpolate(t - BEAT.pop, [0, 6], [0, 1], {
            ...CLAMP,
            easing: LIGHT_IN,
          })
        : 0;
      const color =
        tint > 0
          ? `color-mix(in oklab, ${hi} ${(tint * 100).toFixed(1)}%, ${inkC})`
          : inkC;

      const style: CSSProperties = {
        position: "absolute",
        left: 0,
        top: 0,
        fontSize: B,
        lineHeight: 1,
        whiteSpace: "pre",
        fontFamily: geist.fontFamily,
        fontWeight: 300,
        letterSpacing: `${TRACK_BIG + (TRACK_SMALL - TRACK_BIG) * p}em`,
        color,
        transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) translate(-50%, -50%) scale(${k.toFixed(5)})`,
        clipPath: "inset(-80% -30% -0.26em -30%)",
      };
      return (
        <div key={`w${i}`} style={style}>
          <div
            style={{
              transform: `translateY(${((1 - e) * 0.62 + lifted).toFixed(4)}em) scale(${popScale.toFixed(4)})`,
              transformOrigin: "50% 80%",
              opacity: e,
              filter:
                blurScreen > 0.05
                  ? `blur(${(blurScreen / k).toFixed(2)}px)`
                  : undefined,
            }}
          >
            {word}
          </div>
        </div>
      );
    });

    const landed =
      BEAT.shrink +
      BEAT.shrinkLen +
      (words.length - 1) * BEAT.wordLag * (multi ? 3 : 1);
    const typeAt = Math.max(BEAT.type, landed);
    const typed = Math.max(
      0,
      Math.min(
        continuation.length,
        Math.floor((t - typeAt) * BEAT.charsPerFrame),
      ),
    );
    const typeEnd =
      typeAt + Math.ceil(continuation.length / BEAT.charsPerFrame);
    const headLen = head.length;
    const caretCh = headLen + typed;
    const textNodes = lines.map((ln, li) => {
      const from = Math.max(ln.start, headLen);
      const to = Math.min(ln.end, caretCh);
      if (to <= from) return null;
      return (
        <div
          key={`l${li}`}
          style={{
            position: "absolute",
            left: charX(from),
            top: lineY(li) - s / 2,
            fontSize: s,
            lineHeight: 1,
            whiteSpace: "pre",
            fontFamily: geist.fontFamily,
            fontWeight: 300,
            letterSpacing: `${TRACK_SMALL}em`,
            color: inkC,
          }}
        >
          {full.slice(from, to)}
        </div>
      );
    });

    const caretIn = interpolate(t, [landed - 6, landed], [0, 1], CLAMP);
    const blinkOn =
      t < typeEnd + 6 || Math.floor((t - typeEnd - 6) / 15) % 2 === 1;
    const caretLine = lineOf(caretCh);
    const caretX = charX(caretCh) + s * 0.06;
    const caret = (
      <div
        style={{
          position: "absolute",
          left: caretX,
          top: lineY(caretLine) - s * 0.56,
          width: Math.max(2, s * 0.05),
          height: s * 1.12,
          borderRadius: s,
          background: c.caret,
          opacity: caretIn * (blinkOn ? 1 : 0),
        }}
      />
    );

    content = (
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${push.toFixed(5)})`,
        }}
      >
        {wordNodes}
        {textNodes}
        {caret}
      </div>
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `translateY(${(groundShift * 100).toFixed(3)}%) scale(${(1.08 - 0.04 * rise).toFixed(4)})`,
        }}
      >
        <GshGround
          preset={preset}
          params={groundParams}
          timeOffset={c.groundOffset}
          timeScale={0.25}
        />
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `radial-gradient(70% 46% at 50% ${portrait ? 46 : 47}%, rgba(${c.scrim},${scrimA.toFixed(3)}) 0%, rgba(${c.scrim},0) 100%)`,
        }}
      />
      {content}
    </AbsoluteFill>
  );
}

