const ELEMENT_PROP_KEYS = new Set(["theme","accent","label","value","rings","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  label: "of renders served from cache",
  value: 86,
  rings: 7,
  speed: 1,
};

type HexFillElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HexFillBase>;

const HexFillInner = forwardRef<
  HTMLDivElement,
  HexFillElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HexFill>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HexFillBase
          {...(componentProps as unknown as ComponentProps<typeof HexFillBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HexFill = Interactive.withSchema({
  Component: HexFillInner,
  componentName: "<HexFill>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

