  text: {
    type: "text-content",
    default: "Small teams make their launch film in code and post it by Friday.",
    description: "Text",
  },
  word: {
    type: "text-content",
    default: "ship",
    description: "Word",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
