} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","text","word","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  text: "Small teams make their launch film in code and post it by Friday.",
  word: "ship",
  speed: 1,
};

type HiddenWordElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HiddenWordBase>;

const HiddenWordInner = forwardRef<
  HTMLDivElement,
  HiddenWordElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HiddenWord>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HiddenWordBase
          {...(componentProps as unknown as ComponentProps<typeof HiddenWordBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HiddenWord = Interactive.withSchema({
  Component: HiddenWordInner,
  componentName: "<HiddenWord>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

