export type IconScatterProps = {
  /** How many icons populate the field. Default 15. */
  count?: number;
  /** Icon stroke color. Default near-white ink. */
  color?: string;
  /** The fill that hides the swap at the field's peak. Default warm obsidian. */
  coverColor?: string;
  /** Peak opacity of the cover fill (0–1). Lower = more of the swap shows. */
  coverOpacity?: number;
  /** Stroke width of the icons, in their 24px viewBox units. Default 2. */
  strokeWidth?: number;
  /** How far icons fly on scatter, in px. Default 260. */
  flyDistance?: number;
  /** Seed so two scatters in one video can differ. Default "icon-scatter". */
  seed?: string;
};

type Placed = {
  path: string;
  xPct: number;
  yPct: number;
  size: number;
  spin: number; // degrees swept over the whole transition
  dir: number; // outward scatter angle offset
  strokeOpacity: number;
  pStart: number; // when this icon begins drawing (p-space)
  pOut: number; // when this icon begins flying out (p-space)
};

// Jittered grid so the field reads as scattered but never clumps or overlaps.
function placeIcons(count: number, seed: string): Placed[] {
  const cols = Math.ceil(Math.sqrt((count * 16) / 9));
  const rows = Math.ceil(count / cols);
  const out: Placed[] = [];
  for (let i = 0; i < count; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const cellW = 100 / cols;
    const cellH = 100 / rows;
    const jx = (random(`${seed}-jx-${i}`) - 0.5) * cellW * 0.7;
    const jy = (random(`${seed}-jy-${i}`) - 0.5) * cellH * 0.7;
    out.push({
      path: ICON_PATHS[
        Math.floor(random(`${seed}-p-${i}`) * ICON_PATHS.length)
      ],
      xPct: cellW * (col + 0.5) + jx,
      yPct: cellH * (row + 0.5) + jy,
      size: 34 + random(`${seed}-s-${i}`) * 40,
      spin: (random(`${seed}-r-${i}`) - 0.5) * 320,
      dir: (random(`${seed}-d-${i}`) - 0.5) * 1.2,
      strokeOpacity: 0.5 + random(`${seed}-o-${i}`) * 0.5,
      pStart: random(`${seed}-a-${i}`) * 0.16,
      pOut: 0.52 + random(`${seed}-b-${i}`) * 0.16,
    });
  }
  return out;
}

const IconField: React.FC<{
  p: number;
  placed: Placed[];
  color: string;
  strokeWidth: number;
  flyDistance: number;
}> = ({ p, placed, color, strokeWidth, flyDistance }) => (
  <AbsoluteFill style={{ pointerEvents: "none" }}>
    {placed.map((icon, i) => {
      // Draw on over ~0.34 of p from the icon's start, then fly out.
      const draw = interpolate(p, [icon.pStart, icon.pStart + 0.34], [0, 1], {
        ...clampOpts,
        easing: Easing.out(Easing.cubic),
      });
      const scaleIn = interpolate(
        p,
        [icon.pStart, icon.pStart + 0.3],
        [0.4, 1],
        {
          ...clampOpts,
          easing: Easing.out(Easing.back(1.6)),
        },
      );
      const outP = interpolate(p, [icon.pOut, 1], [0, 1], {
        ...clampOpts,
        easing: Easing.in(Easing.cubic),
      });

      // Scatter outward from the frame center, along the icon's own radial.
      const cx = icon.xPct - 50;
      const cy = icon.yPct - 50;
      const angle = Math.atan2(cy, cx) + icon.dir;
      const fly = outP * flyDistance;
      const tx = Math.cos(angle) * fly;
      const ty = Math.sin(angle) * fly;

      const spin =
        icon.spin * interpolate(p, [icon.pStart, 1], [0, 1], clampOpts);
      const opacity = Math.min(draw, 1 - outP) * icon.strokeOpacity;
      if (opacity <= 0.001) return null;

      return (
        <svg
          key={i}
          width={icon.size}
          height={icon.size}
          viewBox="0 0 24 24"
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{
            position: "absolute",
            left: `${icon.xPct}%`,
            top: `${icon.yPct}%`,
            opacity,
            overflow: "visible",
            transform: `translate(-50%, -50%) translate(${tx}px, ${ty}px) scale(${
              scaleIn * (1 - outP * 0.3)
            }) rotate(${spin}deg)`,
          }}
        >
          <path
            d={icon.path}
            pathLength={1}
            strokeDasharray={1}
            strokeDashoffset={1 - draw}
          />
        </svg>
      );
    })}
  </AbsoluteFill>
);

const IconScatterPresentation: React.FC<
  TransitionPresentationComponentProps<IconScatterProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    count = 15,
    color = "#fafafa",
    coverColor = "#0a0a0a",
    coverOpacity = 0.92,
    strokeWidth = 2,
    flyDistance = 260,
    seed = "icon-scatter",
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  if (!entering) {
    // The outgoing scene sinks back and blurs as the field rises over it.
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, [0.28, 0.5], [1, 0], clampOpts),
      scale: `${interpolate(p, [0, 0.5], [1, 0.94], {
        ...clampOpts,
        easing: Easing.in(Easing.cubic),
      })})`,
      filter: `blur(${interpolate(p, [0.1, 0.45], [0, 10], clampOpts)}px)`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  const placed = placeIcons(count, seed);

  // The incoming scene resolves once the field starts clearing.
  const childStyle: React.CSSProperties = {
    opacity: interpolate(p, [0.5, 0.68], [0, 1], clampOpts),
    scale: `${interpolate(p, [0.5, 1], [1.06, 1], {
      ...clampOpts,
      easing: Easing.out(Easing.cubic),
    })})`,
    filter: `blur(${interpolate(p, [0.5, 0.72], [8, 0], clampOpts)}px)`,
  };

  // The cover fill hides the swap while the field is densest.
  const cover = interpolate(p, [0, 0.3, 0.62, 0.9], [0, 1, 1, 0], clampOpts);

  return (
    <AbsoluteFill>
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
      <AbsoluteFill
        style={{
          background: coverColor,
          opacity: cover * coverOpacity,
          pointerEvents: "none",
        }}
      />
      <IconField
        p={p}
        placed={placed}
        color={color}
        strokeWidth={strokeWidth}
        flyDistance={flyDistance}
      />
    </AbsoluteFill>
  );
};

export function iconScatter(
  props: IconScatterProps = {},
): TransitionPresentation<IconScatterProps> {
  return {
    component: IconScatterPresentation,
    props,
  };
}

import { Easing, Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { evolvePath } from "@remotion/paths";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface IconAnimationProps {
  animation?: "draw" | "action" | "both";
  loop?: boolean;
  speed?: number;
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}

interface IconTimings {
  drawDurationInFrames?: number;
  actionDelayInFrames?: number;
  actionDurationInFrames?: number;
  loop?: boolean;
}

interface IconTimeline {
  drawProgress: number;
  scaleIn: number;
  actionFrame: number;
  actionProgress: number;
  cycleIndex: number;
}

function clamp01(t: number): number {
  return t < 0 ? 0 : t > 1 ? 1 : t;
}

function easeOut(t: number): number {
  return 1 - (1 - t) ** 3;
}

function iconTimeline(
  frame: number,
  fps: number,
  props: IconAnimationProps,
  timings: IconTimings,
): IconTimeline {
  const animation = props.animation ?? "both";
  const loop = props.loop ?? timings.loop ?? false;
  const drawDuration = timings.drawDurationInFrames ?? 14;
  const actionDelay = timings.actionDelayInFrames ?? 2;
  const actionDuration = timings.actionDurationInFrames ?? 20;

  const drawProgress =
    animation === "action"
      ? 1
      : easeOut(clamp01(drawDuration > 0 ? frame / drawDuration : 1));

  const scaleIn = clamp01(
    spring({
      frame,
      fps,
      config: { damping: 18, stiffness: 220, mass: 0.7 },
      durationInFrames: Math.max(1, drawDuration),
    }),
  );

  const actionStart = animation === "action" ? 0 : drawDuration + actionDelay;
  const sinceStart = frame - actionStart;

  if (animation === "draw" || sinceStart < 0) {
    return {
      drawProgress,
      scaleIn,
      actionFrame: sinceStart,
      actionProgress: 0,
      cycleIndex: 0,
    };
  }

  if (actionDuration <= 0) {
    return {
      drawProgress,
      scaleIn,
      actionFrame: sinceStart,
      actionProgress: 1,
      cycleIndex: 0,
    };
  }

  if (loop) {
    const cycleIndex = Math.floor(sinceStart / actionDuration);
    const local = sinceStart - cycleIndex * actionDuration;
    return {
      drawProgress,
      scaleIn,
      actionFrame: local,
      actionProgress: local / actionDuration,
      cycleIndex,
    };
  }

  return {
    drawProgress,
    scaleIn,
    actionFrame: sinceStart,
    actionProgress: clamp01(sinceStart / actionDuration),
    cycleIndex: 0,
  };
}

function useIconAnimation(
  props: IconAnimationProps,
  timings: IconTimings,
): IconTimeline {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const speed = props.speed ?? 1;
  return iconTimeline(frame * speed, fps, props, timings);
}

function staggeredProgress(
  progress: number,
  index: number,
  count: number,
  overlap = 0.5,
): number {
  if (count <= 1) return clamp01(progress);
  const o = clamp01(overlap);
  const width = 1 / (count - (count - 1) * o);
  const start = index * width * (1 - o);
  return clamp01((progress - start) / width);
}

function drawnPathProps(
  d: string,
  progress: number,
): { strokeDasharray: string; strokeDashoffset: number } {
  return evolvePath(clamp01(progress), d);
}

const CIRCLE_PATH =
  "M11 3 A8 8 0 0 1 19 11 A8 8 0 0 1 11 19 A8 8 0 0 1 3 11 A8 8 0 0 1 11 3";
const HANDLE_DRAW = "M16.66 16.66 21 21";
const HANDLE_STATIC = "m21 21-4.34-4.34";

const TIMINGS = {
  drawDurationInFrames: 14,
  actionDelayInFrames: 2,
  actionDurationInFrames: 40,
  loop: false,
} as const;

function SearchIconBase({
  animation = "both",
  loop,
  speed,
  size = 48,
  color = "currentColor",
  strokeWidth = 2,
  className,
}: IconAnimationProps) {
  const { drawProgress, scaleIn, actionProgress } = useIconAnimation(
    { animation, loop, speed },
    TIMINGS,
  );

  const linearDraw = 1 - (1 - drawProgress) ** (1 / 3);

  const circleProgress = interpolate(linearDraw, [0, 0.857], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });
  const handleProgress = interpolate(linearDraw, [0.571, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const circle = drawnPathProps(CIRCLE_PATH, circleProgress);
  const handle = drawnPathProps(HANDLE_DRAW, handleProgress);

  const scanEase = {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  } as const;
  const scanX = interpolate(
    actionProgress,
    [0, 0.25, 0.5, 0.75, 1],
    [0, -3, 3, -1, 0],
    scanEase,
  );
  const scanY = interpolate(
    actionProgress,
    [0, 0.25, 0.5, 0.75, 1],
    [0, -2, -1, 2, 0],
    scanEase,
  );

  const scale = 0.85 + 0.15 * scaleIn;

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{
        overflow: "visible",
        transformOrigin: "center",
        transform: `scale(${scale})`,
      }}
    >
      <g transform={`translate(${scanX} ${scanY})`}>
        <path
          d={CIRCLE_PATH}
          strokeDasharray={circle.strokeDasharray}
          strokeDashoffset={circle.strokeDashoffset}
        />
        <path
          d={HANDLE_DRAW}
          strokeDasharray={handle.strokeDasharray}
          strokeDashoffset={handle.strokeDashoffset}
        />
      </g>
    </svg>
  );
}

function SearchIconStatic({
  size = 48,
  color = "currentColor",
  strokeWidth = 2,
  className,
}: {
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <circle cx="11" cy="11" r="8" />
