import { loadFont } from "@remotion/google-fonts/HubotSans";
import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const hubot = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface InProportionPair {
  worry: string;
  answer: string;
}

interface InProportionProps {
  pairs?: InProportionPair[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_PAIRS: InProportionPair[] = [
  { worry: "It’ll look homemade.", answer: "It’ll look like your app." },
  {
    worry: "I’ll get lost in keyframes.",
    answer: "You’ll write a component.",
  },
];

const THEMES = {
  dark: { bg: "#1C1C1E", ink: "#FFFFFF", accent: "#FFE14D" },
  light: { bg: "#FFFBEA", ink: "#17150F", accent: "#9A7A00" },
} as const;

const TRACK = -0.03;
const LH = 1.02;
const WORD = 3;
const RISE = 13;
const SHRINK = 24;
const EXIT = 12;
const NOTE_DIM = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.85, 0.35);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function breakLines(ws: number[], space: number, maxEm: number) {
  const n = ws.length;
  if (n === 0) return [] as number[][];
  let count = 1;
  let x = 0;
  for (let i = 0; i < n; i++) {
    if (x > 0 && x + space + ws[i] > maxEm) {
      count++;
      x = ws[i];
    } else {
      x += (x > 0 ? space : 0) + ws[i];
    }
  }
  if (count === 1) return [ws.map((_, i) => i)];
  const lineW = (i: number, j: number) => {
    let s = 0;
    for (let k = i; k < j; k++) s += ws[k] + (k > i ? space : 0);
    return s;
  };
  const avg = lineW(0, n) / count;
  const INF = 1e12;
  const dp = Array.from({ length: count + 1 }, () =>
    new Array<number>(n + 1).fill(INF),
  );
  const back = Array.from({ length: count + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  dp[0][0] = 0;
  for (let l = 1; l <= count; l++) {
    for (let j = 1; j <= n; j++) {
      for (let i = l - 1; i < j; i++) {
        if (dp[l - 1][i] >= INF) continue;
        const lw = lineW(i, j);
        if (lw > maxEm + 1e-6 && j - i > 1) continue;
        const cost = (lw - avg) ** 2;
        if (dp[l - 1][i] + cost < dp[l][j]) {
          dp[l][j] = dp[l - 1][i] + cost;
          back[l][j] = i;
        }
      }
    }
  }
  if (dp[count][n] >= INF) return [ws.map((_, i) => i)];
  const starts: number[] = [];
  let j = n;
  for (let l = count; l > 0; l--) {
    const i = back[l][j];
    starts.unshift(i);
    j = i;
  }
  return starts.map((s, l) => {
    const e = l + 1 < starts.length ? starts[l + 1] : n;
    return Array.from({ length: e - s }, (_, k) => s + k);
  });
}

function useWidths(specs: string[]) {
  const key = specs.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("in-proportion: measuring"));
  const released = useRef(false);
  const ref = useRef(specs);
  ref.current = specs;
  useEffect(() => {
    let live = true;
    Promise.all([
      hubot.waitUntilDone(),
      document.fonts.load(`400 100px "${hubot.fontFamily}"`),
      document.fonts.load(`500 100px "${hubot.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        for (const spec of ref.current) {
          const cut = spec.indexOf("|");
          const weight = spec.slice(0, cut);
          const text = spec.slice(cut + 1);
          if (ctx) ctx.font = `${weight} 100px "${hubot.fontFamily}"`;
          w[spec] = ctx ? ctx.measureText(text).width / 100 : text.length * 0.5;
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.w : null;
}

interface Placed {
  x: number;
  line: number;
}

function layout(ws: number[], space: number, maxEm: number) {
  const lines = breakLines(ws, space, maxEm);
  const placed: Placed[] = [];
  let widest = 0;
  lines.forEach((idx, line) => {
    let x = 0;
    idx.forEach((k, m) => {
      if (m > 0) x += space;
      placed.push({ x, line });
      x += ws[k];
    });
    widest = Math.max(widest, x);
  });
  return { placed, lines: lines.length, widest };
}

function InProportionBase({
  pairs = DEFAULT_PAIRS,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: InProportionProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames: T } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = pairs.length > 0 ? pairs : DEFAULT_PAIRS;
  const worries = list.map((p) => p.worry.trim().split(/\s+/));
  const answers = list.map((p) => p.answer.trim().split(/\s+/));
  const specs = Array.from(
    new Set([
      "400| ",
      "500| ",
      ...worries.flat().map((s) => `500|${s}`),
      ...answers.flat().map((s) => `500|${s}`),
    ]),
  );
  const w = useWidths(specs);

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const adv = (s: string) =>
    (w[`500|${s}`] ?? 0) + TRACK * Array.from(s).length;
  const space = (w["500| "] ?? 0.25) + 0.04;

  const portrait = H > W * 1.1;
  const unit = Math.min(W, H);
  const mx = W * (portrait ? 0.08 : 0.06);
  const my = H * (portrait ? 0.07 : 0.085);
  const regionW = W - mx * 2;

  const worryWs = worries.map((ws) => ws.map(adv));
  const answerWs = answers.map((ws) => ws.map(adv));

  const Fs0 = Math.max(15, unit * (portrait ? 0.045 : 0.044));
  const noteGap = Fs0 * 0.7;
  const maxLines = portrait ? 5 : 3;
  const bigLays: { lay: ReturnType<typeof layout>; F: number; y0: number }[] =
    [];
  let noteBottom = my;
  worryWs.forEach((ws, i) => {
    const top = i > 0 ? noteBottom + Fs0 * 1.2 : my;
    const regionH = H - my - top;
    let F = H * (portrait ? 0.2 : 0.3);
    let lay = layout(ws, space, regionW / F);
    for (let k = 0; k < 80; k++) {
      const fits =
        lay.widest * F <= regionW + 0.5 &&
        lay.lines * LH * F <= regionH &&
        lay.lines <= maxLines;
      if (fits) break;
      F *= 0.97;
      lay = layout(ws, space, regionW / F);
    }
    const blockH = lay.lines * LH * F;
    bigLays.push({ lay, F, y0: top + (regionH - blockH) / 2 });
    noteBottom += (i > 0 ? noteGap : 0) + lay.lines * LH * Fs0;
  });
  const noteMax = W * (portrait ? 0.6 : 0.36);
  const noteWidest = Math.max(...bigLays.map((b) => b.lay.widest));
  const Fs = Math.min(Fs0, noteMax / noteWidest);
  const noteLeft = W - mx - noteWidest * Fs;
  const noteTops: number[] = [];
  let nt = my;
  bigLays.forEach((b) => {
    noteTops.push(nt);
    nt += b.lay.lines * LH * Fs + noteGap;
  });

  const answerMax = W * (portrait ? 0.84 : 0.8);
  const answerLinesMax = portrait ? 3 : 2;
  let Fa = portrait ? W * 0.13 : H * 0.17;
  let answerLays = answerWs.map((ws) => layout(ws, space, answerMax / Fa));
  for (let k = 0; k < 60; k++) {
    const most = Math.max(...answerLays.map((l) => l.lines));
    const widest = Math.max(...answerLays.map((l) => l.widest));
    if (most <= answerLinesMax && widest * Fa <= answerMax + 0.5) break;
    Fa *= 0.96;
    answerLays = answerWs.map((ws) => layout(ws, space, answerMax / Fa));
  }

  const worryStart: number[] = [];
  const shrinkAt: number[] = [];
  const answerStart: number[] = [];
  let clock = 4;
  list.forEach((_, i) => {
    worryStart.push(clock);
    clock += worries[i].length * WORD + RISE + 16;
    shrinkAt.push(clock);
    answerStart.push(clock + 10);
    clock += 10 + answers[i].length * WORD + RISE;
    clock += i < list.length - 1 ? 24 : 0;
  });
  const room = Math.max(1, T - Math.max(30, T * 0.18));
  const k = clock > room ? room / clock : 1;

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily: hubot.fontFamily,
        fontWeight: 500,
      }}
    >
      {list.map((_, i) => {
        if (t < worryStart[i] * k - 1) return null;
        const big = bigLays[i];
        return worries[i].map((word, j) => {
          const at = (worryStart[i] + j * WORD) * k;
          const e = interpolate(t, [at, at + RISE], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const s0 = shrinkAt[i] * k;
          const p = interpolate(t, [s0, s0 + SHRINK * k], [0, 1], {
            ...CLAMP,
            easing: EASE_IO,
          });
          const bp = big.lay.placed[j];
          const bx = mx + bp.x * big.F;
          const by = big.y0 + bp.line * LH * big.F;
          const sx = noteLeft + bp.x * Fs;
          const sy = noteTops[i] + bp.line * LH * Fs;
          const size = big.F + (Fs - big.F) * p;
          const x = bx + (sx - bx) * p;
          const y = by + (sy - by) * p;
          return (
            <div
              key={`w${i}-${j}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                fontSize: size,
                lineHeight: `${size * LH}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color: c.ink,
                opacity: e * (1 - (1 - NOTE_DIM) * p),
                transform: `translateY(${((1 - e) * size * 0.18).toFixed(2)}px)`,
              }}
            >
              {word}
            </div>
          );
        });
      })}
      {list.map((_, i) => {
        const last = i === list.length - 1;
        const leaveAt = last ? 1e9 : worryStart[i + 1] * k - 2;
        const leave = interpolate(t, [leaveAt, leaveAt + EXIT], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        if (t < answerStart[i] * k - 1 || leave >= 1) return null;
        const lay = answerLays[i];
        const top = H - my - lay.lines * LH * Fa;
        return answers[i].map((word, j) => {
          const at = (answerStart[i] + j * WORD) * k;
          const e = interpolate(t, [at, at + RISE], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const p = lay.placed[j];
          return (
            <div
              key={`a${i}-${j}`}
              style={{
                position: "absolute",
                left: mx + p.x * Fa,
                top: top + p.line * LH * Fa,
                fontSize: Fa,
                lineHeight: `${Fa * LH}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color: hi,
                opacity: e * (1 - leave),
                transform: `translateY(${((1 - e) * Fa * 0.22 + leave * H * 0.04).toFixed(2)}px)`,
              }}
            >
              {word}
            </div>
          );
        });
      })}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  speed: 1,
};

type InProportionElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InProportionBase>;

const InProportionInner = forwardRef<
  HTMLDivElement,
  InProportionElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InProportion>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InProportionBase
          {...(componentProps as unknown as ComponentProps<typeof InProportionBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InProportion = Interactive.withSchema({
  Component: InProportionInner,
  componentName: "<InProportion>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadHanken } from "@remotion/google-fonts/HankenGrotesk";
import { Fragment, forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const hanken = loadHanken("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

interface IndentStepsProps {
  lines?: string[];
  highlight?: string;
  lineNumbers?: boolean;
  exit?: boolean;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#5E5D64",
    guide: "rgba(244,243,240,0.2)",
    highlight: `linear-gradient(90deg, ${FLUTED[1]} 0%, #8f7cf0 30%, ${FLUTED[2]} 62%, ${FLUTED[3]} 100%)`,
    ground: [
      `radial-gradient(70% 80% at 104% 108%, color-mix(in oklab, ${FLUTED[0]} 50%, transparent) 0%, color-mix(in oklab, ${FLUTED[0]} 18%, transparent) 45%, transparent 75%)`,
      `radial-gradient(36% 44% at 100% 104%, color-mix(in oklab, ${FLUTED[2]} 16%, transparent) 0%, transparent 80%)`,
    ],
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#A8A59E",
    guide: "rgba(17,17,19,0.18)",
    highlight: `linear-gradient(90deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 34%, #c05a8a 66%, ${FLUTED[2]} 100%)`,
    ground: [
      `radial-gradient(70% 80% at 104% 108%, color-mix(in oklab, ${FLUTED[1]} 14%, transparent) 0%, color-mix(in oklab, ${FLUTED[3]} 40%, transparent) 45%, transparent 75%)`,
    ],
    grain: 0.035,
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SNAP = Easing.bezier(0.3, 1.25, 0.45, 1);
const EASE_IN = Easing.bezier(0.6, 0, 0.9, 0.5);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const HANKEN_500 = [
  260, 244, 347, 697, 560, 743, 691, 180, 240, 240, 398, 560, 240, 327, 240,
  419, 560, 560, 560, 560, 560, 560, 560, 560, 560, 560, 240, 240, 560, 560,
  560, 516, 874, 649, 604, 706, 679, 583, 563, 732, 683, 252, 553, 644, 498,
  845, 680, 748, 557, 778, 603, 568, 586, 656, 661, 964, 651, 610, 590, 272,
  454, 272, 577, 434, 299, 542, 583, 519, 583, 540, 339, 517, 553, 232, 232,
  541, 269, 833, 553, 575, 583, 583, 413, 471, 353, 553, 526, 750, 527, 526,
  472, 254, 262, 254, 560,
];
const TRACK = -0.035;
const ASC = 1.0;
const DESC = 0.303;
const LINE = 1.16;

function textEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += (c >= 32 && c <= 126 ? HANKEN_500[c - 32] : 600) / 1000 + TRACK;
  }
  return w;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Row {
  text: string;
  line: number;
  sub: number;
  hl: [number, number] | null;
}

function wrapRows(
  lines: string[],
  availEm: (line: number) => number,
  highlight: string,
) {
  const rows: Row[] = [];
  const needle = highlight.toLowerCase();
  lines.forEach((text, line) => {
    const words = text.split(/\s+/).filter(Boolean);
    const out: string[] = [];
    let cur = "";
    for (const w of words) {
      const next = cur ? `${cur} ${w}` : w;
      if (cur && textEm(next) > availEm(line)) {
        out.push(cur);
        cur = w;
      } else cur = next;
    }
    if (cur || out.length === 0) out.push(cur);
    out.forEach((t, sub) => {
      const a = needle ? t.toLowerCase().indexOf(needle) : -1;
      rows.push({
        text: t,
        line,
        sub,
        hl: a >= 0 ? [a, a + needle.length] : null,
      });
    });
  });
  return rows;
}

function IndentStepsBase({
  lines = ["Write it in React.", "Render it in Remotion.", "Ship it tonight."],
  highlight = "tonight",
  lineNumbers = true,
  exit = false,
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: IndentStepsProps) {
  const raw = useCurrentFrame();
  const frame = raw * speed;
  const { width, height, durationInFrames } = useVideoConfig();
  const p = PALETTES[theme];
  const logical = lines.slice(0, 5);
  const n = Math.max(1, logical.length);

  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.55
    : Math.min(width / 1280, height / 720);
  const padX = width * (portrait ? 0.07 : 0.09);
  const gutterEm = lineNumbers ? 0.95 : 0;
  const maxW = width - padX * 2;
  const maxH = height * (portrait ? 0.7 : 0.78);

  const widths = logical.map(textEm);
  const baseFs = (portrait ? 104 : 104) * s;
  const tab = portrait ? 1.1 : 1.5;
  const needEm = gutterEm + Math.max(...widths.map((w, i) => w + i * tab));
  const fitNoWrap = maxW / needEm;
  let fs: number;
  let rows: Row[];
  if (!portrait && fitNoWrap >= baseFs * 0.66) {
    fs = Math.min(baseFs, fitNoWrap);
    rows = wrapRows(logical, () => Number.POSITIVE_INFINITY, highlight);
  } else {
    fs = baseFs * (portrait ? 0.86 : 0.7);
    rows = [];
    for (let k = 0; k < 12; k++) {
      const f = fs;
      rows = wrapRows(logical, (i) => maxW / f - gutterEm - i * tab, highlight);
      const longestWord = Math.max(
        ...logical.flatMap((t, i) =>
          t.split(/\s+/).map((w) => textEm(w) + i * tab + gutterEm),
        ),
      );
      if (rows.length * fs * LINE <= maxH && longestWord * fs <= maxW) break;
      fs *= 0.92;
    }
  }
  const lh = fs * LINE;
  const blockW =
    (gutterEm + Math.max(...rows.map((r) => textEm(r.text) + r.line * tab))) *
    fs;
  const x0 = (width - blockW) / 2 + gutterEm * fs;
  const top = (height - rows.length * lh) / 2;
  const baseline = ((LINE - (ASC + DESC)) / 2 + ASC) * fs;
  const span = logical.map((_, i) => {
    const first = rows.findIndex((r) => r.line === i);
    return { first, count: rows.filter((r) => r.line === i).length };
  });

  const beat = n > 1 ? Math.min(20, 60 / (n - 1)) : 20;
  const enter = (i: number) => 4 + i * beat;
  const tabAt = (i: number) => enter(i) + Math.min(10, beat * 0.5);
  const done = n > 1 ? tabAt(n - 1) + 8 : enter(0) + 16;
  const EXIT = 18;
  const exitStart = durationInFrames - EXIT;
  const outdent = exit
    ? interpolate(raw, [exitStart, exitStart + 8], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      })
    : 0;
  const leave = (r: number) =>
    exit
      ? interpolate(
          raw,
          [exitStart + 6 + r * 2, exitStart + 15 + r * 2],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_IN,
          },
        )
      : 0;
  const lightT = interpolate(frame, [done - 4, done + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const drift = interpolate(raw, [0, durationInFrames], [0, 1], CLAMP);

  const indent = (i: number) => {
    if (i === 0) return 0;
    const snap = interpolate(frame, [tabAt(i), tabAt(i) + 8], [0, 1], {
      ...CLAMP,
      easing: EASE_SNAP,
    });
    return (i - 1 + snap) * (1 - outdent);
  };
  const rise = (row: Row) =>
    interpolate(
      frame,
      [enter(row.line) + row.sub * 2, enter(row.line) + row.sub * 2 + 16],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );

  const transparent = background === "transparent";
  const guideW = Math.max(1, 1.5 * s);

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: p.ground.join(", "),
              transform: `translate(${(-drift * 2).toFixed(3)}%, ${(-drift * 1.5).toFixed(3)}%) scale(1.06)`,
            }}
          />
          <Grain opacity={p.grain} />
        </>
      ) : null}

      {logical.map((_, i) => {
        const { first, count } = span[i];
        if (first < 0) return null;
        const pos = indent(i);
        const r = rise(rows[first]) * (1 - leave(first));
        if (r <= 0) return null;
        const stops = Math.min(i, Math.ceil(pos - 0.001));
        return Array.from({ length: stops }, (_, k) => {
          const grow = Math.min(1, pos - k);
          const heat =
            k === i - 1
              ? interpolate(frame, [tabAt(i) + 2, tabAt(i) + 20], [1, 0], CLAMP)
              : 0;
          return (
            <div
              key={`${i}-${k}`}
              style={{
                position: "absolute",
                left: x0 + k * tab * fs + fs * 0.03,
                top: top + first * lh - lh * 0.04,
                width: guideW,
                height: count * lh * grow,
                background: heat > 0.01 ? accent : p.guide,
                opacity: (heat > 0.01 ? 0.35 + 0.65 * heat : 1) * r,
              }}
            />
          );
        });
      })}

      {lineNumbers
        ? logical.map((_, i) => {
            const { first } = span[i];
            if (first < 0) return null;
            const r = rise(rows[first]) * (1 - leave(first));
            if (r <= 0) return null;
            const nfs = Math.max(12, fs * 0.22);
            return (
              <div
                key={`n${i}`}
                style={{
                  position: "absolute",
                  left: x0 - gutterEm * fs,
                  width: gutterEm * fs * 0.62,
                  top: top + first * lh + baseline - nfs * 0.98,
                  textAlign: "right",
                  fontFamily: mono.fontFamily,
                  fontWeight: 400,
                  fontSize: nfs,
                  lineHeight: 1,
                  color: p.muted,
                  fontVariantNumeric: "tabular-nums",
                  opacity: r,
                }}
              >
                {i + 1}
              </div>
            );
          })
        : null}

      {rows.map((row, ri) => {
        const r = rise(row);
        if (r <= 0) return null;
        const out = leave(ri);
        const pos = indent(row.line);
        const parts: [string, boolean][] = row.hl
          ? [
              [row.text.slice(0, row.hl[0]), false],
              [row.text.slice(row.hl[0], row.hl[1]), true],
              [row.text.slice(row.hl[1]), false],
            ]
          : [[row.text, false]];
        return (
          <div
            key={`l${ri}`}
            style={{
              position: "absolute",
              left: x0 + pos * tab * fs,
              top: top + ri * lh,
              height: lh,
              overflow: "hidden",
              paddingRight: "0.1em",
              fontFamily: hanken.fontFamily,
              fontWeight: 500,
              fontSize: fs,
              lineHeight: `${lh}px`,
              letterSpacing: `${TRACK}em`,
              whiteSpace: "nowrap",
              color: p.fg,
            }}
          >
            <div
              style={{
                transform: `translateY(${((1 - r) * 100 - out * 100).toFixed(2)}%)`,
              }}
            >
              {parts.map(([text, hl], k) =>
                hl ? (
                  <span key={k} style={{ position: "relative" }}>
                    <span style={{ opacity: 1 - lightT }}>{text}</span>
                    <span
                      style={{
                        position: "absolute",
                        left: 0,
                        top: 0,
                        opacity: lightT,
                        backgroundImage: p.highlight,
                        backgroundSize: "160% 100%",
                        backgroundPosition: `${(drift * 60).toFixed(2)}% 0%`,
                        WebkitBackgroundClip: "text",
                        backgroundClip: "text",
                        color: "transparent",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {text}
                    </span>
                  </span>
                ) : (
                  <Fragment key={k}>{text}</Fragment>
                ),
              )}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  highlight: {
    type: "text-content",
    default: "tonight",
    description: "Highlight",
  },
  lineNumbers: {
    type: "boolean",
    default: true,
    description: "Line numbers",
  },
  exit: {
    type: "boolean",
    default: false,
    description: "Exit",
  },
  speed: {
