interface RowsProps {
  items: string[];
  t: number;
  rowTop: (i: number) => number;
  rowH: number;
  F: number;
  numX: number;
  nameX: number;
  numColor: string;
  nameColor: string;
}

function Rows({
  items,
  t,
  rowTop,
  rowH,
  F,
  numX,
  nameX,
  numColor,
  nameColor,
}: RowsProps) {
  const maskH = F * 1.24;
  const cell = (
    key: string,
    x: number,
    i: number,
    delay: number,
    style: React.CSSProperties,
    text: string,
  ) => {
    const p = interpolate(
      t,
      [
        RULE_START + 8 + i * STAGGER + delay,
        RULE_START + 26 + i * STAGGER + delay,
      ],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    return (
      <div
        key={key}
        style={{
          position: "absolute",
          left: x,
          top: rowTop(i) + rowH / 2 - maskH / 2,
          height: maskH,
          overflow: "hidden",
          paddingRight: F * 0.2,
        }}
      >
        <div
          style={{
            height: maskH,
            display: "flex",
            alignItems: "center",
            transform: `translateY(${(1 - p) * maskH}px)`,
            fontSize: F,
            lineHeight: 1,
            whiteSpace: "nowrap",
            ...style,
          }}
        >
          {text}
        </div>
      </div>
    );
  };
  return (
    <>
      {items.map((item, i) => (
        <div key={`${i}-${item}`}>
          {cell(
            "n",
            numX,
            i,
            0,
            {
              fontFamily: hanken,
              fontWeight: 400,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
              color: numColor,
            },
            pad(i + 1),
          )}
          {cell(
            "t",
            nameX,
            i,
            2,
            {
              fontFamily: hanken,
              fontWeight: 500,
              letterSpacing: "-0.03em",
              color: nameColor,
            },
            item,
          )}
        </div>
      ))}
    </>
  );
}

function IndexListBase({
  items = DEFAULT_ITEMS,
  highlight = 3,
  title = "What’s inside 3.0",
  logo,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: IndexListProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const c = THEMES[theme];
  const n = Math.max(1, items.length);
  const hl = Math.min(Math.max(0, Math.round(highlight)), n - 1);

  const mX = W * 0.075;
  const cw = W - mX * 2;
  const col = cw / 12;
  const headerY = H * 0.1;
  const listTop = H * 0.205;
  const listBottom = H * 0.9;
  const rowH = (listBottom - listTop) / n;
  const longest = Math.max(...items.map((s) => s.length), 1);
  const F = Math.min(rowH * 0.5, 58 * u, (cw - col * 2.4) / (longest * 0.56));
  const inset = 20 * u;
  const numX = mX + inset;
  const nameX = mX + col * 2;
  const rowTop = (i: number) => listTop + rowH * i;
  const hair = Math.max(1, u);

  const rule = (i: number) =>
    interpolate(
      t,
      [RULE_START + i * STAGGER, RULE_START + 22 + i * STAGGER],
      [0, 1],
      { ...CLAMP, easing: EASE_IO },
    );
  const head = (d: number) =>
    interpolate(t, [d, d + 18], [0, 1], { ...CLAMP, easing: EASE_OUT });

  const wipe = interpolate(t, [BLOCK_IN, BLOCK_IN + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const travelStart = BLOCK_IN + 12;
  const travelDur = 14 + hl * 5;
  const lead = interpolate(t, [travelStart, travelStart + travelDur], [0, hl], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const trail = interpolate(
    t,
    [travelStart + 5, travelStart + 5 + travelDur],
    [0, hl],
    { ...CLAMP, easing: EASE_IO },
  );
  const parkedAt = travelStart + 5 + travelDur;
  const bTop = rowTop(trail) + hair;
  const bBottom = rowTop(lead) + rowH;
  const bLeft = mX;
  const bRight = mX + cw * wipe;
  const arrowP = interpolate(t, [parkedAt - 4, parkedAt + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, parkedAt + 40], [1.03, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.33, 0, 0.2, 1),
  });

  const rowsProps = { items, t, rowTop, rowH, F, numX, nameX };
  const arrowSize = F * 0.78;
  const dim = interpolate(t, [parkedAt - 2, parkedAt + 18], [1, 0.42], {
    ...CLAMP,
    easing: EASE_IO,
  });

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 80% at 30% 30%, ${c.key}, transparent 70%)`,
        }}
      />
      <AbsoluteFill
        style={{ transform: `scale(${push})`, transformOrigin: "50% 45%" }}
      >
        <div
          style={{
            position: "absolute",
            left: mX,
            top: headerY,
            display: "flex",
            alignItems: "baseline",
            gap: 14 * u,
            fontFamily: hanken,
            fontWeight: 400,
            fontSize: 19 * u,
            lineHeight: 1,
            letterSpacing: "-0.01em",
            color: c.muted,
            opacity: head(0),
            transform: `translateY(${(1 - head(0)) * 10 * u}px)`,
          }}
        >
          {logo ?? <RemocnLogo fontSize={24 * u} color={c.fg} />}
          <span
            style={{
              width: hair,
              height: 18 * u,
              background: c.hair,
              alignSelf: "center",
            }}
          />
          {title}
        </div>
        <div
          style={{
            position: "absolute",
            right: mX,
            top: headerY,
            height: 24 * u,
            display: "flex",
            alignItems: "center",
            fontFamily: hanken,
            fontWeight: 400,
            fontSize: 18 * u,
            lineHeight: 1,
            letterSpacing: "-0.01em",
            fontVariantNumeric: "tabular-nums",
            color: c.muted,
            opacity: head(4),
            transform: `translateY(${(1 - head(4)) * 10 * u}px)`,
          }}
        >
          {`${pad(n)} features`}
        </div>

        {Array.from({ length: n + 1 }, (_, i) => {
          const strong = i === 0;
          const th = strong ? 2 * u : hair;
          return (
            <div
              key={`r${i}`}
              style={{
                position: "absolute",
                left: mX,
                top: rowTop(i) - th / 2,
                width: cw * rule(i),
                height: th,
                background: strong ? c.rule : c.hair,
              }}
            />
          );
        })}

        <div style={{ position: "absolute", inset: 0, opacity: dim }}>
          <Rows {...rowsProps} numColor={c.muted} nameColor={c.fg} />
        </div>

        {wipe > 0 ? (
          <>
            <div
              style={{
                position: "absolute",
                left: bLeft,
                top: bTop,
                width: bRight - bLeft,
                height: bBottom - bTop,
                backgroundImage: beamFill(t, accent),
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                clipPath: `inset(${bTop}px ${W - bRight}px ${H - bBottom}px ${bLeft}px)`,
              }}
            >
              <Rows
                {...rowsProps}
                numColor="rgba(255,255,255,0.62)"
                nameColor={c.onAccent}
              />
              <div
                style={{
                  position: "absolute",
                  left: W - mX - inset - arrowSize,
                  top: rowTop(hl) + rowH / 2 - arrowSize / 2,
                  opacity: arrowP,
                  transform: `translateX(${(1 - arrowP) * -24 * u}px)`,
                }}
              >
                <Arrow size={arrowSize} color={c.onAccent} />
              </div>
            </div>
          </>
        ) : null}
      </AbsoluteFill>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

