const ELEMENT_PROP_KEYS = new Set(["color","highlight","dotColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  color: "#E5322D",
  highlight: "#FFFFFF",
  dotColor: "#111111",
  backgroundColor: "#111111",
  speed: 1,
};

type InflateElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InflateBase>;

const InflateInner = forwardRef<
  HTMLDivElement,
  InflateElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Inflate>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InflateBase
          {...(componentProps as unknown as ComponentProps<typeof InflateBase>)}
        />
      </div>
    </Sequence>
  );
});

