      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <InlineHighlightBase
            {...(componentProps as unknown as ComponentProps<typeof InlineHighlightBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

