    : { x: 92, y: (DH - DOC.h) / 2 };
  const panelW = tall ? 600 : PANEL_W;
  const panel = tall
    ? { x: 60, y: 132 + DOC.h * docScale + 36 }
    : { x: DW - PANEL_W - 92, y: 136 };
  const notif = tall
    ? { x: 60, y: 36, w: 600 }
    : { x: DW - 92 - 420, y: 40, w: 420 };

  const docIn = spring({ frame, fps, config: HEAVY });
  const panelIn = spring({ frame: frame - 6, fps, config: CARD });
