    [
      {
        t: 14,
        x: tall ? DW - 80 : DW - 60,
        y: tall ? panel.y + 420 : DH - 60,
      },
      { t: T.send - 2, ...sendPt },
      { t: T.send + 8, ...sendPt },
      {
        t: T.send + 30,
        x: sendPt.x + 40,
        y: sendPt.y + 140,
