                ? pal.node
                : pal.panel;
            const icon = (["file", "send", "eye", "check"] as const)[i];
            const y = TL_Y + i * STEP;
            return (
              <div key={ev.title} style={rowIn(3 + i)}>
                {i < 3 ? (
                  <div
                    style={{
                      position: "absolute",
                      left: PAD + 15,
                      top: y + 34,
                      width: 1.5,
                      height: STEP - 36,
                      background: pal.line,
                    }}
                  >
                    <div
                      style={{
                        width: "100%",
                        height: "100%",
                        background: i === 2 ? pal.green : pal.faint,
                        transformOrigin: "50% 0",
                        transform: `scaleY(${tween(frame, reachAt[i + 1] - 8, reachAt[i + 1], MOVE)})`,
                        opacity: 0.7,
                      }}
                    />
                  </div>
                ) : null}
                <div
                  style={{
                    position: "absolute",
                    left: PAD,
                    top: y,
                    width: 32,
                    height: 32,
                    borderRadius: 16,
                    background: nodeBg,
                    boxShadow:
                      isPaid && on > 0.5
                        ? "none"
                        : `inset 0 0 0 1px ${pal.line}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${isPaid ? 0.85 + 0.15 * pop : 1})`,
                  }}
                >
                  <div style={{ opacity: 0.3 + 0.7 * on }}>
                    <Icon
                      name={icon}
                      color={isPaid && on > 0.5 ? "#FFFFFF" : pal.text}
                      size={16}
                    />
                  </div>
                </div>
                <div
                  style={{
                    position: "absolute",
                    left: PAD + 48,
                    right: PAD,
                    top: y - 2,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "flex-start",
                  }}
                >
                  <div>
                    <div
                      style={{
                        fontSize: 17,
                        color:
                          on > 0.5
                            ? isPaid
                              ? pal.green
                              : pal.text
                            : pal.faint,
                      }}
                    >
                      {ev.title}
                    </div>
                    <div
                      style={{
                        fontSize: 16,
                        color: pal.muted,
                        marginTop: 2,
                        opacity: on,
                        transform: `translateY(${(1 - on) * 4}px)`,
                      }}
                    >
                      {ev.detail}
                    </div>
                  </div>
                  <span
                    style={{
                      fontSize: 16,
                      color: pal.faint,
                      fontVariantNumeric: "tabular-nums",
                      opacity: on,
                      marginTop: 1,
                    }}
                  >
                    {ev.time}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <div style={{ opacity: cursorOp }}>
          <Cursor x={cur.x} y={cur.y} press={press} />
        </div>

        <div
          style={{
            position: "absolute",
            left: notif.x,
            top: notif.y,
            width: notif.w,
            borderRadius: 16,
            padding: "14px 16px",
            boxSizing: "border-box",
            background: pal.notif,
            color: pal.text,
            display: "flex",
            alignItems: "center",
            gap: 14,
            opacity: Math.min(1, Math.max(0, notifIn) * 1.5),
            transform: `translateY(${(1 - notifIn) * -70}px) scale(${0.96 + 0.04 * notifIn})`,
            boxShadow: pal.panelShadow,
          }}
        >
          <div
            style={{
              width: 40,
              height: 40,
              borderRadius: 10,
              background: withAlpha(pal.green, pal.dark ? 0.18 : 0.12),
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <Icon name="bank" color={pal.green} size={20} />
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "baseline",
                fontSize: 17,
              }}
            >
              <span>Payout on the way</span>
              <span style={{ fontSize: 15, color: pal.faint }}>now</span>
            </div>
            <div
              style={{
                fontSize: 16,
                color: pal.muted,
                marginTop: 2,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
            >
              <span
                style={{ color: pal.text, fontVariantNumeric: "tabular-nums" }}
              >
                {fmt(total - payoutFee, currency)}
              </span>{" "}
              to ••{payoutAccount.slice(-4)} · arrives {payoutArrival}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

