const ELEMENT_PROP_KEYS = new Set(["grid","maxHeight","stagger","gap","floors","seed","background","color","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  grid: 5,
  maxHeight: 2.2,
  stagger: 2,
  gap: 0.04,
  floors: true,
  seed: 4,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
  speed: 1,
};

type IsometricBuildElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof IsometricBuildBase>;

const IsometricBuildInner = forwardRef<
  HTMLDivElement,
  IsometricBuildElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<IsometricBuild>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <IsometricBuildBase
          {...(componentProps as unknown as ComponentProps<typeof IsometricBuildBase>)}
        />
      </div>
    </Sequence>
  );
});

export const IsometricBuild = Interactive.withSchema({
  Component: IsometricBuildInner,
  componentName: "<IsometricBuild>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

