    "3-40 3–40 3—40 4-40 4–40 4—40 5-40 5–40 5—40 6-20 6–20 6—20 77-10",
    "7,-120 7--40 7…-120 7–-40 7—-40 8-30 8–30 8—30 9-40 9–40 9—40 -V-50",
    "-W-50 -X-50 -Y-135 -040 -140 -240 -340 -440 -540 -640 -830 -920 'A-98",
    "'J-100 '4-12 ',-50 '…-50 ’A-98 –V-50 –W-50 –X-50 –Y-135 –040 –140",
    "–240 –340 –440 –540 –640 –830 –920 —V-50 —W-50 —X-50 —Y-135 —040 —140",
    "—240 —340 —440 —540 —640 —830 —920",
  ]
    .join(" ")
    .split(" ")
    .map((p) => [p.slice(0, 2), Number(p.slice(2)) / 1000] as const),
);
const CAP = 0.686;

// Beat sheet (30fps, speed 1):
//  0–12    horizontal speed strips shoot in from the left edge, already moving
//          on frame 0, each with its own length and weight
//  3–19    the word rides in on them at high skew, leading letter first; the
//          trailing letters catch up, so the word arrives stretched
//  13–24   each letter brakes and its skew snaps to the resting slant with a
//          small overshoot (leans back a hair, then settles)
//  18–33   the strips retract: left ends race in, they fold down onto one thin
//          accent underline under the word
//  32–43   the second line slides up out from under the underline
//  43–     poster hold
const ARRIVE = 13;
const TRAVEL = 11;
const STAGGER = 1.2;
const LEAN = 34;
const RETRACT_AT = 18;
const RETRACT_LEN = 11;
const SUB_AT = 32;
const SUB_LEN = 11;

const RIDE = Easing.bezier(0.16, 0.8, 0.25, 1);
const STRIP_IN = Easing.bezier(0.2, 0.7, 0.3, 1);
const RETRACT = Easing.bezier(0.6, 0, 0.2, 1);
const SUB = Easing.bezier(0.2, 0.85, 0.3, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    strip: "#2E2E34",
    sub: "#B9B8B3",
    // gradients.sh "beam": tail fades into the stage, head burns white-blue.
    beam: ["#1A1660", "#3D5BFF", "#8FB4FF", "#F4F7FF"],
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    strip: "#D6D4CD",
    sub: "#55545A",
    beam: ["#C9D4FF", "#8FB4FF", "#3D5BFF", "#1A1660"],
  },
} as const;

// Strips: vertical position (0 = cap top, 1 = baseline), thickness (× cap),
// right-end overhang past the word (× word width), whether it takes the
// accent, and how far across the frame it already is on frame 0.
const STRIPS = [
  { y: -0.06, h: 0.035, over: 0.08, accent: false, head: 0.55 },
  { y: 0.1, h: 0.09, over: -0.18, accent: true, head: 0.35 },
  { y: 0.24, h: 0.03, over: 0.14, accent: false, head: 0.7 },
  { y: 0.37, h: 0.13, over: -0.3, accent: false, head: 0.25 },
  { y: 0.52, h: 0.05, over: 0.03, accent: true, head: 0.6 },
  { y: 0.64, h: 0.025, over: 0.2, accent: false, head: 0.45 },
  { y: 0.76, h: 0.08, over: -0.08, accent: false, head: 0.3 },
  { y: 0.9, h: 0.04, over: 0.1, accent: true, head: 0.65 },
  { y: 1.06, h: 0.06, over: -0.22, accent: false, head: 0.4 },
];

const EXTRA = "’“”…–—";
function code(ch: string) {
  const c = ch.charCodeAt(0);
  if (c >= 32 && c < 127) return c - 32;
  const x = EXTRA.indexOf(ch);
  return x >= 0 ? 95 + x : 46;
}

/** Pen offset of each glyph plus the total advance, in em, kerned. */
function layout(text: string) {
  const pens: number[] = [];
  let pen = 0;
  for (let i = 0; i < text.length; i++) {
    if (i > 0) pen += KERN.get(text[i - 1] + text[i]) ?? 0;
    pens.push(pen);
    pen += ADV[code(text[i])] / 1000;
  }
  return { pens, advance: pen };
}

function ItalicSpeedBase({
  title = "FASTER",
  subtitle = "Ship at race pace.",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ItalicSpeedProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const text = title.trim().toUpperCase() || "GO";
  const { pens, advance } = layout(text);
  const lsb = LSB[code(text[0])] / 1000;
  const rsb = RSB[code(text[text.length - 1])] / 1000;
  const inkEm = Math.max(0.5, advance - lsb - rsb);
  const fs = Math.min((0.78 * W) / inkEm, (0.36 * H) / CAP);
  const cap = CAP * fs;
  const inkW = inkEm * fs;

  const sub = subtitle.trim();
  const subFs = Math.max(0.44 * fs, 0.06 * W);
  const ruleGap = 0.13 * cap;
  const ruleH = Math.max(3, 0.0085 * H);
  const subGap = 0.3 * subFs;
  const blockH = cap + ruleGap + ruleH + (sub ? subGap + subFs * CAP * 1.3 : 0);
  const baseline = (H - blockH) / 2 + cap;
  const left = (W - inkW) / 2 - 0.02 * W;
  const penX = left - lsb * fs;
  const ruleY = baseline + ruleGap;
  // Italic: at the baseline the ink starts a little left of the cap-top ink.
  const ruleL = left - 0.02 * fs;
  const ruleR = left + inkW - 0.1 * fs;

  // Letters: the last one leads; each trails the next by STAGGER frames.
  const n = text.length;
  const letters = text.split("").map((ch, i) => {
    const arrive = ARRIVE + (n - 1 - i) * STAGGER;
    const ride = RIDE(interpolate(t, [arrive - TRAVEL, arrive], [0, 1], CLAMP));
    const dx = -(1.05 * W) * (1 - ride);
    const snap = spring({
      frame: t - (arrive - 2),
      fps,
      config: { damping: 11, stiffness: 320, mass: 0.55 },
    });
    const lean = -LEAN * (1 - snap);
    const x = penX + pens[i] * fs + dx;
    const pivot = x + (ADV[code(ch)] / 2000) * fs;
    return { ch, x, lean, pivot, visible: ride > 0 };
  });
  const lead = letters[n - 1];
  const leadRight = lead.x + (ADV[code(lead.ch)] / 1000) * fs;

  const strips = STRIPS.map((s, k) => {
    const color = s.accent ? `url(#${uid}-beam)` : c.strip;
    const enter = STRIP_IN(
      interpolate(t, [-TRAVEL * s.head, ARRIVE - 2 + k * 0.5], [0, 1], CLAMP),
    );
    const restR = ruleR + s.over * inkW;
    // The strip head never falls behind the leading letter it pulls along.
    const headX = Math.max(-0.02 * W + (restR + 0.02 * W) * enter, leadRight);
    const r0 = Math.min(headX, restR + 0.6 * W);
    const ret = RETRACT(
      interpolate(
        t,
        [RETRACT_AT + k * 0.5, RETRACT_AT + k * 0.5 + RETRACT_LEN],
        [0, 1],
        CLAMP,
      ),
    );
    const y0 = baseline - cap + s.y * cap - (s.h * cap * 1.4) / 2;
    const h0 = s.h * cap * 1.4;
    const l = -0.05 * W + (ruleL + 0.05 * W) * ret;
    const r = r0 + (ruleR - r0) * ret;
    const y = y0 + (ruleY - y0) * ret;
    const h = h0 + (ruleH - h0) * ret;
    return { key: k, l, r, y, h, color, accent: s.accent, ret };
  });
  const done = strips.every((s) => s.ret >= 1);

  const subP = SUB(interpolate(t, [SUB_AT, SUB_AT + SUB_LEN], [0, 1], CLAMP));
  const subLean = -14 * (1 - subP);
  const subBase = ruleY + ruleH + subGap + subFs * CAP;
  const subDy = -(subFs * 1.2) * (1 - subP);
  const subX = ruleL + 0.004 * W;

  return (
    <AbsoluteFill style={{ background: c.stage }}>
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        role="img"
        aria-label={sub ? `${text}. ${sub}` : text}
      >
        <defs>
          <linearGradient id={`${uid}-beam`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={c.beam[0]} stopOpacity={0} />
            <stop offset="0.35" stopColor={c.beam[0]} />
            <stop offset="0.7" stopColor={c.beam[1]} />
            <stop offset="0.92" stopColor={c.beam[2]} />
            <stop offset="1" stopColor={c.beam[3]} />
          </linearGradient>
          <linearGradient id={`${uid}-rule`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={accent} />
            <stop offset="0.75" stopColor={c.beam[1]} />
            <stop offset="1" stopColor={c.beam[2]} />
          </linearGradient>
          <clipPath id={`${uid}-sub`}>
            <rect x={0} y={ruleY + ruleH} width={W} height={H} />
          </clipPath>
        </defs>
        {done ? (
          <rect
            x={ruleL}
            y={ruleY}
            width={ruleR - ruleL}
            height={ruleH}
            fill={`url(#${uid}-rule)`}
          />
        ) : (
          [
            ...strips.filter((s) => !s.accent),
            ...strips.filter((s) => s.accent),
          ]
            .filter((s) => s.r > s.l)
            .map((s) => (
              <rect
                key={s.key}
                x={s.l}
                y={s.y}
                width={s.r - s.l}
                height={s.h}
                fill={s.color}
              />
            ))
        )}
        {letters.map((g, i) =>
          g.visible && g.ch !== " " ? (
            <text
              key={i}
              x={g.x}
              y={baseline}
              transform={`translate(${g.pivot} ${baseline}) skewX(${g.lean}) translate(${-g.pivot} ${-baseline})`}
              fill={c.ink}
              fontFamily={display}
              fontStyle="italic"
              fontWeight={500}
              fontSize={fs}
              style={{ fontKerning: "none" }}
            >
              {g.ch}
            </text>
          ) : null,
        )}
        {sub && subP > 0 ? (
          <g clipPath={`url(#${uid}-sub)`}>
            <text
              x={subX}
              y={subBase + subDy}
              transform={`translate(${subX} ${subBase}) skewX(${subLean}) translate(${-subX} ${-subBase})`}
              fill={c.sub}
              fontFamily={serif}
              fontStyle="italic"
              fontWeight={400}
              fontSize={subFs}
              style={{ letterSpacing: "-0.01em" }}
            >
              {sub}
            </text>
          </g>
        ) : null}
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  title: {
    type: "text-content",
    default: "FASTER",
    description: "Title",
  },
  subtitle: {
    type: "text-content",
    default: "Ship at race pace.",
    description: "Subtitle",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","subtitle","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "FASTER",
  subtitle: "Ship at race pace.",
  speed: 1,
};

type ItalicSpeedElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ItalicSpeedBase>;

const ItalicSpeedInner = forwardRef<
  HTMLDivElement,
  ItalicSpeedElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ItalicSpeed>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ItalicSpeedBase
          {...(componentProps as unknown as ComponentProps<typeof ItalicSpeedBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ItalicSpeed = Interactive.withSchema({
  Component: ItalicSpeedInner,
  componentName: "<ItalicSpeed>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Gloock";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const gloock = loadFont("normal", { weights: ["400"], subsets: ["latin"] });

interface KeepBelief {
  text: string;
  keep: string;
}

interface KeepWordsProps {
  beliefs?: KeepBelief[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_BELIEFS: KeepBelief[] = [
  {
    text: "A launch video should be written, the same way the product was.",
    keep: "written",
  },
  {
    text: "Every frame you install should stay yours, down to the last easing curve.",
    keep: "yours",
  },
  {
    text: "And the film should land on time, in the same release as the code.",
    keep: "on time",
  },
];

const THEMES = {
  dark: { bg: "#0A1230", ink: "#FFFFFF", accent: "#FF4436" },
  light: { bg: "#F7F3EC", ink: "#14161F", accent: "#D92B1E" },
} as const;

const TRACK = -0.02;
const LH = 1.08;
const START = 6;
const STACK_MOVE = 24;
const FINAL_HOLD = 34;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.75, 0.2);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string): number {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) return s.length * 0.5;
  measureCtx.font = `400 100px "${gloock.fontFamily}"`;
  return measureCtx.measureText(s).width / 100 + TRACK * Array.from(s).length;
}

function useFontReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("keep-words: font"));
  useEffect(() => {
    let live = true;
    gloock
      .waitUntilDone()
      .then(() => document.fonts.load(`400 100px "${gloock.fontFamily}"`))
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setReady(true);
        continueRender(handle);
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

interface Seg {
  text: string;
  dx: number;
  key: number;
}

interface Word {
  segs: Seg[];
  w: number;
}

interface Laid {
  words: { x: number; line: number }[];
  lines: number;
}

function wrapAt(words: Word[], maxEm: number): Laid {
  const space = em(" ");
  const out: { x: number; line: number }[] = [];
  let line = 0;
  let x = 0;
  for (const w of words) {
    if (x > 0 && x + w.w > maxEm) {
      line += 1;
      x = 0;
    }
    out.push({ x, line });
    x += w.w + space;
  }
  return { words: out, lines: line + 1 };
}

function balanced(words: Word[], maxEm: number): Laid {
  const base = wrapAt(words, maxEm);
  let lo = Math.max(...words.map((w) => w.w), 0.1);
  let hi = maxEm;
  for (let i = 0; i < 14; i++) {
    const mid = (lo + hi) / 2;
    if (wrapAt(words, mid).lines <= base.lines) hi = mid;
    else lo = mid;
  }
  return wrapAt(words, hi);
}

function fitSize(words: Word[], boxW: number, boxH: number, maxF: number) {
  let lo = 8;
  let hi = maxF;
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    const lay = wrapAt(words, boxW / mid);
    const widest = Math.max(...words.map((w) => w.w)) * mid;
    if (lay.lines * LH * mid <= boxH && widest <= boxW) lo = mid;
    else hi = mid;
  }
  return lo;
}

function splitBelief(b: KeepBelief): Word[] {
  const tokens = b.text.split(/\s+/).filter(Boolean);
  const keepTokens = b.keep.toLowerCase().split(/\s+/).filter(Boolean);
  const core = (s: string) =>
    s.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, "");
  let at = -1;
  for (let i = 0; i + keepTokens.length <= tokens.length && at < 0; i++) {
    let ok = true;
    for (let j = 0; j < keepTokens.length; j++) {
      if (core(tokens[i + j]).toLowerCase() !== keepTokens[j]) ok = false;
    }
    if (ok) at = i;
  }
  return tokens.map((tk, i) => {
    const k = at >= 0 && i >= at && i < at + keepTokens.length ? i - at : -1;
    if (k < 0) return { segs: [{ text: tk, dx: 0, key: -1 }], w: em(tk) };
    const c = core(tk);
    const start = tk.indexOf(c);
    const lead = tk.slice(0, start);
    const tail = tk.slice(start + c.length);
    const segs: Seg[] = [];
    if (lead) segs.push({ text: lead, dx: 0, key: -1 });
    segs.push({ text: c, dx: em(lead), key: k });
    if (tail) segs.push({ text: tail, dx: em(lead + c), key: -1 });
    return { segs, w: em(tk) };
  });
}

function mottoOf(keep: string) {
  const t = keep.trim();
  return `${t.charAt(0).toUpperCase()}${t.slice(1)}`;
}

function KeepWordsBase({
  beliefs = DEFAULT_BELIEFS,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: KeepWordsProps) {
  const frame = useCurrentFrame();
  const t = frame * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontReady();

  if (!ready || beliefs.length === 0) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const n = beliefs.length;
  const D = durationInFrames * speed;
  const seg = Math.max(
    48,
    (D - START - STACK_MOVE - FINAL_HOLD - 30) / Math.max(1, n),
  );
  const lastTravel =
    START + (n - 1) * seg + seg * 0.66 + Math.min(24, seg * 0.3);
  const stackAt = lastTravel + 14;

  const mx = W * (portrait ? 0.08 : 0.07);
  const boxTop = H * (portrait ? 0.1 : 0.1);
  const boxW = W * (portrait ? 0.84 : 0.8);
  const boxH = H * (portrait ? 0.46 : 0.56);

  const mottoItems = beliefs.map((b) => mottoOf(b.keep));
  const space = em(" ");
  const mottoWidthEm =
    mottoItems.reduce((s, m) => s + em(`${m}.`), 0) + space * (n - 1);
  const Fm = Math.min(
    H * (portrait ? 0.05 : 0.085),
    (W - mx * 2) / mottoWidthEm,
  );
  const mottoTop = H * (portrait ? 0.66 : 0.76);

  const stackWidest = Math.max(...mottoItems.map((m) => em(`${m}.`)));
  const Ff = Math.min(
    (H * (portrait ? 0.62 : 0.8)) / (n * LH),
    (W - mx * 2) / stackWidest,
    H * 0.3,
  );
  const stackTop = portrait ? H * 0.5 - (n * LH * Ff) / 2 : boxTop;

  const mottoSlots: { x: number; y: number }[][] = [];
  const stackSlots: { x: number; y: number }[][] = [];
  let mxEm = 0;
  mottoItems.forEach((m, i) => {
    const parts = m.split(/\s+/);
    const rowSlots: { x: number; y: number }[] = [];
    const colSlots: { x: number; y: number }[] = [];
    let local = 0;
    for (const p of parts) {
      rowSlots.push({ x: mx + (mxEm + local) * Fm, y: mottoTop });
      colSlots.push({ x: mx + local * Ff, y: stackTop + i * LH * Ff });
      local += em(p) + space;
    }
    rowSlots.push({ x: mx + (mxEm + em(m)) * Fm, y: mottoTop });
    colSlots.push({ x: mx + em(m) * Ff, y: stackTop + i * LH * Ff });
    mottoSlots.push(rowSlots);
    stackSlots.push(colSlots);
    mxEm += em(`${m}.`) + space;
  });

  const stackOf = (i: number) =>
    interpolate(t, [stackAt + i * 4, stackAt + i * 4 + STACK_MOVE], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });

  const nodes: React.ReactNode[] = [];

  const glyph = (
    key: string,
    text: string,
    x: number,
    y: number,
    size: number,
    renderSize: number,
    color: string,
    opacity: number,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        fontFamily: gloock.fontFamily,
        fontWeight: 400,
        fontSize: renderSize,
        lineHeight: `${LH * renderSize}px`,
        letterSpacing: `${TRACK}em`,
        whiteSpace: "pre",
        color,
        opacity,
        transformOrigin: "0 0",
        transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) scale(${(size / renderSize).toFixed(4)})`,
      }}
    >
      {text}
    </div>
  );

  beliefs.forEach((b, bi) => {
    const stackP = stackOf(bi);
    const s0 = START + bi * seg;
    const u = t - s0;
    const words = splitBelief(b);
    const F = fitSize(words, boxW, boxH, H * (portrait ? 0.1 : 0.17));
    const lay = balanced(words, boxW / F);
    const markAt = seg * 0.42;
    const fallAt = seg * 0.6;
    const travelAt = seg * 0.66;
    const travelLen = Math.min(24, seg * 0.3);
    const mark = interpolate(u, [markAt, markAt + 8], [0, 1], CLAMP);
    const keyColor = interpolateColors(mark, [0, 1], [c.ink, hi]);

    if (u > -1) {
      const stagger = Math.min(2, 22 / Math.max(1, words.length));
      let order = 0;
      words.forEach((w, wi) => {
        const pos = lay.words[wi];
        const wx = mx + pos.x * F;
        const wy = boxTop + pos.line * LH * F;
        const enter = interpolate(
          u,
          [order * stagger, order * stagger + 16],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_OUT,
          },
        );
        order += 1;
        w.segs.forEach((sg, si) => {
          const id = `b${bi}w${wi}s${si}`;
          if (sg.key < 0) {
            const fall = interpolate(
              u,
              [fallAt + (wi % 4), fallAt + (wi % 4) + 12],
              [0, 1],
              { ...CLAMP, easing: EASE_IN },
            );
            const op = enter * (1 - fall);
            if (op <= 0.001) return;
            nodes.push(
              glyph(
                id,
                sg.text,
                wx + sg.dx * F,
                wy + (1 - enter) * F * 0.32 + fall * F * 0.22,
                F,
                F,
                c.ink,
                op,
              ),
            );
            return;
          }
          const travel = interpolate(
            u,
            [travelAt + sg.key * 2, travelAt + sg.key * 2 + travelLen],
            [0, 1],
            { ...CLAMP, easing: EASE_IO },
          );
          const row = mottoSlots[bi][sg.key];
          const col = stackSlots[bi][sg.key];
          const fx = wx + sg.dx * F;
          const fy = wy + (1 - enter) * F * 0.32;
          const rx = row.x + (col.x - row.x) * stackP;
          const ry = row.y + (col.y - row.y) * stackP;
          const rs = Fm + (Ff - Fm) * stackP;
          const x = fx + (rx - fx) * travel;
          const y = fy + (ry - fy) * travel;
          const size = F + (rs - F) * travel;
          const render = Math.max(F, Ff);
          const landed = interpolate(travel, [0.85, 1], [0, 1], CLAMP);
          const color = interpolateColors(landed, [0, 1], [keyColor, c.ink]);
          const finalText =
            sg.key === 0 ? mottoItems[bi].split(/\s+/)[0] : sg.text;
          const swap = finalText !== sg.text ? landed : 0;
          if (swap < 1) {
            nodes.push(
              glyph(id, sg.text, x, y, size, render, color, enter * (1 - swap)),
            );
          }
          if (swap > 0) {
            nodes.push(
              glyph(`${id}f`, finalText, x, y, size, render, color, swap),
            );
          }
        });
      });
    }

    const dotAt = travelAt + (mottoSlots[bi].length - 2) * 2 + travelLen;
    const dot = interpolate(u, [dotAt - 4, dotAt + 6], [0, 1], CLAMP);
    if (dot > 0) {
      const row = mottoSlots[bi][mottoSlots[bi].length - 1];
      const col = stackSlots[bi][stackSlots[bi].length - 1];
      const rs = Fm + (Ff - Fm) * stackP;
      nodes.push(
        glyph(
          `b${bi}dot`,
          ".",
          row.x + (col.x - row.x) * stackP,
          row.y + (col.y - row.y) * stackP,
          rs,
          Ff,
          hi,
          dot,
        ),
      );
    }
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

