    sideTop: [0x2e, 0x2e, 0x34],
    sideBottom: [0x10, 0x10, 0x13],
    legend: "#ECEBE7",
    sub: "#8F8E95",
    rim: 0.3,
    dish: 0.34,
    sheen: 0.11,
    front: 0.4,
