    sideTop: [0xe9, 0xe7, 0xe1],
    sideBottom: [0xa9, 0xa5, 0x9b],
    legend: "#2A2A2E",
    sub: "#8C8981",
    rim: 0.9,
    dish: 0.07,
    sheen: 0.5,
    front: 0.14,
    left: 0.35,
    right: 0.16,
