const ELEMENT_PROP_KEYS = new Set(["platform","theme","accent","size","linger","x","y","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  platform: "mac",
  theme: "light",
  accent: "#0a84ff",
  size: 64,
  linger: 30,
  x: 0.5,
  y: 0.86,
  speed: 1,
};

type KeystrokeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof KeystrokeBase>;

const KeystrokeInner = forwardRef<
  HTMLDivElement,
  KeystrokeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Keystroke>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <KeystrokeBase
          {...(componentProps as unknown as ComponentProps<typeof KeystrokeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Keystroke = Interactive.withSchema({
  Component: KeystrokeInner,
  componentName: "<Keystroke>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

