const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","subline","label","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "Knockout",
  subline: "The old workflow did not get up.",
  label: "The count",
  speed: 1,
};

type KoCountElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof KoCountBase>;

const KoCountInner = forwardRef<
  HTMLDivElement,
  KoCountElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<KoCount>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <KoCountBase
          {...(componentProps as unknown as ComponentProps<typeof KoCountBase>)}
        />
      </div>
    </Sequence>
  );
});

export const KoCount = Interactive.withSchema({
  Component: KoCountInner,
  componentName: "<KoCount>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

