export interface LandingConfirmedProps {
  /** Altitude the descent starts from, in metres. */
  from?: number;
  /** The slam at touchdown. Two words read best (one per line). */
  confirm?: string;
  /** The first resolve line, set big in caps. */
  title?: string;
  /** The second resolve line, set in a serif italic. */
  subtitle?: string;
  /** Replaces the remocn logo under the resolve. */
  logo?: React.ReactNode;
  /** Gauge marker and small marks. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1):
//   0–50    altitude counts down fast from 1,200 m; the gauge marker rides the
//           vertical scale down to the pad line; velocity bleeds off top right
//   50      0 m: hard stop with a kick, the pad line lights; holds 6 frames
//   56–57   two-frame "aurora" flash
//   58      TOUCHDOWN / CONFIRMED slams in; the aurora glows up from the pad
//   88–102  it shrinks up into a label; SHIPPED. slams, "Nailed the landing."
//           and the logo rise in under it
//   104–    poster hold
const DESCENT = 50;
const FLASH_AT = DESCENT + 6;
const SLAM_AT = FLASH_AT + 2;
const RESOLVE_AT = SLAM_AT + 30;

const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "aurora": bg #03050b, #a0f0c8 #3fb5a3 #5147b6 #b25c9c.
const AURORA = ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"] as const;

const THEMES = {
  dark: {
    stage: "#03050B",
    ink: "#F1F4F2",
    dim: "#737A7A",
    faint: "#22282B",
    glowOp: 0.95,
    titleFill: `linear-gradient(100deg, #EFFFF7 0%, ${AURORA[0]} 38%, ${AURORA[1]} 70%, #9C93F0 100%)`,
    flash: `radial-gradient(120% 100% at 50% 100%, #F2FFF8 0%, ${AURORA[0]} 30%, ${AURORA[1]} 58%, ${AURORA[2]} 85%, ${AURORA[3]} 100%)`,
    grain: 0.06,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#111315",
    dim: "#7D7C77",
    faint: "#D8D6CF",
    glowOp: 0.6,
    titleFill: `linear-gradient(100deg, #1F7A6C 0%, ${AURORA[1]} 35%, ${AURORA[2]} 72%, ${AURORA[3]} 100%)`,
    flash: `radial-gradient(120% 100% at 50% 100%, #FFFFFF 0%, ${AURORA[0]} 40%, ${AURORA[1]} 75%, ${AURORA[2]} 100%)`,
    grain: 0.04,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

function kick(d: number, len: number) {
  if (d < 0 || d > len + 1) return 0;
  if (d < 1) return d;
  const k = 1 - (d - 1) / len;
  return k * k;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={21}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function LandingConfirmed({
  from = 1200,
  confirm = "Touchdown confirmed",
  title = "Shipped.",
  subtitle = "Nailed the landing.",
  logo,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: LandingConfirmedProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);

  // ── Descent ───────────────────────────────────────────────────────────────
  // Fast off the top, still moving when it hits the pad: a hard stop.
  const p = ramp(t, 0, DESCENT);
  const frac = (1 - p) * (1 - 0.55 * p);
  const alt = Math.max(0, Math.round(from * frac));
  const landed = t >= DESCENT;
  const vel = landed ? 0 : 2 + 238 * (1 - p) ** 1.4;

  // ── Layout ────────────────────────────────────────────────────────────────
  const padY = H - 110 * u;
  const gaugeX = 118 * u;
  const gaugeTop = 92 * u;
  const markerY = interpolate(frac, [0, 1], [padY, gaugeTop]);
  const numFs = 290 * u;
  const numCX = W * 0.54;
  const numCY = H * 0.47;
  const margin = 56 * u;

  const intro = OUT(ramp(t, -4, 10));
  const stopKick = kick(t - DESCENT, 7);
  const flash = t >= FLASH_AT && t < FLASH_AT + 2;
  const glow = OUT(ramp(t, FLASH_AT, 18));

  const slam = OUT(ramp(t, SLAM_AT - 1, 8));
  const slamHit = kick(t - SLAM_AT - 4, 8);
  const resolve = MOVE(ramp(t, RESOLVE_AT, 14));
  const exit = Easing.bezier(0.55, 0, 1, 0.45)(ramp(t, RESOLVE_AT, 6));
  const labelIn = OUT(ramp(t, RESOLVE_AT + 6, 10));
  const titleIn = OUT(ramp(t, RESOLVE_AT + 5, 9));
  const titleHit = kick(t - RESOLVE_AT - 8, 8);
  const subIn = OUT(ramp(t, RESOLVE_AT + 9, 12));
  const logoIn = OUT(ramp(t, RESOLVE_AT + 14, 12));
  const descentOut = landed ? 1 - ramp(t, FLASH_AT, 1) : 1;
  const gaugeOut = 1 - ramp(t, SLAM_AT, 10);

  const words = confirm.split(" ");
  const confirmA = words.slice(0, Math.ceil(words.length / 2)).join(" ");
  const confirmB = words.slice(Math.ceil(words.length / 2)).join(" ");

  const drift = ramp(t, FLASH_AT, 120);
  const aurora = [
    ...AURORA.map(
      (col, i) =>
        `radial-gradient(42% 30% at ${14 + i * 24 + drift * (i % 2 ? -4 : 4)}% ${(padY / H) * 100 + 2}%, color-mix(in oklab, ${col} 70%, transparent) 0%, transparent 72%)`,
    ),
    `linear-gradient(180deg, transparent 55%, color-mix(in oklab, ${AURORA[1]} 18%, transparent) ${(padY / H) * 100}%, transparent 100%)`,
  ].join(", ");

  const small: React.CSSProperties = {
    fontFamily: sans,
    fontWeight: 400,
    fontSize: 15 * u,
    letterSpacing: "0.14em",
    textTransform: "uppercase",
    color: c.dim,
    whiteSpace: "nowrap",
    lineHeight: 1,
    fontVariantNumeric: "tabular-nums",
  };

  const ticks: number[] = [];
  for (let m = 0; m <= from; m += from / 12) ticks.push(m);

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      {/* Aurora from the pad. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: aurora,
          opacity: c.glowOp * glow,
          transform: `translateY(${(1 - glow) * 80 * u}px)`,
        }}
      />
      <Grain opacity={c.grain} />

      {/* Gauge. */}
      <div style={{ opacity: intro * gaugeOut }}>
        <div
          style={{
            position: "absolute",
            left: gaugeX,
            top: gaugeTop,
            width: 2 * u,
            height: padY - gaugeTop,
            background: c.faint,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: gaugeX,
            top: markerY,
            width: 3 * u,
            height: padY - markerY,
            background: c.ink,
          }}
        />
        {ticks.map((m, i) => {
          const y = interpolate(m / from, [0, 1], [padY, gaugeTop]);
          const major = i % 3 === 0;
          return (
            <div key={m}>
              <div
                style={{
                  position: "absolute",
                  left: gaugeX - (major ? 14 : 8) * u,
                  top: y - 0.5 * u,
                  width: (major ? 14 : 8) * u,
                  height: 1.5 * u,
                  background: y >= markerY ? c.ink : c.dim,
                }}
              />
              {major ? (
                <div
                  style={{
                    ...small,
                    position: "absolute",
                    right: W - gaugeX + 24 * u,
                    top: y - 7 * u,
                    letterSpacing: "0.04em",
                  }}
                >
                  {Math.round(m)}
                </div>
              ) : null}
            </div>
          );
        })}
        {/* Marker. */}
        <div
          style={{
            position: "absolute",
            left: gaugeX + 10 * u,
            top: markerY - 1.5 * u,
            width: 40 * u,
            height: 3 * u,
            background: accent,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: gaugeX + 10 * u,
            top: markerY - 7 * u,
            width: 0,
            height: 0,
            borderTop: `${7 * u}px solid transparent`,
            borderBottom: `${7 * u}px solid transparent`,
            borderRight: `${10 * u}px solid ${accent}`,
            transform: `translateX(${-10 * u}px)`,
          }}
        />
      </div>

      {/* Pad line. */}
      <div
        style={{
          position: "absolute",
          left: margin,
          right: margin,
          top: padY,
          height: 2 * u,
          background: landed ? c.ink : c.faint,
          opacity: intro * (1 - resolve * 0.6),
        }}
      />

      {/* Telemetry. */}
      <div
        style={{
          ...small,
          position: "absolute",
          left: margin,
          top: margin - 6 * u,
          opacity: intro * gaugeOut,
        }}
      >
        Descent{" "}
        <span style={{ color: c.ink }}>
          {landed ? "Complete" : "Landing burn"}
        </span>
      </div>
      <div
        style={{
          ...small,
          position: "absolute",
          right: margin,
          top: margin - 6 * u,
          textAlign: "right",
          opacity: intro * gaugeOut,
        }}
      >
        Vel <span style={{ color: c.ink }}>{vel.toFixed(1)}</span> m/s
      </div>

      {/* Altitude. */}
      <div
        style={{
          position: "absolute",
          left: numCX,
          top: numCY,
          opacity: intro * descentOut,
          transform: `translate(-50%, -50%) translateY(${(1 - intro) * -40 * u}px) scale(${1 + 0.05 * stopKick})`,
        }}
      >
        <div
          style={{
            ...small,
            fontSize: 18 * u,
            marginBottom: 6 * u,
            marginLeft: 8 * u,
          }}
        >
          Altitude
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            fontFamily: sans,
            fontWeight: 500,
            fontSize: numFs,
            lineHeight: 1,
            letterSpacing: "-0.04em",
            fontVariantNumeric: "tabular-nums",
            color: c.ink,
            whiteSpace: "nowrap",
          }}
        >
          {alt.toLocaleString("en-US")}
          <span
            style={{
              fontSize: numFs * 0.3,
              letterSpacing: 0,
              marginLeft: 0.04 * numFs,
              color: c.dim,
              fontWeight: 400,
            }}
          >
            m
          </span>
        </div>
      </div>

      {/* TOUCHDOWN CONFIRMED: slams, then lifts away as the label fades in. */}
      {t >= SLAM_AT - 1 && exit < 1 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H * 0.47,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            fontFamily: sans,
            fontWeight: 500,
            fontSize: 148 * u,
            letterSpacing: "-0.035em",
            lineHeight: 0.96,
            textTransform: "uppercase",
            color: c.ink,
            whiteSpace: "nowrap",
            transform: `translateY(-50%) translateY(${-exit * 110 * u}px) scale(${(1.22 - 0.22 * slam) * (1 + 0.02 * slamHit) * (1 - 0.12 * exit)})`,
            opacity: ramp(slam, 0, 0.2) * (1 - exit),
          }}
        >
          <span>{confirmA}</span>
          <span>{confirmB}</span>
        </div>
      ) : null}
      <div
        style={{
          ...small,
          position: "absolute",
          left: 0,
          right: 0,
          top: 86 * u,
          textAlign: "center",
          fontSize: 20 * u,
          letterSpacing: "0.18em",
          opacity: labelIn,
          transform: `translateY(${(1 - labelIn) * 14 * u}px)`,
        }}
      >
        {confirm}
      </div>

      {/* Resolve. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: H * 0.45,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: "translateY(-50%)",
        }}
      >
        <div
          style={{
            fontFamily: sans,
            fontWeight: 500,
            fontSize: 196 * u,
            lineHeight: 1,
            letterSpacing: "-0.045em",
            textTransform: "uppercase",
            whiteSpace: "nowrap",
            paddingRight: "0.02em",
            backgroundImage: c.titleFill,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            opacity: ramp(titleIn, 0, 0.25),
            transform: `scale(${(1.2 - 0.2 * titleIn) * (1 + 0.02 * titleHit)})`,
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontFamily: serif,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: 84 * u,
            lineHeight: 1.1,
            letterSpacing: "-0.01em",
            color: c.ink,
            whiteSpace: "nowrap",
            marginTop: 4 * u,
            opacity: subIn,
            transform: `translateY(${(1 - subIn) * 28 * u}px)`,
          }}
        >
          {subtitle}
        </div>
      </div>

      {/* Logo on the pad. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: padY + 28 * u,
          display: "flex",
          justifyContent: "center",
          opacity: logoIn,
          transform: `translateY(${(1 - logoIn) * 18 * u}px)`,
        }}
      >
        {logo ?? <RemocnLogo fontSize={40 * u} color={c.ink} />}
      </div>

      {flash ? (
        <div style={{ position: "absolute", inset: 0, background: c.flash }} />
      ) : null}
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/Sora";
import React, { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

/**
 * gradients.sh "halo" palette: [#fff4ec, #ffb36b, #e2457a, #3d4dff]. The ring
 * that circles the day is drawn in it, tightens into a full stop that keeps
 * it, and leaves a soft halo ring behind the lockup. The blue end is the
 * accent, so the palette lands on the brand.
 */
const HALO = ["#fff4ec", "#ffb36b", "#e2457a", "#3d4dff"] as const;

/**
 * Beat sheet (30fps, speed 1):
 * 0–30     the month draws itself as hairlines; header and day numbers settle.
 * 14–44    days light up in a quick sweep from the 1st to the launch day.
 * 30–88    slow eased push toward the launch day; the rest of the grid
 *          drifts out of focus.
 * 66–90    an accent stroke circles the day.
 * 92–124   the grid falls away; the day slides into a huge "10.30" lockup
 *          while the circle tightens into the accent full stop.
 * 120–180  label lands, long hold.
 */

interface LaunchDateValue {
  /** 1–12. */
  month: number;
  day: number;
  year: number;
}

interface LaunchDateProps {
  date?: LaunchDateValue;
  /** Short line under the lockup. */
  label?: string;
  /** "month-day" renders 10.30, "day-month" renders 30.10. */
  order?: "month-day" | "day-month";
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
const WEEKDAYS = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday",
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_PUSH = Easing.bezier(0.5, 0, 0.3, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    stage: "rgba(255,255,255,0.055)",
    fg: "#F3F2EF",
    muted: "#85848A",
    faint: "#4A4A50",
    line: "rgba(255,255,255,0.13)",
    lit: "rgba(255,255,255,0.075)",
    grain: 0.065,
    /** Peak opacity of the halo behind the lockup. */
    halo: 1,
    /** Halo ring stops, top-left → bottom-right, before the accent. */
    haloStops: [HALO[0], HALO[1], HALO[2]],
  },
  light: {
    bg: "#F5F4F0",
    stage: "rgba(255,255,255,0.85)",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#B9B6AE",
    line: "rgba(18,18,20,0.13)",
    lit: "rgba(18,18,20,0.05)",
    grain: 0.045,
    halo: 0.9,
    haloStops: [HALO[1], HALO[1], HALO[2]],
  },
} as const;

type Palette = (typeof PALETTES)[keyof typeof PALETTES];

/** Day of week, 0 = Monday (Sakamoto). Pure arithmetic, no Date. */
function weekday(year: number, month: number, day: number) {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  const y = month < 3 ? year - 1 : year;
  const sun0 =
    (y +
      Math.floor(y / 4) -
      Math.floor(y / 100) +
      Math.floor(y / 400) +
      t[month - 1] +
      day) %
    7;
  return (sun0 + 6) % 7;
}

function daysIn(year: number, month: number) {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    return leap ? 29 : 28;
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

const pad = (n: number) => String(n).padStart(2, "0");

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface CellProps {
  t: number;
  day: number;
  col: number;
  row: number;
  cellW: number;
  cellH: number;
  hero: boolean;
  launchDay: number;
  heroRow: number;
  heroCol: number;
  p: Palette;
  u: number;
}

function DayCell({
  t,
  day,
  col,
  row,
  cellW,
  cellH,
  hero,
  launchDay,
  heroRow,
  heroCol,
  p,
  u,
}: CellProps) {
  // settle in with the grid
  const appear = interpolate(t, [8 + row * 2.5, 24 + row * 2.5], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  // sweep: day 1 → launch day across ~28 frames
  const step = 28 / Math.max(1, launchDay);
  const hit = 16 + (day - 1) * step;
  const swept = day <= launchDay;
  const flash = swept
    ? interpolate(t, [hit, hit + 3, hit + 14], [0, 1, 0], CLAMP)
    : 0;
  const after = swept ? interpolate(t, [hit, hit + 10], [0, 1], CLAMP) : 0;
  const numO = appear * (0.38 + 0.62 * flash + 0.22 * after * (1 - flash));
  // fall away: ripple outward from the launch day
  const dist = Math.hypot(col - heroCol, (row - heroRow) * 1.3);
  const f0 = 90 + dist * 2.2;
  const fall = interpolate(t, [f0, f0 + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_IN,
  });
  return (
    <div
      style={{
        position: "absolute",
        left: col * cellW,
        top: row * cellH,
        width: cellW,
        height: cellH,
        transform: `perspective(${900 * u}px) translateY(${fall * cellH * 0.9}px) rotateX(${-fall * 55}deg)`,
        transformOrigin: "50% 100%",
        opacity: 1 - fall,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 1.5 * u,
          borderRadius: 6 * u,
          background: p.lit,
          opacity: flash + (hero ? after * 0.9 : after * 0.25),
        }}
      />
      {hero ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: sora,
            fontWeight: 300,
            fontSize: cellH * 0.3,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: "-0.02em",
            color: p.fg,
            opacity: numO,
          }}
        >
          {day}
        </div>
      )}
    </div>
  );
}

function LaunchDateBase({
  date = { month: 10, day: 30, year: 2026 },
  label = "Coming soon",
  order = "month-day",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: LaunchDateProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const p: Palette = PALETTES[theme];

  const month = Math.min(12, Math.max(1, Math.round(date.month)));
  const total = daysIn(date.year, month);
  const launchDay = Math.min(total, Math.max(1, Math.round(date.day)));
  const lead = weekday(date.year, month, 1);
  const rows = Math.ceil((lead + total) / 7);

  // ---- calendar layout (grid space, origin at the grid's top-left) ----
  const cellH = Math.min(height * 0.64, height) / (rows + 1.7);
  const cellW = Math.min(cellH * 1.38, (width * 0.62) / 7);
  const gridW = cellW * 7;
  const headH = cellH * 1.1;
  const dowH = cellH * 0.6;
  const gridH = headH + dowH + rows * cellH;
  const bodyTop = headH + dowH;
  const heroIdx = lead + launchDay - 1;
  const heroCol = heroIdx % 7;
  const heroRow = Math.floor(heroIdx / 7);
  const heroGX = (heroCol + 0.5) * cellW;
  const heroGY = bodyTop + (heroRow + 0.5) * cellH;

  // ---- camera: screen = C + (g - F) * s ----
  const cx = width / 2;
  const cy = height * 0.5;
  const push = interpolate(t, [20, 90], [0, 1], {
    ...CLAMP,
    easing: EASE_PUSH,
  });
  const S = 2.5;
  const s =
    interpolate(push, [0, 1], [0.94, S]) *
    interpolate(t, [0, 20], [0.97, 1], CLAMP);
  const fx = interpolate(push, [0, 1], [gridW / 2, heroGX]);
  const fy = interpolate(push, [0, 1], [gridH / 2, heroGY]);
  const toScreen = (gx: number, gy: number) => ({
    x: cx + (gx - fx) * s,
    y: cy + (gy - fy) * s,
  });
  const gridOrigin = toScreen(0, 0);
  const dof = interpolate(push, [0.35, 1], [0, 2.4 * u], CLAMP);
  const linesOut = interpolate(t, [86, 104], [1, 0], CLAMP);
  const headOut = interpolate(t, [60, 84], [1, 0], CLAMP);

  // ---- lockup (screen space) ----
  const F = Math.min(height * 0.34, (width * 0.7) / 2.7);
  const groupW = F * 1.14;
  const dotW = F * 0.27;
  const lockW = groupW * 2 + dotW;
  const lockCY = height * 0.45;
  const lockLeft = cx - lockW / 2;
  const dayFirst = order === "day-month";
  const daySlotX = dayFirst
    ? lockLeft + groupW / 2
    : lockLeft + lockW - groupW / 2;
  const dotD = F * 0.135;
  const dotX = cx;
  const dotY = lockCY + F * 0.364 - dotD / 2;

  // hero day: follows its cell, then glides to the lockup slot
  const hand = interpolate(t, [92, 120], [0, 1], { ...CLAMP, easing: EASE_IO });
  const heroCell = toScreen(heroGX, heroGY);
  const heroFont0 = cellH * 0.3 * s;
  const heroX = interpolate(hand, [0, 1], [heroCell.x, daySlotX]);
  const heroY = interpolate(hand, [0, 1], [heroCell.y, lockCY]);
  const heroFont = interpolate(hand, [0, 1], [heroFont0, F]);
  const heroWeight = 300;
  const heroTrack = interpolate(hand, [0, 1], [-0.02, -0.06]);
  const heroAppear = interpolate(
    t,
    [8 + heroRow * 2.5, 24 + heroRow * 2.5],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const heroHit = 16 + (launchDay - 1) * (28 / Math.max(1, launchDay));
  const heroLit = interpolate(t, [heroHit, heroHit + 3], [0.38, 1], CLAMP);

  // circle: draws around the day, rides along with it, then tightens into
  // the full stop of the lockup
  const draw = interpolate(t, [64, 90], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const ringW0 = Math.max(2, 2.5 * u * (s / S));
  const rideR = heroFont * interpolate(hand, [0, 1], [1.2, 0.7]);
  const rideW = ringW0 * interpolate(hand, [0, 1], [1, 1.7]);
  const shrink = interpolate(t, [114, 136], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // stays a hairline while it tightens, fills only once it is dot-sized
  const close = interpolate(t, [124, 134], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const outerR = interpolate(shrink, [0, 1], [rideR + rideW / 2, dotD / 2]);
  const ringW = Math.min(outerR, interpolate(close, [0, 1], [rideW, outerR]));
  const ringR = outerR - ringW / 2;
  const ringX = interpolate(shrink, [0, 1], [heroX, dotX]);
  const ringY = interpolate(shrink, [0, 1], [heroY, dotY]);
  const ringBox = ringR + ringW + 4;
  const circ = 2 * Math.PI * ringR;
  const ringId = `ring${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  // the echo: as the full stop lands, the ring it came from rings out once
  // more, wide, and stays behind the lockup as a halo of the same light
  const echo = interpolate(t, [124, 164], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const echoR = dotD / 2 + (height * 0.37 - dotD / 2) * echo;
  const echoO = interpolate(t, [124, 130], [0, 1], CLAMP);
  const haloSpin = interpolate(t, [124, 195], [-30, 10], CLAMP);
  const haloId = `halo${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const blurId = `hb${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  // the other half of the lockup
  const other = interpolate(t, [128, 152], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelP = (d: number) =>
    interpolate(t, [140 + d, 164 + d], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const labelTop = lockCY + F * 0.5 + 40 * u;
  const otherValue = pad(month);
  const fullDate = `${WEEKDAYS[weekday(date.year, month, launchDay)]}, ${MONTHS[month - 1]} ${launchDay}, ${date.year}`;

  const lines: React.ReactNode[] = [];
  for (let r = 0; r <= rows; r++) {
    const d = r * 2;
    const k = interpolate(t, [d, d + 16], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    lines.push(
      <div
        key={`h${r}`}
        style={{
          position: "absolute",
          left: 0,
          top: bodyTop + r * cellH,
          width: gridW,
          height: Math.max(1, u),
          background: p.line,
          transformOrigin: "0 50%",
          transform: `scaleX(${k})`,
        }}
      />,
    );
  }
  for (let c = 1; c < 7; c++) {
    const d = 4 + c * 2;
    const k = interpolate(t, [d, d + 16], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    lines.push(
      <div
        key={`v${c}`}
        style={{
          position: "absolute",
          left: c * cellW,
          top: bodyTop,
          width: Math.max(1, u),
          height: rows * cellH,
          background: p.line,
          transformOrigin: "50% 0",
          transform: `scaleY(${k})`,
        }}
      />,
    );
  }

  const cells: React.ReactNode[] = [];
  for (let d = 1; d <= total; d++) {
    const i = lead + d - 1;
    cells.push(
      <DayCell
        key={d}
        t={t}
        day={d}
        col={i % 7}
        row={Math.floor(i / 7)}
        cellW={cellW}
        cellH={cellH}
        hero={d === launchDay}
        launchDay={launchDay}
        heroRow={heroRow}
        heroCol={heroCol}
        p={p}
        u={u}
      />,
    );
  }

  // a slow push that never quite stops, so the hold stays alive
  const drift = interpolate(t, [90, 195], [1, 1.035], CLAMP);
  const headIn = interpolate(t, [4, 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 70% at 50% 40%, ${p.stage}, transparent 75%)`,
        }}
      />

      <AbsoluteFill style={{ transform: `scale(${drift})` }}>
        {echoO > 0 ? (
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            aria-hidden
          >
            <defs>
              <linearGradient
                id={haloId}
                gradientUnits="userSpaceOnUse"
                x1={dotX - echoR}
                y1={lockCY - echoR}
                x2={dotX + echoR}
                y2={lockCY + echoR}
                gradientTransform={`rotate(${haloSpin} ${dotX} ${lockCY})`}
              >
                <stop offset="0%" stopColor={p.haloStops[0]} />
                <stop offset="38%" stopColor={p.haloStops[1]} />
                <stop offset="70%" stopColor={p.haloStops[2]} />
                <stop offset="100%" stopColor={accent} />
              </linearGradient>
              <filter id={blurId} x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={16 * u} />
              </filter>
            </defs>
            <g opacity={echoO * p.halo}>
              <circle
                cx={dotX}
                cy={lockCY}
                r={echoR}
                fill="none"
                stroke={`url(#${haloId})`}
                strokeWidth={34 * u}
                filter={`url(#${blurId})`}
                opacity={0.55}
              />
              <circle
                cx={dotX}
                cy={lockCY}
                r={echoR}
                fill="none"
                stroke={`url(#${haloId})`}
                strokeWidth={interpolate(echo, [0, 1], [4, 1.6]) * u}
              />
            </g>
          </svg>
        ) : null}
        {/* the month, in grid space under the camera */}
        <div
          style={{
            position: "absolute",
            left: gridOrigin.x,
            top: gridOrigin.y,
            width: gridW,
            height: gridH,
            transformOrigin: "0 0",
            transform: `scale(${s})`,
            filter: dof > 0.05 ? `blur(${dof / s}px)` : undefined,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: cellW * 0.12,
              right: cellW * 0.12,
              top: 0,
              height: headH,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              opacity: headIn * headOut,
              transform: `translateY(${(1 - headIn) * 10 * u}px)`,
            }}
          >
            <span
              style={{
                fontFamily: sora,
                fontWeight: 500,
                fontSize: cellH * 0.5,
                letterSpacing: "-0.04em",
                color: p.fg,
              }}
            >
              {MONTHS[month - 1]}
            </span>
            <span
              style={{
                fontFamily: sora,
                fontWeight: 400,
                fontSize: cellH * 0.3,
                letterSpacing: "-0.02em",
                fontVariantNumeric: "tabular-nums",
                color: p.muted,
              }}
            >
              {date.year}
            </span>
          </div>
          <div
            style={{
              position: "absolute",
              left: 0,
              top: headH,
              width: gridW,
              height: dowH,
              display: "flex",
              opacity: headIn * headOut,
            }}
          >
            {WEEKDAYS.map((w, i) => (
              <div
                key={w}
                style={{
                  width: cellW,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontFamily: sora,
                  fontWeight: 400,
                  fontSize: cellH * 0.17,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase",
                  color: i > 4 ? p.faint : p.muted,
                }}
              >
                {w.slice(0, 3)}
              </div>
            ))}
          </div>
          <div style={{ position: "absolute", inset: 0, opacity: linesOut }}>
            {lines}
          </div>
          <div style={{ position: "absolute", left: 0, top: bodyTop }}>
            {cells}
          </div>
        </div>

        {/* accent ring → full stop */}
        <svg
          width={ringBox * 2}
          height={ringBox * 2}
          viewBox={`${-ringBox} ${-ringBox} ${ringBox * 2} ${ringBox * 2}`}
          style={{
            position: "absolute",
            left: ringX - ringBox,
            top: ringY - ringBox,
            overflow: "visible",
          }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={ringId}
              gradientUnits="userSpaceOnUse"
              x1={-ringBox}
              y1={-ringBox}
              x2={ringBox}
              y2={ringBox}
            >
              <stop offset="8%" stopColor={HALO[1]} />
              <stop offset="50%" stopColor={HALO[2]} />
              <stop offset="92%" stopColor={accent} />
            </linearGradient>
          </defs>
          <circle
            r={ringR}
            fill="none"
            stroke={`url(#${ringId})`}
            strokeWidth={ringW}
            strokeLinecap="round"
            strokeDasharray={circ}
            strokeDashoffset={circ * (1 - draw)}
            transform="rotate(-118)"
          />
        </svg>

        {/* the launch day, in screen space so it can leave the grid */}
        <div
          style={{
            position: "absolute",
            left: heroX - F * 2,
            top: heroY - F,
            width: F * 4,
            height: F * 2,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: sora,
            fontWeight: heroWeight,
            fontSize: heroFont,
            lineHeight: 1,
            letterSpacing: `${heroTrack}em`,
            fontVariantNumeric: "tabular-nums",
            color: p.fg,
            opacity: heroAppear * heroLit,
            filter:
              dof > 0.05 && hand < 0.01 ? `blur(${dof * 0.15}px)` : undefined,
          }}
        >
          {pad(launchDay)}
        </div>

        {/* the other half of the lockup, revealed from behind the full stop */}
        <div
          style={{
            position: "absolute",
            left: dayFirst ? cx + dotW / 2 : lockLeft,
            top: lockCY - F,
            width: groupW,
            height: F * 2,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: sora,
              fontWeight: 300,
              fontSize: F,
              lineHeight: 1,
              letterSpacing: "-0.06em",
              fontVariantNumeric: "tabular-nums",
              color: p.fg,
              opacity: other,
              transform: `translateX(${(dayFirst ? -1 : 1) * (1 - other) * groupW * 0.55}px)`,
            }}
          >
            {otherValue}
          </div>
        </div>

        {/* label */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: labelTop,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: 16 * u,
            fontFamily: sora,
            fontSize: 21 * u,
            lineHeight: 1,
          }}
        >
          <span
            style={{
              color: p.fg,
              fontWeight: 500,
              letterSpacing: "-0.02em",
              opacity: labelP(0),
              transform: `translateY(${(1 - labelP(0)) * 12 * u}px)`,
            }}
          >
            {label}
          </span>
          <div
            style={{
              width: Math.max(1, u),
              height: 20 * u,
              background: p.line,
              transform: `scaleY(${labelP(3)})`,
            }}
          />
          <span
            style={{
              color: p.muted,
              fontWeight: 400,
              letterSpacing: "-0.015em",
              fontVariantNumeric: "tabular-nums",
              opacity: labelP(6),
              transform: `translateY(${(1 - labelP(6)) * 12 * u}px)`,
            }}
          >
            {fullDate}
          </span>
        </div>
      </AbsoluteFill>
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

