  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","label","order","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  label: "Coming soon",
  order: "month-day",
  speed: 1,
};

type LaunchDateElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LaunchDateBase>;

const LaunchDateInner = forwardRef<
  HTMLDivElement,
  LaunchDateElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LaunchDate>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LaunchDateBase
          {...(componentProps as unknown as ComponentProps<typeof LaunchDateBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LaunchDate = Interactive.withSchema({
  Component: LaunchDateInner,
  componentName: "<LaunchDate>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

