    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","less","more","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  less: "Less explaining.",
  more: "More showing.",
  speed: 1,
};

type LessMoreElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LessMoreBase>;

const LessMoreInner = forwardRef<
  HTMLDivElement,
  LessMoreElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LessMore>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LessMoreBase
          {...(componentProps as unknown as ComponentProps<typeof LessMoreBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LessMore = Interactive.withSchema({
  Component: LessMoreInner,
  componentName: "<LessMore>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

