  word: {
    type: "text-content",
    default: "remocn",
    description: "Word",
  },
  mark: {
    type: "boolean",
    default: true,
    description: "Mark",
  },
  hop: {
    type: "number",
    default: 10,
    min: 0,
    max: 30,
    step: 1,
    description: "Hop",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","mark","hop","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "remocn",
  mark: true,
  hop: 10,
  speed: 1,
};

type LetterRelayElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LetterRelayBase>;

const LetterRelayInner = forwardRef<
  HTMLDivElement,
  LetterRelayElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LetterRelay>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LetterRelayBase
          {...(componentProps as unknown as ComponentProps<typeof LetterRelayBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LetterRelay = Interactive.withSchema({
  Component: LetterRelayInner,
  componentName: "<LetterRelay>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

