const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","beat","hold","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "SHIP IT.",
  beat: 10,
  hold: 24,
  speed: 1,
};

type LightsOutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LightsOutBase>;

const LightsOutInner = forwardRef<
  HTMLDivElement,
  LightsOutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LightsOut>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LightsOutBase
          {...(componentProps as unknown as ComponentProps<typeof LightsOutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LightsOut = Interactive.withSchema({
  Component: LightsOutInner,
  componentName: "<LightsOut>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

