function layoutGlyphs(value: string) {
  const strokes: Pt[][] = [];
  const segs: Seg[] = [];
  let x = 0;
  const chars = Array.from(value);
  chars.forEach((ch, i) => {
    const g = GLYPHS[ch] ?? { advance: 0.4, strokes: [] };
    for (const s of g.strokes) {
      const moved = s.map(([px, py]) => [px + x, py] as Pt);
      strokes.push(moved);
      for (let k = 0; k < Math.max(1, moved.length - 1); k++) {
        const a = moved[k];
        const b = moved[Math.min(k + 1, moved.length - 1)];
        segs.push([a[0], a[1], b[0], b[1]]);
      }
    }
    x += g.advance + (i < chars.length - 1 ? TRACK : 0);
  });
  return { strokes, segs, width: x };
}

function segDist(px: number, py: number, s: Seg) {
  const [ax, ay, bx, by] = s;
  const dx = bx - ax;
  const dy = by - ay;
  const l2 = dx * dx + dy * dy;
  const t =
    l2 === 0
      ? 0
      : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / l2));
  const qx = ax + dx * t - px;
  const qy = ay + dy * t - py;
  return Math.sqrt(qx * qx + qy * qy);
}

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

type Slot = {
  x: number;
  top: number;
  bottom: number;
  land: number;
  fall: number;
};

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function LineCascadeBase({
  value = "240",
  caption = "launch films rendered with remocn today",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: LineCascadeProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const stage = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const maskId = `m${uid}`;
  const fluteId = `f${uid}`;
  const fluteGlyphId = `fg${uid}`;
  const isDark = theme === "dark";
  const flute: Array<[number, string]> = isDark
    ? [
        [0, FLUTED[3]],
        [0.3, FLUTED[2]],
        [0.66, accent],
        [1, FLUTED[0]],
      ]
    : [
        [0, FLUTED[2]],
        [0.6, accent],
        [1, FLUTED[0]],
      ];

  const layout = useMemo(() => layoutGlyphs(value), [value]);
  const capSize = 24 * u;
  const gapBelow = 34 * u;
  const glyphH = Math.min(0.5 * H, (0.74 * W) / Math.max(layout.width, 0.5));
  const glyphW = layout.width * glyphH;
  const blockH = glyphH + (caption ? gapBelow + capSize * 1.3 : 0);
  const gx = (W - glyphW) / 2;
  const gy = (H - blockH) / 2 + 4 * u;
  const floorY = gy + glyphH;

  const pitch = 6.5 * u;
  const slotH = 13 * u;
  const hair = Math.max(1.5, 1.6 * u);
  const gapY = 3 * u;
  const lineLen = slotH - gapY;
  const fallSpeed = 0.072 * H;

  const slots = useMemo(() => {
    const out: Slot[] = [];
    const cols = Math.floor(glyphW / pitch);
    const offset = (glyphW - cols * pitch) / 2;
    const step = 1.5 * u;
    for (let c = 0; c < cols; c++) {
      const x = gx + offset + (c + 0.5) * pitch;
      const ux = (x - gx) / glyphH;
      const intervals: Array<[number, number]> = [];
      let start = -1;
      for (let y = gy - R * glyphH; y <= floorY + R * glyphH; y += step) {
        const uy = (y - gy) / glyphH;
        let inside = false;
        for (const s of layout.segs) {
          if (segDist(ux, uy, s) <= R) {
            inside = true;
            break;
          }
        }
        if (inside && start < 0) start = y;
        if (!inside && start >= 0) {
          intervals.push([start, y - step]);
          start = -1;
        }
      }
      if (start >= 0) intervals.push([start, floorY]);
      const colRate = 0.88 + 0.24 * hash(c * 3.1 + 7);
      const colLag = 5 * hash(c * 1.7 + 2);
      intervals.forEach(([a, b], iv) => {
        let bottom = b;
        let j = 0;
        while (bottom - a > 0.45 * slotH) {
          const top = Math.max(a, bottom - slotH);
          const level = (floorY - bottom) / glyphH;
          const jitter = 4 * hash(c * 91.7 + iv * 13.1 + j * 5.3);
          const land = Math.min(
            SNAP_AT - 5,
            RAIN_AT + 12 + level * RAIN_SPAN * colRate + colLag + jitter,
          );
          const target = bottom - gapY / 2;
          const fall = (target + lineLen * 3) / fallSpeed;
          out.push({ x, top: top + gapY / 2, bottom: target, land, fall });
          bottom = top;
          j++;
        }
      });
    }
    return out;
  }, [
    layout,
    gx,
    gy,
    glyphW,
    glyphH,
    floorY,
    pitch,
    slotH,
    gapY,
    lineLen,
    u,
    fallSpeed,
  ]);

  const floorDraw = EASE_IO(
    interpolate(t, [FLOOR_AT, FLOOR_END], [0, 1], CLAMP),
  );
  const floorFade = interpolate(t, [SNAP_AT, SNAP_END + 6], [1, 0], CLAMP);
  const snap = EASE_OUT(interpolate(t, [SNAP_AT, SNAP_END], [0, 1], CLAMP));
  const solid = EASE_IO(
    interpolate(t, [SNAP_AT + 2, SNAP_END - 1], [0, 1], CLAMP),
  );
  const pileOut = interpolate(t, [SNAP_END - 3, SNAP_END + 1], [1, 0], CLAMP);
  const pileOpacity = stage.pile + (1 - stage.pile) * snap;
  const lineW = hair + (pitch + 0.6 * u - hair) * snap;
  const growY = gapY * snap;
  const capIn = EASE_OUT(
    interpolate(t, [CAPTION_AT, CAPTION_AT + 16], [0, 1], CLAMP),
  );

  const falling: React.ReactNode[] = [];
  const landed: React.ReactNode[] = [];
  slots.forEach((s, i) => {
    if (t >= s.land) {
      landed.push(
        <rect
          key={i}
          x={s.x - lineW / 2}
          y={s.top - growY / 2}
          width={lineW}
          height={s.bottom - s.top + growY}
        />,
      );
      return;
    }
    const startT = s.land - s.fall;
    if (t < startT) return;
    const p = (t - startT) / s.fall;
    const head = -lineLen * 3 + p * (s.bottom + lineLen * 3);
    const streak = lineLen * (1 + 1.6 * Math.min(1, (1 - p) * 4));
    falling.push(
      <rect
        key={i}
        x={s.x - hair / 2}
        y={head - streak}
        width={hair}
        height={streak}
      />,
    );
  });

  return (
    <AbsoluteFill style={{ background: stage.bg, overflow: "hidden" }}>
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={fluteId}
            gradientUnits="userSpaceOnUse"
            x1={0}
            x2={0}
            y1={gy - R * glyphH}
            y2={floorY + R * glyphH}
          >
            {flute.map(([o, c]) => (
              <stop key={o} offset={o} stopColor={c} />
            ))}
          </linearGradient>
          <linearGradient
            id={fluteGlyphId}
            gradientUnits="userSpaceOnUse"
            x1={0}
            x2={0}
            y1={-R}
            y2={1 + R}
          >
            {flute.map(([o, c]) => (
              <stop key={o} offset={o} stopColor={c} />
            ))}
          </linearGradient>
          <mask
            id={maskId}
            maskUnits="userSpaceOnUse"
            x={0}
            y={0}
            width={W}
            height={H}
          >
            <g
              transform={`translate(${gx} ${gy}) scale(${glyphH})`}
              fill="none"
              stroke="#fff"
              strokeWidth={STROKE}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              {layout.strokes.map((s, i) => (
                <path
                  key={i}
                  d={`M${s.map((p) => `${p[0]} ${p[1]}`).join("L")}`}
                />
              ))}
            </g>
          </mask>
        </defs>
        <rect
          x={gx - 0.04 * W}
          y={floorY + 8 * u}
          width={(glyphW + 0.08 * W) * floorDraw}
          height={Math.max(1, u)}
          fill={stage.floor}
          opacity={floorFade}
        />
        <g fill={stage.fg} opacity={stage.rain * (1 - snap)}>
          {falling}
        </g>
        <g
          transform={`translate(${gx} ${gy}) scale(${glyphH})`}
          fill="none"
          stroke={`url(#${fluteGlyphId})`}
          strokeWidth={STROKE}
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity={solid}
        >
          {layout.strokes.map((s, i) => (
            <path key={i} d={`M${s.map((p) => `${p[0]} ${p[1]}`).join("L")}`} />
          ))}
        </g>
        <g
          mask={`url(#${maskId})`}
          fill={`url(#${fluteId})`}
          opacity={pileOpacity * pileOut}
        >
          {landed}
        </g>
      </svg>
      {caption ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: floorY + gapBelow + (1 - capIn) * 10 * u,
            textAlign: "center",
            fontFamily: sans,
            fontWeight: 400,
            fontSize: capSize,
            letterSpacing: "-0.005em",
            lineHeight: 1.3,
            color: stage.muted,
            opacity: capIn,
          }}
        >
          {caption
            .split(/(remocn)/i)
            .map((part, i) =>
              /^remocn$/i.test(part) ? (
                <RemocnLogo key={i} color={stage.fg} />
              ) : (
                part
              ),
            )}
        </div>
      ) : null}
      <Grain opacity={stage.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  value: {
    type: "text-content",
    default: "240",
    description: "Value",
  },
  caption: {
    type: "text-content",
    default: "launch films rendered with remocn today",
    description: "Caption",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","caption","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "240",
  caption: "launch films rendered with remocn today",
  speed: 1,
};

type LineCascadeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LineCascadeBase>;

const LineCascadeInner = forwardRef<
  HTMLDivElement,
  LineCascadeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LineCascade>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LineCascadeBase
          {...(componentProps as unknown as ComponentProps<typeof LineCascadeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LineCascade = Interactive.withSchema({
  Component: LineCascadeInner,
  componentName: "<LineCascade>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

