function fmtTime(sec: number, format: "clock" | "minutes") {
  if (format === "minutes") return `${Math.max(1, Math.ceil(sec / 60))} min`;
  const s = Math.max(0, Math.round(sec));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function Ticker({
  value,
  prev,
  since,
  style,
}: {
  value: string;
  prev: string;
  since: number;
  style: React.CSSProperties;
}) {
  const t = enterE(Math.min(1, since / 4));
  const chars = Array.from(value);
  const old = Array.from(prev.padStart(chars.length, " "));
  return (
    <span
      style={{
        display: "inline-flex",
        fontVariantNumeric: "tabular-nums",
        ...style,
      }}
    >
      {chars.map((ch, i) => {
        const changed = old[i] !== ch && prev.length === value.length;
        return (
          <span
            key={i}
            style={{
              position: "relative",
              display: "inline-block",
              whiteSpace: "pre",
              overflow: "hidden",
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: changed ? `translateY(${(1 - t) * 45}%)` : undefined,
                opacity: changed ? t : 1,
              }}
            >
              {ch}
            </span>
            {changed && t < 1 ? (
              <span
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  transform: `translateY(${-t * 45}%)`,
                  opacity: 1 - t,
                }}
              >
                {old[i]}
              </span>
            ) : null}
          </span>
        );
      })}
    </span>
  );
}

