          position: "relative",
        }}
      >
        <div
          style={{
            width: "100%",
            maxWidth: 560,
            position: "relative",
            borderRadius: 14,
            padding: 1,
            background:
              "linear-gradient(180deg, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0.02) 50%, rgba(255,255,255,0.06) 100%)",
            boxShadow: "0 30px 80px rgba(0,0,0,0.5), 0 0 0 1px rgba(0,0,0,0.4)",
          }}
        >
          <div
            style={{
              borderRadius: 13,
              background: "rgba(12,12,14,0.85)",
