                        ))
                      )}
                      {isLast && cursorVisible && (
                        <span
                          style={{
                            display: "inline-block",
                            width: 8,
                            height: 16,
                            marginLeft: 1,
                            verticalAlign: "text-bottom",
                            background: accentColor,
                          }}
                        />
                      )}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      {/* RIGHT: Live preview */}
      <div
        style={{
          flex: 1,
          position: "relative",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
