                  <span
                    style={{
                      position: "absolute",
                      inset: 0,
                      borderRadius: 4,
                      background: c.live,
                      opacity: (1 - pulse) * 0.45,
                      transform: `scale(${1 + pulse * 1.8})`,
                    }}
                  />
                  <span
                    style={{
                      position: "absolute",
                      inset: 0,
                      borderRadius: 4,
                      background: c.live,
