                      boxShadow:
                        [
                          col > 0 ? `inset 1px 0 0 ${c.rule}` : null,
                          row > 0 ? `inset 0 1px 0 ${c.rule}` : null,
                        ]
                          .filter(Boolean)
                          .join(", ") || "none",
                      opacity: clamp01(enter * 1.5),
                      transform: `translateY(${(1 - enter) * 22}px)`,
                    }}
                  >
                    <div
                      style={{ display: "flex", fontSize: 16, color: c.muted }}
                    >
                      {m.label}
                      <span
                        style={{
                          marginLeft: "auto",
                          color: good ? c.good : c.bad,
                          fontVariantNumeric: "tabular-nums",
                          opacity: interpolate(
                            frame,
                            [B.kpi + 30 + i * 3, B.kpi + 40 + i * 3],
                            [0, 1],
                            {
                              ...clamp,
                              easing: ENTER,
                            },
                          ),
                        }}
                      >
                        {m.change >= 0 ? "+" : ""}
                        {m.change.toFixed(1)}%
                      </span>
                    </div>
                    <div
                      style={{
                        fontSize: 30,
                        fontWeight: 300,
                        color: c.text,
                        marginTop: 6,
                        height: 36,
                        lineHeight: "36px",
                        fontVariantNumeric: "tabular-nums",
                        letterSpacing: "-0.03em",
                      }}
                    >
                      {step && ticksDone > 0 ? (
                        <Rolling
                          from={m.value + step * (ticksDone - 1)}
                          to={m.value + step * ticksDone}
                          t={lastTickT - 2}
                          fmt={fmt}
                          lineHeight={36}
                        />
                      ) : (
                        fmt(m.value * roll)
                      )}
                    </div>
                    <div style={{ marginTop: 10, marginBottom: 14 }}>
                      <Sparkline
                        values={spark}
                        w={kpiW - 44}
                        h={tall ? 48 : 34}
                        p={sparkP}
                        color={good ? accent : c.faint}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

