] as const;

// The wordmark, set like the site header: R is 0.76em tall, "emocn" Manrope 600 at -0.025em.
const FONT = H / 0.76;
const X_HEIGHT = 0.54;
const WORD_XLINE = H - FONT * X_HEIGHT;
const TRACK = -0.025;
/** Manrope 600 advances, per em. */
const ADV: Record<string, number> = {
  a: 0.57,
  c: 0.568,
  e: 0.596,
  i: 0.264,
  l: 0.264,
  m: 0.882,
