} as const;

const WGHT = 400;
const TRACK = -0.035;
const SERIF_TRACK = -0.01;
const PX = 200;
const CHIP_H = 0.74;
const CHIP_GAP = 0.14;

const TYPE_IN = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const MORPH = { damping: 200 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Measure = { sans: (s: string) => number; serif: (s: string) => number };

function buildMetrics(_version: number): Measure {
  const ctx = document.createElement("canvas").getContext("2d");
  const make = (font: string, track: number) => {
    const cache: Record<string, number> = {};
    return (s: string) => {
      if (cache[s] === undefined) {
        if (!ctx) return s.length * 0.5;
        ctx.font = font;
        cache[s] = ctx.measureText(s).width / PX + track * Array.from(s).length;
      }
      return cache[s];
    };
  };
  return {
    sans: make(`${WGHT} ${PX}px "${onest.fontFamily}"`, TRACK),
    serif: make(`italic 400 ${PX}px "${serif.fontFamily}"`, SERIF_TRACK),
  };
}

function useMetrics() {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("looks-like-this: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      onest.waitUntilDone(),
      serif.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${onest.fontFamily}"`),
      document.fonts.load(`italic 400 100px "${serif.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle]);
  return useMemo(() => buildMetrics(version), [version]);
}

interface Token {
  w: number;
  gap: number;
  glue?: boolean;
}

interface Placed {
  x: number;
  y: number;
}

function layout(
  tokens: Token[],
  size: number,
  maxW: number,
  centerX: number,
  topY: number,
  leading: number,
) {
  const lines: number[][] = [[]];
  let run = 0;
  tokens.forEach((t, i) => {
    const line = lines[lines.length - 1];
    const add = (line.length > 0 ? t.gap : 0) + t.w;
    if (line.length > 0 && (run + add) * size > maxW) {
      if (t.glue && line.length > 1) {
        const prev = line.pop() as number;
        lines.push([prev, i]);
        run = tokens[prev].w + t.gap + t.w;
      } else {
        lines.push([i]);
        run = t.w;
      }
    } else {
      line.push(i);
      run += add;
    }
  });
  const placed: Placed[] = new Array(tokens.length);
  lines.forEach((line, li) => {
    const total = line.reduce(
      (acc, i, k) => acc + tokens[i].w + (k > 0 ? tokens[i].gap : 0),
      0,
    );
    let x = centerX - (total * size) / 2;
    line.forEach((i, k) => {
      if (k > 0) x += tokens[i].gap * size;
      placed[i] = { x, y: topY + li * leading * size };
      x += tokens[i].w * size;
    });
  });
  return { placed, lines: lines.length };
}

function PlayGlyph({ size, color }: { size: number; color: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden>
      <path
        d="M8 5.8 L18 12 L8 18.2 Z"
        fill={color}
        stroke={color}
        strokeWidth="1.5"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function LooksLikeThis({
  lead = "Your next launch looks like",
  word = "this",
  end = ".",
  src,
  aspect = 16 / 9,
  duration = "0:30",
  accent,
  background,
  speed = 1,
  theme = "dark",
  ground,
  groundParams,
}: LooksLikeThisProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, fps, durationInFrames: D } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const image = src ?? staticFile("hero.png");
  const m = useMetrics();

  const words = lead.split(/\s+/).filter(Boolean);
  const k = Math.min(1.6, Math.max(0.6, D / 150));
  const t = frame * speed;
  const portrait = H > W * 1.1;
  const u = portrait ? W / 1080 : W / 1280;
  const sp = m.sans(" ");
  const chipW = CHIP_H * aspect;
  const leading = 1.08;
  const wordW = m.serif(word);
  const endW = m.sans(end);

  const tokensA: Token[] = [
    ...words.map((wd) => ({ w: m.sans(wd), gap: sp })),
    { w: chipW + CHIP_GAP * 2 + endW, gap: sp - CHIP_GAP, glue: true },
  ];
  const tokensB: Token[] = [
    ...words.map((wd) => ({ w: m.sans(wd), gap: sp })),
    { w: wordW + endW, gap: sp, glue: true },
  ];

  const maxW = W * (portrait ? 0.84 : 0.8);
  const lineA = tokensA.reduce(
    (acc, tk, i) => acc + tk.w + (i > 0 ? tk.gap : 0),
    0,
  );
  const sizeA = Math.max(
    portrait ? W * 0.095 : H * 0.075,
    Math.min(portrait ? W * 0.12 : H * 0.12, maxW / lineA),
  );
  const sizeB = portrait ? W * 0.085 : H * 0.074;

  const probeA = layout(tokensA, sizeA, maxW, W / 2, 0, leading);
  const blockA = (probeA.lines - 1) * leading * sizeA + sizeA;
  const A = layout(tokensA, sizeA, maxW, W / 2, (H - blockA) / 2, leading);

  const probeB = layout(tokensB, sizeB, maxW, W / 2, 0, leading);
  const blockB = (probeB.lines - 1) * leading * sizeB + sizeB;
  const gapB = H * (portrait ? 0.035 : 0.05);
  const heroMaxW = W * (portrait ? 0.86 : 0.72);
  const heroAspect = portrait ? Math.min(aspect, 1) : aspect;
  const heroRoom = H * (portrait ? 0.78 : 0.8) - blockB - gapB;
  const heroH = Math.min(heroRoom, heroMaxW / heroAspect);
  const heroW = heroH * heroAspect;
  const topB = portrait ? (H - (blockB + gapB + heroH)) / 2 : H * 0.085;
  const B = layout(tokensB, sizeB, maxW, W / 2, topB, leading);
  const hero = {
    x: (W - heroW) / 2,
    y: topB + blockB + gapB,
    w: heroW,
    h: heroH,
  };

  const CHIP_AT = 12 * k;
  const GROW_AT = 48 * k;
  const GROW_LEN = 30 * k;

  const p = interpolate(t, [GROW_AT, GROW_AT + GROW_LEN], [0, 1], {
    ...CLAMP,
    easing: MOVE,
  });
  const pChip = spring({
    frame: t - GROW_AT - 4 * k,
    fps,
    config: MORPH,
    durationInFrames: GROW_LEN + 2 * k,
  });
  const lerp = (a: number, b: number, q: number) => a + (b - a) * q;
  const size = lerp(sizeA, sizeB, p);

  const last = words.length;
  const slotA = A.placed[last];
  const chipRect0 = {
    x: slotA.x + CHIP_GAP * sizeA,
    y: slotA.y + sizeA * (0.6 - CHIP_H / 2),
    w: chipW * sizeA,
    h: CHIP_H * sizeA,
  };
  const chipOpen = spring({ frame: t - CHIP_AT, fps, config: CARD });
  const chipY = lerp(chipRect0.y, hero.y, pChip);
  const lineFloor = lerp(slotA.y, B.placed[words.length].y, p) + size * 1.14;
  const leave = interpolate(pChip, [0, 0.14], [0, 1], CLAMP);
  const chip = {
    x: lerp(chipRect0.x, hero.x, pChip),
    y: lerp(chipY, Math.max(chipY, lineFloor), leave),
    w: lerp(chipRect0.w, hero.w, pChip),
    h: lerp(chipRect0.h, hero.h, pChip),
  };
  const radius = lerp(sizeA * 0.12, 16 * u, pChip);
  const settle = interpolate(t, [GROW_AT + GROW_LEN, D], [1.04, 1], {
    ...CLAMP,
    easing: TYPE_IN,
  });
  const imgScale = lerp(1.2, settle, pChip);

  const endA = {
    x: slotA.x + (CHIP_GAP * 2 + chipW) * sizeA,
    y: slotA.y,
  };
  const slotB = B.placed[last];
  const endB = { x: slotB.x + wordW * sizeB, y: slotB.y };
  const endY = lerp(endA.y, endB.y, p);

  const wordIn = interpolate(
    t,
    [GROW_AT + GROW_LEN * 0.4, GROW_AT + GROW_LEN + 4 * k],
    [0, 1],
    { ...CLAMP, easing: TYPE_IN },
  );

  const prevA = A.placed[last - 1];
  const prevB = B.placed[last - 1];
  const wordX =
    last > 0
      ? lerp(prevA.x, prevB.x, p) + (m.sans(words[last - 1]) + sp) * size
      : lerp(slotA.x, slotB.x, p);

  const endX = lerp(
    endA.x,
    wordX + wordW * size,
    interpolate(p, [0, 0.55], [0, 1], { ...CLAMP, easing: TYPE_IN }),
  );

  const chrome = interpolate(
    t,
    [GROW_AT + GROW_LEN, GROW_AT + GROW_LEN + 12 * k],
    [0, 1],
    { ...CLAMP, easing: TYPE_IN },
  );
  const play = interpolate(t, [GROW_AT + GROW_LEN, D], [0.04, 0.32], CLAMP);
  const totalSec = (() => {
    const [mm, ss] = duration.split(":").map((v) => Number.parseInt(v, 10));
    return (mm || 0) * 60 + (ss || 0);
  })();
  const nowSec = Math.floor(play * totalSec);
  const stamp = `${Math.floor(nowSec / 60)}:${String(nowSec % 60).padStart(2, "0")}`;
  const label = Math.max(17 * u, H * 0.024);
  const flat = background !== undefined;

  const textStyle = {
    position: "absolute" as const,
    left: 0,
    top: 0,
    fontFamily: onest.fontFamily,
    fontWeight: WGHT,
    fontSize: size,
    lineHeight: 1,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre" as const,
    color: c.ink,
  };

  const open = 0.12 + 0.88 * Math.min(1, chipOpen);
  const visW = chip.w * open;

  return (
    <AbsoluteFill
      style={{
        background:
          flat && background !== "transparent" ? background : undefined,
        overflow: "hidden",
      }}
    >
      {flat ? null : (
        <GshGround
          preset={ground ?? (groundParams ? undefined : c.preset)}
          params={groundParams}
          timeOffset={c.groundOffset}
          timeScale={0.4}
        />
      )}
      {words.map((wd, i) => {
        const a = A.placed[i];
        const b = B.placed[i];
        const enter = interpolate(
          t,
          [i * 2.5 * k, i * 2.5 * k + 12 * k],
          [0, 1],
          { ...CLAMP, easing: TYPE_IN },
        );
        const x = lerp(a.x, b.x, p);
        const y = lerp(a.y, b.y, p) + (1 - enter) * size * 0.32;
        return (
          <span
            key={`${wd}-${i.toString()}`}
            style={{
              ...textStyle,
              transform: `translate(${x}px, ${y}px)`,
              opacity: enter,
            }}
          >
            {wd}
          </span>
        );
      })}
      <span
        style={{
          ...textStyle,
          transform: `translate(${endX}px, ${endY}px)`,
          opacity: interpolate(t, [10 * k, 18 * k], [0, 1], {
            ...CLAMP,
            easing: TYPE_IN,
          }),
        }}
      >
        {end}
      </span>
      <span
        style={{
          ...textStyle,
          fontFamily: serif.fontFamily,
          fontStyle: "italic",
          fontWeight: 400,
          letterSpacing: `${SERIF_TRACK}em`,
          color: hi,
          transform: `translate(${wordX}px, ${lerp(slotA.y, slotB.y, p) + (1 - wordIn) * size * 0.3}px)`,
          opacity: wordIn,
        }}
      >
        {word}
      </span>
      <div
        style={{
          position: "absolute",
          left: chip.x + (chip.w - visW) / 2,
          top: chip.y,
          width: visW,
          height: chip.h,
          borderRadius: radius,
          overflow: "hidden",
          background: c.well,
          boxShadow: pChip > 0.3 ? c.lift : "none",
          opacity: interpolate(chipOpen, [0, 0.25], [0, 1], CLAMP),
        }}
      >
        <Img
          src={image}
          style={{
            position: "absolute",
            left: -(chip.w - visW) / 2,
            top: 0,
            width: chip.w,
            height: chip.h,
            objectFit: "cover",
            transform: `scale(${imgScale})`,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            height: "34%",
            backgroundImage:
              "linear-gradient(180deg, rgba(6,7,10,0) 0%, rgba(6,7,10,0.18) 40%, rgba(6,7,10,0.55) 100%)",
            opacity: chrome,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: label * 1.1,
            right: label * 1.1,
            bottom: label * 0.95,
            display: "flex",
            alignItems: "center",
            gap: label * 0.8,
            opacity: chrome,
            transform: `translateY(${(1 - chrome) * label * 0.6}px)`,
            color: "#ffffff",
            fontFamily: mono.fontFamily,
            fontSize: label,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
          }}
        >
          <PlayGlyph size={label * 1.05} color="#ffffff" />
          <div
            style={{
              flex: 1,
              height: Math.max(2, label * 0.14),
              borderRadius: label,
              background: "rgba(255,255,255,0.3)",
            }}
          >
            <div
              style={{
                width: `${play * 100}%`,
                height: "100%",
                borderRadius: "inherit",
                background: "#ffffff",
              }}
            />
          </div>
          <span>
            {stamp} / {duration}
          </span>
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            borderRadius: "inherit",
            boxShadow: `inset 0 0 0 1px ${c.edge}`,
          }}
        />
      </div>
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/DMSans";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const dmSans = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface LoopBreakProps {
  loop?: string[];
  fix?: string;
  highlight?: string;
  passes?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2E3440", ink: "#FFFFFF", accent: "#FFB020" },
  light: { bg: "#F1F2F4", ink: "#2E3440", accent: "#B86E00" },
} as const;

const WGHT = 500;
const TRACK = -0.03;
const PROBE = 200;
const BASE = 215;
const LEAD = 1.14;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const START = 6;
const ENTER = 14;
const WORD_STAGGER = 3;
const ROW_GAP = 15;
const HOLD = 16;
const REWIND = 7;
const REWIND_WORD = 1.5;
const REWIND_ROW = 4;
const TEMPO = 0.6;
const MIN_TEMPO = 0.4;
const BREAK_PAUSE = 12;
const FIX_TEMPO = 1.25;
const DIM_AFTER = 6;

interface Word {
  text: string;
  start: number;
  x: number;
  w: number;
}

interface Metrics {
  rows: Word[][];
  fix: Word[];
  widest: number;
}

interface Placed extends Word {
  row: number;
  px: number;
}

function layoutWords(s: string, em: (x: string) => number) {
  const out: Word[] = [];
  const re = /\S+/g;
  for (let m = re.exec(s); m; m = re.exec(s)) {
    out.push({
      text: m[0],
      start: m.index,
      x: em(s.slice(0, m.index)),
      w: em(m[0]),
    });
  }
  return out;
}

function measure(loop: string[], fix: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("loop-break: no 2d context");
  ctx.font = `${WGHT} ${PROBE}px "${dmSans.fontFamily}"`;
  const em = (x: string) =>
    ctx.measureText(x).width / PROBE + TRACK * Array.from(x).length;
  return {
    rows: loop.map((s) => layoutWords(s, em)),
    fix: layoutWords(fix, em),
    widest: Math.max(
      ...loop.map(em),
      ...(fix.match(/[^.!?…]+[.!?…]*/g) ?? []).map((x) => em(x.trim())),
      0.1,
    ),
  };
}

function useMetrics(loop: string[], fix: string) {
  const key = `${loop.join("\u0002")}\u0001${fix}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("loop-break: measuring"));
  const released = useRef(false);
  const src = useRef({ loop, fix });
  src.current = { loop, fix };
  useEffect(() => {
    let live = true;
    Promise.all([
      dmSans.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${dmSans.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(src.current.loop, src.current.fix) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

interface Take {
  row: number;
  fix: boolean;
  at: number;
  tempo: number;
  back: number;
  backTempo: number;
}

function wrapFix(words: Word[], measure: number) {
  const out: Placed[] = [];
  let row = 0;
  let rowStart = 0;
  words.forEach((w, i) => {
    const prev = words[i - 1];
    if (
      i > 0 &&
      (/[.!?…]$/.test(prev.text) || w.x + w.w - rowStart > measure + 0.01)
    ) {
      row += 1;
      rowStart = w.x;
    }
    out.push({ ...w, row, px: w.x - rowStart });
  });
  return out;
}

function schedule(rowCount: number, words: number[], passes: number) {
  const takes: Take[] = [];
  let cursor = START;
  let fixAt = 0;
  for (let p = 0; p < passes; p++) {
    const s = Math.max(MIN_TEMPO, TEMPO ** p);
    const final = p === passes - 1;
    const pass: Take[] = [];
    for (let r = p === 0 ? 0 : 1; r < rowCount; r++) {
      const fix = final && r === rowCount - 1;
      if (fix) {
        cursor += BREAK_PAUSE;
        fixAt = cursor;
      }
      const take: Take = {
        row: r,
        fix,
        at: cursor,
        tempo: fix ? FIX_TEMPO : s,
        back: Number.POSITIVE_INFINITY,
        backTempo: s,
      };
      pass.push(take);
      takes.push(take);
      if (r < rowCount - 1) cursor += ROW_GAP * s;
    }
    const last = pass[pass.length - 1];
    if (final) {
      cursor =
        last.at +
        (ENTER + WORD_STAGGER * Math.max(0, words[rowCount] - 1)) * last.tempo;
      break;
    }
    cursor =
      last.at +
      (ENTER + WORD_STAGGER * Math.max(0, words[last.row] - 1)) * s +
      HOLD * s;
    const back = [...pass].reverse().filter((tk) => tk.row > 0);
    back.forEach((tk, i) => {
      tk.back = cursor + i * REWIND_ROW * s;
    });
    const lastBack = back[back.length - 1];
    cursor =
      lastBack.back +
      (REWIND + REWIND_WORD * Math.max(0, words[lastBack.row] - 1)) * s +
      2;
  }
  return { takes, fixAt, end: cursor };
}

function LoopBreakBase({
  loop = ["Render the cut.", "Spot a typo.", "Start over."],
  fix = "Change one word. Done.",
  highlight = "Done.",
  passes = 3,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: LoopBreakProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const k = Math.min(1, durationInFrames / BASE);
  const t = (frame * speed) / k;
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const rows = loop.length >= 2 ? loop : [...loop, "Start over."];
  const m = useMetrics(rows, fix);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const R = m.rows.length;
  const measureW = W * (portrait ? 0.84 : 0.58);
  const F = Math.min(measureW / m.widest, portrait ? W * 0.13 : H * 0.15);
  const fixRows = wrapFix(m.fix, measureW / F);
  const total = R - 1 + (fixRows[fixRows.length - 1]?.row ?? 0) + 1;
  const pitch = F * LEAD;
  const left = W * 0.08;
  const blockTop = (H - total * pitch) / 2;

  const words = [...m.rows.map((r) => r.length), m.fix.length];
  const plan = schedule(R, words, Math.max(2, Math.round(passes)));
  const settled = plan.end + DIM_AFTER;
  const dim = interpolate(t, [settled, settled + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const hiStart = highlight ? fix.lastIndexOf(highlight) : -1;
  const hiEnd = hiStart >= 0 ? hiStart + highlight.length : -1;

  const rowBox = (key: string, row: number, glyphs: React.ReactNode[]) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: blockTop + row * pitch,
        height: pitch,
        overflow: "hidden",
      }}
    >
      {glyphs}
    </div>
  );

  const nodes: React.ReactNode[] = [];
  for (let r = 0; r < R; r++) {
    let take: Take | null = null;
    for (const tk of plan.takes) {
      if (tk.row === r && tk.at <= t) take = tk;
    }
    if (!take) continue;
    const cur = take;
    const list: Placed[] = cur.fix
      ? fixRows
      : m.rows[r].map((w) => ({ ...w, row: 0, px: w.x }));
    const n = list.length;
    const byRow = new Map<number, React.ReactNode[]>();
    list.forEach((w, i) => {
      const inAt = cur.at + i * WORD_STAGGER * cur.tempo;
      const rise = interpolate(t, [inAt, inAt + ENTER * cur.tempo], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const outAt = cur.back + (n - 1 - i) * REWIND_WORD * cur.backTempo;
      const sink = Number.isFinite(cur.back)
        ? interpolate(t, [outAt, outAt + REWIND * cur.backTempo], [0, 1], {
            ...CLAMP,
            easing: EASE_IN,
          })
        : 0;
      const shown = rise - sink;
      if (shown <= 0) return;
      const lit =
        cur.fix &&
        hiStart >= 0 &&
        w.start < hiEnd &&
        w.start + w.text.length > hiStart;
      const fade = cur.fix ? 0 : dim * 0.55;
      const color = lit
        ? `color-mix(in oklab, ${hi} ${(rise * 100).toFixed(1)}%, ${c.ink})`
        : c.ink;
      const bucket = byRow.get(w.row) ?? [];
      bucket.push(
        <div
          key={`${cur.fix ? "f" : "l"}${i}`}
          style={{
            position: "absolute",
            left: left + w.px * F,
            top: 0,
            height: pitch,
            lineHeight: `${pitch}px`,
            whiteSpace: "pre",
            fontFamily: dmSans.fontFamily,
            fontWeight: WGHT,
            fontSize: F,
            letterSpacing: `${TRACK}em`,
            fontKerning: "normal",
            color,
            opacity: 1 - fade,
            transform: `translateY(${((1 - shown) * pitch).toFixed(2)}px)`,
          }}
        >
          {w.text}
        </div>,
      );
      byRow.set(w.row, bucket);
    });
    for (const [row, glyphs] of byRow) {
      nodes.push(rowBox(`r${r}-${row}`, r + row, glyphs));
    }
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  fix: {
    type: "text-content",
    default: "Change one word. Done.",
    description: "Fix",
  },
  highlight: {
    type: "text-content",
    default: "Done.",
    description: "Highlight",
  },
  passes: {
    type: "number",
    default: 3,
    min: 0,
    max: 10,
    step: 1,
    description: "Passes",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","fix","highlight","passes","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  fix: "Change one word. Done.",
  highlight: "Done.",
  passes: 3,
  speed: 1,
};

type LoopBreakElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LoopBreakBase>;

const LoopBreakInner = forwardRef<
  HTMLDivElement,
  LoopBreakElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LoopBreak>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LoopBreakBase
          {...(componentProps as unknown as ComponentProps<typeof LoopBreakBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LoopBreak = Interactive.withSchema({
  Component: LoopBreakInner,
  componentName: "<LoopBreak>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

