  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","label","index","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "Built to move.",
  label: "remocn",
  index: "01",
  speed: 1,
};

type MacroPanElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof MacroPanBase>;

const MacroPanInner = forwardRef<
  HTMLDivElement,
  MacroPanElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<MacroPan>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <MacroPanBase
          {...(componentProps as unknown as ComponentProps<typeof MacroPanBase>)}
        />
      </div>
    </Sequence>
  );
});

export const MacroPan = Interactive.withSchema({
  Component: MacroPanInner,
  componentName: "<MacroPan>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

"use client";

import { loadFont as loadInterTight } from "@remotion/google-fonts/InterTight";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  random,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";

const inter = loadInterTight("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const FOCUS = Easing.bezier(0.22, 1, 0.36, 1);
const SWAY = Easing.bezier(0.45, 0, 0.55, 1);
const GROW = { mass: 0.5, damping: 13, stiffness: 240 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const GLIDE = { mass: 0.8, damping: 22, stiffness: 150 };

const B = {
  focus: 0,
  type: 10,
  step: 3,
  space: 6,
  clicks: [1, 6],
  park: 12,
  morph: 60,
  resolve: 86,
  end: 108,
};

export const MACRO_TAB_NAME_DURATION = B.end;

const MEASURE_PX = 100;

const ramp = (f: number, start: number, dur: number, easing = ENTER) =>
  interpolate(f, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

interface Metrics {
  width: (s: string) => number;
}

function buildMetrics(_version: number): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const font = `400 ${MEASURE_PX}px "${inter.fontFamily}"`;
  const cache: Record<string, number> = {};
  return {
    width: (s: string) => {
      if (cache[s] === undefined) {
        if (!ctx) return s.length * 0.52;
        ctx.font = font;
        cache[s] = ctx.measureText(s).width / MEASURE_PX;
      }
      return cache[s];
    },
  };
}

function useMetrics() {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("macro-tab-name: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`400 ${MEASURE_PX}px "${inter.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle]);
  return useMemo(() => buildMetrics(version), [version]);
}

function FileIcon({ size, color }: { size: number; color: string }) {
