            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
          }}
        >
          {status}
        </div>
      </div>

      {/* MAX Q band. */}
      {bandOn ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: bandY,
            width: W,
            height: bandH,
            clipPath: `inset(0 ${(1 - bandIn) * 100}% 0 ${bandOut * 100}%)`,
            background: `linear-gradient(90deg, ${BEAM[3]} 0%, ${BEAM[2]} 22%, ${BEAM[1]} 40%, ${BEAM[0]} 52%, ${BEAM[1]} 66%, ${BEAM[2]} 84%, ${BEAM[3]} 100%)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 40 * u,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: BEAM[0],
              opacity: bandHit * 0.8,
            }}
          />
          <div
            style={{
              fontFamily: condensed,
              fontWeight: 500,
              fontSize: 168 * u,
              lineHeight: 1,
              letterSpacing: "-0.01em",
