const TURN_END = 86;
const START_ANGLE = 11;
const DRIFT = 3;
const LOCK_AT = 100;
const LOCK_END = 114;
const CAPTION_AT = 110;

const TURN = Easing.bezier(0.3, 0.15, 0.25, 1);
const LOCK = Easing.bezier(0.5, 0, 0.1, 1);
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);

const THEMES = {
