    min: 4,
    max: 32,
    step: 1,
    description: "Line weight",
    hiddenFromList: false,
  },
  expandCell: {
    type: "number",
    default: 0,
    min: 0,
    max: 12,
    step: 1,
    description: "Expanding cell (0 is the largest)",
    hiddenFromList: false,
  },
