  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["seed","splits","lineWeight","expandCell","lineColor","redColor","yellowColor","blueColor","fieldColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  seed: 7,
  splits: 7,
  lineWeight: 14,
  expandCell: 0,
  lineColor: "#121212",
  redColor: "#d62d20",
  yellowColor: "#f4c20d",
  blueColor: "#1f4e9e",
  fieldColor: "#d62d20",
  speed: 1,
};

type MondrianSplitElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof MondrianSplitBase>;

const MondrianSplitInner = forwardRef<
  HTMLDivElement,
  MondrianSplitElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<MondrianSplit>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <MondrianSplitBase
          {...(componentProps as unknown as ComponentProps<typeof MondrianSplitBase>)}
        />
      </div>
    </Sequence>
  );
});

export const MondrianSplit = Interactive.withSchema({
  Component: MondrianSplitInner,
  componentName: "<MondrianSplit>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
