import { loadFont } from "@remotion/google-fonts/GolosText";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const golos = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface MovesUpProps {
  items?: string[];
  labels?: [string, string, string];
  shipped?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#1D2B53", ink: "#FFFFFF", accent: "#FFB38A" },
  light: { bg: "#FFF4EC", ink: "#1D2B53", accent: "#D9623B" },
} as const;

const DEFAULT_ITEMS = [
  "Auto captions",
  "Voiceover",
  "Vertical cuts",
  "Your type, your colours",
  "Whatever you ask for",
];

const ROW_SCALE = [1, 0.56, 0.38];
const ROW_INK = [1, 0.74, 0.5];
const LH = 1.06;
const BASE_EM = 0.86;

const INTRO = 30;
const HOLD = 22;
const STEP = 66;
const TAG_IN = 10;
const EXIT_AT = 11;
const EXIT_DUR = 10;
const PROMO_AT = 14;
const PROMO_DUR = 20;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_STEP = Easing.bezier(0.4, 0, 0.15, 1);
const EASE_IN = Easing.bezier(0.5, 0, 0.75, 0);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function MovesUpBase({
  items = DEFAULT_ITEMS,
  labels = ["Now", "Next", "Later"],
  shipped = "shipped",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: MovesUpProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const queue = items.length > 0 ? items : DEFAULT_ITEMS;
  const steps = Math.max(0, queue.length - 3);
  const stepAt = (s: number) => INTRO + HOLD + (s - 1) * STEP;
  const naturalEnd = steps > 0 ? stepAt(steps) + PROMO_AT + PROMO_DUR : INTRO;
  const pace = Math.max(1, (naturalEnd + 30) / Math.max(1, durationInFrames));
  const t = frame * speed * pace;

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.08 : 0.07);
  const labelW = portrait ? 0 : W * 0.2;
  const itemX = margin + labelW;
  const itemW = W - margin - itemX;
  const baseSize = Math.min(H * 0.15, W * (portrait ? 0.13 : 0.085));
  const minRow = queue.map((_, k) => Math.max(0, Math.min(2, k - steps)));

  const refs = useRef<(HTMLDivElement | null)[]>([]);
  const probes = useRef<(HTMLSpanElement | null)[]>([]);
  const [natural, setNatural] = useState<number[] | null>(null);
  const [handle] = useState(() => delayRender("moves-up: measuring"));
  const released = useRef(false);
  const [fontsOk, setFontsOk] = useState(false);
  const [heights, setHeights] = useState<number[] | null>(null);

  useEffect(() => {
    let live = true;
    Promise.all([
      golos.waitUntilDone(),
      document.fonts.load(`500 100px "${golos.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setFontsOk(true);
      });
    return () => {
      live = false;
    };
  }, []);

  useLayoutEffect(() => {
    if (!fontsOk) return;
    const nat = queue.map(
      (_, i) => (probes.current[i]?.offsetWidth ?? 0) / 100,
    );
    setNatural((prev) =>
      prev && prev.length === nat.length && prev.every((v, i) => v === nat[i])
        ? prev
        : nat,
    );
    const next = queue.map((_, i) => refs.current[i]?.offsetHeight ?? 0);
    setHeights((prev) =>
      prev && prev.length === next.length && prev.every((v, i) => v === next[i])
        ? prev
        : next,
    );
  });

  useEffect(() => {
    if (heights && natural && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  }, [heights, natural, handle]);

  let fit = baseSize;
  if (natural) {
    for (let k = 0; k < queue.length; k++) {
      const w = natural[k] * ROW_SCALE[minRow[k]];
      if (w > 0) fit = Math.min(fit, (itemW * 0.98) / w);
    }
  }
  const size = Math.max(baseSize * 0.62, fit);
  const labelSize = Math.max(size * 0.24, H * 0.022);
  const labelLift = portrait ? labelSize * 1.5 : 0;
  const rowGap = size * 0.42 + labelLift;

  const lineH = size * LH;
  const slots = [0, 1, 2].map((r) => {
    let mx = lineH * ROW_SCALE[r];
    if (heights) {
      for (let k = r; k <= r + steps && k < queue.length; k++) {
        mx = Math.max(mx, heights[k] * ROW_SCALE[r]);
      }
    }
    return mx;
  });
  const total = slots[0] + slots[1] + slots[2] + rowGap * 2 + labelLift;
  const group = Math.min(1, (H * 0.84) / total);
  const top0 = (H - total) / 2 + labelLift;
  const slotTop = [top0, top0 + slots[0] + rowGap];
  slotTop.push(slotTop[1] + slots[1] + rowGap);

  const promoted = (() => {
    let sum = 0;
    for (let s = 1; s <= steps; s++) {
      const at = stepAt(s);
      sum += interpolate(
        t,
        [at + PROMO_AT, at + PROMO_AT + PROMO_DUR],
        [0, 1],
        {
          ...CLAMP,
          easing: EASE_STEP,
        },
      );
    }
    return sum;
  })();

  const lerpRow = (arr: number[], rf: number) => {
    const r = Math.max(0, Math.min(2, rf));
    const i = Math.min(1, Math.floor(r));
    const f = r - i;
    return arr[i] + (arr[i + 1] - arr[i]) * f;
  };

  const rise = (start: number, dur = 14) =>
    interpolate(t, [start, start + dur], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const font: React.CSSProperties = {
    fontFamily: golos.fontFamily,
    fontWeight: 500,
    letterSpacing: "-0.03em",
    lineHeight: LH,
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          visibility: "hidden",
          whiteSpace: "nowrap",
        }}
      >
        {queue.map((item, k) => (
          <span
            key={`probe-${k}-${item}`}
            ref={(el) => {
              probes.current[k] = el;
            }}
            style={{ ...font, fontSize: 100, display: "inline-block" }}
          >
            {item}
            {k < steps ? (
              <span style={{ fontSize: "0.3em", marginLeft: "0.6em" }}>
                {shipped}
              </span>
            ) : null}
          </span>
        ))}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: heights && natural ? 1 : 0,
          transformOrigin: "50% 50%",
          transform: `scale(${group.toFixed(4)})`,
        }}
      >
        {labels.map((label, r) => {
          const p = rise(r * 4);
          const sc = ROW_SCALE[r];
          return (
            <div
              key={`label-${r}`}
              style={{
                ...font,
                position: "absolute",
                left: margin,
                top: portrait
                  ? slotTop[r] - labelLift
                  : slotTop[r] + BASE_EM * size * sc - BASE_EM * labelSize,
                fontSize: labelSize,
                letterSpacing: "-0.01em",
                color: r === 0 ? hi : c.ink,
                opacity: p * (r === 0 ? 1 : 0.62),
                transform: `translateY(${((1 - p) * 0.4).toFixed(3)}em)`,
                whiteSpace: "nowrap",
              }}
            >
              {label}
            </div>
          );
        })}
        {queue.map((item, k) => {
          const rf = k - promoted;
          const introP = k < 3 ? rise(6 + k * 5, 18) : 1;
          const shipStep = k + 1;
          const shipAt = shipStep <= steps ? stepAt(shipStep) : Infinity;
          const tagP = Number.isFinite(shipAt)
            ? interpolate(t, [shipAt, shipAt + TAG_IN], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              })
            : 0;
          const exitP = Number.isFinite(shipAt)
            ? interpolate(
                t,
                [shipAt + EXIT_AT, shipAt + EXIT_AT + EXIT_DUR],
                [0, 1],
                { ...CLAMP, easing: EASE_IN },
              )
            : 0;

          let y: number;
          let sc: number;
          let ink: number;
          let alpha: number;
          if (rf >= 2) {
            const e = Math.min(1, rf - 2);
            y = slotTop[2] + e * slots[2] * 0.9;
            sc = ROW_SCALE[2];
            ink = ROW_INK[2];
            alpha = k < 3 ? introP : interpolate(e, [0, 0.4], [1, 0], CLAMP);
          } else if (rf >= 0) {
            y = lerpRow(slotTop, rf);
            sc = lerpRow(ROW_SCALE, rf);
            ink = lerpRow(ROW_INK, rf);
            alpha = introP;
          } else {
            y = slotTop[0];
            sc = 1;
            ink = 1;
            alpha = 1;
          }
          y -= exitP * slots[0] * 0.45;
          alpha *= 1 - exitP;
          const introY = (1 - introP) * size * sc * 0.35;

          return (
            <div
              key={`${k}-${item}`}
              ref={(el) => {
                refs.current[k] = el;
              }}
              style={{
                ...font,
                position: "absolute",
                left: itemX,
                top: y + introY,
                width: itemW / ROW_SCALE[minRow[k]],
                fontSize: size,
                color: c.ink,
                transformOrigin: "0 0",
                transform: `scale(${sc.toFixed(4)})`,
                opacity: Math.max(0, alpha) * ink,
                textWrap: "balance",
              }}
            >
              {item}
              {k < steps ? (
                <span
                  style={{
                    display: "inline-block",
                    fontSize: "0.3em",
                    letterSpacing: "-0.01em",
                    marginLeft: "0.6em",
                    color: hi,
                    opacity: tagP / Math.max(0.01, ink),
                    transform: `translateX(${((1 - tagP) * -0.6).toFixed(3)}em)`,
                  }}
                >
                  {shipped}
                </span>
              ) : null}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  shipped: {
    type: "text-content",
    default: "shipped",
    description: "Shipped",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","shipped","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  shipped: "shipped",
  speed: 1,
};

type MovesUpElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof MovesUpBase>;

const MovesUpInner = forwardRef<
  HTMLDivElement,
  MovesUpElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<MovesUp>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <MovesUpBase
          {...(componentProps as unknown as ComponentProps<typeof MovesUpBase>)}
        />
      </div>
    </Sequence>
  );
});

export const MovesUp = Interactive.withSchema({
  Component: MovesUpInner,
  componentName: "<MovesUp>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

