              position: "absolute",
              left: 0,
              right: 0,
              top: groupTop,
              height: headH,
              overflow: "hidden",
              textAlign: "center",
            }}
          >
            <div
              style={{
                fontSize: headSize,
                lineHeight: 1.2,
                fontWeight: 300,
                letterSpacing: "-0.035em",
                color: ink,
                transform: `translateY(${mix(100, 0, headIn)}%)`,
              }}
            >
