                    fill="none"
                    stroke={soft}
                    strokeWidth={1.5}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
                <span style={{ fontVariantNumeric: "tabular-nums" }}>
                  {frame < B.deal
                    ? "Attach"
                    : resolvedCount < n
                      ? `Uploading ${resolvedCount}/${n}`
                      : `${n} files · 3.4 MB`}
                </span>
              </div>
              <div style={{ marginLeft: "auto" }}>Build</div>
              <svg
                viewBox="0 0 24 24"
                width={16 * u}
                height={16 * u}
                aria-hidden
              >
                <path
                  d="m7 10 5 5 5-5"
                  fill="none"
                  stroke={soft}
                  strokeWidth={1.5}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              <svg
                viewBox="0 0 24 24"
                width={20 * u}
                height={20 * u}
                aria-hidden
                style={{ marginLeft: 6 * u }}
              >
                <g
                  fill="none"
                  stroke={soft}
                  strokeWidth={1.5}
                  strokeLinecap="round"
                >
                  <rect x={9} y={3.5} width={6} height={11} rx={3} />
                  <path d="M6 11.5a6 6 0 0 0 12 0M12 17.5v3" />
                </g>
              </svg>
              <div
                style={{
                  width: 38 * u,
                  height: 38 * u,
                  borderRadius: 11 * u,
                  marginLeft: 4 * u,
                  background:
                    ready > 0
                      ? accent
                      : dark
                        ? "rgba(255,255,255,0.1)"
                        : "rgba(20,24,48,0.08)",
                  transform: `scale(${(1 + 0.06 * Math.sin(Math.PI * Math.min(1, readyPop)) * ready) * (1 - 0.04 * sendPress)})`,
                  boxShadow:
                    ready > 0
                      ? "inset 0 1px 0 rgba(255,255,255,0.22), 0 1px 2px rgba(4,6,30,0.3)"
                      : undefined,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg
                  viewBox="0 0 24 24"
                  width={18 * u}
                  height={18 * u}
                  aria-hidden
