                    opacity={1 - sent}
                    transform={`translate(0 ${-4 * sent})`}
                  />
                  <rect
                    x={7.5}
                    y={7.5}
                    width={9}
                    height={9}
                    rx={2}
                    fill="#fff"
                    opacity={sent}
