interface Glyph {
  ch: string;
  line: number;
  /** Pen x and glyph advance in em, relative to the line start. */
  pen: number;
  adv: number;
  /** Lit cells (col, row) of the dot glyph. */
  cells: [number, number][];
  cols: number;
  emphasis: boolean;
  order: number;
}

function lineWidth(s: string, m: Measure) {
  return m(s) + TRACK * Math.max(0, s.length - 1);
}

function splitLines(text: string, maxEm: number, m: Measure): string[] {
  if (text.includes("\n")) return text.split("\n");
  const widthOf = (s: string) => lineWidth(s, m);
  if (widthOf(text) <= maxEm) return [text];
  const words = text.split(" ");
  let best: string[] = [text];
  let bestScore = Number.POSITIVE_INFINITY;
  for (let k = 1; k < words.length; k++) {
    const a = words.slice(0, k).join(" ");
    const b = words.slice(k).join(" ");
    const sentence = /[.!?,:;]$/.test(a) ? 0.75 : 1;
    const score = Math.max(widthOf(a), widthOf(b)) * sentence;
    if (score < bestScore) {
      bestScore = score;
      best = [a, b];
    }
  }
  return best;
}

function layout(text: string, emphasis: string, maxEm: number, m: Measure) {
  const lines = splitLines(text, maxEm, m);
  const target = emphasis.trim().toLowerCase();
  const glyphs: Glyph[] = [];
  let order = 0;
  lines.forEach((line, li) => {
    // Mark which characters belong to the emphasis word (with its punctuation).
    const hot = new Array(line.length).fill(false);
    if (target) {
      const re = /\S+/g;
      let m = re.exec(line);
      while (m) {
        const core = m[0].replace(/[^\p{L}\p{N}]/gu, "").toLowerCase();
        if (core === target) {
          for (let i = m.index; i < m.index + m[0].length; i++) hot[i] = true;
        }
        m = re.exec(line);
      }
    }
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      const a = m(ch);
      // Pen from the measured prefix, so the font's kerning carries through.
      const pen = m(line.slice(0, i)) + TRACK * i;
      const rows = GLYPHS[ch];
      const cells: [number, number][] = [];
      if (rows) {
        rows.forEach((row, r) => {
          for (let c = 0; c < row.length; c++) {
            if (row[c] === "#") cells.push([c, r]);
          }
        });
      }
      glyphs.push({
        ch,
        line: li,
        pen,
        adv: a,
        cells,
        cols: rows ? rows[0].length : 0,
        emphasis: hot[i],
        order: ch === " " ? -1 : order++,
      });
    }
  });
  const widths = lines.map((l) => lineWidth(l, m));
  const descender = glyphs.some((g) => (GLYPHS[g.ch]?.length ?? 0) > 7);
  return { lines, glyphs, widths, count: order, descender };
}

// Timeline (frames at speed 1).
const ROW_STEP = 1.1;
const RES_START = 34;
const STAGGER = 2.2;
const WIPE_LEN = 5;
const WIPE_EASE = Easing.bezier(0.33, 0, 0.2, 1);
const DOT_R = 0.47;

const dotPath = (x: number, y: number, r: number) =>
  `M${(x - r).toFixed(2)} ${y.toFixed(2)}a${r.toFixed(2)} ${r.toFixed(2)} 0 1 0 ${(2 * r).toFixed(2)} 0a${r.toFixed(2)} ${r.toFixed(2)} 0 1 0 ${(-2 * r).toFixed(2)} 0`;

function NdotResolveBase({
  text = "Less noise. More launch.",
  emphasis = "launch",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: NdotResolveProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const pal = THEMES[theme];
  const metrics = useMeasurer();

  const maxFs = H * 0.235;
  const laid = useMemo(
    () =>
      metrics
        ? layout(text, emphasis, (W * 0.84) / maxFs, metrics.measure)
        : null,
    [text, emphasis, W, maxFs, metrics],
  );

  if (!metrics || !laid) {
    return (
      <div style={{ position: "absolute", inset: 0, background: pal.bg }} />
    );
  }

  const { glyphs, widths, lines, count, descender } = laid;
  const CAP = metrics.cap;
  const blockEm = Math.max(...widths);
  const fs = Math.min(maxFs, (W * 0.84) / blockEm);
  const p = (CAP * fs) / 7;
  const lead = fs * (descender ? 1.16 : 1.08);
  const blockH = (lines.length - 1) * lead + CAP * fs;
  const left = (W - blockEm * fs) / 2;
  const top = (H - blockH) / 2 + CAP * fs;
  const rowsPerLine = 9;

  const ink2: string[] = [];
  const ink3: string[] = [];
  const hot: string[] = [];
  const hotDim: string[] = [];
  const wiping: ReactNode[] = [];
  const solid: ReactNode[] = [];
  const resEnd = RES_START + (count - 1) * STAGGER + WIPE_LEN;
  // Extent of the emphasis word, for its gradient.
  let hotX0 = Number.POSITIVE_INFINITY;
  let hotX1 = Number.NEGATIVE_INFINITY;
  let hotY = top;

  for (const g of glyphs) {
    if (g.order < 0) continue;
    const baseline = top + g.line * lead;
    const penX = left + g.pen * fs;
    const inkLeft = penX + (g.adv * fs - g.cols * p) / 2;
    const cx = (c: number) => inkLeft + (c + 0.5) * p;
    const cy = (r: number) => baseline - (6.5 - r) * p;
    const start = RES_START + g.order * STAGGER;

    if (g.emphasis) {
      hotX0 = Math.min(hotX0, inkLeft);
      hotX1 = Math.max(hotX1, inkLeft + g.cols * p);
      hotY = baseline;
      for (const [c, r] of g.cells) {
        const tr = (g.line * rowsPerLine + r) * ROW_STEP;
        if (t < tr) continue;
        // Refresh into the gradient, row by row, one dark step per row.
        const sw = start + r * 0.6;
        if (t >= sw && t < sw + 1) continue;
        // A quiet refresh pass over the emphasis word during the hold.
        const pass = resEnd + 12 + r * 0.9;
        const d = dotPath(cx(c), cy(r), DOT_R * p);
        if (t >= sw + 1) {
          if (t >= pass && t < pass + 1.5) hotDim.push(d);
          else hot.push(d);
        } else if (t < tr + 1) ink2.push(d);
        else ink3.push(d);
      }
      continue;
    }

    // A hard line refreshes each glyph top to bottom: solid Geist above it,
    // the dot face below it. One system per region, never two overlapping.
    const lf = t - start;
    const yTop = baseline - fs * 0.8;
    const yBot = baseline + fs * 0.26;
    const wipeY =
      lf <= 0
        ? yTop
        : yTop + (yBot - yTop) * WIPE_EASE(Math.min(1, lf / WIPE_LEN));

    if (lf < WIPE_LEN) {
      for (const [c, row] of g.cells) {
        const tr = (g.line * rowsPerLine + row) * ROW_STEP;
        if (t < tr) continue;
        if (lf > 0 && cy(row) < wipeY) continue;
        const d = dotPath(cx(c), cy(row), DOT_R * p);
        if (t < tr + 1) ink2.push(d);
        else ink3.push(d);
      }
    }
    if (lf <= 0) continue;

    const glyphText = (extra: Record<string, string | number>) => (
      <text
        key={`t${g.order}-${g.line}`}
        x={penX}
        y={baseline}
        fill={pal.ink}
        fontFamily={geist.fontFamily}
        fontWeight={WEIGHT}
        fontSize={fs}
        style={{ fontKerning: "none" }}
        {...extra}
      >
        {g.ch}
      </text>
    );

    if (lf >= WIPE_LEN) {
      solid.push(glyphText({}));
      continue;
    }
    const id = `${uid}-c${g.line}-${g.order}`;
    wiping.push(
      <g key={id}>
        <clipPath id={id}>
          <rect
            x={penX - fs * 0.2}
            y={yTop - fs * 0.2}
            width={g.adv * fs + fs * 0.4}
            height={wipeY - yTop + fs * 0.2}
          />
        </clipPath>
        {glyphText({ clipPath: `url(#${id})` })}
      </g>,
    );
  }

  // The emphasis fill sweeps left to right and drifts a few percent.
  const hotW = Math.max(1, hotX1 - hotX0);
  const sway = Math.sin(t / 34) * 0.06 * hotW;
  const gradId = `${uid}-hot`;

  return (
    <AbsoluteFill style={{ background: pal.bg, overflow: "hidden" }}>
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <linearGradient
            id={gradId}
            gradientUnits="userSpaceOnUse"
            x1={hotX0 - 0.08 * hotW + sway}
            y1={hotY - CAP * fs * 0.6}
            x2={hotX1 + 0.04 * hotW + sway}
            y2={hotY + CAP * fs * 0.1}
          >
            <stop offset={0} stopColor={pal.hot[0]} />
            <stop offset={0.5} stopColor={pal.hot[1]} />
            <stop offset={1} stopColor={accent} />
          </linearGradient>
        </defs>
        {ink2.length ? (
          <path d={ink2.join("")} fill={pal.ink} fillOpacity={0.45} />
        ) : null}
        {ink3.length ? <path d={ink3.join("")} fill={pal.ink} /> : null}
        {wiping}
        {solid}
        {hot.length ? <path d={hot.join("")} fill={`url(#${gradId})`} /> : null}
        {hotDim.length ? (
          <path
            d={hotDim.join("")}
            fill={`url(#${gradId})`}
            fillOpacity={0.45}
          />
        ) : null}
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  text: {
    type: "text-content",
    default: "Less noise. More launch.",
    description: "Text",
  },
  emphasis: {
    type: "text-content",
    default: "launch",
    description: "Emphasis",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","text","emphasis","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  text: "Less noise. More launch.",
  emphasis: "launch",
  speed: 1,
};

type NdotResolveElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof NdotResolveBase>;

const NdotResolveInner = forwardRef<
  HTMLDivElement,
  NdotResolveElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<NdotResolve>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <NdotResolveBase
          {...(componentProps as unknown as ComponentProps<typeof NdotResolveBase>)}
        />
      </div>
    </Sequence>
  );
});

export const NdotResolve = Interactive.withSchema({
  Component: NdotResolveInner,
  componentName: "<NdotResolve>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/BarlowCondensed";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const barlow = loadFont("normal", { weights: ["500"], subsets: ["latin"] });

interface NegationDropProps {
  lines?: string[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#000000",
    ink: "#FFFFFF",
    dim: "#4A4A4A",
    accent: "#D4FF00",
    onBlock: "#000000",
  },
  light: {
    bg: "#D4FF00",
    ink: "#000000",
    dim: "#8FAD00",
    accent: "#000000",
    onBlock: "#D4FF00",
  },
} as const;

const TRACK = -0.01;
const LINE_H = 0.88;
const ENTER_AT = -4;
const ENTER_STAGGER = 6;
const ENTER_LEN = 16;
const FLIP_AT = 44;
const FLIP_GAP = 14;
const FALL_LEN = 9;
const CLOSE_DELAY = 6;
const LIT_DELAY = 6;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_FALL = Easing.bezier(0.55, 0, 0.9, 0.45);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const DEFAULT_LINES = [
  "You can’t animate.",
  "You don’t have a team.",
  "It isn’t done.",
];

type PartKind = "plain" | "keep" | "drop";
interface Part {
  text: string;
  kind: PartKind;
}

function splitLine(line: string): Part[][] {
  const words = line.trim().split(/\s+/);
  let flipped = false;
  return words.map((w) => {
    if (!flipped) {
      const can = w.match(/^(can)([’']t)(\W*)$/i);
      const nt =
        can || /^(won|shan)[’']t/i.test(w)
          ? null
          : w.match(/^(\w+)(n[’']t)(\W*)$/i);
      const hit = can ?? nt;
      if (hit) {
        flipped = true;
        const parts: Part[] = [
          { text: hit[1], kind: "keep" },
          { text: hit[2].replace("'", "’"), kind: "drop" },
        ];
        if (hit[3]) parts.push({ text: hit[3], kind: "plain" });
        return parts;
      }
    }
    return [{ text: w, kind: "plain" }];
  });
}

const upper = (s: string) => s.toUpperCase();

function useWidths(strings: string[]) {
  const key = strings.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Map<string, number>;
    space: number;
    baseline: number;
    capTop: number;
  } | null>(null);
  const [handle] = useState(() => delayRender("negation-drop: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      barlow.waitUntilDone(),
      document.fonts.load(`500 100px "${barlow.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const probe = document.createElement("span");
        Object.assign(probe.style, {
          position: "absolute",
          left: "-99999px",
          top: "0",
          visibility: "hidden",
          whiteSpace: "pre",
          fontFamily: `"${barlow.fontFamily}"`,
          fontWeight: "500",
          fontSize: "100px",
          lineHeight: "1",
          letterSpacing: `${TRACK}em`,
        });
        document.body.appendChild(probe);
        const w = new Map<string, number>();
        for (const s of key.split("\u0001")) {
          probe.textContent = upper(s);
          w.set(s, probe.getBoundingClientRect().width / 100);
        }
        probe.textContent = "A A";
        const aa = probe.getBoundingClientRect().width;
        probe.textContent = "AA";
        const space = Math.max(
          0.2,
          ((aa - probe.getBoundingClientRect().width) / 100) * 1.5,
        );
        probe.remove();

        let baseline = 0.8;
        let capTop = 0.7;
        const ctx = document.createElement("canvas").getContext("2d");
        if (ctx) {
          ctx.font = `500 200px "${barlow.fontFamily}"`;
          const fm = ctx.measureText("H");
          const asc = fm.fontBoundingBoxAscent / 200;
          const desc = fm.fontBoundingBoxDescent / 200;
          baseline = (1 - (asc + desc)) / 2 + asc;
          capTop = fm.actualBoundingBoxAscent / 200;
        }
        setState({ key, w, space, baseline, capTop });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state : null;
}

function NegationDropBase({
  lines = DEFAULT_LINES,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: NegationDropProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const block = accent ?? c.accent;

  const rows = useMemo(() => lines.map(splitLine), [lines]);
  const strings = useMemo(() => {
    const set = new Set<string>();
    for (const r of rows) for (const w of r) for (const p of w) set.add(p.text);
    return [...set];
  }, [rows]);
  const m = useWidths(strings);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const wOf = (s: string) => m.w.get(s) ?? 0;

  const lineEm = rows.map((r) => {
    let full = 0;
    let drop = 0;
    r.forEach((word, wi) => {
      if (wi > 0) full += m.space;
      for (const p of word) {
        full += wOf(p.text);
        if (p.kind === "drop") drop += wOf(p.text);
      }
    });
    return { full, drop };
  });

  const flipAt = (i: number) => FLIP_AT + i * FLIP_GAP;
  const close = rows.map((_, i) =>
    spring({
      frame: t - flipAt(i) - CLOSE_DELAY,
      fps,
      config: { damping: 15, stiffness: 150, mass: 0.8 },
    }),
  );

  const padX = W * (portrait ? 0.035 : 0.025);
  const measureW = W - padX * 2;
  const fitF = lineEm.map(
    (l, i) => measureW / Math.max(0.3, l.full - l.drop * close[i]),
  );
  const restF = lineEm.map((l) => measureW / Math.max(0.3, l.full - l.drop));
  const maxBlockH = H * (portrait ? 0.72 : 0.9);
  const restH = restF.reduce((a, f) => a + f * LINE_H, 0);
  const k = Math.min(1, maxBlockH / Math.max(1, restH));
  const sizes = fitF.map((f) => f * k);
  const blockH = sizes.reduce((a, f) => a + f * LINE_H, 0);
  const blockTop = (H - blockH) / 2 + (sizes[0] ?? 0) * 0.04;

  let lineTop = blockTop;
  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {rows.map((r, i) => {
        const F = sizes[i];
        const top = lineTop;
        lineTop += F * LINE_H;
        const enter = interpolate(
          t,
          [
            ENTER_AT + i * ENTER_STAGGER,
            ENTER_AT + i * ENTER_STAGGER + ENTER_LEN,
          ],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        );
        const f0 = flipAt(i);
        const tint = interpolate(t, [f0 - 8, f0 - 1], [0, 1], CLAMP);
        const fall = interpolate(t, [f0, f0 + FALL_LEN], [0, 1], {
          ...CLAMP,
          easing: EASE_FALL,
        });
        const lit = interpolate(
          t,
          [f0 + LIT_DELAY, f0 + LIT_DELAY + 10],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        );
        const clipTop = top - F * 0.2;
        const baseY = top + m.baseline * F;
        const clipBottom = baseY + F * 0.1;
        const lineW = (lineEm[i].full - lineEm[i].drop * close[i]) * F;
        const left = (W - lineW) / 2;
        const bpad = F * 0.05;

        const pieces: React.ReactNode[] = [];
        let x = 0;
        let passedDrop = false;
        r.forEach((word, wi) => {
          if (wi > 0) x += m.space * F;
          for (const p of word) {
            const pw = wOf(p.text) * F;
            const shift = passedDrop ? -lineEm[i].drop * F * close[i] : 0;
            const style: React.CSSProperties = {
              position: "absolute",
              left: left + x + shift,
              top: top - clipTop,
              height: F,
              lineHeight: `${F}px`,
              whiteSpace: "pre",
              color: c.ink,
            };
            if (p.kind === "drop") {
              style.color = interpolateHex(c.ink, c.dim, tint);
              style.transform = `translateY(${(fall * F * 0.95).toFixed(2)}px)`;
              passedDrop = true;
            }
            if (p.kind === "keep" && lit > 0) {
              style.color = `color-mix(in oklab, ${c.ink} ${((1 - lit) * 100).toFixed(1)}%, ${c.onBlock})`;
              pieces.push(
                <div
                  key={`b${wi}`}
                  style={{
                    position: "absolute",
                    left: left + x - bpad,
                    top: baseY - m.capTop * F - bpad - clipTop,
                    width: pw + bpad * 2,
                    height: m.capTop * F + bpad * 2,
                    background: block,
                    transformOrigin: "0 50%",
                    transform: `scaleX(${lit.toFixed(4)})`,
                  }}
                />,
              );
            }
            pieces.push(
              <span key={`${wi}-${p.kind}-${p.text}`} style={style}>
                {upper(p.text)}
              </span>,
            );
            x += pw;
          }
        });

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: clipTop,
              height: clipBottom - clipTop,
              overflow: "hidden",
              fontFamily: barlow.fontFamily,
              fontWeight: 500,
              fontSize: F,
              letterSpacing: `${TRACK}em`,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                transform: `translateY(${((1 - enter) * (clipBottom - clipTop + F * 0.05)).toFixed(2)}px)`,
              }}
            >
              {pieces}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

function interpolateHex(a: string, b: string, k: number) {
  const pa = hex(a);
  const pb = hex(b);
  if (!pa || !pb) return k < 0.5 ? a : b;
  const mix = pa.map((v, i) => Math.round(v + (pb[i] - v) * k));
  return `rgb(${mix[0]}, ${mix[1]}, ${mix[2]})`;
}

function hex(s: string) {
  const mm = s.trim().match(/^#?([0-9a-f]{6})$/i);
