type Glyph = { key: string; order: number; mark: boolean; char: string };

function glyphPlan(word: string): Glyph[] {
  const chars = Array.from(word);
  const n = chars.length;
  const centre = (n - 1) / 2;
  const letters = chars.map((c, i) => ({
    key: `${c}-${i.toString()}`,
    order: Math.floor(Math.abs(i - centre)),
    mark: false,
    char: c,
  }));
  const last = letters.reduce((m, g) => Math.max(m, g.order), 0);
  return [{ key: "mark", order: last + 1, mark: true, char: "" }, ...letters];
}

function Slice({
  index,
  frame,
  start,
  lockAt,
  amp,
  seed,
  children,
}: {
  index: number;
  frame: number;
  start: number;
  lockAt: number;
  amp: number;
  seed: string;
  children: ReactNode;
}) {
  const tick = Math.floor(frame / 2);
  const appear = start + Math.floor(random(`${seed}-a-${index}`) * 4);
  if (frame < appear) return null;
  const p = clamp01((frame - start) / Math.max(1, lockAt - start));
  const r = random(`${seed}-x-${index}-${tick}`) * 2 - 1;
  const left = (1 - p) ** 1.6;
  const dx = r * amp * left;
  const sx = 1 + left * random(`${seed}-s-${index}-${tick}`) * 1.4;
  const flicker = p < 0.8 && random(`${seed}-f-${index}-${tick}`) < 0.28;
  if (flicker) return null;
  const top = (index / SLICES) * 100;
  const bottom = 100 - ((index + 1) / SLICES) * 100;
  return (
    <span
      style={{
        position: "absolute",
        inset: 0,
        clipPath: `inset(${top}% -60% ${bottom}% -60%)`,
        transform: `translateX(${dx}em) scaleX(${sx})`,
        transformOrigin: "50% 50%",
      }}
    >
      {children}
    </span>
  );
}

function Bars({
  frame,
  start,
  len,
  seed,
  color,
}: {
  frame: number;
  start: number;
  len: number;
  seed: string;
  color: string;
}) {
  const p = (frame - start) / len;
  if (p < 0 || p > 0.5) return null;
  const tick = Math.floor(frame / 2);
  const fade = 1 - p / 0.5;
  return (
    <>
      {Array.from({ length: BARS }, (_, i) => {
        const k = `${seed}-b-${i}-${tick}`;
        if (random(`${k}-on`) < 0.3) return null;
        const row = Math.floor(random(`${k}-y`) * SLICES);
        const w = 30 + random(`${k}-w`) * 110;
        const x = -40 + random(`${k}-p`) * 110;
        return (
          <span
            key={`bar-${i.toString()}`}
            style={{
              position: "absolute",
              left: `${x}%`,
              top: `${(row / SLICES) * 100}%`,
              width: `${w}%`,
              height: `${(0.55 / SLICES) * 100}%`,
              background: color,
              opacity: fade * (0.55 + random(`${k}-o`) * 0.45),
            }}
          />
        );
      })}
    </>
  );
}

function MarkSvg({ color }: { color: string }) {
  return (
    <svg
      viewBox="0 0 124.06 134.26"
      style={{ height: "0.76em", width: "auto", display: "block" }}
      aria-hidden
    >
      <path fill={color} d={REMOCN_R_PATH} />
    </svg>
  );
}

function ForgedGlyph({
  glyph,
  frame,
  color,
  hot,
}: {
  glyph: Glyph;
  frame: number;
  color: string;
  hot: string;
}) {
  const start = B.forge + glyph.order * B.ring;
  const len = glyph.mark ? B.markLen : B.glyphLen;
  const seed = `nf-${glyph.key}`;
  const content = glyph.mark ? <MarkSvg color={color} /> : glyph.char;
  const locked = frame >= start + len;
  const box = {
    position: "relative" as const,
    display: "inline-block",
    marginLeft: glyph.mark ? 0 : glyph.key.endsWith("-0") ? "0.04em" : 0,
  };
  if (locked) {
    return <span style={{ ...box, color }}>{content}</span>;
  }
  const amp = glyph.mark ? 0.5 : 0.36;
  return (
    <span style={{ ...box, color }}>
      <span style={{ visibility: "hidden", display: "inline-block" }}>
        {content}
      </span>
      {frame >= start &&
        Array.from({ length: SLICES }, (_, i) => {
          const lockAt =
            start + len * (0.4 + 0.6 * random(`${seed}-l-${i.toString()}`));
          return (
            <Slice
              key={`s-${i.toString()}`}
              index={i}
              frame={frame}
              start={start}
              lockAt={lockAt}
              amp={amp}
              seed={seed}
            >
              {content}
            </Slice>
          );
        })}
      <Bars frame={frame} start={start} len={len} seed={seed} color={hot} />
    </span>
  );
}

export function NoiseForgeSting({
  theme = "dark",
  accent,
  ink,
  hot,
  tagline = "Launch videos, built from parts.",
  ground,
  groundParams,
}: NoiseForgeStingProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const markC = accent ?? c.accent;
  const hotC = hot ?? c.hot;
  const portrait = H > W * 1.1;
  const custom = Boolean(ground || groundParams);
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams =
    groundParams ??
    (ground
      ? undefined
      : portrait && c.tallParams
        ? c.tallParams
        : c.groundParams);
  const lift = custom || (portrait && c.tallParams) ? 1 : c.lift;

  const fontSize = portrait ? W * 0.205 : W * 0.172;
  const glyphs = glyphPlan("emocn");

  const cool = ramp(frame, B.cool, B.coolLen, COOL);
  const heat = 1 - cool;
  const letterC = interpolateColors(cool, [0, 1], [hotC, inkC]);
  const markColor = interpolateColors(cool, [0, 1], [hotC, markC]);

  const sparkIn = ramp(frame, B.spark - 3, 6, LIGHT);
  const seamGrow = ramp(frame, B.seam, B.seamLen, ENTER);
  const seamOut = ramp(frame, B.seamOut, B.seamOutLen, COOL);
  const seamW = interpolate(seamGrow, [0, 1], [0.05, 4.4]);
  const seamH = interpolate(seamOut, [0, 1], [1, 0.3]);

  const punch = interpolate(
    frame,
    [B.lock, B.lock + 2, B.lock + 8],
    [1, 1.028, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: CAMERA,
    },
  );
  const push = interpolate(frame, [0, B.end], [1.04, 1], {
    easing: CAMERA,
    extrapolateRight: "clamp",
  });

  const glowA = (fontSize * 0.05 + 2) * heat;
  const glowB = fontSize * 0.22 * heat;
  const glow =
    heat > 0.01
      ? `drop-shadow(0 0 ${glowA}px ${c.halo}) drop-shadow(0 0 ${glowB}px ${c.halo})`
      : undefined;

  const tagSize = fontSize * (portrait ? 0.36 : 0.25);
  const words = tagline.split(" ");
  const groundFade = interpolate(frame, [0, 18], [0.35, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        overflow: "hidden",
        background: gshParams(preset, gParams).background,
      }}
    >
      <AbsoluteFill
        style={{
          opacity: groundFade,
          transform: lift !== 1 ? `scale(${lift})` : undefined,
          transformOrigin: "50% 0%",
        }}
      >
        <GshGround
          preset={preset}
          params={gParams}
          timeOffset={4}
          timeScale={0.5}
        />
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${push * punch})`,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: fontSize * (portrait ? 0.34 : 0.26),
            marginTop: portrait ? -H * 0.04 : 0,
          }}
        >
          <div
            style={{
              position: "relative",
              display: "flex",
              alignItems: "baseline",
              fontFamily: manrope.fontFamily,
              fontWeight: 600,
              fontSize,
              letterSpacing: "-0.025em",
              lineHeight: 1,
              filter: glow,
            }}
          >
            <span
              style={{
                position: "absolute",
                left: "50%",
                top: "52%",
                width: `${seamW}em`,
                height: Math.max(2, fontSize * 0.018) * seamH,
                transform: "translate(-50%, -50%)",
                borderRadius: 999,
                background: hotC,
                opacity: sparkIn * (1 - seamOut),
              }}
            />
            {glyphs.map((g) => (
              <ForgedGlyph
                key={g.key}
                glyph={g}
                frame={frame}
                color={g.mark ? markColor : letterC}
                hot={hotC}
              />
            ))}
          </div>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              maxWidth: portrait ? W * 0.8 : W * 0.8,
              rowGap: tagSize * 0.1,
              fontFamily: geist.fontFamily,
              fontWeight: 300,
              fontSize: tagSize,
              letterSpacing: "-0.02em",
              lineHeight: 1.12,
              color: c.sub,
            }}
          >
            {words.map((w, i) => {
              const p = ramp(frame, B.tagline + i * 2, 14);
              return (
                <span
                  key={`${w}-${i.toString()}`}
                  style={{
                    display: "inline-block",
                    overflow: "hidden",
                    paddingBottom: tagSize * 0.14,
                    marginBottom: -tagSize * 0.14,
                    marginRight: i < words.length - 1 ? tagSize * 0.26 : 0,
                  }}
                >
                  <span
                    style={{
                      display: "inline-block",
                      transform: `translateY(${(1 - p) * 105}%)`,
                      filter: p < 1 ? `blur(${(1 - p) * 6}px)` : undefined,
                    }}
                  >
                    {w}
                  </span>
                </span>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/RedHatDisplay";
import React, { useEffect, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const redHat = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface NonstopProps {
  label?: string;
  from?: number;
  unit?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#B84A26", ink: "#FFF1E0", accent: "#8FD3FF" },
  light: { bg: "#FFF1E0", ink: "#B84A26", accent: "#1B4F72" },
} as const;

const WGHT = 500;
const TRACK = -0.035;
const FONT_PX = 200;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const IN = 4;
const FIRST_STEP = 34;
const STEP = 20;
const ROLL = 10;
const ZERO_HOLD = 26;
const SHRINK = 14;
const BOARD_GAP = 6;
const CLOSE_GAP = 26;
const CLOSE = 13;

type Token = { id: string; ch: string };

interface StateLayout {
  x: Record<string, number>;
  width: number;
}

interface Metrics {
  states: StateLayout[];
  adv: Record<string, number>;
  asc: number;
  desc: number;
  fig: number;
  xh: number;
}

function buildStates(from: number, unit: string): Token[][] {
  const stem = unit.endsWith("s") ? unit.slice(0, -1) : unit;
  const stemTokens = Array.from(stem).map((ch, i) => ({ id: `u${i}`, ch }));
  const states: Token[][] = [];
  for (let v = from; v >= 0; v--) {
    const row: Token[] = [
      { id: "d", ch: String(v) },
      { id: "sp", ch: " " },
      ...stemTokens,
    ];
    if (v !== 1) row.push({ id: "pl", ch: "s" });
    states.push(row);
  }
  states.push([
    { id: "N", ch: "N" },
    { id: "d", ch: "o" },
    { id: "sp", ch: " " },
    ...stemTokens,
    { id: "pl", ch: "s" },
  ]);
  states.push([
    { id: "N", ch: "N" },
    { id: "d", ch: "o" },
    { id: "n", ch: "n" },
    ...stemTokens,
    { id: "dot", ch: "." },
  ]);
  return states;
}

function measureStates(states: Token[][]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("nonstop: no 2d context");
  ctx.font = `${WGHT} ${FONT_PX}px "${redHat.fontFamily}"`;
  const em = (s: string) =>
    ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
  const adv: Record<string, number> = {};
  const layouts = states.map((row) => {
    const x: Record<string, number> = {};
    let prefix = "";
    for (const tk of row) {
      x[tk.id] = em(prefix);
      prefix += tk.ch;
      adv[tk.ch] = em(tk.ch);
    }
    return { x, width: em(prefix) };
  });
  const fm = ctx.measureText("Hxg");
  const zero = ctx.measureText("0");
  const o = ctx.measureText("o");
  return {
    states: layouts,
    adv,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
    fig: zero.actualBoundingBoxAscent / FONT_PX,
    xh: o.actualBoundingBoxAscent / FONT_PX,
  };
}

function useMetrics(states: Token[][], label: string) {
  const key = `${label}\u0002${states.map((r) => r.map((tk) => `${tk.id}=${tk.ch}`).join("\u0001")).join("\u0003")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("nonstop: measuring"));
  const released = useRef(false);
  const statesRef = useRef(states);
  statesRef.current = states;
  useEffect(() => {
    let live = true;
    Promise.all([
      redHat.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${redHat.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measureStates(statesRef.current) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

export function Nonstop({
  label = "From idea to export",
  from = 3,
  unit = "stops",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: NonstopProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const start = Math.max(1, Math.min(9, Math.round(from)));
  const states = buildStates(start, unit);
  const m = useMetrics(states, label);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const countSteps = start;
  const stepAt = (k: number) => FIRST_STEP + (k - 1) * STEP;
  const zeroAt = stepAt(countSteps);
  const shrinkAt = zeroAt + ROLL + ZERO_HOLD;
  const boardAt = shrinkAt + BOARD_GAP;
  const closeAt = boardAt + SHRINK + CLOSE_GAP;
  const changeAt = [
    ...Array.from({ length: countSteps }, (_, i) => stepAt(i + 1)),
    shrinkAt,
    closeAt,
  ];
  const durOf = (k: number) =>
    k < countSteps ? ROLL : k === countSteps ? SHRINK + 4 : CLOSE;

  let cur = 0;
  let mix = 0;
  for (let k = 0; k < changeAt.length; k++) {
    if (t >= changeAt[k]) {
      cur = k;
      mix = interpolate(t, [changeAt[k], changeAt[k] + durOf(k)], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      });
    }
  }
  const before = t < changeAt[0];
  const prevIdx = before ? 0 : cur;
  const nextIdx = before ? 0 : cur + 1;
  const p = before ? 0 : mix;

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.07);
  const measureW = W - marginX * 2;
  const widest = Math.max(...m.states.map((s) => s.width), 0.1);
  const F = Math.min(H * (portrait ? 0.16 : 0.37), measureW / widest);
  const right = W - marginX;
  const base = H * (portrait ? 0.56 : 0.66);
  const boxTop = base - ((1 - m.asc - m.desc) / 2 + m.asc) * F;
  const L = Math.max(16, F * 0.17);

  const lineIn = interpolate(t, [IN, IN + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const A = m.states[prevIdx];
  const B = m.states[nextIdx];
  const leftA = right - A.width * F;
  const leftB = right - B.width * F;
  const rowA = states[prevIdx];
  const rowB = states[nextIdx];
  const idsA = new Set(rowA.map((tk) => tk.id));
  const idsB = new Set(rowB.map((tk) => tk.id));
  const shrinking = prevIdx === countSteps;

  const glyph = (
    key: string,
    ch: string,
    x: number,
    dy: number,
    opacity: number,
    color: string,
    extra?: React.CSSProperties,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: x,
        top: boxTop,
        height: F,
        lineHeight: `${F}px`,
        whiteSpace: "pre",
        fontFamily: redHat.fontFamily,
        fontWeight: WGHT,
        fontSize: F,
        letterSpacing: `${TRACK}em`,
        color,
        opacity,
        transform: `translateY(${dy.toFixed(2)}px)`,
        ...extra,
      }}
    >
      {ch}
    </div>
  );

  const nodes: React.ReactNode[] = [];
  const rise = F * 1.3;
  const ids = new Set([...idsA, ...idsB]);
  for (const id of ids) {
    const ta = rowA.find((tk) => tk.id === id);
    const tb = rowB.find((tk) => tk.id === id);
    const color = id === "d" || id === "dot" ? hi : c.ink;
    if (ta && tb) {
      const xa = leftA + A.x[id] * F;
      const xb = leftB + B.x[id] * F;
      const x = xa + (xb - xa) * p;
      if (ta.ch === tb.ch) {
        if (id === "sp") continue;
        nodes.push(glyph(id, ta.ch, x, 0, 1, color));
      } else if (shrinking && id === "d") {
        const zeroW = m.adv[ta.ch];
        const oW = m.adv[tb.ch];
        const sy = 1 + (m.xh / m.fig - 1) * p;
        const sx = 1 + (oW / zeroW - 1) * p;
        const swap = interpolate(p, [0.82, 1], [0, 1], CLAMP);
        nodes.push(
          glyph(`${id}-a`, ta.ch, x, 0, 1 - swap, color, {
            transformOrigin: `${((zeroW * F) / 2).toFixed(2)}px ${(base - boxTop).toFixed(2)}px`,
            transform: `scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`,
          }),
        );
        if (swap > 0) nodes.push(glyph(`${id}-b`, tb.ch, x, 0, swap, color));
      } else {
        const out = interpolate(p, [0, 0.45], [0, 1], {
          ...CLAMP,
          easing: Easing.bezier(0.55, 0, 1, 0.45),
        });
        const inn = interpolate(p, [0.4, 1], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        const travel = (m.fig + 0.12) * F;
        nodes.push(
          <div
            key={`${id}-clip`}
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: base - (m.fig + 0.05) * F,
              height: (m.fig + 0.1) * F,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                top: -(base - (m.fig + 0.05) * F),
              }}
            >
              {out < 1
                ? glyph(`${id}-a`, ta.ch, x, -travel * out, 1, color)
                : null}
              {inn > 0
                ? glyph(`${id}-b`, tb.ch, x, travel * (1 - inn), 1, color)
                : null}
            </div>
          </div>,
        );
      }
    } else if (ta) {
      if (ta.ch === " ") continue;
      const x = leftA + A.x[id] * F;
      nodes.push(glyph(`${id}-a`, ta.ch, x, -rise * p, 1 - p, color));
    } else if (tb) {
      if (tb.ch === " ") continue;
      const x = leftB + B.x[id] * F;
      let q = p;
      if (id === "N") {
        q = interpolate(t, [boardAt, boardAt + SHRINK], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
      }
      nodes.push(glyph(`${id}-b`, tb.ch, x, rise * (1 - q), q, color));
    }
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          right: marginX,
          top: base - F * 0.98 - L * 1.5,
          fontFamily: redHat.fontFamily,
          fontWeight: 400,
          fontSize: L,
          lineHeight: 1,
          letterSpacing: "-0.01em",
          color: c.ink,
          whiteSpace: "pre",
          opacity: lineIn,
          transform: `translateY(${((1 - lineIn) * L * 0.8).toFixed(2)}px)`,
        }}
      >
        {label}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: `inset(${(base - F * 0.98).toFixed(1)}px 0 ${(H - base - F * 0.3).toFixed(1)}px 0)`,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translateY(${((1 - lineIn) * F * 1.3).toFixed(2)}px)`,
          }}
        >
          {nodes}
        </div>
      </div>
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/GolosText";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const golos = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface NotYetProps {
  lines?: string[];
  word?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#1D2B53", ink: "#FFFFFF", accent: "#FFB38A", rule: 0.22 },
  light: { bg: "#FFF4EC", ink: "#1D2B53", accent: "#D9623B", rule: 0.2 },
} as const;

const DEFAULT_LINES = [
  "It can’t write your script.",
  "It can’t pick your music.",
  "It can’t voice your launch.",
];

const WORD_GAP = 3;
const WORD_RISE = 12;
const YET_PAUSE = 9;
const YET_HOLD = 20;
const STEP_DUR = 16;
const OLD_SCALE = 0.58;
const OLD_INK = 0.4;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_STEP = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function splitWords(s: string) {
  return s.split(/\s+/).filter(Boolean);
}

function schedule(lines: string[][]) {
  const starts: number[] = [];
  const yets: number[] = [];
  let at = 0;
  for (const words of lines) {
    starts.push(at);
    const set =
      (at === 0 ? 0 : STEP_DUR - 6) +
      2 +
      (words.length - 1) * WORD_GAP +
      WORD_RISE;
    const yet = at + set + YET_PAUSE;
    yets.push(yet);
    at = yet + YET_HOLD;
  }
  const end = (yets[yets.length - 1] ?? 0) + 10;
  return { starts, yets, end };
}

function NotYetBase({
  lines = DEFAULT_LINES,
  word = "Yet.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: NotYetProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const wordLines = lines.map(splitWords);
  const plan = schedule(wordLines);
  const pace = Math.max(1, (plan.end + 30) / Math.max(1, durationInFrames));
  const t = frame * speed * pace;

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.08 : 0.07);
  const size = Math.min(H * 0.105, W * (portrait ? 0.125 : 0.063));
  const baseline = H * (portrait ? 0.7 : 0.765);
  const blockW = W - margin * 2;
  const gap = size * 0.34;

  const refs = useRef<(HTMLDivElement | null)[]>([]);
  const [handle] = useState(() => delayRender("not-yet: measuring"));
  const released = useRef(false);
  const [fontsOk, setFontsOk] = useState(false);
  const [heights, setHeights] = useState<number[] | null>(null);

  useEffect(() => {
    let live = true;
    Promise.all([
      golos.waitUntilDone(),
      document.fonts.load(`500 100px "${golos.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setFontsOk(true);
      });
    return () => {
      live = false;
    };
  }, []);

  useLayoutEffect(() => {
    if (!fontsOk) return;
    const next = wordLines.map((_, i) => refs.current[i]?.offsetHeight ?? 0);
    setHeights((prev) =>
      prev && prev.length === next.length && prev.every((v, i) => v === next[i])
        ? prev
        : next,
    );
  });

  useEffect(() => {
    if (heights && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  }, [heights, handle]);

  const stepIn = wordLines.map((_, i) =>
    i === 0
      ? 1
      : interpolate(t, [plan.starts[i], plan.starts[i] + STEP_DUR], [0, 1], {
          ...CLAMP,
          easing: EASE_STEP,
        }),
  );
  const ages = wordLines.map((_, i) => {
    let a = 0;
    for (let j = i + 1; j < wordLines.length; j++) a += stepIn[j];
    return a;
  });
  const scaleOf = (a: number) => interpolate(a, [0, 1], [1, OLD_SCALE], CLAMP);

  const ruleIn = interpolate(t, [0, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const rise = (start: number, dur = WORD_RISE) =>
    interpolate(t, [start, start + dur], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const text: React.CSSProperties = {
    fontFamily: golos.fontFamily,
    fontWeight: 500,
    fontSize: size,
    lineHeight: 1.08,
    letterSpacing: "-0.03em",
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: margin,
          top: baseline + size * 0.2,
          width: blockW,
          height: Math.max(1, Math.round(H * 0.0018)),
          background: c.ink,
          opacity: c.rule,
          transformOrigin: "0 50%",
          transform: `scaleX(${ruleIn.toFixed(4)})`,
        }}
      />
      {wordLines.map((words, i) => {
        const a = ages[i];
        const sc = scaleOf(a);
        let lift = 0;
        if (heights) {
          for (let j = i + 1; j < wordLines.length; j++) {
            lift += (heights[j] * scaleOf(ages[j]) + gap) * stepIn[j];
          }
        }
        const inkAlpha = interpolate(a, [0, 1], [1, OLD_INK], CLAMP);
        const gone = interpolate(a, [2.2, 3], [1, 0], CLAMP);
        const s0 = plan.starts[i] + (i === 0 ? 0 : STEP_DUR - 6);
        const yetT = interpolate(t, [plan.yets[i], plan.yets[i] + 8], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <div
            key={`${i}-${words.join(" ")}`}
            ref={(el) => {
              refs.current[i] = el;
            }}
            style={{
              ...text,
              position: "absolute",
              left: margin,
              bottom: H - baseline + lift,
              width: blockW,
              transformOrigin: "0 100%",
              transform: `scale(${sc.toFixed(4)})`,
              opacity: heights ? gone : 0,
              textWrap: "balance",
            }}
          >
            {words.map((w, wi) => {
              const p = rise(s0 + 2 + wi * WORD_GAP);
              return (
                <span
                  key={`${wi}-${w}`}
                  style={{
                    display: "inline-block",
                    marginRight: "0.24em",
                    color: c.ink,
                    opacity: p * inkAlpha,
                    transform: `translateY(${((1 - p) * 0.3).toFixed(3)}em)`,
                  }}
                >
                  {w}
                </span>
              );
            })}
            <span
              style={{
                display: "inline-block",
                color: hi,
                opacity: yetT,
                transform: `translateX(${((1 - yetT) * 0.35).toFixed(3)}em)`,
              }}
            >
              {word}
            </span>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  word: {
    type: "text-content",
    default: "Yet.",
    description: "Word",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","word","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "Yet.",
  speed: 1,
};

type NotYetElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof NotYetBase>;

const NotYetInner = forwardRef<
  HTMLDivElement,
  NotYetElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<NotYet>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <NotYetBase
          {...(componentProps as unknown as ComponentProps<typeof NotYetBase>)}
        />
      </div>
    </Sequence>
  );
});

export const NotYet = Interactive.withSchema({
  Component: NotYetInner,
  componentName: "<NotYet>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

