function PlayPause({
  m,
  size,
  color,
}: {
  m: number;
  size: number;
  color: string;
}) {
  const L: number[][][] = [
    [
      [-6, -10],
      [-7, -9],
    ],
    [
      [2, -5.5],
      [-2, -9],
    ],
    [
      [2, 5.5],
      [-2, 9],
    ],
    [
      [-6, 10],
      [-7, 9],
    ],
  ];
  const R: number[][][] = [
    [
      [2, -5.5],
      [2, -9],
    ],
    [
      [10, 0],
      [7, -9],
    ],
    [
      [10, 0],
      [7, 9],
    ],
    [
      [2, 5.5],
      [2, 9],
    ],
  ];
  const path = (pts: number[][][]) =>
    `M${pts.map(([a, b]) => `${lerp(a[0], b[0], m) + 12} ${lerp(a[1], b[1], m) + 12}`).join("L")}Z`;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24">
      <path
        d={path(L)}
        fill={color}
        stroke={color}
        strokeWidth={1.2}
        strokeLinejoin="round"
      />
      <path
        d={path(R)}
        fill={color}
        stroke={color}
        strokeWidth={1.2}
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ridge(seed: number, base: number, amp: number, freq: number) {
  let d = "M0 100";
  for (let x = 0; x <= 100; x += 2) {
    const y =
      base -
      amp *
        (0.55 * Math.sin(x * freq + seed) +
          0.3 * Math.sin(x * freq * 2.3 + seed * 1.7) +
          0.15 * Math.sin(x * freq * 5.9 + seed * 3.1));
    d += `L${x} ${y.toFixed(2)}`;
  }
  return `${d}L100 100Z`;
}

