function HeartBurst({ t, accent }: { t: number; accent: string }) {
  if (t <= 0 || t > 20) return null;
  const p = Easing.bezier(0.22, 1, 0.36, 1)(Math.min(1, t / 16));
  return (
    <svg
      width={80}
      height={80}
      viewBox="-40 -40 80 80"
      style={{ position: "absolute", left: -26, top: -26, overflow: "visible" }}
    >
      {Array.from({ length: 8 }, (_, i) => {
        const a = (i / 8) * Math.PI * 2 - Math.PI / 2;
        const r0 = 12 + p * 10;
        const r1 = 14 + p * 17;
        return (
          <line
            key={i}
            x1={Math.cos(a) * r0}
            y1={Math.sin(a) * r0}
            x2={Math.cos(a) * r1}
            y2={Math.sin(a) * r1}
            stroke={i % 2 ? "#fff" : accent}
            strokeWidth={2.4 * (1 - p) + 0.4}
            strokeLinecap="round"
            opacity={1 - p * 0.9}
          />
        );
      })}
      <circle
        r={10 + p * 16}
        fill="none"
        stroke={accent}
        strokeWidth={2 * (1 - p)}
        opacity={1 - p}
      />
    </svg>
  );
}

