        }}
      />
      <div style={{ position: "absolute", inset: 0, opacity: fullIn }}>
        <div
          style={{
            position: "absolute",
            top: 62,
            left: 18,
            right: 18,
            display: "flex",
            alignItems: "center",
            color: "#fff",
          }}
        >
          <Glyph d={ICON.down} size={26} sw={1.8} />
          <div style={{ flex: 1, textAlign: "center" }}>
            <div style={{ fontSize: 12, color: muted }}>
              Playing from playlist
