            <div style={{ fontSize: 14, marginTop: 2 }}>{playlist}</div>
          </div>
          <Glyph d="M5 12h.01M12 12h.01M19 12h.01" size={26} sw={3} />
        </div>
        <div
          style={{
            position: "absolute",
            top: 494,
            left: 24,
            right: 24,
            display: "flex",
            alignItems: "center",
          }}
        >
          <div style={{ flex: 1 }}>
            <div
              style={{ color: "#fff", fontSize: 25, letterSpacing: "-0.02em" }}
            >
              {title}
