function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={7}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const LIT_STEPS = 6;

/** Field running clock: ticks at full rate, then brakes to a stop. */
function fieldClock(t: number) {
  const a = 44;
  const b = 92;
  if (t <= a) return t;
  const d = Math.min(t, b) - a;
  return a + d - (d * d) / (2 * (b - a));
}

export function NumberMosaic({
  value = "10,000",
  label = "launch videos rendered",
  name = "remocn",
  logo,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: NumberMosaicProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const p: Palette = THEMES[theme];
  const gid = `m${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const cellW = 12 * u;
  const cellH = 16 * u;
  // overscan so the tilted plane never shows its edge
  const cols = Math.ceil((width * 1.16) / cellW);
  const rows = Math.ceil((height * 1.18) / cellH);
  const ox = (width - cols * cellW) / 2;
  const oy = (height - rows * cellH) / 2;

  const layout = useMemo(() => layoutGlyphs(value), [value]);
  const unit = Math.min((width * 0.84) / layout.width, height * 0.46);
  const numW = layout.width * unit;
  const numTop = height * 0.43 - unit * 0.56;
  const numLeft = (width - numW) / 2;

  // Per-cell constants: coverage by the big number, tier, tick rate, seed, light order.
  const cells = useMemo(() => {
    const feather = (0.55 * cellW) / unit;
    const out: Array<{
      cov: number;
      tier: number;
      rate: number;
      seed: number;
      start: number;
    }> = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const i = r * cols + c;
        const px = (ox + (c + 0.5) * cellW - numLeft) / unit;
        const py = (oy + (r + 0.5) * cellH - numTop) / unit;
        let cov = 0;
        if (px > -0.4 && px < layout.width + 0.4 && py > -0.4 && py < 1.4) {
          let d = 9;
          for (const s of layout.segs) d = Math.min(d, segDist(px, py, s));
          cov = Math.max(0, Math.min(1, (R + feather - d) / (2 * feather)));
        }
        const n1 = hash(i + 1);
        const n2 = hash(i * 3.7 + 11);
        const n3 = hash(i * 1.3 + 97);
        const xN = Math.max(0, Math.min(1, px / layout.width));
        out.push({
          cov,
          tier: n1 < 0.52 ? 0 : n1 < 0.86 ? 1 : 2,
          rate: n2 < 0.35 ? 0 : 1 / (5 + n2 * 14),
          seed: Math.floor(n3 * 10),
          start: 22 + xN * 26 + hash(i * 5.1 + 3) * 12,
        });
      }
    }
    return out;
  }, [rows, cols, cellW, cellH, ox, oy, unit, numLeft, numTop, layout]);

  // Global beats
  const enter = interpolate(t, [0, 16], [0.7, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const dim = interpolate(t, [26, 76], [1, p.rest], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const cam = interpolate(t, [0, 112], [0, 1], { ...CLAMP, easing: EASE_IO });
  const push = 1.08 - cam * 0.08;
  const rotY = -12 * (1 - cam);
  const rotX = 5 * (1 - cam);
  const clock = fieldClock(t);
  const lx = interpolate(t, [0, 130], [32, 66], CLAMP);
  const ly = 38 + Math.sin(t / 50) * 6;

  // Bucket every cell into a layer: 0..2 resting tiers, 3..(3+LIT_STEPS-1) lit steps.
  const layerCount = 3 + LIT_STEPS;
  const buckets: Array<Array<{ x: number[]; y: number; s: string }>> = [];
  for (let l = 0; l < layerCount; l++) buckets.push([]);
  // lit cells also get a solid tile, so the number reads as one shape
  const tiles: string[] = Array.from({ length: LIT_STEPS + 1 }, () => "");
  const tw = cellW - 1.6 * u;
  const th = cellH - 1.6 * u;
  for (let r = 0; r < rows; r++) {
    const rowChars: string[][] = [];
    const rowX: number[][] = [];
    for (let l = 0; l < layerCount; l++) {
      rowChars.push([]);
      rowX.push([]);
    }
    for (let c = 0; c < cols; c++) {
      const cell = cells[r * cols + c];
      const lit = interpolate(t, [cell.start, cell.start + 12], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const v = cell.cov * lit;
      const step = Math.round(v * LIT_STEPS);
      // lit counters lock their digit as they light up
      const k =
        cell.cov > 0.5 ? Math.min(clock, fieldClock(cell.start + 4)) : clock;
      const digit = (cell.seed + Math.floor(k * cell.rate)) % 10;
      const layer = step === 0 ? cell.tier : 2 + step;
      if (step > 0) {
        const tx = ox + c * cellW + 0.8 * u;
        const ty = oy + r * cellH + 0.8 * u;
        tiles[step] +=
          `M${tx.toFixed(1)} ${ty.toFixed(1)}h${tw.toFixed(1)}v${th.toFixed(1)}h${(-tw).toFixed(1)}Z`;
      }
      rowChars[layer].push(String(digit));
      rowX[layer].push(ox + (c + 0.5) * cellW);
    }
    for (let l = 0; l < layerCount; l++) {
      if (rowChars[l].length)
        buckets[l].push({
          x: rowX[l],
          y: oy + (r + 0.5) * cellH + 4.2 * u,
          s: rowChars[l].join(""),
        });
    }
  }

  const ink = p.ink;
  // digits on a lit tile go from field ink to a print colour that sits on the gradient
  const litColor = (k: number) => {
    const f = k / LIT_STEPS;
    const a = p.tiers[2] * dim * (1 - f) + p.printAlpha * f;
    const c = ink.map((v, i) => Math.round(v + (p.print[i] - v) * f));
    return `rgba(${c[0]},${c[1]},${c[2]},${a.toFixed(3)})`;
  };
  // the gradient drifts a few % sideways over the shot
  const gDrift = interpolate(t, [0, 140], [-0.04, 0.04], CLAMP);

  // Label
  const lab = (d: number) =>
    interpolate(t, [84 + d, 108 + d], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const labelTop = numTop + unit * 1.08 + 30 * u;
  const band = interpolate(t, [74, 100], [0, 1], { ...CLAMP, easing: EASE_IO });

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          opacity: enter,
          perspective: 1600 * u,
          perspectiveOrigin: "50% 46%",
        }}
      >
        <AbsoluteFill
          style={{
            transform: `rotateX(${rotX}deg) rotateY(${rotY}deg) scale(${push})`,
            transformOrigin: "50% 46%",
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            aria-hidden
          >
            <defs>
              <radialGradient
                id={gid}
                gradientUnits="userSpaceOnUse"
                cx={(lx / 100) * width}
                cy={(ly / 100) * height}
                r={width * 0.62}
              >
                <stop offset="0" stopColor="#fff" stopOpacity={1} />
                <stop offset="0.55" stopColor="#fff" stopOpacity={0.55} />
                <stop offset="1" stopColor="#fff" stopOpacity={0.22} />
              </radialGradient>
              <linearGradient
                id={`${gid}t`}
                gradientUnits="userSpaceOnUse"
                x1={numLeft + numW * gDrift}
                y1={numTop + unit}
                x2={numLeft + numW * (1 + gDrift)}
                y2={numTop}
              >
                {/* the accent opens the gradient; the rest is the palette */}
                {[accent, ...p.tile.slice(1)].map((col, k) => (
                  <stop
                    key={`${col}${k}`}
                    offset={k / (p.tile.length - 1)}
                    stopColor={col}
                  />
                ))}
              </linearGradient>
              <mask id={`${gid}k`}>
                <rect
                  x={-width * 0.1}
                  y={-height * 0.1}
                  width={width * 1.2}
                  height={height * 1.2}
                  fill={`url(#${gid})`}
                />
              </mask>
            </defs>
            <g fill={`url(#${gid}t)`}>
              {tiles.map((d, k) =>
                d ? (
                  <path
                    key={k}
                    d={d}
                    opacity={Math.min(1, (k / LIT_STEPS) * 1.15)}
                  />
                ) : null,
              )}
            </g>
            <g
              fontFamily={mono}
              fontSize={11 * u}
              textAnchor="middle"
              style={{ fontVariantNumeric: "tabular-nums" }}
            >
              <g mask={`url(#${gid}k)`}>
                {[0, 1, 2].map((l) => (
                  <g
                    key={l}
                    fill={`rgba(${ink[0]},${ink[1]},${ink[2]},${(p.tiers[l] * dim).toFixed(3)})`}
                    fontWeight={400}
                  >
                    {buckets[l].map((row) => (
                      <text key={row.y} x={row.x.join(" ")} y={row.y}>
                        {row.s}
                      </text>
                    ))}
                  </g>
                ))}
              </g>
              {Array.from({ length: LIT_STEPS }, (_, i) => i + 1).map((k) => (
                <g
                  key={k}
                  fill={litColor(k)}
                  fontWeight={k >= LIT_STEPS - 2 ? 500 : 400}
                >
                  {buckets[2 + k].map((row) => (
                    <text key={row.y} x={row.x.join(" ")} y={row.y}>
                      {row.s}
                    </text>
                  ))}
                </g>
              ))}
            </g>
          </svg>
        </AbsoluteFill>
      </AbsoluteFill>

      {/* quiet band behind the label so it reads over the field */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: labelTop - 34 * u,
          height: 104 * u,
          background: `radial-gradient(ellipse 34% 50% at 50% 50%, ${p.bg} 30%, transparent 100%)`,
          opacity: band,
        }}
      />

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: labelTop,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: 16 * u,
          fontFamily: sans,
          fontSize: 22 * u,
          lineHeight: 1,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 9 * u,
            opacity: lab(0),
            transform: `translateY(${(1 - lab(0)) * 14 * u}px)`,
          }}
        >
          {logo ??
            (name.trim().toLowerCase() === "remocn" ? (
              <RemocnLogo fontSize={27 * u} color={p.fg} />
            ) : (
              <span
                style={{
                  color: p.fg,
                  fontWeight: 500,
                  letterSpacing: "-0.03em",
                  fontSize: 26 * u,
                }}
              >
                {name}
              </span>
            ))}
        </div>
        <div
          style={{
            width: Math.max(1, u),
            height: 22 * u,
            background: p.hair,
            transform: `scaleY(${lab(3)})`,
          }}
        />
        <span
          style={{
            color: p.muted,
            fontWeight: 400,
            letterSpacing: "-0.01em",
            opacity: lab(6),
            transform: `translateY(${(1 - lab(6)) * 14 * u}px)`,
          }}
        >
          {label}
        </span>
      </div>

      {/* vignette */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 75% 75% at 50% 46%, transparent 55%, ${p.bg} 100%)`,
          opacity: 0.85,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/DMSans";
import { loadFont as loadDisplay } from "@remotion/google-fonts/Fraunces";
import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
loadDisplay("italic", { weights: ["400"], subsets: ["latin"] });

interface SplitPart {
  label: string;
  value: number;
}

interface NumberSplitProps {
  total?: string;
  label?: string;
  parts?: SplitPart[];
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_PARTS: SplitPart[] = [
  { label: "animations", value: 120 },
  { label: "captions", value: 31 },
  { label: "transitions", value: 90 },
  { label: "backgrounds", value: 60 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_LAND = Easing.bezier(0.2, 1.1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    key: "rgba(255,255,255,0.05)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.28)",
    // gradients.sh "mesh": accent blue through periwinkle to lilac.
    ramp: ["#2e45b7", "#8796ee", "#ecdcf2"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    key: "rgba(255,255,255,0.85)",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.3)",
    ramp: ["#2e45b7", "#6f7fe6", "#b3a3ec"],
    grain: 0.045,
  },
} as const;

const BAR_IN = 10;
const MOVE = 36;
const MOVE_DUR = 26;
const SPLIT = MOVE + MOVE_DUR - 10;
const TREE = MOVE + MOVE_DUR - 2;

const numberSplitLength = () => TREE + 8 + 12 + 6 + 24 + 40;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function widths(values: number[], total: number, min: number) {
  const sum = values.reduce((a, b) => a + Math.max(0, b), 0) || 1;
  let w = values.map((v) => (Math.max(0, v) / sum) * total);
  for (let pass = 0; pass < 4; pass++) {
    const small = w.map((x) => x < min);
    const fixed = small.filter(Boolean).length * min;
    const rest = w.reduce((a, x, i) => (small[i] ? a : a + x), 0);
    if (!small.some(Boolean) || rest <= 0) break;
    w = w.map((x, i) => (small[i] ? min : (x / rest) * (total - fixed)));
  }
  return w;
}

function splitUnit(total: string) {
  const m = total.match(/^([\d.,\s]+)(.*)$/);
  return m ? { num: m[1], unit: m[2] } : { num: total, unit: "" };
}

function NumberSplitBase({
  total = "300+",
  label = "components",
  parts = DEFAULT_PARTS,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: NumberSplitProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const c = THEMES[theme];
  const n = Math.max(1, parts.length);

  const L = W * 0.1;
  const rowW = W - 2 * L;
  const gap = 20 * u;
  const segW = widths(
    parts.map((p) => p.value),
    rowW - gap * (n - 1),
    120 * u,
  );

  const heroF0 = 240 * u;
  const heroF1 = 156 * u;
  const valF = 64 * u;
  const barH = 16 * u;
  const treeH = 64 * u;
  const block = heroF1 * 0.92 + 18 * u + treeH + barH + 26 * u + valF + 34 * u;
  const top = (H - block) / 2;
  const heroTop1 = top;
  const treeTop = top + heroF1 * 0.92 + 18 * u;
  const barY1 = treeTop + treeH;
  const valTop = barY1 + barH + 26 * u;

  const heroTop0 = H / 2 - heroF0 * 0.56;
  const barY0 = heroTop0 + heroF0 * 0.92 + 30 * u;
  const { num, unit } = splitUnit(total);
  const heroW0 = (num.length * 0.6 + unit.length * 0.4) * heroF0;

  const heroIn = interpolate(t, [0, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_LAND,
  });
  const heroBlur = interpolate(t, [0, 9], [1, 0], CLAMP);
  const barIn = interpolate(t, [BAR_IN, BAR_IN + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const mv = interpolate(t, [MOVE, MOVE + MOVE_DUR], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const split = interpolate(t, [SPLIT, SPLIT + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gapP = interpolate(t, [SPLIT, SPLIT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_LAND,
  });
  const labelIn = interpolate(t, [MOVE + 14, MOVE + 32], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const stemP = interpolate(t, [TREE, TREE + 8], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const spanP = interpolate(t, [TREE + 8, TREE + 22], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const cam = interpolate(t, [0, TREE + 90], [1, 1.025], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const heroScale = 1 + (heroF1 / heroF0 - 1) * mv;
  const heroTop = heroTop0 + (heroTop1 - heroTop0) * mv;
  const labelF = 44 * u;
  const labelW = label.length * 0.43 * labelF;
  const lockShift = -((labelW + 22 * u) / 2) * labelIn;

  const barY = barY0 + (barY1 - barY0) * mv;
  const fullW = heroW0 * 0.86 + (rowW - heroW0 * 0.86) * mv;
  const scaleW = fullW / rowW;
  const gapNow = gap * gapP;
  const segs: { x: number; w: number; cx: number }[] = [];
  const sumW = segW.reduce((a, b) => a + b, 0);
  let x = W / 2 - (sumW * scaleW + gapNow * (n - 1)) / 2;
  for (let i = 0; i < n; i++) {
    const w = segW[i] * scaleW;
    segs.push({ x, w, cx: x + w / 2 });
    x += w + gapNow;
  }

  const stroke = Math.max(1, u);
  const stemTop = treeTop;
  const midY = treeTop + treeH * 0.45;
  const firstCx = segs[0].cx;
  const lastCx = segs[n - 1].cx;
  const center = W / 2;
  const root = center + lockShift;
  const dropAt = segs.map((s) => {
    const end = s.cx < root ? firstCx : lastCx;
    const frac = Math.min(
      1,
      Math.abs(s.cx - root) / Math.max(1, Math.abs(end - root)),
    );
    return TREE + 8 + 12 * frac;
  });

  const gradId = `split${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const barL = center + (segs[0].x - center) * barIn;
  const barR = center + (segs[n - 1].x + segs[n - 1].w - center) * barIn;
  const drift = interpolate(t, [0, 150], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 65% at 50% 42%, ${c.key}, transparent 72%)`,
        }}
      />
      <AbsoluteFill
        style={{ transform: `scale(${cam})`, transformOrigin: "50% 45%" }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: heroTop,
            display: "flex",
            justifyContent: "center",
            transform: `translateX(${lockShift}px)`,
          }}
        >
          <div
            style={{
              position: "relative",
              transformOrigin: "50% 0",
              transform: `scale(${heroScale})`,
            }}
          >
            <div
              style={{
                overflow: "hidden",
                padding: `${heroF0 * 0.04}px ${heroF0 * 0.04}px 0`,
                margin: `${-heroF0 * 0.04}px ${-heroF0 * 0.04}px 0`,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  fontFamily: display,
                  fontWeight: 400,
                  fontSize: heroF0,
                  lineHeight: 0.92,
                  letterSpacing: "-0.035em",
                  fontVariantNumeric: "tabular-nums",
                  color: c.fg,
                  transform: `translateY(${(1 - heroIn) * 104}%)`,
                  filter:
                    heroBlur > 0.02
                      ? `blur(${heroBlur * 10 * u}px)`
