        {gridVals.slice(1, -1).map((g) => (
          <line
            key={`g-${g}`}
            x1={boxL}
            x2={boxR}
            y1={bottom - g * px}
            y2={bottom - g * px}
            stroke={p.grid}
            strokeWidth={sw}
            opacity={gridIn}
          />
        ))}

        <line
          x1={boxL}
          x2={boxL}
          y1={bottom}
          y2={bottom - upH}
          stroke={p.frame}
          strokeWidth={sw}
        />
        {rightDraw > 0 && (
          <line
            x1={boxR}
            x2={boxR}
            y1={boxT}
            y2={lerp(boxT, bottom, rightDraw)}
            stroke={p.frame}
            strokeWidth={sw}
          />
