          {fmt(g)}
        </div>
      ))}

      <div
        style={{
          position: "absolute",
          left: boxR + 14 * u,
          top: ty - 10 * u,
          height: 20 * u,
          lineHeight: `${20 * u}px`,
          fontFamily: sans,
          fontWeight: 500,
          fontSize: 16 * u,
          color: p.fg,
          opacity: targetLab,
          transform: `translateX(${(1 - targetLab) * -6 * u}px)`,
