            textAlign: "center",
            fontFamily: sans,
            fontWeight: i === ai ? 500 : 400,
            fontSize: 16 * u,
            color: i === ai ? p.fg : p.muted,
            opacity: interpolate(t, [6 + i * 2, 18 + i * 2], [0, 1], CLAMP),
          }}
        >
          {d.label}
        </div>
      ))}

      <div
        style={{
          position: "absolute",
          left: aX,
          width: bw,
          top: aTop + 10 * u,
          textAlign: "center",
          fontFamily: sans,
          fontWeight: 500,
          fontSize: 16 * u,
          letterSpacing: "0",
          fontVariantNumeric: "tabular-nums",
          color: broken ? "#2B1206" : "#FFFFFF",
          opacity: counterO * interpolate(aH, [36 * u, 48 * u], [0, 1], CLAMP),
          whiteSpace: "nowrap",
        }}
      >
        {`${Math.round(aVal)}${unit}`}
      </div>

      <div
        style={{
          position: "absolute",
          left: aX + bw + 30 * u,
          top: aTop - 10 * u,
          opacity: heroO,
          transform: `translateY(${(1 - hero) * 18 * u}px)`,
        }}
      >
        <div
          style={{
