const ELEMENT_PROP_KEYS = new Set(["moons","tilt","coreColor","moonColor","flashColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  moons: 3,
  tilt: 64,
  coreColor: "#E5322D",
  moonColor: "#FFFFFF",
  flashColor: "#FFFFFF",
  backgroundColor: "#111111",
  speed: 1,
};

type OrbitLockElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OrbitLockBase>;

const OrbitLockInner = forwardRef<
  HTMLDivElement,
  OrbitLockElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<OrbitLock>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OrbitLockBase
          {...(componentProps as unknown as ComponentProps<typeof OrbitLockBase>)}
        />
      </div>
    </Sequence>
  );
});

export const OrbitLock = Interactive.withSchema({
