    type: "number",
    default: 150,
    min: 60,
    max: 300,
    step: 2,
    description: "Font size",
    hiddenFromList: false,
  },
  strokeWidth: {
    type: "number",
    default: 2.5,
    min: 0.5,
    max: 8,
