          <div
            style={{
              width: `${w * lineP(i) * 100}%`,
              height: "100%",
              borderRadius: 99,
              background: pal.line,
            }}
          />
          {i === active && (
            <div
              style={{
                position: "absolute",
                left: `calc(${caretX * 100}% + ${4 * u}px)`,
                top: -4 * u,
                width: 2 * u,
                height: 18 * u,
                borderRadius: u,
                background: accent,
                opacity: blink,
              }}
            />
          )}
        </div>
      ))}
    </div>
  );
}

function FilmStrip({
  p,
  u,
  pal,
  accent,
}: {
  p: number;
  u: number;
  pal: Palette;
  accent: string;
}) {
  const n = 5;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 * u }}>
      <div style={{ display: "flex", gap: 10 * u }}>
        {Array.from({ length: n }, (_, i) => {
          const done = interpolate(p, [i / n, (i + 0.8) / n], [0, 1], CLAMP);
          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: 78 * u,
                height: 50 * u,
                borderRadius: 8 * u,
                background: pal.card,
                boxShadow: `0 0 0 ${Math.max(1, u)}px ${pal.hair}, 0 ${10 * u}px ${24 * u}px -${12 * u}px ${pal.cardShadow}`,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: `linear-gradient(160deg, ${pal.block}, ${pal.line})`,
                  clipPath: `inset(0 ${(1 - done) * 100}% 0 0)`,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 9 * u,
                  bottom: 9 * u,
                  width: 26 * u,
                  height: 5 * u,
                  borderRadius: 99,
                  background: i === 2 ? accent : pal.line,
                  opacity: done,
                }}
              />
            </div>
          );
        })}
      </div>
      <div
        style={{
          height: Math.max(1, 1.5 * u),
          background: pal.hair,
          borderRadius: 99,
          position: "relative",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            right: `${(1 - p) * 100}%`,
            background: pal.fg,
            opacity: 0.55,
            borderRadius: 99,
          }}
        />
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */

function PaperPlaneBase({
  steps = ["Write", "Render", "Launch"],
  logo,
  url = "remocn.dev",
  accent = "#3B5BFD",
  speed = 1,
  theme = "light",
}: PaperPlaneProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const pal = THEMES[theme];
  const W = width;
  const D = width * 0.92;

  // lockup geometry (world space, origin = centre of the first stop)
  const F = 128 * u;
  const dotR = 0.068 * F;
  const lockW = logo ? 4 * F : F * (LOGO_R + 0.04 + LOGO_EMOCN);
  const lockX = 2 * D - (lockW + 0.06 * F + dotR * 2) / 2;
  const lockY = 30 * u;
  const baseY = lockY + 0.36 * F;
  const dotX = lockX + lockW + 0.06 * F + dotR;
  const dotY = baseY - dotR;
  const dot: V2 = { x: dotX, y: dotY };

  const track = useMemo(() => {
    const dot: V2 = { x: dotX, y: dotY };
    // the loop sits above-left of the logo, clear of the letters
    const C = { x: 2 * D - 360 * u, y: lockY - 170 * u };
    const R = 88 * u;
    const loop: V2[] = [];
    for (let k = 0; k <= 12; k++) {
      const a = Math.PI / 2 - (k * Math.PI * 2) / 12;
      loop.push({ x: C.x + Math.cos(a) * R, y: C.y + Math.sin(a) * R });
    }
    return buildTrack([
      { x: -0.66 * W, y: 250 * u },
      { x: -0.32 * W, y: 196 * u },
      { x: 0.02 * W, y: 214 * u },
      { x: 0.32 * W, y: 120 * u },
      { x: 0.6 * W, y: -150 * u },
      { x: D - 0.1 * W, y: -252 * u },
      { x: D + 0.17 * W, y: -180 * u },
      { x: D + 0.36 * W, y: 40 * u },
      { x: C.x - 130 * u, y: C.y + R + 8 * u },
      ...loop,
      // skim over the word, drop past its end and hook back into the full stop
      { x: lockX + lockW * 0.4, y: lockY - 150 * u },
      { x: dot.x + 64 * u, y: lockY - 118 * u },
      { x: dot.x + 90 * u, y: dot.y + 2 * u },
      { x: dot.x + 36 * u, y: dot.y + 22 * u },
      dot,
    ]);
  }, [W, D, u, dotX, dotY, lockX, lockY, lockW]);
  const dist = useMemo(buildDistance, []);

  const sAt = (time: number) => {
    const x = Math.min(LAND, Math.max(0, time)) * 2;
    const i = Math.floor(x);
    const f = x - i;
    const a = dist[Math.min(i, dist.length - 1)];
    const b = dist[Math.min(i + 1, dist.length - 1)];
    return (a + (b - a) * f) * track.total;
  };
  const s = sAt(t);
  const pos = sampleTrack(track, s);
  const heading = headingAt(track, s);

  // bank into the turn, plus a slow rock so the facets keep catching light
  const turn = headingAt(track, s + 30 * u) - headingAt(track, s - 30 * u);
  const wrapped = Math.atan2(Math.sin(turn), Math.cos(turn));
  const bank =
    Math.max(-0.6, Math.min(0.6, wrapped * 0.9)) + Math.sin(t / 13) * 0.22;
  const tilt = 0.95 + Math.sin(t / 21) * 0.08;

  // camera: follows the plane with a soft lag, then settles on the lockup
  let lagX = 0;
  let lagY = 0;
  for (let k = 0; k < 6; k++) {
    const p = sampleTrack(track, sAt(t - 6 - k * 3));
    lagX += p.x / 6;
    lagY += p.y / 6;
  }
  const softMax = (a: number, b: number, k: number) =>
    (a + b + Math.sqrt((a - b) ** 2 + k * k)) / 2;
  const settle = interpolate(t, [LAND - 60, LAND + 6], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const followX = softMax(lagX + 0.08 * W, 0, 180 * u);
  const camX = followX + (2 * D - followX) * settle;
  const camY = lagY * 0.28 * (1 - settle);
  const zoom = 1 + 0.035 * settle;

  // landing: the plane folds itself into the accent dot
  const morph = interpolate(t, [LAND - 14, LAND], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.55, 0, 1, 0.45),
  });
  const planeSize = 62 * u * (1 - morph * 0.86);
  const height3d = interpolate(t, [LAND - 40, LAND], [1, 0], {
    ...CLAMP,
    easing: Easing.bezier(0.55, 0, 1, 0.45),
  });
  const lift = { x: 10 * u * height3d + 2 * u, y: 30 * u * height3d + 3 * u };
  const facets = planeFacets(heading, bank, tilt, planeSize, lift);
  const accentRgb = hexRgb(accent);
  const dotIn = interpolate(t, [LAND - 3, LAND + 4], [0, 1], CLAMP);
  const dotPop = interpolate(t, [LAND, LAND + 6, LAND + 16], [1, 1.12, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // the dashed trail, oldest part faded
  const trailEnd = Math.max(0, s - planeSize * 0.72);
  const dash = 7 * u;
  const gap = 9 * u;
  const chunks: React.ReactNode[] = [];
  const CH = 140 * u;
  const trailDim = interpolate(t, [LAND - 6, LAND + 30], [1, 0.4], CLAMP);
  for (let c0 = 0; c0 < trailEnd; c0 += CH) {
    const c1 = Math.min(trailEnd, c0 + CH);
    const pts: string[] = [];
    for (let d = c0; d <= c1 + 0.01; d += 6 * u) {
      const p = sampleTrack(track, Math.min(d, c1));
      pts.push(`${p.x.toFixed(1)},${p.y.toFixed(1)}`);
    }
    const behind = trailEnd - c1;
    chunks.push(
      <polyline
        key={c0}
        points={pts.join(" ")}
        fill="none"
        stroke={pal.trail}
        strokeWidth={1.4 * u}
        strokeLinecap="round"
        strokeDasharray={`${dash} ${gap}`}
        strokeDashoffset={-(c0 % (dash + gap))}
        opacity={interpolate(behind, [0, 1800 * u], [1, 0.3], CLAMP) * trailDim}
      />,
    );
  }

  // stop reactions, driven by where the plane is
  const writeP = interpolate(pos.x, [-0.42 * W, 0.42 * W], [0, 1], CLAMP);
  const renderP = interpolate(
    pos.x,
    [D - 0.3 * W, D + 0.36 * W],
    [0, 1],
    CLAMP,
  );
  const enter = (start: number) =>
    interpolate(t, [start, start + 22], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const s1 = enter(-8);
  const s2 = interpolate(camX, [0.35 * D, 0.75 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const s3 = interpolate(camX, [1.3 * D, 1.75 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const wordReveal = interpolate(camX, [1.5 * D, 1.85 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const urlIn = interpolate(t, [LAND + 8, LAND + 28], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const rise = (p: number) => ({
    opacity: p,
    transform: `translateY(${(1 - p) * 16 * u}px)`,
  });

  const shadowBlur = (2 + height3d * 5) * u;
  const svgId = `pp${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  return (
    <AbsoluteFill style={{ background: pal.bg, overflow: "hidden" }}>
      {pal.texture > 0 && (
        <AbsoluteFill
          style={{
            backgroundImage: PAPER_TEX,
            backgroundSize: `${240 * u}px ${240 * u}px`,
            backgroundPosition: `${-camX * 0.98}px ${-camY}px`,
          }}
        />
      )}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 80% at 40% 30%, ${
            theme === "light"
              ? "rgba(255,255,255,0.6)"
              : "rgba(255,255,255,0.035)"
          }, transparent 100%)`,
        }}
      />

      <AbsoluteFill
        style={{ backgroundImage: groundFill(theme, camX / (2 * D)) }}
      />

      {/* world */}
      <div
        style={{
          position: "absolute",
          left: W / 2,
          top: height / 2,
          width: 0,
          height: 0,
          transform: `scale(${zoom}) translate(${-camX}px, ${-camY}px)`,
        }}
      >
        {/* stop 1: write */}
        <div
          style={{
            position: "absolute",
            left: -0.36 * W,
            top: -150 * u,
            ...rise(s1),
          }}
        >
          <StepLabel index="01" u={u} pal={pal} />
          <BigWord text={steps[0]} u={u} pal={pal} />
        </div>
        <div
          style={{
            position: "absolute",
            left: 0.07 * W,
            top: -110 * u,
            transform: `rotate(-3deg) translateY(${(1 - s1) * 20 * u}px)`,
            opacity: s1,
          }}
        >
          <WriteCard p={writeP} t={t} u={u} pal={pal} accent={accent} />
        </div>

        {/* stop 2: render */}
        <div
          style={{
            position: "absolute",
            left: D - 0.3 * W,
            top: -150 * u,
            ...rise(s2),
          }}
        >
          <FilmStrip p={renderP} u={u} pal={pal} accent={accent} />
        </div>
        <div
          style={{
            position: "absolute",
            left: D - 0.3 * W,
            top: -10 * u,
            ...rise(s2),
          }}
        >
          <StepLabel index="02" u={u} pal={pal} />
          <BigWord text={steps[1]} u={u} pal={pal} />
        </div>

        {/* stop 3: launch, the lockup the plane lands in */}
        <div
          style={{
            position: "absolute",
            left: lockX,
            width: lockW,
            display: "flex",
            justifyContent: "flex-end",
            top: baseY - 0.72 * F - 64 * u,
            ...rise(s3),
          }}
        >
          <StepLabel index="03" text={steps[2]} u={u} pal={pal} />
        </div>
        <div
          style={{
            position: "absolute",
            left: lockX,
            top: baseY - LOGO_BASELINE * F,
            height: F,
            display: "flex",
            alignItems: "baseline",
            color: pal.fg,
            fontFamily: sans,
            fontWeight: 600,
            fontSize: F,
            lineHeight: 1,
            letterSpacing: "-0.025em",
          }}
        >
          {logo ?? (
            <>
              <svg
                viewBox="0 0 124.06 134.26"
                style={{
                  height: "0.76em",
                  width: "auto",
                  opacity: s3,
                  transform: `translateY(${(1 - s3) * 16 * u}px)`,
                }}
                aria-hidden
              >
                <path fill="currentColor" d={REMOCN_R_PATH} />
              </svg>
              <span
                style={{
                  marginLeft: "0.04em",
                  clipPath: `inset(-20% ${(1 - wordReveal) * 100}% -20% 0)`,
                  transform: `translateX(${(1 - wordReveal) * -20 * u}px)`,
                }}
              >
                emocn
              </span>
            </>
          )}
        </div>
        <div
          style={{
            position: "absolute",
            left: lockX,
            width: lockW,
            top: baseY + 44 * u,
            textAlign: "center",
            fontFamily: sans,
            fontSize: 21 * u,
            fontWeight: 500,
            letterSpacing: "-0.01em",
            color: pal.muted,
            ...rise(urlIn),
          }}
        >
          {url}
        </div>

        {/* trail + plane */}
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            overflow: "visible",
          }}
          width={1}
          height={1}
          aria-hidden
        >
          <defs>
            <filter id={svgId} x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation={shadowBlur} />
            </filter>
          </defs>
          {chunks}
          {morph < 1 && (
            <g transform={`translate(${pos.x} ${pos.y})`}>
              <g filter={`url(#${svgId})`} opacity={1 - morph}>
                {facets.map((fc, i) => (
                  <polygon
                    key={`s${i}`}
                    points={fc.shadowPts}
                    fill={pal.shadow}
                    opacity={0.22 + (1 - height3d) * 0.3}
                  />
                ))}
              </g>
              {facets.map((fc, i) => (
                <polygon
                  key={i}
                  points={fc.pts}
                  fill={rgb(
                    mix(mix(pal.fold, pal.paper, fc.lit), accentRgb, morph),
                  )}
                  stroke={pal.edge}
                  strokeWidth={0.6 * u}
                  strokeLinejoin="round"
                />
              ))}
            </g>
          )}
          {dotIn > 0 && (
            <circle
              cx={dot.x}
              cy={dot.y}
              r={dotR * dotPop}
              fill={accent}
              opacity={dotIn}
            />
          )}
        </svg>
      </div>

      <Grain opacity={pal.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "light",
    variants: {
      light: {},
      dark: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  url: {
    type: "text-content",
    default: "remocn.dev",
    description: "Url",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","url","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "light",
  accent: "#3B5BFD",
  url: "remocn.dev",
  speed: 1,
};

type PaperPlaneElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PaperPlaneBase>;

const PaperPlaneInner = forwardRef<
  HTMLDivElement,
  PaperPlaneElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PaperPlane>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PaperPlaneBase
          {...(componentProps as unknown as ComponentProps<typeof PaperPlaneBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PaperPlane = Interactive.withSchema({
  Component: PaperPlaneInner,
  componentName: "<PaperPlane>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

"use client";

import type React from "react";
import { useCurrentFrame } from "remotion";
import {
  DEFAULT_STEP,
  hashRange,
  paperJitter,
  steppedRamp,
} from "@/lib/remocn/stop-motion";

export interface PaperStickerProps {
  children: React.ReactNode;
  at?: number;
  seed?: string;
  padding?: string;
  background?: string;
  borderColor?: string;
  maxTilt?: number;
  step?: number;
}

export function PaperSticker({
  children,
  at = 0,
  seed = "sticker",
  padding = "10px 16px",
  background = "#fbfaf6",
  borderColor = "rgba(38,36,44,0.55)",
  maxTilt = 2.6,
  step = DEFAULT_STEP,
}: PaperStickerProps) {
  const frame = useCurrentFrame();
  const progress = steppedRamp(frame, at, at + 2 * step, { step });
  if (progress === 0) return null;

  const tilt = hashRange(`${seed}:rot`, -maxTilt, maxTilt);
  const jitter = paperJitter(frame, `sticker:${seed}`, {
    amp: 0.7,
    rotAmp: 0.2,
    step,
  });

  return (
    <div
      style={{
        display: "inline-block",
        padding,
        background,
        border: `1px solid ${borderColor}`,
        borderRadius: 3,
        boxShadow: "0 2px 5px rgba(38,36,44,0.14)",
        translate: `${jitter.x}px ${jitter.y}px`,
        rotate: `${tilt + jitter.rot}deg`,
        scale: `${progress < 1 ? 1.12 : 1}`,
      }}
    >
      {children}
    </div>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  random,
  spring,
  useVideoConfig,
} from "remotion";

export type PaperTearProps = {
  /** Strength of the impact: shake, flash and debris. 0 turns them off. */
  impact?: number;
  /** Seed for the shape of the rip. */
  seed?: number | string;
  /** Color of the fibrous torn edge. */
  edgeColor?: string;
  /** How jagged the rip is, 0 to 1. */
  roughness?: number;
  /** Shadow the torn halves cast on the incoming scene. */
  shadowColor?: string;
};

export const paperTearDefaults: Required<PaperTearProps> = {
  impact: 1,
  seed: 7,
  edgeColor: "#FFFFFF",
  roughness: 0.5,
  shadowColor: "rgba(0, 0, 0, 0.45)",
};

// Timeline, as shares of the transition: the paper strains, then the rip
// tears through the whole frame in a couple of frames (the impact), then the
// halves are flung apart.
const STRAIN = 0.2;
const IMPACT = 0.28;
const SEGMENTS = 44;
const DEBRIS = 28;
const ripEase = Easing.in(Easing.quad);
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

type TearPoint = { x: number; y: number; left: number; right: number };

function buildTear(
  seed: number | string,
  roughness: number,
  width: number,
  height: number,
): TearPoint[] {
  const r = Math.min(1, Math.max(0, roughness));
  const unit = Math.min(width, height);
  const tilt = (random(`tear-tilt-${seed}`) - 0.5) * width * 0.08;
  const phaseA = random(`tear-pa-${seed}`) * Math.PI * 2;
  const phaseB = random(`tear-pb-${seed}`) * Math.PI * 2;
  const fiber = unit * (0.008 + r * 0.012);
  const points: TearPoint[] = [];
  for (let i = 0; i <= SEGMENTS; i++) {
    const t = i / SEGMENTS;
    const wander =
      Math.sin(t * Math.PI * 2.2 + phaseA) * width * 0.025 +
      Math.sin(t * Math.PI * 5.3 + phaseB) * width * 0.012;
    // Alternate the jitter sign so the rip zig-zags instead of drifting.
    const zig = (i % 2 === 0 ? 1 : -1) * random(`tear-z-${seed}-${i}`);
    points.push({
      x:
        width / 2 +
        tilt * (t - 0.5) +
        wander * (0.4 + r) +
        zig * unit * 0.022 * r,
      y: -unit * 0.05 + t * (height + unit * 0.1),
      left: fiber * (0.35 + random(`tear-l-${seed}-${i}`) * 1.3),
      right: fiber * (0.2 + random(`tear-r-${seed}-${i}`) * 0.9),
    });
  }
  return points;
}

type Shard = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  spin: number;
  size: number;
  shape: string;
};

// Paper scraps blown out of the seam at the moment of impact.
function buildDebris(
  seed: number | string,
  tear: TearPoint[],
  unit: number,
): Shard[] {
  return Array.from({ length: DEBRIS }, (_, i) => {
    const r = (k: string) => random(`tear-debris-${seed}-${i}-${k}`);
    const at = tear[Math.floor(r("at") * tear.length)];
    const side = r("side") < 0.5 ? -1 : 1;
    const corners = Array.from({ length: 4 }, (_, k) => {
      const a = (k / 4) * Math.PI * 2 + r(`a${k}`) * 1.2;
      const d = 0.55 + r(`d${k}`) * 0.45;
      return `${(50 + Math.cos(a) * 50 * d).toFixed(0)}% ${(50 + Math.sin(a) * 50 * d).toFixed(0)}%`;
    });
    return {
      x: at.x,
      y: at.y,
      vx: side * unit * (0.25 + r("vx") * 0.9),
      vy: -unit * (0.1 + r("vy") * 0.55),
      spin: (r("spin") - 0.5) * 1440,
      size: unit * (0.008 + r("size") ** 2 * 0.026),
      shape: `polygon(${corners.join(",")})`,
    };
  });
}

// Damped camera jolt that starts at the impact.
function shakeAt(p: number, unit: number, impact: number) {
  const t = p - IMPACT;
  if (t < 0 || impact <= 0) return { x: 0, y: 0, amp: 0 };
  const decay = Math.exp(-t * 11);
  const amp = unit * 0.03 * impact * decay;
  return {
    x: Math.sin(t * 95) * amp,
    y: Math.cos(t * 120 + 0.6) * amp * 0.7,
    amp,
  };
}

const px = (x: number, y: number) => `${x}px ${y}px`;

const PaperTearPresentation: React.FC<
  TransitionPresentationComponentProps<PaperTearProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const { width, height, fps } = useVideoConfig();
  const { seed, edgeColor, roughness, shadowColor, impact } = {
    ...paperTearDefaults,
    ...passedProps,
  };
  const tear = useMemo(
    () => buildTear(seed, roughness, width, height),
    [seed, roughness, width, height],
  );
  const unit = Math.min(width, height);
  const debris = useMemo(
    () => buildDebris(seed, tear, unit),
    [seed, tear, unit],
  );
  const p = presentationProgress;
  const shake = shakeAt(p, unit, impact);

  if (presentationDirection === "entering") {
    // The next scene is punched toward camera by the hit and settles back.
    const scale = interpolate(p, [IMPACT, 1], [1 + 0.1 * impact, 1], {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    });
    return (
      <AbsoluteFill
        style={{
          transform: `translate(${shake.x}px, ${shake.y}px) scale(${scale})`,
        }}
      >
        {children}
      </AbsoluteFill>
    );
  }

  // Strain: the sheet trembles and leans toward camera before it gives way.
  const strain = interpolate(p, [0, STRAIN, IMPACT], [0, 1, 1], {
    ...clamp,
    easing: Easing.in(Easing.cubic),
  });
  const tremble =
    p < IMPACT ? Math.sin(p * 260) * unit * 0.004 * strain * impact : 0;
  const lean = 1 + 0.025 * strain * (p < IMPACT ? 1 : 0);
  const front =
    -unit * 0.1 +
    ripEase(interpolate(p, [STRAIN, IMPACT], [0, 1], clamp)) *
      (height + unit * 0.25);
  // The torn fibres open up a short distance behind the running rip front.
  const open = (y: number) =>
    interpolate(front - y, [0, unit * 0.12], [0, 1], clamp);

  const pad = unit;
  const edge = tear.map((t) => px(t.x, t.y));
  const leftInk = tear.map((t) => px(t.x - t.left * open(t.y), t.y));
  const rightInk = tear.map((t) => px(t.x + t.right * open(t.y), t.y));
  const leftOuter = [px(-pad, height + pad), px(-pad, -pad)];
  const rightOuter = [px(width + pad, height + pad), px(width + pad, -pad)];
  const poly = (pts: string[]) => `polygon(${pts.join(",")})`;
  const leftPaper = poly([...edge, ...leftOuter]);
  const rightPaper = poly([...edge, ...rightOuter]);
  const leftPrint = poly([...leftInk, ...leftOuter]);
  const rightPrint = poly([...rightInk, ...rightOuter]);

  const peelFrames = 30;
  // A stiff spring right after the impact flings the halves apart.
  const peel = spring({
    frame: Math.max(0, (p - IMPACT) / (1 - IMPACT)) * peelFrames,
    fps,
    durationInFrames: peelFrames,
    config: { damping: 15, stiffness: 150, mass: 0.8 },
  });
  const maxX = Math.max(...tear.map((t) => t.x));
  const minX = Math.min(...tear.map((t) => t.x));
  // The inner edges swing toward camera as the halves part, so travel gets
  // headroom for the perspective growth. Pivoting on the outer edges keeps
  // the frame border sealed (a flat rotate would expose the top or bottom).
  const leftTravel = (maxX + unit * 0.12) * 1.3;
  const rightTravel = (width - minX + unit * 0.12) * 1.3;
  const curl = peel * 24;
  const lens = `perspective(${unit * 2.6}px)`;
  // Grow the shadow from zero so the closed rip shows no dark seam.
  const cast = interpolate(p, [IMPACT, IMPACT + 0.1], [0, 1], clamp);
  const shadow = `drop-shadow(0 ${unit * 0.012 * cast}px ${unit * 0.04 * cast}px ${shadowColor})`;

  const half = (
    paper: string,
    print: string,
    transform: string,
    origin: string,
  ) => (
    <AbsoluteFill
      style={{
        transform,
        transformOrigin: origin,
        filter: cast > 0 ? shadow : undefined,
      }}
    >
      <AbsoluteFill style={{ clipPath: paper, backgroundColor: edgeColor }} />
      <AbsoluteFill style={{ clipPath: print }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );

  // Flash along the seam and scraps of paper blown out of it.
  const flash =
    impact > 0
      ? interpolate(p, [IMPACT - 0.03, IMPACT, IMPACT + 0.14], [0, 1, 0], {
          ...clamp,
        }) * Math.min(1, impact)
      : 0;
  const seam = tear.map((t) => `${t.x},${t.y}`).join(" ");
  const age = p - IMPACT;
  const gravity = unit * 2.6;
  // Debris time runs in "seconds" of the transition so it reads physical.
  const dt = age * 1.1;

  return (
    <AbsoluteFill
      style={{
        zIndex: 2,
        // Overscan just enough that the jolt never exposes the frame edge.
        transform: `translate(${shake.x + tremble}px, ${shake.y}px) scale(${
          lean + (2.2 * shake.amp) / unit
        })`,
      }}
    >
      {front < height + unit * 0.05 ? (
        // Below the running rip the sheet is still whole. Cover the seam with
        // an intact copy so the split halves never show an anti-aliased hairline.
        <AbsoluteFill
          style={{
            clipPath: poly([
              px(-pad, front),
              px(width + pad, front),
              px(width + pad, height + pad),
              px(-pad, height + pad),
            ]),
            zIndex: 1,
          }}
        >
          {children}
        </AbsoluteFill>
      ) : null}
      {half(
        leftPaper,
        leftPrint,
        `${lens} translateX(${-peel * leftTravel}px) rotateY(${-curl}deg)`,
        "0% 50%",
      )}
      {half(
        rightPaper,
        rightPrint,
        `${lens} translateX(${peel * rightTravel}px) rotateY(${curl}deg)`,
        "100% 50%",
      )}
      {flash > 0.01 ? (
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{ position: "absolute", inset: 0, overflow: "visible" }}
          aria-hidden
        >
          <polyline
            points={seam}
            fill="none"
            stroke={edgeColor}
            strokeOpacity={flash * 0.35}
            strokeWidth={unit * 0.06 * flash}
            strokeLinejoin="round"
          />
          <polyline
            points={seam}
            fill="none"
            stroke={edgeColor}
            strokeOpacity={flash}
            strokeWidth={unit * 0.012}
            strokeLinejoin="round"
          />
        </svg>
      ) : null}
      {impact > 0 && age > 0
        ? debris.map((shard, i) => {
            const fade = interpolate(age, [0.35, 0.6], [1, 0], clamp);
            if (fade <= 0) return null;
            const x = shard.x + shard.vx * dt * impact;
            const y =
              shard.y + shard.vy * dt * impact + 0.5 * gravity * dt * dt;
            const size = shard.size * (0.5 + 0.5 * Math.min(1, impact));
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: x - size / 2,
                  top: y - size / 2,
                  width: size,
                  height: size,
                  backgroundColor: edgeColor,
                  clipPath: shard.shape,
                  opacity: fade,
                  transform: `rotate(${shard.spin * dt}deg)`,
                }}
              />
            );
          })
        : null}
    </AbsoluteFill>
  );
};

export function paperTear(
  props: PaperTearProps = {},
): TransitionPresentation<PaperTearProps> {
  return { component: PaperTearPresentation, props };
}

"use client";

import type React from "react";
import { useCurrentFrame } from "remotion";
import { DEFAULT_STEP, paperJitter } from "@/lib/remocn/stop-motion";

export interface PaperWobbleProps {
  children: React.ReactNode;
  seed?: string;
  amp?: number;
  rotAmp?: number;
  step?: number;
  className?: string;
  style?: React.CSSProperties;
}

export function PaperWobble({
  children,
  seed = "wobble",
  amp = 1.4,
  rotAmp = 0.35,
  step = DEFAULT_STEP,
  className,
  style,
}: PaperWobbleProps) {
  const frame = useCurrentFrame();
  const jitter = paperJitter(frame, seed, { amp, rotAmp, step });
  const wobble = `translate(${jitter.x}px, ${jitter.y}px) rotate(${jitter.rot}deg)`;

  return (
    <div
      className={className}
      style={{
        display: "inline-block",
        ...style,
