export type ParticleDissolveDirection =
  | "reveal"
  | "up"
  | "down"
  | "left"
  | "right";

export type ParticleDissolveProps = {
  particleSize?: number;
  scatter?: number;
  shimmer?: number;
  aberration?: number;
  direction?: ParticleDissolveDirection;
  stagger?: number;
};

const DEFAULTS = {
