  scatter: 0.08,
  shimmer: 0.6,
  aberration: 0.5,
  direction: "reveal" as ParticleDissolveDirection,
  stagger: 0.55,
};

const AXES: Record<ParticleDissolveDirection, [number, number]> = {
  reveal: [0, 0],
  up: [0, -1],
  down: [0, 1],
  left: [-1, 0],
  right: [1, 0],
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_aspect;
uniform float u_cells;
uniform float u_scatter;
uniform float u_shimmer;
uniform float u_aberration;
uniform float u_stagger;
uniform vec2 u_dir;
uniform float u_radial;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    sum += noise(p) * amp;
    p *= 2.03;
    amp *= 0.5;
  }
  return sum * 1.0667;
}

float luma(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

vec4 grab(sampler2D tex, vec2 uv, vec2 dir, float amount) {
  vec4 centre = texture(tex, uv);
  float r = texture(tex, uv + dir * amount).r;
  float b = texture(tex, uv - dir * amount).b;
  return vec4(r, centre.g, b, centre.a);
}

void main() {
  vec2 grid = vec2(u_cells * u_aspect, u_cells);
  vec2 skewed = vec2(v_uv.x * u_aspect, v_uv.y);
  vec2 centred = skewed - vec2(0.5 * u_aspect, 0.5);

  float spatial = u_radial > 0.5
    ? clamp(length(centred) / 0.62, 0.0, 1.0)
    : clamp(dot(v_uv - 0.5, u_dir) + 0.5, 0.0, 1.0);
  float blob = fbm(skewed * 2.2);
  float order = mix(blob, spatial, 0.55) * u_stagger;
  float span = max(1.0 - u_stagger, 0.08);
  float phase = clamp((u_progress - order) / span, 0.0, 1.0);
  float dust = sin(phase * PI);

  vec2 flow = vec2(
    fbm(skewed * 3.0 + vec2(0.0, u_progress * 0.8)),
    fbm(skewed * 3.0 + vec2(5.3, 2.7 - u_progress * 0.7))
  ) - 0.5;
  vec2 aim =
    flow * 2.0 + normalize(centred + 0.0001) * 0.7 * u_radial + u_dir;
  vec2 heading = aim / max(length(aim), 0.0001);

  float bright = luma(texture(u_from, v_uv).rgb);
  float travel = u_scatter * dust * (0.18 + bright * 1.25);
  vec2 drift = vec2(heading.x / u_aspect, heading.y) * travel;

  float split = u_aberration * dust * 0.35;
  vec4 leaving = grab(u_from, v_uv - drift, drift, split);
  vec4 arriving = grab(u_to, v_uv + drift, -drift, split);

  vec4 base = mix(leaving, arriving, smoothstep(0.25, 0.75, phase));
  base.rgb = mix(base.rgb, vec3(luma(base.rgb)), dust);
  base.rgb *= 1.0 - dust * 0.25;

  vec2 g = (v_uv - drift) * grid;
  vec2 origin = floor(g);
  float cover = 0.0;
  float light = 0.0;
  for (int oy = -1; oy <= 1; oy++) {
    for (int ox = -1; ox <= 1; ox++) {
      vec2 cell = origin + vec2(float(ox), float(oy));
      vec2 jitter = vec2(hash(cell + 3.1), hash(cell + 8.7));
      float mote = hash(cell + 13.7);
      float twinkle =
        0.5 + 0.5 * sin(u_progress * (12.0 + mote * 30.0) + mote * 6.2831);
      float radius =
        (0.36 + 0.46 * hash(cell + 21.3)) * (0.65 + 0.6 * twinkle);
      float reach = length(g - (cell + jitter));
      float hit = 1.0 - smoothstep(radius * 0.45, radius, reach);
      cover = max(cover, hit);
      light = max(light, hit * mote * twinkle);
    }
  }
  cover = mix(1.0, cover, dust);
  light *= dust;

  vec4 speck = vec4(
    base.rgb + vec3(0.36 * light * u_shimmer) * base.a,
    base.a
  );
  vec4 gap = vec4(base.rgb * (1.0 - dust * 0.6), base.a);
  outColor = mix(gap, speck, cover);
}`;

const shader = makeSceneShader<ParticleDissolveProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, height, passedProps }) => {
    const {
      particleSize = DEFAULTS.particleSize,
      scatter = DEFAULTS.scatter,
      shimmer = DEFAULTS.shimmer,
      aberration = DEFAULTS.aberration,
      direction = DEFAULTS.direction,
      stagger = DEFAULTS.stagger,
    } = passedProps;
    const axis = AXES[direction] ?? AXES[DEFAULTS.direction];
    gl.uniform1f(uniform("u_cells"), height / Math.max(particleSize, 1));
    gl.uniform1f(uniform("u_scatter"), scatter);
    gl.uniform1f(uniform("u_shimmer"), shimmer);
    gl.uniform1f(uniform("u_aberration"), aberration);
    gl.uniform1f(uniform("u_stagger"), Math.min(Math.max(stagger, 0), 0.92));
    gl.uniform2f(uniform("u_dir"), axis[0], axis[1]);
    gl.uniform1f(uniform("u_radial"), direction === "reveal" ? 1 : 0);
  },
);

const ParticleDissolveFallback: React.FC<
  TransitionPresentationComponentProps<ParticleDissolveProps>
> = ({ children, presentationProgress, presentationDirection }) => {
  const p = presentationProgress;
  const entering = presentationDirection === "entering";
  const t = entering ? p : 1 - p;
  const settle = Math.min(1, Math.max(0, (t - 0.2) / 0.6));
  const grain = 1 - settle;

  return (
    <AbsoluteFill
      style={{
        opacity: settle,
        filter:
          grain > 0.02
            ? `blur(${grain * 10}px) saturate(${1 - grain * 0.9}) contrast(${1 + grain * 0.5})`
            : undefined,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<ParticleDissolveProps>({
  shader,
  fallback: ParticleDissolveFallback,
});

export function particleDissolve(
  props: ParticleDissolveProps = {},
): TransitionPresentation<ParticleDissolveProps> {
  return presentation(props);
}

import { loadFont as loadDisplay } from "@remotion/google-fonts/HankenGrotesk";
import React, { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Img, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

/**
 * gradients.sh "fluted": ink blue, electric blue, ember orange, cream. The
 * objects carry it (the blue slot takes the accent) and so does the last word.
 */
const FLUTED = {
  bg: "#050507",
  colors: ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"],
} as const;

interface PassSwapProps {
  /** Headlines in order; each pass of the object swaps to the next one. */
  lines?: string[];
  /** Object when no `src` is given; "mixed" alternates slab and disc per pass. */
  shape?: "slab" | "disc" | "mixed";
  /** A product cutout (transparent PNG) to sweep instead of the shape. */
  src?: string;
  /** Fill the last word of the final line with the object gradient. */
  accentLastWord?: boolean;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps), for three lines / two passes:
//  0–20    first line settles in (rise + unblur)
//  30–60   pass 1, left → right: the object crosses in front of the line;
//          behind its center line the headline has already become line 2
//  60–76   hold on line 2
//  76–106  pass 2, right → left, swaps to the final line
//  106–150 hold on the final line (poster frame)
const FIRST_PASS = 30;
const PASS_LEN = 30;
const PASS_GAP = 46;
const FINAL_HOLD = 44;

function passSwapDuration(lineCount = 3) {
  const passes = Math.max(1, lineCount - 1);
  return FIRST_PASS + (passes - 1) * PASS_GAP + PASS_LEN + FINAL_HOLD;
}

const SWEEP = Easing.bezier(0.62, 0, 0.36, 1);
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F2F1EE",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    grain: 0.04,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `ps-grain-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.85"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** Polygon (px) covering the half-plane on one side of a tilted line. */
function halfPlane(
  cx: number,
  cy: number,
  angleDeg: number,
  side: 1 | -1,
  L: number,
) {
  const th = (angleDeg * Math.PI) / 180;
  const ax = Math.sin(th);
  const ay = -Math.cos(th);
  const nx = Math.cos(th) * side;
  const ny = Math.sin(th) * side;
  const pts = [
    [cx + ax * L, cy + ay * L],
    [cx + ax * L + nx * L, cy + ay * L + ny * L],
    [cx - ax * L + nx * L, cy - ay * L + ny * L],
    [cx - ax * L, cy - ay * L],
  ];
  return `polygon(${pts.map(([x, y]) => `${x.toFixed(1)}px ${y.toFixed(1)}px`).join(", ")})`;
}

function PassSwapBase({
  lines = ["Copy the code.", "Own every frame.", "Ship the film."],
  shape = "mixed",
  src,
  accentLastWord = true,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: PassSwapProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const blurId = `ps-blur-${uid}`;

  const safeLines = lines.length > 0 ? lines : [""];
  const passes = Math.max(0, safeLines.length - 1);
  const longest = Math.max(...safeLines.map((l) => l.length), 1);
  // Hanken Grotesk 500 at -0.035em averages ~0.47em per character.
  const fs = Math.min(150 * u, (W * 0.86) / (longest * 0.47));

  // Which pass is live (or last finished).
  let index = 0;
  let passP = -1;
  for (let i = 0; i < passes; i++) {
    const t0 = FIRST_PASS + i * PASS_GAP;
    if (frame >= t0) {
      index = i;
      passP = (frame - t0) / PASS_LEN;
    }
  }
  const passing = passP >= 0 && passP < 1;
  const done = passP >= 1;
  const dir: 1 | -1 = index % 2 === 0 ? 1 : -1;

  // Object size: tall enough to hide the swap line across the whole cap height.
  const isDisc =
    !src && (shape === "disc" || (shape === "mixed" && index % 2 === 1));
  const ow = src ? H * 0.62 : isDisc ? H * 0.7 : H * 0.34;
  const oh = src ? H * 0.82 : isDisc ? H * 0.7 : H * 0.92;
  const radius = isDisc ? oh / 2 : ow / 2;

  const travel = W + ow * 1.6;
  const sweepAt = (p: number) => {
    const e = SWEEP(Math.min(1, Math.max(0, p)));
    const x = -ow * 0.8 + e * travel;
    return dir === 1 ? x : W - x;
  };
  const cx = sweepAt(passP);
  const vel =
    Math.abs(
      sweepAt(passP + 0.5 / PASS_LEN) - sweepAt(passP - 0.5 / PASS_LEN),
    ) * speed;
  const tilt = dir * interpolate(passP, [0, 1], [11, 4], CLAMP);
  const cy = H / 2 + interpolate(passP, [0, 0.5, 1], [10, 0, -10], CLAMP) * u;

  const fromLine = safeLines[Math.min(index, safeLines.length - 1)];
  const toLine = safeLines[Math.min(index + 1, safeLines.length - 1)];
  const current = passes === 0 ? safeLines[0] : done ? toLine : fromLine;

  // First line arrives.
  const intro = interpolate(frame, [0, 22], [0, 1], {
    ...CLAMP,
    easing: SETTLE,
  });
  // New line is dragged a touch by the object and settles.
  const tStart = FIRST_PASS + index * PASS_GAP;
  const drag = interpolate(
    frame,
    [tStart + PASS_LEN * 0.3, tStart + PASS_LEN + 16],
    [1, 0],
    { ...CLAMP, easing: SETTLE },
  );
  const toOffset = -dir * 26 * u * drag;

  // The last word takes the palette's warm end on dark, the deep end on light.
  const ink =
    theme === "dark"
      ? [
          FLUTED.colors[2],
          `color-mix(in oklab, ${FLUTED.colors[2]} 50%, ${FLUTED.colors[3]})`,
          FLUTED.colors[3],
        ]
      : [
          FLUTED.colors[0],
          accent,
          `color-mix(in oklab, ${accent} 70%, ${FLUTED.colors[2]})`,
        ];

  const finalIdx = safeLines.length - 1;
  const renderLine = (text: string, lineIdx: number) => {
    const isFinal = lineIdx === finalIdx && accentLastWord && passes > 0;
    const cut = isFinal ? text.trimEnd().lastIndexOf(" ") : -1;
    const head = cut >= 0 ? text.slice(0, cut + 1) : text;
    const tail = cut >= 0 ? text.slice(cut + 1) : "";
    return (
      <div
        style={{
          fontFamily: display,
          fontWeight: 500,
          fontSize: fs,
          letterSpacing: "-0.035em",
          lineHeight: 1,
          color: c.fg,
          whiteSpace: "pre",
          textAlign: "center",
        }}
      >
        {head}
        {tail && (
          <span
            style={{
              backgroundImage: `linear-gradient(100deg, ${ink.join(", ")})`,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
              // keeps the clip box wide enough for the final glyph's overhang
              paddingRight: "0.04em",
              marginRight: "-0.04em",
            }}
          >
            {tail}
          </span>
        )}
      </div>
    );
  };

  const lineBox = (
    text: string,
    lineIdx: number,
    extra: React.CSSProperties,
  ) => (
    <AbsoluteFill
      style={{
        alignItems: "center",
        justifyContent: "center",
        ...extra,
      }}
    >
      {renderLine(text, lineIdx)}
    </AbsoluteFill>
  );

  const L = W * 3;
  const blur = Math.min(vel * 0.09, 14 * u);

  // One palette, two flat readings: the slab is a blue column warming at its
  // foot, the disc a low sun going from cream to ember to blue. The angle
  // drifts a few degrees with the pass.
  const [f0, , f2, f3] = FLUTED.colors;
  const f1 = accent;
  const drift = passP * 10;
  const slabFill = `linear-gradient(${180 - drift}deg, ${f0} 0%, ${f1} 42%, color-mix(in oklab, ${f1} 50%, ${f2}) 74%, ${f2} 100%)`;
  const discFill = `linear-gradient(${170 + drift}deg, ${f3} 0%, color-mix(in oklab, ${f3} 40%, ${f2}) 26%, ${f2} 52%, color-mix(in oklab, ${f2} 45%, ${f1}) 78%, ${f1} 100%)`;

  const object = src ? (
    <Img
      src={src}
      style={{ width: "100%", height: "100%", objectFit: "contain" }}
    />
  ) : (
    <div
      style={{
        width: "100%",
        height: "100%",
        borderRadius: radius,
        background: isDisc ? discFill : slabFill,
        boxShadow: `inset 0 ${1.5 * u}px 0 rgba(255,255,255,0.28), inset 0 0 0 1px rgba(255,255,255,0.08)`,
      }}
    />
  );

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <filter
          id={blurId}
          x="-40%"
          y="-10%"
          width="180%"
          height="120%"
          colorInterpolationFilters="sRGB"
        >
          <feGaussianBlur stdDeviation={`${blur} 0`} />
        </filter>
      </svg>

      {passing ? (
        <>
          {lineBox(fromLine, index, {
            clipPath: halfPlane(cx, cy, tilt, dir, L),
          })}
          {lineBox(toLine, index + 1, {
            clipPath: halfPlane(cx, cy, tilt, -dir as 1 | -1, L),
            transform: `translateX(${toOffset}px)`,
          })}
        </>
      ) : (
        lineBox(current, done ? index + 1 : index, {
          opacity: index === 0 && !done ? intro : 1,
          transform: `translateX(${done ? toOffset : 0}px) translateY(${index === 0 && !done ? (1 - intro) * 14 * u : 0}px)`,
          filter:
            index === 0 && !done && intro < 1
              ? `blur(${(1 - intro) * 10 * u}px)`
              : undefined,
        })
      )}

      {passing && (
        <div
          style={{
            position: "absolute",
            left: cx - ow / 2,
            top: cy - oh / 2,
            width: ow,
            height: oh,
            transform: `rotate(${tilt}deg)`,
            filter: blur > 0.4 ? `url(#${blurId})` : undefined,
          }}
        >
          {object}
        </div>
      )}

      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  shape: {
    type: "enum",
    default: "mixed",
    variants: {
      slab: {},
      disc: {},
      mixed: {},
    },
    description: "Shape",
  },
  accentLastWord: {
    type: "boolean",
    default: true,
    description: "Accent last word",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","shape","accentLastWord","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  shape: "mixed",
  accentLastWord: true,
  speed: 1,
};

type PassSwapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PassSwapBase>;

const PassSwapInner = forwardRef<
  HTMLDivElement,
  PassSwapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PassSwap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PassSwapBase
          {...(componentProps as unknown as ComponentProps<typeof PassSwapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PassSwap = Interactive.withSchema({
  Component: PassSwapInner,
  componentName: "<PassSwap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Inter";
import { getLength, getPointAtLength, getTangentAtLength } from "@remotion/paths";
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["100", "900"],
  subsets: ["latin"],
});

interface PathRideProps {
  text?: string;
  path?: string;
  fontSize?: number;
  fontWeight?: number;
  fontFamily?: string;
  color?: string;
  lineColor?: string;
  lineWidth?: number;
  speed?: number;
  className?: string;
}

/** An S-curve across a 1280×720 frame. */
const pathRideDefaultPath =
  "M 120 560 C 360 120 560 120 640 360 S 920 600 1160 160";

const pathRideDefaults = {
  text: "Follow the line",
  path: pathRideDefaultPath,
  fontSize: 44,
  fontWeight: 700,
  fontFamily: INTER,
  color: "#fafafa",
  lineColor: "#D97757",
  lineWidth: 3,
  speed: 1,
} satisfies Required<Omit<PathRideProps, "className">>;

/** Beats on the 30 fps clock. */
const pathRideTiming = {
  draw: [0, 40],
  straighten: [50, 68],
  erase: [52, 70],
} as const;

/** Gap between the head and the last letter, in em. */
const LEAD = 0.3;
/** Letters fade in over this much arc length, in em. */
const FADE_IN = 0.5;
/** Extra lift of the baseline above the line, in em. */
const LIFT = 0.08;
/** Samples along the path; the line and the letters read positions from them. */
const SAMPLES = 400;
const MEASURE_SIZE = 100;
/** Inter's baseline and cap height in a `line-height: 1` box, until measured. */
const INTER_METRICS = { baseline: 0.8637, capHeight: 0.7275 };

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const easeInOutCubic = Easing.inOut(Easing.cubic);

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getPathRideTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

/** Arc length drawn so far. */
function getPathRideHead(t: number, length: number) {
  return interpolate(t, [...pathRideTiming.draw], [0, length], {
    ...CLAMP,
    easing: easeInOutCubic,
  });
}

/** Arc length erased from the start. */
function getPathRideTail(t: number, length: number) {
  return interpolate(t, [...pathRideTiming.erase], [0, length], {
    ...CLAMP,
    easing: easeInOutCubic,
  });
}

/** How far the curve has pulled straight, 0..1. */
function getPathRideStraighten(t: number) {
  return interpolate(t, [...pathRideTiming.straighten], [0, 1], {
    ...CLAMP,
    easing: easeInOutCubic,
  });
}

/** Frame where the line has erased and the text rests on its baseline. */
const pathRideLength = Math.max(
  pathRideTiming.straighten[1],
  pathRideTiming.erase[1],
);

/** Letter centers from the text start, and the total width. */
function getPathRideCenters(advances: readonly number[]) {
  let x = 0;
  const centers = advances.map((a) => {
    const c = x + a / 2;
    x += a;
    return c;
  });
  return { centers, width: x };
}

/**
 * Arc length of a letter's center: it trails the head by the lead plus the
 * text after it, so the last letter follows the head most closely.
 */
function getPathRideArc(
  head: number,
  center: number,
  width: number,
  fontSize: number,
) {
  return head - LEAD * fontSize - (width - center);
}

/** Opacity of a letter from how far onto the curve it has come. */
function getPathRideFade(arc: number, fontSize: number) {
  return Math.min(1, Math.max(0, arc / (FADE_IN * fontSize)));
}

interface Point {
  x: number;
  y: number;
}

interface PathSamples {
  length: number;
  points: Point[];
  tangents: Point[];
}

/** Points and unit tangents at evenly spaced arc lengths along `path`. */
function samplePath(path: string, count = SAMPLES): PathSamples {
  const length = getLength(path);
  const n = Math.max(2, Math.round(count));
  const points: Point[] = [];
  const tangents: Point[] = [];
  for (let i = 0; i < n; i++) {
    const at = (length * i) / (n - 1);
    // Both can come back null on a degenerate path; reuse the last sample.
    const p = getPointAtLength(path, at) ?? points[i - 1] ?? { x: 0, y: 0 };
    const tangent = getTangentAtLength(path, at) ??
      tangents[i - 1] ?? { x: 1, y: 0 };
    points.push({ x: p.x, y: p.y });
    tangents.push({ x: tangent.x, y: tangent.y });
  }
  return { length, points, tangents };
}

/** Position and unit tangent at arc length `s`, clamped to the path. */
function getPathSample(samples: PathSamples, s: number) {
  const n = samples.points.length;
  const u = samples.length > 0 ? (s / samples.length) * (n - 1) : 0;
  const i = Math.min(n - 2, Math.max(0, Math.floor(u)));
  const f = Math.min(1, Math.max(0, u - i));
  const a = samples.points[i];
  const b = samples.points[i + 1];
  const ta = samples.tangents[i];
  const tb = samples.tangents[i + 1];
  const tx = ta.x + (tb.x - ta.x) * f;
  const ty = ta.y + (tb.y - ta.y) * f;
  const norm = Math.hypot(tx, ty) || 1;
  return {
    x: a.x + (b.x - a.x) * f,
    y: a.y + (b.y - a.y) * f,
    tx: tx / norm,
    ty: ty / norm,
  };
}

interface PathRideStraight {
  /** Arc length that lands on the text's left edge. */
  start: number;
  /** Reference x of the text's left edge on the straight baseline. */
  left: number;
  /** Reference y of the straight baseline. */
  baseline: number;
}

interface PathRidePose {
  x: number;
  y: number;
  angle: number;
}

/**
 * A point of the path pulled `k` of the way from the curve to the straight
 * baseline, lifted `lift` along its normal. Arc length maps to x one to one,
 * so the text keeps its spacing while the curve pulls taut.
 */
function getPathRidePoint(
  samples: PathSamples,
  s: number,
  k: number,
  straight: PathRideStraight,
  lift = 0,
): PathRidePose {
  const p = getPathSample(samples, s);
  const x = p.x + (straight.left + (s - straight.start) - p.x) * k;
  const y = p.y + (straight.baseline - p.y) * k;
  const tx = p.tx + (1 - p.tx) * k;
  const ty = p.ty * (1 - k);
  const norm = Math.hypot(tx, ty) || 1;
  return {
    x: x + (ty / norm) * lift,
    y: y - (tx / norm) * lift,
    angle: Math.atan2(ty, tx),
  };
}

/** Polyline of the pulled path between two arc lengths. */
function getPathRideLine(
  samples: PathSamples,
  from: number,
  to: number,
  k: number,
  straight: PathRideStraight,
) {
  if (to <= from) return "";
  const step = samples.length / (samples.points.length - 1);
  const stops = [from];
  for (let s = Math.ceil(from / step) * step; s < to; s += step) {
    if (s > from) stops.push(s);
  }
  stops.push(to);
  return stops
    .map((s, i) => {
      const p = getPathRidePoint(samples, s, k, straight);
      return `${i === 0 ? "M" : "L"}${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
    })
    .join("");
}

function useMetrics(text: string, font: string, fallback: number) {
  const chars = Array.from(text);
  const key = chars.join("");
  const [metrics, setMetrics] = useState<{
    advances: number[];
    baseline: number;
    capHeight: number;
  } | null>(null);

  useEffect(() => {
    const handle = delayRender("path-ride: measuring the text");
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    const measure = () => {
      if (released) return;
      const ctx = document.createElement("canvas").getContext("2d");
      if (ctx) {
        ctx.font = font;
        const m = ctx.measureText("H");
        const ascent = m.fontBoundingBoxAscent / MEASURE_SIZE;
        const descent = m.fontBoundingBoxDescent / MEASURE_SIZE;
        setMetrics({
          advances: Array.from(key).map(
            (c) => ctx.measureText(c).width / MEASURE_SIZE,
          ),
          baseline:
            ascent > 0
              ? (1 - (ascent + descent)) / 2 + ascent
              : INTER_METRICS.baseline,
          capHeight:
            m.actualBoundingBoxAscent > 0
              ? m.actualBoundingBoxAscent / MEASURE_SIZE
              : INTER_METRICS.capHeight,
        });
      }
      release();
    };
    document.fonts.load(font, key).then(measure, measure);
    return release;
  }, [key, font]);

  return (
    metrics ?? {
      advances: chars.map(() => fallback),
      baseline: INTER_METRICS.baseline,
      capHeight: INTER_METRICS.capHeight,
    }
  );
}

function PathRideBase({
  text = pathRideDefaults.text,
  path = pathRideDefaults.path,
  fontSize = pathRideDefaults.fontSize,
  fontWeight = pathRideDefaults.fontWeight,
  fontFamily = pathRideDefaults.fontFamily,
  color = pathRideDefaults.color,
  lineColor = pathRideDefaults.lineColor,
  lineWidth = pathRideDefaults.lineWidth,
  speed = pathRideDefaults.speed,
  className,
}: PathRideProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const unit = height / 720;
  const t = getPathRideTime(frame, { fps, speed });
  const metrics = useMetrics(
    text,
    `${fontWeight} ${MEASURE_SIZE}px ${fontFamily}`,
    0.55,
  );
  const samples = useMemo(() => samplePath(path), [path]);
  const chars = Array.from(text);
  const advances = metrics.advances.map((a) => a * fontSize);
  const { centers, width: textWidth } = getPathRideCenters(advances);
  const length = samples.length;
  const head = getPathRideHead(t, length);
  const tail = getPathRideTail(t, length);
  const k = getPathRideStraighten(t);
  const lift = lineWidth / 2 + LIFT * fontSize;
  // The line settles `lift` below the text so the capitals center on the frame.
  const straight: PathRideStraight = {
    start: getPathRideArc(length, 0, textWidth, fontSize),
    left: 640 - textWidth / 2,
    baseline: 360 + (metrics.capHeight * fontSize) / 2 + lift,
  };
  const tip = getPathRidePoint(samples, head, k, straight);
  const tipOpacity = interpolate(
    head,
    [0, length * 0.02, length * 0.98, length],
    [0, 1, 1, 0],
    CLAMP,
  );
  // Reference space (1280×720, y down) mapped onto the composition.
  const toX = (x: number) => width / 2 + (x - 640) * unit;
  const toY = (y: number) => height / 2 + (y - 360) * unit;
  const size = fontSize * unit;
  const line = getPathRideLine(samples, tail, head, k, straight);

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
      >
        <g
          transform={`translate(${toX(0)} ${toY(0)}) scale(${unit})`}
          fill="none"
        >
          {line ? (
            <path
              d={line}
              stroke={lineColor}
              strokeWidth={lineWidth}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          ) : null}
          {tipOpacity > 0 ? (
            <circle
              cx={tip.x}
              cy={tip.y}
              r={lineWidth * 1.6}
              fill={lineColor}
              opacity={tipOpacity}
            />
          ) : null}
        </g>
      </svg>
      {chars.map((char, j) => {
        const arc = getPathRideArc(head, centers[j], textWidth, fontSize);
        const fade = getPathRideFade(arc, fontSize);
        if (fade <= 0) return null;
        const pose = getPathRidePoint(samples, arc, k, straight, lift);
        return (
          <span
            key={j}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              fontFamily,
              fontSize: size,
              lineHeight: 1,
              fontWeight,
              fontVariationSettings: `"wght" ${fontWeight}`,
              color,
              whiteSpace: "pre",
              opacity: fade,
              transformOrigin: "0 0",
              transform: `translate(${toX(pose.x)}px, ${toY(pose.y)}px) rotate(${pose.angle}rad) translate(-50%, ${-metrics.baseline * size}px)`,
            }}
          >
            {char}
          </span>
        );
      })}
    </div>
  );
}

