        ))}
        <linearGradient id={id("haze")} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#D9958A" stopOpacity="0" />
          <stop offset="0.55" stopColor="#D9958A" stopOpacity="1" />
