  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["count","size","arm","growFrames","pulseFrames","rotation","background","color","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  count: 420,
  size: 1,
  arm: 21,
  growFrames: 60,
  pulseFrames: 45,
  rotation: 4,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
  speed: 1,
};

type PhyllotaxisElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PhyllotaxisBase>;

const PhyllotaxisInner = forwardRef<
  HTMLDivElement,
  PhyllotaxisElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Phyllotaxis>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PhyllotaxisBase
          {...(componentProps as unknown as ComponentProps<typeof PhyllotaxisBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Phyllotaxis = Interactive.withSchema({
  Component: PhyllotaxisInner,
  componentName: "<Phyllotaxis>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

