  },
  step: {
    type: "number",
    default: 40,
    min: 0,
    max: 120,
    step: 1,
    description: "Step",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","highlight","step","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: 0,
  step: 40,
  speed: 1,
};

type PlainLicenseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PlainLicenseBase>;

const PlainLicenseInner = forwardRef<
  HTMLDivElement,
  PlainLicenseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PlainLicense>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PlainLicenseBase
          {...(componentProps as unknown as ComponentProps<typeof PlainLicenseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PlainLicense = Interactive.withSchema({
  Component: PlainLicenseInner,
  componentName: "<PlainLicense>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

