const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","role","stat","highlight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "Play of the game",
  role: "Solo builder",
  stat: "Shipped in 6 hours",
  highlight: "6 hours",
