              position: "absolute",
              left: L.pad + 4 * u,
              right: L.pad + 4 * u,
              top: L.pad + 2 * u,
              fontSize: fs,
              fontWeight: 300,
              letterSpacing: "-0.01em",
              lineHeight: 1.32,
              color: typed > 0 ? palette.ink : palette.faint,
