          </div>
          <div
            style={{
              position: "absolute",
              left: L.pad,
              bottom: L.pad,
              height: btn.r * 2,
              display: "flex",
              alignItems: "center",
              gap: 8 * u,
              fontSize: small,
              color: palette.muted,
            }}
          >
            <div
              style={{
                width: 36 * u,
                height: 36 * u,
                borderRadius: 99,
                boxShadow: `inset 0 0 0 1px ${palette.hairline}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Icon d={ICONS.plus} size={17 * u} color={palette.muted} />
            </div>
            {["Film", "16:9"].map((c) => (
              <div
                key={c}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 4 * u,
                  padding: `${7 * u}px ${12 * u}px`,
