            }}
          >
            <Icon d={ICONS.wave} size={20 * u} color={palette.muted} />
          </div>
        </div>
        <div
          style={{
            position: "absolute",
            left: L.tall ? cx : 0,
            width: L.tall ? cw : W,
            top: L.suggY,
            display: "flex",
            flexDirection: L.tall ? "column" : "row",
            justifyContent: "center",
