function RollingNumber({
  value,
  frame,
  start,
  lineHeight,
}: {
  value: string;
  frame: number;
  start: number;
  lineHeight: number;
}) {
  return (
    <span style={{ display: "inline-flex", height: lineHeight }}>
      {value.split("").map((ch, i) => {
        const p = interpolate(
          frame,
          [start + i * 2, start + i * 2 + 14],
          [0, 1],
          { ...clamp, easing: LIGHT },
        );
        if (!/\d/.test(ch)) return <span key={`${ch}-${i}`}>{ch}</span>;
        const pos = Number(ch) + (2 + i) * (1 - p);
        const shown = Math.round(pos);
        const off = pos - shown;
        return (
          <span
            key={`${ch}-${i}`}
            style={{
              display: "inline-block",
              width: "0.6em",
              textAlign: "center",
              lineHeight: `${lineHeight}px`,
              opacity: 1 - Math.abs(off) * 0.9,
              transform: `translateY(${off * lineHeight * 0.18}px)`,
            }}
          >
            {shown % 10}
          </span>
        );
      })}
    </span>
  );
}

function pressScale(frame: number, at: number, fps: number) {
  const down = spring({ frame: frame - at, fps, config: CHIP });
  const up = spring({ frame: frame - at - 4, fps, config: CHIP });
  return 1 - 0.04 * (down - up);
}

interface CardProps {
  plan: PricingPlan;
  index: number;
  pal: Pal;
  accent: string;
  currency: string;
  discountLabel: string;
  badgeLabel: string;
  frame: number;
  fps: number;
  width: number;
  height: number;
  compact: boolean;
}

function PlanCard({
  plan,
  index,
  pal,
  accent,
  currency,
  discountLabel,
  badgeLabel,
  frame,
  fps,
  width,
  height,
  compact,
}: CardProps) {
  const featured = !!plan.featured;
  const enterAt = B.cards + index * B.stagger;
  const rise = spring({ frame: frame - enterAt, fps, config: CARD });
  const fade = interpolate(frame, [enterAt, enterAt + 10], [0, 1], {
    ...clamp,
    easing: ENTER,
  });
  const lift = spring({ frame: frame - B.lift, fps, config: HEAVY });
  const recede = featured
    ? 0
    : spring({ frame: frame - B.lift, fps, config: MORPH });
  const strike = featured
    ? interpolate(frame, [B.strike, B.strike + 9], [0, 1], {
        ...clamp,
        easing: MOVE,
      })
    : 0;
  const settle = featured
    ? spring({ frame: frame - B.roll, fps, config: MORPH })
    : 0;
  const fill = featured
    ? interpolate(frame, [B.fill, B.fill + 8], [0, 1], {
        ...clamp,
        easing: ENTER,
      })
    : 0;
  const tag = featured
    ? spring({ frame: frame - B.tag, fps, config: CHIP })
    : 0;
  const press = featured ? pressScale(frame, B.press, fps) : 1;
  const hasWas = featured && plan.was !== undefined;

  const priceSize = compact ? 48 : 64;
  const lh = Math.round(priceSize * 1.04);
  const strap = 26;
  const blockH = hasWas || !compact ? lh + strap : lh;
  const oldScale = interpolate(settle, [0, 1], [1, 0.32]);
  const oldY = interpolate(settle, [0, 1], [strap, 0]);
  const liftY = featured ? -10 * lift : 6 * recede;

  const price = (value: number | string, faded = false) => (
    <span
      style={{
        fontSize: priceSize,
        fontWeight: 300,
        letterSpacing: "-0.045em",
        lineHeight: `${lh}px`,
        fontVariantNumeric: "tabular-nums",
        color: faded ? pal.faint : pal.text,
      }}
    >
      {currency}
      {value}
    </span>
  );

  const period = (o = 1) => (
    <span
      style={{
        fontFamily: mono.fontFamily,
        fontSize: 16,
        lineHeight: "20px",
        color: pal.faint,
        marginLeft: 10,
        marginBottom: 8,
        alignSelf: "flex-end",
        opacity: o,
        whiteSpace: "nowrap",
      }}
    >
      {plan.period}
    </span>
  );

  const priceBlock = (
    <div
      style={{
        position: "relative",
        height: blockH,
        width: compact ? 200 : undefined,
        flexShrink: 0,
      }}
    >
      {hasWas ? (
        <>
          <div
            style={{
              position: "absolute",
              left: 0,
              top: oldY,
              transformOrigin: "0 0",
              transform: `scale(${oldScale})`,
              display: "flex",
              alignItems: "center",
              whiteSpace: "nowrap",
            }}
          >
            <span style={{ position: "relative" }}>
              {price(plan.was as number | string, settle > 0.5)}
              <span
                style={{
                  position: "absolute",
                  left: -4,
                  top: "52%",
                  height: 3 / Math.max(0.4, oldScale),
                  width: `calc(${strike * 100}% + ${8 * strike}px)`,
                  background: accent,
                  borderRadius: 4,
                  transformOrigin: "0 50%",
                }}
              />
            </span>
          </div>
          <div
            style={{
              position: "absolute",
              left: 0,
              top: strap,
              display: "flex",
              alignItems: "center",
              opacity: interpolate(frame, [B.roll + 1, B.roll + 5], [0, 1], {
                ...clamp,
                easing: ENTER,
              }),
            }}
          >
            <span
              style={{
                display: "inline-flex",
                fontSize: priceSize,
                fontWeight: 300,
                letterSpacing: "-0.045em",
                lineHeight: `${lh}px`,
                fontVariantNumeric: "tabular-nums",
                color: pal.text,
              }}
            >
              <span style={{ opacity: settle }}>{currency}</span>
              <RollingNumber
                value={String(plan.price)}
                frame={frame}
                start={B.roll + 2}
                lineHeight={lh}
              />
            </span>
            {period(settle)}
          </div>
          <div
            style={{
              position: "absolute",
              right: 0,
              top: -2,
              height: 28,
              padding: "0 9px",
              borderRadius: 6,
              background: accent,
              color: "#fff",
              fontSize: 16,
              lineHeight: "28px",
              whiteSpace: "nowrap",
              fontVariantNumeric: "tabular-nums",
              opacity: interpolate(tag, [0, 0.25], [0, 1], clamp),
              transformOrigin: "100% 50%",
              transform: `translateY(${(1 - tag) * -14}px) rotate(${(1 - tag) * -8 - 2}deg) scale(${0.8 + 0.2 * tag})`,
            }}
          >
            {discountLabel}
          </div>
        </>
      ) : (
        <div
          style={{
            position: "absolute",
            left: compact ? undefined : 0,
            right: compact ? 0 : undefined,
            bottom: 0,
            display: "flex",
            alignItems: "center",
          }}
        >
          {price(plan.price)}
          {period()}
        </div>
      )}
    </div>
  );

  const button = (
    <div
      style={{
        height: 46,
        borderRadius: 10,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 8,
        fontSize: 16,
        flexShrink: 0,
        background: featured ? (fill > 0 ? accent : pal.ink) : "transparent",
        color: featured ? (fill > 0 ? "#fff" : pal.inkText) : pal.text,
        boxShadow: featured
          ? `inset 0 1px 0 rgba(255,255,255,${0.18 * fill})`
          : `inset 0 0 0 1px ${pal.dark ? "rgba(255,255,255,0.14)" : "rgba(22,23,27,0.14)"}`,
        transform: `scale(${press})`,
      }}
    >
      {plan.cta}
      {featured ? <Arrow /> : null}
    </div>
  );

  const ring =
    featured && lift > 0.01
      ? `0 0 0 ${1 + 0.5 * lift}px ${withAlpha(accent, 0.25 + 0.75 * lift)}`
      : `0 0 0 1px ${pal.ring}`;

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        flexShrink: 0,
        opacity: fade * (1 - 0.32 * recede),
        transform: `translateY(${(1 - rise) * 56 + liftY}px) scale(${(0.96 + 0.04 * rise) * (1 + 0.025 * (featured ? lift : -recede * 0.6))})`,
        zIndex: featured ? 2 : 1,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 18,
          background: pal.card,
          backdropFilter: pal.dark ? "blur(24px)" : undefined,
          boxShadow: `${ring}, ${pal.depth}`,
          padding: compact ? "22px 26px" : "24px 26px",
          boxSizing: "border-box",
          display: "flex",
          flexDirection: compact ? "row" : "column",
          alignItems: compact ? "center" : "stretch",
          gap: compact ? 24 : 0,
        }}
      >
        <div style={{ flex: compact ? 1 : undefined, minWidth: 0 }}>
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              justifyContent: "space-between",
              fontSize: 22,
              color: pal.text,
              letterSpacing: "-0.01em",
            }}
          >
            {plan.name}
            {featured ? (
              <span
                style={{
                  fontFamily: mono.fontFamily,
                  fontSize: 16,
                  color: accent,
                  opacity: lift,
                }}
              >
                {badgeLabel}
              </span>
            ) : null}
          </div>
          <div
            style={{
              fontSize: 16,
              lineHeight: 1.4,
              color: pal.muted,
              marginTop: 6,
              height: compact ? undefined : 45,
              whiteSpace: compact ? "nowrap" : undefined,
              overflow: compact ? "hidden" : undefined,
              textOverflow: compact ? "ellipsis" : undefined,
              textWrap: "pretty",
            }}
          >
            {plan.description}
          </div>
        </div>
        {compact ? (
          priceBlock
        ) : (
          <>
            <div style={{ marginTop: 18 }}>{priceBlock}</div>
            <div style={{ marginTop: 18 }}>{button}</div>
            <div
              style={{
                height: 1,
                background: pal.rule,
                margin: "22px 0 12px",
                flexShrink: 0,
              }}
            />
            {plan.features.map((feat, j) => {
              const a = spring({
                frame: frame - (B.features + index * B.stagger + j * 2),
                fps,
                config: CARD,
              });
              return (
                <div
                  key={feat}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10,
                    height: 30,
                    fontSize: 16,
                    color: pal.text,
                    opacity: interpolate(a, [0, 0.6], [0, 1], clamp),
                    transform: `translateY(${(1 - a) * 10}px)`,
                    whiteSpace: "nowrap",
                  }}
                >
                  <Check color={featured ? accent : pal.faint} />
                  {feat}
                </div>
              );
            })}
          </>
        )}
      </div>
    </div>
  );
}

export function PricingReveal({
  plans = DEFAULT_PLANS,
  currency = "$",
  discountLabel = "−35% launch week",
  badgeLabel = "Most picked",
  eyebrow = "Billed monthly · cancel anytime",
  heading = "Simple pricing for every launch.",
  theme = "light",
  accent = "#3B5BFD",
  speed = 1,
  ground,
  groundParams,
}: PricingRevealProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const tall = height > width;
  const W = tall ? 720 : 1280;
  const H = tall ? 1280 : 720;
  const u = Math.min(width / W, height / H);
  const pal = palette(theme);

  const head = interpolate(frame, [B.head, B.head + 16], [0, 1], {
    ...clamp,
    easing: ENTER,
  });
  const meta = interpolate(frame, [B.head + 6, B.head + 20], [0, 1], {
    ...clamp,
    easing: LIGHT,
  });
  const camera = interpolate(frame, [0, 100], [1.035, 1], {
    ...clamp,
    easing: CAMERA,
  });

  const M = tall ? 48 : 72;
  const gap = tall ? 32 : 20;
  const cardW = tall ? W - M * 2 : (W - M * 2 - gap * 2) / 3;
  const fullH = tall ? 500 : 470;
  const compactH = 150;

  return (
    <AbsoluteFill
      style={{
        fontFamily: geist.fontFamily,
        overflow: "hidden",
        WebkitFontSmoothing: "antialiased",
      }}
    >
      <GshGround
        preset={ground ?? (pal.dark ? "earthshine" : "paper-crease")}
        params={groundParams}
        timeOffset={pal.dark ? 6 : 3}
        timeScale={0.4}
      />
      {pal.dark ? null : (
        <AbsoluteFill style={{ background: "rgba(240,238,234,0.38)" }} />
      )}
      <div
        style={{
          position: "absolute",
          left: (width - W * u) / 2,
          top: (height - H * u) / 2,
          width: W,
          height: H,
          transformOrigin: "0 0",
          transform: `scale(${u})`,
        }}
      >
        <AbsoluteFill
          style={{
            transform: `scale(${camera})`,
            transformOrigin: "50% 60%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: M,
              right: M,
              top: tall ? 96 : 58,
              display: "flex",
              flexDirection: tall ? "column" : "row",
              alignItems: tall ? "flex-start" : "flex-end",
              justifyContent: "space-between",
              gap: tall ? 20 : 24,
            }}
          >
            <div
              style={{
                fontFamily: serif.fontFamily,
                fontWeight: 400,
                fontSize: tall ? 64 : 54,
                lineHeight: 1.02,
                letterSpacing: "-0.02em",
                color: pal.text,
                maxWidth: tall ? 560 : 720,
                textWrap: "balance",
                clipPath: "inset(-10% -5% -20% -5%)",
              }}
            >
              <div
                style={{
                  transform: `translateY(${(1 - head) * 40}px)`,
                  opacity: head,
                }}
              >
                {heading}
              </div>
            </div>
            <div
              style={{
                fontFamily: mono.fontFamily,
                fontSize: 16,
                color: pal.muted,
                paddingBottom: tall ? 0 : 8,
                whiteSpace: "nowrap",
                opacity: meta,
                transform: `translateY(${(1 - meta) * 10}px)`,
              }}
            >
              {eyebrow}
            </div>
          </div>
          <div
            style={{
              position: "absolute",
              top: tall ? 340 : 186,
              left: M,
              right: M,
              display: "flex",
              flexDirection: tall ? "column" : "row",
              alignItems: "flex-start",
              gap,
            }}
          >
            {plans.map((plan, i) => {
              const compact = tall && !plan.featured;
              return (
                <PlanCard
                  key={plan.name}
                  plan={plan}
                  index={i}
                  pal={pal}
                  accent={accent}
                  currency={currency}
                  discountLabel={discountLabel}
                  badgeLabel={badgeLabel}
                  frame={frame}
                  fps={fps}
                  width={cardW}
                  height={compact ? compactH : fullH}
                  compact={compact}
                />
              );
            })}
          </div>
        </AbsoluteFill>
      </div>
    </AbsoluteFill>
  );
}

import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const geist = loadGeist("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", { weights: ["400"], subsets: ["latin"] });
const serif = loadSerif("italic", { weights: ["400"], subsets: ["latin"] });

interface PromptRestyleProps {
  headline?: string;
  highlight?: string;
  instructions?: string[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const HALO = ["#fff4ec", "#ffb36b", "#e2457a", "#3d4dff"] as const;
const RIBBON = ["#ff3d9a", "#ff8a3d", "#ffc83d", "#7a5cff"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    draft: "#6E6D73",
    muted: "#8E8D94",
    hero: (a: string) =>
      `linear-gradient(100deg, ${HALO[1]} 0%, ${HALO[2]} 48%, ${a} 100%)`,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    draft: "#A3A19B",
    muted: "#6E6C67",
    hero: (a: string) =>
      `linear-gradient(100deg, ${RIBBON[1]} 0%, ${RIBBON[0]} 46%, ${a} 100%)`,
  },
} as const;

const SERIF_SCALE = 1.22;
const SERIF_TRACK = -0.02;

interface Style {
  size: number;
  wght: number;
  track: number;
  lead: number;
}
const S0: Style = { size: 0.42, wght: 300, track: 0.01, lead: 1.3 };
const S1: Style = { size: 0.8, wght: 500, track: 0.01, lead: 1.3 };
const S2: Style = { size: 1, wght: 500, track: -0.04, lead: 1.02 };

const TYPE_RATE = 1.6;
const ENTER_PAUSE = 6;
const APPLY = 24;
const NEXT_GAP = 20;
const FIRST_AT = 16;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Token {
  text: string;
  hero: boolean;
}

interface Layout {
  lines: Token[][];
  F: number;
  heroSans: number;
  heroSerif: number;
  sansAsc: number;
  sansDesc: number;
  serifAsc: number;
  serifDesc: number;
}

function tokenize(headline: string, highlight: string): Token[] {
  const words = headline.split(/\s+/).filter(Boolean);
  const hw = highlight.split(/\s+/).filter(Boolean);
  if (hw.length > 0) {
    for (let i = 0; i + hw.length <= words.length; i++) {
      const slice = words.slice(i, i + hw.length);
      const ok = slice.every((w, k) =>
        k === hw.length - 1
          ? w.replace(/[.,!?;:]+$/, "") === hw[k]
          : w === hw[k],
      );
      if (!ok) continue;
      const last = slice[slice.length - 1];
      const tail = last.slice(hw[hw.length - 1].length);
      const out: Token[] = words
        .slice(0, i)
        .map((text) => ({ text, hero: false }));
      out.push({ text: hw.join(" "), hero: true });
      if (tail) out.push({ text: tail, hero: false });
      for (const text of words.slice(i + hw.length))
        out.push({ text, hero: false });
      return out;
    }
  }
  return words.map((text) => ({ text, hero: false }));
}

function measureLayout(
  tokens: Token[],
  W: number,
  H: number,
  heroOn: boolean,
): Layout {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("prompt-restyle: no 2d context");
  const PX = 200;
  const sansW = (s: string) => {
    ctx.font = `500 ${PX}px "${geist.fontFamily}"`;
    return ctx.measureText(s).width / PX + S2.track * Array.from(s).length;
  };
  const serifW = (s: string) => {
    ctx.font = `400 ${PX}px "${serif.fontFamily}"`;
    return (
      (ctx.measureText(s).width / PX + SERIF_TRACK * Array.from(s).length) *
      SERIF_SCALE
    );
  };
  const space = sansW(" ");
  const tokW = tokens.map((t) =>
    t.hero && heroOn ? serifW(t.text) : sansW(t.text),
  );
  const glue = tokens.map((t) => /^[.,!?;:]+$/.test(t.text));

  const lineWidth = (a: number, b: number) => {
    let w = 0;
    for (let i = a; i < b; i++) w += tokW[i] + (i > a && !glue[i] ? space : 0);
    return w;
  };
  const breaks = tokens.map((_, i) => i > 0 && !glue[i]);

  let best: { lines: number[]; F: number } | null = null;
  const n = tokens.length;
  for (let L = 1; L <= Math.min(4, n); L++) {
    let bestCut: number[] | null = null;
    let bestMax = Number.POSITIVE_INFINITY;
    const cut = (start: number, left: number, acc: number[], max: number) => {
      if (max >= bestMax) return;
      if (left === 1) {
        const m = Math.max(max, lineWidth(start, n));
        if (m < bestMax) {
          bestMax = m;
          bestCut = [...acc];
        }
        return;
      }
      for (let i = start + 1; i <= n - left + 1; i++) {
        if (!breaks[i]) continue;
        cut(i, left - 1, [...acc, i], Math.max(max, lineWidth(start, i)));
      }
    };
    cut(0, L, [], 0);
    if (!bestCut) continue;
    const F = Math.min(
      (W * 0.84) / bestMax,
      (H * 0.52) / (L * S2.lead),
      H * 0.2,
    );
    if (!best || F > best.F * 1.12) best = { lines: bestCut, F };
  }
  const cuts = best ? best.lines : [];
  const lines: Token[][] = [];
  let s = 0;
  for (const c of [...cuts, n]) {
    lines.push(tokens.slice(s, c));
    s = c;
  }
  const hero = tokens.find((t) => t.hero);
  ctx.font = `500 ${PX}px "${geist.fontFamily}"`;
  const ms = ctx.measureText("Hg");
  ctx.font = `italic 400 ${PX}px "${serif.fontFamily}"`;
  const mr = ctx.measureText("Hg");
  return {
    sansAsc: ms.fontBoundingBoxAscent / PX,
    sansDesc: ms.fontBoundingBoxDescent / PX,
    serifAsc: mr.fontBoundingBoxAscent / PX,
    serifDesc: mr.fontBoundingBoxDescent / PX,
    lines,
    F: best ? best.F : H * 0.1,
    heroSans: hero ? sansW(hero.text) : 0,
    heroSerif: hero ? serifW(hero.text) : 0,
  };
}

function useLayout(tokens: Token[], W: number, H: number, heroOn: boolean) {
  const [layout, setLayout] = useState<Layout | null>(null);
  const [handle] = useState(() => delayRender("prompt-restyle: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      geist.waitUntilDone(),
      serif.waitUntilDone(),
      mono.waitUntilDone(),
      document.fonts.load(`500 100px "${geist.fontFamily}"`),
      document.fonts.load(`italic 400 100px "${serif.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setLayout(measureLayout(tokens, W, H, heroOn));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [tokens, W, H, heroOn, handle]);
  return layout;
}

const lerp = (a: number, b: number, k: number) => a + (b - a) * k;

function PromptRestyleBase({
  headline = "Launch videos from parts you own.",
  highlight = "you own",
  instructions,
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: PromptRestyleProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;

  const tokens = useMemo(
    () => tokenize(headline, highlight),
    [headline, highlight],
  );
  const heroOn = tokens.some((tk) => tk.hero);
  const layout = useLayout(tokens, W, H, heroOn);

  const steps = useMemo(() => {
    const d = [
      "make it bigger",
      "tighten it up",
      `set “${highlight}” in serif`,
    ];
    const list = (instructions ?? d).slice(0, heroOn ? 3 : 2);
    const out: { text: string; start: number; enter: number }[] = [];
    let at = FIRST_AT;
    for (const text of list) {
      const enter = at + Math.ceil(text.length / TYPE_RATE) + ENTER_PAUSE;
      out.push({ text, start: at, enter });
      at = enter + NEXT_GAP;
    }
    return out;
  }, [instructions, highlight, heroOn]);

  if (!layout) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const apply = (i: number) =>
    steps[i]
      ? interpolate(t, [steps[i].enter, steps[i].enter + APPLY], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })
      : 0;
  const k1 = apply(0);
  const k2 = apply(1);
  const k3 = apply(2);

  const st: Style = {
    size: lerp(lerp(S0.size, S1.size, k1), S2.size, k2),
    wght: lerp(S0.wght, S1.wght, k1),
    track: lerp(S0.track, S2.track, k2),
    lead: lerp(S0.lead, S2.lead, k2),
  };
  const F = layout.F;
  const size = st.size * F;
  const ink = interpolateColors(k1, [0, 1], [c.draft, c.ink]);
  const enterIn = interpolate(t, [0, 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const lineH = size * st.lead;
  const blockH = lineH * layout.lines.length;
  const centerY = H * 0.46;

  const sansStyle: React.CSSProperties = {
    fontFamily: geist.fontFamily,
    fontWeight: 400,
    fontVariationSettings: `"wght" ${st.wght.toFixed(1)}`,
    letterSpacing: `${st.track}em`,
    color: ink,
  };

  const heroNode = (text: string) => {
    if (k3 <= 0) return <span style={sansStyle}>{text}</span>;
    const wSans = layout.heroSans * size;
    const wSerif = layout.heroSerif * size;
    const w = lerp(wSans, wSerif + size * 0.17, k3);
    const roll = lineH * 1.1;
    const sz = size * SERIF_SCALE;
    const baseSans =
      (lineH - (layout.sansAsc + layout.sansDesc) * size) / 2 +
      layout.sansAsc * size;
    const baseSerif =
      (lineH - (layout.serifAsc + layout.serifDesc) * sz) / 2 +
      layout.serifAsc * sz;
    const dy = baseSans - baseSerif;
    return (
      <span
        style={{
          position: "relative",
          display: "inline-block",
          width: w,
          height: lineH,
          verticalAlign: "top",
          clipPath: `inset(0 ${-size * 0.4}px)`,
        }}
      >
        <span
          style={{
            ...sansStyle,
            position: "absolute",
            left: (w - wSans) / 2,
            top: 0,
            lineHeight: `${lineH}px`,
            whiteSpace: "pre",
            opacity: 1 - k3,
            transform: `translateY(${(-k3 * roll).toFixed(2)}px)`,
          }}
        >
          {text}
        </span>
        <span
          style={{
            position: "absolute",
            left: (w - wSerif - size * 0.17) / 2,
            top: dy,
            width: wSerif + size * 0.3,
            paddingRight: size * 0.1,
            lineHeight: `${lineH}px`,
            whiteSpace: "pre",
            fontFamily: serif.fontFamily,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: sz,
            letterSpacing: `${SERIF_TRACK}em`,
            backgroundImage: c.hero(accent),
            backgroundSize: "100% 100%",
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            transform: `translateY(${((1 - k3) * roll).toFixed(2)}px)`,
          }}
        >
          {text}
        </span>
      </span>
    );
  };

  let active: (typeof steps)[number] | undefined;
  for (const s of steps) if (t >= s.start) active = s;
  let instruction: React.ReactNode = null;
  if (active) {
    const typed = Math.min(
      active.text.length,
      Math.floor((t - active.start) * TYPE_RATE),
    );
    const gone = interpolate(t, [active.enter, active.enter + 10], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const show = interpolate(
      t,
      [active.start, active.start + 5],
      [0, 1],
      CLAMP,
    );
    const monoSize = Math.max(16, Math.min(W, H) * 0.04);
    const blink = t < active.enter && Math.floor((t - active.start) / 8) % 2;
    instruction = (
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: H * 0.84 - monoSize / 2,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: monoSize * 0.6,
          fontFamily: mono.fontFamily,
          fontWeight: 400,
          fontSize: monoSize,
          lineHeight: 1,
          color: c.muted,
          whiteSpace: "pre",
          opacity: show * (1 - gone),
          transform: `translateY(${(-gone * monoSize * 1.2).toFixed(2)}px)`,
        }}
      >
        <span style={{ color: accent }}>›</span>
        <span style={{ position: "relative" }}>
          <span style={{ visibility: "hidden" }}>{active.text}</span>
          <span style={{ position: "absolute", left: 0, top: 0 }}>
            {active.text.slice(0, typed)}
            <span
              style={{
                display: "inline-block",
                width: Math.max(2, monoSize * 0.08),
                height: monoSize * 1.1,
                marginLeft: 2,
                verticalAlign: "-0.2em",
                background: accent,
                opacity: blink ? 0 : 1,
              }}
            />
          </span>
        </span>
      </div>
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: centerY - blockH / 2,
          opacity: enterIn,
          transform: `translateY(${((1 - enterIn) * F * 0.15).toFixed(2)}px)`,
          fontSize: size,
          lineHeight: `${lineH}px`,
        }}
      >
        {layout.lines.map((line, li) => (
          <div
            key={`line-${li}-${line.map((tk) => tk.text).join("_")}`}
            style={{
              display: "flex",
              justifyContent: "center",
              height: lineH,
              whiteSpace: "pre",
            }}
          >
            {line.map((tk, ti) => {
              const glued = /^[.,!?;:]+$/.test(tk.text);
              const lead = ti > 0 && !glued ? " " : "";
              return (
                <span key={`${tk.text}-${ti}`} style={{ display: "flex" }}>
                  {lead ? <span style={sansStyle}>{lead}</span> : null}
                  {tk.hero && heroOn ? (
                    heroNode(tk.text)
                  ) : (
                    <span style={sansStyle}>{tk.text}</span>
                  )}
                </span>
              );
            })}
          </div>
        ))}
      </div>
      {instruction}
    </AbsoluteFill>
  );
}

