const ELEMENT_PROP_KEYS = new Set(["theme","accent","headline","highlight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  headline: "Launch videos from parts you own.",
  highlight: "you own",
  speed: 1,
};

type PromptRestyleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PromptRestyleBase>;

const PromptRestyleInner = forwardRef<
  HTMLDivElement,
  PromptRestyleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PromptRestyle>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PromptRestyleBase
          {...(componentProps as unknown as ComponentProps<typeof PromptRestyleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PromptRestyle = Interactive.withSchema({
  Component: PromptRestyleInner,
  componentName: "<PromptRestyle>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

