function arc(
  a: { x: number; y: number },
  b: { x: number; y: number },
  p: number,
) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const d = Math.hypot(dx, dy) || 1;
  const lift = Math.sin(p * Math.PI) * Math.min(40, d * 0.12);
  return {
    x: a.x + dx * p + (-dy / d) * lift,
    y: a.y + dy * p + (dx / d) * lift,
  };
}

