function Section({
  start,
  done,
  frame,
  label,
  accent,
  skeleton,
  children,
  height,
}: {
  start: number;
  done: number;
  frame: number;
  label: string;
  accent: string;
  skeleton: React.ReactNode;
  children: React.ReactNode;
  height: number;
}) {
  const shown = tween(frame, start - 2, start + 5);
  const real = tween(frame, start + 8, start + 15);
  const edit =
    tween(frame, start, start + 5) * (1 - tween(frame, done + 2, done + 9));
  if (shown <= 0) return <div style={{ height }} />;
  return (
    <div style={{ position: "relative", height }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: shown * (1 - tween(frame, start + 8, start + 11)),
        }}
      >
        {skeleton}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: real,
          transform: `translateY(${(1 - real) * 6}px)`,
        }}
      >
        {children}
      </div>
      {edit > 0 ? (
        <>
          <div
            style={{
              position: "absolute",
              inset: 3,
              borderRadius: 6,
              boxShadow: `inset 0 0 0 1.5px ${withAlpha(accent, 0.85 * edit)}`,
              pointerEvents: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              left: 3,
              top: 3,
              transform: `translateY(${(1 - edit) * 2}px)`,
              opacity: edit,
              fontFamily,
              fontSize: 11,
              fontWeight: 400,
              color: "#fff",
              background: accent,
              borderRadius: "6px 0 6px 0",
              padding: "2px 7px",
            }}
          >
            {label}
          </div>
        </>
      ) : null}
    </div>
  );
}

