                file(2).start + 17 + i * 3,
              );
              return (
                <div
                  key={p.name}
                  style={{
                    flex: 1,
                    borderRadius: 10,
                    background: "#FFFFFF",
                    boxShadow:
                      "0 0 0 1px rgba(42,33,28,0.08), 0 1px 2px rgba(42,33,28,0.04)",
                    padding: 8,
                    opacity: a,
                    transform: `translateY(${(1 - a) * 8}px)`,
                  }}
                >
                  <div
                    style={{
                      height: 64,
                      borderRadius: 6,
                      background: `linear-gradient(135deg, ${p.tone[0]}, ${p.tone[1]})`,
                      position: "relative",
                      overflow: "hidden",
                    }}
                  >
                    <svg
                      width={40}
                      height={64}
                      viewBox="0 0 40 64"
                      style={{ position: "absolute", right: 16, bottom: 0 }}
                    >
                      <path
                        d="M16 4h8v14c6 4 8 9 8 16v30H8V34c0-7 2-12 8-16z"
                        fill="rgba(20,12,8,0.32)"
                      />
                      <rect
                        x="11"
                        y="38"
                        width="18"
                        height="14"
                        rx="1.5"
                        fill="rgba(255,250,240,0.75)"
                      />
                    </svg>
                  </div>
                  <div style={{ padding: "8px 4px 2px" }}>
                    <div style={{ fontSize: 13, fontWeight: 400 }}>
                      {p.name}
                    </div>
                    <div
                      style={{
                        display: "flex",
                        fontSize: 12,
                        color: SITE.muted,
                        marginTop: 3,
                      }}
                    >
                      <span>{p.origin}</span>
                      <span
                        style={{
                          marginLeft: "auto",
                          fontVariantNumeric: "tabular-nums",
                          color: SITE.ink,
                        }}
                      >
                        {p.price}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </Section>
    </div>
  );
}

export function PromptToApp({
  prompt = DEFAULT_PROMPT,
  plan = DEFAULT_PLAN,
  files = [
    "components/Nav.tsx",
    "components/Hero.tsx",
    "components/PourCards.tsx",
    "app/page.tsx",
  ],
  doneMessage = "Fernway is ready. The booking button links to your reservations page.",
  projectName = "fernway-site",
  deployUrl = "fernway.remocn.app",
  siteName = "Fernway",
  siteEyebrow = "Wine bar · Open late",
  siteHeadline = "Natural wine, small plates, one long table.",
  siteBody = "Low-intervention bottles and seasonal plates in the Mission. Walk-ins welcome until 10.",
  siteLinks = ["Menu", "Wine list", "Events", "Visit"],
  pours = DEFAULT_POURS,
  children,
  theme = "light",
  accent = "#3B5BFD",
  speed = 1,
  ground,
  groundParams,
}: PromptToAppProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const tall = H > W;
  const L = tall ? LAYOUT_TALL : LAYOUT_WIDE;
  const u = W / L.w;
  const pal = palette(theme);
  const planWords = plan.split(" ");
  const tl = timeline(prompt.length, planWords.length);
  const file = (i: number) => tl.file(i);
  const sp = (at: number, config: SpringCfg, durationInFrames?: number) =>
    spring({ frame: frame - at, fps, config, durationInFrames });

  const chatIn = sp(0, HEAVY);
  const dock = sp(tl.send - 6, HEAVY);
  const pvIn = sp(tl.send - 2, HEAVY);
  const chatW = L.chat.w * L.chat.s;
  const chatH = L.chat.h * L.chat.s;
  const chatX = interpolate(
    dock,
    [0, 1],
    [tall ? L.chat.x : (L.w - chatW) / 2, L.chat.x],
  );
  const chatY = interpolate(
    dock,
    [0, 1],
    [tall ? (L.h - chatH) / 2 : L.chat.y, L.chat.y],
  );
  const typed = Math.max(
    0,
    Math.min(prompt.length, Math.floor((frame - T.type) * T.cps)),
  );
  const sent = frame >= tl.send + 1;
  const sendScale =
    1 - 0.06 * (sp(tl.send - 2, MORPH, 3) - sp(tl.send + 1, CHIP));
  const emptyOut = tween(frame, tl.send + 1, tl.send + 6, exitE);
  const bubble = sp(tl.send, MORPH);
  const thinkIn = sp(tl.think, MORPH);
  const thinking = frame < tl.planAt;
  const planIn = sp(tl.planAt - 2, MORPH);
  const filesIn = (i: number) => sp(file(i).start - 2, MORPH);
  const doneIn = sp(tl.doneMsg, MORPH);
  const ready =
    tween(frame, tl.think, tl.think + 6) *
    (1 - tween(frame, file(0).start - 4, file(0).start + 2, exitE));

  const target = {
    x: L.pv.x + L.pv.s * (DEPLOY.x + DEPLOY.w / 2 + 6),
    y: L.pv.y + L.pv.s * (DEPLOY.y + DEPLOY.h / 2 + 4),
  };
  const cp = sp(tl.cursorIn, CARD, tl.deployClick - 2 - tl.cursorIn);
  const cur = arc(L.cursorFrom, target, cp);
  const cursorOp =
    tween(frame, tl.cursorIn - 4, tl.cursorIn + 2) *
    (1 - tween(frame, tl.deployed + 12, tl.deployed + 18, exitE));
  const press = sp(tl.deployClick - 2, MORPH, 3) - sp(tl.deployClick + 2, CHIP);
  const deploying = frame >= tl.deployClick + 1 && frame < tl.deployed;
  const isLive = frame >= tl.deployed;
  const hover = tween(frame, tl.deployClick - 8, tl.deployClick - 4);
  const pop = sp(tl.deployed + 2, CHIP);
  const popOp = tween(frame, tl.deployed + 2, tl.deployed + 6);
  const urlSwap = tween(frame, tl.deployed, tl.deployed + 8);

  const cam = interpolate(frame, [0, tl.end], [1, 1.025], {
    ...clampX,
    easing: camE,
  });

  const composerText = sent ? "" : prompt.slice(0, typed);
  const caretOn = !sent && Math.floor(frame / 8) % 2 === 0;
  const ink = pal.dark ? "#EDEDEF" : "#18181B";
  const inkOn = pal.dark ? "#18181B" : "#FFFFFF";

  return (
    <AbsoluteFill
      style={{
        fontFamily,
        overflow: "hidden",
        WebkitFontSmoothing: "antialiased",
        background: pal.base,
      }}
    >
      <GshGround
        preset={ground ?? (pal.dark ? "hearth" : "paper-crease")}
        params={groundParams}
        timeOffset={pal.dark ? 5 : 3}
        timeScale={0.3}
      />
      <AbsoluteFill style={{ background: pal.scrim }} />
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: L.w,
          height: L.h,
          transformOrigin: "0 0",
          transform: `scale(${u})`,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${cam})`,
            transformOrigin: `${(target.x / L.w) * 100}% ${(target.y / L.h) * 100}%`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: chatX,
              top: chatY,
              width: L.chat.w,
              height: L.chat.h,
              transformOrigin: "0 0",
              transform: `translateY(${(1 - chatIn) * 40}px) scale(${L.chat.s})`,
              opacity: Math.min(1, chatIn * 1.6),
            }}
          >
            <div
              style={{
                position: "relative",
                width: L.chat.w,
                height: L.chat.h,
                borderRadius: 18,
                background: pal.win,
                boxShadow: pal.shadow,
                overflow: "hidden",
                display: "flex",
                flexDirection: "column",
              }}
            >
              <div
                style={{
                  height: 52,
                  flexShrink: 0,
                  display: "flex",
                  alignItems: "center",
                  gap: 10,
                  padding: "0 20px",
                  borderBottom: `1px solid ${pal.line}`,
                  fontSize: 15,
                }}
              >
                <RemocnR height={15} color={pal.text} />
                <span style={{ color: pal.faint }}>/</span>
                <span style={{ color: pal.text }}>{projectName}</span>
                <Icon name="chevDown" color={pal.faint} size={14} />
              </div>
              <div
                style={{
                  flex: 1,
                  minHeight: 0,
                  overflow: "hidden",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "flex-end",
                  padding: "0 22px",
                }}
              >
                <div style={{ marginBottom: "auto", paddingTop: 20 }}>
                  {frame >= tl.send ? (
                    <Grow p={bubble}>
                      <div
                        style={{
                          marginLeft: 28,
                          background: pal.bubble,
                          borderRadius: 14,
                          padding: "12px 15px",
                          fontSize: 15,
                          lineHeight: 1.5,
                          color: pal.text,
                          textWrap: "pretty",
                          opacity: tween(frame, tl.send, tl.send + 4),
                        }}
                      >
                        {prompt}
                      </div>
                    </Grow>
                  ) : null}
                  {frame >= tl.think ? (
                    <Grow p={thinkIn}>
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 8,
                          marginTop: 20,
                          fontSize: 14,
                          color: pal.muted,
                        }}
                      >
                        <RemocnR height={13} color={pal.text} />
                        {thinking ? (
                          <span
                            style={{
                              opacity:
                                0.45 + 0.55 * Math.abs(Math.cos(frame / 9)),
                            }}
                          >
                            Thinking
                          </span>
                        ) : (
                          <span
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: 2,
                              color: pal.faint,
                            }}
                          >
                            Thought for 3s
                            <Icon
                              name="chevRight"
                              color={pal.faint}
                              size={13}
                            />
                          </span>
                        )}
                      </div>
                    </Grow>
                  ) : null}
                  {frame >= tl.planAt - 2 ? (
                    <Grow p={planIn}>
                      <div
                        style={{
                          marginTop: 10,
                          fontSize: 15,
                          lineHeight: 1.5,
                          color: pal.text,
                          textWrap: "pretty",
                        }}
                      >
                        {planWords.map((w, k) => (
                          <span
                            key={k}
                            style={{
                              opacity: tween(
                                frame,
                                tl.planAt + k * 1.3,
                                tl.planAt + k * 1.3 + 5,
                              ),
                            }}
                          >
                            {w}{" "}
                          </span>
                        ))}
                      </div>
                    </Grow>
                  ) : null}
                  {frame >= file(0).start - 2 ? (
                    <div
                      style={{
                        marginTop: 14,
                        opacity: tween(
                          frame,
                          file(0).start - 2,
                          file(0).start + 4,
                        ),
                      }}
                    >
                      {files.slice(0, 4).map((f, i) => {
                        const st =
                          frame >= file(i).done
                            ? 2
                            : frame >= file(i).start
                              ? 1
                              : 0;
                        const ok = sp(file(i).done, CHIP);
                        if (i > 0 && frame < file(i).start - 2) return null;
                        return (
                          <Grow key={f} p={i === 0 ? 1 : filesIn(i)}>
                            <div
                              style={{
                                display: "flex",
                                alignItems: "center",
                                gap: 10,
                                height: 32,
                                fontSize: 14,
                                color: pal.muted,
                                borderTop:
                                  i === 0 ? "none" : `1px solid ${pal.line}`,
                              }}
                            >
                              <span
                                style={{
                                  width: 58,
                                  color: st === 1 ? pal.text : pal.faint,
                                }}
                              >
                                {st === 2 ? "Edited" : "Writing"}
                              </span>
                              <span
                                style={{
                                  fontFamily: mono,
                                  fontSize: 13,
                                  color: st === 1 ? pal.text : pal.muted,
                                }}
                              >
                                {f}
                              </span>
                              <span
                                style={{
                                  marginLeft: "auto",
                                  position: "relative",
                                  width: 15,
                                  height: 15,
                                }}
                              >
                                <span
                                  style={{
                                    position: "absolute",
                                    inset: 0,
                                    opacity: 1 - Math.min(1, ok),
                                  }}
                                >
                                  <Spinner
                                    color={pal.muted}
                                    size={15}
                                    frame={frame}
                                  />
                                </span>
                                <span
                                  style={{
                                    position: "absolute",
                                    inset: 0,
                                    opacity: Math.min(1, ok),
                                    transform: `scale(${0.4 + 0.6 * ok})`,
                                  }}
                                >
                                  <Icon
                                    name="check"
                                    color={pal.green}
                                    size={15}
                                    stroke={2}
                                  />
                                </span>
                              </span>
                            </div>
                          </Grow>
                        );
                      })}
                    </div>
                  ) : null}
                  {frame >= tl.doneMsg ? (
                    <Grow p={doneIn}>
                      <div
                        style={{
                          marginTop: 12,
                          fontSize: 15,
                          lineHeight: 1.5,
                          color: pal.text,
                          opacity: tween(frame, tl.doneMsg + 2, tl.doneMsg + 8),
                          textWrap: "pretty",
                        }}
                      >
                        {doneMessage}
                      </div>
                    </Grow>
                  ) : null}
                </div>
              </div>

              {emptyOut < 1 ? (
                <div
                  style={{
                    position: "absolute",
                    left: 28,
                    right: 28,
                    top: L.chat.h * 0.3,
                    opacity: 1 - emptyOut,
                    transform: `translateY(${-emptyOut * 10}px)`,
                  }}
                >
                  <div
                    style={{
                      fontSize: 26,
                      fontWeight: 300,
                      letterSpacing: "-0.03em",
                      lineHeight: 1.15,
                      color: pal.text,
                    }}
                  >
                    What should we build?
                  </div>
                </div>
              ) : null}

              <div style={{ padding: "12px 14px 14px", flexShrink: 0 }}>
                <div
                  style={{
                    borderRadius: 14,
                    background: pal.field,
                    boxShadow: `inset 0 0 0 1px ${pal.border}`,
                    padding: "12px 10px 10px 14px",
                  }}
                >
                  <div
                    style={{
                      height: 45,
                      fontSize: 15,
                      lineHeight: 1.5,
                      color: composerText ? pal.text : pal.faint,
                      overflow: "hidden",
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "flex-end",
                    }}
                  >
                    <div style={{ marginBottom: "auto" }}>
                      {composerText || "Describe an app or a page"}
                      {caretOn && composerText ? (
                        <span
                          style={{
                            display: "inline-block",
                            width: 1.5,
                            height: 18,
                            background: ink,
                            verticalAlign: "-3px",
                            marginLeft: 1,
                          }}
                        />
                      ) : null}
                    </div>
                  </div>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                      marginTop: 6,
                    }}
                  >
                    <Icon name="paperclip" color={pal.faint} size={17} />
                    <div
                      style={{
                        marginLeft: "auto",
                        width: 32,
                        height: 32,
                        borderRadius: 99,
                        background:
                          typed > 0 && !sent
                            ? ink
                            : pal.dark
                              ? "rgba(255,255,255,0.08)"
                              : "rgba(17,19,24,0.06)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        transform: `scale(${sendScale})`,
                      }}
                    >
                      {sent && frame < tl.doneMsg ? (
                        <div
                          style={{
                            width: 10,
                            height: 10,
                            borderRadius: 2,
                            background: pal.muted,
                          }}
                        />
                      ) : (
                        <Icon
                          name="arrowUp"
                          color={typed > 0 && !sent ? inkOn : pal.faint}
                          size={16}
                          stroke={2}
                        />
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div
            style={{
              position: "absolute",
              left: L.pv.x,
              top: L.pv.y,
              width: PVW,
              height: L.pvH,
              transformOrigin: "0 0",
              transform: `translateY(${(1 - pvIn) * 56}px) scale(${L.pv.s})`,
              opacity: Math.min(1, pvIn * 1.6),
            }}
          >
            <div
              style={{
                position: "relative",
                width: PVW,
                height: L.pvH,
                borderRadius: 14,
                overflow: "hidden",
                background: pal.win,
                boxShadow: pal.shadow,
              }}
            >
              <div
                style={{
                  height: PV_BAR,
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  padding: "0 12px 0 16px",
                  borderBottom: `1px solid ${pal.line}`,
                }}
              >
                <div style={{ display: "flex", gap: 7 }}>
                  {[0, 1, 2].map((d) => (
                    <div
                      key={d}
                      style={{
                        width: 11,
                        height: 11,
                        borderRadius: 99,
                        boxShadow: `inset 0 0 0 1px ${pal.border}`,
                      }}
                    />
                  ))}
                </div>
                <div
                  style={{
                    marginLeft: 70,
                    width: 330,
                    height: 30,
                    borderRadius: 8,
                    background: pal.well,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 13,
                    color: pal.muted,
                    position: "relative",
                    overflow: "hidden",
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  <span
                    style={{
                      position: "absolute",
                      opacity: 1 - urlSwap,
                      transform: `translateY(${-urlSwap * 8}px)`,
                    }}
                  >
                    localhost:3000
                  </span>
                  <span
                    style={{
                      position: "absolute",
                      opacity: urlSwap,
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      transform: `translateY(${(1 - urlSwap) * 8}px)`,
                    }}
                  >
                    <Icon name="lock" color={pal.muted} size={12} />
                    <span style={{ color: pal.text }}>{deployUrl}</span>
                  </span>
                </div>
              </div>
              <div
                style={{
                  position: "absolute",
                  left: DEPLOY.x,
                  top: DEPLOY.y,
                  width: DEPLOY.w,
                  height: DEPLOY.h,
                  borderRadius: 8,
                  background: isLive ? "transparent" : ink,
                  boxShadow: isLive ? `inset 0 0 0 1px ${pal.border}` : "none",
                  color: isLive ? pal.text : inkOn,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 7,
                  fontSize: 14,
                  transform: `scale(${1 - 0.04 * press})`,
                  filter: `brightness(${1 + (pal.dark ? -0.08 : 0.25) * hover * (isLive ? 0 : 1)})`,
                }}
              >
                {deploying ? (
                  <Spinner color={inkOn} size={13} frame={frame} />
                ) : isLive ? (
                  <div
                    style={{
                      width: 7,
                      height: 7,
                      borderRadius: 99,
                      background: pal.green,
                    }}
                  />
                ) : null}
                {deploying ? "Deploying" : isLive ? "Live" : "Deploy"}
              </div>
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  right: 0,
                  top: PV_BAR,
                  bottom: 0,
                  background: pal.dark ? "#141416" : "#F6F6F7",
                }}
              >
                {children ? (
                  <div
                    style={{
                      width: "100%",
                      height: "100%",
                      opacity: tween(frame, file(0).start, file(0).start + 10),
                    }}
                  >
                    {children}
                  </div>
                ) : (
                  <div
                    style={{
                      height: "100%",
                      opacity: tween(
                        frame,
                        file(0).start - 4,
                        file(0).start + 2,
                      ),
                    }}
                  >
                    <Site
                      frame={frame}
                      accent={accent}
                      file={file}
                      siteName={siteName}
                      siteEyebrow={siteEyebrow}
                      siteHeadline={siteHeadline}
                      siteBody={siteBody}
                      siteLinks={siteLinks}
                      pours={pours}
                    />
                  </div>
                )}
                {ready > 0 ? (
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: 9,
                      opacity: ready,
                      fontSize: 14,
                      color: pal.muted,
                    }}
                  >
                    <Spinner color={pal.muted} size={14} frame={frame} />
                    Starting dev server
                  </div>
                ) : null}
              </div>

              {popOp > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    right: 12,
                    top: DEPLOY.y + DEPLOY.h + 8,
                    width: 316,
                    borderRadius: 14,
                    background: pal.pop,
                    boxShadow: pal.popShadow,
                    padding: 6,
                    opacity: popOp,
                    transform: `translateY(${(1 - pop) * -6}px) scale(${0.94 + 0.06 * pop})`,
                    transformOrigin: `${316 - DEPLOY.w / 2}px 0`,
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "baseline",
                      padding: "8px 10px 10px",
                    }}
                  >
                    <span style={{ fontSize: 16, color: pal.text }}>
                      Deployed to production
                    </span>
                    <span
                      style={{
                        marginLeft: "auto",
                        fontSize: 13,
                        color: pal.faint,
                        fontVariantNumeric: "tabular-nums",
                      }}
                    >
                      21.4s
                    </span>
                  </div>
                  <div
                    style={{
                      height: 40,
                      borderRadius: 8,
                      background: pal.well,
                      display: "flex",
                      alignItems: "center",
                      gap: 9,
                      padding: "0 5px 0 12px",
                      fontSize: 14,
                      color: pal.text,
                    }}
                  >
                    <div
                      style={{
                        width: 7,
                        height: 7,
                        borderRadius: 99,
                        background: pal.green,
                      }}
                    />
                    {deployUrl}
                    <div
                      style={{
                        marginLeft: "auto",
                        height: 30,
                        padding: "0 11px",
                        borderRadius: 6,
                        background: ink,
                        color: inkOn,
                        display: "flex",
                        alignItems: "center",
                        gap: 5,
                        fontSize: 13,
                      }}
                    >
                      Visit
                      <Icon
                        name="external"
                        color={inkOn}
                        size={12}
                        stroke={1.75}
                      />
                    </div>
                  </div>
                </div>
              ) : null}
            </div>
          </div>

          {cursorOp > 0 ? (
            <div style={{ opacity: cursorOp }}>
              <Cursor x={cur.x} y={cur.y} press={press} />
            </div>
          ) : null}
        </div>
      </div>
    </AbsoluteFill>
  );
}

import { loadFont as loadJakarta } from "@remotion/google-fonts/PlusJakartaSans";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const jakarta = loadJakarta("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface PullInProps {
  lead?: string;
  places?: string[];
  hold?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0B1F33",
    ink: "#E8EEF2",
    muted: "#7F93A6",
    teal: "#00BFA5",
  },
  light: {
    bg: "#E8EEF2",
    ink: "#0B1F33",
    muted: "#5C7083",
    teal: "#00A08A",
  },
} as const;

const WGHT = 500;
const LEAD_WGHT = 400;
const TRACK = -0.028;
const WORD = 0.14;
const FONT_PX = 200;

const HEADWAY = 1.25;
const BRAKE = 20;
const NOSE = 0.045;
const SETTLE = 12;
const BUNCH = 0.93;
const FOLLOW = 1.3;
const ARRIVE = BRAKE + SETTLE;
const DEPART_GAP = 9;
const LEAD_AT = 0;
const FIRST_AT = 4;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface WordMetrics {
  x: number[];
  adv: number[];
  width: number;
}

interface Metrics {
  places: WordMetrics[];
  lead: number;
  asc: number;
  desc: number;
  capTop: number;
}

const spaces = (s: string) => s.split(" ").length - 1;

function measureWord(ctx: CanvasRenderingContext2D, s: string): WordMetrics {
  const chars = Array.from(s);
  const x: number[] = [];
  let prefix = "";
  for (let i = 0; i < chars.length; i++) {
    x.push(
      ctx.measureText(prefix).width / FONT_PX +
        TRACK * i +
        WORD * spaces(prefix),
    );
    prefix += chars[i];
  }
  const width =
    ctx.measureText(s).width / FONT_PX +
    TRACK * Math.max(0, chars.length - 1) +
    WORD * spaces(s);
  const adv = chars.map(
    (_, i) => (i + 1 < chars.length ? x[i + 1] : width) - x[i],
  );
  return { x, adv, width };
}

function measure(places: string[], lead: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("pull-in: no 2d context");
  ctx.font = `${WGHT} ${FONT_PX}px "${jakarta.fontFamily}"`;
  const m = places.map((p) => measureWord(ctx, p));
  const fm = ctx.measureText("Hxg");
  const cap = ctx.measureText("H");
  ctx.font = `${LEAD_WGHT} ${FONT_PX}px "${jakarta.fontFamily}"`;
  const leadW = lead
    ? ctx.measureText(lead).width / FONT_PX + WORD * spaces(lead)
    : 0;
  return {
    places: m,
    lead: leadW,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
    capTop: cap.actualBoundingBoxAscent / FONT_PX,
  };
}

function useMetrics(places: string[], lead: string) {
  const key = [lead, ...places].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("pull-in: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [l, ...p] = key.split("\u0001");
    Promise.all([
      jakarta.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${jakarta.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(p, l) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function arrival(tau: number, x0: number, nose: number) {
  const v0 = (2 * x0) / BRAKE;
  if (tau <= 0) return x0 - v0 * tau;
  if (tau < BRAKE) {
    const u = 1 - tau / BRAKE;
    return x0 * u * u - nose * Math.sin((Math.PI / 2) * (1 - u)) ** 3;
  }
  const k = (tau - BRAKE) / SETTLE;
  if (k >= 1) return 0;
  return -nose * Math.cos((Math.PI / 2) * k) * (1 - k) ** 0.5;
}

function departure(tau: number) {
  if (tau <= 0) return 0;
  return 1.4 * tau * tau + 0.04 * tau * tau * tau;
}

function PullInBase({
  lead = "Now in",
  places = ["vertical.", "4K.", "your codebase."],
  hold = 24,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: PullInProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.teal;
  const list = useMemo(
    () => (places.length > 0 ? places : ["your codebase."]),
    [places],
  );
  const m = useMetrics(list, lead);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.085);
  const measureW = W - marginX * 2;
  const widest = Math.max(...m.places.map((p) => p.width), 0.1);
  const F = Math.min(H * (portrait ? 0.16 : 0.34), measureW / widest);
  const L = lead
    ? Math.min(F * 0.5, (measureW * 0.9) / Math.max(0.1, m.lead))
    : 0;
  const leadGap = lead ? F * 0.16 : 0;

  const placeCap = m.capTop * F;
  const leadCap = m.capTop * L;
  const blockH = (lead ? leadCap + leadGap + F * 0.42 : 0) + placeCap;
  const blockTop = H / 2 - blockH / 2 - F * 0.04;
  const placeBase = blockTop + blockH;
  const leadBase = blockTop + leadCap;

  const STEP = ARRIVE + Math.max(8, hold) + DEPART_GAP;
  const arriveAt = (k: number) => FIRST_AT + k * STEP;
  const departAt = (k: number) => arriveAt(k + 1) - DEPART_GAP;
  const x0 = W - marginX + F * 0.6;

  interface Glyph {
    k: number;
    i: number;
    ch: string;
    x: number;
  }
  const glyphs: Glyph[] = [];
  list.forEach((word, k) => {
    const chars = Array.from(word);
    const start = arriveAt(k);
    const leave = k === list.length - 1 ? null : departAt(k);
    if (t < start - chars.length * HEADWAY - 30) return;
    if (leave !== null && t > leave + 40 + chars.length * HEADWAY) return;
    chars.forEach((ch, i) => {
      let dx = arrival(t - start - i * HEADWAY, x0, NOSE * F);
      if (leave !== null) dx -= departure(t - leave - i * HEADWAY);
      glyphs.push({ k, i, ch, x: marginX + m.places[k].x[i] * F + dx });
    });
  });
  for (let g = 1; g < glyphs.length; g++) {
    const prev = glyphs[g - 1];
    const cur = glyphs[g];
    const advPrev = m.places[prev.k].adv[prev.i] * F;
    const floor =
      prev.k === cur.k
        ? prev.x + advPrev * BUNCH
        : prev.x + advPrev + FOLLOW * F;
    if (cur.x < floor) cur.x = floor;
  }

  const letters: React.ReactNode[] = [];
  for (const { k, i, ch, x } of glyphs) {
    const wm = m.places[k];
    if (x > W + F || x + wm.adv[i] * F < -F) continue;
    const last = k === list.length - 1;
    letters.push(
      <div
        key={`p${k}-${i}`}
        style={{
          position: "absolute",
          left: x,
          top: placeBase - (m.asc + (1 - m.asc - m.desc) / 2) * F,
          height: F,
          lineHeight: `${F}px`,
          whiteSpace: "pre",
          fontFamily: jakarta.fontFamily,
          fontWeight: WGHT,
          fontSize: F,
          color: last ? hi : c.ink,
        }}
      >
        {ch}
      </div>,
    );
  }

  const leadP = interpolate(t, [LEAD_AT, LEAD_AT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
      }}
    >
      {lead ? (
        <div
          style={{
            position: "absolute",
            left: marginX,
            top: leadBase - ((1.4 - m.asc - m.desc) / 2 + m.asc) * L,
            height: L * 1.4,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              fontFamily: jakarta.fontFamily,
              fontWeight: LEAD_WGHT,
              fontSize: L,
              lineHeight: `${L * 1.4}px`,
              height: L * 1.4,
              letterSpacing: "-0.02em",
              wordSpacing: `${WORD}em`,
              whiteSpace: "pre",
              color: c.muted,
              transform: `translateY(${((1 - leadP) * L * 1.2).toFixed(2)}px)`,
            }}
          >
            {lead}
          </div>
        </div>
      ) : null}
      {letters}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  lead: {
    type: "text-content",
    default: "Now in",
    description: "Lead",
  },
  hold: {
    type: "number",
    default: 24,
    min: 0,
    max: 72,
    step: 1,
    description: "Hold",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","lead","hold","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  lead: "Now in",
  hold: 24,
  speed: 1,
};

type PullInElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PullInBase>;

const PullInInner = forwardRef<
  HTMLDivElement,
  PullInElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PullIn>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PullInBase
          {...(componentProps as unknown as ComponentProps<typeof PullInBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PullIn = Interactive.withSchema({
  Component: PullInInner,
  componentName: "<PullIn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadInterTight } from "@remotion/google-fonts/InterTight";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const inter = loadInterTight("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface PulseLineProps {
  text?: string;
  highlight?: string;
  caption?: string;
  beats?: number;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const AURORA = ["#a0f0c8", "#3fb5a3", "#5147b6", "#b25c9c"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    flat: "#9C9BA3",
    muted: "#8E8D94",
    glow: ["#F2FFF8", AURORA[0], AURORA[1]],
    hl: (accent: string) =>
      `linear-gradient(100deg, ${AURORA[0]} 0%, ${AURORA[1]} 38%, ${accent} 78%, ${AURORA[3]} 100%)`,
    ground: (k: number) =>
      `radial-gradient(70% 55% at 50% 108%, rgba(63,181,163,${(0.1 + 0.1 * k).toFixed(3)}) 0%, rgba(81,71,182,${(0.06 + 0.05 * k).toFixed(3)}) 45%, transparent 75%)`,
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    flat: "#55545A",
    muted: "#6E6C67",
    glow: ["#0B5E52", "#1E8C7C", AURORA[2]],
    hl: (accent: string) =>
      `linear-gradient(100deg, #12806F 0%, #1E8C7C 30%, ${accent} 72%, #8C3A78 100%)`,
    ground: (k: number) =>
      `radial-gradient(70% 55% at 50% 108%, rgba(63,181,163,${(0.12 + 0.08 * k).toFixed(3)}) 0%, rgba(81,71,182,${(0.05 + 0.04 * k).toFixed(3)}) 45%, transparent 75%)`,
    grain: 0.035,
  },
} as const;

const TRACK = -0.035;
const LINE_GAP = 1.1;
const FONT_PX = 200;

const WAVE = [
  { a: 0.1, c: 1.0, w: 0.5, tent: false },
  { a: -0.09, c: 2.25, w: 0.5, tent: true },
  { a: 0.62, c: 2.9, w: 0.85, tent: true },
  { a: -0.22, c: 3.6, w: 0.6, tent: true },
  { a: 0.16, c: 5.3, w: 0.85, tent: false },
] as const;
const R_AT = 2.9;
const WAVE_LEN = 7.2;
const V = 0.42;
const FLAT_SCALE = 0.05;
const COOL = 11;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function ecg(s: number) {
  let y = 0;
  for (const k of WAVE) {
    y += k.tent
      ? k.a * Math.max(0, 1 - Math.abs(s - k.c) / k.w)
      : k.a * Math.exp(-((s - k.c) ** 2) / (2 * k.w * k.w));
  }
  return y;
}

function mixHex(a: string, b: string, t: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (p: number, sh: number) => (p >> sh) & 255;
  const m = (sh: number) =>
    Math.round(ch(pa, sh) + (ch(pb, sh) - ch(pa, sh)) * t);
  return `rgb(${m(16)}, ${m(8)}, ${m(0)})`;
}

function heatColor(stops: readonly string[], ink: string, h: number) {
  const ramp = [ink, stops[2], stops[1], stops[0]];
  const x = Math.max(0, Math.min(1, h)) ** 1.4 * (ramp.length - 1);
  const i = Math.min(ramp.length - 2, Math.floor(x));
  return mixHex(ramp[i], ramp[i + 1], x - i);
}

interface Metrics {
  width: (s: string) => number;
  offsets: (s: string) => number[];
  caption: number;
  baseline: number;
}

function useMetrics(caption: string) {
  const [m, setM] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("pulse-line: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`500 100px "${inter.fontFamily}"`),
      document.fonts.load(`400 100px "${inter.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        if (!ctx) throw new Error("pulse-line: no 2d context");
        ctx.font = `500 ${FONT_PX}px "${inter.fontFamily}"`;
        const fm = ctx.measureText("Hg");
        const asc = fm.fontBoundingBoxAscent / FONT_PX;
        const desc = fm.fontBoundingBoxDescent / FONT_PX;
        const raw = (s: string) => ctx.measureText(s).width / FONT_PX;
        const width = (s: string) =>
          raw(s) + TRACK * Math.max(0, Array.from(s).length - 1);
        const offsets = (s: string) => {
          const chars = Array.from(s);
          return chars.map(
            (_, i) => raw(chars.slice(0, i).join("")) + TRACK * i,
          );
        };
        ctx.font = `400 ${FONT_PX}px "${inter.fontFamily}"`;
        const cap = caption ? ctx.measureText(caption).width / FONT_PX : 0;
        setM({
          width,
          offsets,
          caption: cap,
          baseline: (1 - (asc + desc)) / 2 + asc,
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [caption, handle]);
  return m;
}

function breakLines(words: string[], n: number, width: (s: string) => number) {
  if (n <= 1 || words.length <= 1) return [words.join(" ")];
  let best: string[] = [words.join(" ")];
  let bestW = Number.POSITIVE_INFINITY;
  const rec = (start: number, left: number, acc: string[]) => {
    if (left === 1) {
      const lines = [...acc, words.slice(start).join(" ")];
      const w = Math.max(...lines.map(width));
      if (w < bestW) {
        bestW = w;
        best = lines;
      }
      return;
    }
    for (let k = start + 1; k <= words.length - left + 1; k++)
      rec(k, left - 1, [...acc, words.slice(start, k).join(" ")]);
  };
  rec(0, Math.min(n, words.length), []);
  return best;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `pl${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function PulseLineBase({
  text = "Every frame has a pulse.",
  highlight = "a pulse.",
  caption = "Motion components for Remotion. Copy one in, own every frame.",
  beats = 2,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: PulseLineProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const m = useMetrics(caption);

  const words = useMemo(() => text.split(/\s+/).filter(Boolean), [text]);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: c.bg }} />;
  }

  const maxW = W * 0.86;
  const capH = caption ? 0.16 : 0;
  let lines: string[] = [text];
  let F = 0;
  for (let n = 1; n <= 3; n++) {
    const ls = breakLines(words, n, m.width);
    const wEm = Math.max(...ls.map(m.width));
    const hEm = (ls.length - 1) * LINE_GAP + 1.1;
    const f = Math.min(
      maxW / wEm,
      (H * (0.7 - capH)) / hEm,
      H * (n === 1 ? 0.24 : 0.19),
    );
    if (n === 1 || f > F * 1.15) {
      lines = ls;
      F = f;
    }
    if (n === 1 && f >= H * 0.17) break;
  }

  const hlStart = highlight ? text.indexOf(highlight) : -1;
  const hlEnd = hlStart >= 0 ? hlStart + highlight.length : -1;
  type G = {
    ch: string;
    line: number;
    x: number;
    adv: number;
    strip: number;
    hl: boolean;
  };
  const glyphs: G[] = [];
  let cursor = 0;
  const lineW = lines.map(m.width);
  const blockW = Math.max(...lineW);
  for (let li = 0; li < lines.length; li++) {
    const s = lines[li];
    const offs = m.offsets(s);
    const lw = lineW[li];
    const chars = Array.from(s);
    const at = text.indexOf(s, cursor);
    const pad = (blockW - lw) / 2;
    chars.forEach((ch, i) => {
      const next = i + 1 < chars.length ? offs[i + 1] : lw + TRACK;
      const adv = next - offs[i];
      const gi = at + i;
      glyphs.push({
        ch,
        line: li,
        x: offs[i],
        adv,
        strip: pad + offs[i] + adv / 2,
        hl: gi >= hlStart && gi < hlEnd,
      });
    });
    cursor = at + s.length;
  }
  const stripLen = blockW;
  const hlBox = new Map<number, { x0: number; x1: number }>();
  for (const g of glyphs) {
    if (!g.hl || g.ch === " ") continue;
    const b = hlBox.get(g.line) ?? { x0: g.x, x1: g.x + g.adv };
    b.x0 = Math.min(b.x0, g.x);
    b.x1 = Math.max(b.x1, g.x + g.adv);
    hlBox.set(g.line, b);
  }

  const nBeats = Math.max(1, Math.min(4, Math.round(beats)));
  const run = (stripLen + WAVE_LEN + 1) / V;
  const period = Math.max(34, run + 4);
  const beatAt = (b: number) => 6 + b * period;
  const front = (b: number) => -1 + (t - beatAt(b)) * V;
  const endT = beatAt(nBeats - 1) + run;

  const blockH = (lines.length - 1) * LINE_GAP * F + F;
  const capGap = Math.max(F * 0.42, H * 0.06);
  const capSize = Math.min(
    Math.max(F * 0.17, H * 0.035),
    H * 0.044,
    (W * 0.86) / Math.max(0.1, m.caption),
  );
  const totalH = blockH + (caption ? capGap + capSize : 0);
  const top0 = (H - totalH) / 2;
  const capAt = beatAt(nBeats - 1) + run * 0.45;

  let breathe = 0;
  for (let b = 0; b < nBeats; b++) {
    const tr = beatAt(b) + (stripLen / 2 + R_AT + 1) / V;
    const d = t - tr;
    if (d > -4) breathe = Math.max(breathe, Math.exp(-((d + 0) ** 2) / 120));
  }

  const nodes: React.ReactNode[] = [];
  glyphs.forEach((g, i) => {
    if (g.ch === " ") return;
    const lw = lineW[g.line];
    const left = (W - lw * F) / 2 + g.x * F;
    const baseY = top0 + g.line * LINE_GAP * F + m.baseline * F;

    let y = 0;
    let heat = 0;
    let alive = 0;
    let hlOn = 0;
    for (let b = 0; b < nBeats; b++) {
      const s = front(b) - g.strip;
      if (s < -0.5) continue;
      y += ecg(s);
      const since = (s - R_AT) / V;
      if (since > -1.5) {
        heat = Math.max(
          heat,
          since < 0 ? 1 + since / 1.5 : Math.exp(-since / COOL),
        );
      }
      if (b === 0)
        alive = interpolate(s, [R_AT - 0.35, R_AT + 0.25], [0, 1], CLAMP);
      if (b === nBeats - 1 && g.hl)
        hlOn = interpolate(since, [0, 12], [0, 1], CLAMP);
    }
    const spike = Math.max(0, y) / WAVE[2].a;
    const sy = FLAT_SCALE + (1 - FLAT_SCALE) * alive + spike * 0.22 * alive;
    const sx = 1 - spike * 0.06;
    const dy = -y * F * (lines.length > 1 ? 0.8 : 1);
    const ink = alive > 0.02 ? c.ink : c.flat;
    const restInk = mixHex(c.flat, c.ink, alive);
    const col =
      heat > 0.001
        ? heatColor(c.glow, ink === c.ink ? c.ink : restInk, heat)
        : restInk;

    const style: React.CSSProperties = {
      position: "absolute",
      left,
      top: baseY - m.baseline * F,
      fontFamily: inter.fontFamily,
      fontWeight: 500,
      fontSize: F,
      lineHeight: `${F}px`,
      whiteSpace: "pre",
      transformOrigin: `${((g.adv / 2) * F).toFixed(2)}px ${(m.baseline * F).toFixed(2)}px`,
      transform: `translateY(${dy.toFixed(2)}px) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`,
    };
    nodes.push(
      <div key={`g${i}`} style={{ ...style, color: col }}>
        {g.ch}
      </div>,
    );
    if (g.hl && hlOn > 0) {
      const box = hlBox.get(g.line);
      const bw = box ? (box.x1 - box.x0) * F : g.adv * F;
      const bx = box ? (g.x - box.x0) * F : 0;
      nodes.push(
        <div
          key={`h${i}`}
          style={{
            ...style,
            color: "transparent",
            backgroundImage: c.hl(accent),
            backgroundSize: `${bw.toFixed(2)}px 100%`,
            backgroundPosition: `${(-bx).toFixed(2)}px 0`,
            backgroundRepeat: "no-repeat",
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            opacity: hlOn * (1 - Math.min(1, heat * 0.6)),
          }}
        >
          {g.ch}
        </div>,
      );
    }
  });

  const capP = interpolate(t, [capAt, capAt + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const settled = interpolate(t, [endT, endT + 30], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: c.ground(Math.max(breathe, settled * 0.35)),
        }}
      />
      {nodes}
      {caption ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: top0 + blockH + capGap,
            textAlign: "center",
            fontFamily: inter.fontFamily,
            fontWeight: 400,
            fontSize: capSize,
            letterSpacing: "-0.01em",
            lineHeight: 1.2,
            color: c.muted,
            opacity: capP,
            transform: `translateY(${((1 - capP) * capSize * 0.7).toFixed(2)}px)`,
          }}
        >
          {caption}
        </div>
      ) : null}
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

