// Manrope 600 advance widths (per 1000 em), lowercase. Measured with HarfBuzz.
const ADVANCE: Record<string, number> = {
  a: 570,
  b: 608,
  c: 568,
  d: 608,
  e: 596,
  f: 370,
  g: 608,
  h: 615,
  i: 264,
