    type: "number",
    default: 120,
    min: 0,
    max: 360,
    step: 1,
    description: "Quote duration",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","quoteDuration","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  quoteDuration: 120,
  speed: 1,
};

type QuoteHeroElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof QuoteHeroBase>;

const QuoteHeroInner = forwardRef<
  HTMLDivElement,
  QuoteHeroElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<QuoteHero>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <QuoteHeroBase
          {...(componentProps as unknown as ComponentProps<typeof QuoteHeroBase>)}
        />
      </div>
    </Sequence>
  );
});

export const QuoteHero = Interactive.withSchema({
  Component: QuoteHeroInner,
  componentName: "<QuoteHero>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

