function groupThousands(n: number) {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={13}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function RollNumber({
  value,
  min,
  max,
  size,
  lineHeight,
  color,
  font,
  weight,
  travel = 0.34,
  blur = 0,
  paint,
}: {
  value: number;
  min: number;
  max: number;
  size: number;
  lineHeight: number;
  color: string;
  font: string;
  weight: number;
  travel?: number;
  blur?: number;
  paint?: string;
}) {
  const nums: number[] = [];
  for (let n = min; n <= max; n++) nums.push(n);
  const lh = size * lineHeight;
  const text: React.CSSProperties = {
    height: lh,
    lineHeight: `${lh}px`,
    fontFamily: font,
    fontWeight: weight,
    fontSize: size,
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
    ...(paint
      ? {
          backgroundImage: paint,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          WebkitTextFillColor: "transparent",
        }
      : null),
  };
  return (
    <span
      style={{
        display: "inline-block",
        position: "relative",
        height: lh,
        verticalAlign: "top",
      }}
    >
      <span style={{ ...text, visibility: "hidden" }}>{max}</span>
      {nums.map((n) => {
        const d = n - value;
        const a = interpolate(Math.abs(d), [0, 0.62], [1, 0], CLAMP);
        if (a <= 0) return null;
        const b = Math.abs(d) * blur;
        return (
          <span
            key={n}
            style={{
              ...text,
              position: "absolute",
              left: 0,
              top: 0,
              color,
              opacity: a,
              transform: `translateY(${d * travel * size}px)`,
              filter: b > 0.2 ? `blur(${b}px)` : undefined,
            }}
          >
            {n}
          </span>
        );
      })}
    </span>
  );
}

function Upvote({ size, color }: { size: number; color: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 10 10" aria-hidden>
      <path d="M5 1.6 L9 8.2 H1 Z" fill={color} />
    </svg>
  );
}

