    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","label","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "10x",
  label: "Faster renders in remocn 2.0",
  speed: 1,
};

type RasterPaintElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RasterPaintBase>;

const RasterPaintInner = forwardRef<
  HTMLDivElement,
  RasterPaintElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RasterPaint>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RasterPaintBase
          {...(componentProps as unknown as ComponentProps<typeof RasterPaintBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RasterPaint = Interactive.withSchema({
  Component: RasterPaintInner,
  componentName: "<RasterPaint>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

