/* Marks */

/**
 * Annotation primitives: the redline marks a design review paints over a UI.
 * Each takes a `delay` in frames and draws itself in from there.
 */

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function progress(frame: number, start: number, duration: number) {
  return interpolate(frame, [start, start + duration], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
}

/** Pop-in for labels and chips: a cubic ease-out, no overshoot. */
function usePop(delay: number) {
  return progress(useAuditFrame(), delay, 12);
}

function Layer({ children }: { children: ReactNode }) {
  return (
    <svg
      width={1280}
      height={720}
      viewBox="0 0 1280 720"
      style={{ position: "absolute", inset: 0, overflow: "visible" }}
    >
      {children}
    </svg>
  );
}

type Side =
  | "center"
  | "above"
  | "below"
  | "left"
  | "right"
  | "aboveStart"
  | "aboveEnd"
  | "belowStart";

/** Small spec label: mono text on a solid color chip. */
function Pill({
  x,
  y,
  text,
  color,
  delay = 0,
  anchor = "center",
  ink = "#fff",
}: {
  x: number;
  y: number;
  text: string;
  color: string;
  delay?: number;
  anchor?: Side;
  ink?: string;
}) {
  const pop = usePop(delay);
  const shift = {
    center: "translate(-50%, -50%)",
    above: "translate(-50%, calc(-100% - 5px))",
    below: "translate(-50%, 5px)",
    left: "translate(calc(-100% - 6px), -50%)",
    right: "translate(6px, -50%)",
    aboveStart: "translate(0, calc(-100% - 5px))",
    aboveEnd: "translate(-100%, calc(-100% - 5px))",
    belowStart: "translate(0, 5px)",
  }[anchor];
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `${shift} scale(${0.7 + 0.3 * pop})`,
        opacity: Math.min(1, pop * 1.4),
        background: color,
        color: ink,
        fontFamily: MONO,
        fontSize: 10.5,
        fontWeight: 600,
        lineHeight: "15px",
        padding: "0 5px",
        borderRadius: 3,
        whiteSpace: "nowrap",
      }}
    >
      {text}
    </div>
  );
}

/**
 * Measurement between two points on one axis: end ticks snap in, the line
 * grows out from its middle, then the value pops on.
 */
function Ruler({
  from,
  to,
  label,
  color,
  delay = 0,
  labelSide,
}: {
  from: [number, number];
  to: [number, number];
  label: string;
  color: string;
  delay?: number;
  labelSide?: Side;
}) {
  const frame = useAuditFrame();
  const grow = progress(frame, delay, 12);
  const ticks = progress(frame, delay - 2, 6);
  const horizontal = Math.abs(to[0] - from[0]) >= Math.abs(to[1] - from[1]);
  const mx = (from[0] + to[0]) / 2;
  const my = (from[1] + to[1]) / 2;
  const x1 = mx + (from[0] - mx) * grow;
  const y1 = my + (from[1] - my) * grow;
  const x2 = mx + (to[0] - mx) * grow;
  const y2 = my + (to[1] - my) * grow;
  const t = 4 * ticks;
  const tick = (x: number, y: number) =>
    horizontal ? `M${x} ${y - t}V${y + t}` : `M${x - t} ${y}H${x + t}`;
  return (
    <>
      <Layer>
        <path
          d={`${tick(...from)}${tick(...to)}`}
          stroke={color}
          strokeWidth={1.25}
          fill="none"
        />
        <line
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={color}
          strokeWidth={1.25}
        />
      </Layer>
      <Pill
        x={mx}
        y={my}
        text={label}
        color={color}
        delay={delay + 7}
        anchor={labelSide ?? (horizontal ? "above" : "left")}
      />
    </>
  );
}

/** Hairline box traced around an element, clockwise from the top left. */
function OutlineBox({
  rect,
  color,
  delay = 0,
  radius = 3,
  inset = -3,
  dashed,
  fill,
}: {
  rect: Rect;
  color: string;
  delay?: number;
  radius?: number;
  inset?: number;
  dashed?: boolean;
  fill?: string;
}) {
  const frame = useAuditFrame();
  const draw = progress(frame, delay, 14);
  const x = rect.x + inset;
  const y = rect.y + inset;
  const w = rect.w - inset * 2;
  const h = rect.h - inset * 2;
  return (
    <Layer>
      <rect
        x={x}
        y={y}
        width={w}
        height={h}
        rx={radius}
        fill={fill ?? "none"}
        fillOpacity={draw}
        stroke={color}
        strokeWidth={1.25}
        pathLength={1}
        strokeDasharray={dashed ? undefined : `${draw} 1`}
        strokeOpacity={dashed ? draw : 1}
        style={dashed ? { strokeDasharray: "3 3" } : undefined}
      />
    </Layer>
  );
}

/** Quarter arc swept into a corner to call out its radius. */
function CornerArc({
  x,
  y,
  r,
  color,
  label,
  delay = 0,
}: {
  x: number;
  y: number;
  r: number;
  color: string;
  label: string;
  delay?: number;
}) {
  const frame = useAuditFrame();
  const draw = progress(frame, delay, 12);
  const size = Math.max(r, 10) + 4;
  return (
    <>
      <Layer>
        <path
          d={`M${x} ${y + size}A${size} ${size} 0 0 1 ${x + size} ${y}`}
          stroke={color}
          strokeWidth={1.5}
          fill="none"
          pathLength={1}
          strokeDasharray={`${draw} 1`}
          strokeLinecap="round"
        />
      </Layer>
      <Pill
        x={x - 2}
        y={y - 2}
        text={label}
        color={color}
        delay={delay + 8}
        anchor="aboveStart"
      />
    </>
  );
}

/**
 * Design-token tag: a dot lands on the element, a leader line runs out with
 * one elbow, and a dark chip with the token name settles at its end.
 */
function TokenTag({
  anchor,
  at,
  label,
  swatch,
  delay = 0,
  lineColor = "#0E121B",
}: {
  anchor: [number, number];
  at: [number, number];
  label: string;
  swatch: string;
  delay?: number;
  lineColor?: string;
}) {
  const frame = useAuditFrame();
  const dot = usePop(delay);
  const draw = progress(frame, delay + 3, 14);
  const elbowY = at[1];
  const path = `M${anchor[0]} ${anchor[1]}L${anchor[0] + (at[0] - anchor[0]) * 0.35} ${elbowY}H${at[0]}`;
  return (
    <>
      <Layer>
        <path
          d={path}
          stroke={lineColor}
          strokeOpacity={0.55}
          strokeWidth={1}
          fill="none"
          pathLength={1}
          strokeDasharray={`${draw} 1`}
        />
        <circle
          cx={anchor[0]}
          cy={anchor[1]}
          r={3.5 * dot}
          fill="#fff"
          stroke={lineColor}
          strokeWidth={1.5}
        />
      </Layer>
      <TokenChip
        x={at[0]}
        y={at[1]}
        label={label}
        swatch={swatch}
        delay={delay + 13}
      />
    </>
  );
}

function TokenChip({
  x,
  y,
  label,
  swatch,
  delay = 0,
}: {
  x: number;
  y: number;
  label: string;
  swatch: string;
  delay?: number;
}) {
  const pop = usePop(delay);
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(-50%, -50%) translateY(${(1 - pop) * 6}px)`,
        opacity: Math.min(1, pop * 1.4),
        display: "flex",
        alignItems: "center",
        gap: 6,
        background: "#0E121B",
        color: "#fff",
        fontFamily: MONO,
        fontSize: 11,
        lineHeight: "22px",
        padding: "0 8px",
        borderRadius: 5,
        whiteSpace: "nowrap",
        boxShadow: "0 4px 10px -4px rgba(10,13,20,0.4)",
      }}
    >
      <span
        style={{
          width: 8,
          height: 8,
          borderRadius: 4,
          background: swatch,
          boxShadow: "0 0 0 1px rgba(255,255,255,0.35)",
        }}
      />
      {label}
    </div>
  );
}

/** Guide line that drops down (vertical) or slides across (horizontal). */
function Guide({
  x,
  y,
  length,
  vertical,
  color,
  delay = 0,
  dashed,
  width = 1,
}: {
  x: number;
  y: number;
  length: number;
  vertical?: boolean;
  color: string;
  delay?: number;
  dashed?: boolean;
  width?: number;
}) {
  const frame = useAuditFrame();
  const draw = progress(frame, delay, 16) * length;
  return (
    <Layer>
      <line
        x1={x}
        y1={y}
        x2={vertical ? x : x + draw}
        y2={vertical ? y + draw : y}
        stroke={color}
        strokeWidth={width}
        strokeDasharray={dashed ? "4 4" : undefined}
      />
    </Layer>
  );
}

/**
 * Scan band: a crisp line with a soft wash trailing behind it, the way the
 * fix pass sweeps the screen. `y` is the line's position.
 */
function ScanBand({
  y,
  color,
  x = 0,
  w = 1280,
  trail = 90,
  opacity = 1,
}: {
  y: number;
  color: string;
  x?: number;
  w?: number;
  trail?: number;
  opacity?: number;
}) {
  return (
    <div
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
    >
      <div
        style={{
          position: "absolute",
          left: x,
          width: w,
          top: y - trail,
          height: trail,
          background: `linear-gradient(to bottom, transparent, ${color}2E)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: x,
          width: w,
          top: y - 1,
          height: 2,
          background: color,
          boxShadow: `0 0 12px 1px ${color}`,
        }}
      />
    </div>
  );
}

/** Stage-colored wash over everything except one rect, to push focus. */
function Spotlight({
  rect,
  opacity,
  color = C.stage,
}: {
  rect: Rect;
  opacity: number;
  color?: string;
}) {
  const pad = 10;
  const x = rect.x - pad;
  const y = rect.y - pad;
  const w = rect.w + pad * 2;
  const h = rect.h + pad * 2;
  const r = 12;
  return (
    <svg
      width={1280}
      height={720}
      style={{ position: "absolute", inset: 0, opacity }}
    >
      <path
        fillRule="evenodd"
        fill={color}
        fillOpacity={0.72}
        d={`M0 0H1280V720H0Z M${x + r} ${y}H${x + w - r}Q${x + w} ${y} ${x + w} ${y + r}V${y + h - r}Q${x + w} ${y + h} ${x + w - r} ${y + h}H${x + r}Q${x} ${y + h} ${x} ${y + h - r}V${y + r}Q${x} ${y} ${x + r} ${y}Z`}
      />
    </svg>
  );
}

/** Two full frames split at `y`: `top` shows above the line, `bottom` below. */
function SplitAt({
  y,
  top,
  bottom,
}: {
  y: number;
  top: ReactNode;
  bottom: ReactNode;
}) {
  return (
    <>
      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: `inset(${Math.max(0, y)}px 0 0 0)`,
        }}
      >
        {bottom}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: `inset(0 0 ${Math.max(0, 720 - y)}px 0)`,
        }}
      >
        {top}
      </div>
    </>
  );
}

/** Cubic ease-in-out between keyframes, clamped at both ends. */
function easeInOut(frame: number, input: number[], output: number[]) {
  return interpolate(frame, input, output, {
    ...clamp,
    easing: Easing.inOut(Easing.cubic),
  });
}

/* Mark data */

type Point = [number, number];

/** A distance between two points on one axis, with its value. */
type Measure = { from: Point; to: Point; label: string; side?: Side };
/** A corner whose radius gets an arc and a label. `x`, `y` is the corner. */
type RadiusMark = { x: number; y: number; r: number; label: string };
/** An off-spec element and the fix it needs. */
type Issue = {
  rect: Rect;
  note: string;
  side?: "start" | "end" | "below";
};
/** A token tag: dot on `anchor`, chip centered on `at`. */
type TokenSpec = {
  anchor: Point;
  at: Point;
  label: string;
  swatch: string;
};
/** Layout guides over a column grid. */
type GuideSpec = {
  /** x of every column edge, left to right. */
  columns: number[];
  top: number;
  bottom: number;
  /** One column (or any rect) to fill and label. */
  highlight?: { rect: Rect; label: string };
  /** A measurement drawn with the guides, like a gutter width. */
  ruler?: Measure;
  /** A horizontal marker line across the grid, like a calendar's now line. */
  now?: { y: number; from: number; to: number; label: string };
};

