type RedlineMeasureElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RedlineMeasureBase>;

const RedlineMeasureInner = forwardRef<
  HTMLDivElement,
  RedlineMeasureElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RedlineMeasure>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RedlineMeasureBase
          {...(componentProps as unknown as ComponentProps<typeof RedlineMeasureBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RedlineMeasure = Interactive.withSchema({
  Component: RedlineMeasureInner,
  componentName: "<RedlineMeasure>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { AbsoluteFill, Easing, Img, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};
const EASE_OUT = Easing.out(Easing.cubic);

type ReelProps = {
  images: string[];
  width?: number;
  height?: number;
  radius?: number;
  step?: number;
  reveal?: number;
  objectPosition?: string;
  background?: string;
};

function ReelBase({
  images,
  width = 1180,
  height = 676,
  radius = 16,
  step = 20,
  reveal = 13,
  objectPosition = "top",
  background = "#050506",
}: ReelProps) {
  const frame = useCurrentFrame();
  const { width: compWidth, height: compHeight } = useVideoConfig();
  const left = (compWidth - width) / 2;
  const top = (compHeight - height) / 2;

  return (
    <AbsoluteFill>
      {images.map((src, i) => {
        const p = interpolate(frame, [i * step, i * step + reveal], [0, 1], {
          ...clamp,
          easing: EASE_OUT,
        });
        if (p <= 0) return null;
        const inset = (1 - p) * 50;
        const imgScale = interpolate(p, [0, 1], [1.08, 1], clamp);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left,
              top,
              width,
              height,
              zIndex: i,
              clipPath: `inset(${inset}% ${inset}% round ${radius}px)`,
              WebkitClipPath: `inset(${inset}% ${inset}% round ${radius}px)`,
              background,
              boxShadow: "0 30px 80px rgba(0,0,0,0.6)",
              willChange: "clip-path",
            }}
          >
            <Img
              src={src}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                objectPosition,
                scale: `${imgScale}`,
                willChange: "transform",
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: radius,
                border: "1px solid rgba(255,255,255,0.08)",
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

