const SWEEP = Easing.bezier(0.55, 0, 0.4, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "fluted": bg #050507, #1d2a8f, #2f7bff, #ff7a3d, #ffe2c4.
