          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const gauss = (x: number, m: number, s: number) =>
  Math.exp(-((x - m) ** 2) / (2 * s * s));

interface Shape {
  m: number;
  s: number;
  m2: number;
  s2: number;
  w2: number;
}

function shapeFor(i: number, n: number): Shape {
  const k = n > 1 ? i / (n - 1) : 0;
  const side = hash(i + 7.7) > 0.45 ? 1 : -1;
  return {
    m: 0.25 + 0.14 * k + (hash(i + 0.7) - 0.5) * 0.04,
    s: 0.055 + 0.03 * hash(i + 3.1),
    m2: 0.25 + 0.14 * k + side * (0.08 + 0.06 * hash(i + 5.3)),
    s2: 0.035 + 0.025 * hash(i + 8.9),
    w2: 0.35 + 0.5 * hash(i + 2.2),
  };
}

function density(x: number, sh: Shape, shift: number) {
  return gauss(x, sh.m + shift, sh.s) + sh.w2 * gauss(x, sh.m2 + shift, sh.s2);
}

function peakOf(sh: Shape) {
  let best = 0;
  for (let i = 0; i <= 200; i++) best = Math.max(best, density(i / 200, sh, 0));
  return best || 1;
}

function RidgelineBase({
  labels = DEFAULT_LABELS,
  highlightLabel = "With remocn",
  value = "2.6×",
  caption = "more videos per team",
  axisLabel = "videos per team, per month",
  ticks = DEFAULT_TICKS,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: RidgelineProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];

  const greys = labels.slice(0, 6);
  const n = greys.length + 1;
  const x0 = W * 0.19;
  const x1 = W * 0.92;
  const yFirst = H * 0.36;
  const yLast = H * 0.82;
  const gap = n > 1 ? (yLast - yFirst) / (n - 1) : 0;
  const greyH = Math.min(gap * 2.3, H * 0.17);
  const accentH = Math.min(gap * 4, H * 0.33);

  const push = interpolate(t, [0, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const camScale = 0.975 + 0.025 * push;
  const shift = interpolate(t, SHIFT, [0, 1], { ...CLAMP, easing: EASE_IO });

  const rows = Array.from({ length: n }, (_, i) => {
    const isHl = i === n - 1;
    const sh = isHl
      ? { m: 0.4, s: 0.085, m2: 0.5, s2: 0.06, w2: 0.45 }
      : shapeFor(i, n - 1);
    const norm = peakOf(sh);
    const baseStart = BASE_AT + i * BASE_STAGGER;
    const draw = interpolate(t, [baseStart, baseStart + BASE_DRAW], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const riseAt = isHl ? ACCENT_RISE : RISE_AT + i * RISE_STAGGER;
    const rise = spring({
      frame: t - riseAt,
      fps,
      config: isHl
        ? { damping: 20, stiffness: 70, mass: 1 }
        : { damping: 18, stiffness: 110, mass: 0.8 },
    });
    const amp = (isHl ? accentH : greyH * (0.86 + 0.14 * hash(i + 4.4))) * rise;
    const off = isHl ? 0.28 * shift : 0;
    return {
      i,
      isHl,
      sh,
      norm,
      draw,
      amp,
      off,
      label: isHl ? highlightLabel : greys[i],
      y: yFirst + i * gap,
      labelIn: interpolate(t, [baseStart + 4, baseStart + 18], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      }),
    };
  });

  const paths = rows.map((r) => {
    const end = Math.max(0.0001, r.draw);
    const pts: string[] = [];
    const steps = Math.max(2, Math.ceil(SAMPLES * end));
    for (let k = 0; k <= steps; k++) {
      const nx = (end * k) / steps;
      const yv = (density(nx, r.sh, r.off) / r.norm) * r.amp;
      pts.push(
        `${k ? "L" : "M"}${(x0 + (x1 - x0) * nx).toFixed(2)} ${(r.y - yv).toFixed(2)}`,
      );
    }
    const line = pts.join(" ");
    const xEnd = x0 + (x1 - x0) * end;
    const fill = `${line} L${xEnd.toFixed(2)} ${r.y.toFixed(2)} L${x0.toFixed(2)} ${r.y.toFixed(2)} Z`;
    return { line, fill };
  });

  const hit = spring({
    frame: t - HIT,
    fps,
    config: { damping: 16, stiffness: 160, mass: 0.7 },
  });
  const hitO = interpolate(t, [HIT, HIT + 8], [0, 1], CLAMP);
  const capIn = interpolate(t, [HIT + 8, HIT + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const axisIn = interpolate(t, [10, 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const quiet = interpolate(t, [ACCENT_RISE, ACCENT_RISE + 24], [1, 0.62], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const stroke = Math.max(1, u);
  const axisY = yLast + 22 * u;
  const valueSize = 112 * u;

  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const hl = rows[n - 1];
  const auroraW = (x1 - x0) * 0.2;
  const auroraX = x0 + (x1 - x0) * (0.44 + hl.off) + auroraW * 0.15 * push;
  const auroraStops = p.aurora.map((c) => (c === "accent" ? accent : c));

  const ridgeEls: React.ReactNode[] = rows.map((r, idx) =>
    r.draw <= 0.01 ? null : (
      <g key={r.label + String(idx)}>
        <path d={paths[idx].fill} fill={p.bg} />
        {r.isHl && (
          <path
            d={paths[idx].fill}
            fill={`url(#${uid}-aurora)`}
            mask={`url(#${uid}-fade)`}
          />
        )}
        <path
          d={paths[idx].line}
          fill="none"
          stroke={r.isHl ? `url(#${uid}-aurora)` : p.line}
          strokeOpacity={r.isHl ? 1 : quiet}
          strokeWidth={(r.isHl ? 2.6 : 1.6) * u}
          strokeLinejoin="round"
          strokeLinecap="round"
        />
      </g>
    ),
  );

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `scale(${camScale})`,
          transformOrigin: "50% 55%",
        }}
      >
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={`${uid}-aurora`}
              gradientUnits="userSpaceOnUse"
              x1={auroraX - auroraW}
              y1={0}
              x2={auroraX + auroraW}
              y2={0}
            >
              {auroraStops.map((c, k) => (
                <stop
                  key={c}
                  offset={k / (auroraStops.length - 1)}
                  stopColor={c}
                />
              ))}
            </linearGradient>
            <linearGradient id={`${uid}-fadeg`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="#fff" stopOpacity={p.tint} />
              <stop offset="1" stopColor="#fff" stopOpacity={0.03} />
            </linearGradient>
            <mask
              id={`${uid}-fade`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect
                x={0}
                y={hl.y - accentH}
                width={W}
                height={accentH}
                fill={`url(#${uid}-fadeg)`}
              />
            </mask>
          </defs>
          {ridgeEls}
          <line
            x1={x0}
            x2={x0 + (x1 - x0) * axisIn}
            y1={axisY}
            y2={axisY}
            stroke={p.axis}
            strokeWidth={stroke}
          />
          {ticks.map((tk, k) => {
            const x = x0 + ((x1 - x0) * k) / Math.max(1, ticks.length - 1);
            return (
              <line
                key={tk}
                x1={x}
                x2={x}
                y1={axisY}
                y2={axisY + 6 * u}
                stroke={p.axis}
                strokeWidth={stroke}
                opacity={axisIn}
              />
            );
          })}
        </svg>

        {rows.map((r) => (
          <div
            key={`lab${r.i}`}
            style={{
              position: "absolute",
              left: x0 - 18 * u - 200 * u,
              width: 200 * u,
              top: r.y - 22 * u,
              textAlign: "right",
              fontFamily: bricolage,
              fontWeight: r.isHl ? 500 : 400,
              fontSize: 17 * u,
              lineHeight: `${22 * u}px`,
              letterSpacing: "-0.01em",
              color: r.isHl ? p.fg : p.muted,
              fontVariantNumeric: "tabular-nums",
              opacity: r.labelIn * (r.isHl ? 1 : 0.5 + 0.5 * quiet),
              transform: `translateX(${(1 - r.labelIn) * 8 * u}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {r.label}
          </div>
        ))}

        {ticks.map((tk, k) => {
          const x = x0 + ((x1 - x0) * k) / Math.max(1, ticks.length - 1);
          return (
            <div
              key={`t${tk}`}
              style={{
                position: "absolute",
                left: x - 40 * u,
                width: 80 * u,
                top: axisY + 12 * u,
                textAlign: "center",
                fontFamily: bricolage,
                fontWeight: 500,
                fontSize: 15 * u,
                color: p.muted,
                fontVariantNumeric: "tabular-nums",
                opacity: axisIn,
              }}
            >
              {tk}
            </div>
          );
        })}
        <div
          style={{
            position: "absolute",
            right: W - x1,
            top: axisY + 38 * u,
            fontFamily: bricolage,
            fontWeight: 500,
            fontSize: 15 * u,
            color: p.muted,
            opacity: axisIn,
            whiteSpace: "nowrap",
          }}
        >
          {axisLabel}
        </div>

        {value ? (
          <div
            style={{
              position: "absolute",
              right: W - x1,
              top: H * 0.09,
              textAlign: "right",
              opacity: hitO,
              transform: `translateY(${(1 - hit) * 20 * u}px)`,
            }}
          >
            <div
              style={{
                fontFamily: bricolage,
                fontWeight: 400,
                fontSize: valueSize,
                lineHeight: 0.95,
                letterSpacing: "-0.02em",
                color: p.fg,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
              }}
            >
              {value}
            </div>
            <div
              style={{
                marginTop: 8 * u,
                fontFamily: bricolage,
                fontWeight: 500,
                fontSize: 20 * u,
                letterSpacing: "-0.01em",
                color: p.muted,
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 8 * u}px)`,
                whiteSpace: "nowrap",
              }}
            >
              {caption}
            </div>
          </div>
        ) : null}
      </AbsoluteFill>
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  highlightLabel: {
    type: "text-content",
    default: "With remocn",
    description: "Highlight label",
  },
  value: {
    type: "text-content",
    default: "2.6×",
    description: "Value",
  },
  caption: {
    type: "text-content",
    default: "more videos per team",
    description: "Caption",
  },
  axisLabel: {
    type: "text-content",
    default: "videos per team, per month",
    description: "Axis label",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","highlightLabel","value","caption","axisLabel","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  highlightLabel: "With remocn",
  value: "2.6×",
  caption: "more videos per team",
  axisLabel: "videos per team, per month",
  speed: 1,
};

type RidgelineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RidgelineBase>;

const RidgelineInner = forwardRef<
  HTMLDivElement,
  RidgelineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Ridgeline>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RidgelineBase
          {...(componentProps as unknown as ComponentProps<typeof RidgelineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Ridgeline = Interactive.withSchema({
  Component: RidgelineInner,
  componentName: "<Ridgeline>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadDisplay } from "@remotion/google-fonts/Geist";
import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface RingAlignProps {
  /** Word revealed in the channel once every slot lines up. */
  word?: string;
  /** Number of concentric rings. */
  rings?: number;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const FIRST_LOCK = 30;
const LOCK_STEP = 8;
const BEAM_GAP = 4;
const BEAM = 14;
const TAIL_DELAY = 8;
const TAIL = 16;
const HOLD = 32;

const ringAlignLength = (rings = 6) =>
  FIRST_LOCK + (rings - 1) * LOCK_STEP + BEAM_GAP + TAIL_DELAY + TAIL + HOLD;

const LOCK = Easing.bezier(0.3, 0.55, 0.32, 1.05);
const WIPE = Easing.bezier(0.22, 1, 0.36, 1);
const TAIL_EASE = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function hash(n: number): number {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function circle(x: number, y: number, r: number) {
  const rs = r.toFixed(2);
  const d = (2 * r).toFixed(2);
  return `M${(x - r).toFixed(1)} ${y.toFixed(1)}a${rs} ${rs} 0 1 0 ${d} 0a${rs} ${rs} 0 1 0 -${d} 0`;
}

function wrap(a: number) {
  let v = a % (Math.PI * 2);
  if (v > Math.PI) v -= Math.PI * 2;
  if (v < -Math.PI) v += Math.PI * 2;
  return v;
}

/* gradients.sh "radial-glow" palette: the beam that runs the channel, and
   the fill the word keeps once the beam has passed. */
const GLOW = ["#f3f1ff", "#9db4ff", "#5a46cb", "#1d1240"] as const;

function Grain({ opacity, light }: { opacity: number; light: boolean }) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={`${uid}-grain`}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency={0.85}
          numOctaves={2}
          seed={3}
        />
        <feColorMatrix
          type="matrix"
          values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0"
        />
      </filter>
      <rect
        width="100%"
        height="100%"
        filter={`url(#${uid}-grain)`}
        opacity={opacity}
        style={{ mixBlendMode: light ? "multiply" : "screen" }}
      />
    </svg>
  );
}

function RingAlignBase({
  word = "Aligned.",
  rings = 6,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: RingAlignProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const isLight = theme === "light";
  const bg = isLight ? "#F5F4F0" : "#0A0A0B";
  const ink = isLight ? "#141416" : "#EEEEF0";
  const u = Math.min(W, H) / 720;
  const n = Math.max(3, Math.min(9, Math.round(rings)));
  const cx = W / 2;
  const cy = H / 2;

  const band = H * 0.175;
  const pad = 9 * u;
  const rIn = H * 0.165;
  const rOut = H * 0.44;
  const dotR = 3.1 * u;
  const pitch = 17 * u;

  const lastLock = FIRST_LOCK + (n - 1) * LOCK_STEP;
  const beamStart = lastLock + BEAM_GAP;

  const ringPaths: { d: string; opacity: number }[] = [];
  for (let k = 0; k < n; k++) {
    // Outer ring locks first, the innermost last.
    const r = rOut - ((rOut - rIn) * k) / (n - 1);
    const count = Math.round((Math.PI * 2 * r) / pitch);
    const gap = 2 * Math.asin(Math.min(0.98, (band / 2 + pad) / r));
    const lockAt = FIRST_LOCK + k * LOCK_STEP;
    const dir = k % 2 === 0 ? 1 : -1;
    const offset = dir * Math.PI * (1.35 + hash(k * 4.1) * 0.5);
    const x = Math.min(1, Math.max(0, t / lockAt));
    let rot = offset * (1 - LOCK(x));
    const since = t - lockAt;
    if (since > 0) {
      rot +=
        -dir * 0.012 * Math.sin((since / 7) * Math.PI) * Math.exp(-since / 4);
    }
    const lit = interpolate(since, [-2, 6], [0.42, 1], CLAMP);
    const segs: string[] = [];
    for (let j = 0; j < count; j++) {
      const a = (j / count) * Math.PI * 2 + rot;
      const local = wrap((j / count) * Math.PI * 2);
      const toSlot = Math.min(Math.abs(local), Math.abs(wrap(local - Math.PI)));
      if (toSlot < gap / 2) continue;
      segs.push(circle(cx + Math.cos(a) * r, cy + Math.sin(a) * r, dotR));
    }
    ringPaths.push({ d: segs.join(""), opacity: lit });
  }

  const head =
    W * WIPE(interpolate(t, [beamStart, beamStart + BEAM], [0, 1], CLAMP));
  const tail =
    W *
    TAIL_EASE(
      interpolate(
        t,
        [beamStart + TAIL_DELAY, beamStart + TAIL_DELAY + TAIL],
        [0, 1],
        CLAMP,
      ),
    );
  const fontSize = band * 0.72;
  const dot = word.endsWith(".");
  const body = dot ? word.slice(0, -1) : word;
  const [g0, g1, g2, g3] = GLOW;
  const drift = interpolate(t, [beamStart, ringAlignLength(n)], [0, 1], CLAMP);
  const wordFill = isLight
    ? `linear-gradient(90deg, ${g2} ${(-10 + 20 * drift).toFixed(1)}%, ${g3} ${(45 + 10 * drift).toFixed(1)}%, ${g2} ${(110 + 10 * drift).toFixed(1)}%)`
    : `linear-gradient(90deg, ${g1} ${(-10 + 20 * drift).toFixed(1)}%, ${g0} ${(45 + 10 * drift).toFixed(1)}%, ${g1} ${(110 + 10 * drift).toFixed(1)}%)`;
  const beamFill = `linear-gradient(90deg, ${g3} 0%, ${g2} 45%, color-mix(in oklab, ${g2} 55%, ${g1}) 88%, ${g1} 98%, ${g0} 100%)`;
  const wordLayer = (fill: string, l: number, r: number) => (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: cy - band / 2,
        width: W,
        height: band,
        clipPath: `inset(0 ${(W - r).toFixed(1)}px 0 ${l.toFixed(1)}px)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily: display,
          fontWeight: 500,
          fontSize,
          letterSpacing: "-0.035em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          paddingBottom: fontSize * 0.04,
          paddingRight: fontSize * 0.04,
          backgroundImage: fill,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }}
      >
        {body}
        {dot ? (
          <span
            style={{
              WebkitTextFillColor: fill.includes("#FFFFFF")
                ? "#FFFFFF"
                : accent,
            }}
          >
            .
          </span>
        ) : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        backgroundImage: isLight
          ? `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[1]} 16%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #FBFAF7 0%, ${bg} 72%)`
          : `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[2]} 22%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #121215 0%, ${bg} 72%)`,
        overflow: "hidden",
      }}
    >
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        {ringPaths.map((p, k) => (
          <path
            key={`ring-${k.toString()}`}
            d={p.d}
            fill={ink}
            opacity={p.opacity}
          />
        ))}
      </svg>
      {tail > 0 ? wordLayer(wordFill, 0, tail) : null}
      {head > tail + 0.5 ? (
        <div
          style={{
            position: "absolute",
            left: tail,
            top: cy - band / 2,
            width: head - tail,
            height: band,
            backgroundImage: beamFill,
          }}
        />
      ) : null}
      {head > tail + 0.5
        ? wordLayer("linear-gradient(#FFFFFF, #FFFFFF)", tail, head)
        : null}
      <Grain opacity={isLight ? 0.045 : 0.06} light={isLight} />
    </AbsoluteFill>
  );
}

