  extrapolateRight: "clamp",
} as const;

type RingKind = "a" | "b" | "line" | "final";

const START = 6;
const DUR = 24;
const RINGS: { kind: RingKind; at: number }[] = [
  { kind: "b", at: 0 },
  { kind: "line", at: 3 },
  { kind: "a", at: 6 },
  { kind: "b", at: 9 },
