];

const EXPAND = Easing.bezier(0.3, 0, 0.2, 1);
const SETTLE = Easing.bezier(0.22, 1, 0.36, 1);

/** Final ground: gradients.sh "mesh" (dark) and "pixel-glass" (light). */
const STAGES = {
  dark: {
    a: "#0A0A0B",
    aFg: "#F3F2EF",
    b: "#F5F4F0",
    aLight: "rgba(255,255,255,0.06)",
