interface RoundSlamProps {
  /** The round call, slammed in first in two hits ("ROUND" then "1"). */
  round?: string;
  /** The finisher word, punched in bigger and cracked open by the slashes. */
  call?: string;
  /** One of the thin speed slashes. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1):
//   0–6    "ROUND" slams in from 1.9× with two echo ghosts; small shake on landing
//   6–12   the round number slams in from 2.6×; frame 12 is the impact frame
//          (one inverted frame) and the camera shakes for 10 frames
//  12–34   hold with a slow push
//  34–43   the round call ducks up to a label above the stage
//  38–44   the call word punches in from 2.8×; frame 44 is the second impact:
//          inverted frame, bigger shake, the word splits along a diagonal crack
//  44–53   speed slashes crack outward from the centre, the main "chrome" band
//          opens behind the word
//  56–66   the logo rises in under the band; poster hold to the end
const ROUND_AT = 0;
const ROUND_LEN = 6;
const NUM_AT = 6;
const NUM_LEN = 6;
const DUCK_AT = 34;
const DUCK_LEN = 9;
const CALL_AT = 38;
const CALL_LEN = 6;
const LOGO_AT = 56;

// Steep cuts slashed through the band, outside the word.
const CUTS = [
  { x: -0.43, w: 22, delay: 0 },
  { x: -0.385, w: 7, delay: 1 },
  { x: 0.4, w: 14, delay: 2 },
];

const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const INOUT = Easing.bezier(0.65, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "chrome": bg #050203, [#e0202e, #ffd6b8, #4fe3f0].
const CHROME = ["#E0202E", "#FFD6B8", "#4FE3F0"] as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    dim: "#8A8990",
    slashA: CHROME[2],
    slashB: CHROME[1],
    logo: "#F3F2EF",
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    slashA: "#1F8FA0",
    slashB: CHROME[0],
    logo: "#121214",
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** Decaying camera shake that starts at `at`, stepped per frame like a game hit-stop. */
function shake(t: number, at: number, len: number, amp: number) {
  const d = Math.floor(t - at);
  if (d < 0 || d >= len) return { x: 0, y: 0 };
  const k = (1 - d / len) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.4 + 0.6),
    y: amp * 0.6 * k * Math.cos(d * 3.1 + 0.3),
  };
}

/**
 * A slash with pointed tips, running along the x axis of the (rotated) stage.
 * `reach` is how far it has cracked out from the centre, 0–1.
 */
function slashPoly(
  cx: number,
  cy: number,
  thick: number,
  half: number,
  reach: number,
  tip: number,
) {
  const r = half * reach;
  const top = cy - thick / 2;
  const bot = cy + thick / 2;
  return `polygon(${cx - r - tip}px ${cy}px, ${cx - r}px ${top}px, ${cx + r}px ${top}px, ${cx + r + tip}px ${cy}px, ${cx + r}px ${bot}px, ${cx - r}px ${bot}px)`;
}

function RoundSlamBase({
  round = "ROUND 1",
  call = "SHIP!",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: RoundSlamProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);

  const words = round.trim().split(/\s+/);
  const head = words.length > 1 ? words.slice(0, -1).join(" ") : round;
  const tail = words.length > 1 ? words[words.length - 1] : "";

  // ── Impact frames ─────────────────────────────────────────────────────────
  const numHit = NUM_AT + NUM_LEN;
  const callHit = CALL_AT + CALL_LEN;
  const inverted =
    (t >= numHit && t < numHit + speed) ||
    (t >= callHit && t < callHit + speed);
  const s1 = shake(t, ROUND_AT + ROUND_LEN, 5, 5 * u);
  const s2 = shake(t, numHit, 10, 13 * u);
  const s3 = shake(t, callHit, 14, 20 * u);
  const camX = s1.x + s2.x + s3.x;
  const camY = s1.y + s2.y + s3.y;
  const push = interpolate(t, [numHit, DUCK_AT], [1, 1.035], CLAMP);
  const settle = interpolate(t, [callHit, callHit + 70], [1, 1.025], CLAMP);

  // ── Round call ────────────────────────────────────────────────────────────
  const roundFs = 150 * u;
  const roundScale = (d: number) =>
    1.9 - 0.9 * SLAM(ramp(d, ROUND_AT, ROUND_LEN));
  const numScale = (d: number) => 2.6 - 1.6 * SLAM(ramp(d, NUM_AT, NUM_LEN));
  const duck = INOUT(ramp(t, DUCK_AT, DUCK_LEN));
  const roundY = interpolate(duck, [0, 1], [0.5 * H, 0.205 * H]);
  const roundK = interpolate(duck, [0, 1], [push, 0.36]);

  // ── Call word and the band ────────────────────────────────────────────────
  const callFs = 250 * u;
  const callY = 0.54 * H;
  const callScale = (d: number) => 2.8 - 1.8 * SLAM(ramp(d, CALL_AT, CALL_LEN));
  const callOp = ramp(t, CALL_AT, 3);
  const crack = Math.max(0, 1 - Math.max(0, t - callHit) / 9);
  const crackOff = t >= callHit ? 30 * u * crack * crack : 0;

  const half = 0.72 * W;
  const bandOpen = OUT(ramp(t, callHit + 1, 9));
  const bandThick = interpolate(bandOpen, [0, 1], [6 * u, 0.4 * H]);
  const bandReach = OUT(ramp(t, callHit, 5));
  const drift = interpolate(t, [callHit, callHit + 80], [0, 10], CLAMP);

  const slashes = [
    { dy: -0.27 * H, thick: 7 * u, delay: 0, fill: c.slashA },
    { dy: -0.235 * H, thick: 3 * u, delay: 2, fill: accent },
    { dy: 0.24 * H, thick: 11 * u, delay: 1, fill: c.slashB },
    { dy: 0.275 * H, thick: 3 * u, delay: 3, fill: c.slashA },
  ];

  const bandGround = [
    `radial-gradient(38% 55% at ${30 + drift}% 34%, ${CHROME[1]}e6 0%, transparent 62%)`,
    `radial-gradient(55% 80% at ${68 - drift}% 68%, #FF3B4Acc 0%, transparent 70%)`,
    `linear-gradient(100deg, #4A0610 4%, ${CHROME[0]} 30%, #C0142A 64%, #2E0410 96%)`,
  ].join(", ");

  const logoP = OUT(ramp(t, LOGO_AT, 10));

  const word = (
    text: string,
    fs: number,
    color: string,
    extra?: React.CSSProperties,
  ) => (
    <div
      style={{
        fontFamily: display,
        fontWeight: 500,
        fontSize: fs,
        lineHeight: 1,
        letterSpacing: "-0.02em",
        color,
        whiteSpace: "nowrap",
        ...extra,
      }}
    >
      {text}
    </div>
  );

  // The call word, sliced on a diagonal so the two halves can crack apart.
  const cutTop = `polygon(0 0, 100% 0, 100% 38%, 0 62%)`;
  const cutBot = `polygon(0 62%, 100% 38%, 100% 100%, 0 100%)`;
  const callBox = (scale: number, opacity: number, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        width: W,
        top: callY - callFs * 0.6,
        height: callFs * 1.2,
        transform: `scale(${scale})`,
        opacity,
      }}
    >
      {(crackOff > 0.01 ? [cutTop, cutBot] : ["none"]).map((clip, i) => (
        <div
          key={clip}
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            clipPath: clip === "none" ? undefined : clip,
            transform: `translateX(${i === 0 ? crackOff : -crackOff}px)`,
          }}
        >
          {word(
            call,
            callFs,
            theme === "dark" ? "#FFFFFF" : bandOpen > 0.5 ? "#FFFFFF" : c.ink,
            {
              paddingTop: callFs * 0.06,
            },
          )}
        </div>
      ))}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: c.stage,
          filter: inverted ? "invert(1)" : undefined,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${camX}px, ${camY}px) rotate(-6deg) scale(${settle})`,
            transformOrigin: "50% 50%",
          }}
        >
          {/* The chrome band and slashes crack open behind the call word. */}
          {t >= callHit ? (
            <>
              <div
                style={{
                  position: "absolute",
                  inset: `${-0.2 * H}px ${-0.2 * W}px`,
                  clipPath: slashPoly(
                    W / 2 + 0.2 * W,
                    callY + 0.2 * H,
                    bandThick,
                    half,
                    bandReach,
                    bandThick * 0.9,
                  ),
                  background: bandGround,
                }}
              />
              {CUTS.map((k) => {
                const x = W / 2 + k.x * W;
                const top = callY - bandThick / 2 - 2;
                const bot = callY + bandThick / 2 + 2;
                const lean = 0.32 * bandThick;
                const w = k.w * u;
                const p = OUT(ramp(t, callHit + 2 + k.delay, 5));
                const yEnd = top + (bot - top) * p;
                const xAt = (y: number) =>
                  x + lean - ((y - top) / (bot - top)) * 2 * lean;
                return (
                  <div
                    key={k.x}
                    style={{
                      position: "absolute",
                      inset: 0,
                      clipPath: `polygon(${xAt(top)}px ${top}px, ${xAt(top) + w}px ${top}px, ${xAt(yEnd) + w}px ${yEnd}px, ${xAt(yEnd)}px ${yEnd}px)`,
                      background: c.stage,
                    }}
                  />
                );
              })}
              {slashes.map((s) => {
                const reach = OUT(ramp(t, callHit + s.delay, 6));
                return (
                  <div
                    key={s.dy}
                    style={{
                      position: "absolute",
                      inset: 0,
                      clipPath: slashPoly(
                        W / 2,
                        callY + s.dy,
                        s.thick,
                        half,
                        reach,
                        60 * u,
                      ),
                      background: s.fill,
                    }}
                  />
                );
              })}
            </>
          ) : null}

          {/* Round call: echoes trail the slam, then it ducks to a label. */}
          {[4, 2, 0].map((lag) => {
            const tt = t - lag;
            const ghost = lag > 0;
            const headK = roundScale(tt);
            const numK = numScale(tt);
            const headOp = ramp(tt, ROUND_AT, 2) * (ghost ? 0.18 / lag : 1);
            const numOp = ramp(tt, NUM_AT, 2) * (ghost ? 0.18 / lag : 1);
            if (ghost && t > numHit + lag) return null;
            return (
              <div
                key={lag}
                style={{
                  position: "absolute",
                  left: 0,
                  width: W,
                  top: roundY - roundFs * 0.6,
                  height: roundFs * 1.2,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 0.32 * roundFs,
                  transform: `scale(${ghost ? 1 : roundK})`,
                }}
              >
                {word(head, roundFs, c.ink, {
                  transform: `scale(${headK})`,
                  opacity: headOp,
                  paddingTop: roundFs * 0.06,
                })}
                {tail
                  ? word(tail, roundFs, c.ink, {
                      transform: `scale(${numK})`,
                      opacity: numOp,
                      paddingTop: roundFs * 0.06,
                    })
                  : null}
              </div>
            );
          })}

          {/* Call word with echoes. */}
          {t >= CALL_AT
            ? [4, 2].map((lag) =>
                t < callHit + lag
                  ? callBox(
                      callScale(t - lag),
                      ramp(t - lag, CALL_AT, 3) * (0.2 / lag),
                      `g${lag}`,
                    )
                  : null,
              )
            : null}
          {t >= CALL_AT ? callBox(callScale(t), callOp, "call") : null}
        </div>

        {/* Logo under the band. */}
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: 0.885 * H,
            display: "flex",
            justifyContent: "center",
            opacity: logoP,
            transform: `translateY(${(1 - logoP) * 18 * u}px)`,
          }}
        >
          <RemocnLogo fontSize={34 * u} color={c.logo} />
        </div>
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  round: {
    type: "text-content",
    default: "ROUND 1",
    description: "Round",
  },
  call: {
    type: "text-content",
    default: "SHIP!",
    description: "Call",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","round","call","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  round: "ROUND 1",
  call: "SHIP!",
  speed: 1,
};

type RoundSlamElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RoundSlamBase>;

const RoundSlamInner = forwardRef<
  HTMLDivElement,
  RoundSlamElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RoundSlam>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RoundSlamBase
          {...(componentProps as unknown as ComponentProps<typeof RoundSlamBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RoundSlam = Interactive.withSchema({
  Component: RoundSlamInner,
  componentName: "<RoundSlam>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadPlexSans } from "@remotion/google-fonts/IBMPlexSans";
import { useMemo } from "react";
import { AbsoluteFill, Easing, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";

const plex = loadPlexSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface RowCountProps {
  value?: number;
  from?: number;
  prefix?: string;
  label?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0F1B2D",
    ink: "#F3F5F8",
    muted: "#93A1B5",
    comma: "#4D5D75",
    rule: "rgba(243, 245, 248, 0.22)",
    accent: "#FF9900",
  },
  light: {
    bg: "#FFFFFF",
    ink: "#0F1B2D",
    muted: "#5A677A",
    comma: "#B5BDC9",
    rule: "rgba(15, 27, 45, 0.2)",
    accent: "#C76A00",
  },
} as const;

const FIG = 0.6;
const COMMA = 0.26;
const ROW = 1.0;
const TRACK = -0.02;

const COUNT_AT = 6;
const COUNT_LEN = 78;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_COUNT = Easing.bezier(0.3, 0.1, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function groups(n: number): string[] {
  const s = String(Math.max(0, Math.floor(n)));
  const out: string[] = [];
  for (let end = s.length; end > 0; end -= 3) {
    out.unshift(s.slice(Math.max(0, end - 3), end));
  }
  return out;
}

export function RowCount({
  value = 27300000,
  from = 1,
  prefix = "",
  label = "frames rendered in every region, every night",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: RowCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  const target = Math.max(1, Math.floor(value));
  const start = Math.min(target, Math.max(1, Math.floor(from)));
  const finalRows = groups(target).length;

  const p = interpolate(t, [COUNT_AT, COUNT_AT + COUNT_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_COUNT,
  });
  const live =
    p >= 1
      ? target
      : Math.floor(start * (target / start) ** Math.min(1, Math.max(0, p)));
  const g = groups(live);
  const rows = g.length;

  const rowBorn = useMemo(() => {
    const born: number[] = [];
    for (let k = 0; k < finalRows; k++) {
      const thresh = 1000 ** k;
      if (thresh <= start) {
        born.push(-100);
        continue;
      }
      let lo = COUNT_AT;
      let hi = COUNT_AT + COUNT_LEN;
      for (let i = 0; i < 24; i++) {
        const mid = (lo + hi) / 2;
        const pm = interpolate(mid, [COUNT_AT, COUNT_AT + COUNT_LEN], [0, 1], {
          ...CLAMP,
          easing: EASE_COUNT,
        });
        const v = start * (target / start) ** pm;
        if (v >= thresh) hi = mid;
        else lo = mid;
      }
      born.push(hi);
    }
    return born;
  }, [finalRows, start, target]);

  const shift = (k: number) => {
    let s = 0;
    for (let j = k + 1; j < finalRows; j++) {
      s += spring({
        frame: t - rowBorn[j] + 4,
        fps,
        config: { damping: 16, stiffness: 140, mass: 0.8 },
      });
    }
    return s;
  };
  let rowsAnim = 1;
  for (let k = 1; k < finalRows; k++) {
    rowsAnim += spring({
      frame: t - rowBorn[k] + 4,
      fps,
      config: { damping: 16, stiffness: 140, mass: 0.8 },
    });
  }

  const portrait = H > W * 1.1;
  const margin = Math.min(W, H) * 0.09;
  const prefixW = prefix ? Array.from(prefix).length * FIG : 0;
  const colW = prefixW + 3 * FIG + 2 * TRACK;
  const labelSize = label
    ? portrait
      ? Math.min(W * 0.06, H * 0.034)
      : Math.min(H * 0.042, W * 0.026)
    : 0;
  const labelW = portrait ? W - margin * 2 : W * 0.34;
  const labelBlock = portrait && label ? labelSize * 1.3 * 3 + margin * 0.6 : 0;
  const ruleY = margin;
  const avail = H - margin * 2 - labelBlock - margin * 0.3;
  const F = Math.min(
    avail / (Math.max(2, finalRows) * ROW),
    (W * (portrait ? 0.74 : 0.5)) / (colW + COMMA),
    H * 0.3,
  );
  const rowH = F * ROW;
  const colRight = W - margin - COMMA * F;
  const firstTop = ruleY + labelBlock + margin * 0.3;

  const ruleP = interpolate(t, [0, 16], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const enter = interpolate(t, [0, 14], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const labelP = interpolate(t, [6, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const rowEls = g.map((grp, idx) => {
    const k = rows - 1 - idx;
    const born = interpolate(t, [rowBorn[k], rowBorn[k] + 10], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const isNew = k === 0 ? enter : born;
    const y = firstTop + shift(k) * rowH;
    const topness = Math.max(0, 1 - Math.abs(rowsAnim - 1 - k));
    const text = (k === rows - 1 ? prefix : "") + grp;
    const comma = k > 0;
    return (
      <div key={`r${k}`}>
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: y,
            height: rowH,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              right: W - colRight,
              top: (isNew - 1) * rowH,
              height: rowH,
              display: "flex",
              alignItems: "baseline",
              fontFamily: plex.fontFamily,
              fontWeight: 500,
              fontSize: F,
              lineHeight: `${rowH}px`,
              letterSpacing: `${TRACK}em`,
              fontFeatureSettings: '"tnum" 1, "lnum" 1',
              whiteSpace: "pre",
            }}
          >
            <span style={{ position: "relative", color: c.ink }}>
              {text}
              <span
                aria-hidden
                style={{
                  position: "absolute",
                  inset: 0,
                  opacity: topness,
                  color: accent ?? c.accent,
                }}
              >
                {text}
              </span>
            </span>
            {comma ? (
              <span
                style={{
                  position: "absolute",
                  left: "100%",
                  color: c.comma,
                  letterSpacing: 0,
                }}
              >
                ,
              </span>
            ) : null}
          </div>
        </div>
        <div
          style={{
            position: "absolute",
            left: margin + (W - margin * 2) * (1 - isNew),
            right: margin,
            top: y + rowH,
            height: 1,
            background: c.rule,
          }}
        />
      </div>
    );
  });

  const labelEl = label ? (
    <div
      style={{
        position: "absolute",
        left: margin,
        width: labelW,
        top: ruleY + labelSize * 0.9,
        height: labelSize * 1.3 * 3,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          fontFamily: plex.fontFamily,
          fontWeight: 400,
          fontSize: labelSize,
          lineHeight: 1.3,
          letterSpacing: "-0.005em",
          color: c.muted,
          textWrap: "balance",
          transform: `translateY(${((1 - labelP) * labelSize * 4).toFixed(2)}px)`,
        }}
      >
        {label}
      </div>
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: margin,
          top: ruleY,
          width: (W - margin * 2) * ruleP,
          height: Math.max(2, H * 0.003),
          background: c.ink,
        }}
      />
      {rowEls}
      {labelEl}
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/Lexend";
import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const lexend = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

interface RsvpField {
  label: string;
  value: string;
}

interface RsvpProps {
  headline?: string;
  fields?: RsvpField[];
  rsvpLabel?: string;
  rsvp?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#E8392B", ink: "#FFFFFF", accent: "#0A0A0A" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", accent: "#E8392B" },
} as const;

const TRACK = -0.035;
const ROW_TRACK = -0.012;
const LH = 1.04;
const ROW_LH = 1.2;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Spec {
  text: string;
  weight: number;
}

function useWidths(specs: Spec[]) {
  const key = specs.map((s) => `${s.weight}|${s.text}`).join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("rsvp: measuring"));
  const released = useRef(false);
  const ref = useRef(specs);
  ref.current = specs;
  useEffect(() => {
    let live = true;
    const weights = Array.from(new Set(ref.current.map((s) => s.weight)));
    Promise.all([
      lexend.waitUntilDone(),
      ...weights.map((wt) =>
        document.fonts.load(`${wt} 100px "${lexend.fontFamily}"`),
      ),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        for (const s of ref.current) {
          const k = `${s.weight}|${s.text}`;
          if (ctx) {
            ctx.font = `${s.weight} 100px "${lexend.fontFamily}"`;
            w[k] = ctx.measureText(s.text).width / 100;
          } else {
            w[k] = s.text.length * 0.56;
          }
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.w : null;
}

function greedy(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const lines: string[][] = [];
  let line: string[] = [];
  let x = 0;
  for (const word of words) {
    const w = adv(word);
    if (line.length > 0 && x + space + w > maxEm) {
      lines.push(line);
      line = [word];
      x = w;
    } else {
      x += (line.length > 0 ? space : 0) + w;
      line.push(word);
    }
  }
  if (line.length > 0) lines.push(line);
  return lines;
}

function balanced(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const base = greedy(words, adv, space, maxEm);
  if (base.length <= 1) return base;
  let lo = 0;
  let hi = maxEm;
  for (let k = 0; k < 24; k++) {
    const mid = (lo + hi) / 2;
    if (greedy(words, adv, space, mid).length <= base.length) hi = mid;
    else lo = mid;
  }
  return greedy(words, adv, space, hi);
}

const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);

const DEFAULT_FIELDS: RsvpField[] = [
  { label: "What", value: "Your launch film" },
  { label: "When", value: "Whenever you’re ready" },
  { label: "Where", value: "Your own repo" },
  { label: "Bring", value: "The story. We brought the parts." },
];

function RsvpBase({
  headline = "You’re invited.",
  fields = DEFAULT_FIELDS,
  rsvpLabel = "RSVP",
  rsvp = "npx shadcn add @remocn/whip-pan",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: RsvpProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const Tt = durationInFrames * speed;
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const rows = [
    ...fields.filter((f) => f.label || f.value),
    ...(rsvp ? [{ label: rsvpLabel, value: rsvp }] : []),
  ];
  const headWords = splitWords(headline);
  const rowWords = rows.map((r) => splitWords(r.value));
  const w = useWidths([
    { text: " ", weight: 500 },
    { text: " ", weight: 400 },
    ...headWords.map((text) => ({ text, weight: 500 })),
    ...rows.map((r) => ({ text: r.label, weight: 400 })),
    ...rowWords.flat().map((text) => ({ text, weight: 400 })),
  ]);

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const headAdv = (s: string) =>
    (w[`500|${s}`] ?? s.length * 0.56) + TRACK * Array.from(s).length;
  const rowAdv = (s: string) =>
    (w[`400|${s}`] ?? s.length * 0.56) + ROW_TRACK * Array.from(s).length;
  const headSpace = w["500| "] ?? 0.25;
  const rowSpace = w["400| "] ?? 0.25;

  const portrait = H > W * 1.1;
  const mx = W * (portrait ? 0.08 : 0.07);
  const availW = W - mx * 2;
  const labelEm = Math.max(0, ...rows.map((r) => rowAdv(r.label)));

  let fH = portrait ? W * 0.2 : H * 0.2;
  let fR = portrait ? W * 0.064 : H * 0.054;
  const labelH = portrait ? ROW_LH * 0.72 : 0;
  const build = () => {
    const headLines = balanced(headWords, headAdv, headSpace, availW / fH);
    const labelCol = portrait
      ? 0
      : Math.max(labelEm * fR + fR * 1.4, availW * 0.2);
    const valueW = availW - labelCol;
    const valueLines = rowWords.map((ws) =>
      balanced(ws, rowAdv, rowSpace, valueW / fR),
    );
    const headH = headLines.length * LH * fH;
    const gapHR = fH * (portrait ? 0.5 : 0.36);
    const rowGap = fR * (portrait ? 0.9 : 0.62);
    const rowHs = valueLines.map(
      (ls) => (labelH + Math.max(1, ls.length) * ROW_LH) * fR,
    );
    const rowsH =
      rowHs.reduce((a, b) => a + b, 0) + rowGap * Math.max(0, rowHs.length - 1);
    return {
      headLines,
      labelCol,
      valueLines,
      headH,
      gapHR,
      rowGap,
      rowHs,
      rowsH,
      total: headH + gapHR + rowsH,
    };
  };
  let B = build();
  const maxH = H * (portrait ? 0.76 : 0.82);
  for (let k = 0; k < 80; k++) {
    if (B.total <= maxH && B.headLines.length <= (portrait ? 3 : 2)) break;
    fH *= 0.96;
    fR *= 0.97;
    B = build();
  }

  const top = portrait
    ? (H - B.total) / 2 - H * 0.02
    : Math.max(H * 0.09, (H - B.total) / 2 - H * 0.04);
  const rowsTop = top + B.headH + B.gapHR;

  const n = rows.length;
  const rowStart = 26;
  const span = Math.max(n * 10, Math.min(Tt * 0.5, Tt - 70) - rowStart);
  const rowStep = Math.min(16, span / Math.max(1, n));
  const rowAt = (k: number) =>
    rowStart + k * rowStep + (rsvp && k === n - 1 ? 10 : 0);
  const lastAt = rowAt(n - 1);
  const focus = rsvp
    ? interpolate(t, [lastAt + 12, lastAt + 30], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      })
    : 0;

  let wordIndex = 0;
  const headNodes = B.headLines.map((line, li) => (
    <div
      key={`h${li}`}
      style={{
        position: "absolute",
        left: mx,
        top: top + li * LH * fH,
        height: LH * fH,
        lineHeight: `${LH * fH}px`,
        fontSize: fH,
        fontWeight: 500,
        whiteSpace: "pre",
        letterSpacing: `${TRACK}em`,
        color: c.ink,
      }}
    >
      {line.map((word, wi) => {
        const s = 3 + wordIndex * 4;
        wordIndex++;
        const e = interpolate(t, [s, s + 20], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span key={`hw${wi}`}>
            {wi > 0 ? " " : ""}
            <span
              style={{
                display: "inline-block",
                opacity: e,
                transform: `translateY(${((1 - e) * fH * 0.3).toFixed(2)}px)`,
              }}
            >
              {word}
            </span>
          </span>
        );
      })}
    </div>
  ));

  let y = rowsTop;
  const rowNodes = rows.map((row, k) => {
    const rowTop = y;
    y += B.rowHs[k] + B.rowGap;
    const at = rowAt(k);
    const le = interpolate(t, [at, at + 14], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const isRsvp = Boolean(rsvp) && k === n - 1;
    const dim = isRsvp ? 1 : 1 - 0.45 * focus;
    return (
      <div
        key={`r${k}`}
        style={{
          position: "absolute",
          left: mx,
          top: rowTop,
          width: availW,
          height: B.rowHs[k],
          fontSize: fR,
          lineHeight: `${ROW_LH * fR}px`,
          letterSpacing: `${ROW_TRACK}em`,
          whiteSpace: "pre",
          opacity: dim,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            fontSize: portrait ? fR * 0.62 : fR,
            lineHeight: `${(portrait ? labelH : ROW_LH) * fR}px`,
            fontWeight: 400,
            color: hi,
            opacity: le,
            transform: `translateY(${((1 - le) * fR * 0.5).toFixed(2)}px)`,
          }}
        >
          {row.label}
        </div>
        <div
          style={{
            position: "absolute",
            left: B.labelCol,
            top: labelH * fR,
            fontWeight: 400,
            color: isRsvp ? hi : c.ink,
          }}
        >
          {B.valueLines[k].map((line, li) => {
            const before = B.valueLines[k]
              .slice(0, li)
              .reduce((a, l) => a + l.length, 0);
            return (
              <div key={`v${li}`}>
                {line.map((word, wi) => {
                  const s = at + 5 + (before + wi) * 2;
                  const e = interpolate(t, [s, s + 16], [0, 1], {
                    ...CLAMP,
                    easing: EASE_OUT,
                  });
                  return (
                    <span key={`vw${wi}`}>
                      {wi > 0 ? " " : ""}
                      <span
                        style={{
                          display: "inline-block",
                          opacity: e,
                          transform: `translateY(${((1 - e) * fR * 0.55).toFixed(2)}px)`,
                        }}
                      >
                        {word}
                      </span>
                    </span>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily: lexend.fontFamily,
      }}
    >
      {headNodes}
      {rowNodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  headline: {
    type: "text-content",
    default: "You’re invited.",
    description: "Headline",
  },
  rsvpLabel: {
    type: "text-content",
    default: "RSVP",
    description: "Rsvp label",
  },
  rsvp: {
    type: "text-content",
    default: "npx shadcn add @remocn/whip-pan",
    description: "Rsvp",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","headline","rsvpLabel","rsvp","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  headline: "You’re invited.",
  rsvpLabel: "RSVP",
  rsvp: "npx shadcn add @remocn/whip-pan",
  speed: 1,
};

type RsvpElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RsvpBase>;

const RsvpInner = forwardRef<
  HTMLDivElement,
  RsvpElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Rsvp>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RsvpBase
          {...(componentProps as unknown as ComponentProps<typeof RsvpBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Rsvp = Interactive.withSchema({
  Component: RsvpInner,
  componentName: "<Rsvp>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

