  937, 858, 865, 649, 865, 710, 682, 602, 785, 719, 1052, 705, 654, 652, 382,
  365, 382, 587, 581, 300, 581, 694, 608, 694, 616, 380, 679, 644, 317, 324,
  595, 296, 973, 644, 678, 694, 694, 414, 543, 429, 634, 572, 873, 574, 555,
  493, 382, 375, 382, 511,
];
const RSB = [
  0, 81, 81, 35, 50, 31, 25, 80, 13, 64, 45, 60, 51, 59, 65, 23, 67, 110, 53,
  55, 24, 42, 47, 31, 47, 66, 65, 48, 74, 60, 74, 43, 61, 23, 60, 33, 41, 59,
  44, 31, 98, 100, 86, -9, 26, 98, 98, 51, 32, 51, 21, 49, 24, 84, 28, 27, 15,
  15, 43, 50, 15, 102, 60, 0, 86, 77, 48, 35, 86, 40, 10, 80, 77, 88, 84, 1, 86,
  77, 77, 48, 48, 86, 18, 42, 41, 88, 30, 34, 16, 24, 34, 43, 136, 52, 20,
];
const LSB = [
  0, 82, 81, 35, 49, 31, 29, 81, 64, 13, 45, 61, 20, 59, 65, 23, 67, 39, 62, 41,
  43, 53, 66, 43, 47, 47, 65, 23, 74, 61, 74, 36, 61, 23, 98, 52, 98, 98, 98,
  52, 98, 100, 37, 98, 98, 98, 98, 52, 98, 52, 98, 48, 25, 84, 22, 27, 14, 13,
  54, 102, 15, 50, 61, 0, 0, 41, 86, 48, 48, 48, 28, 48, 86, 33, 0, 86, 21, 86,
  86, 48, 86, 48, 86, 39, 12, 74, 21, 23, 23, 14, 49, 52, 136, 43, 20,
];
// Lowercase + period kerning pairs, |k| >= 10/1000.
const KERN = new Map(
  [
    "bv-11 bw-11 bx-12 by-11 b.-13 ff-38 fl12 fv17 fw17 fy17 f.-43 kc-15",
    "kd-15 ke-15 kg-15 ko-15 kq-15 ks-10 ov-11 ow-11 ox-12 oy-11 o.-13",
    "pv-11 pw-11 px-12 py-11 p.-13 qj15 rt11 rv18 rw18 ry18 r.-61 vc-11",
    "vd-11 ve-11 vg-11 vo-11 vq-11 vt10 v.-37 wc-11 wd-11 we-11 wg-11 wo-11",
    "wq-11 wt10 w.-37 xa-10 xc-12 xd-12 xe-12 xg-12 xo-12 xq-12 xu-12 yc-11",
    "yd-11 ye-11 yg-11 yo-11 yq-11 yt10 y.-37 .c-13 .d-13 .e-13 .g-13 .o-13",
    ".q-13 .u-17 .v-37 .w-37 .y-37",
  ]
    .join(" ")
    .split(" ")
    .map((p) => [p.slice(0, 2), Number(p.slice(2)) / 1000] as const),
);
// Sora's hhea box is 0.97 + 0.29 em; with lineHeight 1 the baseline sits at 0.84.
const TRACK = -0.03;
const BASELINE = 0.84;
const XHEIGHT = 0.534;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "halo" palette (#fff4ec #ffb36b #e2457a #3d4dff), warm end at
// the word, accent end at the pulled letter. The band carries it while pulled;
// the snapped word inherits it. Light swaps the pale amber for one that reads.
const THEMES = {
  dark: { bg: "#0A0A0B", fg: "#F3F2EF", halo: ["#FFB36B", "#E2457A"] },
  light: { bg: "#F5F4F0", fg: "#121214", halo: ["#E8743A", "#D83A71"] },
} as const;

// Beats (frames at speed 1).
const GRAB = 22;
const DRAG_END = 56;
const RELEASE = 64;

function adv(ch: string) {
  const c = ch.charCodeAt(0);
  return (c >= 32 && c < 127 ? ADV[c - 32] : 600) / 1000;
}
function lsb(ch: string) {
  const c = ch.charCodeAt(0);
  return (c >= 32 && c < 127 ? LSB[c - 32] : 50) / 1000;
}
function rsb(ch: string) {
  const c = ch.charCodeAt(0);
  return (c >= 32 && c < 127 ? RSB[c - 32] : 50) / 1000;
}

/** Glyph left edges and widths in em, plus the total advance. */
function layout(text: string) {
  const xs: number[] = [];
  const ws: number[] = [];
  let x = 0;
  for (let i = 0; i < text.length; i++) {
    if (i > 0) x += (KERN.get(text[i - 1] + text[i]) ?? 0) + TRACK;
    xs.push(x);
    ws.push(adv(text[i]));
    x += adv(text[i]);
  }
  return { xs, ws, width: x };
}

/**
 * The elastic. Pulled (`s > 0`): the grabbed last glyph travels with the
 * cursor, the letters before it spread a little toward it and squash. On the
 * overshoot (`s < 0`) the whole word compresses evenly, so nothing overlaps.
 */
function elastic(
  i: number,
  count: number,
  xs: number[],
  s: number,
  sMax: number,
) {
  const last = count - 1;
  const u = count > 1 ? (xs[i] - xs[0]) / Math.max(1e-3, xs[last] - xs[0]) : 1;
  if (s >= 0) {
    const k = s / sMax;
    if (i === last) return { dx: s, sx: 1 + 0.07 * k, sy: 1 - 0.07 * k };
    return {
      dx: s * 0.16 * u ** 1.3,
      sx: 1 + 0.05 * k * u,
      sy: 1 - 0.05 * k * u,
    };
  }
  const k = Math.max(-1, s / (sMax * 0.14));
  return { dx: s * 0.5 * u, sx: 1 + 0.05 * k * u, sy: 1 - 0.07 * k * u };
}

/** Taffy band between the word and the pulled letter: thins and pinches as it grows. */
function bandPath(
  xL: number,
  xR: number,
  cy: number,
  xh: number,
  F: number,
  thinAs: number,
) {
  const L = Math.max(0, xR - xL);
  const thin = (1 / (1 + Math.max(0, thinAs) / (0.55 * F))) ** 0.85;
  const a = xh * 0.5 * Math.max(0.2, thin * 0.75);
  const b = xh * 0.5 * Math.max(0.4, 0.95 * thin ** 0.4);
  const c = a * (0.62 + 0.38 * thin);
  const h1 = xL + L * 0.38;
  const h2 = xR - L * 0.38;
  return [
    `M${xL} ${cy - a}`,
    `C${h1} ${cy - c} ${h2} ${cy - c} ${xR} ${cy - b}`,
    `L${xR} ${cy + b}`,
    `C${h2} ${cy + c} ${h1} ${cy + c} ${xL} ${cy + a}`,
    `A${a} ${a} 0 0 1 ${xL} ${cy - a}Z`,
  ].join("");
}

function Cursor({ size, pressed }: { size: number; pressed: number }) {
  return (
    <svg
      width={size * 0.7}
      height={size}
      viewBox="0 0 17.5 25"
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        overflow: "visible",
        transformOrigin: "6% 6%",
        transform: `scale(${1 - 0.1 * pressed})`,
        filter: "drop-shadow(0 1.5px 2px rgba(0,0,0,0.32))",
      }}
      aria-hidden
    >
      <path
        d="M1.5 1.5 L1.5 20.6 L6.1 16.3 L9.1 23.2 L12.6 21.7 L9.7 14.9 L15.9 14.9 Z"
        fill="#0A0A0B"
        stroke="#FFFFFF"
        strokeWidth={1.4}
        strokeLinejoin="round"
      />
    </svg>
  );
}

function RubberbandWordBase({
  word = "tension",
  snapWord = "release",
  period = true,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: RubberbandWordProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const t = THEMES[theme];

  const from = word.trim() || "tension";
  const to = snapWord.trim() || from;
  const swaps = to !== from;

  const A = layout(from);
  const B = layout(to);
  const dotW = period ? adv(".") + TRACK : 0;
  const longest = Math.max(A.width, B.width + dotW);
  const F = Math.min(H * 0.27, (W * 0.54) / longest);
  const xh = XHEIGHT * F;
  const baseline = H * 0.5 + xh * 0.5;
  const cy = baseline - xh * 0.5;
  const leftA = (W - A.width * F) / 2;
  const leftB = swaps ? (W - (B.width + dotW) * F) / 2 : leftA;
  const sMax = W * 0.21;

  // Pull: drag out, hold the tension, then let go with one damped overshoot.
  const drag = interpolate(frame, [GRAB + 4, DRAG_END], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const creep = interpolate(frame, [DRAG_END, RELEASE], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const held = sMax * (0.95 * drag + 0.05 * creep);
  const snap = spring({
    frame: frame - RELEASE,
    fps,
    config: { damping: 15, stiffness: 230, mass: 1 },
  });
  const s = frame < RELEASE ? held : sMax * (1 - snap);

  // Grab point: the last glyph's right stem, at mid x-height.
  const lastA = from.length - 1;
  const grabX0 =
    leftA + (A.xs[lastA] + A.ws[lastA] - rsb(from[lastA])) * F - F * 0.05;
  const press = interpolate(
    frame,
    [GRAB, GRAB + 3, RELEASE, RELEASE + 4],
    [0, 1, 1, 0],
    CLAMP,
  );
  const approach = interpolate(frame, [0, GRAB], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const startX = W * 0.8;
  const startY = H * 0.86;
  const arc = Math.sin(approach * Math.PI) * H * 0.05;
  const away = interpolate(frame, [RELEASE + 1, RELEASE + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lift = H * 0.015 * (0.95 * drag + 0.05 * creep);
  let cx = startX + (grabX0 - startX) * approach + arc * 0.5;
  let cyCursor = startY + (cy - startY) * approach + arc;
  if (frame >= GRAB) {
    cx = grabX0 + held;
    cyCursor = cy - lift;
  }
  if (frame >= RELEASE) {
    cx = grabX0 + sMax + W * 0.03 * away;
    cyCursor = cy - H * 0.015 + H * 0.06 * away;
  }
  const cursorOpacity = interpolate(
    frame,
    [RELEASE + 8, RELEASE + 22],
    [1, 0],
    CLAMP,
  );
  const cursorSize = H * 0.085;

  // The swap rides the snap: the old word squashes flat onto its baseline,
  // the new one springs up out of that line with one overshoot.
  const SWAP = RELEASE + 4;
  const clipTop = baseline - F * 0.98;
  const clipH = F * 1.24;
  const squash = (i: number, count: number, incoming: boolean) => {
    const start = SWAP + (count - 1 - i) * 0.5 + (incoming ? 4 : 0);
    if (!incoming) {
      return interpolate(frame, [start, start + 5], [1, 0], {
        ...CLAMP,
        easing: Easing.bezier(0.55, 0, 1, 0.45),
      });
    }
    return spring({
      frame: frame - start,
      fps,
      config: { damping: 12, stiffness: 240, mass: 0.8 },
    });
  };
  const halo = [t.halo[0], t.halo[1], accent];
  const wordGradient = `linear-gradient(90deg, ${halo[0]} 0%, ${halo[1]} 52%, ${halo[2]} 100%)`;
  // The fill is a touch wider than the word and slides a few percent so the
  // last letter settles on the accent, next to the accent period.
  const gradW = B.width * F * 1.12;
  const gradShift =
    B.width *
    F *
    0.12 *
    interpolate(frame, [RELEASE, RELEASE + 60], [0, 1], {
      ...CLAMP,
      easing: Easing.bezier(0.45, 0, 0.55, 1),
    });
  const accentOn = interpolate(frame, [GRAB, GRAB + 3], [0, 1], CLAMP) > 0.5;

  const glyphs = (
    text: string,
    L: ReturnType<typeof layout>,
    left: number,
    incoming: boolean,
  ) =>
    text.split("").map((ch, i) => {
      const g = elastic(i, text.length, L.xs, s, sMax);
      const q = swaps ? squash(i, text.length, incoming) : 1;
      if (q <= 0.01) return null;
      const isLast = i === text.length - 1;
      const color =
        !incoming && isLast && accentOn && (swaps || frame < RELEASE + 6)
          ? accent
          : t.fg;
      const w = L.ws[i] * F;
      // The snapped word wears the gradient; without a swap the word itself does.
      const fill: React.CSSProperties =
        incoming || (!swaps && frame >= RELEASE + 6)
          ? {
              color: "transparent",
              backgroundImage: wordGradient,
              backgroundRepeat: "no-repeat",
              backgroundSize: `${gradW}px ${F}px`,
              backgroundPosition: `${-L.xs[i] * F - gradShift}px 0px`,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
            }
          : { color };
      return (
        <span
          key={`${uid}-${incoming ? "b" : "a"}-${i}`}
          style={{
            position: "absolute",
            left: left + L.xs[i] * F + g.dx,
            top: baseline - clipTop - BASELINE * F,
            width: w,
            fontSize: F,
            lineHeight: 1,
            ...fill,
            opacity: Math.min(1, q * 6),
            transformOrigin: `50% ${BASELINE * F}px`,
            transform: `scale(${g.sx}, ${g.sy * q})`,
            whiteSpace: "pre",
          }}
        >
          {ch}
        </span>
      );
    });

  // Band: from just inside the previous glyph to the pulled glyph's left stem.
  let band = "";
  let bandX: [number, number] = [0, 1];
  const bandOpacity =
    interpolate(s, [sMax * 0.02, sMax * 0.1], [0, 1], CLAMP) *
    interpolate(frame, [RELEASE, RELEASE + 5], [1, 0], CLAMP);
  if (from.length > 1 && bandOpacity > 0) {
    const prev = lastA - 1;
    const gp = elastic(prev, from.length, A.xs, s, sMax);
    const gl = elastic(lastA, from.length, A.xs, s, sMax);
    const wp = A.ws[prev] * F;
    const wl = A.ws[lastA] * F;
    const xL =
      leftA +
      A.xs[prev] * F +
      gp.dx +
      wp / 2 +
      (wp / 2 - rsb(from[prev]) * F) * gp.sx -
      F * 0.1;
    const xR =
      leftA +
      A.xs[lastA] * F +
      gl.dx +
      wl / 2 -
      (wl / 2 - lsb(from[lastA]) * F) * gl.sx +
      F * 0.05;
    // After the release the band stays thin while it whips back and fades.
    const thinAs = frame >= RELEASE ? Math.max(xR - xL, sMax * 0.8) : xR - xL;
    band = bandPath(xL, xR, cy, xh * gl.sy, F, thinAs);
    bandX = [xL - xh * 0.3, xR];
  }

  const dotIn = interpolate(frame, [SWAP + 10, SWAP + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lastB = to.length - 1;
  const gB = elastic(lastB, to.length, B.xs, s, sMax);
  const dotLeft = leftB + (B.xs[lastB] + B.ws[lastB] + TRACK) * F + gB.dx;

  return (
    <AbsoluteFill style={{ background: t.bg }}>
      {band ? (
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={`${uid}-band`}
              gradientUnits="userSpaceOnUse"
              x1={bandX[0]}
              y1={0}
              x2={bandX[1]}
              y2={0}
            >
              <stop offset="0" stopColor={halo[0]} />
              <stop offset="0.55" stopColor={halo[1]} />
              <stop offset="1" stopColor={halo[2]} />
            </linearGradient>
          </defs>
          <path d={band} fill={`url(#${uid}-band)`} opacity={bandOpacity} />
        </svg>
      ) : null}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: clipTop,
          width: W,
          height: clipH,
          overflow: "hidden",
          fontFamily: sans,
          fontWeight: 500,
        }}
      >
        {glyphs(from, A, leftA, false)}
        {swaps ? glyphs(to, B, leftB, true) : null}
        {period ? (
          <span
            style={{
              position: "absolute",
              left: dotLeft,
              top: baseline - clipTop - BASELINE * F,
              fontSize: F,
              lineHeight: 1,
              color: accent,
              opacity: dotIn,
              transformOrigin: `30% ${BASELINE * F}px`,
              transform: `scale(${0.6 + 0.4 * dotIn})`,
            }}
          >
            .
          </span>
        ) : null}
      </div>
      <div
        style={{
          position: "absolute",
          left: cx - cursorSize * 0.06,
          top: cyCursor - cursorSize * 0.06,
          opacity: cursorOpacity,
        }}
      >
        <Cursor size={cursorSize} pressed={press} />
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  word: {
    type: "text-content",
    default: "tension",
    description: "Word",
  },
  snapWord: {
    type: "text-content",
    default: "release",
    description: "Snap word",
  },
  period: {
    type: "boolean",
    default: true,
    description: "Period",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","snapWord","period","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "tension",
  snapWord: "release",
  period: true,
  speed: 1,
};

type RubberbandWordElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RubberbandWordBase>;

const RubberbandWordInner = forwardRef<
  HTMLDivElement,
  RubberbandWordElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RubberbandWord>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RubberbandWordBase
          {...(componentProps as unknown as ComponentProps<typeof RubberbandWordBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RubberbandWord = Interactive.withSchema({
  Component: RubberbandWordInner,
  componentName: "<RubberbandWord>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadZenKaku } from "@remotion/google-fonts/ZenKakuGothicNew";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const kaku = loadZenKaku("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface RubyPressProps {
  before?: string;
  words?: string[];
  after?: string;
  hold?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const VERMILION = "#E03C31";

const THEMES = {
  dark: { bg: "#111111", ink: "#F5F1EA" },
  light: { bg: "#F5F1EA", ink: "#111111" },
} as const;

const TRACK = -0.02;
const RUBY = 0.4;
const RUBY_GAP = 0.1;

const RISE_AT = 0;
const RISE_LEN = 18;
const RISE_GAP = 3;
const FIRST_GLOSS = 28;
const GLOSS_IN = 12;
const GLOSS_WAIT = 12;
const PRESS = 22;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_PRESS = Easing.bezier(0.6, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  tokens: number[];
  slots: number[];
  slotDesc: number[];
  space: number;
  cap: number;
  base: number;
}

function measure(tokens: string[], slots: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("ruby-press: no 2d context");
  ctx.font = `500 100px "${kaku.fontFamily}"`;
  const w = (s: string) =>
    ctx.measureText(s).width / 100 + TRACK * Math.max(0, s.length - 1);
  const h = ctx.measureText("H");
  const asc = h.fontBoundingBoxAscent / 100;
  const desc = h.fontBoundingBoxDescent / 100;
  return {
    tokens: tokens.map(w),
    slots: slots.map(w),
    slotDesc: slots.map((s) =>
      Math.max(0, ctx.measureText(s).actualBoundingBoxDescent / 100),
    ),
    space: ctx.measureText(" ").width / 100,
    cap: h.actualBoundingBoxAscent / 100,
    base: (1 - (asc + desc)) / 2 + asc,
  };
}

function useMetrics(tokens: string[], slots: string[]) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("ruby-press: measuring"));
  const released = useRef(false);
  const key = JSON.stringify([tokens, slots]);
  useEffect(() => {
    let live = true;
    Promise.all([
      kaku.waitUntilDone(),
      document.fonts.load(`500 100px "${kaku.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [tk, sl] = JSON.parse(key) as [string[], string[]];
        setMetrics(measure(tk, sl));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return metrics;
}

interface Item {
  text: string;
  w: number;
  slot: boolean;
  hug: boolean;
}

function RubyPressBase({
  before = "Subtitles for every market in",
  words = ["a fortnight", "a morning", "one render"],
  after = ".",
  hold = 14,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: RubyPressProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const red = accent ?? VERMILION;

  const slots = words.length ? words : [""];
  const beforeTokens = useMemo(
    () => before.split(/\s+/).filter(Boolean),
    [before],
  );
  const afterTokens = useMemo(
    () => after.split(/\s+/).filter(Boolean),
    [after],
  );
  const tokens = useMemo(
    () => [...beforeTokens, ...afterTokens],
    [beforeTokens, afterTokens],
  );
  const m = useMetrics(tokens, slots);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const swaps = slots.length - 1;
  const swapAt = (i: number) =>
    FIRST_GLOSS + i * (GLOSS_IN + GLOSS_WAIT + PRESS + hold);
  const pressAt = (i: number) => swapAt(i) + GLOSS_IN + GLOSS_WAIT;
  const pressP = (i: number) =>
    interpolate(t, [pressAt(i), pressAt(i) + PRESS], [0, 1], {
      ...CLAMP,
      easing: EASE_PRESS,
    });
  let landed = 0;
  while (landed < swaps && pressP(landed) >= 1) landed++;
  const active = landed < swaps;
  const p = active ? pressP(landed) : 0;
  const slotW = active
    ? m.slots[landed] + (m.slots[landed + 1] - m.slots[landed]) * p
    : m.slots[landed];

  const items: Item[] = [
    ...beforeTokens.map((s, i) => ({
      text: s,
      w: m.tokens[i],
      slot: false,
      hug: false,
    })),
    { text: "", w: 0, slot: true, hug: false },
    ...afterTokens.map((s, i) => ({
      text: s,
      w: m.tokens[beforeTokens.length + i],
      slot: false,
      hug: i === 0 && /^[.,;:!?…’”)]/.test(s),
    })),
  ];

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.07);
  const heroX = portrait ? marginX : W * 0.38;
  const heroW = W - marginX - heroX;
  const leadX = marginX;
  const leadW = portrait ? W * 0.62 : heroX - marginX - W * 0.05;
  const maxSlot = Math.max(...m.slots);
  const afterW = afterTokens.reduce(
    (acc, _s, i) =>
      acc +
      m.tokens[beforeTokens.length + i] +
      (i === 0 && /^[.,;:!?…’”)]/.test(afterTokens[0]) ? 0 : m.space),
    0,
  );

  const F = Math.min(heroW / (maxSlot + afterW), H * (portrait ? 0.1 : 0.22));
  const wrap = (f: number) => {
    const lines: number[][] = [];
    let x = 0;
    beforeTokens.forEach((_s, i) => {
      const w = m.tokens[i] * f;
      if (lines.length === 0 || (x > 0 && x + m.space * f + w > leadW)) {
        lines.push([i]);
        x = w;
      } else {
        lines[lines.length - 1].push(i);
        x += m.space * f + w;
      }
    });
    return lines;
  };
  let f = Math.min(F * 0.34, H * (portrait ? 0.034 : 0.056));
  let lead = wrap(f);
  for (let k = 0; k < 24 && lead.length > 5; k++) {
    f *= 0.93;
    lead = wrap(f);
  }

  const r0 = RUBY * F;
  const leadPitch = f * 1.3;
  const heroBase = portrait ? H * 0.58 : H * 0.64;
  const leadBase0 = portrait
    ? H * 0.1 + m.cap * f
    : heroBase - m.cap * F - (RUBY + RUBY_GAP) * F + m.cap * f;

  const placed: { it: Item; x: number; base: number; sz: number; o: number }[] =
    [];
  lead.forEach((idx, li) => {
    let x = leadX;
    idx.forEach((i, k) => {
      if (k > 0) x += m.space * f;
      placed.push({
        it: items[i],
        x,
        base: leadBase0 + li * leadPitch,
        sz: f,
        o: placed.length,
      });
      x += m.tokens[i] * f;
    });
  });
  const heroItems = items.slice(beforeTokens.length);
  const heroWs = heroItems.map((it) => (it.slot ? slotW : it.w) * F);
  let hx = heroX;
  heroItems.forEach((it, k) => {
    if (k > 0 && !it.hug) hx += m.space * F;
    placed.push({ it, x: hx, base: heroBase, sz: F, o: placed.length + 1 });
    hx += heroWs[k];
  });

  const riseOf = (i: number) =>
    interpolate(
      t,
      [RISE_AT + i * RISE_GAP, RISE_AT + i * RISE_GAP + RISE_LEN],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );

  const textStyle = (size: number): React.CSSProperties => ({
    position: "absolute",
    fontFamily: kaku.fontFamily,
    fontWeight: 500,
    fontSize: size,
    lineHeight: `${size}px`,
    height: size * 1.4,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre",
  });

  const nodes: React.ReactNode[] = [];
  const overlay: React.ReactNode[] = [];
  placed.forEach((pl, k) => {
    const sz = pl.sz;
    const rise = riseOf(pl.o);
    const maskPad = sz * 0.34;
    const lineTop = pl.base - m.cap * sz - maskPad;
    const maskH = m.cap * sz + maskPad * 2;
    const dy = (1 - rise) * maskH;
    if (!pl.it.slot) {
      nodes.push(
        <div
          key={`w${k}`}
          style={{
            position: "absolute",
            left: 0,
            top: lineTop,
            width: W,
            height: maskH,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              ...textStyle(sz),
              left: pl.x,
              top: pl.base - lineTop - m.base * sz + dy,
              color: c.ink,
            }}
          >
            {pl.it.text}
          </div>
        </div>,
      );
      return;
    }

    const slotX = pl.x;
    const oldIdx = landed;
    const oldW = m.slots[oldIdx] * F;
    const glossIdx = oldIdx + 1;
    const hasGloss = active && t >= swapAt(landed);
    let flat = 1;
    if (hasGloss) {
      const size = r0 + (F - r0) * p;
      const topBase = pl.base - m.cap * F - RUBY_GAP * F;
      const gBase = topBase + (pl.base - topBase) * p;
      const gIn = interpolate(
        t,
        [swapAt(landed), swapAt(landed) + GLOSS_IN],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      const gW = m.slots[glossIdx] * size;
      const bottom = gBase + m.slotDesc[glossIdx] * size + F * 0.02;
      flat = Math.max(0, Math.min(1, (pl.base - bottom) / (m.cap * F)));
      overlay.push(
        <div
          key="gloss"
          style={{
            ...textStyle(size),
            left: slotX + (slotW * F - gW) / 2,
            top: gBase - m.base * size + (1 - gIn) * r0 * 0.6,
            opacity: gIn,
            color: red,
          }}
        >
          {slots[glossIdx]}
        </div>,
      );
    }
    if (flat > 0.001) {
      nodes.push(
        <div
          key="slot"
          style={{
            position: "absolute",
            left: 0,
            top: lineTop,
            width: W,
            height: maskH,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              ...textStyle(F),
              left: slotX + (slotW * F - oldW) / 2,
              top: pl.base - lineTop - m.base * F + dy,
              transform: `scaleY(${flat.toFixed(4)})`,
              transformOrigin: `50% ${(m.base * F).toFixed(2)}px`,
              opacity: interpolate(flat, [0, 0.12], [0, 1], CLAMP),
              color: oldIdx === 0 ? c.ink : red,
            }}
          >
            {slots[oldIdx]}
          </div>
        </div>,
      );
    }
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {nodes}
      {overlay}
    </AbsoluteFill>
  );
}

