const THEMES = {
  dark: {
    bg: "#0A0A0B",
    stage: "rgba(255,255,255,0.05)",
    fg: "#F3F2EF",
    muted: "#85848A",
    faint: "#46464C",
    major: "rgba(243,242,239,0.7)",
    minor: "rgba(243,242,239,0.26)",
    future: 0.4,
    grain: 0.065,
    hero: (a: number) =>
      `linear-gradient(${172 + a}deg, #fbeee4 0%, #f3d6c0 22%, #b9a6ff 58%, #8a7bff 78%, #5a5ef0 100%)`,
    glow: [
      "color-mix(in oklab, #8a7bff 16%, transparent)",
      "color-mix(in oklab, #3b3fd8 22%, transparent)",
    ],
  },
  light: {
    bg: "#F5F4F0",
    stage: "rgba(255,255,255,0.9)",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#B9B6AE",
    major: "rgba(18,18,20,0.66)",
    minor: "rgba(18,18,20,0.24)",
    future: 0.45,
    grain: 0.045,
    hero: (a: number) =>
      `linear-gradient(${155 + a}deg, #7a5cff 0%, #b04cd9 30%, #ff3d9a 62%, #ff8a3d 100%)`,
    glow: [
      "color-mix(in oklab, #ff8a3d 10%, transparent)",
      "color-mix(in oklab, #7a5cff 12%, transparent)",
    ],
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

function decimalsOf(step: number) {
  const s = String(step);
  const i = s.indexOf(".");
  return i < 0 ? 0 : Math.min(4, s.length - i - 1);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={31}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Ticks({
  pos,
  steps,
  gap,
  width,
  u,
  h,
  p,
  accent,
  text,
  centerLit,
  heroOut,
  labelSize,
}: {
  pos: number;
  steps: number;
  gap: number;
  width: number;
  u: number;
  h: number;
  p: Palette;
  accent: string;
  text: (i: number) => string;
  centerLit: number;
  heroOut: number;
  labelSize: number;
}) {
  const span = width / 2 / gap + 1;
  const first = Math.floor((pos - span) * SUBDIV);
  const last = Math.ceil((pos + span) * SUBDIV);
  const lines: React.ReactNode[] = [];
  const labels: React.ReactNode[] = [];
  for (let k = first; k <= last; k++) {
    const x = width / 2 + (k / SUBDIV - pos) * gap;
    const major = k % SUBDIV === 0;
    const mid = !major && k % (SUBDIV / 2) === 0;
    const len = h * (major ? 0.075 : mid ? 0.048 : 0.028);
    const future = k / SUBDIV > steps + 1e-6 ? p.future : 1;
    const isHero = k === steps * SUBDIV;
    const lit = isHero ? centerLit : 0;
    lines.push(
      <line
        key={k}
        x1={x}
        x2={x}
        y1={0}
        y2={-len * (1 + lit * 0.35)}
        stroke={lit > 0.5 ? accent : major ? p.major : p.minor}
        strokeWidth={(major ? 1.75 : 1.1) * u * (1 + lit * 0.4)}
        opacity={future}
      />,
    );
    if (major) {
      const i = k / SUBDIV;
      labels.push(
        <div
          key={`t${k}`}
          style={{
            position: "absolute",
            left: x - gap / 2,
            width: gap,
            top: -h * 0.098 - labelSize,
            textAlign: "center",
            fontFamily: sans,
            fontWeight: 500,
            fontSize: labelSize,
            lineHeight: 1,
            letterSpacing: "-0.005em",
            fontVariantNumeric: "tabular-nums",
            color: isHero ? p.fg : p.muted,
            opacity: future * (isHero ? 1 - heroOut : 1),
          }}
        >
          {text(i)}
        </div>,
      );
    }
  }
  return (
    <>
      <svg
        width={width}
        height={h * 0.12}
        viewBox={`0 ${-h * 0.12} ${width} ${h * 0.12}`}
        style={{
          position: "absolute",
          left: 0,
          top: -h * 0.12,
          overflow: "visible",
        }}
        aria-hidden
      >
        {lines}
      </svg>
      {labels}
    </>
  );
}

export function RulerScrub({
  from = 2012,
  to = 2026,
  step = 1,
  format = "{value}",
  label = "The year launch videos became code",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: RulerScrubProps) {
  const t = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const u = height / 720;
  const p: Palette = THEMES[theme];
  const inc = step > 0 ? step : 1;
  const steps = Math.max(1, Math.round((to - from) / inc));
  const dec = decimalsOf(inc);
  const fmt = (v: number) => {
    const n = v.toFixed(dec);
    return typeof format === "function"
      ? format(Number(n))
      : format.replace("{value}", n);
  };
  const text = (i: number) => fmt(from + i * inc);

  const gap = Math.max(width * 0.115, 96 * u);
  const scrubAt = (f: number) => {
    const x = Math.min(1, Math.max(0, f / SCRUB_END));
    const main = (1 - (1 - x) ** 3) * 0.93 + x * 0.07;
    if (f <= SCRUB_END) return steps * main;
    const dt = f - SCRUB_END;
    const v0 = (0.07 * steps) / SCRUB_END;
    return steps + (v0 / 0.9) * Math.sin(dt * 0.9) * Math.exp(-dt * 0.5);
  };
  const pos = scrubAt(t);
  const vel = (scrubAt(t) - scrubAt(t - 1)) * gap;
  const ghost = interpolate(Math.abs(vel), [8 * u, 60 * u], [0, 1], CLAMP);

  const lift = interpolate(t, [SCRUB_END + 6, SCRUB_END + 38], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rulerY = interpolate(lift, [0, 1], [height * 0.56, height * 0.68]);
  const centerLit = interpolate(
    t,
    [SCRUB_END - 4, SCRUB_END + 2],
    [0, 1],
    CLAMP,
  );
  const heroOut = interpolate(lift, [0, 0.06], [0, 1], CLAMP);
  const enter = interpolate(t, [0, 10], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const flash = interpolate(
    t,
    [SCRUB_END - 2, SCRUB_END + 1, SCRUB_END + 14],
    [0, 1, 0],
    CLAMP,
  );
  const blur = Math.min(8 * u, Math.max(0, Math.abs(vel) - 6 * u) * 0.11);
  const blurId = `b${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const labelSize = 21 * u;
  const heroSize = Math.min(height * 0.34, width * 0.2);
  const heroScale0 = labelSize / heroSize;
  const heroStartY = rulerY - height * 0.098 - labelSize * 0.5;
  const heroEndY = height * 0.34;
  const heroY = interpolate(lift, [0, 1], [heroStartY, heroEndY]);
  const heroScale =
    interpolate(lift, [0, 1], [heroScale0, 1]) *
    interpolate(t, [SCRUB_END + 38, SCRUB_END + 110], [1, 1.02], CLAMP);
  const heroWeight = interpolate(lift, [0, 1], [450, 500]);
  const sheen = interpolate(t, [SCRUB_END, SCRUB_END + 110], [-4, 4], CLAMP);

  const markTop = -height * 0.075 * (1 + centerLit * 0.35) - 6 * u;
  const markBottom = height * 0.034;

  const labelIn = interpolate(t, [SCRUB_END + 30, SCRUB_END + 54], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const ghosts = [0.5, 1];
  const fade =
    "linear-gradient(90deg, transparent 0%, #000 22%, #000 78%, transparent 100%)";
  const tickProps = {
    pos,
    steps,
    gap,
    width,
    u,
    h: height,
    p,
    accent,
    text,
    labelSize,
  };

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: [
            `radial-gradient(ellipse 42% 46% at ${46 + sheen}% ${36 - 6 * (1 - lift)}%, ${p.glow[0]}, transparent 72%)`,
            `radial-gradient(ellipse 70% 50% at 50% 100%, ${p.glow[1]}, transparent 72%)`,
            `radial-gradient(ellipse 60% 60% at 50% 48%, ${p.stage}, transparent 75%)`,
          ].join(", "),
        }}
      />
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <filter id={blurId} x="-10%" y="-10%" width="120%" height="120%">
          <feGaussianBlur stdDeviation={`${blur} 0`} />
        </filter>
      </svg>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: rulerY - height * 0.25,
          width,
          height: height * 0.3,
          opacity: enter,
          maskImage: fade,
          WebkitMaskImage: fade,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: height * 0.25,
            width,
            height: Math.max(1, u),
            background: p.minor,
          }}
        />
        <div
          style={{
            position: "absolute",
            inset: 0,
            filter: blur > 0.4 ? `url(#${blurId})` : undefined,
          }}
        >
          <div style={{ position: "absolute", left: 0, top: height * 0.25 }}>
            {ghosts.map((g) =>
              ghost > 0.01 ? (
                <div
                  key={g}
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    opacity: ghost * 0.22 * (1.25 - g),
                    transform: `translateX(${vel * g * 0.7}px)`,
                  }}
                >
                  <Ticks {...tickProps} centerLit={0} heroOut={0} />
                </div>
              ) : null,
            )}
            <div style={{ position: "absolute", left: 0, top: 0 }}>
              <Ticks {...tickProps} centerLit={centerLit} heroOut={heroOut} />
            </div>
          </div>
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: width / 2 - u,
          top: rulerY + markTop,
          width: 2 * u,
          height: markBottom - markTop,
          background: accent,
          borderRadius: u,
          opacity: enter,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: width / 2 - 4.5 * u,
          top: rulerY + markBottom - 4.5 * u,
          width: 9 * u,
          height: 9 * u,
          borderRadius: 9 * u,
          background: accent,
          opacity: enter,
          boxShadow: `0 0 0 ${flash * 7 * u}px ${accent}2E`,
        }}
      />

      <div
        style={{
          position: "absolute",
          left: 0,
          width,
          top: heroY,
          height: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: heroOut,
        }}
      >
        <div
          style={{
            fontFamily: display,
            fontWeight: heroWeight,
            fontSize: heroSize,
            lineHeight: 1,
            letterSpacing: `${interpolate(lift, [0, 1], [-0.005, -0.05])}em`,
            fontVariantNumeric: "tabular-nums",
            color: "transparent",
            backgroundImage: p.hero(sheen),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            padding: "0.08em 0.06em",
            whiteSpace: "nowrap",
            transform: `scale(${heroScale})`,
          }}
        >
          {text(steps)}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: 0,
          width,
          top: height * 0.83,
          display: "flex",
          justifyContent: "center",
          fontFamily: sans,
          fontWeight: 400,
          fontSize: 28 * u,
          letterSpacing: "-0.015em",
          color: p.fg,
          opacity: labelIn,
          transform: `translateY(${(1 - labelIn) * 14 * u}px)`,
        }}
      >
        {label}
      </div>
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/DMSans";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const dmSans = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface RunOnProps {
  text?: string;
  promise?: string;
  highlight?: string;
  joiners?: string[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2E3440", ink: "#FFFFFF", dim: "#FFFFFF8C", accent: "#FFB020" },
  light: {
    bg: "#F1F2F4",
    ink: "#2E3440",
    dim: "#2E34408C",
    accent: "#B86E00",
  },
} as const;

const WGHT = 500;
const TRACK = -0.035;
const PROBE = 200;
const BASE = 200;
const LEAD = 1.08;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const START = 6;
const FIRST_GAP = 9;
const LAST_GAP = 2.6;
const REVEAL = 6;
const STOP_GAP = 7;
const SLAM = 5;
const HOLD = 16;
const DRAIN = 16;
const PROMISE_LAG = 5;
const SCROLL = 10;
const PROMISE_STAGGER = 4;
const PROMISE_IN = 16;

interface Word {
  text: string;
  start: number;
  x: number;
  w: number;
}

interface Metrics {
  words: Word[];
  promise: Word[];
  promiseW: number;
  dotW: number;
}

function layoutWords(s: string, em: (x: string) => number) {
  const out: Word[] = [];
  const re = /\S+/g;
  for (let m = re.exec(s); m; m = re.exec(s)) {
    out.push({
      text: m[0],
      start: m.index,
      x: em(s.slice(0, m.index)),
      w: em(m[0]),
    });
  }
  return out;
}

function measure(text: string, promise: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("run-on: no 2d context");
  ctx.font = `${WGHT} ${PROBE}px "${dmSans.fontFamily}"`;
  const em = (x: string) =>
    ctx.measureText(x).width / PROBE + TRACK * Array.from(x).length;
  const body = promise.replace(/\.$/, "");
  return {
    words: layoutWords(text, em),
    promise: layoutWords(body, em),
    promiseW: em(body),
    dotW: em("."),
  };
}

function useMetrics(text: string, promise: string) {
  const key = `${text}\u0001${promise}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("run-on: measuring"));
  const released = useRef(false);
  const src = useRef({ text, promise });
  src.current = { text, promise };
  useEffect(() => {
    let live = true;
    Promise.all([
      dmSans.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${dmSans.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(src.current.text, src.current.promise) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function RunOnBase({
  text = "Open last year’s project and relink the fonts and nudge every keyframe and render and spot a typo and render it all again",
  promise = "Or change one line.",
  highlight = "one line",
  joiners = ["and", "then"],
  accent,
  background,
  speed = 1,
  theme = "dark",
}: RunOnProps) {
  const frame = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const k = Math.min(1, durationInFrames / BASE);
  const t = (frame * speed) / k;
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const body = text.trim().replace(/[.!?…]+$/, "");
  const said = promise.trim();
  const m = useMetrics(body, said);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const F = portrait ? W * 0.105 : H * 0.135;
  const pitch = F * LEAD;
  const marginX = W * (portrait ? 0.08 : 0.07);
  const measureW = (W - marginX * 2) / F;
  const top0 = H * (portrait ? 0.2 : 0.14);
  const floor = H * (portrait ? 0.62 : 0.86);
  const n = m.words.length;

  const placed: { line: number; x: number }[] = [];
  let line = 0;
  let lineStart = 0;
  m.words.forEach((w, i) => {
    if (i > 0 && w.x + w.w - lineStart > measureW) {
      line += 1;
      lineStart = w.x;
    }
    placed.push({ line, x: w.x - lineStart });
  });

  const arrive: number[] = [];
  let acc = START;
  for (let i = 0; i < n; i++) {
    arrive.push(acc);
    const p = n > 1 ? i / (n - 1) : 1;
    acc += FIRST_GAP + (LAST_GAP - FIRST_GAP) * p ** 0.6;
  }
  const stopAt = arrive[n - 1] + STOP_GAP;
  const drainAt = stopAt + SLAM + HOLD;
  const promiseAt = drainAt + DRAIN - PROMISE_LAG;

  const need = (ln: number) => Math.max(0, top0 + (ln + 1) * pitch - floor);
  let scroll = 0;
  for (let i = 0; i < n; i++) {
    if (t < arrive[i]) break;
    const from = i === 0 ? 0 : need(placed[i - 1].line);
    const to = need(placed[i].line);
    if (to !== from) {
      scroll =
        from +
        (to - from) *
          interpolate(t, [arrive[i], arrive[i] + SCROLL], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
    } else {
      scroll = to;
    }
  }
  const drain = interpolate(t, [drainAt, drainAt + DRAIN], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.55, 0, 1, 0.45),
  });
  const wallY = -scroll - drain * H * 1.05;

  const Fp = Math.min(
    portrait ? W * 0.16 : H * 0.22,
    (W - marginX * 2) / (m.promiseW + m.dotW),
  );
  const promiseBase = H * (portrait ? 0.62 : 0.66);
  const joinSet = new Set(joiners.map((j) => j.toLowerCase()));

  const hiStart = highlight ? said.lastIndexOf(highlight) : -1;
  const hiEnd = hiStart >= 0 ? hiStart + highlight.length : -1;

  const glyph = (
    key: string,
    text: string,
    x: number,
    baseY: number,
    size: number,
    dy: number,
    opacity: number,
    color: string,
  ) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        height: size * 1.2,
        lineHeight: `${size * 1.2}px`,
        whiteSpace: "pre",
        fontFamily: dmSans.fontFamily,
        fontWeight: WGHT,
        fontSize: size,
        letterSpacing: `${TRACK}em`,
        fontKerning: "normal",
        color,
        opacity,
        transform: `translate(${x.toFixed(2)}px, ${(baseY - size * 0.93 + dy).toFixed(2)}px)`,
      }}
    >
      {text}
    </div>
  );

  const baseOf = (ln: number) => top0 + ln * pitch + F * 0.93;
  const nodes: React.ReactNode[] = [];
  if (drain < 1) {
    m.words.forEach((w, i) => {
      const r = interpolate(t, [arrive[i], arrive[i] + REVEAL], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      if (r <= 0) return;
      const y = baseOf(placed[i].line) + wallY;
      if (y < -F || y > H + F * 2) return;
      const join = joinSet.has(w.text.toLowerCase());
      nodes.push(
        glyph(
          `w${i}`,
          w.text,
          marginX + placed[i].x * F,
          y,
          F,
          F * 0.3 * (1 - r),
          r * (1 - drain * 0.5),
          join ? c.dim : c.ink,
        ),
      );
    });
  }

  const slam = interpolate(t, [stopAt, stopAt + SLAM], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const dotTravel = interpolate(t, [drainAt, drainAt + DRAIN + 6], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.65, 0, 0.35, 1),
  });
  if (slam > 0) {
    const last = n - 1;
    const stopX = marginX + (placed[last].x + m.words[last].w) * F;
    const stopY = baseOf(placed[last].line) - scroll;
    const restX = marginX + m.promiseW * Fp;
    const size = F + (Fp - F) * dotTravel;
    nodes.push(
      glyph(
        "stop",
        ".",
        stopX + (restX - stopX) * dotTravel,
        stopY + (promiseBase - stopY) * dotTravel,
        size,
        -F * 0.7 * (1 - slam),
        Math.min(1, slam * 1.6),
        hi,
      ),
    );
  }

  m.promise.forEach((w, i) => {
    const at = promiseAt + i * PROMISE_STAGGER;
    const r = interpolate(t, [at, at + PROMISE_IN], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    if (r <= 0) return;
    const lit = interpolate(
      t,
      [promiseAt + PROMISE_IN + 4, promiseAt + PROMISE_IN + 14],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const inHi =
      hiStart >= 0 && w.start < hiEnd && w.start + w.text.length > hiStart;
    const color = inHi
      ? `color-mix(in oklab, ${hi} ${(lit * 100).toFixed(1)}%, ${c.ink})`
      : c.ink;
    nodes.push(
      glyph(
        `p${i}`,
        w.text,
        marginX + w.x * Fp,
        promiseBase,
        Fp,
        Fp * 0.4 * (1 - r),
        r,
        color,
      ),
    );
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
