type ScanFixElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ScanFixBase>;

const ScanFixInner = forwardRef<
  HTMLDivElement,
  ScanFixElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ScanFix>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ScanFixBase
          {...(componentProps as unknown as ComponentProps<typeof ScanFixBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ScanFix = Interactive.withSchema({
  Component: ScanFixInner,
  componentName: "<ScanFix>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

