function widthEm(text: string, track: number) {
  let w = 0;
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    const adv = code >= 32 && code < 127 ? SPACE_500[code - 32] : 600;
    w += adv / 1000 + track;
  }
  return Math.max(w, 0.5);
}

