const ELEMENT_PROP_KEYS = new Set(["theme","accent","before","cut","after","replacement","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  before: "Launch ",
  cut: "next month",
  after: ".",
  replacement: "today",
  speed: 1,
};

type ScissorsCutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ScissorsCutBase>;

const ScissorsCutInner = forwardRef<
  HTMLDivElement,
  ScissorsCutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ScissorsCut>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ScissorsCutBase
          {...(componentProps as unknown as ComponentProps<typeof ScissorsCutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ScissorsCut = Interactive.withSchema({
  Component: ScissorsCutInner,
  componentName: "<ScissorsCut>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

