const RED = "#E60012";

const THEMES = {
  dark: { bg: "#000000", ink: "#FFFFFF", soft: "rgba(255,255,255,0.64)" },
  light: { bg: "#FFFFFF", ink: "#000000", soft: "rgba(0,0,0,0.6)" },
} as const;

const NUM_TRACK = -0.03;
const LOGO_CAP = 0.76;
const SUP = 0.52;

const NAME_AT = 0;
const SUP_AT = 10;
const DROP_AT = 42;
const DROP_LEN = 10;
const GROW_AT = 50;
const SETTLE_LEN = 26;
const TAG_AT = 82;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_DROP = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  name: number;
  nameBase: number;
  num: number;
  numCap: number;
  numBase: number;
  tagline: number;
}

const isRemocn = (name: string) => name.trim().toLowerCase() === "remocn";

const baseOf = (asc: number, desc: number) => (1 - (asc + desc)) / 2 + asc;

function measure(name: string, numeral: string, tagline: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) throw new Error("sequel-numeral: no 2d context");
  ctx.font = `600 100px "${manrope.fontFamily}"`;
  const nameText = isRemocn(name) ? "emocn" : name;
  const nameRaw =
    ctx.measureText(nameText).width / 100 - 0.025 * nameText.length;
  const nameW = isRemocn(name)
    ? nameRaw + 0.04 + (LOGO_CAP * 124.06) / 134.26
    : nameRaw;
  const nm = ctx.measureText("e");
  const nameBase = baseOf(
    nm.fontBoundingBoxAscent / 100,
    nm.fontBoundingBoxDescent / 100,
  );

  ctx.font = `500 100px "${rubik.fontFamily}"`;
  const nmText = numeral || "2";
  const fm = ctx.measureText(nmText);
  const num =
    fm.width / 100 + NUM_TRACK * Math.max(0, Array.from(nmText).length - 1);
  const numCap = fm.actualBoundingBoxAscent / 100;
  const numBase = baseOf(
    fm.fontBoundingBoxAscent / 100,
    fm.fontBoundingBoxDescent / 100,
  );

  ctx.font = `400 100px "${rubik.fontFamily}"`;
  const tagW = tagline ? ctx.measureText(tagline).width / 100 : 0;
  return { name: nameW, nameBase, num, numCap, numBase, tagline: tagW };
}

function useMetrics(name: string, numeral: string, tagline: string) {
  const key = [name, numeral, tagline].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("sequel-numeral: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [n, nu, tg] = key.split("\u0001");
    Promise.all([
      rubik.waitUntilDone(),
      manrope.waitUntilDone(),
      document.fonts.load(`500 100px "${rubik.fontFamily}"`),
      document.fonts.load(`400 100px "${rubik.fontFamily}"`),
      document.fonts.load(`600 100px "${manrope.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(n, nu, tg) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

export function SequelNumeral({
  name = "remocn",
  numeral = "2",
  tagline = "Part two. Out now.",
  accent = RED,
  background,
  speed = 1,
  theme = "dark",
}: SequelNumeralProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const m = useMetrics(name, numeral, tagline);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const margin = Math.min(W, H) * (portrait ? 0.07 : 0.075);

  const L0 = Math.min(
    H * (portrait ? 0.075 : 0.16),
    (W * (portrait ? 0.62 : 0.5)) / m.name,
  );
  const L1 = L0 * (portrait ? 0.62 : 0.5);
  const supS0 = (SUP * LOGO_CAP * L0) / m.numCap;
  const gapSup = 0.06 * L0;

  const capTarget = H * (portrait ? 0.46 : 0.8);
  const room = W - 2 * margin - m.name * L1;
  const S1 = Math.min(capTarget / m.numCap, room / (m.num + 0.08));
  const gap1 = 0.08 * S1;

  const nameP = interpolate(t, [NAME_AT, NAME_AT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const supP = interpolate(t, [SUP_AT, SUP_AT + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const drop = interpolate(t, [DROP_AT, DROP_AT + DROP_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_DROP,
  });
  const grow = spring({
    frame: t - GROW_AT,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.9 },
  });
  const settle = spring({
    frame: t - GROW_AT,
    fps,
    config: { damping: 200, stiffness: 120, mass: 0.9 },
    durationInFrames: SETTLE_LEN,
  });
  const tagP = interpolate(t, [TAG_AT, TAG_AT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const L = L0 + (L1 - L0) * settle;
  const cap = LOGO_CAP * L;
  const supS = (SUP * cap) / m.numCap;
  const sizeFree = supS + (S1 - supS) * grow;
  const gap = gapSup + (gap1 - gapSup) * Math.min(1, Math.max(0, grow));

  const lock0 = m.name * L0 + gapSup + m.num * supS0;
  const nameLeft0 = (W - lock0) / 2;
  const nameLeft1 = W - margin - m.num * S1 - gap1 - m.name * L1;
  const nameLeft = nameLeft0 + (nameLeft1 - nameLeft0) * settle;
  const numLeft = nameLeft + m.name * L + gap;

  const base0 = H / 2 + (LOGO_CAP * L0) / 2;
  const base1 = (H + m.numCap * S1) / 2;
  const baseY = base0 + (base1 - base0) * settle;

  const supBase = baseY - cap + m.numCap * sizeFree;
  const numBaseY = supBase + (baseY - supBase) * drop;
  const size = Math.min(sizeFree, (numBaseY - margin) / m.numCap);

  const nameRise = (1 - nameP) * L * 1.2;
  const tagFs = Math.min(
    H * (portrait ? 0.022 : 0.04),
    (W * 0.6) / Math.max(0.1, m.tagline),
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: nameLeft - L * 0.1,
          top: baseY - L * 1.1,
          width: m.name * L + L * 0.3,
          height: L * 1.4,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: L * 0.1,
            top: L * 1.1 - m.nameBase * L + nameRise,
            height: L,
          }}
        >
          {isRemocn(name) ? (
            <RemocnLogo fontSize={L} color={c.ink} />
          ) : (
            <div
              style={{
                fontFamily: manrope.fontFamily,
                fontWeight: 600,
                fontSize: L,
                lineHeight: 1,
                letterSpacing: "-0.025em",
                whiteSpace: "pre",
                color: c.ink,
              }}
            >
              {name}
            </div>
          )}
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: numLeft,
          top: numBaseY - m.numBase * size,
          height: size,
          lineHeight: `${size}px`,
          whiteSpace: "pre",
          fontFamily: rubik.fontFamily,
          fontWeight: 500,
          fontSize: size,
          letterSpacing: `${NUM_TRACK}em`,
          color: accent,
          opacity: supP,
          transform: `translateY(${((1 - supP) * cap * 0.4).toFixed(2)}px)`,
        }}
      >
        {numeral}
      </div>

      {tagline ? (
        <div
          style={{
            position: "absolute",
            left: margin,
            top: margin,
            height: tagFs * 1.3,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              fontFamily: rubik.fontFamily,
              fontWeight: 400,
              fontSize: tagFs,
              lineHeight: `${tagFs * 1.3}px`,
              letterSpacing: "-0.01em",
              whiteSpace: "pre",
              color: c.soft,
              transform: `translateY(${((1 - tagP) * tagFs * 1.4).toFixed(2)}px)`,
            }}
          >
            {tagline}
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

import { loadVariableFont } from "@remotion/google-fonts/BricolageGrotesque";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const gothic = loadVariableFont("normal", { subsets: ["latin"] });

interface SerifRiseProps {
  lines?: string[];
  highlight?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#16130F",
    ink: "#F2EFE8",
    accent: "#E5342A",
    rule: "rgba(242,239,232,0.2)",
    grain: 0.05,
  },
  light: {
    bg: "#F2EFE8",
    ink: "#111111",
    accent: "#E5342A",
    rule: "rgba(17,17,17,0.18)",
    grain: 0.035,
  },
} as const;

const W_START = 500;
const W_END = 380;
const WGHT = W_END;
const CTRS_MAX = 1;
const TRACK = -0.022;
const LINE = 1.02;
const HAIR = 0.03;
const REACH = 0.62;

const RISE_LEN = 18;
const RISE_GAP = 1.5;
const SWEEP_AT = 32;
const SWEEP_GAP = 2;
const SWEEP_SPAN = 44;
const SWEEP_LEN = 16;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_CTRS = Easing.bezier(0.33, 0, 0.2, 1);
const EASE_SERIF = Easing.bezier(0.3, 1.45, 0.5, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const fvs = (k: number) =>
  `"wght" ${(W_START + (W_END - W_START) * k).toFixed(1)}, "opsz" 96, "wdth" 100`;

type Side = "none" | "both" | "left" | "right";
interface Stem {
  cx: number;
  w: number;
  foot: Side;
  head: Side;
  top: number;
}
interface Metrics {
  adv: Record<string, [number, number]>;
  kern: Record<string, [number, number]>;
  stems: Record<string, Stem[]>;
  cap: number;
  baseline: number;
}

const RASTER = 300;

function runsAt(
  data: Uint8ClampedArray,
  W: number,
  y: number,
): [number, number][] {
  const out: [number, number][] = [];
  let start = -1;
  for (let x = 0; x < W; x++) {
    const on = data[(y * W + x) * 4 + 3] > 110;
    if (on && start < 0) start = x;
    if (!on && start >= 0) {
      out.push([start, x]);
      start = -1;
    }
  }
  if (start >= 0) out.push([start, W]);
  return out;
}

function findStems(
  ctx: CanvasRenderingContext2D,
  ch: string,
  xh: number,
  cap: number,
  asc: number,
): Stem[] {
  const S = RASTER;
  const pad = Math.round(S * 0.3);
  const advPx = ctx.measureText(ch).width;
  const W = Math.ceil(advPx + pad * 2);
  const H = Math.ceil(S * 1.6);
  const base = Math.round(S * 1.15);
  ctx.canvas.width = W;
  ctx.canvas.height = H;
  ctx.font = `${WGHT} ${S}px "${gothic.fontFamily}"`;
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#000";
  ctx.fillText(ch, pad, base);
  const data = ctx.getImageData(0, 0, W, H).data;
  const alpha = (x: number, y: number) =>
    x < 0 || x >= W || y < 0 || y >= H ? 0 : data[(y * W + x) * 4 + 3];
  const upper = ch !== ch.toLowerCase() || /[0-9]/.test(ch);
  const near = (a: number, b: number, tol: number) => Math.abs(a - b) <= tol;
  const y1 = base - 3;
  const y2 = base - Math.round(xh * S * 0.22);
  const y3 = base - Math.round(xh * S * 0.48);
  const r1s = runsAt(data, W, y1);
  const r3s = runsAt(data, W, y3);
  const stems: Stem[] = [];
  for (const [a, b] of runsAt(data, W, y2)) {
    const w = b - a;
    const cx = (a + b) / 2;
    if (w > S * 0.2 || w < S * 0.02) continue;
    const r3 = r3s.find(([p, q]) => near((p + q) / 2, cx, w * 0.2));
    if (!r3 || !near(r3[1] - r3[0], w, w * 0.3)) continue;
    let foot: Side = "none";
    const r1 = r1s.find(([p, q]) => p <= cx && q >= cx);
    if (r1 && alpha(Math.round(cx), base + 5) < 40) {
      const w1 = r1[1] - r1[0];
      if (near(w1, w, w * 0.3)) foot = "both";
      else if (near(r1[0], a, w * 0.25)) foot = "left";
      else if (near(r1[1], b, w * 0.25)) foot = "right";
    }
    let y = y2;
    while (y > 1 && alpha(Math.round(cx), y - 1) > 110) y--;
    const top = (base - y) / S;
    let head: Side = "none";
    const atHeight =
      near(top, xh, 0.05) || near(top, cap, 0.05) || near(top, asc, 0.06);
    if (atHeight && !"tf".includes(ch)) {
      const rt = runsAt(data, W, y + 3).find(([p, q]) => p <= cx && q >= cx);
      if (rt) {
        const wt = rt[1] - rt[0];
        if (near(wt, w, w * 0.35)) head = upper ? "both" : "left";
        else if (near(rt[0], a, w * 0.25)) head = "left";
        else if (near(rt[1], b, w * 0.25) && upper) head = "right";
      }
    }
    if (foot === "none" && head === "none") continue;
    stems.push({ cx: (cx - pad) / S, w: w / S, foot, head, top });
  }
  return stems;
}

function measure(lines: string[]): Metrics {
  const probe = document.createElement("span");
  Object.assign(probe.style, {
    position: "absolute",
    left: "-99999px",
    top: "0",
    visibility: "hidden",
    whiteSpace: "pre",
    fontFamily: `"${gothic.fontFamily}"`,
    fontStyle: "normal",
    fontSize: "100px",
    lineHeight: "1",
  });
  document.body.appendChild(probe);
  const widthOf = (s: string, ctrs: number) => {
    probe.style.fontVariationSettings = fvs(ctrs);
    probe.textContent = s;
    return probe.getBoundingClientRect().width / 100;
  };
  const adv: Metrics["adv"] = {};
  const kern: Metrics["kern"] = {};
  for (const line of lines) {
    const chars = Array.from(line);
    chars.forEach((ch, i) => {
      if (!adv[ch]) adv[ch] = [widthOf(ch, 0), widthOf(ch, CTRS_MAX)];
      const next = chars[i + 1];
      if (next) {
        const pair = ch + next;
        if (!kern[pair]) {
          kern[pair] = [0, CTRS_MAX].map((c) => {
            const k = widthOf(pair, c) - widthOf(ch, c) - widthOf(next, c);
            return Math.abs(k) < 0.002 ? 0 : k;
          }) as [number, number];
        }
      }
    });
  }
  probe.remove();

  const ctx = document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true });
  const stems: Metrics["stems"] = {};
  let cap = 0.7;
  let baseline = 0.8;
  if (ctx) {
    ctx.font = `${WGHT} 100px "${gothic.fontFamily}"`;
    const fH = ctx.measureText("H");
    cap = fH.actualBoundingBoxAscent / 100;
    const xh = ctx.measureText("x").actualBoundingBoxAscent / 100;
    const asc = ctx.measureText("l").actualBoundingBoxAscent / 100;
    const fa = fH.fontBoundingBoxAscent / 100;
    const fd = fH.fontBoundingBoxDescent / 100;
    baseline = (1 - (fa + fd)) / 2 + fa;
    for (const ch of Object.keys(adv)) {
      stems[ch] = ch.trim() ? findStems(ctx, ch, xh, cap, asc) : [];
    }
  }
  return { adv, kern, stems, cap, baseline };
}

function useMetrics(lines: string[]) {
  const key = lines.join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("serif-rise: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      gothic.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${gothic.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `sr${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={7}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function SerifRiseBase({
  lines = ["From rough cut", "to final cut."],
  highlight = "final cut.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: SerifRiseProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const rows = useMemo(
    () => (lines.length > 0 ? lines : ["final cut."]).map((l) => l || " "),
    [lines],
  );
  const m = useMetrics(rows);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
  const lineWidth = (s: string, k: number) => {
    const chars = Array.from(s);
    return chars.reduce((acc, ch, i) => {
      const a = m.adv[ch];
      const kn = i < chars.length - 1 ? m.kern[ch + chars[i + 1]] : null;
      return (
        acc +
        lerp(a[0], a[1], k) +
        (kn ? lerp(kn[0], kn[1], k) : 0) +
        (i < chars.length - 1 ? TRACK : 0)
      );
    }, 0);
  };
  const widest = Math.max(
    ...rows.map((r) => Math.max(lineWidth(r, 0), lineWidth(r, 1))),
  );

  const portrait = H > W * 1.1;
  const edge = W * (portrait ? 0.05 : 0.035);
  const F = Math.min(
    (W - edge * 2) / widest,
    (H * (portrait ? 0.5 : 0.78)) / (rows.length * LINE),
  );
  const lineH = F * LINE;
  const capPx = m.cap * F;
  const blockH = (rows.length - 1) * lineH + capPx;
  const firstBase = (H - blockH) / 2 + capPx;
  const ruleH = Math.max(1.5, F * 0.008);

  const hlRanges = rows.map((r) => {
    if (!highlight) return null;
    const at = r.indexOf(highlight);
    return at >= 0 ? [at, at + Array.from(highlight).length] : null;
  });

  const ruleNodes: React.ReactNode[] = [];
  const glyphNodes: React.ReactNode[] = [];
  const serifNodes: React.ReactNode[] = [];
  const total = rows.reduce((a, r) => a + Array.from(r).length, 0);
  const gap = Math.min(SWEEP_GAP, SWEEP_SPAN / Math.max(1, total - 1));
  let gi = 0;
  rows.forEach((row, r) => {
    const chars = Array.from(row);
    const baseY = firstBase + r * lineH;
    const ruleP = interpolate(t, [r * 4, r * 4 + 22], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    ruleNodes.push(
      <div
        key={`rule${r}`}
        style={{
          position: "absolute",
          left: 0,
          top: baseY + ruleH * 0.5,
          width: W,
          height: ruleH,
          background: c.rule,
          transformOrigin: "0% 50%",
          transform: `scaleX(${ruleP.toFixed(4)})`,
        }}
      />,
    );
    const progress = chars.map((ch, i) => {
      const idx = gi + i;
      const p = interpolate(
        t,
        [SWEEP_AT + idx * gap, SWEEP_AT + idx * gap + SWEEP_LEN],
        [0, 1],
        CLAMP,
      );
      return {
        ctrs: EASE_CTRS(p),
        serif: p <= 0.3 ? 0 : EASE_SERIF(Math.min(1, (p - 0.3) / 0.7)),
        ch,
      };
    });
    let x = 0;
    const xs = progress.map(({ ch, ctrs }, i) => {
      const gx = x;
      const a = m.adv[ch];
      const kn = i < chars.length - 1 ? m.kern[ch + chars[i + 1]] : null;
      x += lerp(a[0], a[1], ctrs) + (kn ? lerp(kn[0], kn[1], ctrs) : 0) + TRACK;
      return gx;
    });
    const left = edge;
    const hl = hlRanges[r];
    const hlFill = (i: number) => hl !== null && i >= hl[0] && i < hl[1];
    const colorFor = (i: number) => (hlFill(i) ? spot : c.ink);

    progress.forEach(({ ch, ctrs, serif }, i) => {
      const idx = gi + i;
      const gxPx = left + xs[i] * F;
      const rise = interpolate(
        t,
        [idx * RISE_GAP, idx * RISE_GAP + RISE_LEN],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      const dy = (1 - rise) * F * 0.9;
      glyphNodes.push(
        <div
          key={`m${r}-${i}`}
          style={{
            position: "absolute",
            left: gxPx - F * 0.2,
            top: baseY - capPx * 1.5,
            width: m.adv[ch][0] * F + F * 0.6,
            height: capPx * 1.5 + F * 0.3,
            overflow: "hidden",
            clipPath: `inset(0 0 ${rise < 1 ? (F * 0.3 - F * 0.03).toFixed(1) : 0}px 0)`,
          }}
        >
          <span
            style={{
              position: "absolute",
              left: F * 0.2,
              top: capPx * 1.5 - m.baseline * F,
              height: F,
              lineHeight: `${F}px`,
              whiteSpace: "pre",
              fontFamily: gothic.fontFamily,
              fontStyle: "normal",
              fontSize: F,
              fontVariationSettings: fvs(CTRS_MAX * ctrs),
              transform: `translateY(${dy.toFixed(2)}px)`,
              color: colorFor(i),
            }}
          >
            {ch}
          </span>
        </div>,
      );
      if (serif <= 0.001) return;
      const a = m.adv[ch];
      const scale = lerp(a[0], a[1], ctrs) / Math.max(1e-6, a[1]);
      const th = Math.max(1.5, HAIR * F);
      const boxL = gxPx + F * 0.006;
      const boxR = gxPx + lerp(a[0], a[1], ctrs) * F - F * 0.006;
      m.stems[ch]?.forEach((s, k) => {
        const cx = gxPx + s.cx * scale * F;
        const w = s.w * F;
        const reach = w * REACH * serif;
        const bar = (side: Side, y: number, key: string) => {
          if (side === "none") return;
          const x0 = Math.max(
            Math.min(boxL, cx - w / 2),
            side === "right" ? cx : cx - w / 2 - reach,
          );
          const x1 = Math.min(
            Math.max(boxR, cx + w / 2),
            side === "left" ? cx : cx + w / 2 + reach,
          );
          serifNodes.push(
            <div
              key={key}
              style={{
                position: "absolute",
                left: x0,
                top: y,
                width: x1 - x0,
                height: th,
                background: colorFor(i),
              }}
            />,
          );
        };
        bar(s.foot, baseY - th, `f${r}-${i}-${k}`);
        bar(s.head, baseY - s.top * F, `h${r}-${i}-${k}`);
      });
    });
    gi += chars.length;
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {ruleNodes}
      {glyphNodes}
      {serifNodes}
      {transparent ? null : <Grain opacity={c.grain} />}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  highlight: {
    type: "text-content",
    default: "final cut.",
    description: "Highlight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","highlight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: "final cut.",
  speed: 1,
};

type SerifRiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SerifRiseBase>;

const SerifRiseInner = forwardRef<
  HTMLDivElement,
  SerifRiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SerifRise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SerifRiseBase
          {...(componentProps as unknown as ComponentProps<typeof SerifRiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SerifRise = Interactive.withSchema({
  Component: SerifRiseInner,
  componentName: "<SerifRise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// A field of refracted light — caustics. The web of bright filaments light
// makes when it passes through a surface and lands on the floor beneath.
// Written for the remocn registry as a custom WebGL shader (not a
// paper-design wrapper): frame-driven, deterministic, no wall-clock time.
//
// The filaments are slightly denser and brighter toward the bottom of the
// frame — the light lands on the base — which makes it a natural carrier for
// foundation stories. `accent` / `accentAmount` tint the filaments themselves
// (not the floor), so an undertone can arrive mid-video by animating
// `accentAmount` from the master timeline and stay in the light afterwards.

interface ShaderCausticsProps {
  /** [floor color, filament light color]. */
  colors?: [string, string];
  /** Tint mixed into the bright filaments. */
  accent?: string;
  /** 0..1 — how much of the accent the filaments take. */
  accentAmount?: number;
  /** Spatial frequency of the light web. */
  scale?: number;
  /** Overall brightness of the filaments. */
  intensity?: number;
  /** Global time multiplier. */
  speed?: number;
  className?: string;
}

const VERT = `
attribute vec2 a_pos;
void main() {
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;

uniform vec2 u_res;
uniform float u_time;
uniform float u_scale;
uniform float u_intensity;
uniform vec3 u_floor;
uniform vec3 u_light;
uniform vec3 u_accent;
uniform float u_accentAmt;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  vec2 p = vec2(uv.x * aspect, uv.y) * u_scale;

  // Iterative trigonometric warp: each pass bends the sample point by the
  // previous pass, and the reciprocal distance to the warped axes
  // accumulates into the caustic web.
  float t = u_time * 0.35;
  vec2 i = p;
  float c = 0.0;
  for (int n = 0; n < 4; n++) {
    float phase = t * (1.0 - 3.2 / float(n + 2));
    i = p + vec2(
      cos(phase - i.x) + sin(phase + i.y),
      sin(phase - i.y) + cos(phase + i.x)
    );
    c += 1.0 / length(vec2(
      p.x / (sin(i.x + phase) * 90.0),
      p.y / (cos(i.y + phase) * 90.0)
    ));
  }
  c /= 4.0;
  c = 1.24 - pow(abs(c), 1.35);
  // |c| collapses to zero along thin branching veins — that zero-crossing
  // set IS the caustic web. Light the veins with an exponential falloff
  // (sharp core + a soft halo) and leave everything else near-black.
  float web = exp(-abs(c) * 0.5) + 0.22 * exp(-abs(c) * 0.12);
  web = web / (1.0 + 0.6 * web);

  // The light lands on the base: filaments read stronger low in the frame.
  float ground = mix(1.25, 0.55, uv.y);
  web *= ground * u_intensity;

  // Vignette keeps the corners quiet so type always wins.
  vec2 v = uv - 0.5;
  float vig = 1.0 - dot(v, v) * 1.1;
  web *= clamp(vig, 0.0, 1.0);

  vec3 filament = mix(u_light, u_accent, clamp(u_accentAmt, 0.0, 1.0));
  vec3 col = u_floor + filament * web;

  // A whisper of living grain, time-derived so it stays deterministic.
  col += (hash(gl_FragCoord.xy + floor(u_time * 9.0)) - 0.5) * 0.012;

  gl_FragColor = vec4(col, 1.0);
}
`;

const hexToRgb = (hex: string): [number, number, number] => {
  const h = hex.replace("#", "");
  const v =
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h;
  const n = parseInt(v, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
};

type GlState = {
  gl: WebGLRenderingContext;
  uniforms: Record<string, WebGLUniformLocation | null>;
};

function ShaderCausticsBase({
  colors = ["#0a0a0a", "#2e2e33"],
  accent = "#7F57FF",
  accentAmount = 0,
  scale = 5.2,
  intensity = 1,
  speed = 1,
  className,
}: ShaderCausticsProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stateRef = useRef<GlState | null>(null);
  const [handle] = useState(() => delayRender("shader-caustics"));
  const continuedRef = useRef(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || stateRef.current) return;
    const gl = canvas.getContext("webgl", {
      antialias: false,
      preserveDrawingBuffer: true,
    });
    if (!gl) return;

    const compile = (type: number, src: string) => {
      const shader = gl.createShader(type);
      if (!shader) throw new Error("Failed to create WebGL shader");
      gl.shaderSource(shader, src);
      gl.compileShader(shader);
      return shader;
    };
    const program = gl.createProgram();
    if (!program) return;
    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(program);
    // biome-ignore lint/correctness/useHookAtTopLevel: gl.useProgram is a WebGL method, not a React hook
    gl.useProgram(program);

    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]),
      gl.STATIC_DRAW,
    );
    const loc = gl.getAttribLocation(program, "a_pos");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

    const uniforms: GlState["uniforms"] = {};
    for (const name of [
      "u_res",
      "u_time",
      "u_scale",
      "u_intensity",
      "u_floor",
      "u_light",
      "u_accent",
      "u_accentAmt",
    ]) {
      uniforms[name] = gl.getUniformLocation(program, name);
    }
    stateRef.current = { gl, uniforms };
  }, []);

  useEffect(() => {
    const state = stateRef.current;
    const canvas = canvasRef.current;
    if (!state || !canvas) return;
    const { gl, uniforms } = state;

    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.uniform2f(uniforms.u_res, canvas.width, canvas.height);
    gl.uniform1f(uniforms.u_time, (frame / fps) * speed);
    gl.uniform1f(uniforms.u_scale, scale);
    gl.uniform1f(uniforms.u_intensity, intensity);
    gl.uniform3fv(uniforms.u_floor, hexToRgb(colors[0]));
    gl.uniform3fv(uniforms.u_light, hexToRgb(colors[1]));
    gl.uniform3fv(uniforms.u_accent, hexToRgb(accent));
    gl.uniform1f(uniforms.u_accentAmt, accentAmount);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    if (!continuedRef.current) {
      continuedRef.current = true;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    }
  }, [
    frame,
    fps,
    speed,
    scale,
    intensity,
    colors,
    accent,
    accentAmount,
    handle,
  ]);

  return (
    <div className={className} style={{ position: "absolute", inset: 0 }}>
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        style={{ width: "100%", height: "100%", display: "block" }}
      />
    </div>
  );
}

