const ELEMENT_PROP_KEYS = new Set(["text","fontSize","rise","driftLeft","shadowSoftness","color","backgroundColor","shadowColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "are abandoned",
  fontSize: 96,
  rise: 96,
  driftLeft: 16,
  shadowSoftness: 130,
  color: "#aaa6b5",
  backgroundColor: "#030012",
  shadowColor: "#030012",
  fontWeight: "700",
  speed: 1,
};

type ShadowSweepTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShadowSweepTextBase>;

const ShadowSweepTextInner = forwardRef<
  HTMLDivElement,
  ShadowSweepTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShadowSweepText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShadowSweepTextBase
          {...(componentProps as unknown as ComponentProps<typeof ShadowSweepTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShadowSweepText = Interactive.withSchema({
  Component: ShadowSweepTextInner,
  componentName: "<ShadowSweepText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

