const isBrand = (label: string) => label.trim().toLowerCase() === "remocn";

interface DonutSegment {
  label: string;
  value: number;
}

interface ShareDonutProps {
  segments?: DonutSegment[];
  highlight?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_SEGMENTS: DonutSegment[] = [
  { label: "remocn", value: 38 },
  { label: "Kitebase", value: 24 },
  { label: "Lumen", value: 17 },
  { label: "Fernway", value: 12 },
  { label: "Other", value: 9 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SEG = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.22)",
    track: "rgba(255,255,255,0.05)",
    grays: ["#B9B7B2", "#85848A", "#5C5B61", "#3E3D43"],
    // gradients.sh "halo": the highlighted share burns accent → rose → amber.
    halo: ["#E2457A", "#FFB36B"],
    haze: ["rgba(226,69,122,0.12)", "rgba(61,77,255,0.09)"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.22)",
    track: "rgba(18,18,20,0.05)",
    grays: ["#4F4D49", "#85837E", "#AEACA6", "#D0CEC8"],
    halo: ["#E2457A", "#FF9A4D"],
    haze: ["rgba(226,69,122,0.08)", "rgba(61,77,255,0.05)"],
    grain: 0.045,
  },
} as const;

const DRAW_START = 6;
const DRAW_LEN = 52;
const TAU = Math.PI * 2;

function pt(cx: number, cy: number, r: number, a: number) {
  return { x: cx + r * Math.sin(a), y: cy - r * Math.cos(a) };
}

function arc(cx: number, cy: number, r: number, a0: number, a1: number) {
  const s = pt(cx, cy, r, a0);
  const e = pt(cx, cy, r, a1);
  const large = a1 - a0 > Math.PI ? 1 : 0;
  return `M ${s.x.toFixed(2)} ${s.y.toFixed(2)} A ${r} ${r} 0 ${large} 1 ${e.x.toFixed(2)} ${e.y.toFixed(2)}`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function ShareDonutBase({
  segments = DEFAULT_SEGMENTS,
  highlight = 0,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: ShareDonutProps) {
  const t = useCurrentFrame() * speed;
  const { width, height, fps } = useVideoConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const list = segments.slice(0, 5);
  const hl = Math.min(Math.max(0, Math.round(highlight)), list.length - 1);
  const total = list.reduce((s, x) => s + Math.max(0, x.value), 0) || 1;

  const cx = width / 2;
  const cy = height / 2;
  const R = height * 0.3;
  const sw = 12 * u;
  const gapA = (6 * u) / R;

  let acc = 0;
  let grayIdx = 0;
  let clock = DRAW_START;
  const segs = list.map((s, i) => {
    const frac = Math.max(0, s.value) / total;
    const a0 = acc * TAU;
    acc += frac;
    const a1 = acc * TAU;
    const dur = Math.max(9, DRAW_LEN * frac);
    const start = clock;
    clock += dur - 2;
    const color = i === hl ? accent : p.grays[Math.min(grayIdx++, 3)];
    return {
      ...s,
      i,
      frac,
      a0: a0 + gapA / 2,
      a1: a1 - gapA / 2,
      mid: (a0 + a1) / 2,
      start,
      end: start + dur,
      color,
      pct: Math.round(frac * 100),
    };
  });
  const drawEnd = segs.length ? segs[segs.length - 1].end : DRAW_START;
  const HIT = drawEnd + 8;

  const detach = spring({
    frame: t - HIT,
    fps,
    config: { damping: 15, stiffness: 150, mass: 0.7 },
  });
  const dim = interpolate(t, [HIT, HIT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const land = interpolate(t, [HIT + 4, HIT + 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [HIT + 4, HIT + 30], [0.55, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const labIn = interpolate(t, [HIT + 12, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const stage = interpolate(t, [0, 10], [0.4, 1], CLAMP);
  const spin = interpolate(t, [0, HIT + 10], [-14, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [0, HIT + 60], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const scale = 0.97 + 0.04 * push;

  const target = segs[hl];
  const gradId = `h${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const g0 = target ? pt(cx, cy, R, target.a0) : { x: cx, y: cy - R };
  const g1 = target ? pt(cx, cy, R, target.a1) : { x: cx + R, y: cy };
  const off = detach * 18 * u;
  const hx = target ? Math.sin(target.mid) * off : 0;
  const hy = target ? -Math.cos(target.mid) * off : 0;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, transparent ${R * 0.62}px, ${p.haze[0]} ${R * 1.02}px, ${p.haze[1]} ${R * 1.3}px, transparent ${R * 1.85}px)`,
          opacity: 0.25 + 0.75 * land,
          transform: `rotate(${spin}deg)`,
        }}
      />
      <AbsoluteFill
        style={{
          transform: `scale(${scale})`,
          transformOrigin: "50% 50%",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, opacity: stage }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={g0.x}
              y1={g0.y}
              x2={g1.x}
              y2={g1.y}
            >
              <stop offset="0" stopColor={accent} />
              <stop offset="0.58" stopColor={p.halo[0]} />
              <stop offset="1" stopColor={p.halo[1]} />
            </linearGradient>
          </defs>
          <g transform={`rotate(${spin} ${cx} ${cy})`}>
            <circle
              cx={cx}
              cy={cy}
              r={R}
              fill="none"
              stroke={p.track}
              strokeWidth={sw}
              opacity={1 - dim}
            />
            {segs.map((s) => {
              const k = interpolate(t, [s.start, s.end], [0, 1], {
                ...CLAMP,
                easing: EASE_SEG,
              });
              if (k <= 0 || s.a1 <= s.a0) return null;
              const isHl = s.i === hl;
              const a1 = s.a0 + (s.a1 - s.a0) * k;
              return (
                <path
                  key={s.label}
                  d={arc(cx, cy, R, s.a0, a1)}
                  fill="none"
                  stroke={isHl ? `url(#${gradId})` : s.color}
                  strokeLinecap={isHl ? "round" : "butt"}
                  strokeWidth={isHl ? sw * (1 + 0.5 * detach) : sw}
                  opacity={isHl ? 1 : 1 - 0.5 * dim}
                  transform={isHl ? `translate(${hx} ${hy})` : undefined}
                />
              );
            })}
            {segs.map((s) => {
              const a = interpolate(t, [s.end - 6, s.end + 8], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const p0 = pt(cx, cy, R + sw / 2 + 8 * u, s.mid);
              const p1 = pt(cx, cy, R + sw / 2 + 8 * u + 14 * u * a, s.mid);
              const fade = s.i === hl ? 1 - dim : 1 - 0.55 * dim;
              return (
                <line
                  key={s.label}
                  x1={p0.x}
                  y1={p0.y}
                  x2={p1.x}
                  y2={p1.y}
                  stroke={p.hair}
                  strokeWidth={Math.max(1, u)}
                  opacity={a * fade}
                />
              );
            })}
          </g>
        </svg>

        {segs.map((s) => {
          const a = interpolate(t, [s.end - 4, s.end + 12], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const ang = s.mid + (spin * Math.PI) / 180;
          const q = pt(cx, cy, R + sw / 2 + 38 * u + (1 - a) * -8 * u, ang);
          const right = Math.sin(ang) >= -0.05;
          const fade = s.i === hl ? 1 - dim : 1 - 0.6 * dim;
          return (
            <div
              key={s.label}
              style={{
                position: "absolute",
                left: q.x,
                top: q.y,
                transform: `translate(${right ? 0 : -100}%, -50%)`,
                display: "flex",
                flexDirection: "column",
                alignItems: right ? "flex-start" : "flex-end",
                gap: 2 * u,
                opacity: a * fade * stage,
                whiteSpace: "nowrap",
              }}
            >
              <span
                style={{
                  fontFamily: sans,
                  fontWeight: 500,
                  fontSize: 22 * u,
                  letterSpacing: "-0.02em",
                  color: p.fg,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {s.pct}%
              </span>
              {isBrand(s.label) ? (
                <RemocnLogo fontSize={15 * u} color={p.muted} />
              ) : (
                <span
                  style={{
                    fontFamily: sans,
                    fontWeight: 400,
                    fontSize: 15 * u,
                    color: p.muted,
                  }}
                >
                  {s.label}
                </span>
              )}
            </div>
          );
        })}

        {target ? (
          <AbsoluteFill
            style={{
              alignItems: "center",
              justifyContent: "center",
              flexDirection: "column",
            }}
          >
            <div
              style={{
                fontFamily: display,
                fontWeight: 300,
                fontSize: 176 * u,
                lineHeight: 0.9,
                letterSpacing: "-0.035em",
                color: p.fg,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
                opacity: land,
                filter:
                  land < 0.99 ? `blur(${(1 - land) * 8 * u}px)` : undefined,
                transform: `translateY(${(1 - land) * 22 * u}px) scale(${1.05 - 0.05 * land})`,
                marginTop: 10 * u,
              }}
            >
              {Math.round(target.pct * count)}
              <span
                style={{
                  fontSize: 92 * u,
                  fontStyle: "italic",
                  letterSpacing: "-0.02em",
                  marginLeft: 4 * u,
                  color: p.muted,
                }}
              >
                %
              </span>
            </div>
            <div
              style={{
                marginTop: 14 * u,
                display: "flex",
                alignItems: "center",
                gap: 10 * u,
                opacity: labIn,
                transform: `translateY(${(1 - labIn) * 8 * u}px)`,
              }}
            >
              {isBrand(target.label) ? (
                <RemocnLogo fontSize={28 * u} color={p.fg} />
              ) : (
                <>
                  <span
                    style={{
                      width: 10 * u,
                      height: 10 * u,
                      borderRadius: "50%",
                      background: `linear-gradient(135deg, ${accent}, ${p.halo[0]}, ${p.halo[1]})`,
                    }}
                  />
                  <span
                    style={{
                      fontFamily: sans,
                      fontWeight: 400,
                      fontSize: 22 * u,
                      letterSpacing: "-0.01em",
                      color: p.muted,
                      whiteSpace: "nowrap",
                    }}
                  >
                    {target.label}
                  </span>
                </>
              )}
            </div>
          </AbsoluteFill>
        ) : null}
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  highlight: {
    type: "number",
    default: 0,
    min: 0,
    max: 10,
    step: 1,
    description: "Highlight",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","highlight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  highlight: 0,
  speed: 1,
};

type ShareDonutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShareDonutBase>;

const ShareDonutInner = forwardRef<
  HTMLDivElement,
  ShareDonutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShareDonut>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShareDonutBase
          {...(componentProps as unknown as ComponentProps<typeof ShareDonutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShareDonut = Interactive.withSchema({
  Component: ShareDonutInner,
  componentName: "<ShareDonut>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface SharedAxisYProps {
  fromText: string;
  toText: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

function SharedAxisYBase({
  fromText,
  toText,
  fontSize = 72,
  color = "#171717",
  fontWeight = 600,
  speed = 1,
  className,
}: SharedAxisYProps) {
  const frame = useCurrentFrame() * speed;

  const fromWords = fromText.split(" ");
  const toWords = toText.split(" ");

  const enterDur = 5;
  const exitDur = 4;
  const enterStagger = 2;
  const exitStagger = 2;
  const overlapF = 0;
  const microDelayF = 1;

  const exitTotal = exitDur + (fromWords.length - 1) * exitStagger;
  const newStart = Math.max(0, exitTotal - overlapF + microDelayF);

  const fontStack =
    "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background: "transparent",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <span
          style={{
            fontSize,
            fontWeight,
            color,
            letterSpacing: "-0.03em",
            fontFamily: fontStack,
          }}
        >
          {fromWords.map((word, i) => {
            const local = frame - i * exitStagger;
            const opacity = interpolate(local, [0, exitDur], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.step1,
            });
            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  marginRight: "0.25em",
                  opacity,
                }}
              >
                {word}
              </span>
            );
          })}
        </span>
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <span
          style={{
            fontSize,
            fontWeight,
            color,
            letterSpacing: "-0.03em",
            fontFamily: fontStack,
          }}
        >
          {toWords.map((word, j) => {
            const local = frame - newStart - j * enterStagger;
            const opacity = interpolate(local, [0, enterDur], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.step1,
            });
            return (
              <span
                key={j}
                style={{
                  display: "inline-block",
                  marginRight: "0.25em",
                  opacity,
                }}
              >
                {word}
              </span>
            );
          })}
        </span>
      </div>
    </div>
  );
}

