const ELEMENT_PROP_KEYS = new Set(["theme","value","unit","label","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "27",
  unit: "Mar",
  label: "Demo day. Every team shows a film.",
  speed: 1,
};

type SingleStrokeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SingleStrokeBase>;

const SingleStrokeInner = forwardRef<
  HTMLDivElement,
  SingleStrokeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SingleStroke>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SingleStrokeBase
          {...(componentProps as unknown as ComponentProps<typeof SingleStrokeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SingleStroke = Interactive.withSchema({
  Component: SingleStrokeInner,
  componentName: "<SingleStroke>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

