function spread(ys: number[], minGap: number) {
  const order = ys.map((y, i) => ({ y, i })).sort((a, b) => a.y - b.y);
  for (let pass = 0; pass < 8; pass++) {
    for (let k = 1; k < order.length; k++) {
      const gap = order[k].y - order[k - 1].y;
      if (gap < minGap) {
        const push = (minGap - gap) / 2;
        order[k - 1].y -= push;
        order[k].y += push;
      }
    }
  }
  const out = [...ys];
  for (const o of order) out[o.i] = o.y;
  return out;
}

function taper(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  w0: number,
  w1: number,
) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  const a = [x0 + (nx * w0) / 2, y0 + (ny * w0) / 2];
  const b = [x1 + (nx * w1) / 2, y1 + (ny * w1) / 2];
  const c = [x1 - (nx * w1) / 2, y1 - (ny * w1) / 2];
  const d = [x0 - (nx * w0) / 2, y0 - (ny * w0) / 2];
  return `M${a[0]} ${a[1]} L${b[0]} ${b[1]} L${c[0]} ${c[1]} L${d[0]} ${d[1]} Z`;
}

const fmt = (n: number) =>
  Number.isInteger(n) ? String(n) : n.toFixed(1).replace(/\.0$/, "");

function SlopeChartBase({
  lines = DEFAULT_LINES,
  highlight = DEFAULT_HIGHLIGHT,
  value = "6.8×",
  label = "more launch videos shipped",
  beforeLabel = "Before",
  afterLabel = "After",
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: SlopeChartProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];

  const greys = lines.slice(0, 8);
  const all = [...greys, highlight];
  const max = Math.max(1, ...all.flatMap((l) => [l.before, l.after]));
  const min = Math.min(0, ...all.flatMap((l) => [l.before, l.after]));

  const xL = W * 0.2;
  const xR = W * 0.58;
  const yTop = H * 0.235;
  const yBot = H * 0.8;
  const yOf = (v: number) => yBot - ((v - min) / (max - min)) * (yBot - yTop);

  const axisIn = interpolate(t, AXES, [0, 1], { ...CLAMP, easing: EASE_IO });
  const axisLabelIn = interpolate(t, [6, 22], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const push = interpolate(t, [0, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const camScale = 0.975 + 0.025 * push;
  // The chart sits centred alone; the frame eases over as the number lands.
  const slide = interpolate(t, [CLIMB[0] + 8, HIT + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const camX = W * 0.11 * (1 - slide);

  const climb = interpolate(t, CLIMB, [0, 1], {
    ...CLAMP,
    easing: CLIMB_EASE,
  });
  const dim = interpolate(t, [CLIMB[0] - 2, CLIMB[0] + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const leftYs = spread(
    all.map((l) => yOf(l.before)),
    20 * u,
  );
  const rightYs = spread(
    greys.map((l) => yOf(l.after)),
    20 * u,
  );

  const hx0 = xL;
  const hy0 = yOf(highlight.before);
  const hx1 = xR;
  const hy1 = yOf(highlight.after);
  const tipX = hx0 + (hx1 - hx0) * climb;
  const tipY = hy0 + (hy1 - hy0) * climb;
  const wStart = 2.2 * u;
  const wTip = (2.2 + 5.4 * climb) * u;
  const startDot = spring({
    frame: t - CLIMB[0] + 6,
    fps,
    config: { damping: 14, stiffness: 180, mass: 0.6 },
  });

  const hit = spring({
    frame: t - HIT,
    fps,
    config: { damping: 15, stiffness: 170, mass: 0.7 },
  });
  const hitO = interpolate(t, [HIT, HIT + 6], [0, 1], CLAMP);
  const ring = interpolate(t, [HIT, HIT + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lab = interpolate(t, [HIT + 8, HIT + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const valueSize = 156 * u;
  const gradId = `${useId().replace(/[^a-zA-Z0-9_-]/g, "")}-limb`;
  const tipColor = p.limb[p.limb.length - 1];
  const stroke = Math.max(1, u);

  const greyEls: React.ReactNode[] = [];
  const greyDots: React.ReactNode[] = [];
  greys.forEach((l, i) => {
    const start = GREY_AT + i * GREY_STAGGER;
    const prog = interpolate(t, [start, start + GREY_DRAW], [0, 1], {
      ...CLAMP,
      easing: DRAW_EASE,
    });
    if (prog <= 0) return;
    const y0 = yOf(l.before);
    const y1 = yOf(l.after);
    const x = xL + (xR - xL) * prog;
    const y = y0 + (y1 - y0) * prog;
    const o = 0.95 - 0.4 * dim;
    greyEls.push(
      <line
        key={`l${i}`}
        x1={xL}
        y1={y0}
        x2={x}
        y2={y}
        stroke={p.line}
        strokeWidth={1.7 * u}
        strokeLinecap="round"
        opacity={o}
      />,
    );
    const a = interpolate(t, [start, start + 6], [0, 1], CLAMP);
    const b = interpolate(
      t,
      [start + GREY_DRAW - 4, start + GREY_DRAW + 4],
      [0, 1],
      CLAMP,
    );
    greyDots.push(
      <circle
        key={`a${i}`}
        cx={xL}
        cy={y0}
        r={3.6 * u * (0.6 + 0.4 * a)}
        fill={p.line}
        opacity={a * o}
      />,
      <circle
        key={`b${i}`}
        cx={xR}
        cy={y1}
        r={3.6 * u * (0.6 + 0.4 * b)}
        fill={p.line}
        opacity={b * o}
      />,
    );
  });

  const gridVals = [0.25, 0.5, 0.75, 1].map((k) => min + (max - min) * k);

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `translateX(${camX}px) scale(${camScale})`,
          transformOrigin: "50% 50%",
        }}
      >
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={hx0}
              y1={hy0}
              x2={hx1}
              y2={hy1}
            >
              {p.limb.map((c, i) => (
                <stop
                  key={c}
                  offset={i / (p.limb.length - 1)}
                  stopColor={c === "accent" ? accent : c}
                />
              ))}
            </linearGradient>
            <linearGradient
              id={`${gradId}-w`}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={hy1}
              x2={0}
              y2={hy0}
            >
              <stop
                offset={0}
                stopColor={p.limb[1] === "accent" ? accent : p.limb[1]}
                stopOpacity={p.wedge}
              />
              <stop offset={1} stopColor={accent} stopOpacity={0} />
            </linearGradient>
          </defs>
          {gridVals.map((v) => (
            <line
              key={v}
              x1={xL}
              x2={xL + (xR - xL) * axisIn}
              y1={yOf(v)}
              y2={yOf(v)}
              stroke={p.tick}
              strokeWidth={stroke}
              strokeDasharray={`${2 * u} ${6 * u}`}
            />
          ))}
          {[xL, xR].map((x) => (
            <line
              key={x}
              x1={x}
              x2={x}
              y1={yBot + 14 * u}
              y2={yBot + 14 * u - (yBot - yTop + 28 * u) * axisIn}
              stroke={p.axis}
              strokeWidth={stroke}
            />
          ))}
          {climb > 0 && (
            <path
              d={`M${hx0} ${hy0} L${tipX} ${tipY} L${tipX} ${hy0} Z`}
              fill={`url(#${gradId}-w)`}
            />
          )}
          {greyEls}
          {greyDots}
          {climb > 0 && (
            <>
              <path
                d={taper(hx0, hy0, tipX, tipY, wStart, wTip)}
                fill={`url(#${gradId})`}
              />
              <circle
                cx={tipX}
                cy={tipY}
                r={wTip / 2}
                fill={`url(#${gradId})`}
              />
            </>
          )}
          <circle
            cx={hx0}
            cy={hy0}
            r={5 * u * (0.6 + 0.4 * startDot)}
            fill={accent}
            opacity={Math.min(1, startDot * 1.4)}
          />
          {t >= HIT && (
            <circle
              cx={hx1}
              cy={hy1}
              r={(8 + 34 * ring) * u}
              fill="none"
              stroke={tipColor}
              strokeWidth={1.5 * u}
              opacity={(1 - ring) * 0.7}
            />
          )}
          {climb > 0 && (
            <circle
              cx={tipX}
              cy={tipY}
              r={(6.5 + 2 * hit) * u}
              fill={`url(#${gradId})`}
            />
          )}
          {climb > 0 && <circle cx={tipX} cy={tipY} r={2.4 * u} fill={p.bg} />}
        </svg>

        {all.map((l, i) => {
          const isHl = i === all.length - 1;
          const start = isHl ? CLIMB[0] - 6 : GREY_AT + i * GREY_STAGGER;
          const a = interpolate(t, [start + 2, start + 14], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const o = isHl ? 1 : 0.9 - 0.45 * dim;
          return (
            <div
              key={`v${i}`}
              style={{
                position: "absolute",
                left: xL - 120 * u - 18 * u,
                top: leftYs[i] - 10 * u,
                width: 120 * u,
                textAlign: "right",
                fontFamily: sans,
                fontWeight: isHl ? 500 : 400,
                fontSize: 16 * u,
                lineHeight: `${20 * u}px`,
                color: isHl ? accent : p.muted,
                fontVariantNumeric: "tabular-nums",
                opacity: a * o,
                transform: `translateX(${(1 - a) * 8 * u}px)`,
              }}
            >
              {fmt(l.before)}
            </div>
          );
        })}

        {greys.map((l, i) => {
          const end = GREY_AT + i * GREY_STAGGER + GREY_DRAW;
          const a = interpolate(t, [end - 4, end + 10], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          return (
            <div
              key={`r${i}`}
              style={{
                position: "absolute",
                left: xR + 18 * u,
                top: rightYs[i] - 10 * u,
                fontFamily: sans,
                fontWeight: 400,
                fontSize: 16 * u,
                lineHeight: `${20 * u}px`,
                color: p.muted,
                fontVariantNumeric: "tabular-nums",
                opacity: a * (0.9 - 0.45 * dim),
                transform: `translateX(${(1 - a) * -8 * u}px)`,
              }}
            >
              {fmt(l.after)}
            </div>
          );
        })}

        {[
          { x: xL, text: beforeLabel },
          { x: xR, text: afterLabel },
        ].map((ax) => (
          <div
            key={ax.text}
            style={{
              position: "absolute",
              left: ax.x - 100 * u,
              width: 200 * u,
              top: yBot + 30 * u,
              textAlign: "center",
              fontFamily: sans,
              fontWeight: 500,
              fontSize: 18 * u,
              letterSpacing: "-0.01em",
              color: p.fg,
              opacity: axisLabelIn,
              transform: `translateY(${(1 - axisLabelIn) * 8 * u}px)`,
            }}
          >
            {ax.text}
          </div>
        ))}

        <div
          style={{
            position: "absolute",
            left: xR + 44 * u,
            top: hy1 - valueSize * 0.5,
            opacity: hitO,
            transform: `translateX(${(1 - hit) * -18 * u}px)`,
          }}
        >
          <div
            style={{
              fontFamily: serif,
              fontWeight: 400,
              fontSize: valueSize,
              lineHeight: 1,
              letterSpacing: "-0.02em",
              color: p.fg,
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
            }}
          >
            {value}
          </div>
          <div
            style={{
              marginTop: 10 * u,
              fontFamily: sans,
              fontWeight: 500,
              fontSize: 20 * u,
              letterSpacing: "-0.01em",
              color: p.muted,
              opacity: lab,
              transform: `translateY(${(1 - lab) * 8 * u}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {label}
          </div>
        </div>
      </AbsoluteFill>
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  value: {
    type: "text-content",
    default: "6.8×",
    description: "Value",
  },
  label: {
    type: "text-content",
    default: "more launch videos shipped",
    description: "Label",
  },
  beforeLabel: {
    type: "text-content",
    default: "Before",
    description: "Before label",
  },
  afterLabel: {
    type: "text-content",
    default: "After",
    description: "After label",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","label","beforeLabel","afterLabel","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "6.8×",
  label: "more launch videos shipped",
  beforeLabel: "Before",
  afterLabel: "After",
  speed: 1,
};

type SlopeChartElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SlopeChartBase>;

const SlopeChartInner = forwardRef<
  HTMLDivElement,
  SlopeChartElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SlopeChart>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SlopeChartBase
          {...(componentProps as unknown as ComponentProps<typeof SlopeChartBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SlopeChart = Interactive.withSchema({
  Component: SlopeChartInner,
  componentName: "<SlopeChart>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface SlotMachineRollProps {
  from?: string;
  to?: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

export function SlotMachineRoll({
  from = "$99",
  to = "$199",
  fontSize = 120,
  color = "#171717",
  fontWeight = 700,
  speed = 1,
  className,
}: SlotMachineRollProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const len = Math.max(from.length, to.length);
  const paddedFrom = from.padStart(len, " ");
  const paddedTo = to.padStart(len, " ");

  const columns = [];
  for (let i = 0; i < len; i++) {
    const raw = spring({
      frame: frame - i * 4,
      fps,
      config: { damping: 14 },
    });
    const t = Math.max(0, Math.min(1, raw));
    columns.push(
      <span
        key={i}
        style={{
          display: "inline-block",
          overflow: "hidden",
          height: "1.1em",
          lineHeight: "1.1em",
          verticalAlign: "top",
          width: "0.7em",
          textAlign: "center",
        }}
      >
        <span
          style={{
            display: "flex",
            flexDirection: "column",
            translate: `0 ${-t * fontSize * 1.1}px`,
          }}
        >
          <span>{paddedFrom[i]}</span>
          <span>{paddedTo[i]}</span>
        </span>
      </span>,
    );
  }

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "white",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.03em",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
          lineHeight: 1.1,
        }}
      >
        {columns}
      </span>
    </div>
  );
}

import { loadFont as loadRubik } from "@remotion/google-fonts/Rubik";
import { useEffect, useMemo, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const rubik = loadRubik("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface SmashCountProps {
  value?: number;
  from?: number;
  cuts?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const RED = "#E60012";

const THEMES = {
  dark: { bg: "#000000", ink: "#FFFFFF" },
  light: { bg: "#FFFFFF", ink: "#000000" },
} as const;

type Anchor = "c" | "tl" | "tr" | "bl" | "br";
const ROUTE: Anchor[] = ["c", "tr", "bl", "tl", "br", "c", "tr", "tl"];

const TRACK = -0.04;
const FIRST_GAP = 13;
const LAST_GAP = 6;
const PUNCH_LEN = 5;
const LAND_LEN = 12;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  widths: number[];
  cap: number;
  base: number;
  label: number;
}

function cutValues(from: number, value: number, cuts: number) {
  const n = Math.max(2, Math.min(cuts, Math.abs(value - from) + 1));
  const out: number[] = [];
  for (let k = 0; k < n; k++) {
    const x = k / (n - 1);
    const e = 1 - (1 - x) ** 1.7;
    out.push(Math.round(from + (value - from) * e));
  }
  for (let k = 1; k < n; k++) {
    if (out[k] === out[k - 1]) out[k] = out[k - 1] + Math.sign(value - from);
  }
  out[n - 1] = value;
  return out;
}

function cutTimes(n: number) {
  const out = [0];
  for (let k = 1; k < n; k++) {
    const g =
      FIRST_GAP + (LAST_GAP - FIRST_GAP) * ((k - 1) / Math.max(1, n - 2));
    out.push(out[k - 1] + g);
  }
  return out.map((v) => Math.round(v));
}

function measure(texts: string[], label: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) throw new Error("smash-count: no 2d context");
  ctx.font = `500 100px "${rubik.fontFamily}"`;
  const widths = texts.map(
    (s) =>
      ctx.measureText(s).width / 100 +
      TRACK * Math.max(0, Array.from(s).length - 1),
  );
  const fm = ctx.measureText("0123456789");
  const asc = fm.fontBoundingBoxAscent / 100;
  const desc = fm.fontBoundingBoxDescent / 100;
  ctx.font = `400 100px "${rubik.fontFamily}"`;
  return {
    widths,
    cap: ctx.measureText("0").actualBoundingBoxAscent / 100,
    base: (1 - (asc + desc)) / 2 + asc,
    label: label ? ctx.measureText(label).width / 100 : 0,
  };
}

function useMetrics(texts: string[], label: string) {
  const key = [...texts, label].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("smash-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const parts = key.split("\u0001");
    Promise.all([
      rubik.waitUntilDone(),
      document.fonts.load(`500 100px "${rubik.fontFamily}"`),
      document.fonts.load(`400 100px "${rubik.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          m: measure(parts.slice(0, -1), parts[parts.length - 1] ?? ""),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function splitLabel(label: string) {
  const words = label.split(" ").filter(Boolean);
  if (words.length < 3) return [label];
  let best = 1;
  let bestDiff = Number.POSITIVE_INFINITY;
  for (let i = 1; i < words.length; i++) {
    const a = words.slice(0, i).join(" ").length;
    const b = words.slice(i).join(" ").length;
    const d = Math.abs(a - b);
    if (d < bestDiff) {
      bestDiff = d;
      best = i;
    }
  }
  return [words.slice(0, best).join(" "), words.slice(best).join(" ")];
}

export function SmashCount({
  value = 64,
  from = 1,
  cuts = 6,
  prefix = "",
  suffix = "",
  label = "scenes, zero keyframes",
  accent = RED,
  background,
  speed = 1,
  theme = "dark",
}: SmashCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const values = useMemo(
    () => cutValues(Math.round(from), Math.round(value), Math.round(cuts)),
    [from, value, cuts],
  );
  const texts = useMemo(
    () => values.map((v) => `${prefix}${v.toLocaleString("en-US")}${suffix}`),
    [values, prefix, suffix],
  );
  const lines = useMemo(() => (label ? splitLabel(label) : []), [label]);
  const m = useMetrics(
    texts,
    lines.reduce((a, b) => (a.length > b.length ? a : b), ""),
  );

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const n = texts.length;
  const times = cutTimes(n);
  let k = 0;
  for (let i = 0; i < n; i++) if (t >= times[i]) k = i;
  const last = k === n - 1;
  const local = t - times[k];

  const margin = Math.min(W, H) * 0.07;
  const anchor: Anchor = last ? "bl" : ROUTE[k % ROUTE.length];
  const x = k / Math.max(1, n - 1);
  const capFrac = last
    ? portrait
      ? 0.34
      : 0.74
    : (portrait ? 0.12 : 0.24) + (portrait ? 0.14 : 0.3) * x ** 1.2;
  const F = Math.min(
    (capFrac * H) / m.cap,
    (W - 2 * margin) / Math.max(0.2, m.widths[k]),
  );
  const textW = m.widths[k] * F;
  const capPx = m.cap * F;

  const left =
    anchor === "c"
      ? (W - textW) / 2
      : anchor === "tl" || anchor === "bl"
        ? margin
        : W - margin - textW;
  const baseY =
    anchor === "c"
      ? (H + capPx) / 2
      : anchor === "tl" || anchor === "tr"
        ? margin + capPx
        : H - margin;

  const punch = last
    ? interpolate(local, [0, LAND_LEN], [1.05, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      })
    : interpolate(local, [0, PUNCH_LEN], [1.08, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
  const ox =
    anchor === "c" ? "50%" : anchor === "tl" || anchor === "bl" ? "0%" : "100%";
  const oy = `${(m.base * 100).toFixed(1)}%`;

  const labelFs = Math.min(
    H * (portrait ? 0.03 : 0.052),
    (W * (portrait ? 0.8 : 0.42)) / Math.max(0.1, m.label),
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left,
          top: baseY - m.base * F,
          height: F,
          lineHeight: `${F}px`,
          whiteSpace: "pre",
          fontFamily: rubik.fontFamily,
          fontWeight: 500,
          fontSize: F,
          letterSpacing: `${TRACK}em`,
          color: accent,
          transform: `scale(${punch.toFixed(4)})`,
          transformOrigin: `${ox} ${oy}`,
        }}
      >
        {texts[k]}
      </div>
      {last && lines.length > 0 ? (
        <div
          style={{
            position: "absolute",
            right: margin,
            top: margin - labelFs * 0.1,
            textAlign: "right",
            fontFamily: rubik.fontFamily,
            fontWeight: 400,
            fontSize: labelFs,
            lineHeight: 1.12,
            letterSpacing: "-0.015em",
            whiteSpace: "pre",
            color: c.ink,
          }}
        >
          {lines.join("\n")}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface SoftBlurInProps {
  text: string;
  blur?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

function SoftBlurInBase({
  text,
  blur = 12,
  fontSize = 72,
  color = "#171717",
  fontWeight = 600,
  speed = 1,
  className,
}: SoftBlurInProps) {
  const frame = useCurrentFrame() * speed;

  const chars = Array.from(text);
  const charDurationFrames = 27;
  const charTravelFrames = 9;
  const staggerFrames = 1;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.05em",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        }}
      >
        {chars.map((char, i) => {
          const local = frame - i * staggerFrames;
          const easing = Easing.bezier(0.22, 1, 0.36, 1);
          const opacity = interpolate(local, [0, charDurationFrames], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing,
          });
          const y = interpolate(local, [0, charTravelFrames], [16, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing,
          });
          const blurAmount = interpolate(
            local,
            [0, charDurationFrames],
            [blur, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing },
          );
          return (
            <span
              key={i}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                backfaceVisibility: "hidden",
                transformOrigin: "50% 55%",
                opacity,
                translate: `0 ${y}px`,
                filter: `blur(${blurAmount}px)`,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Think different.",
    description: "Text",
  },
  blur: {
    type: "number",
    min: 1,
    max: 30,
    step: 1,
    default: 12,
    description: "Blur",
    hiddenFromList: false,
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 160,
    step: 1,
    default: 72,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "600",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 600,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 100,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","blur","fontSize","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Think different.",
  blur: 12,
  fontSize: 72,
  color: "#171717",
  fontWeight: "600",
  speed: 1,
};

type SoftBlurInElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof SoftBlurInBase>;

const SoftBlurInInner = forwardRef<
  HTMLDivElement,
  SoftBlurInElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 600, height = 100, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SoftBlurIn>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <SoftBlurInBase
            {...(componentProps as unknown as ComponentProps<typeof SoftBlurInBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const SoftBlurIn = Interactive.withSchema({
  Component: SoftBlurInInner,
  componentName: "<SoftBlurIn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Archivo";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
loadFont("italic", { weights: ["500"], subsets: ["latin"] });
const { fontFamily: serif } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

interface SoldOutProps {
  /** Stock when the shot opens; it races down to zero. */
  stock?: number;
  /** Word after the counter. */
  unit?: string;
  /** Tag that flashes once the stock hits ten. */
  warning?: string;
  /** Set huge on the diagonal band at zero. */
  stamp?: string;
  /** Subline lead, in the grotesk. */
  lead?: string;
  /** Subline accent, in the serif italic. */
  tail?: string;
  /** Kept for the shared draft API; the band takes the "chrome" gradient. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Archivo 500 (fontTools, wght 500, wdth 100): cap 0.686; figures 0.57em,
// set in fixed 0.58em cells. "LEFT" 2.449em, side bearings 0.081 / 0.022.
// Archivo 500 italic: "SOLD OUT" 5.068em.
const CAP = 0.686;
const CELL = 0.58;
const ADV: Record<string, number> = {
  L: 0.552,
  E: 0.674,
  F: 0.611,
  T: 0.612,
  S: 0.67,
  O: 0.785,
  D: 0.731,
  U: 0.728,
  " ": 0.205,
  W: 0.938,
  C: 0.725,
  K: 0.677,
};
const textEm = (s: string, track = 0) => {
  const a = Array.from(s);
  return (
    a.reduce((w, ch) => w + (ADV[ch] ?? 0.66), 0) +
    track * Math.max(0, a.length - 1)
  );
};

// Beat sheet (30fps, speed 1, stock 128):
//   0–9    "128 LEFT" punches in from 1.25× and a blur
//  10–56   the reels race down to 10 (ease in-out), the units reel smears;
//          the frame shakes harder the lower it gets
//  56–86   ten hard ticks, 3 frames apart, each with a hit; LOW STOCK flashes
//          and the figures turn red
//  86–92   "0 LEFT" holds, trembling
//  92–98   the SOLD OUT band slams across on the diagonal, big hit
// 104–     subline rises; poster hold, the band's gradient drifts
const ENTER_LEN = 9;
const RACE_AT = 10;
const RACE_END = 56;
const TICK = 3;
const LOW = 10;
const ZERO_HOLD = 6;
const BAND_LEN = 6;

const SLAM = Easing.bezier(0.22, 1, 0.36, 1);
const RACE = Easing.bezier(0.55, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "chrome" (bg #050203): #e0202e #ffd6b8 #4fe3f0.
const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    dim: "#8A8990",
    red: "#F0333F",
    tagInk: "#F3F2EF",
    bandInk: "#0A0A0B",
    flash: "#F3F2EF",
    haze: "#4a0d14",
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#77766F",
    red: "#D41E2C",
    tagInk: "#F5F4F0",
    bandInk: "#0A0A0B",
    flash: "#121214",
    haze: "#ffd6b8",
  },
} as const;
const CHROME = ["#e0202e", "#ff7a6a", "#ffd6b8", "#4fe3f0"];

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 2 frames, eases back over 8. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 8);
  return k * k;
}

/** A decaying shake that dies in 7 frames. Deterministic. */
function shake(d: number, amp: number, seed: number) {
  if (d < 0 || d > 7) return { x: 0, y: 0 };
  const k = (1 - d / 7) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.7 + seed),
    y: amp * 0.7 * k * Math.cos(d * 3.3 + seed * 1.7),
  };
}

/** Continuous stock level at time t (reels read this). */
function level(t: number, stock: number) {
  const low = Math.min(LOW, stock);
  if (t < RACE_AT) return stock;
  if (t < RACE_END) {
    const p = RACE((t - RACE_AT) / (RACE_END - RACE_AT));
    return stock - (stock - low) * p;
  }
  // ten hard ticks: each one rolls its reel in 2 frames
  const d = t - RACE_END;
  const k = Math.floor(d / TICK);
  const f = Math.min(1, (d - k * TICK) / 2);
  const roll = SLAM(f);
  return Math.max(0, low - k - (k < low ? roll : 0));
}

/** Reel position of the digit at place `p` (1, 10, 100…) for level v. */
function reelPos(v: number, p: number) {
  if (p === 1) return v;
  const whole = Math.floor(v / p);
  const rem = v - whole * p;
  return whole + Math.max(0, rem - (p - 1));
}

function SoldOutBase({
  stock = 128,
  unit = "LEFT",
  warning = "LOW STOCK",
  stamp = "SOLD OUT",
  lead = "Restocking:",
  tail = "every launch.",
  theme = "dark",
  speed = 1,
}: SoldOutProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = Math.min(W / 1280, H / 720);
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const total = Math.max(1, Math.round(stock));
  const low = Math.min(LOW, total);
  const zeroAt = RACE_END + low * TICK;
  const bandAt = zeroAt + ZERO_HOLD;
  const places = String(total).length;

  const v = level(t, total);
  const vel = Math.abs(level(t + 0.5, total) - level(t - 0.5, total));
  const shown = Math.round(v);

  // ── Layout: figures (huge) + unit (smaller, on the same baseline) ──
  const unitRatio = 0.34;
  const unitTrack = -0.01;
  const unitEm = textEm(unit, unitTrack) - 0.081 - 0.022;
  const gapEm = 0.16;
  const fullEm = places * CELL + gapEm + unitEm * unitRatio;
  const N = Math.min((0.86 * W) / fullEm, (0.62 * H) / CAP);
  const capH = CAP * N;
  const baseline = H * 0.53 + capH / 2;
  const step = (CAP + 0.14) * N;

  // places fade out as the stock drops below them; the group re-centres
  let visible = 0;
  const placeVis: number[] = [];
  for (let i = 0; i < places; i++) {
    const p = 10 ** (places - 1 - i);
    const keep =
      p === 1 ? 1 : interpolate(v, [p - 0.4, p + 0.05], [0, 1], CLAMP);
    placeVis.push(SLAM(keep));
    visible += SLAM(keep);
  }
  const groupW = visible * CELL * N + gapEm * N + unitEm * unitRatio * N;
  const groupX = (W - groupW) / 2;
  const unitX = groupX + visible * CELL * N + gapEm * N;

  // ── Motion ──
  const enter = SLAM(ramp(t, 0, ENTER_LEN));
  const enterScale = 1.25 - 0.25 * enter;
  const enterBlur = (1 - enter) * 14;
  const isLow = v <= low + 0.01 && t >= RACE_END;
  const lowAt = RACE_END;
  // the tremble grows as the stock drains, then drops away under the band
  const drain = 1 - v / total;
  const band = SLAM(ramp(t, bandAt, BAND_LEN));
  const tremble = 9 * u * drain ** 2.2 * (1 - ramp(t, bandAt, 4));
  let sx =
    tremble * (0.6 * Math.sin(t * 2.31 + 0.4) + 0.4 * Math.sin(t * 5.17 + 1.3));
  let sy =
    tremble * (0.6 * Math.cos(t * 2.83 + 2.1) + 0.4 * Math.sin(t * 4.41 + 0.2));
  let bump = 0;
  for (let k = 0; k < low; k++) {
    const d = t - (RACE_END + k * TICK);
    if (d < 0 || d > 12) continue;
    const g = 0.5 + (0.7 * k) / Math.max(1, low - 1);
    bump = Math.max(bump, 0.6 * g * kick(d));
    const s = shake(d, 5 * u * g, k * 1.9);
    sx += s.x;
    sy += s.y;
  }
  const hitD = t - bandAt - BAND_LEN + 2;
  bump = Math.max(bump, 1.5 * kick(hitD));
  const s3 = shake(hitD, 16 * u, 3.3);
  sx += s3.x;
  sy += s3.y;
  const camScale = 1 + 0.035 * bump;
  const flash = interpolate(
    t,
    [bandAt + BAND_LEN - 2, bandAt + BAND_LEN - 1, bandAt + BAND_LEN + 3],
    [0, 0.32, 0],
    CLAMP,
  );

  const figInk = isLow ? c.red : c.ink;
  const sinceLow = t - lowAt;
  const tagOn =
    t >= lowAt &&
    t < bandAt + 4 &&
    (sinceLow >= 24 || Math.floor(sinceLow / 4) % 2 === 0);
  const tagPop = SLAM(ramp(t, lowAt, 4));
  const behind = ramp(t, bandAt + 1, 8);

  // ── Band ──
  const angle = -11;
  const bandH = 0.34 * H;
  const bandLen = 1.5 * Math.hypot(W, H);
  const bandX = -1.25 * bandLen * (1 - band);
  const stampEm = textEm(stamp, -0.02);
  const stampFs = Math.min((0.9 * W) / stampEm, (bandH * 0.78) / CAP);
  const drift = ramp(t, bandAt, 70);
  const bandGrad = `linear-gradient(90deg, ${CHROME[0]} ${34 - 8 * drift}%, ${CHROME[1]} ${44 - 6 * drift}%, ${CHROME[2]} ${58 - 4 * drift}%, ${CHROME[3]} ${74 - 4 * drift}%)`;
  const rise = SLAM(ramp(t, bandAt + 12, 18));

  const digit = (n: number) => ((n % 10) + 10) % 10;

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      {/* A low red haze creeps up as the stock runs out. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: Math.max(0, drain - 0.4) * (theme === "dark" ? 0.9 : 0.7),
          background: `radial-gradient(80% 60% at 50% 115%, ${c.haze} 0%, transparent 72%)`,
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${sx}px, ${sy}px) scale(${camScale})`,
          transformOrigin: "50% 50%",
        }}
      >
        {/* The counter. */}
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            overflow: "visible",
            opacity: Math.min(ramp(t, 0, 2), 1 - 0.6 * behind),
            transform: `scale(${enterScale * (1 - 0.04 * behind)})`,
            transformOrigin: "50% 52%",
            filter: enterBlur > 0.2 ? `blur(${enterBlur * u}px)` : undefined,
          }}
          role="img"
          aria-label={t >= bandAt ? stamp : `${shown} ${unit}`}
        >
          <defs>
            <linearGradient id={`${uid}feather`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="#fff" stopOpacity={0} />
              <stop offset="0.1" stopColor="#fff" />
              <stop offset="0.9" stopColor="#fff" />
              <stop offset="1" stopColor="#fff" stopOpacity={0} />
            </linearGradient>
            <mask
              id={`${uid}win`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect
                x={0}
                y={baseline - capH - 0.07 * N}
                width={W}
                height={capH + 0.14 * N}
                fill={`url(#${uid}feather)`}
              />
            </mask>
          </defs>

          {/* LOW STOCK tag over the figures. */}
          {tagOn ? (
            <g
              transform={`translate(${groupX} ${baseline - capH - 0.1 * H}) scale(${0.9 + 0.1 * tagPop})`}
            >
              <rect
                x={0}
                y={-0.062 * H}
                width={
                  (textEm(warning.toUpperCase(), 0.06) * 0.042 + 0.036) * H
                }
                height={0.074 * H}
                fill={c.red}
              />
              <text
                x={0.018 * H}
                y={-0.009 * H}
                fontFamily={sans}
                fontWeight={500}
                fontSize={0.042 * H}
                fill={c.tagInk}
                style={{ letterSpacing: "0.06em" }}
              >
                {warning.toUpperCase()}
              </text>
            </g>
          ) : null}

          <g
            fontFamily={sans}
            fontWeight={500}
            fontSize={N}
            textAnchor="middle"
            fill={figInk}
            mask={`url(#${uid}win)`}
            style={{ letterSpacing: "-0.02em" }}
          >
            {placeVis.map((vis, i) => {
              const p = 10 ** (places - 1 - i);
              const r = reelPos(v, p);
              const base = Math.floor(r);
              const f = r - base;
              const x =
                groupX +
                (placeVis.slice(0, i).reduce((a, b) => a + b, 0) + 0.5) *
                  CELL *
                  N;
              const placeVel = vel / p;
              const sd = Math.min(0.22, placeVel * 0.06) * N;
              if (vis < 0.01) return null;
              return (
                <g
                  key={p}
                  opacity={vis}
                  transform={`translate(0 ${-f * step})`}
                >
                  <g filter={sd > 0.3 ? `url(#${uid}b${i})` : undefined}>
                    <text x={x} y={baseline}>
                      {digit(base)}
                    </text>
                    {f > 0.001 ? (
                      <text x={x} y={baseline + step}>
                        {digit(base + 1)}
                      </text>
                    ) : null}
                  </g>
                  <filter
                    id={`${uid}b${i}`}
                    filterUnits="userSpaceOnUse"
                    x={0}
                    y={-H}
                    width={W}
                    height={3 * H}
                  >
                    <feGaussianBlur stdDeviation={`0 ${sd.toFixed(2)}`} />
                  </filter>
                </g>
              );
            })}
          </g>
          <text
            x={unitX - 0.081 * N * unitRatio}
            y={baseline}
            fontFamily={sans}
            fontWeight={500}
            fontSize={N * unitRatio}
            fill={figInk}
            opacity={ramp(t, 2, 6)}
            style={{ letterSpacing: `${unitTrack}em` }}
          >
            {unit}
          </text>
        </svg>

        {/* The SOLD OUT band. */}
        {t >= bandAt ? (
          <div
            style={{
              position: "absolute",
              left: W / 2 - bandLen / 2,
              top: H * 0.5 - bandH / 2,
              width: bandLen,
              height: bandH,
              transform: `rotate(${angle}deg) translateX(${bandX}px)`,
              transformOrigin: "50% 50%",
              background: bandGrad,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              filter:
                band < 0.98 ? `blur(${(1 - band) * 10 * u}px)` : undefined,
            }}
          >
            <div
              style={{
                fontFamily: sans,
                fontStyle: "italic",
                fontWeight: 500,
                fontSize: stampFs,
                lineHeight: 1,
                letterSpacing: "-0.02em",
                color: c.bandInk,
                whiteSpace: "nowrap",
                transform: `translateY(${0.04 * stampFs}px)`,
              }}
            >
              {stamp}
            </div>
          </div>
        ) : null}
      </div>

      {/* Subline. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: H * 0.845,
          display: "flex",
          justifyContent: "center",
          alignItems: "baseline",
          gap: 0.012 * H,
          color: c.ink,
          lineHeight: 1,
          whiteSpace: "nowrap",
          opacity: rise,
          transform: `translateY(${(1 - rise) * 14 * u}px)`,
        }}
      >
        <span
          style={{
            fontFamily: sans,
            fontWeight: 400,
            fontSize: 0.05 * H,
            letterSpacing: "-0.02em",
          }}
        >
          {lead}
        </span>
        <span
          style={{
            fontFamily: serif,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: 0.062 * H,
            letterSpacing: "-0.01em",
          }}
        >
          {tail}
        </span>
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          background: c.flash,
          opacity: flash,
        }}
      />
    </AbsoluteFill>
  );
}

