    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","unit","banner","previousLabel","comparison","label","value","previous","max","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  unit: "km/h",
  banner: "Top speed",
  previousLabel: "2025",
  comparison: "vs last year",
  label: "Speed trap · Sector 3",
  value: 348,
  previous: 300,
  max: 360,
  speed: 1,
};

type SpeedTrapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SpeedTrapBase>;

const SpeedTrapInner = forwardRef<
  HTMLDivElement,
  SpeedTrapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SpeedTrap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SpeedTrapBase
          {...(componentProps as unknown as ComponentProps<typeof SpeedTrapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SpeedTrap = Interactive.withSchema({
  Component: SpeedTrapInner,
  componentName: "<SpeedTrap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Nunito";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const nunito = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface SpellOutProps {
  name?: string;
  line?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#133A24",
    ink: "#EAF7EC",
    accent: "#FFD23F",
    line: "#FFD23F",
  },
  light: {
    bg: "#FFD23F",
    ink: "#133A24",
    accent: "#FFFFFF",
    line: "#133A24",
  },
} as const;

const FONT_PX = 200;
const TRACK = -0.03;
const LINE_TRACK = -0.01;
const SPELL_AT = 4;
const LETTER_GAP = 8;
const FALL = 7;
const HOLD_SPELLED = 14;
const CLOSE_LEN = 20;
const LINE_DELAY = 14;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.85, 0.35);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: number[];
  pos: number[];
  width: number;
  hyphen: number;
  hyphenInk: number;
  asc: number;
  desc: number;
  top: number;
  xh: number;
  lineW: number;
  lineCap: number;
}

function measure(chars: string[], line: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("spell-out: no 2d context");
  const fam = `"${nunito.fontFamily}"`;
  ctx.font = `500 ${FONT_PX}px ${fam}`;
  const adv = chars.map((ch) => ctx.measureText(ch).width / FONT_PX);
  const pos: number[] = [];
  let prefix = "";
  for (let i = 0; i < chars.length; i++) {
    pos.push(prefix ? ctx.measureText(prefix).width / FONT_PX + TRACK * i : 0);
    prefix += chars[i];
  }
  const width =
    ctx.measureText(prefix).width / FONT_PX + TRACK * (chars.length - 1);
  const hm = ctx.measureText("-");
  const fm = ctx.measureText(prefix || "x");
  const metrics = ctx.measureText("Hg");
  ctx.font = `500 ${FONT_PX}px ${fam}`;
  const lm = ctx.measureText(line || " ");
  return {
    adv,
    pos,
    width,
    hyphen: hm.width / FONT_PX,
    hyphenInk: (hm.actualBoundingBoxRight + hm.actualBoundingBoxLeft) / FONT_PX,
    asc: metrics.fontBoundingBoxAscent / FONT_PX,
    desc: metrics.fontBoundingBoxDescent / FONT_PX,
    top: fm.actualBoundingBoxAscent / FONT_PX,
    xh: ctx.measureText("x").actualBoundingBoxAscent / FONT_PX,
    lineW:
      lm.width / FONT_PX +
      LINE_TRACK * Math.max(0, Array.from(line).length - 1),
    lineCap: ctx.measureText("H").actualBoundingBoxAscent / FONT_PX,
  };
}

function useMetrics(chars: string[], line: string) {
  const key = chars.join("");
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("spell-out: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      nunito.waitUntilDone(),
      document.fonts.load(`500 100px "${nunito.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(Array.from(key), line));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, line, handle]);
  return metrics;
}

function impact(u: number) {
  if (u < 0) return 0;
  return Math.exp(-u / 3.6) * Math.cos(u * 0.55);
}

export function SpellOut({
  name = "remocn",
  line = "Say it once. Remember it.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: SpellOutProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const dash = accent ?? c.accent;
  const chars = useMemo(() => Array.from(name.replace(/\s+/g, "")), [name]);
  const m = useMetrics(chars, line);

  if (!m || chars.length === 0) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const n = chars.length;
  const gap = 0.07;
  const unit = m.hyphen + gap * 2;
  const spelled: number[] = [];
  let run = 0;
  for (let i = 0; i < n; i++) {
    spelled.push(run);
    run += m.adv[i] + (i < n - 1 ? unit : 0);
  }
  const spelledW = run;
  const S = Math.min((W * 0.9) / spelledW, H * 0.3);
  const lineSize0 = line ? Math.min(H * 0.088, (W * 0.8) / m.lineW) : 0;
  const F0 = Math.min((W * 0.84) / m.width, H * 0.42);
  const lineGap = line ? F0 * 0.34 : 0;
  const blockH = m.top * F0 + lineGap + (line ? m.lineCap * lineSize0 : 0);
  const F = F0;
  const finalBase = (H - blockH) / 2 + m.top * F;
  const spellBase = H / 2 + (m.xh * S) / 2;
  const R = Math.max(S, F);
  const lh = R * 1.4;
  const bo = (lh - (m.asc + m.desc) * R) / 2 + m.asc * R;

  const lastLand = SPELL_AT + (n - 1) * LETTER_GAP + FALL;
  const closeAt = lastLand + HOLD_SPELLED;
  const close = interpolate(t, [closeAt, closeAt + CLOSE_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_IN_OUT,
  });
  const size = S + (F - S) * close;
  const spellLeft = (W - spelledW * S) / 2;
  const finalLeft = (W - m.width * F) / 2;
  const base = spellBase + (finalBase - spellBase) * close;

  const nodes: React.ReactNode[] = [];
  for (let i = 0; i < n; i++) {
    const landAt = SPELL_AT + i * LETTER_GAP + FALL;
    const fall = interpolate(t, [landAt - FALL, landAt], [0, 1], {
      ...CLAMP,
      easing: EASE_IN,
    });
    if (t < landAt - FALL) continue;
    const x0 = spellLeft + spelled[i] * S;
    const x1 = finalLeft + m.pos[i] * F;
    const x = x0 + (x1 - x0) * close;
    const dy = (1 - fall) * -S * 0.9;
    const air = fall < 1 ? Math.sin(fall * Math.PI * 0.5) : 1;
    const stretch = fall < 1 ? 0.22 * air : 0;
    const q = impact(t - landAt);
    const centre = (n - 1) / 2;
    const settleAt = closeAt + CLOSE_LEN - 2 + Math.abs(i - centre) * 1.5;
    const q2 = impact(t - settleAt) * 0.6;
    const sy = 1 + stretch - 0.2 * q - 0.12 * q2;
    const sx = 1 - stretch * 0.5 + 0.12 * q + 0.08 * q2;
    const s = size / R;
    const o = interpolate(fall, [0, 0.35], [0, 1], CLAMP);
    nodes.push(
      <div
        key={`l${i}`}
        style={{
          position: "absolute",
          left: x + (m.adv[i] * (size - R)) / 2,
          top: base - bo + dy,
          height: lh,
          fontFamily: nunito.fontFamily,
          fontWeight: 500,
          fontSize: R,
          lineHeight: `${lh}px`,
          whiteSpace: "pre",
          color: c.ink,
          opacity: o,
          transform: `scale(${(s * sx).toFixed(4)}, ${(s * sy).toFixed(4)})`,
          transformOrigin: `${((m.adv[i] * R) / 2).toFixed(1)}px ${bo.toFixed(1)}px`,
        }}
      >
        {chars[i]}
      </div>,
    );
    if (i < n - 1) {
      const born = landAt + 1;
      const hp = interpolate(t, [born, born + 7], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const shrink = 1 - close;
      if (hp > 0 && shrink > 0.001) {
        const nextX0 = spellLeft + spelled[i + 1] * S;
        const nextX1 = finalLeft + m.pos[i + 1] * F;
        const nx = nextX0 + (nextX1 - nextX0) * close;
        const mid = (x + m.adv[i] * size + nx) / 2;
        const barH = S * 0.1;
        const barW = Math.max(
          barH * shrink,
          m.hyphenInk * S * shrink * (0.4 + 0.6 * hp),
        );
        nodes.push(
          <div
            key={`h${i}`}
            style={{
              position: "absolute",
              left: mid - barW / 2,
              top: base - m.xh * size * 0.5 - (barH * shrink) / 2,
              width: barW,
              height: barH * Math.max(0.3, shrink),
              borderRadius: barH,
              background: dash,
              opacity: hp * Math.min(1, shrink * 2.5),
            }}
          />,
        );
      }
    }
  }

  const lineAt = closeAt + CLOSE_LEN - 4 + LINE_DELAY - 10;
  const lp = interpolate(t, [lineAt, lineAt + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lineBase = finalBase + lineGap + m.lineCap * lineSize0;
  const llh = lineSize0 * 1.45;
  const lbo = (llh - (m.asc + m.desc) * lineSize0) / 2 + m.asc * lineSize0;

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {nodes}
      {line ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: lineBase - lbo,
            height: llh,
            overflow: "hidden",
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              fontFamily: nunito.fontFamily,
              fontWeight: 500,
              fontSize: lineSize0,
              lineHeight: `${llh}px`,
              letterSpacing: `${LINE_TRACK}em`,
              color: c.line,
              whiteSpace: "pre",
              transform: `translateY(${((1 - lp) * llh).toFixed(2)}px)`,
            }}
          >
            {line}
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

import { loadFont as loadPlexSans } from "@remotion/google-fonts/IBMPlexSans";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const plex = loadPlexSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface SpineTurnProps {
  titles?: string[];
  hold?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0F1B2D",
    spine: "#7D8CA3",
    rule: "rgba(243, 245, 248, 0.22)",
    accent: "#FF9900",
  },
  light: {
    bg: "#FFFFFF",
    spine: "#8A96A8",
    rule: "rgba(15, 27, 45, 0.2)",
    accent: "#C76A00",
  },
} as const;

const TRACK = -0.035;
const SPINE_TRACK = -0.01;
const BOX = 1.0;
const BASE = 0.8;

const ENTER = 16;
const TURN = 26;
const NEXT_LAG = 14;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_TURN = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function measure(titles: string[]) {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("spine-turn: no 2d context");
  ctx.font = `500 100px "${plex.fontFamily}"`;
  return titles.map((s) => {
    const n = Array.from(s).length;
    return {
      hero: ctx.measureText(s).width / 100 + TRACK * Math.max(0, n - 1),
      spine: ctx.measureText(s).width / 100 + SPINE_TRACK * Math.max(0, n - 1),
    };
  });
}

function useWidths(titles: string[]) {
  const key = titles.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: { hero: number; spine: number }[];
  } | null>(null);
  const [handle] = useState(() => delayRender("spine-turn: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      plex.waitUntilDone(),
      document.fonts.load(`500 100px "${plex.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, w: measure(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.w : null;
}

function SpineTurnBase({
  titles = ["Kickoff", "Deep dive", "Wrap-up"],
  hold = 26,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: SpineTurnProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const list = useMemo(() => {
    const l = titles.filter((s) => s.trim().length > 0);
    return l.length > 0 ? l : ["remocn"];
  }, [titles]);
  const widths = useWidths(list);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!widths) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const margin = Math.min(W, H) * 0.08;
  const ruleY = H - margin;

  const spineLen = H - margin * 2.4;
  const longest = Math.max(...widths.slice(0, -1).map((w) => w.spine), 0.01);
  const S = Math.min(
    spineLen / longest,
    Math.min(W, H) * (portrait ? 0.13 : 0.16),
  );
  const spineCol = S * BOX * 0.86;
  const spineGap = S * 0.3;

  const turnAt = (k: number) => ENTER + hold + k * (TURN + NEXT_LAG + hold);

  const heroOf = (k: number) => {
    const areaL = margin + k * (spineCol + spineGap) + (k > 0 ? S * 0.5 : 0);
    const areaW = W - margin - areaL;
    const F = Math.min(
      (areaW * 0.94) / widths[k].hero,
      H * (portrait ? 0.18 : 0.46),
    );
    const x = areaL;
    const baseline = ruleY - F * 0.26;
    return { F, x, baseline };
  };

  const spineOf = (k: number) => {
    const x = margin + k * (spineCol + spineGap) + S * 0.78;
    const y = ruleY - S * 0.3;
    return { x, y };
  };

  const els: React.ReactNode[] = [];
  list.forEach((title, k) => {
    const isLast = k === n - 1;
    const hero = heroOf(k);
    const enterAt = k === 0 ? 0 : turnAt(k - 1) + NEXT_LAG;
    const enter = interpolate(t, [enterAt, enterAt + ENTER], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    if (enter <= 0) return;
    const turn = isLast
      ? 0
      : interpolate(t, [turnAt(k), turnAt(k) + TURN], [0, 1], {
          ...CLAMP,
          easing: EASE_TURN,
        });
    const spine = spineOf(k);
    const ox = hero.x + (spine.x - hero.x) * turn;
    const oy = hero.baseline + (spine.y - hero.baseline) * turn;
    const size = hero.F + (S - hero.F) * turn;
    const track = TRACK + (SPINE_TRACK - TRACK) * turn;
    const rot = -90 * turn;

    const glyphs = (
      <div
        key="glyphs"
        style={{
          position: "absolute",
          left: 0,
          top: -BASE * size,
          height: BOX * size,
          lineHeight: `${BOX * size}px`,
          whiteSpace: "pre",
          fontFamily: plex.fontFamily,
          fontWeight: 500,
          fontSize: size,
          letterSpacing: `${track}em`,
          color:
            turn > 0
              ? `color-mix(in oklab, ${c.spine} ${(Math.min(1, turn * 1.4) * 100).toFixed(1)}%, ${accent ?? c.accent})`
              : (accent ?? c.accent),
        }}
      >
        {title}
      </div>
    );

    const masked = enter < 1;
    els.push(
      <div
        key={`t${k}`}
        style={{
          position: "absolute",
          left: ox,
          top: oy,
          width: 0,
          height: 0,
          transform: `rotate(${rot.toFixed(3)}deg)`,
          transformOrigin: "0 0",
        }}
      >
        {masked ? (
          <div
            style={{
              position: "absolute",
              left: -size * 0.2,
              top: -BASE * size - size * 0.1,
              width: widths[k].hero * size + size * 0.4,
              height: BOX * size + size * 0.12,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: size * 0.2,
                top: BASE * size + size * 0.1 + (1 - enter) * BOX * size * 1.05,
              }}
            >
              {glyphs}
            </div>
          </div>
        ) : (
          glyphs
        )}
      </div>,
    );
  });

  const ruleP = interpolate(t, [0, ENTER + 6], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: margin,
          top: ruleY,
          width: (W - margin * 2) * ruleP,
          height: Math.max(1, H * 0.0016),
          background: c.rule,
        }}
      />
      {els}
    </AbsoluteFill>
  );
}

const elementSchema = {
