import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { forwardRef, useCallback, useEffect, useId, useImperativeHandle, useMemo, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const bricolage = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

interface SplitMatchProps {
  /**
   * Words in order; the reels lock on each one, the last one is the poster.
   * "remocn" is set as the real logo (R mark + "emocn" in Manrope).
   */
  words?: string[];
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps), four words:
//  0–10    both reels slam in from opposite sides and lock on word 1
//  10–26   hold: left half on stage, right half on a gradient panel, one word
//  26–35   step: left reel climbs, right reel drops, halves blur past each other
//  ...     two more step + lock beats
//  85      final lock on the last word
//  93–109  the seam closes: the gradient floods the left panel, neighbours fall away
//  109–145 poster hold with a slow push
const ENTER = 10;
const HOLD = 16;
const STEP = 9;
const MERGE_DELAY = 8;
const MERGE = 16;
const TAIL = 36;

function splitMatchDuration(wordCount = 4) {
  return (
    ENTER +
    Math.max(0, wordCount - 1) * (HOLD + STEP) +
    MERGE_DELAY +
    MERGE +
    TAIL
  );
}

