const ELEMENT_PROP_KEYS = new Set(["theme","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  speed: 1,
};

type SplitMatchElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SplitMatchBase>;

const SplitMatchInner = forwardRef<
  HTMLDivElement,
  SplitMatchElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SplitMatch>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SplitMatchBase
          {...(componentProps as unknown as ComponentProps<typeof SplitMatchBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SplitMatch = Interactive.withSchema({
  Component: SplitMatchInner,
  componentName: "<SplitMatch>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

