const MESH = ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    label: "#8C8B91",
    stops: (a: string) => [MESH[0], MESH[1], a, MESH[1]],
