  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  value: {
    type: "text-content",
    default: "12,480",
    description: "Value",
  },
  text: {
    type: "text-content",
    default: "Builders shipped {value} launch videos with remocn this year.",
    description: "Text",
  },
  label: {
    type: "text-content",
    default: "Launch videos shipped",
    description: "Label",
  },
  align: {
    type: "enum",
    default: "left",
    variants: {
      left: {},
