    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","text","label","align","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "12,480",
  text: "Builders shipped {value} launch videos with remocn this year.",
  label: "Launch videos shipped",
  align: "left",
  speed: 1,
};

type StatInlineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof StatInlineBase>;

const StatInlineInner = forwardRef<
  HTMLDivElement,
  StatInlineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<StatInline>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <StatInlineBase
          {...(componentProps as unknown as ComponentProps<typeof StatInlineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const StatInline = Interactive.withSchema({
  Component: StatInlineInner,
  componentName: "<StatInline>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

