/**
 * Per-glyph slot motion: each glyph rises from below the mask on `enter`,
 * leaves through the top on `exit`. Returns y in % of the line box and a
 * small blur while the glyph is travelling fast.
 */
function glyph(
  t: number,
  i: number,
  enter: number,
  exit: number,
  stagger: number,
) {
  const e = interpolate(
    t,
    [enter + i * stagger, enter + i * stagger + 12],
    [0, 1],
    { ...CLAMP, easing: EASE_LAND },
  );
  const x = interpolate(t, [exit + i * 0.4, exit + i * 0.4 + 5], [0, 1], {
    ...CLAMP,
    easing: EASE_IN,
  });
  const y = (1 - e) * 108 - x * 108;
  const raw = interpolate(
    t,
    [enter + i * stagger, enter + i * stagger + 6],
    [1, 0],
    CLAMP,
  );
  const blur = raw + x * (1 - x) * 4;
  return { y, blur, visible: e > 0 && x < 1 };
}

function SlotText({
  text,
  t,
  enter,
  exit,
  stagger,
  u,
  style,
  glyphStyle,
}: {
  text: string;
  t: number;
  enter: number;
  exit: number;
  stagger: number;
  u: number;
  style?: React.CSSProperties;
  /** Per-glyph paint, e.g. a clip-text gradient (each glyph box is 1em tall). */
  glyphStyle?: React.CSSProperties;
}) {
  return (
    <span style={{ display: "inline-flex", whiteSpace: "pre", ...style }}>
      {[...text].map((ch, i) => {
        const g = glyph(t, i, enter, exit, stagger);
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              ...glyphStyle,
              transform: `translateY(${g.y}%)`,
              filter: g.blur > 0.05 ? `blur(${g.blur * 3 * u}px)` : undefined,
              visibility: g.visible ? "visible" : "hidden",
            }}
          >
            {ch}
          </span>
        );
      })}
    </span>
  );
}

/** The monumental number + its small accent unit, inside one mask. */
function Figure({
  stat,
  t,
  enter,
  exit,
  size,
  u,
  c,
  accent,
}: {
  stat: Stat;
  t: number;
  enter: number;
  exit: number;
  size: number;
  u: number;
  c: Theme;
  accent: string;
}) {
  const unitIndex = [...stat.value].length;
  const ug = glyph(t, unitIndex + 1, enter, exit, 1.6);
  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        overflow: "hidden",
        padding: `${0.06 * size}px ${0.04 * size}px ${0.02 * size}px 0`,
        fontFamily: sans,
        fontWeight: 400,
        fontSize: size,
        lineHeight: 1,
        letterSpacing: "-0.042em",
        fontVariantNumeric: "tabular-nums",
        color: c.fg,
      }}
    >
      <SlotText
        text={stat.value}
        t={t}
        enter={enter}
        exit={exit}
        stagger={1.6}
        u={u}
        glyphStyle={{
          backgroundImage: c.ink,
          backgroundSize: "100% 100%",
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }}
      />
      {stat.unit ? (
        <span
          style={{
            display: "inline-flex",
            marginLeft: 0.04 * size,
            marginTop: 0.1 * size,
            transform: `translateY(${ug.y * 2.2}%)`,
            visibility: ug.visible ? "visible" : "hidden",
            color: accent,
            fontSize: 0.46 * size,
            lineHeight: 1,
            letterSpacing: 0,
          }}
        >
          {stat.unit === "★" ? (
            <Star size={0.42 * size} color={accent} />
          ) : (
            stat.unit
          )}
        </span>
      ) : null}
    </div>
  );
}

/** Label + detail, each line rising through its own mask. */
function Caption({
  stat,
  t,
  enter,
  exit,
  labelSize,
  detailSize = labelSize * 0.56,
  c,
}: {
  stat: Stat;
  t: number;
  enter: number;
  exit: number;
  labelSize: number;
  detailSize?: number;
  c: Theme;
}) {
  const line = (k: number) => {
    const e = interpolate(t, [enter + k * 3, enter + k * 3 + 14], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const x = interpolate(t, [exit + k, exit + k + 5], [0, 1], {
      ...CLAMP,
      easing: EASE_IN,
    });
    return `translateY(${(1 - e) * 110 - x * 110}%)`;
  };
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 0.22 * labelSize,
      }}
    >
      <div style={{ overflow: "hidden", paddingBottom: 0.12 * labelSize }}>
        <div
          style={{
            transform: line(0),
            fontFamily: sans,
            fontWeight: 500,
            fontSize: labelSize,
            lineHeight: 1.05,
            letterSpacing: "-0.025em",
            color: c.fg,
            whiteSpace: "nowrap",
          }}
        >
          {stat.label}
        </div>
      </div>
      {stat.detail ? (
        <div style={{ overflow: "hidden", paddingBottom: 0.1 * labelSize }}>
          <div
            style={{
              transform: line(1),
              fontFamily: sans,
              fontWeight: 400,
              fontSize: detailSize,
              lineHeight: 1.2,
              letterSpacing: "-0.005em",
              color: c.muted,
              whiteSpace: "nowrap",
            }}
          >
            {stat.detail}
          </div>
        </div>
      ) : null}
    </div>
  );
}

export function StatSequence({
  stats = DEFAULT_STATS,
  name = "remocn",
  eyebrow = "in numbers",
  logo,
  beat = 26,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: StatSequenceProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = frame * speed;
  const u = Math.min(width / 1280, height / 720);
  const c = THEMES[theme];
  const n = Math.max(1, stats.length);

  const START = 8;
  const inAt = (i: number) => START + i * beat;
  const lastIn = inAt(n - 1);
  const M = lastIn + 42; // the hero stat starts moving into the summary row
  const MORPH = 24;

  const F = 196 * u; // monumental size
  const L = width * 0.08; // left rule of the frame
  const pad = 30 * u;
  const colW = (width - 2 * L) / n;
  const S = Math.min(0.42, (colW - pad * 1.6) / (F * 3.4)); // summary scale
  const bigTop = height / 2 - F * 0.6;
  const rowTop = height / 2 - (F * S * 1.12 + 70 * u) / 2;

  const mp = interpolate(t, [M, M + MORPH], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // slow camera drift over the whole shot
  const drift = interpolate(t, [0, M + MORPH + 40], [0, 1], CLAMP);

  // accent bar: the cut marker. Grows from below on the first stat, swipes
  // up-and-out / up-and-in on every cut, retires as the row assembles.
  const barTop = bigTop + 0.18 * F;
  const barH = 0.72 * F;
  let barScale = interpolate(t, [inAt(0) - 2, inAt(0) + 10], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  let barOrigin = "bottom";
  for (let i = 1; i < n; i++) {
    const cut = inAt(i);
    if (t >= cut - 4 && t < cut + 1) {
      barScale = interpolate(t, [cut - 4, cut + 1], [1, 0], {
        ...CLAMP,
        easing: EASE_IN,
      });
      barOrigin = "top";
    } else if (t >= cut + 1 && t < cut + 10) {
      barScale = interpolate(t, [cut + 1, cut + 10], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      barOrigin = "bottom";
    }
  }
  if (t >= M - 2) {
    barScale = interpolate(t, [M - 2, M + 8], [1, 0], {
      ...CLAMP,
      easing: EASE_IN,
    });
    barOrigin = "top";
  }

  // index ticker, bottom left
  const idxSize = 15 * u;

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      {/* mesh ground: three soft blobs that drift a few % over the shot */}
      <AbsoluteFill
        style={{
          background: c.mesh.join(", "),
          transform: `translate(${drift * 3}%, ${-drift * 2}%) scale(${1.04 + drift * 0.04})`,
        }}
      />

      <AbsoluteFill
        style={{
          transform: `scale(${1 + drift * 0.025}) translateX(${-drift * 6 * u}px)`,
          transformOrigin: "40% 50%",
        }}
      >
        {/* corner lockup */}
        <div
          style={{
            position: "absolute",
            left: L,
            top: 52 * u,
            display: "flex",
            alignItems: "center",
            gap: 10 * u,
            fontFamily: sans,
            fontSize: 17 * u,
            lineHeight: 1,
            opacity: interpolate(t, [0, 12], [0, 1], CLAMP),
            transform: `translateY(${interpolate(t, [0, 16], [8, 0], { ...CLAMP, easing: EASE_OUT }) * u}px)`,
          }}
        >
          {logo ??
            (name.trim().toLowerCase() === "remocn" ? (
              <RemocnLogo fontSize={21 * u} color={c.fg} />
            ) : (
              <span
                style={{
                  color: c.fg,
                  fontWeight: 500,
                  fontSize: 19 * u,
                  letterSpacing: "-0.02em",
                }}
              >
                {name}
              </span>
            ))}
          <span
            style={{
              width: Math.max(1, u),
              height: 16 * u,
              background: c.hair,
              margin: `0 ${2 * u}px`,
            }}
          />
          <span style={{ color: c.muted, fontWeight: 400 }}>{eyebrow}</span>
        </div>

        {/* the accent cut bar */}
        <div
          style={{
            position: "absolute",
            left: L,
            top: barTop,
            width: 5 * u,
            height: barH,
            borderRadius: 3 * u,
            background: c.bar,
            transform: `scaleY(${barScale})`,
            transformOrigin: barOrigin,
          }}
        />

        {/* one monumental stat at a time */}
        {stats.map((stat, i) => {
          const isLast = i === n - 1;
          const enter = inAt(i);
          const exit = isLast ? 1e9 : inAt(i + 1) - 5;
          if (t < enter - 1 || t > exit + 14) return null;
          const tx = isLast ? (n - 1) * colW * mp : 0;
          const ty = isLast ? (rowTop - bigTop) * mp : 0;
          const sc = isLast ? 1 + (S - 1) * mp : 1;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: L + pad,
                top: bigTop,
                display: "flex",
                alignItems: "flex-end",
                gap: 34 * u,
                transformOrigin: "0 0",
                transform: `translate(${tx}px, ${ty}px) scale(${sc})`,
              }}
            >
              <Figure
                stat={stat}
                t={t}
                enter={enter}
                exit={exit}
                size={F}
                u={u}
                c={c}
                accent={accent}
              />
              <div style={{ paddingBottom: 0.2 * F }}>
                <Caption
                  stat={stat}
                  t={t}
                  enter={enter + 5}
                  exit={isLast ? M - 6 : exit}
                  labelSize={34 * u}
                  c={c}
                />
              </div>
            </div>
          );
        })}

        {/* summary row: column rules, the other figures, labels below */}
        {stats.map((stat, i) => {
          const colLeft = L + i * colW;
          const ruleP = interpolate(
            t,
            [M + 6 + i * 3, M + 24 + i * 3],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
          const isLast = i === n - 1;
          const figEnter = M + 8 + i * 4;
          return (
            <div key={`row-${i}`}>
              <div
                style={{
                  position: "absolute",
                  left: colLeft,
                  top: rowTop - 6 * u,
                  width: Math.max(1, u),
                  height: F * S + 120 * u,
                  background: c.hair,
                  transform: `scaleY(${ruleP})`,
                  transformOrigin: "top",
                }}
              />
              {!isLast && t >= figEnter - 1 ? (
                <div
                  style={{
                    position: "absolute",
                    left: colLeft + pad,
                    top: rowTop,
                    transformOrigin: "0 0",
                    transform: `scale(${S})`,
                  }}
                >
                  <Figure
                    stat={stat}
                    t={t}
                    enter={figEnter}
                    exit={1e9}
                    size={F}
                    u={u}
                    c={c}
                    accent={accent}
                  />
                </div>
              ) : null}
              <div
                style={{
                  position: "absolute",
                  left: colLeft + pad,
                  top: rowTop + F * S * 1.12 + 14 * u,
                }}
              >
                <Caption
                  stat={stat}
                  t={t}
                  enter={M + 16 + i * 4}
                  exit={1e9}
                  labelSize={22 * u}
                  detailSize={15 * u}
                  c={c}
                />
              </div>
            </div>
          );
        })}

        {/* index ticker */}
        <div
          style={{
            position: "absolute",
            left: L,
            bottom: 48 * u,
            display: "flex",
            alignItems: "center",
            gap: 8 * u,
            fontFamily: mono,
            fontWeight: 400,
            fontSize: idxSize,
            lineHeight: 1,
            fontVariantNumeric: "tabular-nums",
            color: c.muted,
            opacity:
              interpolate(t, [2, 12], [0, 1], CLAMP) *
              interpolate(t, [M, M + 10], [1, 0], CLAMP),
          }}
        >
          <span
            style={{
              position: "relative",
              display: "inline-block",
              overflow: "hidden",
              height: idxSize * 1.15,
              width: idxSize * 1.4,
              color: c.fg,
            }}
          >
            {stats.map((_, i) => (
              <span
                key={i}
                style={{ position: "absolute", left: 0, top: idxSize * 0.06 }}
              >
                <SlotText
                  text={String(i + 1).padStart(2, "0")}
                  t={t}
                  enter={i === 0 ? 2 : inAt(i)}
                  exit={i === n - 1 ? 1e9 : inAt(i + 1) - 5}
                  stagger={1}
                  u={u * 0.3}
                />
              </span>
            ))}
          </span>
          <span
            style={{
              width: 18 * u,
              height: Math.max(1, u),
              background: c.hair,
            }}
          />
          <span>{String(n).padStart(2, "0")}</span>
        </div>
      </AbsoluteFill>

      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

import { loadFont as loadInstrument } from "@remotion/google-fonts/InstrumentSans";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const instrument = loadInstrument("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface StemStretchProps {
  value?: string;
  label?: string;
  steps?: number;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#0A0A0B", ink: "#F4F3F0", muted: "#8E8D94", grain: 0.05 },
  light: { bg: "#F5F4F0", ink: "#121214", muted: "#6E6C67", grain: 0.035 },
};

const STRETCH = {
  dark: (accent: string) =>
    `linear-gradient(180deg, #F4F3F0 0%, #FFF1E2 8%, #FF8A3D 34%, #C2452A 58%, ${accent} 92%, #F4F3F0 100%)`,
  light: (accent: string) =>
    `linear-gradient(180deg, #121214 0%, #3A1A14 6%, #F2552C 34%, #E889B5 62%, ${accent} 92%, #121214 100%)`,
};
const GLOW = {
  dark: "radial-gradient(60% 50% at 50% 50%, color-mix(in oklab, #ff8a3d 10%, transparent) 0%, transparent 70%), radial-gradient(80% 50% at 50% 115%, color-mix(in oklab, #a3301a 30%, transparent) 0%, transparent 70%)",
  light:
    "radial-gradient(60% 50% at 50% 50%, color-mix(in oklab, #f7b23b 12%, transparent) 0%, transparent 70%), radial-gradient(80% 50% at 50% 115%, color-mix(in oklab, #f2552c 12%, transparent) 0%, transparent 70%)",
};

const TRACK = -0.035;
const RISE_LEN = 18;
const RISE_GAP = 3;
const SNAP_AT = 26;
const SNAP_GAP = 12;
const LABEL_AT = 66;
const SLICE = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const FONT_PX = 400;

interface Metrics {
  width: number;
  label: number;
  adv: number[];
  baseline: number;
  cap: number;
  cut: number;
  desc: number;
}

function findCut(ctx: CanvasRenderingContext2D, text: string, cap: number) {
  const W = Math.ceil(ctx.measureText(text).width) + 40;
  const H = Math.ceil(FONT_PX * 1.4);
  ctx.canvas.width = W;
  ctx.canvas.height = H;
  ctx.font = `500 ${FONT_PX}px "${instrument.fontFamily}"`;
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#000";
  const base = Math.round(FONT_PX * 1.1);
  ctx.fillText(text, 20, base);
  const data = ctx.getImageData(0, 0, W, H).data;
  const a = (x: number, y: number) => data[(y * W + x) * 4 + 3];
  const capPx = cap * FONT_PX;
  let best = 0.45;
  let bestScore = Number.POSITIVE_INFINITY;
  for (let f = 0.3; f <= 0.66; f += 0.01) {
    const y = Math.round(base - capPx * f);
    let diff = 0;
    let ink = 0;
    for (let x = 0; x < W; x++) {
      const v = a(x, y);
      ink += v;
      diff += Math.abs(v - a(x, y - 3)) + Math.abs(v - a(x, y + 3));
    }
    if (ink === 0) continue;
    const score = diff / ink + Math.abs(f - 0.48) * 0.6;
    if (score < bestScore) {
      bestScore = score;
      best = f;
    }
  }
  return best * cap;
}

function measure(text: string, label: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) throw new Error("stem-stretch: no 2d context");
  ctx.font = `500 ${FONT_PX}px "${instrument.fontFamily}"`;
  const chars = Array.from(text);
  const adv = chars.map((ch) => ctx.measureText(ch).width / FONT_PX + TRACK);
  const width =
    ctx.measureText(text).width / FONT_PX +
    TRACK * Math.max(0, chars.length - 1);
  const fm = ctx.measureText("H");
  const asc = fm.fontBoundingBoxAscent / FONT_PX;
  const desc = fm.fontBoundingBoxDescent / FONT_PX;
  const cap = fm.actualBoundingBoxAscent / FONT_PX;
  const inkDesc = Math.max(
    0,
    ctx.measureText(text).actualBoundingBoxDescent / FONT_PX,
  );
  ctx.font = `400 ${FONT_PX}px "${instrument.fontFamily}"`;
  const lab = label ? ctx.measureText(label).width / FONT_PX : 0;
  const cut = findCut(ctx, text, cap);
  return {
    width,
    label: lab,
    adv,
    baseline: (1 - (asc + desc)) / 2 + asc,
    cap,
    cut,
    desc: inkDesc,
  };
}

function useMetrics(text: string, label: string) {
  const key = `${text}\u0000${label}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("stem-stretch: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [tx, lb] = key.split("\u0000");
    Promise.all([
      instrument.waitUntilDone(),
      document.fonts.load(`500 100px "${instrument.fontFamily}"`),
      document.fonts.load(`400 100px "${instrument.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(tx, lb) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state?.m ?? null;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `ss${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function StemStretchBase({
  value = "4 hours",
  label = "back, every week",
  steps = 4,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: StemStretchProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const m = useMetrics(value, label);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: c.bg }} />;
  }

  const n = Math.max(1, Math.round(steps));
  const portrait = H > W;
  const F = Math.min(H * (portrait ? 0.2 : 0.3), (W * 0.84) / m.width);
  const capPx = m.cap * F;
  const gapMax = Math.max(capPx * 0.6, H * (portrait ? 0.42 : 0.62) - capPx);
  const block = gapMax / n;

  let snapped = 0;
  for (let k = 0; k < n; k++) {
    snapped += spring({
      frame: t - (SNAP_AT + k * SNAP_GAP),
      fps,
      config: { damping: 13, stiffness: 210, mass: 0.7 },
    });
  }
  const gap = block * snapped;

  const labelSize = Math.min(
    Math.max(F * 0.17, H * 0.044),
    H * 0.056,
    (W * 0.84) / Math.max(0.1, m.label),
  );
  const labelGap = label ? Math.max(F * 0.2, H * 0.04) : 0;
  const groupH = capPx + gap + (label ? labelGap + labelSize : 0);
  const capTop = (H - groupH) / 2;
  const baseY = capTop + capPx + gap;
  const lineTop0 = capTop + capPx - m.baseline * F;
  const cutY0 = capTop + capPx - m.cut * F;
  const left = (W - m.width * F) / 2;

  const chars = Array.from(value);
  const glyphs = (keyPrefix: string, style: React.CSSProperties) => {
    let x = 0;
    return chars.map((ch, i) => {
      const gx = x;
      x += m.adv[i] * F;
      const p = interpolate(
        t,
        [i * RISE_GAP - 2, i * RISE_GAP - 2 + RISE_LEN],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      return (
        <span
          key={`${keyPrefix}-${i}-${ch}`}
          style={{
            position: "absolute",
            left: gx,
            top: 0,
            transform: `translateY(${((1 - p) * F * 0.9).toFixed(2)}px)`,
            ...style,
          }}
        >
          {ch}
        </span>
      );
    });
  };

  const lineStyle: React.CSSProperties = {
    position: "absolute",
    left,
    width: m.width * F + F,
    height: F,
    lineHeight: `${F}px`,
    whiteSpace: "pre",
    fontFamily: instrument.fontFamily,
    fontWeight: 500,
    fontSize: F,
    fontFeatureSettings: '"tnum" 1',
  };

  const k = gap / SLICE;
  const cutLocal = cutY0 - lineTop0;
  const drift = (t / 30) * 2;
  const stretchFill = STRETCH[theme](accent);
  const groupBg = theme === "dark" ? "#000" : "#fff";
  const groupInk = theme === "dark" ? "#fff" : "#000";

  const maskTop = capTop - F * 0.3;

  const labelWords = label ? label.split(" ") : [];

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: GLOW[theme],
          transform: `translateY(${(Math.sin(drift * 0.3) * H * 0.01).toFixed(2)}px)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: maskTop,
          height: cutY0 - maskTop,
          overflow: "hidden",
        }}
      >
        <div style={{ ...lineStyle, top: lineTop0 - maskTop, color: c.ink }}>
          {glyphs("top", {})}
        </div>
      </div>
      {gap > 0.5 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: cutY0,
            height: gap,
            overflow: "hidden",
            isolation: "isolate",
            background: groupBg,
            mixBlendMode: theme === "dark" ? "screen" : "multiply",
          }}
        >
          <div
            style={{
              ...lineStyle,
              top: -cutLocal,
              transformOrigin: `0 ${cutLocal}px`,
              transform: `scaleY(${k.toFixed(3)})`,
              color: groupInk,
            }}
          >
            {glyphs("mid", {})}
          </div>
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundImage: stretchFill,
              backgroundSize: "100% 114%",
              backgroundPosition: `0 ${(50 + Math.sin(drift * 0.5) * 45).toFixed(2)}%`,
              mixBlendMode: theme === "dark" ? "multiply" : "screen",
            }}
          />
          {Array.from({ length: n - 1 }, (_, j) => {
            const y = (j + 1) * block;
            if (y >= gap - 1) return null;
            return (
              <div
                key={`tick-${j}`}
                style={{
                  position: "absolute",
                  left: left - F * 0.04,
                  width: m.width * F + F * 0.08,
                  top: y - Math.max(1, F * 0.016),
                  height: Math.max(2, F * 0.032),
                  background: groupBg,
                }}
              />
            );
          })}
        </div>
      ) : null}
      <div
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: cutY0 + gap,
          height: baseY + (m.desc + 0.02) * F - (cutY0 + gap),
          overflow: "hidden",
        }}
      >
        <div
          style={{
            ...lineStyle,
            top: -cutLocal,
            color: c.ink,
          }}
        >
          {glyphs("bot", {})}
        </div>
      </div>
      {label ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: baseY + labelGap,
            textAlign: "center",
            fontFamily: instrument.fontFamily,
            fontWeight: 400,
            fontSize: labelSize,
            letterSpacing: "-0.01em",
            color: c.muted,
            whiteSpace: "pre",
            lineHeight: 1,
          }}
        >
          {labelWords.map((w, i) => {
            const p = interpolate(
              t,
              [LABEL_AT + i * 3, LABEL_AT + i * 3 + 16],
              [0, 1],
              { ...CLAMP, easing: EASE_OUT },
            );
            return (
              <span
                key={`${w}-${i}`}
                style={{
                  display: "inline-block",
                  opacity: p,
                  transform: `translateY(${((1 - p) * labelSize * 0.6).toFixed(2)}px)`,
                }}
              >
                {w}
                {i < labelWords.length - 1 ? " " : ""}
              </span>
            );
          })}
        </div>
      ) : null}
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

