  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<StretchIn>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <StretchInBase
          {...(componentProps as unknown as ComponentProps<typeof StretchInBase>)}
        />
      </div>
    </Sequence>
  );
});

export const StretchIn = Interactive.withSchema({
  Component: StretchInInner,
  componentName: "<StretchIn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export interface StrikethroughReplaceProps {
  from: string;
  to: string;
  lineColor?: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

export function StrikethroughReplace({
  from,
  to,
  lineColor = "#ff5e3a",
  fontSize = 48,
  color = "#171717",
  fontWeight = 600,
  speed = 1,
  className,
}: StrikethroughReplaceProps) {
  const frame = useCurrentFrame() * speed;
  const { durationInFrames } = useVideoConfig();

  // Phases:
  // 0 .. 40% -> draw strikethrough across `from`
  // 40% .. 60% -> fade out `from`, fade in `to`
  // 60% .. 100% -> hold
  const strikeEnd = durationInFrames * 0.4;
  const fadeStart = durationInFrames * 0.4;
  const fadeEnd = durationInFrames * 0.6;

  const linePct = interpolate(frame, [0, strikeEnd], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fromOpacity = interpolate(frame, [fadeStart, fadeEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const toOpacity = interpolate(frame, [fadeStart, fadeEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const toY = interpolate(frame, [fadeStart, fadeEnd], [8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textStyle: React.CSSProperties = {
    fontSize,
    fontWeight,
    color,
    letterSpacing: "-0.03em",
    fontFamily:
      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
    whiteSpace: "nowrap",
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "white",
      }}
    >
      <div
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* from text with strikethrough line */}
        <span
          className={className}
          style={{
            ...textStyle,
            position: "absolute",
            opacity: fromOpacity,
          }}
        >
          {from}
          <span
            aria-hidden
            style={{
              position: "absolute",
              left: 0,
              top: "50%",
              height: Math.max(2, Math.round(fontSize * 0.08)),
              width: `${linePct}%`,
              background: lineColor,
              translate: "0 -50%",
              borderRadius: 2,
            }}
          />
        </span>

        {/* to text */}
        <span
          className={className}
          style={{
            ...textStyle,
            opacity: toOpacity,
            translate: `0 ${toY}px`,
          }}
        >
          {to}
        </span>
      </div>
    </div>
  );
}

import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export type StringArtProps = {
  /** Pins around the ring. */
  pins?: number;
  /** Multiplier at the start (2 draws a cardioid). */
  from?: number;
  /** Multiplier at the end (3 is a nephroid, 4 a three-cusp epicycloid). */
  to?: number;
  /** Frames for the threads to be strung, one pin after another. */
  stringFrames?: number;
  /** Frames for the multiplier to drift from `from` to `to`. */
  morphFrames?: number;
  /** Length of the accent sweep, as a share of all threads; 0 disables. */
  sweep?: number;
  /** Pins per frame the accent sweep travels once the threads are strung. */
  sweepSpeed?: number;
  /** Thread opacity, 0 to 1. */
  threadOpacity?: number;
  /** Show the running multiplier in the corner. */
  showLabel?: boolean;
  speed?: number;
  background?: string;
  color?: string;
  accent?: string;
};

export const stringArtDefaults: Required<StringArtProps> = {
  pins: 200,
  from: 2,
  to: 4,
  stringFrames: 60,
  morphFrames: 240,
  sweep: 0.08,
  sweepSpeed: 0.9,
  threadOpacity: 0.42,
  showLabel: true,
  speed: 1,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
};

const TAU = Math.PI * 2;
const MORPH_DELAY = 24;
// Share of each integer step spent holding on the clean integer figure.
const HOLD = 0.3;
const SWEEP_BUCKETS = 4;
const fmt = (n: number) => Math.round(n * 10) / 10;

export function StringArt({
  pins = stringArtDefaults.pins,
  from = stringArtDefaults.from,
  to = stringArtDefaults.to,
  stringFrames: stringFramesProp = stringArtDefaults.stringFrames,
  morphFrames: morphFramesProp = stringArtDefaults.morphFrames,
  sweep = stringArtDefaults.sweep,
  sweepSpeed = stringArtDefaults.sweepSpeed,
  threadOpacity = stringArtDefaults.threadOpacity,
  showLabel = stringArtDefaults.showLabel,
  speed = stringArtDefaults.speed,
  background = stringArtDefaults.background,
  color = stringArtDefaults.color,
  accent = stringArtDefaults.accent,
}: StringArtProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const n = Math.max(8, Math.round(pins));
  const unit = Math.min(width, height) / 720;
  const radius = Math.min(width, height) * 0.42;
  const cx = width / 2;
  const cy = height / 2;
  const time = frame * speed;
  // interpolate() needs a strictly increasing range.
  const stringFrames = Math.max(1, stringFramesProp);
  const morphFrames = Math.max(1, morphFramesProp);

  const strung = interpolate(time, [0, stringFrames], [0, n], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });
  const morphStart = stringFrames + MORPH_DELAY;
  // The multiplier walks through each integer table (cardioid, nephroid, ...)
  // with an eased step and a short hold on every clean figure.
  const span = to - from;
  const steps = Math.max(1, Math.ceil(Math.abs(span) - 1e-6));
  const u =
    interpolate(time, [morphStart, morphStart + morphFrames], [0, steps], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }) - 1e-9;
  const step = Math.max(0, Math.floor(u));
  const within = Easing.inOut(Easing.cubic)(
    Math.min(1, Math.max(0, (u - step) / (1 - HOLD))),
  );
  const k = from + (span * Math.min(steps, step + within)) / steps;

  // Pin 0 sits on the left so the cardioid cusp points left and the figure is
  // symmetric about the horizontal axis. Angles stay continuous in k, so the
  // pattern morphs smoothly instead of snapping between integer tables.
  const point = (index: number) => {
    const a = Math.PI + (TAU * index) / n;
    return { x: cx + Math.cos(a) * radius, y: cy + Math.sin(a) * radius };
  };
  const xy = (p: { x: number; y: number }) => `${fmt(p.x)} ${fmt(p.y)}`;

  let threads = "";
  const accents: string[] = new Array(SWEEP_BUCKETS).fill("");
  const whole = Math.floor(strung);
  // The accent sweep rides the stringing head, then keeps circling the ring.
  const head = strung + Math.max(0, time - stringFrames) * sweepSpeed;
  const tail = Math.max(0, sweep) * n;
  for (let i = 0; i < Math.ceil(strung); i++) {
    const start = point(i);
    const end = point(k * i);
    // The thread being strung right now grows from its pin to the target.
    const f = i < whole ? 1 : strung - whole;
    const tip = {
      x: start.x + (end.x - start.x) * f,
      y: start.y + (end.y - start.y) * f,
    };
    const d = `M ${xy(start)} L ${xy(tip)} `;
    const behind = (((head - i) % n) + n) % n;
    if (tail > 0 && behind < tail) {
      accents[
        Math.min(SWEEP_BUCKETS - 1, Math.floor((behind / tail) * SWEEP_BUCKETS))
      ] += d;
    } else threads += d;
  }

  let pinDots = "";
  const pr = 1.6 * unit;
  for (let i = 0; i < n; i++) {
    const { x, y } = point(i);
    pinDots += `M ${fmt(x - pr)} ${fmt(y)} a ${fmt(pr)} ${fmt(pr)} 0 1 0 ${fmt(pr * 2)} 0 a ${fmt(pr)} ${fmt(pr)} 0 1 0 ${fmt(-pr * 2)} 0 `;
  }
  const pinsIn = interpolate(time, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const labelIn = interpolate(
    time,
    [stringFrames - 10, stringFrames + 6],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );

  return (
    <AbsoluteFill style={{ backgroundColor: background }}>
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="String art times table"
        style={{ display: "block" }}
      >
        <path d={pinDots} fill={color} fillOpacity={0.55 * pinsIn} />
        <path
          d={threads}
          fill="none"
          stroke={color}
          strokeOpacity={threadOpacity}
          strokeWidth={unit}
          strokeLinecap="round"
        />
        <g fill="none" stroke={accent} strokeLinecap="round">
          {accents.map((d, b) => (
            <path
              key={b}
              d={d}
              strokeOpacity={1 - b / SWEEP_BUCKETS}
              strokeWidth={unit * (1.6 - b * 0.15)}
            />
          ))}
        </g>
      </svg>
      {showLabel ? (
        <div
          style={{
            position: "absolute",
            left: width * 0.06,
            bottom: height * 0.08,
            fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
            fontSize: 22 * unit,
            letterSpacing: "0.04em",
            color,
            opacity: 0.7 * labelIn,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          <span style={{ color: accent }}>i → </span>
          {k.toFixed(2)} · i mod {n}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

import { loadFont as loadFamiljen } from "@remotion/google-fonts/FamiljenGrotesk";
import { useEffect, useId, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const familjen = loadFamiljen("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface StripeCountProps {
  value?: number;
  from?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  stripes?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const ORANGE = "#FF4F00";

const THEMES = {
  dark: { field: "#1E1E1E", ink: "#FFE7D6", inkOnAccent: "#1E1E1E" },
  light: { field: "#FFE7D6", ink: "#1E1E1E", inkOnAccent: "#1E1E1E" },
} as const;

const TRACK = -0.03;
const RISE_AT = 0;
const RISE_LEN = 16;
const PAINT_AT = 16;
const PAINT_END = 76;
const LABEL_AT = 66;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  figH: number;
  label: number;
  width: (s: string) => number;
}

function format(n: number) {
  return Math.round(n).toLocaleString("en-US");
}

function measureAll(label: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("stripe-count: no 2d context");
  const fam = `"${familjen.fontFamily}"`;
  ctx.font = `500 100px ${fam}`;
  const figH = ctx.measureText("0123456789").actualBoundingBoxAscent / 100;
  const cache = new Map<string, number>();
  const width = (raw: string) => {
    const s = raw.replace(/[0-9]/g, "0");
    const hit = cache.get(s);
    if (hit !== undefined) return hit;
    ctx.font = `500 100px ${fam}`;
    const w = ctx.measureText(s).width / 100 + TRACK * Array.from(s).length;
    cache.set(s, w);
    return w;
  };
  ctx.font = `400 100px ${fam}`;
  const labelW = label ? ctx.measureText(label).width / 100 : 0;
  return { figH, label: labelW, width };
}

function useMetrics(label: string) {
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("stripe-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      familjen.waitUntilDone(),
      document.fonts.load(`500 100px "${familjen.fontFamily}"`),
      document.fonts.load(`400 100px "${familjen.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key: label, m: measureAll(label) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [label, handle]);
  return state && state.key === label ? state.m : null;
}

export function StripeCount({
  value = 184,
  from = 0,
  prefix = "",
  suffix = "",
  label = "scenes that take your brand colour from one prop",
  stripes = 12,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: StripeCountProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const m = useMetrics(label);

  const transparent = background === "transparent";
  const hot = accent ?? ORANGE;
  const field = transparent ? c.field : (background ?? c.field);

  if (!m) {
    return (
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: transparent ? "transparent" : field,
        }}
      />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);
  const pad = Math.min(W, H) * 0.075;

  const paint = (time: number) =>
    interpolate(time, [PAINT_AT, PAINT_END], [0, 1], {
      ...CLAMP,
      easing: EASE_IN_OUT,
    });
  const p = paint(t);
  const text = `${prefix}${format(from + (value - from) * paint(t))}${suffix}`;
  const finalText = `${prefix}${format(value)}${suffix}`;
  const wFinal = m.width(finalText);

  const labelFs = (portrait ? 50 : 36) * s;
  const labelW = Math.min(W - pad * 2, labelFs * (portrait ? 16 : 22));
  const labelLines = Math.max(1, Math.ceil((m.label * labelFs) / labelW));
  const bandH = label
    ? pad * 2 + labelFs * 1.22 * labelLines
    : H * (portrait ? 0.2 : 0.24);

  const F = Math.min((W - pad * 2) / wFinal, (H - bandH - pad * 2) / m.figH);
  const figH = m.figH * F;
  const baseY = H - pad;
  const right = W - pad;

  const rise = interpolate(t, [RISE_AT, RISE_AT + RISE_LEN], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const top = baseY - figH - F * 0.06;
  const bottom = Math.min(H, baseY + F * 0.16);
  const bandClipH = bottom - top;
  const dy = (1 - rise) * bandClipH;

  const n = Math.max(4, Math.round(stripes));
  const pitch = (figH + F * 0.06) / n;
  const firstY = baseY - figH - F * 0.06;
  const rows = Math.ceil(bandClipH / pitch);
  const reach = 0.55;
  const minK = 0.07;

  const outline = 1 - interpolate(p, [0.78, 1], [0, 1], CLAMP);
  const strokeW = Math.max(1.2, F * 0.0065);
  const ink = transparent ? c.ink : c.inkOnAccent;

  const labelWords = label ? label.split(" ") : [];

  const textProps = {
    x: right,
    y: baseY + dy,
    textAnchor: "end" as const,
    fontFamily: familjen.fontFamily,
    fontWeight: 500,
    fontSize: F,
    letterSpacing: `${TRACK}em`,
    style: { fontVariantNumeric: "tabular-nums" as const },
  };

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : hot,
        overflow: "hidden",
      }}
    >
      {transparent ? null : (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: W,
            height: bandH,
            background: field,
          }}
        />
      )}

      <svg
        width={W}
        height={H}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <clipPath id={`${uid}t`}>
            <text {...textProps}>{text}</text>
          </clipPath>
          <filter id={`${uid}o`} x="-5%" y="-20%" width="110%" height="140%">
            <feMorphology
              in="SourceAlpha"
              operator="erode"
              radius={strokeW}
              result="in"
            />
            <feComposite in="SourceGraphic" in2="in" operator="out" />
          </filter>
          <clipPath id={`${uid}b`}>
            <rect x={0} y={top} width={W} height={bandClipH} />
          </clipPath>
        </defs>
        <g clipPath={`url(#${uid}b)`}>
          <g clipPath={`url(#${uid}t)`}>
            {Array.from({ length: rows }, (_, k) => {
              const local = interpolate(
                p * (1 + reach) - (k / Math.max(1, rows - 1)) * reach,
                [0, 1],
                [0, 1],
                { ...CLAMP, easing: EASE_OUT },
              );
              const th = pitch * (minK + (1.04 - minK) * local);
              const yc = firstY + dy + pitch * (k + 0.5);
              return (
                <rect
                  key={`s${k}`}
                  x={0}
                  y={yc - th / 2}
                  width={W}
                  height={th}
                  style={{ fill: ink }}
                />
              );
            })}
          </g>
          {outline > 0 ? (
            <text
              {...textProps}
              filter={`url(#${uid}o)`}
              opacity={outline}
              style={{ ...textProps.style, fill: ink }}
            >
              {text}
            </text>
          ) : null}
        </g>
      </svg>

      {label ? (
        <div
          style={{
            position: "absolute",
            left: pad,
            width: labelW,
            top: pad - labelFs * 0.12,
            display: "flex",
            flexWrap: "wrap",
            columnGap: "0.26em",
            fontFamily: familjen.fontFamily,
            fontWeight: 400,
            fontSize: labelFs,
            lineHeight: 1.22,
            letterSpacing: "-0.01em",
            color: c.ink,
          }}
        >
          {labelWords.map((w, k) => {
            const q = interpolate(
              t,
              [LABEL_AT + k * 2, LABEL_AT + k * 2 + 16],
              [0, 1],
              { ...CLAMP, easing: EASE_OUT },
            );
            return (
              <span
                key={`${w}-${k}`}
                style={{
                  display: "inline-block",
                  opacity: q,
                  transform: `translateY(${((1 - q) * labelFs * 0.7).toFixed(2)}px)`,
                }}
              >
                {w}
              </span>
            );
          })}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

