    description: "Horizon",
    hiddenFromList: false,
  },
  sunStripes: {
    type: "boolean",
    default: true,
    description: "Scrolling sun stripes",
  },
  grid: {
    type: "color",
    default: "#E5322D",
    description: "Grid",
  },
  sunTop: {
    type: "color",
    default: "#FFC46B",
    description: "Sun top",
