  c: ["#ffe2c4", "#ff9a4d", "#d2456b", "#3a1f6b"],
} as const;

interface TallyMarksProps {
  value?: number;
  label?: string;
  rows?: number;
  groupsPerRow?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
