const T0 = 6;
const TALLY = 66;
const R0 = 0.2;
const ROW_IN = 78;
const ROW_LEN = 18;
const COL_IN = 90;
const COL_LEN = 18;
const COL_STAGGER = 4;
const TIP = COL_IN + COL_LEN + COL_STAGGER;
const NUM_IN = TIP + 10;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: SWIRL.bg,
    fg: "#F4F1EC",
    muted: "#9A949C",
    stops: ["#ffc79a", SWIRL.c[1], SWIRL.c[2], "#9b4fa6"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    stops: ["#ff8a3d", "#f2602c", SWIRL.c[2], "#7a3a9a"],
    grain: 0.045,
  },
} as const;

function hash(a: number, b: number) {
  let h = (Math.imul(a, 374761393) + Math.imul(b, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function formatNumber(n: number) {
  return Math.round(Math.abs(n))
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function solveRate(n: number, d: number, r0: number) {
  if (r0 * d >= n) return 1e-6;
  let lo = 1e-6;
  let hi = 1;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    const f = (r0 / mid) * (Math.exp(mid * d) - 1);
    if (f > n) hi = mid;
    else lo = mid;
  }
  return (lo + hi) / 2;
}

interface Stroke {
  key: string;
  row: number;
  col: number;
  k: number;
  slash: boolean;
  at: number;
  dur: number;
  ja: number;
  jl: number;
  jx: number;
  jy: number;
}

function buildStrokes(rows: number, perRow: number): Stroke[] {
  const n = rows * perRow * 5;
  const rate = solveRate(n, TALLY, R0);
  const list: Stroke[] = [];
  for (let i = 0; i < n; i++) {
    const g = Math.floor(i / 5);
    const k = i % 5;
    const slash = k === 4;
    const at = T0 + Math.log(1 + (i * rate) / R0) / rate;
    const prog = i / Math.max(1, n - 1);
    list.push({
      key: `s${i}`,
      row: Math.floor(g / perRow),
      col: g % perRow,
      k,
      slash,
      at,
      dur: interpolate(prog, [0, 0.35, 1], [6, 4, 3], CLAMP),
      ja: (hash(i, 3) - 0.5) * (slash ? 6 : 5),
      jl: (hash(i, 5) - 0.5) * 0.08,
      jx: (hash(i, 7) - 0.5) * 2.4,
      jy: (hash(i, 11) - 0.5) * 4,
    });
  }
  return list;
}

function Grain({ opacity }: { opacity: number }) {
