      light: {},
    },
    description: "Theme",
  },
  text: {
    type: "text-content",
    default: "Read it both ways.",
    description: "Text",
  },
  hold: {
    type: "number",
    default: 16,
    min: 0,
    max: 48,
    step: 1,
    description: "Hold",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
