  after?: ThinSlabSide;
  callout?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const BEAM = ["#f4f7ff", "#8fb4ff", "#3d5bff", "#1a1660"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    slab: "#26262C",
    slabEdge: "#34343B",
    ghost: "#6A6970",
    deep: BEAM[3],
    tip: BEAM[0],
