      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  title: {
    type: "text-content",
    default: "Time to your first launch video",
    description: "Title",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  title: "Time to your first launch video",
  speed: 1,
};

type ThinSlabElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ThinSlabBase>;

const ThinSlabInner = forwardRef<
  HTMLDivElement,
  ThinSlabElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ThinSlab>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ThinSlabBase
          {...(componentProps as unknown as ComponentProps<typeof ThinSlabBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ThinSlab = Interactive.withSchema({
  Component: ThinSlabInner,
  componentName: "<ThinSlab>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

