export interface TickerTapeProps {
  /** The hero symbol the middle band stops on. */
  symbol?: string;
  /** Hero price, shown as typed. */
  price?: string;
  /** Hero move in percent; negative reads as a down move. */
  change?: number;
  /** Other (fictional) symbols filling the bands. */
  symbols?: string[];
  /** Product under the poster; "remocn" renders the real logo. */
  name?: string;
  /** Replaces the logo / name under the poster. */
  logo?: React.ReactNode;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Oswald 500 advances per em for A–Z (fontTools, wght 500); cap height 0.81.
const OSWALD: Record<string, number> = {
  A: 0.522,
  B: 0.557,
  C: 0.54,
  D: 0.557,
  E: 0.428,
  F: 0.413,
  G: 0.559,
  H: 0.586,
  I: 0.275,
  J: 0.326,
  K: 0.532,
  L: 0.421,
  M: 0.683,
  N: 0.545,
  O: 0.563,
  P: 0.527,
  Q: 0.564,
  R: 0.561,
  S: 0.494,
  T: 0.43,
  U: 0.566,
  V: 0.516,
  W: 0.712,
  X: 0.499,
  Y: 0.487,
  Z: 0.425,
};
const CAP = 0.81;
/** JetBrains Mono: every glyph advances 0.6em, cap height 0.73. */
const MONO = 0.6;
const MONO_CAP = 0.73;

const symWidth = (s: string) =>
  Array.from(s).reduce((w, ch) => w + (OSWALD[ch] ?? 0.52), 0);

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.8, 0.2);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Beat sheet (30fps, speed 1):
//   0–40   seven bands run at full tilt, alternating directions, fast ones smear
//  40–86   everything brakes; the middle band stops dead with the hero symbol
//          centred, the others slow to a crawl
//  84–108  the side bands clear out up and down, the hero's neighbours slide
//          off, and the hero quote scales up into the poster
//  108–    poster: symbol, price, move; the thin mono tapes keep crawling
const BRAKE_AT = 40;
const STOP_AT = 86;
const RISE_AT = 84;
const RISE_LEN = 26;

// gradients.sh "aurora" (bg #03050b): #a0f0c8 #3fb5a3 #5147b6 #b25c9c.
// Up moves take the mint/teal end; the glow under the poster uses the set.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#7E7D84",
    rule: "rgba(243,242,239,0.1)",
    up: ["#A0F0C8", "#3FB5A3"],
    down: "#C8675E",
    glow: ["#3FB5A3", "#5147B6", "#A0F0C8"],
    glowAlpha: 0.3,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#7A7873",
    rule: "rgba(18,18,20,0.1)",
    up: ["#2E9C8B", "#5147B6"],
    down: "#B24A40",
    glow: ["#A0F0C8", "#C9C4F2", "#A0F0C8"],
    glowAlpha: 0.45,
  },
} as const;

const SYMBOLS = [
  "KTBS",
  "KEYF",
  "EASE",
  "SPRG",
  "TWEN",
  "FRMS",
  "SEQN",
  "MOTN",
  "BLUR",
  "PXLS",
  "KERN",
  "GLYF",
  "WIPE",
  "CRVE",
  "TIMR",
  "FADE",
];

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

interface Quote {
  sym: string;
  price: string;
  chg: number;
  hero: boolean;
}

interface Placed extends Quote {
  /** left edge inside the tile, px */
  x: number;
  w: number;
}

interface RowSpec {
  /** font size as a share of the frame height */
  size: number;
  kind: "big" | "mono";
  dir: 1 | -1;
  /** px per frame at 720p */
  v: number;
  hero?: boolean;
}

const ROWS: RowSpec[] = [
  { size: 0.026, kind: "mono", dir: -1, v: 2.6 },
  { size: 0.088, kind: "big", dir: 1, v: 7 },
  { size: 0.13, kind: "big", dir: -1, v: 11.5 },
  { size: 0.2, kind: "big", dir: -1, v: 17, hero: true },
  { size: 0.13, kind: "big", dir: 1, v: 10 },
  { size: 0.088, kind: "big", dir: -1, v: 7.5 },
  { size: 0.026, kind: "mono", dir: 1, v: 2.8 },
];

function fmtChg(c: number) {
  return `${Math.abs(c).toFixed(1)}%`;
}

/** Width of a quote at font size `fs`. Big: symbol + a two-line price/move stack. */
function quoteWidth(q: Quote, fs: number, kind: RowSpec["kind"]) {
  if (kind === "mono") {
    const chars = q.sym.length + 1 + q.price.length + 3 + fmtChg(q.chg).length;
    return chars * MONO * fs;
  }
  const sub = fs * 0.3;
  const stack = Math.max(
    q.price.length * MONO * sub,
    (fmtChg(q.chg).length + 1.4) * MONO * sub,
  );
  return symWidth(q.sym) * fs + fs * 0.16 + stack;
}

function Triangle({
  x,
  baseline,
  size,
  up,
  fill,
}: {
  x: number;
  baseline: number;
  size: number;
  up: boolean;
  fill: string;
}) {
  // sits on the cap height of the figures beside it
  const h = size * 0.56;
  const w = size * 0.62;
  const top = baseline - size * MONO_CAP + (size * MONO_CAP - h) / 2;
  const d = up
    ? `M${x} ${top + h} L${x + w / 2} ${top} L${x + w} ${top + h} Z`
    : `M${x} ${top} L${x + w} ${top} L${x + w / 2} ${top + h} Z`;
  return <path d={d} fill={fill} />;
}

function QuoteView({
  q,
  x,
  baseline,
  fs,
  kind,
  fg,
  muted,
  upFill,
  downFill,
}: {
  q: Quote;
  x: number;
  baseline: number;
  fs: number;
  kind: RowSpec["kind"];
  fg: string;
  muted: string;
  upFill: string;
  downFill: string;
}) {
  const up = q.chg >= 0;
  const col = up ? upFill : downFill;
  if (kind === "mono") {
    const a = x + (q.sym.length + 1) * MONO * fs;
    const b = a + (q.price.length + 1) * MONO * fs;
    return (
      <g fontFamily={mono} fontSize={fs}>
        <text x={x} y={baseline} fill={fg} fontWeight={500}>
          {q.sym}
        </text>
        <text x={a} y={baseline} fill={muted} fontWeight={400}>
          {q.price}
        </text>
        <Triangle
          x={b}
          baseline={baseline}
          size={fs}
          up={up}
          fill={up ? upFill : downFill}
        />
        <text x={b + 1.1 * MONO * fs} y={baseline} fill={col} fontWeight={400}>
          {fmtChg(q.chg)}
        </text>
      </g>
    );
  }
  const sub = fs * 0.3;
  const sx = x + symWidth(q.sym) * fs + fs * 0.16;
  const capTop = baseline - CAP * fs;
  return (
    <g>
      <text
        x={x}
        y={baseline}
        fill={fg}
        fontFamily={display}
        fontWeight={500}
        fontSize={fs}
      >
        {q.sym}
      </text>
      <g fontFamily={mono} fontSize={sub} fontWeight={400}>
        <text x={sx} y={capTop + MONO_CAP * sub} fill={muted}>
          {q.price}
        </text>
        <Triangle x={sx} baseline={baseline} size={sub} up={up} fill={col} />
        <text x={sx + 1.4 * MONO * sub} y={baseline} fill={col}>
          {fmtChg(q.chg)}
        </text>
      </g>
    </g>
  );
}

/** Distance travelled: full speed, then a cubic brake to `rest` × speed. */
function travel(t: number, v: number, stopAt: number, rest: number) {
  const L = stopAt - BRAKE_AT;
  if (t <= BRAKE_AT) return v * t;
  const tau = Math.min(1, (t - BRAKE_AT) / L);
  const brake = (v * (1 - rest) * L * (1 - (1 - tau) ** 3)) / 3;
  return v * BRAKE_AT + brake + v * rest * (t - BRAKE_AT);
}

function speedAt(t: number, v: number, stopAt: number, rest: number) {
  if (t <= BRAKE_AT) return v;
  const tau = Math.min(1, (t - BRAKE_AT) / (stopAt - BRAKE_AT));
  return v * rest + v * (1 - rest) * (1 - tau) ** 2;
}

export function TickerTape({
  symbol = "RMCN",
  price = "128.40",
  change = 12.4,
  symbols = SYMBOLS,
  name = "remocn",
  logo,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: TickerTapeProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const p = THEMES[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const heroSym = symbol.trim().toUpperCase() || "RMCN";

  // One tile of quotes per row, wide enough to cover the frame twice.
  const rows = useMemo(() => {
    let seed = 0;
    return ROWS.map((r, ri) => {
      const fs = r.size * H;
      const placed: Placed[] = [];
      let x = 0;
      const gap = r.kind === "mono" ? 2.4 * MONO * fs : fs * 0.5;
      let k = 0;
      while (x < W * 2.2 || (r.hero && k < 7)) {
        const isHero = Boolean(r.hero) && k === 5;
        const sym = isHero
          ? heroSym
          : symbols[
              (ri * 5 + k * 3 + Math.floor(hash(seed) * 4)) % symbols.length
            ];
        const up = hash(seed * 1.7 + 3) < 0.6;
        const q: Quote = isHero
          ? { sym, price, chg: change, hero: true }
          : {
              sym,
              price: (8 + hash(seed * 2.9) * 390).toFixed(2),
              chg: (up ? 1 : -1) * (0.2 + hash(seed * 4.3 + 1) * 8.6),
              hero: false,
            };
        const w = quoteWidth(q, fs, r.kind);
        placed.push({ ...q, x, w });
        x += w + gap;
        k++;
        seed++;
      }
      return { ...r, fs, placed, period: x };
    });
  }, [H, W, heroSym, price, change, symbols]);

  // vertical stack: rows separated by hairlines, centred in the frame
  const gaps = rows.map((r) => (r.kind === "mono" ? 0.03 : 0.036) * H);
  const heights = rows.map((r) => CAP * r.fs);
  const total =
    heights.reduce((a, b) => a + b, 0) +
    gaps.slice(0, -1).reduce((a, b) => a + b, 0) * 1;
  let yCursor = (H - total) / 2;
  const baselines = rows.map((_, i) => {
    const b = yCursor + heights[i];
    yCursor = b + gaps[i];
    return b;
  });

  const heroRowIdx = rows.findIndex((r) => r.hero);
  const heroRow = rows[heroRowIdx];
  const heroQ = heroRow.placed.find((q) => q.hero) as Placed;

  // poster scale and position
  const rise = interpolate(t, [RISE_AT, RISE_AT + RISE_LEN], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.7, 0, 0.2, 1),
  });
  const posterScale = Math.min((W * 0.74) / heroQ.w, (H * 0.36) / heroRow.fs);
  const scale = 1 + (posterScale - 1) * rise;
  const heroBaseline0 = baselines[heroRowIdx];
  const heroCy0 = heroBaseline0 - (CAP * heroRow.fs) / 2;
  const heroCy1 = H * 0.46;
  const heroCy = heroCy0 + (heroCy1 - heroCy0) * rise;

  const clear = interpolate(t, [RISE_AT - 4, RISE_AT + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_IN,
  });
  const caption = (d: number) =>
    interpolate(
      t,
      [RISE_AT + RISE_LEN - 6 + d, RISE_AT + RISE_LEN + 14 + d],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
  const glowIn = interpolate(t, [RISE_AT, RISE_AT + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const drift = interpolate(t, [0, 160], [0, 1], CLAMP);

  const upId = `${uid}up`;
  const upFill = `url(#${upId})`;

  return (
    <AbsoluteFill style={{ background: p.bg, overflow: "hidden" }}>
      {/* aurora glow lands under the poster */}
      <AbsoluteFill
        style={{
          opacity: p.glowAlpha * glowIn,
          background: p.glow
            .map(
              (c, i) =>
                `radial-gradient(30% 42% at ${22 + i * 28 + drift * 4}% ${heroCy1 / (H / 100) + (i % 2 ? 5 : -3)}%, ${c} 0%, transparent 70%)`,
            )
            .join(", "),
        }}
      />
      <svg
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        style={{ position: "absolute", inset: 0 }}
        role="img"
        aria-label={`${heroSym} ${price} ${change >= 0 ? "up" : "down"} ${fmtChg(change)}`}
      >
        <defs>
          <linearGradient id={upId} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={p.up[0]} />
            <stop offset="1" stopColor={p.up[1]} />
          </linearGradient>
          <clipPath id={`${uid}stage`}>
            <rect
              x={0}
              y={baselines[0] + gaps[0] / 2}
              width={W}
              height={
                baselines[rows.length - 1] -
                heights[rows.length - 1] -
                gaps[rows.length - 2] / 2 -
                (baselines[0] + gaps[0] / 2)
              }
            />
          </clipPath>
          {rows.map((r, i) => {
            const v = speedAt(
              t,
              r.v * u,
              r.hero ? STOP_AT : STOP_AT - 8 + i * 3,
              r.hero ? 0 : 0.12,
            );
            return (
              <filter
                key={`blur${r.size}${r.dir}${r.v}`}
                id={`${uid}blur${i}`}
                x="-5%"
                y="-50%"
                width="110%"
                height="200%"
              >
                <feGaussianBlur stdDeviation={`${(v * 0.2).toFixed(2)} 0`} />
              </filter>
            );
          })}
        </defs>

        {rows.map((r, i) => {
          const stopAt = r.hero ? STOP_AT : STOP_AT - 8 + i * 3;
          const rest = r.hero ? 0 : r.kind === "mono" ? 0.35 : 0.12;
          const D = travel(t, r.v * u, stopAt, rest);
          // the hero row is offset so the hero quote lands dead centre
          const Dstop = travel(stopAt + 1000, r.v * u, stopAt, 0);
          const x0 = r.hero
            ? W / 2 - (heroQ.x + heroQ.w / 2) - r.dir * Dstop
            : -hash(i * 3.3) * r.period;
          const shift = x0 + r.dir * D;
          const off = ((shift % r.period) + r.period) % r.period;
          const baseline = baselines[i];
          // side bands clear: upper ones up, lower ones down
          const away =
            r.kind === "mono" || r.hero
              ? 0
              : (i < heroRowIdx ? -1 : 1) * clear * H * 0.55;
          const fade = r.kind === "mono" ? 1 - 0.35 * clear : 1 - clear;
          const copies = [-1, 0, 1, 2];
          return (
            <g
              key={`row${r.size}${r.dir}${r.v}`}
              clipPath={r.kind === "mono" ? undefined : `url(#${uid}stage)`}
            >
              <g opacity={fade} transform={`translate(0 ${away})`}>
                {/* hairlines between bands, carried away by the side bands */}
                {i !== heroRowIdx ? (
                  <line
                    x1={0}
                    x2={W}
                    y1={
                      i < heroRowIdx
                        ? baseline + gaps[i] / 2
                        : baseline - heights[i] - gaps[i - 1] / 2
                    }
                    y2={
                      i < heroRowIdx
                        ? baseline + gaps[i] / 2
                        : baseline - heights[i] - gaps[i - 1] / 2
                    }
                    stroke={p.rule}
                    strokeWidth={Math.max(1, u)}
                  />
                ) : null}
                <g filter={`url(#${uid}blur${i})`}>
                  {copies.flatMap((c) =>
                    r.placed.map((q) => {
                      if (q.hero) return null;
                      let x =
                        q.x + c * r.period + (r.hero ? shift : off - r.period);
                      if (r.hero) {
                        // neighbours make room for the growing hero quote
                        const heroX = heroQ.x + c * r.period + shift;
                        const dirSide = x < heroX ? -1 : 1;
                        x +=
                          dirSide *
                          ((scale - 1) * heroQ.w * 0.5 + rise * W * 0.12);
                      }
                      if (x > W + 20 * u || x + q.w < -20 * u) return null;
                      return (
                        <g key={`${c}-${q.x}`} opacity={r.hero ? 1 - rise : 1}>
                          <QuoteView
                            q={q}
                            x={x}
                            baseline={baseline}
                            fs={r.fs}
                            kind={r.kind}
                            fg={p.fg}
                            muted={p.muted}
                            upFill={upFill}
                            downFill={p.down}
                          />
                        </g>
                      );
                    }),
                  )}
                </g>
              </g>
            </g>
          );
        })}

        {/* hero quote: rides its band, then scales into the poster */}
        {(() => {
          const r = heroRow;
          const D = travel(t, r.v * u, STOP_AT, 0);
          const Dstop = travel(STOP_AT + 1000, r.v * u, STOP_AT, 0);
          const x0 = W / 2 - (heroQ.x + heroQ.w / 2) - r.dir * Dstop;
          const shift = x0 + r.dir * D;
          // nearest copy to the centre
          const raw = heroQ.x + shift;
          const n = Math.round((W / 2 - heroQ.w / 2 - raw) / r.period);
          const left = raw + n * r.period;
          const cx = left + heroQ.w / 2;
          return (
            <g
              transform={`translate(${cx} ${heroCy}) scale(${scale}) translate(${-cx} ${-heroCy0})`}
            >
              <g filter={`url(#${uid}blur${heroRowIdx})`}>
                <QuoteView
                  q={heroQ}
                  x={left}
                  baseline={heroBaseline0}
                  fs={r.fs}
                  kind="big"
                  fg={p.fg}
                  muted={p.muted}
                  upFill={upFill}
                  downFill={p.down}
                />
              </g>
            </g>
          );
        })()}
      </svg>

      {/* caption under the poster */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: heroCy1 + (CAP * heroRow.fs * posterScale) / 2 + 46 * u,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: 14 * u,
          fontFamily: mono,
          fontSize: 15 * u,
          letterSpacing: "0.12em",
          color: p.muted,
          lineHeight: 1,
        }}
      >
        <div
          style={{
            opacity: caption(0),
            transform: `translateY(${(1 - caption(0)) * 12 * u}px)`,
          }}
        >
          {logo ??
            (name.trim().toLowerCase() === "remocn" ? (
              <RemocnLogo fontSize={30 * u} color={p.fg} />
            ) : (
              <span
                style={{
                  fontFamily: display,
                  fontWeight: 500,
                  fontSize: 30 * u,
                  letterSpacing: "0.01em",
                  color: p.fg,
                }}
              >
                {name}
              </span>
            ))}
        </div>
        <div
          style={{
            width: Math.max(1, u),
            height: 20 * u,
            background: p.rule,
            transform: `scaleY(${caption(3)})`,
          }}
        />
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 9 * u,
            opacity: caption(6),
            transform: `translateY(${(1 - caption(6)) * 12 * u}px)`,
          }}
        >
          <div
            style={{
              width: 7 * u,
              height: 7 * u,
              borderRadius: 99,
              background: accent,
            }}
          />
          <span>MARKET CLOSE</span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

import { loadFont as loadDisplay } from "@remotion/google-fonts/SpaceGrotesk";
import React, { useId } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface TileWaveProps {
  /** Outgoing scene: a short headline string or any React node. */
  from?: React.ReactNode;
  /** Incoming scene, set on a "beam" gradient panel. */
  to?: React.ReactNode;
  /** Tile rows; columns follow the aspect ratio. */
  rows?: number;
  /** Frames the outgoing scene holds before the wave. */
  delay?: number;
  accent?: string;
  /** Playback multiplier. */
  speed?: number;
  /** Stage seen between the tiles; the outgoing scene takes the other tone. */
  theme?: "dark" | "light";
}

const STAGE = { dark: "#0A0A0B", light: "#F5F4F0" } as const;
const INK = { dark: "#F3F2EF", light: "#121214" } as const;

const SPREAD = 26;
const TILE = 22;
const SHRINK_END = 0.46;
const GROW_START = 0.54;

const EASE_SHRINK = Easing.bezier(0.4, 0, 0.7, 0.5);
const EASE_GROW = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export const tileWaveLength = (delay = 16) => delay + SPREAD + TILE + 30;

/* gradients.sh "beam" palette: deep indigo into the remocn blue, a cold
   highlight rising from the lower right. Drifts a few percent per shot. */
const BEAM = ["#f4f7ff", "#8fb4ff", "#3d5bff", "#1a1660"] as const;

const mixA = (c: string, a: number) =>
  `color-mix(in oklab, ${c} ${Math.round(a * 100)}%, transparent)`;

function beamGround(d: number) {
  const [c0, c1, c2, c3] = BEAM;
  const s = Math.sin(d * Math.PI) * 4;
  return [
    `radial-gradient(70% 90% at ${(86 - s).toFixed(2)}% ${(108 - s).toFixed(2)}%, ${mixA(c0, 0.55)} 0%, ${mixA(c1, 0.45)} 30%, transparent 68%)`,
    `radial-gradient(60% 70% at ${(8 + s).toFixed(2)}% 0%, ${mixA(c3, 0.9)} 0%, transparent 72%)`,
    `linear-gradient(${(158 + s).toFixed(2)}deg, ${c3} 0%, ${c2} 52%, ${c2} 70%, ${c1} 100%)`,
  ].join(", ");
}

function Headline({
  text,
  bg,
  fg,
  dotColor,
}: {
  text: string;
  bg: string;
  fg: string;
  dotColor: string;
}) {
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const dot = text.endsWith(".");
  const body = dot ? text.slice(0, -1) : text;
  const size = Math.min(
    196 * u,
    (0.74 * W) / (Math.max(4, text.length) * 0.56),
  );
  return (
    <AbsoluteFill
      style={{
        background: bg,
        color: fg,
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily: display,
          fontWeight: 500,
          fontSize: size,
          letterSpacing: "-0.04em",
          lineHeight: 1,
          whiteSpace: "nowrap",
          paddingBottom: size * 0.08,
          paddingRight: size * 0.04,
        }}
      >
        {body}
        {dot ? <span style={{ color: dotColor }}>.</span> : null}
      </div>
    </AbsoluteFill>
  );
}

function Scene({
  content,
  bg,
  fg,
  dotColor,
}: {
  content: React.ReactNode;
  bg: string;
  fg: string;
  dotColor: string;
}) {
  if (typeof content === "string" || typeof content === "number") {
    return (
      <Headline text={String(content)} bg={bg} fg={fg} dotColor={dotColor} />
    );
  }
  return <AbsoluteFill style={{ background: bg }}>{content}</AbsoluteFill>;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function TileWave({
  from = "Idea.",
  to = "Shipped.",
  rows = 8,
  delay = 16,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: TileWaveProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const stage = STAGE[theme];
  const aTone = theme === "dark" ? "light" : "dark";
  const aBg = STAGE[aTone];
  const aFg = INK[aTone];
  const bFg = "#FFFFFF";

  const nRows = Math.max(3, Math.round(rows));
  const nCols = Math.max(3, Math.round((W / H) * nRows));
  const cw = W / nCols;
  const ch = H / nRows;
  const minScale = (7 * u) / Math.min(cw, ch);
  const bleed = 0.6;

  const sceneA = <Scene content={from} bg={aBg} fg={aFg} dotColor={accent} />;
  const bGround = beamGround(Math.min(1, t / tileWaveLength(delay)));
  const sceneB = <Scene content={to} bg={bGround} fg={bFg} dotColor={bFg} />;
  const before = t <= delay;
  const after = t >= delay + SPREAD + TILE;

  const tiles: React.ReactNode[] = [];
  const tileB = BEAM[2];
  const restA: string[] = [];
  const restB: string[] = [];
  const cell = (x: number, y: number) => {
    const e = bleed;
    return `M${(x - e).toFixed(2)} ${(y - e).toFixed(2)}h${(cw + 2 * e).toFixed(2)}v${(ch + 2 * e).toFixed(2)}h${(-cw - 2 * e).toFixed(2)}Z`;
  };
  for (let r = 0; r < (before || after ? 0 : nRows); r++) {
    for (let c = 0; c < nCols; c++) {
      const x = c * cw;
      const y = r * ch;
      const diag = (c / (nCols - 1) + r / (nRows - 1)) / 2;
      const start = delay + diag * SPREAD;
      const p = interpolate(t, [start, start + TILE], [0, 1], CLAMP);
      const isB = p >= (SHRINK_END + GROW_START) / 2;
      let s: number;
      if (p <= SHRINK_END) {
        s = 1 - (1 - minScale) * EASE_SHRINK(p / SHRINK_END);
      } else if (p < GROW_START) {
        s = minScale;
      } else {
        s =
          minScale +
          (1 - minScale) * EASE_GROW((p - GROW_START) / (1 - GROW_START));
      }
      s = Math.min(1, s * 1.03);
      if (s >= 1) {
        (isB ? restB : restA).push(cell(x, y));
        continue;
      }
      const tw = cw * s;
      const th = ch * s;
      const round = Math.min(1, (1 - s) / (1 - minScale)) ** 1.6;
      const radius = Math.min(tw, th) * 0.5 * round;
      if (s <= 0.14) {
        tiles.push(
          <div
            key={`${r}-${c}`}
            style={{
              position: "absolute",
              left: x + (cw - tw) / 2,
              top: y + (ch - th) / 2,
              width: tw,
              height: th,
              borderRadius: radius,
              background: isB ? tileB : aBg,
            }}
          />,
        );
        continue;
      }
      const ins = [y, W - x - cw, H - y - ch, x]
        .map((v) => `${v.toFixed(2)}px`)
        .join(" ");
      tiles.push(
        <div
          key={`${r}-${c}`}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: W,
            height: H,
            transform: `scale(${s})`,
            transformOrigin: `${x + cw / 2}px ${y + ch / 2}px`,
            clipPath: `inset(${ins} round ${(radius / s).toFixed(2)}px)`,
          }}
        >
          {isB ? sceneB : sceneA}
        </div>,
      );
    }
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {before ? sceneA : null}
      {after ? sceneB : null}
      {restA.length ? (
        <AbsoluteFill style={{ clipPath: `path("${restA.join("")}")` }}>
          {sceneA}
        </AbsoluteFill>
      ) : null}
      {restB.length ? (
        <AbsoluteFill style={{ clipPath: `path("${restB.join("")}")` }}>
          {sceneB}
        </AbsoluteFill>
      ) : null}
      {tiles}
      <Grain opacity={0.04} />
    </AbsoluteFill>
  );
}

