interface TimingTowerProps {
  /** Three-letter code of the hero car, the one that climbs to P1. */
  code?: string;
  /** The nine other cars, leader first. The hero starts behind the seventh. */
  field?: string[];
  /** Lap the tower opens on. One lap ticks per overtake. */
  lap?: number;
  /** Race distance shown after the slash in the lap counter. */
  laps?: number;
  /** The poster's interval to P2. */
  interval?: string;
  /** Small label over the poster interval. */
  intervalLabel?: string;
  /** The live dot in the tower header. */
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (internal clock = frame + 4, 30fps, speed 1):
//   0–16   the tower wipes in from the left edge, header first, rows staggered
//          2 frames apart; the giant "P8" rises on the right
//  14–93   seven laps, one every ~11 frames, the gaps rewriting on each tick:
//          the hero swaps up one row per lap (9-frame eased swap, nudged out
//          of line while it passes), the row and the giant numeral flash the
//          aurora "personal best" green, the numeral rolls to the new place;
//          a few other cars swap behind it so the whole tower lives
//  93      P1: the hero row and the numeral turn aurora purple for good
// 110–130  the tower peels off to the left, bottom row first; the numeral
//          slides left and the code, team logo and interval wipe in beside it
// 130–     poster hold: "P1 · RMC" with the interval counted up to +12.408
const LAP_AT = [14, 28, 41, 53, 64, 74, 84];
const SWAP = 9;
const EXIT_AT = 110;

const EASE = Easing.bezier(0.22, 1, 0.36, 1);
const SWAP_EASE = Easing.bezier(0.65, 0, 0.35, 1);
const EXIT_EASE = Easing.bezier(0.55, 0, 0.85, 0.35);
const MOVE = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "aurora": bg #03050b, #a0f0c8 #3fb5a3 #5147b6 #b25c9c.
const AURORA = ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"] as const;
const GREEN = `linear-gradient(180deg, ${AURORA[0]} 0%, ${AURORA[1]} 100%)`;
const PURPLE = `linear-gradient(165deg, ${AURORA[3]} 0%, #7A4FB8 45%, ${AURORA[2]} 100%)`;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    row: "#141417",
    rowEdge: "#1F1F23",
    pos: "#F3F2EF",
    posInk: "#0A0A0B",
    head: "#1C1C20",
    ink: "#F3F2EF",
    dim: "#8A8990",
    faint: "#3A3A40",
    stripes: ["#6E6D74", "#4E4D54", "#9A99A0", "#5E5D64", "#3E3D44"],
    greenInk: AURORA[0],
    ground: 1,
  },
  light: {
    stage: "#F5F4F0",
    row: "#FFFFFF",
    rowEdge: "#E6E4DE",
    pos: "#121214",
    posInk: "#F5F4F0",
    head: "#121214",
    ink: "#121214",
    dim: "#7E7D77",
    faint: "#C9C7C0",
    stripes: ["#9A9993", "#BDBBB4", "#6E6D68", "#AEACA5", "#85847E"],
    greenInk: "#1F8C7B",
    ground: 0.55,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** Up in 1 frame, eases back over `len`. */
function flash(d: number, len: number) {
  if (d < 0 || d > len + 1) return 0;
  if (d < 1) return d;
  const k = 1 - (d - 1) / len;
  return k * k;
}

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

// Swaps per lap, as slot pairs (0 = P1). The first pair of every lap is the
// hero passing the car ahead; the rest shuffle the field behind it.
const SWAPS: number[][][] = [
  [[6, 7]],
  [
    [5, 6],
    [2, 3],
  ],
  [
    [4, 5],
    [8, 9],
  ],
  [[3, 4]],
  [
    [2, 3],
    [6, 7],
  ],
  [[1, 2]],
  [
    [0, 1],
    [8, 9],
  ],
];

function TimingTowerBase({
  code = "RMC",
  field = ["KRV", "DLA", "MTS", "BRN", "OKO", "VAL", "PIR", "SAN", "TOR"],
  lap = 41,
  laps = 58,
  interval = "+12.408",
  intervalLabel = "Gap to P2",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: TimingTowerProps) {
  // Starts four frames in, so frame 0 already shows the tower wiping in.
  const t = useCurrentFrame() * speed + 4;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);

  // ── Orders per lap ────────────────────────────────────────────────────────
  const cars = [...field.slice(0, 7), code, ...field.slice(7, 9)];
  const hero = 7;
  const orders: number[][] = [cars.map((_, i) => i)];
  for (const pairs of SWAPS) {
    const next = [...orders[orders.length - 1]];
    for (const [a, b] of pairs) {
      const tmp = next[a];
      next[a] = next[b];
      next[b] = tmp;
    }
    orders.push(next);
  }
  let k = 0;
  while (k < LAP_AT.length && t >= LAP_AT[k]) k++;
  const from = orders[Math.max(0, k - 1)];
  const to = orders[k];
  const swapP = k === 0 ? 1 : SWAP_EASE(ramp(t, LAP_AT[k - 1], SWAP));
  const slotIn = (order: number[], car: number) => order.indexOf(car);
  const heroSlot = slotIn(to, hero);
  const heroPos = heroSlot + 1;
  const p1At = LAP_AT[LAP_AT.length - 1];
  const p1 = SWAP_EASE(ramp(t, p1At + SWAP - 1, 6));

  // ── Layout ────────────────────────────────────────────────────────────────
  const towerX = 64 * u;
  const towerW = 388 * u;
  const headH = 58 * u;
  const pitch = 50 * u;
  const rowH = 46 * u;
  const towerY = (H - (headH + 8 * u + 10 * pitch - (pitch - rowH))) / 2;
  const rowsY = towerY + headH + 8 * u;
  const posW = 50 * u;

  const enter = (delay: number) => EASE(ramp(t, delay, 9));
  const exitP = (slot: number) =>
    EXIT_EASE(ramp(t, EXIT_AT + (9 - slot) * 0.8, 9));
  const exitDX = towerX + towerW + 60 * u;

  const lapNow = lap + k;
  const lapFlash = k > 0 ? flash(t - LAP_AT[k - 1], 8) : 0;

  // Interval to the car ahead: rewritten every lap, leader shows "Leader".
  const gapText = (slot: number) => {
    if (slot === 0) return "Leader";
    const v = 0.18 + 1.6 * hash(slot * 13.1 + k * 7.7);
    return `+${v.toFixed(3)}`;
  };

  // Hero flash on every pass.
  const passFlash = LAP_AT.reduce(
    (a, at) => Math.max(a, flash(t - at - 3, 12)),
    0,
  );

  // ── Giant numeral & poster ────────────────────────────────────────────────
  const giantFs = 400 * u;
  const cellW = 0.58 * giantFs;
  const posterP = MOVE(ramp(t, EXIT_AT + 7, 18));
  const blockIn = (d: number) => EASE(ramp(t, EXIT_AT + 15 + d, 12));
  const giantShift = (1 - posterP) * 420 * u;
  const giantIn = EASE(ramp(t, 6, 12));
  const intervalNum = Number.parseFloat(interval.replace(/[^0-9.]/g, "")) || 0;
  const decimals = (interval.split(".")[1] ?? "").length;
  const countP = Easing.bezier(0.22, 1, 0.36, 1)(ramp(t, EXIT_AT + 19, 18));
  const intervalText = `${interval.trim().startsWith("-") ? "−" : "+"}${(intervalNum * countP).toFixed(decimals)}`;

  // Which digit is rolling in the giant numeral.
  const lastPass = k > 0 ? LAP_AT[k - 1] : -100;
  const rollP = SWAP_EASE(ramp(t, lastPass + 2, 8));
  const prevPos = k > 0 ? slotIn(from, hero) + 1 : heroPos;

  // One glyph, stacked: ink, then the green flash and the purple P1 fill as
  // clip-text copies on top (each glyph clips its own gradient).
  const glyph = (ch: string | number) => {
    const fills: [string, number][] = [
      [GREEN, passFlash * (1 - p1)],
      [PURPLE, p1],
    ];
    return (
      <span style={{ position: "relative", display: "inline-block" }}>
        <span style={{ color: c.ink, opacity: 1 - p1 }}>{ch}</span>
        {fills.map(([fill, op]) =>
          op > 0 ? (
            <span
              key={fill}
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                opacity: op,
                backgroundImage: fill,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }}
            >
              {ch}
            </span>
          ) : null,
        )}
      </span>
    );
  };

  const digitLayer = (n: number, y: number, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: cellW,
        height: giantFs,
        transform: `translateY(${y}px)`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {glyph(n)}
    </div>
  );

  const giantText = (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        fontFamily: saira,
        fontWeight: 500,
        fontSize: giantFs,
        lineHeight: 1,
        letterSpacing: "-0.03em",
        fontVariantNumeric: "tabular-nums",
      }}
    >
      {glyph("P")}
      <div
        style={{
          position: "relative",
          width: cellW,
          height: giantFs,
          overflow: "hidden",
          marginLeft: -0.02 * giantFs,
        }}
      >
        {rollP < 1 && prevPos !== heroPos
          ? [
              digitLayer(prevPos, -rollP * giantFs, "out"),
              digitLayer(heroPos, (1 - rollP) * giantFs, "in"),
            ]
          : digitLayer(heroPos, 0, "now")}
      </div>
    </div>
  );

  const giantW = 0.62 * giantFs + cellW;

  // Aurora ground under the poster, gently drifting.
  const drift = interpolate(t, [0, 165], [0, 8], CLAMP);
  const ground = [
    `radial-gradient(34% 60% at ${62 - drift}% 30%, color-mix(in oklab, ${AURORA[3]} 55%, transparent) 0%, transparent 70%)`,
    `radial-gradient(34% 60% at ${84 - drift}% 38%, color-mix(in oklab, ${AURORA[2]} 65%, transparent) 0%, transparent 70%)`,
    `radial-gradient(30% 55% at ${30 + drift}% 34%, color-mix(in oklab, ${AURORA[1]} 35%, transparent) 0%, transparent 70%)`,
    `linear-gradient(180deg, transparent 40%, color-mix(in oklab, ${AURORA[2]} 30%, transparent) 72%, transparent 100%)`,
  ].join(", ");
  const groundOp = c.ground * (0.25 * giantIn + 0.75 * p1);

  // Rows, hero rendered last so it passes over the others.
  const drawOrder = cars.map((_, i) => i).filter((i) => i !== hero);
  drawOrder.push(hero);

  const rows = drawOrder.map((car) => {
    const a = slotIn(from, car);
    const b = slotIn(to, car);
    const slot = a + (b - a) * swapP;
    const settled = b;
    const isHero = car === hero;
    const passing = a !== b && b < a ? Math.sin(Math.PI * swapP) : 0;
    const ent = enter(3 + settled * 1.2);
    const ex = exitP(settled);
    const x = towerX - (1 - ent) * (towerW + towerX) - ex * exitDX;
    const y = rowsY + slot * pitch;
    const stripe = isHero ? PURPLE : c.stripes[(car * 3) % c.stripes.length];
    return (
      <div
        key={cars[car]}
        style={{
          position: "absolute",
          left: x + posW + 4 * u + passing * 14 * u,
          top: y,
          width: towerW - posW - 4 * u,
          height: rowH,
          background: c.row,
          boxShadow: `inset 0 0 0 ${1 * u}px ${c.rowEdge}`,
          display: "flex",
          alignItems: "center",
          overflow: "hidden",
        }}
      >
        {isHero ? (
          <>
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: `linear-gradient(90deg, ${AURORA[1]} 0%, color-mix(in oklab, ${AURORA[1]} 25%, transparent) 100%)`,
                opacity: passFlash * (1 - p1) * 0.85,
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: `linear-gradient(90deg, ${AURORA[3]} 0%, #7A4FB8 40%, ${AURORA[2]} 100%)`,
                clipPath: `inset(0 ${(1 - p1) * 100}% 0 0)`,
              }}
            />
          </>
        ) : null}
        <div
          style={{
            position: "relative",
            width: 6 * u,
            height: rowH - 16 * u,
            marginLeft: 12 * u,
            background: isHero ? GREEN : stripe,
            flexShrink: 0,
          }}
        />
        <div
          style={{
            position: "relative",
            marginLeft: 14 * u,
            fontFamily: saira,
            fontWeight: 500,
            fontSize: 27 * u,
            letterSpacing: "0.06em",
            color: isHero && (p1 > 0.5 || passFlash > 0.4) ? "#FFFFFF" : c.ink,
            flex: 1,
            paddingTop: 1 * u,
          }}
        >
          {cars[car]}
        </div>
        <div
          style={{
            position: "relative",
            marginRight: 18 * u,
            fontFamily: saira,
            fontWeight: 400,
            fontSize: 22 * u,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: settled === 0 ? "0.08em" : "0.01em",
            textTransform: "uppercase",
            color: isHero && p1 > 0.5 ? "#FFFFFF" : c.dim,
          }}
        >
          {gapText(settled)}
        </div>
      </div>
    );
  });

  // Position boxes stay put; the cars move past them.
  const posBoxes = cars.map((_, s) => {
    const ent = enter(3 + s * 1.2);
    const ex = exitP(s);
    return (
      <div
        key={`pos-${s + 1}`}
        style={{
          position: "absolute",
          left: towerX - (1 - ent) * (towerW + towerX) - ex * exitDX,
          top: rowsY + s * pitch,
          width: posW,
          height: rowH,
          background: c.pos,
          color: c.posInk,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: saira,
          fontWeight: 500,
          fontSize: 25 * u,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {s + 1}
      </div>
    );
  });

  const headEnt = enter(0);
  const headEx = exitP(-1);

  const label: React.CSSProperties = {
    fontFamily: mono,
    fontWeight: 500,
    fontSize: 16 * u,
    letterSpacing: "0.14em",
    textTransform: "uppercase",
    color: c.dim,
  };

  return (
    <AbsoluteFill style={{ background: c.stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: ground,
          opacity: groundOp,
        }}
      />

      {/* Tower header: lap counter. */}
      <div
        style={{
          position: "absolute",
          left: towerX - (1 - headEnt) * (towerW + towerX) - headEx * exitDX,
          top: towerY,
          width: towerW,
          height: headH,
          background: c.head,
          display: "flex",
          alignItems: "center",
          paddingLeft: 18 * u,
          paddingRight: 18 * u,
          gap: 12 * u,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            right: 0,
            height: 4 * u,
            background: `linear-gradient(90deg, ${AURORA[0]} 0%, ${AURORA[1]} 35%, ${AURORA[2]} 70%, ${AURORA[3]} 100%)`,
          }}
        />
        <div
          style={{
            width: 9 * u,
            height: 9 * u,
            background: accent,
            opacity: Math.floor(t / 15) % 2 === 0 ? 1 : 0.35,
          }}
        />
        <div
          style={{
            fontFamily: saira,
            fontWeight: 500,
            fontSize: 26 * u,
            letterSpacing: "0.08em",
            color: "#F3F2EF",
            flex: 1,
            paddingTop: 2 * u,
          }}
        >
          LAP{" "}
          <span
            style={{
              fontVariantNumeric: "tabular-nums",
              color: lapFlash > 0.3 ? AURORA[0] : "#F3F2EF",
            }}
          >
            {lapNow}
          </span>
          <span style={{ color: "#8A8990" }}>/{laps}</span>
        </div>
        <div style={{ ...label, color: "#8A8990", fontSize: 13 * u }}>
          Interval
        </div>
      </div>

      {posBoxes}
      {rows}

      {/* Giant numeral; slides left into the poster with the info block. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 52 * u,
            transform: `translateX(${giantShift}px)`,
          }}
        >
          <div
            style={{
              position: "relative",
              width: giantW,
              height: giantFs,
              transform: `translateY(${(1 - giantIn) * 60 * u}px)`,
              opacity: giantIn,
            }}
          >
            <div
              style={{
                ...label,
                position: "absolute",
                left: 0.02 * giantFs,
                top: 0.06 * giantFs,
                opacity: 1 - posterP,
              }}
            >
              {code} · Position
            </div>
            {giantText}
          </div>

          {/* Poster block: code, team, interval. */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              width: 400 * u,
            }}
          >
            <div style={{ overflow: "hidden" }}>
              <div
                style={{
                  fontFamily: saira,
                  fontWeight: 500,
                  fontSize: 150 * u,
                  lineHeight: 0.9,
                  letterSpacing: "0.02em",
                  color: c.ink,
                  transform: `translateY(${(1 - blockIn(0)) * 100}%)`,
                }}
              >
                {code}
              </div>
            </div>
            <div
              style={{
                marginTop: 18 * u,
                opacity: blockIn(3),
                transform: `translateX(${(1 - blockIn(3)) * -30 * u}px)`,
              }}
            >
              <RemocnLogo fontSize={46 * u} color={c.ink} />
            </div>
            <div
              style={{
                marginTop: 34 * u,
                width: 360 * u,
                height: 2 * u,
                background: c.faint,
                transformOrigin: "0 0",
                transform: `scaleX(${blockIn(5)})`,
              }}
            />
            <div
              style={{
                ...label,
                marginTop: 16 * u,
                opacity: blockIn(6),
              }}
            >
              {intervalLabel}
            </div>
            <div
              style={{
                marginTop: 4 * u,
                fontFamily: saira,
                fontWeight: 500,
                fontSize: 78 * u,
                lineHeight: 1,
                letterSpacing: "-0.01em",
                fontVariantNumeric: "tabular-nums",
                color: c.greenInk,
                opacity: blockIn(6),
                transform: `translateX(${(1 - blockIn(6)) * -30 * u}px)`,
              }}
            >
              {intervalText}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  code: {
    type: "text-content",
    default: "RMC",
    description: "Code",
  },
  interval: {
    type: "text-content",
    default: "+12.408",
    description: "Interval",
  },
  intervalLabel: {
    type: "text-content",
    default: "Gap to P2",
    description: "Interval label",
  },
  lap: {
    type: "number",
    default: 41,
    min: 0,
    max: 123,
    step: 1,
    description: "Lap",
    hiddenFromList: false,
  },
  laps: {
    type: "number",
    default: 58,
    min: 0,
    max: 174,
    step: 1,
    description: "Laps",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","code","interval","intervalLabel","lap","laps","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  code: "RMC",
  interval: "+12.408",
  intervalLabel: "Gap to P2",
  lap: 41,
  laps: 58,
  speed: 1,
};

type TimingTowerElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TimingTowerBase>;

const TimingTowerInner = forwardRef<
  HTMLDivElement,
  TimingTowerElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TimingTower>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TimingTowerBase
          {...(componentProps as unknown as ComponentProps<typeof TimingTowerBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TimingTower = Interactive.withSchema({
  Component: TimingTowerInner,
  componentName: "<TimingTower>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type TinyPlanetColors = {
  sky: string;
  ground: string;
  near: string;
  far: string;
  window: string;
  sun: string;
};

type TinyPlanetProps = {
  /** Buildings in the front row; the back row gets a matching count. */
  buildings?: number;
  seed?: number;
  /** Planet spin once bent, in degrees per frame at 30fps. */
  spin?: number;
  colors?: Partial<TinyPlanetColors>;
  /** Sky color. Overrides `colors.sky`. */
  skyColor?: string;
  /** Sun color. Overrides `colors.sun`. */
  sunColor?: string;
  /** Front-row building color. Overrides `colors.near`. */
  buildingColor?: string;
  /** Ground color. Overrides `colors.ground`. */
  groundColor?: string;
  speed?: number;
};

const tinyPlanetDefaults = {
  buildings: 26,
  seed: 4,
  spin: 0.7,
  colors: {
    sky: "#111111",
    ground: "#262626",
    near: "#FFFFFF",
    far: "#6B6B6B",
    window: "#111111",
    sun: "#E5322D",
  } satisfies TinyPlanetColors,
  speed: 1,
};

const BEND_START = 8;
const BEND_END = 40;
const SPIN_RAMP = 14;

type Block = { s0: number; s1: number; h: number; row: 0 | 1; spire: number };

function makeCity(length: number, height: number, count: number, seed: number) {
  const blocks: Block[] = [];
  for (const row of [1, 0] as const) {
    const n = row === 1 ? Math.round(count * 0.8) : count;
    const slot = length / n;
    for (let i = 0; i < n; i++) {
      const key = `tiny-planet-${seed}-${row}-${i}`;
      const w = slot * (0.55 + random(`${key}-w`) * 0.4);
      const start =
        i * slot + random(`${key}-x`) * (slot - w) + (row ? slot * 0.5 : 0);
      const tall = random(`${key}-h`);
      const h = row
        ? height * (0.13 + tall * 0.16)
        : height * (0.05 + tall * tall * 0.15);
      const spire = random(`${key}-s`) < 0.18 ? height * 0.04 : 0;
      blocks.push({
        s0: start - length / 2,
        s1: start + w - length / 2,
        h,
        row,
        spire,
      });
    }
  }
  return blocks;
}

function TinyPlanetBase({
  buildings = tinyPlanetDefaults.buildings,
  seed = tinyPlanetDefaults.seed,
  spin = tinyPlanetDefaults.spin,
  colors: colorOverrides,
  skyColor,
  sunColor,
  buildingColor,
  groundColor,
  speed = tinyPlanetDefaults.speed,
}: TinyPlanetProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const baseColors = { ...tinyPlanetDefaults.colors, ...colorOverrides };
  const colors = {
    ...baseColors,
    sky: skyColor ?? baseColors.sky,
    sun: sunColor ?? baseColors.sun,
    near: buildingColor ?? baseColors.near,
    ground: groundColor ?? baseColors.ground,
  };
  const t = (frame * speed * 30) / fps;

  // The skyline strip is exactly as long as the planet's circumference.
  const length = width;
  const radius = length / (2 * Math.PI);
  const city = useMemo(
    () => makeCity(length, height, Math.max(4, Math.round(buildings)), seed),
    [length, height, buildings, seed],
  );

  const bend = interpolate(t, [BEND_START, BEND_END], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  // Spin eases in while the strip closes, then turns at a steady rate.
  const spinT = Math.max(0, t - (BEND_END - SPIN_RAMP));
  const turn =
    spinT < SPIN_RAMP
      ? (spin * spinT * spinT) / (2 * SPIN_RAMP)
      : spin * (spinT - SPIN_RAMP / 2);
  const rot = (turn * Math.PI) / 180;

  const kappa = Math.max(1e-5, bend / radius);
  const horizon = height * 0.7;
  const tallest = height * 0.33;
  const finalScale = (height * 0.43) / (radius + tallest);
  const scale = 1 + (finalScale - 1) * bend;
  const anchorY = horizon + (height / 2 - finalScale * radius - horizon) * bend;

  // Bend: arc-length s and height h onto a circle of curvature kappa whose
  // top sits at the pivot. kappa -> 0 is the flat skyline.
  const map = (s: number, h: number): [number, number] => {
    const a = kappa * s + rot * bend;
    const rr = 1 / kappa + h;
    const x = Math.sin(a) * rr;
    const y = 1 / kappa - Math.cos(a) * rr;
    return [width / 2 + x * scale, anchorY + y * scale];
  };
  const P = (s: number, h: number) =>
    map(s, h)
      .map((v) => v.toFixed(1))
      .join(",");

  const steps = 160;
  const depth = Math.min(1 / kappa, height * 3);
  let ground = "";
  for (let i = 0; i <= steps; i++) {
    const s = -length / 2 + (length * i) / steps;
    ground += `${i ? "L" : "M"}${P(s, 0)}`;
  }
  for (let i = steps; i >= 0; i--) {
    const s = -length / 2 + (length * i) / steps;
    ground += `L${P(s, -depth)}`;
  }

  const sunX = interpolate(bend, [0, 1], [width * 0.7, width * 0.8]);
  const sunY = interpolate(bend, [0, 1], [height * 0.36, height * 0.2]);
  const sunR = height * interpolate(bend, [0, 1], [0.12, 0.075]);

  return (
    <AbsoluteFill style={{ backgroundColor: colors.sky, overflow: "hidden" }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <circle cx={sunX} cy={sunY} r={sunR} fill={colors.sun} />
        {city.map((b, i) => {
          const sub = 4;
          const top: string[] = [];
          for (let k = 0; k <= sub; k++)
            top.push(P(b.s0 + ((b.s1 - b.s0) * k) / sub, b.h));
          const mid = (b.s0 + b.s1) / 2;
          const spire = b.spire
            ? ` M${P(mid - 1.5, b.h)} L${P(mid, b.h + b.spire)} L${P(mid + 1.5, b.h)}`
            : "";
          const d = `M${P(b.s0, -2)} L${top.join(" L")} L${P(b.s1, -2)} Z${spire}`;
          return (
            <path
              key={i}
              d={d}
              fill={b.row ? colors.far : colors.near}
              stroke={b.row ? colors.far : colors.near}
              strokeWidth={b.spire ? 2 * scale : 0}
            />
          );
        })}
        {city.map((b, i) => {
          if (b.row || b.h < height * 0.09) return null;
          const cols = Math.max(1, Math.floor((b.s1 - b.s0) / (height * 0.03)));
          const rows = Math.floor(b.h / (height * 0.04));
          const cells: string[] = [];
          for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
              if (random(`tiny-planet-${seed}-win-${i}-${r}-${c}`) < 0.55)
                continue;
              const s = b.s0 + ((b.s1 - b.s0) * (c + 0.5)) / cols;
              const h = b.h - height * 0.03 - r * height * 0.04;
              const ws = height * 0.006;
              cells.push(
                `M${P(s - ws, h)} L${P(s + ws, h)} L${P(s + ws, h - ws * 2.2)} L${P(s - ws, h - ws * 2.2)} Z`,
              );
            }
          }
          return (
            <path key={`w${i}`} d={cells.join(" ")} fill={colors.window} />
          );
        })}
        <path d={ground} fill={colors.ground} />
      </svg>
    </AbsoluteFill>
  );
}

