          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TinyPlanetBase
          {...(componentProps as unknown as ComponentProps<typeof TinyPlanetBase>)}
        />
      </div>
    </Sequence>
  );
});

