/** Rulers then radius arcs, each `stagger` frames after the last. */
function MeasureMarks({
  measures,
  radii = [],
  color,
  start = 0,
  stagger = 5,
}: {
  measures: Measure[];
  radii?: RadiusMark[];
  color: string;
  start?: number;
  stagger?: number;
}) {
  return (
    <>
      {measures.map((m, i) => (
        <Ruler
          key={`${m.from.join()}-${m.to.join()}`}
          from={m.from}
          to={m.to}
          label={m.label}
          color={color}
          delay={start + i * stagger}
          labelSide={m.side}
        />
      ))}
      {radii.map((r, i) => (
        <CornerArc
          key={`${r.x}-${r.y}`}
          x={r.x}
          y={r.y}
          r={r.r}
          label={r.label}
          color={color}
          delay={start + (measures.length + i) * stagger}
        />
      ))}
    </>
  );
}

const NOTE_SPOT = {
  start: (r: Rect) => ({
    x: r.x - 3,
    y: r.y - 3,
    anchor: "aboveStart" as const,
