  end: (r: Rect) => ({
    x: r.x + r.w + 3,
    y: r.y - 3,
    anchor: "aboveEnd" as const,
  }),
  below: (r: Rect) => ({
    x: r.x - 3,
    y: r.y + r.h + 3,
