/** Column guides drop in, the highlight fills, then the now line slides across. */
function GuideMarks({
  guides,
  color,
  nowColor = C.primary,
  start = 0,
}: {
  guides: GuideSpec;
  color: string;
  nowColor?: string;
  start?: number;
}) {
  const { columns, top, bottom, highlight, ruler, now } = guides;
  const h = highlight?.rect;
  return (
    <>
      {columns.map((x, i) => (
        <Guide
          key={x}
          x={x}
          y={top}
          length={bottom - top}
          vertical
          color={color}
          dashed
          delay={start + i * 3}
        />
      ))}
      {h && highlight && (
        <>
          <OutlineBox
            rect={h}
            color={color}
            fill={`${color}14`}
            inset={0}
            radius={0}
            delay={start + 14}
          />
          <OutlineBox
            rect={{ x: h.x + 6, y: h.y + 4, w: h.w - 12, h: 22 }}
            color={color}
            radius={4}
            inset={0}
            delay={start + 20}
          />
          <Pill
            x={h.x + h.w / 2}
            y={h.y + 4}
            text={highlight.label}
            color={color}
            delay={start + 26}
            anchor="above"
          />
        </>
      )}
      {ruler && (
        <Ruler
          from={ruler.from}
          to={ruler.to}
          label={ruler.label}
          color={color}
          delay={start + 24}
          labelSide={ruler.side}
        />
      )}
      {now && (
        <>
          <Guide
            x={now.from}
            y={now.y}
            length={now.to - now.from}
            color={nowColor}
            width={1.5}
            delay={start + 30}
          />
          <Pill
            x={now.from}
            y={now.y}
            text={now.label}
            color={nowColor}
            delay={start + 30}
            anchor="left"
          />
        </>
      )}
    </>
  );
}

