  /** Default front face color. Overrides `colors.front`. */
  frontColor?: string;
  /** Card edge color. Overrides `colors.edge`. */
  edgeColor?: string;
  /** Default back face color. Overrides `colors.back`. */
  backColor?: string;
  /** Stage background. Overrides `colors.background`. */
  backgroundColor?: string;
