};

const turntableDefaults = {
  thickness: 22,
  turns: 1,
  tilt: 8,
  colors: {
    background: "#111111",
    front: "#E5322D",
    back: "#F2F2F2",
    edge: "#A3201C",
    mark: "#FFFFFF",
    shadow: "#000000",
  } satisfies TurntableColors,
  speed: 1,
};

const START = 6;
const END = 64;

function DefaultFront({ colors }: { colors: TurntableColors }) {
  return (
    <AbsoluteFill
      style={{
        backgroundColor: colors.front,
        padding: "9%",
        justifyContent: "space-between",
      }}
