import { AbsoluteFill, isHtmlInCanvasSupported, useCurrentFrame, useDelayRender, useVideoConfig } from "remotion";
import React from "react";
import { type TransitionPresentation, type TransitionPresentationComponentProps } from "@remotion/transitions";

const QUAD = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

const VERTEX_SHADER = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;
void main() {
  v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5);
  gl_Position = vec4(a_pos, 0.0, 1.0);
}`;

const LAYER: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
};

const OUTPUT_LAYER: React.CSSProperties = { ...LAYER, pointerEvents: "none" };

const isCanvasTransitionSupported = (): boolean =>
  isHtmlInCanvasSupported();

const isCanvasFilterSupported = (): boolean => isHtmlInCanvasSupported();

type SceneShaderFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderDrawParams<Props> = {
  from: OffscreenCanvas | null;
  to: OffscreenCanvas | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderInstance<Props> = {
  draw: (params: SceneShaderDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneShader<Props> = (
  canvas: OffscreenCanvas,
) => SceneShaderInstance<Props>;

type SceneFilterFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterDrawParams<Props> = {
  scene: OffscreenCanvas | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterInstance<Props> = {
  draw: (params: SceneFilterDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneFilter<Props> = (
  canvas: OffscreenCanvas,
) => SceneFilterInstance<Props>;

function compileShader(
  gl: WebGL2RenderingContext,
  source: string,
  type: GLenum,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) {
    throw new Error("canvas-presentation: failed to create shader");
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(`canvas-presentation: failed to compile shader: ${log}`);
  }
  return shader;
}

function createProgram(
  gl: WebGL2RenderingContext,
  fragment: string,
): WebGLProgram {
  const program = gl.createProgram();
  if (!program) {
    throw new Error("canvas-presentation: failed to create program");
  }
  const vs = compileShader(gl, VERTEX_SHADER, gl.VERTEX_SHADER);
  const fs = compileShader(gl, fragment, gl.FRAGMENT_SHADER);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(`canvas-presentation: failed to link program: ${log}`);
  }
  return program;
}

function createSceneTexture(gl: WebGL2RenderingContext): WebGLTexture {
  const texture = gl.createTexture();
  if (!texture) {
    throw new Error("canvas-presentation: failed to create texture");
  }
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    1,
    1,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    new Uint8Array([0, 0, 0, 0]),
  );
  return texture;
}

function createQuadSurface(canvas: OffscreenCanvas, fragment: string) {
  const gl = canvas.getContext("webgl2", { premultipliedAlpha: true });
  if (!gl) {
    throw new Error("canvas-presentation: WebGL2 is unavailable");
  }

  const program = createProgram(gl, fragment);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, QUAD, gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const locations = new Map<string, WebGLUniformLocation | null>();
  const uniform = (name: string) => {
    const cached = locations.get(name);
    if (cached !== undefined) {
      return cached;
    }
    const location = gl.getUniformLocation(program, name);
    locations.set(name, location);
    return location;
  };

  const clear = () => {
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  };

  const textures: WebGLTexture[] = [];
  const createTexture = () => {
    const texture = createSceneTexture(gl);
    textures.push(texture);
    return texture;
  };

  const begin = (width: number, height: number) => {
    gl.viewport(0, 0, width, height);
    clear();
    gl.useProgram(program);
    gl.bindVertexArray(vao);
  };

  const bindScene = (
    image: OffscreenCanvas | null,
    texture: WebGLTexture,
    unit: number,
    name: string,
  ) => {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    if (image) {
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        image,
      );
    }
    gl.uniform1i(uniform(name), unit);
  };

  const draw = () => gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  const cleanup = () => {
    gl.deleteProgram(program);
    for (const texture of textures) {
      gl.deleteTexture(texture);
    }
    gl.deleteBuffer(buffer);
    gl.deleteVertexArray(vao);
  };

  return {
    gl,
    uniform,
    clear,
    createTexture,
    begin,
    bindScene,
    draw,
    cleanup,
  };
}

function makeSceneShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneShaderFrame<Props>) => void,
): SceneShader<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const fromTexture = surface.createTexture();
    const toTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ from, to, width, height, progress, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(from, fromTexture, 0, "u_from");
        surface.bindScene(to, toTexture, 1, "u_to");

        surface.gl.uniform1f(surface.uniform("u_progress"), progress);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          progress,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

function makeFilterShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneFilterFrame<Props>) => void,
): SceneFilter<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const sceneTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ scene, width, height, frame, time, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(scene, sceneTexture, 0, "u_scene");

        surface.gl.uniform1f(surface.uniform("u_frame"), frame);
        surface.gl.uniform1f(surface.uniform("u_time"), time);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          frame,
          time,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

const transferred = new WeakMap<HTMLCanvasElement, OffscreenCanvas>();

function takeOffscreen(canvas: HTMLCanvasElement): OffscreenCanvas {
  const existing = transferred.get(canvas);
  if (existing) {
    return existing;
  }
  const created = canvas.transferControlToOffscreen();
  transferred.set(canvas, created);
  return created;
}

function makeCanvasComponent<Props extends Record<string, unknown>>(
  shader: SceneShader<Props>,
): React.FC<TransitionPresentationComponentProps<Props>> {
  return function CanvasScenePresentation({
    children,
    presentationProgress,
    presentationDirection,
    passedProps,
    onElementImage,
    onUnmount,
    bothEnteringAndExiting,
  }) {
    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneShaderInstance<Props> | null>(null);
    const passedPropsRef = React.useRef(passedProps);
    passedPropsRef.current = passedProps;
    const onElementImageRef = React.useRef(onElementImage);
    onElementImageRef.current = onElementImage;
    const onUnmountRef = React.useRef(onUnmount);
    onUnmountRef.current = onUnmount;

    const { delayRender, continueRender } = useDelayRender();
    const passThrough =
      bothEnteringAndExiting && presentationDirection === "exiting";

    const drawRef = React.useRef<
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => void
    >(() => undefined);
    drawRef.current = (prevImage, nextImage, progress) => {
      const instance = instanceRef.current;
      if (!instance) {
        return;
      }
      const handle = delayRender("canvas-presentation: paint");
      const to = prevImage;
      const from = nextImage;
      const width = from?.width ?? to?.width ?? 0;
      const height = from?.height ?? to?.height ?? 0;
      if (width === 0 || height === 0) {
        instance.clear();
        continueRender(handle);
        return;
      }
      instance.draw({
        from,
        to,
        width,
        height,
        progress: !to ? 0 : !from ? 1 : progress,
        passedProps: passedPropsRef.current,
      });
      continueRender(handle);
    };

    const draw = React.useCallback(
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => drawRef.current(prevImage, nextImage, progress),
      [],
    );

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [passThrough, shader]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        if (!scene || !capture || !context) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        onElementImageRef.current(capture, draw);
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, [passThrough, draw]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, [passThrough]);

    // biome-ignore lint/correctness/useExhaustiveDependencies: presentationProgress is the intentional trigger — a new progress value is what schedules the next paint
    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      layoutRef.current?.requestPaint?.();
    }, [passThrough, presentationProgress]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      return () => onUnmountRef.current();
    }, [passThrough]);

    if (passThrough) {
      return <>{children}</>;
    }

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasFilterProps = {
  children: React.ReactNode;
};

function makeFilterComponent<Props extends Record<string, unknown>>(
  shader: SceneFilter<Props>,
): React.FC<Props & CanvasFilterProps> {
  return function CanvasSceneFilter(props) {
    const frame = useCurrentFrame();
    const { fps } = useVideoConfig();
    const { delayRender, continueRender } = useDelayRender();

    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneFilterInstance<Props> | null>(null);

    const passedPropsRef = React.useRef(props);
    passedPropsRef.current = props;
    const frameRef = React.useRef(frame);
    frameRef.current = frame;
    const timeRef = React.useRef(frame / fps);
    timeRef.current = frame / fps;

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [shader]);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        const instance = instanceRef.current;
        if (!scene || !capture || !context || !instance) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        if (capture.width === 0 || capture.height === 0) {
          instance.clear();
          return;
        }
        instance.draw({
          scene: capture,
          width: capture.width,
          height: capture.height,
          frame: frameRef.current,
          time: timeRef.current,
          passedProps: passedPropsRef.current,
        });
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const handle = delayRender("canvas-presentation: filter paint");
      const settle = () => continueRender(handle);
      layout.addEventListener("paint", settle, { once: true });
      layout.requestPaint?.();
      return () => {
        layout.removeEventListener("paint", settle);
        continueRender(handle);
      };
    });

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {props.children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasPresentationOptions<Props extends Record<string, unknown>> = {
  shader: SceneShader<Props>;
  fallback: React.FC<TransitionPresentationComponentProps<Props>>;
};

function makeCanvasPresentation<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasPresentationOptions<Props>): (
  props: Props,
) => TransitionPresentation<Props> {
  const Canvas = makeCanvasComponent(shader);

  const Presentation: React.FC<TransitionPresentationComponentProps<Props>> = (
    props,
  ) =>
    isCanvasTransitionSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );

  return (props) => ({ component: Presentation, props });
}

type CanvasFilterOptions<Props extends Record<string, unknown>> = {
  shader: SceneFilter<Props>;
  fallback: React.FC<Props & CanvasFilterProps>;
};

function makeCanvasFilter<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasFilterOptions<Props>): React.FC<Props & CanvasFilterProps> {
  const Canvas = makeFilterComponent(shader);

  return function CanvasFilter(props) {
    return isCanvasFilterSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );
  };
}

export type TvPowerOffProps = {
  durationInFrames?: number;
  delay?: number;
  gain?: number;
  afterglow?: number;
  phosphor?: string;
};

const DEFAULTS = {
  durationInFrames: 18,
  delay: 0,
  gain: 1,
  afterglow: 1,
  phosphor: "#d8ecff",
};

const COLLAPSE_END = 0.6;
const PINCH_END = 0.82;
const MIN_SQUASH = 0.0055;
const MIN_PINCH = 0.004;
const CONCENTRATION = 0.3;
const DECAY_CURVE = 2.6;
const BLACKOUT_IN = 0.06;

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform vec2 u_resolution;
uniform float u_aspect;
uniform float u_progress;
uniform float u_gain;
uniform float u_afterglow;
uniform vec3 u_phosphor;

in vec2 v_uv;
out vec4 outColor;

const int TAPS = 32;
const int COLUMN_TAPS = 8;
const float GOLDEN = 0.6180339887;
const float COLLAPSE_END = ${COLLAPSE_END.toFixed(4)};
const float PINCH_END = ${PINCH_END.toFixed(4)};
const float MIN_SQUASH = ${MIN_SQUASH.toFixed(5)};
const float MIN_PINCH = ${MIN_PINCH.toFixed(5)};
const float CONCENTRATION = ${CONCENTRATION.toFixed(4)};
const float DECAY_CURVE = ${DECAY_CURVE.toFixed(4)};
const float BLACKOUT_IN = ${BLACKOUT_IN.toFixed(4)};

void main() {
  float p = u_progress;

  if (p <= 0.0) {
    outColor = texture(u_scene, v_uv);
    return;
  }
  if (p >= 1.0) {
    outColor = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }

  float collapse = clamp(p / COLLAPSE_END, 0.0, 1.0);
  float pinch = clamp((p - COLLAPSE_END) / (PINCH_END - COLLAPSE_END), 0.0, 1.0);
  float decayed = clamp((p - PINCH_END) / (1.0 - PINCH_END), 0.0, 1.0);

  vec2 scale = vec2(pow(MIN_PINCH, pinch), pow(MIN_SQUASH, collapse));
  vec2 centered = (v_uv - 0.5) / scale + 0.5;
  vec2 span = 1.0 / (scale * u_resolution);

  vec3 sum = vec3(0.0);
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    vec2 at = centered + vec2(
      (fract(fi * GOLDEN + 0.5) - 0.5) * span.x,
      ((fi + 0.5) / float(TAPS) - 0.5) * span.y
    );
    vec2 inside = step(vec2(0.0), at) * step(at, vec2(1.0));
    sum += texture(u_scene, at).rgb * inside.x * inside.y;
  }

  float concentrate = pow(1.0 / (scale.x * scale.y), CONCENTRATION);
  vec3 light =
    (sum / float(TAPS)) * (1.0 + (concentrate - 1.0) * max(u_gain, 0.0));

  float glow = max(u_afterglow, 0.0);
  float bleed = smoothstep(0.2, 0.8, collapse) * (1.0 - pinch) * glow;

  if (bleed > 0.0) {
    vec3 column = vec3(0.0);
    float cx = clamp(centered.x, 0.0, 1.0);
    for (int i = 0; i < COLUMN_TAPS; i++) {
      column +=
        texture(u_scene, vec2(cx, (float(i) + 0.5) / float(COLUMN_TAPS))).rgb;
    }
    column /= float(COLUMN_TAPS);

    float dy = v_uv.y - 0.5;
    float reach = 0.02 + 0.03 * collapse;
    light +=
      column *
      mix(vec3(1.0), u_phosphor, 0.65) *
      exp(-(dy * dy) / (reach * reach)) *
      bleed *
      0.9;
  }

  if (pinch > 0.0) {
    vec2 d = (v_uv - 0.5) * vec2(u_aspect, 1.0);
    float radius = max(0.045 * glow, 0.0005);
    light +=
      u_phosphor *
      exp(-dot(d, d) / (radius * radius)) *
      smoothstep(0.0, 0.5, pinch) *
      1.15;
  }

  light *= pow(max(1.0 - decayed, 0.0001), DECAY_CURVE);

  float blackout = smoothstep(0.0, BLACKOUT_IN, p);
  outColor = vec4(
    clamp(light, 0.0, 1.0),
    mix(texture(u_scene, v_uv).a, 1.0, blackout)
  );
}`;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

function powerProgress(props: TvPowerOffProps, frame: number): number {
  const {
    durationInFrames = DEFAULTS.durationInFrames,
    delay = DEFAULTS.delay,
  } = props;
  return clamp((frame - delay) / Math.max(1, durationInFrames), 0, 1);
}

const shader = makeFilterShader<TvPowerOffProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, width, height, frame, passedProps }) => {
    const {
      gain = DEFAULTS.gain,
      afterglow = DEFAULTS.afterglow,
      phosphor = DEFAULTS.phosphor,
    } = passedProps;
    gl.uniform1f(uniform("u_progress"), powerProgress(passedProps, frame));
    gl.uniform2f(uniform("u_resolution"), width, height);
    gl.uniform1f(uniform("u_gain"), gain);
    gl.uniform1f(uniform("u_afterglow"), afterglow);
    gl.uniform3fv(uniform("u_phosphor"), toRgb(phosphor));
  },
);

const TvPowerOffFallback: React.FC<TvPowerOffProps & CanvasFilterProps> = (
  props,
) => {
  const frame = useCurrentFrame();
  const {
    children,
    gain = DEFAULTS.gain,
    afterglow = DEFAULTS.afterglow,
    phosphor = DEFAULTS.phosphor,
  } = props;

  const p = powerProgress(props, frame);
  const collapse = clamp(p / COLLAPSE_END, 0, 1);
  const pinch = clamp((p - COLLAPSE_END) / (PINCH_END - COLLAPSE_END), 0, 1);
  const decayed = clamp((p - PINCH_END) / (1 - PINCH_END), 0, 1);

  const squash = MIN_SQUASH ** collapse;
  const pinchX = MIN_PINCH ** pinch;
  const concentrate = (1 / (squash * pinchX)) ** CONCENTRATION;
  const fade = (1 - decayed) ** DECAY_CURVE;

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          background: "#000000",
          opacity: clamp(p / BLACKOUT_IN, 0, 1),
        }}
      />
      <AbsoluteFill
        style={{
          scale: `${pinchX} ${squash}`,
          filter: `brightness(${1 + (concentrate - 1) * Math.max(gain, 0)})`,
          opacity: fade,
        }}
      >
        {children}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, ${phosphor} 0%, transparent 55%)`,
          opacity: clamp(pinch * afterglow, 0, 1) * fade,
        }}
      />
    </AbsoluteFill>
  );
};

export const TvPowerOff = makeCanvasFilter<TvPowerOffProps>({
  shader,
  fallback: TvPowerOffFallback,
});

import { loadVariableFont } from "@remotion/google-fonts/Urbanist";
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const urbanist = loadVariableFont("normal", { subsets: ["latin"] });

interface TwoHitProps {
  before?: string;
  after?: string;
  hitAt?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#0B0B0B", ink: "#FFFFFF", blue: "#2F6BFF" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", blue: "#1F4FE0" },
} as const;

const WGHT = 400;
const REST = -0.035;
const FIRST_GAIN = 0.32;
const MAX_TRACK = 0.75;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_ATTACK = Easing.bezier(0.2, 0.9, 0.3, 1);
const EASE_RELEASE = Easing.bezier(0.45, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  widths: number[][];
  baseline: number;
  cap: number;
}

function measure(phrases: string[][]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  let widths = phrases.map((lines) => lines.map((l) => l.length * 0.5));
  let baseline = 0.8;
  let cap = 0.7;
  if (ctx) {
    ctx.font = `${WGHT} 200px "${urbanist.fontFamily}"`;
    widths = phrases.map((lines) =>
      lines.map((l) => ctx.measureText(l).width / 200),
    );
    const fm = ctx.measureText("H");
    const asc = fm.fontBoundingBoxAscent / 200;
    const desc = fm.fontBoundingBoxDescent / 200;
    baseline = (1 - (asc + desc)) / 2 + asc;
    cap = fm.actualBoundingBoxAscent / 200;
  }
  return { widths, baseline, cap };
}

function useMetrics(phrases: string[][]) {
  const key = phrases.map((l) => l.join("\u0002")).join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("two-hit: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const list = key.split("\u0001").map((l) => l.split("\u0002"));
    Promise.all([
      urbanist.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${urbanist.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(list) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function pulse(x: number, attack: number, hold: number, release: number) {
  if (x <= 0) return 0;
  if (x < attack) return EASE_ATTACK(x / attack);
  if (x < attack + hold) return 1;
  return 1 - EASE_RELEASE(Math.min(1, (x - attack - hold) / release));
}

function splitLast(text: string) {
  const clean = text.trim().replace(/\s+/g, " ");
  const i = clean.lastIndexOf(" ");
  if (i < 0) return [clean];
  return [clean.slice(0, i), clean.slice(i + 1)];
}

function normalizeHex(c: string | undefined, fallback: string) {
  if (c && /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(c)) return c;
  return fallback;
}

function TwoHitBase({
  before = "Premieres Friday.",
  after = "Streaming now.",
  hitAt = 34,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: TwoHitProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const blue = normalizeHex(accent, c.blue);
  const a = before.trim() || "Soon.";
  const b = after.trim() || "Now.";
  const phrases = useMemo(() => [splitLast(a), splitLast(b)], [a, b]);
  const m = useMetrics(phrases);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.06 : 0.055);
  const span = W - margin * 2;
  const lens = phrases.map((lines) => lines.map((l) => Array.from(l).length));
  const restW = (i: number, j: number) =>
    m.widths[i][j] + REST * (lens[i][j] - 1);
  let widest = 0;
  phrases.forEach((lines, i) => {
    lines.forEach((_, j) => {
      widest = Math.max(widest, restW(i, j));
    });
  });
  const rows = Math.max(phrases[0].length, phrases[1].length);
  const LEAD = 0.98;
  const F = Math.min(
    (W * (portrait ? 0.86 : 0.62)) / widest,
    (H * (portrait ? 0.3 : 0.62)) / (m.cap + (rows - 1) * LEAD),
  );
  const peak = (i: number, j: number) =>
    Math.min(
      MAX_TRACK,
      Math.max(REST, (span / F - m.widths[i][j]) / Math.max(1, lens[i][j] - 1)),
    );

  const h1 = hitAt;
  const h2 = hitAt + 24;
  const swapAt = h2 + 7;
  const e1 = FIRST_GAIN * pulse(t - h1, 4, 0, 16);
  const e2 = pulse(t - h2, 5, 4, 24);
  const e = Math.max(e1, e2);
  const idx = t < swapAt ? 0 : 1;
  const lines = phrases[idx];

  const enter = (j: number) =>
    interpolate(t, [2 + j * 4, 20 + j * 4], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const blockH = (m.cap + (lines.length - 1) * LEAD) * F;
  const firstBase = H * (portrait ? 0.5 : 0.53) - blockH / 2 + m.cap * F;

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily: urbanist.fontFamily,
      }}
    >
      {lines.map((line, j) => {
        const track = REST + e * (peak(idx, j) - REST);
        const baseY = firstBase + j * LEAD * F;
        const p = enter(j);
        const last = j === lines.length - 1 && lines.length > 1;
        return (
          <div
            key={`${idx}-${j}`}
            style={{
              position: "absolute",
              right: margin,
              top: baseY - m.baseline * F - F * 0.1,
              height: F * 1.25,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                paddingTop: F * 0.1,
                fontSize: F,
                lineHeight: `${F}px`,
                fontVariationSettings: `"wght" ${WGHT}`,
                letterSpacing: `${track.toFixed(4)}em`,
                marginRight: `${(-track).toFixed(4)}em`,
                whiteSpace: "pre",
                color: last ? blue : c.ink,
                transform: `translateY(${((1 - p) * F * 1.05).toFixed(2)}px)`,
              }}
            >
              {line}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

