  "SY20 TA54 TG10 TJ80 TQ10 TS10 TT-40 Ta60 Tc50 Td50 Te50 Tg50 Tm20",
  "Tn20 To50 Tp20 Tq50 Tr20 Ts50 Tu20 UA10 Ua20 Uc10 Ud10 Ue10 Ug10 Uo10",
  "Uq10 Us10 VA50 VC25 VG25 VJ80 VO26 VQ25 VS25 Va50 Vc50 Vd50 Ve50 Vg50",
  "Vm20 Vn20 Vo50 Vp20 Vq50 Vr20 Vs50 Vu20 Vz20 WA30 WJ30 Wa35 Wd25 XC24",
  "XG24 XO24 XQ24 XS30 YA60 YC20 YG20 YJ90 YO26 YQ20 YS20 Ya70 Yc70 Yd70",
  "Ye70 Yf20 Yg70 Ym30 Yn30 Yo70 Yp30 Yq70 Yr30 Ys70 Yu30 Yv30 Yw20 Yx20",
  "Yz30 bT50 bV50 bY70 bc-10 bd-10 bf10 bx10 cT50 cV50 cY70 cc-10 cf10",
  "cx10 eT50 eV50 eY70 ec-10 ef10 ex10 fc10 fd10 fe10 fg10 fo10 fq10",
  "fs10 jj-20 oT50 oV50 oY70 of10 ox10 pT50 pV50 pY70 pc-10 pf20 pt20",
  "px10 qj-20 rc10 rd10 re10 rg10 ro10 rq10 rs10 rt-30 sT50 sV50 sY70",
  "sc-10 sf10 st10 sx15 vA30 xc10 xd10 xe10 xg10 xo10 xq10 xs10",
].join(" ");
const KERN = new Map(
  KERN_PAIRS.split(" ").map((p) => [p.slice(0, 2), -Number(p.slice(2)) / 1000]),
);

const TRACK = -0.03;
const ASC = 0.97;
const LINE = 1.275;
const CAP = 0.708;
const SPACE = 0.274 + TRACK;

const ENTER_STAGGER = 3;
const ENTER_LEN = 18;
const SQUIGGLE_AT = 20;
const SQUIGGLE_LEN = 14;
const SWAP_AT = 44;
const SWAP_STAGGER = 1;
const TRAVEL = 20;
const RETRACT_LEN = 10;
const RULE_DELAY = 1;
const RULE_LEN = 10;
const HOLD = 36;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Ground: gradients.sh "grain" (dark) and "smear" (light), a warm light
// from the top left, kept low so the type and the red squiggle stay crisp.
const THEMES = {
  dark: {
    bg: "#070505",
    fg: "#F5F1EC",
    dim: "#6A605B",
    error: "#FF5A4F",
    grain: 0.08,
    glow: "rgba(255, 216, 180, 0.36)",
    wash: [
      "rgba(224, 112, 59, 0.85)",
      "rgba(138, 44, 29, 0.62)",
      "rgba(43, 16, 21, 0.55)",
    ],
  },
  light: {
    bg: "#F5F2EC",
    fg: "#141212",
    dim: "#ABA39C",
    error: "#D9302C",
    grain: 0.05,
    glow: "rgba(255, 236, 200, 0.6)",
    wash: [
      "rgba(247, 178, 59, 0.62)",
      "rgba(242, 85, 44, 0.36)",
      "rgba(232, 137, 181, 0.2)",
    ],
  },
} as const;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? ONEST_500[code - 32] : 620) / 1000;
}

function textEm(s: string) {
  let w = 0;
  for (let i = 0; i < s.length; i++) {
    if (i > 0) w += KERN.get(s[i - 1] + s[i]) ?? 0;
    w += advance(s[i]) + TRACK;
  }
  return w;
}

function layoutWord(chars: string[]) {
  const xs: number[] = [];
  let x = 0;
  chars.forEach((ch, i) => {
    if (i > 0) x += KERN.get(chars[i - 1] + ch) ?? 0;
    xs.push(x);
    x += advance(ch) + TRACK;
  });
  return { xs, total: x };
}

function mapLetters(a: string[], b: string[]) {
  const used = new Array<boolean>(a.length).fill(false);
  const src = new Array<number>(b.length).fill(-1);
  b.forEach((ch, j) => {
    if (a[j] === ch) {
      src[j] = j;
      used[j] = true;
    }
  });
  const pick = (j: number, same: (x: string, y: string) => boolean) => {
    let best = -1;
    let bestD = Number.POSITIVE_INFINITY;
    a.forEach((ch, i) => {
      if (used[i] || !same(ch, b[j])) return;
      const d = Math.abs(i - j);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    if (best >= 0) used[best] = true;
    return best;
  };
  b.forEach((_, j) => {
    if (src[j] < 0) src[j] = pick(j, (x, y) => x === y);
  });
  b.forEach((_, j) => {
    if (src[j] < 0)
      src[j] = pick(j, (x, y) => x.toLowerCase() === y.toLowerCase());
  });
  const orphans = a.map((_, i) => i).filter((i) => !used[i]);
  return { src, orphans };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Glyph {
  key: string;
  ch: string;
  x0: number;
  x1: number;
  start: number;
  lift: number;
  over: boolean;
  fadeIn: boolean;
  fadeOut: boolean;
}

function typoFixDuration(wrong = "Lanuch") {
  return (
    SWAP_AT +
    Math.max(0, wrong.length - 1) * SWAP_STAGGER +
    TRAVEL +
    RULE_DELAY +
    RULE_LEN +
    HOLD
  );
}

function TypoFixBase({
  wrong = "Lanuch",
  correct = "Launch",
  before = "",
  after = "day",
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: TypoFixProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const clipId = `tf${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const a = useMemo(() => Array.from(wrong), [wrong]);
  const b = useMemo(() => Array.from(correct), [correct]);
  const la = useMemo(() => layoutWord(a), [a]);
  const lb = useMemo(() => layoutWord(b), [b]);
  const beforeW = before ? textEm(before) + SPACE : 0;
  const afterW = after ? SPACE + textEm(after) : 0;

  const glyphs = useMemo<Glyph[]>(() => {
    const { src, orphans } = mapLetters(a, b);
    let order = 0;
    const list: Glyph[] = b.map((ch, j) => {
      const i = src[j];
      const x1 = lb.xs[j];
      if (i < 0)
        return {
          key: `in-${j}`,
          ch,
          x0: x1,
          x1,
          start: SWAP_AT,
          lift: 0,
          over: true,
          fadeIn: true,
          fadeOut: false,
        };
      const x0 = la.xs[i];
      const dx = x1 - x0;
      const moving = Math.abs(dx) > 0.02;
      return {
        key: `m-${i}`,
        ch,
        x0,
        x1,
        start: SWAP_AT + (moving ? order++ * SWAP_STAGGER : 0),
        lift: moving ? Math.min(0.62, Math.max(0.44, Math.abs(dx) * 0.85)) : 0,
        over: dx > 0,
        fadeIn: false,
        fadeOut: false,
      };
    });
    for (const i of orphans)
      list.push({
        key: `o-${i}`,
        ch: a[i],
        x0: la.xs[i],
        x1: la.xs[i],
        start: SWAP_AT,
        lift: 0,
        over: false,
        fadeIn: false,
        fadeOut: true,
      });
    return list.sort((m, n) => Number(m.over) - Number(n.over));
  }, [a, b, la, lb]);

  const swapEnd = Math.max(...glyphs.map((g) => g.start)) + TRAVEL;
  const fix = EASE_IO(interpolate(t, [SWAP_AT, swapEnd], [0, 1], CLAMP));
  const wordW = la.total + (lb.total - la.total) * fix;
  const maxTotal = beforeW + Math.max(la.total, lb.total) - TRACK + afterW;
  const F = Math.min(H * 0.27, (W * 0.8) / Math.max(maxTotal, 0.1));
  const total = beforeW + wordW - TRACK + afterW;
  const left = -total / 2;
  const wordLeft = left + beforeW;
  const baseline = H / 2 + (CAP * F) / 2;

  const enter = (k: number) =>
    EASE_OUT(
      interpolate(
        t,
        [k * ENTER_STAGGER, k * ENTER_STAGGER + ENTER_LEN],
        [0, 1],
        CLAMP,
      ),
    );
  const wordEnter = enter(before ? 1 : 0);

  const ulY = baseline + 0.19 * F;
  const ulX0 = W / 2 + wordLeft * F;
  const ulX1 = W / 2 + (wordLeft + la.total - TRACK) * F;
  const amp = 0.036 * F;
  const wave = 0.13 * F;
  const pts: string[] = [];
  for (let x = ulX0; x <= ulX1 + 0.5; x += 2) {
    const y = ulY + amp * Math.sin(((x - ulX0) / wave) * Math.PI * 2);
    pts.push(`${x.toFixed(1)},${y.toFixed(1)}`);
  }
  const draw = EASE_OUT(
    interpolate(t, [SQUIGGLE_AT, SQUIGGLE_AT + SQUIGGLE_LEN], [0, 1], CLAMP),
  );
  const retractAt = swapEnd - RETRACT_LEN + 2;
  const retract = EASE_IO(
    interpolate(t, [retractAt, retractAt + RETRACT_LEN], [0, 1], CLAMP),
  );
  const clipL = ulX0 - amp + (ulX1 - ulX0 + 2 * amp) * retract;
  const clipR = ulX0 - amp + (ulX1 - ulX0 + 2 * amp) * draw;

  const ruleAt = swapEnd + RULE_DELAY;
  const rule = EASE_OUT(
    interpolate(t, [ruleAt, ruleAt + RULE_LEN], [0, 1], CLAMP),
  );
  const ruleT = Math.max(3, 0.045 * F);
  const ruleX0 = W / 2 + wordLeft * F;
  const ruleW = (lb.total - TRACK) * F;
  const settle = spring({
    frame: t - swapEnd,
    fps,
    config: { damping: 14, stiffness: 220, mass: 0.6 },
  });
  const tick = t >= swapEnd ? Math.sin(Math.PI * Math.min(1, settle)) : 0;

  const textStyle = {
    position: "absolute" as const,
    top: `${-ASC}em`,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre" as const,
    color: c.fg,
  };

  // The light drifts a few percent across the shot.
  const drift = interpolate(t, [0, swapEnd + RULE_LEN + HOLD], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gx = 10 + 5 * drift;
  const gy = 8 + 3 * drift;
  const ground = [
    `radial-gradient(48% 42% at ${gx.toFixed(2)}% ${gy.toFixed(2)}%, ${c.glow} 0%, transparent 60%)`,
    `linear-gradient(${(150 - 4 * drift).toFixed(2)}deg, ${c.wash[0]} 0%, ${c.wash[1]} 20%, ${c.wash[2]} 40%, transparent 62%)`,
  ].join(", ");

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, background: ground }} />
      <svg
        width={W}
        height={H}
        style={{ position: "absolute", inset: 0 }}
        aria-hidden
      >
        <defs>
          <clipPath id={clipId}>
            <rect
              x={clipL}
              y={ulY - amp * 3}
              width={Math.max(0, clipR - clipL)}
              height={amp * 6}
            />
          </clipPath>
        </defs>
        {draw > 0 && retract < 1 ? (
          <polyline
            points={pts.join(" ")}
            fill="none"
            stroke={c.error}
            strokeWidth={Math.max(2, 0.03 * F)}
            strokeLinecap="round"
            strokeLinejoin="round"
            clipPath={`url(#${clipId})`}
          />
        ) : null}
      </svg>
      {rule > 0 ? (
        <div
          style={{
            position: "absolute",
            left: ruleX0,
            top: ulY - ruleT / 2,
            width: ruleW * rule,
            height: ruleT,
            borderRadius: ruleT / 2,
            background: accent,
          }}
        />
      ) : null}
      <div
        style={{
          position: "absolute",
          left: W / 2,
          top: baseline,
          fontFamily: sans,
          fontWeight: 500,
          fontSize: F,
          lineHeight: LINE,
          fontKerning: "none",
        }}
      >
        {before ? (
          <div
            style={{
              ...textStyle,
              left: `${left}em`,
              fontKerning: "normal",
              opacity: enter(0),
              transform: `translateY(${(1 - enter(0)) * 0.2}em)`,
            }}
          >
            {before}
          </div>
        ) : null}
        <div
          style={{
            position: "absolute",
            left: `${wordLeft}em`,
            top: 0,
            opacity: wordEnter,
            transform: `translateY(${(1 - wordEnter) * 0.2 - tick * 0.035}em)`,
          }}
        >
          {glyphs.map((g) => {
            const p = EASE_IO(
              interpolate(t, [g.start, g.start + TRAVEL], [0, 1], CLAMP),
            );
            const arc = Math.sin(Math.PI * p);
            const x = g.x0 + (g.x1 - g.x0) * p;
            const y = g.over ? -g.lift * arc : g.lift * 0.85 * arc;
            const scale = g.lift
              ? g.over
                ? 1 + 0.08 * arc
                : 1 - 0.08 * arc
              : 1;
            let opacity = 1;
            if (g.fadeIn) opacity = interpolate(p, [0.4, 1], [0, 1], CLAMP);
            if (g.fadeOut) opacity = interpolate(p, [0, 0.6], [1, 0], CLAMP);
            const color =
              g.lift && !g.over
                ? interpolateColors(arc, [0, 1], [c.fg, c.dim])
                : c.fg;
            return (
              <div
                key={g.key}
                style={{
                  ...textStyle,
                  left: 0,
                  color,
                  opacity,
                  transform: `translate(${x}em, ${y}em) scale(${scale})`,
                  transformOrigin: `${advance(g.ch) / 2}em ${ASC}em`,
                }}
              >
                {g.ch}
              </div>
            );
          })}
        </div>
        {after ? (
          <div
            style={{
              ...textStyle,
              left: `${wordLeft + wordW + SPACE}em`,
              fontKerning: "normal",
              opacity: enter(before ? 2 : 1),
              transform: `translateY(${(1 - enter(before ? 2 : 1)) * 0.2}em)`,
            }}
          >
            {after}
          </div>
        ) : null}
      </div>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  wrong: {
    type: "text-content",
    default: "Lanuch",
    description: "Wrong",
  },
  correct: {
    type: "text-content",
    default: "Launch",
    description: "Correct",
  },
  before: {
    type: "text-content",
    default: "",
    description: "Before",
  },
  after: {
    type: "text-content",
    default: "day",
    description: "After",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","wrong","correct","before","after","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  wrong: "Lanuch",
  correct: "Launch",
  before: "",
  after: "day",
  speed: 1,
};

type TypoFixElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypoFixBase>;

const TypoFixInner = forwardRef<
  HTMLDivElement,
  TypoFixElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypoFix>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypoFixBase
          {...(componentProps as unknown as ComponentProps<typeof TypoFixBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypoFix = Interactive.withSchema({
  Component: TypoFixInner,
  componentName: "<TypoFix>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const geist = loadGeist("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const geistMono = loadGeistMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

interface UncommentLineProps {
  lines?: string[];
  marker?: string;
  highlight?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { pink: "#F472B6", bg: "#14151A", ink: "#FBF0DF" },
  light: { pink: "#C2185B", bg: "#FBF0DF", ink: "#14151A" },
} as const;

const TRACK = -0.035;
const LEADING = 1.06;
const MARK_SCALE = 0.62;
const DIM = 0.28;

const RISE_LEN = 16;
const RISE_GAP = 4;
const OPEN_AT = 34;
const OPEN_GAP = 13;
const OPEN_LEN = 14;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  lines: number[];
  marker: number;
  cap: number;
  base: number;
  baseM: number;
}

const baseOf = (asc: number, desc: number) => (1 - (asc + desc)) / 2 + asc;

function measure(lines: string[], marker: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) throw new Error("uncomment-line: no 2d context");
  ctx.font = `500 100px "${geist.fontFamily}"`;
  const widths = lines.map(
    (s) =>
      ctx.measureText(s).width / 100 +
      TRACK * Math.max(0, Array.from(s).length - 1),
  );
  const hm = ctx.measureText("H");
  ctx.font = `400 100px "${geistMono.fontFamily}"`;
  const mm = ctx.measureText(marker);
  return {
    lines: widths,
    marker: mm.width / 100,
    cap: hm.actualBoundingBoxAscent / 100,
    base: baseOf(
      hm.fontBoundingBoxAscent / 100,
      hm.fontBoundingBoxDescent / 100,
    ),
    baseM: baseOf(
      mm.fontBoundingBoxAscent / 100,
      mm.fontBoundingBoxDescent / 100,
    ),
  };
}

function useMetrics(lines: string[], marker: string) {
  const key = [marker, ...lines].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("uncomment-line: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [mk, ...ls] = key.split("\u0001");
    Promise.all([
      geist.waitUntilDone(),
      geistMono.waitUntilDone(),
      document.fonts.load(`500 100px "${geist.fontFamily}"`),
      document.fonts.load(`400 100px "${geistMono.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(ls, mk) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function UncommentLineBase({
  lines = ["Fork the scenes.", "Change anything.", "Own the cut."],
  marker = "// ",
  highlight = -1,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: UncommentLineProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.pink;
  const list = lines.length > 0 ? lines : [" "];
  const m = useMetrics(list, marker);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);
  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const hl = highlight < 0 ? list.length + highlight : highlight;
  const portrait = H > W * 1.1;
  const margin = Math.min(W, H) * (portrait ? 0.08 : 0.085);
  const measureW = W - 2 * margin;
  const markEm = m.marker * MARK_SCALE;
  const widest = Math.max(...m.lines) + markEm;
  const F = Math.min(
    (H * (portrait ? 0.4 : 0.7)) / (list.length * LEADING),
    measureW / widest,
  );
  const lineH = F * LEADING;
  const blockH = lineH * (list.length - 1) + m.cap * F;
  const firstBase = (H - blockH) / 2 + m.cap * F;
  const M = F * MARK_SCALE;

  const nodes = list.map((line, i) => {
    const baseY = firstBase + i * lineH;
    const r = interpolate(t, [i * RISE_GAP, i * RISE_GAP + RISE_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const at = OPEN_AT + i * OPEN_GAP;
    const o = interpolate(t, [at, at + OPEN_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const lit = interpolate(t, [at + 2, at + OPEN_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const textLeft = margin + markEm * F * (1 - o);
    const h = F * 1.3;
    const top = baseY - F * 1.05;
    const drop = (1 - r) * h;
    const color = i === hl ? spot : c.ink;
    const markOpacity = 1 - interpolate(o, [0, 0.6], [0, 1], CLAMP);
    return (
      <div key={`l${i}`}>
        {markOpacity > 0.001 ? (
          <div
            style={{
              position: "absolute",
              left: margin - F * 0.05,
              top,
              width: markEm * F + F * 0.1,
              height: h,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: F * 0.05 - o * markEm * F * 0.6,
                top: F * 1.05 - m.baseM * M + drop,
                height: M,
                lineHeight: `${M}px`,
                fontFamily: geistMono.fontFamily,
                fontWeight: 400,
                fontSize: M,
                whiteSpace: "pre",
                color: spot,
                opacity: markOpacity,
              }}
            >
              {marker}
            </div>
          </div>
        ) : null}
        <div
          style={{
            position: "absolute",
            left: textLeft - F * 0.05,
            top,
            width: m.lines[i] * F + F * 0.2,
            height: h,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: F * 0.05,
              top: F * 1.05 - m.base * F + drop,
              height: F,
              lineHeight: `${F}px`,
              fontFamily: geist.fontFamily,
              fontWeight: 500,
              fontSize: F,
              letterSpacing: `${TRACK}em`,
              whiteSpace: "pre",
              color,
              opacity: DIM + (1 - DIM) * lit,
            }}
          >
            {line}
          </div>
        </div>
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  marker: {
    type: "text-content",
    default: "// ",
    description: "Marker",
  },
  highlight: {
    type: "number",
    default: -1,
    min: -10,
    max: 10,
    step: 1,
    description: "Highlight",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","marker","highlight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  marker: "// ",
  highlight: -1,
  speed: 1,
};

type UncommentLineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof UncommentLineBase>;

const UncommentLineInner = forwardRef<
  HTMLDivElement,
  UncommentLineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<UncommentLine>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <UncommentLineBase
          {...(componentProps as unknown as ComponentProps<typeof UncommentLineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const UncommentLine = Interactive.withSchema({
  Component: UncommentLineInner,
  componentName: "<UncommentLine>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { AbsoluteFill, Interactive, Sequence, isHtmlInCanvasSupported, useCurrentFrame, useDelayRender, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";
import { type TransitionPresentation, type TransitionPresentationComponentProps } from "@remotion/transitions";

const QUAD = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

const VERTEX_SHADER = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;
void main() {
  v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5);
  gl_Position = vec4(a_pos, 0.0, 1.0);
}`;

const LAYER: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
};

const OUTPUT_LAYER: React.CSSProperties = { ...LAYER, pointerEvents: "none" };

const isCanvasTransitionSupported = (): boolean =>
  isHtmlInCanvasSupported();

const isCanvasFilterSupported = (): boolean => isHtmlInCanvasSupported();

type SceneShaderFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderDrawParams<Props> = {
  from: OffscreenCanvas | null;
  to: OffscreenCanvas | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderInstance<Props> = {
  draw: (params: SceneShaderDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneShader<Props> = (
  canvas: OffscreenCanvas,
) => SceneShaderInstance<Props>;

type SceneFilterFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterDrawParams<Props> = {
  scene: OffscreenCanvas | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterInstance<Props> = {
  draw: (params: SceneFilterDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneFilter<Props> = (
  canvas: OffscreenCanvas,
) => SceneFilterInstance<Props>;

function compileShader(
  gl: WebGL2RenderingContext,
  source: string,
  type: GLenum,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) {
    throw new Error("canvas-presentation: failed to create shader");
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(`canvas-presentation: failed to compile shader: ${log}`);
  }
  return shader;
}

function createProgram(
  gl: WebGL2RenderingContext,
  fragment: string,
): WebGLProgram {
  const program = gl.createProgram();
  if (!program) {
    throw new Error("canvas-presentation: failed to create program");
  }
  const vs = compileShader(gl, VERTEX_SHADER, gl.VERTEX_SHADER);
  const fs = compileShader(gl, fragment, gl.FRAGMENT_SHADER);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(`canvas-presentation: failed to link program: ${log}`);
  }
  return program;
}

function createSceneTexture(gl: WebGL2RenderingContext): WebGLTexture {
  const texture = gl.createTexture();
  if (!texture) {
    throw new Error("canvas-presentation: failed to create texture");
  }
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    1,
    1,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    new Uint8Array([0, 0, 0, 0]),
  );
  return texture;
}

function createQuadSurface(canvas: OffscreenCanvas, fragment: string) {
  const gl = canvas.getContext("webgl2", { premultipliedAlpha: true });
  if (!gl) {
    throw new Error("canvas-presentation: WebGL2 is unavailable");
  }

  const program = createProgram(gl, fragment);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, QUAD, gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const locations = new Map<string, WebGLUniformLocation | null>();
  const uniform = (name: string) => {
    const cached = locations.get(name);
    if (cached !== undefined) {
      return cached;
    }
    const location = gl.getUniformLocation(program, name);
    locations.set(name, location);
    return location;
  };

  const clear = () => {
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  };

  const textures: WebGLTexture[] = [];
  const createTexture = () => {
    const texture = createSceneTexture(gl);
    textures.push(texture);
    return texture;
  };

  const begin = (width: number, height: number) => {
    gl.viewport(0, 0, width, height);
    clear();
    gl.useProgram(program);
    gl.bindVertexArray(vao);
  };

  const bindScene = (
    image: OffscreenCanvas | null,
    texture: WebGLTexture,
    unit: number,
    name: string,
  ) => {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    if (image) {
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        image,
      );
    }
    gl.uniform1i(uniform(name), unit);
  };

  const draw = () => gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  const cleanup = () => {
    gl.deleteProgram(program);
    for (const texture of textures) {
      gl.deleteTexture(texture);
    }
    gl.deleteBuffer(buffer);
    gl.deleteVertexArray(vao);
  };

  return {
    gl,
    uniform,
    clear,
    createTexture,
    begin,
    bindScene,
    draw,
    cleanup,
  };
}

function makeSceneShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneShaderFrame<Props>) => void,
): SceneShader<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const fromTexture = surface.createTexture();
    const toTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ from, to, width, height, progress, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(from, fromTexture, 0, "u_from");
        surface.bindScene(to, toTexture, 1, "u_to");

        surface.gl.uniform1f(surface.uniform("u_progress"), progress);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          progress,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

function makeFilterShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneFilterFrame<Props>) => void,
): SceneFilter<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const sceneTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ scene, width, height, frame, time, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(scene, sceneTexture, 0, "u_scene");

        surface.gl.uniform1f(surface.uniform("u_frame"), frame);
        surface.gl.uniform1f(surface.uniform("u_time"), time);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          frame,
          time,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

const transferred = new WeakMap<HTMLCanvasElement, OffscreenCanvas>();

function takeOffscreen(canvas: HTMLCanvasElement): OffscreenCanvas {
  const existing = transferred.get(canvas);
  if (existing) {
    return existing;
  }
  const created = canvas.transferControlToOffscreen();
  transferred.set(canvas, created);
  return created;
}

function makeCanvasComponent<Props extends Record<string, unknown>>(
  shader: SceneShader<Props>,
): React.FC<TransitionPresentationComponentProps<Props>> {
  return function CanvasScenePresentation({
    children,
    presentationProgress,
    presentationDirection,
    passedProps,
    onElementImage,
    onUnmount,
    bothEnteringAndExiting,
  }) {
    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneShaderInstance<Props> | null>(null);
    const passedPropsRef = React.useRef(passedProps);
    passedPropsRef.current = passedProps;
    const onElementImageRef = React.useRef(onElementImage);
    onElementImageRef.current = onElementImage;
    const onUnmountRef = React.useRef(onUnmount);
    onUnmountRef.current = onUnmount;

    const { delayRender, continueRender } = useDelayRender();
    const passThrough =
      bothEnteringAndExiting && presentationDirection === "exiting";

    const drawRef = React.useRef<
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => void
    >(() => undefined);
    drawRef.current = (prevImage, nextImage, progress) => {
      const instance = instanceRef.current;
      if (!instance) {
        return;
      }
      const handle = delayRender("canvas-presentation: paint");
      const to = prevImage;
      const from = nextImage;
      const width = from?.width ?? to?.width ?? 0;
      const height = from?.height ?? to?.height ?? 0;
      if (width === 0 || height === 0) {
        instance.clear();
        continueRender(handle);
        return;
      }
      instance.draw({
        from,
        to,
        width,
        height,
        progress: !to ? 0 : !from ? 1 : progress,
        passedProps: passedPropsRef.current,
      });
      continueRender(handle);
    };

    const draw = React.useCallback(
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => drawRef.current(prevImage, nextImage, progress),
      [],
    );

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [passThrough, shader]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        if (!scene || !capture || !context) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        onElementImageRef.current(capture, draw);
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, [passThrough, draw]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, [passThrough]);

    // biome-ignore lint/correctness/useExhaustiveDependencies: presentationProgress is the intentional trigger — a new progress value is what schedules the next paint
    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      layoutRef.current?.requestPaint?.();
    }, [passThrough, presentationProgress]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      return () => onUnmountRef.current();
    }, [passThrough]);

    if (passThrough) {
      return <>{children}</>;
    }

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasFilterProps = {
  children: React.ReactNode;
};

function makeFilterComponent<Props extends Record<string, unknown>>(
  shader: SceneFilter<Props>,
): React.FC<Props & CanvasFilterProps> {
  return function CanvasSceneFilter(props) {
    const frame = useCurrentFrame();
    const { fps } = useVideoConfig();
    const { delayRender, continueRender } = useDelayRender();

    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneFilterInstance<Props> | null>(null);

    const passedPropsRef = React.useRef(props);
    passedPropsRef.current = props;
    const frameRef = React.useRef(frame);
    frameRef.current = frame;
    const timeRef = React.useRef(frame / fps);
    timeRef.current = frame / fps;

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [shader]);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        const instance = instanceRef.current;
        if (!scene || !capture || !context || !instance) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        if (capture.width === 0 || capture.height === 0) {
          instance.clear();
          return;
        }
        instance.draw({
          scene: capture,
          width: capture.width,
          height: capture.height,
          frame: frameRef.current,
          time: timeRef.current,
          passedProps: passedPropsRef.current,
        });
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const handle = delayRender("canvas-presentation: filter paint");
      const settle = () => continueRender(handle);
      layout.addEventListener("paint", settle, { once: true });
      layout.requestPaint?.();
      return () => {
        layout.removeEventListener("paint", settle);
        continueRender(handle);
      };
    });

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {props.children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasPresentationOptions<Props extends Record<string, unknown>> = {
  shader: SceneShader<Props>;
  fallback: React.FC<TransitionPresentationComponentProps<Props>>;
};

function makeCanvasPresentation<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasPresentationOptions<Props>): (
  props: Props,
) => TransitionPresentation<Props> {
  const Canvas = makeCanvasComponent(shader);

  const Presentation: React.FC<TransitionPresentationComponentProps<Props>> = (
    props,
  ) =>
    isCanvasTransitionSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );

  return (props) => ({ component: Presentation, props });
}

type CanvasFilterOptions<Props extends Record<string, unknown>> = {
  shader: SceneFilter<Props>;
  fallback: React.FC<Props & CanvasFilterProps>;
};

function makeCanvasFilter<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasFilterOptions<Props>): React.FC<Props & CanvasFilterProps> {
  const Canvas = makeFilterComponent(shader);

  return function CanvasFilter(props) {
    return isCanvasFilterSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );
  };
}

type UnderwaterRippleProps = {
  amplitude?: number;
  scale?: number;
  speed?: number;
  dispersion?: number;
};

const DEFAULTS = {
  amplitude: 7,
  scale: 1,
  speed: 2,
  dispersion: 1,
};

type NormalizedProps = {
  amplitude: number;
  scale: number;
  phase: number;
  dispersion: number;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_phase;
uniform float u_amplitude;
uniform float u_scale;
uniform float u_dispersion;

in vec2 v_uv;
out vec4 outColor;

vec2 fieldGradient(vec2 p, float phase) {
  float scale = max(u_scale, 0.05);
  vec2 k1 = vec2(1.0, 0.35);
  vec2 k2 = vec2(-0.42, 1.0);
  vec2 k3 = vec2(0.78, -0.63);
  float f1 = 6.1 * scale;
  float f2 = 8.7 * scale;
  float f3 = 12.3 * scale;

  vec2 g = vec2(0.0);
  g += cos(dot(p, k1) * f1 + phase) * f1 * k1;
  g += cos(dot(p, k2) * f2 - phase * 2.0) * f2 * k2;
  g += cos(dot(p, k3) * f3 + phase * 3.0) * f3 * k3;

  return g / (3.0 * f2);
}

void main() {
  vec2 p = vec2(v_uv.x * u_aspect, v_uv.y);
  vec2 grad = fieldGradient(p, u_phase);

  vec2 offset = grad * u_amplitude;
  float strength = length(grad);
  vec2 direction = strength > 0.0001 ? grad / strength : vec2(0.0);
  float spread = u_dispersion * u_amplitude * 0.3 * min(strength, 2.0);

  vec2 base = v_uv + vec2(offset.x / u_aspect, offset.y);
  vec2 lead = vec2(direction.x / u_aspect, direction.y) * spread;

  vec4 center = texture(u_scene, base);
  float r = texture(u_scene, base + lead).r;
  float b = texture(u_scene, base - lead).b;

  outColor = vec4(r, center.g, b, center.a);
}`;

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { amplitude, scale, phase, dispersion } = passedProps;
    gl.uniform1f(uniform("u_amplitude"), amplitude);
    gl.uniform1f(uniform("u_scale"), scale);
    gl.uniform1f(uniform("u_phase"), phase);
    gl.uniform1f(uniform("u_dispersion"), dispersion);
  },
);

const UnderwaterRippleFallback: React.FC<
  NormalizedProps & CanvasFilterProps
> = ({ children }) => <AbsoluteFill>{children}</AbsoluteFill>;

const UnderwaterRippleCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: UnderwaterRippleFallback,
});

const UnderwaterRippleBase: React.FC<
  UnderwaterRippleProps & CanvasFilterProps
> = ({
  amplitude = DEFAULTS.amplitude,
  scale = DEFAULTS.scale,
  speed = DEFAULTS.speed,
  dispersion = DEFAULTS.dispersion,
  children,
}) => {
  const frame = useCurrentFrame();
  const { height, durationInFrames } = useVideoConfig();
  const cycle = Math.max(durationInFrames, 1);

  return (
    <UnderwaterRippleCanvas
      amplitude={amplitude / height}
      scale={scale}
      phase={(frame / cycle) * speed * Math.PI * 2}
      dispersion={dispersion}
    >
      {children}
    </UnderwaterRippleCanvas>
  );
};

