        >
          <defs>
            {centers.map((c, i) => (
              <clipPath id={`${uid}c${i}`} key={list[i]}>
                <circle cx={c.x} cy={c.y} r={R} />
              </clipPath>
            ))}
            <radialGradient
              id={`${uid}g`}
              gradientUnits="userSpaceOnUse"
              cx={cx + glowX}
              cy={cy + R * 0.95}
              r={R * 1.75}
            >
              <stop offset={0} stopColor={LIMB[0]} />
              <stop offset={0.2} stopColor={LIMB[1]} />
              <stop offset={0.5} stopColor={accent} />
              <stop offset={0.74} stopColor={LIMB[2]} />
              <stop offset={1} stopColor={LIMB[3]} />
            </radialGradient>
            <radialGradient
              id={`${uid}h`}
              gradientUnits="userSpaceOnUse"
              cx={cx - glowX * 1.4}
              cy={cy - R * 0.55}
              r={R * 0.75}
            >
              <stop offset={0} stopColor={LIMB[1]} stopOpacity={0.55} />
              <stop offset={1} stopColor={LIMB[1]} stopOpacity={0} />
            </radialGradient>
          </defs>
          {centers.map((c, i) => (
            <circle
              key={list[i]}
              cx={c.x}
              cy={c.y}
              r={R}
              fill="none"
              stroke={p.ring}
              strokeWidth={ring}
              strokeDasharray={`${circ * draw} ${circ}`}
              transform={`rotate(${i === 0 ? 180 : three && i === 2 ? -90 : 0} ${c.x} ${c.y})`}
            />
          ))}
          {fill > 0 ? (
            <g clipPath={`url(#${uid}c0)`}>
              <g clipPath={`url(#${uid}c1)`}>
                <g clipPath={three ? `url(#${uid}c2)` : undefined}>
                  <rect
                    x={cx - R * 2}
                    y={cy + R - 2 * R * fill}
                    width={R * 4}
                    height={2 * R * fill}
                    fill={`url(#${uid}g)`}
                  />
                  <rect
                    x={cx - R * 2}
                    y={cy + R - 2 * R * fill}
                    width={R * 4}
                    height={2 * R * fill}
                    fill={`url(#${uid}h)`}
                  />
                </g>
              </g>
            </g>
          ) : null}
        </svg>

        {labels.map((l) => (
          <div
            key={l.name}
            style={{
              position: "absolute",
              left: l.x,
              top: l.y,
              transform: `translate(-50%, -50%) translateY(${(1 - l.a) * 8 * u}px)`,
              fontFamily: serif,
              fontWeight: 400,
              fontSize: labelSize,
              letterSpacing: "-0.01em",
              lineHeight: 1,
              color: p.fg,
              opacity: l.a,
              whiteSpace: "nowrap",
            }}
          >
            {l.name}
          </div>
        ))}

        <div
          style={{
            position: "absolute",
            left: cx,
            top: brandY,
            transform: `translate(-50%, -50%) translateY(${(1 - brand) * 18 * u}px) scale(${1.06 - 0.06 * brand})`,
            whiteSpace: "nowrap",
            opacity: brand,
            filter: brand < 0.99 ? `blur(${(1 - brand) * 8 * u}px)` : undefined,
          }}
        >
          {isLogo ? (
            <RemocnLogo fontSize={brandSize} color="#FFFFFF" />
          ) : (
            <div
              style={{
                fontFamily: manrope.fontFamily,
                fontWeight: 500,
                fontSize: brandSize,
                lineHeight: 1,
                letterSpacing: "-0.035em",
                color: "#FFFFFF",
              }}
            >
              {center}
            </div>
          )}
        </div>

        {caption ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: cy + (three ? finalSep / Math.sqrt(3) / 2 : 0) + R + 34 * u,
              textAlign: "center",
              fontFamily: manrope.fontFamily,
              fontWeight: 400,
              fontSize: 24 * u,
              letterSpacing: "-0.01em",
              color: p.muted,
              opacity: capIn,
              transform: `translateY(${(1 - capIn) * 10 * u}px)`,
              textWrap: "balance",
            }}
          >
            {caption}
          </div>
        ) : null}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.55,
        }}
      />
      <Grain opacity={p.grain} />
    </AbsoluteFill>
  );
}

