});

import { AbsoluteFill, Interactive, Sequence, isHtmlInCanvasSupported, random, useCurrentFrame, useDelayRender, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";
import { type TransitionPresentation, type TransitionPresentationComponentProps } from "@remotion/transitions";

const QUAD = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

const VERTEX_SHADER = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;
void main() {
  v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5);
  gl_Position = vec4(a_pos, 0.0, 1.0);
}`;

const LAYER: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
};

const OUTPUT_LAYER: React.CSSProperties = { ...LAYER, pointerEvents: "none" };

const isCanvasTransitionSupported = (): boolean =>
  isHtmlInCanvasSupported();

const isCanvasFilterSupported = (): boolean => isHtmlInCanvasSupported();

type SceneShaderFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderDrawParams<Props> = {
  from: OffscreenCanvas | null;
  to: OffscreenCanvas | null;
  width: number;
  height: number;
  progress: number;
  passedProps: Props;
};

type SceneShaderInstance<Props> = {
  draw: (params: SceneShaderDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneShader<Props> = (
  canvas: OffscreenCanvas,
) => SceneShaderInstance<Props>;

type SceneFilterFrame<Props> = {
  gl: WebGL2RenderingContext;
  uniform: (name: string) => WebGLUniformLocation | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterDrawParams<Props> = {
  scene: OffscreenCanvas | null;
  width: number;
  height: number;
  frame: number;
  time: number;
  passedProps: Props;
};

type SceneFilterInstance<Props> = {
  draw: (params: SceneFilterDrawParams<Props>) => void;
  clear: () => void;
  cleanup: () => void;
};

type SceneFilter<Props> = (
  canvas: OffscreenCanvas,
) => SceneFilterInstance<Props>;

function compileShader(
  gl: WebGL2RenderingContext,
  source: string,
  type: GLenum,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) {
    throw new Error("canvas-presentation: failed to create shader");
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(`canvas-presentation: failed to compile shader: ${log}`);
  }
  return shader;
}

function createProgram(
  gl: WebGL2RenderingContext,
  fragment: string,
): WebGLProgram {
  const program = gl.createProgram();
  if (!program) {
    throw new Error("canvas-presentation: failed to create program");
  }
  const vs = compileShader(gl, VERTEX_SHADER, gl.VERTEX_SHADER);
  const fs = compileShader(gl, fragment, gl.FRAGMENT_SHADER);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(`canvas-presentation: failed to link program: ${log}`);
  }
  return program;
}

function createSceneTexture(gl: WebGL2RenderingContext): WebGLTexture {
  const texture = gl.createTexture();
  if (!texture) {
    throw new Error("canvas-presentation: failed to create texture");
  }
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    1,
    1,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    new Uint8Array([0, 0, 0, 0]),
  );
  return texture;
}

function createQuadSurface(canvas: OffscreenCanvas, fragment: string) {
  const gl = canvas.getContext("webgl2", { premultipliedAlpha: true });
  if (!gl) {
    throw new Error("canvas-presentation: WebGL2 is unavailable");
  }

  const program = createProgram(gl, fragment);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, QUAD, gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const locations = new Map<string, WebGLUniformLocation | null>();
  const uniform = (name: string) => {
    const cached = locations.get(name);
    if (cached !== undefined) {
      return cached;
    }
    const location = gl.getUniformLocation(program, name);
    locations.set(name, location);
    return location;
  };

  const clear = () => {
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  };

  const textures: WebGLTexture[] = [];
  const createTexture = () => {
    const texture = createSceneTexture(gl);
    textures.push(texture);
    return texture;
  };

  const begin = (width: number, height: number) => {
    gl.viewport(0, 0, width, height);
    clear();
    gl.useProgram(program);
    gl.bindVertexArray(vao);
  };

  const bindScene = (
    image: OffscreenCanvas | null,
    texture: WebGLTexture,
    unit: number,
    name: string,
  ) => {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    if (image) {
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        image,
      );
    }
    gl.uniform1i(uniform(name), unit);
  };

  const draw = () => gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  const cleanup = () => {
    gl.deleteProgram(program);
    for (const texture of textures) {
      gl.deleteTexture(texture);
    }
    gl.deleteBuffer(buffer);
    gl.deleteVertexArray(vao);
  };

  return {
    gl,
    uniform,
    clear,
    createTexture,
    begin,
    bindScene,
    draw,
    cleanup,
  };
}

function makeSceneShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneShaderFrame<Props>) => void,
): SceneShader<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const fromTexture = surface.createTexture();
    const toTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ from, to, width, height, progress, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(from, fromTexture, 0, "u_from");
        surface.bindScene(to, toTexture, 1, "u_to");

        surface.gl.uniform1f(surface.uniform("u_progress"), progress);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          progress,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

function makeFilterShader<Props extends Record<string, unknown>>(
  fragment: string,
  setUniforms?: (frame: SceneFilterFrame<Props>) => void,
): SceneFilter<Props> {
  return (canvas) => {
    const surface = createQuadSurface(canvas, fragment);
    const sceneTexture = surface.createTexture();

    return {
      clear: surface.clear,
      cleanup: surface.cleanup,
      draw: ({ scene, width, height, frame, time, passedProps }) => {
        surface.begin(width, height);
        surface.bindScene(scene, sceneTexture, 0, "u_scene");

        surface.gl.uniform1f(surface.uniform("u_frame"), frame);
        surface.gl.uniform1f(surface.uniform("u_time"), time);
        surface.gl.uniform1f(surface.uniform("u_aspect"), width / height);
        setUniforms?.({
          gl: surface.gl,
          uniform: surface.uniform,
          width,
          height,
          frame,
          time,
          passedProps,
        });

        surface.draw();
      },
    };
  };
}

const transferred = new WeakMap<HTMLCanvasElement, OffscreenCanvas>();

function takeOffscreen(canvas: HTMLCanvasElement): OffscreenCanvas {
  const existing = transferred.get(canvas);
  if (existing) {
    return existing;
  }
  const created = canvas.transferControlToOffscreen();
  transferred.set(canvas, created);
  return created;
}

function makeCanvasComponent<Props extends Record<string, unknown>>(
  shader: SceneShader<Props>,
): React.FC<TransitionPresentationComponentProps<Props>> {
  return function CanvasScenePresentation({
    children,
    presentationProgress,
    presentationDirection,
    passedProps,
    onElementImage,
    onUnmount,
    bothEnteringAndExiting,
  }) {
    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneShaderInstance<Props> | null>(null);
    const passedPropsRef = React.useRef(passedProps);
    passedPropsRef.current = passedProps;
    const onElementImageRef = React.useRef(onElementImage);
    onElementImageRef.current = onElementImage;
    const onUnmountRef = React.useRef(onUnmount);
    onUnmountRef.current = onUnmount;

    const { delayRender, continueRender } = useDelayRender();
    const passThrough =
      bothEnteringAndExiting && presentationDirection === "exiting";

    const drawRef = React.useRef<
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => void
    >(() => undefined);
    drawRef.current = (prevImage, nextImage, progress) => {
      const instance = instanceRef.current;
      if (!instance) {
        return;
      }
      const handle = delayRender("canvas-presentation: paint");
      const to = prevImage;
      const from = nextImage;
      const width = from?.width ?? to?.width ?? 0;
      const height = from?.height ?? to?.height ?? 0;
      if (width === 0 || height === 0) {
        instance.clear();
        continueRender(handle);
        return;
      }
      instance.draw({
        from,
        to,
        width,
        height,
        progress: !to ? 0 : !from ? 1 : progress,
        passedProps: passedPropsRef.current,
      });
      continueRender(handle);
    };

    const draw = React.useCallback(
      (
        prevImage: OffscreenCanvas | null,
        nextImage: OffscreenCanvas | null,
        progress: number,
      ) => drawRef.current(prevImage, nextImage, progress),
      [],
    );

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [passThrough, shader]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        if (!scene || !capture || !context) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        onElementImageRef.current(capture, draw);
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, [passThrough, draw]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, [passThrough]);

    // biome-ignore lint/correctness/useExhaustiveDependencies: presentationProgress is the intentional trigger — a new progress value is what schedules the next paint
    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      layoutRef.current?.requestPaint?.();
    }, [passThrough, presentationProgress]);

    React.useLayoutEffect(() => {
      if (passThrough) {
        return;
      }
      return () => onUnmountRef.current();
    }, [passThrough]);

    if (passThrough) {
      return <>{children}</>;
    }

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasFilterProps = {
  children: React.ReactNode;
};

function makeFilterComponent<Props extends Record<string, unknown>>(
  shader: SceneFilter<Props>,
): React.FC<Props & CanvasFilterProps> {
  return function CanvasSceneFilter(props) {
    const frame = useCurrentFrame();
    const { fps } = useVideoConfig();
    const { delayRender, continueRender } = useDelayRender();

    const layoutRef = React.useRef<HTMLCanvasElement | null>(null);
    const outputRef = React.useRef<HTMLCanvasElement | null>(null);
    const captureRef = React.useRef<OffscreenCanvas | null>(null);
    const captureContextRef =
      React.useRef<OffscreenCanvasRenderingContext2D | null>(null);
    const outputSurfaceRef = React.useRef<OffscreenCanvas | null>(null);
    const instanceRef = React.useRef<SceneFilterInstance<Props> | null>(null);

    const passedPropsRef = React.useRef(props);
    passedPropsRef.current = props;
    const frameRef = React.useRef(frame);
    frameRef.current = frame;
    const timeRef = React.useRef(frame / fps);
    timeRef.current = frame / fps;

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      const output = outputRef.current;
      if (!layout || !output) {
        return;
      }
      const capture = takeOffscreen(layout);
      const context = capture.getContext("2d");
      if (!context) {
        throw new Error("canvas-presentation: failed to acquire a 2D context");
      }
      const surface = takeOffscreen(output);
      captureRef.current = capture;
      captureContextRef.current = context;
      outputSurfaceRef.current = surface;
      instanceRef.current = shader(surface);

      return () => {
        instanceRef.current?.cleanup();
        instanceRef.current = null;
        captureRef.current = null;
        captureContextRef.current = null;
        outputSurfaceRef.current = null;
      };
    }, [shader]);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      layout.layoutSubtree = true;
      const handlePaint = () => {
        const scene = layout.firstElementChild;
        const capture = captureRef.current;
        const context = captureContextRef.current;
        const instance = instanceRef.current;
        if (!scene || !capture || !context || !instance) {
          return;
        }
        const elementImage = layout.captureElementImage(scene);
        try {
          context.reset();
          context.drawElementImage(elementImage, 0, 0);
        } finally {
          elementImage.close();
        }
        if (capture.width === 0 || capture.height === 0) {
          instance.clear();
          return;
        }
        instance.draw({
          scene: capture,
          width: capture.width,
          height: capture.height,
          frame: frameRef.current,
          time: timeRef.current,
          passedProps: passedPropsRef.current,
        });
      };
      layout.addEventListener("paint", handlePaint);
      return () => layout.removeEventListener("paint", handlePaint);
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const observer = new ResizeObserver(([entry]) => {
        const capture = captureRef.current;
        const surface = outputSurfaceRef.current;
        if (!capture || !surface) {
          return;
        }
        const width = entry.devicePixelContentBoxSize[0].inlineSize;
        const height = entry.devicePixelContentBoxSize[0].blockSize;
        capture.width = width;
        capture.height = height;
        surface.width = width;
        surface.height = height;
        layout.requestPaint?.();
      });
      observer.observe(layout, { box: "device-pixel-content-box" });
      return () => observer.disconnect();
    }, []);

    React.useLayoutEffect(() => {
      const layout = layoutRef.current;
      if (!layout) {
        return;
      }
      const handle = delayRender("canvas-presentation: filter paint");
      const settle = () => continueRender(handle);
      layout.addEventListener("paint", settle, { once: true });
      layout.requestPaint?.();
      return () => {
        layout.removeEventListener("paint", settle);
        continueRender(handle);
      };
    });

    return (
      <AbsoluteFill>
        <canvas ref={layoutRef} style={LAYER}>
          {props.children}
        </canvas>
        <canvas ref={outputRef} style={OUTPUT_LAYER} />
      </AbsoluteFill>
    );
  };
}

type CanvasPresentationOptions<Props extends Record<string, unknown>> = {
  shader: SceneShader<Props>;
  fallback: React.FC<TransitionPresentationComponentProps<Props>>;
};

function makeCanvasPresentation<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasPresentationOptions<Props>): (
  props: Props,
) => TransitionPresentation<Props> {
  const Canvas = makeCanvasComponent(shader);

  const Presentation: React.FC<TransitionPresentationComponentProps<Props>> = (
    props,
  ) =>
    isCanvasTransitionSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );

  return (props) => ({ component: Presentation, props });
}

type CanvasFilterOptions<Props extends Record<string, unknown>> = {
  shader: SceneFilter<Props>;
  fallback: React.FC<Props & CanvasFilterProps>;
};

function makeCanvasFilter<Props extends Record<string, unknown>>({
  shader,
  fallback: Fallback,
}: CanvasFilterOptions<Props>): React.FC<Props & CanvasFilterProps> {
  const Canvas = makeFilterComponent(shader);

  return function CanvasFilter(props) {
    return isCanvasFilterSupported() ? (
      <Canvas {...props} />
    ) : (
      <Fallback {...props} />
    );
  };
}

type VhsFilterProps = {
  bleed?: number;
  wobble?: number;
  noise?: number;
  intensity?: number;
};

const DEFAULTS = {
  bleed: 1,
  wobble: 1,
  noise: 1,
  intensity: 1,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_time;
uniform float u_bleed;
uniform float u_wobble;
uniform float u_noise;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float LINES = 486.0;
const int TAPS = 6;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float valueNoise(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash(vec2(i, 7.0));
  float b = hash(vec2(i + 1.0, 7.0));
  return mix(a, b, f * f * (3.0 - 2.0 * f));
}

vec3 rgb2yiq(vec3 c) {
  return vec3(
    dot(c, vec3(0.299, 0.587, 0.114)),
    dot(c, vec3(0.5959, -0.2746, -0.3213)),
    dot(c, vec3(0.2115, -0.5227, 0.3112))
  );
}

vec3 yiq2rgb(vec3 c) {
  return vec3(
    c.x + 0.956 * c.y + 0.619 * c.z,
    c.x - 0.272 * c.y - 0.647 * c.z,
    c.x - 1.106 * c.y + 1.703 * c.z
  );
}

void main() {
  float line = floor(v_uv.y * LINES);
  float clock = mod(u_frame, 64.0);

  float drift =
    sin(v_uv.y * 37.0 + u_time * 2.3) * 0.55 +
    sin(v_uv.y * 96.0 - u_time * 1.1) * 0.25;
  float jitter = valueNoise(line * 0.61 + u_time * 24.0) - 0.5;
  float wobble = (drift * 0.35 + jitter * 0.9) * 0.007 * u_wobble * u_intensity;

  float band = smoothstep(0.955, 0.994, v_uv.y);
  float tear = valueNoise(line * 2.7 + u_time * 43.0) - 0.5;
  float headSwitch = band * tear * 0.085 * u_intensity;

  vec2 uv = vec2(v_uv.x + wobble + headSwitch, v_uv.y);
  vec4 base = texture(u_scene, uv);
  float luma = rgb2yiq(base.rgb).x;

  float smear = u_bleed * 0.02 * u_intensity;
  vec2 chroma = vec2(0.0);
  float total = 0.0;
  for (int i = 0; i < TAPS; i++) {
    float t = float(i) / float(TAPS - 1);
    float weight = 1.0 - t * 0.72;
    vec3 tap = texture(u_scene, vec2(uv.x - smear * t, uv.y)).rgb;
    chroma += rgb2yiq(tap).yz * weight;
    total += weight;
  }

  vec3 color = yiq2rgb(vec3(luma, chroma / total));

  float scan = 0.94 + 0.06 * cos(v_uv.y * LINES * PI);
  color *= mix(1.0, scan, u_intensity);

  float grain =
    hash(vec2(v_uv.x * 640.0 + clock * 13.0, line + clock * 5.0)) - 0.5;
  color += grain * 0.07 * u_noise * u_intensity;

  color = mix(color, vec3(luma), band * 0.55 * u_intensity);
  color += band * (hash(vec2(line, clock * 3.0)) - 0.5) * 0.26 * u_intensity;

  outColor = vec4(clamp(color, 0.0, 1.0), base.a);
}`;

const shader = makeFilterShader<VhsFilterProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      bleed = DEFAULTS.bleed,
      wobble = DEFAULTS.wobble,
      noise = DEFAULTS.noise,
      intensity = DEFAULTS.intensity,
    } = passedProps;
    gl.uniform1f(uniform("u_bleed"), bleed);
    gl.uniform1f(uniform("u_wobble"), wobble);
    gl.uniform1f(uniform("u_noise"), noise);
    gl.uniform1f(uniform("u_intensity"), intensity);
  },
);

const VhsFilterFallback: React.FC<VhsFilterProps & CanvasFilterProps> = ({
  children,
  bleed = DEFAULTS.bleed,
  wobble = DEFAULTS.wobble,
  noise = DEFAULTS.noise,
  intensity = DEFAULTS.intensity,
}) => {
  const frame = useCurrentFrame();
  const shift =
    (random(`vhs-wobble-${frame}`) - 0.5) * 3.4 * wobble * intensity;
  const flicker =
    1 + (random(`vhs-flicker-${frame}`) - 0.5) * 0.07 * noise * intensity;
  const smear = 3 + bleed * 5;

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          translate: `${shift}px`,
          filter: `saturate(${1 + bleed * 0.3}) contrast(1.04) brightness(${flicker}) blur(${0.3 * intensity}px)`,
        }}
      >
        {children}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          translate: `${shift - smear}px`,
          filter: "saturate(2.2) blur(1.4px)",
          mixBlendMode: "screen",
          opacity: 0.24 * bleed * intensity,
        }}
      >
        {children}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background:
            "repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.22) 0px, rgba(0, 0, 0, 0.22) 1px, transparent 1px, transparent 3px)",
          opacity: intensity,
        }}
      />
      <div
        style={{
          position: "absolute",
          insetInline: 0,
          bottom: 0,
          height: "3.6%",
          translate: `${shift * 3}px`,
          background: `rgba(228, 228, 228, ${0.13 * intensity})`,
          mixBlendMode: "screen",
        }}
      />
    </AbsoluteFill>
  );
};

const VhsFilterBase = makeCanvasFilter<VhsFilterProps>({
  shader,
  fallback: VhsFilterFallback,
});

const elementSchema = {
  ...Interactive.baseSchema,
  bleed: {
    type: "number",
    min: 0,
    max: 3,
    step: 0.1,
    default: 1,
    description: "Chroma bleed",
    hiddenFromList: false,
  },
  wobble: {
    type: "number",
    min: 0,
    max: 3,
    step: 0.1,
    default: 1,
    description: "Tape wobble",
    hiddenFromList: false,
  },
  noise: {
    type: "number",
    min: 0,
    max: 3,
    step: 0.1,
    default: 1,
    description: "Noise",
    hiddenFromList: false,
  },
  intensity: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 1,
    description: "Intensity",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["bleed","wobble","noise","intensity","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  bleed: 1,
  wobble: 1,
  noise: 1,
  intensity: 1,
  speed: 1,
};

type VhsFilterElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof VhsFilterBase>;

const VhsFilterInner = forwardRef<
  HTMLDivElement,
  VhsFilterElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<VhsFilter>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <VhsFilterBase
          {...(componentProps as unknown as ComponentProps<typeof VhsFilterBase>)}
        />
      </div>
    </Sequence>
  );
});

export const VhsFilter = Interactive.withSchema({
  Component: VhsFilterInner,
  componentName: "<VhsFilter>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont as loadFigtree } from "@remotion/google-fonts/Figtree";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const figtree = loadFigtree("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"] });

interface WakeWipeProps {
  lines?: string[];
  highlight?: string;
  eyebrow?: string;
  hold?: number;
  accent?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    muted: "#8E8D94",
    edge: ["#fff4ec", "#ffb36b", "#e2457a"],
    ground: 0.5,
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    muted: "#6E6C67",
    edge: ["#ff8a3d", "#ff3d9a", "#7a5cff"],
    ground: 0.46,
    grain: 0.035,
  },
} as const;

const TRACK = -0.035;
const START = 4;
const WAKE_LEN = 28;
const REVEAL_LEN = 18;
const REVEAL_TAIL = 0.32;
const TAIL = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_WAKE = Easing.bezier(0.5, 0, 0.2, 1);
const EASE_REVEAL = Easing.bezier(0.3, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const mix = (c: string, a: number) =>
  `color-mix(in oklab, ${c} ${(Math.max(0, Math.min(1, a)) * 100).toFixed(1)}%, transparent)`;

function measure(lines: string[]) {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) return lines.map((l) => l.length * 0.52);
  ctx.font = `500 1000px "${figtree.fontFamily}"`;
  return lines.map(
    (l) => ctx.measureText(l).width / 1000 + TRACK * Array.from(l).length,
  );
}

function useWidths(lines: string[]) {
  const [widths, setWidths] = useState<number[] | null>(null);
  const [handle] = useState(() => delayRender("wake-wipe: measuring"));
  const released = useRef(false);
  const key = lines.join("\n");
  useEffect(() => {
    let live = true;
    Promise.all([
      figtree.waitUntilDone(),
      mono.waitUntilDone(),
      document.fonts.load(`500 100px "${figtree.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setWidths(measure(key.split("\n")));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return widths;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `ww${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function WakeWipeBase({
  lines = [
    "Animations you own.",
    "Transitions that land.",
    "Ship the launch video today.",
  ],
  highlight = "today.",
  eyebrow = "Inside remocn",
  hold = 54,
  accent = "#3B5BFD",
  speed = 1,
  theme = "dark",
}: WakeWipeProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const items = lines.length ? lines : [""];
  const widths = useWidths(items);

  if (!widths) {
    return <div style={{ position: "absolute", inset: 0, background: c.bg }} />;
  }

  const portrait = H > W;
  const padX = W * (portrait ? 0.08 : 0.085);
  const maxW = W - padX * 2;
  const widest = Math.max(...widths, 0.1);
  const maxRows = portrait ? 3 : 2;
  const F = Math.min(
    portrait ? W * 0.15 : H * 0.17,
    (maxW * maxRows * 0.9) / widest,
  );

  const rowsOf = (w: number) => Math.max(1, Math.ceil((w * F) / maxW - 0.02));
  const rows = Math.max(...widths.map(rowsOf), 1);
  const blockH = rows * F * 1.04;
  const ebSize = Math.max(Math.min(H, W) * 0.026, 12);
  const ebGap = F * 0.42;
  const stackH = blockH + (eyebrow ? ebSize + ebGap : 0);
  const centerY = portrait ? H * 0.56 : H * 0.5;
  const blockTop = centerY - stackH / 2 + (eyebrow ? ebSize + ebGap : 0);

  const cx = -W * 0.6;
  const cy = H * 0.64;
  const T = W * TAIL;
  const T2 = W * REVEAL_TAIL;
  const r0 = Math.hypot(0 - cx, 0) - 2;
  const r1 = Math.hypot(W - cx, Math.max(cy, H - cy)) + T + 2;

  const boxTop = blockTop - F * 0.08;
  const boxRight = (i: number) =>
    padX + Math.min(widths[i] * F, maxW) + F * 0.1;
  const boxBottom = (i: number) =>
    blockTop + rowsOf(widths[i]) * F * 1.04 + F * 0.12;
  const far = (i: number) =>
    Math.max(
      Math.hypot(boxRight(i) - cx, boxTop - cy),
      Math.hypot(boxRight(i) - cx, boxBottom(i) - cy),
    );
  const near = (i: number) =>
    Math.hypot(
      padX - F * 0.1 - cx,
      Math.min(Math.max(cy, boxTop), boxBottom(i)) - cy,
    );

  const last = items.length - 1;
  const startOf = (k: number) => START + k * hold;
  const rRest = Math.max(
    W * 1.06 - cx,
    last > 0 ? far(last - 1) + W * 0.03 : 0,
  );
  const frontAt = (k: number, time: number) => {
    const end = k === last ? rRest : r1;
    const p = interpolate(time, [startOf(k), startOf(k) + WAKE_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_WAKE,
    });
    const breathe =
      k === last ? Math.sin((time - startOf(k)) / 22) * W * 0.006 * p : 0;
    return r0 + (end - r0) * p + breathe;
  };
  const erasedAt = (k: number) => {
    if (k === 0) return startOf(0);
    const target = far(k - 1);
    for (let s = 0; s <= WAKE_LEN; s += 0.25)
      if (frontAt(k, startOf(k) + s) >= target) return startOf(k) + s;
    return startOf(k) + WAKE_LEN;
  };
  const revealAt = (k: number, time: number) => {
    const t0 = erasedAt(k);
    if (time < t0) return 0;
    const p = interpolate(time, [t0, t0 + REVEAL_LEN], [0, 1], {
      ...CLAMP,
      easing: EASE_REVEAL,
    });
    const r = near(k) + (far(k) + T2 - near(k)) * p;
    return Math.min(r, frontAt(k, time) - 1);
  };

  let k = 0;
  for (let i = 0; i < items.length; i++) if (t >= startOf(i)) k = i;
  const R = frontAt(k, t);
  const R2 = revealAt(k, t);
  const at = `circle farthest-corner at ${cx.toFixed(1)}px ${cy.toFixed(1)}px`;

  const deep = accent;
  const tail = (a: number) =>
    `radial-gradient(${at}, transparent ${(R - T).toFixed(1)}px, ${mix(deep, 0.55 * a)} ${(R - T * 0.5).toFixed(1)}px, ${mix(c.edge[2], 0.82 * a)} ${(R - T * 0.2).toFixed(1)}px, ${mix(c.edge[1], 0.96 * a)} ${(R - T * 0.055).toFixed(1)}px, ${mix(c.edge[0], a)} ${(R - 2.5).toFixed(1)}px, ${mix(c.edge[0], a)} ${R.toFixed(1)}px, transparent ${(R + 1).toFixed(1)}px)`;
  const revealTint = (a: number) =>
    `radial-gradient(${at}, transparent ${(R2 - T2).toFixed(1)}px, ${mix(deep, 0.6 * a)} ${(R2 - T2 * 0.55).toFixed(1)}px, ${mix(c.edge[2], 0.9 * a)} ${(R2 - T2 * 0.22).toFixed(1)}px, ${mix(c.edge[1], a)} ${(R2 - T2 * 0.06).toFixed(1)}px, ${mix(c.edge[0], a)} ${(R2 - 1).toFixed(1)}px, transparent ${(R2 + 0.5).toFixed(1)}px)`;
  const inside = `radial-gradient(${at}, #000 ${(R2 - 0.5).toFixed(1)}px, transparent ${(R2 + 0.5).toFixed(1)}px)`;
  const outside = `radial-gradient(${at}, transparent ${(R - 0.5).toFixed(1)}px, #000 ${(R + 0.5).toFixed(1)}px)`;

  const textBlock: React.CSSProperties = {
    position: "absolute",
    left: padX,
    width: maxW,
    top: blockTop,
    fontFamily: figtree.fontFamily,
    fontWeight: 500,
    fontSize: F,
    lineHeight: 1.04,
    letterSpacing: `${TRACK}em`,
    textWrap: "balance",
  };

  const revealEnd = erasedAt(last) + REVEAL_LEN;
  const settled = interpolate(t, [revealEnd - 4, revealEnd + 8], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const finalFill = `linear-gradient(100deg, ${c.edge[1]} 0%, ${c.edge[2]} 45%, ${deep} 100%)`;

  type Mode = "ink" | "lit" | "final";
  const renderLine = (i: number, mode: Mode) => {
    const text = items[i];
    const h = i === last && highlight ? text.lastIndexOf(highlight) : -1;
    if (h < 0) return mode === "final" ? null : text;
    const word = text.slice(h, h + highlight.length);
    const wordStyle: React.CSSProperties =
      mode === "final"
        ? {
            backgroundImage: finalFill,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            opacity: settled,
          }
        : mode === "ink"
          ? { opacity: 1 - settled }
          : {};
    return (
      <>
        {text.slice(0, h)}
        <span style={wordStyle}>{word}</span>
        {text.slice(h + highlight.length)}
      </>
    );
  };

  const layer = (
    key: string,
    i: number,
    mode: Mode,
    style: React.CSSProperties,
  ) => (
    <div key={key} style={{ position: "absolute", inset: 0, ...style }}>
      <div style={textBlock}>{renderLine(i, mode)}</div>
    </div>
  );

  const eyebrowP = interpolate(t, [START + 8, START + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: tail(c.ground),
        }}
      />
      {k > 0
        ? layer("old", k - 1, "ink", {
            color: c.ink,
            WebkitMaskImage: outside,
            maskImage: outside,
          })
        : null}
      {layer("new", k, "ink", {
        color: c.ink,
        WebkitMaskImage: inside,
        maskImage: inside,
      })}
      {k === last && highlight
        ? layer("final", k, "final", { color: "transparent" })
        : null}
      {layer("lit", k, "lit", {
        color: "transparent",
        backgroundImage: revealTint(k === last ? 1 - settled : 1),
        WebkitBackgroundClip: "text",
        backgroundClip: "text",
      })}
      {eyebrow ? (
        <div
          style={{
            position: "absolute",
            left: padX,
            top: blockTop - ebGap - ebSize,
            lineHeight: 1,
            fontFamily: mono.fontFamily,
            fontWeight: 400,
            fontSize: ebSize,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            color: c.muted,
            opacity: eyebrowP,
            transform: `translateY(${((1 - eyebrowP) * ebSize * 0.6).toFixed(2)}px)`,
          }}
        >
          {eyebrow}
        </div>
      ) : null}
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

