import { loadFont } from "@remotion/google-fonts/Bitter";
import { useEffect, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

const bitter = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface WeCallItProps {
  descriptions?: string[];
  lead?: string;
  name?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#0F1B3D", ink: "#F4EFE6", accent: "#FF8A3D" },
  light: { bg: "#F4EFE6", ink: "#0F1B3D", accent: "#C85A12" },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const BODY_TRACK = -0.02;
const NAME_TRACK = -0.04;
const LH = 1.18;
const NAME_LH = 1.02;
const NAME_BOX = 1.24;
const STEP = 40;
const HOLD = 26;
const MOVE = 18;
const KICK_DIM = 0.62;
const CAP = 0.7;
const DESC = 0.24;

function useFontsReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("we-call-it: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      bitter.waitUntilDone(),
      document.fonts.load(`400 100px "${bitter.fontFamily}"`),
      document.fonts.load(`500 100px "${bitter.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

function useMeasure() {
  const ctx = useRef<CanvasRenderingContext2D | null>(null);
  const cache = useRef(new Map<string, number>());
  return (text: string, weight: 400 | 500, track: number) => {
    const key = `${weight}\u0001${track}\u0001${text}`;
    const hit = cache.current.get(key);
    if (hit !== undefined) return hit;
    if (!ctx.current)
      ctx.current = document.createElement("canvas").getContext("2d");
    let w = text.length * 0.5;
    if (ctx.current) {
      ctx.current.font = `${weight} 100px "${bitter.fontFamily}"`;
      w = ctx.current.measureText(text).width / 100;
    }
    const em = w + track * Array.from(text).length;
    cache.current.set(key, em);
    return em;
  };
}

function greedy(
  words: string[],
  wOf: (s: string) => number,
  space: number,
  max: number,
) {
  const lines: string[][] = [];
  let line: string[] = [];
  let x = 0;
  for (const word of words) {
    const w = wOf(word);
    if (line.length > 0 && x + space + w > max) {
      lines.push(line);
      line = [word];
      x = w;
    } else {
      x += (line.length > 0 ? space : 0) + w;
      line.push(word);
    }
  }
  if (line.length > 0) lines.push(line);
  return lines;
}

function balanced(
  words: string[],
  wOf: (s: string) => number,
  space: number,
  max: number,
) {
  const base = greedy(words, wOf, space, max);
  if (base.length <= 1) return base;
  let best = base;
  for (let k = 1; k <= 30; k++) {
    const next = greedy(words, wOf, space, max * (1 - k * 0.015));
    if (next.length !== base.length) break;
    best = next;
  }
  return best;
}

function useBaseline() {
  const memo = useRef<number | null>(null);
  return () => {
    if (memo.current !== null) return memo.current;
    const ctx = document.createElement("canvas").getContext("2d");
    let asc = 0.935;
    let desc = 0.265;
    if (ctx) {
      ctx.font = `500 100px "${bitter.fontFamily}"`;
      const m = ctx.measureText("Hg");
      if (m.fontBoundingBoxAscent > 0) {
        asc = m.fontBoundingBoxAscent / 100;
        desc = m.fontBoundingBoxDescent / 100;
      }
    }
    memo.current = (NAME_BOX - asc - desc) / 2 + asc;
    return memo.current;
  };
}

function splits(words: string[], k: number): string[][][] {
  if (k === 1) return [[words]];
  const out: string[][][] = [];
  for (let i = 1; i <= words.length - k + 1; i++) {
    for (const rest of splits(words.slice(i), k - 1)) {
      out.push([words.slice(0, i), ...rest]);
    }
  }
  return out;
}

function splitWords(s: string) {
  return s.trim().split(/\s+/).filter(Boolean);
}

export function WeCallIt({
  descriptions = [
    "Scenes you install like components.",
    "Edits that land as commits.",
    "A film that ships with the release.",
  ],
  lead = "We call it a",
  name = "video registry.",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WeCallItProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames: T } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontsReady();
  const measure = useMeasure();
  const baselineOf = useBaseline();

  if (!ready) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const descs = descriptions.map(splitWords).filter((d) => d.length > 0);
  const n = descs.length;
  const nameWords = splitWords(name);

  const leadAt = 6 + n * STEP - 2;
  const ruleAt = leadAt + 4;
  const nameAt = leadAt + 10;
  const motionEnd = nameAt + nameWords.length * 4 + 24;
  const tail = Math.max(30, T * 0.18);
  const pace = Math.min(1.5, Math.max(0.5, (T - tail) / motionEnd));
  const t = frame / pace;

  const portrait = H > W * 1.1;
  const mx = W * (portrait ? 0.08 : 0.07);
  const my = H * (portrait ? 0.14 : 0.09);
  const mb = H * (portrait ? 0.07 : 0.08);
  const innerW = W - mx * 2;

  const space = measure(" ", 400, BODY_TRACK);
  const wBody = (s: string) => measure(s, 400, BODY_TRACK);

  let Fb = portrait ? W * 0.095 : H * 0.115;
  const stageW = innerW * (portrait ? 1 : 0.86);
  let stageLines = descs.map((d) => balanced(d, wBody, space, stageW / Fb));
  for (
    let k = 0;
    k < 40 && stageLines.some((l) => l.length > (portrait ? 3 : 2));
    k++
  ) {
    Fb *= 0.95;
    stageLines = descs.map((d) => balanced(d, wBody, space, stageW / Fb));
  }
  const Fk = portrait ? W * 0.044 : H * 0.042;
  const s = Fk / Fb;
  const bigLineH = Fb * LH;
  const kickGap = Fk * 0.32;

  const kickTops: number[] = [];
  let y = my;
  for (let i = 0; i < n; i++) {
    kickTops.push(y);
    y += stageLines[i].length * bigLineH * s + kickGap;
  }
  const leadTop = y;
  const kickBottom = leadTop + Fk * LH;

  const nameAvailH = H - mb - kickBottom - H * 0.07;
  let best = { font: 0, rows: [nameWords] };
  for (let k = 1; k <= Math.min(3, nameWords.length); k++) {
    for (const rows of splits(nameWords, k)) {
      const widest = Math.max(
        ...rows.map((r) => measure(r.join(" "), 500, NAME_TRACK)),
      );
      const font = Math.min(
        innerW / widest,
        nameAvailH / ((k - 1) * NAME_LH + CAP + DESC),
        H * (portrait ? 0.2 : 0.42),
      );
      if (font > best.font * 1.04) best = { font, rows };
    }
  }
  const Fn = best.font;
  const nameRows = best.rows;
  const lastBase = H - mb - DESC * Fn;
  const firstBase = lastBase - (nameRows.length - 1) * NAME_LH * Fn;
  const nameTop = firstBase - baselineOf() * Fn;
  const ruleY = firstBase - CAP * Fn - Math.min(Fn * 0.2, H * 0.05);

  const stageH = (i: number) => stageLines[i].length * bigLineH;
  const stageTopOf = (i: number) => {
    const midY = (kickBottom + Math.min(ruleY, H * 0.82)) / 2 + H * 0.02;
    return midY - stageH(i) / 2;
  };

  const ease = (a: number, b: number, e = EASE_OUT) =>
    interpolate(t, [a, b], [0, 1], { ...CLAMP, easing: e });

  const lineStyle = (size: number, lh: number) => ({
    height: lh,
    lineHeight: `${lh}px`,
    fontSize: size,
    whiteSpace: "nowrap" as const,
  });

  return (
    <AbsoluteFill
      style={{
        background: stage,
        color: c.ink,
        fontFamily: bitter.fontFamily,
        fontWeight: 400,
        overflow: "hidden",
      }}
    >
      {descs.map((_, i) => {
        const a = 6 + i * STEP;
        const m = a + HOLD;
        const mv = ease(m, m + MOVE, EASE_IO);
        const left = mx;
        const top = stageTopOf(i) + (kickTops[i] - stageTopOf(i)) * mv;
        const scale = 1 + (s - 1) * mv;
        let wi = 0;
        return (
          <div
            key={`d${i}`}
            style={{
              position: "absolute",
              left,
              top,
              transform: `scale(${scale.toFixed(4)})`,
              transformOrigin: "0 0",
              opacity: 1 - (1 - KICK_DIM) * mv,
              letterSpacing: `${BODY_TRACK}em`,
            }}
          >
            {stageLines[i].map((row, li) => (
              <div key={`d${i}-${li}`} style={lineStyle(Fb, bigLineH)}>
                {row.map((word, k) => {
                  const order = wi++;
                  const p = ease(a + order * 3, a + order * 3 + 16);
                  return (
                    <span
                      key={`d${i}-${li}-${k}`}
                      style={{
                        display: "inline-block",
                        whiteSpace: "pre",
                        opacity: p,
                        transform: `translateY(${((1 - p) * Fb * 0.32).toFixed(2)}px)`,
                      }}
                    >
                      {k < row.length - 1 ? `${word} ` : word}
                    </span>
                  );
                })}
              </div>
            ))}
          </div>
        );
      })}

      {lead.trim() ? (
        <div
          style={{
            position: "absolute",
            left: mx,
            top: leadTop,
            ...lineStyle(Fk, Fk * LH),
            letterSpacing: `${BODY_TRACK}em`,
            color: hi,
            opacity: ease(leadAt, leadAt + 14),
            transform: `translateY(${((1 - ease(leadAt, leadAt + 14)) * Fk * 0.5).toFixed(2)}px)`,
          }}
        >
          {lead.trim()}
        </div>
      ) : null}

      <div
        style={{
          position: "absolute",
          left: mx,
          top: ruleY,
          width: innerW,
          height: Math.max(2, Fk * 0.07),
          background: hi,
          transform: `scaleX(${ease(ruleAt, ruleAt + 22, EASE_IO).toFixed(4)})`,
          transformOrigin: "0 50%",
        }}
      />

      {nameRows.map((row, li) => {
        const p = ease(nameAt + li * 5, nameAt + li * 5 + 24);
        const boxTop = nameTop + li * NAME_LH * Fn;
        return (
          <div
            key={`n${li}`}
            style={{
              position: "absolute",
              left: mx,
              top: boxTop,
              ...lineStyle(Fn, NAME_BOX * Fn),
              fontWeight: 500,
              letterSpacing: `${NAME_TRACK}em`,
              color: hi,
              transform: `translateY(${((1 - p) * (H - boxTop)).toFixed(2)}px)`,
            }}
          >
            {row.join(" ")}
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/Unbounded";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const unbounded = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface WeekShippedEntry {
  day: string;
  item: string;
}

interface WeekShippedProps {
  entries?: WeekShippedEntry[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_ENTRIES: WeekShippedEntry[] = [
  { day: "Monday,", item: "captions that keep up." },
  { day: "Tuesday,", item: "shaders you can scrub." },
  { day: "Wednesday,", item: "icons that draw themselves." },
  { day: "Thursday,", item: "vertical, from the same file." },
  { day: "Friday,", item: "renders on your own server." },
  { day: "Saturday,", item: "one tiny fix." },
  { day: "Sunday,", item: "we rested." },
];

const FONT_PX = 200;
const TRACK = -0.03;
const DAY_SCALE = 0.42;

const EASE_ROLL = Easing.bezier(0.6, 0, 0.1, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const FIRST = 24;
const BEAT = 13;
const BREATH = 26;
const ROLL = 7;
const LAST_ROLL = 13;
const STAGGER = 1;
const HOLD_MIN = 36;

interface Metrics {
  days: number[];
  words: number[][];
  itemWords: string[][];
  space: number;
  asc: number;
  desc: number;
  tall: number;
  deep: number;
}

function measure(entries: WeekShippedEntry[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("week-shipped: no 2d context");
  const em = (s: string, w: number) => {
    ctx.font = `${w} ${FONT_PX}px "${unbounded.fontFamily}"`;
    return (
      ctx.measureText(s).width / FONT_PX +
      TRACK * Math.max(0, Array.from(s).length - 1)
    );
  };
  const itemWords = entries.map((e) => e.item.trim().split(/\s+/));
  ctx.font = `500 ${FONT_PX}px "${unbounded.fontFamily}"`;
  const fm = ctx.measureText("Hgy");
  return {
    days: entries.map((e) => em(e.day, 400)),
    words: itemWords.map((ws) => ws.map((w) => em(w, 500))),
    itemWords,
    space: em(" ", 500) - TRACK,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
    tall: ctx.measureText("dlkhfH").actualBoundingBoxAscent / FONT_PX,
    deep: ctx.measureText("gjpqy,").actualBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics(entries: WeekShippedEntry[]) {
  const key = entries.map((e) => `${e.day}\u0001${e.item}`).join("\u0002");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("week-shipped: measuring"));
  const released = useRef(false);
  const input = useRef(entries);
  input.current = entries;
  useEffect(() => {
    let live = true;
    Promise.all([
      unbounded.waitUntilDone(),
      document.fonts.load(`500 100px "${unbounded.fontFamily}"`),
      document.fonts.load(`400 100px "${unbounded.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(input.current) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function wrap(words: string[], widths: number[], space: number, max: number) {
  const run = (limit: number) => {
    const lines: string[][] = [];
    let line: string[] = [];
    let w = 0;
    words.forEach((word, i) => {
      const add = line.length === 0 ? widths[i] : w + space + widths[i];
      if (line.length > 0 && add > limit) {
        lines.push(line);
        line = [word];
        w = widths[i];
      } else {
        line.push(word);
        w = add;
      }
    });
    if (line.length) lines.push(line);
    return lines;
  };
  const first = run(max);
  let best = first;
  for (let k = 1; k <= 20; k++) {
    const next = run(max * (1 - k * 0.025));
    if (next.length !== first.length) break;
    best = next;
  }
  return best.map((l) => l.join(" "));
}

function WeekShippedBase({
  entries = DEFAULT_ENTRIES,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WeekShippedProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const dark = theme === "dark";
  const field = dark ? (accent ?? "#FF5A1F") : "#FFFFFF";
  const stage =
    background === "transparent" ? "transparent" : (background ?? field);
  const ink = "#000000";
  const dayInk = dark ? "#000000" : (accent ?? "#E8480F");

  const list = entries.length > 0 ? entries : DEFAULT_ENTRIES;
  const m = useMetrics(list);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const total = durationInFrames * speed;
  const natural = Array.from({ length: n - 1 }, (_, k) =>
    k === 0 ? FIRST : k === n - 2 && n > 2 ? BREATH : BEAT,
  );
  const sum = natural.reduce((s, d) => s + d, 0);
  const fit = sum > 0 ? Math.min(1, (total - HOLD_MIN - LAST_ROLL) / sum) : 1;
  const starts: number[] = [0];
  for (let k = 0; k < n - 1; k++)
    starts.push(starts[k] + Math.max(8, Math.round(natural[k] * fit)));

  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.09 : 0.075);
  const maxW = W - marginX * 2;
  const lead = Math.max(1.04, m.tall + m.deep + 0.1);
  const longest = Math.max(
    ...m.words.map(
      (ws) => ws.reduce((s, w) => s + w, 0) + m.space * (ws.length - 1),
    ),
  );
  const widestWord = Math.max(...m.words.flat());
  const F = Math.min(
    portrait ? W * 0.11 : H * 0.17,
    maxW / Math.max(widestWord, 0.1),
    (maxW * 3) / Math.max(longest * 1.15, 0.1),
  );
  const Fd = F * DAY_SCALE;
  const wrapped = list.map((_, k) =>
    wrap(m.itemWords[k], m.words[k], m.space, maxW / F),
  );
  const lineH = lead * F;
  const dayGap = F * 0.3;
  const layoutOf = (k: number) => {
    const rows = wrapped[k].length;
    const dayBox = Fd * (m.tall + m.deep);
    const blockH = dayBox + dayGap + F * (m.tall + m.deep) + (rows - 1) * lineH;
    const top = H / 2 - blockH / 2;
    return {
      dayBase: top + Fd * m.tall,
      itemBase: top + dayBox + dayGap + F * m.tall,
    };
  };

  let cur = 0;
  for (let k = 0; k < n; k++) if (t >= starts[k]) cur = k;
  const last = cur === n - 1 && n > 1;
  const roll = last ? LAST_ROLL : ROLL;
  const s0 = starts[cur];

  const outP =
    cur === 0
      ? 1
      : interpolate(t, [s0, s0 + roll * 0.5], [0, 1], {
          ...CLAMP,
          easing: Easing.bezier(0.55, 0, 1, 0.45),
        });
  const inP = (order: number) =>
    cur === 0
      ? interpolate(t, [order * STAGGER - 3, order * STAGGER + 11], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })
      : interpolate(t, [s0 + roll * 0.35 + order, s0 + roll + order], [0, 1], {
          ...CLAMP,
          easing: last ? EASE_OUT : EASE_ROLL,
        });

  const line = (
    key: string,
    text: string,
    base: number,
    size: number,
    weight: number,
    color: string,
    shift: number,
  ) => {
    const winTop = base - size * (m.tall + 0.05);
    const winH = size * (m.tall + m.deep + 0.1);
    const lineBox = size * (m.asc + m.desc);
    return (
      <div
        key={key}
        style={{
          position: "absolute",
          left: marginX,
          right: 0,
          top: winTop,
          height: winH,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: base - size * m.asc - winTop + shift * winH * 1.04,
            height: lineBox,
            lineHeight: `${lineBox}px`,
            fontFamily: unbounded.fontFamily,
            fontWeight: weight,
            fontSize: size,
            letterSpacing: `${TRACK}em`,
            whiteSpace: "pre",
            color,
          }}
        >
          {text}
        </div>
      </div>
    );
  };

  const entryNodes = (
    k: number,
    shiftOf: (order: number) => number,
    tag: string,
  ) => {
    const L = layoutOf(k);
    const out: React.ReactNode[] = [];
    const d = shiftOf(0);
    if (Math.abs(d) < 1) {
      out.push(line(`${tag}d`, list[k].day, L.dayBase, Fd, 400, dayInk, d));
    }
    wrapped[k].forEach((tx, i) => {
      const sh = shiftOf(i + 1);
      if (Math.abs(sh) < 1) {
        out.push(
          line(`${tag}${i}`, tx, L.itemBase + i * lineH, F, 500, ink, sh),
        );
      }
    });
    return out;
  };

  const nodes: React.ReactNode[] = [];
  if (cur > 0 && outP < 1) nodes.push(...entryNodes(cur - 1, () => -outP, "o"));
  nodes.push(...entryNodes(cur, (order) => 1 - inP(order), "i"));

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  speed: 1,
};

type WeekShippedElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WeekShippedBase>;

const WeekShippedInner = forwardRef<
  HTMLDivElement,
  WeekShippedElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WeekShipped>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WeekShippedBase
          {...(componentProps as unknown as ComponentProps<typeof WeekShippedBase>)}
        />
      </div>
    </Sequence>
  );
});

export const WeekShipped = Interactive.withSchema({
  Component: WeekShippedInner,
  componentName: "<WeekShipped>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/BarlowCondensed";
import { useEffect, useMemo, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";

const WEIGHTS = ["100", "200", "300", "400", "500"] as const;
const barlow = loadFont("normal", {
  weights: [...WEIGHTS],
  subsets: ["latin"],
});

export interface WeightCutProps {
  value?: number;
  from?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  eyebrow?: string;
  label?: string;
  lightWeight?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: {
    bg: "#000000",
    ink: "#FFFFFF",
    accent: "#D4FF00",
  },
  light: {
    bg: "#D4FF00",
    ink: "#000000",
    accent: "#000000",
  },
} as const;

const TRACK = 0.01;
const SUFFIX_SCALE = 0.3;

const ENTER_END = 14;
const COUNT_AT = 20;
const COUNT_END = 78;
const LABEL_AT = 64;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_COUNT = Easing.bezier(0.3, 0, 0.12, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: Record<string, number>;
  slot: number;
  stemLight: number;
  stemHeavy: number;
  baseline: number;
  figTop: number;
}

function snapWeight(w: number) {
  const v = Math.min(500, Math.max(100, w));
  return Math.round(v / 100) * 100;
}

function measure(chars: string[], light: number): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const adv: Record<string, number> = {};
  let slot = 0.45;
  let stemLight = 0.02;
  let stemHeavy = 0.1;
  let baseline = 0.8;
  let figTop = 0.7;
  if (!ctx) {
    for (const ch of chars) adv[ch] = 0.45;
    return { adv, slot, stemLight, stemHeavy, baseline, figTop };
  }
  const ink = (w: number) => {
    ctx.font = `${w} 200px "${barlow.fontFamily}"`;
    const mm = ctx.measureText("I");
    return (mm.actualBoundingBoxLeft + mm.actualBoundingBoxRight) / 200;
  };
  stemHeavy = ink(500);
  stemLight = ink(light);
  ctx.font = `${light} 200px "${barlow.fontFamily}"`;
  for (const ch of chars) adv[ch] = ctx.measureText(ch).width / 200;
  slot = Math.max(
    ...Array.from({ length: 10 }, (_, d) => adv[String(d)] ?? 0.4),
  );
  const fm = ctx.measureText("0");
  const asc = fm.fontBoundingBoxAscent / 200;
  const desc = fm.fontBoundingBoxDescent / 200;
  baseline = (1 - (asc + desc)) / 2 + asc;
  figTop = fm.actualBoundingBoxAscent / 200;
  return { adv, slot, stemLight, stemHeavy, baseline, figTop };
}

function useMetrics(chars: string[], light: number) {
  const key = `${light}\u0002${chars.join("\u0001")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("weight-cut: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [lw, list] = key.split("\u0002");
    Promise.all([
      barlow.waitUntilDone(),
      ...WEIGHTS.map((w) =>
        document.fonts.load(`${w} 100px "${barlow.fontFamily}"`),
      ),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(list.split("\u0001"), Number(lw)) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

function format(v: number, decimals: number) {
  return v.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function intDigits(v: number, decimals: number) {
  const shown = Math.round(Math.abs(v) * 10 ** decimals) / 10 ** decimals;
  return Math.max(1, Math.floor(shown).toString().length);
}

export function WeightCut({
  value = 6.8,
  from = 94,
  decimals = 1,
  prefix = "",
  suffix = "KB",
  eyebrow = "Per scene, gzipped",
  label = "Lighter than your logo file.",
  lightWeight = 100,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WeightCutProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const light = snapWeight(lightWeight);
  const chars = useMemo(
    () =>
      Array.from(
        new Set(["0123456789.,", prefix, suffix.toUpperCase()].join("")),
      ),
    [prefix, suffix],
  );
  const m = useMetrics(chars, light);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  const drops = useMemo(() => {
    const out: { at: number }[] = [];
    let prev = intDigits(from, decimals);
    for (let f = COUNT_AT; f <= COUNT_END; f += 0.25) {
      const g = EASE_COUNT((f - COUNT_AT) / (COUNT_END - COUNT_AT));
      const d = intDigits(from + (value - from) * g, decimals);
      if (d < prev) {
        for (let k = prev; k > d; k--) out.push({ at: f });
        prev = d;
      }
    }
    return out;
  }, [from, value, decimals]);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);

  const g = interpolate(t, [COUNT_AT, COUNT_END], [0, 1], {
    ...CLAMP,
    easing: EASE_COUNT,
  });
  const raw = from + (value - from) * g;
  const shown = Math.round(raw * 10 ** decimals) / 10 ** decimals;
  const text = `${prefix}${format(shown, decimals)}`;
  const span = from - value;
  const heavy = span === 0 ? 0 : Math.min(1, Math.max(0, (raw - value) / span));

  const enter = interpolate(t, [-5, ENTER_END], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const relax = spring({
    frame: t - (COUNT_END - 10),
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.9 },
  });
  const closing = drops
    .filter((d) => t >= d.at)
    .map((d) =>
      spring({
        frame: t - d.at,
        fps,
        config: { damping: 16, stiffness: 140, mass: 0.8 },
      }),
    )
    .filter((k) => k < 0.999);

  const sufText = suffix.toUpperCase();
  const advOf = (ch: string) => m.adv[ch] ?? m.slot;
  const startText = `${prefix}${format(from, decimals)}`;
  const startEm =
    Array.from(startText).reduce(
      (a, ch) => a + (/[0-9]/.test(ch) ? m.slot : advOf(ch)) + TRACK,
      0,
    ) +
    m.stemHeavy +
    (sufText
      ? 0.03 +
        Array.from(sufText).reduce((a, ch) => a + advOf(ch), 0) * SUFFIX_SCALE +
        m.stemHeavy * SUFFIX_SCALE
      : 0);

  const margin = portrait ? W * 0.07 : W * 0.05;
  const colW = portrait ? 0 : W * 0.28;
  const roomW = W - margin * 2 - colW;
  const F = Math.min(
    roomW / Math.max(0.2, startEm),
    (H * (portrait ? 0.3 : 0.76)) / m.figTop,
  );
  const stroke = Math.max(0, m.stemHeavy - m.stemLight) * F * heavy;
  const baseY = portrait ? H * 0.62 : H - margin;
  const boxTop = baseY - m.baseline * F;

  const glyphs: { ch: string; x: number; w: number }[] = [];
  let x = margin + stroke / 2;
  for (const k of closing) x += m.slot * F * (1 - k);
  for (const ch of Array.from(text)) {
    const natural = advOf(ch);
    const w =
      (/[0-9]/.test(ch) ? m.slot + (natural - m.slot) * relax : natural) * F +
      TRACK * F +
      stroke;
    glyphs.push({ ch, x, w });
    x += w;
  }
  const numRight = x;
  const sufF = F * SUFFIX_SCALE;

  const eyebrowFs = (portrait ? 40 : 26) * s;
  const labelFs = (portrait ? 72 : 52) * s;
  const eyebrowP = interpolate(t, [2, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelP = interpolate(t, [LABEL_AT, LABEL_AT + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const figure = {
    position: "absolute" as const,
    whiteSpace: "pre" as const,
    fontFamily: barlow.fontFamily,
    fontWeight: light,
    color: c.ink,
    WebkitTextStroke:
      stroke > 0.05 ? `${stroke.toFixed(2)}px ${c.ink}` : undefined,
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: enter,
          transform: `translateY(${((1 - enter) * F * 0.06).toFixed(2)}px)`,
        }}
      >
        {glyphs.map((gl, i) => (
          <div
            key={i}
            style={{
              ...figure,
              left: gl.x,
              width: gl.w,
              top: boxTop,
              height: F,
              lineHeight: `${F}px`,
              textAlign: "center",
              fontSize: F,
            }}
          >
            {gl.ch}
          </div>
        ))}
        {sufText ? (
          <div
            style={{
              ...figure,
              left: numRight + F * 0.03,
              top: baseY - m.baseline * sufF,
              height: sufF,
              lineHeight: `${sufF}px`,
              fontSize: sufF,
              WebkitTextStroke:
                stroke > 0.05
                  ? `${(stroke * SUFFIX_SCALE).toFixed(2)}px ${c.ink}`
                  : undefined,
            }}
          >
            {sufText}
          </div>
        ) : null}
      </div>

      <div
        style={{
          position: "absolute",
          ...(portrait
            ? { left: margin, right: margin, top: margin * 1.6 }
            : { right: margin, width: colW - margin * 0.5, top: margin }),
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: eyebrowFs * 0.7,
          fontFamily: barlow.fontFamily,
          textTransform: "uppercase",
        }}
      >
        {eyebrow ? (
          <div
            style={{
              fontWeight: 500,
              fontSize: eyebrowFs,
              lineHeight: 1,
              color: spot,
              opacity: eyebrowP,
            }}
          >
            {eyebrow}
          </div>
        ) : null}
        {label ? (
          <div
            style={{
              fontWeight: 500,
              fontSize: labelFs,
              lineHeight: 0.94,
              color: c.ink,
              textWrap: "balance",
              opacity: labelP,
              transform: `translateY(${((1 - labelP) * labelFs * 0.4).toFixed(2)}px)`,
            }}
          >
            {label}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

import { loadVariableFont } from "@remotion/google-fonts/Geist";
import React, { useId, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate, interpolateColors, spring, useCurrentFrame, useVideoConfig } from "remotion";

const { fontFamily: sans } = loadVariableFont("normal", {
  subsets: ["latin"],
});

export interface WeightWaveProps {
  text?: string;
  highlight?: string;
  from?: number;
  peak?: number;
  settle?: number;
  waves?: number;
  accent?: string;
  theme?: "dark" | "light";
  speed?: number;
}

/** Geist 500 advance widths (per 1000 em) for ASCII 32–126 (widest weight used). */
const GEIST_500 = [
  243, 228, 361, 515, 643, 810, 649, 186, 290, 290, 427, 562, 213, 418, 213,
  494, 673, 406, 630, 625, 629, 641, 604, 531, 624, 606, 302, 302, 546, 544,
  546, 570, 925, 689, 688, 713, 701, 609, 595, 713, 716, 280, 607, 656, 583,
  890, 745, 751, 657, 745, 680, 654, 568, 694, 688, 968, 633, 594, 561, 361,
  470, 361, 438, 558, 258, 565, 608, 563, 608, 576, 412, 607, 591, 256, 284,
  609, 282, 885, 591, 588, 608, 608, 394, 537, 410, 586, 560, 829, 607, 553,
  552, 395, 274, 395, 523,
];
/** The wght axis is kept inside this range (brand rule: display type at most 500). */
const WGHT_MIN = 100;
const WGHT_MAX = 500;
const TRACK = -0.035;

const ENTER = 4;
const WAVE_START = 16;
const WAVE_LEN = 46;
const WAVE_GAP = 24;
const SETTLE_STAGGER = 2.4;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_TRAVEL = Easing.bezier(0.42, 0, 0.58, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam": the settled hero word takes a clip-text beam fill, and a faint
// beam haze sits low behind the line.
const THEMES = {
  dark: {
    bg: "#02030A",
    fg: "#F2F3F8",
    fgClear: "rgba(242,243,248,0)",
    grain: 0.07,
    beam: ["#F4F7FF", "#8FB4FF", "#3D5BFF"],
    haze: "rgba(61,91,255,0.16)",
  },
  light: {
    bg: "#F4F5F8",
    fg: "#12131A",
    fgClear: "rgba(18,19,26,0)",
    grain: 0.045,
    beam: ["#3D5BFF", "#2A3BD0", "#1A1660"],
    haze: "rgba(143,180,255,0.24)",
  },
} as const;

function em(text: string) {
  let w = 0;
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    w += (code >= 32 && code < 127 ? GEIST_500[code - 32] : 600) / 1000;
    w += TRACK;
  }
  return w;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={41}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function WeightWave({
  text = "Made to move.",
  highlight,
  from = 100,
  peak = 500,
  settle = 460,
  waves = 2,
  accent = "#3B5BFD",
  theme = "dark",
  speed = 1,
}: WeightWaveProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];

  const chars = useMemo(() => Array.from(text), [text]);
  const n = chars.length;

  const accentRange = useMemo(() => {
    const target = highlight ?? text.trim().split(/\s+/).pop() ?? "";
    const at = target ? text.lastIndexOf(target) : -1;
    return at < 0 ? [n, n] : [at, at + Array.from(target).length];
  }, [highlight, text, n]);

  const F = Math.min(H * 0.32, (W * 0.8) / em(text));
  const clampW = (w: number) => Math.min(WGHT_MAX, Math.max(WGHT_MIN, w));
  const lo = clampW(from);
  const hi = clampW(peak);
  const rest = clampW(settle);

  const settleStart = WAVE_START + (waves - 1) * WAVE_GAP + WAVE_LEN - 8;
  const sigma = 0.12;
  const push = interpolate(t, [0, settleStart + 70], [0, 1], CLAMP);

  const tintAt = settleStart + 12;
  const sheen = interpolate(t, [tintAt, tintAt + 80], [0, 1], CLAMP);
  // The deep end of the beam is the brand accent (dark), or its first stop (light).
  const beam =
    theme === "light"
      ? [accent, c.beam[1], c.beam[2]]
      : [c.beam[0], c.beam[1], accent];
  const beamFill = `linear-gradient(${96 + sheen * 10}deg, ${beam[0]} ${-10 + sheen * 8}%, ${beam[1]} ${44 + sheen * 6}%, ${beam[2]} 100%)`;
  const hazeIn = interpolate(t, [WAVE_START, settleStart + 40], [0.35, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const group = (nodes: React.ReactNode[]) => {
    const [a, b] = accentRange;
    if (a >= b) return nodes;
    return [
      ...nodes.slice(0, a),
      <span
        key="accent"
        style={{
          display: "inline-flex",
          alignItems: "baseline",
          padding: "0.12em 0.06em 0.22em",
          margin: "-0.12em -0.06em -0.22em",
          color: "transparent",
          backgroundImage: t >= tintAt ? beamFill : "none",
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
        }}
      >
        {nodes.slice(a, b)}
      </span>,
      ...nodes.slice(b),
    ];
  };

  return (
    <AbsoluteFill style={{ background: c.bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(48% 34% at 50% 60%, ${c.haze} 0%, transparent 72%)`,
          opacity: hazeIn,
        }}
      />
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${1 + push * 0.025})`,
          transformOrigin: "50% 50%",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            justifyContent: "center",
            whiteSpace: "pre",
            fontFamily: sans,
            fontSize: F,
            lineHeight: 1,
            letterSpacing: `${TRACK}em`,
            fontKerning: "normal",
          }}
        >
          {group(
            chars.map((ch, i) => {
              const p = n > 1 ? i / (n - 1) : 0.5;
              let bump = 0;
              for (let k = 0; k < waves; k++) {
                const s = WAVE_START + k * WAVE_GAP;
                const crest = interpolate(t, [s, s + WAVE_LEN], [-0.3, 1.3], {
                  ...CLAMP,
                  easing: EASE_TRAVEL,
                });
                const live = t > s && t < s + WAVE_LEN ? 1 : 0;
                bump = Math.max(
                  bump,
                  live * Math.exp(-(((p - crest) / sigma) ** 2)),
                );
              }
              const wave = lo + (hi - lo) * bump;
              const sp = spring({
                frame: t - settleStart - i * SETTLE_STAGGER,
                fps,
                config: { damping: 15, stiffness: 120, mass: 0.9 },
              });
              const weight = clampW(wave + (rest - wave) * sp);
              const isAccent = i >= accentRange[0] && i < accentRange[1];
              const tint = isAccent
                ? interpolate(
                    t,
                    [
                      settleStart + 14 + (i - accentRange[0]) * 2,
                      settleStart + 30 + (i - accentRange[0]) * 2,
                    ],
                    [0, 1],
                    CLAMP,
                  )
                : 0;
              const o = interpolate(t, [ENTER + i, ENTER + i + 12], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              return (
                <span
                  key={`${i}-${ch}`}
                  style={{
                    display: "inline-block",
                    fontWeight: weight,
                    color: interpolateColors(tint, [0, 1], [c.fg, c.fgClear]),
                    opacity: o,
                  }}
                >
                  {ch}
                </span>
              );
            }),
          )}
        </div>
      </AbsoluteFill>
      <Grain opacity={c.grain} />
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/Rubik";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const rubik = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface WhatSticksProps {
  lines?: string[];
  keep?: number;
  moments?: string[];
  forget?: number[];
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2A1033", ink: "#FFFFFF", accent: "#7CC4FF", ghost: 0.17 },
  light: { bg: "#F3EEF5", ink: "#2A1033", accent: "#2B7BD6", ghost: 0.2 },
} as const;

const DEFAULT_LINES = [
  "Scenes install with one command.",
  "Every word on screen is a prop.",
  "Transitions land on the beat.",
  "Captions come from the transcript.",
  "You own every file.",
  "It renders on your laptop.",
];

const DEFAULT_MOMENTS = [
  "Tonight, you’ll remember all of it.",
  "Tomorrow, about half.",
  "Next week, just this.",
];

const WGHT = 500;
const TRACK = -0.025;
const LH = 1.2;
const SLUG = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Metrics = Record<string, number>;

function measureAll(texts: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("what-sticks: no 2d context");
  ctx.font = `${WGHT} 100px "${rubik.fontFamily}"`;
  const w: Metrics = {};
  for (const s of texts) {
    w[s] = ctx.measureText(s).width / 100 + TRACK * Array.from(s).length;
  }
  return w;
}

function useMetrics(texts: string[]) {
  const key = texts.join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("what-sticks: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      rubik.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${rubik.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measureAll(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.m : null;
}

const lineW = (words: string[], m: Metrics) =>
  m[words.join(" ")] ?? words.reduce((a, w) => a + m[w], 0);

function splitTwo(text: string, m: Metrics): string[] {
  const words = text.split(" ").filter(Boolean);
  if (words.length < 2) return [text];
  let best: string[] = [text];
  let bestW = Number.POSITIVE_INFINITY;
  for (let cut = 1; cut < words.length; cut++) {
    const a = words.slice(0, cut).join(" ");
    const b = words.slice(cut).join(" ");
    const w = Math.max(m[a], m[b]);
    if (w < bestW) {
      bestW = w;
      best = [a, b];
    }
  }
  return best;
}

function prefixes(text: string): string[] {
  const words = text.split(" ").filter(Boolean);
  const out: string[] = [];
  for (let i = 1; i <= words.length; i++) {
    out.push(words.slice(0, i).join(" "));
    out.push(words.slice(i).join(" "));
  }
  return out;
}

const hash = (i: number, salt: number) => {
  const x = Math.sin(i * 127.1 + salt * 311.7) * 43758.5453;
  return x - Math.floor(x);
};

function WhatSticksBase({
  lines = DEFAULT_LINES,
  keep,
  moments = DEFAULT_MOMENTS,
  forget,
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WhatSticksProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = lines.length > 0 ? lines : DEFAULT_LINES;
  const steps = moments.length > 0 ? moments : DEFAULT_MOMENTS;
  const n = list.length;
  const kept = Math.min(
    n - 1,
    Math.max(0, keep ?? Math.min(n - 1, Math.floor(n * 0.7))),
  );

  const m = useMetrics([...list.flatMap(prefixes), ...steps]);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const availW = W * (portrait ? 0.84 : 0.8);
  let F = 0;
  let blocks: string[][] = [];
  for (const L of [1, 2]) {
    const target = Math.max(
      ...list.map((s) => Math.max(...splitTwo(s, m).map((r) => m[r]))),
    );
    const b = list.map((s) =>
      L === 1 || m[s] <= target ? [s] : splitTwo(s, m),
    );
    const widest = Math.max(
      0.1,
      ...b.flat().map((r) => lineW([r], m)),
      ...steps.map((s) => m[s] * SLUG),
    );
    const rows = b.reduce((a, x) => a + x.length, 0);
    const size = Math.min(
      H * (portrait ? 0.062 : 0.092),
      availW / widest,
      (H * (portrait ? 0.7 : 0.8)) / (rows * LH + SLUG * 1.6 + 0.9),
    );
    if (size > F * 1.12) {
      F = size;
      blocks = b;
    }
  }

  const S = F * SLUG;
  const slugH = S * 1.5;
  const gapAfterSlug = F * 0.75;
  const rowH = F * LH;
  const totalRows = blocks.reduce((a, x) => a + x.length, 0);
  const blockH = slugH + gapAfterSlug + totalRows * rowH;
  const top = (H - blockH) / 2;

  const others = list.map((_, i) => i).filter((i) => i !== kept);
  const order =
    forget && forget.length > 0
      ? [
          ...forget.filter((i) => i !== kept && i >= 0 && i < n),
          ...others.filter((i) => !forget.includes(i)),
        ]
      : [...others].sort((a, b) => hash(a, n) - hash(b, n));

  const stepCount = Math.max(1, steps.length);
  const span = durationInFrames * speed;
  const enterOf = (i: number) => 10 + i * 5;
  const first = enterOf(n - 1) + 18 + 30;
  const gap =
    stepCount > 2
      ? Math.min(90, Math.max(42, (span - first - 100) / (stepCount - 2)))
      : 0;
  const stepAt = (s: number) => first + (s - 1) * gap;

  const forgottenAt = new Map<number, { step: number; rank: number }>();
  if (stepCount > 1) {
    let done = 0;
    for (let s = 1; s < stepCount; s++) {
      const target = Math.round(((n - 1) * s) / (stepCount - 1));
      for (let r = 0; done < target; r++, done++) {
        forgottenAt.set(order[done], { step: s, rank: r });
      }
    }
  }

  const slugIndex = (() => {
    let k = 0;
    for (let s = 1; s < stepCount; s++) if (t >= stepAt(s)) k = s;
    return k;
  })();

  const nodes: React.ReactNode[] = [];

  for (let s = 0; s < stepCount; s++) {
    const tin = s === 0 ? 0 : stepAt(s);
    const tout = s + 1 < stepCount ? stepAt(s + 1) : Number.POSITIVE_INFINITY;
    if (t < tin - 1 || t > tout + 14) continue;
    if (Math.abs(s - slugIndex) > 1) continue;
    const enter = s === 0 ? tin : tin + 6;
    const pin = interpolate(t, [enter, enter + 14], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const pout = Number.isFinite(tout)
      ? interpolate(t, [tout, tout + 5], [0, 1], {
          ...CLAMP,
          easing: EASE_IN_OUT,
        })
      : 0;
    const last = s === stepCount - 1;
    nodes.push(
      <div
        key={`slug-${s}`}
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top,
          height: slugH,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: "100%",
            textAlign: "center",
            fontFamily: rubik.fontFamily,
            fontWeight: 400,
            fontSize: S,
            lineHeight: `${slugH}px`,
            letterSpacing: "-0.005em",
            whiteSpace: "pre",
            color: last
              ? interpolateColors(
                  Math.min(Math.max(t, tin + 6), tin + 20),
                  [tin + 6, tin + 20],
                  [c.ink, hi],
                )
              : c.ink,
            opacity: (0.72 + (last ? 0.28 : 0)) * (1 - pout) * pin,
            transform: `translateY(${((1 - pin) * slugH * 0.6).toFixed(2)}px)`,
          }}
        >
          {steps[s]}
        </div>
      </div>,
    );
  }

  let row = 0;
  const finalStep = stepCount - 1;
  const glowAt = stepAt(Math.max(1, finalStep)) + 22;
  for (let i = 0; i < n; i++) {
    const rows = blocks[i];
    const y0 = top + slugH + gapAfterSlug + row * rowH;
    row += rows.length;
    const d = enterOf(i);
    if (t < d - 1) continue;
    const pin = interpolate(t, [d, d + 18], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const f = forgottenAt.get(i);
    let alpha = 1;
    if (f) {
      const fs = stepAt(f.step) + 10 + f.rank * 5;
      alpha = interpolate(t, [fs, fs + 20], [1, c.ghost], {
        ...CLAMP,
        easing: EASE_IN_OUT,
      });
    }
    const isKept = i === kept && stepCount > 1;
    const glow = isKept
      ? interpolate(t, [glowAt, glowAt + 18], [0, 1], {
          ...CLAMP,
          easing: EASE_IN_OUT,
        })
      : 0;
    const color = isKept ? interpolateColors(glow, [0, 1], [c.ink, hi]) : c.ink;
    nodes.push(
      <div
        key={`line-${i}`}
        style={{
          position: "absolute",
          left: 0,
          width: W,
          top: y0 - F * 0.12,
          height: rows.length * rowH + F * 0.24,
          overflow: "hidden",
          opacity: alpha,
          transform: `scale(${1 + glow * 0.05})`,
          transformOrigin: "50% 50%",
        }}
      >
        <div
          style={{
            paddingTop: F * 0.12,
            transform: `translateY(${((1 - pin) * rowH * 0.9).toFixed(2)}px)`,
          }}
        >
          {rows.map((r) => (
            <div
              key={r}
              style={{
                width: "100%",
                height: rowH,
                textAlign: "center",
                fontFamily: rubik.fontFamily,
                fontWeight: WGHT,
                fontSize: F,
                lineHeight: `${rowH}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color,
              }}
            >
              {r}
            </div>
          ))}
        </div>
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  speed: 1,
};

type WhatSticksElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WhatSticksBase>;

const WhatSticksInner = forwardRef<
  HTMLDivElement,
  WhatSticksElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WhatSticks>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WhatSticksBase
          {...(componentProps as unknown as ComponentProps<typeof WhatSticksBase>)}
        />
      </div>
    </Sequence>
  );
});

export const WhatSticks = Interactive.withSchema({
  Component: WhatSticksInner,
  componentName: "<WhatSticks>",
