  schema: elementSchema,
  supportsEffects: false,
});

import { loadFont } from "@remotion/google-fonts/Geologica";
import React, { useEffect, useRef, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig } from "remotion";

const geologica = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface WhichMeansProps {
  name?: string;
  label?: string;
  steps?: string[];
  hinge?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#0E3B43", ink: "#FFFFFF", accent: "#4FE3D0" },
  light: { bg: "#E8F6F5", ink: "#0B3138", accent: "#0F8C7E" },
} as const;

const DEFAULT_STEPS = [
  "Every edit shows up as you type,",
  "you catch the typo before you render,",
  "the first render is the one you ship.",
];

const FONT_PX = 200;
const NAME_W = 500;
const BODY_W = 400;
const NAME_TRACK = -0.035;
const BODY_TRACK = -0.02;
const LH = 1.16;
const NAME_LH = 1.02;
const HINGE_EM = 0.5;
const GAP_EM = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const NAME_AT = 0;
const FIRST_AT = 12;
const FIRST_READ = 36;
const WORD_STAGGER = 2;
const WORD_IN = 12;
const CENTER_TO_SLOT = 14;
const EXIT = 11;
const RISE = 18;
const WRITE_AFTER_RISE = 13;
const DIM = 0.5;
const TAIL = 76;

type Metrics = Record<string, number>;
const key = (w: number, s: string) => `${w}\u0002${s}`;

function measureAll(texts: string[]): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("which-means: no 2d context");
  const out: Metrics = {};
  for (const weight of [NAME_W, BODY_W]) {
    ctx.font = `${weight} ${FONT_PX}px "${geologica.fontFamily}"`;
    for (const s of texts) {
      out[key(weight, s)] = ctx.measureText(s).width / FONT_PX;
    }
  }
  return out;
}

function useMetrics(texts: string[]) {
  const id = texts.join("\u0001");
  const [state, setState] = useState<{ id: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("which-means: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      geologica.waitUntilDone(),
      document.fonts.load(`${NAME_W} 100px "${geologica.fontFamily}"`),
      document.fonts.load(`${BODY_W} 100px "${geologica.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ id, m: measureAll(id.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [id, handle]);
  return state && state.id === id ? state.m : null;
}

const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);

function greedy(
  words: string[],
  width: (w: string) => number,
  space: number,
  limit: number,
) {
  const lines: string[][] = [];
  let cur: string[] = [];
  let acc = 0;
  for (const w of words) {
    const ww = width(w);
    if (cur.length > 0 && acc + space + ww > limit) {
      lines.push(cur);
      cur = [w];
      acc = ww;
    } else {
      acc = cur.length > 0 ? acc + space + ww : ww;
      cur.push(w);
    }
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

function balanced(
  words: string[],
  width: (w: string) => number,
  space: number,
  limit: number,
) {
  const count = greedy(words, width, space, limit).length;
  let lo = 0;
  let hi = limit;
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    if (greedy(words, width, space, mid).length <= count) hi = mid;
    else lo = mid;
  }
  return greedy(words, width, space, hi);
}

function partitions(words: string[], parts: number): string[][][] {
  if (parts <= 1 || words.length <= 1) return [[words]];
  const out: string[][][] = [];
  for (let cut = 1; cut <= words.length - parts + 1; cut++) {
    for (const rest of partitions(words.slice(cut), parts - 1)) {
      out.push([words.slice(0, cut), ...rest]);
    }
  }
  return out;
}

const stripEnd = (s: string) => s.replace(/[\s,.;:…]+$/u, "");

interface Clause {
  lines: string[][];
  h: number;
}

export function WhichMeans({
  name = "Live preview",
  label = "New",
  steps = DEFAULT_STEPS,
  hinge = "which means",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WhichMeansProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = (steps.length > 0 ? steps : DEFAULT_STEPS).map(stripEnd);
  const nameWords = splitWords(name);
  const m = useMetrics([
    " ",
    "…",
    ...nameWords,
    ...list.flatMap(splitWords),
    hinge,
    label,
  ]);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.07);

  const nameX = marginX;
  const colX = portrait ? marginX : W * 0.36;
  const nameMaxW = portrait ? W - marginX * 2 : colX - marginX - W * 0.055;
  const colW = W - marginX - colX;

  const nW = (s: string) =>
    m[key(NAME_W, s)] + NAME_TRACK * Array.from(s).length;
  const bW = (s: string) =>
    m[key(BODY_W, s)] + BODY_TRACK * Array.from(s).length;
  const nSpace = nW(" ");
  const bSpace = bW(" ");
  const lineWidth = (line: string[], f: (s: string) => number, sp: number) =>
    line.reduce((a, w, i) => a + f(w) + (i > 0 ? sp : 0), 0);

  const nameCap = H * (portrait ? 0.09 : 0.16);
  let nameLines: string[][] = [nameWords];
  let nameF = 0;
  let nameScore = -1;
  for (let L = 1; L <= Math.min(3, nameWords.length); L++) {
    for (const p of partitions(nameWords, L)) {
      const wEm = Math.max(...p.map((l) => lineWidth(l, nW, nSpace)));
      const f = Math.min(nameCap, nameMaxW / wEm);
      const score = f / (1 + 0.12 * (L - 1));
      if (score > nameScore) {
        nameScore = score;
        nameF = f;
        nameLines = p;
      }
    }
  }

  const bodyCap = H * (portrait ? 0.058 : 0.1);
  const maxStack = H * (portrait ? 0.56 : 0.86);
  let F = bodyCap;
  let clauses: Clause[] = [];
  for (let i = 0; i < 40; i++) {
    clauses = list.map((s) => {
      const lines = balanced(splitWords(s), bW, bSpace, colW / F);
      return { lines, h: lines.length * LH * F };
    });
    const tallest = Math.max(...clauses.map((cl) => cl.h));
    const stack = tallest * 2 + F * (HINGE_EM + GAP_EM * 2);
    const tooMany = clauses.some((cl) => cl.lines.length > 3);
    if (!tooMany && stack <= maxStack) break;
    F *= 0.95;
  }

  const span = durationInFrames * speed;
  const fixed = FIRST_AT + FIRST_READ + TAIL;
  const period =
    n > 2
      ? Math.min(72, Math.max(44, (span - fixed - 10) / (n - 2)))
      : Math.max(44, span - fixed);
  const stepAt = (k: number) =>
    k <= 0 ? FIRST_AT : FIRST_AT + FIRST_READ + (k - 1) * period;

  const ease = (from: number, dur: number, curve = EASE_OUT) =>
    interpolate(t, [from, from + dur], [0, 1], { ...CLAMP, easing: curve });

  const hingeY = portrait ? H * 0.57 : H * 0.5;
  const hingeF = F * HINGE_EM;
  const gap = F * GAP_EM;
  const causeBottom = hingeY - hingeF / 2 - gap;
  const effectTop = hingeY + hingeF / 2 + gap;
  const causeTop = (k: number) => causeBottom - clauses[k].h;

  const nameH = nameLines.length * NAME_LH * nameF;
  const labelF = Math.max(12, nameF * 0.3, F * 0.46);
  const nameTop = portrait ? H * 0.16 : hingeY - nameH / 2 + labelF * 0.6;

  const nodes: React.ReactNode[] = [];

  const labelIn = ease(NAME_AT + 4, 14);
  if (label) {
    nodes.push(
      <div
        key="label"
        style={{
          position: "absolute",
          left: nameX,
          top: nameTop - labelF * 1.9,
          fontFamily: geologica.fontFamily,
          fontWeight: BODY_W,
          fontSize: labelF,
          lineHeight: 1,
          color: hi,
          opacity: labelIn,
          transform: `translateY(${((1 - labelIn) * labelF * 0.6).toFixed(2)}px)`,
          whiteSpace: "pre",
        }}
      >
        {label}
      </div>,
    );
  }

  nameLines.forEach((line, li) => {
    nodes.push(
      <div
        key={`name-${line.join(" ")}`}
        style={{
          position: "absolute",
          left: nameX - nameF * 0.04,
          top: nameTop + li * NAME_LH * nameF - nameF * 0.08,
          height: nameF * NAME_LH + nameF * 0.16,
          paddingLeft: nameF * 0.04,
          paddingRight: nameF * 0.1,
          overflow: "hidden",
          fontFamily: geologica.fontFamily,
          fontWeight: NAME_W,
          fontSize: nameF,
          lineHeight: `${nameF * NAME_LH + nameF * 0.16}px`,
          letterSpacing: `${NAME_TRACK}em`,
          color: c.ink,
          whiteSpace: "pre",
        }}
      >
        {line.map((w, wi) => {
          const e = ease(NAME_AT + (li * 2 + wi) * 3, 16);
          return (
            <span
              key={w}
              style={{
                display: "inline-block",
                transform: `translateY(${((1 - e) * nameF * 1.1).toFixed(2)}px)`,
              }}
            >
              {wi > 0 ? ` ${w}` : w}
            </span>
          );
        })}
      </div>,
    );
  });

  const renderClause = (
    k: number,
    top: number,
    opacity: number,
    color: string,
    writeAt: number,
    endDot: number,
    ellipsis: number,
  ) => {
    const cl = clauses[k];
    const last = k === n - 1;
    let wordIndex = 0;
    return (
      <div
        key={`clause-${k}`}
        style={{
          position: "absolute",
          left: colX,
          top,
          width: colW + F,
          opacity,
          color,
          fontFamily: geologica.fontFamily,
          fontWeight: BODY_W,
          fontSize: F,
          letterSpacing: `${BODY_TRACK}em`,
          lineHeight: `${LH * F}px`,
          whiteSpace: "pre",
        }}
      >
        {ellipsis > 0 && colX > (bW("…") + 0.12) * F ? (
          <span
            style={{
              position: "absolute",
              left: -bW("…") * F - F * 0.06,
              top: 0,
              opacity: ellipsis,
            }}
          >
            …
          </span>
        ) : null}
        {cl.lines.map((line, li) => (
          <div key={line.join(" ")}>
            {line.map((w, wi) => {
              const e = ease(writeAt + wordIndex++ * WORD_STAGGER, WORD_IN);
              const isEnd =
                li === cl.lines.length - 1 && wi === line.length - 1;
              return (
                <span
                  key={`${w}-${wi}`}
                  style={{
                    display: "inline-block",
                    opacity: e,
                    transform: `translateY(${((1 - e) * F * 0.45).toFixed(2)}px)`,
                  }}
                >
                  {wi > 0 ? ` ${w}` : w}
                  {isEnd ? (
                    <span style={{ position: "relative" }}>
                      <span style={{ opacity: last ? 1 : endDot }}>.</span>
                      {last ? null : (
                        <span
                          style={{
                            position: "absolute",
                            left: 0,
                            top: 0,
                            opacity: 1 - endDot,
                          }}
                        >
                          ,
                        </span>
                      )}
                    </span>
                  ) : null}
                </span>
              );
            })}
          </div>
        ))}
      </div>
    );
  };

  const s1 = stepAt(1);
  const c0Slot = n > 1 ? ease(s1, CENTER_TO_SLOT, EASE_MOVE) : 0;

  for (let k = 0; k < n; k++) {
    const enter = stepAt(k);
    if (t < enter - 1) continue;
    const promoteAt = stepAt(k + 1);
    const leaveAt = stepAt(k + 2);
    const promoting = k >= 1 && k + 1 < n;
    const isLast = k === n - 1;

    let top: number;
    let opacity = 1;
    let writeAt: number;
    let endDot = 1;
    let ellipsis = 0;

    if (k === 0) {
      writeAt = enter;
      const centred = hingeY - clauses[0].h / 2;
      top = centred + (causeTop(0) - centred) * c0Slot;
      opacity = 1 - (1 - DIM) * ease(s1 + 2, 14);
      endDot = n > 1 ? 1 - ease(s1, 10) : 1;
    } else {
      writeAt = k === 1 ? enter + 4 : enter + WRITE_AFTER_RISE;
      top = effectTop;
      if (promoting) {
        const rise = ease(promoteAt, RISE, EASE_MOVE);
        top = effectTop + (causeTop(k) - effectTop) * rise;
        opacity = 1 - (1 - DIM) * ease(promoteAt + 4, 14);
        endDot = 1 - ease(promoteAt + 4, 10);
        ellipsis = ease(promoteAt + RISE - 4, 10);
      }
    }

    if (k + 2 < n) {
      const exit = ease(leaveAt, EXIT, EASE_MOVE);
      if (exit >= 1) continue;
      top -= exit * F * 0.9;
      opacity *= 1 - exit;
    }

    const color = isLast
      ? interpolateColors(
          ease(enter + WRITE_AFTER_RISE + 8, 16),
          [0, 1],
          [c.ink, hi],
        )
      : c.ink;

    nodes.push(renderClause(k, top, opacity, color, writeAt, endDot, ellipsis));
  }

  if (n > 1) {
    const hingeIn = ease(s1, 12);
    let hingeOp = hingeIn;
    for (let k = 2; k < n; k++) {
      const p = stepAt(k);
      const dip =
        interpolate(t, [p, p + 5], [0, 1], CLAMP) *
        (1 - interpolate(t, [p + RISE - 4, p + RISE + 6], [0, 1], CLAMP));
      hingeOp *= 1 - dip;
    }
    nodes.push(
      <div
        key="hinge"
        style={{
          position: "absolute",
          left: colX,
          top: hingeY - hingeF * 0.6,
          fontFamily: geologica.fontFamily,
          fontWeight: BODY_W,
          fontSize: hingeF,
          lineHeight: `${hingeF * 1.2}px`,
          color: hi,
          opacity: hingeOp,
          transform: `translateX(${((1 - hingeIn) * -F * 0.4).toFixed(2)}px)`,
          whiteSpace: "pre",
        }}
      >
        {hinge}
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {nodes}
    </AbsoluteFill>
  );
}

import { loadFont } from "@remotion/google-fonts/Gloock";
import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const gloock = loadFont("normal", { weights: ["400"], subsets: ["latin"] });

interface WholePageProps {
  beliefs?: string[];
  title?: string;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const DEFAULT_BELIEFS = [
  "A launch video is part of the launch, not the chore you do after it.",
  "If it lives in code, it can live in the repo with everything else.",
  "Every frame you install is a file you are free to rewrite.",
  "Motion should explain the product. It should never show off.",
  "A team of one deserves a real film, too.",
  "The video goes out the same day the product does.",
];

const THEMES = {
  dark: { bg: "#0A1230", ink: "#FFFFFF", accent: "#FF4436" },
  light: { bg: "#F7F3EC", ink: "#14161F", accent: "#D92B1E" },
} as const;

const TRACK = -0.02;
const LH = 1.12;
const START = 6;
const PULL = 36;
const HOLD = 40;
const DIM = 0;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string): number {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) return s.length * 0.5;
  measureCtx.font = `400 100px "${gloock.fontFamily}"`;
  return measureCtx.measureText(s).width / 100 + TRACK * Array.from(s).length;
}

function useFontReady() {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("whole-page: font"));
  useEffect(() => {
    let live = true;
    gloock
      .waitUntilDone()
      .then(() => document.fonts.load(`400 100px "${gloock.fontFamily}"`))
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setReady(true);
        continueRender(handle);
      });
    return () => {
      live = false;
    };
  }, [handle]);
  return ready;
}

interface Laid {
  words: { text: string; x: number; line: number }[];
  lines: number;
}

function wrapAt(words: string[], widths: number[], maxEm: number): Laid {
  const space = em(" ");
  const out: { text: string; x: number; line: number }[] = [];
  let line = 0;
  let x = 0;
  words.forEach((w, i) => {
    if (x > 0 && x + widths[i] > maxEm) {
      line += 1;
      x = 0;
    }
    out.push({ text: w, x, line });
    x += widths[i] + space;
  });
  return { words: out, lines: line + 1 };
}

function balanced(text: string, maxEm: number): Laid {
  const words = text.split(/\s+/).filter(Boolean);
  const widths = words.map(em);
  const base = wrapAt(words, widths, maxEm);
  let lo = Math.max(...widths, 0.1);
  let hi = maxEm;
  for (let i = 0; i < 14; i++) {
    const mid = (lo + hi) / 2;
    if (wrapAt(words, widths, mid).lines <= base.lines) hi = mid;
    else lo = mid;
  }
  return wrapAt(words, widths, hi);
}

function WholePageBase({
  beliefs = DEFAULT_BELIEFS,
  title = "What we believe",
  accent,
  background,
  speed = 1,
  theme = "dark",
}: WholePageProps) {
  const frame = useCurrentFrame();
  const t = frame * speed;
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontReady();

  if (!ready || beliefs.length === 0) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = beliefs.length;
  const portrait = H > W * 1.1;
  const cols = Math.min(n, portrait ? 2 : 3);
  const rows = Math.ceil(n / cols);
  const mx = W * (portrait ? 0.08 : 0.07);
  const top = H * (portrait ? 0.08 : 0.1);
  const Ft = H * (portrait ? 0.022 : 0.04);
  const gridTop = title ? top + Ft * 2.6 : top;
  const gutter = W * (portrait ? 0.06 : 0.04);
  const colW = (W - mx * 2 - gutter * (cols - 1)) / cols;
  const gridH = H * (portrait ? 0.9 : 0.9) - gridTop;

  const layoutAt = (F: number) => {
    const lays = beliefs.map((b) => balanced(b, colW / F));
    const rowLines = Array.from({ length: rows }, (_, r) =>
      Math.max(...lays.slice(r * cols, r * cols + cols).map((l) => l.lines), 1),
    );
    const total =
      rowLines.reduce((s, l) => s + l * LH * F, 0) + (rows - 1) * F * 1.1;
    return { lays, rowLines, total };
  };

  const widestWord = Math.max(
    ...beliefs.flatMap((b) => b.split(/\s+/).map(em)),
  );
  const fits = (F: number) =>
    layoutAt(F).total <= gridH && widestWord * F <= colW;
  const orphaned = (F: number) =>
    layoutAt(F).lays.some(
      (l) =>
        l.lines > 1 && l.words.filter((w) => w.line === l.lines - 1).length < 2,
    );
  let Fp = 0;
  let firstFit = 0;
  for (let F = H * 0.12; F > 6 && Fp === 0; F *= 0.985) {
    if (!fits(F)) continue;
    if (firstFit === 0) firstFit = F;
    if (!orphaned(F) || F < firstFit * 0.9) Fp = F;
  }
  if (Fp === 0) Fp = firstFit || 6;
  const { lays, rowLines } = layoutAt(Fp);
  const rowTop: number[] = [];
  let acc = gridTop;
  for (let r = 0; r < rows; r++) {
    rowTop.push(acc);
    acc += rowLines[r] * LH * Fp + Fp * 1.1;
  }
  const slack = portrait ? Math.max(0, (H * 0.9 - (acc - Fp * 1.1)) / 2) : 0;
  const paras = lays.map((l, i) => ({
    x: mx + (i % cols) * (colW + gutter),
    y: rowTop[Math.floor(i / cols)] + slack,
    h: l.lines * LH * Fp,
    lay: l,
  }));
  const zoomOf = paras.map((p) => {
    const lineW = Math.max(...p.lay.words.map((w) => w.x + em(w.text)), 0.1);
    return Math.max(
      1,
      Math.min(
        (W - mx * 2) / (lineW * Fp),
        (H * (portrait ? 0.6 : 0.78)) / p.h,
        (H * (portrait ? 0.1 : 0.16)) / Fp,
      ),
    );
  });
  const ax = mx;
  const ay = H * (portrait ? 0.1 : 0.1);

  const D = durationInFrames * speed;
  const per = Math.max(30, (D - START - PULL - HOLD) / n);
  const pan = Math.min(16, per * 0.36);
  const arriveAt = (i: number) => START + i * per;
  const pullAt = START + n * per - 6;

  let qx = paras[0].x;
  let qy = paras[0].y;
  let S = zoomOf[0];
  for (let i = 1; i < n; i++) {
    const p = interpolate(t, [arriveAt(i) - pan, arriveAt(i)], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    if (p > 0) {
      qx = paras[i - 1].x + (paras[i].x - paras[i - 1].x) * p;
      qy = paras[i - 1].y + (paras[i].y - paras[i - 1].y) * p;
      S = zoomOf[i - 1] * (zoomOf[i] / zoomOf[i - 1]) ** p;
    }
  }
  const pull = interpolate(t, [pullAt, pullAt + PULL], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const z = S ** (1 - pull);
  const zp = (S - z) / Math.max(0.0001, S - 1);
  const cx = qx + (ax - qx) * zp;
  const cy = qy + (ay - qy) * zp;
  const tx = ax - cx * z;
  const ty = ay - cy * z;

  const intro = interpolate(t, [0, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const settle = interpolate(pull, [0.35, 1], [0, 1], CLAMP);

  const nodes: React.ReactNode[] = [];
  paras.forEach((para, i) => {
    const arrive = i === 0 ? START : arriveAt(i);
    const leaveAt = arriveAt(i + 1) - pan;
    const leave =
      i < n - 1
        ? interpolate(t, [leaveAt, leaveAt + pan * 0.55], [0, 1], {
            ...CLAMP,
            easing: Easing.bezier(0.55, 0, 1, 0.45),
          })
        : 0;
    const isLast = i === n - 1;
    const wordsN = para.lay.words.length;
    const stagger = Math.min(1.6, 14 / Math.max(1, wordsN));
    para.lay.words.forEach((w, wi) => {
      const on = interpolate(
        t,
        [
          arrive - pan * 0.5 + wi * stagger,
          arrive - pan * 0.5 + 12 + wi * stagger,
        ],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      const focus = on * (1 - leave);
      const read = t >= arrive - pan * 0.5 + 12 + wi * stagger ? 1 : 0;
      const base = DIM + (1 - DIM) * focus;
      const finalOp = read ? 1 : DIM;
      const opacity = (base + (finalOp - base) * settle) * intro;
      const color = isLast
        ? interpolateColors(Math.max(focus, settle * read), [0, 1], [c.ink, hi])
        : c.ink;
      const rise = i === 0 ? (1 - intro) * Fp * 0.3 : 0;
      nodes.push(
        <div
          key={`p${i}w${wi}`}
          style={{
            position: "absolute",
            left: para.x + w.x * Fp,
            top: para.y + w.line * LH * Fp + rise,
            fontFamily: gloock.fontFamily,
            fontWeight: 400,
            fontSize: Fp,
            lineHeight: `${LH * Fp}px`,
            letterSpacing: `${TRACK}em`,
            whiteSpace: "pre",
            color,
            opacity,
          }}
        >
          {w.text}
        </div>,
      );
    });
  });

  const titleOp = interpolate(pull, [0.4, 1], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: W,
          height: H,
          transformOrigin: "0 0",
          transform: `translate(${tx.toFixed(2)}px, ${ty.toFixed(2)}px) scale(${z.toFixed(5)})`,
        }}
      >
        {title ? (
          <div
            style={{
              position: "absolute",
              left: mx,
              top: top + slack,
              fontFamily: gloock.fontFamily,
              fontWeight: 400,
              fontSize: Ft,
              lineHeight: 1,
              letterSpacing: "-0.01em",
              whiteSpace: "pre",
              color: c.ink,
              opacity: 0.6 * titleOp,
            }}
          >
            {title}
          </div>
        ) : null}
        {nodes}
      </div>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  title: {
    type: "text-content",
    default: "What we believe",
    description: "Title",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","title","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "What we believe",
  speed: 1,
};

type WholePageElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WholePageBase>;

const WholePageInner = forwardRef<
  HTMLDivElement,
  WholePageElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WholePage>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WholePageBase
          {...(componentProps as unknown as ComponentProps<typeof WholePageBase>)}
        />
      </div>
    </Sequence>
  );
});

export const WholePage = Interactive.withSchema({
  Component: WholePageInner,
  componentName: "<WholePage>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { loadVariableFont } from "@remotion/google-fonts/RobotoFlex";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const flex = loadVariableFont("oblique 0deg 10deg", { subsets: ["latin"] });

interface WidthLockProps {
  before?: string;
  words?: string[];
  after?: string;
  hold?: number;
  accent?: string;
  background?: string;
  speed?: number;
  theme?: "dark" | "light";
}

const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    hl: (a: string) =>
      `linear-gradient(100deg, ${LIMB[0]} 0%, ${LIMB[1]} 30%, color-mix(in oklab, ${a} 78%, ${LIMB[1]}) 62%, ${LIMB[0]} 100%)`,
    haze: (a: string) =>
      [
        `radial-gradient(64% 52% at 50% 122%, color-mix(in oklab, ${LIMB[2]} 46%, transparent) 0%, color-mix(in oklab, ${LIMB[3]} 50%, transparent) 50%, transparent 80%)`,
        `radial-gradient(30% 22% at 50% 106%, color-mix(in oklab, ${a} 24%, transparent) 0%, transparent 80%)`,
      ].join(", "),
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    hl: (a: string) =>
      `linear-gradient(100deg, ${LIMB[3]} 0%, ${LIMB[2]} 34%, ${a} 64%, ${LIMB[3]} 100%)`,
    haze: (a: string) =>
      `radial-gradient(60% 48% at 50% 120%, color-mix(in oklab, ${LIMB[1]} 34%, transparent) 0%, color-mix(in oklab, ${a} 8%, transparent) 50%, transparent 80%)`,
    grain: 0.035,
  },
} as const;

const WDTH_MIN = 25;
const WDTH_MAX = 151;
const SAMPLES = [25, 35, 50, 65, 80, 100, 115, 130, 151];
const WGHT = 480;
const TRACK = -0.02;
const MAX_EXTRA_TRACK = 0.04;
const LONGEST_AT = 46;
const LINE = 0.98;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.85, 0.35);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const LOCK_SPRING = { damping: 13, stiffness: 120, mass: 0.9 };

const fvs = (wdth: number) =>
  `"wdth" ${wdth.toFixed(2)}, "wght" ${WGHT}, "slnt" 0, "opsz" 72`;

type Curve = number[];

function widthAt(curve: Curve, wdth: number) {
  const w = Math.min(WDTH_MAX, Math.max(WDTH_MIN, wdth));
  for (let i = 0; i < SAMPLES.length - 1; i++) {
    if (w <= SAMPLES[i + 1]) {
      const k = (w - SAMPLES[i]) / (SAMPLES[i + 1] - SAMPLES[i]);
      return curve[i] + (curve[i + 1] - curve[i]) * k;
    }
  }
  return curve[curve.length - 1];
}

function solveWdth(curve: Curve, target: number) {
  if (target <= curve[0]) return WDTH_MIN;
  for (let i = 0; i < SAMPLES.length - 1; i++) {
    if (target <= curve[i + 1]) {
      const k = (target - curve[i]) / Math.max(1e-6, curve[i + 1] - curve[i]);
      return SAMPLES[i] + (SAMPLES[i + 1] - SAMPLES[i]) * k;
    }
  }
  return WDTH_MAX;
}

function measure(strings: string[]): Curve[] {
  const probe = document.createElement("span");
  Object.assign(probe.style, {
    position: "absolute",
    left: "-99999px",
    top: "0",
    visibility: "hidden",
    whiteSpace: "pre",
    fontFamily: `"${flex.fontFamily}"`,
    fontStyle: "normal",
    fontSize: "100px",
    lineHeight: "1",
    letterSpacing: `${TRACK}em`,
  });
  document.body.appendChild(probe);
  const curves = strings.map((s) =>
    SAMPLES.map((wd) => {
      probe.style.fontVariationSettings = fvs(wd);
      probe.textContent = s;
      return probe.getBoundingClientRect().width / 100 - TRACK;
    }),
  );
  probe.remove();
  return curves;
}

function useCurves(strings: string[]) {
  const key = strings.join("\u0001");
  const [state, setState] = useState<{ key: string; c: Curve[] } | null>(null);
  const [handle] = useState(() => delayRender("width-lock: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      flex.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${flex.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, c: measure(key.split("\u0001")) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle]);
  return state && state.key === key ? state.c : null;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `wl${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Fit {
  wdth: number;
  extra: number;
}

const NATURAL: Fit = { wdth: 100, extra: 0 };

function WidthLockBase({
  before = "Ship the",
  words = ["trailer", "transitions", "captions", "launch video"],
  after = "by tonight.",
  hold = 30,
  accent = "#3B5BFD",
  background,
  speed = 1,
  theme = "dark",
}: WidthLockProps) {
  const t = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const list = words.length > 0 ? words : ["launch video"];
  const strings = useMemo(
    () => [before, after, ...list].map((s) => s || " "),
    [before, after, list],
  );
  const curves = useCurves(strings);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!curves) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const measureW = W * (portrait ? 0.86 : 0.74);
  const rows = (before ? 1 : 0) + 1 + (after ? 1 : 0);

  const live = strings
    .map((s, i) => ({ s, curve: curves[i] }))
    .filter((r) => r.s.trim());
  const floor = Math.max(...live.map((r) => r.curve[0]));
  const ceil = Math.min(...live.map((r) => r.curve[r.curve.length - 1]));
  const pref = Math.max(...live.map((r) => widthAt(r.curve, LONGEST_AT)));
  const M =
    ceil >= floor
      ? Math.min(ceil, Math.max(floor, pref))
      : Math.max(floor, 0.1);
  const F = Math.min(
    measureW / M,
    (H * (portrait ? 0.5 : 0.72)) / (rows * LINE),
  );

  const fit = (i: number): Fit => {
    const curve = curves[i];
    const wdth = solveWdth(curve, M);
    const n = Math.max(1, Array.from(strings[i]).length - 1);
    const short = M - widthAt(curve, wdth);
    return {
      wdth,
      extra: short > 0.001 ? Math.min(MAX_EXTRA_TRACK, short / n) : 0,
    };
  };

  const LOCK_AT = 18;
  const FIRST_SWAP = 46;
  const STEP = Math.max(16, hold);
  const swapAt = (k: number) => FIRST_SWAP + (k - 1) * STEP;
  const OUT = 7;
  const IN_AT = 6;
  const IN = 10;
  const SWAP_LOCK = 13;

  const lineH = F * LINE;
  const blockH = rows * lineH;
  const top = H / 2 - blockH / 2 - F * 0.02;
  const cx = W / 2;

  const renderRun = (
    i: number,
    state: Fit,
    key: string,
    style: React.CSSProperties,
    gradient: boolean,
  ) => {
    const s = strings[i];
    const n = Math.max(1, Array.from(s).length - 1);
    const w = (widthAt(curves[i], state.wdth) + state.extra * n) * F;
    return (
      <div
        key={key}
        style={{
          position: "absolute",
          left: cx - w / 2,
          top: 0,
          height: lineH * 1.24,
          lineHeight: `${lineH * 1.24}px`,
          whiteSpace: "pre",
          fontFamily: flex.fontFamily,
          fontStyle: "normal",
          fontSize: F,
          fontVariationSettings: fvs(state.wdth),
          letterSpacing: `${TRACK + state.extra}em`,
          color: c.ink,
          ...(gradient
            ? {
                backgroundImage: c.hl(accent),
                backgroundSize: `${Math.max(w, 1)}px 100%`,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }
            : null),
          ...style,
        }}
      >
        {s}
      </div>
    );
  };

  const lerpFit = (a: Fit, b: Fit, k: number): Fit => ({
    wdth: a.wdth + (b.wdth - a.wdth) * k,
    extra: Math.max(0, a.extra + (b.extra - a.extra) * k),
  });

  const lock = (start: number) =>
    spring({ frame: t - start, fps, config: LOCK_SPRING });

  const riseY = (start: number, len: number) => {
    const p = interpolate(t, [start, start + len], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    return { y: (1 - p) * lineH * 0.34, o: p, blur: (1 - p) * F * 0.05 };
  };

  const band = (row: number, children: React.ReactNode, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        width: W,
        top: top + row * lineH - lineH * 0.12,
        height: lineH * 1.24,
      }}
    >
      {children}
    </div>
  );

  const bands: React.ReactNode[] = [];
  let row = 0;

  const fixed = (idx: number, enterAt: number) => {
    const r = riseY(enterAt, 18);
    const state = lerpFit(NATURAL, fit(idx), lock(LOCK_AT + row * 3));
    bands.push(
      band(
        row,
        renderRun(
          idx,
          state,
          `f${idx}`,
          {
            transform: `translateY(${r.y.toFixed(2)}px)`,
            opacity: r.o,
            filter: r.blur > 0.05 ? `blur(${r.blur.toFixed(2)}px)` : undefined,
          },
          false,
        ),
        `band${row}`,
      ),
    );
    row++;
  };

  if (before) fixed(0, 0);

  {
    const runs: React.ReactNode[] = [];
    list.forEach((_, k) => {
      const idx = 2 + k;
      const enterAt = k === 0 ? 3 : swapAt(k) + IN_AT;
      const lockAt = k === 0 ? LOCK_AT + row * 3 : swapAt(k) + SWAP_LOCK;
      const leaveAt = k < list.length - 1 ? swapAt(k + 1) : null;
      if (t < enterAt - 1) return;
      if (leaveAt !== null && t > leaveAt + OUT + 1) return;
      const r = riseY(enterAt, k === 0 ? 18 : IN);
      const state = lerpFit(NATURAL, fit(idx), lock(lockAt));
      let o = r.o;
      let blur = r.blur;
      let sx = 1;
      if (leaveAt !== null) {
        const p = interpolate(t, [leaveAt, leaveAt + OUT], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        sx = 1 - p * 0.94;
        o *= 1 - p;
        blur += p * F * 0.03;
      }
      runs.push(
        renderRun(
          idx,
          state,
          `w${k}`,
          {
            transform: `translateY(${r.y.toFixed(2)}px) scaleX(${sx.toFixed(4)})`,
            opacity: o,
            filter: blur > 0.05 ? `blur(${blur.toFixed(2)}px)` : undefined,
          },
          true,
        ),
      );
    });
    bands.push(band(row, runs, `band${row}`));
    row++;
  }

  if (after) fixed(1, 6);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {transparent ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: c.haze(accent),
            opacity: interpolate(t, [0, 30], [0.4, 1], CLAMP),
          }}
        />
      )}
      {bands}
      {transparent ? null : <Grain opacity={c.grain} />}
    </AbsoluteFill>
  );
}

