const TRACK = -0.03;
const ASC = 1.066;
const LINE = 1.366;
const CAP = 0.72;
const SPACE = 0.2 + TRACK;
const LEAD = 1.06;
const MAX_SIZE = 0.2;
const FILL = 0.84;

const ENTER_STAGGER = 3;
const ENTER_LEN = 18;
const FIRST = 36;
const STEP = 50;
const MOVE = 22;
const INSERT_DELAY = 12;
const INSERT_LEN = 18;
const INSERT_STAGGER = 3;
const ACCENT_HOLD = 12;
const SETTLE = 16;
const HOLD = 30;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Inserted words are painted with one stage-wide gradient (clip-text):
// gradients.sh "aurora" on dark, "ribbon" on light. `null` = the accent.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    grain: 0.07,
    stops: ["#a0f0c8", "#3fb5a3", null, "#b25c9c"],
