const CAP = 0.66;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_BEAT = Easing.bezier(0.76, 0, 0.18, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// One gradients.sh palette per theme, laid as a single field across the whole
// frame: odd blocks are windows onto it, even blocks are solid and let the field
// through their letters. Dark = radial-glow (+ accent), light = ribbon.
const THEMES = {
  dark: {
    stage: "#08080C",
    field: ["", "#5A46CB", "#1D1240"],
    glow: "#9DB4FF",
    glowAlpha: 0.6,
    solid: "#F3F1FF",
    onField: "#F3F1FF",
    grain: 0.1,
  },
  light: {
    stage: "#F5F4F0",
    field: ["#7A5CFF", "#FF3D9A", "#FF8A3D"],
    glow: "#FFFFFF",
    glowAlpha: 0.34,
    solid: "#0A0A0B",
    onField: "#FFFFFF",
    grain: 0.08,
  },
} as const;

function code(ch: string) {
  const c = ch.charCodeAt(0);
  return c >= 32 && c < 127 ? c - 32 : 33;
}

/** Advance width plus the ink box of a line, in em. */
function measure(text: string) {
  let adv = 0;
  for (let i = 0; i < text.length; i++) {
    adv += ADV[code(text[i])] / 1000;
    if (i > 0) adv += KERN.get(text[i - 1] + text[i]) ?? 0;
  }
  const lsb = LSB[code(text[0] ?? " ")] / 1000;
  const rsb = RSB[code(text[text.length - 1] ?? " ")] / 1000;
  return { adv, lsb, ink: Math.max(0.2, adv - lsb - rsb) };
}

/** Stage n shows lines 0..n; the newest line arrives loud and squeezes the rest. */
function weights(inks: number[], visible: number, final: boolean) {
  return inks.map((ink, i) => {
    if (i >= visible) return 0;
    const balanced = 1 / ink;
    if (final || visible === 1) return balanced;
    return i === visible - 1 ? balanced * 1.75 : balanced * 0.7;
  });
}

function normalize(w: number[]) {
  const sum = w.reduce((a, b) => a + b, 0) || 1;
  return w.map((v) => v / sum);
}

function WrappedSquashBase({
  lines = ["YOU", "SHIPPED", "A LOT"],
  accent = "#3B5BFD",
  colors,
  theme = "dark",
  speed = 1,
}: WrappedSquashProps) {
  const frame = useCurrentFrame() * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const t = THEMES[theme];

  const rows = lines
    .slice(0, 3)
    .map((l) => l.toUpperCase().replace(/\s+/g, " ").trim())
    .filter(Boolean);
  const n = Math.max(1, rows.length);
  const metrics = rows.map(measure);
  const inks = metrics.map((m) => m.ink);

  const field = t.field.map((c, i) =>
    theme === "dark" && i === 0 ? accent : c,
  );
  // Flat two-color override: blocks alternate the pair, no field.
  const flat = colors
    ? (i: number) =>
        i % 2 === 0
          ? { bg: colors[0], fg: colors[1] }
          : { bg: colors[1], fg: colors[0] }
    : null;

  // Beats: line 1 grows in, each next line arrives on a beat, then the lock.
  const BEATS = [26, 52].slice(0, n - 1);
  const LOCK = 26 + 26 * (n - 1);
  const intro = interpolate(frame, [0, 16], [0.46, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const stages = [
    ...Array.from({ length: n }, (_, s) =>
      normalize(weights(inks, s + 1, false)),
    ),
    normalize(weights(inks, n, true)),
  ];
  // How far each line has arrived (0..1), drives its gutter.
  const arrive = rows.map((_, i) =>
    i === 0
      ? 1
      : interpolate(frame, [BEATS[i - 1], BEATS[i - 1] + 14], [0, 1], {
          ...CLAMP,
          easing: EASE_BEAT,
        }),
  );
  let frac = stages[0];
  for (let s = 1; s < n; s++) {
    const p = arrive[s];
    frac = frac.map((v, i) => v + (stages[s][i] - v) * p);
  }
  const lock = spring({
    frame: frame - LOCK,
    fps,
    config: { damping: 16, stiffness: 170, mass: 0.9 },
  });
  frac = frac.map((v, i) => v + (stages[n][i] - v) * lock);

  const margin = Math.round(H * 0.03);
  const gutter = Math.round(H * 0.012);
  const gaps = arrive.slice(1).reduce((a, p) => a + p * gutter, 0);
  const full = H - margin * 2 - gaps;
  const usable = full * intro;
  const blockW = W - margin * 2;
  const F = H * 0.4;

  let y = margin + (full - usable) / 2;
  const blocks = rows.map((text, i) => {
    if (i > 0) y += arrive[i] * gutter;
    const h = Math.max(0, frac[i] * usable);
    const top = y;
    y += h;
    return { text, i, top, h };
  });

  // The field turns a few degrees and its light drifts across the shot.
  const drift = interpolate(frame, [0, 150], [0, 1], CLAMP);
  const ang = ((24 + 8 * drift) * Math.PI) / 180;
  const reach = Math.hypot(W, H) / 2;
  const fx = Math.cos(ang) * reach;
  const fy = Math.sin(ang) * reach;
  const fieldFill = `url(#${uid}-field)`;
  const glowFill = `url(#${uid}-glow)`;

  return (
    <AbsoluteFill style={{ background: t.stage }}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} aria-hidden>
        <defs>
          <linearGradient
            id={`${uid}-field`}
            gradientUnits="userSpaceOnUse"
            x1={W / 2 - fx}
            y1={H / 2 - fy}
            x2={W / 2 + fx}
            y2={H / 2 + fy}
          >
            {field.map((c, i) => (
              <stop
                key={`${uid}-s${String(i)}`}
                offset={0.12 + (0.8 * i) / (field.length - 1)}
                stopColor={c}
              />
            ))}
          </linearGradient>
          <radialGradient
            id={`${uid}-glow`}
            gradientUnits="userSpaceOnUse"
            cx={W * (0.16 + 0.1 * drift)}
            cy={H * (0.12 + 0.04 * drift)}
            r={W * 0.55}
          >
            <stop offset="0" stopColor={t.glow} stopOpacity={t.glowAlpha} />
            <stop
              offset="0.5"
              stopColor={t.glow}
              stopOpacity={t.glowAlpha * 0.27}
            />
            <stop offset="1" stopColor={t.glow} stopOpacity={0} />
          </radialGradient>
          <filter id={`${uid}-grain`} x="0" y="0" width="100%" height="100%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.85"
              numOctaves={2}
              seed={7}
              stitchTiles="stitch"
            />
            <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1.4 -0.2" />
          </filter>
        </defs>
        {blocks.map(({ text, i, top, h }) => {
          if (h < 0.5) return null;
          const m = metrics[i];
          const pad = Math.min(W * 0.018, h * 0.12);
          const innerW = blockW - pad * 2;
          const innerH = Math.max(0.01, h - pad * 2);
          const sx = innerW / (m.ink * F);
          const sy = innerH / (CAP * F);
          const tx = margin + pad - m.lsb * F * sx;
          const base = top + h - pad;
          const isWindow = i % 2 === 0;
          const flatC = flat ? flat(i) : null;
          const word = (fill: string) => (
            <text
              x={0}
              y={0}
              fill={fill}
              fontFamily={display}
              fontWeight={500}
              fontSize={F}
              textLength={m.adv * F}
              lengthAdjust="spacingAndGlyphs"
              style={{ fontKerning: "normal" }}
              transform={`translate(${tx} ${base}) scale(${sx} ${sy})`}
            >
              {text}
            </text>
          );
          const rect = (fill: string, mask?: string) => (
            <rect
              x={margin}
              y={top}
              width={blockW}
              height={h}
              fill={fill}
              mask={mask}
            />
          );
          return (
            <g key={`${uid}-${i}`}>
              {flatC ? (
                rect(flatC.bg)
              ) : isWindow ? (
                <>
                  {rect(fieldFill)}
                  {rect(glowFill)}
                </>
              ) : (
                rect(t.solid)
              )}
              <svg
                x={margin}
                y={top}
                width={blockW}
                height={h}
                viewBox={`${margin} ${top} ${blockW} ${h}`}
                overflow="hidden"
              >
                {flatC ? (
                  word(flatC.fg)
                ) : isWindow ? (
                  word(t.onField)
                ) : (
                  <>
                    <mask
                      id={`${uid}-m${i}`}
                      maskUnits="userSpaceOnUse"
                      x={margin}
                      y={top}
                      width={blockW}
                      height={h}
                    >
                      {word("#FFFFFF")}
                    </mask>
                    {rect(fieldFill, `url(#${uid}-m${i})`)}
                    {rect(glowFill, `url(#${uid}-m${i})`)}
                  </>
                )}
              </svg>
            </g>
          );
        })}
        {flat ? null : (
          <rect
            width={W}
            height={H}
            filter={`url(#${uid}-grain)`}
            opacity={t.grain}
            style={{ mixBlendMode: "overlay" }}
          />
        )}
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  speed: 1,
};

type WrappedSquashElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WrappedSquashBase>;

const WrappedSquashInner = forwardRef<
  HTMLDivElement,
  WrappedSquashElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WrappedSquash>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WrappedSquashBase
          {...(componentProps as unknown as ComponentProps<typeof WrappedSquashBase>)}
        />
      </div>
    </Sequence>
  );
});

export const WrappedSquash = Interactive.withSchema({
  Component: WrappedSquashInner,
  componentName: "<WrappedSquash>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});

import { forwardRef, useId, useImperativeHandle, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type XRayScanColors = {
  background: string;
  shell: string;
  detail: string;
  xray: string;
  line: string;
  accent: string;
};

type XRayScanProps = {
  /** Exterior shown ahead of the bar. Defaults to the back of a phone. */
  outside?: ReactNode;
  /** Interior revealed behind the bar. Defaults to white-line phone internals. */
  inside?: ReactNode;
  colors?: Partial<XRayScanColors>;
  /** Phone shell color. Overrides `colors.shell` when set. */
  shell?: string;
  /** Highlighted internal part. Overrides `colors.accent` when set. */
  accent?: string;
  /** Scan line and interior line art. Overrides `colors.line` when set. */
  line?: string;
  /** Background. Overrides `colors.background` when set. */
  background?: string;
  /** "horizontal" sweeps left to right, "vertical" top to bottom. */
  direction?: "horizontal" | "vertical";
  speed?: number;
};

const xRayScanDefaults = {
  colors: {
    background: "#111111",
    shell: "#E5322D",
    detail: "#111111",
    xray: "#07080A",
    line: "#FFFFFF",
    accent: "#E5322D",
