        />
        <path
          d={`M ${X(0.42)} ${Y(0.4)} V ${Y(0.385)} H ${X(0.58)} V ${Y(0.4)}`}
        />
        {[0.26, 0.2, 0.14].map((f) => (
          <circle
            key={f}
            cx={X(0.5)}
            cy={Y(0.62)}
            r={d.w * f}
