        <path
          d={`M ${X(0.5)} ${Y(0.47)} V ${Y(0.5)} M ${X(0.485)} ${Y(0.485)} H ${X(0.515)}`}
        />
        {/* Flex cable, speaker and port */}
        <path
          d={`M ${X(0.86)} ${Y(0.36)} V ${Y(0.38)} H ${X(0.92)} V ${Y(0.89)} H ${X(0.66)}`}
          strokeOpacity={0.6}
        />
        <rect
          x={X(0.38)}
