          width={d.w * 0.24}
          height={d.h * 0.025}
          rx={d.h * 0.0125}
        />
        {Array.from({ length: 6 }, (_, i) => (
          <circle key={i} cx={X(0.14 + i * 0.035)} cy={Y(0.947)} r={1.8 * u} />
        ))}
      </g>
      {/* The one part in red: the SoC */}
      <g stroke={c.accent} strokeWidth={2.4 * u} fill="none">
        <rect
          x={X(0.6)}
          y={Y(0.17)}
          width={d.w * 0.22}
          height={d.w * 0.22}
          rx={3 * u}
          fill={c.accent}
